CREATE FUNCTION kaverimis.fn_book1_rule17_report(_districtcode integer, _srocode integer, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtcode integer, districtname character varying, srocode integer, sroname character varying, bookid integer, registrationdatetime timestamp without time zone, isregistrationcompleted boolean, isfiling boolean, finalregistrationnumber character varying, uploaddocdeedpath text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
