		                    end
		
		                    )
				
					
					   )

            select cte.*,null::bigint as totalcount from cte OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
			
			
				
			elsif (pagenumber=-1 or  pagesize=-1) then 
			
			return query
			with cte as (select 
					dm.districtcode,
					dm.districtnamee,
					sm.srocode,
					sm.sronamee,
					d.bookid,
					d.registrationdatetime,
					d.isregistrationcompleted,
					d.isfiling,
					d.finalregistrationnumber,
					d.uploadsummarydocpath
					
					from 
