					join kaveri.sromaster sm on sm.srocode=d.srocode
					join kaveri.districtmaster dm on dm.districtcode=sm.districtcode 
					
					where  
					d.bookid=11 and d.isregistrationcompleted=true and d.isfiling=true and 
					(d.registrationdatetime between _fromdate and  _todate+ INTERVAL '1 day')
					and (
		
		                    CASE
		
		                       WHEN _districtcode <> 0 THEN  dm.districtcode = _districtcode
		
