--
-- Name: fn_daily_doc_count_sro(integer, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_daily_doc_count_sro(_srocode integer, _date timestamp without time zone) RETURNS TABLE(districtname character varying, sroname character varying, regddate text, doccount bigint, marriagecount bigint, eccount bigint, cccount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
BEGIN	
return query 

select 
dsm.districtnamee,
sm.sronamee,
to_char(_date::date,'DD.MM.YYYY') as regdate,
docappl.Doccount,
0::bigint as marriagecount,
ecappl.Eccount,
ccappl.cccount
from kaveri.sromaster sm
join kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode and sm.srocode=_srocode 
full outer join
(	select d.srocode as srocode,
    count(d.applicationnumber) as Doccount
    from kaveri.feesrequired f 
    join kaveri.applicantapplicationdetails a on a.applicationnumber = f.applicationnumber 
    join kaveri.documentmaster d on d.applicationnumber = f.applicationnumber 
	JOIN kaveri.sromaster sm ON d.srocode = sm.srocode
	JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
    where d.isregistrationcompleted is true
    and d.srocode =_srocode
    and to_char(d.registrationdatetime::date,'DD.MM.YYYY') =to_char(_date::date, 'DD.MM.YYYY')
   group by to_char(d.registrationdatetime::date, 'DD.MM.YYYY'),dsm.districtnamee,sm.sronamee,d.srocode)as docappl on  docappl.srocode=sm.srocode
 full outer join
	(select  distinct
	 eca.kaverisrocode as srocode,
	count(eca.applicationnumber)  as Eccount
	from kaveri.ec_applicationdetails eca 
	join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode
	join kaveri.ams_reg_epaymenttransdetails amsre on eca.applicationnumber=amsre.applicationnumber 
	where	eca.kaverisrocode=_srocode and  
	to_char(eca.submitteddatetime::date, 'DD.MM.YYYY') =to_char(_date::date,'DD.MM.YYYY')group by sronamee,eca.kaverisrocode, 
	to_char(eca.submitteddatetime::date, 'DD.MM.YYYY' )) as ecappl 
	on sm.srocode=ecappl.srocode
	 
full outer join
	 
	 (select  DISTINCT
	  cca.kaverisrocode as srocode,
	count(cca.applicationnumber) as cccount
	from kaveri.cc_applicationdetails cca 
	join kaveri.sromaster sr on cca.kaverisrocode  = sr.srocode
	join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
	join kaveri.ams_reg_epaymenttransdetails amsre on cca.applicationnumber=amsre.applicationnumber 

	where cca.kaverisrocode=_srocode  and to_char(cca.submitteddatetime::date, 'DD.MM.YYYY') =to_char(_date::date, 'DD.MM.YYYY')
	group by districtnamee,sronamee,cca.kaverisrocode,to_char(cca.submitteddatetime::date,'DD.MM.YYYY')) as ccappl 
		on ccappl.srocode=sm.srocode;
	
	END;

$$;


ALTER FUNCTION kaverimis.fn_daily_doc_count_sro(_srocode integer, _date timestamp without time zone) OWNER TO csgadmin;

--
-- Name: fn_daily_revenue_at_district(integer, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_daily_revenue_at_district(_districtcode integer, _date timestamp without time zone) RETURNS TABLE(districtname character varying, sroname character varying, regddate character varying, stampduty numeric, registrationfees numeric, scanfees numeric, otherfees numeric, totalfees numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE
BEGIN	
return query 

select
    d2.districtnamee,s.sronamee,
    to_char(d.registrationdatetime::date, 'DD.MM.YYYY')::character varying as regdate,
    sum(case when f.feerulecode = 36 then f.amountpaid end) as stampduty,
    sum(case when f.feerulecode = 1 then f.amountpaid end) as regfees,
    sum(case when f.feerulecode = 2 then f.amountpaid end) as scanfees,
    sum(case when f.feerulecode not in (36, 1, 2) then f.amountpaid end) as otherfees,
    sum(f.amountpaid) as totalfees 
    from kaveri.feesrequired f 
    --join kaveri.applicantapplicationdetails a on a.applicationnumber = f.applicationnumber 
    join kaveri.documentmaster d on d.applicationnumber = f.applicationnumber 
    join kaveri.sromaster s on d.srocode = s.srocode 
    join kaveri.districtmaster d2 on d2.districtcode = s.districtcode 
    where d.isregistrationcompleted is true
    and d2.districtcode = _districtcode
    and to_char(d.registrationdatetime::date, 'DD.MM.YYYY') =
    to_char(_date::date, 'DD.MM.YYYY')
    group by to_char(d.registrationdatetime::date, 'DD.MM.YYYY'),d2.districtnamee,s.sronamee;


	END;

$$;


ALTER FUNCTION kaverimis.fn_daily_revenue_at_district(_districtcode integer, _date timestamp without time zone) OWNER TO csgadmin;

--
-- Name: fn_daily_revenue_at_sro(bigint, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_daily_revenue_at_sro(_srocode bigint, _date timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE(districtname character varying, sroname character varying, regddate character varying, stampduty numeric, registrationfees numeric, scanfees numeric, otherfees numeric, totalfees numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE
BEGIN	
return query 

select dsm.districtnamee,sm.sronamee,
    to_char(d.registrationdatetime::date, 'DD.MM.YYYY')::character varying as regdate,
    sum(case when f.feerulecode = 36 then f.amountpaid end) as stampduty,
    sum(case when f.feerulecode = 1 then f.amountpaid end) as regfees,
    sum(case when f.feerulecode = 2 then f.amountpaid end) as scanfees,
    sum(case when f.feerulecode not in (36, 1, 2) then f.amountpaid end) as otherfees,
    sum(f.amountpaid) as totalfees 
    from kaveri.feesrequired f 
   -- join kaveri.applicantapplicationdetails a on a.applicationnumber = f.applicationnumber 
    join kaveri.documentmaster d on d.applicationnumber = f.applicationnumber 
	JOIN kaveri.sromaster sm ON d.srocode = sm.srocode
	JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
    where d.isregistrationcompleted is true
    and d.srocode = _srocode
    and to_char(d.registrationdatetime::date, 'DD.MM.YYYY') =
    to_char(_date::date, 'DD.MM.YYYY')
    group by to_char(d.registrationdatetime::date, 'DD.MM.YYYY'),dsm.districtnamee,sm.sronamee;
	
	END;

$$;


ALTER FUNCTION kaverimis.fn_daily_revenue_at_sro(_srocode bigint, _date timestamp without time zone) OWNER TO csgadmin;

--
-- Name: fn_daily_revenue_at_state(timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_daily_revenue_at_state(_date timestamp without time zone) RETURNS TABLE(regddate character varying, stampduty numeric, registrationfees numeric, scanfees numeric, otherfees numeric, totalfees numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN	
return query 
select
    to_char(d.registrationdatetime::date, 'DD.MM.YYYY')::character varying  as regdate,
    sum(case when f.feerulecode = 36 then f.amountpaid end) as stampduty,
    sum(case when f.feerulecode = 1 then f.amountpaid end) as regfees,
    sum(case when f.feerulecode = 2 then f.amountpaid end) as scanfees,
    sum(case when f.feerulecode not in (36, 1, 2) then f.amountpaid end) as otherfees,
    sum(f.amountpaid) as totalfees 
    from kaveri.feesrequired f 
    join kaveri.documentmaster d on d.applicationnumber = f.applicationnumber 
    where d.isregistrationcompleted is true
    and to_char(d.registrationdatetime::date, 'DD.MM.YYYY') = to_char(_date::date, 'DD.MM.YYYY')
    group by to_char(d.registrationdatetime::date, 'DD.MM.YYYY');


	END;

$$;


ALTER FUNCTION kaverimis.fn_daily_revenue_at_state(_date timestamp without time zone) OWNER TO csgadmin;

--
-- Name: fn_document_references_report(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_document_references_report(_srocode integer, _districtcode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(officename character varying, documenttype character varying, registrationnumber character varying, referencetext character varying, referenceaddedthrough character varying, revenueofficerno text, revenueofficerdate text, registrationdatetime timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
return query 
select 
b.sronamee as officename,
d.documenttypedesc as documenttype,
a.finalregistrationnumber as registrationnumber,
c.referencetext,
e.throghtype as referenceaddedthrough,
c.revenueofficerno ||' /'||c.court_no as revenueofficerno,
c.revenuedate ||'/ '||c.courtorderdate as revenueofficerdate,
a.registrationdatetime
from kaveri.documentmaster a join kaveri.sromaster b
on a.srocode = b.srocode
 join kaveri.referencemaster c on a.documentid = c.documentid
 join kaveri.documenttypemaster d on c.documenttypeid = d.documenttypeid
 join kaveri.referencesthroghmaster e on c.throughid = e.throghid
where
a.srocode = _srocode and
b.districtcode = _districtcode and
a.registrationdatetime >= _fromdate and a.registrationdatetime <= _todate;

END;
$$;


