-- Name: fn_fetch_any_where_registration_document_report(integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_fetch_any_where_registration_document_report(_districtcode integer, _srocode integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(propertysrocode integer, propertysroname character varying, regsrocode integer, regsroname character varying, regcount bigint)
    LANGUAGE plpgsql
    AS $$
 
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
return query 
select 
  s.srocode PropertySroCode, 
  s.sronamee PropertySroName, 
  resultdata.RegSroCode, 
  resultdata.RegSroname, 
  resultdata.RegCount 
from 
  kaveri.sromaster s 
   join (
    select 
      s.sronamee as PropertySroName, 
      p.srocode as PropertySroCode, 
      p.regsrocode as RegSroCode, 
      s2.sronamee as RegSroname, 
      count(*) as RegCount 
    from 
      --kaveri.applicantapplicationdetails a 
       kaveri.documentmaster d join  kaveri.propertymaster p on d.documentid = p.documentid 
      join kaveri.sromaster s on s.srocode = p.srocode 
      join kaveri.sromaster s2 on s2.srocode = p.regsrocode 
    where 
      s.districtcode = _districtcode 
      and d.isregistrationcompleted = true 
      --and a.currentstatus = 'CD120' 
      and p.srocode > 0 
      and p.regsrocode > 0 
    /*  and d.registrationdatetime >= '2000-01-01' 
      and cast(d.registrationdatetime as date) <= current_date */
    group by 
      p.srocode, 
      p.regsrocode, 
      s.sronamee, 
      s2.sronamee
  ) as resultdata on resultdata.PropertySroCode = s.srocode 
where 
  s.districtcode = _districtcode and s.srocode = _srocode;
END;
$$;


