--
-- Name: fn_fetch_any_where_registration_document_report_new(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_fetch_any_where_registration_document_report_new(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(registrationoffice character varying, jurisdictionaloffice character varying, noofdocumentregisterd bigint, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
if(_districtcode = 0) then
return query

		with cte as (select 
		distinct(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode) as Registration_Office,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode) as jurisdictionoffice,
		count(distinct dm.finalregistrationnumber) as noofdocumentregisterd 
		from kaveri.anywhere_reg_log arl
		left
		 join kaveri.documentmaster dm on arl.applicationnumber = dm.applicationnumber
		 join kaveri.sromaster b on dm.srocode = b.srocode
		 join kaveri.districtmaster c on b.districtcode = c.districtcode 
		 where
		  --c.districtcode=2 
		 --and arl.regsrocode=173 
		 --and
		 dm.isregistrationcompleted = true  and arl.srocode<>0 and arl.regsrocode<>0
		 and dm.registrationdatetime between  _fromdate  and  _todate 
 		group by arl.regsrocode,arl.srocode),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;


	elsif (_srocode = 0) then
	return query
			with cte as (select 
		distinct(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode) as Registration_Office,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode) as jurisdictionoffice,
		count(distinct dm.finalregistrationnumber) as noofdocumentregisterd 
		from kaveri.anywhere_reg_log arl
		left
		 join kaveri.documentmaster dm on arl.applicationnumber = dm.applicationnumber
		 join kaveri.sromaster b on dm.srocode = b.srocode
		 join kaveri.districtmaster c on b.districtcode = c.districtcode 
		 where
		  c.districtcode=_districtcode and 
		 --and arl.regsrocode=173 
		 --and
		 dm.isregistrationcompleted = true  and arl.srocode<>0 and arl.regsrocode<>0
		 and dm.registrationdatetime between  _fromdate  and  _todate 
 		group by arl.regsrocode,arl.srocode),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

	else
return query
		with cte as (select 
		distinct(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode) as Registration_Office,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode) as jurisdictionoffice,
		count(distinct dm.finalregistrationnumber) as noofdocumentregisterd 
		from kaveri.anywhere_reg_log arl
		left
		 join kaveri.documentmaster dm on arl.applicationnumber = dm.applicationnumber
		 join kaveri.sromaster b on dm.srocode = b.srocode
		 join kaveri.districtmaster c on b.districtcode = c.districtcode 
		 where
		  c.districtcode=_districtcode
		 and arl.regsrocode=_srocode and 
		 --and
		 dm.isregistrationcompleted = true  and arl.srocode<>0 and arl.regsrocode<>0
		 and dm.registrationdatetime between  _fromdate  and  _todate 
 		group by arl.regsrocode,arl.srocode),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

end if;
end;
$$;


