ALTER FUNCTION kaverimis.fn_fetch_any_where_registration_document_report_new_23012024(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_fetch_centeralized_document_report(date, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_fetch_centeralized_document_report(_registrationdate date, _srocode integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(srocode integer, sronamee character varying, regcompletedcount bigint, lastregtime timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
return query 
select 
  regCompleted.srocode srocode, 
  regCompleted.sronamee sronamee, 
  regCompleted.regcompletedCount regcompletedCount, 
  lastregdetails.lastregtime lastregtime 
from 
  (
    (
      select 
        s.srocode, 
        s.sronamee, 
        count(*) regcompletedCount 
      from 
        kaveri.documentmaster d 
        join kaveri.applicantapplicationdetails a on a.applicationnumber = d.applicationnumber 
        join kaveri.wrkflowmaster w on w.wrkflowstatusid = a.currentstatus 
        join kaveri.sromaster s on s.srocode = d.srocode 
      where 
        case when _srocode <> 0 Then d.srocode = _srocode Else d.srocode in (
          select 
            se.srocode 
          from 
            kaveri.sromaster se
        ) End 
        and a.currentstatus = 'CD120' 
        and d.isregistrationcompleted = true 
        and cast(d.registrationdatetime as date) = _registrationdate 
      group by 
        s.srocode, 
        s.sronamee
    ) as regCompleted 
    left join (
      select 
        lastesRecords.lastregtime, 
        lastesRecords.srocode 
      from 
        (
          select 
            d.registrationdatetime as lastregtime, 
            d.srocode, 
            ROW_NUMBER() OVER(
              PARTITION BY d.srocode 
              ORDER BY 
                d.registrationdatetime desc
            ) AS Row 
          from 
            kaveri.documentmaster d 
            join kaveri.applicantapplicationdetails a on a.applicationnumber = d.applicationnumber 
          where 
            a.currentstatus = 'CD120' 
            and d.isregistrationcompleted = true
        ) as lastesRecords 
      where 
        lastesRecords.Row = 1
    ) as lastregdetails on lastregdetails.srocode = regCompleted.srocode
  );
END;
$$;


ALTER FUNCTION kaverimis.fn_fetch_centeralized_document_report(_registrationdate date, _srocode integer, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_fetch_misellaneious_register(bigint, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_fetch_misellaneious_register(_srocode bigint, _fromdt timestamp without time zone, _todt timestamp without time zone) RETURNS TABLE(sronamee character varying, districtnamee character varying, registrationnumberofdocument character varying, documentcopy text, ec_cc_copy text, valeofstampduty numeric, bookno text, registration_no_with_year text, volumn_no text, page_no text)
    LANGUAGE plpgsql
    AS $$
begin
return query
select distinct s.sronamee as sronamee ,d2.districtnamee  as districtnamee
,d.finalregistrationnumber as registrationnumberofdocument,null  as documentcopy,
null as EC_CC_Copy
,case when f.feerulecode=2 then 
sum(f.amountpaid) else 0 end as valeofstampduty,
null as bookno,
null as Registration_No_With_year,
null as volumn_no,
null as page_no
from kaveri.documentmaster d 
join kaveri.propertymaster p on d.documentid =p.documentid 
join kaveri.feesrequired f on f.documentid = d.documentid
join kaveri.sromaster s on d.srocode = s.srocode 
join kaveri.districtmaster d2 on s.districtcode = d2.districtcode 
where d.isregistrationcompleted =true and d.srocode =_srocode --and d2.districtcode=_districtcode
and d.executiondatetime >=_fromdt and d.executiondatetime <=_todt
group by s.sronamee ,d2.districtnamee  ,d.finalregistrationnumber,d.documentnumber,f.feerulecode;
end;
$$;


ALTER FUNCTION kaverimis.fn_fetch_misellaneious_register(_srocode bigint, _fromdt timestamp without time zone, _todt timestamp without time zone) OWNER TO csgadmin;

--
-- Name: fn_fetch_pendency_report(character varying, bigint[], bigint[]); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_fetch_pendency_report(_currentstatus character varying, _districtcode bigint[] DEFAULT '{}'::bigint[], _srocode bigint[] DEFAULT '{}'::bigint[]) RETURNS TABLE(droname character varying, sroname character varying, bucket0to7 bigint, bucket7to15 bigint, bucket15to30 bigint, bucketabv30 bigint)
    LANGUAGE plpgsql
    AS $$
 
BEGIN
	return query
		with application as (
		 select ad.srocode,ad.currentstatus,aa.applicationnumber,current_date - MAX(crtdt) FILTER (WHERE aa.wrkflowstatusid = _currentstatus) maxdt
		 from kaveri.applicantapplicationdetails ad
		 join kaveri.applicationaudit aa on aa.applicationnumber =ad.applicationnumber
		 where ad.currentstatus = _currentstatus
		 group by ad.srocode,aa.applicationnumber,ad.currentstatus
		 )
		select districtnamee as droname,
		    sronamee as sroname,
		    COUNT(applicationnumber) FILTER (WHERE maxdt <= interval '7 days') AS bucket0to7,
		    COUNT(applicationnumber) FILTER (WHERE maxdt > interval '7 days' AND maxdt <= interval '15 days') AS bucket7to15,
		    COUNT(applicationnumber) FILTER (WHERE maxdt > interval '15 days' AND maxdt <= interval '30 days') AS bucket15to30,
		    COUNT(applicationnumber) FILTER (WHERE maxdt > interval '30 days') AS bucketabv30
		FROM
		kaveri.sromaster s --on s.srocode = ad.srocode
		join kaveri.districtmaster d on d.districtcode = s.districtcode
		left join application a on s.srocode = a.srocode
		where (CASE WHEN _districtcode <> '{}' AND NOT (0 = ANY(_districtcode)) THEN d.districtcode = any(_districtcode) ELSE TRUE END)
		      AND (CASE WHEN _srocode <> '{}' AND NOT (0 = ANY(_srocode)) THEN s.srocode = any(_srocode) ELSE TRUE END)
		GROUP BY d.districtcode,d.districtnamee,s.srocode,s.sronamee
	order by districtnamee,sronamee;
END;
$$;


ALTER FUNCTION kaverimis.fn_fetch_pendency_report(_currentstatus character varying, _districtcode bigint[], _srocode bigint[]) OWNER TO postgres;

--
-- Name: fn_fetch_pendency_report_1(character varying, bigint[], bigint[], integer); Type: FUNCTION; Schema: kaverimis; Owner: manjunathswamy
--

CREATE FUNCTION kaverimis.fn_fetch_pendency_report_1(_currentstatus character varying, _districtcode bigint[] DEFAULT '{}'::bigint[], _srocode bigint[] DEFAULT '{}'::bigint[], _serviceid integer DEFAULT NULL::integer) RETURNS TABLE(droname character varying, sroname character varying, servicename character varying, bucket0to7 bigint, bucket7to15 bigint, bucket15to30 bigint, bucketabv30 bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH svc AS (
        SELECT s.serviceid, s.servicename
        FROM kaveri.servicesmaster s
        WHERE s.serviceid IN (1,12,13)
          AND (_serviceid IS NULL OR s.serviceid = _serviceid)
    ),
    application AS (
        SELECT
            ad.srocode,
            ad.applicationtypeid,
            aa.applicationnumber,
            current_date - MAX(aa.crtdt) FILTER (
                WHERE aa.wrkflowstatusid = _currentstatus
            ) AS maxdt
        FROM kaveri.applicantapplicationdetails ad
        JOIN kaveri.applicationaudit aa
            ON aa.applicationnumber = ad.applicationnumber
        WHERE ad.currentstatus = _currentstatus
          AND ad.applicationtypeid IN (1,12,13)
          AND (_serviceid IS NULL OR ad.applicationtypeid = _serviceid)
        GROUP BY
            ad.srocode,
            ad.applicationtypeid,
            aa.applicationnumber
    )
    SELECT
        d.districtnamee AS droname,
        s.sronamee AS sroname,
        svc.servicename,

        COUNT(a.applicationnumber) FILTER (
            WHERE a.maxdt <= interval '7 days'
        ) AS bucket0to7,

        COUNT(a.applicationnumber) FILTER (
            WHERE a.maxdt > interval '7 days'
              AND a.maxdt <= interval '15 days'
        ) AS bucket7to15,

        COUNT(a.applicationnumber) FILTER (
            WHERE a.maxdt > interval '15 days'
              AND a.maxdt <= interval '30 days'
        ) AS bucket15to30,

        COUNT(a.applicationnumber) FILTER (
            WHERE a.maxdt > interval '30 days'
        ) AS bucketabv30

    FROM kaveri.sromaster s
    JOIN kaveri.districtmaster d
        ON d.districtcode = s.districtcode
    CROSS JOIN svc
    LEFT JOIN application a
        ON a.srocode = s.srocode
       AND a.applicationtypeid = svc.serviceid
    WHERE
        (CASE
            WHEN _districtcode <> '{}' AND NOT (0 = ANY(_districtcode))
            THEN d.districtcode = ANY(_districtcode)
            ELSE TRUE
        END)
        AND
        (CASE
            WHEN _srocode <> '{}' AND NOT (0 = ANY(_srocode))
            THEN s.srocode = ANY(_srocode)
            ELSE TRUE
        END)
    GROUP BY
        d.districtcode,
        d.districtnamee,
        s.srocode,
        s.sronamee,
        svc.serviceid,
        svc.servicename
    ORDER BY
        d.districtnamee,
        s.sronamee,
        svc.servicename;
END;
$$;


ALTER FUNCTION kaverimis.fn_fetch_pendency_report_1(_currentstatus character varying, _districtcode bigint[], _srocode bigint[], _serviceid integer) OWNER TO manjunathswamy;

--
-- Name: fn_fetch_pending_document_summary_report(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_fetch_pending_document_summary_report(_srocode integer, _districtcode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtnamee character varying, sronamee character varying, numberofdocumentspresented bigint, numberofdocumentsregistered bigint, numberofdocumentscurrentlypending bigint, totaldocumentsregisteredafterkeepingpending bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
return query 
      select dis.districtnamee districtnamee, s.sronamee sronamee, 
   countofPen.countofpenrow NumberofDocumentsPresented,
   regcompleted.regcompletedCount NumberofDocumentsRegistered, 
   currpending.currPencount NumberofDocumentsCurrentlyPending,
   penregcom.tolregafterpen TotalDocumentsRegisteredAfterKeepingPending
   from kaveri.sromaster s 
join kaveri.districtmaster dis on dis.districtcode = s.districtcode 
left join 
(select d.sroCode, count(*) as countofpenrow from kaveri.documentmaster d
   join kaveri.applicantapplicationdetails a on a.applicationnumber = d.applicationnumber
   join kaveri.wrkflowmaster w on w.wrkflowstatusid = a.currentstatus  
   join kaveri.sromaster sro on sro.srocode = d.srocode 
   join kaveri.districtmaster dis on dis.districtcode  = sro.districtcode 
   where a.currentstatus !='CC101' and d.presentdatetime is not null 
   and d.presentdatetime >= _fromdate and cast(d.presentdatetime as date) <= _todate
   group by d.srocode) countofPen on countofPen.sroCode=s.srocode  
left join 
 (select d.sroCode, count(*) regcompletedCount from kaveri.documentmaster d
   join kaveri.applicantapplicationdetails a on a.applicationnumber = d.applicationnumber
   join kaveri.wrkflowmaster w on w.wrkflowstatusid = a.currentstatus
   where a.currentstatus ='CD120' and d.isregistrationcompleted = true
   and d.registrationdatetime >= _fromdate and cast(d.registrationdatetime as date) <= _todate
   group by d.srocode) as regcompleted on regcompleted.sroCode = s.srocode  
left join 
(select d.sroCode, count(*) as currPencount from kaveri.documentmaster d
   join kaveri.applicantapplicationdetails a on a.applicationnumber = d.applicationnumber
   join kaveri.wrkflowmaster w on w.wrkflowstatusid = a.currentstatus 
   where a.currentstatus = 'CD119' and d.ispending = true and d.presentdatetime >= _fromdate
   and cast(d.presentdatetime as date) <= '2022-10-12'
   group by d.srocode) as currpending on currpending.sroCode = s.srocode
left join 
(select d.sroCode, count(*) as tolregafterpen from kaveri.documentmaster d
   join kaveri.applicantapplicationdetails ON applicantapplicationdetails.applicationnumber = d.applicationnumber
   join kaveri.wrkflowmaster ON wrkflowmaster.wrkflowstatusid = applicantapplicationdetails.currentstatus
   where applicantapplicationdetails.currentstatus = 'CD120' and d.ispending = true and d.registrationdatetime >= _fromdate 
   and cast(d.registrationdatetime as date)<= _todate
   group by d.srocode) penregcom on penregcom.sroCode = s.srocode
   where 
   CASE WHEN _srocode <> 0
   Then
   s.srocode = _srocode and s.districtcode = _districtcode
   Else
   CASE WHEN _districtcode <> 0
   THEN
   s.srocode in (select srocode from Kaveri.sromaster where districtcode= _districtcode)
   ELSE
   s.srocode in (select srocode from kaveri.sromaster)
   END
   END
   order by dis.districtnamee;
END;
$$;


ALTER FUNCTION kaverimis.fn_fetch_pending_document_summary_report(_srocode integer, _districtcode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_fetch_report_queue_by_user(bigint); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_fetch_report_queue_by_user(_deptuserid bigint) RETURNS TABLE(requestedreport character varying, fromdate character varying, todate character varying, status character varying, reportfilepath character varying, isreportdownloaded boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
   RETURN QUERY
 	select (rq.requestedreport||' reqid '||rid)::character varying as requestedreport,
	to_char(rq.fromdate,'dd-Mon-YYYY')::character varying as fromdate,
 	to_char(rq.todate,'dd-Mon-YYYY')::character varying as todate,
	rq.status::character varying,
	rq.reportfilepath::character varying,
	rq.isreportdownloaded
	from kaverimis.report_queue rq where isfiledeleted=false  and
	requesteduser =_deptuserid  order by rq.rid asc;
END;
$$;


ALTER FUNCTION kaverimis.fn_fetch_report_queue_by_user(_deptuserid bigint) OWNER TO postgres;

--
-- Name: fn_insert_mis_daily_register_of_fees_statutory_docreg_12(timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_insert_mis_daily_register_of_fees_statutory_docreg_12(_fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS text[]
    LANGUAGE plpgsql
    AS $$
 
DECLARE
PageOffset INTEGER := 0;
v_record record; 
v_array text[];
BEGIN	
for v_record in (select applicationnumber from kaveri.documentmaster d where d.registrationdatetime::date>=_fromdate  and d.registrationdatetime::date<=_todate
and d.bookid in (1,2,3,4) and isregistrationcompleted = true)
loop
v_array:=array_append(v_array,v_record.applicationnumber);
insert into kaveri.revised_form_7_statutory_doc_reg
with cte as (
			with dm as (
					select d2.districtnamee,d.applicationnumber, d.registrationdatetime, d.finalregistrationnumber, d.bookid, d.presentdatetime, d.srocode,s.sronamee
					from kaveri.documentmaster d
					join kaveri.sromaster s on d.srocode = s.srocode
                    join kaveri.districtmaster d2 on d2.districtcode = s.districtcode
					where d.applicationnumber=v_record.applicationnumber
				),
				success_txns as (
					select distinct e.deptreferencecode
					from kaveri.ams_reg_epaymenttransdetails e
					join kaveri.ams_reg_epaymentbankackdetails b on b.deptreferencecode = e.deptreferencecode
					where b.paymentstatuscode in ('10700066','10700072')
					  and e.isdelete = false
					  and e.applicationnumber =v_record.applicationnumber
				),
				pm as (
					select
						applicationnumber,
						sum(totalarea) as totalarea,
						coalesce(sum(sroconsideration),0) as consideration,
						coalesce(sum(sromarketvalue),0) as marketvalue
					from kaveri.propertymaster
					where applicationnumber =v_record.applicationnumber
					  --and totalarea <= 0.125
					group by applicationnumber
				),
				epay as (
					select
						e.applicationnumber,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (35,36,64,89,91,92,101,107,110,138)),0) as stampduty,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (59,100)),0) as cessduty,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109)),0) as feesforregistrationofdocs,
						coalesce(sum(e.totalamount) filter (where e.feerulecode = 2),0) as scanningfee,
						coalesce(sum(e.totalamount) filter (where e.feerulecode = 6),0) as mutationfee
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.applicationnumber =v_record.applicationnumber
					  and e.isdelete = false
					group by e.applicationnumber
				),
				surcharge as (
					select e.applicationnumber, sum(e.totalamount) as totalsurcharge
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.isdelete = false
					  and e.feerulecode in (58,99)
					  and e.applicationnumber =v_record.applicationnumber
					group by e.applicationnumber
				),
				has_taluk as (
					select pm.applicationnumber, bool_or(pnd.currentpropertytypeid = 60) as has_taluk
					from kaveri.propertymaster pm
					join kaveri.propertynumberdetails pnd on pnd.propertyid = pm.propertyid
					where pm.applicationnumber =v_record.applicationnumber
					group by pm.applicationnumber
				),
				bk as (
					select e.applicationnumber, sum(e.totalamount) as feesremittedtotreasury
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.isdelete = false
					  and e.applicationnumber =v_record.applicationnumber
					group by e.applicationnumber
				)
				select d.districtnamee,
					d.sronamee,
					null::varchar as finalregistrationnumber,
					d.applicationnumber as applicationnumber2,
					d.presentdatetime::text as presentationdatetime,
					pr.presenternamee as presenter_name,
					art.description_of_docs as description_of_document,
					pm.consideration::numeric as considerationamount,
					pm.marketvalue::bigint as marketvalue,
					ep.stampduty::numeric as stampduty,
					ep.cessduty::numeric as cess,
					case when h.has_taluk then 0 else coalesce(s.totalsurcharge,0) end::numeric as surcharge_duty_muncipal,
					case when h.has_taluk then coalesce(s.totalsurcharge,0) else 0 end::numeric as surcharge_duty_taluk,
--					total_duty::numeric,
					coalesce(ep.stampduty::numeric + ep.cessduty::numeric + s.totalsurcharge::numeric,0) as total_duty,
					d.finalregistrationnumber::varchar as documentnumber,
					d.bookid::varchar as bookid,
					null::text as volumenumber,
					d.registrationdatetime::text as dateofcompletion,
					d.registrationdatetime::text as dateofreturn,
					ep.feesforregistrationofdocs::numeric as registrationfees,
					null::numeric as feescopygranted,
					ep.scanningfee::numeric as miscfees,
					null::numeric as otherstampduty,
					null::numeric as miscarticlefees,
					(COALESCE(ep.feesforregistrationofdocs,0)
						+ COALESCE(ep.scanningfee,0))::numeric as total_fees, --sum
					bk.feesremittedtotreasury::numeric as treasury_fees,
					bklast.transactiondate::text as feedate_treasury,
					null::text as dailymutationreceipts,
					ep.mutationfee::numeric as mutationfees,
					mut.mutationfeeremittedtotreasurydate::text as mutationfeedate,
					ar.copiesofmemo::text as transmission_of_memorandum,
					--ar.officename as transmission_of_memoranda,
					ar.memoacceptingoffice::text as transmission_of_memoranda,
					  (coalesce(ep.stampduty,0)
					  + coalesce(ep.cessduty,0)
					  + coalesce(case when h.has_taluk then 0 else s.totalsurcharge end,0)
					  + coalesce(case when h.has_taluk then s.totalsurcharge else 0 end,0)
					  + coalesce(ep.feesforregistrationofdocs,0)
					  + coalesce(ep.scanningfee,0)
					  + coalesce(ep.mutationfee,0))::bigint as total_amount_collected,
					null::text as signature_of_register,
					null::text as remarks,
					null::text as copy_of_document
					--pm.totalarea,	
					--ar.memosentdate,
					--ar.memonumber,
					--ar.memoaccepteddate
				from dm d
				left join pm on pm.applicationnumber = d.applicationnumber
				left join epay ep on ep.applicationnumber = d.applicationnumber
				left join surcharge s on s.applicationnumber = d.applicationnumber
				left join has_taluk h on h.applicationnumber = d.applicationnumber
				left join bk on bk.applicationnumber = d.applicationnumber
				
				left join lateral (
					select b.amount as feesremittedtotreasury, b.transactiontimestamp::date as transactiondate
					from kaveri.ams_reg_epaymenttransdetails e2
					join kaveri.ams_reg_epaymentbankackdetails b on b.deptreferencecode = e2.deptreferencecode
					where e2.applicationnumber = d.applicationnumber
					  and e2.isdelete = false
					  and b.paymentstatuscode in ('10700066','10700072')
					order by b.transactiontimestamp desc
					limit 1
				) bklast on true
				
				left join lateral (
					select coalesce(nullif(p2.firstname,''), nullif(p1.firstname,''), p.firstname) as presenternamee
					from kaveri.partyinfo p
					left join kaveri.partyinfo p1 on p.partyid = p1.linkpartyid
					left join kaveri.partyinfo p2 on p1.partyid = p2.linkpartyid
					where p.applicationnumber = d.applicationnumber and p.ispresenter = true
					order by p.partyid
					limit 1
				) pr on true
				
				left join lateral (
					select s.articlenamee as description_of_docs
					from (
						select distinct stamparticlecode
						from kaveri.propertymaster
						where applicationnumber = d.applicationnumber
						order by stamparticlecode
						limit 1
					) pmx
					join kaveri.stamparticles s on s.stamparticlecode = pmx.stamparticlecode
				) art on true
				
				left join lateral (
					select min(t.inserteddatetime)::date as mutationfeeremittedtotreasurydate
					from kaveri.ams_reg_epaymenttransdetails t
					join success_txns st using (deptreferencecode)
					where t.applicationnumber = d.applicationnumber
					  and t.feerulecode = 6
					  and t.isdelete = false
				) mut on true
				left join lateral (
					select
						a.newapplicationnumber as copiesofmemo,
						a.memosentdatetime::date as memosentdate,
						a.memoaccepteddatetime::date as memoaccepteddate,
						d2.finalregistrationnumber as memonumber,
						s1.sronamee as officename,
						s2.sronamee as memoacceptingoffice
					from kaveri.anywhere_reg_log a
					left join kaveri.documentmaster d2 on d2.applicationnumber = a.newapplicationnumber
					left join kaveri.sromaster s1 on s1.srocode = a.srocode
					left join kaveri.sromaster s2 on s2.srocode = a.regsrocode
					where a.applicationnumber = d.applicationnumber
					order by a.memosentdatetime desc
					limit 1
				) ar on true
				order by d.finalregistrationnumber)
				select cte.*,
                1 as totalcount
                from cte;

end loop;
return v_array;
END;

$$;


ALTER FUNCTION kaverimis.fn_insert_mis_daily_register_of_fees_statutory_docreg_12(_fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_insert_report_queue(text, text, timestamp without time zone, timestamp without time zone, text, text, bigint, text, text, boolean, boolean); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_insert_report_queue(_requestedapi text, _requestedreport text, _fromdate timestamp without time zone, _todate timestamp without time zone, _inputjson text, _requesttype text, _requesteduser bigint, _status text, _reportfilepath text DEFAULT NULL::text, _isreportdownloaded boolean DEFAULT false, _isfiledeleted boolean DEFAULT false) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare
v_cnt bigint;
v_id bigint;
begin
select count(*) into v_cnt
from kaverimis.report_queue
where requestedapi=_requestedapi and
requestedreport=_requestedreport and fromdate=_fromdate
and todate=_todate and requesteduser=_requesteduser 
and inputjson=_inputjson  ;
 


if (v_cnt =0 and _inputjson not like 'DistrictCode=0&SroCode=0%'
		and ((_inputjson not like 'DistrictCode=0%' and _inputjson like '%SroCode=0%'  and (_todate::date -_fromdate::date)::integer<=93 )
		or (_inputjson not like 'DistrictCode=0%' and _inputjson not like '%SroCode=0%'))) then
 
     
 
	INSERT INTO kaverimis.report_queue (
        requestedapi,
        requestedreport,
        fromdate,
        todate,
        inputjson,
        requesttype,
        requesteduser,
        status,
        reportfilepath,
        isreportdownloaded,
        isfiledeleted
    ) VALUES (
        _requestedapi,
        _requestedreport,
        _fromdate,
        _todate,
        _inputjson,
        _requesttype,
       _requesteduser,
        _status,
        _reportfilepath,
        _isreportdownloaded,
        _isfiledeleted
    ) returning rid into v_id;
 
    -- Commit the transaction
   -- COMMIT;
    
    
	
else
		raise notice 'Data already exists';
		return 0;
	
   
end if;
raise notice 'Succefully inserted  into table misreportqueue ';
return v_id;
EXCEPTION
        WHEN others then
        	RAISE EXCEPTION 'Error inserting data into misreportqueue: %', SQLERRM;
            return -1;
  END;
$$;


ALTER FUNCTION kaverimis.fn_insert_report_queue(_requestedapi text, _requestedreport text, _fromdate timestamp without time zone, _todate timestamp without time zone, _inputjson text, _requesttype text, _requesteduser bigint, _status text, _reportfilepath text, _isreportdownloaded boolean, _isfiledeleted boolean) OWNER TO postgres;

