-- Name: fn_insert_report_queue_bck(text, text, timestamp without time zone, timestamp without time zone, text, text, bigint, text, text, boolean, boolean); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_insert_report_queue_bck(_requestedapi text, _requestedreport text, _fromdate timestamp without time zone, _todate timestamp without time zone, _inputjson text, _requesttype text, _requesteduser bigint, _status text, _reportfilepath text DEFAULT NULL::text, _isreportdownloaded boolean DEFAULT false, _isfiledeleted boolean DEFAULT false) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare
v_cnt bigint;
v_id bigint;
begin
select count(*) into v_cnt 
from kaverimis.report_queue
where requestedapi=_requestedapi and 
requestedreport=_requestedreport and fromdate=_fromdate 
and todate=_todate and requesteduser=_requesteduser;


if (v_cnt =0) then

	INSERT INTO kaverimis.report_queue (
        requestedapi,
        requestedreport,
        fromdate,
        todate,
        inputjson,
        requesttype,
        requesteduser,
        status,
        reportfilepath,
        isreportdownloaded,
        isfiledeleted
    ) VALUES (
        _requestedapi,
        _requestedreport,
        _fromdate,
        _todate,
        _inputjson,
        _requesttype,
       _requesteduser,
        _status,
        _reportfilepath,
        _isreportdownloaded,
        _isfiledeleted
    ) returning rid into v_id;

    -- Commit the transaction
   -- COMMIT;
    
    
	
else
		raise notice 'Data already exists';
		return 0;
	
   
end if;
raise notice 'Succefully inserted  into table misreportqueue ';
return v_id;
EXCEPTION
        WHEN others then
        	RAISE EXCEPTION 'Error inserting data into misreportqueue: %', SQLERRM;
            return -1;
  END;
$$;


ALTER FUNCTION kaverimis.fn_insert_report_queue_bck(_requestedapi text, _requestedreport text, _fromdate timestamp without time zone, _todate timestamp without time zone, _inputjson text, _requesttype text, _requesteduser bigint, _status text, _reportfilepath text, _isreportdownloaded boolean, _isfiledeleted boolean) OWNER TO postgres;

--
-- Name: fn_jurisdictionalwise_report(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, bigint, bigint); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_jurisdictionalwise_report(_districtcode bigint, _jurisdictionaloffice bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval bigint DEFAULT NULL::bigint, _maxval bigint DEFAULT NULL::bigint) RETURNS TABLE(district character varying, jurisdictionaloffice character varying, regsroname character varying, finalregistrationnumber character varying, copy_of_doc text, stampduty numeric, registrationfees numeric, otherfees numeric, total numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE
--PageOffset INTEGER := 0;
BEGIN	
--PageOffset := ((pagenumber - 1) * pagesize);	
if _districtcode=0 then--All Sro
	
		if _amounttype = 0 then --no amounttype 
		return query 
		with a as 
        (select distinct 
		c.districtnamee as districtname,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode) as jurisdictionoffice,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode) as regsroname,
		dm.finalregistrationnumber,dm.applicationnumber 
	   from kaveri.anywhere_reg_log arl
		left join kaveri.documentmaster dm on arl.applicationnumber = dm.applicationnumber
		join kaveri.sromaster b on dm.srocode = b.srocode
		join kaveri.districtmaster c on b.districtcode = c.districtcode
		where  arl.regsrocode=_jurisdictionaloffice and 
		arl.ismemosent = true and dm.registrationdatetime >=_fromdate and dm.registrationdatetime <= _todate 
		group by dm.finalregistrationnumber,c.districtnamee,arl.regsrocode,arl.srocode,dm.applicationnumber)
        select a.districtname,a.jurisdictionoffice,a.regsroname,a.finalregistrationnumber,
		dm.uploaddocdeedpath as copy_of_doc,
	    sum(case when fr.feerulecode in (36,58,59) then amountpaid else 0 end) as Stamp_duty,
		sum(case when fr.feerulecode=1 then amountpaid else 0 end) as Registration_fee,
		sum(case when fr.feerulecode not in (1,36,58,59)then amountpaid else 0 end) as otherfees ,
		sum(case when fr.feerulecode in (36,58,59) then amountpaid else 0 end)+
		sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
		sum(case when fr.feerulecode not in (1,36,58,59)then amountpaid else 0 end) as Total
        from 
        kaveri.documentmaster dm 
		join kaveri.feesrequired fr on fr.applicationnumber=dm.applicationnumber 
		join a on a.applicationnumber = dm.applicationnumber 
        group by a.districtname,a.jurisdictionoffice,a.regsroname,a.finalregistrationnumber,dm.uploaddocdeedpath;
		
		--OFFSET PageOffset
			--	FETCH NEXT pagesize ROWS ONLY;
		elsif _amounttype=1 THEN --Total
		
		return query 
		with a as 
        (select distinct 
		c.districtnamee as districtname,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode) as jurisdictionoffice,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode) as regsroname,
		dm.finalregistrationnumber,dm.applicationnumber 
	    from kaveri.anywhere_reg_log arl
		left join kaveri.documentmaster dm on arl.applicationnumber = dm.applicationnumber
		join kaveri.sromaster b on dm.srocode = b.srocode
		join kaveri.districtmaster c on b.districtcode = c.districtcode
		join kaveri.feesrequired fr on fr.applicationnumber=dm.applicationnumber
		where  arl.regsrocode=_jurisdictionaloffice and 
		arl.ismemosent = true and dm.registrationdatetime >=_fromdate and dm.registrationdatetime <= _todate 
		group by dm.finalregistrationnumber,c.districtnamee,arl.regsrocode,arl.srocode,dm.applicationnumber
		having sum(case when fr.feerulecode in (36,58,59) then amountpaid else 0 end)+
		sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
		sum(case when fr.feerulecode not in (1,36,58,59)then amountpaid else 0 end) >=_minval 
		and sum(case when fr.feerulecode in (36,58,59) then amountpaid else 0 end)+
		sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
		sum(case when fr.feerulecode not in (1,36,58,59)then amountpaid else 0 end)<=_maxval)
        select a.districtname,a.jurisdictionoffice,a.regsroname,a.finalregistrationnumber,
		dm.uploaddocdeedpath as copy_of_doc,
	    sum(case when fr.feerulecode in (36,58,59) then amountpaid else 0 end) as Stamp_duty,
		sum(case when fr.feerulecode=1 then amountpaid else 0 end) as Registration_fee,
		sum(case when fr.feerulecode not in (1,36,58,59)then amountpaid else 0 end) as otherfees ,
		sum(case when fr.feerulecode in (36,58,59) then amountpaid else 0 end)+
		sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
		sum(case when fr.feerulecode not in (1,36,58,59)then amountpaid else 0 end) as Total
        from 
        kaveri.documentmaster dm 
		join kaveri.feesrequired fr on fr.applicationnumber=dm.applicationnumber 
		join a on a.applicationnumber = dm.applicationnumber 
        group by a.districtname,a.jurisdictionoffice,a.regsroname,a.finalregistrationnumber,dm.uploaddocdeedpath;
		
		--OFFSET PageOffset
				--FETCH NEXT pagesize ROWS ONLY;
		elsif _amounttype=2 THEN  --Registration_fee
		
		return query 
		with a as 
        (select distinct 
		c.districtnamee as districtname,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode) as jurisdictionoffice,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode) as regsroname,
		dm.finalregistrationnumber,dm.applicationnumber 
	    from kaveri.anywhere_reg_log arl
		left join kaveri.documentmaster dm on arl.applicationnumber = dm.applicationnumber
		join kaveri.sromaster b on dm.srocode = b.srocode
		join kaveri.districtmaster c on b.districtcode = c.districtcode
		join kaveri.feesrequired fr on fr.applicationnumber=dm.applicationnumber
		where  arl.regsrocode=_jurisdictionaloffice and 
		arl.ismemosent = true and dm.registrationdatetime >=_fromdate and dm.registrationdatetime <= _todate 
		group by dm.finalregistrationnumber,c.districtnamee,arl.regsrocode,arl.srocode,dm.applicationnumber
		having 
		sum(case when fr.feerulecode=1 then amountpaid else 0 end) >=_minval 
		and sum(case when fr.feerulecode=1 then amountpaid else 0 end)<=_maxval)
        select a.districtname,a.jurisdictionoffice,a.regsroname,a.finalregistrationnumber,
		dm.uploaddocdeedpath as copy_of_doc,
	    sum(case when fr.feerulecode in (36,58,59) then amountpaid else 0 end) as Stamp_duty,
		sum(case when fr.feerulecode=1 then amountpaid else 0 end) as Registration_fee,
		sum(case when fr.feerulecode not in (1,36,58,59)then amountpaid else 0 end) as otherfees ,
