ALTER FUNCTION kaverimis.fn_jurisdictionalwise_report(_districtcode bigint, _jurisdictionaloffice bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval bigint, _maxval bigint) OWNER TO csgadmin;

--
-- Name: fn_jurisdictionalwise_report(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, bigint, bigint, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_jurisdictionalwise_report(_districtcode bigint, _jurisdictionaloffice bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval bigint DEFAULT NULL::bigint, _maxval bigint DEFAULT NULL::bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, jurisdictionaloffice character varying, regsroname character varying, finalregistrationnumber character varying, copy_of_doc text, stampduty numeric, registrationfees numeric, otherfees numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$


DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);



	
if _districtcode=0 then--All Sro
	
		if _amounttype = 0 then --no amounttype 
		return query 
		with cte as (with a as 
        (select distinct 
		c.districtnamee as districtname,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode) as jurisdictionoffice,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode) as regsroname,
		dm.finalregistrationnumber,dm.applicationnumber 
	   from kaveri.anywhere_reg_log arl
		left join kaveri.documentmaster dm on arl.applicationnumber = dm.applicationnumber
		join kaveri.sromaster b on dm.srocode = b.srocode
		join kaveri.districtmaster c on b.districtcode = c.districtcode
		where  
		--arl.regsrocode=_jurisdictionaloffice and 
		arl.ismemosent = true and  arl.srocode<>0 and arl.regsrocode<>0 and   dm.registrationdatetime >=_fromdate and dm.registrationdatetime <= _todate 
		group by dm.finalregistrationnumber,c.districtnamee,arl.regsrocode,arl.srocode,dm.applicationnumber)
        select a.districtname,a.jurisdictionoffice,a.regsroname,a.finalregistrationnumber,
		dm.uploaddocdeedpath as copy_of_doc,
	    sum(case when fr.feerulecode in (36,58,59) then amountpaid else 0 end) as Stamp_duty,
		sum(case when fr.feerulecode=1 then amountpaid else 0 end) as Registration_fee,
		sum(case when fr.feerulecode not in (1,36,58,59)then amountpaid else 0 end) as otherfees ,
		sum(case when fr.feerulecode in (36,58,59) then amountpaid else 0 end)+
		sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
		sum(case when fr.feerulecode not in (1,36,58,59)then amountpaid else 0 end) as Total
        from 
        kaveri.documentmaster dm 
		join kaveri.feesrequired fr on fr.applicationnumber=dm.applicationnumber 
		join a on a.applicationnumber = dm.applicationnumber 
        group by a.districtname,a.jurisdictionoffice,a.regsroname,a.finalregistrationnumber,dm.uploaddocdeedpath),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
		
		elsif _amounttype=1 THEN --Total
		
		return query 
		with cte as (with a as 
        (select distinct 
		c.districtnamee as districtname,
