			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
		 
		elsif _amounttype=2 THEN  --Registration_fee
		
		return query 
		with cte as (with a as 
        (select distinct 
		c.districtnamee as districtname,
