		having 
		sum(case when fr.feerulecode=1 then amountpaid else 0 end) >=_minval 
		and sum(case when fr.feerulecode=1 then amountpaid else 0 end)<=_maxval)
        select a.districtname,a.jurisdictionoffice,a.regsroname,a.finalregistrationnumber,
		dm.uploaddocdeedpath as copy_of_doc,
	    sum(case when fr.feerulecode in (36,58,59) then amountpaid else 0 end) as Stamp_duty,
		sum(case when fr.feerulecode=1 then amountpaid else 0 end) as Registration_fee,
