ALTER FUNCTION kaverimis.fn_jurisdictionalwise_report_23012024(_districtcode bigint, _jurisdictionaloffice bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval bigint, _maxval bigint, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_jurisdictionalwise_report_temp(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, bigint, bigint); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_jurisdictionalwise_report_temp(_districtcode bigint, _jurisdictionaloffice bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval bigint DEFAULT NULL::bigint, _maxval bigint DEFAULT NULL::bigint) RETURNS TABLE(district character varying, jurisdictionaloffice character varying, regsroname character varying, finalregistrationnumber character varying, stampduty numeric, registrationfees numeric, otherfees numeric, total numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN	
if _districtcode=0 then--All Sro
	
		if _amounttype = 0 then --no amounttype 
		return query 
		select distinct 
		c.districtnamee as districtname,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode) as jurisdictionoffice,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode) as regsroname,
		dm.finalregistrationnumber, 
		sum(distinct case when fr.feerulecode in (36,58,59) then amountpaid else 0 end) as Stamp_duty,
		sum(distinct  case when fr.feerulecode=1 then amountpaid else 0 end) as Registration_fee,
		sum(distinct  case when fr.feerulecode not in (1,36,58,59)then amountpaid else 0 end) as otherfees ,
		sum(distinct case when fr.feerulecode in (36,58,59) then amountpaid else 0 end)+
		sum(distinct  case when fr.feerulecode=1 then amountpaid else 0 end)+
		sum(distinct  case when fr.feerulecode not in (1,36,58,59)then amountpaid else 0 end) as Total
						
		from kaveri.anywhere_reg_log arl
		left join kaveri.documentmaster dm on arl.applicationnumber = dm.applicationnumber
		join kaveri.registrationarticles ra on ra.regarticlecode=dm.regarticlecode
		join kaveri.feesrequired fr on fr.applicationnumber=dm.applicationnumber 
		join kaveri.sromaster b on dm.srocode = b.srocode
		join kaveri.districtmaster c on b.districtcode = c.districtcode
		left join kaveri.propertymaster pm on arl.propertyid = pm.propertyid  
		left join kaveri.propertyschedules ps on pm.propertyid = ps.propertyid 
		where 
		arl.regsrocode=_jurisdictionaloffice and arl.ismemosent = true   AND 
		dm.registrationdatetime >=_fromdate and dm.registrationdatetime <= _todate 
		group by dm.finalregistrationnumber,c.districtnamee,arl.regsrocode,arl.srocode;
		
		elsif _amounttype=1 THEN --Total
		
		return query 
		select distinct 
		c.districtnamee as districtname,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode) as jurisdictionoffice,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode) as regsroname,
		dm.finalregistrationnumber, 
		sum(distinct case when fr.feerulecode in (36,58,59) then amountpaid else 0 end) as Stamp_duty,
		sum(distinct  case when fr.feerulecode=1 then amountpaid else 0 end) as Registration_fee,
		sum(distinct  case when fr.feerulecode not in (1,36,58,59)then amountpaid else 0 end) as otherfees ,
		sum(distinct case when fr.feerulecode in (36,58,59) then amountpaid else 0 end)+
		sum(distinct  case when fr.feerulecode=1 then amountpaid else 0 end)+
