ALTER FUNCTION kaverimis.fn_jurisdictionalwise_report_temp(_districtcode bigint, _jurisdictionaloffice bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval bigint, _maxval bigint) OWNER TO csgadmin;

--
-- Name: fn_jurisdictionalwise_report_temp1(bigint, timestamp without time zone, timestamp without time zone, integer, bigint, bigint, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_jurisdictionalwise_report_temp1(_jurisdictionaloffice bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _feetype integer DEFAULT NULL::integer, _minval bigint DEFAULT NULL::bigint, _maxval bigint DEFAULT NULL::bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer, _choice integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, jurisdictionaloffice character varying, sroname character varying, finalregistrationnumber character varying, stampduty numeric, registrationfees numeric, otherfees numeric, total numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
	
if _choice = 1 then  -- stamp duty,registrationfee,otherfee, and feetype with min and max for particular sro
return query 
select distinct
    d.districtnamee as district,
    vw.sroname as jurisdictionaloffice,
    vw.sroname as sroname,
    vw.finalregistrationnumber,
	 sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end)as StampDuty,
	sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
        sum(case when vw.feerulecode not in (1,36)  then vw.amountpaid else 0 end) as otherfees,
	sum(vw.amountpaid) Total
from kaverimis.vw_mis_revenue_report vw 
inner join  
 (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_jurisdictionaloffice
     and amountpaid >=_minval and amountpaid<=_maxval and feerulecode=_feetype)
     vw1 on vw.applicationnumber=vw1.applicationnumber
 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
where  
vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
   and vw.srocode=_jurisdictionaloffice  group by   d.districtnamee ,
    vw.sroname,
    vw.finalregistrationnumber;


elseif _choice = 2 then -- other fees with min and max for particular sro
return query 
select distinct
    d.districtnamee as district,
    vw.sroname as jurisdictionaloffice,
    vw.sroname as sroname,
    vw.finalregistrationnumber,
	 sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end)as StampDuty,
	sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
        sum(case when vw.feerulecode not in (1,36)  then vw.amountpaid else 0 end) as otherfees,
	sum(vw.amountpaid) Total
from kaverimis.vw_mis_revenue_report vw 
inner join  
 (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_jurisdictionaloffice
     and amountpaid >=_minval and amountpaid<=_maxval and feerulecode not in (1,36))
     vw1 on vw.applicationnumber=vw1.applicationnumber
 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
where  
vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
   and vw.srocode=_jurisdictionaloffice  group by   d.districtnamee ,
    vw.sroname,
    vw.finalregistrationnumber;

elseif (_choice = 3 and _feetype = 3) then -- total with min and max for particular sro
return query 
select distinct
    d.districtnamee as district,
    vw.sroname as jurisdictionaloffice,
    vw.sroname as sroname,
    vw.finalregistrationnumber,
	 sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end)as StampDuty,
	sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
        sum(case when vw.feerulecode not in (1,36)  then vw.amountpaid else 0 end) as otherfees,
	sum(vw.amountpaid) Total
from kaverimis.vw_mis_revenue_report vw 
inner join  
 (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_jurisdictionaloffice
     and amountpaid >=_minval and amountpaid<=_maxval )
     vw1 on vw.applicationnumber=vw1.applicationnumber
 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
where  
vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
   and vw.srocode=_jurisdictionaloffice  group by   d.districtnamee ,
    vw.sroname,
    vw.finalregistrationnumber;


elseif _choice = 4 and _minval is null and _maxval is null then  -- feetype - stamp duty or registrationfee  without min and max for particular sro
return query 
select distinct
    d.districtnamee as district,
    vw.sroname as jurisdictionaloffice,
    vw.sroname as sroname,
    vw.finalregistrationnumber,
	 sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end)as StampDuty,
	sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
        sum(case when vw.feerulecode not in (1,36)  then vw.amountpaid else 0 end) as otherfees,
	sum(vw.amountpaid) Total
from kaverimis.vw_mis_revenue_report vw 
inner join  
 (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_jurisdictionaloffice
      and feerulecode=_feetype)
     vw1 on vw.applicationnumber=vw1.applicationnumber
 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
where  
vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
   and vw.srocode=_jurisdictionaloffice  group by   d.districtnamee ,
    vw.sroname,
    vw.finalregistrationnumber;

elseif (_choice = 5 and _minval is null and _maxval is null) then -- other fees without min and max for particular sro
return query 
select distinct
    d.districtnamee as district,
    vw.sroname as jurisdictionaloffice,
    vw.sroname as sroname,
    vw.finalregistrationnumber,
	 sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end)as StampDuty,
