ALTER FUNCTION kaverimis.fn_jurisdictionalwise_report_temp1(_jurisdictionaloffice bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _feetype integer, _minval bigint, _maxval bigint, pagenumber integer, pagesize integer, _choice integer) OWNER TO csgadmin;

--
-- Name: fn_mis_a_register(bigint, date, date, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_a_register(_srocode bigint, _fromdate date, _todate date, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
declare 
v_data_json json;
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
select row_to_json(data_json) into v_data_json from ( 
select array_to_json(array_agg(row_to_json(app_json))) from (
	(select to_char(dm.presentdatetime,'dd-MM-YYYY') presentdate,case when dm.finalregistrationnumber is not null then dm.finalregistrationnumber else dm.pendingdocumentnumber end documentnumber, 
	s.articlenamee,dm.bookid,pi.name,
	sum(case when fr.feerulecode in (36,59,58) then amountpaid else 0 end) totalduty,
	sum(case when fr.feerulecode=59 then amountpaid else 0 end) cess,
	sum(case when fr.feerulecode=36 then amountpaid else 0 end) stampduty,
	sum(case when fr.feerulecode=1 then amountpaid else 0 end) registrationfees,
	sum(case when fr.feerulecode=31 then amountpaid else 0 end) deficitregistrationfees,
	sum(pm.marketvalue) marketvalue, sum(pm.consideration) consideration,
	sum(case when pm.propertytypeid=28 then pm.surcharge else 0 end) municipalsurcharge,
	sum(case when pm.propertytypeid=17 then pm.surcharge else 0 end) panchayatsurcharge,
	sum(case when fr.feerulecode=2 then amountpaid else 0 end) scanningfees,
	sum(case when fr.feerulecode=6 then amountpaid else 0 end) mutationfees,
	sum(case when fr.feerulecode not in (36,59,58,1,31,28,17,2,6) then amountpaid else 0 end) otherfees,
	to_char(dm.registrationdatetime,'dd-MM-YYYY') registrationdatetime,
	aad.remarks
	from kaveri.documentmaster dm left outer join kaveri.propertymaster pm on
	dm.applicationnumber=pm.applicationnumber left outer join kaveri.feesrequired fr 
	on dm.applicationnumber=fr.applicationnumber left outer join kaveri.applicantapplicationdetails aad
	on aad.applicationnumber=dm.applicationnumber left outer join kaveri.stamparticles s
	on pm.stamparticlecode=s.stamparticlecode left outer join
	(select applicationnumber, name from kaverimis.vw_mis_partyinfo where ispresenter=true
	and presentdatetime between _fromdate and _todate) as pi on pi.applicationnumber=dm.applicationnumber
	where aad.currentstatus in ('CD120','CD134','CD109') and 
	dm.srocode=_srocode and dm.presentdatetime between _fromdate and _todate
	group by dm.finalregistrationnumber,dm.pendingdocumentnumber,s.articlenamee,
	aad.remarks,dm.bookid,dm.registrationdatetime,dm.presentdatetime,pi.name)
	union all
	(
	select distinct 
	to_char(ec.ecdate::date,'DD-MM-YYYY') as ecdate,
	ec.certificatenumber,'EC',NULL::integer as bookid,
	concat_ws(' '::text, cm.firstname, cm.middlename, cm.lastname) AS presenter,	
	NULL::numeric as totalduty,
	NULL::numeric as cess,
	NULL::numeric as stampduty,
	NULL::numeric as registrationfees,
	NULL::numeric as deficitregistrationfees,
	NULL::numeric as marketvalue,
	NULL::numeric as consideration,
	NULL::numeric as municipalsurcharge,
	NULL::numeric as panchayatsurcharge,
	NULL::numeric as scanningfees,
	NULL::numeric as mutationfees,
	(
		select sum(ecfees.payableamount) as amountpaid
		from kaveri.ec_requiredfees ecfees 
		where ecfees.ispaid=true and ec.ecid=ecfees.ecid
		group by ec.ecid
	),
	to_char(ec.signeddatetime,'dd-MM-YYYY') registrationdatetime,
	NULL::character varying as remarks	
	from kaveri.ec_applicationdetails ec
	join kaveri.sromaster sr on ec.kaverisrocode=sr.srocode
	join kaveri.ec_requiredfees ecfees on ec.ecid=ecfees.ecid
	join kaveri.vw_feesrule_mapping fm on ecfees.feeruleid = fm.feerulecode
	JOIN kaveri.applicantapplicationdetails aad ON ec.applicationnumber::text = aad.applicationnumber::text
	JOIN kaveri.citizenmaster cm ON aad.citizenid = cm.citizenid
	/*left join kaveri.ams_reg_epaymenttransdetails pd on pd.applicationnumber=ec.applicationnumber
	LEFT JOIN ( select applicationnumber,
					string_agg((vw.name || ' '::text) || vw.address, ', '::text) as presenter
				from kaveri.vw_mis_partyinfo vw 
				where vw.ispresenter=true and presentdatetime::date=_date
				group by vw.applicationnumber) prt_pr ON prt_pr.applicationnumber = ec.applicationnumber*/
	where ec.kaverisrocode=_srocode and ec.ecdate::date>=_fromdate and ec.ecdate::date<_todate
    )
	union all
	(
	select distinct
	to_char(cc.ccdate,'DD-MM-YYYY') as ccdate,
	cc.certificatenumber,'CC',NULL::integer as bookid,
	concat_ws(' '::text, cm.firstname, cm.middlename, cm.lastname) AS presenter,	
	NULL::numeric as totalduty,
	NULL::numeric as cess,
	NULL::numeric as stampduty,
	NULL::numeric as registrationfees,
	NULL::numeric as deficitregistrationfees,
	NULL::numeric as marketvalue,
	NULL::numeric as consideration,
	NULL::numeric as municipalsurcharge,
	NULL::numeric as panchayatsurcharge,
	NULL::numeric as scanningfees,
	NULL::numeric as mutationfees,
	(
		select sum(ccfees.payableamount) as amountpaid 
		from kaveri.cc_requiredfees ccfees 
		where ccfees.ispaid=true and cc.ccid=ccfees.ccid 
		group by cc.ccid
	),
	to_char(cc.signeddatetime,'dd-MM-YYYY') registrationdatetime,
	NULL::character varying as remarks	
	from kaveri.cc_applicationdetails cc
	join kaveri.sromaster sr on cc.kaverisrocode=sr.srocode
	join kaveri.cc_requiredfees ccfees on cc.ccid=ccfees.ccid
	join kaveri.vw_feesrule_mapping fm on ccfees.feeruleid = fm.feerulecode
	JOIN kaveri.applicantapplicationdetails aad ON cc.applicationnumber::text = aad.applicationnumber::text
    JOIN kaveri.citizenmaster cm ON aad.citizenid = cm.citizenid
	/*left join kaveri.ams_reg_epaymenttransdetails pd on pd.applicationnumber=cc.applicationnumber
	LEFT JOIN ( select applicationnumber,
					string_agg((vw.name || ' '::text) || vw.address, ', '::text) as presenter
				from kaveri.vw_mis_partyinfo vw 
				where vw.ispresenter=true and presentdatetime::date=_date
				group by vw.applicationnumber) prt_pr ON prt_pr.applicationnumber = cc.applicationnumber*/
				
	where cc.kaverisrocode=_srocode and cc.ccdate::date>=_fromdate and cc.ccdate::date<_todate
	)
) app_json 
)data_json;
	 
return v_data_json;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_a_register(_srocode bigint, _fromdate date, _todate date, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_bhoomi_file_upload_report(integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_bhoomi_file_upload_report(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(officename character varying, registrationnumber character varying, surveynumber integer, referencenumber character varying, uploaddate timestamp without time zone, dateofregistration timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	 
return query
select distinct sronamee as officename,
finalregistrationnumber as registrationnumber,
d.survey_no as surveynumber,
e.referenceno as referencenumber,
uploaddocdatetime as uploaddate,
registrationdatetime as dateofregistration
from kaveri.documentmaster a left join kaveri.sromaster b on a.srocode = b.srocode
left join kaveri.propertymaster c on a.documentid = c.documentid
left join kaveri.propertynumberdetails d on c.propertyid = d.propertyid
left join kaveri.fruits_data_recv_details e on a.documentid = e.documentid
where a.srocode = _srocode and registrationdatetime >= _from_date and registrationdatetime <= _to_date
and referenceno is not null;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_bhoomi_file_upload_report(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_cash_collection_report(integer, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_cash_collection_report(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer, _choice integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, officename character varying, documentnumber integer, finalregistrationnumber character varying, presentdate timestamp without time zone, stampduty numeric, registrationfee numeric, otherfees numeric, total numeric, receiptnumber character varying)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);		
if _choice = 1 then  -- stampduty
	return query 
select distinct 
c.districtnamee as districtname,
b.sronamee as officename,
a.documentnumber,
a.finalregistrationnumber,
a.registrationdatetime as presentdate,
case when vw.feerulecode = 36 then
vw.amountpaid else 0 end as stampduty,
case when vw.feerulecode = 1 then
vw.amountpaid else 0 end as registrationfee,
case when vw.feerulecode = 2 then
vw.amountpaid else 0 end as Otherfees,
(case when vw.feerulecode = 36 then
vw.amountpaid else 0 end +
case when vw.feerulecode = 1 then
vw.amountpaid else 0 end +
case when vw.feerulecode = 2 then
vw.amountpaid else 0 end ) as Total,
e.receiptnumber
from kaveri.documentmaster a left join kaveri.sromaster b on a.srocode = b.srocode
left join kaveri.districtmaster c on b.districtcode = c.districtcode
--left join kaveri.feesrequired d on a.applicationnumber = d.applicationnumber
left join kaverimis.vw_mis_revenue_report vw on a.applicationnumber = vw.applicationnumber
left join (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_srocode
     and amountpaid >=_minval and amountpaid<=_maxval and feerulecode=36)
     vw1 on vw.applicationnumber=vw1.applicationnumber
left join kaveri.referencemaster e on a.documentid = e.documentid
where --e.receiptnumber is not null and 
vw.amountpaid > 0 and b.srocode = _srocode
and a.registrationdatetime >= _from_date and  a.registrationdatetime <= _to_date
;
elsif _choice = 2 then -- registrationfee
	return query 
select distinct 
c.districtnamee as districtname,
b.sronamee as officename,
a.documentnumber,
a.finalregistrationnumber,
a.registrationdatetime as presentdate,
case when vw.feerulecode = 36 then
vw.amountpaid else 0 end as stampduty,
case when vw.feerulecode = 1 then
vw.amountpaid else 0 end as registrationfee,
case when vw.feerulecode = 2 then
vw.amountpaid else 0 end as Otherfees,
(case when vw.feerulecode = 36 then
vw.amountpaid else 0 end +
case when vw.feerulecode = 1 then
vw.amountpaid else 0 end +
case when vw.feerulecode = 2 then
vw.amountpaid else 0 end ) as Total,
e.receiptnumber
from kaveri.documentmaster a left join kaveri.sromaster b on a.srocode = b.srocode
left join kaveri.districtmaster c on b.districtcode = c.districtcode
--left join kaveri.feesrequired d on a.applicationnumber = d.applicationnumber
left join kaverimis.vw_mis_revenue_report vw on a.applicationnumber = vw.applicationnumber
left join (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_srocode
     and amountpaid >=_minval and amountpaid<=_maxval and feerulecode=1)
     vw1 on vw.applicationnumber=vw1.applicationnumber
left join kaveri.referencemaster e on a.documentid = e.documentid
where --e.receiptnumber is not null and 
vw.amountpaid > 0 and b.srocode = _srocode
and a.registrationdatetime >= _from_date and  a.registrationdatetime <= _to_date
;
elsif _choice = 3 then -- scanning fee
	return query 
select distinct 
c.districtnamee as districtname,
b.sronamee as officename,
a.documentnumber,
a.finalregistrationnumber,
a.registrationdatetime as presentdate,
case when vw.feerulecode = 36 then
vw.amountpaid else 0 end as stampduty,
case when vw.feerulecode = 1 then
vw.amountpaid else 0 end as registrationfee,
case when vw.feerulecode = 2 then
vw.amountpaid else 0 end as Otherfees,
(case when vw.feerulecode = 36 then
vw.amountpaid else 0 end +
case when vw.feerulecode = 1 then
vw.amountpaid else 0 end +
case when vw.feerulecode = 2 then
vw.amountpaid else 0 end ) as Total,
e.receiptnumber
from kaveri.documentmaster a left join kaveri.sromaster b on a.srocode = b.srocode
left join kaveri.districtmaster c on b.districtcode = c.districtcode
--left join kaveri.feesrequired d on a.applicationnumber = d.applicationnumber
left join kaverimis.vw_mis_revenue_report vw on a.applicationnumber = vw.applicationnumber
left join (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_srocode
     and amountpaid >=_minval and amountpaid<=_maxval and feerulecode=2)
     vw1 on vw.applicationnumber=vw1.applicationnumber
left join kaveri.referencemaster e on a.documentid = e.documentid
where --e.receiptnumber is not null and 
vw.amountpaid > 0 and b.srocode = _srocode
