--
-- Name: fn_mis_cc_or_ec_daily_receipt_details(integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_cc_or_ec_daily_receipt_details(_srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(receiptnumber integer, paymentmode character varying, challannumber character varying, receiptdate timestamp without time zone, applicationnumber character varying, applicantname text, issuedbyoffice character varying, dateofreceipt timestamp without time zone, amount numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
return query 
select distinct a.receiptnumber,
c.descriptionenglish as paymentmode,
d.deptreferencecode as challannumber,
a.dateofreceipt as receiptdate  ,
e.applicationnumber,
e.firstname||' '|| e.middlename ||' '||e.lastname as applicantname,
f.sronamee as issuedbyoffice,
a.dateofreceipt,
b.amount
from kaveri.receiptmaster a left join kaveri.receiptpaymentdetails b on a.receiptid = b.receiptid
left join kaveri.paymentmodemaster c on b.paymentmodeid = c.paymentmodeid
left join kaveri.ams_reg_epaymenttransdetails d on b.receiptid = d.receiptid
left join kaveri.partyinfo e on d.applicationnumber = e.applicationnumber
left join kaveri.sromaster f on a.srocode = f.srocode
where
a.srocode = _srocode and a.dateofreceipt >= _fromdate and a.dateofreceipt < _todate;
END;
$$;


