--
-- Name: fn_mis_challan_details_report(character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_challan_details_report(_challannumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, registrationtype character varying, registrationdate timestamp without time zone, challanreferencenumber character varying, transactiondatetime timestamp without time zone, challanamount bigint, amountpaid numeric, amountpending numeric, challanstatus character varying, documentpendingnumber character varying, registrationnumber character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	 
return query
select distinct c.districtnamee as districtname,
b.sronamee as sroname,
e.servicename as registrationtype,
a.registrationdatetime as registrationdate,
f.chlnrefnum as challanreferencenumber,
f.transactiondatetime as transactiondatetime,
f.totalamount as challanamount,
g.amountpaid,
(f.totalamount - g.amountpaid) as amountpending,
h.paymentstatus as challanstatus,
a.pendingdocumentnumber as documentpendingnumber, 
a.finalregistrationnumber as registrationnumber
from kaveri.documentmaster a left join kaveri.sromaster b on a.srocode = b.srocode
left join kaveri.districtmaster c on b.districtcode = c.districtcode
left join kaveri.referencemaster d on a.documentid = d.documentid 
left join kaveri.servicesmaster e on d.documenttypeid = serviceid
left join kaveri.ams_reg_epaymenttransdetails f on a.applicationnumber = f.applicationnumber
left join kaveri.feesrequired g on a.documentid = g.documentid
left join kaveri.ams_mas_epaymentstatus h on f.paymentstatuscode = h.paymentstatuscode
where f.deptreferencecode = _challannumber and (f.totalamount - g.amountpaid) > 0;
END;
$$;


