ALTER FUNCTION kaverimis.fn_mis_company_transaction_report(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _minval bigint, _maxval bigint, pagenumber integer, pagesize integer, _choice integer) OWNER TO csgadmin;

--
-- Name: fn_mis_company_transaction_report(integer, timestamp without time zone, timestamp without time zone, integer, bigint, bigint, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_company_transaction_report(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _amounttype integer DEFAULT NULL::integer, _minval bigint DEFAULT NULL::bigint, _maxval bigint DEFAULT NULL::bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer, _choice integer DEFAULT NULL::integer) RETURNS TABLE(droname character varying, srooffice character varying, booktype character varying, parttype text, articlename character varying, documentsregistered bigint, stampduty numeric, registrationfee numeric, otherfees numeric, total numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
if _choice = 1 then -- stampduty,registrationfee with min,max
	return query 
select 
c.districtnamee as droname, b.sronamee as srooffice,d.booknameenglish as booktype,null as parttype,
(e.articlenamee) as articlename,count(a.documentid) as documentsregistered,
				sum(case when f.feerulecode in (36,58,59) then
f.amountpaid else 0 end) as stampduty,sum(case when f.feerulecode = 1 then
f.amountpaid else 0 end) registrationfee,sum(case when f.feerulecode not in (1,36) then
f.amountpaid else 0 end) otherfees,
sum(case when f.feerulecode in (36,58,59) then
f.amountpaid else 0 end) +
sum(case when f.feerulecode = 1 then
f.amountpaid else 0 end)  +
sum(case when f.feerulecode not in (1,36) then
f.amountpaid else 0 end) as total
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
 join kaveri.districtmaster c on b.districtcode = c.districtcode
 join kaveri.booktypemaster d on a.bookid = d.bookid
 join kaveri.registrationarticles e on a.regarticlecode = e.regarticlecode
 join kaveri.feesrequired f on a.documentid = f.documentid
 left join kaveri.feesrequired g on f.documentid = g.documentid
where a.srocode = _srocode and a.registrationdatetime >= _from_date and a.registrationdatetime <= _to_date and
f.amountpaid >= _minval and f.amountpaid <= _maxval and isregistrationcompleted = true
and g.feerulecode = _amounttype
group by c.districtnamee,b.sronamee,d.booknameenglish,e.articlenamee;
elseif _choice = 2 then -- stampduty,registrationfee without min,max
	return query 
select 
c.districtnamee as droname, b.sronamee as srooffice,d.booknameenglish as booktype,null as parttype,
(e.articlenamee) as articlename,count(a.documentid) as documentsregistered,
				sum(case when f.feerulecode in (36,58,59) then
f.amountpaid else 0 end) as stampduty,sum(case when f.feerulecode = 1 then
f.amountpaid else 0 end) registrationfee,sum(case when f.feerulecode not in (1,36) then
f.amountpaid else 0 end) otherfees,
sum(case when f.feerulecode in (36,58,59) then
f.amountpaid else 0 end) +
sum(case when f.feerulecode = 1 then
f.amountpaid else 0 end)  +
sum(case when f.feerulecode not in (1,36) then
f.amountpaid else 0 end) as total
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
 join kaveri.districtmaster c on b.districtcode = c.districtcode
 join kaveri.booktypemaster d on a.bookid = d.bookid
 join kaveri.registrationarticles e on a.regarticlecode = e.regarticlecode
 join kaveri.feesrequired f on a.documentid = f.documentid
 left join kaveri.feesrequired g on f.documentid = g.documentid
where a.srocode = _srocode and a.registrationdatetime >= _from_date and a.registrationdatetime <= _to_date and
 isregistrationcompleted = true
and g.feerulecode = _amounttype
group by c.districtnamee,b.sronamee,d.booknameenglish,e.articlenamee;
elsif _choice = 3 then -- other fee with min and max
	return query 
select 
c.districtnamee as droname, b.sronamee as srooffice,d.booknameenglish as booktype,null as parttype,
(e.articlenamee) as articlename,count(a.documentid) as documentsregistered,
