 join kaveri.districtmaster c on b.districtcode = c.districtcode
 join kaveri.booktypemaster d on a.bookid = d.bookid
 join kaveri.registrationarticles e on a.regarticlecode = e.regarticlecode
 join kaveri.feesrequired f on a.documentid = f.documentid
 left join kaveri.feesrequired g on f.documentid = g.documentid
where a.srocode = _srocode and a.registrationdatetime >= _from_date and a.registrationdatetime <= _to_date and
