and g.feerulecode not in (1,36)
group by c.districtnamee,b.sronamee,d.booknameenglish,e.articlenamee;
elsif _choice = 4 then -- otherfee with out min max
	return query 
	select 
c.districtnamee as droname, b.sronamee as srooffice,d.booknameenglish as booktype,null as parttype,
(e.articlenamee) as articlename,count(a.documentid) as documentsregistered,
				sum(case when f.feerulecode in (36,58,59) then
f.amountpaid else 0 end) as stampduty,sum(case when f.feerulecode = 1 then
