 join kaveri.districtmaster c on b.districtcode = c.districtcode
 join kaveri.booktypemaster d on a.bookid = d.bookid
 join kaveri.registrationarticles e on a.regarticlecode = e.regarticlecode
 join kaveri.feesrequired f on a.documentid = f.documentid
 left join kaveri.feesrequired g on f.documentid = g.documentid
where  a.registrationdatetime >= _from_date and a.registrationdatetime <= _to_date and
 isregistrationcompleted = true and   f.amountpaid >= _minval and f.amountpaid <= _maxval
group by c.districtnamee,b.sronamee,d.booknameenglish,e.articlenamee;
elseif _choice = 6 and _srocode = 0 then -- all feerulecodes without  min max
	return query 
	select 
c.districtnamee as droname, b.sronamee as srooffice,d.booknameenglish as booktype,null as parttype,
(e.articlenamee) as articlename,count(a.documentid) as documentsregistered,
				sum(case when f.feerulecode in (36,58,59) then
f.amountpaid else 0 end) as stampduty,sum(case when f.feerulecode = 1 then
f.amountpaid else 0 end) registrationfee,sum(case when f.feerulecode not in (1,36) then
f.amountpaid else 0 end) otherfees,
sum(case when f.feerulecode in (36,58,59) then
f.amountpaid else 0 end) +
sum(case when f.feerulecode = 1 then
f.amountpaid else 0 end)  +
sum(case when f.feerulecode not in (1,36) then
f.amountpaid else 0 end) as total
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
 join kaveri.districtmaster c on b.districtcode = c.districtcode
 join kaveri.booktypemaster d on a.bookid = d.bookid
 join kaveri.registrationarticles e on a.regarticlecode = e.regarticlecode
 join kaveri.feesrequired f on a.documentid = f.documentid
 left join kaveri.feesrequired g on f.documentid = g.documentid
where  a.registrationdatetime >= _from_date and a.registrationdatetime <= _to_date and
 isregistrationcompleted = true 
group by c.districtnamee,b.sronamee,d.booknameenglish,e.articlenamee;

elseif _choice = 7 then -- feerulecode not in (1,36) and with out min max
	return query 
	select 
c.districtnamee as droname, b.sronamee as srooffice,d.booknameenglish as booktype,null as parttype,
(e.articlenamee) as articlename,count(a.documentid) as documentsregistered,
				sum(case when f.feerulecode in (36,58,59) then
f.amountpaid else 0 end) as stampduty,sum(case when f.feerulecode = 1 then
f.amountpaid else 0 end) registrationfee,sum(case when f.feerulecode not in (1,36) then
f.amountpaid else 0 end) otherfees,
sum(case when f.feerulecode in (36,58,59) then
f.amountpaid else 0 end) +
sum(case when f.feerulecode = 1 then
f.amountpaid else 0 end)  +
sum(case when f.feerulecode not in (1,36) then
f.amountpaid else 0 end) as total
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
 join kaveri.districtmaster c on b.districtcode = c.districtcode
 join kaveri.booktypemaster d on a.bookid = d.bookid
 join kaveri.registrationarticles e on a.regarticlecode = e.regarticlecode
 join kaveri.feesrequired f on a.documentid = f.documentid
 left join kaveri.feesrequired g on f.documentid = g.documentid
where  a.registrationdatetime >= _from_date and a.registrationdatetime <= _to_date and
 isregistrationcompleted = true  and g.feerulecode = _amounttype
group by c.districtnamee,b.sronamee,d.booknameenglish,e.articlenamee;

elseif _choice = 8 and _srocode = 0 then -- with all sros particular feerulecode  and with  min max
	return query 
	select 
c.districtnamee as droname, b.sronamee as srooffice,d.booknameenglish as booktype,null as parttype,
(e.articlenamee) as articlename,count(a.documentid) as documentsregistered,
				sum(case when f.feerulecode in (36,58,59) then
f.amountpaid else 0 end) as stampduty,sum(case when f.feerulecode = 1 then
f.amountpaid else 0 end) registrationfee,sum(case when f.feerulecode not in (1,36) then
f.amountpaid else 0 end) otherfees,
sum(case when f.feerulecode in (36,58,59) then
f.amountpaid else 0 end) +
sum(case when f.feerulecode = 1 then
f.amountpaid else 0 end)  +
sum(case when f.feerulecode not in (1,36) then
f.amountpaid else 0 end) as total
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
 join kaveri.districtmaster c on b.districtcode = c.districtcode
 join kaveri.booktypemaster d on a.bookid = d.bookid
 join kaveri.registrationarticles e on a.regarticlecode = e.regarticlecode
 join kaveri.feesrequired f on a.documentid = f.documentid
 left join kaveri.feesrequired g on f.documentid = g.documentid
where  a.registrationdatetime >= _from_date and a.registrationdatetime <= _to_date and
g.feerulecode = _amounttype and  isregistrationcompleted = true and   f.amountpaid >= _minval and f.amountpaid <= _maxval
group by c.districtnamee,b.sronamee,d.booknameenglish,e.articlenamee;

elseif _choice = 9 and _srocode = 0 then -- with all sros others feerulecode  and with  min max
	return query 
	select 
c.districtnamee as droname, b.sronamee as srooffice,d.booknameenglish as booktype,null as parttype,
(e.articlenamee) as articlename,count(a.documentid) as documentsregistered,
				sum(case when f.feerulecode in (36,58,59) then
f.amountpaid else 0 end) as stampduty,sum(case when f.feerulecode = 1 then
f.amountpaid else 0 end) registrationfee,sum(case when f.feerulecode not in (1,36) then
f.amountpaid else 0 end) otherfees,
sum(case when f.feerulecode in (36,58,59) then
f.amountpaid else 0 end) +
sum(case when f.feerulecode = 1 then
f.amountpaid else 0 end)  +
sum(case when f.feerulecode not in (1,36) then
f.amountpaid else 0 end) as total
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
 join kaveri.districtmaster c on b.districtcode = c.districtcode
 join kaveri.booktypemaster d on a.bookid = d.bookid
 join kaveri.registrationarticles e on a.regarticlecode = e.regarticlecode
 join kaveri.feesrequired f on a.documentid = f.documentid
 left join kaveri.feesrequired g on f.documentid = g.documentid
where  g.feerulecode not in (1,36) and a.registrationdatetime >= _from_date and a.registrationdatetime <= _to_date and
  isregistrationcompleted = true and   f.amountpaid >= _minval and f.amountpaid <= _maxval
group by c.districtnamee,b.sronamee,d.booknameenglish,e.articlenamee;

else -- with all sros total feerulecodes  and without  min max
	return query 
		select 
c.districtnamee as droname, b.sronamee as srooffice,d.booknameenglish as booktype,null as parttype,
(e.articlenamee) as articlename,count(a.documentid) as documentsregistered,
				sum(case when f.feerulecode in (36,58,59) then
f.amountpaid else 0 end) as stampduty,sum(case when f.feerulecode = 1 then
f.amountpaid else 0 end) registrationfee,sum(case when f.feerulecode not in (1,36) then
f.amountpaid else 0 end) otherfees,
sum(case when f.feerulecode in (36,58,59) then
f.amountpaid else 0 end) +
sum(case when f.feerulecode = 1 then
f.amountpaid else 0 end)  +
sum(case when f.feerulecode not in (1,36) then
f.amountpaid else 0 end) as total
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
 join kaveri.districtmaster c on b.districtcode = c.districtcode
 join kaveri.booktypemaster d on a.bookid = d.bookid
 join kaveri.registrationarticles e on a.regarticlecode = e.regarticlecode
 join kaveri.feesrequired f on a.documentid = f.documentid
 left join kaveri.feesrequired g on f.documentid = g.documentid
where  a.registrationdatetime >= _from_date and a.registrationdatetime <= _to_date and
  isregistrationcompleted = true
group by c.districtnamee,b.sronamee,d.booknameenglish,e.articlenamee;

end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_company_transaction_report(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _amounttype integer, _minval bigint, _maxval bigint, pagenumber integer, pagesize integer, _choice integer) OWNER TO csgadmin;

--
-- Name: fn_mis_comparativestatementofrevenue(integer, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_comparativestatementofrevenue(_srocode integer, _prev_from_date timestamp without time zone, _prev_to_date timestamp without time zone, _curr_from_date timestamp without time zone, _curr_to_date timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(sroofficename character varying, targetamount_prev_fy numeric, numberofdocuments_prev_fy bigint, stampduty_prev_fy numeric, registrationfee_prev_fy numeric, scanningfee_prev_fy numeric, otherfees_prev_fy numeric, total_prev_fy numeric, targetamount_curr_fy numeric, numberofdocuments_curr_fy bigint, stampduty_curr_fy numeric, registrationfee_curr_fy numeric, scanningfee_curr_fy numeric, otherfees_curr_fy numeric, total_curr_fy numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	 
return query
select distinct 
sronamee as sroofficename,
fy_2021_to_2022.targetamount_2021_2022 as targetamount_prev_fy ,
fy_2021_to_2022.Numberofdocuments_2021_2022 as Numberofdocuments_prev_fy,
fy_2021_to_2022.stampduty_2021_2022 as stampduty_prev_fy,
fy_2021_to_2022.registrationfee_2021_2022 as registrationfee_prev_fy,
fy_2021_to_2022.scanningfee_2021_2022 as scanningfee_prev_fy,
fy_2021_to_2022.otherfees_2021_2022 as otherfees_prev_fy,
fy_2021_to_2022.total_2021_2022 as total_prev_fy,
fy_2022_to_2023.targetamount_2022_2023 as targetamount_curr_fy,
fy_2022_to_2023.Numberofdocuments_2022_2023 as Numberofdocuments_curr_fy,
fy_2022_to_2023.stampduty_2022_2023 as stampduty_curr_fy,
fy_2022_to_2023.registrationfee_2022_2023 as registrationfee_curr_fy,
fy_2022_to_2023.scanningfee_2022_2023 as scanningfee_curr_fy,
fy_2022_to_2023.otherfees_2022_2023 as otherfees_curr_fy,
fy_2022_to_2023.total_2022_2023 as total_curr_fy
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.feesrequired c on a.documentid = c.documentid
join ( select feerulecode,count(b.documentid) Numberofdocuments_2021_2022,
sum(a.amountrequired) as targetamount_2021_2022,
case when feerulecode = 36 then
sum(amountpaid) else 0 end as stampduty_2021_2022,
case when feerulecode = 1 then
sum(amountpaid) else 0 end as registrationfee_2021_2022,
case when feerulecode = 2 then
sum(amountpaid) else 0 end as scanningfee_2021_2022,
case when feerulecode not in (36,1,2) then
sum(amountpaid) else 0 end as otherfees_2021_2022,
(case when feerulecode = 36 then
sum(amountpaid) else 0 end +
case when feerulecode = 1 then
sum(amountpaid) else 0 end +
case when feerulecode = 2 then
sum(amountpaid) else 0 end +
case when feerulecode not in (36,1,2) then
sum(amountpaid) else 0 end ) as Total_2021_2022
from kaveri.feesrequired a join kaveri.documentmaster b on a.documentid = b.documentid
where b.registrationdatetime >= _prev_from_date and b.registrationdatetime <= _prev_to_date	  
	  group by feerulecode
) as fy_2021_to_2022 on c.feerulecode = fy_2021_to_2022.feerulecode
join ( select feerulecode,sum(a.amountrequired) as targetamount_2022_2023,
count(b.documentid) Numberofdocuments_2022_2023,
case when feerulecode = 36 then
sum(amountpaid) else 0 end as stampduty_2022_2023,
case when feerulecode = 1 then
sum(amountpaid) else 0 end as registrationfee_2022_2023,
case when feerulecode = 2 then
sum(amountpaid) else 0 end as scanningfee_2022_2023,
case when feerulecode not in (36,1,2) then
sum(amountpaid) else 0 end as otherfees_2022_2023,
(case when feerulecode = 36 then
sum(amountpaid) else 0 end +
case when feerulecode = 1 then
sum(amountpaid) else 0 end +
case when feerulecode = 2 then
sum(amountpaid) else 0 end +
case when feerulecode not in (36,1,2) then
sum(amountpaid) else 0 end ) as Total_2022_2023
from kaveri.feesrequired a join kaveri.documentmaster b on a.documentid = b.documentid
where b.registrationdatetime >= _curr_from_date and b.registrationdatetime <= _curr_to_date	  
	  group by feerulecode
) as fy_2022_to_2023 on fy_2021_to_2022.feerulecode = fy_2022_to_2023.feerulecode
where isregistrationcompleted = true and a.srocode = _srocode
group by 
sronamee,
fy_2021_to_2022.targetamount_2021_2022,
fy_2021_to_2022.Numberofdocuments_2021_2022,
fy_2021_to_2022.stampduty_2021_2022,
fy_2021_to_2022.registrationfee_2021_2022,
fy_2021_to_2022.scanningfee_2021_2022,
fy_2021_to_2022.otherfees_2021_2022,
fy_2021_to_2022.total_2021_2022,
fy_2022_to_2023.targetamount_2022_2023,
fy_2022_to_2023.Numberofdocuments_2022_2023,
fy_2022_to_2023.stampduty_2022_2023,
fy_2022_to_2023.registrationfee_2022_2023,
fy_2022_to_2023.scanningfee_2022_2023,
fy_2022_to_2023.otherfees_2022_2023,
fy_2022_to_2023.total_2022_2023;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_comparativestatementofrevenue(_srocode integer, _prev_from_date timestamp without time zone, _prev_to_date timestamp without time zone, _curr_from_date timestamp without time zone, _curr_to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_comparativestatementofrevenue(bigint, integer, character varying, character varying, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_comparativestatementofrevenue(_districtcode bigint, _srocode integer, _prevyear character varying, _currentyear character varying, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer) RETURNS TABLE(districtnamee character varying, sronamee character varying, prevtarget numeric, prevnoofdoc bigint, prevstampduty numeric, prevregistrationfee numeric, prevotherfees numeric, prevscanningfees numeric, prevtotalfees numeric, currrevenuetarget numeric, currnoofdoc bigint, currstampduty numeric, currregistrationfee numeric, currotherfees numeric, currscanningfees numeric, currtotalfees numeric)
    LANGUAGE plpgsql
    AS $$



DECLARE

BEGIN	

if _districtcode=0 then 

		if _amounttype=0 then --no min max
 
			return query
			select
			d.districtnamee,
			s.sronamee,
			prev_year.revenuetarget as prevtarget,
			prev_year.noofdoc as prevnoofdoc,
			prev_year.stampduty as prevstampduty,
			prev_year.registrationfee as prevregistrationfee,
			prev_year.otherfees  as  prevotherfees,
			prev_year.scanningfees as prevscanningfees,
			prev_year.Totalfees as prevTotalfees,
			curr_year.revenuetarget as currrevenuetarget,
			curr_year.noofdoc as  currnoofdoc,
			curr_year.stampduty  as currstampduty,
			curr_year.registrationfee as currregistrationfee,
			curr_year.otherfees as  currotherfees,
			curr_year.scanningfees  as currscanningfees,
			curr_year.Totalfees as currTotalfees

			from 
			kaveri.districtmaster d 
			join kaveri.sromaster s on d.districtcode=s.districtcode  --and d.districtcode=_districtcode and s.srocode=_srocode
			left join
			(select distinct
			dm.srocode,
			null::numeric as revenuetarget,
			count(distinct dm.documentid) as noofdoc,
			sum(case when feerulecode in (36,58,59) then amountpaid else 0 end ) as stampduty,
			sum(case when feerulecode = 1 then amountpaid  else 0 end ) as registrationfee,
			sum(case when feerulecode = 2 then amountpaid  else 0 end ) as scanningfees,
			sum(case when feerulecode  not in(1,36,2,58,59) then amountpaid  else 0 end ) as otherfees,
			sum(amountpaid) as Totalfees
			from 
			kaveri.documentmaster dm
			left join kaveri.feesrequired fr on fr.documentid = dm.documentid and fr.srocode = dm.srocode
			/*join (select srocode,documentid,sum(amountpaid) from kaveri.feesrequired where feerulecode=36 group by srocode,documentid having sum(amountpaid)>=_minval 
			and sum(amountpaid)<=_maxval )fr2 
				  on fr.documentid = fr2.documentid and fr.srocode = fr2.srocode*/

			where to_char(dm.registrationdatetime,'YYYY')=_prevyear
			and 
			dm.isregistrationcompleted is true

			group by dm.srocode) prev_year on s.srocode=prev_year.srocode

			left join 

			(select distinct
			dm.srocode,
			null::numeric as revenuetarget,
			count(distinct dm.documentid) as noofdoc,
			sum(case when feerulecode in (36,58,59) then amountpaid else 0 end ) as stampduty,
			sum(case when feerulecode = 1 then amountpaid  else 0 end ) as registrationfee,
			sum(case when feerulecode = 2 then amountpaid  else 0 end ) as scanningfees,
			sum(case when feerulecode  not in(1,36,2,58,59) then amountpaid  else 0 end ) as otherfees,
			sum(amountpaid) as Totalfees
			from 
			kaveri.documentmaster dm
			left join kaveri.feesrequired fr on fr.documentid = dm.documentid and fr.srocode = dm.srocode
			/*join (select srocode,documentid,sum(amountpaid) from kaveri.feesrequired where feerulecode=36 group by srocode,documentid having sum(amountpaid)>=_minval 
			and sum(amountpaid)<=_maxval)fr2 
				  on fr.documentid = fr2.documentid and fr.srocode = fr2.srocode*/

			where to_char(dm.registrationdatetime,'YYYY')=_currentyear
			and dm.isregistrationcompleted is true

			group by dm.srocode) curr_year on s.srocode=curr_year.srocode

			where (prev_year.noofdoc is not null or curr_year.noofdoc is not null) and s.srocode>0; 
			
			elsif _amounttype=1 then --Total with min and max
			
			
			return query
			select
			d.districtnamee,
			s.sronamee,
			prev_year.revenuetarget as prevtarget,
			prev_year.noofdoc as prevnoofdoc,
			prev_year.stampduty as prevstampduty,
			prev_year.registrationfee as prevregistrationfee,
			prev_year.otherfees  as  prevotherfees,
			prev_year.scanningfees as prevscanningfees,
			prev_year.Totalfees as prevTotalfees,
			curr_year.revenuetarget as currrevenuetarget,
			curr_year.noofdoc as  currnoofdoc,
			curr_year.stampduty  as currstampduty,
			curr_year.registrationfee as currregistrationfee,
			curr_year.otherfees as  currotherfees,
			curr_year.scanningfees  as currscanningfees,
			curr_year.Totalfees as currTotalfees

			from 
			kaveri.districtmaster d 
			join kaveri.sromaster s on d.districtcode=s.districtcode  --and d.districtcode=_districtcode and s.srocode=_srocode
			left join
			(select distinct
			dm.srocode,
			null::numeric as revenuetarget,
			count(distinct dm.documentid) as noofdoc,
			sum(case when feerulecode in (36,58,59) then amountpaid else 0 end ) as stampduty,
			sum(case when feerulecode = 1 then amountpaid  else 0 end ) as registrationfee,
			sum(case when feerulecode = 2 then amountpaid  else 0 end ) as scanningfees,
			sum(case when feerulecode  not in(1,36,2,58,59) then amountpaid  else 0 end ) as otherfees,
			sum(amountpaid) as Totalfees
			from 
			kaveri.documentmaster dm
			left join kaveri.feesrequired fr on fr.documentid = dm.documentid and fr.srocode = dm.srocode
			left join (select srocode,documentid,sum(amountpaid) from kaveri.feesrequired  group by srocode,documentid having sum(amountpaid)>=_minval 
			and sum(amountpaid)<=_maxval )fr2 
				  on fr.documentid = fr2.documentid and fr.srocode = fr2.srocode

			where to_char(dm.registrationdatetime,'YYYY')=_prevyear
			and 
			dm.isregistrationcompleted is true

			group by dm.srocode) prev_year on s.srocode=prev_year.srocode

			left join 

			(select distinct
			dm.srocode,
			null::numeric as revenuetarget,
			count(distinct dm.documentid) as noofdoc,
			sum(case when feerulecode in (36,58,59) then amountpaid else 0 end ) as stampduty,
			sum(case when feerulecode = 1 then amountpaid  else 0 end ) as registrationfee,
			sum(case when feerulecode = 2 then amountpaid  else 0 end ) as scanningfees,
			sum(case when feerulecode  not in(1,36,2,58,59) then amountpaid  else 0 end ) as otherfees,
			sum(amountpaid) as Totalfees
			from 
			kaveri.documentmaster dm
			left join kaveri.feesrequired fr on fr.documentid = dm.documentid and fr.srocode = dm.srocode
			left join (select srocode,documentid,sum(amountpaid) from kaveri.feesrequired  group by srocode,documentid having sum(amountpaid)>=_minval
			and sum(amountpaid)<=_maxval )fr2 
				  on fr.documentid = fr2.documentid and fr.srocode = fr2.srocode

			where to_char(dm.registrationdatetime,'YYYY')=_currentyear
			and dm.isregistrationcompleted is true

			group by dm.srocode) curr_year on s.srocode=curr_year.srocode

			where (prev_year.noofdoc is not null or curr_year.noofdoc is not null) and s.srocode>0; 
			
		elsif _amounttype=2 then --Registration fee with min and MAX
		
			return query
			select
			d.districtnamee,
			s.sronamee,
			prev_year.revenuetarget as prevtarget,
			prev_year.noofdoc as prevnoofdoc,
			prev_year.stampduty as prevstampduty,
			prev_year.registrationfee as prevregistrationfee,
			prev_year.otherfees  as  prevotherfees,
			prev_year.scanningfees as prevscanningfees,
			prev_year.Totalfees as prevTotalfees,
			curr_year.revenuetarget as currrevenuetarget,
			curr_year.noofdoc as  currnoofdoc,
			curr_year.stampduty  as currstampduty,
			curr_year.registrationfee as currregistrationfee,
			curr_year.otherfees as  currotherfees,
			curr_year.scanningfees  as currscanningfees,
			curr_year.Totalfees as currTotalfees

			from 
			kaveri.districtmaster d 
			join kaveri.sromaster s on d.districtcode=s.districtcode  --and d.districtcode=_districtcode and s.srocode=_srocode
			left join
			(select distinct
			dm.srocode,
			null::numeric as revenuetarget,
			count(distinct dm.documentid) as noofdoc,
			sum(case when feerulecode in (36,58,59) then amountpaid else 0 end ) as stampduty,
			sum(case when feerulecode = 1 then amountpaid  else 0 end ) as registrationfee,
			sum(case when feerulecode = 2 then amountpaid  else 0 end ) as scanningfees,
			sum(case when feerulecode  not in(1,36,2,58,59) then amountpaid  else 0 end ) as otherfees,
			sum(amountpaid) as Totalfees
			from 
			kaveri.documentmaster dm
			left join kaveri.feesrequired fr on fr.documentid = dm.documentid and fr.srocode = dm.srocode
			left join (select srocode,documentid,sum(amountpaid) from kaveri.feesrequired where feerulecode=1 group by srocode,documentid having sum(amountpaid)>=_minval 
