			sum(case when feerulecode in (36,58,59) then amountpaid else 0 end ) as stampduty,
			sum(case when feerulecode = 1 then amountpaid  else 0 end ) as registrationfee,
			sum(case when feerulecode = 2 then amountpaid  else 0 end ) as scanningfees,
			sum(case when feerulecode  not in(1,36,2,58,59) then amountpaid  else 0 end ) as otherfees,
