ALTER FUNCTION kaverimis.fn_mis_comparativestatementofrevenue(_districtcode bigint, _srocode integer, _prevyear character varying, _currentyear character varying, _amounttype integer, _minval integer, _maxval integer) OWNER TO csgadmin;

--
-- Name: fn_mis_comparativestatementofrevenue(bigint, integer, character varying, character varying, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_comparativestatementofrevenue(_districtcode bigint, _srocode integer, _prevyear character varying, _currentyear character varying, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtnamee character varying, sronamee character varying, prevtarget numeric, prevnoofdoc bigint, prevstampduty numeric, prevregistrationfee numeric, prevotherfees numeric, prevscanningfees numeric, prevtotalfees numeric, currrevenuetarget numeric, currnoofdoc bigint, currstampduty numeric, currregistrationfee numeric, currotherfees numeric, currscanningfees numeric, currtotalfees numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$



DECLARE
PageOffset INTEGER := 0;
v_fromprevyear timestamp without time zone;
v_toprevyear timestamp without time zone;
v_fromcurrentyear timestamp without time zone;
v_tocurrentyear timestamp without time zone;


BEGIN
PageOffset := ((pagenumber - 1) * pagesize);

select to_timestamp(_prevyear||'-04-01','yyyy-mm-dd')  into v_fromprevyear;
select to_timestamp(_prevyear::integer + 1||'-04-01','yyyy-mm-dd')  into v_toprevyear;
select to_timestamp(_currentyear ||'-04-01','yyyy-mm-dd')  into v_fromcurrentyear;
select to_timestamp(_currentyear::integer + 1||'-04-01','yyyy-mm-dd')  into v_tocurrentyear;

