if _districtcode=0 then 

		if _amounttype=0 then --no min max
 
			return query
			with cte as (select
			d.districtnamee,
			s.sronamee,
			prev_year.revenuetarget as prevtarget,
			prev_year.noofdoc as prevnoofdoc,
			prev_year.stampduty as prevstampduty,
