			and v_tocurrentyear)
			and dm.isregistrationcompleted is true

			group by dm.srocode) curr_year on s.srocode=curr_year.srocode

			where (prev_year.noofdoc is not null or curr_year.noofdoc is not null) and s.srocode>0),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY; 
			
			elsif _amounttype=1 then --Total with min and max
			
			
			return query
