			null::numeric as revenuetarget,
			count(distinct dm.documentid) as noofdoc,
			sum(case when feerulecode in (36,58,59) then amountpaid else 0 end ) as stampduty,
			sum(case when feerulecode = 1 then amountpaid  else 0 end ) as registrationfee,
			sum(case when feerulecode = 2 then amountpaid  else 0 end ) as scanningfees,
			sum(case when feerulecode  not in(1,36,2,58,59) and amountpaid>0 then amountpaid  else 0 end ) as otherfees,
			sum(case when  amountpaid>0 then amountpaid  else 0 end )  as Totalfees
			from 
			kaveri.documentmaster dm
			left join kaveri.feesrequired fr on dm.applicationnumber=fr.applicationnumber
			left join (select srocode,documentid,sum(amountpaid) from kaveri.feesrequired where feerulecode  not in(1,36,2) group by srocode,documentid having sum(amountpaid)>=_minval 
			and sum(amountpaid)<=_maxval )fr2 
				  on fr.documentid = fr2.documentid and fr.srocode = fr2.srocode

			where (dm.registrationdatetime between v_fromprevyear 	and v_toprevyear)
			and 
			dm.isregistrationcompleted is true

			group by dm.srocode) prev_year on s.srocode=prev_year.srocode

			left join 

			(select distinct
			dm.srocode,
			null::numeric as revenuetarget,
			count(distinct dm.documentid) as noofdoc,
			sum(case when feerulecode in (36,58,59) then amountpaid else 0 end ) as stampduty,
			sum(case when feerulecode = 1 then amountpaid  else 0 end ) as registrationfee,
			sum(case when feerulecode = 2 then amountpaid  else 0 end ) as scanningfees,
			sum(case when feerulecode  not in(1,36,2,58,59) and amountpaid>0 then amountpaid  else 0 end ) as otherfees,
			sum(case when  amountpaid>0 then amountpaid  else 0 end )  as Totalfees
			from 
			kaveri.documentmaster dm
			left join kaveri.feesrequired fr on dm.applicationnumber=fr.applicationnumber
			left join (select srocode,documentid,sum(amountpaid) from kaveri.feesrequired where  feerulecode  not in(1,36,2) group by srocode,documentid having sum(amountpaid)>=_minval 
			and sum(amountpaid)<=_maxval)fr2 
				  on fr.documentid = fr2.documentid and fr.srocode = fr2.srocode

			where (dm.registrationdatetime between v_fromcurrentyear
			and v_tocurrentyear)
			and dm.isregistrationcompleted is true

			group by dm.srocode) curr_year on s.srocode=curr_year.srocode

			where (prev_year.noofdoc is not null or curr_year.noofdoc is not null) and s.srocode>0),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY; 
			
			
	elsif _amounttype=5 then --scanning fees
	
			return query
			with cte as (select
			d.districtnamee,
			s.sronamee,
			prev_year.revenuetarget as prevtarget,
			prev_year.noofdoc as prevnoofdoc,
			prev_year.stampduty as prevstampduty,
			prev_year.registrationfee as prevregistrationfee,
			prev_year.otherfees  as  prevotherfees,
			prev_year.scanningfees as prevscanningfees,
			prev_year.Totalfees as prevTotalfees,
			curr_year.revenuetarget as currrevenuetarget,
			curr_year.noofdoc as  currnoofdoc,
			curr_year.stampduty  as currstampduty,
			curr_year.registrationfee as currregistrationfee,
			curr_year.otherfees as  currotherfees,
			curr_year.scanningfees  as currscanningfees,
			curr_year.Totalfees as currTotalfees

			from 
			kaveri.districtmaster d 
			join kaveri.sromaster s on d.districtcode=s.districtcode  and d.districtcode=_districtcode and s.srocode=_srocode
			left join
			(select distinct
			dm.srocode,
			null::numeric as revenuetarget,
			count(distinct dm.documentid) as noofdoc,
			sum(case when feerulecode in (36,58,59) then amountpaid else 0 end ) as stampduty,
			sum(case when feerulecode = 1 then amountpaid  else 0 end ) as registrationfee,
			sum(case when feerulecode = 2 then amountpaid  else 0 end ) as scanningfees,
			sum(case when feerulecode  not in(1,36,2,58,59) and amountpaid>0 then amountpaid  else 0 end ) as otherfees,
			sum(case when  amountpaid>0 then amountpaid  else 0 end )  as Totalfees
			from 
			kaveri.documentmaster dm
			left join kaveri.feesrequired fr on dm.applicationnumber=fr.applicationnumber
			left join (select srocode,documentid,sum(amountpaid) from kaveri.feesrequired where feerulecode=2 group by srocode,documentid having sum(amountpaid)>=_minval 
			and sum(amountpaid)<=_maxval )fr2 
				  on fr.documentid = fr2.documentid and fr.srocode = fr2.srocode

			where (dm.registrationdatetime between v_fromprevyear 	and v_toprevyear)
			and 
			dm.isregistrationcompleted is true

			group by dm.srocode) prev_year on s.srocode=prev_year.srocode

			left join 

			(select distinct
			dm.srocode,
			null::numeric as revenuetarget,
			count(distinct dm.documentid) as noofdoc,
			sum(case when feerulecode in (36,58,59) then amountpaid else 0 end ) as stampduty,
			sum(case when feerulecode = 1 then amountpaid  else 0 end ) as registrationfee,
			sum(case when feerulecode = 2 then amountpaid  else 0 end ) as scanningfees,
			sum(case when feerulecode  not in(1,36,2,58,59) and amountpaid>0 then amountpaid  else 0 end )
			as otherfees,
			
			sum(case when  amountpaid>0 then amountpaid  else 0 end )  as Totalfees
			from 
			kaveri.documentmaster dm
			left join kaveri.feesrequired fr on dm.applicationnumber=fr.applicationnumber
			left join (select srocode,documentid,sum(amountpaid) from kaveri.feesrequired 
			where feerulecode=2 group by srocode,documentid having sum(amountpaid)>=_minval 
			and sum(amountpaid)<=_maxval)fr2 
				  on fr.documentid = fr2.documentid and fr.srocode = fr2.srocode

			where (dm.registrationdatetime between v_fromcurrentyear
			and v_tocurrentyear)
			and dm.isregistrationcompleted is true

			group by dm.srocode) curr_year on s.srocode=curr_year.srocode

			where (prev_year.noofdoc is not null or curr_year.noofdoc is not null) and s.srocode>0),
			cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
			
		end if;
		
		
	end if;
		
		
			

END;
$$;


ALTER FUNCTION kaverimis.fn_mis_comparativestatementofrevenue(_districtcode bigint, _srocode integer, _prevyear character varying, _currentyear character varying, _amounttype integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_concurrent_audit_revenue_report(integer, integer, integer, timestamp without time zone, timestamp without time zone, boolean, boolean, boolean, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_concurrent_audit_revenue_report(_districtcode integer, _srocode integer, _auditorid integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _isgreater boolean, _isequal boolean, _isaccepted boolean, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
v_data_json json;
v_fromdate date;
v_todate date;

BEGIN	 
PageOffset := (pagesize*pagenumber) - pagesize;
v_fromdate :=_from_date;
v_todate :=_to_date;
	 
select array_to_json(array_agg(row_to_json(dashboard)))   into v_data_json 

from (

SELECT *, COUNT(*) OVER() AS "totalcount" from (

	select DISTINCT
	ad.applicationnumber AS applicationnum,
    COALESCE(ad.applicationdate::date, ad.applicationstartdate::date) AS applicationdate,
    rg.articlenamee,
    dsm.districtnamee,
	sm.sronamee as srooffice,
    ad.srocode,
    vsar.*

   FROM kaveri.applicantapplicationdetails ad
	JOIN kaveri.vw_scrutinyfeechange_applicationforscruity_revenue vsar on vsar.applicationnumber::text = ad.applicationnumber ::text
	JOIN kaveri.registrationarticles rg ON vsar.regarticlecode = rg.regarticlecode
	JOIN kaveri.sromaster sm on sm.srocode=ad.srocode
	JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
	and  (case when _from_date is not null and _to_date is not null then vsar.auditcompleteddatetime::date between _from_date
             and _to_date
                    else true
             end)
	and (
		case
		when _districtcode <> 0 then dsm.districtcode = _districtcode
		else true
	end
	)
	and (
		case
		when _srocode <> 0 then ad.srocode = _srocode
		else true
	end
	)
	and (
		case
		when _auditorid <> 0 then vsar.auditor = _auditorid
		else true
	end
	)
	and (
		case
		when _isaccepted is true then vsar.isaccepted = _isaccepted
		when _isaccepted is false then vsar.isaccepted = _isaccepted
		else 
			true
	end
	)
	and vsar.isauditcompleted is true
group by ad.applicationnumber,
    ad.applicationdate, ad.applicationstartdate,
    rg.articlenamee,
    vsar.auditcompleteddatetime,
    vsar.audtr_rmrksfilepath,
    dsm.districtnamee,
	sm.sronamee,
    ad.srocode,
    vsar.auditor,
    vsar.applicationnumber,
    vsar.auditorname_designation,
    vsar.totalauditorcalculation,
    vsar.totalsrocalculation,
    vsar.auditoramountrequiredstampduty,
    vsar.sroamountrequiredstampduty,
    vsar.auditoramountrequiredregistrationfees,
    vsar.sroamountrequiredregistrationfees,
    vsar.regarticlecode,
    vsar.isaccepted,
    vsar.isauditcompleted,
    vsar.sr_remarks,
    vsar.username,
	vsar.uploaddocdeedpath
having
	 (
		case
		when _isgreater is true then vsar.totalauditorcalculation > vsar.totalsrocalculation
		when _isgreater is false then vsar.totalauditorcalculation < vsar.totalsrocalculation
		when _isequal is false then vsar.totalauditorcalculation = vsar.totalsrocalculation
	
		else true
	end
	) 
	
	) AS countquery
 
	offset pageoffset
	fetch next pagesize rows only  
) as dashboard ;


return v_data_json; 

END; 
$$;


