--
-- Name: fn_mis_concurrent_audited_report(integer, integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_concurrent_audited_report(_districtcode integer, _srocode integer, _auditorid integer, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
v_data_json json;
v_fromdate date;
v_todate date;

BEGIN	 
--PageOffset := ((pagenumber - 1) * pagesize);
PageOffset := (pagesize*pagenumber) - pagesize;
v_fromdate :=_from_date;
v_todate :=_to_date;
	 
select array_to_json(array_agg(row_to_json(dashboard)))   into v_data_json 

from (	

SELECT *, COUNT(*) OVER() AS "totalcount" from (

 SELECT DISTINCT ad.applicationnumber AS applicationnum,
    COALESCE(ad.applicationdate::date, ad.applicationstartdate::date) AS applicationdate,
    rg.articlenamee,
    a.auditcompleteddatetime,
    a.audtr_rmrksfilepath,
    dsm.districtnamee,
	sm.sronamee as srooffice,
	usr.username,
    ad.srocode,
    (select concat_ws(' '::text, du.firstname, du.middlename, du.lastname) AS auditorname from kaveri.departmentusers du where du.userid = a.auditor) auditorname,
    a.auditor,
    case
		when vd.uploaddocdeedpath is null then 'Not Registered'
		when vd.uploaddocdeedpath is not null then vd.uploaddocdeedpath
	end as uploaddocdeedpath
   FROM kaveri.applicantapplicationdetails ad
     JOIN kaveri.applicationforscrutiny a  ON a.applicationnumber::text = ad.applicationnumber::text
     LEFT JOIN kaveri.vw_department_users usr ON usr.userid = ad.sfdaid
     JOIN kaveri.registrationarticles rg ON a.regarticlecode = rg.regarticlecode
     JOIN kaveri.propertymaster pm ON pm.applicationnumber::text = ad.applicationnumber::text
	 join kaveri.sromaster sm on sm.srocode=ad.srocode
	 JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
	 left join kaveri.vw_documentmaster vd on vd.applicationnumber = a.applicationnumber
     WHERE  a.isauditcompleted is true -- and ad.currentstatus::text = 'CD142'
  
and (case when _from_date is not null and _to_date is not null then a.auditcompleteddatetime::date between _from_date
             and _to_date
                    else true
             end)
and (
	case
	when _districtcode <> 0 then dsm.districtcode = _districtcode
	else true
end
)
and (
	case
	when _srocode <> 0 then ad.srocode = _srocode
	else true
end
)
and (
	case
	when _auditorid <> 0 then a.auditor = _auditorid
	else true
end
)

) AS countquery

                 
  offset pageoffset
fetch next pagesize rows only  

 ) as dashboard;

return v_data_json; 

END; 
$$;


