--
-- Name: fn_mis_concurrent_unattended_report(integer, integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_concurrent_unattended_report(_districtcode integer, _srocode integer, _auditorid integer, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
v_data_json json;
v_fromdate date;
v_todate date;

BEGIN	 
PageOffset := ((pagenumber - 1) * pagesize);
--PageOffset := (pagesize*pagenumber) - pagesize;
v_fromdate :=_from_date;
v_todate :=_to_date;
	 
select array_to_json(array_agg(row_to_json(dashboard)))   into v_data_json 

from (				

SELECT *, COUNT(*) OVER() AS "totalcount" from (

		SELECT distinct ash.id,
		ad.applicationnumber AS applicationnum,
    COALESCE(ad.applicationdate::date, ad.applicationstartdate::date) AS applicationdate,
    rg.articlenamee,
    ash.previous_dateofallocation,
--    ash.
--    a.audtr_rmrksfilepath as auditorremarks,
    dsm.districtnamee,
	sm.sronamee as srooffice,
	usr.username,
    ad.srocode,
    (select concat_ws(' '::text, du.firstname, du.middlename, du.lastname) AS auditorname from kaveri.departmentusers du where du.userid = ash.previous_auditor) auditorname,
    ash.previous_auditor
   FROM kaveri.applicantapplicationdetails ad
     JOIN kaveri.applicationforscrutiny a  ON a.applicationnumber::text = ad.applicationnumber::text
     JOIN kaveri.application_audit_scrutiny_history ash ON ad.applicationnumber::text = ash.applicationnumber::text
     LEFT JOIN kaveri.vw_department_users usr ON usr.userid = ad.sfdaid
     JOIN kaveri.registrationarticles rg ON a.regarticlecode = rg.regarticlecode
--     JOIN kaveri.propertymaster pm ON pm.applicationnumber::text = ad.applicationnumber::text
	 join kaveri.sromaster sm on sm.srocode=ad.srocode
	 JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
--     WHERE a.isauditcompleted is false
and (case when _from_date is not null and _to_date is not null then ash.previous_dateofallocation between _from_date
             and _to_date
                    else true
             end)
and (
	case
	when _districtcode <> 0 then dsm.districtcode = _districtcode
	else true
end
)
and (
	case
	when _srocode <> 0 then ad.srocode = _srocode
	else true
end
)
and (
	case
	when _auditorid <> 0 then ash.previous_auditor = _auditorid
	else true
end
) 

) AS countquery

                 
  offset pageoffset
fetch next pagesize rows only  

) as dashboard ;


--limit pagesize offset PageOffset;

return v_data_json; 

END; 
$$;


