ALTER FUNCTION kaverimis.fn_mis_concurrent_unattended_report_bck(_districtcode integer, _srocode integer, _auditorid integer, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_receipt_details(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_daily_receipt_details(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer DEFAULT 0, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(distirctname character varying, sroname character varying, documentnumber integer, challannumber text, articlename character varying, finalregistrationnumber character varying, copy_of_document text, receiptnumber text, dateofreceipt text, description text, paymentmode text, stampduty numeric, registrationfee numeric, scanningfee numeric, otherfees numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
declare
    pageoffset integer := 0;
begin
    if _choice is null then
        _choice := 0;
    end if;

    if pagenumber is not null and pagesize is not null and pagenumber <> -1 and pagesize <> -1 then
        pageoffset := (pagesize * pagenumber) - pagesize;

        return query
        with base_docs as (
            select
                d.documentid,
                d.applicationnumber,
                di.districtnamee::varchar as distirctname,
                s.sronamee::varchar as sroname,
                d.documentnumber,
                r.articlenamee::varchar as articlename,
                d.finalregistrationnumber,
                d.uploaddocdeedpath::text as copy_of_document
            from kaveri.documentmaster d
            join kaveri.sromaster s
                on d.srocode = s.srocode
            join kaveri.districtmaster di
                on s.districtcode = di.districtcode
            left join kaveri.registrationarticles r
                on d.regarticlecode = r.regarticlecode
            where d.isregistrationcompleted = true
              and d.registrationdatetime between _fromdate::timestamp and _todate::timestamp + interval '1 day'
              and (
                    case
                        when _districtcode <> 0 then di.districtcode = _districtcode
                        else true
                    end
                  )
              and (
                    case
                        when _srocode <> 0 then d.srocode = _srocode
                        else true
                    end
                  )
        ),
        success_epay as (
            select
                e.applicationnumber,
                e.feerulecode,
                e.totalamount,
                e.deptreferencecode,
                b.paymentmode
            from kaveri.ams_reg_epaymenttransdetails e
            join kaveri.ams_reg_epaymentbankackdetails b
                on b.deptreferencecode = e.deptreferencecode
            where e.isdelete = false
              and b.paymentstatuscode in ('10700066','10700072')
              and e.applicationnumber in (select applicationnumber from base_docs)
        ),
        amt as (
            select
                se.applicationnumber,
                coalesce(sum(se.totalamount) filter (
                    where se.feerulecode in (35,36,58,59,64,89,91,92,99,100,101,107,110,138)
                ), 0) as stamp_amt,
                coalesce(sum(se.totalamount) filter (
                    where se.feerulecode in (
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ), 0) as regfee_amt,
                coalesce(sum(se.totalamount) filter (
                    where se.feerulecode = 2
                ), 0) as scanning_amt,
                coalesce(sum(se.totalamount) filter (
                    where se.feerulecode not in (
                        35,36,58,59,64,89,91,92,99,100,101,107,110,138,
                        2,
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ), 0) as other_amt,
                coalesce(sum(se.totalamount), 0) as total_amt
            from success_epay se
            group by se.applicationnumber
        ),
        pay_info as (
            select
                se.applicationnumber,
                string_agg(distinct se.deptreferencecode, ',') as challannumber,
                string_agg(distinct se.paymentmode, ',') as paymentmode
            from success_epay se
            group by se.applicationnumber
        ),
        receipt_info as (
            select
                bd.documentid,
                string_agg(distinct rm.receiptnumber::text, ',') as receiptnumber,
                string_agg(distinct to_char(rm.dateofreceipt, 'dd-mm-yyyy'), ',') as dateofreceipt
            from base_docs bd
            left join kaveri.receiptmaster rm
                on bd.documentid = rm.documentid
            group by bd.documentid
        ),
        schedule_info as (
            select
                bd.documentid,
                string_agg(
                    distinct ('Schedule ' || ps.scheduletype || ' - ' || ps.description),
                    ','
                ) as description
            from base_docs bd
            join kaveri.propertymaster p
                on p.documentid = bd.documentid
            left join kaveri.propertyschedules ps
                on ps.propertyid = p.propertyid
            group by bd.documentid
        ),
        final_data as (
            select
                bd.distirctname,
                bd.sroname,
                bd.documentnumber,
                pi.challannumber,
                bd.articlename,
                bd.finalregistrationnumber,
                bd.copy_of_document,
                ri.receiptnumber,
                ri.dateofreceipt,
                si.description,
                pi.paymentmode,
                coalesce(a.stamp_amt, 0) as stampduty,
                coalesce(a.regfee_amt, 0) as registrationfee,
                coalesce(a.scanning_amt, 0) as scanningfee,
                coalesce(a.other_amt, 0) as otherfees,
                coalesce(a.total_amt, 0) as total
            from base_docs bd
            left join amt a
                on a.applicationnumber = bd.applicationnumber
            left join pay_info pi
                on pi.applicationnumber = bd.applicationnumber
            left join receipt_info ri
                on ri.documentid = bd.documentid
            left join schedule_info si
                on si.documentid = bd.documentid
            where case
                when _choice = 0 then true
                when _choice = 1 then coalesce(a.total_amt, 0) >= coalesce(_minval, 0)
                                  and coalesce(a.total_amt, 0) <= coalesce(_maxval, 999999999999999)
                when _choice = 2 then coalesce(a.regfee_amt, 0) >= coalesce(_minval, 0)
                                  and coalesce(a.regfee_amt, 0) <= coalesce(_maxval, 999999999999999)
                when _choice = 3 then coalesce(a.stamp_amt, 0) >= coalesce(_minval, 0)
                                  and coalesce(a.stamp_amt, 0) <= coalesce(_maxval, 999999999999999)
                when _choice = 4 then coalesce(a.scanning_amt, 0) >= coalesce(_minval, 0)
                                  and coalesce(a.scanning_amt, 0) <= coalesce(_maxval, 999999999999999)
                when _choice = 5 then coalesce(a.other_amt, 0) >= coalesce(_minval, 0)
                                  and coalesce(a.other_amt, 0) <= coalesce(_maxval, 999999999999999)
                else true
            end
        )
        select
            fd.distirctname,
            fd.sroname,
            fd.documentnumber,
            fd.challannumber,
            fd.articlename,
            fd.finalregistrationnumber,
            fd.copy_of_document,
            fd.receiptnumber,
            fd.dateofreceipt,
            fd.description,
            fd.paymentmode,
            fd.stampduty,
            fd.registrationfee,
            fd.scanningfee,
            fd.otherfees,
            fd.total,
            count(*) over() as totalcount
        from final_data fd
        order by fd.distirctname, fd.sroname, fd.documentnumber
        limit pagesize offset pageoffset;

    else
        return query
        with base_docs as (
            select
                d.documentid,
                d.applicationnumber,
                di.districtnamee::varchar as distirctname,
                s.sronamee::varchar as sroname,
                d.documentnumber,
                r.articlenamee::varchar as articlename,
                d.finalregistrationnumber,
                d.uploaddocdeedpath::text as copy_of_document
            from kaveri.documentmaster d
            join kaveri.sromaster s
                on d.srocode = s.srocode
            join kaveri.districtmaster di
                on s.districtcode = di.districtcode
            left join kaveri.registrationarticles r
                on d.regarticlecode = r.regarticlecode
            where d.isregistrationcompleted = true
              and d.registrationdatetime between _fromdate::timestamp and _todate::timestamp + interval '1 day'
              and (
                    case
                        when _districtcode <> 0 then di.districtcode = _districtcode
                        else true
                    end
                  )
              and (
                    case
                        when _srocode <> 0 then d.srocode = _srocode
                        else true
                    end
                  )
        ),
        success_epay as (
            select
                e.applicationnumber,
                e.feerulecode,
                e.totalamount,
                e.deptreferencecode,
                b.paymentmode
            from kaveri.ams_reg_epaymenttransdetails e
            join kaveri.ams_reg_epaymentbankackdetails b
                on b.deptreferencecode = e.deptreferencecode
            where e.isdelete = false
              and b.paymentstatuscode in ('10700066','10700072')
              and e.applicationnumber in (select applicationnumber from base_docs)
        ),
        amt as (
            select
                se.applicationnumber,
                coalesce(sum(se.totalamount) filter (
                    where se.feerulecode in (35,36,58,59,64,89,91,92,99,100,101,107,110,138)
                ), 0) as stamp_amt,
                coalesce(sum(se.totalamount) filter (
                    where se.feerulecode in (
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ), 0) as regfee_amt,
                coalesce(sum(se.totalamount) filter (
                    where se.feerulecode = 2
                ), 0) as scanning_amt,
                coalesce(sum(se.totalamount) filter (
                    where se.feerulecode not in (
                        35,36,58,59,64,89,91,92,99,100,101,107,110,138,
                        2,
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ), 0) as other_amt,
                coalesce(sum(se.totalamount), 0) as total_amt
            from success_epay se
            group by se.applicationnumber
        ),
        pay_info as (
            select
                se.applicationnumber,
                string_agg(distinct se.deptreferencecode, ',') as challannumber,
                string_agg(distinct se.paymentmode, ',') as paymentmode
            from success_epay se
            group by se.applicationnumber
        ),
        receipt_info as (
            select
                bd.documentid,
                string_agg(distinct rm.receiptnumber::text, ',') as receiptnumber,
                string_agg(distinct to_char(rm.dateofreceipt, 'dd-mm-yyyy'), ',') as dateofreceipt
            from base_docs bd
            left join kaveri.receiptmaster rm
                on bd.documentid = rm.documentid
            group by bd.documentid
        ),
        schedule_info as (
            select
                bd.documentid,
                string_agg(
                    distinct ('Schedule ' || ps.scheduletype || ' - ' || ps.description),
                    ','
                ) as description
            from base_docs bd
            join kaveri.propertymaster p
                on p.documentid = bd.documentid
            left join kaveri.propertyschedules ps
                on ps.propertyid = p.propertyid
            group by bd.documentid
        ),
        final_data as (
            select
                bd.distirctname,
                bd.sroname,
                bd.documentnumber,
                pi.challannumber,
                bd.articlename,
                bd.finalregistrationnumber,
                bd.copy_of_document,
                ri.receiptnumber,
                ri.dateofreceipt,
                si.description,
                pi.paymentmode,
                coalesce(a.stamp_amt, 0) as stampduty,
                coalesce(a.regfee_amt, 0) as registrationfee,
                coalesce(a.scanning_amt, 0) as scanningfee,
                coalesce(a.other_amt, 0) as otherfees,
                coalesce(a.total_amt, 0) as total
            from base_docs bd
            left join amt a
                on a.applicationnumber = bd.applicationnumber
            left join pay_info pi
                on pi.applicationnumber = bd.applicationnumber
            left join receipt_info ri
                on ri.documentid = bd.documentid
            left join schedule_info si
                on si.documentid = bd.documentid
            where case
                when _choice = 0 then true
                when _choice = 1 then coalesce(a.total_amt, 0) >= coalesce(_minval, 0)
                                  and coalesce(a.total_amt, 0) <= coalesce(_maxval, 999999999999999)
                when _choice = 2 then coalesce(a.regfee_amt, 0) >= coalesce(_minval, 0)
                                  and coalesce(a.regfee_amt, 0) <= coalesce(_maxval, 999999999999999)
                when _choice = 3 then coalesce(a.stamp_amt, 0) >= coalesce(_minval, 0)
                                  and coalesce(a.stamp_amt, 0) <= coalesce(_maxval, 999999999999999)
                when _choice = 4 then coalesce(a.scanning_amt, 0) >= coalesce(_minval, 0)
                                  and coalesce(a.scanning_amt, 0) <= coalesce(_maxval, 999999999999999)
                when _choice = 5 then coalesce(a.other_amt, 0) >= coalesce(_minval, 0)
                                  and coalesce(a.other_amt, 0) <= coalesce(_maxval, 999999999999999)
                else true
            end
        )
        select
            fd.distirctname,
            fd.sroname,
            fd.documentnumber,
            fd.challannumber,
            fd.articlename,
            fd.finalregistrationnumber,
            fd.copy_of_document,
            fd.receiptnumber,
            fd.dateofreceipt,
            fd.description,
            fd.paymentmode,
            fd.stampduty,
            fd.registrationfee,
            fd.scanningfee,
            fd.otherfees,
            fd.total,
            null::bigint as totalcount
        from final_data fd
        order by fd.distirctname, fd.sroname, fd.documentnumber;
    end if;
end;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_receipt_details(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_daily_receipt_details_20260204(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: manjunathswamy
--

CREATE FUNCTION kaverimis.fn_mis_daily_receipt_details_20260204(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer DEFAULT 0, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(distirctname character varying, sroname character varying, documentnumber integer, challannumber text, articlename character varying, finalregistrationnumber character varying, copy_of_document text, receiptnumber text, dateofreceipt text, description text, paymentmode text, stampduty numeric, registrationfee numeric, scanningfee numeric, otherfees numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    PageOffset INTEGER := 0;
BEGIN
    PageOffset := (pagesize * pagenumber) - pagesize;

    IF (pagenumber <> -1 AND pagesize <> -1) THEN

        RETURN QUERY
        WITH
        base_docs AS (
            SELECT
                d.documentid,
                d.applicationnumber,
                d.finalregistrationnumber,
                d.documentnumber,
                d.regarticlecode,
                d.uploaddocdeedpath,
                d.srocode,
                d.registrationdatetime,
                di.districtnamee AS distirctname,
                s.sronamee
            FROM kaveri.documentmaster d
            JOIN kaveri.sromaster s
              ON d.srocode = s.srocode
            JOIN kaveri.districtmaster di
              ON s.districtcode = di.districtcode
            WHERE d.isregistrationcompleted = TRUE
              AND (d.registrationdatetime BETWEEN _fromdate::timestamp AND _todate::timestamp + INTERVAL '1 day')
              AND (CASE WHEN _districtcode <> 0 THEN di.districtcode = _districtcode ELSE TRUE END)
              AND (CASE WHEN _srocode <> 0 THEN d.srocode = _srocode ELSE TRUE END)
        ),

        success_epay AS (
            SELECT
                e.applicationnumber,
                e.deptreferencecode,
                e.feerulecode,
                e.totalamount,
                b.paymentmode,
                b.paymentstatuscode,
                b.transactiontimestamp
            FROM kaveri.ams_reg_epaymenttransdetails e
            JOIN kaveri.ams_reg_epaymentbankackdetails b
              ON b.deptreferencecode = e.deptreferencecode
            WHERE e.isdelete = FALSE
              AND b.paymentstatuscode IN ('10700066','10700072')
              AND e.applicationnumber IN (SELECT applicationnumber FROM base_docs)
        ),

        amt AS (
            SELECT
                se.applicationnumber,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode IN (35,36,64,89,91,92,101,107,110,138)),0) AS stampduty_amt,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode IN (59,100)),0) AS cess_amt,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode IN (
                    1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                    57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                )),0) AS regfee_amt,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode = 2),0) AS scanning_amt,
                COALESCE(SUM(se.totalamount),0) AS total_amt,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode NOT IN (
                    -- stamp + cess
                    35,36,64,89,91,92,101,107,110,138,59,100,
                    -- scanning
                    2,
                    -- registration-fee bucket
                    1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                    57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                )),0) AS other_amt
            FROM success_epay se
            GROUP BY se.applicationnumber
        ),

        a AS (
            SELECT
                bd.distirctname,
                bd.sronamee,
                bd.documentnumber,
                string_agg(DISTINCT se.deptreferencecode, ',') AS challannumber,
                r.articlenamee AS articlename,
                bd.finalregistrationnumber,
                bd.uploaddocdeedpath AS copy_of_document,
                string_agg(DISTINCT rm.receiptnumber::text, ',') AS receiptnumber,
                string_agg(DISTINCT to_char(rm.dateofreceipt,'DD-MM-YYYY'), ',') AS dateofreceipt,
                string_agg(DISTINCT 'Schedule '||ps.scheduletype||' - '||ps.description, ',') AS description,
                string_agg(DISTINCT se.paymentmode, ',') AS paymentmode,
                bd.applicationnumber
            FROM base_docs bd
            LEFT JOIN kaveri.registrationarticles r
              ON bd.regarticlecode = r.regarticlecode
            LEFT JOIN success_epay se
              ON se.applicationnumber = bd.applicationnumber
            LEFT JOIN kaveri.receiptmaster rm
              ON bd.documentid = rm.documentid
             AND bd.applicationnumber = rm.applicationnumber
            LEFT JOIN kaveri.propertymaster p
              ON bd.documentid = p.documentid
             AND bd.applicationnumber = p.applicationnumber
            LEFT JOIN kaveri.propertyschedules ps
              ON p.propertyid = ps.propertyid
             AND p.applicationnumber = ps.applicationnumber
            LEFT JOIN amt
              ON amt.applicationnumber = bd.applicationnumber
            GROUP BY
                bd.distirctname, bd.sronamee, bd.documentnumber,
                r.articlenamee, bd.finalregistrationnumber, bd.uploaddocdeedpath,
                bd.applicationnumber,
                amt.stampduty_amt, amt.cess_amt, amt.regfee_amt, amt.scanning_amt, amt.other_amt, amt.total_amt
            HAVING
                CASE
                    WHEN _choice = 0 THEN TRUE
                    WHEN _choice = 1 THEN (COALESCE(amt.total_amt,0) >= _minval AND COALESCE(amt.total_amt,0) <= _maxval)
                    WHEN _choice = 2 THEN (COALESCE(amt.regfee_amt,0) >= _minval AND COALESCE(amt.regfee_amt,0) <= _maxval)
                    WHEN _choice = 3 THEN ((COALESCE(amt.stampduty_amt,0) + COALESCE(amt.cess_amt,0)) >= _minval
                                            AND (COALESCE(amt.stampduty_amt,0) + COALESCE(amt.cess_amt,0)) <= _maxval)
                    WHEN _choice = 4 THEN (COALESCE(amt.scanning_amt,0) >= _minval AND COALESCE(amt.scanning_amt,0) <= _maxval)
                    WHEN _choice = 5 THEN (COALESCE(amt.other_amt,0) >= _minval AND COALESCE(amt.other_amt,0) <= _maxval)
                    ELSE TRUE
                END
            LIMIT pagesize OFFSET PageOffset
        ),

        cte AS (
            SELECT
                a.distirctname,
                a.sronamee AS sroname,
                a.documentnumber,
                a.challannumber,
                a.articlename,
                a.finalregistrationnumber,
                a.copy_of_document,
                a.receiptnumber,
                a.dateofreceipt,
                a.description,
                a.paymentmode,
                COALESCE(amt.stampduty_amt,0)::numeric AS stampduty,
                COALESCE(amt.regfee_amt,0)::numeric AS registrationfee,
                COALESCE(amt.scanning_amt,0)::numeric AS scanningfee,
                COALESCE(amt.other_amt,0)::numeric AS otherfees,
                COALESCE(amt.total_amt,0)::numeric AS total
            FROM a
            LEFT JOIN amt
              ON amt.applicationnumber = a.applicationnumber
        )
        SELECT
            cte.*,
            COUNT(*) OVER()::bigint AS totalcount
        FROM cte;

    ELSIF (pagenumber = -1 OR pagesize = -1) THEN

        RETURN QUERY
        WITH
        base_docs AS (
            SELECT
                d.documentid,
                d.applicationnumber,
                d.finalregistrationnumber,
                d.documentnumber,
                d.regarticlecode,
                d.uploaddocdeedpath,
                d.srocode,
                d.registrationdatetime,
                di.districtnamee AS distirctname,
                s.sronamee
            FROM kaveri.documentmaster d
            JOIN kaveri.sromaster s
              ON d.srocode = s.srocode
            JOIN kaveri.districtmaster di
              ON s.districtcode = di.districtcode
            WHERE d.isregistrationcompleted = TRUE
              AND (d.registrationdatetime BETWEEN _fromdate::timestamp AND _todate::timestamp + INTERVAL '1 day')
              AND (CASE WHEN _districtcode <> 0 THEN di.districtcode = _districtcode ELSE TRUE END)
              AND (CASE WHEN _srocode <> 0 THEN d.srocode = _srocode ELSE TRUE END)
        ),

        success_epay AS (
            SELECT
                e.applicationnumber,
                e.deptreferencecode,
                e.feerulecode,
                e.totalamount,
                b.paymentmode,
                b.paymentstatuscode,
                b.transactiontimestamp
            FROM kaveri.ams_reg_epaymenttransdetails e
            JOIN kaveri.ams_reg_epaymentbankackdetails b
              ON b.deptreferencecode = e.deptreferencecode
            WHERE e.isdelete = FALSE
              AND b.paymentstatuscode IN ('10700066','10700072')
              AND e.applicationnumber IN (SELECT applicationnumber FROM base_docs)
        ),

        amt AS (
            SELECT
                se.applicationnumber,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode IN (35,36,64,89,91,92,101,107,110,138)),0) AS stampduty_amt,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode IN (59,100)),0) AS cess_amt,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode IN (
                    1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                    57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                )),0) AS regfee_amt,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode = 2),0) AS scanning_amt,
                COALESCE(SUM(se.totalamount),0) AS total_amt,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode NOT IN (
                    35,36,64,89,91,92,101,107,110,138,59,100,
                    2,
                    1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                    57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                )),0) AS other_amt
            FROM success_epay se
            GROUP BY se.applicationnumber
        ),

        a AS (
            SELECT
                bd.distirctname,
                bd.sronamee,
                bd.documentnumber,
                string_agg(DISTINCT se.deptreferencecode, ',') AS challannumber,
                r.articlenamee AS articlename,
                bd.finalregistrationnumber,
                bd.uploaddocdeedpath AS copy_of_document,
                string_agg(DISTINCT rm.receiptnumber::text, ',') AS receiptnumber,
                string_agg(DISTINCT to_char(rm.dateofreceipt,'DD-MM-YYYY'), ',') AS dateofreceipt,
                string_agg(DISTINCT 'Schedule '||ps.scheduletype||' - '||ps.description, ',') AS description,
                string_agg(DISTINCT se.paymentmode, ',') AS paymentmode,
                bd.applicationnumber
            FROM base_docs bd
            LEFT JOIN kaveri.registrationarticles r
              ON bd.regarticlecode = r.regarticlecode
            LEFT JOIN success_epay se
              ON se.applicationnumber = bd.applicationnumber
            LEFT JOIN kaveri.receiptmaster rm
              ON bd.documentid = rm.documentid
             AND bd.applicationnumber = rm.applicationnumber
            LEFT JOIN kaveri.propertymaster p
              ON bd.documentid = p.documentid
             AND bd.applicationnumber = p.applicationnumber
            LEFT JOIN kaveri.propertyschedules ps
              ON p.propertyid = ps.propertyid
             AND p.applicationnumber = ps.applicationnumber
            LEFT JOIN amt
              ON amt.applicationnumber = bd.applicationnumber
            GROUP BY
                bd.distirctname, bd.sronamee, bd.documentnumber,
                r.articlenamee, bd.finalregistrationnumber, bd.uploaddocdeedpath,
                bd.applicationnumber,
                amt.stampduty_amt, amt.cess_amt, amt.regfee_amt, amt.scanning_amt, amt.other_amt, amt.total_amt
            HAVING
                CASE
                    WHEN _choice = 0 THEN TRUE
                    WHEN _choice = 1 THEN (COALESCE(amt.total_amt,0) >= _minval AND COALESCE(amt.total_amt,0) <= _maxval)
                    WHEN _choice = 2 THEN (COALESCE(amt.regfee_amt,0) >= _minval AND COALESCE(amt.regfee_amt,0) <= _maxval)
                    WHEN _choice = 3 THEN ((COALESCE(amt.stampduty_amt,0) + COALESCE(amt.cess_amt,0)) >= _minval
                                            AND (COALESCE(amt.stampduty_amt,0) + COALESCE(amt.cess_amt,0)) <= _maxval)
                    WHEN _choice = 4 THEN (COALESCE(amt.scanning_amt,0) >= _minval AND COALESCE(amt.scanning_amt,0) <= _maxval)
                    WHEN _choice = 5 THEN (COALESCE(amt.other_amt,0) >= _minval AND COALESCE(amt.other_amt,0) <= _maxval)
                    ELSE TRUE
                END
        ),

        cte AS (
            SELECT
                a.distirctname,
                a.sronamee AS sroname,
                a.documentnumber,
                a.challannumber,
                a.articlename,
                a.finalregistrationnumber,
                a.copy_of_document,
                a.receiptnumber,
                a.dateofreceipt,
                a.description,
                a.paymentmode,
                COALESCE(amt.stampduty_amt,0)::numeric AS stampduty,
                COALESCE(amt.regfee_amt,0)::numeric AS registrationfee,
                COALESCE(amt.scanning_amt,0)::numeric AS scanningfee,
                COALESCE(amt.other_amt,0)::numeric AS otherfees,
                COALESCE(amt.total_amt,0)::numeric AS total
            FROM a
            LEFT JOIN amt
              ON amt.applicationnumber = a.applicationnumber
        )
        SELECT
            cte.*,
            COUNT(*) OVER()::bigint AS totalcount
        FROM cte;

    END IF;

END;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_receipt_details_20260204(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer) OWNER TO manjunathswamy;

--
-- Name: fn_mis_daily_receipt_details_20260309(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_receipt_details_20260309(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer DEFAULT 0, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(distirctname character varying, sroname character varying, documentnumber integer, challannumber text, articlename character varying, finalregistrationnumber character varying, copy_of_document text, receiptnumber text, dateofreceipt text, description text, paymentmode text, stampduty numeric, registrationfee numeric, scanningfee numeric, otherfees numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	

			PageOffset := (pagesize*pagenumber) - pagesize;
	        if (pagenumber<>-1 and   pagesize<>-1) then	
			
				return query 
				with cte as (with a as  
				(select  
					di.districtnamee as distirctname, 
					s.sronamee,
					d.documentnumber,								
					string_agg( distinct pay.deptreferencecode,',')as challannumber,
					r.articlenamee as articlename,
					d.finalregistrationnumber,
					d.uploaddocdeedpath as copy_of_document,
					string_agg( distinct ref.receiptnumber::text,',') as receiptnumber,
					string_agg(distinct to_char(ref.dateofreceipt,'DD-MM-YYYY'),',') as dateofreceipt, 
					string_agg( distinct 'Schedule '||ps.scheduletype || ' - ' || ps.description ,',')
					as description,
					string_agg( distinct ack.paymentmode,',') as paymentmode 

				 from kaveri.documentmaster d
				left join kaveri.registrationarticles r on d.regarticlecode = r.regarticlecode 
				--and d.srocode=259 
				join kaveri.sromaster s on d.srocode = s.srocode  
				left join kaveri.feesrequired  f on f.applicationnumber = d.applicationnumber 
				left join kaveri.ams_reg_epaymenttransdetails pay on d.applicationnumber = pay.applicationnumber 
				and pay.isdelete=false
				join kaveri.districtmaster di on s.districtcode = di.districtcode
				
				Left
				join kaveri.receiptmaster ref on d.documentid = ref.documentid  and d.applicationnumber = ref.applicationnumber
				left join kaveri.ams_reg_epaymentbankackdetails ack on pay.deptreferencecode = ack.deptreferencecode 
				left join kaveri.propertymaster p on d.documentid=p.documentid and d.applicationnumber = p.applicationnumber
				left join kaveri.propertyschedules ps on p.propertyid=ps.propertyid and p.applicationnumber = ps.applicationnumber
				where d.isregistrationcompleted = true  
				--and ack.paymentstatuscode in ('10700066','10700072')
				and (d.registrationdatetime  between  _fromdate ::timestamp and _todate ::timestamp + INTERVAL '1 day'  )
				and (case
					when _districtcode <> 0 then di.districtcode = _districtcode
					else
						true
				end)
				
				and (case
					when _srocode<>0 then d.srocode =_srocode
					else true
				end)
				and 
				(case

			          when _choice=0 then true  --amount type null
			          when _choice=1 then true  -- amount type total                
			          when _choice=2 then f.feerulecode=1     -- amount type registration fee
			          when _choice=3 then f.feerulecode in (36,58,59,104,89,88) -- amounttype stamp duty
			          when _choice=4 then f.feerulecode=2        -- amount type scanning fees
			          when _choice=5 then f.feerulecode not in (1,2,36,58,59,104,89,88)  -- amount type others
			           else 
			           true

          		end)
				
				--and (case
					--when _documentnumber<>null then dm.documentnumber =_documentnumber
					--else true
				--end)

				group by 

				di.districtnamee ,s.sronamee,d.documentnumber,
				r.articlenamee,d.finalregistrationnumber,d.uploaddocdeedpath
				having
       		(case

       		   when _choice=0 then true
         		 when _choice in (1,2,3,4,5)  then sum(f.amountpaid) >=_minval and sum(f.amountpaid)<=_maxval                
          	 	else 
          	 	true

         	 	end) limit pagesize offset PageOffset
				
				) 
				select a.*, 
				sum(distinct case when rr.feerulecode in (36,58,59,104,89,88) then rr.amountpaid else 0 end)as StampDuty, 
				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end )as RegistrationFees, 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)as scanningfee, 

				sum(case when rr.feerulecode not in (1,2,36,58,59,104,89,88) then rr.amountpaid else 0 end) as otherfees, 

				sum( coalesce(rr.amountpaid,0)) 	as Total

				from 
				      kaveri.documentmaster d 
				      left join kaveri.feesrequired  rr   on d.applicationnumber=rr.applicationnumber
					 inner join a on a.finalregistrationnumber = d.finalregistrationnumber 	

				group by a.distirctname,a.sronamee,a.documentnumber,a.articlename,a.finalregistrationnumber,
				a.challannumber,a.copy_of_document,a.receiptnumber,a.dateofreceipt,a.description,a.paymentmode)
				
			

				              select *,null::bigint as total_row from cte	;
				
				
				elsif (pagenumber=-1 or  pagesize=-1) then 

				return query 
				with cte as (with a as  
				(select  
					di.districtnamee as distirctname, 
					s.sronamee,
					d.documentnumber,								
					string_agg( distinct pay.deptreferencecode,',')as challannumber,
					r.articlenamee as articlename,
					d.finalregistrationnumber,
					d.uploaddocdeedpath as copy_of_document,
					string_agg( distinct ref.receiptnumber::text,',') as receiptnumber,
					string_agg(distinct to_char(ref.dateofreceipt,'DD-MM-YYYY'),',') as dateofreceipt, 
					string_agg( distinct 'Schedule '||ps.scheduletype || ' - ' || ps.description ,',')
					as description,
					string_agg( distinct ack.paymentmode,',') as paymentmode 

				 from kaveri.documentmaster d
				left join kaveri.registrationarticles r on d.regarticlecode = r.regarticlecode 
				--and d.srocode=259 
				join kaveri.sromaster s on d.srocode = s.srocode  
				left join kaveri.feesrequired  f on f.applicationnumber = d.applicationnumber 
				left join kaveri.ams_reg_epaymenttransdetails pay on d.applicationnumber = pay.applicationnumber 
				and pay.isdelete=false
				join kaveri.districtmaster di on s.districtcode = di.districtcode
				
				Left
				join kaveri.receiptmaster ref on d.documentid = ref.documentid  and d.applicationnumber = ref.applicationnumber
				left join kaveri.ams_reg_epaymentbankackdetails ack on pay.deptreferencecode = ack.deptreferencecode 
				left join kaveri.propertymaster p on d.documentid=p.documentid and d.applicationnumber = p.applicationnumber
				left join kaveri.propertyschedules ps on p.propertyid=ps.propertyid and p.applicationnumber = ps.applicationnumber
				where d.isregistrationcompleted = true  
				--and ack.paymentstatuscode in ('10700066','10700072')
				and (d.registrationdatetime  between  _fromdate ::timestamp and _todate ::timestamp + INTERVAL '1 day'  )
				and (case
					when _districtcode <> 0 then di.districtcode = _districtcode
					else
						true
				end)
				
				and (case
					when _srocode<>0 then d.srocode =_srocode
					else true
				end)
				and 
				(case

			          when _choice=0 then true  --amount type null
			          when _choice=1 then true  -- amount type total                
			          when _choice=2 then f.feerulecode=1     -- amount type registration fee
			          when _choice=3 then f.feerulecode in (36,58,59,104,89,88) -- amounttype stamp duty
			          when _choice=4 then f.feerulecode=2        -- amount type scanning fees
			          when _choice=5 then f.feerulecode not in (1,2,36,58,59,104,89,88)  -- amount type others
			           else 
			           true

          		end)
				
				--and (case
					--when _documentnumber<>null then dm.documentnumber =_documentnumber
					--else true
				--end)

				group by 

				di.districtnamee ,s.sronamee,d.documentnumber,
				r.articlenamee,d.finalregistrationnumber,d.uploaddocdeedpath
				having
       		(case

       		   when _choice=0 then true
         		 when _choice in (1,2,3,4,5)  then sum(f.amountpaid) >=_minval and sum(f.amountpaid)<=_maxval                
          	 	else 
          	 	true

         	 	end) 
				
				) 
				select a.*, 
				sum(distinct case when rr.feerulecode in (36,58,59,104,89,88) then rr.amountpaid else 0 end)as StampDuty, 
				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end )as RegistrationFees, 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)as scanningfee, 

				sum(case when rr.feerulecode not in (1,2,36,58,59,104,89,88) then rr.amountpaid else 0 end) as otherfees, 

				sum( coalesce(rr.amountpaid,0)) 	as Total

				from 
				      kaveri.documentmaster d 
				      left join kaveri.feesrequired  rr   on d.applicationnumber=rr.applicationnumber
					 inner join a on a.finalregistrationnumber = d.finalregistrationnumber 	

				group by a.distirctname,a.sronamee,a.documentnumber,a.articlename,a.finalregistrationnumber,
				a.challannumber,a.copy_of_document,a.receiptnumber,a.dateofreceipt,a.description,a.paymentmode)
				
			

				              select *,null::bigint as total_row from cte	;
						
	end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_receipt_details_20260309(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_receipt_details_20260406_bkp(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_daily_receipt_details_20260406_bkp(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer DEFAULT 0, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(distirctname character varying, sroname character varying, documentnumber integer, challannumber text, articlename character varying, finalregistrationnumber character varying, copy_of_document text, receiptnumber text, dateofreceipt text, description text, paymentmode text, stampduty numeric, registrationfee numeric, scanningfee numeric, otherfees numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	

			PageOffset := (pagesize*pagenumber) - pagesize;
	        if (pagenumber<>-1 and   pagesize<>-1) then	
			
				return query 
				with cte as (with a as  
				(select  
					di.districtnamee as distirctname, 
					s.sronamee,
					d.documentnumber,								
					string_agg( distinct pay.deptreferencecode,',')as challannumber,
					r.articlenamee as articlename,
					d.finalregistrationnumber,
					d.uploaddocdeedpath as copy_of_document,
					string_agg( distinct ref.receiptnumber::text,',') as receiptnumber,
					string_agg(distinct to_char(ref.dateofreceipt,'DD-MM-YYYY'),',') as dateofreceipt, 
					string_agg( distinct 'Schedule '||ps.scheduletype || ' - ' || ps.description ,',')
					as description,
					string_agg( distinct ack.paymentmode,',') as paymentmode 

				 from kaveri.documentmaster d
				left join kaveri.registrationarticles r on d.regarticlecode = r.regarticlecode 
				--and d.srocode=259 
				join kaveri.sromaster s on d.srocode = s.srocode  
				join kaveri.feesrequired  f on f.applicationnumber = d.applicationnumber 
				left join kaveri.ams_reg_epaymenttransdetails pay on d.applicationnumber = pay.applicationnumber 
				and pay.isdelete=false
				join kaveri.districtmaster di on s.districtcode = di.districtcode
				
				Left
				join kaveri.receiptmaster ref on d.documentid = ref.documentid 
				left join kaveri.ams_reg_epaymentbankackdetails ack on pay.deptreferencecode = ack.deptreferencecode 
				join kaveri.propertymaster p on p.documentid=d.documentid
				left join kaveri.propertyschedules ps on ps.propertyid=p.propertyid
				where d.isregistrationcompleted = true  
				--and ack.paymentstatuscode in ('10700066','10700072')
				and (d.registrationdatetime  between  _fromdate ::timestamp and _todate ::timestamp + INTERVAL '1 day'  )
				and (case
					when _districtcode <> 0 then di.districtcode = _districtcode
					else
						true
				end)
				
				and (case
					when _srocode<>0 then d.srocode =_srocode
					else true
				end)
				and 
				(case

			          when _choice=0 then true
			          when _choice=1 then true                  
			          when _choice=2 then f.feerulecode=1
			          when _choice=3 then f.feerulecode in (36,58,59)
			          when _choice=4 then f.feerulecode=2
			          when _choice=5 then f.feerulecode not in (1,2,36,58,59,64)
			           else 
			           true

          		end)
				
				--and (case
					--when _documentnumber<>null then dm.documentnumber =_documentnumber
					--else true
				--end)

				group by 

				di.districtnamee ,s.sronamee,d.documentnumber,
				r.articlenamee,d.finalregistrationnumber,d.uploaddocdeedpath
				having
       		(case

       		   when _choice=0 then true
         		 when _choice in (1,2,3,4,5)  then sum(f.amountpaid) >=_minval and sum(f.amountpaid)<=_maxval                
          	 	else 
          	 	true

         	 	end) limit pagesize offset PageOffset
				
				) 
				select a.*, 
				sum(distinct case when rr.feerulecode in (36,58,59) then rr.amountpaid else 0 end)as StampDuty, 
				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end )as RegistrationFees, 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)as scanningfee, 

				sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end) as otherfees, 

				(sum(case when rr.feerulecode in (36,58,59) then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)) 	as Total 

				from 
				      kaveri.documentmaster d 
				      join kaveri.feesrequired  rr   on d.applicationnumber=rr.applicationnumber
					 inner join a on a.finalregistrationnumber = d.finalregistrationnumber 	

				group by a.distirctname,a.sronamee,a.documentnumber,a.articlename,a.finalregistrationnumber,
				a.challannumber,a.copy_of_document,a.receiptnumber,a.dateofreceipt,a.description,a.paymentmode)
				
			

				               select * from cte
			right join (select null::bigint as total_rows) total_row on true;
		
				
				
				elsif (pagenumber=-1 or  pagesize=-1) then 

				return query 
				with cte as (with a as  
				(select  
					di.districtnamee as distirctname, 
					s.sronamee,
					d.documentnumber,								
					string_agg( distinct pay.deptreferencecode,',')as challannumber,
					r.articlenamee as articlename,
					d.finalregistrationnumber,
					d.uploaddocdeedpath as copy_of_document,
					string_agg( distinct ref.receiptnumber::text,',') as receiptnumber,
					string_agg(distinct to_char(ref.dateofreceipt,'DD-MM-YYYY'),',') as dateofreceipt, 
					string_agg( distinct 'Schedule '||ps.scheduletype || ' - ' || ps.description ,',')
					as description,
					string_agg( distinct ack.paymentmode,',') as paymentmode 

				 from kaveri.documentmaster d
				left join kaveri.registrationarticles r on d.regarticlecode = r.regarticlecode 
				--and d.srocode=259 
				join kaveri.sromaster s on d.srocode = s.srocode  
				join kaveri.feesrequired  f on f.applicationnumber = d.applicationnumber 
				left join kaveri.ams_reg_epaymenttransdetails pay on d.applicationnumber = pay.applicationnumber 
				and pay.isdelete=false
				join kaveri.districtmaster di on s.districtcode = di.districtcode
				
				Left
				join kaveri.receiptmaster ref on d.documentid = ref.documentid 
				left join kaveri.ams_reg_epaymentbankackdetails ack on pay.deptreferencecode = ack.deptreferencecode 
				join kaveri.propertymaster p on p.documentid=d.documentid
				left join kaveri.propertyschedules ps on ps.propertyid=p.propertyid
				where d.isregistrationcompleted = true  
				--and ack.paymentstatuscode in ('10700066','10700072')
				and (d.registrationdatetime  between  _fromdate ::timestamp and _todate ::timestamp + INTERVAL '1 day'  )
				and (case
					when _districtcode <> 0 then di.districtcode = _districtcode
					else
						true
				end)
				
				and (case
					when _srocode<>0 then d.srocode =_srocode
					else true
				end)
				and 
				(case

			          when _choice=0 then true
			          when _choice=1 then true                  
			          when _choice=2 then f.feerulecode=1
			          when _choice=3 then f.feerulecode in (36,58,59)
			          when _choice=4 then f.feerulecode=2
			          when _choice=5 then f.feerulecode not in (1,2,36,58,59,64)
			           else 
			           true

          		end)
				
				--and (case
					--when _documentnumber<>null then dm.documentnumber =_documentnumber
					--else true
				--end)

				group by 

				di.districtnamee ,s.sronamee,d.documentnumber,
				r.articlenamee,d.finalregistrationnumber,d.uploaddocdeedpath
				having
       		(case

       		   when _choice=0 then true
         		 when _choice in (1,2,3,4,5)  then sum(f.amountpaid) >=_minval and sum(f.amountpaid)<=_maxval                
          	 	else 
          	 	true

         	 	end)
				
				) 
				select a.*, 
				sum(distinct case when rr.feerulecode in (36,58,59) then rr.amountpaid else 0 end)as StampDuty, 
				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end )as RegistrationFees, 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)as scanningfee, 

				sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end) as otherfees, 

				(sum(case when rr.feerulecode in (36,58,59) then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)) 	as Total 

				from 
				      kaveri.documentmaster d 
				      join kaveri.feesrequired  rr   on d.applicationnumber=rr.applicationnumber
					 inner join a on a.finalregistrationnumber = d.finalregistrationnumber 	

				group by a.distirctname,a.sronamee,a.documentnumber,a.articlename,a.finalregistrationnumber,
				a.challannumber,a.copy_of_document,a.receiptnumber,a.dateofreceipt,a.description,a.paymentmode)
			

				      select * from cte
			right join (select null::bigint as total_rows ) total_row on true; 
						
	end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_receipt_details_20260406_bkp(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_daily_receipt_details_bck_19122023(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_daily_receipt_details_bck_19122023(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer DEFAULT 0, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(distirctname character varying, sroname character varying, documentnumber integer, challannumber text, articlename character varying, finalregistrationnumber character varying, copy_of_document text, receiptnumber text, dateofreceipt text, description text, paymentmode text, stampduty numeric, registrationfee numeric, scanningfee numeric, otherfees numeric, total numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
if(_districtcode=0) then--All district
			if _choice = 1 then  --- stampduty
				return query 
				with a as  
				(select
					di.districtnamee as distirctname, 
					s.sronamee,
					d.documentnumber,								
					string_agg( distinct pay.deptreferencecode,',')as challannumber,
					r.articlenamee as articlename,
					d.finalregistrationnumber,
					d.uploaddocdeedpath as copy_of_document,
					string_agg( distinct ref.receiptnumber::text,',') as receiptnumber,
					string_agg(distinct to_char(ref.dateofreceipt,'DD-MM-YYYY'),',') as dateofreceipt, 
					string_agg( distinct 'Schedule '||ps.scheduletype || ' - ' || ps.description ,',') as description,
					string_agg( distinct ack.paymentmode,',') as paymentmode 

				 from kaveri.documentmaster d
				join kaveri.registrationarticles r on d.regarticlecode = r.regarticlecode 
				--and d.srocode=259 
				join kaveri.sromaster s on d.srocode = s.srocode  
				join (select applicationnumber,sum(amountpaid) from 
				kaveri.feesrequired  where feerulecode in (36,58,59) group by applicationnumber 
				having sum(amountpaid)>=_minval and sum(amountpaid)<=_maxval)f on f.applicationnumber = d.applicationnumber 
				join kaveri.ams_reg_epaymenttransdetails pay on d.applicationnumber = pay.applicationnumber 
				join kaveri.districtmaster di on s.districtcode = di.districtcode
				-- and di.districtcode=_districtcode 
				Left
				join kaveri.receiptmaster ref on d.documentid = ref.documentid 
				join kaveri.ams_reg_epaymentbankackdetails ack on pay.deptreferencecode = ack.deptreferencecode 
				join kaveri.propertymaster p on p.documentid=d.documentid
				left join kaveri.propertyschedules ps on ps.propertyid=p.propertyid
				where d.isregistrationcompleted = true  
				and d.registrationdatetime::date >= _fromdate and 
				d.registrationdatetime::date <= _todate 

				group by 

				di.districtnamee ,s.sronamee,d.documentnumber,r.articlenamee,d.finalregistrationnumber,d.uploaddocdeedpath
				
				) 
				select a.*, 
				sum(distinct case when rr.feerulecode in (36,58,59) then rr.amountpaid else 0 end)as StampDuty, 
				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end )as RegistrationFees, 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)as scanningfee, 

				sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end) as otherfees, 

				(sum(case when rr.feerulecode in (36,58,59) then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)) 	as Total 

				from 
				      kaveri.documentmaster d 
				      join kaveri.feesrequired  rr   on d.applicationnumber=rr.applicationnumber
					 inner join a on a.finalregistrationnumber = d.finalregistrationnumber 	

				group by a.distirctname,a.sronamee,a.documentnumber,a.articlename,a.finalregistrationnumber,
				a.challannumber,a.copy_of_document,a.receiptnumber,a.dateofreceipt,a.description,a.paymentmode
										
				OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
			elsif _choice = 2 then  --- Registration fees
				return query 
				with a as  
				(select
					di.districtnamee as distirctname, 
					s.sronamee,
					d.documentnumber,								
					string_agg( distinct pay.deptreferencecode,',')as challannumber,
					r.articlenamee as articlename,
					d.finalregistrationnumber,
					d.uploaddocdeedpath as copy_of_document,
					string_agg( distinct ref.receiptnumber::text,',') as receiptnumber,
					string_agg(distinct to_char(ref.dateofreceipt,'DD-MM-YYYY'),',') as dateofreceipt, 
					string_agg( distinct 'Schedule '||ps.scheduletype || ' - ' || ps.description ,',') as description,
					string_agg( distinct ack.paymentmode,',') as paymentmode 

				 from kaveri.documentmaster d
				join kaveri.registrationarticles r on d.regarticlecode = r.regarticlecode 
				--and d.srocode=259 
				join kaveri.sromaster s on d.srocode = s.srocode  
				join (select applicationnumber,sum(amountpaid) from 
				kaveri.feesrequired  where feerulecode in (1) group by applicationnumber 
				having sum(amountpaid)>=_minval and sum(amountpaid)<=_maxval)f on f.applicationnumber = d.applicationnumber 
				join kaveri.ams_reg_epaymenttransdetails pay on d.applicationnumber = pay.applicationnumber 
				join kaveri.districtmaster di on s.districtcode = di.districtcode
				-- and di.districtcode=_districtcode 
				Left
				join kaveri.receiptmaster ref on d.documentid = ref.documentid 
				join kaveri.ams_reg_epaymentbankackdetails ack on pay.deptreferencecode = ack.deptreferencecode 
				join kaveri.propertymaster p on p.documentid=d.documentid
				left join kaveri.propertyschedules ps on ps.propertyid=p.propertyid
				where d.isregistrationcompleted = true  
				and d.registrationdatetime::date >= _fromdate and 
				d.registrationdatetime::date <= _todate 

				group by 

				di.districtnamee ,s.sronamee,d.documentnumber,r.articlenamee,d.finalregistrationnumber,d.uploaddocdeedpath
				
				) 
				select a.*, 
				sum(distinct case when rr.feerulecode in (36,58,59) then rr.amountpaid else 0 end)as StampDuty, 
				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end )as RegistrationFees, 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)as scanningfee, 

				sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end) as otherfees, 

				(sum(case when rr.feerulecode in (36,58,59) then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)) 	as Total 

				from 
				      kaveri.documentmaster d 
				      join kaveri.feesrequired  rr   on d.applicationnumber=rr.applicationnumber
					 inner join a on a.finalregistrationnumber = d.finalregistrationnumber 	  

				group by a.distirctname,a.sronamee,a.documentnumber,a.articlename,a.finalregistrationnumber,
				a.challannumber,a.copy_of_document,a.receiptnumber,a.dateofreceipt,a.description,a.paymentmode
										
				OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
						
				
			elsif _choice = 3  then --- Scanning fees
			return query
				with a as  
				(select
					di.districtnamee as distirctname, 
					s.sronamee,
					d.documentnumber,								
					string_agg( distinct pay.deptreferencecode,',')as challannumber,
					r.articlenamee as articlename,
					d.finalregistrationnumber,
					d.uploaddocdeedpath as copy_of_document,
					string_agg( distinct ref.receiptnumber::text,',') as receiptnumber,
					string_agg(distinct to_char(ref.dateofreceipt,'DD-MM-YYYY'),',') as dateofreceipt, 
					string_agg( distinct 'Schedule '||ps.scheduletype || ' - ' || ps.description ,',') as description,
					string_agg( distinct ack.paymentmode,',') as paymentmode 

				 from kaveri.documentmaster d
				join kaveri.registrationarticles r on d.regarticlecode = r.regarticlecode 
				--and d.srocode=259 
				join kaveri.sromaster s on d.srocode = s.srocode  
				join (select applicationnumber,sum(amountpaid) from 
				kaveri.feesrequired  where feerulecode in (2) group by applicationnumber 
				having sum(amountpaid)>=_minval and sum(amountpaid)<=_maxval)f on f.applicationnumber = d.applicationnumber 
				join kaveri.ams_reg_epaymenttransdetails pay on d.applicationnumber = pay.applicationnumber 
				join kaveri.districtmaster di on s.districtcode = di.districtcode
				-- and di.districtcode=_districtcode 
				Left
				join kaveri.receiptmaster ref on d.documentid = ref.documentid 
				join kaveri.ams_reg_epaymentbankackdetails ack on pay.deptreferencecode = ack.deptreferencecode 
				join kaveri.propertymaster p on p.documentid=d.documentid
				left join kaveri.propertyschedules ps on ps.propertyid=p.propertyid
				where d.isregistrationcompleted = true  
				and d.registrationdatetime::date >= _fromdate and 
				d.registrationdatetime::date <= _todate 

				group by 

				di.districtnamee ,s.sronamee,d.documentnumber,r.articlenamee,d.finalregistrationnumber,d.uploaddocdeedpath
				
				) 
				select a.*, 
				sum(distinct case when rr.feerulecode in (36,58,59) then rr.amountpaid else 0 end)as StampDuty, 
				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end )as RegistrationFees, 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)as scanningfee, 

				sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end) as otherfees, 

				(sum(case when rr.feerulecode in (36,58,59) then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)) 	as Total 

				from 
				      kaveri.documentmaster d 
				      join kaveri.feesrequired  rr   on d.applicationnumber=rr.applicationnumber
					 inner join a on a.finalregistrationnumber = d.finalregistrationnumber 	  

				group by a.distirctname,a.sronamee,a.documentnumber,a.articlename,a.finalregistrationnumber,
				a.challannumber,a.copy_of_document,a.receiptnumber,a.dateofreceipt,a.description,a.paymentmode
										
										
				OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
				elsif _choice = 4 then  ---otherfees
				return query
				with a as  
				(select
					di.districtnamee as distirctname, 
					s.sronamee,
					d.documentnumber,								
					string_agg( distinct pay.deptreferencecode,',')as challannumber,
					r.articlenamee as articlename,
					d.finalregistrationnumber,
					d.uploaddocdeedpath as copy_of_document,
					string_agg( distinct ref.receiptnumber::text,',') as receiptnumber,
					string_agg(distinct to_char(ref.dateofreceipt,'DD-MM-YYYY'),',') as dateofreceipt, 
					string_agg( distinct 'Schedule '||ps.scheduletype || ' - ' || ps.description ,',') as description,
					string_agg( distinct ack.paymentmode,',') as paymentmode 

				 from kaveri.documentmaster d
				join kaveri.registrationarticles r on d.regarticlecode = r.regarticlecode 
				--and d.srocode=259 
				join kaveri.sromaster s on d.srocode = s.srocode  
				join (select applicationnumber,sum(amountpaid) from 
				kaveri.feesrequired  where feerulecode  not in (1,2,36,58,59,64) group by applicationnumber 
				having sum(amountpaid)>=_minval and sum(amountpaid)<=_maxval)f on f.applicationnumber = d.applicationnumber 
				join kaveri.ams_reg_epaymenttransdetails pay on d.applicationnumber = pay.applicationnumber 
				join kaveri.districtmaster di on s.districtcode = di.districtcode
				-- and di.districtcode=_districtcode 
				Left
				join kaveri.receiptmaster ref on d.documentid = ref.documentid 
				join kaveri.ams_reg_epaymentbankackdetails ack on pay.deptreferencecode = ack.deptreferencecode 
				join kaveri.propertymaster p on p.documentid=d.documentid
				left join kaveri.propertyschedules ps on ps.propertyid=p.propertyid
				where d.isregistrationcompleted = true  
				and d.registrationdatetime::date >= _fromdate and 
				d.registrationdatetime::date <= _todate 

				group by 

				di.districtnamee ,s.sronamee,d.documentnumber,r.articlenamee,d.finalregistrationnumber,d.uploaddocdeedpath
				
				) 
				select a.*, 
				sum(distinct case when rr.feerulecode in (36,58,59) then rr.amountpaid else 0 end)as StampDuty, 
				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end )as RegistrationFees, 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)as scanningfee, 

				sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end) as otherfees, 

				(sum(case when rr.feerulecode in (36,58,59) then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)) 	as Total 

				from 
				kaveri.documentmaster d 
