ALTER FUNCTION kaverimis.fn_mis_daily_receipt_details_bck_19122023(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_daily_receipt_details_count(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_receipt_details_count(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer DEFAULT 0, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
    v_totalcount integer;
begin
    if _choice is null then
        _choice := 0;
    end if;

    select count(*) into v_totalcount
    from (
        with base_docs as (
            select
                d.applicationnumber,
                d.finalregistrationnumber
            from kaveri.documentmaster d
            join kaveri.sromaster s
              on d.srocode = s.srocode
            join kaveri.districtmaster di
              on s.districtcode = di.districtcode
            where d.isregistrationcompleted = true
              and (d.registrationdatetime between _fromdate and _todate + interval '1 day')
              and (case when _districtcode <> 0 then di.districtcode = _districtcode else true end)
              and (case when _srocode <> 0 then d.srocode = _srocode else true end)
        ),

        success_epay as (
            select
                e.applicationnumber,
                e.feerulecode,
                e.totalamount
            from kaveri.ams_reg_epaymenttransdetails e
            join kaveri.ams_reg_epaymentbankackdetails b
              on b.deptreferencecode = e.deptreferencecode
            where e.isdelete = false
              and b.paymentstatuscode in ('10700066','10700072')
              and e.applicationnumber in (select applicationnumber from base_docs)
        ),

        amt as (
            select
                se.applicationnumber,
                /* stamp duty + cess + surcharge */
                coalesce(sum(se.totalamount) filter (
                    where se.feerulecode in (35,36,58,59,64,89,91,92,99,100,101,107,110,138)
                ),0) as stamp_amt,
               
                coalesce(sum(se.totalamount) filter (
                    where se.feerulecode in (59,100)
                ),0) as cess_amt,
              
                coalesce(sum(se.totalamount) filter (
                    where se.feerulecode in (
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ),0) as regfee_amt,
              
                coalesce(sum(se.totalamount) filter (
                    where se.feerulecode = 2
                ),0) as scanning_amt,
               
                coalesce(sum(se.totalamount),0) as total_amt,
               
                coalesce(sum(se.totalamount) filter (
                    where se.feerulecode not in (
                        35,36,58,59,64,89,91,92,99,100,101,107,110,138,
                        2,
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ),0) as other_amt
            from success_epay se
            group by se.applicationnumber
        )
        select distinct bd.finalregistrationnumber
        from base_docs bd
        join amt on amt.applicationnumber = bd.applicationnumber
        where
            case
                when _choice = 0 then true
                when _choice = 1 then amt.total_amt between _minval and _maxval
                when _choice = 2 then amt.regfee_amt between _minval and _maxval
                when _choice = 3 then amt.stamp_amt between _minval and _maxval
                when _choice = 4 then amt.scanning_amt between _minval and _maxval
                when _choice = 5 then amt.other_amt between _minval and _maxval
                else true
            end
    ) x;

    return v_totalcount;
end;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_receipt_details_count(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_receipt_details_count_20260309(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_receipt_details_count_20260309(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer DEFAULT 0, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
v_totalcount integer;
BEGIN	
 
	if _choice is null then 
	_choice:=0;
	end if;
	

	select count(distinct finalregistrationnumber ) into v_totalcount from ( select
					distinct d.finalregistrationnumber 

				 from kaveri.documentmaster d
				join kaveri.sromaster s on d.srocode = s.srocode  
				left join kaveri.feesrequired  f on d.applicationnumber=f.applicationnumber   
				join kaveri.districtmaster di on s.districtcode = di.districtcode
						
				where d.isregistrationcompleted = true  
				and (d.registrationdatetime  between  _fromdate and _todate + INTERVAL '1 day' )
				and (case
					when _districtcode <> 0 then di.districtcode = _districtcode
					else
						true
				end)
				
				and (case
					when _srocode<>0 then d.srocode =_srocode
					else true
				end)
				and 
				(case

			          when _choice=0 then true
			          when _choice=1 then true                  
			          when _choice=2 then f.feerulecode=1
			          when _choice=3 then f.feerulecode in (36,58,59)
			          when _choice=4 then f.feerulecode=2
			          when _choice=5 then f.feerulecode not in (1,2,36,58,59,64)
			           else 
			           true

          		end) 
          		--and   (f.receiptid is not null)
				
				--and (case
					--when _documentnumber<>null then dm.documentnumber =_documentnumber
					--else true
				--end)

				group by 

				 d.finalregistrationnumber 
				having
       		(case

       		   when _choice=0 then true
         		 when _choice in (1,2,3,4,5)  then sum(f.amountpaid) >=_minval 
         		 and sum(f.amountpaid)<=_maxval                
          	 	else 
          	 	true

         	 	end))temp;
         	 
         	 return v_totalcount;
         	 	
         	 	
	       
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_receipt_details_count_20260309(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_receipt_details_count_20260406_bkp(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: manjunathswamy
--

CREATE FUNCTION kaverimis.fn_mis_daily_receipt_details_count_20260406_bkp(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer DEFAULT 0, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_totalcount integer;
BEGIN
    IF _choice IS NULL THEN
        _choice := 0;
    END IF;

    SELECT COUNT(*) INTO v_totalcount
    FROM (
        WITH base_docs AS (
            SELECT
                d.applicationnumber,
                d.finalregistrationnumber
            FROM kaveri.documentmaster d
            JOIN kaveri.sromaster s
              ON d.srocode = s.srocode
            JOIN kaveri.districtmaster di
              ON s.districtcode = di.districtcode
            WHERE d.isregistrationcompleted = TRUE
              AND (d.registrationdatetime BETWEEN _fromdate AND _todate + INTERVAL '1 day')
              AND (CASE WHEN _districtcode <> 0 THEN di.districtcode = _districtcode ELSE TRUE END)
              AND (CASE WHEN _srocode <> 0 THEN d.srocode = _srocode ELSE TRUE END)
        ),

        success_epay AS (
            SELECT
                e.applicationnumber,
                e.feerulecode,
                e.totalamount
            FROM kaveri.ams_reg_epaymenttransdetails e
            JOIN kaveri.ams_reg_epaymentbankackdetails b
              ON b.deptreferencecode = e.deptreferencecode
            WHERE e.isdelete = FALSE
              AND b.paymentstatuscode IN ('10700066','10700072')
              AND e.applicationnumber IN (SELECT applicationnumber FROM base_docs)
        ),

        amt AS (
            SELECT
                se.applicationnumber,

                /* stamp duty */
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (35,36,64,89,91,92,101,107,110,138)
                ),0) AS stamp_amt,

                /* cess */
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (59,100)
                ),0) AS cess_amt,

                /* registration fees */
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ),0) AS regfee_amt,

                /* scanning */
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode = 2
                ),0) AS scanning_amt,

                /* total */
                COALESCE(SUM(se.totalamount),0) AS total_amt,

                /* other */
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode NOT IN (
                        35,36,64,89,91,92,101,107,110,138,
                        59,100,
                        2,
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ),0) AS other_amt
            FROM success_epay se
            GROUP BY se.applicationnumber
        )

        SELECT DISTINCT bd.finalregistrationnumber
        FROM base_docs bd
        JOIN amt ON amt.applicationnumber = bd.applicationnumber
        WHERE
            CASE
                WHEN _choice = 0 THEN TRUE
                WHEN _choice = 1 THEN amt.total_amt BETWEEN _minval AND _maxval
                WHEN _choice = 2 THEN amt.regfee_amt BETWEEN _minval AND _maxval
                WHEN _choice = 3 THEN (amt.stamp_amt + amt.cess_amt) BETWEEN _minval AND _maxval
                WHEN _choice = 4 THEN amt.scanning_amt BETWEEN _minval AND _maxval
                WHEN _choice = 5 THEN amt.other_amt BETWEEN _minval AND _maxval
                ELSE TRUE
            END
    ) x;

    RETURN v_totalcount;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_receipt_details_count_20260406_bkp(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer) OWNER TO manjunathswamy;

--
-- Name: fn_mis_daily_receipt_details_flat(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_receipt_details_flat(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer DEFAULT 0, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(distirctname character varying, sroname character varying, documentnumber integer, challannumber text, articlename character varying, finalregistrationnumber character varying, copy_of_document text, receiptnumber text, dateofreceipt text, description text, paymentmode text, stampduty numeric, registrationfee numeric, scanningfee numeric, otherfees numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    PageOffset INTEGER := 0;
BEGIN
    PageOffset := (pagesize * pagenumber) - pagesize;

    IF (pagenumber <> -1 AND pagesize <> -1) THEN

        RETURN QUERY
        WITH
        base_docs AS (
            SELECT
                d.documentid,
                d.applicationnumber,
                d.finalregistrationnumber,
                d.documentnumber,
                d.regarticlecode,
                d.uploaddocdeedpath,
                d.srocode,
                d.registrationdatetime,
                di.districtnamee AS distirctname,
                s.sronamee
            FROM kaveri.documentmaster d
            JOIN kaveri.sromaster s
              ON d.srocode = s.srocode
            JOIN kaveri.districtmaster di
              ON s.districtcode = di.districtcode
            WHERE d.isregistrationcompleted = TRUE
              AND (d.registrationdatetime BETWEEN _fromdate::timestamp AND _todate::timestamp + INTERVAL '1 day')
              AND (CASE WHEN _districtcode <> 0 THEN di.districtcode = _districtcode ELSE TRUE END)
              AND (CASE WHEN _srocode <> 0 THEN d.srocode = _srocode ELSE TRUE END)
        ),

        success_epay AS (
            SELECT
                e.applicationnumber,
                e.deptreferencecode,
                e.feerulecode,
                e.totalamount,
                b.paymentmode,
                b.paymentstatuscode,
                b.transactiontimestamp
            FROM kaveri.ams_reg_epaymenttransdetails e
            JOIN kaveri.ams_reg_epaymentbankackdetails b
              ON b.deptreferencecode = e.deptreferencecode
            WHERE e.isdelete = FALSE
              AND b.paymentstatuscode IN ('10700066','10700072')
              AND e.applicationnumber IN (SELECT applicationnumber FROM base_docs)
        ),

        amt AS (
            SELECT
                se.applicationnumber,
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (35,36,58,59,64,89,91,92,99,100,101,107,110,138)
                ),0) AS stampduty_amt,
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (59,100)
                ),0) AS cess_amt,
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ),0) AS regfee_amt,
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode = 2
                ),0) AS scanning_amt,
                COALESCE(SUM(se.totalamount),0) AS total_amt,
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode NOT IN (
                        35,36,58,59,64,89,91,92,99,100,101,107,110,138,
                        2,
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ),0) AS other_amt
            FROM success_epay se
            GROUP BY se.applicationnumber
        ),

        a AS (
            SELECT
                bd.distirctname,
                bd.sronamee,
                bd.documentnumber,
                string_agg(DISTINCT se.deptreferencecode, ',') AS challannumber,
                r.articlenamee AS articlename,
                bd.finalregistrationnumber,
                bd.uploaddocdeedpath AS copy_of_document,
                string_agg(DISTINCT rm.receiptnumber::text, ',') AS receiptnumber,
                string_agg(DISTINCT to_char(rm.dateofreceipt,'DD-MM-YYYY'), ',') AS dateofreceipt,
                string_agg(DISTINCT 'Schedule '||ps.scheduletype||' - '||ps.description, ',') AS description,
                string_agg(DISTINCT se.paymentmode, ',') AS paymentmode,
                bd.applicationnumber
            FROM base_docs bd
            LEFT JOIN kaveri.registrationarticles r
              ON bd.regarticlecode = r.regarticlecode
            LEFT JOIN success_epay se
              ON se.applicationnumber = bd.applicationnumber
            LEFT JOIN kaveri.receiptmaster rm
              ON bd.documentid = rm.documentid
             AND bd.applicationnumber = rm.applicationnumber
            LEFT JOIN kaveri.propertymaster p
              ON bd.documentid = p.documentid
             AND bd.applicationnumber = p.applicationnumber
            LEFT JOIN kaveri.propertyschedules ps
              ON p.propertyid = ps.propertyid
             AND p.applicationnumber = ps.applicationnumber
            LEFT JOIN amt
              ON amt.applicationnumber = bd.applicationnumber
            WHERE
                CASE
                    WHEN _choice = 0 THEN TRUE
                    WHEN _choice = 1 THEN TRUE
                    WHEN _choice = 2 THEN TRUE
                    WHEN _choice = 3 THEN TRUE
                    WHEN _choice = 4 THEN TRUE
                    WHEN _choice = 5 THEN TRUE
                    ELSE TRUE
                END
            GROUP BY
                bd.distirctname, bd.sronamee, bd.documentnumber,
                r.articlenamee, bd.finalregistrationnumber, bd.uploaddocdeedpath,
                bd.applicationnumber,
                amt.stampduty_amt, amt.cess_amt, amt.regfee_amt, amt.scanning_amt, amt.other_amt, amt.total_amt
            HAVING
                CASE
                    WHEN _choice = 0 THEN TRUE
                    WHEN _choice = 1 THEN (COALESCE(amt.total_amt,0) >= _minval AND COALESCE(amt.total_amt,0) <= _maxval)
                    WHEN _choice = 2 THEN (COALESCE(amt.regfee_amt,0) >= _minval AND COALESCE(amt.regfee_amt,0) <= _maxval)
                    WHEN _choice = 3 THEN (COALESCE(amt.stampduty_amt,0) >= _minval AND COALESCE(amt.stampduty_amt,0) <= _maxval)
                    WHEN _choice = 4 THEN (COALESCE(amt.scanning_amt,0) >= _minval AND COALESCE(amt.scanning_amt,0) <= _maxval)
                    WHEN _choice = 5 THEN (COALESCE(amt.other_amt,0) >= _minval AND COALESCE(amt.other_amt,0) <= _maxval)
                    ELSE TRUE
                END
            LIMIT pagesize OFFSET PageOffset
        ),

        cte AS (
            SELECT
                a.distirctname,
                a.sronamee AS sroname,
                a.documentnumber,
                a.challannumber,
                a.articlename,
                a.finalregistrationnumber,
                a.copy_of_document,
                a.receiptnumber,
                a.dateofreceipt,
                a.description,
                a.paymentmode,
                COALESCE(amt.stampduty_amt,0)::numeric AS stampduty,
                COALESCE(amt.regfee_amt,0)::numeric AS registrationfee,
                COALESCE(amt.scanning_amt,0)::numeric AS scanningfee,
                COALESCE(amt.other_amt,0)::numeric AS otherfees,
                COALESCE(amt.total_amt,0)::numeric AS total
            FROM a
            LEFT JOIN amt
              ON amt.applicationnumber = a.applicationnumber
        )
        SELECT
            cte.*,
            COUNT(*) OVER()::bigint AS totalcount
        FROM cte;

    ELSE

        RETURN QUERY
        WITH
        base_docs AS (
            SELECT
                d.documentid,
                d.applicationnumber,
                d.finalregistrationnumber,
                d.documentnumber,
                d.regarticlecode,
                d.uploaddocdeedpath,
                d.srocode,
                d.registrationdatetime,
                di.districtnamee AS distirctname,
                s.sronamee
            FROM kaveri.documentmaster d
            JOIN kaveri.sromaster s
              ON d.srocode = s.srocode
            JOIN kaveri.districtmaster di
              ON s.districtcode = di.districtcode
            WHERE d.isregistrationcompleted = TRUE
              AND (d.registrationdatetime BETWEEN _fromdate::timestamp AND _todate::timestamp + INTERVAL '1 day')
              AND (CASE WHEN _districtcode <> 0 THEN di.districtcode = _districtcode ELSE TRUE END)
              AND (CASE WHEN _srocode <> 0 THEN d.srocode = _srocode ELSE TRUE END)
        ),

        success_epay AS (
            SELECT
                e.applicationnumber,
                e.deptreferencecode,
                e.feerulecode,
                e.totalamount,
                b.paymentmode,
                b.paymentstatuscode,
                b.transactiontimestamp
            FROM kaveri.ams_reg_epaymenttransdetails e
            JOIN kaveri.ams_reg_epaymentbankackdetails b
              ON b.deptreferencecode = e.deptreferencecode
            WHERE e.isdelete = FALSE
              AND b.paymentstatuscode IN ('10700066','10700072')
              AND e.applicationnumber IN (SELECT applicationnumber FROM base_docs)
        ),

        amt AS (
            SELECT
                se.applicationnumber,
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (35,36,58,59,64,89,91,92,99,100,101,107,110,138)
                ),0) AS stampduty_amt,
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (59,100)
                ),0) AS cess_amt,
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ),0) AS regfee_amt,
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode = 2
                ),0) AS scanning_amt,
                COALESCE(SUM(se.totalamount),0) AS total_amt,
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode NOT IN (
                        35,36,58,59,64,89,91,92,99,100,101,107,110,138,
                        2,
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ),0) AS other_amt
            FROM success_epay se
            GROUP BY se.applicationnumber
        ),

        a AS (
            SELECT
                bd.distirctname,
                bd.sronamee,
                bd.documentnumber,
                string_agg(DISTINCT se.deptreferencecode, ',') AS challannumber,
                r.articlenamee AS articlename,
                bd.finalregistrationnumber,
                bd.uploaddocdeedpath AS copy_of_document,
                string_agg(DISTINCT rm.receiptnumber::text, ',') AS receiptnumber,
                string_agg(DISTINCT to_char(rm.dateofreceipt,'DD-MM-YYYY'), ',') AS dateofreceipt,
                string_agg(DISTINCT 'Schedule '||ps.scheduletype||' - '||ps.description, ',') AS description,
                string_agg(DISTINCT se.paymentmode, ',') AS paymentmode,
                bd.applicationnumber
            FROM base_docs bd
            LEFT JOIN kaveri.registrationarticles r
              ON bd.regarticlecode = r.regarticlecode
            LEFT JOIN success_epay se
              ON se.applicationnumber = bd.applicationnumber
            LEFT JOIN kaveri.receiptmaster rm
              ON bd.documentid = rm.documentid
             AND bd.applicationnumber = rm.applicationnumber
            LEFT JOIN kaveri.propertymaster p
              ON bd.documentid = p.documentid
             AND bd.applicationnumber = p.applicationnumber
            LEFT JOIN kaveri.propertyschedules ps
              ON p.propertyid = ps.propertyid
             AND p.applicationnumber = ps.applicationnumber
            LEFT JOIN amt
              ON amt.applicationnumber = bd.applicationnumber
            GROUP BY
                bd.distirctname, bd.sronamee, bd.documentnumber,
                r.articlenamee, bd.finalregistrationnumber, bd.uploaddocdeedpath,
                bd.applicationnumber,
                amt.stampduty_amt, amt.cess_amt, amt.regfee_amt, amt.scanning_amt, amt.other_amt, amt.total_amt
            HAVING
                CASE
                    WHEN _choice = 0 THEN TRUE
                    WHEN _choice = 1 THEN (COALESCE(amt.total_amt,0) >= _minval AND COALESCE(amt.total_amt,0) <= _maxval)
                    WHEN _choice = 2 THEN (COALESCE(amt.regfee_amt,0) >= _minval AND COALESCE(amt.regfee_amt,0) <= _maxval)
                    WHEN _choice = 3 THEN (COALESCE(amt.stampduty_amt,0) >= _minval AND COALESCE(amt.stampduty_amt,0) <= _maxval)
                    WHEN _choice = 4 THEN (COALESCE(amt.scanning_amt,0) >= _minval AND COALESCE(amt.scanning_amt,0) <= _maxval)
                    WHEN _choice = 5 THEN (COALESCE(amt.other_amt,0) >= _minval AND COALESCE(amt.other_amt,0) <= _maxval)
                    ELSE TRUE
                END
        ),

        cte AS (
            SELECT
                a.distirctname,
                a.sronamee AS sroname,
                a.documentnumber,
                a.challannumber,
                a.articlename,
                a.finalregistrationnumber,
                a.copy_of_document,
                a.receiptnumber,
                a.dateofreceipt,
                a.description,
                a.paymentmode,
                COALESCE(amt.stampduty_amt,0)::numeric AS stampduty,
                COALESCE(amt.regfee_amt,0)::numeric AS registrationfee,
                COALESCE(amt.scanning_amt,0)::numeric AS scanningfee,
                COALESCE(amt.other_amt,0)::numeric AS otherfees,
                COALESCE(amt.total_amt,0)::numeric AS total
            FROM a
            LEFT JOIN amt
              ON amt.applicationnumber = a.applicationnumber
        )
        SELECT
            cte.*,
            COUNT(*) OVER()::bigint AS totalcount
        FROM cte;

    END IF;

END;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_receipt_details_flat(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_receipt_details_flat_20260309(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_receipt_details_flat_20260309(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer DEFAULT 0, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(distirctname character varying, sroname character varying, documentnumber integer, challannumber text, articlename character varying, finalregistrationnumber character varying, copy_of_document text, receiptnumber text, dateofreceipt text, description text, paymentmode text, stampduty numeric, registrationfee numeric, scanningfee numeric, otherfees numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	

			PageOffset := (pagesize*pagenumber) - pagesize;
	        if (pagenumber<>-1 and   pagesize<>-1) then	
			
				return query 
				with cte as (with a as  
				(select  
					di.districtnamee as distirctname, 
					s.sronamee,
					d.documentnumber,								
					string_agg( distinct pay.deptreferencecode,',')as challannumber,
					r.articlenamee as articlename,
					d.finalregistrationnumber,
					d.uploaddocdeedpath as copy_of_document,
					string_agg( distinct ref.receiptnumber::text,',') as receiptnumber,
					string_agg(distinct to_char(ref.dateofreceipt,'DD-MM-YYYY'),',') as dateofreceipt, 
					string_agg( distinct 'Schedule '||ps.scheduletype || ' - ' || ps.description ,',')
					as description,
					string_agg( distinct ack.paymentmode,',') as paymentmode 

				 from kaveri.documentmaster d
				left join kaveri.registrationarticles r on d.regarticlecode = r.regarticlecode 
				--and d.srocode=259 
				join kaveri.sromaster s on d.srocode = s.srocode  
				left join kaveri.feesrequired  f on f.applicationnumber = d.applicationnumber 
				left join kaveri.ams_reg_epaymenttransdetails pay on d.applicationnumber = pay.applicationnumber 
				and pay.isdelete=false
				join kaveri.districtmaster di on s.districtcode = di.districtcode
				
				Left
				join kaveri.receiptmaster ref on d.documentid = ref.documentid  and d.applicationnumber = ref.applicationnumber
				left join kaveri.ams_reg_epaymentbankackdetails ack on pay.deptreferencecode = ack.deptreferencecode 
				left join kaveri.propertymaster p on d.documentid=p.documentid and d.applicationnumber = p.applicationnumber
				left join kaveri.propertyschedules ps on p.propertyid=ps.propertyid and p.applicationnumber = ps.applicationnumber
				where d.isregistrationcompleted = true  
				--and ack.paymentstatuscode in ('10700066','10700072')
				and (d.registrationdatetime  between  _fromdate ::timestamp and _todate ::timestamp + INTERVAL '1 day'  )
				and (case
					when _districtcode <> 0 then di.districtcode = _districtcode
					else
						true
				end)
				
				and (case
					when _srocode<>0 then d.srocode =_srocode
					else true
				end)
				and 
				(case

			          when _choice=0 then true  --amount type null
			          when _choice=1 then true  -- amount type total                
			          when _choice=2 then f.feerulecode=1     -- amount type registration fee
			          when _choice=3 then f.feerulecode in (36,58,59,104,89,88) -- amounttype stamp duty
			          when _choice=4 then f.feerulecode=2        -- amount type scanning fees
			          when _choice=5 then f.feerulecode not in (1,2,36,58,59,104,89,88)  -- amount type others
			           else 
			           true

          		end)
				
				--and (case
					--when _documentnumber<>null then dm.documentnumber =_documentnumber
					--else true
				--end)

				group by 

				di.districtnamee ,s.sronamee,d.documentnumber,
				r.articlenamee,d.finalregistrationnumber,d.uploaddocdeedpath
				having
       		(case

       		   when _choice=0 then true
         		 when _choice in (1,2,3,4,5)  then sum(f.amountpaid) >=_minval and sum(f.amountpaid)<=_maxval                
          	 	else 
          	 	true

         	 	end) limit pagesize offset PageOffset
				
				) 
				select a.*, 
				sum(distinct case when rr.feerulecode in (36,58,59,104,89,88) then rr.amountpaid else 0 end)as StampDuty, 
				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end )as RegistrationFees, 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)as scanningfee, 

				sum(case when rr.feerulecode not in (1,2,36,58,59,104,89,88) then rr.amountpaid else 0 end) as otherfees, 

				sum( coalesce(rr.amountpaid,0)) 	as Total

				from 
				      kaveri.documentmaster d 
				      left join kaveri.feesrequired  rr   on d.applicationnumber=rr.applicationnumber
					 inner join a on a.finalregistrationnumber = d.finalregistrationnumber 	

				group by a.distirctname,a.sronamee,a.documentnumber,a.articlename,a.finalregistrationnumber,
				a.challannumber,a.copy_of_document,a.receiptnumber,a.dateofreceipt,a.description,a.paymentmode)
				
			

				              select *,null::bigint as total_row from cte	;
				
				
				elsif (pagenumber=-1 or  pagesize=-1) then 

				return query 
				with cte as (with a as  
				(select  
					di.districtnamee as distirctname, 
					s.sronamee,
					d.documentnumber,								
					string_agg( distinct pay.deptreferencecode,',')as challannumber,
					r.articlenamee as articlename,
					d.finalregistrationnumber,
					d.uploaddocdeedpath as copy_of_document,
					string_agg( distinct ref.receiptnumber::text,',') as receiptnumber,
					string_agg(distinct to_char(ref.dateofreceipt,'DD-MM-YYYY'),',') as dateofreceipt, 
					string_agg( distinct 'Schedule '||ps.scheduletype || ' - ' || ps.description ,',')
					as description,
					string_agg( distinct ack.paymentmode,',') as paymentmode 

				 from kaveri.documentmaster d
				left join kaveri.registrationarticles r on d.regarticlecode = r.regarticlecode 
				--and d.srocode=259 
				join kaveri.sromaster s on d.srocode = s.srocode  
				left join kaveri.feesrequired  f on f.applicationnumber = d.applicationnumber 
				left join kaveri.ams_reg_epaymenttransdetails pay on d.applicationnumber = pay.applicationnumber 
				and pay.isdelete=false
				join kaveri.districtmaster di on s.districtcode = di.districtcode
				
				Left
				join kaveri.receiptmaster ref on d.documentid = ref.documentid  and d.applicationnumber = ref.applicationnumber
				left join kaveri.ams_reg_epaymentbankackdetails ack on pay.deptreferencecode = ack.deptreferencecode 
				left join kaveri.propertymaster p on d.documentid=p.documentid and d.applicationnumber = p.applicationnumber
				left join kaveri.propertyschedules ps on p.propertyid=ps.propertyid and p.applicationnumber = ps.applicationnumber
				where d.isregistrationcompleted = true  
				--and ack.paymentstatuscode in ('10700066','10700072')
				and (d.registrationdatetime  between  _fromdate ::timestamp and _todate ::timestamp + INTERVAL '1 day'  )
				and (case
					when _districtcode <> 0 then di.districtcode = _districtcode
					else
						true
				end)
				
				and (case
					when _srocode<>0 then d.srocode =_srocode
					else true
				end)
				and 
				(case

			          when _choice=0 then true  --amount type null
			          when _choice=1 then true  -- amount type total                
			          when _choice=2 then f.feerulecode=1     -- amount type registration fee
			          when _choice=3 then f.feerulecode in (36,58,59,104,89,88) -- amounttype stamp duty
			          when _choice=4 then f.feerulecode=2        -- amount type scanning fees
			          when _choice=5 then f.feerulecode not in (1,2,36,58,59,104,89,88)  -- amount type others
			           else 
			           true

          		end)
				
				--and (case
					--when _documentnumber<>null then dm.documentnumber =_documentnumber
					--else true
				--end)

				group by 

				di.districtnamee ,s.sronamee,d.documentnumber,
				r.articlenamee,d.finalregistrationnumber,d.uploaddocdeedpath
				having
       		(case

       		   when _choice=0 then true
         		 when _choice in (1,2,3,4,5)  then sum(f.amountpaid) >=_minval and sum(f.amountpaid)<=_maxval                
          	 	else 
          	 	true

         	 	end) 
				
				) 
				select a.*, 
				sum(distinct case when rr.feerulecode in (36,58,59,104,89,88) then rr.amountpaid else 0 end)as StampDuty, 
				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end )as RegistrationFees, 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)as scanningfee, 

				sum(case when rr.feerulecode not in (1,2,36,58,59,104,89,88) then rr.amountpaid else 0 end) as otherfees, 

				sum( coalesce(rr.amountpaid,0)) 	as Total

				from 
				      kaveri.documentmaster d 
				      left join kaveri.feesrequired  rr   on d.applicationnumber=rr.applicationnumber
					 inner join a on a.finalregistrationnumber = d.finalregistrationnumber 	

				group by a.distirctname,a.sronamee,a.documentnumber,a.articlename,a.finalregistrationnumber,
				a.challannumber,a.copy_of_document,a.receiptnumber,a.dateofreceipt,a.description,a.paymentmode)
				
			

				              select *,null::bigint as total_row from cte	;
						
	end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_receipt_details_flat_20260309(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_receipt_details_flat_20260406_bkp(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: manjunathswamy
--

CREATE FUNCTION kaverimis.fn_mis_daily_receipt_details_flat_20260406_bkp(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer DEFAULT 0, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(distirctname character varying, sroname character varying, documentnumber integer, challannumber text, articlename character varying, finalregistrationnumber character varying, copy_of_document text, receiptnumber text, dateofreceipt text, description text, paymentmode text, stampduty numeric, registrationfee numeric, scanningfee numeric, otherfees numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    PageOffset INTEGER := 0;
BEGIN
    PageOffset := (pagesize * pagenumber) - pagesize;

    IF (pagenumber <> -1 AND pagesize <> -1) THEN

        RETURN QUERY
        WITH
        base_docs AS (
            SELECT
                d.documentid,
                d.applicationnumber,
                d.finalregistrationnumber,
                d.documentnumber,
                d.regarticlecode,
                d.uploaddocdeedpath,
                d.srocode,
                d.registrationdatetime,
                di.districtnamee AS distirctname,
                s.sronamee
            FROM kaveri.documentmaster d
            JOIN kaveri.sromaster s
              ON d.srocode = s.srocode
            JOIN kaveri.districtmaster di
              ON s.districtcode = di.districtcode
            WHERE d.isregistrationcompleted = TRUE
              AND (d.registrationdatetime BETWEEN _fromdate::timestamp AND _todate::timestamp + INTERVAL '1 day')
              AND (CASE WHEN _districtcode <> 0 THEN di.districtcode = _districtcode ELSE TRUE END)
              AND (CASE WHEN _srocode <> 0 THEN d.srocode = _srocode ELSE TRUE END)
        ),

        success_epay AS (
            SELECT
                e.applicationnumber,
                e.deptreferencecode,
                e.feerulecode,
                e.totalamount,
                b.paymentmode,
                b.paymentstatuscode,
                b.transactiontimestamp
            FROM kaveri.ams_reg_epaymenttransdetails e
            JOIN kaveri.ams_reg_epaymentbankackdetails b
              ON b.deptreferencecode = e.deptreferencecode
            WHERE e.isdelete = FALSE
              AND b.paymentstatuscode IN ('10700066','10700072')
              AND e.applicationnumber IN (SELECT applicationnumber FROM base_docs)
        ),

        -- amount buckets per application (same feerulecode buckets as docreg)
        amt AS (
            SELECT
                se.applicationnumber,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode IN (35,36,64,89,91,92,101,107,110,138)),0) AS stampduty_amt,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode IN (59,100)),0) AS cess_amt,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode IN (
                    1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                    57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                )),0) AS regfee_amt,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode = 2),0) AS scanning_amt,
                COALESCE(SUM(se.totalamount),0) AS total_amt,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode NOT IN (
                    -- stamp + cess
                    35,36,64,89,91,92,101,107,110,138,59,100,
                    -- scanning
                    2,
                    -- registration-fee bucket
                    1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                    57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                )),0) AS other_amt
            FROM success_epay se
            GROUP BY se.applicationnumber
        ),

        a AS (
            SELECT
                bd.distirctname,
                bd.sronamee,
                bd.documentnumber,
                string_agg(DISTINCT se.deptreferencecode, ',') AS challannumber,
                r.articlenamee AS articlename,
                bd.finalregistrationnumber,
                bd.uploaddocdeedpath AS copy_of_document,
                string_agg(DISTINCT rm.receiptnumber::text, ',') AS receiptnumber,
                string_agg(DISTINCT to_char(rm.dateofreceipt,'DD-MM-YYYY'), ',') AS dateofreceipt,
                string_agg(DISTINCT 'Schedule '||ps.scheduletype||' - '||ps.description, ',') AS description,
                string_agg(DISTINCT se.paymentmode, ',') AS paymentmode,
                bd.applicationnumber
            FROM base_docs bd
            LEFT JOIN kaveri.registrationarticles r
              ON bd.regarticlecode = r.regarticlecode

            LEFT JOIN success_epay se
              ON se.applicationnumber = bd.applicationnumber

            LEFT JOIN kaveri.receiptmaster rm
              ON bd.documentid = rm.documentid
             AND bd.applicationnumber = rm.applicationnumber

            LEFT JOIN kaveri.propertymaster p
              ON bd.documentid = p.documentid
             AND bd.applicationnumber = p.applicationnumber

            LEFT JOIN kaveri.propertyschedules ps
              ON p.propertyid = ps.propertyid
             AND p.applicationnumber = ps.applicationnumber

            -- choice filter now based on SUCCESS epay buckets (amt table)
            LEFT JOIN amt
              ON amt.applicationnumber = bd.applicationnumber

            WHERE
                CASE
                    WHEN _choice = 0 THEN TRUE
                    WHEN _choice = 1 THEN TRUE
                    WHEN _choice = 2 THEN TRUE
                    WHEN _choice = 3 THEN TRUE
                    WHEN _choice = 4 THEN TRUE
                    WHEN _choice = 5 THEN TRUE
                    ELSE TRUE
                END

            GROUP BY
                bd.distirctname, bd.sronamee, bd.documentnumber,
                r.articlenamee, bd.finalregistrationnumber, bd.uploaddocdeedpath,
                bd.applicationnumber,
                amt.stampduty_amt, amt.cess_amt, amt.regfee_amt, amt.scanning_amt, amt.other_amt, amt.total_amt

            HAVING
                CASE
                    WHEN _choice = 0 THEN TRUE
                    WHEN _choice = 1 THEN (COALESCE(amt.total_amt,0) >= _minval AND COALESCE(amt.total_amt,0) <= _maxval)
                    WHEN _choice = 2 THEN (COALESCE(amt.regfee_amt,0) >= _minval AND COALESCE(amt.regfee_amt,0) <= _maxval)
                    WHEN _choice = 3 THEN ((COALESCE(amt.stampduty_amt,0) + COALESCE(amt.cess_amt,0)) >= _minval
                                            AND (COALESCE(amt.stampduty_amt,0) + COALESCE(amt.cess_amt,0)) <= _maxval)
                    WHEN _choice = 4 THEN (COALESCE(amt.scanning_amt,0) >= _minval AND COALESCE(amt.scanning_amt,0) <= _maxval)
                    WHEN _choice = 5 THEN (COALESCE(amt.other_amt,0) >= _minval AND COALESCE(amt.other_amt,0) <= _maxval)
                    ELSE TRUE
                END

            LIMIT pagesize OFFSET PageOffset
        ),

        cte AS (
            SELECT
                a.distirctname,
                a.sronamee AS sroname,
                a.documentnumber,
                a.challannumber,
                a.articlename,
                a.finalregistrationnumber,
                a.copy_of_document,
                a.receiptnumber,
                a.dateofreceipt,
                a.description,
                a.paymentmode,

                -- amounts from SUCCESS epay buckets
                COALESCE(amt.stampduty_amt,0)::numeric AS stampduty,
                COALESCE(amt.regfee_amt,0)::numeric AS registrationfee,
                COALESCE(amt.scanning_amt,0)::numeric AS scanningfee,
                COALESCE(amt.other_amt,0)::numeric AS otherfees,
                COALESCE(amt.total_amt,0)::numeric AS total
            FROM a
            LEFT JOIN amt
              ON amt.applicationnumber = a.applicationnumber
        )
        SELECT
            cte.*,
            COUNT(*) OVER()::bigint AS totalcount
        FROM cte;

    ELSE
        -- non-paginated
        RETURN QUERY
        WITH
        base_docs AS (
            SELECT
                d.documentid,
                d.applicationnumber,
                d.finalregistrationnumber,
                d.documentnumber,
                d.regarticlecode,
                d.uploaddocdeedpath,
                d.srocode,
                d.registrationdatetime,
                di.districtnamee AS distirctname,
                s.sronamee
            FROM kaveri.documentmaster d
            JOIN kaveri.sromaster s
              ON d.srocode = s.srocode
            JOIN kaveri.districtmaster di
              ON s.districtcode = di.districtcode
            WHERE d.isregistrationcompleted = TRUE
              AND (d.registrationdatetime BETWEEN _fromdate::timestamp AND _todate::timestamp + INTERVAL '1 day')
              AND (CASE WHEN _districtcode <> 0 THEN di.districtcode = _districtcode ELSE TRUE END)
              AND (CASE WHEN _srocode <> 0 THEN d.srocode = _srocode ELSE TRUE END)
        ),

        success_epay AS (
            SELECT
                e.applicationnumber,
                e.deptreferencecode,
                e.feerulecode,
                e.totalamount,
                b.paymentmode,
                b.paymentstatuscode,
                b.transactiontimestamp
            FROM kaveri.ams_reg_epaymenttransdetails e
            JOIN kaveri.ams_reg_epaymentbankackdetails b
              ON b.deptreferencecode = e.deptreferencecode
            WHERE e.isdelete = FALSE
              AND b.paymentstatuscode IN ('10700066','10700072')
              AND e.applicationnumber IN (SELECT applicationnumber FROM base_docs)
        ),

        amt AS (
            SELECT
                se.applicationnumber,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode IN (35,36,64,89,91,92,101,107,110,138)),0) AS stampduty_amt,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode IN (59,100)),0) AS cess_amt,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode IN (
                    1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                    57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                )),0) AS regfee_amt,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode = 2),0) AS scanning_amt,
                COALESCE(SUM(se.totalamount),0) AS total_amt,
                COALESCE(SUM(se.totalamount) FILTER (WHERE se.feerulecode NOT IN (
                    35,36,64,89,91,92,101,107,110,138,59,100,
                    2,
                    1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                    57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                )),0) AS other_amt
            FROM success_epay se
            GROUP BY se.applicationnumber
        ),

        a AS (
            SELECT
                bd.distirctname,
                bd.sronamee,
                bd.documentnumber,
                string_agg(DISTINCT se.deptreferencecode, ',') AS challannumber,
                r.articlenamee AS articlename,
                bd.finalregistrationnumber,
                bd.uploaddocdeedpath AS copy_of_document,
                string_agg(DISTINCT rm.receiptnumber::text, ',') AS receiptnumber,
                string_agg(DISTINCT to_char(rm.dateofreceipt,'DD-MM-YYYY'), ',') AS dateofreceipt,
                string_agg(DISTINCT 'Schedule '||ps.scheduletype||' - '||ps.description, ',') AS description,
                string_agg(DISTINCT se.paymentmode, ',') AS paymentmode,
                bd.applicationnumber
            FROM base_docs bd
            LEFT JOIN kaveri.registrationarticles r
              ON bd.regarticlecode = r.regarticlecode
            LEFT JOIN success_epay se
              ON se.applicationnumber = bd.applicationnumber
            LEFT JOIN kaveri.receiptmaster rm
              ON bd.documentid = rm.documentid
             AND bd.applicationnumber = rm.applicationnumber
            LEFT JOIN kaveri.propertymaster p
              ON bd.documentid = p.documentid
             AND bd.applicationnumber = p.applicationnumber
            LEFT JOIN kaveri.propertyschedules ps
              ON p.propertyid = ps.propertyid
             AND p.applicationnumber = ps.applicationnumber
            LEFT JOIN amt
              ON amt.applicationnumber = bd.applicationnumber
            GROUP BY
                bd.distirctname, bd.sronamee, bd.documentnumber,
                r.articlenamee, bd.finalregistrationnumber, bd.uploaddocdeedpath,
                bd.applicationnumber,
                amt.stampduty_amt, amt.cess_amt, amt.regfee_amt, amt.scanning_amt, amt.other_amt, amt.total_amt
            HAVING
                CASE
                    WHEN _choice = 0 THEN TRUE
                    WHEN _choice = 1 THEN (COALESCE(amt.total_amt,0) >= _minval AND COALESCE(amt.total_amt,0) <= _maxval)
                    WHEN _choice = 2 THEN (COALESCE(amt.regfee_amt,0) >= _minval AND COALESCE(amt.regfee_amt,0) <= _maxval)
                    WHEN _choice = 3 THEN ((COALESCE(amt.stampduty_amt,0) + COALESCE(amt.cess_amt,0)) >= _minval
                                            AND (COALESCE(amt.stampduty_amt,0) + COALESCE(amt.cess_amt,0)) <= _maxval)
                    WHEN _choice = 4 THEN (COALESCE(amt.scanning_amt,0) >= _minval AND COALESCE(amt.scanning_amt,0) <= _maxval)
                    WHEN _choice = 5 THEN (COALESCE(amt.other_amt,0) >= _minval AND COALESCE(amt.other_amt,0) <= _maxval)
                    ELSE TRUE
                END
        ),

        cte AS (
            SELECT
                a.distirctname,
                a.sronamee AS sroname,
                a.documentnumber,
                a.challannumber,
                a.articlename,
                a.finalregistrationnumber,
                a.copy_of_document,
                a.receiptnumber,
                a.dateofreceipt,
                a.description,
                a.paymentmode,
                COALESCE(amt.stampduty_amt,0)::numeric AS stampduty,
                COALESCE(amt.regfee_amt,0)::numeric AS registrationfee,
                COALESCE(amt.scanning_amt,0)::numeric AS scanningfee,
                COALESCE(amt.other_amt,0)::numeric AS otherfees,
                COALESCE(amt.total_amt,0)::numeric AS total
            FROM a
            LEFT JOIN amt
              ON amt.applicationnumber = a.applicationnumber
        )
        SELECT
            cte.*,
            COUNT(*) OVER()::bigint AS totalcount
        FROM cte;

    END IF;

END;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_receipt_details_flat_20260406_bkp(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer) OWNER TO manjunathswamy;

--
-- Name: fn_mis_daily_receipt_details_flat_bck(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_receipt_details_flat_bck(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer DEFAULT 0, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(distirctname character varying, sroname character varying, documentnumber integer, challannumber text, articlename character varying, finalregistrationnumber character varying, copy_of_document text, receiptnumber text, dateofreceipt text, description text, paymentmode text, stampduty numeric, registrationfee numeric, scanningfee numeric, otherfees numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	

			PageOffset := (pagesize*pagenumber) - pagesize;
	        if (pagenumber<>-1 and   pagesize<>-1) then	
			
	        	return query 
				with cte as (with a as  
				(select  
					d.distirctname as distirctname, 
					d.sroname,
					d.documentnumber,								
					string_agg( distinct d.challannumber,',')as challannumber,
					d.articlename as articlename,
					d.finalregistrationnumber,
					d.copy_of_document as copy_of_document,
					string_agg( distinct d.receiptnumber::text,',') as receiptnumber,
					string_agg(distinct d.dateofreceipt,',') as dateofreceipt, 
					string_agg( distinct d.description ,',')
					as description,
					string_agg( distinct d.paymentmode,',') as paymentmode 

				 from kaverimis.statisticalform7table d
				where d.isregistrationcompleted = true  
				
				and (d.registrationdatetime  between  _fromdate ::timestamp
				and _todate ::timestamp + INTERVAL '1 day'  )
				and (case
					when _districtcode <> 0 then d.districtcode = _districtcode
					else
						true
				end)
				
				and (case
					when _srocode<>0 then d.srocode =_srocode
					else true
				end)
				--and d.receiptnumber is not null

				and 
				(case

			          when _choice=0 then true  --amount type null
			          when _choice=1 then true  -- amount type total                
			          when _choice=2 then d.feerulecode=1     -- amount type registration fee
			          when _choice=3 then d.feerulecode in (36,58,59,104,89,88) -- amounttype stamp duty
			          when _choice=4 then d.feerulecode=2        -- amount type scanning fees
			          when _choice=5 then d.feerulecode not in (1,2,36,58,59,104,89,88) -- amount type others
			           else 
			           true

          		end)
				
				--and (case
					--when _documentnumber<>null then dm.documentnumber =_documentnumber
					--else true
				--end)

				group by 

				d.distirctname ,d.sroname,d.documentnumber,
				d.articlename,d.finalregistrationnumber,d.copy_of_document
				having
       		(case

       		   when _choice=0 then true
         		 when _choice in (1,2,3,4,5)  then sum(d.amountpaid) >=_minval 
         		 and sum(d.amountpaid)<=_maxval                
          	 	else 
          	 	true

         	 	end)OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY
				
				) 
				select a.*, 
				sum(distinct case when rr.feerulecode in (36,58,59,104,89,88) then rr.amountpaid else 0 end)as StampDuty, 
				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end )as RegistrationFees, 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)as scanningfee, 

				sum(case when rr.feerulecode not in (1,2,36,58,59,104,89,88) then rr.amountpaid else 0 end) as otherfees, 

				sum( coalesce(rr.amountpaid,0))  	as Total 

				from 
				      kaverimis.statisticalform7table  rr   
					 inner join a on a.finalregistrationnumber = rr.finalregistrationnumber  	

				group by a.distirctname,a.sroname,a.documentnumber,a.articlename,a.finalregistrationnumber,
				a.challannumber,a.copy_of_document,a.receiptnumber,a.dateofreceipt,a.description,a.paymentmode)
			

		    select * from cte
			join (select null::bigint as total_rows ) total_row on true
		   order by cte.distirctname,cte.sroname; 
	       
				
				
				elsif (pagenumber=-1 or  pagesize=-1) then 

				return query 
				with cte as (with a as  
				(select  
					d.distirctname as distirctname, 
					d.sroname,
					d.documentnumber,								
					string_agg( distinct d.challannumber,',')as challannumber,
					d.articlename as articlename,
					d.finalregistrationnumber,
					d.copy_of_document as copy_of_document,
					string_agg( distinct d.receiptnumber::text,',') as receiptnumber,
					string_agg(distinct d.dateofreceipt,',') as dateofreceipt, 
					string_agg( distinct d.description ,',')
					as description,
					string_agg( distinct d.paymentmode,',') as paymentmode 

				 from kaverimis.statisticalform7table d
				where d.isregistrationcompleted = true  
				
				and (d.registrationdatetime  between  _fromdate ::timestamp
				and _todate ::timestamp + INTERVAL '1 day'  )
				and (case
					when _districtcode <> 0 then d.districtcode = _districtcode
					else
						true
				end)
				
				and (case
					when _srocode<>0 then d.srocode =_srocode
					else true
				end)
				--and d.receiptnumber is not null

				and 
				(case

			          when _choice=0 then true  --amount type null
			          when _choice=1 then true  -- amount type total                
			          when _choice=2 then d.feerulecode=1     -- amount type registration fee
			          when _choice=3 then d.feerulecode in (36,58,59,104,89,88) -- amounttype stamp duty
			          when _choice=4 then d.feerulecode=2        -- amount type scanning fees
			          when _choice=5 then d.feerulecode not in (1,2,36,58,59,104,89,88) -- amount type others
			           else 
			           true

          		end)
				
				--and (case
					--when _documentnumber<>null then dm.documentnumber =_documentnumber
					--else true
				--end)

				group by 

				d.distirctname ,d.sroname,d.documentnumber,
				d.articlename,d.finalregistrationnumber,d.copy_of_document
				having
       		(case

       		   when _choice=0 then true
         		 when _choice in (1,2,3,4,5)  then sum(d.amountpaid) >=_minval 
         		 and sum(d.amountpaid)<=_maxval                
          	 	else 
          	 	true

         	 	end)
				
				) 
				select a.*, 
				sum(distinct case when rr.feerulecode in (36,58,59,104,89,88) then rr.amountpaid else 0 end)as StampDuty, 
				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end )as RegistrationFees, 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)as scanningfee, 

				sum(case when rr.feerulecode not in (1,2,36,58,59,104,89,88) then rr.amountpaid else 0 end) as otherfees, 

				sum( coalesce(rr.amountpaid,0))  	as Total 

				from 
				      kaverimis.statisticalform7table  rr   
					 inner join a on a.finalregistrationnumber = rr.finalregistrationnumber  	

				group by a.distirctname,a.sroname,a.documentnumber,a.articlename,a.finalregistrationnumber,
				a.challannumber,a.copy_of_document,a.receiptnumber,a.dateofreceipt,a.description,a.paymentmode)
			

		    select * from cte
			join (select null::bigint as total_rows ) total_row on true
		order by cte.distirctname,cte.sroname; 
						
	end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_receipt_details_flat_bck(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_receipt_details_optimization(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_daily_receipt_details_optimization(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice integer DEFAULT 0, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(finalregistrationnumber character varying, applicationnumber character varying, distirctname character varying, sroname character varying, documentnumber integer, challannumber text, articlename character varying, copy_of_document text, receiptnumber text, dateofreceipt text, description text, paymentmode text, stampduty numeric, registrationfee numeric, scanningfee numeric, otherfees numeric, total numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;

	begin
		
---		PageOffset := ((pagenumber - 1) * pagesize);
		PageOffset := (pagesize*pagenumber) - pagesize;
	
		return query 
		
		with cte as (
		
		with a as (
		
			select
					distinct d.finalregistrationnumber,
					d.applicationnumber,
					di.districtnamee as distirctname, 
					s.sronamee,
					d.documentnumber,								
					string_agg( distinct pay.deptreferencecode,',')as challannumber,
					r.articlenamee as articlename,
					d.uploaddocdeedpath as copy_of_document,
					string_agg( distinct ref.receiptnumber::text,',') as receiptnumber,
					string_agg(distinct to_char(ref.dateofreceipt,'DD-MM-YYYY'),',') as dateofreceipt, 
					string_agg( distinct 'Schedule '||ps.scheduletype || ' - ' || ps.description ,',') as description,
					string_agg( distinct ack.paymentmode,',') as paymentmode
					
				from kaveri.documentmaster d
				join kaveri.registrationarticles r on d.regarticlecode = r.regarticlecode 
				join kaveri.sromaster s on d.srocode = s.srocode  
				
				join kaveri.feesrequired f on f.applicationnumber = d.applicationnumber
				
				join kaveri.ams_reg_epaymenttransdetails pay on d.applicationnumber = pay.applicationnumber 
				join kaveri.districtmaster di on s.districtcode = di.districtcode
				
				Left join kaveri.receiptmaster ref on d.documentid = ref.documentid 
				join kaveri.ams_reg_epaymentbankackdetails ack on pay.deptreferencecode = ack.deptreferencecode 
				join kaveri.propertymaster p on p.documentid=d.documentid
				left join kaveri.propertyschedules ps on ps.propertyid=p.propertyid
				where d.isregistrationcompleted = true  
				and d.registrationdatetime::date >= _fromdate and  d.registrationdatetime::date <= _todate
				
				and (CASE   
                      WHEN _choice <> 1 and _choice <> 2 and _choice <> 3 and _choice <> 4 and _choice <> 5 then 
                            
							true 
							
                      ELSE 
                                
							 
										(case   
			                                WHEN _choice = 1 THEN f.feerulecode in (36,58,59) 
			                                WHEN _choice = 2 THEN f.feerulecode in (1)
			                                WHEN _choice = 3 THEN f.feerulecode in (2) 
			                                WHEN _choice = 4 THEN f.feerulecode  not in (1,2,36,58,59,64)
			                                ELSE 
			                                    TRUE
			                            end)
							
                end)
				
				and (case
					when _districtcode <> 0 then di.districtcode=_districtcode 
					else
						true
				end)
				
				and (case
					when _srocode<>0 then d.srocode=_srocode
					else true
				end)
				
				
				group by 

				di.districtnamee ,s.sronamee,d.documentnumber,r.articlenamee,d.finalregistrationnumber,d.uploaddocdeedpath,f.amountpaid,f.applicationnumber,d.applicationnumber  
				
				having 
				
				(case   
			                                WHEN _minval is not null and _maxval is not null then
				                                sum(f.amountpaid)>=_minval and sum(f.amountpaid)<=_maxval
			                                ELSE 
			                                	true 
			                                    
				end) 
				
				limit pagesize offset PageOffset
		)
		
		select a.*, 
		
				sum(distinct case when rr.feerulecode in (36,58,59) then rr.amountpaid else 0 end)as StampDuty,
				
				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end )as RegistrationFees, 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)as scanningfee, 

				sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end) as otherfees, 

				(sum(case when rr.feerulecode in (36,58,59) then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode=1 then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode=2 then rr.amountpaid else 0 end)+ 

				sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)) 	as Total 

				from 
				      a 
				      join kaveri.feesrequired  rr   on a.applicationnumber=rr.applicationnumber
					  ---inner join a on a.finalregistrationnumber = d.finalregistrationnumber 	

				group by a.distirctname,a.sronamee,a.documentnumber,a.articlename,a.finalregistrationnumber,
				a.challannumber,a.copy_of_document,a.receiptnumber,a.dateofreceipt,a.description,a.paymentmode,a.applicationnumber
		
		)
		
		select * from cte;
						

	END;
$$;


