--
-- Name: fn_mis_daily_register_of_fees_statutory(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document character varying, considerationamount numeric, marketvalue numeric, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid character varying, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees numeric, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if pagenumber <> -1 and pagesize <> -1 then 

			return query
			with cte as (with a as ( select     
			dsm.districtnamee,
			sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,
			to_char(dm.presentdatetime,'dd-MM-YYYY') presentdate,
			(select 
			string_agg(distinct (coalesce(firstname,' ')||coalesce(middlename,' ')|| 
			coalesce(lastname,' ')::text),',') 
			from kaveri.partyinfo where applicationnumber=dm.applicationnumber  
			and ispresenter is true group by applicationnumber)as presentername ,
			--pi1.presentername,
			sa.articlenamee AS descriptionofdocument, 
			max(pm.sroconsideration) as consideration_fees,
			max(pm.sromarketvalue) as marketvalue,
			pm.propertytypeid ,
			case when dm.finalregistrationnumber is not null
			then dm.finalregistrationnumber else dm.pendingdocumentnumber end documentnumber,
			b.booknameenglish ,
			null  as volumenumber,
			(select sum(amsreg.totalamount)
			from kaveri.ams_reg_epaymenttransdetails amsreg where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false) as Treasury_amount,
			(select to_char(amsreg.inserteddatetime,'dd-MM-yyyy')
			from kaveri.ams_reg_epaymenttransdetails amsreg where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false limit 1)  as Challan_date ,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofcompletion,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofreturn,
			dm.uploaddocdeedpath as copy_of_document

			from  kaveri.documentmaster dm
			join  kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber 
			join kaveri.stamparticles sa on pm.stamparticlecode=sa.stamparticlecode 
			JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
			join kaveri.booktypemaster b on dm.bookid=b.bookid 
			--left join kaveri.ams_reg_epaymenttransdetails amsreg on 
			--amsreg.applicationnumber = dm.applicationnumber and amsreg.isdelete=false  
			where 
			
			(dm.registrationdatetime between _fromdate	and _todate + INTERVAL '1 day'  )
			and 
			
			(

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			and
			
				(

                    CASE

                    WHEN _srocode <> 0 THEN  dm.srocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  dm.finalregistrationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
               and 
			    
			 dm.isregistrationcompleted=true
			 group by dsm.districtnamee,sm.sronamee,dm.finalregistrationnumber,dm.applicationnumber,
			 sa.articlenamee,dm.pendingdocumentnumber,b.booknameenglish,
			 --,booknameenglish,
			dm.registrationdatetime,dm.uploaddocdeedpath,dm.presentdatetime,pm.propertytypeid	)

			select a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) stampduty,
			sum(case when fr.feerulecode=59  then amountpaid else 0 end) cess,
			sum(case when a.propertytypeid=28 and fr.feerulecode=58 then amountpaid else 0 end ) as municipalsurcharge,
			sum(case when a.propertytypeid=17 and fr.feerulecode=58 then amountpaid else 0 end ) as taluksurcharge,
			sum(case when fr.feerulecode in (36,58,59)  then amountpaid else 0 end)  as Total_duty,
			a.documentnumber,a.booknameenglish,a.volumenumber,
			a.dateofcompletion,a.dateofreturn,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end) registrationfees,
			sum(case when fr.feerulecode=41 then amountpaid else 0 end) as feesforcopies,
			sum(case when fr.feerulecode=2 then amountpaid else 0 end) miscelaneousfees,
			sum(case when fr.feerulecode in (34,91)then amountpaid else 0 end) otherstampduty,
			NULL::numeric miscellaneous_article_fees,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=41 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=2 then amountpaid else 0 end)+
			sum(case when fr.feerulecode  in (34,91)then amountpaid else 0 end) Total_fees2,
			a.Treasury_amount,
			a.Challan_date,
			string_agg(distinct (case when fr.feerulecode=6 then r.receiptnumber::text  else ' ' end ),' ')as dailymutationreceipts,
			sum(case when fr.feerulecode=6 then fr.amountpaid else 0 end) mutationfees,
			string_agg(distinct ( case when fr.feerulecode=6 then to_char(r.dateofreceipt,'DD-MM-YYYY')  else ' ' end ),' ')as mutationfeedate,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			a.copy_of_document

			from 
			a
			left join 	kaveri.feesrequired fr on a.applicationnumber=fr.applicationnumber
			left join kaveri.receiptmaster r on fr.receiptid=r.receiptid
			
			group by a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,
			a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			a.documentnumber,a.booknameenglish,
			a.volumenumber,a.Treasury_amount,
			a.Challan_date,a.dateofcompletion,a.dateofreturn,a.copy_of_document,a.propertytypeid
			
			
			
			

			Union all
			
			 
			
			select  
					dsm.districtnamee as districtname,
					sr.sronamee as sroname,
					null as finalregistrationnumber,
					eca.applicationnumber,
					to_char(a.applicationenddate,'dd-MM-YYYY') as  signeddatetime,
					c.firstname||c.middlename||c.lastname  as Presentername,
					'ECSearch' as descriptionofdocument,
					null::numeric  as considerationfees,
					null::numeric  as marketvalue,
					sum(case when er.feeruleid=64  then er.payableamount else 0 end) searchfee,
					sum(case when er.feeruleid=23  then er.payableamount else 0 end) searchapplfee,
					null::numeric as muncipalsurcharge,
					null::numeric  as taluksurcharge,
					 sum(case when er.feeruleid=64  then er.payableamount else 0 end)+
					 sum(case when er.feeruleid=23  then er.payableamount else 0 end)
					 as Total_duty,
					eca.certificatenumber as documentnumber,
					null as bookname,
					null as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofreturn,
					null as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount) as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
					null as dailymutation_receipt,
					null::numeric as mutationfees,
					null as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					eca.signedform22 as copy_of_document
					
					
					  from kaveri.ec_applicationdetails   eca
					  join kaveri.applicantapplicationdetails a on eca.applicationnumber=a.applicationnumber 
					  join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=eca.userid 
					  left join kaveri.ams_reg_epaymenttransdetails amsre on eca.applicationnumber=amsre.applicationnumber 
					  join  kaveri.ec_requiredfees er on eca.ecid=er.ecid 
					 where 
					 
					 (a.applicationenddate between _fromdate	and _todate + INTERVAL '1 day'  ) and 
					 (

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
				 and 
					 
					 (

                    CASE

                    WHEN _srocode <> 0 THEN  eca.kaverisrocode = _srocode

                    ELSE TRUE

                    end

                    )
				 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  eca.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
                and  a.currentstatus='CE110'
					 
					
					group by dsm.districtnamee,sr.sronamee,eca.applicationnumber,eca.signedform22,
					eca.propertydescription,a.applicationenddate,c.firstname,c.middlename,c.lastname,
					eca.certificatenumber,a.applicationenddate
					

			Union All

			select  
					dsm.districtnamee as district,
					sr.sronamee as sroname,
					null as finalregistrationnumber,
					cca.applicationnumber,
					to_char(a.applicationenddate,'dd-MM-YYYY') as  signeddatetime,
					c.firstname||c.middlename||c.lastname  as Presentername,
					'CCSearch' as descriptionofdocument,
					null::numeric as considerationfees,
					null::numeric as marketvalue,
					sum(case when cr.feeruleid=36  then cr.payableamount else 0 end) stampduty,
					sum(case when cr.feeruleid=14  then cr.payableamount else 0 end) searchfee,
				
					null as muncipalsurcharge,
					null as taluksurcharge,
					 sum(case when cr.feeruleid=36  then payableamount else 0 end)+
					 sum(case when cr.feeruleid=14  then payableamount else 0 end)
					 as Total_duty,
					cca.certificatenumber as documentnumber,
					null::text as bookname,
					null::text as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofreturn,
					null::numeric as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount) as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
					null as dailymutation_receipt,
					null::numeric as mutationfees,
					null::text as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					cca.signedform22 as copy_of_document
					
					
					from kaveri.cc_applicationdetails   cca
					  join kaveri.applicantapplicationdetails a on cca.applicationnumber=a.applicationnumber 
					  join kaveri.sromaster sr on cca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=cca.userid  
					  left join kaveri.ams_reg_epaymenttransdetails amsre on cca.applicationnumber=amsre.applicationnumber 
					  join (select ccid,feeruleid,sum(payableamount) as payableamount  from kaveri.cc_requiredfees  
					  group by ccid,feeruleid)cr on cca.ccid=cr.ccid 
					 where 
					 
					 (a.applicationenddate between _fromdate
			 			and _todate + INTERVAL '1 day'  ) and 
					 
					 (

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			 and 
					 
					 (

                    CASE

                    WHEN _srocode <> 0 THEN  cca.kaverisrocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  cca.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
                and  a.currentstatus='CC109'
			
					group by dsm.districtnamee,sr.sronamee,cca.applicationnumber,cca.signedform22,
					a.applicationenddate,c.firstname,c.middlename,c.lastname,
					cca.certificatenumber

			Union All

			select dsm.districtnamee,sm.sronamee,
			o.applicationnumber,
			o.applicationnumber,
			to_char(othfee.receiptdate,'dd-MM-YYYY') presentdate,
			othfee.partyfirstname||' '||othfee.partymiddlename||' '||othfee.partylastname as presentername,
			othfee.paymentdescription as descriptionofdocument,
			null as consideration_fees,
			null as marketvalue,
			sum( case when o.feerulecode=36 then COALESCE (receipttotal,0)  else 0 end) stampduty,
			null::numeric as cess,
			NULL as municipalsurcharge,
			NULL as Taluksurcharge,
			sum(distinct case when o.feerulecode=36 then COALESCE (receipttotal,0)  else 0 end) Total_duty,
			null as documentnumber,
			othfee.bookdetails as bookid,
			null::text as volumenumber,
			to_char(receiptdate,'dd-MM-YYYY') dateofcompletion,
			to_char(receiptdate,'dd-MM-YYYY') as dateofreturn,
			sum( case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end) registrationfees,
			null as feesforcopies,
			sum(distinct  case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) miscelaneousfees,
			null::numeric as otherstampduty,
			null as miscellaneous_article_fees,
			sum( case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end)+
			sum( case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) 
			as total_fees2,
			Null::numeric as Treasury_amount,
			null  as Treasury_transaction_date,
			 null::text as dailymutationreceipts,
			sum(distinct  case when o.feerulecode=6 then COALESCE (receipttotal,0) else 0 end) mutationfees,
			Null as mutationfees_to_treasury_date,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			null::text copy_of_document
			from kaveri.otherfeesrequired o
			join kaveri.otherreceiptdetails othfee  on o.receiptid = othfee.receiptid
			join kaveri.departmentusers d on o.departmentuserid = d.userid
			 join kaveri.sromaster sm on sm.srocode=d.srocode
			 JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode 
			 where 
			 
			 (othfee.receiptdate between _fromdate	and _todate + INTERVAL '1 day'  ) and 
			 
			 (

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode=_districtcode 

                    ELSE TRUE

                    end

                    )
			 and 
			 (

                    CASE

                    WHEN _srocode <> 0 THEN  d.srocode=_srocode 

                    ELSE TRUE

                    end

                    )
			
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  o.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
                 

			group by dsm.districtnamee,sm.sronamee,othfee.receiptdate,othfee.partyfirstname,
			othfee.partymiddlename,
			othfee.partylastname,o.applicationnumber,
			othfee.paymentdescription,othfee.bookdetails),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0 OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

 elsif pagenumber <> -1 or  pagesize <> -1 then 
 
 		return query
			with cte as (with a as ( select     
			dsm.districtnamee,
			sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,
			to_char(dm.presentdatetime,'dd-MM-YYYY') presentdate,
			(select 
			string_agg(distinct (coalesce(firstname,' ')||coalesce(middlename,' ')|| 
			coalesce(lastname,' ')::text),',') 
			from kaveri.partyinfo where applicationnumber=dm.applicationnumber  
			and ispresenter is true group by applicationnumber)as presentername ,
			--pi1.presentername,
			sa.articlenamee AS descriptionofdocument, 
			max(pm.sroconsideration) as consideration_fees,
			max(pm.sromarketvalue) as marketvalue,
			pm.propertytypeid ,
			case when dm.finalregistrationnumber is not null
			then dm.finalregistrationnumber else dm.pendingdocumentnumber end documentnumber,
			b.booknameenglish ,
			null  as volumenumber,
			(select sum(amsreg.totalamount)
			from kaveri.ams_reg_epaymenttransdetails amsreg where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false) as Treasury_amount,
			(select to_char(amsreg.inserteddatetime,'dd-MM-yyyy')
			from kaveri.ams_reg_epaymenttransdetails amsreg where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false limit 1)  as Challan_date ,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofcompletion,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofreturn,
			dm.uploaddocdeedpath as copy_of_document

			from  kaveri.documentmaster dm
			join  kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber 
			join kaveri.stamparticles sa on pm.stamparticlecode=sa.stamparticlecode 
			JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
			join kaveri.booktypemaster b on dm.bookid=b.bookid 
			--left join kaveri.ams_reg_epaymenttransdetails amsreg on 
			--amsreg.applicationnumber = dm.applicationnumber and amsreg.isdelete=false 
			where 
			
			(dm.registrationdatetime between _fromdate	and _todate + INTERVAL '1 day'  )
			and 
			
			(

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			and
			
				(

                    CASE

                    WHEN _srocode <> 0 THEN  dm.srocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  dm.finalregistrationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
               and 
			    
			 dm.isregistrationcompleted=true
			 group by dsm.districtnamee,sm.sronamee,dm.finalregistrationnumber,dm.applicationnumber,
			 sa.articlenamee,dm.pendingdocumentnumber,b.booknameenglish,
			 --,booknameenglish,
			dm.registrationdatetime,dm.uploaddocdeedpath,dm.presentdatetime,pm.propertytypeid	)

			select a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) stampduty,
			sum(case when fr.feerulecode=59  then amountpaid else 0 end) cess,
			sum(case when a.propertytypeid=28 and fr.feerulecode=58 then amountpaid else 0 end ) as municipalsurcharge,
			sum(case when a.propertytypeid=17 and fr.feerulecode=58 then amountpaid else 0 end ) as taluksurcharge,
			sum(case when fr.feerulecode in (36,58,59)  then amountpaid else 0 end)  as Total_duty,
			a.documentnumber,a.booknameenglish,a.volumenumber,
			a.dateofcompletion,a.dateofreturn,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end) registrationfees,
			sum(case when fr.feerulecode=41 then amountpaid else 0 end) as feesforcopies,
			sum(case when fr.feerulecode=2 then amountpaid else 0 end) miscelaneousfees,
			sum(case when fr.feerulecode in (34,91)then amountpaid else 0 end) otherstampduty,
			NULL::numeric miscellaneous_article_fees,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=41 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=2 then amountpaid else 0 end)+
			sum(case when fr.feerulecode  in (34,91)then amountpaid else 0 end) Total_fees2,
			a.Treasury_amount,
			a.Challan_date,
			string_agg(distinct (case when fr.feerulecode=6 then r.receiptnumber::text  else ' ' end ),' ')as dailymutationreceipts,
			sum(case when fr.feerulecode=6 then fr.amountpaid else 0 end) mutationfees,
			string_agg(distinct ( case when fr.feerulecode=6 then to_char(r.dateofreceipt,'DD-MM-YYYY')  else ' ' end ),' ')as mutationfeedate,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			a.copy_of_document

			from 
			a
			left join 	kaveri.feesrequired fr on a.applicationnumber=fr.applicationnumber
			left join kaveri.receiptmaster r on fr.receiptid=r.receiptid
			
			group by a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,
			a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			a.documentnumber,a.booknameenglish,
			a.volumenumber,a.Treasury_amount,
			a.Challan_date,a.dateofcompletion,a.dateofreturn,a.copy_of_document,a.propertytypeid
			
			
			
			

			Union all
			
			 
			
			select  
					dsm.districtnamee as districtname,
					sr.sronamee as sroname,
					null as finalregistrationnumber,
					eca.applicationnumber,
					to_char(a.applicationenddate,'dd-MM-YYYY') as  signeddatetime,
					c.firstname||c.middlename||c.lastname  as Presentername,
					'ECSearch' as descriptionofdocument,
					null::numeric  as considerationfees,
					null::numeric  as marketvalue,
					sum(case when er.feeruleid=64  then er.payableamount else 0 end) searchfee,
					sum(case when er.feeruleid=23  then er.payableamount else 0 end) searchapplfee,
					null::numeric as muncipalsurcharge,
					null::numeric  as taluksurcharge,
					 sum(case when er.feeruleid=64  then er.payableamount else 0 end)+
					 sum(case when er.feeruleid=23  then er.payableamount else 0 end)
					 as Total_duty,
					eca.certificatenumber as documentnumber,
					null as bookname,
					null as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofreturn,
					null as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount) as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
					null as dailymutation_receipt,
					null::numeric as mutationfees,
					null as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					eca.signedform22 as copy_of_document
					
					
					  from kaveri.ec_applicationdetails   eca
					  join kaveri.applicantapplicationdetails a on eca.applicationnumber=a.applicationnumber 
					  join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=eca.userid 
					  left join kaveri.ams_reg_epaymenttransdetails amsre on eca.applicationnumber=amsre.applicationnumber 
					  join  kaveri.ec_requiredfees er on eca.ecid=er.ecid 
					 where 
					 
					 (a.applicationenddate between _fromdate	and _todate + INTERVAL '1 day'  ) and 
					 (

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
				 and 
					 
					 (

                    CASE

                    WHEN _srocode <> 0 THEN  eca.kaverisrocode = _srocode

                    ELSE TRUE

                    end

                    )
				 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  eca.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
                and  a.currentstatus='CE110'
					 
					
					group by dsm.districtnamee,sr.sronamee,eca.applicationnumber,eca.signedform22,
					eca.propertydescription,a.applicationenddate,c.firstname,c.middlename,c.lastname,
					eca.certificatenumber,a.applicationenddate
					

			Union All

			select  
					dsm.districtnamee as district,
					sr.sronamee as sroname,
					null as finalregistrationnumber,
					cca.applicationnumber,
					to_char(a.applicationenddate,'dd-MM-YYYY') as  signeddatetime,
					c.firstname||c.middlename||c.lastname  as Presentername,
					'CCSearch' as descriptionofdocument,
					null::numeric as considerationfees,
					null::numeric as marketvalue,
					sum(case when cr.feeruleid=36  then cr.payableamount else 0 end) stampduty,
					sum(case when cr.feeruleid=14  then cr.payableamount else 0 end) searchfee,
				
					null as muncipalsurcharge,
					null as taluksurcharge,
					 sum(case when cr.feeruleid=36  then payableamount else 0 end)+
					 sum(case when cr.feeruleid=14  then payableamount else 0 end)
					 as Total_duty,
					cca.certificatenumber as documentnumber,
					null::text as bookname,
					null::text as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofreturn,
					null::numeric as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount) as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
					null as dailymutation_receipt,
					null::numeric as mutationfees,
					null::text as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					cca.signedform22 as copy_of_document
					
					
					from kaveri.cc_applicationdetails   cca
					  join kaveri.applicantapplicationdetails a on cca.applicationnumber=a.applicationnumber 
					  join kaveri.sromaster sr on cca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=cca.userid  
					  left join kaveri.ams_reg_epaymenttransdetails amsre on cca.applicationnumber=amsre.applicationnumber 
					  join (select ccid,feeruleid,sum(payableamount) as payableamount  from kaveri.cc_requiredfees  
					  group by ccid,feeruleid)cr on cca.ccid=cr.ccid 
					 where 
					 
					 (a.applicationenddate between _fromdate
			 			and _todate + INTERVAL '1 day'  ) and 
					 
					 (

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			 and 
					 
					 (

                    CASE

                    WHEN _srocode <> 0 THEN  cca.kaverisrocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  cca.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
                and  a.currentstatus='CC109'
			
					group by dsm.districtnamee,sr.sronamee,cca.applicationnumber,cca.signedform22,
					a.applicationenddate,c.firstname,c.middlename,c.lastname,
					cca.certificatenumber

			Union All

			select dsm.districtnamee,sm.sronamee,
			o.applicationnumber,
			o.applicationnumber,
			to_char(othfee.receiptdate,'dd-MM-YYYY') presentdate,
			othfee.partyfirstname||' '||othfee.partymiddlename||' '||othfee.partylastname as presentername,
			othfee.paymentdescription as descriptionofdocument,
			null as consideration_fees,
			null as marketvalue,
			sum( case when o.feerulecode=36 then COALESCE (receipttotal,0)  else 0 end) stampduty,
			null::numeric as cess,
			NULL as municipalsurcharge,
			NULL as Taluksurcharge,
			sum(distinct case when o.feerulecode=36 then COALESCE (receipttotal,0)  else 0 end) Total_duty,
			null as documentnumber,
			othfee.bookdetails as bookid,
			null::text as volumenumber,
			to_char(receiptdate,'dd-MM-YYYY') dateofcompletion,
			to_char(receiptdate,'dd-MM-YYYY') as dateofreturn,
			sum( case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end) registrationfees,
			null as feesforcopies,
			sum(distinct  case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) miscelaneousfees,
			null::numeric as otherstampduty,
			null as miscellaneous_article_fees,
			sum( case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end)+
			sum( case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) 
			as total_fees2,
			Null::numeric as Treasury_amount,
			null  as Treasury_transaction_date,
			 null::text as dailymutationreceipts,
			sum(distinct  case when o.feerulecode=6 then COALESCE (receipttotal,0) else 0 end) mutationfees,
			Null as mutationfees_to_treasury_date,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			null::text copy_of_document
			from kaveri.otherfeesrequired o
			join kaveri.otherreceiptdetails othfee  on o.receiptid = othfee.receiptid
			join kaveri.departmentusers d on o.departmentuserid = d.userid
			 join kaveri.sromaster sm on sm.srocode=d.srocode
			 JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode 
			 where 
			 
			 (othfee.receiptdate between _fromdate	and _todate + INTERVAL '1 day'  ) and 
			 
			 (

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode=_districtcode 

                    ELSE TRUE

                    end

                    )
			 and 
			 (

                    CASE

                    WHEN _srocode <> 0 THEN  d.srocode=_srocode 

                    ELSE TRUE

                    end

                    )
			
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  o.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
                 

			group by dsm.districtnamee,sm.sronamee,othfee.receiptdate,othfee.partyfirstname,
			othfee.partymiddlename,
			othfee.partylastname,o.applicationnumber,
			othfee.paymentdescription,othfee.bookdetails),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0 ;
 
 
 
 end if;
		


 

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_register_of_fees_statutory_01122023(bigint, timestamp without time zone, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_01122023(_srocode bigint, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _documentnumber character varying DEFAULT NULL::character varying) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document character varying, considerationamount numeric, marketvalue numeric, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid character varying, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees numeric, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, signature_of_register text, remarks text, copy_of_document text)
    LANGUAGE plpgsql
    AS $$

DECLARE
BEGIN 


		if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
			raise notice 'Documentnumber null';

			return query
			with a as ( select     
			dsm.districtnamee,
			sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,
			to_char(dm.presentdatetime,'dd-MM-YYYY') presentdate,
			(select 
			string_agg(distinct (coalesce(firstname,' ')||coalesce(middlename,' ')|| 
			coalesce(lastname,' ')::text),',') 
			from kaveri.partyinfo where applicationnumber=dm.applicationnumber  
			and ispresenter is true group by applicationnumber)as presentername ,
			--pi1.presentername,
			sa.articlenamee AS descriptionofdocument, 
			max(pm.sroconsideration) as consideration_fees,
			max(pm.sromarketvalue) as marketvalue,
			sum(case when pm.propertytypeid=28 then COALESCE (pm.surcharge,0)  else 0 end) as municipalsurcharge,
			sum(case when pm.propertytypeid=17 then COALESCE (pm.surcharge,0) else 0 end)  as Taluksurcharge,
			case when dm.finalregistrationnumber is not null
			then dm.finalregistrationnumber else dm.pendingdocumentnumber end documentnumber,
			b.booknameenglish ,
			null  as volumenumber,
			sum(amsreg.totalamount)as Treasury_amount,
			string_agg(distinct to_char(amsreg.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofcompletion,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofreturn,
			dm.uploaddocdeedpath as copy_of_document

			from  kaveri.documentmaster dm
			join  kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber 
			join kaveri.stamparticles sa on pm.stamparticlecode=sa.stamparticlecode 
			JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
			join kaveri.booktypemaster b on dm.bookid=b.bookid 
			left join kaveri.ams_reg_epaymenttransdetails amsreg on amsreg.applicationnumber = dm.applicationnumber 
			where 
			--dsm.districtcode=_districtcode and 
			dm.srocode=_srocode and 
			 (dm.registrationdatetime between _fromdate
			 and _todate  ) and
			 dm.isregistrationcompleted is true group by dsm.districtnamee,
			sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,sa.articlenamee,dm.pendingdocumentnumber
			,b.booknameenglish,
			--,booknameenglish,
			dm.registrationdatetime,dm.uploaddocdeedpath,dm.presentdatetime	)

			select a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) stampduty,
			sum(case when fr.feerulecode=59  then amountpaid else 0 end) cess,
			a.municipalsurcharge,a.Taluksurcharge,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) +
			sum(case when fr.feerulecode=59  then amountpaid else 0 end)+
			a.municipalsurcharge+a.Taluksurcharge as Total_duty,
			a.documentnumber,a.booknameenglish,a.volumenumber,
			a.dateofcompletion,a.dateofreturn,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end) registrationfees,
			sum(case when fr.feerulecode=30 then amountpaid else 0 end) as feesforcopies,
			sum(case when fr.feerulecode=2 then amountpaid else 0 end) miscelaneousfees,
			sum(case when fr.feerulecode not in (1,36,59,2)then amountpaid else 0 end) otherstampduty,
			NULL::numeric miscellaneous_article_fees,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=30 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=2 then amountpaid else 0 end)+
			sum(case when fr.feerulecode not in (1,36,59,2)then amountpaid else 0 end) Total_fees2,
			a.Treasury_amount,
			a.Challan_date,
			string_agg(distinct (case when fr.feerulecode=6 then r.receiptnumber::text  else ' ' end ),' ')as dailymutationreceipts,
			sum(case when fr.feerulecode=6 then fr.amountpaid else 0 end) mutationfees,
			string_agg(distinct ( case when fr.feerulecode=6 then to_char(r.dateofreceipt,'DD-MM-YYYY')  else ' ' end ),' ')as mutationfeedate,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			a.copy_of_document

			from 
			a
			left join 	kaveri.feesrequired fr on a.applicationnumber=fr.applicationnumber
			left join kaveri.receiptmaster r on fr.receiptid=r.receiptid
			
			group by a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,
			a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			a.municipalsurcharge,a.Taluksurcharge,a.documentnumber,a.booknameenglish,
			a.volumenumber,a.Treasury_amount,
			a.Challan_date,a.dateofcompletion,a.dateofreturn,a.copy_of_document
			
			
			

			Union all
			
			 
			
			select  
					dsm.districtnamee as districtname,
					sr.sronamee as sroname,
					null as finalregistrationnumber,
					eca.applicationnumber,
					to_char(a.applicationenddate,'dd-MM-YYYY') as  signeddatetime,
					c.firstname||c.middlename||c.lastname  as Presentername,
					'ECSearch' as descriptionofdocument,
					null::numeric  as considerationfees,
					null::numeric  as marketvalue,
					sum(case when er.feeruleid=64  then er.payableamount else 0 end) searchfee,
					sum(case when er.feeruleid=23  then er.payableamount else 0 end) searchapplfee,
					null::numeric as muncipalsurcharge,
					null::numeric  as taluksurcharge,
					 sum(case when er.feeruleid=64  then er.payableamount else 0 end)+
					 sum(case when er.feeruleid=23  then er.payableamount else 0 end)
					 as Total_duty,
					eca.certificatenumber as documentnumber,
					null as bookname,
					null as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofreturn,
					null as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount) as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
					null as dailymutation_receipt,
					null::numeric as mutationfees,
					null as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					eca.signedform22 as copy_of_document
					
					
					  from kaveri.ec_applicationdetails   eca
					  join kaveri.applicantapplicationdetails a on eca.applicationnumber=a.applicationnumber 
					  join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=eca.userid 
					  left join kaveri.ams_reg_epaymenttransdetails amsre on eca.applicationnumber=amsre.applicationnumber 
					  join  kaveri.ec_requiredfees er on eca.ecid=er.ecid 
					 where 
				--dsm.districtcode =_districtcode	and
				eca.kaverisrocode=_srocode and 
					(eca.submitteddatetime  between _fromdate and _todate  ) -- and 
					--eca.signedform22 is not null and length(eca.signedform22 )>0 
					and a.currentstatus='CE110'
					group by dsm.districtnamee,sr.sronamee,eca.applicationnumber,eca.signedform22,
					eca.propertydescription,a.applicationenddate,c.firstname,c.middlename,c.lastname,
					eca.certificatenumber,a.applicationenddate
					

			Union All

			select  
					dsm.districtnamee as district,
					sr.sronamee as sroname,
					null as finalregistrationnumber,
					cca.applicationnumber,
					to_char(a.applicationenddate,'dd-MM-YYYY') as  signeddatetime,
					c.firstname||c.middlename||c.lastname  as Presentername,
					'CCSearch' as descriptionofdocument,
					null::numeric as considerationfees,
					null::numeric as marketvalue,
					sum(case when cr.feeruleid=36  then cr.payableamount else 0 end) stampduty,
					sum(case when cr.feeruleid=14  then cr.payableamount else 0 end) searchfee,
				
					null as muncipalsurcharge,
					null as taluksurcharge,
					 sum(case when cr.feeruleid=36  then payableamount else 0 end)+
					 sum(case when cr.feeruleid=14  then payableamount else 0 end)
					 as Total_duty,
					cca.certificatenumber as documentnumber,
					null::text as bookname,
					null::text as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofreturn,
					null::numeric as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount) as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
					null as dailymutation_receipt,
					null::numeric as mutationfees,
					null::text as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					cca.signedform22 as copy_of_document
					
					
					from kaveri.cc_applicationdetails   cca
					  join kaveri.applicantapplicationdetails a on cca.applicationnumber=a.applicationnumber 
					  join kaveri.sromaster sr on cca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=cca.userid  
					  left join kaveri.ams_reg_epaymenttransdetails amsre on cca.applicationnumber=amsre.applicationnumber 
					  join (select ccid,feeruleid,sum(payableamount) as payableamount  from kaveri.cc_requiredfees  
					  group by ccid,feeruleid)cr on cca.ccid=cr.ccid 
					 where 
			cca.kaverisrocode=_srocode and
			--dsm.districtcode=_districtcode and 
					(cca.submitteddatetime between _fromdate and _todate) 
					--and 
					--cca.signedform22 is not null and length(cca.signedform22 )>0 
					and a.currentstatus='CC109'
					group by dsm.districtnamee,sr.sronamee,cca.applicationnumber,cca.signedform22,
					a.applicationenddate,c.firstname,c.middlename,c.lastname,
					cca.certificatenumber

			Union All

			select dsm.districtnamee,sm.sronamee,
			o.applicationnumber,
			o.applicationnumber,
			to_char(othfee.receiptdate,'dd-MM-YYYY') presentdate,
			othfee.partyfirstname||' '||othfee.partymiddlename||' '||othfee.partylastname as presentername,
			othfee.paymentdescription as descriptionofdocument,
			null as consideration_fees,
			null as marketvalue,
			sum( case when o.feerulecode=36 then COALESCE (receipttotal,0)  else 0 end) stampduty,
			null::numeric as cess,
			NULL as municipalsurcharge,
			NULL as Taluksurcharge,
			sum(distinct case when o.feerulecode=36 then COALESCE (receipttotal,0)  else 0 end) Total_duty,
			null as documentnumber,
			othfee.bookdetails as bookid,
			null::text as volumenumber,
			to_char(receiptdate,'dd-MM-YYYY') dateofcompletion,
			to_char(receiptdate,'dd-MM-YYYY') as dateofreturn,
			sum( case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end) registrationfees,
			null as feesforcopies,
			sum(distinct  case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) miscelaneousfees,
			null::numeric as otherstampduty,
			null as miscellaneous_article_fees,
			sum( case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end)+
			sum( case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) 
			as total_fees2,
			Null::numeric as Treasury_amount,
			null  as Treasury_transaction_date,
			 null::text as dailymutationreceipts,
			sum(distinct  case when o.feerulecode=6 then COALESCE (receipttotal,0) else 0 end) mutationfees,
			Null as mutationfees_to_treasury_date,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			null::text copy_of_document
			from kaveri.otherfeesrequired o
			join kaveri.otherreceiptdetails othfee  on o.receiptid = othfee.receiptid
			join kaveri.departmentusers d on o.departmentuserid = d.userid
			 join kaveri.sromaster sm on sm.srocode=d.srocode
			 JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode 
			 where 
		d.srocode=_srocode and 
		--dsm.districtcode=_districtcode and 
			 (othfee.receiptdate  between _fromdate  and  _todate )  

			group by dsm.districtnamee,sm.sronamee,othfee.receiptdate,othfee.partyfirstname,
			othfee.partymiddlename,
			othfee.partylastname,o.applicationnumber,
			othfee.paymentdescription,othfee.bookdetails;

 
		elseif _documentnumber is not NULL  then

		raise notice 'date null';
		return query
		with a as ( select     
			dsm.districtnamee,
			sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,
			to_char(dm.presentdatetime,'dd-MM-YYYY') presentdate,
			(select 
			string_agg(distinct (coalesce(firstname,' ')||coalesce(middlename,' ')|| 
			coalesce(lastname,' ')::text),',') 
			from kaveri.partyinfo where applicationnumber=dm.applicationnumber  
			and ispresenter is true group by applicationnumber)as presentername ,
			--pi1.presentername,
			sa.articlenamee AS descriptionofdocument, 
			max(pm.sroconsideration) as consideration_fees,
			max(pm.sromarketvalue) as marketvalue,
			sum(case when pm.propertytypeid=28 then COALESCE (pm.surcharge,0)  else 0 end) as municipalsurcharge,
			sum(case when pm.propertytypeid=17 then COALESCE (pm.surcharge,0) else 0 end)  as Taluksurcharge,
			case when dm.finalregistrationnumber is not null
			then dm.finalregistrationnumber else dm.pendingdocumentnumber end documentnumber,
			b.booknameenglish ,
			null  as volumenumber,
			sum(amsreg.totalamount)as Treasury_amount,
			string_agg(distinct to_char(amsreg.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofcompletion,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofreturn,
			dm.uploaddocdeedpath as copy_of_document

			from  kaveri.documentmaster dm
			join  kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber 
			join kaveri.stamparticles sa on pm.stamparticlecode=sa.stamparticlecode 
			JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
			join kaveri.booktypemaster b on dm.bookid=b.bookid 
			left join kaveri.ams_reg_epaymenttransdetails amsreg on amsreg.applicationnumber = dm.applicationnumber 
			where 
			--dsm.districtcode=_districtcode and 
			dm.srocode=_srocode and 
			  dm.finalregistrationnumber=_documentnumber and 
			-- (dm.registrationdatetime between _fromdate
			-- and _todate  ) and
			 dm.isregistrationcompleted is true 
			 group by dsm.districtnamee,
			sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,sa.articlenamee,dm.pendingdocumentnumber
			,b.booknameenglish,
			--,booknameenglish,
			dm.registrationdatetime,dm.uploaddocdeedpath,dm.presentdatetime	)

			select a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) stampduty,
			sum(case when fr.feerulecode=59  then amountpaid else 0 end) cess,
			a.municipalsurcharge,a.Taluksurcharge,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) +
			sum(case when fr.feerulecode=59  then amountpaid else 0 end)+
			a.municipalsurcharge+a.Taluksurcharge as Total_duty,
			a.documentnumber,a.booknameenglish,a.volumenumber,
			a.dateofcompletion,a.dateofreturn,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end) registrationfees,
			sum(case when fr.feerulecode=30 then amountpaid else 0 end) as feesforcopies,
			sum(case when fr.feerulecode=2 then amountpaid else 0 end) miscelaneousfees,
			sum(case when fr.feerulecode not in (1,36,59,2)then amountpaid else 0 end) otherstampduty,
			NULL::numeric miscellaneous_article_fees,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=30 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=2 then amountpaid else 0 end)+
			sum(case when fr.feerulecode not in (1,36,59,2)then amountpaid else 0 end) Total_fees2,
			a.Treasury_amount,
			a.Challan_date,
			string_agg(distinct (case when fr.feerulecode=6 then r.receiptnumber::text  else ' ' end ),' ')as dailymutationreceipts,
			sum(case when fr.feerulecode=6 then fr.amountpaid else 0 end) mutationfees,
			string_agg(distinct ( case when fr.feerulecode=6 then to_char(r.dateofreceipt,'DD-MM-YYYY')  else ' ' end ),' ')as mutationfeedate,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			a.copy_of_document

			from 
			a
			left join 	kaveri.feesrequired fr on a.applicationnumber=fr.applicationnumber
			left join kaveri.receiptmaster r on fr.receiptid=r.receiptid
			
			group by a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,
			a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			a.municipalsurcharge,a.Taluksurcharge,a.documentnumber,a.booknameenglish,
			a.volumenumber,a.Treasury_amount,
			a.Challan_date,a.dateofcompletion,a.dateofreturn,a.copy_of_document
			
			
			

			Union all
			
			 
			
			select  
					dsm.districtnamee as districtname,
					sr.sronamee as sroname,
					null as finalregistrationnumber,
					eca.applicationnumber,
					to_char(a.applicationenddate,'dd-MM-YYYY') as  signeddatetime,
					c.firstname||c.middlename||c.lastname  as Presentername,
					'ECSearch' as descriptionofdocument,
					null::numeric  as considerationfees,
					null::numeric  as marketvalue,
					sum(case when er.feeruleid=64  then er.payableamount else 0 end) searchfee,
					sum(case when er.feeruleid=23  then er.payableamount else 0 end) searchapplfee,
					null::numeric as muncipalsurcharge,
					null::numeric  as taluksurcharge,
					 sum(case when er.feeruleid=64  then er.payableamount else 0 end)+
					 sum(case when er.feeruleid=23  then er.payableamount else 0 end)
					 as Total_duty,
					eca.certificatenumber as documentnumber,
					null as bookname,
					null as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofreturn,
					null as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount) as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
					null as dailymutation_receipt,
					null::numeric as mutationfees,
					null as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					eca.signedform22 as copy_of_document
					
					
					  from kaveri.ec_applicationdetails   eca
					  join kaveri.applicantapplicationdetails a on eca.applicationnumber=a.applicationnumber 
					  join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=eca.userid 
					  left join kaveri.ams_reg_epaymenttransdetails amsre on eca.applicationnumber=amsre.applicationnumber 
					  join  kaveri.ec_requiredfees er on eca.ecid=er.ecid 
					 where 
				--dsm.districtcode =_districtcode	and
				eca.kaverisrocode=_srocode and 
					eca.applicationnumber=_documentnumber and 
					--(eca.submitteddatetime  between _fromdate and _todate  ) -- and 
					--eca.signedform22 is not null and length(eca.signedform22 )>0 
					a.currentstatus='CE110'
					group by dsm.districtnamee,sr.sronamee,eca.applicationnumber,eca.signedform22,
					eca.propertydescription,a.applicationenddate,c.firstname,c.middlename,c.lastname,
					eca.certificatenumber,a.applicationenddate
					

			Union All

			select  
					dsm.districtnamee as district,
					sr.sronamee as sroname,
					null as finalregistrationnumber,
					cca.applicationnumber,
					to_char(a.applicationenddate,'dd-MM-YYYY') as  signeddatetime,
					c.firstname||c.middlename||c.lastname  as Presentername,
					'CCSearch' as descriptionofdocument,
					null::numeric as considerationfees,
					null::numeric as marketvalue,
					sum(case when cr.feeruleid=36  then cr.payableamount else 0 end) stampduty,
					sum(case when cr.feeruleid=14  then cr.payableamount else 0 end) searchfee,
				
					null as muncipalsurcharge,
					null as taluksurcharge,
					 sum(case when cr.feeruleid=36  then payableamount else 0 end)+
					 sum(case when cr.feeruleid=14  then payableamount else 0 end)
					 as Total_duty,
					cca.certificatenumber as documentnumber,
					null::text as bookname,
					null::text as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofreturn,
					null::numeric as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount) as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
					null as dailymutation_receipt,
					null::numeric as mutationfees,
					null::text as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					cca.signedform22 as copy_of_document
					
					
					from kaveri.cc_applicationdetails   cca
					  join kaveri.applicantapplicationdetails a on cca.applicationnumber=a.applicationnumber 
					  join kaveri.sromaster sr on cca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=cca.userid  
					  left join kaveri.ams_reg_epaymenttransdetails amsre on cca.applicationnumber=amsre.applicationnumber 
					  join (select ccid,feeruleid,sum(payableamount) as payableamount  from kaveri.cc_requiredfees  
					  group by ccid,feeruleid)cr on cca.ccid=cr.ccid 
					 where 
					 cca.applicationnumber=_documentnumber and 
			cca.kaverisrocode=_srocode and
			--dsm.districtcode=_districtcode and 
					--(cca.submitteddatetime between _fromdate and _todate) 
					--and 
					--cca.signedform22 is not null and length(cca.signedform22 )>0 
					 a.currentstatus='CC109'
					group by dsm.districtnamee,sr.sronamee,cca.applicationnumber,cca.signedform22,
					a.applicationenddate,c.firstname,c.middlename,c.lastname,
					cca.certificatenumber

			Union All

			select dsm.districtnamee,sm.sronamee,
			o.applicationnumber,
			o.applicationnumber,
			to_char(othfee.receiptdate,'dd-MM-YYYY') presentdate,
			othfee.partyfirstname||' '||othfee.partymiddlename||' '||othfee.partylastname as presentername,
			othfee.paymentdescription as descriptionofdocument,
			null as consideration_fees,
			null as marketvalue,
			sum( case when o.feerulecode=36 then COALESCE (receipttotal,0)  else 0 end) stampduty,
			null::numeric as cess,
			NULL as municipalsurcharge,
			NULL as Taluksurcharge,
			sum(distinct case when o.feerulecode=36 then COALESCE (receipttotal,0)  else 0 end) Total_duty,
			null as documentnumber,
			othfee.bookdetails as bookid,
			null::text as volumenumber,
			to_char(receiptdate,'dd-MM-YYYY') dateofcompletion,
			to_char(receiptdate,'dd-MM-YYYY') as dateofreturn,
			sum( case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end) registrationfees,
			null as feesforcopies,
			sum(distinct  case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) miscelaneousfees,
			null::numeric as otherstampduty,
			null as miscellaneous_article_fees,
			sum( case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end)+
			sum( case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) 
			as total_fees2,
			Null::numeric as Treasury_amount,
			null  as Treasury_transaction_date,
			 null::text as dailymutationreceipts,
			sum(distinct  case when o.feerulecode=6 then COALESCE (receipttotal,0) else 0 end) mutationfees,
			Null as mutationfees_to_treasury_date,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			null::text copy_of_document
			from kaveri.otherfeesrequired o
			join kaveri.otherreceiptdetails othfee  on o.receiptid = othfee.receiptid
			join kaveri.departmentusers d on o.departmentuserid = d.userid
			 join kaveri.sromaster sm on sm.srocode=d.srocode
			 JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode 
			 where 
			 o.applicationnumber=_documentnumber and 
			d.srocode=_srocode and 
			--dsm.districtcode=_districtcode 
			(othfee.receiptdate  between _fromdate  and  _todate )  

			group by dsm.districtnamee,sm.sronamee,othfee.receiptdate,othfee.partyfirstname,
			othfee.partymiddlename,
			othfee.partylastname,o.applicationnumber,
			othfee.paymentdescription,othfee.bookdetails;

 
 		else

		raise notice 'condition failed';
		end if;

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_01122023(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_mis_daily_register_of_fees_statutory_backup_300323(bigint, timestamp without time zone, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_backup_300323(_srocode bigint, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _documentnumber character varying DEFAULT NULL::character varying) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber character varying, presentationdatetime text, presenter_name text, description_of_document character varying, considerationamount numeric, marketvalue numeric, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid character varying, volumenumber character varying, dateofcompletion text, dateofreturn text, registrationfees numeric, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, signature_of_register text, remarks text, copy_of_document text)
    LANGUAGE plpgsql
    AS $$

DECLARE
BEGIN 

if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
raise notice 'Documentnumber null';

return query
select  distinct 
dsm.districtnamee,
sm.sronamee,
dm.finalregistrationnumber,
dm.applicationnumber,
to_char(dm.presentdatetime,'dd-MM-YYYY') presentdate,
string_agg(distinct vfp.name,',') as presentername,
sa.articlenamee AS descriptionofdocument,  --natureofdocument
sum(distinct COALESCE (pm.sroconsideration,0) ) as consideration_fees,
sum(distinct COALESCE (pm.sromarketvalue,0)) as marketvalue,
sum(distinct case when fr.feerulecode=36  then amountpaid else 0 end) stampduty,
sum(distinct case when fr.feerulecode=59  then amountpaid else 0 end) cess,
sum(distinct  case when pm.propertytypeid=28 then COALESCE (pm.surcharge,0)  else 0 end) municipalsurcharge,
sum(distinct case when pm.propertytypeid=17 then COALESCE (pm.surcharge,0) else 0 end) Taluksurcharge,
sum(distinct  case when fr.feerulecode=36 then amountpaid else 0 end)+ 
sum(distinct case when fr.feerulecode=59  then amountpaid else 0 end)+
sum(distinct case when pm.propertytypeid=28 
then  COALESCE (pm.surcharge,0) else 0 end)+
sum(distinct  case when pm.propertytypeid=17 then  COALESCE (pm.surcharge,0) else 0 end)  Total_duty,
case when dm.finalregistrationnumber is not null
then dm.finalregistrationnumber else dm.pendingdocumentnumber end documentnumber,
b.booknameenglish ,
d.volumename  as volumenumber,
to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofcompletion,
to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofreturn,
sum(distinct  case when fr.feerulecode=1 then amountpaid else 0 end) registrationfees,
sum(distinct case when cca.applicationnumber is not null then 
	cca.totalamount else 	(case when fr.feerulecode=30 then amountpaid else 0 end) end) as feesforcopies,
sum(distinct  case when fr.feerulecode=2 then amountpaid else 0 end) miscelaneousfees,
sum(distinct  case when fr.feerulecode not in (1,36,59,2)then amountpaid else 0 end) otherstampduty,
NULL::numeric miscellaneous_article_fees,
sum(distinct case when fr.feerulecode=1 then amountpaid else 0 end)+
sum(distinct case when cca.applicationnumber is not null then 
	cca.totalamount else 
	(case when fr.feerulecode=30 then amountpaid else 0 end) end)+
sum(distinct  case when fr.feerulecode=2 then amountpaid else 0 end)+
sum(distinct  case when fr.feerulecode not in (1,36,59,2)then amountpaid else 0 end) Total_fees2,
(case when form7.dailyregtreasamt is not null then form7.dailyregtreasamt else 
sum(distinct  amsreg.totalamount) end) as Treasury_amount,
string_agg( distinct to_char(amsreg.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
string_agg(distinct (case when fr.feerulecode=6 then r.receiptnumber::text  else ' ' end ),' ')as dailymutationreceipts,
sum(distinct  case when fr.feerulecode=6 then fr.amountpaid else 0 end) mutationfees,
string_agg(distinct (case when fr.feerulecode=6 then to_char(r.dateofreceipt,'DD-MM-YYYY')  else ' ' end ),' ')as mutationfeedate,
NULL::text transmission_of_memorandum,
NULL::text transmission_of_memoranda,
NULL::text signature_of_register,
NULL::text remarks,
dm.uploaddocdeedpath as copy_of_document
from  kaveri.documentmaster dm
join kaveri.vw_fetch_party vfp on vfp.applicationnumber = dm.applicationnumber and vfp.ispresenter is true
and dm.isregistrationcompleted is true
join kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber and pm.srocode=dm.srocode
left outer join kaveri.propertyschedules ps on pm.propertyid=ps.propertyid
JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
join kaveri.stamparticles sa on pm.stamparticlecode=sa.stamparticlecode 
join kaveri.feesrequired fr ON dm.applicationnumber =fr.applicationnumber and fr.srocode=dm.srocode 
join kaveri.applicantapplicationdetails aad	on aad.applicationnumber=dm.applicationnumber  and aad.srocode=dm.srocode
join kaveri.ams_reg_epaymenttransdetails amsreg on amsreg.applicationnumber = aad.applicationnumber 
left join kaveri.cc_applicationdetails cca on dm.applicationnumber=cca.applicationnumber 
left outer join kaverimis.formno7 form7 on dm.applicationnumber = form7.documentnumber
join kaveri.booktypemaster b on dm.bookid=b.bookid 
left join kaveri.receiptmaster r on fr.receiptid=r.receiptid
left join kaveri.dailyreceiptfees d on r.receiptid=d.receiptid 
where 
--aad.currentstatus in ('CD120','CD134','CD109') and -- Pls refer above
aad.currentstatus not in ('CD134','CD133','CD119') and 
vfp.ispresenter is true and vfp.name is not null
and dm.srocode=_srocode and  dm.presentdatetime::date >= _fromdate  and dm.presentdatetime::date<=_todate
group by dsm.districtnamee,sm.sronamee,dm.presentdatetime,sa.articlenamee,amsreg.transactiondatetime,
dm.finalregistrationnumber,dm.pendingdocumentnumber,
dm.bookid,dm.stamp5datetime,dm.withdrawaldate,dm.applicationnumber,dm.ackdatetime,dailyregmutfee,
dailyregmutfeedate,form7.dailyregtreasamt,form7.dailyregtreasdate,dm.registrationdatetime,
dm.uploaddocdeedpath,b.booknameenglish,d.volumename

union All

select  distinct 
dsm.districtnamee,
sm.sronamee,
dm.finalregistrationnumber,
dm.applicationnumber,
to_char(dm.presentdatetime,'dd-MM-YYYY') presentdate,
string_agg(distinct vfp.name,',') as presentername,
sa.articlenamee AS descriptionofdocument,  --natureofdocument
null::numeric as consideration_fees,
null::numeric  as marketvalue,
null::numeric  as  stampduty,
null::numeric  as  cess,
null::numeric  as  municipalsurcharge,
null::numeric  as  Taluksurcharge,
null::numeric  as  Total_duty,
case when dm.finalregistrationnumber is not null
then dm.finalregistrationnumber else dm.pendingdocumentnumber end documentnumber,
b.booknameenglish ,
d.volumename  as volumenumber,
to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofcompletion,
to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofreturn,
sum(distinct  case when fr.feerulecode=1 then amountpaid else 0 end) registrationfees,
sum(distinct case when cca.applicationnumber is not null then 
	cca.totalamount else 	(case when fr.feerulecode=30 then amountpaid else 0 end) end) as feesforcopies,
sum(distinct  case when fr.feerulecode=2 then amountpaid else 0 end) miscelaneousfees,
sum(distinct  case when fr.feerulecode not in (1,36,59,2)then amountpaid else 0 end) otherstampduty,
NULL::numeric miscellaneous_article_fees,
sum(distinct case when fr.feerulecode=1 then amountpaid else 0 end)+
sum(distinct case when cca.applicationnumber is not null then 
	cca.totalamount else 
	(case when fr.feerulecode=30 then amountpaid else 0 end) end)+
sum(distinct  case when fr.feerulecode=2 then amountpaid else 0 end)+
sum(distinct  case when fr.feerulecode not in (1,36,59,2)then amountpaid else 0 end) Total_fees2,
(case when form7.dailyregtreasamt is not null then form7.dailyregtreasamt else 
sum(distinct  amsreg.totalamount) end) as Treasury_amount,
string_agg( distinct to_char(amsreg.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
string_agg(distinct (case when fr.feerulecode=6 then r.receiptnumber::text  else ' ' end ),' ')as dailymutationreceipts,
sum(distinct  case when fr.feerulecode=6 then fr.amountpaid else 0 end) mutationfees,
string_agg(distinct (case when fr.feerulecode=6 then to_char(r.dateofreceipt,'DD-MM-YYYY')  else ' ' end ),' ')as mutationfeedate,
NULL::text transmission_of_memorandum,
NULL::text transmission_of_memoranda,
NULL::text signature_of_register,
NULL::text remarks,
dm.uploaddocdeedpath as copy_of_document
from  kaveri.documentmaster dm
join kaveri.vw_fetch_party vfp on vfp.applicationnumber = dm.applicationnumber and vfp.ispresenter is true
and dm.isregistrationcompleted is true
join kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber and pm.srocode=dm.srocode
left outer join kaveri.propertyschedules ps on pm.propertyid=ps.propertyid
JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
join kaveri.stamparticles sa on pm.stamparticlecode=sa.stamparticlecode 
join kaveri.feesrequired fr ON dm.applicationnumber =fr.applicationnumber and fr.srocode=dm.srocode 
join kaveri.applicantapplicationdetails aad	on aad.applicationnumber=dm.applicationnumber  and aad.srocode=dm.srocode
join kaveri.ams_reg_epaymenttransdetails amsreg on amsreg.applicationnumber = aad.applicationnumber 
left join kaveri.cc_applicationdetails cca on dm.applicationnumber=cca.applicationnumber 
left outer join kaverimis.formno7 form7 on dm.applicationnumber = form7.documentnumber
join kaveri.booktypemaster b on dm.bookid=b.bookid 
left join kaveri.receiptmaster r on fr.receiptid=r.receiptid
left join kaveri.dailyreceiptfees d on r.receiptid=d.receiptid 
where 
--aad.currentstatus in ('CD120','CD134','CD109') and -- Pls refer above
aad.currentstatus in ('CD134','CD133','CD119') and 
vfp.ispresenter is true and vfp.name is not null
and dm.srocode=_srocode and  dm.presentdatetime::date >= _fromdate and dm.presentdatetime::date<=_todate  
group by dsm.districtnamee,sm.sronamee,dm.presentdatetime,sa.articlenamee,amsreg.transactiondatetime,
dm.finalregistrationnumber,dm.pendingdocumentnumber,
dm.bookid,dm.stamp5datetime,dm.withdrawaldate,dm.applicationnumber,dm.ackdatetime,dailyregmutfee,
dailyregmutfeedate,form7.dailyregtreasamt,form7.dailyregtreasdate,dm.registrationdatetime,
dm.uploaddocdeedpath,b.booknameenglish,d.volumename 

union all 

select dsm.districtnamee,sm.sronamee,
o.applicationnumber,
o.applicationnumber,
to_char(othfee.receiptdate,'dd-MM-YYYY') presentdate,
othfee.partyfirstname||' '||othfee.partymiddlename||' '||othfee.partylastname as presentername,
othfee.paymentdescription as descriptionofdocument,
null as consideration_fees,
null as marketvalue,
sum(distinct case when o.feerulecode=36 then COALESCE (receipttotal,0)  else 0 end) stampduty,
null::numeric as cess,
NULL as municipalsurcharge,
NULL as Taluksurcharge,
sum(distinct case when o.feerulecode=36 then COALESCE (receipttotal,0)  else 0 end) Total_duty,
null as documentnumber,
othfee.bookdetails as bookid,
null::text as volumenumber,
to_char(receiptdate,'dd-MM-YYYY') dateofcompletion,
to_char(receiptdate,'dd-MM-YYYY') as dateofreturn,
sum(distinct  case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end) registrationfees,
null as feesforcopies,
sum(distinct  case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) miscelaneousfees,
null::numeric as otherstampduty,
null as miscellaneous_article_fees,
sum(distinct  case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end)+
sum(distinct  case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) 
as total_fees2,
dailyregtreasamt::numeric as Treasury_amount,
to_char(dailyregtreasdate,'dd-mm-yyyy')
 as Treasury_transaction_date,
 null::text as dailymutationreceipts,
sum(distinct  case when o.feerulecode=6 then COALESCE (receipttotal,0) else 0 end) mutationfees,
to_char(dailyregmutfeedate,'dd-mm-yyyy') as mutationfees_to_treasury_date,
NULL::text transmission_of_memorandum,
