join kaveri.vw_fetch_party vfp on vfp.applicationnumber = dm.applicationnumber and vfp.ispresenter is true and
dm.finalregistrationnumber=_documentnumber 
and dm.isregistrationcompleted is true
join kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber and pm.srocode=dm.srocode
left outer join kaveri.propertyschedules ps on pm.propertyid=ps.propertyid
JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
