null::text as volumenumber,
to_char(receiptdate,'dd-MM-YYYY') dateofcompletion,
to_char(receiptdate,'dd-MM-YYYY') as dateofreturn,
sum(distinct  case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end) registrationfees,
null as feesforcopies,
sum(distinct  case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) miscelaneousfees,
null::numeric as otherstampduty,
null as miscellaneous_article_fees,
sum(distinct  case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end)+
sum(distinct  case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) 
as total_fees2,
dailyregtreasamt::numeric as Treasury_amount,
to_char(dailyregtreasdate,'dd-mm-yyyy')
 as Treasury_transaction_date,
 null::text as dailymutationreceipts,
sum(distinct  case when o.feerulecode=6 then COALESCE (receipttotal,0) else 0 end) mutationfees,
to_char(dailyregmutfeedate,'dd-mm-yyyy') as mutationfees_to_treasury_date,
NULL::text transmission_of_memorandum,
NULL::text transmission_of_memoranda,
NULL::text signature_of_register,
NULL::text remarks,
null::text copy_of_document
from kaveri.otherfeesrequired o
