left join  kaverimis.formno7 on formno7.documentnumber=o.applicationnumber
join kaveri.departmentusers d on o.departmentuserid = d.userid
 join kaveri.sromaster sm on sm.srocode=d.srocode
 JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode 
 where   d.srocode=_srocode and  o.applicationnumber=_documentnumber and
 othfee.receiptdate >=_fromdate and  othfee.receiptdate::date <=_todate   and length(o.applicationnumber)>0

group by dsm.districtnamee,sm.sronamee,othfee.receiptdate,othfee.partyfirstname,
othfee.partymiddlename,
othfee.partylastname,o.applicationnumber,dailyregtreasamt,
dailyregtreasdate,dailyregmutfee,dailyregmutfeedate,othfee.paymentdescription,othfee.bookdetails;

 
 
 else

