$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_backup_300323(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_mis_daily_register_of_fees_statutory_bck_18122023(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_bck_18122023(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _documentnumber character varying DEFAULT NULL::character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document character varying, considerationamount numeric, marketvalue numeric, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid character varying, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees numeric, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if pagenumber <> -1 and pagesize <> -1 then 

			return query
			with cte as (with a as ( select     
			dsm.districtnamee,
			sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,
			to_char(dm.presentdatetime,'dd-MM-YYYY') presentdate,
			(select 
			string_agg(distinct (coalesce(firstname,' ')||coalesce(middlename,' ')|| 
			coalesce(lastname,' ')::text),',') 
			from kaveri.partyinfo where applicationnumber=dm.applicationnumber  
			and ispresenter is true group by applicationnumber)as presentername ,
			--pi1.presentername,
			sa.articlenamee AS descriptionofdocument, 
			max(pm.sroconsideration) as consideration_fees,
			max(pm.sromarketvalue) as marketvalue,
			pm.propertytypeid ,
			case when dm.finalregistrationnumber is not null
			then dm.finalregistrationnumber else dm.pendingdocumentnumber end documentnumber,
			b.booknameenglish ,
			null  as volumenumber,
			(select sum(amsreg.totalamount)
			from kaveri.ams_reg_epaymenttransdetails amsreg where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false) as Treasury_amount,
			(select to_char(amsreg.inserteddatetime,'dd-MM-yyyy')
			from kaveri.ams_reg_epaymenttransdetails amsreg where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false limit 1)  as Challan_date ,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofcompletion,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofreturn,
			dm.uploaddocdeedpath as copy_of_document

			from  kaveri.documentmaster dm
			join  kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber 
			join kaveri.stamparticles sa on pm.stamparticlecode=sa.stamparticlecode 
			JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
			join kaveri.booktypemaster b on dm.bookid=b.bookid 
			--left join kaveri.ams_reg_epaymenttransdetails amsreg on 
			--amsreg.applicationnumber = dm.applicationnumber and amsreg.isdelete=false  
			where 
			
			(dm.registrationdatetime between _fromdate	and _todate + INTERVAL '1 day'  )
			and 
			
			(

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			and
			
				(

                    CASE

                    WHEN _srocode <> 0 THEN  dm.srocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  dm.finalregistrationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
               and 
			    
			 dm.isregistrationcompleted=true
			 group by dsm.districtnamee,sm.sronamee,dm.finalregistrationnumber,dm.applicationnumber,
			 sa.articlenamee,dm.pendingdocumentnumber,b.booknameenglish,
			 --,booknameenglish,
			dm.registrationdatetime,dm.uploaddocdeedpath,dm.presentdatetime,pm.propertytypeid	)

			select a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) stampduty,
			sum(case when fr.feerulecode=59  then amountpaid else 0 end) cess,
			sum(case when a.propertytypeid=28 and fr.feerulecode=58 then amountpaid else 0 end ) as municipalsurcharge,
			sum(case when a.propertytypeid=17 and fr.feerulecode=58 then amountpaid else 0 end ) as taluksurcharge,
			sum(case when fr.feerulecode in (36,58,59)  then amountpaid else 0 end)  as Total_duty,
			a.documentnumber,a.booknameenglish,a.volumenumber,
			a.dateofcompletion,a.dateofreturn,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end) registrationfees,
			sum(case when fr.feerulecode=41 then amountpaid else 0 end) as feesforcopies,
			sum(case when fr.feerulecode=2 then amountpaid else 0 end) miscelaneousfees,
			sum(case when fr.feerulecode in (34,91)then amountpaid else 0 end) otherstampduty,
			NULL::numeric miscellaneous_article_fees,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=41 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=2 then amountpaid else 0 end)+
			sum(case when fr.feerulecode  in (34,91)then amountpaid else 0 end) Total_fees2,
			a.Treasury_amount,
			a.Challan_date,
			string_agg(distinct (case when fr.feerulecode=6 then r.receiptnumber::text  else ' ' end ),' ')as dailymutationreceipts,
			sum(case when fr.feerulecode=6 then fr.amountpaid else 0 end) mutationfees,
			string_agg(distinct ( case when fr.feerulecode=6 then to_char(r.dateofreceipt,'DD-MM-YYYY')  else ' ' end ),' ')as mutationfeedate,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			a.copy_of_document

			from 
			a
			left join 	kaveri.feesrequired fr on a.applicationnumber=fr.applicationnumber
			left join kaveri.receiptmaster r on fr.receiptid=r.receiptid
			
			group by a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,
			a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			a.documentnumber,a.booknameenglish,
			a.volumenumber,a.Treasury_amount,
			a.Challan_date,a.dateofcompletion,a.dateofreturn,a.copy_of_document,a.propertytypeid
			
			
			
			

			Union all
			
			 
			
			select  
					dsm.districtnamee as districtname,
					sr.sronamee as sroname,
					null as finalregistrationnumber,
					eca.applicationnumber,
					to_char(a.applicationenddate,'dd-MM-YYYY') as  signeddatetime,
					c.firstname||c.middlename||c.lastname  as Presentername,
					'ECSearch' as descriptionofdocument,
					null::numeric  as considerationfees,
					null::numeric  as marketvalue,
					sum(case when er.feeruleid=64  then er.payableamount else 0 end) searchfee,
					sum(case when er.feeruleid=23  then er.payableamount else 0 end) searchapplfee,
					null::numeric as muncipalsurcharge,
					null::numeric  as taluksurcharge,
					 sum(case when er.feeruleid=64  then er.payableamount else 0 end)+
					 sum(case when er.feeruleid=23  then er.payableamount else 0 end)
					 as Total_duty,
					eca.certificatenumber as documentnumber,
					null as bookname,
					null as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofreturn,
					null as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount) as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
					null as dailymutation_receipt,
					null::numeric as mutationfees,
					null as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					eca.signedform22 as copy_of_document
					
					
					  from kaveri.ec_applicationdetails   eca
					  join kaveri.applicantapplicationdetails a on eca.applicationnumber=a.applicationnumber 
					  join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=eca.userid 
					  left join kaveri.ams_reg_epaymenttransdetails amsre on eca.applicationnumber=amsre.applicationnumber 
					  join  kaveri.ec_requiredfees er on eca.ecid=er.ecid 
