-- Name: fn_mis_daily_register_of_fees_statutory_bck_18122023_new(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_bck_18122023_new(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document character varying, considerationamount numeric, marketvalue numeric, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid character varying, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees numeric, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if pagenumber <> -1 and pagesize <> -1 then 

			return query
			with cte as (with a as ( select     
			dsm.districtnamee,
			sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,
			to_char(dm.presentdatetime,'dd-MM-YYYY') presentdate,
			(select 
			string_agg(distinct (coalesce(firstname,' ')||coalesce(middlename,' ')|| 
			coalesce(lastname,' ')::text),',') 
			from kaveri.partyinfo where applicationnumber=dm.applicationnumber  
			and ispresenter is true group by applicationnumber)as presentername ,
			--pi1.presentername,
			sa.articlenamee AS descriptionofdocument, 
			max(pm.sroconsideration) as consideration_fees,
			max(pm.sromarketvalue) as marketvalue,
			pm.propertytypeid ,
			case when dm.finalregistrationnumber is not null
			then dm.finalregistrationnumber else dm.pendingdocumentnumber end documentnumber,
			b.booknameenglish ,
			null  as volumenumber,
			(select sum(amsreg.totalamount)
			from kaveri.ams_reg_epaymenttransdetails amsreg where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false) as Treasury_amount,
			(select to_char(amsreg.inserteddatetime,'dd-MM-yyyy')
			from kaveri.ams_reg_epaymenttransdetails amsreg where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false limit 1)  as Challan_date ,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofcompletion,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofreturn,
			dm.uploaddocdeedpath as copy_of_document

			from  kaveri.documentmaster dm
			join  kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber 
			join kaveri.stamparticles sa on pm.stamparticlecode=sa.stamparticlecode 
			JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
			join kaveri.booktypemaster b on dm.bookid=b.bookid 
			--left join kaveri.ams_reg_epaymenttransdetails amsreg on 
			--amsreg.applicationnumber = dm.applicationnumber and amsreg.isdelete=false  
			where 
			
			(dm.registrationdatetime between _fromdate	and _todate + INTERVAL '1 day'  )
			and 
			
			(

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			and
			
				(

                    CASE

                    WHEN _srocode <> 0 THEN  dm.srocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  dm.finalregistrationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
               and 
			    
			 dm.isregistrationcompleted=true
			 group by dsm.districtnamee,sm.sronamee,dm.finalregistrationnumber,dm.applicationnumber,
			 sa.articlenamee,dm.pendingdocumentnumber,b.booknameenglish,
			 --,booknameenglish,
			dm.registrationdatetime,dm.uploaddocdeedpath,dm.presentdatetime,pm.propertytypeid	)

			select a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) stampduty,
			sum(case when fr.feerulecode=59  then amountpaid else 0 end) cess,
			sum(case when a.propertytypeid=28 and fr.feerulecode=58 then amountpaid else 0 end ) as municipalsurcharge,
			sum(case when a.propertytypeid=17 and fr.feerulecode=58 then amountpaid else 0 end ) as taluksurcharge,
			sum(case when fr.feerulecode in (36,58,59)  then amountpaid else 0 end)  as Total_duty,
			a.documentnumber,a.booknameenglish,a.volumenumber,
			a.dateofcompletion,a.dateofreturn,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end) registrationfees,
			sum(case when fr.feerulecode=41 then amountpaid else 0 end) as feesforcopies,
			sum(case when fr.feerulecode=2 then amountpaid else 0 end) miscelaneousfees,
			sum(case when fr.feerulecode in (34,91)then amountpaid else 0 end) otherstampduty,
			NULL::numeric miscellaneous_article_fees,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=41 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=2 then amountpaid else 0 end)+
			sum(case when fr.feerulecode  in (34,91)then amountpaid else 0 end) Total_fees2,
			a.Treasury_amount,
			a.Challan_date,
			string_agg(distinct (case when fr.feerulecode=6 then r.receiptnumber::text  else ' ' end ),' ')as dailymutationreceipts,
			sum(case when fr.feerulecode=6 then fr.amountpaid else 0 end) mutationfees,
			string_agg(distinct ( case when fr.feerulecode=6 then to_char(r.dateofreceipt,'DD-MM-YYYY')  else ' ' end ),' ')as mutationfeedate,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			a.copy_of_document

			from 
			a
			left join 	kaveri.feesrequired fr on a.applicationnumber=fr.applicationnumber
			left join kaveri.receiptmaster r on fr.receiptid=r.receiptid
			
			group by a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,
			a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			a.documentnumber,a.booknameenglish,
			a.volumenumber,a.Treasury_amount,
			a.Challan_date,a.dateofcompletion,a.dateofreturn,a.copy_of_document,a.propertytypeid
			
			
			
			

			Union all
			
			 
			
			select  
					dsm.districtnamee as districtname,
					sr.sronamee as sroname,
					null as finalregistrationnumber,
					eca.applicationnumber,
					to_char(a.applicationenddate,'dd-MM-YYYY') as  signeddatetime,
					c.firstname||c.middlename||c.lastname  as Presentername,
					'ECSearch' as descriptionofdocument,
					null::numeric  as considerationfees,
					null::numeric  as marketvalue,
					sum(case when er.feeruleid=64  then er.payableamount else 0 end) searchfee,
					sum(case when er.feeruleid=23  then er.payableamount else 0 end) searchapplfee,
					null::numeric as muncipalsurcharge,
					null::numeric  as taluksurcharge,
					 sum(case when er.feeruleid=64  then er.payableamount else 0 end)+
					 sum(case when er.feeruleid=23  then er.payableamount else 0 end)
					 as Total_duty,
					eca.certificatenumber as documentnumber,
					null as bookname,
					null as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofreturn,
					null as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount) as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
					null as dailymutation_receipt,
					null::numeric as mutationfees,
					null as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					eca.signedform22 as copy_of_document
					
					
					  from kaveri.ec_applicationdetails   eca
					  join kaveri.applicantapplicationdetails a on eca.applicationnumber=a.applicationnumber 
					  join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=eca.userid 
					  left join kaveri.ams_reg_epaymenttransdetails amsre on eca.applicationnumber=amsre.applicationnumber 
					  join  kaveri.ec_requiredfees er on eca.ecid=er.ecid 
					 where 
					 
					 (a.applicationenddate between _fromdate	and _todate + INTERVAL '1 day'  ) and 
					 (

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
				 and 
					 
					 (

                    CASE

                    WHEN _srocode <> 0 THEN  eca.kaverisrocode = _srocode

                    ELSE TRUE

                    end

                    )
				 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  eca.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
                and  a.currentstatus='CE110'
					 
					
					group by dsm.districtnamee,sr.sronamee,eca.applicationnumber,eca.signedform22,
					eca.propertydescription,a.applicationenddate,c.firstname,c.middlename,c.lastname,
					eca.certificatenumber,a.applicationenddate
					

			Union All

			select  
					dsm.districtnamee as district,
					sr.sronamee as sroname,
					null as finalregistrationnumber,
					cca.applicationnumber,
					to_char(a.applicationenddate,'dd-MM-YYYY') as  signeddatetime,
					c.firstname||c.middlename||c.lastname  as Presentername,
					'CCSearch' as descriptionofdocument,
					null::numeric as considerationfees,
					null::numeric as marketvalue,
					sum(case when cr.feeruleid=36  then cr.payableamount else 0 end) stampduty,
					sum(case when cr.feeruleid=14  then cr.payableamount else 0 end) searchfee,
				
					null as muncipalsurcharge,
					null as taluksurcharge,
					 sum(case when cr.feeruleid=36  then payableamount else 0 end)+
					 sum(case when cr.feeruleid=14  then payableamount else 0 end)
					 as Total_duty,
					cca.certificatenumber as documentnumber,
					null::text as bookname,
					null::text as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofreturn,
					null::numeric as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount) as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
					null as dailymutation_receipt,
					null::numeric as mutationfees,
					null::text as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					cca.signedform22 as copy_of_document
					
					
					from kaveri.cc_applicationdetails   cca
					  join kaveri.applicantapplicationdetails a on cca.applicationnumber=a.applicationnumber 
					  join kaveri.sromaster sr on cca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=cca.userid  
					  left join kaveri.ams_reg_epaymenttransdetails amsre on cca.applicationnumber=amsre.applicationnumber 
					  join (select ccid,feeruleid,sum(payableamount) as payableamount  from kaveri.cc_requiredfees  
					  group by ccid,feeruleid)cr on cca.ccid=cr.ccid 
					 where 
					 
					 (a.applicationenddate between _fromdate
			 			and _todate + INTERVAL '1 day'  ) and 
					 
					 (

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			 and 
					 
					 (

                    CASE

                    WHEN _srocode <> 0 THEN  cca.kaverisrocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  cca.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
                and  a.currentstatus='CC109'
			
					group by dsm.districtnamee,sr.sronamee,cca.applicationnumber,cca.signedform22,
					a.applicationenddate,c.firstname,c.middlename,c.lastname,
					cca.certificatenumber

			Union All

			select dsm.districtnamee,sm.sronamee,
			o.applicationnumber,
			o.applicationnumber,
			to_char(othfee.receiptdate,'dd-MM-YYYY') presentdate,
			othfee.partyfirstname||' '||othfee.partymiddlename||' '||othfee.partylastname as presentername,
			othfee.paymentdescription as descriptionofdocument,
			null as consideration_fees,
			null as marketvalue,
			sum( case when o.feerulecode=36 then COALESCE (receipttotal,0)  else 0 end) stampduty,
			null::numeric as cess,
			NULL as municipalsurcharge,
			NULL as Taluksurcharge,
			sum(distinct case when o.feerulecode=36 then COALESCE (receipttotal,0)  else 0 end) Total_duty,
			null as documentnumber,
			othfee.bookdetails as bookid,
			null::text as volumenumber,
			to_char(receiptdate,'dd-MM-YYYY') dateofcompletion,
			to_char(receiptdate,'dd-MM-YYYY') as dateofreturn,
			sum( case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end) registrationfees,
			null as feesforcopies,
			sum(distinct  case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) miscelaneousfees,
			null::numeric as otherstampduty,
			null as miscellaneous_article_fees,
			sum( case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end)+
			sum( case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) 
			as total_fees2,
			Null::numeric as Treasury_amount,
			null  as Treasury_transaction_date,
			 null::text as dailymutationreceipts,
			sum(distinct  case when o.feerulecode=6 then COALESCE (receipttotal,0) else 0 end) mutationfees,
			Null as mutationfees_to_treasury_date,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			null::text copy_of_document
			from kaveri.otherfeesrequired o
			join kaveri.otherreceiptdetails othfee  on o.receiptid = othfee.receiptid
			join kaveri.departmentusers d on o.departmentuserid = d.userid
			 join kaveri.sromaster sm on sm.srocode=d.srocode
			 JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode 
			 where 
			 
			 (othfee.receiptdate between _fromdate	and _todate + INTERVAL '1 day'  ) and 
			 
			 (

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode=_districtcode 

                    ELSE TRUE

                    end

                    )
			 and 
			 (

                    CASE

                    WHEN _srocode <> 0 THEN  d.srocode=_srocode 

                    ELSE TRUE

                    end

                    )
			
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  o.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
                 

			group by dsm.districtnamee,sm.sronamee,othfee.receiptdate,othfee.partyfirstname,
			othfee.partymiddlename,
			othfee.partylastname,o.applicationnumber,
			othfee.paymentdescription,othfee.bookdetails),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0 OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

 elsif pagenumber <> -1 or  pagesize <> -1 then 
 
 		return query
			with cte as (with a as ( select     
			dsm.districtnamee,
			sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,
			to_char(dm.presentdatetime,'dd-MM-YYYY') presentdate,
			(select 
			string_agg(distinct (coalesce(firstname,' ')||coalesce(middlename,' ')|| 
			coalesce(lastname,' ')::text),',') 
			from kaveri.partyinfo where applicationnumber=dm.applicationnumber  
			and ispresenter is true group by applicationnumber)as presentername ,
			--pi1.presentername,
			sa.articlenamee AS descriptionofdocument, 
			max(pm.sroconsideration) as consideration_fees,
			max(pm.sromarketvalue) as marketvalue,
			pm.propertytypeid ,
			case when dm.finalregistrationnumber is not null
			then dm.finalregistrationnumber else dm.pendingdocumentnumber end documentnumber,
			b.booknameenglish ,
			null  as volumenumber,
			(select sum(amsreg.totalamount)
			from kaveri.ams_reg_epaymenttransdetails amsreg where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false) as Treasury_amount,
			(select to_char(amsreg.inserteddatetime,'dd-MM-yyyy')
			from kaveri.ams_reg_epaymenttransdetails amsreg where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false limit 1)  as Challan_date ,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofcompletion,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofreturn,
			dm.uploaddocdeedpath as copy_of_document

			from  kaveri.documentmaster dm
			join  kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber 
			join kaveri.stamparticles sa on pm.stamparticlecode=sa.stamparticlecode 
			JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
			join kaveri.booktypemaster b on dm.bookid=b.bookid 
			--left join kaveri.ams_reg_epaymenttransdetails amsreg on 
			--amsreg.applicationnumber = dm.applicationnumber and amsreg.isdelete=false 
			where 
			
			(dm.registrationdatetime between _fromdate	and _todate + INTERVAL '1 day'  )
			and 
			
			(

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			and
			
				(

                    CASE

                    WHEN _srocode <> 0 THEN  dm.srocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  dm.finalregistrationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
               and 
			    
			 dm.isregistrationcompleted=true
			 group by dsm.districtnamee,sm.sronamee,dm.finalregistrationnumber,dm.applicationnumber,
			 sa.articlenamee,dm.pendingdocumentnumber,b.booknameenglish,
			 --,booknameenglish,
			dm.registrationdatetime,dm.uploaddocdeedpath,dm.presentdatetime,pm.propertytypeid	)

			select a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) stampduty,
			sum(case when fr.feerulecode=59  then amountpaid else 0 end) cess,
			sum(case when a.propertytypeid=28 and fr.feerulecode=58 then amountpaid else 0 end ) as municipalsurcharge,
			sum(case when a.propertytypeid=17 and fr.feerulecode=58 then amountpaid else 0 end ) as taluksurcharge,
			sum(case when fr.feerulecode in (36,58,59)  then amountpaid else 0 end)  as Total_duty,
			a.documentnumber,a.booknameenglish,a.volumenumber,
			a.dateofcompletion,a.dateofreturn,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end) registrationfees,
			sum(case when fr.feerulecode=41 then amountpaid else 0 end) as feesforcopies,
			sum(case when fr.feerulecode=2 then amountpaid else 0 end) miscelaneousfees,
			sum(case when fr.feerulecode in (34,91)then amountpaid else 0 end) otherstampduty,
			NULL::numeric miscellaneous_article_fees,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=41 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=2 then amountpaid else 0 end)+
			sum(case when fr.feerulecode  in (34,91)then amountpaid else 0 end) Total_fees2,
			a.Treasury_amount,
			a.Challan_date,
			string_agg(distinct (case when fr.feerulecode=6 then r.receiptnumber::text  else ' ' end ),' ')as dailymutationreceipts,
			sum(case when fr.feerulecode=6 then fr.amountpaid else 0 end) mutationfees,
			string_agg(distinct ( case when fr.feerulecode=6 then to_char(r.dateofreceipt,'DD-MM-YYYY')  else ' ' end ),' ')as mutationfeedate,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			a.copy_of_document

			from 
			a
			left join 	kaveri.feesrequired fr on a.applicationnumber=fr.applicationnumber
			left join kaveri.receiptmaster r on fr.receiptid=r.receiptid
			
			group by a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,
			a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			a.documentnumber,a.booknameenglish,
			a.volumenumber,a.Treasury_amount,
			a.Challan_date,a.dateofcompletion,a.dateofreturn,a.copy_of_document,a.propertytypeid
			
			
			
			

			Union all
			
			 
			
			select  
					dsm.districtnamee as districtname,
					sr.sronamee as sroname,
					null as finalregistrationnumber,
					eca.applicationnumber,
					to_char(a.applicationenddate,'dd-MM-YYYY') as  signeddatetime,
					c.firstname||c.middlename||c.lastname  as Presentername,
					'ECSearch' as descriptionofdocument,
					null::numeric  as considerationfees,
					null::numeric  as marketvalue,
					sum(case when er.feeruleid=64  then er.payableamount else 0 end) searchfee,
					sum(case when er.feeruleid=23  then er.payableamount else 0 end) searchapplfee,
					null::numeric as muncipalsurcharge,
					null::numeric  as taluksurcharge,
					 sum(case when er.feeruleid=64  then er.payableamount else 0 end)+
					 sum(case when er.feeruleid=23  then er.payableamount else 0 end)
					 as Total_duty,
					eca.certificatenumber as documentnumber,
					null as bookname,
					null as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofreturn,
					null as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount) as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
					null as dailymutation_receipt,
					null::numeric as mutationfees,
					null as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					eca.signedform22 as copy_of_document
					
					
					  from kaveri.ec_applicationdetails   eca
					  join kaveri.applicantapplicationdetails a on eca.applicationnumber=a.applicationnumber 
					  join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=eca.userid 
					  left join kaveri.ams_reg_epaymenttransdetails amsre on eca.applicationnumber=amsre.applicationnumber 
					  join  kaveri.ec_requiredfees er on eca.ecid=er.ecid 
					 where 
					 
					 (a.applicationenddate between _fromdate	and _todate + INTERVAL '1 day'  ) and 
					 (

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
				 and 
					 
					 (

                    CASE

                    WHEN _srocode <> 0 THEN  eca.kaverisrocode = _srocode

                    ELSE TRUE

                    end

                    )
				 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  eca.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
                and  a.currentstatus='CE110'
					 
					
					group by dsm.districtnamee,sr.sronamee,eca.applicationnumber,eca.signedform22,
					eca.propertydescription,a.applicationenddate,c.firstname,c.middlename,c.lastname,
					eca.certificatenumber,a.applicationenddate
					

			Union All

			select  
					dsm.districtnamee as district,
					sr.sronamee as sroname,
					null as finalregistrationnumber,
					cca.applicationnumber,
					to_char(a.applicationenddate,'dd-MM-YYYY') as  signeddatetime,
					c.firstname||c.middlename||c.lastname  as Presentername,
					'CCSearch' as descriptionofdocument,
					null::numeric as considerationfees,
					null::numeric as marketvalue,
					sum(case when cr.feeruleid=36  then cr.payableamount else 0 end) stampduty,
					sum(case when cr.feeruleid=14  then cr.payableamount else 0 end) searchfee,
				
					null as muncipalsurcharge,
					null as taluksurcharge,
					 sum(case when cr.feeruleid=36  then payableamount else 0 end)+
					 sum(case when cr.feeruleid=14  then payableamount else 0 end)
					 as Total_duty,
					cca.certificatenumber as documentnumber,
					null::text as bookname,
					null::text as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofreturn,
					null::numeric as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount) as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
					null as dailymutation_receipt,
					null::numeric as mutationfees,
					null::text as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					cca.signedform22 as copy_of_document
					
					
					from kaveri.cc_applicationdetails   cca
					  join kaveri.applicantapplicationdetails a on cca.applicationnumber=a.applicationnumber 
					  join kaveri.sromaster sr on cca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=cca.userid  
					  left join kaveri.ams_reg_epaymenttransdetails amsre on cca.applicationnumber=amsre.applicationnumber 
					  join (select ccid,feeruleid,sum(payableamount) as payableamount  from kaveri.cc_requiredfees  
					  group by ccid,feeruleid)cr on cca.ccid=cr.ccid 
					 where 
					 
					 (a.applicationenddate between _fromdate
			 			and _todate + INTERVAL '1 day'  ) and 
					 
					 (

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			 and 
					 
					 (

                    CASE

                    WHEN _srocode <> 0 THEN  cca.kaverisrocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  cca.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
                and  a.currentstatus='CC109'
			
					group by dsm.districtnamee,sr.sronamee,cca.applicationnumber,cca.signedform22,
					a.applicationenddate,c.firstname,c.middlename,c.lastname,
					cca.certificatenumber

			Union All

			select dsm.districtnamee,sm.sronamee,
			o.applicationnumber,
			o.applicationnumber,
			to_char(othfee.receiptdate,'dd-MM-YYYY') presentdate,
			othfee.partyfirstname||' '||othfee.partymiddlename||' '||othfee.partylastname as presentername,
			othfee.paymentdescription as descriptionofdocument,
			null as consideration_fees,
			null as marketvalue,
			sum( case when o.feerulecode=36 then COALESCE (receipttotal,0)  else 0 end) stampduty,
			null::numeric as cess,
			NULL as municipalsurcharge,
			NULL as Taluksurcharge,
			sum(distinct case when o.feerulecode=36 then COALESCE (receipttotal,0)  else 0 end) Total_duty,
			null as documentnumber,
			othfee.bookdetails as bookid,
			null::text as volumenumber,
			to_char(receiptdate,'dd-MM-YYYY') dateofcompletion,
			to_char(receiptdate,'dd-MM-YYYY') as dateofreturn,
			sum( case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end) registrationfees,
			null as feesforcopies,
			sum(distinct  case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) miscelaneousfees,
			null::numeric as otherstampduty,
			null as miscellaneous_article_fees,
			sum( case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end)+
			sum( case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) 
			as total_fees2,
			Null::numeric as Treasury_amount,
			null  as Treasury_transaction_date,
			 null::text as dailymutationreceipts,
			sum(distinct  case when o.feerulecode=6 then COALESCE (receipttotal,0) else 0 end) mutationfees,
			Null as mutationfees_to_treasury_date,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			null::text copy_of_document
			from kaveri.otherfeesrequired o
			join kaveri.otherreceiptdetails othfee  on o.receiptid = othfee.receiptid
			join kaveri.departmentusers d on o.departmentuserid = d.userid
			 join kaveri.sromaster sm on sm.srocode=d.srocode
			 JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode 
			 where 
			 
			 (othfee.receiptdate between _fromdate	and _todate + INTERVAL '1 day'  ) and 
			 
			 (

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode=_districtcode 

                    ELSE TRUE

                    end

                    )
			 and 
			 (

                    CASE

                    WHEN _srocode <> 0 THEN  d.srocode=_srocode 

                    ELSE TRUE

                    end

                    )
			
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  o.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
                 

			group by dsm.districtnamee,sm.sronamee,othfee.receiptdate,othfee.partyfirstname,
			othfee.partymiddlename,
			othfee.partylastname,o.applicationnumber,
			othfee.paymentdescription,othfee.bookdetails),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0 ;
 
 
 
 end if;
		


 

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_bck_18122023_new(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_register_of_fees_statutory_ccreg(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_ccreg(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber text, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document text, considerationamount numeric, marketvalue numeric, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid text, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees text, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, total_amount_collected bigint, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
declare
    pageoffset integer := 0;
begin
    if pagenumber is null or pagesize is null then
        pagenumber := -1;
        pagesize   := -1;
    end if;

    pageoffset := (pagenumber - 1) * pagesize;

    if pagenumber <> -1 and pagesize <> -1 then

        return query
        with base as (
            select
                dsm.districtnamee::varchar as districtname,
                sr.sronamee::varchar       as sroname,
                c.applicationnumber,
                c.ccid,
                c.kaverisrocode            as srocode,
                case when c.booktype in (1,2,3,4) then c.booktype else null end as bookid,
                coalesce(c.documentnumber, c.certificatenumber) as regnumber,
                c.submitteddatetime::date  as presentation_date,
                c.signeddatetime::date     as date_of_completion,
                c.signeddatetime::date     as date_of_return
            from kaveri.cc_applicationdetails c
            join kaveri.sromaster sr
              on c.kaverisrocode = sr.srocode
            join kaveri.districtmaster dsm
              on sr.districtcode = dsm.districtcode
            where c.signeddatetime between _fromdate and (_todate + interval '1 day')
              and (_districtcode = 0 or dsm.districtcode = _districtcode)
              and (_srocode = 0 or c.kaverisrocode = _srocode)
              and (
                    _documentnumber is null
                    or _documentnumber = ''
                    or c.applicationnumber = _documentnumber
                  )
        ),
        ccids as (
            select ccid from base
        ),
        presenter as (
            select
                b.applicationnumber,
                max(e.remittername) as presenter_name
            from base b
            join kaveri.ams_reg_epaymenttransdetails e
              on e.isdelete = false
             and (e.ccid = b.ccid or e.applicationnumber = b.applicationnumber)
            group by b.applicationnumber
        ),
        fees_reg as (
            select
                e.applicationnumber,
                sum(e.totalamount) as reg_fee
            from kaveri.ams_reg_epaymenttransdetails e
            join ccids c
              on c.ccid = e.ccid
            join kaveri.ams_reg_epaymentbankackdetails ack
              on ack.deptreferencecode = e.deptreferencecode
             and ack.paymentstatuscode in ('10700066','10700072')
            where e.isdelete = false
              and e.feerulecode in (
                    1, 3, 4, 5, 7, 8, 9, 13, 14, 15, 16, 17, 18, 19, 20,
                    23, 24, 25, 26, 27, 28, 30, 31, 34, 57, 63, 65, 88,
                    90, 93, 95, 97, 98, 102, 103, 106, 108, 109, 141
              )
            group by e.applicationnumber
        ),
        fees_copy as (
            select
                b.applicationnumber,
                sum(
                    case
                        when rf.feeruleid in (23,134,135,136,137,139,140)
                        then rf.payableamount
                        else 0
                    end
                ) as copy_fee
            from base b
            left join kaveri.cc_requiredfees rf
              on rf.ccid = b.ccid
             and rf.ispaid = true
            group by b.applicationnumber
        ),
        fees as (
            select
                b.applicationnumber,
                coalesce(fr.reg_fee, 0)  as reg_fee,
                coalesce(fc.copy_fee, 0) as copy_fee
            from base b
            left join fees_reg  fr on fr.applicationnumber = b.applicationnumber
            left join fees_copy fc on fc.applicationnumber = b.applicationnumber
        ),
        treasury as (
            select
                are2.ccid,
                sum(distinct ack.amount)            as treasury_amount,
                max(ack.transactiontimestamp::date) as treasury_date
            from kaveri.ams_reg_epaymenttransdetails are2
            join ccids c
              on c.ccid = are2.ccid
            join kaveri.ams_reg_epaymentbankackdetails ack
              on ack.deptreferencecode = are2.deptreferencecode
             and ack.paymentstatuscode in ('10700066','10700072')
            where are2.isdelete = false
            group by are2.ccid
        ),
        mutation_treasury as (
            select
                b.applicationnumber,
                sum(are2.totalamount)               as mutation_amount,
                max(ack.transactiontimestamp::date) as mutation_date
            from base b
            join kaveri.ams_reg_epaymenttransdetails are2
              on are2.isdelete = false
             and are2.feerulecode = 6
             and (
                    are2.ccid = b.ccid
                 or (
                        are2.applicationnumber is not null
                    and are2.applicationnumber = b.applicationnumber
                 )
              )
            join kaveri.ams_reg_epaymentbankackdetails ack
              on ack.deptreferencecode = are2.deptreferencecode
             and ack.paymentstatuscode in ('10700066','10700072')
            group by b.applicationnumber
        ),
        value as (
            select
                b.applicationnumber,
                null::numeric             as consideration,
                null::numeric             as market_value,
                'searches and inspection' as articlenamee
            from base b
        ),
        docs as (
            select
                s.applicationnumber,
                max(s.filepath)::text as copy_of_document
            from kaveri.signed_file_upload_details s
            group by s.applicationnumber
        ),
        final as (
            select
                b.applicationnumber,
                b.presentation_date                  as date_of_presentation,
                pr.presenter_name                    as name_of_presenter,
                v.articlenamee                       as description_of_document,
                null::numeric                        as consideration,
                null::numeric                        as market_value,
                null::numeric                        as stamp_duty_a,
                null::numeric                        as cess_on_duty_b,
                null::numeric                        as surcharge_municipal_c,
                null::numeric                        as surcharge_taluk_d,
                null::numeric                        as total_duty_on_document_e,
                b.regnumber                          as number_in_register,
                b.bookid                             as which_book,
                null::text                           as volume_no,
                b.date_of_completion                 as date_of_completion,
                b.date_of_return                     as date_of_return,
                coalesce(f.reg_fee, 0)               as fees_for_registration_of_documents,
                coalesce(f.copy_fee, 0)              as fees_for_copies_granted,
                0::numeric                           as scanning_fees,
                null::numeric                        as other_stamp_duty,
                null::numeric                        as article_of_table_of_fees,
                coalesce(f.reg_fee, 0)
                + coalesce(f.copy_fee, 0)            as total_of_cols_14_15_16,
                t.treasury_amount                    as fees_remitted_to_treasury_amount,
                t.treasury_date                      as fees_remitted_to_treasury_date,
                mt.mutation_amount                   as daily_mutation_receipts,
                mt.mutation_date                     as mutation_fee_remitted_date,
                coalesce(f.reg_fee, 0)
                + coalesce(f.copy_fee, 0)
                + coalesce(mt.mutation_amount, 0)    as total_amount_collected,
                null::text                           as signature_of_registering_officer,
                null::text                           as remarks,
                b.districtname,
                b.sroname,
                d.copy_of_document
            from base b
            left join presenter         pr on pr.applicationnumber  = b.applicationnumber
            left join value             v  on v.applicationnumber   = b.applicationnumber
            left join fees              f  on f.applicationnumber   = b.applicationnumber
            left join treasury          t  on t.ccid                = b.ccid
            left join mutation_treasury mt on mt.applicationnumber = b.applicationnumber
            left join docs              d  on d.applicationnumber   = b.applicationnumber
        ),
        result as (
            select distinct
                f.districtname,
                f.sroname,
                null::text                                 as finalregistrationnumber,
                f.applicationnumber::varchar               as applicationnumber2,
                f.date_of_presentation::text               as presentationdatetime,
                f.name_of_presenter::text                  as presenter_name,
                f.description_of_document::text            as description_of_document,
                f.consideration                            as considerationamount,
                f.market_value                             as marketvalue,
                f.stamp_duty_a                             as stampduty,
                f.cess_on_duty_b                           as cess,
                f.surcharge_municipal_c                    as surcharge_duty_muncipal,
                f.surcharge_taluk_d                        as surcharge_duty_taluk,
                f.total_duty_on_document_e                 as total_duty,
                f.number_in_register::varchar              as documentnumber,
                f.which_book::text                         as bookid,
                f.volume_no::text                          as volumenumber,
                f.date_of_completion::text                 as dateofcompletion,
                f.date_of_return::text                     as dateofreturn,
                f.fees_for_registration_of_documents::text as registrationfees,
                f.fees_for_copies_granted                  as feescopygranted,
                f.scanning_fees                            as miscfees,
                f.other_stamp_duty                         as otherstampduty,
                f.article_of_table_of_fees                 as miscarticlefees,
                f.total_of_cols_14_15_16                   as total_fees,
                f.fees_remitted_to_treasury_amount         as treasury_fees,
                f.fees_remitted_to_treasury_date::text     as feedate_treasury,
                f.daily_mutation_receipts::text            as dailymutationreceipts,
                f.daily_mutation_receipts                  as mutationfees,
                f.mutation_fee_remitted_date::text         as mutationfeedate,
                null::text                                 as transmission_of_memorandum,
                null::text                                 as transmission_of_memoranda,
                f.total_amount_collected::bigint           as total_amount_collected,
                f.signature_of_registering_officer         as signature_of_register,
                f.remarks                                  as remarks,
                f.copy_of_document                         as copy_of_document
            from final f
        ),
        base_count as (
            select count(*)::bigint as totalcount from result
        )
        select
            r.*,
            bc.totalcount
        from result r
        cross join base_count bc
        order by dateofcompletion, documentnumber
        offset pageoffset
        fetch next pagesize rows only;

    elsif pagenumber = -1 or pagesize = -1 then

        return query
        with base as (
            select
                dsm.districtnamee::varchar as districtname,
                sr.sronamee::varchar       as sroname,
                c.applicationnumber,
                c.ccid,
                c.kaverisrocode            as srocode,
                case when c.booktype in (1,2,3,4) then c.booktype else null end as bookid,
                coalesce(c.documentnumber, c.certificatenumber) as regnumber,
                c.submitteddatetime::date  as presentation_date,
                c.signeddatetime::date     as date_of_completion,
                c.signeddatetime::date     as date_of_return
            from kaveri.cc_applicationdetails c
            join kaveri.sromaster sr
              on c.kaverisrocode = sr.srocode
            join kaveri.districtmaster dsm
              on sr.districtcode = dsm.districtcode
            where c.signeddatetime between _fromdate and (_todate + interval '1 day')
              and (_districtcode = 0 or dsm.districtcode = _districtcode)
              and (_srocode = 0 or c.kaverisrocode = _srocode)
              and (
                    _documentnumber is null
                    or _documentnumber = ''
                    or c.applicationnumber = _documentnumber
                  )
        ),
        ccids as (
            select ccid from base
        ),
        presenter as (
            select
                b.applicationnumber,
                max(e.remittername) as presenter_name
            from base b
            join kaveri.ams_reg_epaymenttransdetails e
              on e.isdelete = false
             and (e.ccid = b.ccid or e.applicationnumber = b.applicationnumber)
            group by b.applicationnumber
        ),
        fees_reg as (
            select
                e.applicationnumber,
                sum(e.totalamount) as reg_fee
            from kaveri.ams_reg_epaymenttransdetails e
            join ccids c
              on c.ccid = e.ccid
            join kaveri.ams_reg_epaymentbankackdetails ack
              on ack.deptreferencecode = e.deptreferencecode
             and ack.paymentstatuscode in ('10700066','10700072')
            where e.isdelete = false
              and e.feerulecode in (
                    1, 3, 4, 5, 7, 8, 9, 13, 14, 15, 16, 17, 18, 19, 20,
                    23, 24, 25, 26, 27, 28, 30, 31, 34, 57, 63, 65, 88,
                    90, 93, 95, 97, 98, 102, 103, 106, 108, 109, 141
              )
            group by e.applicationnumber
        ),
        fees_copy as (
            select
                b.applicationnumber,
                sum(
                    case when rf.feeruleid in (23, 134, 135, 136, 137, 139, 140)
                         then rf.payableamount else 0 end
                ) as copy_fee
            from base b
            left join kaveri.cc_requiredfees rf
              on rf.ccid = b.ccid
             and rf.ispaid = true
            group by b.applicationnumber
        ),
        fees as (
            select
                b.applicationnumber,
                coalesce(fr.reg_fee, 0)  as reg_fee,
                coalesce(fc.copy_fee, 0) as copy_fee
            from base b
            left join fees_reg  fr on fr.applicationnumber = b.applicationnumber
            left join fees_copy fc on fc.applicationnumber = b.applicationnumber
        ),
        treasury as (
            select
                are2.ccid,
                sum(distinct ack.amount)            as treasury_amount,
                max(ack.transactiontimestamp::date) as treasury_date
            from kaveri.ams_reg_epaymenttransdetails are2
            join ccids c
              on c.ccid = are2.ccid
            join kaveri.ams_reg_epaymentbankackdetails ack
              on ack.deptreferencecode = are2.deptreferencecode
             and ack.paymentstatuscode in ('10700066','10700072')
            where are2.isdelete = false
            group by are2.ccid
        ),
        mutation_treasury as (
            select
                b.applicationnumber,
                sum(are2.totalamount)               as mutation_amount,
                max(ack.transactiontimestamp::date) as mutation_date
            from base b
            join kaveri.ams_reg_epaymenttransdetails are2
              on are2.isdelete = false
             and are2.feerulecode = 6
             and (
                    are2.ccid = b.ccid
                 or (
                        are2.applicationnumber is not null
                    and are2.applicationnumber = b.applicationnumber
                 )
              )
            join kaveri.ams_reg_epaymentbankackdetails ack
              on ack.deptreferencecode = are2.deptreferencecode
             and ack.paymentstatuscode in ('10700066','10700072')
            group by b.applicationnumber
        ),
        value as (
            select
                b.applicationnumber,
                null::numeric             as consideration,
                null::numeric             as market_value,
                'searches and inspection' as articlenamee
            from base b
        ),
        docs as (
            select
                s.applicationnumber,
                max(s.filepath)::text as copy_of_document
            from kaveri.signed_file_upload_details s
            group by s.applicationnumber
        ),
        final as (
            select
                --row_number() over (order by b.signeddatetime, b.regnumber) as slno,
                b.applicationnumber,
                b.presentation_date                  as date_of_presentation,
                pr.presenter_name                    as name_of_presenter,
                v.articlenamee                       as description_of_document,
                null::numeric                        as consideration,
                null::numeric                        as market_value,
                null::numeric                        as stamp_duty_a,
                null::numeric                        as cess_on_duty_b,
                null::numeric                        as surcharge_municipal_c,
                null::numeric                        as surcharge_taluk_d,
                null::numeric                        as total_duty_on_document_e,
                b.regnumber                          as number_in_register,
                b.bookid                             as which_book,
                null::text                           as volume_no,
             b.date_of_completion                 as date_of_completion,
                b.date_of_return                     as date_of_return,
                coalesce(f.reg_fee, 0)               as fees_for_registration_of_documents,
                coalesce(f.copy_fee, 0)              as fees_for_copies_granted,
                0::numeric                           as scanning_fees,
                null::numeric                        as other_stamp_duty,
                null::numeric                        as article_of_table_of_fees,
                coalesce(f.reg_fee, 0)
                + coalesce(f.copy_fee, 0)            as total_of_cols_14_15_16,
                t.treasury_amount                    as fees_remitted_to_treasury_amount,
                t.treasury_date                      as fees_remitted_to_treasury_date,
                mt.mutation_amount                   as daily_mutation_receipts,
                mt.mutation_date                     as mutation_fee_remitted_date,
                coalesce(f.reg_fee, 0)
                + coalesce(f.copy_fee, 0)
                + coalesce(mt.mutation_amount, 0)    as total_amount_collected,
                null::text                           as signature_of_registering_officer,
                null::text                           as remarks,
                b.districtname,
                b.sroname,
                d.copy_of_document
            from base b
            left join presenter         pr on pr.applicationnumber  = b.applicationnumber
            left join value             v  on v.applicationnumber   = b.applicationnumber
            left join fees              f  on f.applicationnumber   = b.applicationnumber
            left join treasury          t  on t.ccid                = b.ccid
            left join mutation_treasury mt on mt.applicationnumber = b.applicationnumber
            left join docs              d  on d.applicationnumber   = b.applicationnumber
        ),
        result as (
            select distinct
                f.districtname,
                f.sroname,
