                f.cess_on_duty_b                           as cess,
                f.surcharge_municipal_c                    as surcharge_duty_muncipal,
                f.surcharge_taluk_d                        as surcharge_duty_taluk,
                f.total_duty_on_document_e                 as total_duty,
                f.number_in_register::varchar              as documentnumber,
                f.which_book::text                         as bookid,
                f.volume_no::text                          as volumenumber,
                f.date_of_completion::text                 as dateofcompletion,
                f.date_of_return::text                     as dateofreturn,
                f.fees_for_registration_of_documents::text as registrationfees,
                f.fees_for_copies_granted                  as feescopygranted,
                f.scanning_fees                            as miscfees,
                f.other_stamp_duty                         as otherstampduty,
                f.article_of_table_of_fees                 as miscarticlefees,
                f.total_of_cols_14_15_16                   as total_fees,
                f.fees_remitted_to_treasury_amount         as treasury_fees,
                f.fees_remitted_to_treasury_date::text     as feedate_treasury,
                f.daily_mutation_receipts::text            as dailymutationreceipts,
                f.daily_mutation_receipts                  as mutationfees,
                f.mutation_fee_remitted_date::text         as mutationfeedate,
                null::text                                 as transmission_of_memorandum,
                null::text                                 as transmission_of_memoranda,
                f.total_amount_collected::bigint           as total_amount_collected,
                f.signature_of_registering_officer         as signature_of_register,
                f.remarks                                  as remarks,
                f.copy_of_document                         as copy_of_document
            from final f
        ),
        base_count as (
            select count(*)::bigint as totalcount from result
        )
        select
            r.*,
            bc.totalcount
        from result r
        cross join base_count bc
        order by dateofcompletion, documentnumber;

    end if;
end;
$$;


