--
-- Name: fn_mis_daily_register_of_fees_statutory_ccreg_10092025(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_ccreg_10092025(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber text, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document text, considerationamount numeric, marketvalue numeric, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid text, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees text, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if pagenumber <> -1 and pagesize <> -1 then
			return query
			with cte as (
			select  
					dsm.districtnamee::character varying as district,
					sr.sronamee::character varying as sroname,
					null::text as finalregistrationnumber,
					cca.applicationnumber::character varying,
					to_char(a.applicationenddate,'dd-MM-YYYY')::text as  signeddatetime,
					c.firstname::text||c.middlename::text||c.lastname::text  as Presentername,
					'CCSearch'::text as descriptionofdocument,
					null::numeric as considerationfees,
					null::numeric as marketvalue,
					sum(case when cr.feeruleid=36  then cr.payableamount else 0 end)::numeric stampduty,
					sum(case when cr.feeruleid=14  then cr.payableamount else 0 end)::numeric searchfee,
					null::numeric as muncipalsurcharge,
					null::numeric as taluksurcharge,
					 sum(case when cr.feeruleid=36  then payableamount else 0 end)+
					 sum(case when cr.feeruleid=14  then payableamount else 0 end)::numeric
					 as Total_duty,
					cca.certificatenumber::character varying as documentnumber,
					null::text as bookname,
					null::text as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY')::text dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY')::text dateofreturn,
					null::text as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount)::numeric as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',')::text as Challan_date,
					null::text as dailymutation_receipt,
					null::numeric as mutationfees,
					null::text as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					sg.filepath::text as copy_of_document
					from kaveri.cc_applicationdetails   cca
					  join kaveri.applicantapplicationdetails a on cca.applicationnumber=a.applicationnumber 
					  join kaveri.signed_file_upload_details sg on a.applicationnumber=sg.applicationnumber
					  join kaveri.sromaster sr on cca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=cca.userid  
					  left join kaveri.ams_reg_epaymenttransdetails amsre on cca.applicationnumber=amsre.applicationnumber 
					  join (select ccid,feeruleid,sum(payableamount) as payableamount  from kaveri.cc_requiredfees  
					  group by ccid,feeruleid)cr on cca.ccid=cr.ccid 
					 where 
					 
					 (a.applicationenddate between _fromdate
			 			and _todate + INTERVAL '1 day'  ) and 
					 
					 (

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			 and 
					 
					 (

                    CASE

                    WHEN _srocode <> 0 THEN  cca.kaverisrocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  cca.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
                and  a.currentstatus='CC109'
			
					group by dsm.districtnamee,sr.sronamee,cca.applicationnumber,sg.filepath,
					a.applicationenddate,c.firstname,c.middlename,c.lastname,
					cca.certificatenumber)
			select * from cte
			right join (select null::bigint as total_rows) total_row on true
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
					
					
					
elsif pagenumber = -1 or  pagesize = -1 then  
			return query
			with cte as (
			select  
					dsm.districtnamee::character varying as district,
					sr.sronamee::character varying as sroname,
					null::text  as finalregistrationnumber,
					cca.applicationnumber::character varying,
					to_char(a.applicationenddate,'dd-MM-YYYY')::text as  signeddatetime,
					c.firstname::text||c.middlename::text||c.lastname::text  as Presentername,
					'CCSearch'::text as descriptionofdocument,
					null::numeric as considerationfees,
					null::numeric as marketvalue,
					sum(case when cr.feeruleid=36  then cr.payableamount else 0 end)::numeric stampduty,
					sum(case when cr.feeruleid=14  then cr.payableamount else 0 end)::numeric searchfee,
					null::numeric as muncipalsurcharge,
					null::numeric as taluksurcharge,
					 sum(case when cr.feeruleid=36  then payableamount else 0 end)+
					 sum(case when cr.feeruleid=14  then payableamount else 0 end)::numeric
					 as Total_duty,
					cca.certificatenumber::character varying as documentnumber,
					null::text as bookname,
					null::text as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY')::text dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY')::text dateofreturn,
					null::text as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount)::numeric as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',')::text as Challan_date,
					null::text as dailymutation_receipt,
					null::numeric as mutationfees,
					null::text as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					sg.filepath::text as copy_of_document
					from kaveri.cc_applicationdetails   cca
					  join kaveri.applicantapplicationdetails a on cca.applicationnumber=a.applicationnumber 
					  join kaveri.signed_file_upload_details sg on a.applicationnumber=sg.applicationnumber
					  join kaveri.sromaster sr on cca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=cca.userid  
					  left join kaveri.ams_reg_epaymenttransdetails amsre on cca.applicationnumber=amsre.applicationnumber 
					  join (select ccid,feeruleid,sum(payableamount) as payableamount  from kaveri.cc_requiredfees  
					  group by ccid,feeruleid)cr on cca.ccid=cr.ccid 
					 where 
					 
					 (a.applicationenddate between _fromdate
			 			and _todate + INTERVAL '1 day'  ) and 
					 
					 (

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			 and 
					 
					 (

                    CASE

                    WHEN _srocode <> 0 THEN  cca.kaverisrocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  cca.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
                and  a.currentstatus='CC109'
			
					group by dsm.districtnamee,sr.sronamee,cca.applicationnumber,sg.filepath,
					a.applicationenddate,c.firstname,c.middlename,c.lastname,
					cca.certificatenumber)
			select * from cte
			right join (select null::bigint as total_rows) total_row on true;
			
					

 end if;
		

 

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_ccreg_10092025(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_register_of_fees_statutory_ccreg_20251202(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_ccreg_20251202(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber text, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document text, considerationamount numeric, marketvalue numeric, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid text, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees text, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if pagenumber <> -1 and pagesize <> -1 then
			return query
			with cte as (select dsm.districtnamee,s.sronamee as sroname, rd.numberinregister::text as finalregistrationnumber, rd.applicationnumber ,
					rd.dateofpresenter::text as presentationdatetime,rd.nameofpresenter::text as presenter_name,rd.descriptionofdocument as description_of_document,
					null::numeric as considerationamount, 
					null::numeric as marketvalue, 
					null::numeric as stampduty, 
					null::numeric as cess, 
					null::numeric as surcharge_duty_muncipal,
					null::numeric as surcharge_duty_taluk, 
					null::numeric as total_duty, 
					rd.numberinregister as documentnumber, rd.book::text as bookid, rd.volumeno as volumenumber,rd.dateofcompletion::text as dateofcompletion,
					rd.dateofreturn::text as dateofreturn, rd.feesforregistrationofdocuments as registrationfees,
					null::numeric as feescopygranted,
					null::numeric as miscfees,
					null::numeric as otherstampduty,
					null::numeric as miscarticlefees, 
					null::numeric as total_fees, 
					rd.feesremittedtotreasuryamount::numeric as treasury_fees,rd.feesremittedtotreasurydate::text as feedate_treasury,
					null as dailymutationreceipts,
					null::numeric as mutationfees, rd.mutationfeeremittedtotreasurywithdate::text as mutationfeedate,
					null as transmission_of_memorandum,
					null as transmission_of_memoranda,
					rd.signatureofregisteringofficer as signature_of_register, rd.remarks,
					null as copy_of_document
					from kaveri.revised_form_7_statutory_cc rd
					join kaveri.cc_applicationdetails dm on rd.applicationnumber = dm.applicationnumber
					join kaveri.sromaster s on s.srocode = dm.kaverisrocode
					join kaveri.districtmaster dsm on dsm.districtcode = s.districtcode
					where 
					(rd.dateofcompletion between _fromdate	and _todate + INTERVAL '1 day'  ) 
					and 
					(CASE WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode ELSE TRUE end)
					and 
					(CASE WHEN _srocode <> 0 THEN dm.kaverisrocode = _srocode ELSE TRUE end)
					and 
					(CASE WHEN _documentnumber<>(case when (_documentnumber<>null and _documentnumber<>'') then _documentnumber else  '' end) THEN  rd.numberinregister=_documentnumber ELSE TRUE end))
			select * from cte
			right join (select null::bigint as total_rows) total_row on true
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
					
					
					
elsif pagenumber = -1 or  pagesize = -1 then  
			return query
			with cte as (select dsm.districtnamee,s.sronamee as sroname, rd.numberinregister::text as finalregistrationnumber, rd.applicationnumber ,
					rd.dateofpresenter::text as presentationdatetime,rd.nameofpresenter::text as presenter_name,rd.descriptionofdocument as description_of_document,
					null::numeric as considerationamount, 
					null::numeric as marketvalue, 
					null::numeric as stampduty, 
					null::numeric as cess, 
					null::numeric as surcharge_duty_muncipal,
					null::numeric as surcharge_duty_taluk, 
					null::numeric as total_duty, 
					rd.numberinregister as documentnumber, rd.book::text as bookid, rd.volumeno as volumenumber,rd.dateofcompletion::text as dateofcompletion,
					rd.dateofreturn::text as dateofreturn, rd.feesforregistrationofdocuments as registrationfees,
					null::numeric as feescopygranted,
					null::numeric as miscfees,
					null::numeric as otherstampduty,
					null::numeric as miscarticlefees, 
					null::numeric as total_fees, 
					rd.feesremittedtotreasuryamount::numeric as treasury_fees,rd.feesremittedtotreasurydate::text as feedate_treasury,
					null as dailymutationreceipts,
					null::numeric as mutationfees, rd.mutationfeeremittedtotreasurywithdate::text as mutationfeedate,
					null as transmission_of_memorandum,
					null as transmission_of_memoranda,
					rd.signatureofregisteringofficer as signature_of_register, rd.remarks,
					null as copy_of_document
					from kaveri.revised_form_7_statutory_cc rd
					join kaveri.cc_applicationdetails dm on rd.applicationnumber = dm.applicationnumber
					join kaveri.sromaster s on s.srocode = dm.kaverisrocode
					join kaveri.districtmaster dsm on dsm.districtcode = s.districtcode
					where 
					(rd.dateofcompletion between _fromdate	and _todate + INTERVAL '1 day'  ) 
					and 
					(CASE WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode ELSE TRUE end)
					and 
					(CASE WHEN _srocode <> 0 THEN dm.kaverisrocode = _srocode ELSE TRUE end)
					and 
					(CASE WHEN _documentnumber<>(case when (_documentnumber<>null and _documentnumber<>'') then _documentnumber else  '' end) THEN  rd.numberinregister=_documentnumber ELSE TRUE end))
			select * from cte
			right join (select null::bigint as total_rows) total_row on true;
end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_ccreg_20251202(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_register_of_fees_statutory_ccreg_new(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_ccreg_new(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber text, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document text, considerationamount numeric, marketvalue numeric, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid text, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees text, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, total_amount_collected bigint, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
declare
    pageoffset integer := 0;
begin
    if pagenumber is null or pagesize is null then
        pagenumber := -1;
        pagesize   := -1;
    end if;

    pageoffset := (pagenumber - 1) * pagesize;

    if pagenumber <> -1 and pagesize <> -1 then

        return query
        with base as (
            select
                dsm.districtnamee::varchar as districtname,
                sr.sronamee::varchar       as sroname,
                c.applicationnumber,
                c.ccid,
                c.kaverisrocode            as srocode,
                case when c.booktype in (1,2,3,4) then c.booktype else null end as bookid,
                c.certificatenumber           as regnumber,
                c.submitteddatetime::date  as presentation_date,
                c.signeddatetime::date     as date_of_completion,
                c.signeddatetime::date     as date_of_return
            from kaveri.cc_applicationdetails c
            join kaveri.sromaster sr
              on c.kaverisrocode = sr.srocode
            join kaveri.districtmaster dsm
              on sr.districtcode = dsm.districtcode
            where c.signeddatetime between _fromdate and (_todate + interval '1 day')
              and (_districtcode = 0 or dsm.districtcode = _districtcode)
              and (_srocode = 0 or c.kaverisrocode = _srocode)
              and (
                    _documentnumber is null
                    or _documentnumber = ''
                    or c.applicationnumber = _documentnumber
                  )
        ),
        ccids as (
            select ccid from base
        ),
        presenter as (
            select
                b.applicationnumber,
                max(e.remittername) as presenter_name
            from base b
            join kaveri.ams_reg_epaymenttransdetails e
              on e.isdelete = false
             and (e.ccid = b.ccid or e.applicationnumber = b.applicationnumber)
            group by b.applicationnumber
        ),
        fees_reg as (
            select
                e.applicationnumber,
                sum(e.totalamount) as reg_fee
            from kaveri.ams_reg_epaymenttransdetails e
            join ccids c
              on c.ccid = e.ccid
            join kaveri.ams_reg_epaymentbankackdetails ack
              on ack.deptreferencecode = e.deptreferencecode
             and ack.paymentstatuscode in ('10700066','10700072')
            where e.isdelete = false
              and e.feerulecode in (
                    1, 3, 4, 5, 7, 8, 9, 13, 14, 15, 16, 17, 18, 19, 20,
                    23, 24, 25, 26, 27, 28, 30, 31, 34, 57, 63, 65, 88,
                    90, 93, 95, 97, 98, 102, 103, 106, 108, 109, 141
              )
            group by e.applicationnumber
        ),
        fees_copy as (
            select
                b.applicationnumber,
                sum(
                    case
                        when rf.feeruleid in (23,134,135,136,137,139,140)
                        then rf.payableamount
                        else 0
                    end
                ) as copy_fee
            from base b
            left join kaveri.cc_requiredfees rf
              on rf.ccid = b.ccid
             and rf.ispaid = true
            group by b.applicationnumber
        ),
		fees_stampduty as (
            select
                b.applicationnumber,
                sum(
                    case
                        when rf.feeruleid in (35,36,64,89,91,92,101,107,110,138)
                        then rf.payableamount
                        else 0
                    end
                ) as stampduty_fee
            from base b
            left join kaveri.cc_requiredfees rf
              on rf.ccid = b.ccid
             and rf.ispaid = true
            group by b.applicationnumber
        ),
        fees as (
            select
                b.applicationnumber,
                coalesce(fr.reg_fee, 0)  as reg_fee,
                coalesce(fc.copy_fee, 0) as copy_fee,
				coalesce(fs.stampduty_fee, 0) as stampduty_fee
            from base b
            left join fees_reg  fr on fr.applicationnumber = b.applicationnumber
            left join fees_copy fc on fc.applicationnumber = b.applicationnumber
			left join fees_stampduty fs on fs.applicationnumber=b.applicationnumber
        ),
        treasury as (
            select
                are2.ccid,
                sum(distinct ack.amount)            as treasury_amount,
                max(ack.transactiontimestamp::date) as treasury_date
            from kaveri.ams_reg_epaymenttransdetails are2
            join ccids c
              on c.ccid = are2.ccid
            join kaveri.ams_reg_epaymentbankackdetails ack
              on ack.deptreferencecode = are2.deptreferencecode
             and ack.paymentstatuscode in ('10700066','10700072')
            where are2.isdelete = false
            group by are2.ccid
        ),
        mutation_treasury as (
            select
                b.applicationnumber,
                sum(are2.totalamount)               as mutation_amount,
                max(ack.transactiontimestamp::date) as mutation_date
            from base b
            join kaveri.ams_reg_epaymenttransdetails are2
              on are2.isdelete = false
             and are2.feerulecode = 6
             and (
                    are2.ccid = b.ccid
                 or (
                        are2.applicationnumber is not null
                    and are2.applicationnumber = b.applicationnumber
                 )
              )
            join kaveri.ams_reg_epaymentbankackdetails ack
              on ack.deptreferencecode = are2.deptreferencecode
             and ack.paymentstatuscode in ('10700066','10700072')
            group by b.applicationnumber
        ),
        value as (
            select
                b.applicationnumber,
                null::numeric             as consideration,
                null::numeric             as market_value,
                'searches and inspection' as articlenamee
            from base b
        ),
        docs as (
            select
                s.applicationnumber,
                max(s.filepath)::text as copy_of_document
            from kaveri.signed_file_upload_details s
            group by s.applicationnumber
        ),
        final as (
            select
                b.applicationnumber,
                b.presentation_date                  as date_of_presentation,
                pr.presenter_name                    as name_of_presenter,
                v.articlenamee                       as description_of_document,
                null::numeric                        as consideration,
                null::numeric                        as market_value,
                coalesce(f.stampduty_fee,0)          as stamp_duty_a,
                null::numeric                        as cess_on_duty_b,
                null::numeric                        as surcharge_municipal_c,
                null::numeric                        as surcharge_taluk_d,
                null::numeric                        as total_duty_on_document_e,
                b.regnumber                          as number_in_register,
                b.bookid                             as which_book,
                null::text                           as volume_no,
                b.date_of_completion                 as date_of_completion,
                b.date_of_return                     as date_of_return,
                coalesce(f.reg_fee, 0)               as fees_for_registration_of_documents,
                coalesce(f.copy_fee, 0)              as fees_for_copies_granted,
                0::numeric                           as scanning_fees,
                null::numeric                        as other_stamp_duty,
                null::numeric                        as article_of_table_of_fees,
                coalesce(f.reg_fee, 0)
                + coalesce(f.copy_fee, 0)+ coalesce(f.stampduty_fee,0)           as total_of_cols_14_15_16,
                t.treasury_amount                    as fees_remitted_to_treasury_amount,
                t.treasury_date                      as fees_remitted_to_treasury_date,
                mt.mutation_amount                   as daily_mutation_receipts,
                mt.mutation_date                     as mutation_fee_remitted_date,
                coalesce(f.reg_fee, 0)
                + coalesce(f.copy_fee, 0)
                + coalesce(mt.mutation_amount, 0)    as total_amount_collected,
                null::text                           as signature_of_registering_officer,
                null::text                           as remarks,
                b.districtname,
                b.sroname,
                d.copy_of_document
            from base b
            left join presenter         pr on pr.applicationnumber  = b.applicationnumber
            left join value             v  on v.applicationnumber   = b.applicationnumber
            left join fees              f  on f.applicationnumber   = b.applicationnumber
            left join treasury          t  on t.ccid                = b.ccid
            left join mutation_treasury mt on mt.applicationnumber = b.applicationnumber
            left join docs              d  on d.applicationnumber   = b.applicationnumber
        ),
        result as (
            select distinct
                f.districtname,
                f.sroname,
                null::text                                 as finalregistrationnumber,
                f.applicationnumber::varchar               as applicationnumber2,
                f.date_of_presentation::text               as presentationdatetime,
                f.name_of_presenter::text                  as presenter_name,
                f.description_of_document::text            as description_of_document,
                f.consideration                            as considerationamount,
                f.market_value                             as marketvalue,
                f.stamp_duty_a                             as stampduty,
                f.cess_on_duty_b                           as cess,
                f.surcharge_municipal_c                    as surcharge_duty_muncipal,
                f.surcharge_taluk_d                        as surcharge_duty_taluk,
                f.total_duty_on_document_e                 as total_duty,
                f.number_in_register::varchar              as documentnumber,
                f.which_book::text                         as bookid,
                f.volume_no::text                          as volumenumber,
                f.date_of_completion::text                 as dateofcompletion,
                f.date_of_return::text                     as dateofreturn,
                f.fees_for_registration_of_documents::text as registrationfees,
                f.fees_for_copies_granted                  as feescopygranted,
                f.scanning_fees                            as miscfees,
                f.other_stamp_duty                         as otherstampduty,
                f.article_of_table_of_fees                 as miscarticlefees,
                f.total_of_cols_14_15_16                   as total_fees,
                f.fees_remitted_to_treasury_amount         as treasury_fees,
                f.fees_remitted_to_treasury_date::text     as feedate_treasury,
                f.daily_mutation_receipts::text            as dailymutationreceipts,
                f.daily_mutation_receipts                  as mutationfees,
                f.mutation_fee_remitted_date::text         as mutationfeedate,
                null::text                                 as transmission_of_memorandum,
                null::text                                 as transmission_of_memoranda,
                f.total_amount_collected::bigint           as total_amount_collected,
                f.signature_of_registering_officer         as signature_of_register,
                f.remarks                                  as remarks,
                f.copy_of_document                         as copy_of_document
            from final f
        ),
        base_count as (
            select count(*)::bigint as totalcount from result
        )
        select
            r.*,
            bc.totalcount
        from result r
        cross join base_count bc
        order by dateofcompletion, documentnumber
        offset pageoffset
        fetch next pagesize rows only;

    elsif 
	pagenumber = -1 or pagesize = -1 then

        return query
        with base as (
            select
                dsm.districtnamee::varchar as districtname,
                sr.sronamee::varchar       as sroname,
                c.applicationnumber,
                c.ccid,
                c.kaverisrocode            as srocode,
                case when c.booktype in (1,2,3,4) then c.booktype else null end as bookid,
                c.certificatenumber           as regnumber,
                c.submitteddatetime::date  as presentation_date,
                c.signeddatetime::date     as date_of_completion,
                c.signeddatetime::date     as date_of_return
            from kaveri.cc_applicationdetails c
            join kaveri.sromaster sr
              on c.kaverisrocode = sr.srocode
            join kaveri.districtmaster dsm
              on sr.districtcode = dsm.districtcode
            where c.signeddatetime between _fromdate and (_todate + interval '1 day')
              and (_districtcode = 0 or dsm.districtcode = _districtcode)
              and (_srocode = 0 or c.kaverisrocode = _srocode)
              and (
                    _documentnumber is null
                    or _documentnumber = ''
                    or c.applicationnumber = _documentnumber
                  )
        ),
        ccids as (
            select ccid from base
        ),
        presenter as (
            select
                b.applicationnumber,
                max(e.remittername) as presenter_name
            from base b
            join kaveri.ams_reg_epaymenttransdetails e
              on e.isdelete = false
             and (e.ccid = b.ccid or e.applicationnumber = b.applicationnumber)
            group by b.applicationnumber
        ),
        fees_reg as (
            select
                e.applicationnumber,
                sum(e.totalamount) as reg_fee
            from kaveri.ams_reg_epaymenttransdetails e
            join ccids c
              on c.ccid = e.ccid
            join kaveri.ams_reg_epaymentbankackdetails ack
              on ack.deptreferencecode = e.deptreferencecode
             and ack.paymentstatuscode in ('10700066','10700072')
            where e.isdelete = false
              and e.feerulecode in (
                    1, 3, 4, 5, 7, 8, 9, 13, 14, 15, 16, 17, 18, 19, 20,
                    23, 24, 25, 26, 27, 28, 30, 31, 34, 57, 63, 65, 88,
                    90, 93, 95, 97, 98, 102, 103, 106, 108, 109, 141
              )
            group by e.applicationnumber
        ),
        fees_copy as (
            select
                b.applicationnumber,
                sum(
                    case when rf.feeruleid in (23, 134, 135, 136, 137, 139, 140)
                         then rf.payableamount else 0 end
                ) as copy_fee
            from base b
            left join kaveri.cc_requiredfees rf
              on rf.ccid = b.ccid
             and rf.ispaid = true
            group by b.applicationnumber
        ),
		fees_stampduty as (
            select
                b.applicationnumber,
                sum(
                    case
                        when rf.feeruleid in (35,36,64,89,91,92,101,107,110,138)
                        then rf.payableamount
                        else 0
                    end
                ) as stampduty_fee
            from base b
            left join kaveri.cc_requiredfees rf
              on rf.ccid = b.ccid
             and rf.ispaid = true
            group by b.applicationnumber
        ),
        fees as (
            select
                b.applicationnumber,
                coalesce(fr.reg_fee, 0)  as reg_fee,
                coalesce(fc.copy_fee, 0) as copy_fee,
				coalesce(fs.stampduty_fee, 0) as stampduty_fee
            from base b
            left join fees_reg  fr on fr.applicationnumber = b.applicationnumber
            left join fees_copy fc on fc.applicationnumber = b.applicationnumber
			left join fees_stampduty fs on fc.applicationnumber = b.applicationnumber
        ),
        treasury as (
            select
                are2.ccid,
                sum(distinct ack.amount)            as treasury_amount,
                max(ack.transactiontimestamp::date) as treasury_date
            from kaveri.ams_reg_epaymenttransdetails are2
            join ccids c
              on c.ccid = are2.ccid
            join kaveri.ams_reg_epaymentbankackdetails ack
              on ack.deptreferencecode = are2.deptreferencecode
             and ack.paymentstatuscode in ('10700066','10700072')
            where are2.isdelete = false
            group by are2.ccid
        ),
        mutation_treasury as (
            select
                b.applicationnumber,
                sum(are2.totalamount)               as mutation_amount,
                max(ack.transactiontimestamp::date) as mutation_date
            from base b
            join kaveri.ams_reg_epaymenttransdetails are2
              on are2.isdelete = false
             and are2.feerulecode = 6
             and (
                    are2.ccid = b.ccid
                 or (
                        are2.applicationnumber is not null
                    and are2.applicationnumber = b.applicationnumber
                 )
              )
            join kaveri.ams_reg_epaymentbankackdetails ack
              on ack.deptreferencecode = are2.deptreferencecode
             and ack.paymentstatuscode in ('10700066','10700072')
            group by b.applicationnumber
        ),
        value as (
            select
                b.applicationnumber,
                null::numeric             as consideration,
                null::numeric             as market_value,
                'searches and inspection' as articlenamee
            from base b
        ),
        docs as (
            select
                s.applicationnumber,
                max(s.filepath)::text as copy_of_document
            from kaveri.signed_file_upload_details s
            group by s.applicationnumber
        ),
        final as (
            select
                --row_number() over (order by b.signeddatetime, b.regnumber) as slno,
                b.applicationnumber,
                b.presentation_date                  as date_of_presentation,
                pr.presenter_name                    as name_of_presenter,
                v.articlenamee                       as description_of_document,
                null::numeric                        as consideration,
                null::numeric                        as market_value,
                coalesce(f.stampduty_fee,0)                        as stamp_duty_a,
                null::numeric                        as cess_on_duty_b,
                null::numeric                        as surcharge_municipal_c,
                null::numeric                        as surcharge_taluk_d,
                null::numeric                        as total_duty_on_document_e,
                b.regnumber                          as number_in_register,
                b.bookid                             as which_book,
                null::text                           as volume_no,
                b.date_of_completion                     as date_of_completion,
                b.date_of_return                     as date_of_return,
                coalesce(f.reg_fee, 0)               as fees_for_registration_of_documents,
                coalesce(f.copy_fee, 0)              as fees_for_copies_granted,
                0::numeric                           as scanning_fees,
                null::numeric                        as other_stamp_duty,
                null::numeric                        as article_of_table_of_fees,
                coalesce(f.reg_fee, 0)
                + coalesce(f.copy_fee, 0) +coalesce(f.stampduty_fee,0)           as total_of_cols_14_15_16,
                t.treasury_amount                    as fees_remitted_to_treasury_amount,
                t.treasury_date                      as fees_remitted_to_treasury_date,
                mt.mutation_amount                   as daily_mutation_receipts,
                mt.mutation_date                     as mutation_fee_remitted_date,
                coalesce(f.reg_fee, 0)
                + coalesce(f.copy_fee, 0)
                + coalesce(mt.mutation_amount, 0)    as total_amount_collected,
                null::text                           as signature_of_registering_officer,
                null::text                           as remarks,
                b.districtname,
                b.sroname,
                d.copy_of_document
            from base b
            left join presenter         pr on pr.applicationnumber  = b.applicationnumber
            left join value             v  on v.applicationnumber   = b.applicationnumber
            left join fees              f  on f.applicationnumber   = b.applicationnumber
            left join treasury          t  on t.ccid                = b.ccid
            left join mutation_treasury mt on mt.applicationnumber = b.applicationnumber
            left join docs              d  on d.applicationnumber   = b.applicationnumber
        ),
        result as (
            select distinct
                f.districtname,
                f.sroname,
                null::text                                 as finalregistrationnumber,
                f.applicationnumber::varchar               as applicationnumber2,
                f.date_of_presentation::text               as presentationdatetime,
                f.name_of_presenter::text                  as presenter_name,
                f.description_of_document::text            as description_of_document,
                f.consideration                            as considerationamount,
                f.market_value                             as marketvalue,
                f.stamp_duty_a                             as stampduty,
                f.cess_on_duty_b                           as cess,
                f.surcharge_municipal_c                    as surcharge_duty_muncipal,
                f.surcharge_taluk_d                        as surcharge_duty_taluk,
                f.total_duty_on_document_e                 as total_duty,
                f.number_in_register::varchar              as documentnumber,
                f.which_book::text                         as bookid,
                f.volume_no::text                          as volumenumber,
                f.date_of_completion::text                 as dateofcompletion,
                f.date_of_return::text                     as dateofreturn,
                f.fees_for_registration_of_documents::text as registrationfees,
                f.fees_for_copies_granted                  as feescopygranted,
                f.scanning_fees                            as miscfees,
                f.other_stamp_duty                         as otherstampduty,
                f.article_of_table_of_fees                 as miscarticlefees,
                f.total_of_cols_14_15_16                   as total_fees,
                f.fees_remitted_to_treasury_amount         as treasury_fees,
                f.fees_remitted_to_treasury_date::text     as feedate_treasury,
                f.daily_mutation_receipts::text            as dailymutationreceipts,
                f.daily_mutation_receipts                  as mutationfees,
                f.mutation_fee_remitted_date::text         as mutationfeedate,
                null::text                                 as transmission_of_memorandum,
                null::text                                 as transmission_of_memoranda,
                f.total_amount_collected::bigint           as total_amount_collected,
                f.signature_of_registering_officer         as signature_of_register,
                f.remarks                                  as remarks,
                f.copy_of_document                         as copy_of_document
            from final f
        ),
        base_count as (
            select count(*)::bigint as totalcount from result
        )
        select
            r.*,
            bc.totalcount
        from result r
        cross join base_count bc
        order by dateofcompletion, documentnumber;

    end if;
end;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_ccreg_new(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_register_of_fees_statutory_ccreg_newtest(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_ccreg_newtest(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber text, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document text, considerationamount numeric, marketvalue numeric, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid text, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees text, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, total_amount_collected bigint, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
declare
    pageoffset integer := 0;
begin
    if pagenumber is null or pagesize is null then
        pagenumber := -1;
        pagesize   := -1;
    end if;

    pageoffset := (pagenumber - 1) * pagesize;

    if pagenumber <> -1 and pagesize <> -1 then

        return query
		
		select ag.districtname,ag.sroname,ag.finalregistrationnumber,ag.applicationnumber2,ag.presentationdatetime,ag.presenter_name,ag.description_of_document,ag.considerationamount,ag.marketvalue,ag.stampduty,ag.cess,ag.surcharge_duty_muncipal,ag.surcharge_duty_taluk,ag.total_duty,ag.documentnumber,ag.bookid,ag.volumenumber,ag.dateofcompletion,ag.dateofreturn,ag.registrationfees,ag.feescopygranted,ag.miscfees,ag.otherstampduty,ag.miscarticlefees,ag.total_fees,ag.treasury_fees,ag.feedate_treasury,ag.dailymutationreceipts,ag.mutationfees,ag.mutationfeedate,ag.transmission_of_memorandum,ag.transmission_of_memoranda,ag.total_amount_collected,ag.signature_of_register,ag.remarks,ag.copy_of_document,count(*) over()::bigint as totalcount from kaveri.revised_form_7_statutory_cc_reg ag
		join kaveri.cc_applicationdetails c on ag.applicationnumber2=c.applicationnumber
            join kaveri.sromaster sr
              on c.kaverisrocode = sr.srocode
            join kaveri.districtmaster dsm
              on sr.districtcode = dsm.districtcode
            where c.signeddatetime between _fromdate and (_todate + interval '1 day')
              and (_districtcode = 0 or dsm.districtcode = _districtcode)
              and (_srocode = 0 or c.kaverisrocode = _srocode)
              and (
                    _documentnumber is null
                    or _documentnumber = ''
                    or c.applicationnumber = _documentnumber
                  )
				 OFFSET PageOffset
                FETCH NEXT pagesize ROWS ONLY;
				
elsif pagenumber = -1 or  pagesize = -1 then

        return query
		
		select ag.districtname,ag.sroname,ag.finalregistrationnumber,ag.applicationnumber2,ag.presentationdatetime,ag.presenter_name,ag.description_of_document,ag.considerationamount,ag.marketvalue,ag.stampduty,ag.cess,ag.surcharge_duty_muncipal,ag.surcharge_duty_taluk,ag.total_duty,ag.documentnumber,ag.bookid,ag.volumenumber,ag.dateofcompletion,ag.dateofreturn,ag.registrationfees,ag.feescopygranted,ag.miscfees,ag.otherstampduty,ag.miscarticlefees,ag.total_fees,ag.treasury_fees,ag.feedate_treasury,ag.dailymutationreceipts,ag.mutationfees,ag.mutationfeedate,ag.transmission_of_memorandum,ag.transmission_of_memoranda,ag.total_amount_collected,ag.signature_of_register,ag.remarks,ag.copy_of_document,count(*) over()::bigint as totalcount from kaveri.revised_form_7_statutory_cc_reg ag
		join kaveri.cc_applicationdetails c on ag.applicationnumber2=c.applicationnumber
            join kaveri.sromaster sr
              on c.kaverisrocode = sr.srocode
            join kaveri.districtmaster dsm
              on sr.districtcode = dsm.districtcode
            where c.signeddatetime between _fromdate and (_todate + interval '1 day')
              and (_districtcode = 0 or dsm.districtcode = _districtcode)
              and (_srocode = 0 or c.kaverisrocode = _srocode)
              and (
                    _documentnumber is null
                    or _documentnumber = ''
                    or c.applicationnumber = _documentnumber
                  );
end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_ccreg_newtest(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_register_of_fees_statutory_ccreg_scheduler(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_ccreg_scheduler(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtcode integer, srocode integer, isregistrationcompleted boolean, registrationdatetime timestamp without time zone, districtname character varying, sroname character varying, finalregistrationnumber text, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document text, considerationamount numeric, marketvalue numeric, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid text, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees numeric, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, signature_of_register text, remarks text, copy_of_document text, currentstatus character varying)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if pagenumber <> -1 and pagesize <> -1 then
			return query
			with cte as (
			select  
					dsm.districtcode,
					cca.kaverisrocode::integer,
					true as isregistrationcompleted,
					a.applicationenddate,
					dsm.districtnamee::character varying as district,
					sr.sronamee::character varying as sroname,
					null::text as finalregistrationnumber,
					cca.applicationnumber::character varying,
					to_char(a.applicationenddate,'dd-MM-YYYY')::text as  signeddatetime,
					c.firstname::text||c.middlename::text||c.lastname::text  as Presentername,
					'CCSearch'::text as descriptionofdocument,
					null::numeric as considerationfees,
					null::numeric as marketvalue,
					sum(case when cr.feeruleid=36  then cr.payableamount else 0 end)::numeric stampduty,
					sum(case when cr.feeruleid=14  then cr.payableamount else 0 end)::numeric searchfee,
					null::numeric as muncipalsurcharge,
					null::numeric as taluksurcharge,
					 sum(case when cr.feeruleid=36  then payableamount else 0 end)+
					 sum(case when cr.feeruleid=14  then payableamount else 0 end)::numeric
					 as Total_duty,
					cca.certificatenumber::character varying as documentnumber,
					null::text as bookname,
					null::text as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY')::text dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY')::text dateofreturn,
					null::numeric as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount)::numeric as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',')::text as Challan_date,
					null::text as dailymutation_receipt,
					null::numeric as mutationfees,
					null::text as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					sg.filepath::text as copy_of_document,
					a.currentstatus
					from kaveri.cc_applicationdetails   cca
					  join kaveri.applicantapplicationdetails a on cca.applicationnumber=a.applicationnumber 
					  join kaveri.signed_file_upload_details sg on a.applicationnumber=sg.applicationnumber
					  join kaveri.sromaster sr on cca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=cca.userid  
					  left join kaveri.ams_reg_epaymenttransdetails amsre on cca.applicationnumber=amsre.applicationnumber 
					  join (select ccid,feeruleid,sum(payableamount) as payableamount  from kaveri.cc_requiredfees  
					  group by ccid,feeruleid)cr on cca.ccid=cr.ccid 
					 where 
					 
					 (a.applicationenddate between _fromdate
			 			and _todate + INTERVAL '1 day'  ) and 
					 
					 (

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			 and 
					 
					 (

                    CASE

                    WHEN _srocode <> 0 THEN  cca.kaverisrocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  cca.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
                and  a.currentstatus='CC109'
			
					group by dsm.districtnamee,sr.sronamee,cca.applicationnumber,sg.filepath,
					a.applicationenddate,c.firstname,c.middlename,c.lastname,
					cca.certificatenumber,a.applicationenddate,dsm.districtcode,
					cca.kaverisrocode,a.currentstatus)
			select * from cte
			
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
					
					
					
elsif pagenumber = -1 or  pagesize = -1 then  
			return query
			with cte as (
			select  
					dsm.districtcode,
					cca.kaverisrocode::integer,
					true as isregistrationcompleted,
					a.applicationenddate,
					dsm.districtnamee::character varying as district,
					sr.sronamee::character varying as sroname,
					null::text as finalregistrationnumber,
					cca.applicationnumber::character varying,
					to_char(a.applicationenddate,'dd-MM-YYYY')::text as  signeddatetime,
					c.firstname::text||c.middlename::text||c.lastname::text  as Presentername,
					'CCSearch'::text as descriptionofdocument,
					null::numeric as considerationfees,
					null::numeric as marketvalue,
					sum(case when cr.feeruleid=36  then cr.payableamount else 0 end)::numeric stampduty,
					sum(case when cr.feeruleid=14  then cr.payableamount else 0 end)::numeric searchfee,
					null::numeric as muncipalsurcharge,
					null::numeric as taluksurcharge,
					 sum(case when cr.feeruleid=36  then payableamount else 0 end)+
					 sum(case when cr.feeruleid=14  then payableamount else 0 end)::numeric
					 as Total_duty,
					cca.certificatenumber::character varying as documentnumber,
					null::text as bookname,
					null::text as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY')::text dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY')::text dateofreturn,
					null::numeric as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount)::numeric as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',')::text as Challan_date,
					null::text as dailymutation_receipt,
					null::numeric as mutationfees,
					null::text as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					sg.filepath::text as copy_of_document,
					a.currentstatus
					from kaveri.cc_applicationdetails   cca
					  join kaveri.applicantapplicationdetails a on cca.applicationnumber=a.applicationnumber 
					  join kaveri.signed_file_upload_details sg on a.applicationnumber=sg.applicationnumber
					  join kaveri.sromaster sr on cca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=cca.userid  
					  left join kaveri.ams_reg_epaymenttransdetails amsre on cca.applicationnumber=amsre.applicationnumber 
					  join (select ccid,feeruleid,sum(payableamount) as payableamount  from kaveri.cc_requiredfees  
					  group by ccid,feeruleid)cr on cca.ccid=cr.ccid 
					 where 
					 
					 (a.applicationenddate between _fromdate
			 			and _todate + INTERVAL '1 day'  ) and 
					 
					 (

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			 and 
					 
					 (

                    CASE

                    WHEN _srocode <> 0 THEN  cca.kaverisrocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  cca.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
                and  a.currentstatus='CC109'
			
					group by dsm.districtnamee,sr.sronamee,cca.applicationnumber,sg.filepath,
					a.applicationenddate,c.firstname,c.middlename,c.lastname,
					cca.certificatenumber,a.applicationenddate,dsm.districtcode,
					cca.kaverisrocode,a.currentstatus)
			select * from cte;
			
			
			
					

 end if;
		

 

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_ccreg_scheduler(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_register_of_fees_statutory_cntdata_2(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_cntdata_2(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
			
DECLARE
--PageOffset INTEGER := 0;
v_cnt bigint;
v_doccnt bigint;
v_eccnt bigint;
v_cccnt bigint;
v_otherfeecnt bigint;
BEGIN	

select     
	count(distinct finalregistrationnumber) as cnt into v_doccnt
			from  kaveri.documentmaster dm
			--join  kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber 
			--join kaveri.stamparticles sa on pm.stamparticlecode=sa.stamparticlecode 
			JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
			--join kaveri.booktypemaster b on dm.bookid=b.bookid 
			--left join kaveri.ams_reg_epaymenttransdetails amsreg on 
			--amsreg.applicationnumber = dm.applicationnumber and amsreg.isdelete=false 
			where 
			
			(dm.registrationdatetime between _fromdate	and _todate + INTERVAL '1 day'  )
			and 
			
			(

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			and
			
				(

                    CASE

                    WHEN _srocode <> 0 THEN  dm.srocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  dm.finalregistrationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
               and 
			    
			 dm.isregistrationcompleted=true;
			

select count(*) as cnt into v_cccnt
from kaveri.cc_applicationdetails   cca
					  join kaveri.applicantapplicationdetails a on cca.applicationnumber=a.applicationnumber 
					  --join kaveri.signed_file_upload_details sg on a.applicationnumber=sg.applicationnumber
					  join kaveri.sromaster sr on cca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  --join kaveri.citizenmaster c on c.citizenid=cca.userid  
					  --left join kaveri.ams_reg_epaymenttransdetails amsre on cca.applicationnumber=amsre.applicationnumber 
					  --join (select ccid,feeruleid,sum(payableamount) as payableamount  from kaveri.cc_requiredfees  
					 -- group by ccid,feeruleid)cr on cca.ccid=cr.ccid 
					 where 
					 (a.applicationenddate between _fromdate
			 			and _todate + INTERVAL '1 day'  ) and (CASE
						WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode
						ELSE TRUE
						end)
			 and (CASE
					WHEN _srocode <> 0 THEN  a.srocode = _srocode
					ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  cca.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
                and  a.currentstatus='CC109';
				

select count(*) as cnt into v_eccnt
 from kaveri.ec_applicationdetails   eca
					  join kaveri.applicantapplicationdetails a on eca.applicationnumber=a.applicationnumber
					  --join kaveri.signed_file_upload_details sg on a.applicationnumber=sg.applicationnumber
					  join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  --join kaveri.citizenmaster c on c.citizenid=eca.userid 
					  --left join kaveri.ams_reg_epaymenttransdetails amsre on eca.applicationnumber=amsre.applicationnumber 
					  --join  kaveri.ec_requiredfees er on eca.ecid=er.ecid 
					 where 
					 
					 (a.applicationenddate between _fromdate	and _todate + INTERVAL '1 day'  ) and 
					 (

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
				 and 
					 
					 (

                    CASE

                    WHEN _srocode <> 0 THEN  a.srocode = _srocode

                    ELSE TRUE

                    end

                    )
				 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  eca.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
                and  a.currentstatus='CE110';
				
 				
select count(*) as cnt into v_otherfeecnt 
from kaveri.otherfeesrequired o
			join kaveri.otherreceiptdetails othfee  on o.receiptid = othfee.receiptid
			join kaveri.departmentusers d on o.departmentuserid = d.userid
			 join kaveri.sromaster sm on sm.srocode=d.srocode
			 JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode 
			 where 
			 
			 (othfee.receiptdate between _fromdate	and _todate + INTERVAL '1 day'  ) and 
			 
			 (

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode=_districtcode 

                    ELSE TRUE

                    end

                    )
			 and 
			 (

                    CASE

                    WHEN _srocode <> 0 THEN  d.srocode=_srocode 

                    ELSE TRUE

                    end

                    )
			
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  o.applicationnumber=_documentnumber

                    ELSE TRUE

                    end

                    );
					
v_cnt:=v_doccnt+v_eccnt+v_cccnt+v_otherfeecnt;

return v_cnt;
				
	END;
$$;


