ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_cntdata_2_23012024(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying) OWNER TO postgres;

--
-- Name: fn_mis_daily_register_of_fees_statutory_docreg(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document character varying, considerationamount numeric, marketvalue bigint, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid character varying, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees numeric, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, total_amount_collected bigint, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
 
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
 
if pagenumber <> -1 and pagesize <> -1 then
 
			return query
			    with cte as (
				with dm as (
					select d2.districtnamee,d.applicationnumber, d.registrationdatetime, d.finalregistrationnumber, d.bookid, d.presentdatetime, d.srocode,s.sronamee,d.uploaddocdeedpath
					from kaveri.documentmaster d
					join kaveri.sromaster s on d.srocode = s.srocode
                    join kaveri.districtmaster d2 on d2.districtcode = s.districtcode
					where (d.registrationdatetime between _fromdate::date	and _todate::date + INTERVAL '1 day'  )and
					(CASE WHEN _districtcode <> 0 THEN  s.districtcode = _districtcode ELSE TRUE end)
					and(CASE WHEN _srocode <> 0 THEN  d.srocode = _srocode ELSE TRUE end)
					and d.bookid in (1,2,3,4)
					and isregistrationcompleted = true
				--     and registrationdatetime >= date '2025-08-01'
				--     and registrationdatetime < date '2025-09-01'
				--     and srocode = 171
				),
				success_txns as (
					select distinct e.deptreferencecode
					from kaveri.ams_reg_epaymenttransdetails e
					join kaveri.ams_reg_epaymentbankackdetails b on b.deptreferencecode = e.deptreferencecode
					where b.paymentstatuscode in ('10700066','10700072')
					  and e.isdelete = false
					  and e.applicationnumber in (select applicationnumber from dm)
				),
				pm as (
					select
						applicationnumber,
						sum(totalarea) as totalarea,
						coalesce(sum(sroconsideration),0) as consideration,
						coalesce(sum(sromarketvalue),0) as marketvalue
					from kaveri.propertymaster
					where applicationnumber in (select applicationnumber from dm)
					  --and totalarea <= 0.125
					group by applicationnumber
				),
				epay as (
					select
						e.applicationnumber,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (35,36,64,89,91,92,101,107,110,138)),0) as stampduty,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (59,100)),0) as cessduty,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109)),0) as feesforregistrationofdocs,
						coalesce(sum(e.totalamount) filter (where e.feerulecode = 2),0) as scanningfee,
						coalesce(sum(e.totalamount) filter (where e.feerulecode = 6),0) as mutationfee
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.applicationnumber in (select applicationnumber from dm)
					  and e.isdelete = false
					group by e.applicationnumber
				),
				surcharge as (
					select e.applicationnumber, sum(e.totalamount) as totalsurcharge
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.isdelete = false
					  and e.feerulecode in (58,99)
					  and e.applicationnumber in (select applicationnumber from dm)
					group by e.applicationnumber
				),
				has_taluk as (
					select pm.applicationnumber, bool_or(pnd.currentpropertytypeid = 60) as has_taluk
					from kaveri.propertymaster pm
					join kaveri.propertynumberdetails pnd on pnd.propertyid = pm.propertyid
					where pm.applicationnumber in (select applicationnumber from dm)
					group by pm.applicationnumber
				),
				bk as (
					select e.applicationnumber, sum(e.totalamount) as feesremittedtotreasury
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.isdelete = false
					  and e.applicationnumber in (select applicationnumber from dm)
					group by e.applicationnumber
				)
				select d.districtnamee,
					d.sronamee,
					null::varchar as finalregistrationnumber,
					d.applicationnumber as applicationnumber2,
					d.presentdatetime::text as presentationdatetime,
					pr.presenternamee as presenter_name,
					art.description_of_docs as description_of_document,
					pm.consideration::numeric as considerationamount,
					pm.marketvalue::bigint as marketvalue,
					ep.stampduty::numeric as stampduty,
					ep.cessduty::numeric as cess,
					case when h.has_taluk then 0 else coalesce(s.totalsurcharge,0) end::numeric as surcharge_duty_muncipal,
					case when h.has_taluk then coalesce(s.totalsurcharge,0) else 0 end::numeric as surcharge_duty_taluk,
--					total_duty::numeric,
					coalesce(ep.stampduty::numeric + ep.cessduty::numeric + s.totalsurcharge::numeric,0) as total_duty,
					d.finalregistrationnumber::varchar as documentnumber,
					d.bookid::varchar as bookid,
					null::text as volumenumber,
					d.registrationdatetime::text as dateofcompletion,
					d.registrationdatetime::text as dateofreturn,
					ep.feesforregistrationofdocs::numeric as registrationfees,
					null::numeric as feescopygranted,
					ep.scanningfee::numeric as miscfees,
					null::numeric as otherstampduty,
					null::numeric as miscarticlefees,
					(COALESCE(ep.feesforregistrationofdocs,0)
						+ COALESCE(ep.scanningfee,0))::numeric as total_fees, --sum
					bk.feesremittedtotreasury::numeric as treasury_fees,
					bklast.transactiondate::text as feedate_treasury,
					null::text as dailymutationreceipts,
					ep.mutationfee::numeric as mutationfees,
					mut.mutationfeeremittedtotreasurydate::text as mutationfeedate,
					ar.copiesofmemo::text as transmission_of_memorandum,
					--ar.officename as transmission_of_memoranda,
					ar.memoacceptingoffice::text as transmission_of_memoranda,
					  (coalesce(ep.stampduty,0)
					  + coalesce(ep.cessduty,0)
					  + coalesce(case when h.has_taluk then 0 else s.totalsurcharge end,0)
					  + coalesce(case when h.has_taluk then s.totalsurcharge else 0 end,0)
					  + coalesce(ep.feesforregistrationofdocs,0)
					  + coalesce(ep.scanningfee,0)
					  + coalesce(ep.mutationfee,0))::bigint as total_amount_collected,
					null::text as signature_of_register,
					null::text as remarks,
					--null::text as copy_of_document
					d.uploaddocdeedpath::text as copy_of_document
					--pm.totalarea,	
					--ar.memosentdate,
					--ar.memonumber,
					--ar.memoaccepteddate
				from dm d
				left join pm on pm.applicationnumber = d.applicationnumber
				left join epay ep on ep.applicationnumber = d.applicationnumber
				left join surcharge s on s.applicationnumber = d.applicationnumber
				left join has_taluk h on h.applicationnumber = d.applicationnumber
				left join bk on bk.applicationnumber = d.applicationnumber
				
				left join lateral (
					select b.amount as feesremittedtotreasury, b.transactiontimestamp::date as transactiondate
					from kaveri.ams_reg_epaymenttransdetails e2
					join kaveri.ams_reg_epaymentbankackdetails b on b.deptreferencecode = e2.deptreferencecode
					where e2.applicationnumber = d.applicationnumber
					  and e2.isdelete = false
					  and b.paymentstatuscode in ('10700066','10700072')
					order by b.transactiontimestamp desc
					limit 1
				) bklast on true
				
				left join lateral (
					select coalesce(nullif(p2.firstname,''), nullif(p1.firstname,''), p.firstname) as presenternamee
					from kaveri.partyinfo p
					left join kaveri.partyinfo p1 on p.partyid = p1.linkpartyid
					left join kaveri.partyinfo p2 on p1.partyid = p2.linkpartyid
					where p.applicationnumber = d.applicationnumber and p.ispresenter = true
					order by p.partyid
					limit 1
				) pr on true
				
				left join lateral (
					select s.articlenamee as description_of_docs
					from (
						select distinct stamparticlecode
						from kaveri.propertymaster
						where applicationnumber = d.applicationnumber
						order by stamparticlecode
						limit 1
					) pmx
					join kaveri.stamparticles s on s.stamparticlecode = pmx.stamparticlecode
				) art on true
				
				left join lateral (
					select min(t.inserteddatetime)::date as mutationfeeremittedtotreasurydate
					from kaveri.ams_reg_epaymenttransdetails t
					join success_txns st using (deptreferencecode)
					where t.applicationnumber = d.applicationnumber
					  and t.feerulecode = 6
					  and t.isdelete = false
				) mut on true
				
				left join lateral (
					select
						a.newapplicationnumber as copiesofmemo,
						a.memosentdatetime::date as memosentdate,
						a.memoaccepteddatetime::date as memoaccepteddate,
						d2.finalregistrationnumber as memonumber,
						s1.sronamee as officename,
						s2.sronamee as memoacceptingoffice
					from kaveri.anywhere_reg_log a
					left join kaveri.documentmaster d2 on d2.applicationnumber = a.newapplicationnumber
					left join kaveri.sromaster s1 on s1.srocode = a.srocode
					left join kaveri.sromaster s2 on s2.srocode = a.regsrocode
					where a.applicationnumber = d.applicationnumber
					order by a.memosentdatetime desc
					limit 1
				) ar on true
				order by d.finalregistrationnumber)
				
				select cte.*,
                count(*) over()::bigint as totalcount
                from cte
                OFFSET PageOffset
                FETCH NEXT pagesize ROWS ONLY;
 
 
elsif pagenumber = -1 or  pagesize = -1 then
 
		return query
					    with cte as (
				with dm as (
					select d2.districtnamee,d.applicationnumber, d.registrationdatetime, d.finalregistrationnumber, d.bookid, d.presentdatetime, d.srocode,s.sronamee,d.uploaddocdeedpath
					from kaveri.documentmaster d
					join kaveri.sromaster s on d.srocode = s.srocode
                    join kaveri.districtmaster d2 on d2.districtcode = s.districtcode
					where (d.registrationdatetime between _fromdate::date	and _todate::date + INTERVAL '1 day'  )and
					(CASE WHEN _districtcode <> 0 THEN  s.districtcode = _districtcode ELSE TRUE end)
					and(CASE WHEN _srocode <> 0 THEN  d.srocode = _srocode ELSE TRUE end)
					and d.bookid in (1,2,3,4)
					and isregistrationcompleted = true
				--     and registrationdatetime >= date '2025-08-01'
				--     and registrationdatetime < date '2025-09-01'
				--     and srocode = 171
				),
				success_txns as (
					select distinct e.deptreferencecode
					from kaveri.ams_reg_epaymenttransdetails e
					join kaveri.ams_reg_epaymentbankackdetails b on b.deptreferencecode = e.deptreferencecode
					where b.paymentstatuscode in ('10700066','10700072')
					  and e.isdelete = false
					  and e.applicationnumber in (select applicationnumber from dm)
				),
				pm as (
					select
						applicationnumber,
						sum(totalarea) as totalarea,
						coalesce(sum(sroconsideration),0) as consideration,
						coalesce(sum(sromarketvalue),0) as marketvalue
					from kaveri.propertymaster
					where applicationnumber in (select applicationnumber from dm)
					  --and totalarea <= 0.125
					group by applicationnumber
				),
				epay as (
					select
						e.applicationnumber,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (35,36,64,89,91,92,101,107,110,138)),0) as stampduty,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (59,100)),0) as cessduty,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109)),0) as feesforregistrationofdocs,
						coalesce(sum(e.totalamount) filter (where e.feerulecode = 2),0) as scanningfee,
						coalesce(sum(e.totalamount) filter (where e.feerulecode = 6),0) as mutationfee
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.applicationnumber in (select applicationnumber from dm)
					  and e.isdelete = false
					group by e.applicationnumber
				),
				surcharge as (
					select e.applicationnumber, sum(e.totalamount) as totalsurcharge
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.isdelete = false
					  and e.feerulecode in (58,99)
					  and e.applicationnumber in (select applicationnumber from dm)
					group by e.applicationnumber
				),
				has_taluk as (
					select pm.applicationnumber, bool_or(pnd.currentpropertytypeid = 60) as has_taluk
					from kaveri.propertymaster pm
					join kaveri.propertynumberdetails pnd on pnd.propertyid = pm.propertyid
					where pm.applicationnumber in (select applicationnumber from dm)
					group by pm.applicationnumber
				),
				bk as (
					select e.applicationnumber, sum(e.totalamount) as feesremittedtotreasury
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.isdelete = false
					  and e.applicationnumber in (select applicationnumber from dm)
					group by e.applicationnumber
				)
				select d.districtnamee,
					d.sronamee,
					null::varchar as finalregistrationnumber,
					d.applicationnumber as applicationnumber2,
					d.presentdatetime::text as presentationdatetime,
					pr.presenternamee as presenter_name,
					art.description_of_docs as description_of_document,
					pm.consideration::numeric as considerationamount,
					pm.marketvalue::bigint as marketvalue,
					ep.stampduty::numeric as stampduty,
					ep.cessduty::numeric as cess,
					case when h.has_taluk then 0 else coalesce(s.totalsurcharge,0) end::numeric as surcharge_duty_muncipal,
					case when h.has_taluk then coalesce(s.totalsurcharge,0) else 0 end::numeric as surcharge_duty_taluk,
--					coalesce(sum(e.totalamount) filter (where e.feerulecode in (35,36,64,89,91,92,101,107,110,138,58,59,99,100)),0) as total_duty
					coalesce(ep.stampduty::numeric + ep.cessduty::numeric + s.totalsurcharge::numeric,0) as total_duty,
					d.finalregistrationnumber::varchar as documentnumber,
					d.bookid::varchar as bookid,
					null::text as volumenumber,
					d.registrationdatetime::text as dateofcompletion,
					d.registrationdatetime::text as dateofreturn,
					ep.feesforregistrationofdocs::numeric as registrationfees,
					null::numeric as feescopygranted,
					ep.scanningfee::numeric as miscfees,
					null::numeric as otherstampduty,
					null::numeric as miscarticlefees,
					(COALESCE(ep.feesforregistrationofdocs,0)
						+ COALESCE(ep.scanningfee,0))::numeric as total_fees,
					bk.feesremittedtotreasury::numeric as treasury_fees,
					bklast.transactiondate::text as feedate_treasury,
					null::text as dailymutationreceipts,
					ep.mutationfee::numeric as mutationfees,
					mut.mutationfeeremittedtotreasurydate::text as mutationfeedate,
					ar.copiesofmemo::text as transmission_of_memorandum,
					--ar.officename as transmission_of_memoranda,
					ar.memoacceptingoffice::text as transmission_of_memoranda,
					  (coalesce(ep.stampduty,0)
					  + coalesce(ep.cessduty,0)
					  + coalesce(case when h.has_taluk then 0 else s.totalsurcharge end,0)
					  + coalesce(case when h.has_taluk then s.totalsurcharge else 0 end,0)
					  + coalesce(ep.feesforregistrationofdocs,0)
					  + coalesce(ep.scanningfee,0)
					  + coalesce(ep.mutationfee,0))::bigint as total_amount_collected,
					null::text as signature_of_register,
					null::text as remarks,
					d.uploaddocdeedpath::text as copy_of_document
					--null::text as copy_of_document
					--pm.totalarea,	
					--ar.memosentdate,
					--ar.memonumber,
					--ar.memoaccepteddate
				from dm d
				left join pm on pm.applicationnumber = d.applicationnumber
				left join epay ep on ep.applicationnumber = d.applicationnumber
				left join surcharge s on s.applicationnumber = d.applicationnumber
				left join has_taluk h on h.applicationnumber = d.applicationnumber
				left join bk on bk.applicationnumber = d.applicationnumber
				
				left join lateral (
					select b.amount as feesremittedtotreasury, b.transactiontimestamp::date as transactiondate
					from kaveri.ams_reg_epaymenttransdetails e2
					join kaveri.ams_reg_epaymentbankackdetails b on b.deptreferencecode = e2.deptreferencecode
					where e2.applicationnumber = d.applicationnumber
					  and e2.isdelete = false
					  and b.paymentstatuscode in ('10700066','10700072')
					order by b.transactiontimestamp desc
					limit 1
				) bklast on true
				
				left join lateral (
					select coalesce(nullif(p2.firstname,''), nullif(p1.firstname,''), p.firstname) as presenternamee
					from kaveri.partyinfo p
					left join kaveri.partyinfo p1 on p.partyid = p1.linkpartyid
					left join kaveri.partyinfo p2 on p1.partyid = p2.linkpartyid
					where p.applicationnumber = d.applicationnumber and p.ispresenter = true
					order by p.partyid
					limit 1
				) pr on true
				
				left join lateral (
					select s.articlenamee as description_of_docs
					from (
						select distinct stamparticlecode
						from kaveri.propertymaster
						where applicationnumber = d.applicationnumber
						order by stamparticlecode
						limit 1
					) pmx
					join kaveri.stamparticles s on s.stamparticlecode = pmx.stamparticlecode
				) art on true
				
				left join lateral (
					select min(t.inserteddatetime)::date as mutationfeeremittedtotreasurydate
					from kaveri.ams_reg_epaymenttransdetails t
					join success_txns st using (deptreferencecode)
					where t.applicationnumber = d.applicationnumber
					  and t.feerulecode = 6
					  and t.isdelete = false
				) mut on true
				
				left join lateral (
					select
						a.newapplicationnumber as copiesofmemo,
						a.memosentdatetime::date as memosentdate,
						a.memoaccepteddatetime::date as memoaccepteddate,
						d2.finalregistrationnumber as memonumber,
						s1.sronamee as officename,
						s2.sronamee as memoacceptingoffice
					from kaveri.anywhere_reg_log a
					left join kaveri.documentmaster d2 on d2.applicationnumber = a.newapplicationnumber
					left join kaveri.sromaster s1 on s1.srocode = a.srocode
					left join kaveri.sromaster s2 on s2.srocode = a.regsrocode
					where a.applicationnumber = d.applicationnumber
					order by a.memosentdatetime desc
					limit 1
				) ar on true
				order by d.finalregistrationnumber)
			 select
             cte.*,
             count(*) over()::bigint as totalcount
             from cte;
 
end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_register_of_fees_statutory_docreg_01122025(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg_01122025(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document character varying, considerationamount numeric, marketvalue bigint, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid character varying, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees numeric, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if pagenumber <> -1 and pagesize <> -1 then 

			return query
			with cte as (
				select 
				dsm.districtnamee,s.sronamee as sroname, rd.numberinregistered as finalregistrationnumber, rd.applicationnumber ,
				rd.presentdatetime::text as presentationdatetime,rd.presenternamee::text as presenter_name,rd.description_of_docs as description_of_document,
				rd.consideration as considerationamount, rd.marketvalue::bigint as marketvalue, rd.stampduty, rd.cessduty as cess, rd.muncipalsurchargeduty as surcharge_duty_muncipal,
				rd.talukaboardsurcharge as surcharge_duty_taluk, 
				null::numeric as total_duty, 
				rd.numberinregistered as documentnumber, dm.bookid::varchar, rd.volumneno as volumenumber,rd.dateofcompletion::text as dateofcompletion,
				rd.dateofreturn::text as dateofreturn, rd.feesforregistrationofdocs as registrationfees,
				null::numeric as feescopygranted,
				null::numeric as miscfees,
				rd.otherstampduty::numeric as otherstampduty,
				null::numeric as miscarticlefees, 
				null::numeric as total_fees, rd.feesremittedtotreasury::numeric as treasury_fees,rd.transactiondate::text as feedate_treasury,
				null as dailymutationreceipts,
				rd.mutationfee::numeric as mutationfees, rd.mutationfeeremittedtotreasurydate::text as mutationfeedate,
				null as transmission_of_memorandum,
				null as transmission_of_memoranda,
				rd.signatureofregisteringofficer as signature_of_register, rd.remarks,
				null as copy_of_document
				from 
				kaveri.revised_form_7_statutory_doc_reg rd
				join kaveri.documentmaster dm on rd.applicationnumber = dm.applicationnumber
				join kaveri.sromaster s on s.srocode = dm.srocode
				join kaveri.districtmaster dsm on dsm.districtcode = s.districtcode
				where 
				(CASE WHEN _documentnumber<>(case when (_documentnumber<>null and _documentnumber<>'') then _documentnumber else  '' end) THEN  rd.numberinregistered=_documentnumber ELSE TRUE end)
				and
				(rd.dateofcompletion between _fromdate	and _todate + INTERVAL '1 day'  )
				and 
				(CASE WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode ELSE TRUE end)
				and
				(CASE WHEN _srocode <> 0 THEN  dm.srocode = _srocode ELSE TRUE end)
			--				and dm.isregistrationcompleted=true
				)
				select * from cte
				right join (select null::bigint as total_rows) total_row on true
				OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

 elsif pagenumber = -1 or  pagesize = -1 then 
 
 		return query
			with cte as (
			select 
				dsm.districtnamee,s.sronamee as sroname, rd.numberinregistered as finalregistrationnumber, rd.applicationnumber ,
				rd.presentdatetime::text as presentationdatetime,rd.presenternamee::text as presenter_name,rd.description_of_docs as description_of_document,
				rd.consideration as considerationamount, rd.marketvalue::bigint as marketvalue, rd.stampduty, rd.cessduty as cess, rd.muncipalsurchargeduty as surcharge_duty_muncipal,
				rd.talukaboardsurcharge as surcharge_duty_taluk, 
				null::numeric as total_duty, 
				rd.numberinregistered as documentnumber, dm.bookid::varchar, rd.volumneno as volumenumber,rd.dateofcompletion::text as dateofcompletion,
				rd.dateofreturn::text as dateofreturn, rd.feesforregistrationofdocs as registrationfees,
				null::numeric as feescopygranted,
				null::numeric as miscfees,
				rd.otherstampduty::numeric as otherstampduty,
				null::numeric as miscarticlefees, 
				null::numeric as total_fees, rd.feesremittedtotreasury::numeric as treasury_fees,rd.transactiondate::text as feedate_treasury,
				null as dailymutationreceipts,
				rd.mutationfee::numeric as mutationfees, rd.mutationfeeremittedtotreasurydate::text as mutationfeedate,
				null as transmission_of_memorandum,
				null as transmission_of_memoranda,
				rd.signatureofregisteringofficer as signature_of_register, rd.remarks,
				null as copy_of_document
				from 
				kaveri.revised_form_7_statutory_doc_reg rd
				join kaveri.documentmaster dm on rd.applicationnumber = dm.applicationnumber
				join kaveri.sromaster s on s.srocode = dm.srocode
				join kaveri.districtmaster dsm on dsm.districtcode = s.districtcode
				where 
				(CASE WHEN _documentnumber<>(case when (_documentnumber<>null and _documentnumber<>'') then _documentnumber else  '' end) THEN  rd.numberinregistered=_documentnumber ELSE TRUE end)
				and
				(rd.dateofcompletion between _fromdate	and _todate + INTERVAL '1 day'  )
				and 
				(CASE WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode ELSE TRUE end)
				and
				(CASE WHEN _srocode <> 0 THEN  dm.srocode = _srocode ELSE TRUE end)
				
--				and dm.isregistrationcompleted=true
			)
			select * from cte
			right join (select null::bigint as total_rows) total_row on true;
end if;
END;
$$;


