						sum(totalarea) as totalarea,
						coalesce(sum(sroconsideration),0) as consideration,
						coalesce(sum(sromarketvalue),0) as marketvalue
					from kaveri.propertymaster
					where applicationnumber in (select applicationnumber from dm)
					  --and totalarea <= 0.125
					group by applicationnumber
				),
				epay as (
					select
						e.applicationnumber,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (35,36,64,89,91,92,101,107,110,138)),0) as stampduty,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (59,100)),0) as cessduty,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109)),0) as feesforregistrationofdocs,
						coalesce(sum(e.totalamount) filter (where e.feerulecode = 2),0) as scanningfee,
						coalesce(sum(e.totalamount) filter (where e.feerulecode = 6),0) as mutationfee
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.applicationnumber in (select applicationnumber from dm)
					  and e.isdelete = false
					group by e.applicationnumber
				),
				surcharge as (
					select e.applicationnumber, sum(e.totalamount) as totalsurcharge
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.isdelete = false
					  and e.feerulecode in (58,99)
					  and e.applicationnumber in (select applicationnumber from dm)
					group by e.applicationnumber
				),
				has_taluk as (
					select pm.applicationnumber, bool_or(pnd.currentpropertytypeid = 60) as has_taluk
					from kaveri.propertymaster pm
					join kaveri.propertynumberdetails pnd on pnd.propertyid = pm.propertyid
					where pm.applicationnumber in (select applicationnumber from dm)
					group by pm.applicationnumber
				),
				bk as (
					select e.applicationnumber, sum(e.totalamount) as feesremittedtotreasury
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.isdelete = false
					  and e.applicationnumber in (select applicationnumber from dm)
					group by e.applicationnumber
				)
				select d.districtnamee,
					d.sronamee,
					null::varchar as finalregistrationnumber,
					d.applicationnumber as applicationnumber2,
					d.presentdatetime::text as presentationdatetime,
					pr.presenternamee as presenter_name,
					art.description_of_docs as description_of_document,
					pm.consideration::numeric as considerationamount,
					pm.marketvalue::bigint as marketvalue,
					ep.stampduty::numeric as stampduty,
					ep.cessduty::numeric as cess,
					case when h.has_taluk then 0 else coalesce(s.totalsurcharge,0) end::numeric as surcharge_duty_muncipal,
					case when h.has_taluk then coalesce(s.totalsurcharge,0) else 0 end::numeric as surcharge_duty_taluk,
--					coalesce(sum(e.totalamount) filter (where e.feerulecode in (35,36,64,89,91,92,101,107,110,138,58,59,99,100)),0) as total_duty
					coalesce(ep.stampduty::numeric + ep.cessduty::numeric + s.totalsurcharge::numeric,0) as total_duty,
					d.finalregistrationnumber::varchar as documentnumber,
					d.bookid::varchar as bookid,
					null::text as volumenumber,
					d.registrationdatetime::text as dateofcompletion,
					d.registrationdatetime::text as dateofreturn,
					ep.feesforregistrationofdocs::numeric as registrationfees,
					null::numeric as feescopygranted,
					ep.scanningfee::numeric as miscfees,
					null::numeric as otherstampduty,
					null::numeric as miscarticlefees,
					(COALESCE(ep.feesforregistrationofdocs,0)
						+ COALESCE(ep.scanningfee,0))::numeric as total_fees,
					bk.feesremittedtotreasury::numeric as treasury_fees,
					bklast.transactiondate::text as feedate_treasury,
					null::text as dailymutationreceipts,
					ep.mutationfee::numeric as mutationfees,
					mut.mutationfeeremittedtotreasurydate::text as mutationfeedate,
					ar.copiesofmemo::text as transmission_of_memorandum,
					--ar.officename as transmission_of_memoranda,
					ar.memoacceptingoffice::text as transmission_of_memoranda,
					  (coalesce(ep.stampduty,0)
					  + coalesce(ep.cessduty,0)
					  + coalesce(case when h.has_taluk then 0 else s.totalsurcharge end,0)
					  + coalesce(case when h.has_taluk then s.totalsurcharge else 0 end,0)
					  + coalesce(ep.feesforregistrationofdocs,0)
					  + coalesce(ep.scanningfee,0)
					  + coalesce(ep.mutationfee,0))::bigint as total_amount_collected,
					null::text as signature_of_register,
					null::text as remarks,
					null::text as copy_of_document
					--pm.totalarea,	
					--ar.memosentdate,
					--ar.memonumber,
					--ar.memoaccepteddate
				from dm d
				left join pm on pm.applicationnumber = d.applicationnumber
				left join epay ep on ep.applicationnumber = d.applicationnumber
				left join surcharge s on s.applicationnumber = d.applicationnumber
				left join has_taluk h on h.applicationnumber = d.applicationnumber
				left join bk on bk.applicationnumber = d.applicationnumber
				
				left join lateral (
					select b.amount as feesremittedtotreasury, b.transactiontimestamp::date as transactiondate
					from kaveri.ams_reg_epaymenttransdetails e2
					join kaveri.ams_reg_epaymentbankackdetails b on b.deptreferencecode = e2.deptreferencecode
					where e2.applicationnumber = d.applicationnumber
					  and e2.isdelete = false
					  and b.paymentstatuscode in ('10700066','10700072')
					order by b.transactiontimestamp desc
					limit 1
				) bklast on true
				
				left join lateral (
					select coalesce(nullif(p2.firstname,''), nullif(p1.firstname,''), p.firstname) as presenternamee
					from kaveri.partyinfo p
					left join kaveri.partyinfo p1 on p.partyid = p1.linkpartyid
					left join kaveri.partyinfo p2 on p1.partyid = p2.linkpartyid
					where p.applicationnumber = d.applicationnumber and p.ispresenter = true
					order by p.partyid
					limit 1
				) pr on true
				
				left join lateral (
					select s.articlenamee as description_of_docs
					from (
						select distinct stamparticlecode
						from kaveri.propertymaster
						where applicationnumber = d.applicationnumber
						order by stamparticlecode
						limit 1
					) pmx
					join kaveri.stamparticles s on s.stamparticlecode = pmx.stamparticlecode
				) art on true
				
				left join lateral (
					select min(t.inserteddatetime)::date as mutationfeeremittedtotreasurydate
					from kaveri.ams_reg_epaymenttransdetails t
					join success_txns st using (deptreferencecode)
					where t.applicationnumber = d.applicationnumber
					  and t.feerulecode = 6
					  and t.isdelete = false
				) mut on true
				
				left join lateral (
					select
						a.newapplicationnumber as copiesofmemo,
						a.memosentdatetime::date as memosentdate,
						a.memoaccepteddatetime::date as memoaccepteddate,
						d2.finalregistrationnumber as memonumber,
						s1.sronamee as officename,
						s2.sronamee as memoacceptingoffice
					from kaveri.anywhere_reg_log a
					left join kaveri.documentmaster d2 on d2.applicationnumber = a.newapplicationnumber
					left join kaveri.sromaster s1 on s1.srocode = a.srocode
					left join kaveri.sromaster s2 on s2.srocode = a.regsrocode
					where a.applicationnumber = d.applicationnumber
					order by a.memosentdatetime desc
					limit 1
				) ar on true
				order by d.finalregistrationnumber)
			 select
             cte.*,
             count(*) over()::bigint as totalcount
             from cte;
 
end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg_1(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_register_of_fees_statutory_docreg_10092025(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg_10092025(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document character varying, considerationamount numeric, marketvalue bigint, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid character varying, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees numeric, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if pagenumber <> -1 and pagesize <> -1 then 

			return query
			with cte as (with a as ( select     
			dsm.districtnamee,
			sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,
			to_char(dm.presentdatetime,'dd-MM-YYYY') presentdate,
			(select 
			string_agg(distinct (coalesce(firstname,' ')||coalesce(middlename,' ')|| 
			coalesce(lastname,' ')::text),',') 
			from kaveri.partyinfo where applicationnumber=dm.applicationnumber  
			and ispresenter is true group by applicationnumber)as presentername ,
			--pi1.presentername,
			sa.articlenamee AS descriptionofdocument, 
			max(pm.sroconsideration) as consideration_fees,
			max(pm.sromarketvalue) as marketvalue,
			pm.propertytypeid ,
			case when dm.finalregistrationnumber is not null
			then dm.finalregistrationnumber else dm.pendingdocumentnumber end documentnumber,
			b.booknameenglish ,
			null  as volumenumber,
			(select sum(amsreg.totalamount)
			from kaveri.ams_reg_epaymenttransdetails amsreg where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false) as Treasury_amount,
			(select to_char(amsreg.inserteddatetime,'dd-MM-yyyy')
			from kaveri.ams_reg_epaymenttransdetails amsreg where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false limit 1)  as Challan_date ,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofcompletion,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofreturn,
			dm.uploaddocdeedpath as copy_of_document

			from  kaveri.documentmaster dm
			join  kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber 
			join kaveri.stamparticles sa on pm.stamparticlecode=sa.stamparticlecode 
			JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
			join kaveri.booktypemaster b on dm.bookid=b.bookid 
			--left join kaveri.ams_reg_epaymenttransdetails amsreg on 
			--amsreg.applicationnumber = dm.applicationnumber and amsreg.isdelete=false  
			where 
			
			(dm.registrationdatetime between _fromdate	and _todate + INTERVAL '1 day'  )
			and 
			
			(

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			and
			
				(

                    CASE

                    WHEN _srocode <> 0 THEN  dm.srocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  dm.finalregistrationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
               and 
			    
			 dm.isregistrationcompleted=true
			 group by dsm.districtnamee,sm.sronamee,dm.finalregistrationnumber,dm.applicationnumber,
			 sa.articlenamee,dm.pendingdocumentnumber,b.booknameenglish,
			 --,booknameenglish,
			dm.registrationdatetime,dm.uploaddocdeedpath,dm.presentdatetime,pm.propertytypeid	)

			select a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) stampduty,
			sum(case when fr.feerulecode=59  then amountpaid else 0 end) cess,
			sum(case when a.propertytypeid=28 and fr.feerulecode=58 then amountpaid else 0 end ) as municipalsurcharge,
			sum(case when a.propertytypeid=17 and fr.feerulecode=58 then amountpaid else 0 end ) as taluksurcharge,
			sum(case when fr.feerulecode in (36,58,59)  then amountpaid else 0 end)  as Total_duty,
			a.documentnumber,a.booknameenglish,a.volumenumber,
			a.dateofcompletion,a.dateofreturn,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end) registrationfees,
			sum(case when fr.feerulecode=41 then amountpaid else 0 end) as feesforcopies,
			sum(case when fr.feerulecode=2 then amountpaid else 0 end) miscelaneousfees,
			sum(case when fr.feerulecode in (34,91)then amountpaid else 0 end) otherstampduty,
			NULL::numeric miscellaneous_article_fees,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=41 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=2 then amountpaid else 0 end)+
			sum(case when fr.feerulecode  in (34,91)then amountpaid else 0 end) Total_fees2,
			a.Treasury_amount,
			a.Challan_date,
			string_agg(distinct (case when fr.feerulecode=6 then r.receiptnumber::text  else ' ' end ),' ')as dailymutationreceipts,
			sum(case when fr.feerulecode=6 then fr.amountpaid else 0 end) mutationfees,
			string_agg(distinct ( case when fr.feerulecode=6 then to_char(r.dateofreceipt,'DD-MM-YYYY')  else ' ' end ),' ')as mutationfeedate,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			a.copy_of_document

			from 
			a
			left join 	kaveri.feesrequired fr on a.applicationnumber=fr.applicationnumber
			left join kaveri.receiptmaster r on fr.receiptid=r.receiptid
			
			group by a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,
			a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			a.documentnumber,a.booknameenglish,
			a.volumenumber,a.Treasury_amount,
			a.Challan_date,a.dateofcompletion,a.dateofreturn,a.copy_of_document,a.propertytypeid
			)
			select * from cte
			right join (select null::bigint as total_rows) total_row on true
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

 elsif pagenumber = -1 or  pagesize = -1 then 
 
 		return query
			with cte as (with a as ( select     
			dsm.districtnamee,
			sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,
			to_char(dm.presentdatetime,'dd-MM-YYYY') presentdate,
			(select 
			string_agg(distinct (coalesce(firstname,' ')||coalesce(middlename,' ')|| 
			coalesce(lastname,' ')::text),',') 
			from kaveri.partyinfo where applicationnumber=dm.applicationnumber  
			and ispresenter is true group by applicationnumber)as presentername ,
			--pi1.presentername,
			sa.articlenamee AS descriptionofdocument, 
			max(pm.sroconsideration) as consideration_fees,
			max(pm.sromarketvalue) as marketvalue,
			pm.propertytypeid ,
			case when dm.finalregistrationnumber is not null
			then dm.finalregistrationnumber else dm.pendingdocumentnumber end documentnumber,
			b.booknameenglish ,
			null  as volumenumber,
			(select sum(amsreg.totalamount)
			from kaveri.ams_reg_epaymenttransdetails amsreg where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false) as Treasury_amount,
			(select to_char(amsreg.inserteddatetime,'dd-MM-yyyy')
			from kaveri.ams_reg_epaymenttransdetails amsreg where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false limit 1)  as Challan_date ,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofcompletion,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofreturn,
			dm.uploaddocdeedpath as copy_of_document

			from  kaveri.documentmaster dm
			join  kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber 
			join kaveri.stamparticles sa on pm.stamparticlecode=sa.stamparticlecode 
			JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
			join kaveri.booktypemaster b on dm.bookid=b.bookid 
			--left join kaveri.ams_reg_epaymenttransdetails amsreg on 
			--amsreg.applicationnumber = dm.applicationnumber and amsreg.isdelete=false 
			where 
			
			(dm.registrationdatetime between _fromdate	and _todate + INTERVAL '1 day'  )
			and 
			
			(

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			and
			
				(

                    CASE

                    WHEN _srocode <> 0 THEN  dm.srocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  dm.finalregistrationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
               and 
			    
			 dm.isregistrationcompleted=true
			 group by dsm.districtnamee,sm.sronamee,dm.finalregistrationnumber,dm.applicationnumber,
			 sa.articlenamee,dm.pendingdocumentnumber,b.booknameenglish,
			 --,booknameenglish,
			dm.registrationdatetime,dm.uploaddocdeedpath,dm.presentdatetime,pm.propertytypeid	)

			select a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) stampduty,
			sum(case when fr.feerulecode=59  then amountpaid else 0 end) cess,
			sum(case when a.propertytypeid=28 and fr.feerulecode=58 then amountpaid else 0 end ) as municipalsurcharge,
			sum(case when a.propertytypeid=17 and fr.feerulecode=58 then amountpaid else 0 end ) as taluksurcharge,
			sum(case when fr.feerulecode in (36,58,59)  then amountpaid else 0 end)  as Total_duty,
			a.documentnumber,a.booknameenglish,a.volumenumber,
			a.dateofcompletion,a.dateofreturn,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end) registrationfees,
			sum(case when fr.feerulecode=41 then amountpaid else 0 end) as feesforcopies,
			sum(case when fr.feerulecode=2 then amountpaid else 0 end) miscelaneousfees,
			sum(case when fr.feerulecode in (34,91)then amountpaid else 0 end) otherstampduty,
			NULL::numeric miscellaneous_article_fees,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=41 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=2 then amountpaid else 0 end)+
			sum(case when fr.feerulecode  in (34,91)then amountpaid else 0 end) Total_fees2,
			a.Treasury_amount,
			a.Challan_date,
			string_agg(distinct (case when fr.feerulecode=6 then r.receiptnumber::text  else ' ' end ),' ')as dailymutationreceipts,
			sum(case when fr.feerulecode=6 then fr.amountpaid else 0 end) mutationfees,
			string_agg(distinct ( case when fr.feerulecode=6 then to_char(r.dateofreceipt,'DD-MM-YYYY')  else ' ' end ),' ')as mutationfeedate,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			a.copy_of_document

			from 
			a
			left join 	kaveri.feesrequired fr on a.applicationnumber=fr.applicationnumber
			left join kaveri.receiptmaster r on fr.receiptid=r.receiptid
			
			group by a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,
			a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			a.documentnumber,a.booknameenglish,
			a.volumenumber,a.Treasury_amount,
			a.Challan_date,a.dateofcompletion,a.dateofreturn,a.copy_of_document,a.propertytypeid
			)
			select * from cte
			right join (select null::bigint as total_rows) total_row on true;
			
 
 
 
 end if;
		

 

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg_10092025(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_register_of_fees_statutory_docreg_20260312_test(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: manjunathswamy
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg_20260312_test(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document character varying, considerationamount numeric, marketvalue bigint, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid character varying, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees numeric, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, total_amount_collected bigint, grand_total bigint, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    PageOffset INTEGER := 0;
BEGIN
    PageOffset := ((pagenumber - 1) * pagesize);

    IF pagenumber <> -1 AND pagesize <> -1 THEN

        RETURN QUERY
        WITH cte AS (
            WITH dm AS (
                SELECT
                    d2.districtnamee,
                    d.applicationnumber,
                    d.registrationdatetime,
                    d.finalregistrationnumber,
                    d.bookid,
                    d.presentdatetime,
                    d.srocode,
                    s.sronamee
                FROM kaveri.documentmaster d
                JOIN kaveri.sromaster s
                    ON d.srocode = s.srocode
                JOIN kaveri.districtmaster d2
                    ON d2.districtcode = s.districtcode
                WHERE d.registrationdatetime BETWEEN _fromdate::date
                                                  AND _todate::date + INTERVAL '1 day'
                  AND (CASE WHEN _districtcode <> 0 THEN s.districtcode = _districtcode ELSE TRUE END)
                  AND (CASE WHEN _srocode <> 0 THEN d.srocode = _srocode ELSE TRUE END)
                  AND d.bookid IN (1,2,3,4,11)
                  AND d.isregistrationcompleted = true
            ),
            success_txns AS (
                SELECT DISTINCT e.deptreferencecode
                FROM kaveri.ams_reg_epaymenttransdetails e
                JOIN kaveri.ams_reg_epaymentbankackdetails b
                    ON b.deptreferencecode = e.deptreferencecode
                WHERE b.paymentstatuscode IN ('10700066','10700072')
                  AND e.isdelete = false
                  AND e.applicationnumber IN (SELECT applicationnumber FROM dm)
            ),
            pm AS (
                SELECT
                    applicationnumber,
                    SUM(totalarea) AS totalarea,
                    COALESCE(SUM(sroconsideration),0) AS consideration,
                    COALESCE(SUM(sromarketvalue),0) AS marketvalue
                FROM kaveri.propertymaster
                WHERE applicationnumber IN (SELECT applicationnumber FROM dm)
                GROUP BY applicationnumber
            ),
            epay AS (
                SELECT
                    e.applicationnumber,
                    COALESCE(SUM(e.totalamount) FILTER (
                        WHERE e.feerulecode IN (35,36,64,89,91,92,101,107,110,138)
                    ),0) AS stampduty,
                    COALESCE(SUM(e.totalamount) FILTER (
                        WHERE e.feerulecode IN (59,100)
                    ),0) AS cessduty,
                    COALESCE(SUM(e.totalamount) FILTER (
                        WHERE e.feerulecode IN (
                            1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,
                            27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,
                            103,106,108,109
                        )
                    ),0) AS feesforregistrationofdocs,
                    COALESCE(SUM(e.totalamount) FILTER (WHERE e.feerulecode = 2),0) AS scanningfee,
                    COALESCE(SUM(e.totalamount) FILTER (WHERE e.feerulecode = 6),0) AS mutationfee
                FROM kaveri.ams_reg_epaymenttransdetails e
                JOIN success_txns s USING (deptreferencecode)
                WHERE e.applicationnumber IN (SELECT applicationnumber FROM dm)
                  AND e.isdelete = false
                GROUP BY e.applicationnumber
            ),
            surcharge AS (
                SELECT
                    e.applicationnumber,
                    SUM(e.totalamount) AS totalsurcharge
                FROM kaveri.ams_reg_epaymenttransdetails e
                JOIN success_txns s USING (deptreferencecode)
                WHERE e.isdelete = false
                  AND e.feerulecode IN (58,99)
                  AND e.applicationnumber IN (SELECT applicationnumber FROM dm)
                GROUP BY e.applicationnumber
            ),
            has_taluk AS (
                SELECT
                    pm.applicationnumber,
                    BOOL_OR(pnd.currentpropertytypeid = 60) AS has_taluk
                FROM kaveri.propertymaster pm
                JOIN kaveri.propertynumberdetails pnd
                    ON pnd.propertyid = pm.propertyid
                WHERE pm.applicationnumber IN (SELECT applicationnumber FROM dm)
                GROUP BY pm.applicationnumber
            ),
            bk AS (
                SELECT
                    e.applicationnumber,
                    SUM(e.totalamount) AS feesremittedtotreasury
                FROM kaveri.ams_reg_epaymenttransdetails e
                JOIN success_txns s USING (deptreferencecode)
                WHERE e.isdelete = false
                  AND e.applicationnumber IN (SELECT applicationnumber FROM dm)
                GROUP BY e.applicationnumber
            )
            SELECT
                d.districtnamee AS districtname,
                d.sronamee AS sroname,
                NULL::varchar AS finalregistrationnumber,
                d.applicationnumber AS applicationnumber2,
                d.presentdatetime::text AS presentationdatetime,
                pr.presenternamee AS presenter_name,
                art.description_of_docs AS description_of_document,
                pm.consideration::numeric AS considerationamount,
                pm.marketvalue::bigint AS marketvalue,
                ep.stampduty::numeric AS stampduty,
                ep.cessduty::numeric AS cess,
                CASE
                    WHEN h.has_taluk THEN 0
                    ELSE COALESCE(s.totalsurcharge,0)
                END::numeric AS surcharge_duty_muncipal,
                CASE
                    WHEN h.has_taluk THEN COALESCE(s.totalsurcharge,0)
                    ELSE 0
                END::numeric AS surcharge_duty_taluk,
                COALESCE(
                    ep.stampduty::numeric
                    + ep.cessduty::numeric
                    + s.totalsurcharge::numeric,
                    0
                ) AS total_duty,
                d.finalregistrationnumber::varchar AS documentnumber,
                d.bookid::varchar AS bookid,
                NULL::text AS volumenumber,
                d.registrationdatetime::text AS dateofcompletion,
                d.registrationdatetime::text AS dateofreturn,
                ep.feesforregistrationofdocs::numeric AS registrationfees,
                NULL::numeric AS feescopygranted,
                ep.scanningfee::numeric AS miscfees,
                NULL::numeric AS otherstampduty,
                NULL::numeric AS miscarticlefees,
                (
                    COALESCE(ep.feesforregistrationofdocs,0)
                    + COALESCE(ep.scanningfee,0)
                )::numeric AS total_fees,
                bk.feesremittedtotreasury::numeric AS treasury_fees,
                bklast.transactiondate::text AS feedate_treasury,
                NULL::text AS dailymutationreceipts,
                ep.mutationfee::numeric AS mutationfees,
                mut.mutationfeeremittedtotreasurydate::text AS mutationfeedate,
                ar.copiesofmemo::text AS transmission_of_memorandum,
                ar.memoacceptingoffice::text AS transmission_of_memoranda,
                (
                    COALESCE(ep.stampduty,0)
                    + COALESCE(ep.cessduty,0)
                    + COALESCE(CASE WHEN h.has_taluk THEN 0 ELSE s.totalsurcharge END,0)
                    + COALESCE(CASE WHEN h.has_taluk THEN s.totalsurcharge ELSE 0 END,0)
                    + COALESCE(ep.feesforregistrationofdocs,0)
                    + COALESCE(ep.scanningfee,0)
                    + COALESCE(ep.mutationfee,0)
                )::bigint AS total_amount_collected,
                NULL::text AS signature_of_register,
                NULL::text AS remarks,
                NULL::text AS copy_of_document
            FROM dm d
            LEFT JOIN pm
                ON pm.applicationnumber = d.applicationnumber
            LEFT JOIN epay ep
                ON ep.applicationnumber = d.applicationnumber
            LEFT JOIN surcharge s
                ON s.applicationnumber = d.applicationnumber
            LEFT JOIN has_taluk h
                ON h.applicationnumber = d.applicationnumber
            LEFT JOIN bk
                ON bk.applicationnumber = d.applicationnumber
            LEFT JOIN LATERAL (
                SELECT
                    b.amount AS feesremittedtotreasury,
                    b.transactiontimestamp::date AS transactiondate
                FROM kaveri.ams_reg_epaymenttransdetails e2
                JOIN kaveri.ams_reg_epaymentbankackdetails b
                    ON b.deptreferencecode = e2.deptreferencecode
                WHERE e2.applicationnumber = d.applicationnumber
                  AND e2.isdelete = false
                  AND b.paymentstatuscode IN ('10700066','10700072')
                ORDER BY b.transactiontimestamp DESC
                LIMIT 1
            ) bklast ON true
            LEFT JOIN LATERAL (
                SELECT
                    COALESCE(NULLIF(p2.firstname,''), NULLIF(p1.firstname,''), p.firstname) AS presenternamee
                FROM kaveri.partyinfo p
                LEFT JOIN kaveri.partyinfo p1
                    ON p.partyid = p1.linkpartyid
                LEFT JOIN kaveri.partyinfo p2
                    ON p1.partyid = p2.linkpartyid
                WHERE p.applicationnumber = d.applicationnumber
                  AND p.ispresenter = true
                ORDER BY p.partyid
                LIMIT 1
            ) pr ON true
            LEFT JOIN LATERAL (
                SELECT
                    s.articlenamee AS description_of_docs
                FROM (
                    SELECT DISTINCT stamparticlecode
                    FROM kaveri.propertymaster
                    WHERE applicationnumber = d.applicationnumber
                    ORDER BY stamparticlecode
                    LIMIT 1
                ) pmx
                JOIN kaveri.stamparticles s
                    ON s.stamparticlecode = pmx.stamparticlecode
            ) art ON true
            LEFT JOIN LATERAL (
                SELECT
                    MIN(t.inserteddatetime)::date AS mutationfeeremittedtotreasurydate
                FROM kaveri.ams_reg_epaymenttransdetails t
                JOIN success_txns st USING (deptreferencecode)
                WHERE t.applicationnumber = d.applicationnumber
                  AND t.feerulecode = 6
                  AND t.isdelete = false
            ) mut ON true
            LEFT JOIN LATERAL (
                SELECT
                    a.newapplicationnumber AS copiesofmemo,
                    a.memosentdatetime::date AS memosentdate,
                    a.memoaccepteddatetime::date AS memoaccepteddate,
                    d2.finalregistrationnumber AS memonumber,
                    s1.sronamee AS officename,
                    s2.sronamee AS memoacceptingoffice
                FROM kaveri.anywhere_reg_log a
                LEFT JOIN kaveri.documentmaster d2
                    ON d2.applicationnumber = a.newapplicationnumber
                LEFT JOIN kaveri.sromaster s1
                    ON s1.srocode = a.srocode
                LEFT JOIN kaveri.sromaster s2
                    ON s2.srocode = a.regsrocode
                WHERE a.applicationnumber = d.applicationnumber
                ORDER BY a.memosentdatetime DESC
                LIMIT 1
            ) ar ON true
            ORDER BY d.finalregistrationnumber
        )
        SELECT
            cte.districtname,
            cte.sroname,
            cte.finalregistrationnumber,
            cte.applicationnumber2,
            cte.presentationdatetime,
            cte.presenter_name,
            cte.description_of_document,
            cte.considerationamount,
            cte.marketvalue,
            cte.stampduty,
            cte.cess,
            cte.surcharge_duty_muncipal,
            cte.surcharge_duty_taluk,
            cte.total_duty,
            cte.documentnumber,
            cte.bookid,
            cte.volumenumber,
            cte.dateofcompletion,
            cte.dateofreturn,
            cte.registrationfees,
            cte.feescopygranted,
            cte.miscfees,
            cte.otherstampduty,
            cte.miscarticlefees,
            cte.total_fees,
            cte.treasury_fees,
            cte.feedate_treasury,
            cte.dailymutationreceipts,
            cte.mutationfees,
            cte.mutationfeedate,
            cte.transmission_of_memorandum,
            cte.transmission_of_memoranda,
            cte.total_amount_collected,
            SUM(cte.total_amount_collected) OVER()::bigint AS grand_total,
            cte.signature_of_register,
            cte.remarks,
            cte.copy_of_document,
            COUNT(*) OVER()::bigint AS totalcount
        FROM cte
        OFFSET PageOffset
        FETCH NEXT pagesize ROWS ONLY;

    ELSIF pagenumber = -1 OR pagesize = -1 THEN

        RETURN QUERY
        WITH cte AS (
            WITH dm AS (
                SELECT
                    d2.districtnamee,
                    d.applicationnumber,
                    d.registrationdatetime,
                    d.finalregistrationnumber,
                    d.bookid,
                    d.presentdatetime,
                    d.srocode,
                    s.sronamee
                FROM kaveri.documentmaster d
                JOIN kaveri.sromaster s
                    ON d.srocode = s.srocode
                JOIN kaveri.districtmaster d2
                    ON d2.districtcode = s.districtcode
                WHERE d.registrationdatetime BETWEEN _fromdate::date
                                                  AND _todate::date + INTERVAL '1 day'
                  AND (CASE WHEN _districtcode <> 0 THEN s.districtcode = _districtcode ELSE TRUE END)
                  AND (CASE WHEN _srocode <> 0 THEN d.srocode = _srocode ELSE TRUE END)
                  AND d.bookid IN (1,2,3,4,11)
                  AND d.isregistrationcompleted = true
            ),
            success_txns AS (
                SELECT DISTINCT e.deptreferencecode
                FROM kaveri.ams_reg_epaymenttransdetails e
                JOIN kaveri.ams_reg_epaymentbankackdetails b
                    ON b.deptreferencecode = e.deptreferencecode
                WHERE b.paymentstatuscode IN ('10700066','10700072')
                  AND e.isdelete = false
                  AND e.applicationnumber IN (SELECT applicationnumber FROM dm)
            ),
            pm AS (
                SELECT
                    applicationnumber,
                    SUM(totalarea) AS totalarea,
                    COALESCE(SUM(sroconsideration),0) AS consideration,
                    COALESCE(SUM(sromarketvalue),0) AS marketvalue
                FROM kaveri.propertymaster
                WHERE applicationnumber IN (SELECT applicationnumber FROM dm)
                GROUP BY applicationnumber
            ),
            epay AS (
                SELECT
                    e.applicationnumber,
                    COALESCE(SUM(e.totalamount) FILTER (
                        WHERE e.feerulecode IN (35,36,64,89,91,92,101,107,110,138)
                    ),0) AS stampduty,
                    COALESCE(SUM(e.totalamount) FILTER (
                        WHERE e.feerulecode IN (59,100)
                    ),0) AS cessduty,
                    COALESCE(SUM(e.totalamount) FILTER (
                        WHERE e.feerulecode IN (
                            1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,
                            27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,
                            103,106,108,109
                        )
                    ),0) AS feesforregistrationofdocs,
                    COALESCE(SUM(e.totalamount) FILTER (WHERE e.feerulecode = 2),0) AS scanningfee,
                    COALESCE(SUM(e.totalamount) FILTER (WHERE e.feerulecode = 6),0) AS mutationfee
                FROM kaveri.ams_reg_epaymenttransdetails e
                JOIN success_txns s USING (deptreferencecode)
                WHERE e.applicationnumber IN (SELECT applicationnumber FROM dm)
                  AND e.isdelete = false
                GROUP BY e.applicationnumber
            ),
            surcharge AS (
                SELECT
                    e.applicationnumber,
                    SUM(e.totalamount) AS totalsurcharge
                FROM kaveri.ams_reg_epaymenttransdetails e
                JOIN success_txns s USING (deptreferencecode)
                WHERE e.isdelete = false
                  AND e.feerulecode IN (58,99)
                  AND e.applicationnumber IN (SELECT applicationnumber FROM dm)
                GROUP BY e.applicationnumber
            ),
            has_taluk AS (
                SELECT
                    pm.applicationnumber,
                    BOOL_OR(pnd.currentpropertytypeid = 60) AS has_taluk
                FROM kaveri.propertymaster pm
                JOIN kaveri.propertynumberdetails pnd
                    ON pnd.propertyid = pm.propertyid
                WHERE pm.applicationnumber IN (SELECT applicationnumber FROM dm)
                GROUP BY pm.applicationnumber
            ),
            bk AS (
                SELECT
                    e.applicationnumber,
                    SUM(e.totalamount) AS feesremittedtotreasury
                FROM kaveri.ams_reg_epaymenttransdetails e
                JOIN success_txns s USING (deptreferencecode)
                WHERE e.isdelete = false
                  AND e.applicationnumber IN (SELECT applicationnumber FROM dm)
                GROUP BY e.applicationnumber
            )
            SELECT
                d.districtnamee AS districtname,
                d.sronamee AS sroname,
                NULL::varchar AS finalregistrationnumber,
                d.applicationnumber AS applicationnumber2,
                d.presentdatetime::text AS presentationdatetime,
                pr.presenternamee AS presenter_name,
                art.description_of_docs AS description_of_document,
                pm.consideration::numeric AS considerationamount,
                pm.marketvalue::bigint AS marketvalue,
                ep.stampduty::numeric AS stampduty,
                ep.cessduty::numeric AS cess,
                CASE
                    WHEN h.has_taluk THEN 0
                    ELSE COALESCE(s.totalsurcharge,0)
                END::numeric AS surcharge_duty_muncipal,
                CASE
                    WHEN h.has_taluk THEN COALESCE(s.totalsurcharge,0)
                    ELSE 0
                END::numeric AS surcharge_duty_taluk,
                COALESCE(
                    ep.stampduty::numeric
                    + ep.cessduty::numeric
                    + s.totalsurcharge::numeric,
                    0
                ) AS total_duty,
                d.finalregistrationnumber::varchar AS documentnumber,
                d.bookid::varchar AS bookid,
                NULL::text AS volumenumber,
                d.registrationdatetime::text AS dateofcompletion,
                d.registrationdatetime::text AS dateofreturn,
                ep.feesforregistrationofdocs::numeric AS registrationfees,
                NULL::numeric AS feescopygranted,
                ep.scanningfee::numeric AS miscfees,
                NULL::numeric AS otherstampduty,
                NULL::numeric AS miscarticlefees,
                (
                    COALESCE(ep.feesforregistrationofdocs,0)
                    + COALESCE(ep.scanningfee,0)
                )::numeric AS total_fees,
                bk.feesremittedtotreasury::numeric AS treasury_fees,
                bklast.transactiondate::text AS feedate_treasury,
                NULL::text AS dailymutationreceipts,
                ep.mutationfee::numeric AS mutationfees,
                mut.mutationfeeremittedtotreasurydate::text AS mutationfeedate,
                ar.copiesofmemo::text AS transmission_of_memorandum,
                ar.memoacceptingoffice::text AS transmission_of_memoranda,
                (
                    COALESCE(ep.stampduty,0)
                    + COALESCE(ep.cessduty,0)
                    + COALESCE(CASE WHEN h.has_taluk THEN 0 ELSE s.totalsurcharge END,0)
                    + COALESCE(CASE WHEN h.has_taluk THEN s.totalsurcharge ELSE 0 END,0)
                    + COALESCE(ep.feesforregistrationofdocs,0)
                    + COALESCE(ep.scanningfee,0)
                    + COALESCE(ep.mutationfee,0)
                )::bigint AS total_amount_collected,
                NULL::text AS signature_of_register,
                NULL::text AS remarks,
                NULL::text AS copy_of_document
            FROM dm d
            LEFT JOIN pm
                ON pm.applicationnumber = d.applicationnumber
            LEFT JOIN epay ep
                ON ep.applicationnumber = d.applicationnumber
            LEFT JOIN surcharge s
                ON s.applicationnumber = d.applicationnumber
            LEFT JOIN has_taluk h
                ON h.applicationnumber = d.applicationnumber
            LEFT JOIN bk
                ON bk.applicationnumber = d.applicationnumber
            LEFT JOIN LATERAL (
                SELECT
                    b.amount AS feesremittedtotreasury,
                    b.transactiontimestamp::date AS transactiondate
                FROM kaveri.ams_reg_epaymenttransdetails e2
                JOIN kaveri.ams_reg_epaymentbankackdetails b
                    ON b.deptreferencecode = e2.deptreferencecode
                WHERE e2.applicationnumber = d.applicationnumber
                  AND e2.isdelete = false
                  AND b.paymentstatuscode IN ('10700066','10700072')
                ORDER BY b.transactiontimestamp DESC
                LIMIT 1
            ) bklast ON true
            LEFT JOIN LATERAL (
                SELECT
                    COALESCE(NULLIF(p2.firstname,''), NULLIF(p1.firstname,''), p.firstname) AS presenternamee
                FROM kaveri.partyinfo p
                LEFT JOIN kaveri.partyinfo p1
                    ON p.partyid = p1.linkpartyid
                LEFT JOIN kaveri.partyinfo p2
                    ON p1.partyid = p2.linkpartyid
                WHERE p.applicationnumber = d.applicationnumber
                  AND p.ispresenter = true
                ORDER BY p.partyid
                LIMIT 1
            ) pr ON true
            LEFT JOIN LATERAL (
                SELECT
                    s.articlenamee AS description_of_docs
                FROM (
                    SELECT DISTINCT stamparticlecode
                    FROM kaveri.propertymaster
                    WHERE applicationnumber = d.applicationnumber
                    ORDER BY stamparticlecode
                    LIMIT 1
                ) pmx
                JOIN kaveri.stamparticles s
                    ON s.stamparticlecode = pmx.stamparticlecode
            ) art ON true
            LEFT JOIN LATERAL (
                SELECT
                    MIN(t.inserteddatetime)::date AS mutationfeeremittedtotreasurydate
                FROM kaveri.ams_reg_epaymenttransdetails t
                JOIN success_txns st USING (deptreferencecode)
                WHERE t.applicationnumber = d.applicationnumber
                  AND t.feerulecode = 6
                  AND t.isdelete = false
            ) mut ON true
            LEFT JOIN LATERAL (
                SELECT
                    a.newapplicationnumber AS copiesofmemo,
                    a.memosentdatetime::date AS memosentdate,
                    a.memoaccepteddatetime::date AS memoaccepteddate,
                    d2.finalregistrationnumber AS memonumber,
                    s1.sronamee AS officename,
                    s2.sronamee AS memoacceptingoffice
                FROM kaveri.anywhere_reg_log a
                LEFT JOIN kaveri.documentmaster d2
                    ON d2.applicationnumber = a.newapplicationnumber
                LEFT JOIN kaveri.sromaster s1
                    ON s1.srocode = a.srocode
                LEFT JOIN kaveri.sromaster s2
                    ON s2.srocode = a.regsrocode
                WHERE a.applicationnumber = d.applicationnumber
                ORDER BY a.memosentdatetime DESC
                LIMIT 1
            ) ar ON true
            ORDER BY d.finalregistrationnumber
        )
        SELECT
            cte.districtname,
            cte.sroname,
            cte.finalregistrationnumber,
            cte.applicationnumber2,
            cte.presentationdatetime,
            cte.presenter_name,
            cte.description_of_document,
            cte.considerationamount,
            cte.marketvalue,
            cte.stampduty,
            cte.cess,
            cte.surcharge_duty_muncipal,
            cte.surcharge_duty_taluk,
            cte.total_duty,
            cte.documentnumber,
            cte.bookid,
            cte.volumenumber,
            cte.dateofcompletion,
            cte.dateofreturn,
            cte.registrationfees,
            cte.feescopygranted,
            cte.miscfees,
            cte.otherstampduty,
            cte.miscarticlefees,
            cte.total_fees,
            cte.treasury_fees,
            cte.feedate_treasury,
            cte.dailymutationreceipts,
            cte.mutationfees,
            cte.mutationfeedate,
            cte.transmission_of_memorandum,
            cte.transmission_of_memoranda,
            cte.total_amount_collected,
            SUM(cte.total_amount_collected) OVER()::bigint AS grand_total,
            cte.signature_of_register,
            cte.remarks,
            cte.copy_of_document,
            COUNT(*) OVER()::bigint AS totalcount
        FROM cte;

    END IF;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg_20260312_test(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO manjunathswamy;

--
-- Name: fn_mis_daily_register_of_fees_statutory_docreg_23012024(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg_23012024(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document character varying, considerationamount numeric, marketvalue bigint, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid character varying, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees numeric, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if pagenumber <> -1 and pagesize <> -1 then 

			return query
			with cte as (with a as ( select     
			dsm.districtnamee,
			sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,
			to_char(dm.presentdatetime,'dd-MM-YYYY') presentdate,
			(select 
			string_agg(distinct (coalesce(firstname,' ')||coalesce(middlename,' ')|| 
			coalesce(lastname,' ')::text),',') 
			from kaveri.partyinfo where applicationnumber=dm.applicationnumber  
			and ispresenter is true group by applicationnumber)as presentername ,
			--pi1.presentername,
			sa.articlenamee AS descriptionofdocument, 
			max(pm.sroconsideration) as consideration_fees,
			max(pm.sromarketvalue) as marketvalue,
			pm.propertytypeid ,
			case when dm.finalregistrationnumber is not null
			then dm.finalregistrationnumber else dm.pendingdocumentnumber end documentnumber,
			b.booknameenglish ,
			null  as volumenumber,
			(select sum(amsreg.totalamount)
			from kaveri.ams_reg_epaymenttransdetails amsreg where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false) as Treasury_amount,
			(select to_char(amsreg.inserteddatetime,'dd-MM-yyyy')
			from kaveri.ams_reg_epaymenttransdetails amsreg where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false limit 1)  as Challan_date ,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofcompletion,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofreturn,
			dm.uploaddocdeedpath as copy_of_document

			from  kaveri.documentmaster dm
			join  kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber 
			join kaveri.stamparticles sa on pm.stamparticlecode=sa.stamparticlecode 
			JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
			join kaveri.booktypemaster b on dm.bookid=b.bookid 
			--left join kaveri.ams_reg_epaymenttransdetails amsreg on 
			--amsreg.applicationnumber = dm.applicationnumber and amsreg.isdelete=false  
			where 
			
			(dm.registrationdatetime between _fromdate	and _todate + INTERVAL '1 day'  )
			and 
			
			(

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			and
			
				(

                    CASE

                    WHEN _srocode <> 0 THEN  dm.srocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  dm.finalregistrationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
               and 
			    
			 dm.isregistrationcompleted=true
			 group by dsm.districtnamee,sm.sronamee,dm.finalregistrationnumber,dm.applicationnumber,
			 sa.articlenamee,dm.pendingdocumentnumber,b.booknameenglish,
			 --,booknameenglish,
			dm.registrationdatetime,dm.uploaddocdeedpath,dm.presentdatetime,pm.propertytypeid	)

			select a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) stampduty,
			sum(case when fr.feerulecode=59  then amountpaid else 0 end) cess,
			sum(case when a.propertytypeid=28 and fr.feerulecode=58 then amountpaid else 0 end ) as municipalsurcharge,
			sum(case when a.propertytypeid=17 and fr.feerulecode=58 then amountpaid else 0 end ) as taluksurcharge,
			sum(case when fr.feerulecode in (36,58,59)  then amountpaid else 0 end)  as Total_duty,
			a.documentnumber,a.booknameenglish,a.volumenumber,
			a.dateofcompletion,a.dateofreturn,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end) registrationfees,
			sum(case when fr.feerulecode=41 then amountpaid else 0 end) as feesforcopies,
			sum(case when fr.feerulecode=2 then amountpaid else 0 end) miscelaneousfees,
			sum(case when fr.feerulecode in (34,91)then amountpaid else 0 end) otherstampduty,
			NULL::numeric miscellaneous_article_fees,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=41 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=2 then amountpaid else 0 end)+
			sum(case when fr.feerulecode  in (34,91)then amountpaid else 0 end) Total_fees2,
			a.Treasury_amount,
			a.Challan_date,
			string_agg(distinct (case when fr.feerulecode=6 then r.receiptnumber::text  else ' ' end ),' ')as dailymutationreceipts,
			sum(case when fr.feerulecode=6 then fr.amountpaid else 0 end) mutationfees,
			string_agg(distinct ( case when fr.feerulecode=6 then to_char(r.dateofreceipt,'DD-MM-YYYY')  else ' ' end ),' ')as mutationfeedate,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			a.copy_of_document

			from 
			a
			left join 	kaveri.feesrequired fr on a.applicationnumber=fr.applicationnumber
			left join kaveri.receiptmaster r on fr.receiptid=r.receiptid
			
			group by a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,
			a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			a.documentnumber,a.booknameenglish,
			a.volumenumber,a.Treasury_amount,
			a.Challan_date,a.dateofcompletion,a.dateofreturn,a.copy_of_document,a.propertytypeid
			)
			select * from cte
			right join (select null::bigint as total_rows) total_row on true
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

 elsif pagenumber = -1 or  pagesize = -1 then 
 
 		return query
			with cte as (with a as ( select     
			dsm.districtnamee,
			sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,
			to_char(dm.presentdatetime,'dd-MM-YYYY') presentdate,
			(select 
			string_agg(distinct (coalesce(firstname,' ')||coalesce(middlename,' ')|| 
			coalesce(lastname,' ')::text),',') 
			from kaveri.partyinfo where applicationnumber=dm.applicationnumber  
			and ispresenter is true group by applicationnumber)as presentername ,
			--pi1.presentername,
			sa.articlenamee AS descriptionofdocument, 
			max(pm.sroconsideration) as consideration_fees,
			max(pm.sromarketvalue) as marketvalue,
			pm.propertytypeid ,
			case when dm.finalregistrationnumber is not null
			then dm.finalregistrationnumber else dm.pendingdocumentnumber end documentnumber,
			b.booknameenglish ,
			null  as volumenumber,
			(select sum(amsreg.totalamount)
			from kaveri.ams_reg_epaymenttransdetails amsreg where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false) as Treasury_amount,
			(select to_char(amsreg.inserteddatetime,'dd-MM-yyyy')
			from kaveri.ams_reg_epaymenttransdetails amsreg where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false limit 1)  as Challan_date ,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofcompletion,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofreturn,
			dm.uploaddocdeedpath as copy_of_document

			from  kaveri.documentmaster dm
			join  kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber 
			join kaveri.stamparticles sa on pm.stamparticlecode=sa.stamparticlecode 
			JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
			join kaveri.booktypemaster b on dm.bookid=b.bookid 
			--left join kaveri.ams_reg_epaymenttransdetails amsreg on 
			--amsreg.applicationnumber = dm.applicationnumber and amsreg.isdelete=false 
			where 
			
			(dm.registrationdatetime between _fromdate	and _todate + INTERVAL '1 day'  )
			and 
			
			(

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			and
			
				(

                    CASE

                    WHEN _srocode <> 0 THEN  dm.srocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  dm.finalregistrationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
               and 
			    
			 dm.isregistrationcompleted=true
			 group by dsm.districtnamee,sm.sronamee,dm.finalregistrationnumber,dm.applicationnumber,
			 sa.articlenamee,dm.pendingdocumentnumber,b.booknameenglish,
			 --,booknameenglish,
			dm.registrationdatetime,dm.uploaddocdeedpath,dm.presentdatetime,pm.propertytypeid	)

			select a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) stampduty,
			sum(case when fr.feerulecode=59  then amountpaid else 0 end) cess,
			sum(case when a.propertytypeid=28 and fr.feerulecode=58 then amountpaid else 0 end ) as municipalsurcharge,
			sum(case when a.propertytypeid=17 and fr.feerulecode=58 then amountpaid else 0 end ) as taluksurcharge,
			sum(case when fr.feerulecode in (36,58,59)  then amountpaid else 0 end)  as Total_duty,
			a.documentnumber,a.booknameenglish,a.volumenumber,
			a.dateofcompletion,a.dateofreturn,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end) registrationfees,
			sum(case when fr.feerulecode=41 then amountpaid else 0 end) as feesforcopies,
			sum(case when fr.feerulecode=2 then amountpaid else 0 end) miscelaneousfees,
			sum(case when fr.feerulecode in (34,91)then amountpaid else 0 end) otherstampduty,
			NULL::numeric miscellaneous_article_fees,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=41 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=2 then amountpaid else 0 end)+
			sum(case when fr.feerulecode  in (34,91)then amountpaid else 0 end) Total_fees2,
			a.Treasury_amount,
			a.Challan_date,
			string_agg(distinct (case when fr.feerulecode=6 then r.receiptnumber::text  else ' ' end ),' ')as dailymutationreceipts,
			sum(case when fr.feerulecode=6 then fr.amountpaid else 0 end) mutationfees,
			string_agg(distinct ( case when fr.feerulecode=6 then to_char(r.dateofreceipt,'DD-MM-YYYY')  else ' ' end ),' ')as mutationfeedate,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			a.copy_of_document

			from 
			a
			left join 	kaveri.feesrequired fr on a.applicationnumber=fr.applicationnumber
			left join kaveri.receiptmaster r on fr.receiptid=r.receiptid
			
			group by a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,
			a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			a.documentnumber,a.booknameenglish,
			a.volumenumber,a.Treasury_amount,
			a.Challan_date,a.dateofcompletion,a.dateofreturn,a.copy_of_document,a.propertytypeid
			)
			select * from cte
			right join (select null::bigint as total_rows) total_row on true;
			
 
 
 
 end if;
		

 

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg_23012024(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_register_of_fees_statutory_docreg_bkp_20260526(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg_bkp_20260526(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document character varying, considerationamount numeric, marketvalue bigint, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid character varying, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees numeric, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, total_amount_collected bigint, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
 
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
 
if pagenumber <> -1 and pagesize <> -1 then
 
			return query
			    with cte as (
				with dm as (
					select d2.districtnamee,d.applicationnumber, d.registrationdatetime, d.finalregistrationnumber, d.bookid, d.presentdatetime, d.srocode,s.sronamee
					from kaveri.documentmaster d
					join kaveri.sromaster s on d.srocode = s.srocode
                    join kaveri.districtmaster d2 on d2.districtcode = s.districtcode
					where (d.registrationdatetime between _fromdate::date	and _todate::date + INTERVAL '1 day'  )and
					(CASE WHEN _districtcode <> 0 THEN  s.districtcode = _districtcode ELSE TRUE end)
					and(CASE WHEN _srocode <> 0 THEN  d.srocode = _srocode ELSE TRUE end)
					and d.bookid in (1,2,3,4)
					and isregistrationcompleted = true
				--     and registrationdatetime >= date '2025-08-01'
				--     and registrationdatetime < date '2025-09-01'
				--     and srocode = 171
				),
				success_txns as (
					select distinct e.deptreferencecode
					from kaveri.ams_reg_epaymenttransdetails e
					join kaveri.ams_reg_epaymentbankackdetails b on b.deptreferencecode = e.deptreferencecode
					where b.paymentstatuscode in ('10700066','10700072')
					  and e.isdelete = false
					  and e.applicationnumber in (select applicationnumber from dm)
				),
				pm as (
					select
						applicationnumber,
						sum(totalarea) as totalarea,
						coalesce(sum(sroconsideration),0) as consideration,
						coalesce(sum(sromarketvalue),0) as marketvalue
					from kaveri.propertymaster
					where applicationnumber in (select applicationnumber from dm)
					  --and totalarea <= 0.125
					group by applicationnumber
				),
				epay as (
					select
						e.applicationnumber,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (35,36,64,89,91,92,101,107,110,138)),0) as stampduty,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (59,100)),0) as cessduty,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109)),0) as feesforregistrationofdocs,
						coalesce(sum(e.totalamount) filter (where e.feerulecode = 2),0) as scanningfee,
						coalesce(sum(e.totalamount) filter (where e.feerulecode = 6),0) as mutationfee
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.applicationnumber in (select applicationnumber from dm)
					  and e.isdelete = false
					group by e.applicationnumber
				),
				surcharge as (
					select e.applicationnumber, sum(e.totalamount) as totalsurcharge
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.isdelete = false
					  and e.feerulecode in (58,99)
					  and e.applicationnumber in (select applicationnumber from dm)
					group by e.applicationnumber
				),
				has_taluk as (
					select pm.applicationnumber, bool_or(pnd.currentpropertytypeid = 60) as has_taluk
					from kaveri.propertymaster pm
					join kaveri.propertynumberdetails pnd on pnd.propertyid = pm.propertyid
					where pm.applicationnumber in (select applicationnumber from dm)
					group by pm.applicationnumber
				),
				bk as (
					select e.applicationnumber, sum(e.totalamount) as feesremittedtotreasury
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.isdelete = false
					  and e.applicationnumber in (select applicationnumber from dm)
					group by e.applicationnumber
				)
				select d.districtnamee,
					d.sronamee,
					null::varchar as finalregistrationnumber,
					d.applicationnumber as applicationnumber2,
					d.presentdatetime::text as presentationdatetime,
					pr.presenternamee as presenter_name,
					art.description_of_docs as description_of_document,
					pm.consideration::numeric as considerationamount,
					pm.marketvalue::bigint as marketvalue,
					ep.stampduty::numeric as stampduty,
					ep.cessduty::numeric as cess,
					case when h.has_taluk then 0 else coalesce(s.totalsurcharge,0) end::numeric as surcharge_duty_muncipal,
					case when h.has_taluk then coalesce(s.totalsurcharge,0) else 0 end::numeric as surcharge_duty_taluk,
--					total_duty::numeric,
					coalesce(ep.stampduty::numeric + ep.cessduty::numeric + s.totalsurcharge::numeric,0) as total_duty,
					d.finalregistrationnumber::varchar as documentnumber,
					d.bookid::varchar as bookid,
					null::text as volumenumber,
					d.registrationdatetime::text as dateofcompletion,
					d.registrationdatetime::text as dateofreturn,
					ep.feesforregistrationofdocs::numeric as registrationfees,
					null::numeric as feescopygranted,
					ep.scanningfee::numeric as miscfees,
					null::numeric as otherstampduty,
					null::numeric as miscarticlefees,
					(COALESCE(ep.feesforregistrationofdocs,0)
						+ COALESCE(ep.scanningfee,0))::numeric as total_fees, --sum
					bk.feesremittedtotreasury::numeric as treasury_fees,
					bklast.transactiondate::text as feedate_treasury,
					null::text as dailymutationreceipts,
					ep.mutationfee::numeric as mutationfees,
					mut.mutationfeeremittedtotreasurydate::text as mutationfeedate,
					ar.copiesofmemo::text as transmission_of_memorandum,
					--ar.officename as transmission_of_memoranda,
					ar.memoacceptingoffice::text as transmission_of_memoranda,
					  (coalesce(ep.stampduty,0)
					  + coalesce(ep.cessduty,0)
					  + coalesce(case when h.has_taluk then 0 else s.totalsurcharge end,0)
					  + coalesce(case when h.has_taluk then s.totalsurcharge else 0 end,0)
					  + coalesce(ep.feesforregistrationofdocs,0)
					  + coalesce(ep.scanningfee,0)
					  + coalesce(ep.mutationfee,0))::bigint as total_amount_collected,
					null::text as signature_of_register,
					null::text as remarks,
					null::text as copy_of_document
					--pm.totalarea,	
					--ar.memosentdate,
					--ar.memonumber,
					--ar.memoaccepteddate
				from dm d
				left join pm on pm.applicationnumber = d.applicationnumber
				left join epay ep on ep.applicationnumber = d.applicationnumber
				left join surcharge s on s.applicationnumber = d.applicationnumber
				left join has_taluk h on h.applicationnumber = d.applicationnumber
				left join bk on bk.applicationnumber = d.applicationnumber
				
				left join lateral (
					select b.amount as feesremittedtotreasury, b.transactiontimestamp::date as transactiondate
					from kaveri.ams_reg_epaymenttransdetails e2
					join kaveri.ams_reg_epaymentbankackdetails b on b.deptreferencecode = e2.deptreferencecode
					where e2.applicationnumber = d.applicationnumber
					  and e2.isdelete = false
					  and b.paymentstatuscode in ('10700066','10700072')
					order by b.transactiontimestamp desc
					limit 1
				) bklast on true
				
				left join lateral (
					select coalesce(nullif(p2.firstname,''), nullif(p1.firstname,''), p.firstname) as presenternamee
					from kaveri.partyinfo p
					left join kaveri.partyinfo p1 on p.partyid = p1.linkpartyid
					left join kaveri.partyinfo p2 on p1.partyid = p2.linkpartyid
					where p.applicationnumber = d.applicationnumber and p.ispresenter = true
					order by p.partyid
					limit 1
				) pr on true
				
				left join lateral (
					select s.articlenamee as description_of_docs
					from (
						select distinct stamparticlecode
						from kaveri.propertymaster
						where applicationnumber = d.applicationnumber
						order by stamparticlecode
						limit 1
					) pmx
					join kaveri.stamparticles s on s.stamparticlecode = pmx.stamparticlecode
				) art on true
				
				left join lateral (
					select min(t.inserteddatetime)::date as mutationfeeremittedtotreasurydate
					from kaveri.ams_reg_epaymenttransdetails t
					join success_txns st using (deptreferencecode)
					where t.applicationnumber = d.applicationnumber
					  and t.feerulecode = 6
					  and t.isdelete = false
				) mut on true
				
				left join lateral (
					select
						a.newapplicationnumber as copiesofmemo,
						a.memosentdatetime::date as memosentdate,
						a.memoaccepteddatetime::date as memoaccepteddate,
						d2.finalregistrationnumber as memonumber,
						s1.sronamee as officename,
						s2.sronamee as memoacceptingoffice
					from kaveri.anywhere_reg_log a
					left join kaveri.documentmaster d2 on d2.applicationnumber = a.newapplicationnumber
					left join kaveri.sromaster s1 on s1.srocode = a.srocode
					left join kaveri.sromaster s2 on s2.srocode = a.regsrocode
					where a.applicationnumber = d.applicationnumber
					order by a.memosentdatetime desc
					limit 1
				) ar on true
				order by d.finalregistrationnumber)
				
				select cte.*,
                count(*) over()::bigint as totalcount
                from cte
                OFFSET PageOffset
                FETCH NEXT pagesize ROWS ONLY;
 
 
elsif pagenumber = -1 or  pagesize = -1 then
 
		return query
					    with cte as (
				with dm as (
					select d2.districtnamee,d.applicationnumber, d.registrationdatetime, d.finalregistrationnumber, d.bookid, d.presentdatetime, d.srocode,s.sronamee
					from kaveri.documentmaster d
					join kaveri.sromaster s on d.srocode = s.srocode
                    join kaveri.districtmaster d2 on d2.districtcode = s.districtcode
					where (d.registrationdatetime between _fromdate::date	and _todate::date + INTERVAL '1 day'  )and
					(CASE WHEN _districtcode <> 0 THEN  s.districtcode = _districtcode ELSE TRUE end)
					and(CASE WHEN _srocode <> 0 THEN  d.srocode = _srocode ELSE TRUE end)
					and d.bookid in (1,2,3,4)
					and isregistrationcompleted = true
				--     and registrationdatetime >= date '2025-08-01'
				--     and registrationdatetime < date '2025-09-01'
				--     and srocode = 171
				),
				success_txns as (
					select distinct e.deptreferencecode
					from kaveri.ams_reg_epaymenttransdetails e
					join kaveri.ams_reg_epaymentbankackdetails b on b.deptreferencecode = e.deptreferencecode
					where b.paymentstatuscode in ('10700066','10700072')
					  and e.isdelete = false
					  and e.applicationnumber in (select applicationnumber from dm)
				),
				pm as (
					select
						applicationnumber,
						sum(totalarea) as totalarea,
						coalesce(sum(sroconsideration),0) as consideration,
						coalesce(sum(sromarketvalue),0) as marketvalue
					from kaveri.propertymaster
					where applicationnumber in (select applicationnumber from dm)
					  --and totalarea <= 0.125
					group by applicationnumber
				),
				epay as (
					select
						e.applicationnumber,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (35,36,64,89,91,92,101,107,110,138)),0) as stampduty,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (59,100)),0) as cessduty,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109)),0) as feesforregistrationofdocs,
						coalesce(sum(e.totalamount) filter (where e.feerulecode = 2),0) as scanningfee,
						coalesce(sum(e.totalamount) filter (where e.feerulecode = 6),0) as mutationfee
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.applicationnumber in (select applicationnumber from dm)
					  and e.isdelete = false
					group by e.applicationnumber
				),
				surcharge as (
					select e.applicationnumber, sum(e.totalamount) as totalsurcharge
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.isdelete = false
					  and e.feerulecode in (58,99)
					  and e.applicationnumber in (select applicationnumber from dm)
					group by e.applicationnumber
				),
				has_taluk as (
					select pm.applicationnumber, bool_or(pnd.currentpropertytypeid = 60) as has_taluk
					from kaveri.propertymaster pm
					join kaveri.propertynumberdetails pnd on pnd.propertyid = pm.propertyid
					where pm.applicationnumber in (select applicationnumber from dm)
					group by pm.applicationnumber
				),
				bk as (
					select e.applicationnumber, sum(e.totalamount) as feesremittedtotreasury
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.isdelete = false
					  and e.applicationnumber in (select applicationnumber from dm)
					group by e.applicationnumber
				)
				select d.districtnamee,
					d.sronamee,
					null::varchar as finalregistrationnumber,
					d.applicationnumber as applicationnumber2,
					d.presentdatetime::text as presentationdatetime,
					pr.presenternamee as presenter_name,
					art.description_of_docs as description_of_document,
					pm.consideration::numeric as considerationamount,
					pm.marketvalue::bigint as marketvalue,
					ep.stampduty::numeric as stampduty,
					ep.cessduty::numeric as cess,
					case when h.has_taluk then 0 else coalesce(s.totalsurcharge,0) end::numeric as surcharge_duty_muncipal,
					case when h.has_taluk then coalesce(s.totalsurcharge,0) else 0 end::numeric as surcharge_duty_taluk,
--					coalesce(sum(e.totalamount) filter (where e.feerulecode in (35,36,64,89,91,92,101,107,110,138,58,59,99,100)),0) as total_duty
					coalesce(ep.stampduty::numeric + ep.cessduty::numeric + s.totalsurcharge::numeric,0) as total_duty,
					d.finalregistrationnumber::varchar as documentnumber,
					d.bookid::varchar as bookid,
					null::text as volumenumber,
					d.registrationdatetime::text as dateofcompletion,
					d.registrationdatetime::text as dateofreturn,
					ep.feesforregistrationofdocs::numeric as registrationfees,
					null::numeric as feescopygranted,
					ep.scanningfee::numeric as miscfees,
					null::numeric as otherstampduty,
					null::numeric as miscarticlefees,
					(COALESCE(ep.feesforregistrationofdocs,0)
						+ COALESCE(ep.scanningfee,0))::numeric as total_fees,
					bk.feesremittedtotreasury::numeric as treasury_fees,
					bklast.transactiondate::text as feedate_treasury,
					null::text as dailymutationreceipts,
					ep.mutationfee::numeric as mutationfees,
					mut.mutationfeeremittedtotreasurydate::text as mutationfeedate,
					ar.copiesofmemo::text as transmission_of_memorandum,
					--ar.officename as transmission_of_memoranda,
					ar.memoacceptingoffice::text as transmission_of_memoranda,
					  (coalesce(ep.stampduty,0)
					  + coalesce(ep.cessduty,0)
					  + coalesce(case when h.has_taluk then 0 else s.totalsurcharge end,0)
					  + coalesce(case when h.has_taluk then s.totalsurcharge else 0 end,0)
					  + coalesce(ep.feesforregistrationofdocs,0)
					  + coalesce(ep.scanningfee,0)
					  + coalesce(ep.mutationfee,0))::bigint as total_amount_collected,
					null::text as signature_of_register,
					null::text as remarks,
					null::text as copy_of_document
					--pm.totalarea,	
					--ar.memosentdate,
					--ar.memonumber,
					--ar.memoaccepteddate
				from dm d
				left join pm on pm.applicationnumber = d.applicationnumber
				left join epay ep on ep.applicationnumber = d.applicationnumber
				left join surcharge s on s.applicationnumber = d.applicationnumber
				left join has_taluk h on h.applicationnumber = d.applicationnumber
				left join bk on bk.applicationnumber = d.applicationnumber
				
				left join lateral (
					select b.amount as feesremittedtotreasury, b.transactiontimestamp::date as transactiondate
					from kaveri.ams_reg_epaymenttransdetails e2
					join kaveri.ams_reg_epaymentbankackdetails b on b.deptreferencecode = e2.deptreferencecode
					where e2.applicationnumber = d.applicationnumber
					  and e2.isdelete = false
					  and b.paymentstatuscode in ('10700066','10700072')
					order by b.transactiontimestamp desc
					limit 1
				) bklast on true
				
				left join lateral (
					select coalesce(nullif(p2.firstname,''), nullif(p1.firstname,''), p.firstname) as presenternamee
					from kaveri.partyinfo p
					left join kaveri.partyinfo p1 on p.partyid = p1.linkpartyid
					left join kaveri.partyinfo p2 on p1.partyid = p2.linkpartyid
					where p.applicationnumber = d.applicationnumber and p.ispresenter = true
					order by p.partyid
					limit 1
				) pr on true
				
				left join lateral (
					select s.articlenamee as description_of_docs
					from (
						select distinct stamparticlecode
						from kaveri.propertymaster
						where applicationnumber = d.applicationnumber
						order by stamparticlecode
						limit 1
					) pmx
					join kaveri.stamparticles s on s.stamparticlecode = pmx.stamparticlecode
				) art on true
				
				left join lateral (
					select min(t.inserteddatetime)::date as mutationfeeremittedtotreasurydate
					from kaveri.ams_reg_epaymenttransdetails t
					join success_txns st using (deptreferencecode)
					where t.applicationnumber = d.applicationnumber
					  and t.feerulecode = 6
					  and t.isdelete = false
				) mut on true
				
				left join lateral (
					select
						a.newapplicationnumber as copiesofmemo,
						a.memosentdatetime::date as memosentdate,
						a.memoaccepteddatetime::date as memoaccepteddate,
						d2.finalregistrationnumber as memonumber,
						s1.sronamee as officename,
						s2.sronamee as memoacceptingoffice
					from kaveri.anywhere_reg_log a
					left join kaveri.documentmaster d2 on d2.applicationnumber = a.newapplicationnumber
					left join kaveri.sromaster s1 on s1.srocode = a.srocode
					left join kaveri.sromaster s2 on s2.srocode = a.regsrocode
					where a.applicationnumber = d.applicationnumber
					order by a.memosentdatetime desc
					limit 1
				) ar on true
				order by d.finalregistrationnumber)
			 select
             cte.*,
             count(*) over()::bigint as totalcount
             from cte;
 
end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg_bkp_20260526(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_register_of_fees_statutory_docreg_new(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: raghavendrap
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg_new(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document character varying, considerationamount numeric, marketvalue bigint, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid character varying, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees numeric, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if pagenumber <> -1 and pagesize <> -1 then 

			return query
			with cte as (
				select 
				dsm.districtnamee,s.sronamee as sroname, rd.numberinregistered as finalregistrationnumber, rd.applicationnumber ,
				rd.presentdatetime::text as presentationdatetime,rd.presenternamee::text as presenter_name,rd.description_of_docs as description_of_document,
				rd.consideration as considerationamount, rd.marketvalue::bigint as marketvalue, rd.stampduty, rd.cessduty as cess, rd.muncipalsurchargeduty as surcharge_duty_muncipal,
				rd.talukaboardsurcharge as surcharge_duty_taluk, 
				null::numeric as total_duty, 
				rd.numberinregistered as documentnumber, dm.bookid::varchar, rd.volumneno as volumenumber,rd.dateofcompletion::text as dateofcompletion,
				rd.dateofreturn::text as dateofreturn, rd.feesforregistrationofdocs as registrationfees,
				null::numeric as feescopygranted,
				null::numeric as miscfees,
				rd.otherstampduty::numeric as otherstampduty,
				null::numeric as miscarticlefees, 
				null::numeric as total_fees, rd.feesremittedtotreasury::numeric as treasury_fees,rd.transactiondate::text as feedate_treasury,
				null as dailymutationreceipts,
				rd.mutationfee::numeric as mutationfees, rd.mutationfeeremittedtotreasurydate::text as mutationfeedate,
				null as transmission_of_memorandum,
				null as transmission_of_memoranda,
				rd.signatureofregisteringofficer as signature_of_register, rd.remarks,
				null as copy_of_document
				from 
				kaveri.revised_form_7_statutory_doc_reg rd
				join kaveri.documentmaster dm on rd.applicationnumber = dm.applicationnumber
				join kaveri.sromaster s on s.srocode = dm.srocode
				join kaveri.districtmaster dsm on dsm.districtcode = s.districtcode
				where 
				(rd.dateofcompletion between _fromdate	and _todate + INTERVAL '1 day'  )
				and 
				(CASE WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode ELSE TRUE end)
				and
				(CASE WHEN _srocode <> 0 THEN  dm.srocode = _srocode ELSE TRUE end)
				and 
				(CASE WHEN _documentnumber<>null THEN  rd.numberinregistered=_documentnumber ELSE TRUE end)
--				and dm.isregistrationcompleted=true
				)
				select * from cte
				right join (select null::bigint as total_rows) total_row on true
				OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

 elsif pagenumber = -1 or  pagesize = -1 then 
 
 		return query
			with cte as (
			select 
				dsm.districtnamee,s.sronamee as sroname, rd.numberinregistered as finalregistrationnumber, rd.applicationnumber ,
				rd.presentdatetime::text as presentationdatetime,rd.presenternamee::text as presenter_name,rd.description_of_docs as description_of_document,
				rd.consideration as considerationamount, rd.marketvalue::bigint as marketvalue, rd.stampduty, rd.cessduty as cess, rd.muncipalsurchargeduty as surcharge_duty_muncipal,
				rd.talukaboardsurcharge as surcharge_duty_taluk, 
				null::numeric as total_duty, 
				rd.numberinregistered as documentnumber, dm.bookid::varchar, rd.volumneno as volumenumber,rd.dateofcompletion::text as dateofcompletion,
				rd.dateofreturn::text as dateofreturn, rd.feesforregistrationofdocs as registrationfees,
				null::numeric as feescopygranted,
				null::numeric as miscfees,
				rd.otherstampduty::numeric as otherstampduty,
				null::numeric as miscarticlefees, 
				null::numeric as total_fees, rd.feesremittedtotreasury::numeric as treasury_fees,rd.transactiondate::text as feedate_treasury,
				null as dailymutationreceipts,
				rd.mutationfee::numeric as mutationfees, rd.mutationfeeremittedtotreasurydate::text as mutationfeedate,
				null as transmission_of_memorandum,
				null as transmission_of_memoranda,
				rd.signatureofregisteringofficer as signature_of_register, rd.remarks,
				null as copy_of_document
				from 
				kaveri.revised_form_7_statutory_doc_reg rd
				join kaveri.documentmaster dm on rd.applicationnumber = dm.applicationnumber
				join kaveri.sromaster s on s.srocode = dm.srocode
				join kaveri.districtmaster dsm on dsm.districtcode = s.districtcode
				where 
				(rd.dateofcompletion between _fromdate	and _todate + INTERVAL '1 day'  )
				and 
				(CASE WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode ELSE TRUE end)
				and
				(CASE WHEN _srocode <> 0 THEN  dm.srocode = _srocode ELSE TRUE end)
				and 
				(CASE WHEN _documentnumber<>null THEN  rd.numberinregistered=_documentnumber ELSE TRUE end)
--				and dm.isregistrationcompleted=true
			)
			select * from cte
			right join (select null::bigint as total_rows) total_row on true;
end if;
END;
$$;


