--
-- Name: fn_mis_daily_register_of_fees_statutory_docreg_newtest(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg_newtest(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document character varying, considerationamount numeric, marketvalue bigint, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid character varying, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees numeric, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, total_amount_collected bigint, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
 
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
 
if pagenumber <> -1 and pagesize <> -1 then
 
			return query
			select ag.districtname,ag.sroname,ag.finalregistrationnumber,ag.applicationnumber2,ag.presentationdatetime,ag.presenter_name,ag.description_of_document,ag.considerationamount,ag.marketvalue,ag.stampduty,ag.cess,ag.surcharge_duty_muncipal,ag.surcharge_duty_taluk,ag.total_duty,ag.documentnumber,ag.bookid,ag.volumenumber,ag.dateofcompletion,ag.dateofreturn,ag.registrationfees,ag.feescopygranted,ag.miscfees,ag.otherstampduty,ag.miscarticlefees,ag.total_fees,ag.treasury_fees,ag.feedate_treasury,ag.dailymutationreceipts,ag.mutationfees,ag.mutationfeedate,ag.transmission_of_memorandum,ag.transmission_of_memoranda,ag.total_amount_collected,ag.signature_of_register,ag.remarks,ag.copy_of_document,count(*) over()::bigint as totalcount
			from kaveri.revised_form_7_statutory_doc_reg ag
			join kaveri.documentmaster d on ag.applicationnumber2=d.applicationnumber
					join kaveri.sromaster s on d.srocode = s.srocode
                    join kaveri.districtmaster d2 on d2.districtcode = s.districtcode
					where (d.registrationdatetime between _fromdate::date	and _todate::date + INTERVAL '1 day'  )and
					(CASE WHEN _districtcode <> 0 THEN  s.districtcode = _districtcode ELSE TRUE end)
					and(CASE WHEN _srocode <> 0 THEN  d.srocode = _srocode ELSE TRUE end)
					and d.bookid in (1,2,3,4)
					and d.isregistrationcompleted = true
					 OFFSET PageOffset
                FETCH NEXT pagesize ROWS ONLY;
				
elsif pagenumber = -1 or  pagesize = -1 then
 
		return query
			select ag.districtname,ag.sroname,ag.finalregistrationnumber,ag.applicationnumber2,ag.presentationdatetime,ag.presenter_name,ag.description_of_document,ag.considerationamount,ag.marketvalue,ag.stampduty,ag.cess,ag.surcharge_duty_muncipal,ag.surcharge_duty_taluk,ag.total_duty,ag.documentnumber,ag.bookid,ag.volumenumber,ag.dateofcompletion,ag.dateofreturn,ag.registrationfees,ag.feescopygranted,ag.miscfees,ag.otherstampduty,ag.miscarticlefees,ag.total_fees,ag.treasury_fees,ag.feedate_treasury,ag.dailymutationreceipts,ag.mutationfees,ag.mutationfeedate,ag.transmission_of_memorandum,ag.transmission_of_memoranda,ag.total_amount_collected,ag.signature_of_register,ag.remarks,ag.copy_of_document,count(*) over()::bigint as totalcount
			from kaveri.revised_form_7_statutory_doc_reg ag
			join kaveri.documentmaster d on ag.applicationnumber2=d.applicationnumber
					join kaveri.sromaster s on d.srocode = s.srocode
                    join kaveri.districtmaster d2 on d2.districtcode = s.districtcode
					where (d.registrationdatetime between _fromdate::date	and _todate::date + INTERVAL '1 day'  )and
					(CASE WHEN _districtcode <> 0 THEN  s.districtcode = _districtcode ELSE TRUE end)
					and(CASE WHEN _srocode <> 0 THEN  d.srocode = _srocode ELSE TRUE end)
					and d.bookid in (1,2,3,4)
					and isregistrationcompleted = true;
					
end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg_newtest(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_register_of_fees_statutory_docreg_scheduler(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg_scheduler(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtcode integer, srocode integer, isregistrationcompleted boolean, registrationdatetime timestamp without time zone, districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document character varying, considerationamount numeric, marketvalue bigint, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid character varying, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees numeric, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, signature_of_register text, remarks text, copy_of_document text, currentstatus character varying)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if pagenumber <> -1 and pagesize <> -1 then 

			return query
			with cte as (with a as ( select 
			dsm.districtcode,
			dm.srocode,
			dm.isregistrationcompleted,
			dm.registrationdatetime,
			dsm.districtnamee,
			sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,
			to_char(dm.presentdatetime,'dd-MM-YYYY') presentdate,
			(select 
			string_agg(distinct (coalesce(firstname,' ')||coalesce(middlename,' ')|| 
			coalesce(lastname,' ')::text),',') 
			from kaveri.partyinfo where applicationnumber=dm.applicationnumber  
			and ispresenter is true group by applicationnumber)as presentername ,
			--pi1.presentername,
			sa.articlenamee AS descriptionofdocument, 
			max(pm.sroconsideration) as consideration_fees,
			max(pm.sromarketvalue) as marketvalue,
			pm.propertytypeid ,
			case when dm.finalregistrationnumber is not null
			then dm.finalregistrationnumber else dm.pendingdocumentnumber end documentnumber,
			b.booknameenglish ,
			null  as volumenumber,
			(select sum(amsreg.totalamount)
			from kaveri.ams_reg_epaymenttransdetails amsreg 
			where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false) as Treasury_amount,
			(select to_char(amsreg.inserteddatetime,'dd-MM-yyyy')
			from kaveri.ams_reg_epaymenttransdetails amsreg
			where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false limit 1)  as Challan_date ,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofcompletion,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofreturn,
			dm.uploaddocdeedpath as copy_of_document,
			a.currentstatus 

			from  kaveri.documentmaster dm
			join kaveri.applicantapplicationdetails a on dm.applicationnumber=a.applicationnumber 
			join  kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber 
			join kaveri.stamparticles sa on pm.stamparticlecode=sa.stamparticlecode 
			JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
			join kaveri.booktypemaster b on dm.bookid=b.bookid 
			--left join kaveri.ams_reg_epaymenttransdetails amsreg on 
			--amsreg.applicationnumber = dm.applicationnumber and amsreg.isdelete=false  
			where 
			
			(dm.registrationdatetime between _fromdate	and _todate + INTERVAL '1 day'  )
			and 
			
			(

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			and
			
				(

                    CASE

                    WHEN _srocode <> 0 THEN  dm.srocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  dm.finalregistrationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
               and 
			    
			 dm.isregistrationcompleted=true
			 group by dsm.districtnamee,sm.sronamee,dm.finalregistrationnumber,dm.applicationnumber,
			 sa.articlenamee,dm.pendingdocumentnumber,b.booknameenglish,
			 --,booknameenglish,
			dm.registrationdatetime,dm.uploaddocdeedpath,dm.presentdatetime,pm.propertytypeid,
			dsm.districtcode,
			dm.srocode,
			dm.isregistrationcompleted,
			dm.registrationdatetime,a.currentstatus )

			select 
			a.districtcode,
			a.srocode,
			a.isregistrationcompleted,
			a.registrationdatetime,
			a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) stampduty,
			sum(case when fr.feerulecode=59  then amountpaid else 0 end) cess,
			sum(case when a.propertytypeid=28 and fr.feerulecode=58 then amountpaid else 0 end ) as municipalsurcharge,
			sum(case when a.propertytypeid=17 and fr.feerulecode=58 then amountpaid else 0 end ) as taluksurcharge,
			sum(case when fr.feerulecode in (36,58,59)  then amountpaid else 0 end)  as Total_duty,
			a.documentnumber,a.booknameenglish,a.volumenumber,
			a.dateofcompletion,a.dateofreturn,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end) registrationfees,
			sum(case when fr.feerulecode=41 then amountpaid else 0 end) as feesforcopies,
			sum(case when fr.feerulecode=2 then amountpaid else 0 end) miscelaneousfees,
			sum(case when fr.feerulecode in (34,91)then amountpaid else 0 end) otherstampduty,
			NULL::numeric miscellaneous_article_fees,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=41 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=2 then amountpaid else 0 end)+
			sum(case when fr.feerulecode  in (34,91)then amountpaid else 0 end) Total_fees2,
			a.Treasury_amount,
			a.Challan_date,
			string_agg(distinct (case when fr.feerulecode=6 then r.receiptnumber::text  else ' ' end ),' ')as dailymutationreceipts,
			sum(case when fr.feerulecode=6 then fr.amountpaid else 0 end) mutationfees,
			string_agg(distinct ( case when fr.feerulecode=6 then to_char(r.dateofreceipt,'DD-MM-YYYY')  else ' ' end ),' ')as mutationfeedate,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			a.copy_of_document,
			a.currentstatus 

			from 
			a
			left join 	kaveri.feesrequired fr on a.applicationnumber=fr.applicationnumber
			left join kaveri.receiptmaster r on fr.receiptid=r.receiptid
			
			group by a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,
			a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			a.documentnumber,a.booknameenglish,
			a.volumenumber,a.Treasury_amount,
			a.Challan_date,a.dateofcompletion,a.dateofreturn,a.copy_of_document,a.propertytypeid,
			a.districtcode,
			a.srocode,
			a.isregistrationcompleted,
			a.registrationdatetime,a.currentstatus 
			)
			select * from cte
			
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

 elsif pagenumber = -1 or  pagesize = -1 then 
 
 		return query
			with cte as (with a as ( select 
			dsm.districtcode,
			dm.srocode,
			dm.isregistrationcompleted,
			dm.registrationdatetime,
			dsm.districtnamee,
			sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,
			to_char(dm.presentdatetime,'dd-MM-YYYY') presentdate,
			(select 
			string_agg(distinct (coalesce(firstname,' ')||coalesce(middlename,' ')|| 
			coalesce(lastname,' ')::text),',') 
			from kaveri.partyinfo where applicationnumber=dm.applicationnumber  
			and ispresenter is true group by applicationnumber)as presentername ,
			--pi1.presentername,
			sa.articlenamee AS descriptionofdocument, 
			max(pm.sroconsideration) as consideration_fees,
			max(pm.sromarketvalue) as marketvalue,
			pm.propertytypeid ,
			case when dm.finalregistrationnumber is not null
			then dm.finalregistrationnumber else dm.pendingdocumentnumber end documentnumber,
			b.booknameenglish ,
			null  as volumenumber,
			(select sum(amsreg.totalamount)
			from kaveri.ams_reg_epaymenttransdetails amsreg 
			where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false) as Treasury_amount,
			(select to_char(amsreg.inserteddatetime,'dd-MM-yyyy')
			from kaveri.ams_reg_epaymenttransdetails amsreg
			where amsreg.applicationnumber=dm.applicationnumber 
			and isdelete=false limit 1)  as Challan_date ,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofcompletion,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofreturn,
			dm.uploaddocdeedpath as copy_of_document,
			a.currentstatus 

			from  kaveri.documentmaster dm
			join kaveri.applicantapplicationdetails a on dm.applicationnumber=a.applicationnumber 
			join  kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber 
			join kaveri.stamparticles sa on pm.stamparticlecode=sa.stamparticlecode 
			JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
			join kaveri.booktypemaster b on dm.bookid=b.bookid 
			--left join kaveri.ams_reg_epaymenttransdetails amsreg on 
			--amsreg.applicationnumber = dm.applicationnumber and amsreg.isdelete=false  
			where 
			
			(dm.registrationdatetime between _fromdate	and _todate + INTERVAL '1 day'  )
			and 
			
			(

                    CASE

                    WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode

                    ELSE TRUE

                    end

                    )
			and
			
				(

                    CASE

                    WHEN _srocode <> 0 THEN  dm.srocode = _srocode

                    ELSE TRUE

                    end

                    )
			 
			  and 
			  (

                    CASE

                    WHEN _documentnumber<>null THEN  dm.finalregistrationnumber=_documentnumber

                    ELSE TRUE

                    end

                    )
                    
               and 
			    
			 dm.isregistrationcompleted=true
			 group by dsm.districtnamee,sm.sronamee,dm.finalregistrationnumber,dm.applicationnumber,
			 sa.articlenamee,dm.pendingdocumentnumber,b.booknameenglish,
			 --,booknameenglish,
			dm.registrationdatetime,dm.uploaddocdeedpath,dm.presentdatetime,pm.propertytypeid,
			dsm.districtcode,
			dm.srocode,
			dm.isregistrationcompleted,
			dm.registrationdatetime,a.currentstatus )

			select 
			a.districtcode,
			a.srocode,
			a.isregistrationcompleted,
			a.registrationdatetime,
			a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) stampduty,
			sum(case when fr.feerulecode=59  then amountpaid else 0 end) cess,
			sum(case when a.propertytypeid=28 and fr.feerulecode=58 then amountpaid else 0 end ) as municipalsurcharge,
			sum(case when a.propertytypeid=17 and fr.feerulecode=58 then amountpaid else 0 end ) as taluksurcharge,
			sum(case when fr.feerulecode in (36,58,59)  then amountpaid else 0 end)  as Total_duty,
			a.documentnumber,a.booknameenglish,a.volumenumber,
			a.dateofcompletion,a.dateofreturn,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end) registrationfees,
			sum(case when fr.feerulecode=41 then amountpaid else 0 end) as feesforcopies,
			sum(case when fr.feerulecode=2 then amountpaid else 0 end) miscelaneousfees,
			sum(case when fr.feerulecode in (34,91)then amountpaid else 0 end) otherstampduty,
			NULL::numeric miscellaneous_article_fees,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=41 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=2 then amountpaid else 0 end)+
			sum(case when fr.feerulecode  in (34,91)then amountpaid else 0 end) Total_fees2,
			a.Treasury_amount,
			a.Challan_date,
			string_agg(distinct (case when fr.feerulecode=6 then r.receiptnumber::text  else ' ' end ),' ')as dailymutationreceipts,
			sum(case when fr.feerulecode=6 then fr.amountpaid else 0 end) mutationfees,
			string_agg(distinct ( case when fr.feerulecode=6 then to_char(r.dateofreceipt,'DD-MM-YYYY')  else ' ' end ),' ')as mutationfeedate,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			a.copy_of_document,
			a.currentstatus 

			from 
			a
			left join 	kaveri.feesrequired fr on a.applicationnumber=fr.applicationnumber
			left join kaveri.receiptmaster r on fr.receiptid=r.receiptid
			
			group by a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,
			a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			a.documentnumber,a.booknameenglish,
			a.volumenumber,a.Treasury_amount,
			a.Challan_date,a.dateofcompletion,a.dateofreturn,a.copy_of_document,a.propertytypeid,
			a.districtcode,
			a.srocode,
			a.isregistrationcompleted,
			a.registrationdatetime,a.currentstatus 
			)
			select * from cte;
			
 
 
 
 end if;
		

 

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg_scheduler(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_register_of_fees_statutory_docreg_test(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg_test(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document character varying, considerationamount numeric, marketvalue bigint, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid character varying, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees numeric, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if pagenumber <> -1 and pagesize <> -1 then 

			return query
			with cte as (
				select 
				dsm.districtnamee,s.sronamee as sroname, rd.numberinregistered as finalregistrationnumber, rd.applicationnumber ,
				rd.presentdatetime::text as presentationdatetime,rd.presenternamee::text as presenter_name,rd.description_of_docs as description_of_document,
				rd.consideration as considerationamount, rd.marketvalue::bigint as marketvalue, rd.stampduty, rd.cessduty as cess, rd.muncipalsurchargeduty as surcharge_duty_muncipal,
				rd.talukaboardsurcharge as surcharge_duty_taluk, 
				null::numeric as total_duty, 
				rd.numberinregistered as documentnumber, dm.bookid::varchar, rd.volumneno as volumenumber,rd.dateofcompletion::text as dateofcompletion,
				rd.dateofreturn::text as dateofreturn, rd.feesforregistrationofdocs as registrationfees,
				null::numeric as feescopygranted,
				null::numeric as miscfees,
				rd.otherstampduty::numeric as otherstampduty,
				null::numeric as miscarticlefees, 
				null::numeric as total_fees, rd.feesremittedtotreasury::numeric as treasury_fees,rd.transactiondate::text as feedate_treasury,
				null as dailymutationreceipts,
				rd.mutationfee::numeric as mutationfees, rd.mutationfeeremittedtotreasurydate::text as mutationfeedate,
				null as transmission_of_memorandum,
				null as transmission_of_memoranda,
				rd.signatureofregisteringofficer as signature_of_register, rd.remarks,
				null as copy_of_document
				from 
				kaveri.revised_form_7_statutory_doc_reg rd
				join kaveri.documentmaster dm on rd.applicationnumber = dm.applicationnumber
				join kaveri.sromaster s on s.srocode = dm.srocode
				join kaveri.districtmaster dsm on dsm.districtcode = s.districtcode
				where 
				(CASE WHEN _documentnumber<>(case when (_documentnumber<>null and _documentnumber<>'') then _documentnumber else  '' end) THEN  rd.numberinregistered=_documentnumber ELSE TRUE end)
				and
				(rd.dateofcompletion between _fromdate	and _todate + INTERVAL '1 day'  )
				and 
				(CASE WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode ELSE TRUE end)
				and
				(CASE WHEN _srocode <> 0 THEN  dm.srocode = _srocode ELSE TRUE end)
			--				and dm.isregistrationcompleted=true
				)
				select * from cte
				right join (select null::bigint as total_rows) total_row on true
				OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

 elsif pagenumber = -1 or  pagesize = -1 then 
 
 		return query
			with cte as (
			select 
				dsm.districtnamee,s.sronamee as sroname, rd.numberinregistered as finalregistrationnumber, rd.applicationnumber ,
				rd.presentdatetime::text as presentationdatetime,rd.presenternamee::text as presenter_name,rd.description_of_docs as description_of_document,
				rd.consideration as considerationamount, rd.marketvalue::bigint as marketvalue, rd.stampduty, rd.cessduty as cess, rd.muncipalsurchargeduty as surcharge_duty_muncipal,
				rd.talukaboardsurcharge as surcharge_duty_taluk, 
				null::numeric as total_duty, 
				rd.numberinregistered as documentnumber, dm.bookid::varchar, rd.volumneno as volumenumber,rd.dateofcompletion::text as dateofcompletion,
				rd.dateofreturn::text as dateofreturn, rd.feesforregistrationofdocs as registrationfees,
				null::numeric as feescopygranted,
				null::numeric as miscfees,
				rd.otherstampduty::numeric as otherstampduty,
				null::numeric as miscarticlefees, 
				null::numeric as total_fees, rd.feesremittedtotreasury::numeric as treasury_fees,rd.transactiondate::text as feedate_treasury,
				null as dailymutationreceipts,
				rd.mutationfee::numeric as mutationfees, rd.mutationfeeremittedtotreasurydate::text as mutationfeedate,
				null as transmission_of_memorandum,
				null as transmission_of_memoranda,
				rd.signatureofregisteringofficer as signature_of_register, rd.remarks,
				null as copy_of_document
				from 
				kaveri.revised_form_7_statutory_doc_reg rd
				join kaveri.documentmaster dm on rd.applicationnumber = dm.applicationnumber
				join kaveri.sromaster s on s.srocode = dm.srocode
				join kaveri.districtmaster dsm on dsm.districtcode = s.districtcode
				where 
				(CASE WHEN _documentnumber<>(case when (_documentnumber<>null and _documentnumber<>'') then _documentnumber else  '' end) THEN  rd.numberinregistered=_documentnumber ELSE TRUE end)
				and
				(rd.dateofcompletion between _fromdate	and _todate + INTERVAL '1 day'  )
				and 
				(CASE WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode ELSE TRUE end)
				and
				(CASE WHEN _srocode <> 0 THEN  dm.srocode = _srocode ELSE TRUE end)
				
--				and dm.isregistrationcompleted=true
			)
			select * from cte
			right join (select null::bigint as total_rows) total_row on true;
end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_docreg_test(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_register_of_fees_statutory_ecreg(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_ecreg(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber text, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document text, considerationamount numeric, marketvalue numeric, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid text, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees text, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, total_amount_collected bigint, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    pageoffset integer := 0;
BEGIN
    IF pagenumber IS NULL OR pagesize IS NULL THEN
        pagenumber := -1;
        pagesize   := -1;
    END IF;

    pageoffset := (pagenumber - 1) * pagesize;
    IF pagenumber <> -1 AND pagesize <> -1 THEN

        RETURN QUERY
        WITH base AS (
            SELECT
                dsm.districtnamee::character varying      AS districtname,
                sr.sronamee::character varying            AS sroname,
                e.applicationnumber,
                e.ecid,
                e.kaverisrocode                           AS srocode,
                NULL::integer                             AS bookid,
                COALESCE(e.ecnumber, e.certificatenumber) AS regnumber,
                e.submitteddatetime::date                 AS presentation_date,
                e.signeddatetime::date                    AS date_of_completion,
                e.signeddatetime::date                    AS date_of_return
            FROM kaveri.ec_applicationdetails e
            JOIN kaveri.sromaster sr
              ON e.kaverisrocode = sr.srocode
            JOIN kaveri.districtmaster dsm
              ON sr.districtcode = dsm.districtcode
            WHERE e.signeddatetime BETWEEN _fromdate AND (_todate + INTERVAL '1 day')
              AND (_districtcode = 0 OR dsm.districtcode = _districtcode)
              AND (_srocode = 0 OR e.kaverisrocode = _srocode)
              AND (
                    _documentnumber IS NULL
                    OR _documentnumber = ''
                    OR e.applicationnumber = _documentnumber
                  )
        ),
        ecids AS (
            SELECT ecid
            FROM base
        ),
        presenter AS (
            SELECT
                b.applicationnumber,
                MAX(t.remittername) AS presenter_name
            FROM base b
            JOIN kaveri.ams_reg_epaymenttransdetails t
              ON t.isdelete = FALSE
             AND (t.ecid = b.ecid OR t.applicationnumber = b.applicationnumber)
            GROUP BY b.applicationnumber
        ),
        value AS (
            SELECT
                b.applicationnumber,
                NULL::numeric           AS consideration,
                NULL::numeric           AS market_value,
                'searches and inspection'::text AS articlenamee
            FROM base b
        ),
        fees AS (
            SELECT
                b.applicationnumber,
                0::numeric AS reg_fee,
                SUM( CASE WHEN rf.feeruleid IN (23,134,135,136,137,139,140) THEN rf.payableamount ELSE 0 END ) AS copy_fee
            FROM base b
            LEFT JOIN kaveri.ec_requiredfees rf
              ON rf.ecid   = b.ecid
             AND rf.ispaid = TRUE
            GROUP BY b.applicationnumber
        ),
        treasury AS (
            SELECT
                are2.ecid,
                SUM(DISTINCT ack.amount)            AS treasury_amount,
                MAX(ack.transactiontimestamp::date) AS treasury_date
            FROM kaveri.ams_reg_epaymenttransdetails are2
            JOIN ecids e
              ON e.ecid = are2.ecid
            JOIN kaveri.ams_reg_epaymentbankackdetails ack
              ON ack.deptreferencecode = are2.deptreferencecode
             AND ack.paymentstatuscode IN ('10700066','10700072')
            WHERE are2.isdelete = FALSE
            GROUP BY are2.ecid
        ),
        docs AS (
            SELECT
                s.applicationnumber,
                MAX(s.filepath)::text AS copy_of_document
            FROM kaveri.signed_file_upload_details s
            GROUP BY s.applicationnumber
        ),
        final AS (
            SELECT
                b.districtname,
                b.sroname,
                b.applicationnumber,
                b.presentation_date                     AS date_of_presentation,
                pr.presenter_name                       AS name_of_presenter,
                v.articlenamee                          AS description_of_document,
                v.consideration                         AS consideration,
                v.market_value                          AS market_value,
                NULL::numeric                           AS stamp_duty_a,
                NULL::numeric                           AS cess_on_duty_b,
                NULL::numeric                           AS surcharge_municipal_c,
                NULL::numeric                           AS surcharge_taluk_d,
                NULL::numeric                           AS total_duty_on_document_e,
                b.regnumber                             AS number_in_register,
                b.bookid                                AS which_book,
                NULL::text                              AS volume_no,
                b.date_of_completion                    AS date_of_completion,
                b.date_of_return                        AS date_of_return,
                0::numeric                              AS fees_for_registration_of_documents,
                COALESCE(f.copy_fee,0)                  AS fees_for_copies_granted,
                0::numeric                              AS scanning_fees,
                NULL::numeric                           AS other_stamp_duty,
                NULL::numeric                           AS article_of_table_of_fees,
                COALESCE(f.copy_fee,0)                  AS total_of_cols_14_15_16,
                t.treasury_amount                       AS fees_remitted_to_treasury_amount,
                t.treasury_date                         AS fees_remitted_to_treasury_date,
                NULL::numeric                           AS daily_mutation_receipts,
                NULL::date                              AS mutation_fee_remitted_date,
                COALESCE(f.reg_fee,0) + COALESCE(f.copy_fee,0) AS total_amount,
                NULL::text                              AS signature_of_registering_officer,
                NULL::text                              AS remarks,
                d.copy_of_document
            FROM base b
            LEFT JOIN presenter pr ON pr.applicationnumber = b.applicationnumber
            LEFT JOIN value     v  ON v.applicationnumber  = b.applicationnumber
            LEFT JOIN fees      f  ON f.applicationnumber  = b.applicationnumber
            LEFT JOIN treasury  t  ON t.ecid               = b.ecid
            LEFT JOIN docs      d  ON d.applicationnumber  = b.applicationnumber
        ),
        base_count AS (
            SELECT COUNT(*)::bigint AS totalcount
            FROM base
        ),
        result AS (
            SELECT DISTINCT
                f.districtname,
                f.sroname,
                NULL::text                                   AS finalregistrationnumber,
                f.applicationnumber::character varying       AS applicationnumber2,
                f.date_of_presentation::text                 AS presentationdatetime,
                f.name_of_presenter::text                    AS presenter_name,
                f.description_of_document::text              AS description_of_document,
                f.consideration                              AS considerationamount,
                f.market_value                               AS marketvalue,
                f.stamp_duty_a                               AS stampduty,
                f.cess_on_duty_b                             AS cess,
                f.surcharge_municipal_c                      AS surcharge_duty_muncipal,
                f.surcharge_taluk_d                          AS surcharge_duty_taluk,
                f.total_duty_on_document_e                   AS total_duty,
                f.number_in_register::character varying      AS documentnumber,
                f.which_book::text                           AS bookid,
                f.volume_no::text                            AS volumenumber,
                f.date_of_completion::text                   AS dateofcompletion,
                f.date_of_return::text                       AS dateofreturn,
                f.fees_for_registration_of_documents::text   AS registrationfees,
                f.fees_for_copies_granted                    AS feescopygranted,
                f.scanning_fees                              AS miscfees,
                f.other_stamp_duty                           AS otherstampduty,
                f.article_of_table_of_fees                   AS miscarticlefees,
                f.total_of_cols_14_15_16                     AS total_fees,
                f.fees_remitted_to_treasury_amount           AS treasury_fees,
                f.fees_remitted_to_treasury_date::text       AS feedate_treasury,
                f.daily_mutation_receipts::text              AS dailymutationreceipts,
                f.daily_mutation_receipts                    AS mutationfees,
                f.mutation_fee_remitted_date::text           AS mutationfeedate,
                NULL::text                                   AS transmission_of_memorandum,
                NULL::text                                   AS transmission_of_memoranda,
                f.total_amount::bigint                       AS total_amount_collected,
                f.signature_of_registering_officer           AS signature_of_register,
                f.remarks                                    AS remarks,
                f.copy_of_document                           AS copy_of_document,
                bc.totalcount                                AS totalcount
            FROM final f
            CROSS JOIN base_count bc
        )
        SELECT *
        FROM result
        ORDER BY dateofcompletion, documentnumber
        OFFSET pageoffset
        FETCH NEXT pagesize ROWS ONLY;
    ELSE

        RETURN QUERY
        WITH base AS (
            SELECT
                dsm.districtnamee::character varying      AS districtname,
                sr.sronamee::character varying            AS sroname,
                e.applicationnumber,
                e.ecid,
                e.kaverisrocode                           AS srocode,
                NULL::integer                             AS bookid,
                COALESCE(e.ecnumber, e.certificatenumber) AS regnumber,
                e.submitteddatetime::date                 AS presentation_date,
                e.signeddatetime::date                    AS date_of_completion,
                e.signeddatetime::date                    AS date_of_return
            FROM kaveri.ec_applicationdetails e
            JOIN kaveri.sromaster sr
              ON e.kaverisrocode = sr.srocode
            JOIN kaveri.districtmaster dsm
              ON sr.districtcode = dsm.districtcode
            WHERE e.signeddatetime BETWEEN _fromdate AND (_todate + INTERVAL '1 day')
              AND (_districtcode = 0 OR dsm.districtcode = _districtcode)
              AND (_srocode = 0 OR e.kaverisrocode = _srocode)
              AND (
                    _documentnumber IS NULL
                    OR _documentnumber = ''
                    OR e.applicationnumber = _documentnumber
                  )
        ),
        ecids AS (
            SELECT ecid
            FROM base
        ),
        presenter AS (
            SELECT
                b.applicationnumber,
                MAX(t.remittername) AS presenter_name
            FROM base b
            JOIN kaveri.ams_reg_epaymenttransdetails t
              ON t.isdelete = FALSE
             AND (t.ecid = b.ecid OR t.applicationnumber = b.applicationnumber)
            GROUP BY b.applicationnumber
        ),
        value AS (
            SELECT
                b.applicationnumber,
                NULL::numeric           AS consideration,
                NULL::numeric           AS market_value,
                'searches and inspection'::text AS articlenamee
            FROM base b
        ),
        fees AS (
            SELECT
                b.applicationnumber,
                0::numeric AS reg_fee,
                SUM(CASE WHEN rf.feeruleid IN (23,134,135,136,137,139,140) THEN rf.payableamount ELSE 0 END ) AS copy_fee
            FROM base b
            LEFT JOIN kaveri.ec_requiredfees rf
              ON rf.ecid   = b.ecid
             AND rf.ispaid = TRUE
            GROUP BY b.applicationnumber
        ),
        treasury AS (
            SELECT
                are2.ecid,
                SUM(DISTINCT ack.amount)            AS treasury_amount,
                MAX(ack.transactiontimestamp::date) AS treasury_date
            FROM kaveri.ams_reg_epaymenttransdetails are2
            JOIN ecids e
              ON e.ecid = are2.ecid
            JOIN kaveri.ams_reg_epaymentbankackdetails ack
              ON ack.deptreferencecode = are2.deptreferencecode
             AND ack.paymentstatuscode IN ('10700066','10700072')
            WHERE are2.isdelete = FALSE
            GROUP BY are2.ecid
        ),
        docs AS (
            SELECT
                s.applicationnumber,
                MAX(s.filepath)::text AS copy_of_document
            FROM kaveri.signed_file_upload_details s
            GROUP BY s.applicationnumber
        ),
        final AS (
            SELECT
                b.districtname,
                b.sroname,
                b.applicationnumber,
                b.presentation_date                     AS date_of_presentation,
                pr.presenter_name                       AS name_of_presenter,
                v.articlenamee                          AS description_of_document,
                v.consideration                         AS consideration,
                v.market_value                          AS market_value,
                NULL::numeric                           AS stamp_duty_a,
                NULL::numeric                           AS cess_on_duty_b,
                NULL::numeric                           AS surcharge_municipal_c,
                NULL::numeric                           AS surcharge_taluk_d,
                NULL::numeric                           AS total_duty_on_document_e,
                b.regnumber                             AS number_in_register,
                b.bookid                                AS which_book,
                NULL::text                              AS volume_no,
                b.date_of_completion                    AS date_of_completion,
                b.date_of_return                        AS date_of_return,
                0::numeric                              AS fees_for_registration_of_documents,
                COALESCE(f.copy_fee,0)                  AS fees_for_copies_granted,
                0::numeric                              AS scanning_fees,
                NULL::numeric                           AS other_stamp_duty,
                NULL::numeric                           AS article_of_table_of_fees,
                COALESCE(f.copy_fee,0)                  AS total_of_cols_14_15_16,
                t.treasury_amount                       AS fees_remitted_to_treasury_amount,
                t.treasury_date                         AS fees_remitted_to_treasury_date,
                NULL::numeric                           AS daily_mutation_receipts,
                NULL::date                              AS mutation_fee_remitted_date,
                COALESCE(f.reg_fee,0) + COALESCE(f.copy_fee,0) AS total_amount,
                NULL::text                              AS signature_of_registering_officer,
                NULL::text                              AS remarks,
                d.copy_of_document
            FROM base b
            LEFT JOIN presenter pr ON pr.applicationnumber = b.applicationnumber
            LEFT JOIN value     v  ON v.applicationnumber  = b.applicationnumber
            LEFT JOIN fees      f  ON f.applicationnumber  = b.applicationnumber
            LEFT JOIN treasury  t  ON t.ecid               = b.ecid
            LEFT JOIN docs      d  ON d.applicationnumber  = b.applicationnumber
        ),
        base_count AS (
            SELECT COUNT(*)::bigint AS totalcount
            FROM base
        ),
        result AS (
            SELECT DISTINCT
                f.districtname,
                f.sroname,
                NULL::text                                   AS finalregistrationnumber,
                f.applicationnumber::character varying       AS applicationnumber2,
                f.date_of_presentation::text                 AS presentationdatetime,
                f.name_of_presenter::text                    AS presenter_name,
                f.description_of_document::text              AS description_of_document,
                f.consideration                              AS considerationamount,
                f.market_value                               AS marketvalue,
                f.stamp_duty_a                               AS stampduty,
                f.cess_on_duty_b                             AS cess,
                f.surcharge_municipal_c                      AS surcharge_duty_muncipal,
                f.surcharge_taluk_d                          AS surcharge_duty_taluk,
                f.total_duty_on_document_e                   AS total_duty,
                f.number_in_register::character varying      AS documentnumber,
                f.which_book::text                           AS bookid,
                f.volume_no::text                            AS volumenumber,
                f.date_of_completion::text                   AS dateofcompletion,
                f.date_of_return::text                       AS dateofreturn,
                f.fees_for_registration_of_documents::text   AS registrationfees,
                f.fees_for_copies_granted                    AS feescopygranted,
                f.scanning_fees                              AS miscfees,
                f.other_stamp_duty                           AS otherstampduty,
                f.article_of_table_of_fees                   AS miscarticlefees,
                f.total_of_cols_14_15_16                     AS total_fees,
                f.fees_remitted_to_treasury_amount           AS treasury_fees,
                f.fees_remitted_to_treasury_date::text       AS feedate_treasury,
                f.daily_mutation_receipts::text              AS dailymutationreceipts,
                f.daily_mutation_receipts                    AS mutationfees,
                f.mutation_fee_remitted_date::text           AS mutationfeedate,
                NULL::text                                   AS transmission_of_memorandum,
                NULL::text                                   AS transmission_of_memoranda,
                f.total_amount::bigint                       AS total_amount_collected,
                f.signature_of_registering_officer           AS signature_of_register,
                f.remarks                                    AS remarks,
                f.copy_of_document                           AS copy_of_document,
                bc.totalcount                                AS totalcount
            FROM final f
            CROSS JOIN base_count bc
        )
        SELECT *
        FROM result
        ORDER BY dateofcompletion, documentnumber;

    END IF;
END;
$$;


