--
-- Name: fn_mis_daily_register_of_fees_statutory_ecreg_02122025(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_ecreg_02122025(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber text, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document text, considerationamount numeric, marketvalue numeric, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid text, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees text, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if pagenumber <> -1 and pagesize <> -1 then
			return query
			with cte as (			
					select dsm.districtnamee,s.sronamee as sroname, rd.numberinregister::text as finalregistrationnumber, rd.applicationnumber ,
					rd.dateofpresenter::text as presentationdatetime,rd.nameofpresenter::text as presenter_name,rd.descriptionofdocument as description_of_document,
					null::numeric as considerationamount, 
					null::numeric as marketvalue, 
					null::numeric as stampduty, 
					null::numeric as cess, 
					null::numeric as surcharge_duty_muncipal,
					null::numeric as surcharge_duty_taluk, 
					null::numeric as total_duty, 
					rd.numberinregister as documentnumber, rd.book::text as bookid, rd.volumeno as volumenumber,rd.dateofcompletion::text as dateofcompletion,
					rd.dateofreturn::text as dateofreturn, rd.feesforregistrationofdocuments as registrationfees,
					null::numeric as feescopygranted,
					null::numeric as miscfees,
					null::numeric as otherstampduty,
					null::numeric as miscarticlefees, 
					null::numeric as total_fees, 
					rd.feesremittedtotreasuryamount::numeric as treasury_fees,rd.feesremittedtotreasurydate::text as feedate_treasury,
					null as dailymutationreceipts,
					null::numeric as mutationfees, rd.mutationfeeremittedtotreasurywithdate::text as mutationfeedate,
					null as transmission_of_memorandum,
					null as transmission_of_memoranda,
					rd.signatureofregisteringofficer as signature_of_register, rd.remarks,
					null as copy_of_document
					from kaveri.revised_form_7_statutory_ec rd
					join kaveri.ec_applicationdetails dm on rd.applicationnumber = dm.applicationnumber
					join kaveri.sromaster s on s.srocode = dm.kaverisrocode
					join kaveri.districtmaster dsm on dsm.districtcode = s.districtcode
					where 
					(rd.dateofcompletion between _fromdate	and _todate + INTERVAL '1 day'  ) 
					and 
					(CASE WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode ELSE TRUE end)
					and 
					(CASE WHEN _srocode <> 0 THEN dm.kaverisrocode = _srocode ELSE TRUE end)
					and 
					(CASE WHEN _documentnumber<>(case when (_documentnumber<>null and _documentnumber<>'') then _documentnumber else  '' end) THEN  rd.numberinregister=_documentnumber ELSE TRUE end)
                    -- and  a.currentstatus='CE110'
					)
			select * from cte
			right join (select null::bigint as total_rows) total_row on true
			OFFSET PageOffset
			FETCH NEXT pagesize ROWS ONLY;

 elsif pagenumber = -1 or  pagesize = -1 then 
		return query
			with cte as (
			select dsm.districtnamee,s.sronamee as sroname, rd.numberinregister::text as finalregistrationnumber, rd.applicationnumber ,
					rd.dateofpresenter::text as presentationdatetime,rd.nameofpresenter::text as presenter_name,rd.descriptionofdocument as description_of_document,
					null::numeric as considerationamount, 
					null::numeric as marketvalue, 
					null::numeric as stampduty, 
					null::numeric as cess, 
					null::numeric as surcharge_duty_muncipal,
					null::numeric as surcharge_duty_taluk, 
					null::numeric as total_duty,  
					rd.numberinregister as documentnumber, rd.book::text as bookid, rd.volumeno as volumenumber,rd.dateofcompletion::text as dateofcompletion,
					rd.dateofreturn::text as dateofreturn, rd.feesforregistrationofdocuments as registrationfees,
					null::numeric as feescopygranted,
					null::numeric as miscfees,
					null::numeric as otherstampduty,
					null::numeric as miscarticlefees, 
					null::numeric as total_fees, rd.feesremittedtotreasuryamount::numeric as treasury_fees,rd.feesremittedtotreasurydate::text as feedate_treasury,
					null as dailymutationreceipts,
					null::numeric as mutationfees, rd.mutationfeeremittedtotreasurywithdate::text as mutationfeedate,
					null as transmission_of_memorandum,
					null as transmission_of_memoranda,
					rd.signatureofregisteringofficer as signature_of_register, rd.remarks,
					null as copy_of_document
					from kaveri.revised_form_7_statutory_ec rd
					join kaveri.ec_applicationdetails dm on rd.applicationnumber = dm.applicationnumber
					join kaveri.sromaster s on s.srocode = dm.kaverisrocode
					join kaveri.districtmaster dsm on dsm.districtcode = s.districtcode
					where 
					(rd.dateofcompletion between _fromdate	and _todate + INTERVAL '1 day'  ) 
					and 
					(CASE WHEN _districtcode <> 0 THEN  dsm.districtcode = _districtcode ELSE TRUE end)
					and 
					(CASE WHEN _srocode <> 0 THEN  dm.kaverisrocode = _srocode ELSE TRUE end)
					and 
					(CASE WHEN _documentnumber<>(case when (_documentnumber<>null and _documentnumber<>'') then _documentnumber else  '' end) THEN  rd.numberinregister=_documentnumber ELSE TRUE end)
                    -- and  a.currentstatus='CE110'
					) 
			select * from cte
			right join (select null::bigint as total_rows) total_row on true;
end if;
END;
$$;


