CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_ecreg_newtest(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber text, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document text, considerationamount numeric, marketvalue numeric, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid text, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees text, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, total_amount_collected bigint, signature_of_register text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    pageoffset integer := 0;
BEGIN
    IF pagenumber IS NULL OR pagesize IS NULL THEN
        pagenumber := -1;
        pagesize   := -1;
    END IF;

    pageoffset := (pagenumber - 1) * pagesize;
    IF pagenumber <> -1 AND pagesize <> -1 THEN

        RETURN QUERY
		select ag.districtname,ag.sroname,ag.finalregistrationnumber,ag.applicationnumber2,ag.presentationdatetime,ag.presenter_name
,ag.description_of_document,ag.considerationamount,ag.marketvalue,ag.stampduty,ag.cess,ag.surcharge_duty_muncipal,ag.surcharge_duty_taluk
,ag.total_duty,ag.documentnumber,ag.bookid,ag.volumenumber,ag.dateofcompletion,ag.dateofreturn,ag.registrationfees,ag.feescopygranted,ag.miscfees
,ag.otherstampduty,ag.miscarticlefees,ag.total_fees,ag.treasury_fees,ag.feedate_treasury,ag.dailymutationreceipts,ag.mutationfees
,ag.mutationfeedate,ag.transmission_of_memorandum,ag.transmission_of_memoranda
,ag.total_amount_collected,ag.signature_of_register,ag.remarks,ag.copy_of_document,count(*) over()::bigint as totalcount
		from  kaveri.revised_form_7_statutory_ec_reg ag
		join kaveri.ec_applicationdetails e on ag.applicationnumber2=e.applicationnumber
            JOIN kaveri.sromaster sr
              ON e.kaverisrocode = sr.srocode
            JOIN kaveri.districtmaster dsm
              ON sr.districtcode = dsm.districtcode
            WHERE e.signeddatetime BETWEEN _fromdate AND (_todate + INTERVAL '1 day')
              AND (_districtcode = 0 OR dsm.districtcode = _districtcode)
              AND (_srocode = 0 OR e.kaverisrocode = _srocode)
              AND (
                    _documentnumber IS NULL
                    OR _documentnumber = ''
                    OR e.applicationnumber = _documentnumber
                  )
				   OFFSET PageOffset
                FETCH NEXT pagesize ROWS ONLY;
				
elsif pagenumber = -1 or  pagesize = -1 then

	  RETURN QUERY
		select ag.districtname,ag.sroname,ag.finalregistrationnumber,ag.applicationnumber2,ag.presentationdatetime,ag.presenter_name
,ag.description_of_document,ag.considerationamount,ag.marketvalue,ag.stampduty,ag.cess,ag.surcharge_duty_muncipal,ag.surcharge_duty_taluk
,ag.total_duty,ag.documentnumber,ag.bookid,ag.volumenumber,ag.dateofcompletion,ag.dateofreturn,ag.registrationfees,ag.feescopygranted,ag.miscfees
,ag.otherstampduty,ag.miscarticlefees,ag.total_fees,ag.treasury_fees,ag.feedate_treasury,ag.dailymutationreceipts,ag.mutationfees
,ag.mutationfeedate,ag.transmission_of_memorandum,ag.transmission_of_memoranda
,ag.total_amount_collected,ag.signature_of_register,ag.remarks,ag.copy_of_document,count(*) over()::bigint as totalcount
		from  kaveri.revised_form_7_statutory_ec_reg ag
		join kaveri.ec_applicationdetails e on ag.applicationnumber2=e.applicationnumber
            JOIN kaveri.sromaster sr
              ON e.kaverisrocode = sr.srocode
            JOIN kaveri.districtmaster dsm
              ON sr.districtcode = dsm.districtcode
            WHERE e.signeddatetime BETWEEN _fromdate AND (_todate + INTERVAL '1 day')
              AND (_districtcode = 0 OR dsm.districtcode = _districtcode)
              AND (_srocode = 0 OR e.kaverisrocode = _srocode)
              AND (
                    _documentnumber IS NULL
                    OR _documentnumber = ''
                    OR e.applicationnumber = _documentnumber
                  );
				  
end if;
END;
$$;


