ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_otherfeereg_scheduler(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_daily_register_of_fees_statutory_save(bigint, character varying, numeric, timestamp without time zone, numeric, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_save(_srocode bigint, _documentnumber character varying DEFAULT NULL::character varying, _dailyregtreasamt numeric DEFAULT NULL::numeric, _dailyregtreasdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _dailyregmutfee numeric DEFAULT NULL::numeric, _dailyregmutfeedate timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

DECLARE
v_cnt bigint;
v_docid bigint;

BEGIN 
select count(*) into v_cnt from kaverimis.formno7 a  where a.documentnumber = _documentnumber;
IF (v_cnt = 0 ) then
insert into kaverimis.formno7 
(   form7dataentryid,
    srocode,
    documentnumber,
    dailyregtreasamt,
    dailyregtreasdate,
    dailyregmutfee,
    dailyregmutfeedate,
	insertDatetime 
)
values
(    
	nextval('kaverimis.form7dataentryid_seq'),
     _srocode,
    _documentnumber,
    _dailyregtreasamt,
    _dailyregtreasdate,
    _dailyregmutfee,
    _dailyregmutfeedate,
	CURRENT_TIMESTAMP
) returning form7dataentryid into v_docid;
elseif (v_cnt = 1 ) then
	update 
	kaverimis.formno7 a set
	 dailyregtreasamt=_dailyregtreasamt,
    dailyregtreasdate=_dailyregtreasdate,
    dailyregmutfee=_dailyregmutfee,
    dailyregmutfeedate=_dailyregmutfeedate,
	insertDatetime=CURRENT_TIMESTAMP
	where a.documentnumber = _documentnumber and a.srocode = _srocode
	returning form7dataentryid into v_docid;
	end if;

raise notice 'v_docid=%',v_docid;
return v_docid;
 

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_save(_srocode bigint, _documentnumber character varying, _dailyregtreasamt numeric, _dailyregtreasdate timestamp without time zone, _dailyregmutfee numeric, _dailyregmutfeedate timestamp without time zone) OWNER TO csgadmin;

--
-- Name: fn_mis_daily_register_of_fees_statutory_test(bigint, timestamp without time zone, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_test(_srocode bigint, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _documentnumber character varying DEFAULT NULL::character varying) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber2 character varying, presentationdatetime text, presenter_name text, description_of_document character varying, considerationamount numeric, marketvalue numeric, stampduty numeric, cess numeric, surcharge_duty_muncipal numeric, surcharge_duty_taluk numeric, total_duty numeric, documentnumber character varying, bookid character varying, volumenumber text, dateofcompletion text, dateofreturn text, registrationfees numeric, feescopygranted numeric, miscfees numeric, otherstampduty numeric, miscarticlefees numeric, total_fees numeric, treasury_fees numeric, feedate_treasury text, dailymutationreceipts text, mutationfees numeric, mutationfeedate text, transmission_of_memorandum text, transmission_of_memoranda text, signature_of_register text, remarks text, copy_of_document text)
    LANGUAGE plpgsql
    AS $$


DECLARE
BEGIN 

if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
raise notice 'Documentnumber null';

			return query
			with a as (select     
			dsm.districtnamee,
			sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,
			to_char(dm.presentdatetime,'dd-MM-YYYY') presentdate,
			pi1.presentername,
			sa.articlenamee AS descriptionofdocument, 
			pm.consideration as consideration_fees,
			pm.marketvalue as marketvalue,
			pm.municipalsurcharge,
			pm.Taluksurcharge,
			case when dm.finalregistrationnumber is not null
			then dm.finalregistrationnumber else dm.pendingdocumentnumber end documentnumber,
			b.booknameenglish ,
			null  as volumenumber,
			amsreg.Treasury_amount,
			amsreg.Challan_date,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofcompletion,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofreturn,
			dm.uploaddocdeedpath as copy_of_document

			from  kaveri.documentmaster dm
			join  (select applicationnumber,string_agg(distinct (coalesce(firstname,' ')||coalesce(middlename,' ')|| coalesce(lastname,' ')::text),',') as presentername 
			from kaveri.partyinfo where ispresenter is true group by applicationnumber) pi1   on pi1.applicationnumber = dm.applicationnumber 
			and dm.isregistrationcompleted is true and dm.srocode=_srocode
			join 
			(select applicationnumber,stamparticlecode,max(sroconsideration)
			as consideration,max(sromarketvalue) as marketvalue,
			sum(case when propertytypeid=28 then COALESCE (surcharge,0)  else 0 end) as municipalsurcharge,
			sum(case when propertytypeid=17 then COALESCE (surcharge,0) else 0 end)  as Taluksurcharge
			
			from kaveri.propertymaster 
			group by applicationnumber,stamparticlecode)
			pm on pm.applicationnumber = dm.applicationnumber 
			join kaveri.stamparticles sa on pm.stamparticlecode=sa.stamparticlecode 
			JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
			join kaveri.booktypemaster b on dm.bookid=b.bookid 
			left join (select applicationnumber,sum(totalamount)  as Treasury_amount,
			string_agg(distinct to_char(inserteddatetime,'dd-MM-yyyy'),',') 
			as Challan_date from  kaveri.ams_reg_epaymenttransdetails group by applicationnumber ) 
			amsreg on amsreg.applicationnumber = dm.applicationnumber 
			where 
			 dm.srocode=_srocode and  dm.registrationdatetime::date >= _fromdate
			 and dm.registrationdatetime::date<=_todate  and
			 dm.isregistrationcompleted is true )

			select a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) stampduty,
			sum(case when fr.feerulecode=59  then amountpaid else 0 end) cess,
			a.municipalsurcharge,a.Taluksurcharge,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) +
			sum(case when fr.feerulecode=59  then amountpaid else 0 end)+
			a.municipalsurcharge+a.Taluksurcharge as Total_duty,
			a.documentnumber,a.booknameenglish,a.volumenumber,
			a.dateofcompletion,a.dateofreturn,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end) registrationfees,
			sum(case when fr.feerulecode=30 then amountpaid else 0 end) as feesforcopies,
			sum(case when fr.feerulecode=2 then amountpaid else 0 end) miscelaneousfees,
			sum(case when fr.feerulecode not in (1,36,59,2)then amountpaid else 0 end) otherstampduty,
			NULL::numeric miscellaneous_article_fees,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=30 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=2 then amountpaid else 0 end)+
			sum(case when fr.feerulecode not in (1,36,59,2)then amountpaid else 0 end) Total_fees2,
			a.Treasury_amount,
			a.Challan_date,
			string_agg(distinct (case when fr.feerulecode=6 then r.receiptnumber::text  else ' ' end ),' ')as dailymutationreceipts,
			sum(case when fr.feerulecode=6 then fr.amountpaid else 0 end) mutationfees,
			string_agg(distinct ( case when fr.feerulecode=6 then to_char(r.dateofreceipt,'DD-MM-YYYY')  else ' ' end ),' ')as mutationfeedate,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			a.copy_of_document

			from 
			a
			left join 	kaveri.feesrequired fr on a.applicationnumber=fr.applicationnumber
			left join kaveri.receiptmaster r on fr.receiptid=r.receiptid
			
			group by a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,a.presentdate,
			a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			a.municipalsurcharge,a.Taluksurcharge,a.documentnumber,a.booknameenglish,a.volumenumber,a.Treasury_amount,
			a.Challan_date,a.dateofcompletion,a.dateofreturn,a.copy_of_document

			Union All
			
			select  
					dsm.districtnamee as districtname,
					sr.sronamee as sroname,
					null as finalregistrationnumber,
					eca.applicationnumber,
					to_char(a.applicationenddate,'dd-MM-YYYY') as  signeddatetime,
					c.firstname||c.middlename||c.lastname  as Presentername,
					'ECSearch' as descriptionofdocument,
					null::numeric  as considerationfees,
					null::numeric  as marketvalue,
					sum(case when er.feeruleid=64  then er.payableamount else 0 end) searchfee,
					sum(case when er.feeruleid=23  then er.payableamount else 0 end) searchapplfee,
					null::numeric as muncipalsurcharge,
					null::numeric  as taluksurcharge,
					 sum(case when er.feeruleid=64  then payableamount else 0 end)+
					 sum(case when er.feeruleid=23  then payableamount else 0 end)
					 as Total_duty,
					eca.certificatenumber as documentnumber,
					null as bookname,
					null as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofreturn,
					null as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount) as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
					null as dailymutation_receipt,
					null::numeric as mutationfees,
					null as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					eca.signedform22 as copy_of_document
					
					
					  from kaveri.ec_applicationdetails   eca
					  join kaveri.applicantapplicationdetails a on eca.applicationnumber=a.applicationnumber 
					  join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=eca.userid 
					  left join kaveri.ams_reg_epaymenttransdetails amsre on eca.applicationnumber=amsre.applicationnumber 
					  join (select ecid,feeruleid,sum(payableamount) as payableamount  from kaveri.ec_requiredfees  
					  group by ecid,feeruleid)er on eca.ecid=er.ecid 
					 where 
					 eca.kaverisrocode=_srocode 
					and
					eca.submitteddatetime::date>=_fromdate and eca.submitteddatetime::date <=_todate -- and 
					--eca.signedform22 is not null and length(eca.signedform22 )>0 
					and a.currentstatus='CE110'
					group by dsm.districtnamee,sr.sronamee,eca.applicationnumber,eca.signedform22,
					eca.propertydescription,a.applicationenddate,c.firstname,c.middlename,c.lastname,
					eca.certificatenumber,a.applicationenddate
					

			Union All

			select  
					dsm.districtnamee as district,
					sr.sronamee as sroname,
					null as finalregistrationnumber,
					cca.applicationnumber,
					to_char(a.applicationenddate,'dd-MM-YYYY') as  signeddatetime,
					c.firstname||c.middlename||c.lastname  as Presentername,
					'CCSearch' as descriptionofdocument,
					null::numeric as considerationfees,
					null::numeric as marketvalue,
					sum(case when cr.feeruleid=36  then cr.payableamount else 0 end) stampduty,
					sum(case when cr.feeruleid=14  then cr.payableamount else 0 end) searchfee,
				
					null as muncipalsurcharge,
					null as taluksurcharge,
					 sum(case when cr.feeruleid=36  then payableamount else 0 end)+
					 sum(case when cr.feeruleid=14  then payableamount else 0 end)
					 as Total_duty,
					cca.certificatenumber as documentnumber,
					null::text as bookname,
					null::text as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofreturn,
					null::numeric as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount) as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
					null as dailymutation_receipt,
					null::numeric as mutationfees,
					null::text as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					cca.signedform22 as copy_of_document
					
					
					from kaveri.cc_applicationdetails   cca
					  join kaveri.applicantapplicationdetails a on cca.applicationnumber=a.applicationnumber 
					  join kaveri.sromaster sr on cca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=cca.userid  
					  left join kaveri.ams_reg_epaymenttransdetails amsre on cca.applicationnumber=amsre.applicationnumber 
					  join (select ccid,feeruleid,sum(payableamount) as payableamount  from kaveri.cc_requiredfees  
					  group by ccid,feeruleid)cr on cca.ccid=cr.ccid 
					 where 
					 cca.kaverisrocode=_srocode 
					and
					cca.submitteddatetime::date>=_fromdate and cca.submitteddatetime::date <=_todate 
					--and 
					--cca.signedform22 is not null and length(cca.signedform22 )>0 
					and a.currentstatus='CC109'
					group by dsm.districtnamee,sr.sronamee,cca.applicationnumber,cca.signedform22,
					a.applicationenddate,c.firstname,c.middlename,c.lastname,
					cca.certificatenumber

			Union All

			select dsm.districtnamee,sm.sronamee,
			o.applicationnumber,
			o.applicationnumber,
			to_char(othfee.receiptdate,'dd-MM-YYYY') presentdate,
			othfee.partyfirstname||' '||othfee.partymiddlename||' '||othfee.partylastname as presentername,
			othfee.paymentdescription as descriptionofdocument,
			null as consideration_fees,
			null as marketvalue,
			sum( case when o.feerulecode=36 then COALESCE (receipttotal,0)  else 0 end) stampduty,
			null::numeric as cess,
			NULL as municipalsurcharge,
			NULL as Taluksurcharge,
			sum(distinct case when o.feerulecode=36 then COALESCE (receipttotal,0)  else 0 end) Total_duty,
			null as documentnumber,
			othfee.bookdetails as bookid,
			null::text as volumenumber,
			to_char(receiptdate,'dd-MM-YYYY') dateofcompletion,
			to_char(receiptdate,'dd-MM-YYYY') as dateofreturn,
			sum( case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end) registrationfees,
			null as feesforcopies,
			sum(distinct  case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) miscelaneousfees,
			null::numeric as otherstampduty,
			null as miscellaneous_article_fees,
			sum( case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end)+
			sum( case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) 
			as total_fees2,
			Null::numeric as Treasury_amount,
			null  as Treasury_transaction_date,
			 null::text as dailymutationreceipts,
			sum(distinct  case when o.feerulecode=6 then COALESCE (receipttotal,0) else 0 end) mutationfees,
			Null as mutationfees_to_treasury_date,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			null::text copy_of_document
			from kaveri.otherfeesrequired o
			join kaveri.otherreceiptdetails othfee  on o.receiptid = othfee.receiptid
			join kaveri.departmentusers d on o.departmentuserid = d.userid
			 join kaveri.sromaster sm on sm.srocode=d.srocode
			 JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode 
			 where   d.srocode=_srocode and 
			 othfee.receiptdate >=_fromdate  and  othfee.receiptdate::date <=_todate   

			group by dsm.districtnamee,sm.sronamee,othfee.receiptdate,othfee.partyfirstname,
			othfee.partymiddlename,
			othfee.partylastname,o.applicationnumber,
			othfee.paymentdescription,othfee.bookdetails;

 
 elseif _documentnumber is not NULL  then

		raise notice 'date null';
		return query
		with a as (select     
			dsm.districtnamee,
			sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,
			to_char(dm.presentdatetime,'dd-MM-YYYY') presentdate,
			pi1.presentername,
			sa.articlenamee AS descriptionofdocument, 
			pm.consideration as consideration_fees,
			pm.marketvalue as marketvalue,
			pm.municipalsurcharge,
			pm.Taluksurcharge,
			case when dm.finalregistrationnumber is not null
			then dm.finalregistrationnumber else dm.pendingdocumentnumber end documentnumber,
			b.booknameenglish ,
			null  as volumenumber,
			amsreg.Treasury_amount,
			amsreg.Challan_date,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofcompletion,
			to_char(dm.registrationdatetime,'dd-MM-YYYY') dateofreturn,
			dm.uploaddocdeedpath as copy_of_document

			from  kaveri.documentmaster dm
			join  (select applicationnumber,string_agg(distinct (coalesce(firstname,' ')||coalesce(middlename,' ')|| coalesce(lastname,' ')::text),',') as presentername 
			from kaveri.partyinfo where ispresenter is true group by applicationnumber) pi1   on pi1.applicationnumber = dm.applicationnumber 
			and dm.isregistrationcompleted is true and dm.srocode=_srocode and dm.finalregistrationnumber=_documentnumber
			join 
			(select applicationnumber,stamparticlecode,max(sroconsideration)
			as consideration,max(sromarketvalue) as marketvalue,
			sum(case when propertytypeid=28 then COALESCE (surcharge,0)  else 0 end) as municipalsurcharge,
			sum(case when propertytypeid=17 then COALESCE (surcharge,0) else 0 end)  as Taluksurcharge
			
			from kaveri.propertymaster 
			group by applicationnumber,stamparticlecode)
			pm on pm.applicationnumber = dm.applicationnumber 
			join kaveri.stamparticles sa on pm.stamparticlecode=sa.stamparticlecode 
			JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
			join kaveri.booktypemaster b on dm.bookid=b.bookid 
			left join (select applicationnumber,sum(totalamount)  as Treasury_amount,
			string_agg(distinct to_char(inserteddatetime,'dd-MM-yyyy'),',') 
			as Challan_date from  kaveri.ams_reg_epaymenttransdetails group by applicationnumber ) 
			amsreg on amsreg.applicationnumber = dm.applicationnumber 
			where 
			 dm.srocode=_srocode and  dm.registrationdatetime::date >= _fromdate
			 and dm.registrationdatetime::date<=_todate  and
			 dm.isregistrationcompleted is true )

			select a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,
			a.presentdate,a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) stampduty,
			sum(case when fr.feerulecode=59  then amountpaid else 0 end) cess,
			a.municipalsurcharge,a.Taluksurcharge,
			sum(case when fr.feerulecode=36  then amountpaid else 0 end) +
			sum(case when fr.feerulecode=59  then amountpaid else 0 end)+
			a.municipalsurcharge+a.Taluksurcharge as Total_duty,
			a.documentnumber,a.booknameenglish,a.volumenumber,
			a.dateofcompletion,a.dateofreturn,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end) registrationfees,
			sum(case when fr.feerulecode=30 then amountpaid else 0 end) as feesforcopies,
			sum(case when fr.feerulecode=2 then amountpaid else 0 end) miscelaneousfees,
			sum(case when fr.feerulecode not in (1,36,59,2)then amountpaid else 0 end) otherstampduty,
			NULL::numeric miscellaneous_article_fees,
			sum(case when fr.feerulecode=1 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=30 then amountpaid else 0 end)+
			sum(case when fr.feerulecode=2 then amountpaid else 0 end)+
			sum(case when fr.feerulecode not in (1,36,59,2)then amountpaid else 0 end) Total_fees2,
			a.Treasury_amount,
			a.Challan_date,
			string_agg(distinct (case when fr.feerulecode=6 then r.receiptnumber::text  else ' ' end ),' ')as dailymutationreceipts,
			sum(case when fr.feerulecode=6 then fr.amountpaid else 0 end) mutationfees,
			string_agg(distinct ( case when fr.feerulecode=6 then to_char(r.dateofreceipt,'DD-MM-YYYY')  else ' ' end ),' ')as mutationfeedate,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			a.copy_of_document

			from 
			a
			left join 	kaveri.feesrequired fr on a.applicationnumber=fr.applicationnumber
			left join kaveri.receiptmaster r on fr.receiptid=r.receiptid
			
			group by a.districtnamee,a.sronamee,a.finalregistrationnumber,a.applicationnumber,a.presentdate,
			a.presentername,a.descriptionofdocument,a.consideration_fees,a.marketvalue,
			a.municipalsurcharge,a.Taluksurcharge,a.documentnumber,a.booknameenglish,a.volumenumber,a.Treasury_amount,
			a.Challan_date,a.dateofcompletion,a.dateofreturn,a.copy_of_document
		
				
			Union All
			
			select  
					dsm.districtnamee as districtname,
					sr.sronamee as sroname,
					null as finalregistrationnumber,
					eca.applicationnumber,
					to_char(a.applicationenddate,'dd-MM-YYYY') as  signeddatetime,
					c.firstname||c.middlename||c.lastname  as Presentername,
					'ECSearch' as descriptionofdocument,
					null::numeric  as considerationfees,
					null::numeric  as marketvalue,
					sum(case when er.feeruleid=64  then er.payableamount else 0 end) searchfee,
					sum(case when er.feeruleid=23  then er.payableamount else 0 end) searchapplfee,
					null::numeric as muncipalsurcharge,
					null::numeric  as taluksurcharge,
					 sum(case when er.feeruleid=64  then payableamount else 0 end)+
					 sum(case when er.feeruleid=23  then payableamount else 0 end)
					 as Total_duty,
					eca.certificatenumber as documentnumber,
					null as bookname,
					null as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofreturn,
					null as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount) as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
					null as dailymutation_receipt,
					null::numeric as mutationfees,
					null as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					eca.signedform22 as copy_of_document
					
					
					  from kaveri.ec_applicationdetails   eca
					  join kaveri.applicantapplicationdetails a on eca.applicationnumber=a.applicationnumber  and eca.applicationnumber=_documentnumber
					  join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=eca.userid 
					  left join kaveri.ams_reg_epaymenttransdetails amsre on eca.applicationnumber=amsre.applicationnumber 
					  join (select ecid,feeruleid,sum(payableamount) as payableamount  from kaveri.ec_requiredfees  
					  group by ecid,feeruleid)er on eca.ecid=er.ecid 
					 where 
					 eca.kaverisrocode=_srocode 
					
					-- and 
					--eca.signedform22 is not null and length(eca.signedform22 )>0 
					and a.currentstatus='CE110'
					group by dsm.districtnamee,sr.sronamee,eca.applicationnumber,eca.signedform22,
					eca.propertydescription,a.applicationenddate,c.firstname,c.middlename,c.lastname,
					eca.certificatenumber
					

			Union All

			select  
					dsm.districtnamee as district,
					sr.sronamee as sroname,
					null as finalregistrationnumber,
					cca.applicationnumber,
					to_char(a.applicationenddate,'dd-MM-YYYY') as  signeddatetime,
					c.firstname||c.middlename||c.lastname  as Presentername,
					'CCSearch' as descriptionofdocument,
					null::numeric as considerationfees,
					null::numeric as marketvalue,
					sum(case when cr.feeruleid=36  then cr.payableamount else 0 end) stampduty,
					sum(case when cr.feeruleid=14  then cr.payableamount else 0 end) searchfee,
				
					null as muncipalsurcharge,
					null as taluksurcharge,
					 sum(case when cr.feeruleid=36  then payableamount else 0 end)+
					 sum(case when cr.feeruleid=14  then payableamount else 0 end)
					 as Total_duty,
					cca.certificatenumber as documentnumber,
					null::text as bookname,
					null::text as volumeno,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofcompletion,
					to_char(a.applicationenddate,'dd-MM-YYYY') dateofreturn,
					null::numeric as regdfees,
					null::numeric as feesforcopies,
					null::numeric as misclaneousfees,
					null::numeric as otherstampduty,
					null::numeric as misclaneousarticlefees,
					null::numeric as totalfees2,
					sum(amsre.totalamount) as Treasuryamount,
					string_agg(distinct to_char(amsre.inserteddatetime,'dd-MM-yyyy'),',') as Challan_date,
					null as dailymutation_receipt,
					null::numeric as mutationfees,
					null::text as mutationfeedate,
					NULL::text transmission_of_memorandum,
					NULL::text transmission_of_memoranda,
					NULL::text signature_of_register,
					NULL::text remarks,	
					cca.signedform22 as copy_of_document
					
					
					from kaveri.cc_applicationdetails   cca
					  join kaveri.applicantapplicationdetails a on cca.applicationnumber=a.applicationnumber  and cca.applicationnumber=_documentnumber
					  join kaveri.sromaster sr on cca.kaverisrocode  = sr.srocode
					  join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
					  join kaveri.citizenmaster c on c.citizenid=cca.userid  
					  left join kaveri.ams_reg_epaymenttransdetails amsre on cca.applicationnumber=amsre.applicationnumber 
					  join (select ccid,feeruleid,sum(payableamount) as payableamount  from kaveri.cc_requiredfees  
					  group by ccid,feeruleid)cr on cca.ccid=cr.ccid 
					 where 
					 cca.kaverisrocode=_srocode 
					
					 
					--and 
					--cca.signedform22 is not null and length(cca.signedform22 )>0 
					and a.currentstatus='CC109'
					group by dsm.districtnamee,sr.sronamee,cca.applicationnumber,cca.signedform22,
					a.applicationenddate,c.firstname,c.middlename,c.lastname,
					cca.certificatenumber

			Union All

			select dsm.districtnamee,sm.sronamee,
			o.applicationnumber,
			o.applicationnumber,
			to_char(othfee.receiptdate,'dd-MM-YYYY') presentdate,
			othfee.partyfirstname||' '||othfee.partymiddlename||' '||othfee.partylastname as presentername,
			othfee.paymentdescription as descriptionofdocument,
			null as consideration_fees,
			null as marketvalue,
			sum( case when o.feerulecode=36 then COALESCE (receipttotal,0)  else 0 end) stampduty,
			null::numeric as cess,
			NULL as municipalsurcharge,
			NULL as Taluksurcharge,
			sum(distinct case when o.feerulecode=36 then COALESCE (receipttotal,0)  else 0 end) Total_duty,
			null as documentnumber,
			othfee.bookdetails as bookid,
			null::text as volumenumber,
			to_char(receiptdate,'dd-MM-YYYY') dateofcompletion,
			to_char(receiptdate,'dd-MM-YYYY') as dateofreturn,
			sum( case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end) registrationfees,
			null as feesforcopies,
			sum(distinct  case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) miscelaneousfees,
			null::numeric as otherstampduty,
			null as miscellaneous_article_fees,
			sum( case when o.feerulecode=1 then COALESCE (receipttotal,0)  else 0 end)+
			sum( case when o.feerulecode not in (1,36)then COALESCE (receipttotal,0) else 0 end) 
			as total_fees2,
			Null::numeric as Treasury_amount,
			null  as Treasury_transaction_date,
			 null::text as dailymutationreceipts,
			sum(distinct  case when o.feerulecode=6 then COALESCE (receipttotal,0) else 0 end) mutationfees,
			Null as mutationfees_to_treasury_date,
			NULL::text transmission_of_memorandum,
			NULL::text transmission_of_memoranda,
			NULL::text signature_of_register,
			NULL::text remarks,
			null::text copy_of_document
			from kaveri.otherfeesrequired o
			join kaveri.otherreceiptdetails othfee  on o.receiptid = othfee.receiptid and o.applicationnumber=_documentnumber
			join kaveri.departmentusers d on o.departmentuserid = d.userid
			 join kaveri.sromaster sm on sm.srocode=d.srocode
			 JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode 
			 where   d.srocode=_srocode   

			group by dsm.districtnamee,sm.sronamee,othfee.receiptdate,othfee.partyfirstname,
			othfee.partymiddlename,
			othfee.partylastname,o.applicationnumber,
			othfee.paymentdescription,othfee.bookdetails;

 
 
 else

raise notice 'condition failed';
end if;
 

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_daily_register_of_fees_statutory_test(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_mis_dailyrevenue_docwise(bigint, bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_dailyrevenue_docwise(_districtcode bigint, _srocode bigint, _stamparticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, officename character varying, book character varying, part character varying, finalregistrationnumber character varying, marketvalue text, consideration text, copy_of_document text, stampduty numeric, registrationfees numeric, scanningfee numeric, otherfees numeric, total numeric)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$

DECLARE

BEGIN	

if _stamparticlecode=0 THEN --All article
	if _districtcode=0 then  --All district

				if _amounttype=0 then --no amounttype
					
					raise notice 'stamparticlecode=0 ,district 0 and amounttype 0';
	
						return query
	
        
						  with a as 
						 (select d.districtnamee as district,
						   vw.sroname as officename,
						   vw.booktype as book,
						   vw.printablename as part,
						   vw.finalregistrationnumber,
						   string_agg(distinct vw.marketvalue::text,',') as marketvalue,
						   string_agg(distinct vw.consideration::text,',') as considerationamount
						   from kaverimis.vw_mis_revenue_report vw
						   inner join kaveri.sromaster sro on vw.srocode = sro.srocode
						   inner join kaveri.districtmaster d on sro.districtcode = d.districtcode        
						   where 
						   --sro.districtcode = _districtcode and
						   --vw.stamparticlecode =_stamparticlecode and
						  -- vw.srocode=_srocode
						   vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime::date<=_todate
						   group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.finalregistrationnumber)
							select a.*,dm.uploaddocdeedpath  as copy_of_document, 
							sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end)as StampDuty,
						   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end) as RegistrationFees,
						   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)as scanningfee,
						   sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)as otherfees,
						   sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end)+
						   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end)+
						   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)+
						   sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)as TotalFees 	
						   from kaveri.documentmaster dm
						   join kaveri.feesrequired rr  on dm.applicationnumber=rr.applicationnumber
						   --join (select applicationnumber,sum(amountpaid) from kaveri.feesrequired where --feerulecode in (2) group by applicationnumber 
						   --having sum(amountpaid)>=_minval and sum(amountpaid)<=_maxval)fr on --rr.applicationnumber=fr.applicationnumber
						   inner join a on a.finalregistrationnumber = dm.finalregistrationnumber  
						   group by a.district,a.officename,a.book,a.part,a.finalregistrationnumber,a.marketvalue,a.considerationamount,copy_of_document;
       
	  
				elsif _amounttype=1 then --TotalFees
				raise notice 'stamparticlecode=0 ,district 0 and amounttype 1';
							return query
							with a as 
						 (select d.districtnamee as district,
						   vw.sroname as officename,
						   vw.booktype as book,
						   vw.printablename as part,
						   vw.finalregistrationnumber,
						   string_agg(distinct vw.marketvalue::text,',') as marketvalue,
						   string_agg(distinct vw.consideration::text,',') as considerationamount
						   from kaverimis.vw_mis_revenue_report vw
						   inner join kaveri.sromaster sro on vw.srocode = sro.srocode
						   inner join kaveri.districtmaster d on sro.districtcode = d.districtcode        
						   where 
						   --sro.districtcode = _districtcode and
						   --vw.stamparticlecode =_stamparticlecode and
						  -- vw.srocode=_srocode
						   vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime::date<=_todate
						   group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.finalregistrationnumber)
							select a.*,dm.uploaddocdeedpath  as copy_of_document, 
							sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end)as StampDuty,
						   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end) as RegistrationFees,
						   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)as scanningfee,
						   sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)as otherfees,
						   sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end)+
						   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end)+
						   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)+
						   sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)as TotalFees
						   from kaveri.documentmaster dm
						   join kaveri.feesrequired rr  on dm.applicationnumber=rr.applicationnumber
						   join (select applicationnumber,sum(amountpaid) from kaveri.feesrequired 
						   --where 
						   --feerulecode in (2)
						   group by applicationnumber 
						   having sum(amountpaid)>=_minval and sum(amountpaid)<=_maxval)fr on 
						   rr.applicationnumber=fr.applicationnumber
						   inner join a on a.finalregistrationnumber = dm.finalregistrationnumber  
						   group by a.district,a.officename,a.book,a.part,a.finalregistrationnumber,a.marketvalue,a.considerationamount,copy_of_document;
	  
					elsif _amounttype=2 then --marketvaluation
	  raise notice 'stamparticlecode=0 ,district 0 and amounttype 2';
						  return query
							with a as 
