							select a.*, dm.uploaddocdeedpath  as copy_of_document,
							sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end)as StampDuty,
						   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end) as RegistrationFees,
						   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)as scanningfee,
						   sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)as otherfees,
						   sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end)+
						   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end)+
						   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)+
						   sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)as TotalFees 	
						   from kaveri.documentmaster dm
						   join kaveri.feesrequired rr  on dm.applicationnumber=rr.applicationnumber
						   --join (select applicationnumber,sum(amountpaid) from kaveri.feesrequired where 
						   --feerulecode in (2)
						   --group by applicationnumber 
						   --having sum(amountpaid)>=_minval and sum(amountpaid)<=_maxval)fr on 
						  -- rr.applicationnumber=fr.applicationnumber
						   inner join a on a.finalregistrationnumber = dm.finalregistrationnumber  
						   group by a.district,a.officename,a.book,a.part,a.finalregistrationnumber,a.marketvalue,a.considerationamount,copy_of_document;
	  
					elsif _amounttype=3 then --consideration amount
	  
					raise notice 'stamparticlecode=0 ,district 0 and amounttype 3';
						 return query
							with a as 
						 (select d.districtnamee as district,
						   vw.sroname as officename,
						   vw.booktype as book,
						   vw.printablename as part,
						   vw.finalregistrationnumber,
						   string_agg(distinct vw.marketvalue::text,',') as marketvalue,
						   string_agg(distinct vw.consideration::text,',') as considerationamount
						   from kaverimis.vw_mis_revenue_report vw
						   inner join kaveri.sromaster sro on vw.srocode = sro.srocode
						   inner join kaveri.districtmaster d on sro.districtcode = d.districtcode        
						   where 
						   vw.consideration>=_minval and vw.consideration >=_maxval
						   --sro.districtcode = _districtcode and
						   --vw.stamparticlecode =_stamparticlecode and
						  -- vw.srocode=_srocode
						   and vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime::date<=_todate
						   group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.finalregistrationnumber)
							select a.*, dm.uploaddocdeedpath  as copy_of_document,
							sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end)as StampDuty,
						   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end) as RegistrationFees,
						   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)as scanningfee,
						   sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)as otherfees,
						   sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end)+
						   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end)+
						   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)+
						   sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)as TotalFees 	
						   from kaveri.documentmaster dm
						   join kaveri.feesrequired rr  on dm.applicationnumber=rr.applicationnumber
						   --join (select applicationnumber,sum(amountpaid) from kaveri.feesrequired where 
						   --feerulecode in (2)
						   --group by applicationnumber 
						   --having sum(amountpaid)>=_minval and sum(amountpaid)<=_maxval)fr on 
						  -- rr.applicationnumber=fr.applicationnumber
