			   vw.stamparticlecode =_stamparticlecode and
				vw.srocode=_srocode
			   and vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime::date<=_todate
			   group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.finalregistrationnumber)
				select a.*, dm.uploaddocdeedpath  as copy_of_document,
				sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end)as StampDuty,
			   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end) as RegistrationFees,
			   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)as scanningfee,
			   sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)as otherfees,
			   sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end)+
						   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end)+
						   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)+
						   sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)as TotalFees 	
			   from kaveri.documentmaster dm
			   join kaveri.feesrequired rr  on dm.applicationnumber=rr.applicationnumber
			   join (select applicationnumber,sum(amountpaid) from kaveri.feesrequired where 
			   feerulecode in (2)
			   group by applicationnumber 
			   having sum(amountpaid)>=_minval and sum(amountpaid)<=_maxval)fr on 
			   rr.applicationnumber=fr.applicationnumber
			   inner join a on a.finalregistrationnumber = dm.finalregistrationnumber  
			   group by a.district,a.officename,a.book,a.part,a.finalregistrationnumber,a.marketvalue,a.considerationamount,copy_of_document;
			  
			  elsif _amounttype=7 then --other fees
			  
			  return query
				with a as 
			 (select d.districtnamee as district,
			   vw.sroname as officename,
			   vw.booktype as book,
			   vw.printablename as part,
			   vw.finalregistrationnumber,
			   string_agg(distinct vw.marketvalue::text,',') as marketvalue,
			   string_agg(distinct vw.consideration::text,',') as considerationamount
			   from kaverimis.vw_mis_revenue_report vw
			   inner join kaveri.sromaster sro on vw.srocode = sro.srocode
			   inner join kaveri.districtmaster d on sro.districtcode = d.districtcode        
			   where 
			  -- vw.consideration>=_minval and vw.consideration >=_maxval
				sro.districtcode = _districtcode and
			   vw.stamparticlecode =_stamparticlecode and
			   vw.srocode=_srocode
			   and vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime::date<=_todate
			   group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.finalregistrationnumber)
				select a.*, dm.uploaddocdeedpath  as copy_of_document,
				sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end)as StampDuty,
			   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end) as RegistrationFees,
			   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)as scanningfee,
			   sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)as otherfees,
			   sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end)+
						   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end)+
						   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)+
						   sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)as TotalFees 	
			   from kaveri.documentmaster dm
			   join kaveri.feesrequired rr  on dm.applicationnumber=rr.applicationnumber
			   join (select applicationnumber,sum(amountpaid) from kaveri.feesrequired where 
			   feerulecode not in (1,2,36,58,59,64)
			   group by applicationnumber 
			   having sum(amountpaid)>=_minval and sum(amountpaid)<=_maxval)fr on 
			   rr.applicationnumber=fr.applicationnumber
			   inner join a on a.finalregistrationnumber = dm.finalregistrationnumber  
			   group by a.district,a.officename,a.book,a.part,a.finalregistrationnumber,a.marketvalue,a.considerationamount,copy_of_document;
	  
	   

			end if;
	end if;
end if;
END;

$$;


ALTER FUNCTION kaverimis.fn_mis_dailyrevenue_docwise(_districtcode bigint, _srocode bigint, _stamparticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer) OWNER TO csgadmin;

--
-- Name: fn_mis_dailyrevenue_docwise(bigint, bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_dailyrevenue_docwise(_districtcode bigint, _srocode bigint, _regarticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, officename character varying, book character varying, part character varying, finalregistrationnumber character varying, marketvalue text, consideration text, copy_of_document text, stampduty numeric, registrationfees numeric, scanningfee numeric, otherfees numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$

DECLARE
    PageOffset INTEGER := 0;
BEGIN
    PageOffset := ((pagenumber - 1) * pagesize);

    IF (pagenumber <> -1 AND pagesize <> -1) THEN

        RETURN QUERY
        WITH cte AS (
            WITH a AS (
                SELECT
                    d.districtnamee AS district,
                    sro.sronamee AS officename,
                    bt.booknameenglish AS book,
                    bt.printablename AS part,
                    dm.finalregistrationnumber,
                    dm.applicationnumber,
                    dm.uploaddocdeedpath,
                    string_agg(DISTINCT coalesce(pm.sromarketvalue,0)::text,' , ') AS marketvalue,
                    string_agg(DISTINCT coalesce(pm.sroconsideration,0)::text,' , ') AS considerationamount
                FROM kaveri.documentmaster dm
                JOIN kaveri.propertymaster pm ON dm.applicationnumber = pm.applicationnumber
                JOIN kaveri.booktypemaster bt ON dm.bookid = bt.bookid
                JOIN kaveri.sromaster sro ON dm.srocode = sro.srocode
                JOIN kaveri.districtmaster d ON sro.districtcode = d.districtcode
                WHERE dm.isregistrationcompleted = true
                  AND dm.registrationdatetime BETWEEN _fromdate AND _todate + INTERVAL '1 day'
                  AND (CASE WHEN _districtcode <> 0 THEN d.districtcode = _districtcode ELSE true END)
                  AND (CASE WHEN _srocode <> 0 THEN sro.srocode = _srocode ELSE true END)
                  AND (CASE WHEN _regarticlecode <> 0 THEN dm.regarticlecode = _regarticlecode ELSE true END)
                GROUP BY
                    d.districtnamee, sro.sronamee, bt.booknameenglish, bt.printablename,
                    dm.finalregistrationnumber, dm.applicationnumber, dm.uploaddocdeedpath
                HAVING
                    CASE
                        WHEN _amounttype = 0 THEN true
                        WHEN _amounttype = 3 THEN SUM(pm.sroconsideration) BETWEEN _minval AND _maxval
                        WHEN _amounttype = 2 THEN SUM(pm.sromarketvalue) BETWEEN _minval AND _maxval
                        ELSE true
                    END
            )

            SELECT
                a.district,
                a.officename,
                a.book,
                a.part,
                a.finalregistrationnumber,
                a.marketvalue,
                a.considerationamount,
                a.uploaddocdeedpath AS copy_of_document,

                -- Stamp Duty (as per epay)
                SUM(CASE
                        WHEN rr.feerulecode IN (35,36,64,89,91,92,101,107,110,138)
                        THEN rr.amountpaid ELSE 0
                    END) AS stampduty,

                -- Registration Fees (as per epay)
                SUM(CASE
                        WHEN rr.feerulecode IN (
                            1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,
                            22,23,24,25,26,27,28,30,31,34,
                            57,63,65,88,90,93,94,95,96,97,98,
                            102,103,106,108,109
                        )
                        THEN rr.amountpaid ELSE 0
                    END) AS registrationfees,

                -- Scanning
                SUM(CASE
                        WHEN rr.feerulecode = 2
                        THEN rr.amountpaid ELSE 0
                    END) AS scanningfee,

                -- Other fees = everything else except stamp/reg/scan and excluded heads
                SUM(CASE
                        WHEN rr.feerulecode NOT IN (
                            2,
                            35,36,64,89,91,92,101,107,110,138,
                            1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,
                            22,23,24,25,26,27,28,30,31,34,
                            57,63,65,88,90,93,94,95,96,97,98,
                            102,103,106,108,109,
                            64,104,89,88
                        )
                        THEN rr.amountpaid ELSE 0
                    END) AS otherfees,

                -- Total (original exclusion retained)
                SUM(CASE
                        WHEN rr.feerulecode NOT IN (64,104,89,88)
                        THEN rr.amountpaid ELSE 0
                    END) AS total

            FROM a
            JOIN kaveri.feesrequired rr ON a.applicationnumber = rr.applicationnumber
            GROUP BY
                a.district, a.officename, a.book, a.part,
                a.finalregistrationnumber, a.marketvalue,
                a.considerationamount, a.uploaddocdeedpath
            HAVING
                CASE
                    WHEN _amounttype = 1 THEN SUM(rr.amountpaid) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 4 THEN
                        SUM(CASE WHEN rr.feerulecode IN (35,36,64,89,91,92,101,107,110,138)
                                 THEN rr.amountpaid ELSE 0 END)
                        BETWEEN _minval AND _maxval
                    WHEN _amounttype = 5 THEN
                        SUM(CASE WHEN rr.feerulecode IN (
                            1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,
                            22,23,24,25,26,27,28,30,31,34,
                            57,63,65,88,90,93,94,95,96,97,98,
                            102,103,106,108,109
                        ) THEN rr.amountpaid ELSE 0 END)
                        BETWEEN _minval AND _maxval
                    WHEN _amounttype = 6 THEN
                        SUM(CASE WHEN rr.feerulecode = 2 THEN rr.amountpaid ELSE 0 END)
                        BETWEEN _minval AND _maxval
                    WHEN _amounttype = 7 THEN
                        SUM(CASE
                            WHEN rr.feerulecode NOT IN (
                                2,
                                35,36,64,89,91,92,101,107,110,138,
                                1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,
                                22,23,24,25,26,27,28,30,31,34,
                                57,63,65,88,90,93,94,95,96,97,98,
                                102,103,106,108,109,
                                64,104,89,88
                            )
                            THEN rr.amountpaid ELSE 0 END)
                        BETWEEN _minval AND _maxval
                    ELSE true
                END
        ),
        cte_count AS (SELECT COUNT(*) AS total_rows FROM cte)
        SELECT *
        FROM cte
        RIGHT JOIN (SELECT total_rows FROM cte_count) total_row ON true
        WHERE total_row.total_rows <> 0
        LIMIT pagesize OFFSET PageOffset;

    END IF;
END;
$$;


