CREATE FUNCTION kaverimis.fn_mis_dailyrevenue_docwise_22012026(_districtcode bigint, _srocode bigint, _regarticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, officename character varying, book character varying, part character varying, finalregistrationnumber character varying, marketvalue text, consideration text, copy_of_document text, stampduty numeric, registrationfees numeric, scanningfee numeric, otherfees numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$

DECLARE
