                    string_agg(DISTINCT coalesce(pm.sromarketvalue,0)::text,' , ') AS marketvalue,
                    string_agg(DISTINCT coalesce(pm.sroconsideration,0)::text,' , ') AS considerationamount
                FROM kaveri.documentmaster dm
                JOIN kaveri.propertymaster pm ON dm.applicationnumber = pm.applicationnumber
                JOIN kaveri.booktypemaster bt ON dm.bookid = bt.bookid
                JOIN kaveri.sromaster sro ON dm.srocode = sro.srocode
                JOIN kaveri.districtmaster d ON sro.districtcode = d.districtcode
                WHERE dm.isregistrationcompleted = true
                  AND dm.registrationdatetime BETWEEN _fromdate AND _todate + INTERVAL '1 day'
                  AND (CASE WHEN _districtcode <> 0 THEN d.districtcode = _districtcode ELSE true END)
                  AND (CASE WHEN _srocode <> 0 THEN sro.srocode = _srocode ELSE true END)
                  AND (CASE WHEN _regarticlecode <> 0 THEN dm.regarticlecode = _regarticlecode ELSE true END)
                GROUP BY
                    d.districtnamee, sro.sronamee, bt.booknameenglish, bt.printablename,
                    dm.finalregistrationnumber, dm.applicationnumber, dm.uploaddocdeedpath
                HAVING
                    CASE
                        WHEN _amounttype = 0 THEN true
                        WHEN _amounttype = 3 THEN SUM(pm.sroconsideration) BETWEEN _minval AND _maxval
                        WHEN _amounttype = 2 THEN SUM(pm.sromarketvalue) BETWEEN _minval AND _maxval
                        ELSE true
                    END
            )

            SELECT
                a.district,
                a.officename,
                a.book,
                a.part,
                a.finalregistrationnumber,
                a.marketvalue,
                a.considerationamount,
                a.uploaddocdeedpath AS copy_of_document,

                -- Stamp Duty (as per epay)
                SUM(CASE
                        WHEN rr.feerulecode IN (35,36,64,89,91,92,101,107,110,138)
                        THEN rr.amountpaid ELSE 0
                    END) AS stampduty,

                -- Registration Fees (as per epay)
                SUM(CASE
                        WHEN rr.feerulecode IN (
                            1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,
                            22,23,24,25,26,27,28,30,31,34,
                            57,63,65,88,90,93,94,95,96,97,98,
                            102,103,106,108,109
                        )
                        THEN rr.amountpaid ELSE 0
                    END) AS registrationfees,

                -- Scanning
                SUM(CASE
                        WHEN rr.feerulecode = 2
                        THEN rr.amountpaid ELSE 0
                    END) AS scanningfee,

                -- Other fees = everything else except stamp/reg/scan and excluded heads
                SUM(CASE
                        WHEN rr.feerulecode NOT IN (
                            2,
                            35,36,64,89,91,92,101,107,110,138,
                            1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,
                            22,23,24,25,26,27,28,30,31,34,
                            57,63,65,88,90,93,94,95,96,97,98,
                            102,103,106,108,109,
                            64,104,89,88
                        )
                        THEN rr.amountpaid ELSE 0
                    END) AS otherfees,

                -- Total (original exclusion retained)
                SUM(CASE
                        WHEN rr.feerulecode NOT IN (64,104,89,88)
                        THEN rr.amountpaid ELSE 0
                    END) AS total

            FROM a
            JOIN kaveri.feesrequired rr ON a.applicationnumber = rr.applicationnumber
            GROUP BY
                a.district, a.officename, a.book, a.part,
                a.finalregistrationnumber, a.marketvalue,
                a.considerationamount, a.uploaddocdeedpath
            HAVING
                CASE
                    WHEN _amounttype = 1 THEN SUM(rr.amountpaid) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 4 THEN
                        SUM(CASE WHEN rr.feerulecode IN (35,36,64,89,91,92,101,107,110,138)
                                 THEN rr.amountpaid ELSE 0 END)
