ALTER FUNCTION kaverimis.fn_mis_dailyrevenue_docwise_22012026(_districtcode bigint, _srocode bigint, _regarticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO manjunathswamy;

--
-- Name: fn_mis_dailyrevenue_docwise_23012024(bigint, bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_dailyrevenue_docwise_23012024(_districtcode bigint, _srocode bigint, _regarticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, officename character varying, book character varying, part character varying, finalregistrationnumber character varying, marketvalue text, consideration text, copy_of_document text, stampduty numeric, registrationfees numeric, scanningfee numeric, otherfees numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);


if (pagenumber<>-1 and pagesize<>-1) then

return query

with cte as (with a as 
						 (select d.districtnamee as district,
						   sro.sronamee as officename,
						   bt.booknameenglish  as book,
						   bt.printablename as part,
						   dm.finalregistrationnumber,
						   dm.applicationnumber,
						   dm.uploaddocdeedpath,
						   string_agg(distinct coalesce(pm.sromarketvalue,0)::text,' , ') as marketvalue,
						   string_agg(distinct coalesce(pm.sroconsideration,0)::text,' , ') as considerationamount
						   from 
						   kaveri.documentmaster dm 
						   join kaveri.propertymaster pm on dm.applicationnumber=pm.applicationnumber 
						   JOIN kaveri.booktypemaster bt ON dm.bookid = bt.bookid
						   inner join kaveri.sromaster sro on dm.srocode = sro.srocode
						   inner join kaveri.districtmaster d on sro.districtcode = d.districtcode        
						   where 
			dm.isregistrationcompleted=true and  
						  
			(dm.registrationdatetime between  _fromdate  and _todate + INTERVAL '1 day')
						   
			and (case  when _districtcode<>0 then d.districtcode=_districtcode  ELSE  true end)
			and (case  when _srocode<> 0 then sro.srocode=_srocode  ELSE  true end)
			and (case  when _regarticlecode <> 0 then dm.regarticlecode=_regarticlecode  ELSE  true end)
     					 
			group by d.districtnamee,sro.sronamee, bt.booknameenglish ,
			dm.finalregistrationnumber,dm.applicationnumber,dm.uploaddocdeedpath,bt.printablename
			having 
			(case

                    when _amounttype=0 then true
                                    
                    when _amounttype=3 then sum(pm.sroconsideration) >=_minval and sum(pm.sroconsideration) <=_maxval

                    when _amounttype=2 then sum(pm.sromarketvalue) >=_minval and sum(pm.sromarketvalue) <=_maxval 

                    ELSE

                        true

                                                

                end))
							select a.district,a.officename,a.book,a.part,a.finalregistrationnumber,
							a.marketvalue,a.considerationamount,
							a.uploaddocdeedpath  as copy_of_document, 
							sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end)as StampDuty,
						   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end) as RegistrationFees,
						   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)as scanningfee,
						   sum(case when rr.feerulecode not in (1,2,36,58,59,64,104,89,88) then rr.amountpaid else 0 end)as otherfees,
						   sum(rr.amountpaid) as TotalFees 	
						   from a 
						   inner join kaveri.feesrequired rr   on a.applicationnumber=rr.applicationnumber 
						   
						      
						   group by a.district,a.officename,a.book,a.part,a.finalregistrationnumber,
						  a.marketvalue,a.considerationamount,a.uploaddocdeedpath
						  
						  having 
						  
						  (case

             
                    when _amounttype=1  then sum(rr.amountpaid) >=_minval and sum(rr.amountpaid) <=_maxval 
                    when _amounttype=4  then sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end)
                    >=_minval and sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end) <=_maxval
                     when _amounttype=5  then sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end)
                    >=_minval and sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end)  <=_maxval
                    when _amounttype=6  then sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)
                    >=_minval and sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)   <=_maxval
                    
                     when _amounttype=7  then sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)
                    >=_minval and sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)   <=_maxval
                    
                     
                    
                    
                    

                    ELSE

                        true                                               

                end ))  ,cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0  
			limit pagesize offset PageOffset;
		
	elsif (pagenumber=-1 or  pagesize=-1) then 
	
	return query

with cte as (with a as 
						 (select d.districtnamee as district,
						   sro.sronamee as officename,
						   bt.booknameenglish  as book,
						   bt.printablename as part,
						   dm.finalregistrationnumber,
						   dm.applicationnumber,
						   dm.uploaddocdeedpath,
						   string_agg(distinct coalesce(pm.sromarketvalue,0)::text,' , ') as marketvalue,
						   string_agg(distinct coalesce(pm.sroconsideration,0)::text,' , ') as considerationamount
						   from 
						   kaveri.documentmaster dm 
						   join kaveri.propertymaster pm on dm.applicationnumber=pm.applicationnumber 
						   JOIN kaveri.booktypemaster bt ON dm.bookid = bt.bookid
						   inner join kaveri.sromaster sro on dm.srocode = sro.srocode
						   inner join kaveri.districtmaster d on sro.districtcode = d.districtcode        
						   where 
			dm.isregistrationcompleted=true and  
						  
			(dm.registrationdatetime between  _fromdate  and _todate + INTERVAL '1 day')
						   
