	   vw.stamparticlecode =_stamparticlecode
      group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.finalregistrationnumber,vw.marketvalue, vw.consideration;
	  
	  elsif _amounttype=5 then --RegistrationFees
	  
		return query
		select d.districtnamee as district,
       vw.sroname as officename,
       vw.booktype as book,
       vw.printablename as part,
       vw.finalregistrationnumber,
	   vw.marketvalue,
	   vw.consideration,
       sum(case when vw.feerulecode in (36,58,59)  then vw.amountpaid else 0 end)as StampDuty,
	   sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
	   sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end)as scanningfee,
	   sum(case when vw.feerulecode not in (1,2,36,58,59) then vw.amountpaid else 0 end)as otherfees,
	   sum(vw.amountpaid)as TotalFees 	
       from kaverimis.vw_mis_revenue_report vw 
	   inner join
		(select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report   where feerulecode=1 and amountpaid >=_minval and amountpaid<=_maxval
		
		  )
		 vw1 on vw.applicationnumber=vw1.applicationnumber
		
	   inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	   inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
	   where  sro.districtcode = _districtcode and 
	   vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
		and 
	  vw.srocode=_srocode and 
	   vw.stamparticlecode =_stamparticlecode
      group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.finalregistrationnumber,vw.marketvalue, vw.consideration;
	  
	  elsif _amounttype=6 then --Scanning fee
	  
	  return query
		select d.districtnamee as district,
       vw.sroname as officename,
       vw.booktype as book,
       vw.printablename as part,
       vw.finalregistrationnumber,
	   vw.marketvalue,
	   vw.consideration,
       sum(case when vw.feerulecode in (36,58,59)  then vw.amountpaid else 0 end)as StampDuty,
	   sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
	   sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end)as scanningfee,
	   sum(case when vw.feerulecode not in (1,2,36,58,59) then vw.amountpaid else 0 end)as otherfees,
	   sum(vw.amountpaid)as TotalFees 	
       from kaverimis.vw_mis_revenue_report vw 
	   inner join
		(select applicationnumber,amountpaid  from kaverimis.vw_mis_revenue_report  where feerulecode=2 
		and  amountpaid >=_minval and  amountpaid<=_maxval
	
		  )
		 vw1 on vw.applicationnumber=vw1.applicationnumber
		
	   inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	   inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
	   where sro.districtcode = _districtcode and 
	   vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
		and 
	  vw.srocode=_srocode and 
	   vw.stamparticlecode =_stamparticlecode
      group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.finalregistrationnumber,vw.marketvalue, vw.consideration;
	  
	  elsif _amounttype=7 then --other fees
	  
	  return query
		select d.districtnamee as district,
       vw.sroname as officename,
       vw.booktype as book,
       vw.printablename as part,
       vw.finalregistrationnumber,
	   vw.marketvalue,
	   vw.consideration,
       sum(case when vw.feerulecode in (36,58,59)  then vw.amountpaid else 0 end)as StampDuty,
	   sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
	   sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end)as scanningfee,
	   sum(case when vw.feerulecode not in (1,2,36,58,59) then vw.amountpaid else 0 end)as otherfees,
	   sum(vw.amountpaid)as TotalFees 	
       from kaverimis.vw_mis_revenue_report vw 
	   inner join
		(select applicationnumber,sum(amountpaid) from kaverimis.vw_mis_revenue_report   where feerulecode not in (1,2,36,58,59) group by applicationnumber HAVING
		sum(amountpaid) >=_minval and sum(amountpaid)<=_maxval
	
		  )vw1 on vw.applicationnumber=vw1.applicationnumber
		
	   inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	   inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
	   where  sro.districtcode = _districtcode and 
	   vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
		and 
	  vw.srocode=_srocode and 
	   vw.stamparticlecode =_stamparticlecode
      group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.finalregistrationnumber,vw.marketvalue, vw.consideration;
	  
	  end if;
	  
	 

 end if;
END;

$$;


ALTER FUNCTION kaverimis.fn_mis_dailyrevenue_docwise_temp(_districtcode bigint, _srocode bigint, _stamparticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer) OWNER TO csgadmin;

--
-- Name: fn_mis_dailyrevenue_docwise_temp1(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_dailyrevenue_docwise_temp1(_srocode bigint, _stamparticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT NULL::integer, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer, _choice integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, officename character varying, book character varying, part character varying, finalregistrationnumber character varying, marketvalue numeric, consideration numeric, stampduty numeric, registrationfees numeric, scanningfee numeric, otherfees numeric, total numeric)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
if _choice=0 then   --- Registration fees,stamp duty, scanning fees 
return query
select d.districtnamee as district,
       vw.sroname as officename,
       vw.booktype as book,
       vw.printablename as part,
      	vw.finalregistrationnumber,
	vw.marketvalue,
	vw.consideration,
        sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end)as StampDuty,
	sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end)as scanningfee,
	sum(case when vw.feerulecode not in (1, 2, 36) then vw.amountpaid else 0 end)as otherfees,
	sum(vw.amountpaid)as TotalFees 	
         from kaverimis.vw_mis_revenue_report vw inner join
    (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_srocode
     and amountpaid >=_minval and amountpaid<=_maxval and feerulecode=_amounttype)
     vw1 on vw.applicationnumber=vw1.applicationnumber
	 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
    where --sro.districtcode = _districtcode and 
	vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
   and vw.srocode=_srocode and stamparticlecode =_stamparticlecode
   group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.finalregistrationnumber,vw.marketvalue, vw.consideration;

elsif _choice = 1 then --- other fees (feerulecode in (1,36,2))
return query
select d.districtnamee as district,
       vw.sroname as officename,
       vw.booktype as book,
       vw.printablename as part,
      	vw.finalregistrationnumber,
	vw.marketvalue,
	vw.consideration,
        sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end)as StampDuty,
	sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end)as scanningfee,
	sum(case when vw.feerulecode not in (1, 2, 36) then vw.amountpaid else 0 end)as otherfees,
	sum(vw.amountpaid)as TotalFees 	
         from kaverimis.vw_mis_revenue_report vw inner join
    (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_srocode
     and amountpaid >=_minval and amountpaid<=_maxval and feerulecode in (1,36,2))
     vw1 on vw.applicationnumber=vw1.applicationnumber
	 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
    where --sro.districtcode = _districtcode and 
	vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
   and vw.srocode=_srocode and stamparticlecode =_stamparticlecode
   group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.finalregistrationnumber,vw.marketvalue, vw.consideration;

elseif _choice=2 then --- marketvalue
  return query
select d.districtnamee as district,
       vw.sroname as officename,
       vw.booktype as book,
       vw.printablename as part,
      	vw.finalregistrationnumber,
	vw.marketvalue,
	vw.consideration,
        sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end)as StampDuty,
	sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end)as scanningfee,
	sum(case when vw.feerulecode not in (1, 2, 36) then vw.amountpaid else 0 end)as otherfees,
	sum(vw.amountpaid)as TotalFees 	
         from kaverimis.vw_mis_revenue_report vw inner join
    (select a.applicationnumber,a.amountpaid from kaverimis.vw_mis_revenue_report a where srocode=_srocode
     and a.marketvalue >=_minval and a.marketvalue <= _maxval)
     vw1 on vw.applicationnumber=vw1.applicationnumber
	 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
    where --sro.districtcode = _districtcode and 
	vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
   and vw.srocode=_srocode and stamparticlecode =_stamparticlecode
  group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.finalregistrationnumber,vw.marketvalue, vw.consideration;

elseif _choice=3 then --- consideration
  return query
select d.districtnamee as district,
       vw.sroname as officename,
       vw.booktype as book,
       vw.printablename as part,
      	vw.finalregistrationnumber,
	vw.marketvalue,
	vw.consideration,
        sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end)as StampDuty,
	sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end)as scanningfee,
	sum(case when vw.feerulecode not in (1, 2, 36) then vw.amountpaid else 0 end)as otherfees,
	sum(vw.amountpaid)as TotalFees 	
         from kaverimis.vw_mis_revenue_report vw inner join
    (select a.applicationnumber,a.amountpaid from kaverimis.vw_mis_revenue_report a where srocode=_srocode
     and a.consideration >=_minval and a.consideration <= _maxval)
     vw1 on vw.applicationnumber=vw1.applicationnumber
	 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
    where --sro.districtcode = _districtcode and 
	vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
   and vw.srocode=_srocode and stamparticlecode =_stamparticlecode
  group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.finalregistrationnumber,vw.marketvalue, vw.consideration;

elseif (_choice=4 and _srocode = 0 ) then   --- all srocodes, with particular amount type
return query

select d.districtnamee as district,
       vw.sroname as officename,
       vw.booktype as book,
       vw.printablename as part,
      	vw.finalregistrationnumber,
	vw.marketvalue,
	vw.consideration,
        sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end)as StampDuty,
	sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end)as scanningfee,
	sum(case when vw.feerulecode not in (1, 2, 36) then vw.amountpaid else 0 end)as otherfees,
	sum(vw.amountpaid)as TotalFees 	
         from kaverimis.vw_mis_revenue_report vw inner join
    (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where 
    amountpaid >=_minval and amountpaid <= _maxval and feerulecode = _amounttype)
     vw1 on vw.applicationnumber=vw1.applicationnumber
	 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
    where  vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
    and stamparticlecode =_stamparticlecode
  group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.finalregistrationnumber,vw.marketvalue, vw.consideration;

elseif (_choice = 5  and _srocode = 0) then --  All Srocodes particular with amounttype as (1,36,2) -- otherfees
return query

select d.districtnamee as district,
       vw.sroname as officename,
       vw.booktype as book,
       vw.printablename as part,
      	vw.finalregistrationnumber,
	vw.marketvalue,
	vw.consideration,
        sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end)as StampDuty,
	sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end)as scanningfee,
	sum(case when vw.feerulecode not in (1, 2, 36) then vw.amountpaid else 0 end)as otherfees,
	sum(vw.amountpaid)as TotalFees 	
         from kaverimis.vw_mis_revenue_report vw inner join
    (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where 
     amountpaid >=_minval and amountpaid<=_maxval and feerulecode in (1,36,2))
     vw1 on vw.applicationnumber=vw1.applicationnumber
	 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
    where  vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
   and  stamparticlecode =_stamparticlecode
   group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.finalregistrationnumber,vw.marketvalue, vw.consideration;

elseif (_choice = 6  and _srocode = 0 and _amounttype = 3) then -- All Srocodes consideration amount
return query

select d.districtnamee as district,
       vw.sroname as officename,
       vw.booktype as book,
       vw.printablename as part,
      	vw.finalregistrationnumber,
	vw.marketvalue,
	vw.consideration,
        sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end)as StampDuty,
	sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end)as scanningfee,
	sum(case when vw.feerulecode not in (1, 2, 36) then vw.amountpaid else 0 end)as otherfees,
	sum(vw.amountpaid)as TotalFees 	
         from kaverimis.vw_mis_revenue_report vw inner join
    (select a.applicationnumber,a.amountpaid from kaverimis.vw_mis_revenue_report a where 
      a.consideration >=_minval and a.consideration <=_maxval)
     vw1 on vw.applicationnumber=vw1.applicationnumber
	 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
    where  vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
   and  stamparticlecode =_stamparticlecode
   group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.finalregistrationnumber,vw.marketvalue, vw.consideration;

elseif (_choice = 7  and _srocode = 0 and _amounttype = 4) then --  All Srocodes market value
return query
select d.districtnamee as district,
       vw.sroname as officename,
       vw.booktype as book,
       vw.printablename as part,
      	vw.finalregistrationnumber,
	vw.marketvalue,
	vw.consideration,
        sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end)as StampDuty,
	sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end)as scanningfee,
	sum(case when vw.feerulecode not in (1, 2, 36) then vw.amountpaid else 0 end)as otherfees,
	sum(vw.amountpaid)as TotalFees 	
         from kaverimis.vw_mis_revenue_report vw inner join
    (select a.applicationnumber,a.amountpaid from kaverimis.vw_mis_revenue_report a where 
      a.marketvalue >=_minval and a.marketvalue  <=_maxval)
     vw1 on vw.applicationnumber=vw1.applicationnumber
	 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
    where  vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
   and  stamparticlecode =_stamparticlecode
   group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.finalregistrationnumber,vw.marketvalue, vw.consideration;

else --- ALL srocodes ALL Amounttypes
return query
select d.districtnamee as district,
       vw.sroname as officename,
       vw.booktype as book,
       vw.printablename as part,
      	vw.finalregistrationnumber,
	vw.marketvalue,
	vw.consideration,
        sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end)as StampDuty,
	sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end)as scanningfee,
	sum(case when vw.feerulecode not in (1, 2, 36) then vw.amountpaid else 0 end)as otherfees,
	sum(vw.amountpaid)as TotalFees 	
         from kaverimis.vw_mis_revenue_report vw inner join
    (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where 
      amountpaid >=_minval and amountpaid <=_maxval)
     vw1 on vw.applicationnumber=vw1.applicationnumber
	 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
    where  vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
   and  stamparticlecode =_stamparticlecode
   group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.finalregistrationnumber,vw.marketvalue, vw.consideration;

 end if;
END;

$$;


ALTER FUNCTION kaverimis.fn_mis_dailyrevenue_docwise_temp1(_srocode bigint, _stamparticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer, _choice integer) OWNER TO csgadmin;

--
-- Name: fn_mis_dailyrevenue_fy(bigint, bigint, text, text, bigint, bigint, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_dailyrevenue_fy(_srocode bigint, _regarticlecode bigint, _finfromyear text, _fintoyear text, _minval bigint DEFAULT NULL::bigint, _maxval bigint DEFAULT NULL::bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, officename character varying, book character varying, part text, articlename character varying, applicationnumber_cnt bigint, registrationfees numeric, stampduty numeric, scanningfee numeric, otherfees numeric, total numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
return query 
select distinct vw.district as districtname,
	vw.sroname as officename,
	    vw.booktype as book,
	--to_char(vw.registrationdatetime, 'MM-yyyy') month1,
	null as part,
	vw.articlename,
	count(vw.applicationnumber) as applicationnumber_cnt,
	sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
	sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end)as StampDuty ,
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end)as scanningfee,
	sum(case when vw.feerulecode not in (1,2,36)  then vw.amountpaid else 0 end) 
	/* commented on 29-11-2022 as feerulecode already filtered from feerulecodes 1,2,36 */
	/*-
	(sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end)))*/ as otherfees,
	sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode not in (1,2,36)  then vw.amountpaid else 0 end) /*-
	(sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end))))*/ as Total
from kaverimis.vw_mis_revenue_report vw
where vw.srocode=_srocode and 
vw.regarticlecode=_regarticlecode
and vw.registrationdatetime::date>=(to_date(substr(_finfromyear, 1, strpos(_finfromyear, '-')-1), 'YYYY-MM-DD') + interval '3 month')::date
and vw.registrationdatetime::date<=(to_date(substr(_fintoyear, 1, strpos(_fintoyear, '-')-1), 'YYYY-MM-DD') + interval '14 month' + interval '30 days')::date
group by vw.district , vw.sroname, vw.articlename,vw.booktype,to_char(vw.registrationdatetime, 'MM-yyyy') 
having 	(sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode not in (1,2,36)  then vw.amountpaid else 0 end)) /*-
	(sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end))))*/ >= _minval
	and 
		(sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode not in (1,2,36)  then vw.amountpaid else 0 end)) /*-
	(sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end))))*/ <= _maxval;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_dailyrevenue_fy(_srocode bigint, _regarticlecode bigint, _finfromyear text, _fintoyear text, _minval bigint, _maxval bigint, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_dailyrevenue_month(bigint, bigint, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_dailyrevenue_month(_srocode bigint, _regarticlecode bigint, _monyear character varying, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, sroname character varying, booktype character varying, month1 text, part text, articlename character varying, applicationnumber_cnt bigint, registrationfees numeric, stampduty numeric, scanningfee numeric, otherfees numeric, total numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
return query 
select distinct vw.district,
	vw.sroname,
	    vw.booktype,
	to_char(vw.registrationdatetime, 'MM-yyyy') month1,
	null as part,
	vw.articlename,
	count(vw.applicationnumber) as applicationnumber_cnt,
	sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
	sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end)as StampDuty ,
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end)as scanningfee,
	/* commented on 29-11-2022 as feerulecode already filtered from feerulecodes 1,2,36 */
	sum(case when vw.feerulecode not in (1,2,36)  then vw.amountpaid else 0 end) /*-
	(sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end)))*/ as otherfees,
	sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode not in (1,2,36)  then vw.amountpaid else 0 end)/* -
	(sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end))))*/ as Total
from kaverimis.vw_mis_revenue_report vw
where vw.srocode=_srocode and vw.regarticlecode=_regarticlecode
and to_char(vw.registrationdatetime, 'MM-yyyy')=_monyear
group by vw.district , vw.sroname, vw.articlename,vw.booktype,to_char(vw.registrationdatetime, 'MM-yyyy') 
having 	sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode not in (1,2,36)  then vw.amountpaid else 0 end)/* -
	(sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end))))*/ >= _minval
	and 
		sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode not in (1,2,36)  then vw.amountpaid else 0 end)/* -
	(sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) +
	sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end))))*/ <= _maxval;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_dailyrevenue_month(_srocode bigint, _regarticlecode bigint, _monyear character varying, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_dailyrevenue_periodly(bigint, bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_dailyrevenue_periodly(_districtcode bigint, _srocode bigint, _stamparticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, sroname character varying, booktype character varying, part character varying, articlename character varying, applicationnumber_cnt bigint, stampduty numeric, registrationfees numeric, scanningfees numeric, otherfees numeric, totalfees numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN 

if _stamparticlecode=0 then  --All articlename
 if _districtcode=0 then  --All District
	if _amounttype=0 then --no amounttype
		return query
		with a as  
		(select  distinct d.districtnamee as district,
       vw.sroname as officename, 
       vw.booktype as book,
       vw.printablename as part,
       vw.articlename as article,
       vw.applicationnumber as applicationnumber
	   from kaverimis.vw_mis_revenue_report vw 
	   inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	   inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
       where --feerulecode=1 and      
        vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime::date<=_todate 
		--and 
	  --vw.srocode=_srocode and
       
		--d.districtcode=_districtcode and
       
		--vw.stamparticlecode =_stamparticlecode 

       group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.articlename,vw.applicationnumber 

	  -- having sum(vw.amountpaid) >=_minval and sum(vw.amountpaid)<=_maxval
	 ) 

    select a.district,a.officename,a.book,a.part,a.article,
	   count( distinct rr.applicationnumber) as applicationnumber_cnt,
	   sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end)as StampDuty,
	   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end) as RegistrationFees,
	   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)as scanningfee,
	   sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)as otherfees, 
	   sum(rr.amountpaid)as TotalFees 
       from kaveri.documentmaster dm 
       inner join a on a.applicationnumber = dm.applicationnumber 
       inner join kaveri.feesrequired rr on rr.applicationnumber=dm.applicationnumber 
       
       group by a.district,a.officename,a.book,a.part,a.article; 
       
		   
	 elsif _amounttype=1 then --Total
	 
		return query
		 with a as  
		(select  distinct d.districtnamee as district,
       vw.sroname as officename, 
       vw.booktype as book,
       vw.printablename as part,
       vw.articlename as article,
       vw.applicationnumber as applicationnumber
	   from kaverimis.vw_mis_revenue_report vw 
