	   inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
       where --feerulecode=1 and      
        vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime::date<=_todate 
		--and 
	  --vw.srocode=_srocode and
       
		--d.districtcode=_districtcode and
       
		--vw.stamparticlecode =_stamparticlecode 

       group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.articlename,vw.applicationnumber 

	  having sum(vw.amountpaid) >=_minval and sum(vw.amountpaid)<=_maxval
	 ) 

    select a.district,a.officename,a.book,a.part,a.article,
	   count( distinct rr.applicationnumber) as applicationnumber_cnt,
	   sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end)as StampDuty,
	   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end) as RegistrationFees,
	   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)as scanningfee,
	   sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)as otherfees, 
	   sum(rr.amountpaid)as TotalFees 
       from kaveri.documentmaster dm 
       inner join a on a.applicationnumber = dm.applicationnumber 
       inner join kaveri.feesrequired rr on rr.applicationnumber=dm.applicationnumber 
       
       group by a.district,a.officename,a.book,a.part,a.article; 
	   
	   elsif _amounttype=2 then --Registration fees
	   
	   return query
