		vw.stamparticlecode =_stamparticlecode 

       group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.articlename,vw.applicationnumber 

	  having sum(vw.amountpaid) >=_minval and sum(vw.amountpaid)<=_maxval
	 ) 

    select a.district,a.officename,a.book,a.part,a.article,
	   count( distinct rr.applicationnumber) as applicationnumber_cnt,
	   sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end)as StampDuty,
	   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end) as RegistrationFees,
	   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)as scanningfee,
	   sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)as otherfees, 
	   sum(rr.amountpaid)as TotalFees 
       from kaveri.documentmaster dm 
       inner join a on a.applicationnumber = dm.applicationnumber 
       inner join kaveri.feesrequired rr on rr.applicationnumber=dm.applicationnumber 
       
       group by a.district,a.officename,a.book,a.part,a.article;  
	   
	   elsif _amounttype=5 then --otherfees
	   
	   return query
	   with a as  
		(select  distinct d.districtnamee as district,
       vw.sroname as officename, 
       vw.booktype as book,
       vw.printablename as part,
       vw.articlename as article,
       vw.applicationnumber as applicationnumber
	   from kaverimis.vw_mis_revenue_report vw 
	   inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	   inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
       where feerulecode not in (1,2,36,58,59,64) and      
        vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime::date<=_todate 
		and 
	   vw.srocode=_srocode and
       
		d.districtcode=_districtcode 
		and
       
		vw.stamparticlecode =_stamparticlecode 

       group by d.districtnamee,vw.sroname,vw.booktype,vw.printablename,vw.articlename,vw.applicationnumber 

	  having sum(vw.amountpaid) >=_minval and sum(vw.amountpaid)<=_maxval
	 ) 

    select a.district,a.officename,a.book,a.part,a.article,
	   count( distinct rr.applicationnumber) as applicationnumber_cnt,
	   sum(case when rr.feerulecode in (36,58,59)  then rr.amountpaid else 0 end)as StampDuty,
	   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end) as RegistrationFees,
	   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)as scanningfee,
	   sum(case when rr.feerulecode not in (1,2,36,58,59,64) then rr.amountpaid else 0 end)as otherfees, 
	   sum(rr.amountpaid)as TotalFees 
       from kaveri.documentmaster dm 
       inner join a on a.applicationnumber = dm.applicationnumber 
       inner join kaveri.feesrequired rr on rr.applicationnumber=dm.applicationnumber 
       
       group by a.district,a.officename,a.book,a.part,a.article; 
	   
	   end if;
	   
	   end if;
	   
	 	
END;

$$;


ALTER FUNCTION kaverimis.fn_mis_dailyrevenue_periodly(_districtcode bigint, _srocode bigint, _stamparticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer) OWNER TO csgadmin;

--
-- Name: fn_mis_dailyrevenue_periodly(bigint, bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_dailyrevenue_periodly(_districtcode bigint, _srocode bigint, _regarticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, sroname character varying, booktype character varying, part character varying, articlename character varying, applicationnumber_cnt bigint, stampduty numeric, registrationfees numeric, scanningfees numeric, otherfees numeric, totalfees numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    PageOffset integer := 0;
BEGIN
    IF _amounttype IS NULL THEN
        _amounttype := 0;
        _minval := 0;
        _maxval := 0;
    END IF;
    IF _minval IS NULL THEN
        _minval := 0;
    END IF;
    IF _maxval IS NULL THEN
        _maxval := 999999999;
    END IF;
    IF pagenumber IS NOT NULL AND pagesize IS NOT NULL THEN
        PageOffset := ((pagenumber - 1) * pagesize);
    END IF;
    IF (pagenumber <> -1 AND pagesize <> -1) THEN
        RETURN QUERY
        WITH base_docs AS (
            SELECT DISTINCT
                d.districtnamee::varchar AS district,
                sro.sronamee::varchar AS officename,
                b.booknameenglish::varchar AS book,
                b.printablename::varchar AS part,
                r.articlenamee::varchar AS article,
                dm.applicationnumber
            FROM kaveri.documentmaster dm
            JOIN kaveri.booktypemaster b
                ON dm.bookid = b.bookid
            JOIN kaveri.registrationarticles r
                ON dm.regarticlecode = r.regarticlecode
            JOIN kaveri.sromaster sro
                ON dm.srocode = sro.srocode
            JOIN kaveri.districtmaster d
                ON sro.districtcode = d.districtcode
            WHERE dm.isregistrationcompleted = true
              AND dm.registrationdatetime BETWEEN _fromdate AND (_todate + interval '1 day')
              AND (CASE WHEN _regarticlecode = 0 THEN true ELSE dm.regarticlecode = _regarticlecode END)
              AND (CASE WHEN _districtcode <> 0 THEN d.districtcode = _districtcode ELSE true END)
              AND (CASE WHEN _srocode <> 0 THEN dm.srocode = _srocode ELSE true END)
        ),
        success_epay AS (
            SELECT
                e.applicationnumber,
                e.deptreferencecode,
                e.feerulecode,
                e.totalamount,
                b.paymentmode,
                b.paymentstatuscode,
                b.transactiontimestamp
            FROM kaveri.ams_reg_epaymenttransdetails e
            JOIN kaveri.ams_reg_epaymentbankackdetails b
                ON b.deptreferencecode = e.deptreferencecode
            WHERE e.isdelete = false
              AND b.paymentstatuscode IN ('10700066','10700072')
              AND e.applicationnumber IN (SELECT applicationnumber FROM base_docs)
        ),
        amt AS (
            SELECT
                se.applicationnumber,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (
                        35,36,64,89,91,92,101,107,110,138,   -- stamp duty
                        59,100,                               -- cess
                        58,99                                 -- surcharge
                    )
                ), 0) AS stampduty_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ), 0) AS regfee_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode = 2
                ), 0) AS scanning_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode NOT IN (
                        35,36,64,89,91,92,101,107,110,138,   -- stamp duty
                        59,100,                               -- cess
                        58,99,                                -- surcharge
                        2,                                    -- scanning
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ), 0) AS other_amt,

                COALESCE(SUM(se.totalamount), 0) AS total_amt
            FROM success_epay se
            GROUP BY se.applicationnumber
        ),
        filtered_docs AS (
            SELECT
                bd.district,
                bd.officename,
                bd.book,
                bd.part,
                bd.article,
                bd.applicationnumber,
                COALESCE(a.stampduty_amt, 0) AS stampduty_amt,
                COALESCE(a.regfee_amt, 0) AS regfee_amt,
                COALESCE(a.scanning_amt, 0) AS scanning_amt,
                COALESCE(a.other_amt, 0) AS other_amt,
                COALESCE(a.total_amt, 0) AS total_amt
            FROM base_docs bd
            LEFT JOIN amt a
                ON a.applicationnumber = bd.applicationnumber
            WHERE
                CASE
                    WHEN _amounttype = 0 THEN true
                    WHEN _amounttype = 1 THEN COALESCE(a.total_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 2 THEN COALESCE(a.regfee_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 3 THEN COALESCE(a.stampduty_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 4 THEN COALESCE(a.scanning_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 5 THEN COALESCE(a.other_amt, 0) BETWEEN _minval AND _maxval
                    ELSE true
                END
        ),
        cte AS (
            SELECT
                fd.district,
                fd.officename,
                fd.book,
                fd.part,
                fd.article,
                COUNT(DISTINCT fd.applicationnumber) AS applicationnumber_cnt,
                SUM(fd.stampduty_amt) AS stampduty,
                SUM(fd.regfee_amt) AS registrationfees,
                SUM(fd.scanning_amt) AS scanningfees,
                SUM(fd.other_amt) AS otherfees,
                SUM(fd.total_amt) AS totalfees
            FROM filtered_docs fd
            GROUP BY
                fd.district,
                fd.officename,
                fd.book,
                fd.part,
                fd.article
        ),
        cte_count AS (
            SELECT COUNT(*) AS total_rows
            FROM cte
        )
        SELECT
            cte.district,
            cte.officename AS sroname,
            cte.book AS booktype,
            cte.part,
            cte.article AS articlename,
            cte.applicationnumber_cnt,
            cte.stampduty,
            cte.registrationfees,
            cte.scanningfees,
            cte.otherfees,
            cte.totalfees,
            total_row.total_rows::bigint AS totalcount
        FROM cte
        RIGHT JOIN (SELECT total_rows FROM cte_count) total_row
            ON true
        WHERE total_row.total_rows <> 0
        OFFSET PageOffset
        FETCH NEXT pagesize ROWS ONLY;

    ELSIF (pagenumber = -1 OR pagesize = -1) THEN
        RETURN QUERY
        WITH base_docs AS (
            SELECT DISTINCT
                d.districtnamee::varchar AS district,
                sro.sronamee::varchar AS officename,
                b.booknameenglish::varchar AS book,
                b.printablename::varchar AS part,
                r.articlenamee::varchar AS article,
                dm.applicationnumber
            FROM kaveri.documentmaster dm
            JOIN kaveri.booktypemaster b
                ON dm.bookid = b.bookid
            JOIN kaveri.registrationarticles r
                ON dm.regarticlecode = r.regarticlecode
            JOIN kaveri.sromaster sro
                ON dm.srocode = sro.srocode
            JOIN kaveri.districtmaster d
                ON sro.districtcode = d.districtcode
            WHERE dm.isregistrationcompleted = true
              AND dm.registrationdatetime BETWEEN _fromdate AND (_todate + interval '1 day')
              AND (CASE WHEN _regarticlecode = 0 THEN true ELSE dm.regarticlecode = _regarticlecode END)
              AND (CASE WHEN _districtcode <> 0 THEN d.districtcode = _districtcode ELSE true END)
              AND (CASE WHEN _srocode <> 0 THEN dm.srocode = _srocode ELSE true END)
        ),
        success_epay AS (
            SELECT
                e.applicationnumber,
                e.deptreferencecode,
                e.feerulecode,
                e.totalamount,
                b.paymentmode,
                b.paymentstatuscode,
                b.transactiontimestamp
            FROM kaveri.ams_reg_epaymenttransdetails e
            JOIN kaveri.ams_reg_epaymentbankackdetails b
                ON b.deptreferencecode = e.deptreferencecode
            WHERE e.isdelete = false
              AND b.paymentstatuscode IN ('10700066','10700072')
              AND e.applicationnumber IN (SELECT applicationnumber FROM base_docs)
        ),
        amt AS (
            SELECT
                se.applicationnumber,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (
                        35,36,64,89,91,92,101,107,110,138,   -- stamp duty
                        59,100,                               -- cess
                        58,99                                 -- surcharge
                    )
                ), 0) AS stampduty_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ), 0) AS regfee_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode = 2
                ), 0) AS scanning_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode NOT IN (
                        35,36,64,89,91,92,101,107,110,138,   -- stamp duty
                        59,100,                               -- cess
                        58,99,                                -- surcharge
                        2,                                    -- scanning
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ), 0) AS other_amt,

                COALESCE(SUM(se.totalamount), 0) AS total_amt
            FROM success_epay se
            GROUP BY se.applicationnumber
        ),
        filtered_docs AS (
            SELECT
                bd.district,
                bd.officename,
                bd.book,
                bd.part,
                bd.article,
                bd.applicationnumber,
                COALESCE(a.stampduty_amt, 0) AS stampduty_amt,
                COALESCE(a.regfee_amt, 0) AS regfee_amt,
                COALESCE(a.scanning_amt, 0) AS scanning_amt,
                COALESCE(a.other_amt, 0) AS other_amt,
                COALESCE(a.total_amt, 0) AS total_amt
            FROM base_docs bd
            LEFT JOIN amt a
                ON a.applicationnumber = bd.applicationnumber
            WHERE
                CASE
                    WHEN _amounttype = 0 THEN true
                    WHEN _amounttype = 1 THEN COALESCE(a.total_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 2 THEN COALESCE(a.regfee_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 3 THEN COALESCE(a.stampduty_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 4 THEN COALESCE(a.scanning_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 5 THEN COALESCE(a.other_amt, 0) BETWEEN _minval AND _maxval
                    ELSE true
                END
        ),
        cte AS (
            SELECT
                fd.district,
                fd.officename,
                fd.book,
                fd.part,
                fd.article,
                COUNT(DISTINCT fd.applicationnumber) AS applicationnumber_cnt,
                SUM(fd.stampduty_amt) AS stampduty,
                SUM(fd.regfee_amt) AS registrationfees,
                SUM(fd.scanning_amt) AS scanningfees,
                SUM(fd.other_amt) AS otherfees,
                SUM(fd.total_amt) AS totalfees
            FROM filtered_docs fd
            GROUP BY
                fd.district,
                fd.officename,
                fd.book,
                fd.part,
                fd.article
        ),
        cte_count AS (
            SELECT COUNT(*) AS total_rows
            FROM cte
        )
        SELECT
            cte.district,
            cte.officename AS sroname,
            cte.book AS booktype,
            cte.part,
            cte.article AS articlename,
            cte.applicationnumber_cnt,
            cte.stampduty,
            cte.registrationfees,
            cte.scanningfees,
            cte.otherfees,
            cte.totalfees,
            total_row.total_rows::bigint AS totalcount
        FROM cte
        RIGHT JOIN (SELECT total_rows FROM cte_count) total_row
            ON true
        WHERE total_row.total_rows <> 0;
    END IF;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_dailyrevenue_periodly(_districtcode bigint, _srocode bigint, _regarticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_dailyrevenue_periodly(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_dailyrevenue_periodly(_srocode bigint, _stamparticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT NULL::integer, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer, _choice integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, sroname character varying, booktype character varying, part character varying, articlename character varying, applicationnumber_cnt bigint, registrationfees numeric, stampduty numeric, scanningfees numeric, otherfees numeric, totalfees numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE

PageOffset INTEGER := 0;

BEGIN 

PageOffset := ((pagenumber - 1) * pagesize); 

 
if _choice=0 then   --- amounttype is Registration fees,stamp duty, scanning fees 
return query
select d.districtnamee as district,vw.sroname,vw.booktype,vw.printablename as part,
    vw.articlename, count(vw.applicationnumber) as applicationnumber_cnt,
    sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) as StampDuty,
    sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
    sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end) as ScanningFees,
    sum(case when vw.feerulecode not in (1, 36, 2)  then vw.amountpaid else 0 end) as OtherFees,
    sum(vw.amountpaid) as TotalFees
    from kaverimis.vw_mis_revenue_report vw inner join
    (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_srocode
     and amountpaid >=_minval and amountpaid<=_maxval and feerulecode=_amounttype)
     vw1 on vw.applicationnumber=vw1.applicationnumber
	 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
    where --sro.districtcode = _districtcode and 
	vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
   and vw.srocode=_srocode and stamparticlecode =_stamparticlecode
   group by d.districtnamee,vw.articlename,vw.district,vw.sroname,vw.booktype, vw.printablename;
 
  elseif _choice=1 then -- amount type is other fees
  return query
  select d.districtnamee as district,vw.sroname,vw.booktype,vw.printablename as part,
    vw.articlename, count(vw.applicationnumber) as applicationnumber_cnt,
    sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) as StampDuty,
    sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
    sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end) as ScanningFees,
    sum(case when vw.feerulecode not in (1, 36, 2)  then vw.amountpaid else 0 end) as OtherFees,
    sum(vw.amountpaid) as TotalFees
    from kaverimis.vw_mis_revenue_report vw inner join
    (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_srocode
     and amountpaid >=_minval and amountpaid<=_maxval and feerulecode  in  (1, 36, 2))
     vw1 on vw.applicationnumber=vw1.applicationnumber
	 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
    where --sro.districtcode = _districtcode and 
	vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
   and vw.srocode=_srocode and stamparticlecode =_stamparticlecode
  group by d.districtnamee,vw.articlename,d.districtnamee,vw.sroname,vw.booktype, vw.printablename;

  elseif _choice=2 and _amounttype = 0 then -- amounttype is total
  return query
  select d.districtnamee as district,vw.sroname,vw.booktype,vw.printablename as part,
    vw.articlename, count(vw.applicationnumber) as applicationnumber_cnt,
    sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) as StampDuty,
    sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
    sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end) as ScanningFees,
    sum(case when vw.feerulecode not in (1, 36, 2)  then vw.amountpaid else 0 end) as OtherFees,
    sum(vw.amountpaid) as TotalFees
    from kaverimis.vw_mis_revenue_report vw inner join
    (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_srocode
     and amountpaid >=_minval and amountpaid<=_maxval )
     vw1 on vw.applicationnumber=vw1.applicationnumber
	 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
    where --sro.districtcode = _districtcode and 
	vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
   and vw.srocode=_srocode and stamparticlecode =_stamparticlecode
  group by d.districtnamee,vw.articlename,d.districtnamee,vw.sroname,vw.booktype, vw.printablename;
  
  elseif (_choice=3  and _srocode = 0) then   --- All District All Srocodes with amountype 1,36,2
  return query
  select d.districtnamee as district,vw.sroname,vw.booktype,vw.printablename as part,
    vw.articlename, count(vw.applicationnumber) as applicationnumber_cnt,
    sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) as StampDuty,
    sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
    sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end) as ScanningFees,
    sum(case when vw.feerulecode not in (1, 36, 2)  then vw.amountpaid else 0 end) as OtherFees,
    sum(vw.amountpaid) as TotalFees
    from kaverimis.vw_mis_revenue_report vw inner join
    (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where 
	 srocode=any(select all srocode from kaveri.sromaster)
     and amountpaid >=_minval and amountpaid<=_maxval and feerulecode = _amounttype)
     vw1 on vw.applicationnumber=vw1.applicationnumber
	 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
    where  vw.registrationdatetime::date>=_fromdate
	and vw.registrationdatetime<=_todate 
   and stamparticlecode =_stamparticlecode
  group by stamparticlecode,d.districtnamee,vw.articlename,d.districtnamee,vw.sroname,vw.booktype, vw.printablename;

elseif (_choice = 4  and _srocode = 0 and _amounttype = 3) then --- All District All Srocodes with amountype as otherfees
return query
	  select d.districtnamee as district,vw.sroname,vw.booktype,vw.printablename as part,
    vw.articlename, count(vw.applicationnumber) as applicationnumber_cnt,
    sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) as StampDuty,
    sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
    sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end) as ScanningFees,
    sum(case when vw.feerulecode not in (1, 36, 2)  then vw.amountpaid else 0 end) as OtherFees,
    sum(vw.amountpaid) as TotalFees
    from kaverimis.vw_mis_revenue_report vw inner join
    (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where 
	 srocode=any(select all srocode from kaveri.sromaster)
     and amountpaid >=_minval and amountpaid<=_maxval and feerulecode  in  (1, 36, 2))
     vw1 on vw.applicationnumber=vw1.applicationnumber
	 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
    where vw.registrationdatetime::date>=_fromdate
	and vw.registrationdatetime<=_todate
   and stamparticlecode =_stamparticlecode
    group by stamparticlecode,d.districtnamee,vw.articlename,d.districtnamee,vw.sroname,vw.booktype, vw.printablename;

else	  			--- All districts all srocodes with Total
	 
	 return query
  select d.districtnamee as district,vw.sroname,vw.booktype,vw.printablename as part,
    vw.articlename, count(vw.applicationnumber) as applicationnumber_cnt,
    sum(case when vw.feerulecode=36  then vw.amountpaid else 0 end) as StampDuty,
    sum(case when vw.feerulecode=1  then vw.amountpaid else 0 end) as RegistrationFees,
    sum(case when vw.feerulecode=2  then vw.amountpaid else 0 end) as ScanningFees,
    sum(case when vw.feerulecode not in (1, 36, 2)  then vw.amountpaid else 0 end) as OtherFees,
    sum(vw.amountpaid) as TotalFees
    from kaverimis.vw_mis_revenue_report vw inner join
    (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where amountpaid >=_minval and amountpaid<=_maxval )
     vw1 on vw.applicationnumber=vw1.applicationnumber
	 inner join kaveri.sromaster sro on vw.srocode = sro.srocode
	 inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
    where  vw.registrationdatetime::date>=_fromdate and vw.registrationdatetime<=_todate
    and stamparticlecode =_stamparticlecode
  group by d.districtnamee,vw.articlename,d.districtnamee,vw.sroname,vw.booktype, vw.printablename; 

    
     end if;
END;

$$;


ALTER FUNCTION kaverimis.fn_mis_dailyrevenue_periodly(_srocode bigint, _stamparticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer, _choice integer) OWNER TO csgadmin;

--
-- Name: fn_mis_dailyrevenue_periodly_20260310(bigint, bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_dailyrevenue_periodly_20260310(_districtcode bigint, _srocode bigint, _regarticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, sroname character varying, booktype character varying, part character varying, articlename character varying, applicationnumber_cnt bigint, stampduty numeric, registrationfees numeric, scanningfees numeric, otherfees numeric, totalfees numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$




DECLARE

	PageOffset INTEGER := 0;

BEGIN 
PageOffset := ((pagenumber - 1) * pagesize);
---------

if _amounttype is null then 
 _amounttype:=0;
_minval :=0;
_maxval:=0;

end if;


if (pagenumber<>-1 and pagesize<>-1) then

return query
		with cte as (with a as  
		(select  distinct d.districtnamee as district,
       sro.sronamee as officename, 
       b.booknameenglish  as book,
       b.printablename as part,
       r.articlenamee  as article,
       dm.applicationnumber as applicationnumber
	   from kaveri.documentmaster dm
	   join kaveri.booktypemaster b on dm.bookid=b.bookid 	
	   join kaveri.registrationarticles r on dm.regarticlecode=r.regarticlecode  
	   inner join kaveri.sromaster sro on dm.srocode = sro.srocode
	   inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
	   left join kaveri.feesrequired f on dm.applicationnumber=f.applicationnumber  
       where      dm.isregistrationcompleted=true and  
        (dm.registrationdatetime between _fromdate and  _todate + INTERVAL '1 day')
        and 
        (case

          when _regarticlecode=0 then true
           else 
           dm.regarticlecode=_regarticlecode 

          end)
         
        
        and 
        (case
when _amounttype=2 then f.feerulecode in (1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109)
when _amounttype=3 then f.feerulecode in (35,36,64,89,91,92,101,107,110,138)
when _amounttype=4 then f.feerulecode = 2
when _amounttype=5 then f.feerulecode not in (
    2,
    35,36,64,89,91,92,101,107,110,138,
    1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
)

           else 
           true

          end)
        and (case  when _districtcode<>0 then d.districtcode=_districtcode  ELSE  true end)
		and (case  when _srocode<> 0 then dm.srocode=_srocode  ELSE  true end)
		group by d.districtnamee,sro.sronamee,b.booknameenglish,b.printablename,
		r.articlenamee,
		dm.applicationnumber
       
       having
       (case

          when _amounttype=0 then true
          when _amounttype in (1,2,3,4,5)  then sum(f.amountpaid) >=_minval and sum(f.amountpaid)<=_maxval                
           else 
           true

          end)

	 
	 ) 

    select a.district,a.officename,a.book,a.part,a.article,
	   count( distinct a.applicationnumber) as applicationnumber_cnt,
sum(case when rr.feerulecode in (35,36,64,89,91,92,101,107,110,138)
         then rr.amountpaid else 0 end) as StampDuty,

sum(case when rr.feerulecode in (1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109)
         then rr.amountpaid else 0 end) as RegistrationFees,

sum(case when rr.feerulecode = 2
         then rr.amountpaid else 0 end) as scanningfee,

sum(case when rr.amountpaid > 0
          and rr.feerulecode not in (
              2,
              35,36,64,89,91,92,101,107,110,138,
              1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
          )
         then rr.amountpaid else 0 end) as otherfees,
	   sum(case when  rr.amountpaid>0  then rr.amountpaid else 0 end)as TotalFees 
       from  
        a  
       left join kaveri.feesrequired rr on a.applicationnumber=rr.applicationnumber
       
       group by a.district,a.officename,a.book,a.part,a.article),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true 
			where total_row.total_rows<>0
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
			
elsif (pagenumber=-1 or  pagesize=-1) then 

return query
		with cte as (with a as  
		(select  distinct d.districtnamee as district,
       sro.sronamee as officename, 
       b.booknameenglish  as book,
       b.printablename as part,
       r.articlenamee  as article,
       dm.applicationnumber as applicationnumber
	   from kaveri.documentmaster dm
	   join kaveri.booktypemaster b on dm.bookid=b.bookid 	
	   join kaveri.registrationarticles r on dm.regarticlecode=r.regarticlecode  
	   inner join kaveri.sromaster sro on dm.srocode = sro.srocode
	   inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
	   left join kaveri.feesrequired f on dm.applicationnumber=f.applicationnumber  
       where      dm.isregistrationcompleted=true and  
        (dm.registrationdatetime between _fromdate and  _todate + INTERVAL '1 day')
        and 
        (case

          when _regarticlecode=0 then true
           else 
           dm.regarticlecode=_regarticlecode 

          end)
         
        
        and 
        (case

          when _amounttype=0 then true
          when _amounttype=1 then true                  
when _amounttype=2 then f.feerulecode in (1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109)
when _amounttype=3 then f.feerulecode in (35,36,64,89,91,92,101,107,110,138)
when _amounttype=4 then f.feerulecode = 2
when _amounttype=5 then f.feerulecode not in (
    2,
    35,36,64,89,91,92,101,107,110,138,
    1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
)

           else 
           true

          end)
          
        and (case  when _districtcode<>0 then d.districtcode=_districtcode  ELSE  true end)
		and (case  when _srocode<> 0 then dm.srocode=_srocode  ELSE  true end)
		group by d.districtnamee,sro.sronamee,b.booknameenglish,b.printablename,
		r.articlenamee,
		dm.applicationnumber
       
       having
       (case

          when _amounttype=0 then true
          when _amounttype in (1,2,3,4,5)  then sum(f.amountpaid) >=_minval and sum(f.amountpaid)<=_maxval                
           else 
           true

          end)

	 
	 ) 

    select a.district,a.officename,a.book,a.part,a.article,
	   count( distinct a.applicationnumber) as applicationnumber_cnt,
	  sum(case when rr.feerulecode in (35,36,64,89,91,92,101,107,110,138)
         then rr.amountpaid else 0 end) as StampDuty,

sum(case when rr.feerulecode in (1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109)
         then rr.amountpaid else 0 end) as RegistrationFees,

sum(case when rr.feerulecode = 2
         then rr.amountpaid else 0 end) as scanningfee,

sum(case when rr.amountpaid > 0
          and rr.feerulecode not in (
              2,
              35,36,64,89,91,92,101,107,110,138,
              1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
          )
         then rr.amountpaid else 0 end) as otherfees,

	   sum(case when  rr.amountpaid>0  then rr.amountpaid else 0 end)as TotalFees 
       from  
        a  
       left  join kaveri.feesrequired rr on a.applicationnumber=rr.applicationnumber 
       
       group by a.district,a.officename,a.book,a.part,a.article),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true 
			where total_row.total_rows<>0;



end if;




	   
	 	
END;

$$;


ALTER FUNCTION kaverimis.fn_mis_dailyrevenue_periodly_20260310(_districtcode bigint, _srocode bigint, _regarticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_dailyrevenue_periodly_20260413(bigint, bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: manjunathswamy
--

CREATE FUNCTION kaverimis.fn_mis_dailyrevenue_periodly_20260413(_districtcode bigint, _srocode bigint, _regarticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, sroname character varying, booktype character varying, part character varying, articlename character varying, applicationnumber_cnt bigint, stampduty numeric, registrationfees numeric, scanningfees numeric, otherfees numeric, totalfees numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    PageOffset integer := 0;
BEGIN
    IF _amounttype IS NULL THEN
        _amounttype := 0;
        _minval := 0;
        _maxval := 0;
    END IF;
    IF _minval IS NULL THEN
        _minval := 0;
    END IF;
    IF _maxval IS NULL THEN
        _maxval := 999999999;
    END IF;
    IF pagenumber IS NOT NULL AND pagesize IS NOT NULL THEN
        PageOffset := ((pagenumber - 1) * pagesize);
    END IF;
    IF (pagenumber <> -1 AND pagesize <> -1) THEN
        RETURN QUERY
        WITH base_docs AS (
            SELECT DISTINCT
                d.districtnamee::varchar AS district,
                sro.sronamee::varchar AS officename,
                b.booknameenglish::varchar AS book,
                b.printablename::varchar AS part,
                r.articlenamee::varchar AS article,
                dm.applicationnumber
            FROM kaveri.documentmaster dm
            JOIN kaveri.booktypemaster b
                ON dm.bookid = b.bookid
            JOIN kaveri.registrationarticles r
                ON dm.regarticlecode = r.regarticlecode
            JOIN kaveri.sromaster sro
                ON dm.srocode = sro.srocode
            JOIN kaveri.districtmaster d
                ON sro.districtcode = d.districtcode
            WHERE dm.isregistrationcompleted = true
              AND dm.registrationdatetime BETWEEN _fromdate AND (_todate + interval '1 day')
              AND (CASE WHEN _regarticlecode = 0 THEN true ELSE dm.regarticlecode = _regarticlecode END)
              AND (CASE WHEN _districtcode <> 0 THEN d.districtcode = _districtcode ELSE true END)
              AND (CASE WHEN _srocode <> 0 THEN dm.srocode = _srocode ELSE true END)
        ),
        success_epay AS (
            SELECT
                e.applicationnumber,
                e.deptreferencecode,
                e.feerulecode,
                e.totalamount,
                b.paymentmode,
                b.paymentstatuscode,
                b.transactiontimestamp
            FROM kaveri.ams_reg_epaymenttransdetails e
            JOIN kaveri.ams_reg_epaymentbankackdetails b
                ON b.deptreferencecode = e.deptreferencecode
            WHERE e.isdelete = false
              AND b.paymentstatuscode IN ('10700066','10700072')
              AND e.applicationnumber IN (SELECT applicationnumber FROM base_docs)
        ),
        amt AS (
            SELECT
                se.applicationnumber,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (
                        35,36,64,89,91,92,101,107,110,138,   -- stamp duty
                        59,100,                               -- cess
                        58,99                                 -- surcharge
                    )
                ), 0) AS stampduty_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ), 0) AS regfee_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode = 2
                ), 0) AS scanning_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode NOT IN (
                        35,36,64,89,91,92,101,107,110,138,   -- stamp duty
                        59,100,                               -- cess
                        58,99,                                -- surcharge
                        2,                                    -- scanning
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ), 0) AS other_amt,

                COALESCE(SUM(se.totalamount), 0) AS total_amt
            FROM success_epay se
            GROUP BY se.applicationnumber
        ),
        filtered_docs AS (
            SELECT
                bd.district,
                bd.officename,
                bd.book,
                bd.part,
                bd.article,
                bd.applicationnumber,
                COALESCE(a.stampduty_amt, 0) AS stampduty_amt,
                COALESCE(a.regfee_amt, 0) AS regfee_amt,
                COALESCE(a.scanning_amt, 0) AS scanning_amt,
                COALESCE(a.other_amt, 0) AS other_amt,
                COALESCE(a.total_amt, 0) AS total_amt
            FROM base_docs bd
            LEFT JOIN amt a
                ON a.applicationnumber = bd.applicationnumber
            WHERE
                CASE
                    WHEN _amounttype = 0 THEN true
                    WHEN _amounttype = 1 THEN COALESCE(a.total_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 2 THEN COALESCE(a.regfee_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 3 THEN COALESCE(a.stampduty_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 4 THEN COALESCE(a.scanning_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 5 THEN COALESCE(a.other_amt, 0) BETWEEN _minval AND _maxval
                    ELSE true
                END
        ),
        cte AS (
            SELECT
                fd.district,
                fd.officename,
                fd.book,
                fd.part,
                fd.article,
                COUNT(DISTINCT fd.applicationnumber) AS applicationnumber_cnt,
                SUM(fd.stampduty_amt) AS stampduty,
                SUM(fd.regfee_amt) AS registrationfees,
                SUM(fd.scanning_amt) AS scanningfees,
                SUM(fd.other_amt) AS otherfees,
                SUM(fd.total_amt) AS totalfees
            FROM filtered_docs fd
            GROUP BY
                fd.district,
                fd.officename,
                fd.book,
                fd.part,
                fd.article
        ),
        cte_count AS (
            SELECT COUNT(*) AS total_rows
            FROM cte
        )
        SELECT
            cte.district,
            cte.officename AS sroname,
            cte.book AS booktype,
            cte.part,
            cte.article AS articlename,
            cte.applicationnumber_cnt,
            cte.stampduty,
            cte.registrationfees,
            cte.scanningfees,
            cte.otherfees,
            cte.totalfees,
            total_row.total_rows::bigint AS totalcount
        FROM cte
        RIGHT JOIN (SELECT total_rows FROM cte_count) total_row
            ON true
        WHERE total_row.total_rows <> 0
        OFFSET PageOffset
        FETCH NEXT pagesize ROWS ONLY;

    ELSIF (pagenumber = -1 OR pagesize = -1) THEN
        RETURN QUERY
        WITH base_docs AS (
            SELECT DISTINCT
                d.districtnamee::varchar AS district,
                sro.sronamee::varchar AS officename,
                b.booknameenglish::varchar AS book,
                b.printablename::varchar AS part,
                r.articlenamee::varchar AS article,
                dm.applicationnumber
            FROM kaveri.documentmaster dm
            JOIN kaveri.booktypemaster b
                ON dm.bookid = b.bookid
            JOIN kaveri.registrationarticles r
                ON dm.regarticlecode = r.regarticlecode
            JOIN kaveri.sromaster sro
                ON dm.srocode = sro.srocode
            JOIN kaveri.districtmaster d
                ON sro.districtcode = d.districtcode
            WHERE dm.isregistrationcompleted = true
              AND dm.registrationdatetime BETWEEN _fromdate AND (_todate + interval '1 day')
              AND (CASE WHEN _regarticlecode = 0 THEN true ELSE dm.regarticlecode = _regarticlecode END)
              AND (CASE WHEN _districtcode <> 0 THEN d.districtcode = _districtcode ELSE true END)
              AND (CASE WHEN _srocode <> 0 THEN dm.srocode = _srocode ELSE true END)
        ),
        success_epay AS (
            SELECT
                e.applicationnumber,
                e.deptreferencecode,
                e.feerulecode,
                e.totalamount,
                b.paymentmode,
                b.paymentstatuscode,
                b.transactiontimestamp
            FROM kaveri.ams_reg_epaymenttransdetails e
            JOIN kaveri.ams_reg_epaymentbankackdetails b
                ON b.deptreferencecode = e.deptreferencecode
            WHERE e.isdelete = false
              AND b.paymentstatuscode IN ('10700066','10700072')
              AND e.applicationnumber IN (SELECT applicationnumber FROM base_docs)
        ),
        amt AS (
            SELECT
                se.applicationnumber,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (
                        35,36,64,89,91,92,101,107,110,138,   -- stamp duty
                        59,100,                               -- cess
                        58,99                                 -- surcharge
                    )
                ), 0) AS stampduty_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ), 0) AS regfee_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode = 2
                ), 0) AS scanning_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode NOT IN (
                        35,36,64,89,91,92,101,107,110,138,   -- stamp duty
                        59,100,                               -- cess
                        58,99,                                -- surcharge
                        2,                                    -- scanning
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ), 0) AS other_amt,

                COALESCE(SUM(se.totalamount), 0) AS total_amt
            FROM success_epay se
            GROUP BY se.applicationnumber
        ),
        filtered_docs AS (
            SELECT
                bd.district,
                bd.officename,
                bd.book,
                bd.part,
                bd.article,
                bd.applicationnumber,
                COALESCE(a.stampduty_amt, 0) AS stampduty_amt,
                COALESCE(a.regfee_amt, 0) AS regfee_amt,
                COALESCE(a.scanning_amt, 0) AS scanning_amt,
                COALESCE(a.other_amt, 0) AS other_amt,
                COALESCE(a.total_amt, 0) AS total_amt
            FROM base_docs bd
            LEFT JOIN amt a
                ON a.applicationnumber = bd.applicationnumber
            WHERE
                CASE
                    WHEN _amounttype = 0 THEN true
                    WHEN _amounttype = 1 THEN COALESCE(a.total_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 2 THEN COALESCE(a.regfee_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 3 THEN COALESCE(a.stampduty_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 4 THEN COALESCE(a.scanning_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 5 THEN COALESCE(a.other_amt, 0) BETWEEN _minval AND _maxval
                    ELSE true
                END
        ),
        cte AS (
            SELECT
                fd.district,
                fd.officename,
                fd.book,
                fd.part,
                fd.article,
                COUNT(DISTINCT fd.applicationnumber) AS applicationnumber_cnt,
                SUM(fd.stampduty_amt) AS stampduty,
                SUM(fd.regfee_amt) AS registrationfees,
                SUM(fd.scanning_amt) AS scanningfees,
                SUM(fd.other_amt) AS otherfees,
                SUM(fd.total_amt) AS totalfees
            FROM filtered_docs fd
            GROUP BY
                fd.district,
                fd.officename,
                fd.book,
                fd.part,
                fd.article
        ),
        cte_count AS (
            SELECT COUNT(*) AS total_rows
            FROM cte
        )
        SELECT
            cte.district,
            cte.officename AS sroname,
            cte.book AS booktype,
            cte.part,
            cte.article AS articlename,
            cte.applicationnumber_cnt,
            cte.stampduty,
            cte.registrationfees,
            cte.scanningfees,
            cte.otherfees,
            cte.totalfees,
            total_row.total_rows::bigint AS totalcount
        FROM cte
        RIGHT JOIN (SELECT total_rows FROM cte_count) total_row
            ON true
        WHERE total_row.total_rows <> 0;
    END IF;
END;
$$;


