when _amounttype=2 then f.feerulecode in (1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109)
when _amounttype=3 then f.feerulecode in (35,36,64,89,91,92,101,107,110,138)
when _amounttype=4 then f.feerulecode = 2
when _amounttype=5 then f.feerulecode not in (
