ALTER FUNCTION kaverimis.fn_mis_dailyrevenue_periodly_23012024(_districtcode bigint, _srocode bigint, _regarticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_dailyrevenue_periodly_bck(bigint, bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_dailyrevenue_periodly_bck(_districtcode bigint, _srocode bigint, _regarticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, sroname character varying, booktype character varying, part character varying, articlename character varying, applicationnumber_cnt bigint, stampduty numeric, registrationfees numeric, scanningfees numeric, otherfees numeric, totalfees numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    PageOffset integer := 0;
BEGIN
    IF _amounttype IS NULL THEN
        _amounttype := 0;
        _minval := 0;
        _maxval := 0;
    END IF;
    IF _minval IS NULL THEN
        _minval := 0;
    END IF;
    IF _maxval IS NULL THEN
        _maxval := 999999999;
    END IF;
    IF pagenumber IS NOT NULL AND pagesize IS NOT NULL THEN
        PageOffset := ((pagenumber - 1) * pagesize);
    END IF;
    IF (pagenumber <> -1 AND pagesize <> -1) THEN
        RETURN QUERY
        WITH base_docs AS (
            SELECT DISTINCT
                d.districtnamee::varchar AS district,
                sro.sronamee::varchar AS officename,
                b.booknameenglish::varchar AS book,
                b.printablename::varchar AS part,
                r.articlenamee::varchar AS article,
                dm.applicationnumber
            FROM kaveri.documentmaster dm
            JOIN kaveri.booktypemaster b
                ON dm.bookid = b.bookid
            JOIN kaveri.registrationarticles r
                ON dm.regarticlecode = r.regarticlecode
            JOIN kaveri.sromaster sro
                ON dm.srocode = sro.srocode
            JOIN kaveri.districtmaster d
                ON sro.districtcode = d.districtcode
            WHERE dm.isregistrationcompleted = true
              AND dm.registrationdatetime BETWEEN _fromdate AND (_todate + interval '1 day')
              AND (CASE WHEN _regarticlecode = 0 THEN true ELSE dm.regarticlecode = _regarticlecode END)
              AND (CASE WHEN _districtcode <> 0 THEN d.districtcode = _districtcode ELSE true END)
              AND (CASE WHEN _srocode <> 0 THEN dm.srocode = _srocode ELSE true END)
        ),
        success_epay AS (
            SELECT
                e.applicationnumber,
                e.deptreferencecode,
                e.feerulecode,
                e.totalamount,
                b.paymentmode,
                b.paymentstatuscode,
                b.transactiontimestamp
            FROM kaveri.ams_reg_epaymenttransdetails e
            JOIN kaveri.ams_reg_epaymentbankackdetails b
              ON b.deptreferencecode = e.deptreferencecode
            WHERE e.isdelete = false
              AND b.paymentstatuscode IN ('10700066','10700072')
              AND e.applicationnumber IN (SELECT applicationnumber FROM base_docs)
        ),
        amt AS (
            SELECT
                se.applicationnumber,
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (35,36,64,89,91,92,101,107,110,138)
                ), 0) AS stampduty_amt,
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (59,100)
                ), 0) AS cess_amt,
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ), 0) AS regfee_amt,
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode = 2
                ), 0) AS scanning_amt,
                COALESCE(SUM(se.totalamount), 0) AS total_amt,
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode NOT IN (
                        35,36,64,89,91,92,101,107,110,138,
                        59,100,
                        2,
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ), 0) AS other_amt
            FROM success_epay se
            GROUP BY se.applicationnumber
        ),
        filtered_docs AS (
            SELECT
                bd.district,
                bd.officename,
                bd.book,
                bd.part,
                bd.article,
                bd.applicationnumber,
                COALESCE(a.stampduty_amt, 0) AS stampduty_amt,
                COALESCE(a.regfee_amt, 0) AS regfee_amt,
                COALESCE(a.scanning_amt, 0) AS scanning_amt,
                COALESCE(a.other_amt, 0) AS other_amt,
                COALESCE(a.total_amt, 0) AS total_amt
            FROM base_docs bd
            LEFT JOIN amt a
                ON a.applicationnumber = bd.applicationnumber
            WHERE
                CASE
                    WHEN _amounttype = 0 THEN true
                    WHEN _amounttype = 1 THEN COALESCE(a.total_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 2 THEN COALESCE(a.regfee_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 3 THEN COALESCE(a.stampduty_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 4 THEN COALESCE(a.scanning_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 5 THEN COALESCE(a.other_amt, 0) BETWEEN _minval AND _maxval
                    ELSE true
                END
        ),
        cte AS (
            SELECT
                fd.district,
                fd.officename,
                fd.book,
                fd.part,
                fd.article,
                COUNT(DISTINCT fd.applicationnumber) AS applicationnumber_cnt,
                SUM(fd.stampduty_amt) AS stampduty,
                SUM(fd.regfee_amt) AS registrationfees,
                SUM(fd.scanning_amt) AS scanningfees,
                SUM(fd.other_amt) AS otherfees,
                SUM(fd.total_amt) AS totalfees
            FROM filtered_docs fd
            GROUP BY
                fd.district,
                fd.officename,
                fd.book,
                fd.part,
                fd.article
        ),
        cte_count AS (
            SELECT COUNT(*) AS total_rows
            FROM cte
        )
        SELECT
            cte.district,
            cte.officename AS sroname,
            cte.book AS booktype,
            cte.part,
            cte.article AS articlename,
            cte.applicationnumber_cnt,
            cte.stampduty,
            cte.registrationfees,
            cte.scanningfees,
            cte.otherfees,
            cte.totalfees,
            total_row.total_rows::bigint AS totalcount
        FROM cte
        RIGHT JOIN (SELECT total_rows FROM cte_count) total_row
            ON true
        WHERE total_row.total_rows <> 0
        OFFSET PageOffset
        FETCH NEXT pagesize ROWS ONLY;
    ELSIF (pagenumber = -1 OR pagesize = -1) THEN
        RETURN QUERY
        WITH base_docs AS (
            SELECT DISTINCT
                d.districtnamee::varchar AS district,
                sro.sronamee::varchar AS officename,
                b.booknameenglish::varchar AS book,
                b.printablename::varchar AS part,
                r.articlenamee::varchar AS article,
                dm.applicationnumber
            FROM kaveri.documentmaster dm
            JOIN kaveri.booktypemaster b
                ON dm.bookid = b.bookid
            JOIN kaveri.registrationarticles r
                ON dm.regarticlecode = r.regarticlecode
            JOIN kaveri.sromaster sro
                ON dm.srocode = sro.srocode
            JOIN kaveri.districtmaster d
                ON sro.districtcode = d.districtcode
            WHERE dm.isregistrationcompleted = true
              AND dm.registrationdatetime BETWEEN _fromdate AND (_todate + interval '1 day')
              AND (CASE WHEN _regarticlecode = 0 THEN true ELSE dm.regarticlecode = _regarticlecode END)
              AND (CASE WHEN _districtcode <> 0 THEN d.districtcode = _districtcode ELSE true END)
              AND (CASE WHEN _srocode <> 0 THEN dm.srocode = _srocode ELSE true END)
        ),
        success_epay AS (
            SELECT
                e.applicationnumber,
                e.deptreferencecode,
                e.feerulecode,
                e.totalamount,
                b.paymentmode,
                b.paymentstatuscode,
                b.transactiontimestamp
            FROM kaveri.ams_reg_epaymenttransdetails e
            JOIN kaveri.ams_reg_epaymentbankackdetails b
              ON b.deptreferencecode = e.deptreferencecode
            WHERE e.isdelete = false
              AND b.paymentstatuscode IN ('10700066','10700072')
              AND e.applicationnumber IN (SELECT applicationnumber FROM base_docs)
        ),
        amt AS (
            SELECT
                se.applicationnumber,
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (35,36,64,89,91,92,101,107,110,138)
                ), 0) AS stampduty_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (59,100)
                ), 0) AS cess_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ), 0) AS regfee_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode = 2
                ), 0) AS scanning_amt,

                COALESCE(SUM(se.totalamount), 0) AS total_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode NOT IN (
                        35,36,64,89,91,92,101,107,110,138,
                        59,100,
                        2,
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ), 0) AS other_amt
            FROM success_epay se
            GROUP BY se.applicationnumber
        ),
        filtered_docs AS (
            SELECT
                bd.district,
                bd.officename,
                bd.book,
                bd.part,
                bd.article,
                bd.applicationnumber,
                COALESCE(a.stampduty_amt, 0) AS stampduty_amt,
                COALESCE(a.regfee_amt, 0) AS regfee_amt,
                COALESCE(a.scanning_amt, 0) AS scanning_amt,
                COALESCE(a.other_amt, 0) AS other_amt,
                COALESCE(a.total_amt, 0) AS total_amt
            FROM base_docs bd
            LEFT JOIN amt a
                ON a.applicationnumber = bd.applicationnumber
            WHERE
                CASE
                    WHEN _amounttype = 0 THEN true
                    WHEN _amounttype = 1 THEN COALESCE(a.total_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 2 THEN COALESCE(a.regfee_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 3 THEN COALESCE(a.stampduty_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 4 THEN COALESCE(a.scanning_amt, 0) BETWEEN _minval AND _maxval
                    WHEN _amounttype = 5 THEN COALESCE(a.other_amt, 0) BETWEEN _minval AND _maxval
                    ELSE true
                END
        ),
        cte AS (
            SELECT
                fd.district,
                fd.officename,
                fd.book,
                fd.part,
                fd.article,
                COUNT(DISTINCT fd.applicationnumber) AS applicationnumber_cnt,
                SUM(fd.stampduty_amt) AS stampduty,
                SUM(fd.regfee_amt) AS registrationfees,
                SUM(fd.scanning_amt) AS scanningfees,
                SUM(fd.other_amt) AS otherfees,
                SUM(fd.total_amt) AS totalfees
            FROM filtered_docs fd
            GROUP BY
                fd.district,
                fd.officename,
                fd.book,
                fd.part,
                fd.article
        ),
        cte_count AS (
            SELECT COUNT(*) AS total_rows
            FROM cte
        )
        SELECT
            cte.district,
            cte.officename AS sroname,
            cte.book AS booktype,
            cte.part,
            cte.article AS articlename,
            cte.applicationnumber_cnt,
            cte.stampduty,
            cte.registrationfees,
            cte.scanningfees,
            cte.otherfees,
            cte.totalfees,
            total_row.total_rows::bigint AS totalcount
        FROM cte
        RIGHT JOIN (SELECT total_rows FROM cte_count) total_row
            ON true
        WHERE total_row.total_rows <> 0;
    END IF;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_dailyrevenue_periodly_bck(_districtcode bigint, _srocode bigint, _regarticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_dailyrevenue_periodly_bck_20260122(bigint, bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_dailyrevenue_periodly_bck_20260122(_districtcode bigint, _srocode bigint, _regarticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, sroname character varying, booktype character varying, part character varying, articlename character varying, applicationnumber_cnt bigint, stampduty numeric, registrationfees numeric, scanningfees numeric, otherfees numeric, totalfees numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$




DECLARE

	PageOffset INTEGER := 0;

BEGIN 
PageOffset := ((pagenumber - 1) * pagesize);
---------

if _amounttype is null then 
 _amounttype:=0;
_minval :=0;
_maxval:=0;

end if;


if (pagenumber<>-1 and pagesize<>-1) then

return query
		with cte as (with a as  
		(select  distinct d.districtnamee as district,
       sro.sronamee as officename, 
       b.booknameenglish  as book,
       b.printablename as part,
       r.articlenamee  as article,
       dm.applicationnumber as applicationnumber
	   from kaveri.documentmaster dm
	   join kaveri.booktypemaster b on dm.bookid=b.bookid 	
	   join kaveri.registrationarticles r on dm.regarticlecode=r.regarticlecode  
	   inner join kaveri.sromaster sro on dm.srocode = sro.srocode
	   inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
	   left join kaveri.feesrequired f on dm.applicationnumber=f.applicationnumber  
       where      dm.isregistrationcompleted=true and  
        (dm.registrationdatetime between _fromdate and  _todate + INTERVAL '1 day')
        and 
        (case

          when _regarticlecode=0 then true
           else 
           dm.regarticlecode=_regarticlecode 

          end)
         
        
        and 
        (case

          when _amounttype=0 then true
          when _amounttype=1 then true                  
          when _amounttype=2 then f.feerulecode=1
          when _amounttype=3 then f.feerulecode in (36,58,59,64)
          when _amounttype=4 then f.feerulecode=2
          when _amounttype=5 then f.feerulecode not in (1,2,36,58,59,64)
           else 
           true

          end)
          
        and (case  when _districtcode<>0 then d.districtcode=_districtcode  ELSE  true end)
		and (case  when _srocode<> 0 then dm.srocode=_srocode  ELSE  true end)
		group by d.districtnamee,sro.sronamee,b.booknameenglish,b.printablename,
		r.articlenamee,
		dm.applicationnumber
       
       having
       (case

          when _amounttype=0 then true
          when _amounttype in (1,2,3,4,5)  then sum(f.amountpaid) >=_minval and sum(f.amountpaid)<=_maxval                
           else 
           true

          end)

	 
	 ) 

    select a.district,a.officename,a.book,a.part,a.article,
	   count( distinct a.applicationnumber) as applicationnumber_cnt,
	   sum(case when rr.feerulecode in (36,58,59,64)  then rr.amountpaid else 0 end)as StampDuty,
	   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end) as RegistrationFees,
	   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)as scanningfee,
	   sum(case when rr.feerulecode not in (1,2,36,58,59,64) and rr.amountpaid>0 then rr.amountpaid else 0 end)as otherfees, 
	   sum(case when  rr.amountpaid>0  then rr.amountpaid else 0 end)as TotalFees 
       from  
        a  
       left join kaveri.feesrequired rr on a.applicationnumber=rr.applicationnumber
       
       group by a.district,a.officename,a.book,a.part,a.article),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true 
			where total_row.total_rows<>0
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
			
elsif (pagenumber=-1 or  pagesize=-1) then 

return query
		with cte as (with a as  
		(select  distinct d.districtnamee as district,
       sro.sronamee as officename, 
       b.booknameenglish  as book,
       b.printablename as part,
       r.articlenamee  as article,
       dm.applicationnumber as applicationnumber
	   from kaveri.documentmaster dm
	   join kaveri.booktypemaster b on dm.bookid=b.bookid 	
	   join kaveri.registrationarticles r on dm.regarticlecode=r.regarticlecode  
	   inner join kaveri.sromaster sro on dm.srocode = sro.srocode
	   inner join kaveri.districtmaster d on sro.districtcode = d.districtcode
	   left join kaveri.feesrequired f on dm.applicationnumber=f.applicationnumber  
       where      dm.isregistrationcompleted=true and  
        (dm.registrationdatetime between _fromdate and  _todate + INTERVAL '1 day')
        and 
        (case

          when _regarticlecode=0 then true
           else 
           dm.regarticlecode=_regarticlecode 

          end)
         
        
        and 
        (case

          when _amounttype=0 then true
          when _amounttype=1 then true                  
          when _amounttype=2 then f.feerulecode=1
          when _amounttype=3 then f.feerulecode in (36,58,59,64)
          when _amounttype=4 then f.feerulecode=2
          when _amounttype=5 then f.feerulecode not in (1,2,36,58,59,64)
           else 
           true

          end)
          
        and (case  when _districtcode<>0 then d.districtcode=_districtcode  ELSE  true end)
		and (case  when _srocode<> 0 then dm.srocode=_srocode  ELSE  true end)
		group by d.districtnamee,sro.sronamee,b.booknameenglish,b.printablename,
		r.articlenamee,
		dm.applicationnumber
       
       having
       (case

          when _amounttype=0 then true
          when _amounttype in (1,2,3,4,5)  then sum(f.amountpaid) >=_minval and sum(f.amountpaid)<=_maxval                
           else 
           true

          end)

	 
	 ) 

    select a.district,a.officename,a.book,a.part,a.article,
	   count( distinct a.applicationnumber) as applicationnumber_cnt,
	   sum(case when rr.feerulecode in (36,58,59,64)  then rr.amountpaid else 0 end)as StampDuty,
	   sum(case when rr.feerulecode=1  then rr.amountpaid else 0 end) as RegistrationFees,
	   sum(case when rr.feerulecode=2  then rr.amountpaid else 0 end)as scanningfee,
	   sum(case when rr.feerulecode not in (1,2,36,58,59,64) and rr.amountpaid>0  then rr.amountpaid else 0 end)as otherfees, 
	   sum(case when  rr.amountpaid>0  then rr.amountpaid else 0 end)as TotalFees 
       from  
        a  
       left  join kaveri.feesrequired rr on a.applicationnumber=rr.applicationnumber 
       
       group by a.district,a.officename,a.book,a.part,a.article),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true 
			where total_row.total_rows<>0;



end if;




	   
	 	
END;

$$;


ALTER FUNCTION kaverimis.fn_mis_dailyrevenue_periodly_bck_20260122(_districtcode bigint, _srocode bigint, _regarticlecode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_deo_transcation_details_statutory(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_deo_transcation_details_statutory(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$

 

DECLARE 
v_data_json json;
v_date date;
PageOffset INTEGER := 0;

BEGIN	 

	pageoffset:=((pagenumber-1) * pagesize);



select row_to_json(data_json) into v_data_json from (


SELECT array_to_json(array_agg(row_to_json(details)))
 
from(
select
d.from_firstname,
d. from_lastname,
  d.to_firstname,
d. to_lastname,
(select s.sronamee from kaveri.sromaster s where s.srocode = d.from_srocode ) as from_sronamee,
d.from_srocode,
(select s.sronamee from kaveri.sromaster s where s.srocode = d.to_srocode ) as to_sronamee,
d.to_srocode,
(select dsg.designame from kaveri.desigmaster dsg where dsg.designationid = d.from_designationid ) as from_designationid,
(select dsg.designame from kaveri.desigmaster dsg where dsg.designationid = d.to_designationid ) as to_designationid,
(select mo.officename from kaveri.mas_officemaster mo  where d.from_officeid = mo.officeid  ) as from_officename,
d.from_officeid,
(select mo.officename  from kaveri.mas_officemaster mo  where d.to_officeid = mo.officeid  ) as to_officename,
d.to_officeid,
(select ds.districtnamee from kaveri.districtmaster ds where ds.districtcode = d.from_districtcode ) as from_districtname,
d.from_districtcode,
(select ds.districtnamee from kaveri.districtmaster ds where ds.districtcode = d.to_districtcode ) as to_districtname,
d.from_districtcode
from kaveri.departmentusers_deo_service_history d
	
where 

(case when _srocode <>0 then (d.from_srocode =_srocode or d.to_srocode = _srocode)

	else true
         end
      )


      
and (case when _districtcode <>0 then (d.from_districtcode =_districtcode or d.to_districtcode = _districtcode)
             
         else true
       end 
      )

 and (case when _fromdate is not null and _todate is not null then d.inserteddate::date between _fromdate

             and _todate
             
     else true
                 end)
                 
  offset pageoffset
fetch next pagesize rows only              

) details



) data_json;

return v_data_json;
	END;
$$;


ALTER FUNCTION kaverimis.fn_mis_deo_transcation_details_statutory(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_details_of_gpa_poa_1a_data(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_details_of_gpa_poa_1a_data(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _gpa_poa integer, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer) RETURNS TABLE(districtcode bigint, srocode bigint, documentcount bigint, stampduty numeric, registrationfee numeric, scanningfees numeric, otherfees numeric, totalfees numeric)
    LANGUAGE plpgsql
    AS $$

Begin

		return query 
		
		with a as (select distinct 
			 dsm.districtcode,a.srocode,a.applicationnumber
			
			from kaveri.documentmaster a 
			JOIN kaveri.applicantapplicationdetails aad ON a.applicationnumber=aad.applicationnumber
			left JOIN kaveri.feesrequired fr ON a.applicationnumber=fr.applicationnumber
			JOIN kaveri.sromaster sm ON a.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
		    join kaveri.propertymaster pm  on a.applicationnumber=pm.applicationnumber 
		    		   
		    		
			where  
			(a.registrationdatetime between _fromdate  and 
			_todate ::timestamp + INTERVAL '1 day')
			and a.isregistrationcompleted = true 
			--and aad.currentstatus='CD120'
			and
			(case

		                    when _gpa_poa=0 then pm.stamparticlecode=43   --poa
		                                    
		                    when _gpa_poa=1 then  pm.stampruleid=345  --gpa
		                                              
		
		                  	 else     false 

                                                

  					end)
			
						
			
			and (case  when _districtcode<>0 then dsm.districtcode=_districtcode  ELSE  true end)
			and (case  when _srocode<> 0 then sm.srocode=_srocode  ELSE  true end)
			group by a.srocode,dsm.districtcode,a.applicationnumber
			),
			b as (
			  
			 select distinct a.districtcode,a.srocode,f.applicationnumber  from 
			 a
			 left join  kaveri.feesrequired f on a.applicationnumber=f.applicationnumber
			 where 
			 (case

		                    when _amounttype=1 then true   --Total
		                                    
		                    when _amounttype=2 then  f.feerulecode in (36,58,59,104,89,88)  --stamp duty
		                    
		                    when _amounttype=3 then  f.feerulecode in  (1)  -- registrationfee
		                    
		                    when _amounttype=4 then  f.feerulecode in  (2)  -- Scanning fees
		                    
		                    when _amounttype=5 then  f.feerulecode  not in  (1,2,36,58,59,104,89,88)  -- Other fees
		                   
		
		                    else     true --amounttype null

                                                

  					 end)
			 
			 group by a.districtcode,a.srocode,f.applicationnumber 
			 having 
				(case
					when _amounttype in (1,2,3,4,5) then sum(f.amountpaid) >= _minval 
					and sum(f.amountpaid) <= _maxval
                                        
                    ELSE          true                                               

                end )
			
			
			)
			
			select 
			b.districtcode::bigint,b.srocode::bigint,count(distinct b.applicationnumber),
			sum(case when f.feerulecode in (36,58,59,104,89,88) then
			f.amountpaid  else 0 end) as stampduty,
			sum(case when f.feerulecode in (1) then	f.amountpaid  else 0 end)
			as registrationfee,
			sum(case when f.feerulecode in (2) then	f.amountpaid  else 0 end)
			as scanningfees,
			sum(case when f.feerulecode not in (1,2,36,58,59,104,89,88)  then	f.amountpaid  else 0 end)
			as otherfees,
			sum(f.amountpaid )
			as Total
			
			
			
			from 
			b 
			left join kaveri.feesrequired f on b.applicationnumber=f.applicationnumber 
			group by b.districtcode,b.srocode;
			

END;
$$;


ALTER FUNCTION kaverimis.fn_mis_details_of_gpa_poa_1a_data(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _gpa_poa integer, _amounttype integer, _minval integer, _maxval integer) OWNER TO postgres;

--
-- Name: fn_mis_details_of_gpa_trust_adaptions_other_letters_regt(integer, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_details_of_gpa_trust_adaptions_other_letters_regt(_srocode integer, _current_fromdate timestamp without time zone, _current_todate timestamp without time zone, _prev_fromdate timestamp without time zone, _prev_todate timestamp without time zone, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer, _choice integer DEFAULT NULL::integer) RETURNS TABLE(drname character varying, nameofsubregistrationoffice character varying, poa_cnt_inthemonth bigint, poa_stampduty_inthemonth numeric, poa_registrationfee_inthemonth numeric, poa_lessthanmonth bigint, poa_stampduty_lessthanmonth numeric, poa_registrationfee_lessthanmonth numeric, gpa_cnt_inthemonth integer, gpa_cnt_lessthanmonth integer, gpa_stampduty_inthemonth numeric, gpa_registrationfee_inthemonth numeric, gpa_stampduty_lessthanmonth numeric, gpa_registrationfee_lessthanmonth numeric, adoption_cnt_inthemonth bigint, adoption_stampduty_inthemonth numeric, adoption_registrationfee_inthemonth numeric, adoption_cnt_lessthanmonth bigint, adoption_stampduty_lessthanmonth numeric, adoption_registrationfee_lessthanmonth numeric, trustdeed_cnt_inthemonth bigint, trustdeed_stampduty_inthemonth numeric, trustdeed_registrationfee_inthemonth numeric, trustdeed_cnt_lessthanmonth bigint, trustdeed_stampduty_lessthanmonth numeric, trustdeed_registrationfee_lessthanmonth numeric, otherdeeds_cnt_inthemonth bigint, otherdeeds_stampduty_inthemonth numeric, otherdeeds_registrationfee_inthemonth numeric, otherdeeds_cnt_lessthanmonth bigint, otherdeeds_stampduty_lessthanmonth numeric, otherdeeds_registrationfee_lessthanmonth numeric, book4_cnt_inthemonth bigint, book4_stampduty_inthemonth numeric, book4_registrationfee_inthemonth numeric, book4_cnt_lessthanmonth bigint, book4_stampduty_lessthanmonth numeric, book4_registrationfee_lessthanmonth numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE

BEGIN	
	
if _choice = 1 then -- Stampduty
return query 
select distinct b.districtnamee as drname,
sronamee as nameofsubregistrationoffice,
poa_inthemonth.poa_cnt_inthemonth,
poa_inthemonth.poa_stampduty_inthemonth,
poa_inthemonth.poa_registrationfee_inthemonth,
poa_lessthanmonth.poa_lessthanmonth,
poa_lessthanmonth.poa_stampduty_lessthanmonth,
poa_lessthanmonth.poa_registrationfee_lessthanmonth,
gpa_inthemonth.gpa_cnt_inthemonth,
gpa_lessthanmonth.gpa_cnt_lessthanmonth,
gpa_inthemonth.gpa_stampduty_inthemonth,
gpa_inthemonth.gpa_registrationfee_inthemonth,
gpa_lessthanmonth.gpa_stampduty_lessthanmonth,
gpa_lessthanmonth.gpa_registrationfee_lessthanmonth,
Adoption_inthemonth.Adoption_cnt_inthemonth,
Adoption_inthemonth.Adoption_stampduty_inthemonth,
Adoption_inthemonth.Adoption_registrationfee_inthemonth,
Adoption_lessthanmonth.Adoption_cnt_lessthanmonth,
Adoption_lessthanmonth.Adoption_stampduty_lessthanmonth,
Adoption_lessthanmonth.Adoption_registrationfee_lessthanmonth,
Trustdeed_inthemonth.Trustdeed_cnt_inthemonth,
Trustdeed_inthemonth.Trustdeed_stampduty_inthemonth,
