--
-- Name: fn_mis_details_of_gpa_trust_adaptions_other_letters_regt_1a(integer, integer, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_details_of_gpa_trust_adaptions_other_letters_regt_1a(_districtcode integer, _srocode integer, _prev_fromdate timestamp without time zone, _prev_todate timestamp without time zone, _current_fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _current_todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer) RETURNS TABLE(drname character varying, nameofsubregistrationoffice character varying, poa_lessthanmonth bigint, poa_stampduty_lessthanmonth numeric, poa_registrae_ltionfeessthanmonth numeric, poa_cnt_inthemonth bigint, poa_stampduty_inthemonth numeric, poa_registrationfee_inthemonth numeric, gpa_cnt_lessthanmonth bigint, gpa_stampduty_lessthanmonth numeric, gpa_registrationfee_lessthanmonth numeric, gpa_cnt_inthemonth bigint, gpa_stampduty_inthemonth numeric, gpa_registrationfee_inthemonth numeric)
    LANGUAGE plpgsql
    AS $$

	DECLARE
    
	BEGIN	
	if(_districtcode=0)then --All district
	   raise notice 'All district';
	
	    if(_amounttype=0)then --No amount type
			
			return query
			select distinct b.districtnamee as drname,
			sronamee as nameofsubregistrationoffice,
			poa_lessthanmonth.poa_lessthanmonth,
			poa_lessthanmonth.poa_stampduty_lessthanmonth,
			poa_lessthanmonth.poa_registrationfee_lessthanmonth,
			poa_inthemonth.poa_cnt_inthemonth,
			poa_inthemonth.poa_stampduty_inthemonth,
			poa_inthemonth.poa_registrationfee_inthemonth,
			gpa_lessthanmonth.gpa_cnt_lessthanmonth,
			gpa_lessthanmonth.gpa_stampduty_lessthanmonth,
			gpa_lessthanmonth.gpa_registrationfee_lessthanmonth,
			gpa_inthemonth.gpa_cnt_inthemonth,
			gpa_inthemonth.gpa_stampduty_inthemonth,
			gpa_inthemonth.gpa_registrationfee_inthemonth

			from kaveri.sromaster a  join kaveri.districtmaster b on a.districtcode = b.districtcode 
						
			left outer join 

			(
			select
			a.srocode,
			count(distinct a.applicationnumber)  as poa_lessthanmonth,
			sum(case when fr.feerulecode in (36,58,59,64) then
			fr.amountpaid  else 0 end) as poa_stampduty_lessthanmonth,
			sum(case when fr.feerulecode in (1,65) then
			fr.amountpaid  else 0 end) as poa_registrationfee_lessthanmonth
			from kaveri.documentmaster a 
			JOIN kaveri.applicantapplicationdetails aad ON a.applicationnumber::text = aad.applicationnumber::text
			JOIN kaveri.feesrequired fr ON a.applicationnumber::text = fr.applicationnumber::text
			JOIN kaveri.sromaster sm ON a.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
		    join (select distinct applicationnumber,stamparticlecode from kaveri.propertymaster where stamparticlecode  = 43) 
		    pm on a.applicationnumber=pm.applicationnumber
		    /*inner join  
			 (select distinct applicationnumber,sum(amountpaid) from  kaveri.feesrequired  where
			 
			 feerulecode=36 group by applicationnumber having sum(amountpaid)>=_minval and sum(amountpaid)<=_maxval)
			 fr1 on a.applicationnumber=fr1.applicationnumber*/
			
			
			where  	a.registrationdatetime::date >= _prev_fromdate and
			a.registrationdatetime::date <= _prev_todate
			and a.isregistrationcompleted = true  
			group by a.srocode,dsm.districtcode
		  having count(distinct a.applicationnumber) > 0)as poa_lessthanmonth on a.srocode = poa_lessthanmonth.srocode
			 
			left outer join 

			(select
			a.srocode,
			count(distinct a.applicationnumber)  as poa_cnt_inthemonth,
			sum(case when fr.feerulecode in (36,58,59,64) then
			fr.amountpaid  else 0 end) as poa_stampduty_inthemonth,
			sum(case when fr.feerulecode in (1,65) then
			fr.amountpaid  else 0 end) as poa_registrationfee_inthemonth
			from kaveri.documentmaster a 
			JOIN kaveri.applicantapplicationdetails aad ON a.applicationnumber::text = aad.applicationnumber::text
			JOIN kaveri.feesrequired fr ON a.applicationnumber::text = fr.applicationnumber::text
			JOIN kaveri.sromaster sm ON a.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
		    join (select distinct applicationnumber,stamparticlecode from kaveri.propertymaster where stamparticlecode  = 43) 
		    pm on a.applicationnumber=pm.applicationnumber
		   /* inner join  
			 (select distinct applicationnumber,sum(amountpaid) from  kaveri.feesrequired  where
			 
			 feerulecode=36 group by applicationnumber having sum(amountpaid)>=_minval and sum(amountpaid)<=_maxval)
			 fr1 on a.applicationnumber=fr1.applicationnumber*/
			
			
			where  	a.registrationdatetime::date >= _current_fromdate and
			a.registrationdatetime::date <= _current_todate
			and a.isregistrationcompleted = true  
			group by a.srocode,dsm.districtcode
		  having count(distinct a.applicationnumber) > 0)as poa_inthemonth on a.srocode = poa_inthemonth.srocode

			left outer join 

