--
-- Name: fn_mis_details_of_gpa_trust_adaptions_other_letters_regt_1a(integer, integer, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_details_of_gpa_trust_adaptions_other_letters_regt_1a(_districtcode integer, _srocode integer, _prev_fromdate timestamp without time zone, _prev_todate timestamp without time zone, _current_fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _current_todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(drname character varying, nameofsubregistrationoffice character varying, gpa_cnt_lessthanmonth bigint, gpa_stampduty_lessthanmonth numeric, gpa_registrationfees_lessthanmonth numeric, gpa_scanningfees_lessthanmonth numeric, gpa_otherfees_lessthanmonth numeric, gpa_totalfees_lessthanmonth numeric, gpa_cnt_inthemonth bigint, gpa_stampduty_inthemonth numeric, gpa_registrationfees_inthemonth numeric, gpa_scanningfees_inthemonth numeric, gpa_otherfees_inthemonth numeric, gpa_totalfees_inthemonth numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

	DECLARE
	PageOffset INTEGER := 0;
    
	BEGIN	
	PageOffset := ((pagenumber - 1) * pagesize);

if (pagenumber=1) then

			return query
			with cte as (select distinct b.districtnamee as drname,
			sronamee as nameofsubregistrationoffice,
			gpa_lessthanmonth.documentcount,
			gpa_lessthanmonth.stampduty,
			gpa_lessthanmonth.registrationfee,
			gpa_lessthanmonth.scanningfees,
			gpa_lessthanmonth.otherfees,
			gpa_lessthanmonth.totalfees,
			gpa_inthemonth.documentcount,
			gpa_inthemonth.stampduty,
			gpa_inthemonth.registrationfee,
			gpa_inthemonth.scanningfees,
			gpa_inthemonth.otherfees,
			gpa_inthemonth.totalfees
			

			from kaveri.sromaster a 
			join kaveri.districtmaster b on a.districtcode = b.districtcode 
						
			left outer join 

			(
				select * from kaverimis.fn_mis_details_of_gpa_poa_1a_data
					(_districtcode ,_srocode ,_prev_fromdate,_prev_todate ,1,_amounttype ,_minval ,_maxval)
				
			)as gpa_lessthanmonth on a.srocode = gpa_lessthanmonth.srocode
			 
			left outer join 

			(select * from kaverimis.fn_mis_details_of_gpa_poa_1a_data
					(_districtcode ,_srocode ,_current_fromdate ,_current_todate,1,_amounttype ,_minval ,_maxval))
					as gpa_inthemonth on a.srocode = gpa_inthemonth.srocode

			
			where gpa_lessthanmonth.documentcount is not null or 
			gpa_inthemonth.documentcount is not null ),
			cte_count as (select count(*) as total_rows from cte)
			select * from cte
			join (select total_rows from cte_count) total_row on true 
			order by cte.drname asc ,cte.nameofsubregistrationoffice asc
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
			
elsif (pagenumber>1) then 
	
				return query
			with cte as (select distinct b.districtnamee as drname,
			sronamee as nameofsubregistrationoffice,
			gpa_lessthanmonth.documentcount,
			gpa_lessthanmonth.stampduty,
			gpa_lessthanmonth.registrationfee,
			gpa_lessthanmonth.scanningfees,
			gpa_lessthanmonth.otherfees,
			gpa_lessthanmonth.totalfees,
			gpa_inthemonth.documentcount,
			gpa_inthemonth.stampduty,
			gpa_inthemonth.registrationfee,
			gpa_inthemonth.scanningfees,
			gpa_inthemonth.otherfees,
			gpa_inthemonth.totalfees
			

			from kaveri.sromaster a 
			join kaveri.districtmaster b on a.districtcode = b.districtcode 
						
			left outer join 

			(
				select * from kaverimis.fn_mis_details_of_gpa_poa_1a_data
					(_districtcode ,_srocode ,_prev_fromdate,_prev_todate ,1,_amounttype ,_minval ,_maxval)
				
			)as gpa_lessthanmonth on a.srocode = gpa_lessthanmonth.srocode
			 
			left outer join 

			(select * from kaverimis.fn_mis_details_of_gpa_poa_1a_data
					(_districtcode ,_srocode ,_current_fromdate ,_current_todate,1,_amounttype ,_minval ,_maxval))
					as gpa_inthemonth on a.srocode = gpa_inthemonth.srocode

			
			where gpa_lessthanmonth.documentcount is not null or 
			gpa_inthemonth.documentcount is not null )
			
			select *,null::bigint as total_row from cte 
			order by cte.drname asc ,cte.nameofsubregistrationoffice asc
			OFFSET PageOffset
			FETCH NEXT pagesize ROWS ONLY	;
			

elsif (pagenumber=-1 or pagesize=-1) then

			return query
			with cte as (select distinct b.districtnamee as drname,
			sronamee as nameofsubregistrationoffice,
			gpa_lessthanmonth.documentcount,
			gpa_lessthanmonth.stampduty,
			gpa_lessthanmonth.registrationfee,
			gpa_lessthanmonth.scanningfees,
			gpa_lessthanmonth.otherfees,
			gpa_lessthanmonth.totalfees,
			gpa_inthemonth.documentcount,
			gpa_inthemonth.stampduty,
			gpa_inthemonth.registrationfee,
			gpa_inthemonth.scanningfees,
			gpa_inthemonth.otherfees,
			gpa_inthemonth.totalfees
			

			from kaveri.sromaster a 
			join kaveri.districtmaster b on a.districtcode = b.districtcode 
						
			left outer join 

			(
				select * from kaverimis.fn_mis_details_of_gpa_poa_1a_data
					(_districtcode ,_srocode ,_prev_fromdate,_prev_todate ,1,_amounttype ,_minval ,_maxval)
				
			)as gpa_lessthanmonth on a.srocode = gpa_lessthanmonth.srocode
			 
			left outer join 

			(select * from kaverimis.fn_mis_details_of_gpa_poa_1a_data
					(_districtcode ,_srocode ,_current_fromdate ,_current_todate,1,_amounttype ,_minval ,_maxval))
					as gpa_inthemonth on a.srocode = gpa_inthemonth.srocode

			
			where gpa_lessthanmonth.documentcount is not null or 
			gpa_inthemonth.documentcount is not null )
			
			select *,null::bigint as total_row from cte
		order by cte.drname asc ,cte.nameofsubregistrationoffice asc;

end if;
	
	
	   
			
			
			
		
			
END;
$$;


