CREATE FUNCTION kaverimis.fn_mis_details_of_gpa_trust_adaptions_other_letters_regt_1a_130(_districtcode integer, _srocode integer, _prev_fromdate timestamp without time zone, _prev_todate timestamp without time zone, _current_fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _current_todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(drname character varying, nameofsubregistrationoffice character varying, poa_lessthanmonth bigint, poa_stampduty_lessthanmonth numeric, poa_registrae_ltionfeessthanmonth numeric, poa_cnt_inthemonth bigint, poa_stampduty_inthemonth numeric, poa_registrationfee_inthemonth numeric, gpa_cnt_lessthanmonth bigint, gpa_stampduty_lessthanmonth numeric, gpa_registrationfee_lessthanmonth numeric, gpa_cnt_inthemonth bigint, gpa_stampduty_inthemonth numeric, gpa_registrationfee_inthemonth numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

	DECLARE
