CREATE FUNCTION kaverimis.fn_mis_details_of_gpa_trust_adaptions_other_letters_regt_2a(_districtcode integer, _srocode integer, _prev_fromdate timestamp without time zone, _prev_todate timestamp without time zone, _current_fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _current_todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(drname character varying, nameofsubregistrationoffice character varying, trust_lessthanmonth bigint, trust_stampduty_lessthanmonth numeric, trust_registrae_ltionfeessthanmonth numeric, trust_cnt_inthemonth bigint, trust_stampduty_inthemonth numeric, trust_registrationfee_inthemonth numeric, adoption_cnt_lessthanmonth bigint, adoption_stampduty_lessthanmonth numeric, adoption_registrationfee_lessthanmonth numeric, adoption_cnt_inthemonth bigint, adoption_stampduty_inthemonth numeric, adoption_registrationfee_inthemonth numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

	DECLARE
	PageOffset INTEGER := 0;
    
	BEGIN	
	PageOffset := ((pagenumber - 1) * pagesize);	
	
	---POA replaced by Trust with stamparticlecode 56
	--gpa  replaced with  Adoption with stamp articlecode 3
		
			return query
			with cte as (select distinct b.districtnamee as drname,
			sronamee as nameofsubregistrationoffice,
			poa_lessthanmonth.noofdocument,
			poa_lessthanmonth.stampduty,
			poa_lessthanmonth.registrationfee,
			poa_inthemonth.noofdocument,
			poa_inthemonth.stampduty,
			poa_inthemonth.registrationfee,
			gpa_lessthanmonth.noofdocument,
			gpa_lessthanmonth.stampduty,
			gpa_lessthanmonth.registrationfee,
			gpa_inthemonth.noofdocument,
			gpa_inthemonth.stampduty,
			gpa_inthemonth.registrationfee

			from kaveri.sromaster a 
			join kaveri.districtmaster b on a.districtcode = b.districtcode 
						
			left join 

			(select * from kaverimis.fn_mis_details_of_gpa_trust_adaptions_other_letters_regt_2a_ch
			(_districtcode ,_srocode ,56,_prev_fromdate,_prev_todate ,_amounttype ,_minval ,_maxval))as poa_lessthanmonth on a.srocode = poa_lessthanmonth.srocode
			 
			left join 

			(select * from kaverimis.fn_mis_details_of_gpa_trust_adaptions_other_letters_regt_2a_ch
			(_districtcode ,_srocode ,56,_current_fromdate,_current_todate ,_amounttype ,_minval ,_maxval))as poa_inthemonth on a.srocode = poa_inthemonth.srocode

			left join 

			(select * from kaverimis.fn_mis_details_of_gpa_trust_adaptions_other_letters_regt_2a_ch
			(_districtcode ,_srocode ,3,_prev_fromdate,_prev_todate ,_amounttype ,_minval ,_maxval))as gpa_lessthanmonth on a.srocode = gpa_lessthanmonth.srocode
			 
			left join 

			(select * from kaverimis.fn_mis_details_of_gpa_trust_adaptions_other_letters_regt_2a_ch
			(_districtcode ,_srocode ,3,_current_fromdate,_current_todate ,_amounttype ,_minval ,_maxval))as gpa_inthemonth on a.srocode = gpa_inthemonth.srocode
			
			where poa_lessthanmonth.noofdocument is not null or 
			poa_inthemonth.noofdocument is not null or 
			gpa_lessthanmonth.noofdocument is not null or 
			gpa_inthemonth.noofdocument is not null),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
END;
$$;


