			where poa_lessthanmonth.poa_lessthanmonth is not null or 
			poa_inthemonth.poa_cnt_inthemonth is not null or 
			gpa_lessthanmonth.gpa_cnt_lessthanmonth is not null or 
			gpa_inthemonth.gpa_cnt_inthemonth is not null),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
			end if;
		
		

			
	end if;
			
END;
$$;


