--
-- Name: fn_mis_details_of_gpa_trust_adaptions_other_letters_regt_2a_ch(integer, integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_details_of_gpa_trust_adaptions_other_letters_regt_2a_ch(_districtcode integer, _srocode integer, _stamparticlecode integer, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer) RETURNS TABLE(districtcode integer, srocode integer, noofdocument bigint, stampduty numeric, registrationfee numeric)
    LANGUAGE plpgsql
    AS $$
begin
return query
with a as (select
	sm.districtcode,			
	a.srocode,a.applicationnumber
	from kaveri.documentmaster a 
	JOIN kaveri.feesrequired fr ON a.applicationnumber::text = fr.applicationnumber::text
	JOIN kaveri.sromaster sm ON a.srocode = sm.srocode
	JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
	join kaveri.stampregrelations s on s.regarticlecode = a.regarticlecode 
	where s.stamparticlecode = _stamparticlecode 
	and a.registrationdatetime::date >= _fromdate and a.registrationdatetime::date <= _todate
	and a.isregistrationcompleted = true and
	
	(case
		when _amounttype=0 then true   --Total
		when _amounttype=2 then fr.feerulecode in (36,58,59,64)  --stamp duty
		when _amounttype=3 then fr.feerulecode in (1,65)  -- registrationfee
		else true --amounttype null
  		end)
  		
	and(case when _districtcode <> 0 then sm.districtcode=_districtcode else true end)
	
	and(case when _srocode<>0 then a.srocode=_srocode else true end)
	
group by sm.districtcode, a.srocode, a.applicationnumber
having (case
			when _amounttype in (2,3) then sum(fr.amountpaid) >= _minval and sum(fr.amountpaid) <= _maxval
            else true
            end))
     select 
			a.districtcode,
			a.srocode,
			count(distinct a.applicationnumber) as noofdocument,
			sum(case when f.feerulecode in (36,58,59,64) then f.amountpaid else 0 end) as stampduty,
			sum(case when f.feerulecode in (1,65) then	f.amountpaid  else 0 end) as registrationfee
			from 
			a 
			join kaveri.feesrequired f on a.applicationnumber=f.applicationnumber 
			group by a.districtcode,a.srocode;
END;
$$;


