			 fr1 on a.applicationnumber=fr1.applicationnumber
			
			
			where  	a.registrationdatetime::date >=_prev_fromdate and
			a.registrationdatetime::date <= _prev_todate
			and a.isregistrationcompleted = true  
			and a.bookid=4   group by a.srocode,dsm.districtcode
		  having count(distinct a.applicationnumber) > 0)as gpa_lessthanmonth on a.srocode = gpa_lessthanmonth.srocode
			 
			left outer join 

			(select
			a.srocode,
