			from kaveri.documentmaster a 
			JOIN kaveri.applicantapplicationdetails aad ON a.applicationnumber::text = aad.applicationnumber::text
			JOIN kaveri.feesrequired fr ON a.applicationnumber::text = fr.applicationnumber::text
			JOIN kaveri.sromaster sm ON a.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
		    join (select distinct applicationnumber,stamparticlecode from kaveri.propertymaster pm  ) 
		    pm on a.applicationnumber=pm.applicationnumber
		   inner join  
			 (select applicationnumber,sum(amountpaid) from  kaveri.feesrequired  where
			 
			 feerulecode in (1) group by applicationnumber having sum(amountpaid)>=_minval and sum(amountpaid)<=_maxval)
			 fr1 on a.applicationnumber=fr1.applicationnumber
			
			
			where  	a.registrationdatetime::date >= _current_fromdate and
			a.registrationdatetime::date <= _current_todate
			and a.isregistrationcompleted = true  
			and a.bookid=4   group by a.srocode,dsm.districtcode
		  having count(distinct a.applicationnumber) > 0)as gpa_inthemonth on a.srocode = gpa_inthemonth.srocode
			where poa_lessthanmonth.poa_lessthanmonth is not null or 
			poa_inthemonth.poa_cnt_inthemonth is not null or 
