CREATE FUNCTION kaverimis.fn_mis_details_of_gpa_trust_adaptions_other_letters_regt_2b(_districtcode integer, _srocode integer, _prev_fromdate timestamp without time zone, _prev_todate timestamp without time zone, _current_fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _current_todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(drname character varying, nameofsubregistrationoffice character varying, otherdeed_lessthanmonth bigint, otherdeed_stampduty_lessthanmonth numeric, otherdeed_registrae_ltionfeessthanmonth numeric, otherdeed_cnt_inthemonth bigint, otherdeed_stampduty_inthemonth numeric, otherdeed_registrationfee_inthemonth numeric, book4_cnt_lessthanmonth bigint, book4_stampduty_lessthanmonth numeric, book4_registrationfee_lessthanmonth numeric, book4_cnt_inthemonth bigint, book4_stampduty_inthemonth numeric, book4_registrationfee_inthemonth numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$



DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
	
	
  


		return query
			with cte as (select distinct b.districtnamee as drname,
			sronamee as nameofsubregistrationoffice,
			poa_lessthanmonth.documentcount,
			poa_lessthanmonth.stampduty,
			poa_lessthanmonth.registrationfee,
			poa_inthemonth.documentcount,
			poa_inthemonth.stampduty,
			poa_inthemonth.registrationfee,
			gpa_lessthanmonth.documentcount,
			gpa_lessthanmonth.stampduty,
			gpa_lessthanmonth.registrationfee,
			gpa_inthemonth.documentcount,
			gpa_inthemonth.stampduty,
			gpa_inthemonth.registrationfee

			from kaveri.sromaster a  join kaveri.districtmaster b on a.districtcode = b.districtcode 
						
			left outer join 

			(
			
					select * from kaverimis.fn_mis_get_data_otherdeed_form2b
					(_districtcode ,_srocode ,_prev_fromdate,_prev_todate ,_amounttype ,_minval ,_maxval)
			
			)as poa_lessthanmonth on a.srocode = poa_lessthanmonth.srocode
			 
			left outer join 

			(
					select * from kaverimis.fn_mis_get_data_otherdeed_form2b
					(_districtcode ,_srocode ,_current_fromdate ,_current_todate,_amounttype ,
					_minval ,_maxval)
			)
			as poa_inthemonth on a.srocode = poa_inthemonth.srocode

			left outer join 

			(
					select * from kaverimis.fn_mis_get_book4_form2b
					(_districtcode ,_srocode ,_prev_fromdate,_prev_todate ,_amounttype ,_minval ,_maxval)
					
			)as 
		  gpa_lessthanmonth on a.srocode = gpa_lessthanmonth.srocode
			 
			left outer join 

			(
					select * from kaverimis.fn_mis_get_book4_form2b
					(_districtcode ,_srocode ,_current_fromdate ,_current_todate,_amounttype ,
					_minval ,_maxval)
			
			)as gpa_inthemonth on a.srocode = gpa_inthemonth.srocode
			
			where poa_lessthanmonth.documentcount is not null or 
			poa_inthemonth.documentcount is not null or 
			gpa_lessthanmonth.documentcount is not null or 
			gpa_inthemonth.documentcount is not null),
			cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true 
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
			
			
			
END;
$$;


