--
-- Name: fn_mis_details_of_payment_report(integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_details_of_payment_report(_srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, officename character varying, documentnumber integer, registrationdate timestamp without time zone, modeofpayment character varying, paymentdate timestamp without time zone, totalamount bigint, status character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
return query 
select distinct 
a.districtnamee as districtname,
b.sronamee as officename,
c.documentnumber,
c.registrationdatetime as registrationdate,
h.descriptionenglish as modeofpayment,
f.transactiondatetime as paymentdate,
f.totalamount,
statusdescription as status
from kaveri.districtmaster a left join kaveri.sromaster b on a.districtcode = b.districtcode
left join kaveri.documentmaster c on b.srocode = c.srocode
left join kaveri.referencemaster d on c.documentid = d.documentid
left join kaveri.servicesmaster e on d.documenttypeid = e.serviceid
left join kaveri.ams_reg_epaymenttransdetails f on c.srocode = f.officeid
left join kaveri.receiptpaymentdetails g on c.srocode = g.srocode
left join kaveri.paymentmodemaster h on g.paymentmodeid = h.paymentmodeid
where b.srocode = _srocode and 
c.registrationdatetime > _fromdate and c.registrationdatetime <= _todate
and f.transactiondatetime is not null;
END;
$$;


