--
-- Name: fn_mis_details_of_poa_trust_adaptions_other_letters_regt_1a(integer, integer, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_details_of_poa_trust_adaptions_other_letters_regt_1a(_districtcode integer, _srocode integer, _prev_fromdate timestamp without time zone, _prev_todate timestamp without time zone, _current_fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _current_todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(drname character varying, nameofsubregistrationoffice character varying, poa_cnt_lessthanmonth bigint, poa_stampduty_lessthanmonth numeric, poa_registrationfees_lessthanmonth numeric, poa_scanningfees_lessthanmonth numeric, poa_otherfees_lessthanmonth numeric, poa_totalfees_lessthanmonth numeric, poa_cnt_inthemonth bigint, poa_stampduty_inthemonth numeric, poa_registrationfees_inthemonth numeric, poa_scanningfees_inthemonth numeric, poa_otherfees_inthemonth numeric, poa_totalfees_inthemonth numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

	DECLARE
	PageOffset INTEGER := 0;
    
	BEGIN	
	PageOffset := ((pagenumber - 1) * pagesize);

if (pagenumber=1) then

			return query
			with cte as (select distinct b.districtnamee as drname,
			sronamee as nameofsubregistrationoffice,
			poa_lessthanmonth.documentcount,
			poa_lessthanmonth.stampduty,
			poa_lessthanmonth.registrationfee,
			poa_lessthanmonth.scanningfees,
			poa_lessthanmonth.otherfees,
			poa_lessthanmonth.totalfees,
			poa_inthemonth.documentcount,
			poa_inthemonth.stampduty,
			poa_inthemonth.registrationfee,
			poa_inthemonth.scanningfees,
			poa_inthemonth.otherfees,
			poa_inthemonth.totalfees
			

			from kaveri.sromaster a 
			join kaveri.districtmaster b on a.districtcode = b.districtcode 
						
			left outer join 

			(
				select * from kaverimis.fn_mis_details_of_gpa_poa_1a_data
					(_districtcode ,_srocode ,_prev_fromdate,_prev_todate ,0,_amounttype ,_minval ,_maxval)
				
			)as poa_lessthanmonth on a.srocode = poa_lessthanmonth.srocode
			 
			left outer join 

			(select * from kaverimis.fn_mis_details_of_gpa_poa_1a_data
					(_districtcode ,_srocode ,_current_fromdate ,_current_todate,0,_amounttype ,_minval ,_maxval))
					as poa_inthemonth on a.srocode = poa_inthemonth.srocode

			
			where poa_lessthanmonth.documentcount is not null or 
			poa_inthemonth.documentcount is not null ),
			cte_count as (select count(*) as total_rows from cte)
			select * from cte
			join (select total_rows from cte_count) total_row on true 
			order by cte.drname asc,cte.nameofsubregistrationoffice asc
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
			
elsif (pagenumber>1) then 
	
				return query
			with cte as (select distinct b.districtnamee as drname,
			sronamee as nameofsubregistrationoffice,
			poa_lessthanmonth.documentcount,
			poa_lessthanmonth.stampduty,
			poa_lessthanmonth.registrationfee,
			poa_lessthanmonth.scanningfees,
			poa_lessthanmonth.otherfees,
			poa_lessthanmonth.totalfees,
			poa_inthemonth.documentcount,
			poa_inthemonth.stampduty,
			poa_inthemonth.registrationfee,
			poa_inthemonth.scanningfees,
			poa_inthemonth.otherfees,
			poa_inthemonth.totalfees
			

			from kaveri.sromaster a 
			join kaveri.districtmaster b on a.districtcode = b.districtcode 
						
			left outer join 

			(
				select * from kaverimis.fn_mis_details_of_gpa_poa_1a_data
					(_districtcode ,_srocode ,_prev_fromdate,_prev_todate ,0,_amounttype ,_minval ,_maxval)
				
			)as poa_lessthanmonth on a.srocode = poa_lessthanmonth.srocode
			 
			left outer join 

			(select * from kaverimis.fn_mis_details_of_gpa_poa_1a_data
					(_districtcode ,_srocode ,_current_fromdate ,_current_todate,0,_amounttype ,_minval ,_maxval))
					as poa_inthemonth on a.srocode = poa_inthemonth.srocode

			
			where poa_lessthanmonth.documentcount is not null or 
			poa_inthemonth.documentcount is not null )
			
			select *,null::bigint as total_row from cte
			order by cte.drname asc,cte.nameofsubregistrationoffice asc
			OFFSET PageOffset
			FETCH NEXT pagesize ROWS ONLY	;
			

elsif (pagenumber=-1 or pagesize=-1) then

			return query
			with cte as (select distinct b.districtnamee as drname,
			sronamee as nameofsubregistrationoffice,
			poa_lessthanmonth.documentcount,
			poa_lessthanmonth.stampduty,
			poa_lessthanmonth.registrationfee,
			poa_lessthanmonth.scanningfees,
			poa_lessthanmonth.otherfees,
			poa_lessthanmonth.totalfees,
			poa_inthemonth.documentcount,
			poa_inthemonth.stampduty,
			poa_inthemonth.registrationfee,
			poa_inthemonth.scanningfees,
			poa_inthemonth.otherfees,
			poa_inthemonth.totalfees
			

			from kaveri.sromaster a 
			join kaveri.districtmaster b on a.districtcode = b.districtcode 
						
			left outer join 

			(
				select * from kaverimis.fn_mis_details_of_gpa_poa_1a_data
					(_districtcode ,_srocode ,_prev_fromdate,_prev_todate ,0,_amounttype ,_minval ,_maxval)
				
			)as poa_lessthanmonth on a.srocode = poa_lessthanmonth.srocode
			 
			left outer join 

			(select * from kaverimis.fn_mis_details_of_gpa_poa_1a_data
					(_districtcode ,_srocode ,_current_fromdate ,_current_todate,0,_amounttype ,_minval ,_maxval))
					as poa_inthemonth on a.srocode = poa_inthemonth.srocode

			
			where poa_lessthanmonth.documentcount is not null or 
			poa_inthemonth.documentcount is not null )
			
			select *,null::bigint as total_row from cte 
		 order by cte.drname asc,cte.nameofsubregistrationoffice asc;

end if;
	
	
	   
			
			
			
		
			
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_details_of_poa_trust_adaptions_other_letters_regt_1a(_districtcode integer, _srocode integer, _prev_fromdate timestamp without time zone, _prev_todate timestamp without time zone, _current_fromdate timestamp without time zone, _current_todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_details_of_stamp_and_reg_fee_collected(integer, timestamp without time zone, timestamp without time zone, numeric, numeric, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_details_of_stamp_and_reg_fee_collected(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer, _choice integer DEFAULT NULL::integer) RETURNS TABLE(sroofficename character varying, book1 numeric, book3 numeric, book4 numeric, total numeric, stampduty_cash numeric, stampduty_challan numeric, stampduty_dd numeric, stampduty_epayment numeric, totalstampduty numeric, registrationfee_cash numeric, registrationfee_challan numeric, registrationfee_dd numeric, registrationfee_epayment numeric, totalregistrationfee numeric, scanningfee numeric, grandtotal numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN	
if _choice = 1 then -- stamp duty
	return query 
select distinct sroname as sroofficename,
case when booktype = 'Book-1' then
sum(bookcount) else 0 end as book1,
case when booktype = 'Book-3' then
sum(bookcount) else 0 end as book3,
case when booktype = 'Book-4' then
sum(bookcount) else 0 end as book4,
(case when booktype = 'Book-1' then
sum(bookcount) else 0 end +
case when booktype = 'Book-3' then
sum(bookcount) else 0 end +
case when booktype = 'Book-4' then
sum(bookcount) else 0 end
) Total,
case when a.feerulecode = 36 and c.paymentmodeid = 1 then
sum(amount) else 0 end as stampduty_cash,
case when a.feerulecode = 36 and c.paymentmodeid = 2 then
sum(amount) else 0 end as stampduty_challan,
case when a.feerulecode = 36 and c.paymentmodeid = 3 then
sum(amount) else 0 end as stampduty_dd,
case when a.feerulecode = 36 and c.paymentmodeid = 4 then
sum(amount) else 0 end as stampduty_epayment,
(case when a.feerulecode = 36 and c.paymentmodeid = 1 then
sum(amount) else 0 end +
case when a.feerulecode = 36 and c.paymentmodeid = 2 then
sum(amount) else 0 end +
case when a.feerulecode = 36 and c.paymentmodeid = 3 then
sum(amount) else 0 end +
case when a.feerulecode = 36 and c.paymentmodeid = 4 then
sum(amount) else 0 end) Total_stampduty,
case when a.feerulecode = 1 and c.paymentmodeid = 1 then
sum(amount) else 0 end as registrationfee_cash,
case when a.feerulecode = 1 and c.paymentmodeid = 2 then
sum(amount) else 0 end as registrationfee_challan,
case when a.feerulecode = 1 and c.paymentmodeid = 3 then
sum(amount) else 0 end as registrationfee_dd,
case when a.feerulecode = 1 and c.paymentmodeid = 4 then
sum(amount) else 0 end as registrationfee_epayment,
(case when a.feerulecode = 1 and c.paymentmodeid = 1 then
sum(amount) else 0 end +
case when a.feerulecode = 1 and c.paymentmodeid = 2 then
sum(amount) else 0 end +
case when a.feerulecode = 1 and c.paymentmodeid = 3 then
sum(amount) else 0 end +
case when a.feerulecode = 1 and c.paymentmodeid = 4 then
sum(amount) else 0 end ) Total_registrationfee,
case when a.feerulecode = 2 and c.paymentmodeid = 4 then
sum(amount) else 0 end as scanningfee,
((case when a.feerulecode = 36 and c.paymentmodeid = 1 then
sum(amount) else 0 end +
case when a.feerulecode = 36 and c.paymentmodeid = 2 then
sum(amount) else 0 end +
case when a.feerulecode = 36 and c.paymentmodeid = 3 then
sum(amount) else 0 end +
case when a.feerulecode = 36 and c.paymentmodeid = 4 then
sum(amount) else 0 end) +
(case when a.feerulecode = 1 and c.paymentmodeid = 1 then
sum(amount) else 0 end +
case when a.feerulecode = 1 and c.paymentmodeid = 2 then
sum(amount) else 0 end +
case when a.feerulecode = 1 and c.paymentmodeid = 3 then
sum(amount) else 0 end +
case when a.feerulecode = 1 and c.paymentmodeid = 4 then
sum(amount) else 0 end ) +
case when a.feerulecode = 2 and c.paymentmodeid = 4 then
sum(amount) else 0 end ) as grandtotal
from --kaverimis.vw_mis_revenue_report a
kaverimis.vw_mis_revenue_report a inner join  
 (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_srocode
     and amountpaid >=_minval and amountpaid<=_maxval and feerulecode=36)
     vw1 on a.applicationnumber=vw1.applicationnumber
join kaveri.ams_reg_epaymenttransdetails b on a.feerulecode = b.feerulecode
join kaveri.receiptpaymentdetails c on b.receiptid = c.receiptid
where registrationdatetime::date>=_from_date and registrationdatetime<=_to_date and a.srocode=_srocode and applicationtypeid=1
 group by 
 SROName,booktype,a.feerulecode,c.paymentmodeid;
 elsif  _choice = 2 then -- Registration fee
	return query 
select distinct sroname as sroofficename,
case when booktype = 'Book-1' then
sum(bookcount) else 0 end as book1,
case when booktype = 'Book-3' then
sum(bookcount) else 0 end as book3,
case when booktype = 'Book-4' then
sum(bookcount) else 0 end as book4,
(case when booktype = 'Book-1' then
sum(bookcount) else 0 end +
case when booktype = 'Book-3' then
sum(bookcount) else 0 end +
case when booktype = 'Book-4' then
sum(bookcount) else 0 end
) Total,
case when a.feerulecode = 36 and c.paymentmodeid = 1 then
sum(amount) else 0 end as stampduty_cash,
case when a.feerulecode = 36 and c.paymentmodeid = 2 then
sum(amount) else 0 end as stampduty_challan,
case when a.feerulecode = 36 and c.paymentmodeid = 3 then
sum(amount) else 0 end as stampduty_dd,
case when a.feerulecode = 36 and c.paymentmodeid = 4 then
sum(amount) else 0 end as stampduty_epayment,
(case when a.feerulecode = 36 and c.paymentmodeid = 1 then
sum(amount) else 0 end +
case when a.feerulecode = 36 and c.paymentmodeid = 2 then
sum(amount) else 0 end +
case when a.feerulecode = 36 and c.paymentmodeid = 3 then
sum(amount) else 0 end +
case when a.feerulecode = 36 and c.paymentmodeid = 4 then
sum(amount) else 0 end) Total_stampduty,
case when a.feerulecode = 1 and c.paymentmodeid = 1 then
sum(amount) else 0 end as registrationfee_cash,
case when a.feerulecode = 1 and c.paymentmodeid = 2 then
sum(amount) else 0 end as registrationfee_challan,
case when a.feerulecode = 1 and c.paymentmodeid = 3 then
sum(amount) else 0 end as registrationfee_dd,
case when a.feerulecode = 1 and c.paymentmodeid = 4 then
sum(amount) else 0 end as registrationfee_epayment,
(case when a.feerulecode = 1 and c.paymentmodeid = 1 then
sum(amount) else 0 end +
case when a.feerulecode = 1 and c.paymentmodeid = 2 then
sum(amount) else 0 end +
case when a.feerulecode = 1 and c.paymentmodeid = 3 then
sum(amount) else 0 end +
case when a.feerulecode = 1 and c.paymentmodeid = 4 then
sum(amount) else 0 end ) Total_registrationfee,
case when a.feerulecode = 2 and c.paymentmodeid = 4 then
sum(amount) else 0 end as scanningfee,
((case when a.feerulecode = 36 and c.paymentmodeid = 1 then
sum(amount) else 0 end +
case when a.feerulecode = 36 and c.paymentmodeid = 2 then
sum(amount) else 0 end +
case when a.feerulecode = 36 and c.paymentmodeid = 3 then
sum(amount) else 0 end +
case when a.feerulecode = 36 and c.paymentmodeid = 4 then
sum(amount) else 0 end) +
(case when a.feerulecode = 1 and c.paymentmodeid = 1 then
sum(amount) else 0 end +
case when a.feerulecode = 1 and c.paymentmodeid = 2 then
sum(amount) else 0 end +
case when a.feerulecode = 1 and c.paymentmodeid = 3 then
sum(amount) else 0 end +
case when a.feerulecode = 1 and c.paymentmodeid = 4 then
sum(amount) else 0 end ) +
case when a.feerulecode = 2 and c.paymentmodeid = 4 then
sum(amount) else 0 end ) as grandtotal
from --kaverimis.vw_mis_revenue_report a
kaverimis.vw_mis_revenue_report a inner join  
 (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_srocode
