--
-- Name: fn_mis_detailsofmarriages_registered(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_detailsofmarriages_registered(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(nameofthesubregistrationoffice character varying, marriagetype character varying, before_fin_year_hindumarriage bigint, before_fin_year_fees_hindu bigint, before_fin_year_specialmarriage bigint, before_fin_year_fees_specialmarriage bigint, before_fin_year_specialmarriageotherforms bigint, before_fin_year_fees_specialmarriageotherforms bigint, reporting_month_hindumarriage bigint, reporting_month_fees_hindumarriage bigint, reporting_month_specialmarriage bigint, reporting_month_fees_specialmarriage bigint, reporting_month_specialmarriageotherforms bigint, reporting_month_fees_specialmarriageotherforms bigint, numberofdocuments bigint, fees bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
	return query 
select distinct b.sronamee as Nameofthesubregistrationoffice,
c.marriagetype,
COALESCE(before2022_23.Hindumarriage,0) as before_fin_year_Hindumarriage,COALESCE(before2022_23.Fees_Hindu,0) as before_fin_year_Fees_Hindu,
COALESCE(before2022_23.SpecialMarriage,0) as before_fin_year_SpecialMarriage,COALESCE(before2022_23.fees_specialmarriage,0) as before_fin_year_fees_specialmarriage,
COALESCE(before2022_23.SpecialMarriageotherforms,0) as before_fin_year_SpecialMarriageotherforms,COALESCE(before2022_23.fees_specialmarriageotherforms,0) as before_fin_year_fees_specialmarriageotherforms,
case when a.marriagetypeid = 1 then count(a.registrationid) else 0 end as reporting_month_Hindumarriage,
case when a.marriagetypeid = 1 then sum(feesreceived)  else 0 end as reporting_month_Fees,
case when a.marriagetypeid = 2 then count(a.registrationid) else 0 end as reporting_month_SpecialMarriage,
case when a.marriagetypeid = 2 then sum(feesreceived) else 0 end as reporting_month_fees,
case when a.marriagetypeid = 3 then count(a.registrationid) else 0 end as reporting_month_SpecialMarriageotherforms,
case when a.marriagetypeid = 3 then sum(feesreceived) else 0 end as reporting_month_fees,
(COALESCE(before2022_23.Hindumarriage,0)+COALESCE(before2022_23.SpecialMarriage,0)+COALESCE(before2022_23.SpecialMarriageotherforms,0)+
case when a.marriagetypeid = 1 then COALESCE(count(a.registrationid),0) else 0 end+
case when a.marriagetypeid = 2 then COALESCE(count(a.registrationid),0) else 0 end+
case when a.marriagetypeid = 3 then COALESCE(count(a.registrationid),0) else 0 end) as Numberofdocuments,
(COALESCE(before2022_23.Fees_Hindu,0)+COALESCE(before2022_23.fees_specialmarriage,0)+
 COALESCE(before2022_23.fees_specialmarriageotherforms,0)
+case when a.marriagetypeid = 1 then COALESCE(sum(feesreceived),0) else 0 end 
+case when a.marriagetypeid = 2 then COALESCE(sum(feesreceived),0) else 0 end
+case when a.marriagetypeid = 3 then COALESCE(sum(feesreceived),0) else 0 end) as Fee
from kaveri.marriageregistration a left join kaveri.sromaster b on a.srocode = b.srocode
left join kaveri.marriagetype c on a.marriagetypeid = c.marriagetypeid
left join kaveri.districtmaster d on b.districtcode = d.districtcode
left join (
select a.srocode,case when a.marriagetypeid = 1 then COALESCE(count(a.registrationid),0) else 0 end as Hindumarriage,
case when a.marriagetypeid = 1 then COALESCE(sum(feesreceived),0) else 0 end as Fees_Hindu,
case when a.marriagetypeid = 2 then COALESCE(count(a.registrationid),0) else 0 end as SpecialMarriage,
case when a.marriagetypeid = 2 then COALESCE(sum(feesreceived),0) else 0 end as fees_specialmarriage,
case when a.marriagetypeid = 3 then COALESCE(count(a.registrationid),0) else 0 end as SpecialMarriageotherforms,
case when a.marriagetypeid = 3 then COALESCE(sum(feesreceived),0) else 0 end as fees_specialmarriageotherforms
from kaveri.marriageregistration a left join kaveri.sromaster b on a.srocode = b.srocode
left join kaveri.marriagetype c on a.marriagetypeid = c.marriagetypeid
left join kaveri.districtmaster d on b.districtcode = d.districtcode
where d.districtcode = _districtcode  and a.srocode = _srocode and a.dateofmarriage < _from_date
group by a.srocode,a.marriagetypeid
) as before2022_23 on  before2022_23.srocode = a.srocode
where d.districtcode = _districtcode  and a.srocode = _srocode and dateofmarriage >= _from_date and 
dateofmarriage <= _to_date
group by b.sronamee,a.marriagetypeid,c.marriagetype,
before2022_23.Hindumarriage,before2022_23.Fees_Hindu,
before2022_23.SpecialMarriage,before2022_23.fees_specialmarriage,
before2022_23.SpecialMarriageotherforms,before2022_23.fees_specialmarriageotherforms;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_detailsofmarriages_registered(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_documents_registered_within_family_outof_family(integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_documents_registered_within_family_outof_family(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(sroofficename character varying, totalnumberofdocsregistered_settlementdeed bigint, noofdocsregwithinthefamilymembers_settlementdeed bigint, noofdocsregoutofthefamilymembers_settlementdeed bigint, totalnumberofdocsregistered_giftdeed bigint, noofdocsregwithinthefamilymembers_giftdeed bigint, noofdocsregoutofthefamilymembers_giftdeed bigint, totalnumberofdocsregistered_deedofrelease bigint, noofdocsregwithinthefamilymembers_deedofrelease bigint, noofdocsregoutofthefamilymembers_deedofrelease bigint, totalnumberofdocsregistered_leasedeed bigint, noofdocsregwithinthefamilymembers_leasedeed bigint, noofdocsregoutofthefamilymembers_leasedeed bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
	return query 
select distinct sronamee as sroofficename,
case when b.stamparticlecode = 50 then
count(a.documentid) else 0 end as totalnumberofdocsregistered_settlementdeed,
case when b.stamparticlecode = 50 and descriptione like '%family%' then
count(a.documentid) else 0 end as Noofdocsregwithinthefamilymembers_settlementdeed,
(case when b.stamparticlecode = 50 then
count(a.documentid) else 0 end) -
(case when b.stamparticlecode = 50 and descriptione like '%family%' then
count(a.documentid) else 0 end) NoofdocsregOutoftheFamilymembers_settlementdeed,
case when b.stamparticlecode = 85 then
count(a.documentid) else 0 end as totalnumberofdocsregistered_Giftdeed,
case when b.stamparticlecode = 85 and descriptione like '%family%' then
count(a.documentid) else 0 end as Noofdocsregwithinthefamilymembers_Giftdeed,
(case when b.stamparticlecode = 85 then
count(a.documentid) else 0 end) -
(case when b.stamparticlecode = 85 and descriptione like '%family%' then
count(a.documentid) else 0 end) NoofdocsregOutoftheFamilymembers_Giftdeed,
case when b.stamparticlecode = 47 then
count(a.documentid) else 0 end as totalnumberofdocsregistered_deedofRelease,
case when b.stamparticlecode = 47 and descriptione like '%family%' then
count(a.documentid) else 0 end as Noofdocsregwithinthefamilymembers_deedofRelease,
(case when b.stamparticlecode = 47 then
count(a.documentid) else 0 end -
case when b.stamparticlecode = 47 and descriptione like '%family%' then
count(a.documentid) else 0 end) NoofdocsregOutoftheFamilymembers_deedofRelease,
case when b.stamparticlecode = 31  then
count(a.documentid) else 0 end as totalnumberofdocsregistered_leasedeed,
case when b.stamparticlecode = 31 and descriptione like '%family%' then
count(a.documentid) else 0 end as Noofdocsregwithinthefamilymembers_leasedeed,
(case when b.stamparticlecode = 31 then
count(a.documentid) else 0 end -
case when b.stamparticlecode = 31 and descriptione like '%family%' then
count(a.documentid) else 0 end) NoofdocsregOutoftheFamilymembers_leasedeed
from kaveri.propertymaster a left join kaveri.stamprules b on a.stampruleid = b.stampruleid
left join kaveri.documentmaster c on a.documentid = c.documentid
left join kaveri.sromaster d on a.srocode = d.srocode
where a.srocode = _srocode and c.registrationdatetime >= _from_date and c.registrationdatetime <= _to_date
group by a.srocode,sronamee,b.stamparticlecode,descriptione,c.registrationdatetime
having count(a.documentid) > 0;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_documents_registered_within_family_outof_family(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_documents_registered_within_family_outof_family_30(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_documents_registered_within_family_outof_family_30(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(droofficename character varying, sroofficename character varying, totalnumberofdocsregistered_settlementdeed bigint, noofdocsregwithinthefamilymembers_settlementdeed bigint, noofdocsregoutofthefamilymembers_settlementdeed bigint, totalnumberofdocsregistered_giftdeed bigint, noofdocsregwithinthefamilymembers_giftdeed bigint, noofdocsregoutofthefamilymembers_giftdeed bigint, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if _districtcode = 0 then
		return query 
		with cte as (select d.districtnamee,
			s.sronamee as sroofficename,
			count(distinct case when p.stamparticlecode = 50 then
			c.documentid  else null end) as totalnumberofdocsregistered_settlementdeed,
			count(distinct case when p.stamparticlecode = 50 and p.stampruleid = 150 then
			c.documentid  else null end) as Noofdocsregwithinthefamilymembers_settlementdeed,
			count(distinct case when p.stamparticlecode = 50 and p.stampruleid != 150 then
			c.documentid  else null end) NoofdocsregOutoftheFamilymembers_settlementdeed,
			count(distinct case when p.stamparticlecode = 29 then
			c.documentid  else null end) as totalnumberofdocsregistered_Giftdeed,
			count(distinct case when p.stamparticlecode = 29 and p.stampruleid in (403,73,360,361) then
			c.documentid  else null end )as Noofdocsregwithinthefamilymembers_Giftdeed,
			count(distinct case when p.stamparticlecode = 29 and p.stampruleid not in (403,73,360,361) then
			c.documentid  else null end) as  NoofdocsregOutoftheFamilymembers_Giftdeed

			from kaveri.documentmaster c 
			join kaveri.propertymaster p on p.applicationnumber = c.applicationnumber
			join kaveri.sromaster s on c.srocode = s.srocode
			join kaveri.districtmaster d on d.districtcode = s.districtcode 
			where 
			c.srocode<>0 and  
			--and d.districtcode = _districtcode
			c.registrationdatetime::date >=_from_date  and c.registrationdatetime::date<=_to_date 
			group by s.sronamee,d.districtnamee
			having count(distinct case when p.stamparticlecode in (50,29) then c.documentid  else null end ) > 0),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

			elsif _srocode = 0 then
			return query
			
			with cte as (select d.districtnamee,
			s.sronamee as sroofficename,
			count(distinct case when p.stamparticlecode = 50 then
			c.documentid  else null end) as totalnumberofdocsregistered_settlementdeed,
			count(distinct case when p.stamparticlecode = 50 and p.stampruleid = 150 then
			c.documentid  else null end) as Noofdocsregwithinthefamilymembers_settlementdeed,
			count(distinct case when p.stamparticlecode = 50 and p.stampruleid != 150 then
			c.documentid  else null end) NoofdocsregOutoftheFamilymembers_settlementdeed,
			count(distinct case when p.stamparticlecode = 29 then
			c.documentid  else null end) as totalnumberofdocsregistered_Giftdeed,
			count(distinct case when p.stamparticlecode = 29 and p.stampruleid in (403,73,360,361) then
			c.documentid  else null end )as Noofdocsregwithinthefamilymembers_Giftdeed,
			count(distinct case when p.stamparticlecode = 29 and p.stampruleid not in (403,73,360,361) then
			c.documentid  else null end) as  NoofdocsregOutoftheFamilymembers_Giftdeed

			from kaveri.documentmaster c 
			join kaveri.propertymaster p on p.applicationnumber = c.applicationnumber
			join kaveri.sromaster s on c.srocode = s.srocode
			join kaveri.districtmaster d on d.districtcode = s.districtcode 
			where 
			c.srocode<>0   
			and d.districtcode = _districtcode and 
			c.registrationdatetime::date >=_from_date  and c.registrationdatetime::date<=_to_date 
			group by s.sronamee,d.districtnamee
			having count(distinct case when p.stamparticlecode in (50,29) then c.documentid  else null end ) > 0),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

	else

		return query
			
			with cte as (select d.districtnamee,
			s.sronamee as sroofficename,
			count(distinct case when p.stamparticlecode = 50 then
			c.documentid  else null end) as totalnumberofdocsregistered_settlementdeed,
			count(distinct case when p.stamparticlecode = 50 and p.stampruleid = 150 then
			c.documentid  else null end) as Noofdocsregwithinthefamilymembers_settlementdeed,
			count(distinct case when p.stamparticlecode = 50 and p.stampruleid != 150 then
			c.documentid  else null end) NoofdocsregOutoftheFamilymembers_settlementdeed,
			count(distinct case when p.stamparticlecode = 29 then
			c.documentid  else null end) as totalnumberofdocsregistered_Giftdeed,
			count(distinct case when p.stamparticlecode = 29 and p.stampruleid in (403,73,360,361) then
			c.documentid  else null end )as Noofdocsregwithinthefamilymembers_Giftdeed,
			count(distinct case when p.stamparticlecode = 29 and p.stampruleid not in (403,73,360,361) then
			c.documentid  else null end) as  NoofdocsregOutoftheFamilymembers_Giftdeed

			from kaveri.documentmaster c 
			join kaveri.propertymaster p on p.applicationnumber = c.applicationnumber
			join kaveri.sromaster s on c.srocode = s.srocode
			join kaveri.districtmaster d on d.districtcode = s.districtcode 
			where 
			c.srocode<>0 and  c.srocode=_srocode   
			and d.districtcode = _districtcode and 
			c.registrationdatetime::date >=_from_date  and c.registrationdatetime::date<=_to_date 
			group by s.sronamee,d.districtnamee
			having count(distinct case when p.stamparticlecode in (50,29) then c.documentid  else null end ) > 0),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		

		end if;

END;
$$;


