CREATE FUNCTION kaverimis.fn_mis_documents_registered_within_family_outof_family_30_23012(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(droofficename character varying, sroofficename character varying, totalnumberofdocsregistered_settlementdeed bigint, noofdocsregwithinthefamilymembers_settlementdeed bigint, noofdocsregoutofthefamilymembers_settlementdeed bigint, totalnumberofdocsregistered_giftdeed bigint, noofdocsregwithinthefamilymembers_giftdeed bigint, noofdocsregoutofthefamilymembers_giftdeed bigint)
