			--and d.districtcode = _districtcode
			c.registrationdatetime::date >=_from_date  and c.registrationdatetime::date<=_to_date 
			group by s.sronamee,d.districtnamee
			having count(distinct case when p.stamparticlecode in (50,29) then c.documentid  else null end ) > 0;

			elsif _srocode = 0 then
			return query
			
			select d.districtnamee,
			s.sronamee as sroofficename,
			count(distinct case when p.stamparticlecode = 50 then
			c.documentid  else null end) as totalnumberofdocsregistered_settlementdeed,
			count(distinct case when p.stamparticlecode = 50 and p.stampruleid = 150 then
			c.documentid  else null end) as Noofdocsregwithinthefamilymembers_settlementdeed,
			count(distinct case when p.stamparticlecode = 50 and p.stampruleid != 150 then
			c.documentid  else null end) NoofdocsregOutoftheFamilymembers_settlementdeed,
			count(distinct case when p.stamparticlecode = 29 then
			c.documentid  else null end) as totalnumberofdocsregistered_Giftdeed,
			count(distinct case when p.stamparticlecode = 29 and p.stampruleid in (403,73,360,361) then
			c.documentid  else null end )as Noofdocsregwithinthefamilymembers_Giftdeed,
			count(distinct case when p.stamparticlecode = 29 and p.stampruleid not in (403,73,360,361) then
			c.documentid  else null end) as  NoofdocsregOutoftheFamilymembers_Giftdeed

			from kaveri.documentmaster c 
			join kaveri.propertymaster p on p.applicationnumber = c.applicationnumber
			join kaveri.sromaster s on c.srocode = s.srocode
			join kaveri.districtmaster d on d.districtcode = s.districtcode 
			where 
			c.srocode<>0   
			and d.districtcode = _districtcode and 
			c.registrationdatetime::date >=_from_date  and c.registrationdatetime::date<=_to_date 
			group by s.sronamee,d.districtnamee
			having count(distinct case when p.stamparticlecode in (50,29) then c.documentid  else null end ) > 0;

	else

		return query
			
			select d.districtnamee,
			s.sronamee as sroofficename,
			count(distinct case when p.stamparticlecode = 50 then
			c.documentid  else null end) as totalnumberofdocsregistered_settlementdeed,
			count(distinct case when p.stamparticlecode = 50 and p.stampruleid = 150 then
			c.documentid  else null end) as Noofdocsregwithinthefamilymembers_settlementdeed,
			count(distinct case when p.stamparticlecode = 50 and p.stampruleid != 150 then
			c.documentid  else null end) NoofdocsregOutoftheFamilymembers_settlementdeed,
			count(distinct case when p.stamparticlecode = 29 then
			c.documentid  else null end) as totalnumberofdocsregistered_Giftdeed,
			count(distinct case when p.stamparticlecode = 29 and p.stampruleid in (403,73,360,361) then
			c.documentid  else null end )as Noofdocsregwithinthefamilymembers_Giftdeed,
			count(distinct case when p.stamparticlecode = 29 and p.stampruleid not in (403,73,360,361) then
			c.documentid  else null end) as  NoofdocsregOutoftheFamilymembers_Giftdeed

			from kaveri.documentmaster c 
			join kaveri.propertymaster p on p.applicationnumber = c.applicationnumber
			join kaveri.sromaster s on c.srocode = s.srocode
			join kaveri.districtmaster d on d.districtcode = s.districtcode 
			where 
			c.srocode<>0 and  c.srocode=_srocode   
			and d.districtcode = _districtcode and 
			c.registrationdatetime::date >=_from_date  and c.registrationdatetime::date<=_to_date 
			group by s.sronamee,d.districtnamee
			having count(distinct case when p.stamparticlecode in (50,29) then c.documentid  else null end ) > 0;
		

		end if;

END;
$$;


