--
-- Name: fn_mis_documents_registered_within_family_outof_family_30a(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_documents_registered_within_family_outof_family_30a(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(droofficename character varying, sroofficename character varying, totalnumberofdocsregistered_deedofrelease bigint, noofdocsregwithinthefamilymembers_deedofrelease bigint, noofdocsregoutofthefamilymembers_deedofrelease bigint, totalnumberofdocsregistered_leasedeed bigint, noofdocsregwithinthefamilymembers_leasedeed bigint, noofdocsregoutofthefamilymembers_leasedeed bigint, totalcount bigint)
    LANGUAGE plpgsql
    AS $$



DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if _districtcode = 0 then
return query 
with cte as (select d.districtnamee,s.sronamee as sroofficename,
count(distinct case when p.stamparticlecode = 47 then c.documentid else null end) as totalnumberofdocsregistered_deedofRelease, 
count(distinct case when p.stamparticlecode = 47 and p.stampruleid = 143 then c.documentid else null end) as Noofdocsregwithinthefamilymembers_deedofRelease, 
count(distinct case when p.stamparticlecode = 47 and p.stampruleid != 143 then c.documentid else null end) NoofdocsregOutoftheFamilymembers_deedofRelease, 
count(distinct case when p.stamparticlecode = 31 then c.documentid else null end) as totalnumberofdocsregistered_leasedeed, 
count(distinct case when p.stamparticlecode = 31 and p.stampruleid = 252 then c.documentid else null end )as Noofdocsregwithinthefamilymembers_leasedeed, 
count(distinct case when p.stamparticlecode = 31 and p.stampruleid !=252 then c.documentid else null end) as NoofdocsregOutoftheFamilymembers_leasedeed 
from kaveri.documentmaster c 
join kaveri.propertymaster p on p.applicationnumber  = c.applicationnumber 
join kaveri.sromaster s on c.srocode = s.srocode
join kaveri.districtmaster d on d.districtcode = s.districtcode 
where c.isregistrationcompleted  is true and c.registrationdatetime::date between _from_date and _to_date
group by  s.sronamee,d.districtnamee 
