d.districtcode = _districtcode and
c.isregistrationcompleted  is true and c.registrationdatetime::date between _from_date and _to_date
group by  s.sronamee,d.districtnamee 
having count(distinct case when p.stamparticlecode in (47,31) then c.documentid else null end )  > 0),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

else

return query 
with cte as (select d.districtnamee,s.sronamee as sroofficename,
count(distinct case when p.stamparticlecode = 47 then c.documentid else null end) as totalnumberofdocsregistered_deedofRelease, 
count(distinct case when p.stamparticlecode = 47 and p.stampruleid = 143 then c.documentid else null end) as Noofdocsregwithinthefamilymembers_deedofRelease, 
