join kaveri.sromaster s on c.srocode = s.srocode
join kaveri.districtmaster d on d.districtcode = s.districtcode 
where 
s.srocode = _srocode and
d.districtcode = _districtcode and
c.isregistrationcompleted  is true and c.registrationdatetime::date between _from_date and _to_date
group by  s.sronamee,d.districtnamee 
having count(distinct case when p.stamparticlecode in (47,31) then c.documentid else null end )  > 0),cte_count as (select count(*) as total_rows from cte)
			select * from cte
