--
-- Name: fn_mis_downloadpdfremarks_save(integer, integer, character varying, integer, character varying); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_downloadpdfremarks_save(_srocode integer, _deptuserid integer, _documentnumber character varying, _formno integer, _downloadremarks character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

DECLARE
v_docid bigint;
BEGIN	
insert into kaverimis.downloadpdfremarks
(		dataentryid,
		srocode,
		deptuserid,
		documentnumber,
		formno,
		downloadremarks,
		downloadtime
    )
	values
	(   nextval('kaverimis.downloadRemarksDataentryid_seq'),
		_srocode,
		_deptuserid,
		_documentnumber,
		_formno,
		_downloadremarks,
		CURRENT_TIMESTAMP
	) returning dataentryid into v_docid;
	
raise notice 'v_docid=%',v_docid;
return v_docid;

    
	 

END;

$$;


