--
-- Name: fn_mis_ec_cc_srch_stats(bigint, character varying, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_ec_cc_srch_stats(_srocode bigint, _finyear character varying, _mth character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(sroname character varying, totalecsearched bigint, totalecsubmitted bigint, totalecsigned bigint, totalccsearched bigint, totalccsubmitted bigint, totalccsigned bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
return query 
	select 
        s.sronamee,
		ec_dtls.ec_srch_cnt as TotalECSearched,
		ec_dtls.ec_sbmt_cnt as TotalECSubmitted,
		ec_dtls.ec_sgnd_cnt as TotalECSigned,
		cc_dtls.cc_srch_cnt as TotalCCSearched,
		cc_dtls.cc_sbmt_cnt as TotalCCSubmitted,
		cc_dtls.cc_sgnd_cnt as TotalCCSigned
	from kaveri.sromaster s 
	join (select ea.kaverisrocode as srocode, 
				count(ea.applicationnumber) as ec_srch_cnt,
				count(case when ea.applicationnumber like '%ECC%' then ea.applicationnumber else null end) as ec_sbmt_cnt,
				count(case when (ea.applicationnumber like '%ECC%' and ea.signedby is not null) 
					then ea.applicationnumber else null end) as ec_sgnd_cnt
			from kaveri.ec_applicationdetails ea 
			where  ea.ecdate::date>=(to_date(substr(_finyear, 1, strpos(_finyear, '-')-1), 'YYYY-MM-DD') + interval '3 month')::date
and ea.ecdate::date<=(to_date(substr(_finyear, 1, strpos(_finyear, '-')-1), 'YYYY-MM-DD') + interval '14 month' + interval '30 days')::date 
		  and to_char(ea.ecdate,'MM') = _mth
			group by ea.kaverisrocode) ec_dtls on s.srocode = ec_dtls.srocode
	join (select ca.kaverisrocode as srocode,
				count(ca.applicationnumber) as cc_srch_cnt,
				count(case when ca.applicationnumber like '%CCA%' then ca.applicationnumber else null end) as cc_sbmt_cnt,
				count(case when (ca.applicationnumber like '%CCA%' and ca.signedby is not null) 
					then ca.applicationnumber else null end) as cc_sgnd_cnt
			from kaveri.cc_applicationdetails ca
			where ca.ccdate::date>=(to_date(substr(_finyear, 1, strpos(_finyear, '-')-1), 'YYYY-MM-DD') + interval '3 month')::date
and ca.ccdate::date<=(to_date(substr(_finyear, 1, strpos(_finyear, '-')-1), 'YYYY-MM-DD') + interval '14 month' + interval '30 days')::date
		   and to_char(ca.ccdate,'MM') = _mth
			group by ca.kaverisrocode)  cc_dtls on s.srocode = cc_dtls.srocode
	where s.srocode = _srocode;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_ec_cc_srch_stats(_srocode bigint, _finyear character varying, _mth character varying, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_ec_cc_srch_stats_date_wise(bigint, character varying, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_ec_cc_srch_stats_date_wise(_srocode bigint, _finyear character varying, _mth character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(sroname character varying, ecdate timestamp without time zone, totaluserlogged bigint, totalecsearched bigint, totalecsubmitted bigint, totalecsigned bigint, totalccsearched bigint, totalccsubmitted bigint, totalccsigned bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
return query 
	select s.sronamee,ec_dtls.ecdate,ec_dtls.totaluserlogged,
		ec_dtls.ec_srch_cnt as TotalECSearched,
		ec_dtls.ec_sbmt_cnt as TotalECSubmitted,
		ec_dtls.ec_sgnd_cnt as TotalECSigned,
		cc_dtls.cc_srch_cnt as TotalCCSearched,
		cc_dtls.cc_sbmt_cnt as TotalCCSubmitted,
		cc_dtls.cc_sgnd_cnt as TotalCCSigned
	from kaveri.sromaster s 
	join (select ea.kaverisrocode as srocode, ea.ecdate,count(ea.userid) as totaluserlogged,
				count(ea.applicationnumber) as ec_srch_cnt,
				count(case when ea.applicationnumber like '%ECC%' then ea.applicationnumber else null end) as ec_sbmt_cnt,
				count(case when (ea.applicationnumber like '%ECC%' and ea.signedby is not null) 
					then ea.applicationnumber else null end) as ec_sgnd_cnt
			from kaveri.ec_applicationdetails ea , kaveri.citizenmaster cit where ea.userid = cit.citizenid
			and  ea.ecdate::date>=(to_date(substr(_finyear, 1, strpos(_finyear, '-')-1), 'YYYY-MM-DD') + interval '3 month')::date
and ea.ecdate::date<=(to_date(substr(_finyear, 1, strpos(_finyear, '-')-1), 'YYYY-MM-DD') + interval '14 month' + interval '30 days')::date 
		  and to_char(ea.ecdate,'MM') = _mth
			group by ea.kaverisrocode,ea.ecdate) ec_dtls on s.srocode = ec_dtls.srocode
	join (select ca.kaverisrocode as srocode,
				count(ca.applicationnumber) as cc_srch_cnt,
				count(case when ca.applicationnumber like '%CCA%' then ca.applicationnumber else null end) as cc_sbmt_cnt,
				count(case when (ca.applicationnumber like '%CCA%' and ca.signedby is not null) 
					then ca.applicationnumber else null end) as cc_sgnd_cnt
			from kaveri.cc_applicationdetails ca
			where ca.ccdate::date>=(to_date(substr(_finyear, 1, strpos(_finyear, '-')-1), 'YYYY-MM-DD') + interval '3 month')::date
and ca.ccdate::date<=(to_date(substr(_finyear, 1, strpos(_finyear, '-')-1), 'YYYY-MM-DD') + interval '14 month' + interval '30 days')::date
		   and to_char(ca.ccdate,'MM') = _mth
			group by ca.kaverisrocode)  cc_dtls on s.srocode = cc_dtls.srocode
	where s.srocode = _srocode;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_ec_cc_srch_stats_date_wise(_srocode bigint, _finyear character varying, _mth character varying, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_ec_daily_receipt(bigint, bigint, date, date, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_ec_daily_receipt(_districtcode bigint, _srocode bigint, _fromdate date, _todate date, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(drname character varying, nameofsubregistrationoffice character varying, receiptnumber integer, receipttype character varying, modeofpayment character varying, challannumber character varying, receiptdate text, sroapplicationnumber character varying, applicantname character varying, issuedby character varying, periodofsearch character varying, amount numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
if(_districtcode=0) then --All district
raise notice 'All district';
	return query 
	with cte as (select  distinct
		dsm.districtnamee as drname,
		s.sronamee as nameofsubregistrationoffice,
		r.receiptnumber  as receiptnumber,
		(case when ec.ispropertysearch=true then 'Property Search' else 'Name search' end)::varchar as receipttype,
		'Online'::varchar as modeofpayment,
		epd.deptreferencecode as challannumber,
		to_char(bk.transactiontimestamp,'DD-MM-YYYY')  as receiptdate,
		ec.applicationnumber  as sroapplicationnumber,
		concat_ws(' '::text, c.firstname, c.middlename, c.lastname)::varchar as applicantname,
		s.sronamee as issuedby,
		--(du.firstname||' '||du.lastname)::varchar as issuedby,
		(ceiling((ec.searchtodate::date - ec.searchfromdate::date)/365.0)::varchar||' year ['||to_char(ec.searchfromdate, 'dd-MM-yyyy')||' - '||to_char(ec.searchtodate, 'dd-MM-yyyy')||']')::varchar as periodofsearch,
		bk.amount::numeric as amount
	from kaveri.ec_applicationdetails ec
	join kaveri.applicantapplicationdetails a on ec.applicationnumber = a.applicationnumber
	left join kaveri.ams_reg_epaymenttransdetails epd on epd.ecid=ec.ecid--epd.applicationnumber = ec.applicationnumber
	join kaveri.citizenmaster c on ec.userid = c.citizenid 
	left join kaveri.departmentusers du on a.assignedto::text = du.userid::text
	join kaveri.sromaster s on ec.kaverisrocode = s.srocode
	join kaveri.districtmaster dsm on s.districtcode = dsm.districtcode
	left join kaveri.receiptmaster r on epd.receiptid=r.receiptid 
	join kaveri.ams_reg_epaymentbankackdetails bk on epd.deptreferencecode =bk.deptreferencecode
	where 
	--ec.kaverisrocode = _srocode  and 
	--dsm.districtcode=_districtcode and 
	a.currentstatus ='CE110' and bk.paymentstatuscode='10700066'
	and ec.ecdate::date >= _fromDate and ec.ecdate::date <= _toDate),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
	
	
 elsif(_srocode=0) then
 
 raise notice 'All sro';
 
 return query 
	with cte as (select distinct
		dsm.districtnamee as drname,
		s.sronamee as nameofsubregistrationoffice,
		r.receiptnumber  as receiptnumber,
		(case when ec.ispropertysearch=true then 'Property Search' else 'Name search' end)::varchar as receipttype,
		'Online'::varchar as modeofpayment,
		epd.deptreferencecode as challannumber,
		to_char(bk.transactiontimestamp,'DD-MM-YYYY')  as receiptdate,
		ec.applicationnumber  as sroapplicationnumber,
		concat_ws(' '::text, c.firstname, c.middlename, c.lastname)::varchar as applicantname,
		s.sronamee as issuedby,
		--(du.firstname||' '||du.lastname)::varchar as issuedby,
		(ceiling((ec.searchtodate::date - ec.searchfromdate::date)/365.0)::varchar||' year ['||to_char(ec.searchfromdate, 'dd-MM-yyyy')||' - '||to_char(ec.searchtodate, 'dd-MM-yyyy')||']')::varchar as periodofsearch,
		bk.amount::numeric as amount
	from kaveri.ec_applicationdetails ec
	join kaveri.applicantapplicationdetails a on ec.applicationnumber = a.applicationnumber
	left join kaveri.ams_reg_epaymenttransdetails epd on epd.ecid=ec.ecid--epd.applicationnumber = ec.applicationnumber
	join kaveri.citizenmaster c on ec.userid = c.citizenid 
	left join kaveri.departmentusers du on a.assignedto::text = du.userid::text
	join kaveri.sromaster s on ec.kaverisrocode = s.srocode
	join kaveri.districtmaster dsm on s.districtcode = dsm.districtcode
	left join kaveri.receiptmaster r on epd.receiptid=r.receiptid 
	join kaveri.ams_reg_epaymentbankackdetails bk on epd.deptreferencecode =bk.deptreferencecode
	where 
	--ec.kaverisrocode = _srocode  and 
	dsm.districtcode=_districtcode and 
	a.currentstatus ='CE110' and bk.paymentstatuscode='10700066'
	and ec.ecdate::date >= _fromDate and ec.ecdate::date <= _toDate),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
	
	ELSE
	raise notice 'Perticular district and sro';
	return query 
	with cte as (select distinct
		dsm.districtnamee as drname,
		s.sronamee as nameofsubregistrationoffice,
		r.receiptnumber  as receiptnumber,
		(case when ec.ispropertysearch=true then 'Property Search' else 'Name search' end)::varchar as receipttype,
		'Online'::varchar as modeofpayment,
		epd.deptreferencecode as challannumber,
		to_char(bk.transactiontimestamp,'DD-MM-YYYY') as receiptdate,
		ec.applicationnumber  as sroapplicationnumber,
		concat_ws(' '::text, c.firstname, c.middlename, c.lastname)::varchar as applicantname,
		s.sronamee as issuedby,
		--(du.firstname||' '||du.lastname)::varchar as issuedby,
		(ceiling((ec.searchtodate::date - ec.searchfromdate::date)/365.0)::varchar||' year ['||to_char(ec.searchfromdate, 'dd-MM-yyyy')||' - '||
		to_char(ec.searchtodate, 'dd-MM-yyyy')||']')::varchar as periodofsearch,
		bk.amount::numeric as amount
	from kaveri.ec_applicationdetails ec
	join kaveri.applicantapplicationdetails a on ec.applicationnumber = a.applicationnumber
	left join kaveri.ams_reg_epaymenttransdetails epd on epd.ecid=ec.ecid--epd.applicationnumber = ec.applicationnumber
	join kaveri.citizenmaster c on ec.userid = c.citizenid 
	left join kaveri.departmentusers du on a.assignedto::text = du.userid::text
	join kaveri.sromaster s on ec.kaverisrocode = s.srocode
	join kaveri.districtmaster dsm on s.districtcode = dsm.districtcode
	left join kaveri.receiptmaster r on epd.receiptid=r.receiptid 
	join kaveri.ams_reg_epaymentbankackdetails bk on epd.deptreferencecode =bk.deptreferencecode
	where 
	ec.kaverisrocode = _srocode  and 
	dsm.districtcode=_districtcode and 
	a.currentstatus ='CE110' and bk.paymentstatuscode='10700066'
	and ec.ecdate::date >= _fromDate and ec.ecdate::date <= _toDate),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
	
	end if;
 
end;
$$;


