ALTER FUNCTION kaverimis.fn_mis_ec_daily_receipt_temp1(_districtcode bigint, _srocode bigint, _fromdate date, _todate date, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form11_statistical_genderwise_transaction(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_form11_statistical_genderwise_transaction(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _stamparticle integer DEFAULT 0, _amounttype integer DEFAULT 0, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(droffice character varying, srooffice character varying, total_number_of_documents_registered bigint, documentregistered_male bigint, booktype_male text, documentregistered_female bigint, booktype_female text, documentregistered_transgender bigint, booktype_transgender text, stampduty_male numeric, registrationfee_male numeric, otherfee_male numeric, total_male numeric, stampduty_female numeric, registrationfee_female numeric, otherfee_female numeric, total_female numeric, stampduty_transgender numeric, registrationfee_transgender numeric, otherfee_transgender numeric, total_transgender numeric, stampduty_total numeric, registrationfee_total numeric, otherfee_total numeric, total numeric, totalcount1 bigint)
    LANGUAGE plpgsql
    AS $$


DECLARE
PageOffset INTEGER := 0;

BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if _stamparticle=0 then --All article

			if _districtcode=0 then  --All district

	if _amounttype=0 THEN --no min max
	
		return query
		with cte as (select 
		districtname,
		sroname,
		count(applicationnumber),
		count(distinct case when sex=1 then applicationnumber else null end) as no_doc_male,
		string_agg(distinct case when sex=1 then bookname else null end,',') as book_male,
		count(distinct case when sex=0 then applicationnumber else null end) as no_doc_female,
		string_agg(distinct case when sex=0 then bookname else null end,',') as book_female,
		count(distinct case when sex=2 then applicationnumber else null end) as no_doc_transgender,
		string_agg(distinct case when sex=2 then bookname else null end,',') as book_transgender,
		sum(case when sex=1 then stampduty else 0 end) as total_stamp_male,
		sum(case when sex=1 then registrationfee else 0 end) as total_regd_male,
		sum(case when sex=1 then otherfees else 0 end) as total_other_male,
		sum(case when sex=1 then Totalfees else 0 end) as total_male,
		sum(case when sex=0 then stampduty else 0 end) as total_stamp_female,
		sum(case when sex=0 then registrationfee else 0 end) as total_regd_female,
		sum(case when sex=0 then otherfees else 0 end) as total_other_female,
		sum(case when sex=0 then Totalfees else 0 end) as total_female,
		sum(case when sex=2 then stampduty else 0 end) as total_stamp_trans,
		sum(case when sex=2 then registrationfee else 0 end) as total_regd_trans,
		sum(case when sex=2 then otherfees else 0 end) as total_other_trans,
		sum(case when sex=2 then Totalfees else 0 end) as total_trans,
		sum(stampduty) as totalstampduty,
		sum(registrationfee)as totalregistrationfee,
		sum(otherfees) as totalotherfee,
		sum(Totalfees) as Totalfees

		from

		(select distinct
		dsm.districtnamee as districtname,
		b.sronamee as sroname,
		d.applicationnumber as applicationnumber,
		p.sex as sex,
		e.booknameenglish as bookname,
		sum(case when fr.feerulecode in (36,58,59,64) then fr.amountpaid else 0 end)as stampduty,
		sum(case when fr.feerulecode=1  then fr.amountpaid else 0 end)as registrationfee,
		sum(case when fr.feerulecode not in (1,36,58,59,64) and fr.amountpaid>0 then fr.amountpaid else 0 end)as otherfees,
		sum(case when fr.amountpaid>0 then fr.amountpaid else 0 end  ) as Totalfees

		from kaveri.documentmaster d 
		join kaveri.sromaster b on d.srocode = b.srocode
		join kaveri.districtmaster dsm on b.districtcode=dsm.districtcode 
		join (select distinct applicationnumber,sex,ispresenter from kaveri.partyinfo) p on p.applicationnumber=d.applicationnumber and p.ispresenter is true
		join kaveri.stampregrelations s on d.regarticlecode=s.regarticlecode 
		join kaveri.booktypemaster e on d.bookid = e.bookid
		join kaveri.feesrequired fr on fr.applicationnumber=d.applicationnumber 
		where p.ispresenter is true and isregistrationcompleted = true and registrationdatetime::date >= _fromdate and
		registrationdatetime::date <=_todate 
		--and s.stamparticlecode=_stamparticle
		and p.sex!=3 
		--and dsm.districtcode=_districtcode and d.srocode=_srocode
		group by d.applicationnumber,p.sex,e.booknameenglish,sroname,districtname) as test
		group by districtname,sroname),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0 OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
		elsif _amounttype=1 then --Total
		return query
		with cte as (select 
		districtname,
		sroname,
		count(applicationnumber),
		count(distinct case when sex=1 then applicationnumber else null end) as no_doc_male,
		string_agg(distinct case when sex=1 then bookname else null end,',') as book_male,
		count(distinct case when sex=0 then applicationnumber else null end) as no_doc_female,
		string_agg(distinct case when sex=0 then bookname else null end,',') as book_female,
		count(distinct case when sex=2 then applicationnumber else null end) as no_doc_transgender,
		string_agg(distinct case when sex=2 then bookname else null end,',') as book_transgender,
		sum(case when sex=1 then stampduty else 0 end) as total_stamp_male,
		sum(case when sex=1 then registrationfee else 0 end) as total_regd_male,
		sum(case when sex=1 then otherfees else 0 end) as total_other_male,
		sum(case when sex=1 then Totalfees else 0 end) as total_male,
		sum(case when sex=0 then stampduty else 0 end) as total_stamp_female,
		sum(case when sex=0 then registrationfee else 0 end) as total_regd_female,
		sum(case when sex=0 then otherfees else 0 end) as total_other_female,
		sum(case when sex=0 then Totalfees else 0 end) as total_female,
		sum(case when sex=2 then stampduty else 0 end) as total_stamp_trans,
		sum(case when sex=2 then registrationfee else 0 end) as total_regd_trans,
		sum(case when sex=2 then otherfees else 0 end) as total_other_trans,
		sum(case when sex=2 then Totalfees else 0 end) as total_trans,
		sum(stampduty) as totalstampduty,
		sum(registrationfee)as totalregistrationfee,
		sum(otherfees) as totalotherfee,
		sum(Totalfees) as Totalfees

		from

		(select distinct
		dsm.districtnamee as districtname,
		b.sronamee as sroname,
		d.applicationnumber as applicationnumber,
		p.sex as sex,
		e.booknameenglish as bookname,
		sum(case when fr.feerulecode in (36,58,59,64) then fr.amountpaid else 0 end)as stampduty,
		sum(case when fr.feerulecode=1  then fr.amountpaid else 0 end)as registrationfee,
		sum(case when fr.feerulecode not in (1,36,58,59,64) and fr.amountpaid>0 then fr.amountpaid else 0 end)as otherfees,
		sum(case when fr.amountpaid>0 then fr.amountpaid else 0 end  ) as Totalfees

		from kaveri.documentmaster d 
		join kaveri.sromaster b on d.srocode = b.srocode
		join kaveri.districtmaster dsm on b.districtcode=dsm.districtcode 
		join (select distinct applicationnumber,sex,ispresenter from kaveri.partyinfo) p on p.applicationnumber=d.applicationnumber and p.ispresenter is true
		join kaveri.stampregrelations s on d.regarticlecode=s.regarticlecode 
		join kaveri.booktypemaster e on d.bookid = e.bookid
		join (select applicationnumber,sum(amountpaid) from kaveri.feesrequired group by applicationnumber
		having sum(amountpaid)>=_minval and sum(amountpaid)<=_maxval)
		
		fr1 on fr1.applicationnumber=d.applicationnumber 
		join kaveri.feesrequired  fr on fr.applicationnumber=fr1.applicationnumber
		where p.ispresenter is true and isregistrationcompleted = true and registrationdatetime::date >= _fromdate and
		registrationdatetime::date <=_todate  
		--and s.stamparticlecode=_stamparticle
		and p.sex!=3 
		--and dsm.districtcode=_districtcode and d.srocode=_srocode
		group by d.applicationnumber,p.sex,e.booknameenglish,sroname,districtname) as test
