ALTER FUNCTION kaverimis.fn_mis_form11_statistical_genderwise_transaction_23012024(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _stamparticle integer, _amounttype integer, _minval numeric, _maxval numeric) OWNER TO csgadmin;

--
-- Name: fn_mis_form12_area_wise_transaction(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form12_area_wise_transaction(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _choice integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, srooffice character varying, metropolitan_bbmp bigint, amt_metropolitan_bbmp numeric, city_corporation bigint, amt_city_corporation numeric, mincipality bigint, amt_mincipality numeric, muncipality_tmc bigint, amt_muncipality_tmc numeric, town_panchayat bigint, amt_town_panchayat numeric, agri_land bigint, amt_agri_land numeric, taluk_panchayat bigint, amt_taluk_panchayat numeric, totaldocregistered bigint, totalrevenue numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN	
if _districtcode=0 then --All districtcode

	if _choice = 0 then -- without min max
	raise notice 'All District and All sro  without min, max';
		return query 
		select districtnamee,sronamee,
		count(distinct case when regionid=1  then finalregistrationnumber end ) as Metropolitan_BBMP,
		sum(case when  regionid=1 then amountpaid else 0 end) as Amt_Metropolitan_BBMP,
		count(distinct case when regionid in (2,6)   then finalregistrationnumber end) as city_corporation,
		sum(case when regionid in (2,6) then amountpaid else 0 end) as Amt_city_corporation,
		count(distinct case when regionid=3  then finalregistrationnumber end  ) as mincipality,
		sum(case when regionid=3 then amountpaid else 0 end) as Amt_mincipality,
		count(distinct case when regionid=7    then finalregistrationnumber end ) as muncipality_tmc,
		sum(case when regionid=7 then amountpaid else 0 end) as Amt_muncipality_tmc,
		count(distinct case when regionid=4   then finalregistrationnumber end ) as Town_panchayat,
		sum(case when regionid=4 then amountpaid else 0 end) as Amt_Town_panchayat,
		count(distinct case when propertytypeid=17   then finalregistrationnumber end ) as agri_land,
		sum(case when propertytypeid=17 then amountpaid else 0 end) as Amt_agri_land,
		count(distinct case when regionid=5  and propertytypeid <> 17 then finalregistrationnumber end ) as Taluk_panchayat,
		sum(case when regionid=5 and propertytypeid <> 17 then amountpaid else 0 end) as Amt_Taluk_panchayat,
		count(distinct case when propertytypeid<>17 then finalregistrationnumber end)+ 
		count(distinct case when propertytypeid=17 then finalregistrationnumber end )
		as Totaldocregistered,
		sum(case when  regionid=1 then amountpaid else 0 end)+
		sum(case when regionid in (2,6) then amountpaid else 0 end) +
		sum(case when regionid=3 then amountpaid else 0 end) +
		sum(case when regionid=7 then amountpaid else 0 end) +
		sum(case when regionid=4 then amountpaid else 0 end) +
		sum(case when regionid=5 and propertytypeid <> 17 then amountpaid else 0 end) +
		sum(case when propertytypeid=17 then amountpaid else 0 end) as Totalrevenue
		from 
		(select  distinct 
		dsm.districtnamee,
		sm.sronamee,
		dsm.districtcode,
		dm.srocode,
		dm.finalregistrationnumber,
		d.regionid,
		d.regionname,
		p2.propertytypeid, 
		fr.feerulecode,
		fr.amountpaid
			
		from kaveri.documentmaster dm
		join kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber
		and pm.srocode = dm.srocode 
		join kaveri.propertytypemaster p2 on pm.propertytypeid  = p2.propertytypeid  
		join kaveri.villagemaster vm on pm.villagecode = vm.villagecode 
		join kaveri.roadmaster rm on rm.roadcode = pm.roadcode
		join kaveri.regionmaster d ON  d.regionid = rm.regionid 
		join kaveri.feesrequired fr on fr.applicationnumber = dm.applicationnumber
		join kaveri.sromaster sm on sm.srocode=dm.srocode
		join kaveri.districtmaster dsm on  dsm.districtcode = sm.districtcode
		where  
		dm.registrationdatetime::date>=_from_date and
		dm.registrationdatetime::date<=_to_date)prop 
		group by districtnamee,sronamee;
	
		
	  elsif _choice=1 then 
	  raise notice 'All District and All sro  with min, max';
	  return query 
		select districtnamee,sronamee,
		count(distinct case when regionid=1  then finalregistrationnumber end ) as Metropolitan_BBMP,
		sum(case when  regionid=1 then amountpaid else 0 end) as Amt_Metropolitan_BBMP,
		count(distinct case when regionid in (2,6)   then finalregistrationnumber end) as city_corporation,
		sum(case when regionid in (2,6) then amountpaid else 0 end) as Amt_city_corporation,
		count(distinct case when regionid=3  then finalregistrationnumber end  ) as mincipality,
		sum(case when regionid=3 then amountpaid else 0 end) as Amt_mincipality,
		count(distinct case when regionid=7    then finalregistrationnumber end ) as muncipality_tmc,
		sum(case when regionid=7 then amountpaid else 0 end) as Amt_muncipality_tmc,
		count(distinct case when regionid=4   then finalregistrationnumber end ) as Town_panchayat,
