ALTER FUNCTION kaverimis.fn_mis_form12_area_wise_transaction(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _choice integer, _minval integer, _maxval integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form12_area_wise_transaction(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_form12_area_wise_transaction(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _choice integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, srooffice character varying, metropolitan_bbmp bigint, amt_metropolitan_bbmp numeric, city_corporation bigint, amt_city_corporation numeric, mincipality bigint, amt_mincipality numeric, muncipality_tmc bigint, amt_muncipality_tmc numeric, town_panchayat bigint, amt_town_panchayat numeric, agri_land bigint, amt_agri_land numeric, taluk_panchayat bigint, amt_taluk_panchayat numeric, totaldocregistered bigint, totalrevenue numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$


DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);




	
if _districtcode=0 then --All districtcode

	if _choice = 0 then -- without min max
	raise notice 'All District and All sro  without min, max';
		return query 
		with cte as (select districtnamee,sronamee,
		count(distinct case when regionid=1  then finalregistrationnumber end ) as Metropolitan_BBMP,
		sum(case when  regionid=1 then amountpaid else 0 end) as Amt_Metropolitan_BBMP,
		count(distinct case when regionid in (2,6)   then finalregistrationnumber end) as city_corporation,
		sum(case when regionid in (2,6) then amountpaid else 0 end) as Amt_city_corporation,
		count(distinct case when regionid=3  then finalregistrationnumber end  ) as mincipality,
		sum(case when regionid=3 then amountpaid else 0 end) as Amt_mincipality,
		count(distinct case when regionid=7    then finalregistrationnumber end ) as muncipality_tmc,
		sum(case when regionid=7 then amountpaid else 0 end) as Amt_muncipality_tmc,
		count(distinct case when regionid=4   then finalregistrationnumber end ) as Town_panchayat,
		sum(case when regionid=4 then amountpaid else 0 end) as Amt_Town_panchayat,
		count(distinct case when regionid=5 and propertytypeid=17   then finalregistrationnumber end ) as agri_land,
		sum(case when regionid=5 and propertytypeid=17 then amountpaid else 0 end) as Amt_agri_land,
		count(distinct case when regionid=5  and propertytypeid <> 17 then finalregistrationnumber end ) as Taluk_panchayat,
		sum(case when regionid=5 and propertytypeid <> 17 then amountpaid else 0 end) as Amt_Taluk_panchayat,
		count(distinct case when regionid=1  then finalregistrationnumber end )+
		count(distinct case when regionid in (2,6)   then finalregistrationnumber end)+
		count(distinct case when regionid=3  then finalregistrationnumber end  )+
		count(distinct case when regionid=7    then finalregistrationnumber end )+
		count(distinct case when regionid=4   then finalregistrationnumber end )+
		count(distinct case when regionid=5 and propertytypeid=17   then finalregistrationnumber end )+
		count(distinct case when regionid=5  and propertytypeid <> 17 then finalregistrationnumber end )
		as Totaldocregistered,
		sum(case when  regionid=1 then amountpaid else 0 end)+
		sum(case when regionid in (2,6) then amountpaid else 0 end) +
		sum(case when regionid=3 then amountpaid else 0 end) +
		sum(case when regionid=7 then amountpaid else 0 end) +
		sum(case when regionid=4 then amountpaid else 0 end) +
		sum(case when regionid=5 and propertytypeid <> 17 then amountpaid else 0 end) +
		sum(case when regionid=5 and propertytypeid=17 then amountpaid else 0 end) as Totalrevenue
		from 
		(select  distinct 
		dsm.districtnamee,
		sm.sronamee,
		dsm.districtcode,
		dm.srocode,
		dm.finalregistrationnumber,
		d.regionid,
		d.regionname,
		p2.propertytypeid, 
		fr.feerulecode,
		fr.amountpaid
			
		from kaveri.documentmaster dm
		join kaveri.propertymaster pm on dm.applicationnumber=pm.applicationnumber 
		 
		join kaveri.propertytypemaster p2 on pm.propertytypeid  = p2.propertytypeid  
		join kaveri.villagemaster vm on pm.villagecode = vm.villagecode 
		join kaveri.roadmaster rm on   pm.villagecode=rm.villagecode and pm.roadcode=rm.roadcode
		join kaveri.regionmaster d ON  rm.regionid=d.regionid 
		join kaveri.feesrequired fr on dm.applicationnumber=fr.applicationnumber
		join kaveri.sromaster sm on dm.srocode=sm.srocode
		join kaveri.districtmaster dsm on  sm.districtcode=dsm.districtcode
		where  
		(dm.registrationdatetime between _from_date and _to_date ::timestamp + INTERVAL '1 day' ))prop 
		group by districtnamee,sronamee),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
	
		
	  elsif _choice=1 then 
	  raise notice 'All District and All sro  with min, max';
	  return query 
		with cte as (select districtnamee,sronamee,
		count(distinct case when regionid=1  then finalregistrationnumber end ) as Metropolitan_BBMP,
