		(select  distinct 
		dsm.districtnamee,
		sm.sronamee,
		dsm.districtcode,
		dm.srocode,
		dm.finalregistrationnumber,
		d.regionid,
		d.regionname,
		fr.feerulecode,
		fr.amountpaid
			
		from kaveri.documentmaster dm
		join kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber
		and pm.srocode = dm.srocode 
		join kaveri.villagemaster vm on pm.villagecode = vm.villagecode 
		join kaveri.roadmaster rm on rm.roadcode = pm.roadcode
		join kaveri.regionmaster d ON  d.regionid = rm.regionid 
		join
		(select applicationnumber,sum(amountpaid) from  kaveri.feesrequired group by applicationnumber
		having sum(amountpaid)>=_minval AND
			  sum(amountpaid)<=_maxval )fr2 on fr2.applicationnumber = dm.applicationnumber
		join kaveri.feesrequired fr on fr.applicationnumber = fr2.applicationnumber
		join kaveri.sromaster sm on sm.srocode=dm.srocode
		join kaveri.districtmaster dsm on  dsm.districtcode = sm.districtcode
		where  dsm.districtcode=_districtcode and
		dm.registrationdatetime::date>=_from_date and
		dm.registrationdatetime::date<=_to_date)prop 
		group by districtnamee,sronamee;
		
		end if;
		
		else --perticulare district and perticular sro
		
		if _choice = 0 then -- without min max
		raise notice 'Perticular District and All sro  without min, max';
		return query 
		select districtnamee,sronamee,
		count(distinct finalregistrationnumber) as Totaldocregistered,
		sum(distinct case when feerulecode=1 then amountpaid else 0 end) as TotalRegistrationamount,
		count(distinct case when regionid=1  then finalregistrationnumber end ) as Metropolitan_BBMP,
		count(distinct case when regionid in (2,6)   then finalregistrationnumber end) as city_corporation,
		count(distinct case when regionid=3  then finalregistrationnumber end  ) as mincipality,
		count(distinct case when regionid=7    then finalregistrationnumber end ) as muncipality_tmc,
		count(distinct case when regionid=4   then finalregistrationnumber end ) as Town_panchayat,
		0 as Agri_land,
		count(distinct case when regionid=5   then finalregistrationnumber end ) as Taluk_panchayat,

		sum(amountpaid) as Totalrevenue
		from 
		(select  distinct 
		dsm.districtnamee,
		sm.sronamee,
		dsm.districtcode,
		dm.srocode,
		dm.finalregistrationnumber,
		d.regionid,
		d.regionname,
		fr.feerulecode,
		fr.amountpaid
			
		from kaveri.documentmaster dm
		join kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber
		and pm.srocode = dm.srocode and dm.srocode=_srocode 
		join kaveri.villagemaster vm on pm.villagecode = vm.villagecode and pm.srocode=_srocode
		join kaveri.roadmaster rm on rm.roadcode = pm.roadcode
		join kaveri.regionmaster d ON  d.regionid = rm.regionid
		join kaveri.feesrequired fr on fr.applicationnumber = dm.applicationnumber
		join kaveri.sromaster sm on sm.srocode=dm.srocode
		join kaveri.districtmaster dsm on  dsm.districtcode = sm.districtcode
		where  dm.srocode=_srocode and dsm.districtcode=_districtcode and 
		dm.registrationdatetime::date>=_from_date and
		dm.registrationdatetime::date<=_to_date)prop 
		group by districtnamee,sronamee;
		
	  elsif _choice=1 then 
	  raise notice 'Perticular District and Perticular  sro  with min, max';
	  return query 
		select districtnamee,sronamee,
		count(distinct finalregistrationnumber) as Totaldocregistered,
		sum(distinct case when feerulecode=1 then amountpaid else 0 end) as TotalRegistrationamount,
		count(distinct case when regionid=1  then finalregistrationnumber end ) as Metropolitan_BBMP,
		count(distinct case when regionid in (2,6)   then finalregistrationnumber end) as city_corporation,
		count(distinct case when regionid=3  then finalregistrationnumber end  ) as mincipality,
		count(distinct case when regionid=7    then finalregistrationnumber end ) as muncipality_tmc,
		count(distinct case when regionid=4   then finalregistrationnumber end ) as Town_panchayat,
		0 as Agri_land,
		count(distinct case when regionid=5   then finalregistrationnumber end ) as Taluk_panchayat,

		sum(amountpaid) as Totalrevenue
		from 
		(select  distinct 
		dsm.districtnamee,
		sm.sronamee,
		dsm.districtcode,
		dm.srocode,
		dm.finalregistrationnumber,
		d.regionid,
		d.regionname,
		fr.feerulecode,
		fr.amountpaid
			
		from kaveri.documentmaster dm
		join kaveri.propertymaster pm on pm.applicationnumber = dm.applicationnumber
		and pm.srocode = dm.srocode and dm.srocode=_srocode 
		join kaveri.villagemaster vm on pm.villagecode = vm.villagecode and pm.srocode=_srocode
		join kaveri.roadmaster rm on rm.roadcode = pm.roadcode
		join kaveri.regionmaster d ON  d.regionid = rm.regionid
		join
		(select applicationnumber,sum(amountpaid) from  kaveri.feesrequired group by applicationnumber
		having sum(amountpaid)>=_minval AND
			  sum(amountpaid)<=_maxval )fr2 on fr2.applicationnumber = dm.applicationnumber
		join kaveri.feesrequired fr on fr.applicationnumber = fr2.applicationnumber
		join kaveri.sromaster sm on sm.srocode=dm.srocode
		join kaveri.districtmaster dsm on  dsm.districtcode = sm.districtcode
		where  dm.srocode=_srocode and dsm.districtcode=_districtcode and 
		dm.registrationdatetime::date>=_from_date and
		dm.registrationdatetime::date<=_to_date)prop 
		group by districtnamee,sronamee;
		
		end if;
		
		end if;
	END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form12_area_wise_transaction_backup_28_03_2023(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _choice integer, _minval integer, _maxval integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form12_area_wise_transaction_backup_28_03_2023(integer, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form12_area_wise_transaction_backup_28_03_2023(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer, _choice integer DEFAULT NULL::integer) RETURNS TABLE(srooffice character varying, documentnumber integer, metropolitan numeric, citycorporation numeric, municipality numeric, municipality_tmc numeric, town_panchayat numeric, agriculturalland integer, talukpanchayat integer, totalrevenue numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
if _choice = 1 then -- with min max
	return query 
select distinct 
b.sronamee as srooffice,
a.documentnumber,
case when d.regionid = 1 then
sum(e.amountpaid) else 0 end as Metropolitan,
case when d.regionid = 2 then
sum(e.amountpaid) else 0 end as citycorporation,
case when d.regionid = 3 then
sum(e.amountpaid) else 0 end as Municipality,
case when d.regionid = 7 then
sum(e.amountpaid) else 0 end as Municipality_TMC,
case when d.regionid = 4 then
sum(e.amountpaid) else 0 end as Town_Panchayat,
0 as AgriculturalLand,
0 as TalukPanchayat,
(case when regionid = 1 then
sum(e.amountpaid) else 0 end +
case when regionid = 2 then
sum(e.amountpaid) else 0 end +
case when regionid = 3 then
sum(e.amountpaid) else 0 end +
case when regionid = 7 then
sum(e.amountpaid) else 0 end +
case when regionid = 4 then
sum(e.amountpaid) else 0 end +
0 + 0) TotalRevenue
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.villagemaster c on b.srocode = c.srocode
join kaveri.roadmaster d on c.villagecode = d.villagecode
join kaveri.feesrequired e on a.documentid = e.documentid
--join kaverimis.vw_mis_revenue_report e on a.applicationnumber = e.applicationnumber
inner join kaveri.propertymaster vw1 on e.documentid = vw1.documentid
/* (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_srocode
     and marketvalue >=_minval and marketvalue <=_maxval )
     vw1 on e.applicationnumber=vw1.applicationnumber*/
where a.srocode = _srocode and registrationdatetime >= _from_date  
and marketvalue >=_minval and marketvalue <=_maxval and
registrationdatetime <= _to_date and isregistrationcompleted = true
group by b.sronamee,a.documentnumber,d.regionid;
elsif _choice = 2 then -- without min max
	return query 
select distinct 
b.sronamee as srooffice,
a.documentnumber,
case when d.regionid = 1 then
sum(e.amountpaid) else 0 end as Metropolitan,
case when d.regionid = 2 then
sum(e.amountpaid) else 0 end as citycorporation,
case when d.regionid = 3 then
sum(e.amountpaid) else 0 end as Municipality,
case when d.regionid = 7 then
sum(e.amountpaid) else 0 end as Municipality_TMC,
case when d.regionid = 4 then
sum(e.amountpaid) else 0 end as Town_Panchayat,
0 as AgriculturalLand,
0 as TalukPanchayat,
(case when regionid = 1 then
sum(e.amountpaid) else 0 end +
case when regionid = 2 then
sum(e.amountpaid) else 0 end +
case when regionid = 3 then
sum(e.amountpaid) else 0 end +
case when regionid = 7 then
sum(e.amountpaid) else 0 end +
case when regionid = 4 then
sum(e.amountpaid) else 0 end +
0 + 0) TotalRevenue
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.villagemaster c on b.srocode = c.srocode
join kaveri.roadmaster d on c.villagecode = d.villagecode
--join kaverimis.vw_mis_revenue_report e on a.applicationnumber = e.applicationnumber
join kaveri.feesrequired e on a.documentid = e.documentid
inner join kaveri.propertymaster vw1 on e.documentid = vw1.documentid
/*join kaverimis.vw_mis_revenue_report e on a.applicationnumber = e.applicationnumber
inner join  
 (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_srocode
     and marketvalue >=_minval and marketvalue <=_maxval )
     vw1 on e.applicationnumber=vw1.applicationnumber*/
where a.srocode = _srocode and registrationdatetime >= _from_date  
and marketvalue >=_minval and marketvalue <=_maxval and
registrationdatetime <= _to_date and isregistrationcompleted = true
group by b.sronamee,a.documentnumber,d.regionid;
end if;
END;
$$;


