--

CREATE FUNCTION kaverimis.fn_mis_form17_details_of_collection_of_the_revenue(_srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer, _choice integer DEFAULT NULL::integer) RETURNS TABLE(month text, numberofdocuments bigint, stampduty numeric, registrationfees numeric, scanningfees numeric, otherfees integer, total numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
if _choice = 1 then
return query 
select distinct to_char(a.registrationdatetime,'Month-yyyy') as month,
count(a.documentid) as NumberofDocuments,
case when b.feerulecode = 36 then
sum(b.amountpaid) else 0 end as stampduty,
case when b.feerulecode = 1 then
sum(b.amountpaid) else 0 end as Registrationfees,
case when b.feerulecode = 2 then
sum(b.amountpaid) else 0 end as scanningfees,
0 as otherfees,
(case when b.feerulecode = 36 then
sum(b.amountpaid) else 0 end +
case when b.feerulecode = 1 then
sum(b.amountpaid) else 0 end +
case when b.feerulecode = 2 then
sum(b.amountpaid) else 0 end +
0) Total
from kaveri.documentmaster a join --kaveri.feesrequired b on a.documentid = b.documentid
kaverimis.vw_mis_revenue_report b on a.applicationnumber = b.applicationnumber
inner join  
 (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_srocode
     and amountpaid >=_minval and amountpaid<=_maxval and feerulecode=36)
     vw1 on b.applicationnumber=vw1.applicationnumber
join kaveri.sromaster c on a.srocode = c.srocode
where a.srocode = _srocode and a.registrationdatetime >= _fromdate and a.registrationdatetime < _todate
group by to_char(a.registrationdatetime,'Month-yyyy'),b.feerulecode;
elsif _choice = 2 then
return query 
select distinct to_char(a.registrationdatetime,'Month-yyyy') as month,
count(a.documentid) as NumberofDocuments,
case when b.feerulecode = 36 then
sum(b.amountpaid) else 0 end as stampduty,
case when b.feerulecode = 1 then
sum(b.amountpaid) else 0 end as Registrationfees,
case when b.feerulecode = 2 then
sum(b.amountpaid) else 0 end as scanningfees,
0 as otherfees,
(case when b.feerulecode = 36 then
sum(b.amountpaid) else 0 end +
case when b.feerulecode = 1 then
sum(b.amountpaid) else 0 end +
case when b.feerulecode = 2 then
sum(b.amountpaid) else 0 end +
0) Total
from kaveri.documentmaster a join --kaveri.feesrequired b on a.documentid = b.documentid
kaverimis.vw_mis_revenue_report b on a.applicationnumber = b.applicationnumber
inner join  
 (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_srocode
     and amountpaid >=_minval and amountpaid<=_maxval and feerulecode=1)
     vw1 on b.applicationnumber=vw1.applicationnumber
join kaveri.sromaster c on a.srocode = c.srocode
where a.srocode = _srocode and a.registrationdatetime >= _fromdate and a.registrationdatetime < _todate
group by to_char(a.registrationdatetime,'Month-yyyy'),b.feerulecode;
elsif _choice = 3 then
return query 
select distinct to_char(a.registrationdatetime,'Month-yyyy') as month,
count(a.documentid) as NumberofDocuments,
case when b.feerulecode = 36 then
sum(b.amountpaid) else 0 end as stampduty,
case when b.feerulecode = 1 then
sum(b.amountpaid) else 0 end as Registrationfees,
case when b.feerulecode = 2 then
sum(b.amountpaid) else 0 end as scanningfees,
0 as otherfees,
(case when b.feerulecode = 36 then
sum(b.amountpaid) else 0 end +
case when b.feerulecode = 1 then
sum(b.amountpaid) else 0 end +
case when b.feerulecode = 2 then
sum(b.amountpaid) else 0 end +
0) Total
from kaveri.documentmaster a join --kaveri.feesrequired b on a.documentid = b.documentid
kaverimis.vw_mis_revenue_report b on a.applicationnumber = b.applicationnumber
inner join  
 (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_srocode
     and amountpaid >=_minval and amountpaid<=_maxval and feerulecode=2)
     vw1 on b.applicationnumber=vw1.applicationnumber
join kaveri.sromaster c on a.srocode = c.srocode
where a.srocode = _srocode and a.registrationdatetime >= _fromdate and a.registrationdatetime < _todate
group by to_char(a.registrationdatetime,'Month-yyyy'),b.feerulecode;
elsif _choice = 4 then
return query 
select distinct to_char(a.registrationdatetime,'Month-yyyy') as month,
count(a.documentid) as NumberofDocuments,
case when b.feerulecode = 36 then
sum(b.amountpaid) else 0 end as stampduty,
case when b.feerulecode = 1 then
sum(b.amountpaid) else 0 end as Registrationfees,
case when b.feerulecode = 2 then
sum(b.amountpaid) else 0 end as scanningfees,
0 as otherfees,
(case when b.feerulecode = 36 then
sum(b.amountpaid) else 0 end +
case when b.feerulecode = 1 then
sum(b.amountpaid) else 0 end +
case when b.feerulecode = 2 then
sum(b.amountpaid) else 0 end +
0) Total
from kaveri.documentmaster a join --kaveri.feesrequired b on a.documentid = b.documentid
kaverimis.vw_mis_revenue_report b on a.applicationnumber = b.applicationnumber
inner join  
 (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_srocode
     and amountpaid >=_minval and amountpaid<=_maxval)
     vw1 on b.applicationnumber=vw1.applicationnumber
join kaveri.sromaster c on a.srocode = c.srocode
where a.srocode = _srocode and a.registrationdatetime >= _fromdate and a.registrationdatetime < _todate
group by to_char(a.registrationdatetime,'Month-yyyy'),b.feerulecode;
elsif _choice = 5 then
return query 
select distinct to_char(a.registrationdatetime,'Month-yyyy') as month,
count(a.documentid) as NumberofDocuments,
case when b.feerulecode = 36 then
sum(b.amountpaid) else 0 end as stampduty,
case when b.feerulecode = 1 then
sum(b.amountpaid) else 0 end as Registrationfees,
case when b.feerulecode = 2 then
sum(b.amountpaid) else 0 end as scanningfees,
0 as otherfees,
(case when b.feerulecode = 36 then
sum(b.amountpaid) else 0 end +
case when b.feerulecode = 1 then
sum(amountpaid) else 0 end +
case when b.feerulecode = 2 then
sum(b.amountpaid) else 0 end +
0) Total
