ALTER FUNCTION kaverimis.fn_mis_form17_details_of_collection_of_the_revenue(_srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer, _choice integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form17_details_of_stamp_duty_collected(integer, timestamp without time zone, timestamp without time zone, numeric, numeric, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form17_details_of_stamp_duty_collected(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer, _choice integer DEFAULT NULL::integer) RETURNS TABLE(sroofficename character varying, gift_and_pledge numeric, share_certificates numeric, licenses_of_movable_immovable numeric, contract_notes integer, comodities integer, from_freight_distribution_writings numeric, debenture_certificates numeric, insurance_policies numeric, others integer, totalfee numeric, franking integer, ten_acertification integer, grandtotal numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
if _choice = 1 then -- stamp duty
return query
select distinct b.sronamee as sroofficename,
	case when a.stamparticlecode = 29 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end as gift_and_pledge,
	case when a.stamparticlecode = 16 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end as share_certificates,
	case when a.stamparticlecode = 32 and d.feerulecode = 36  then
	sum(d.amountpaid) else 0 end as licenses_of_movable_immovable,
	0 as contract_notes,
	0 as comodities,
	case when a.stamparticlecode = 25 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end as From_freight_distribution_writings,
	case when a.stamparticlecode = 66 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end as Debenture_certificates,
	case when a.stamparticlecode = 68 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end as Insurance_policies,
	0 as others,
	(case when a.stamparticlecode = 29 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end +
	case when a.stamparticlecode = 16 and d.feerulecode = 36  then
	sum(d.amountpaid) else 0 end +
	case when a.stamparticlecode = 32 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end +
	0 +
	0 +
	case when a.stamparticlecode = 25 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end +
	case when a.stamparticlecode = 66 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end +
	case when a.stamparticlecode = 68 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end +
	0 ) as Totalfee,
	0 as franking,
	0 as ten_acertification,
	((case when a.stamparticlecode = 29 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end +
	case when a.stamparticlecode = 16 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end +
	case when a.stamparticlecode = 32 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end +
	0 +
	0 +
	case when a.stamparticlecode = 25 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end +
	case when a.stamparticlecode = 66 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end +
	case when a.stamparticlecode = 68 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end +
	0 ) + 0 + 0) GrandTotal
	from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
	join kaveri.stamparticles c on a.stamparticlecode = c.stamparticlecode
	--join kaveri.feesrequired d on a.srocode = d.srocode
	join kaverimis.vw_mis_revenue_report d on a.srocode = d.srocode
	inner join  
 (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_srocode
     and amountpaid >=_minval and amountpaid<=_maxval and feerulecode=36)
     vw1 on d.applicationnumber=vw1.applicationnumber
	where a.srocode = _srocode and isregistrationcompleted = false
	and a.registrationdatetime >= _from_date and a.registrationdatetime <= _to_date
	group by b.sronamee,a.stamparticlecode,a.registrationdatetime,
	d.feerulecode;
	elsif _choice = 2 then -- with min max
return query
select distinct b.sronamee as sroofficename,
	case when a.stamparticlecode = 29 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end as gift_and_pledge,
	case when a.stamparticlecode = 16 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end as share_certificates,
	case when a.stamparticlecode = 32 and d.feerulecode = 36  then
	sum(d.amountpaid) else 0 end as licenses_of_movable_immovable,
	0 as contract_notes,
	0 as comodities,
	case when a.stamparticlecode = 25 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end as From_freight_distribution_writings,
	case when a.stamparticlecode = 66 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end as Debenture_certificates,
	case when a.stamparticlecode = 68 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end as Insurance_policies,
	0 as others,
	(case when a.stamparticlecode = 29 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end +
	case when a.stamparticlecode = 16 and d.feerulecode = 36  then
	sum(d.amountpaid) else 0 end +
	case when a.stamparticlecode = 32 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end +
	0 +
	0 +
	case when a.stamparticlecode = 25 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end +
	case when a.stamparticlecode = 66 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end +
	case when a.stamparticlecode = 68 and d.feerulecode = 36 then
	sum(d.amountpaid) else 0 end +
	0 ) as Totalfee,
	0 as franking,
