ALTER FUNCTION kaverimis.fn_mis_form17_details_of_stamp_duty_collected_non_register(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer, _choice integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form20_details_of_will_deposited(integer, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form20_details_of_will_deposited(_srocode integer, _before_fy_from_date timestamp without time zone, _before_fy_to_date timestamp without time zone, _month_of_report_from_date timestamp without time zone, _month_of_report_to_date timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(nameofdroffice character varying, number_before_fy numeric, stampduty_before_fy numeric, registrationfee_before_fy numeric, scanningfee_before_fy numeric, otherfee_before_fy numeric, totalfee_before_fy numeric, number_month_of_report numeric, stampduty_month_of_report numeric, registrationfee_month_of_report numeric, scanningfee_month_of_report numeric, otherfee_month_of_report numeric, totalfee_month_of_report numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	 
return query
select distinct districtnamee as nameofdroffice,
sum(before_fy.number) as number_before_fy,
sum(before_fy.stampduty) as stampduty_before_fy,
sum(before_fy.registrationfee) as registrationfee_before_fy,
sum(before_fy.scanningfee)  as scanningfee_before_fy,
sum(before_fy.otherfee) as otherfee_before_fy,
(sum(before_fy.stampduty) + sum(before_fy.registrationfee) + sum(before_fy.scanningfee) + sum(before_fy.otherfee)) as 
Totalfee_before_fy,
sum(month_of_report.number) as number_month_of_report,
sum(month_of_report.stampduty) as stampduty_month_of_report,
sum(month_of_report.registrationfee) as registrationfee_month_of_report,
sum(month_of_report.scanningfee) as scanningfee_month_of_report,
sum(month_of_report.otherfee) as otherfee_month_of_report,
(sum(month_of_report.stampduty) + sum(month_of_report.registrationfee) + sum(month_of_report.scanningfee) + sum(month_of_report.otherfee))
Totalfee_month_of_report
from 
kaveri.sromaster a join kaveri.districtmaster c on a.districtcode = c.districtcode
join ( select b.srocode,
count(a.documentid) as number,
case when feerulecode = 36 and  stamparticlecode = 76  then
sum(amountpaid) else 0 end as stampduty,
case when feerulecode = 1 and stamparticlecode = 76 then
sum(amountpaid) else 0 end as registrationfee,
 case when feerulecode = 2 and stamparticlecode = 76 
	  then
sum(amountpaid) else 0 end as scanningfee,
	 case when feerulecode not in (1,36,2) and stamparticlecode = 76
	  then
sum(amountpaid) else 0 end as otherfee	
from kaveri.feesrequired a join kaveri.documentmaster b on a.documentid = b.documentid
	  where registrationdatetime >= _before_fy_from_date and
	registrationdatetime <= _before_fy_to_date  and b.srocode = _srocode and bookid = 5
group by b.srocode,feerulecode,stamparticlecode
)   before_fy on before_fy.srocode = a.srocode
join 
( select b.srocode,
count(a.documentid) as number,
case when feerulecode = 36 and stamparticlecode = 76 then
sum(amountpaid) else 0 end as stampduty,
case when feerulecode = 1 and stamparticlecode = 76 then
sum(amountpaid) else 0 end as registrationfee,

  case when feerulecode = 2 and stamparticlecode = 76 
	  then
sum(amountpaid) else 0 end as scanningfee,
	 case when feerulecode not in (1,36,2) and stamparticlecode = 76
	  then
sum(amountpaid) else 0 end as otherfee
 
from kaveri.feesrequired a join kaveri.documentmaster b on a.documentid = b.documentid
	  where registrationdatetime >= _month_of_report_from_date and
	registrationdatetime <= _month_of_report_to_date  and b.srocode = _srocode and bookid = 5
group by b.srocode,feerulecode,stamparticlecode
) month_of_report on before_fy.srocode = month_of_report.srocode
group by districtnamee;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form20_details_of_will_deposited(_srocode integer, _before_fy_from_date timestamp without time zone, _before_fy_to_date timestamp without time zone, _month_of_report_from_date timestamp without time zone, _month_of_report_to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form21_details_of_will_registered_book_3(integer[], timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form21_details_of_will_registered_book_3(_srocode integer[], _before_fy_from_date timestamp without time zone, _before_fy_to_date timestamp without time zone, _month_of_report_from_date timestamp without time zone, _month_of_report_to_date timestamp without time zone, _choice integer DEFAULT NULL::integer, _minval integer DEFAULT NULL::bigint, _maxval integer DEFAULT NULL::bigint) RETURNS TABLE(nameofsubregistrationoffice character varying, number_before_fy numeric, stampduty_before_fy numeric, registrationfee_before_fy numeric, number_month_of_report numeric, stampduty_month_of_report numeric, registrationfee_month_of_report numeric, totalnoofdocregistyered numeric, totalstampduty numeric, totalregistrationfee numeric, totalamount numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN	
	 

if _choice = 1 then -- Stampduty
				return query
				select distinct a.sronamee as nameofsubregistrationoffice,
				sum(before_fy.noofdoc) as number_before_fy,
				sum(before_fy.stampduty) as stampduty_before_fy,
				sum(before_fy.registrationfee) as registrationfee_before_fy,
				sum(month_of_report.noofdoc) as number_month_of_report,
				sum(month_of_report.stampduty) as stampduty_month_of_report,
				sum(month_of_report.registrationfee) as registrationfee_month_of_report,
				(sum(before_fy.noofdoc)+sum(month_of_report.noofdoc)) as Totalnoofdocregistyered,
				(sum(before_fy.stampduty)+sum(month_of_report.stampduty)) as TotalStampduty,
				(sum(before_fy.registrationfee) +sum(month_of_report.registrationfee)) as TotalRegistrationfee,
				(sum(before_fy.stampduty) + sum(before_fy.registrationfee)+
				sum(month_of_report.stampduty) + sum(month_of_report.registrationfee)) as Totalamount
				from 
				kaveri.sromaster a 
				join
						( select b.srocode,
						count(a.applicationnumber) as noofdoc,
						case when feerulecode = 36   then
						sum(amountpaid) else 0 end as stampduty,
						case when feerulecode = 1 then
						sum(amountpaid) else 0 end as registrationfee,	  
						case when feerulecode = 2 
						then sum(amountpaid) else 0 end as scanningfee,
						case when feerulecode not in (1,36,2) 
						then sum(amountpaid) else 0 end as otherfee	  
						from kaveri.documentmaster b 
						join
						(select applicationnumber from  kaveri.feesrequired  where srocode=any(_srocode) and amountpaid >=_minval and amountpaid<=_maxval and feerulecode=36)
						a on a.applicationnumber=b.applicationnumber
						join kaveri.feesrequired fr1 on fr1.applicationnumber=a.applicationnumber
						where b.isregistrationcompleted = true 
						and registrationdatetime >= _before_fy_from_date and
						registrationdatetime <= _before_fy_to_date  and b.srocode=any(_srocode) and bookid = 3
						group by b.srocode,feerulecode,stamparticlecode
						)   before_fy on before_fy.srocode = a.srocode
				join 
				( select b.srocode,
				count(a.applicationnumber) as noofdoc,
				case when feerulecode = 36 then
				sum(amountpaid) else 0 end as stampduty,
				case when feerulecode = 1  then
				sum(amountpaid) else 0 end as registrationfee,
				 case when feerulecode = 2 
					  then
				sum(amountpaid) else 0 end as scanningfee,
					 case when feerulecode not in (1,36,2) 
					  then
				sum(amountpaid) else 0 end as otherfee
				from kaveri.documentmaster b 
						join
						(select applicationnumber from  kaveri.feesrequired  where srocode=any(_srocode) and amountpaid >=_minval and amountpaid<=_maxval and feerulecode=36)
						a on a.applicationnumber=b.applicationnumber
						join kaveri.feesrequired fr1 on fr1.applicationnumber=a.applicationnumber
					  where b.isregistrationcompleted = true and registrationdatetime >= _month_of_report_from_date and
