		sum(case when feerulecode in (36,58,59) then
		amountpaid  else 0 end )as stampduty,
		sum(case when feerulecode = 1  then
		amountpaid else 0 end )as registrationfee,
		sum(case when feerulecode = 2 
		then
		amountpaid else 0 end )as scanningfee,
		sum(case when feerulecode not in (1,36,2,58,59) 
		then
		amountpaid else 0 end) as otherfee
		from kaveri.documentmaster b 
		join
		(select distinct applicationnumber,sum(amountpaid) from  kaveri.feesrequired 
		group by applicationnumber  having sum(amountpaid) >=_minval and sum(amountpaid)<=_maxval
		)a on a.applicationnumber=b.applicationnumber
		
		join kaveri.feesrequired fr1 on fr1.applicationnumber=b.applicationnumber
		where b.isregistrationcompleted = true and
		registrationdatetime::date >= _month_of_report_from_date and
		registrationdatetime::date <= _month_of_report_to_date
		and bookid = 3
		group by b.srocode
		) month_of_report on a.srocode = month_of_report.srocode
				
		where  
		dsm.districtcode=_districtcode 
		and a.srocode=_srocode

		group by a.sronamee	,dsm.districtnamee
		having  (sum(before_fy.noofdoc) is not null or sum(month_of_report.noofdoc) is not null)),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
						
		elsif _choice=0 then  --no min max
				
		return query
		with cte as (select distinct 
		dsm.districtnamee,
		a.sronamee as nameofsubregistrationoffice,
		sum(before_fy.noofdoc) as number_before_fy,
		sum(before_fy.stampduty) as stampduty_before_fy,
		sum(before_fy.registrationfee) as registrationfee_before_fy,
		sum(month_of_report.noofdoc) as number_month_of_report,
		sum(month_of_report.stampduty) as stampduty_month_of_report,
		sum(month_of_report.registrationfee) as registrationfee_month_of_report,
		(sum(before_fy.noofdoc)+sum(month_of_report.noofdoc)) as Totalnoofdocregistyered,
		(sum(before_fy.stampduty)+sum(month_of_report.stampduty)) as TotalStampduty,
		(sum(before_fy.registrationfee) +sum(month_of_report.registrationfee)) as TotalRegistrationfee,
		(sum(before_fy.stampduty) + sum(before_fy.registrationfee)+
		sum(month_of_report.stampduty) + sum(month_of_report.registrationfee)) as Totalamount
		from 
		kaveri.sromaster a 
		join kaveri.districtmaster dsm on dsm.districtcode=a.districtcode  
		left join
		( 
		select b.srocode,
		count(distinct b.applicationnumber) as noofdoc,
		sum(case when feerulecode in (36,58,59)   then
		amountpaid else 0 end) as stampduty,
		sum(case when feerulecode = 1 then
		amountpaid else 0 end) as registrationfee,	  
		sum(case when feerulecode = 2 
		then amountpaid else 0 end) as scanningfee,
		sum(case when feerulecode not in (1,36,2,58,59) 
		then amountpaid else 0 end) as otherfee	  
		from kaveri.documentmaster b 
		join kaveri.feesrequired fr1 on fr1.applicationnumber=b.applicationnumber
		where b.isregistrationcompleted = true 
		and registrationdatetime::date >= _before_fy_from_date and
		registrationdatetime::date <= _before_fy_to_date  
		and bookid = 3
		group by b.srocode
		)   before_fy on a.srocode= before_fy.srocode 
		left join 
		( select 
 		b.srocode,
		count(distinct b.applicationnumber) as noofdoc,
		sum(case when feerulecode in (36,58,59) then
		amountpaid  else 0 end )as stampduty,
		sum(case when feerulecode = 1  then
		amountpaid else 0 end )as registrationfee,
		sum(case when feerulecode = 2 
		then
		amountpaid else 0 end )as scanningfee,
		sum(case when feerulecode not in (1,36,2,58,59) 
		then
		amountpaid else 0 end) as otherfee
		from kaveri.documentmaster b 
		join kaveri.feesrequired fr1 on fr1.applicationnumber=b.applicationnumber
		where b.isregistrationcompleted = true and
		registrationdatetime::date >= _month_of_report_from_date and
		registrationdatetime::date <= _month_of_report_to_date
		and bookid = 3
		group by b.srocode
		) month_of_report on a.srocode = month_of_report.srocode
				
		where  
		dsm.districtcode=_districtcode 
		and a.srocode=_srocode

		group by a.sronamee	,dsm.districtnamee
		having  (sum(before_fy.noofdoc) is not null or sum(month_of_report.noofdoc) is not null)),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
	
				
		end if;
		
		end if;	

END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form21_details_of_will_registered_book_3_23012024(_districtcode bigint, _srocode bigint, _before_fy_from_date timestamp without time zone, _before_fy_to_date timestamp without time zone, _month_of_report_from_date timestamp without time zone, _month_of_report_to_date timestamp without time zone, _choice integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_form22_application_for_search_appl_cp_ec_cc(bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form22_application_for_search_appl_cp_ec_cc(_srocode bigint, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _documentnumber character varying DEFAULT NULL::character varying, _year integer DEFAULT 2022, _choice_ec_cc integer DEFAULT 0) RETURNS TABLE(district character varying, sro character varying, applicationnumber character varying, filepath text, property_desc text)
    LANGUAGE plpgsql
    AS $$


DECLARE

BEGIN	
_todate:=(_todate+'1 day'::interval);
if  (_fromdate is not NULL and _todate is not NULL) and (_choice_ec_cc=0)  then
	
	return query 
	    select  dsm.districtnamee as district,
		sr.sronamee as sro,eca.applicationnumber,eca.signedform22,
		string_agg(distinct h.typenameenglish ||' '||i.newpropertynumber,',')
		  from kaveri.ec_applicationdetails   eca
		  join	  kaveri.ec_propertynumberdetails i on i.ecid = eca.ecid
		  inner join kaveri.propertynotypemaster h  on  h.propertytypeid = i.propertynotypeid
		  join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode
		join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
		join kaveri.eccertificate ecir on ecir.applicationnumber = eca.applicationnumber 
		where eca.kaverisrocode=_srocode and eca.submitteddatetime>=_fromdate and eca.submitteddatetime <_todate  and 
		eca.signedform22 is not null
	group by dsm.districtnamee,sr.sronamee,eca.applicationnumber,ecir.certificatefile,eca.signedform22;
		
elseif (_documentnumber is null and _choice_ec_cc=1) then

return query 
select  dsm.districtnamee as district,
sr.sronamee as sro,ca.applicationnumber,ca.signedform22,
string_agg(distinct ptm.typenameenglish ||' '|| pnd.currentnumber,',')
from kaveri.cc_applicationdetails ca  
join kaveri.cc_documents cd  on cd.ccid = ca.ccid
join kaveri.documentmaster dm on dm.documentnumber::character varying=ca.documentnumber
join kaveri.propertymaster pm on pm.documentid=dm.documentid
join kaveri.propertynumberdetails pnd on pnd.propertyid = pm.propertyid
join kaveri.propertynotypemaster ptm on ptm.propertytypeid = pnd.currentpropertytypeid
join kaveri.sromaster sr on dm.srocode= sr.srocode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
where  dm.srocode=_srocode and  to_char(ca.submitteddatetime,'yyyy')::integer=_year  and ca.signedform22 is not null
group by dsm.districtnamee,sr.sronamee,ca.applicationnumber,ca.yearofregistration,cd.cccertificate,ca.signedform22;

else  

return query 

select  dsm.districtnamee as district,
sr.sronamee as sro,ca.applicationnumber,ca.signedform22,
string_agg(distinct ptm.typenameenglish ||' '|| pnd.currentnumber,',')
from kaveri.cc_applicationdetails ca  
join kaveri.cc_documents cd  on cd.ccid = ca.ccid
join kaveri.documentmaster dm on dm.documentnumber::character varying=ca.documentnumber
join kaveri.propertymaster pm on pm.documentid=dm.documentid
join kaveri.propertynumberdetails pnd on pnd.propertyid = pm.propertyid
join kaveri.propertynotypemaster ptm on ptm.propertytypeid = pnd.currentpropertytypeid
join kaveri.sromaster sr on dm.srocode= sr.srocode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
where  dm.srocode=_srocode and  to_char(ca.submitteddatetime,'yyyy')::integer=_year and ca.applicationnumber=_documentnumber
and ca.signedform22 is not null
group by dsm.districtnamee,sr.sronamee,ca.applicationnumber,ca.yearofregistration,cd.cccertificate,ca.signedform22;
	
	  
end if;
end;
$$;


