--
-- Name: fn_mis_form22_application_for_search_appl_cp_ec_cc(integer, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_form22_application_for_search_appl_cp_ec_cc(_districtcode integer, _srocode bigint, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _documentnumber character varying DEFAULT NULL::character varying, _year integer DEFAULT 2022, _choice_ec_cc integer DEFAULT 0, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, sro character varying, applicationnumber character varying, filepath text, property_desc text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);


if(_districtcode=0) THEN --All district
if  (_fromdate is not NULL and _todate is not NULL) and (_choice_ec_cc=0)  then
	
	return query 
	    with cte as (select  dsm.districtnamee as district,
		sr.sronamee as sro,eca.applicationnumber,eca.signedform22,
		string_agg(distinct h.typenameenglish ||' '||i.newpropertynumber,',')
		  from kaveri.ec_applicationdetails   eca
		   join kaveri.applicantapplicationdetails a on a.applicationnumber=eca.applicationnumber
		  join	  kaveri.ec_propertynumberdetails i on i.ecid = eca.ecid
		  inner join kaveri.propertynotypemaster h  on  h.propertytypeid = i.propertynotypeid
		  join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode 
		join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
		join kaveri.eccertificate ecir on ecir.applicationnumber = eca.applicationnumber 
where (eca.submitteddatetime  between _fromdate  and  _todate + INTERVAL '1 day') 
and eca.signedform22 is not null and a.currentstatus='CE110'
	group by dsm.districtnamee,sr.sronamee,eca.applicationnumber,ecir.certificatefile,eca.signedform22),
	cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
elseif (_documentnumber is null and _choice_ec_cc=1) then

return query 
with cte as (select  dsm.districtnamee as district,
sr.sronamee as sro,ca.applicationnumber,ca.signedform22,
string_agg(distinct ptm.typenameenglish ||' '|| pnd.currentnumber,',')
from kaveri.cc_applicationdetails ca 
join kaveri.applicantapplicationdetails a on a.applicationnumber=ca.applicationnumber
join kaveri.cc_documents cd  on cd.ccid = ca.ccid
join kaveri.documentmaster dm on dm.documentnumber::character varying=ca.documentnumber
join kaveri.propertymaster pm on pm.documentid=dm.documentid
join kaveri.propertynumberdetails pnd on pnd.propertyid = pm.propertyid
join kaveri.propertynotypemaster ptm on ptm.propertytypeid = pnd.currentpropertytypeid
join kaveri.sromaster sr on dm.srocode= sr.srocode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
where to_char(ca.submitteddatetime,'yyyy')::integer=_year  and ca.signedform22 is not null
and a.currentstatus='CC109'
group by dsm.districtnamee,sr.sronamee,ca.applicationnumber,ca.yearofregistration,cd.cccertificate,ca.signedform22),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

else  

return query 

with cte as (select  dsm.districtnamee as district,
sr.sronamee as sro,ca.applicationnumber,ca.signedform22,
string_agg(distinct ptm.typenameenglish ||' '|| pnd.currentnumber,',')
from kaveri.cc_applicationdetails ca 
join kaveri.applicantapplicationdetails a on a.applicationnumber=ca.applicationnumber
join kaveri.cc_documents cd  on cd.ccid = ca.ccid
join kaveri.documentmaster dm on dm.documentnumber::character varying=ca.documentnumber
join kaveri.propertymaster pm on pm.documentid=dm.documentid
join kaveri.propertynumberdetails pnd on pnd.propertyid = pm.propertyid
join kaveri.propertynotypemaster ptm on ptm.propertytypeid = pnd.currentpropertytypeid
join kaveri.sromaster sr on dm.srocode= sr.srocode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
where to_char(ca.submitteddatetime,'yyyy')::integer=_year and ca.applicationnumber=_documentnumber
and ca.signedform22 is not null and a.currentstatus='CC109'
group by dsm.districtnamee,sr.sronamee,ca.applicationnumber,ca.yearofregistration,cd.cccertificate,ca.signedform22),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

end if;
elseif(_srocode=0) then --Perticular District and All Sro
if  (_fromdate is not NULL and _todate is not NULL) and (_choice_ec_cc=0)  then
	
	return query 
	    with cte as (select  dsm.districtnamee as district,
		sr.sronamee as sro,eca.applicationnumber,eca.signedform22,
		string_agg(distinct h.typenameenglish ||' '||i.newpropertynumber,',')
		  from kaveri.ec_applicationdetails   eca
		  join kaveri.applicantapplicationdetails a on a.applicationnumber=eca.applicationnumber 

		  join	  kaveri.ec_propertynumberdetails i on i.ecid = eca.ecid
		  inner join kaveri.propertynotypemaster h  on  h.propertytypeid = i.propertynotypeid
		  join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode and sr.districtcode = _districtcode
		join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
		join kaveri.eccertificate ecir on ecir.applicationnumber = eca.applicationnumber 
where (eca.submitteddatetime  between _fromdate  and  _todate + INTERVAL '1 day')  
and eca.signedform22 is not null and a.currentstatus='CE110'
	group by dsm.districtnamee,sr.sronamee,eca.applicationnumber,ecir.certificatefile,eca.signedform22),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
elseif (_documentnumber is null and _choice_ec_cc=1) then

return query 
with cte as (select  dsm.districtnamee as district,
sr.sronamee as sro,ca.applicationnumber,ca.signedform22,
string_agg(distinct ptm.typenameenglish ||' '|| pnd.currentnumber,',')
from kaveri.cc_applicationdetails ca 
join kaveri.applicantapplicationdetails a on a.applicationnumber=eca.applicationnumber 

join kaveri.cc_documents cd  on cd.ccid = ca.ccid
join kaveri.documentmaster dm on dm.documentnumber::character varying=ca.documentnumber
join kaveri.propertymaster pm on pm.documentid=dm.documentid
join kaveri.propertynumberdetails pnd on pnd.propertyid = pm.propertyid
join kaveri.propertynotypemaster ptm on ptm.propertytypeid = pnd.currentpropertytypeid
join kaveri.sromaster sr on dm.srocode= sr.srocode and sr.districtcode = _districtcode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
where to_char(ca.submitteddatetime,'yyyy')::integer=_year  and ca.signedform22 is not null
and a.currentstatus='CC109'
group by dsm.districtnamee,sr.sronamee,ca.applicationnumber,ca.yearofregistration,cd.cccertificate,ca.signedform22),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

else  

return query 

with cte as (select  dsm.districtnamee as district,
sr.sronamee as sro,ca.applicationnumber,ca.signedform22,
string_agg(distinct ptm.typenameenglish ||' '|| pnd.currentnumber,',')
from kaveri.cc_applicationdetails ca  
join kaveri.applicantapplicationdetails a on a.applicationnumber=ca.applicationnumber 
join kaveri.cc_documents cd  on cd.ccid = ca.ccid
join kaveri.documentmaster dm on dm.documentnumber::character varying=ca.documentnumber
join kaveri.propertymaster pm on pm.documentid=dm.documentid
join kaveri.propertynumberdetails pnd on pnd.propertyid = pm.propertyid
join kaveri.propertynotypemaster ptm on ptm.propertytypeid = pnd.currentpropertytypeid
join kaveri.sromaster sr on dm.srocode= sr.srocode and sr.districtcode = _districtcode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
where to_char(ca.submitteddatetime,'yyyy')::integer=_year and ca.applicationnumber=_documentnumber 
and ca.signedform22 is not null and a.currentstatus='CC109'
group by dsm.districtnamee,sr.sronamee,ca.applicationnumber,ca.yearofregistration,cd.cccertificate,ca.signedform22),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

end if;
else
if  (_fromdate is not NULL and _todate is not NULL) and (_choice_ec_cc=0)  then
	
	return query 
	    with cte as (select  dsm.districtnamee as district,
		sr.sronamee as sro,eca.applicationnumber,eca.signedform22,
		string_agg(distinct h.typenameenglish ||' '||i.newpropertynumber,',')
		  from kaveri.ec_applicationdetails   eca
		  join kaveri.applicantapplicationdetails a on a.applicationnumber=eca.applicationnumber 
		  join	  kaveri.ec_propertynumberdetails i on i.ecid = eca.ecid
		  inner join kaveri.propertynotypemaster h  on  h.propertytypeid = i.propertynotypeid
		  join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode and sr.districtcode = _districtcode
		join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
		join kaveri.eccertificate ecir on ecir.applicationnumber = eca.applicationnumber 
		where eca.kaverisrocode=_srocode and (eca.submitteddatetime  between _fromdate  and  _todate + INTERVAL '1 day')  and 
		eca.signedform22 is not null and a.currentstatus='CE110'
	group by dsm.districtnamee,sr.sronamee,eca.applicationnumber,ecir.certificatefile,eca.signedform22),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
elseif (_documentnumber is null and _choice_ec_cc=1) then

return query 
with cte as (select  dsm.districtnamee as district,
sr.sronamee as sro,ca.applicationnumber,ca.signedform22,
string_agg(distinct ptm.typenameenglish ||' '|| pnd.currentnumber,',')
from kaveri.cc_applicationdetails ca  
join kaveri.applicantapplicationdetails a on a.applicationnumber=ca.applicationnumber 
join kaveri.cc_documents cd  on cd.ccid = ca.ccid
join kaveri.documentmaster dm on dm.documentnumber::character varying=ca.documentnumber
join kaveri.propertymaster pm on pm.documentid=dm.documentid
join kaveri.propertynumberdetails pnd on pnd.propertyid = pm.propertyid
join kaveri.propertynotypemaster ptm on ptm.propertytypeid = pnd.currentpropertytypeid
join kaveri.sromaster sr on dm.srocode= sr.srocode and sr.districtcode = _districtcode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
where  dm.srocode=_srocode and  to_char(ca.submitteddatetime,'yyyy')::integer=_year 
and ca.signedform22 is not null and a.currentstatus='CC109'
group by dsm.districtnamee,sr.sronamee,ca.applicationnumber,ca.yearofregistration,cd.cccertificate,ca.signedform22),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

else  

return query 

with cte as (select  dsm.districtnamee as district,
sr.sronamee as sro,ca.applicationnumber,ca.signedform22,
string_agg(distinct ptm.typenameenglish ||' '|| pnd.currentnumber,',')
from kaveri.cc_applicationdetails ca  
