--
-- Name: fn_mis_form22_details_of_ec_and_certified_copy(integer, integer, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_form22_details_of_ec_and_certified_copy(_districtcode integer, _srocode integer, _before_fy_from_date timestamp without time zone, _before_fy_to_date timestamp without time zone, _month_of_report_from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _month_of_report_to_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(drname character varying, nameofsubregistrationoffice character varying, ec_number_before_fy bigint, ec_fees_before_fy numeric, ec_number_on_the_month bigint, ec_fees_on_the_month numeric, cc_number_before_fy bigint, cc_stampduty_fees_before_fy numeric, cc_registrationfee_before_fy numeric, cc_number_on_the_month bigint, cc_stampduty_on_the_month numeric, cc_registrationfee_on_the_month numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
	

if(_districtcode=0)	 then

	if(_amounttype=0) then --no min max

		return query
				
			with cte as (select 
