return query
		select s.sronamee as nameofsubregistrationoffice,
		count(ec.ecid) as ec_number_before_fy,
		sum(ec.fees_month_before_2021_2022) as ec_fees_before_fy,
		count(ec1.number_on_the_month) as ec_number_on_the_month,
		sum(ec1.fees_on_the_month) as ec_fees_on_the_month,
		count(cc.ccid) as cc_number_before_fy,
		sum(cc.stampduty_month_before_2021_2022) as  cc_stampduty_fees_before_fy,
		sum(cc.Registrationfee_month_before_2021_2022) as cc_registrationfee_before_fy,
		count(cc1.ccid) as cc_number_on_the_month,
		sum(cc1.stampduty_number_on_the_month) as cc_stampduty_on_the_month,
		sum(cc1.registrationfee_number_on_the_month) as cc_registrationfee_on_the_month
		from kaveri.ec_applicationdetails a join
		(select distinct ecid,case when inserteddatetime >= _before_fy_from_date and inserteddatetime <= _before_fy_to_date then
		count(ecid)  else 0 end as number_month_before_2021_2022,
		case when inserteddatetime >= _before_fy_from_date and inserteddatetime <= _before_fy_to_date then
		sum(payableamount)  else 0 end as fees_month_before_2021_2022
		from kaveri.ec_requiredfees where serviceid = 13
		group by ecid,inserteddatetime) ec on a.ecid = ec.ecid
		join (select distinct ecid,case when inserteddatetime >= _month_of_report_from_date and inserteddatetime <= _month_of_report_to_date then
		count(ecid)  else 0 end as number_on_the_month,
		case when inserteddatetime >= _month_of_report_from_date and inserteddatetime <= _month_of_report_to_date then
		sum(payableamount)  else 0 end as fees_on_the_month
		from kaveri.ec_requiredfees where serviceid = 13
		group by ecid,inserteddatetime) ec1 on ec.ecid = ec1.ecid
		join kaveri.cc_applicationdetails b on a.kaverisrocode = b.kaverisrocode
		join kaveri.sromaster s on b.kaverisrocode = s.srocode
		join (select distinct ccid,inserteddatetime,
			  case when feeruleid = 36 then
		 sum(payableamount) else 0 end as stampduty_month_before_2021_2022,
		case when feeruleid = 1 then
		sum(payableamount)  else 0 end as Registrationfee_month_before_2021_2022
		from kaveri.cc_requiredfees where serviceid = 12 and inserteddatetime >= _before_fy_from_date and inserteddatetime <= _before_fy_to_date
		group by ccid,feeruleid,inserteddatetime) cc on b.ccid = cc.ccid
		join (select distinct ccid,
			  case when feeruleid = 36 then
		sum(payableamount)  else 0 end as stampduty_number_on_the_month,
		case when feeruleid = 1  then
		sum(payableamount)  else 0 end as registrationfee_number_on_the_month
		from kaveri.cc_requiredfees where serviceid = 12 and
			inserteddatetime >= _month_of_report_from_date and inserteddatetime <= _month_of_report_to_date  
		group by ccid,feeruleid) cc1 on cc.ccid = cc1.ccid	
		where b.kaverisrocode = _srocode
				group by s.sronamee;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form22_details_of_ec_and_certified_copy_backup_28_03_202(_srocode integer, _before_fy_from_date timestamp without time zone, _before_fy_to_date timestamp without time zone, _month_of_report_from_date timestamp without time zone, _month_of_report_to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form22_details_of_surcharge(bigint, date, date, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form22_details_of_surcharge(_srocode bigint, _fromdate date, _todate date, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(sroofficename character varying, total_number_of_doc_registered bigint, governmentstampfee numeric, bbmp numeric, citymuncipalcorporation numeric, townmuncipalcorporation numeric, townpanchayat numeric, municipality integer, talukpanchayat integer, bmrtl_cess numeric, registrationfee numeric, totalrevenue numeric, net_surcharge numeric, government_commission_10 numeric, government_commission_3 numeric, net_surcharge_2 numeric, totalsurcharge numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
return query 
select distinct b.sronamee as sroofficename,count(a.documentid) as Total_number_of_doc_registered,
case when (c.feerulecode = 89) then
(sum(c.amountpaid) * 5/100) else 0 end as governmentstampfee,
case when lower(d.descriptione) like lower('%bbmp%') then
((sum(d.regvalue) * 2) / 100) else 0 end as bbmp,
case when lower(d.descriptione) like lower('%city%') then
((sum(d.regvalue) * 2) / 100) else 0 end as citymuncipalcorporation,
case when lower(d.descriptione) like lower('%Town%') then
((sum(d.regvalue) * 2) / 100) else 0 end as townmuncipalcorporation,
case when lower(d.descriptione) like lower('%Town% %Panchayat%') then
((sum(d.regvalue) * 2) / 100) else 0 end as townpanchayat,
0 as Municipality,
0 as Talukpanchayat,
(case when lower(d.descriptione) like lower('%bbmp%') then
((sum(d.regvalue) * 2) / 100) else 0 end +
case when lower(d.descriptione) like lower('%city%') then
((sum(d.regvalue) * 2) / 100) else 0 end +
case when lower(d.descriptione) like lower('%Town%') then
((sum(d.regvalue) * 2) / 100) else 0 end +
case when lower(d.descriptione) like lower('%Town% %Panchayat%') then
((sum(d.regvalue) * 2) / 100) else 0 end ) as Net_Surcharge,
case when lower(d.descriptione) like lower('%government%')then
(sum(d.regvalue)*10/100) else 0 end as government_commission_10,
case when lower(d.descriptione) like lower('%government%')then
(sum(d.regvalue)*3/100) else 0 end as government_commission_3,

(case when lower(d.descriptione) like lower('%government%')then
(sum(d.regvalue)*10/100) else 0 end + 
case when lower(d.descriptione) like lower('%government%')then
(sum(d.regvalue)*3/100) else 0 end )as Net_Surcharge_2,

(case when lower(d.descriptione) like lower('%bbmp%') then
((sum(d.regvalue) * 2) / 100) else 0 end +
case when lower(d.descriptione) like lower('%city%') then
((sum(d.regvalue) * 2) / 100) else 0 end +
case when lower(d.descriptione) like lower('%Town%') then
((sum(d.regvalue) * 2) / 100) else 0 end +
case when lower(d.descriptione) like lower('%Town% %Panchayat%') then
((sum(d.regvalue) * 2) / 100) else 0 end +
case when lower(d.descriptione) like lower('%government%')then
(sum(d.regvalue)*10/100) else 0 end +
case when lower(d.descriptione) like lower('%government%')then
(sum(d.regvalue)*3/100) else 0 end ) as totalsurcharge,

(sum(d.value) * 10 /100) as bmrtl_cess,
case when c.feerulecode = 1 then
sum(c.amountpaid)  else 0 end as registrationfee,
((sum(d.value) * 10 /100) +
case when c.feerulecode = 1 then
sum(c.amountpaid)  else 0 end ) totalrevenue
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.feesrequired c on a.documentid = c.documentid
join kaveri.stamprules d on a.stamparticlecode = d.stamparticlecode
where a.srocode = _srocode and a.registrationdatetime >= _fromdate and a.registrationdatetime < _todate
and isregistrationcompleted = true
group by b.sronamee,c.feerulecode,d.descriptione
having ((sum(d.value) * 10 /100) +
case when c.feerulecode = 1 then
sum(c.amountpaid)  else 0 end ) >= _minval and ((sum(d.value) * 10 /100) +
case when c.feerulecode = 1 then
sum(c.amountpaid)  else 0 end ) < _maxval;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form22_details_of_surcharge(_srocode bigint, _fromdate date, _todate date, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form23_details_of_marriages_registration(integer, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form23_details_of_marriages_registration(_srocode integer, _before_fy_from_date timestamp without time zone, _before_fy_to_date timestamp without time zone, _inthemonth_from_date timestamp without time zone, _inthemonth_to_date timestamp without time zone, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(nameofsubregistrationoffice character varying, noofmarriages_hindumarriage_before_fy numeric, fees_hindumarriage_before_fy numeric, noofmarriages_specialmarriage_before_fy numeric, fees_specialmarriage_before_fy numeric, noofmarriages_specialmarriageotherforms_before_fy numeric, fees_specialmarriageotherforms_before_fy numeric, noofmarriages_hindumarriage_in_the_month bigint, fees_hindumarriage_in_the_month bigint, noofmarriages_specialmarriage_in_the_month bigint, fees_specialmarriage_in_the_month bigint, noofmarriages_specialmarriageotherforms_in_the_month bigint, fees_specialmarriageotherforms_in_the_month bigint, number_of_documents numeric, totalfees numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);		
	return query 
select
b.sronamee as nameofsubregistrationoffice,
sum(before_fy_2022_23.noofmarriages_Hindumarriage) as noofmarriages_Hindumarriage_before_fy ,
sum(before_fy_2022_23.fees_Hindumarriage) as fees_Hindumarriage_before_fy,
sum(before_fy_2022_23.noofmarriages_specialmarriage) as noofmarriages_specialmarriage_before_fy ,
sum(before_fy_2022_23.fees_specialmarriage) as fees_specialmarriage_before_fy ,
sum(before_fy_2022_23.noofmarriages_specialmarriageotherforms) as noofmarriages_specialmarriageotherforms_before_fy,
sum(before_fy_2022_23.fees_specialmarriageotherforms) as fees_specialmarriageotherforms_before_fy,
(in_the_month_of_reporting.noofmarriages_Hindumarriage) as noofmarriages_Hindumarriage_in_the_month,
(in_the_month_of_reporting.fees_Hindumarriage) as fees_Hindumarriage_in_the_month,
(in_the_month_of_reporting.noofmarriages_specialmarriage) as noofmarriages_specialmarriage_in_the_month,
(in_the_month_of_reporting.fees_specialmarriage) as fees_specialmarriage_in_the_month,
(in_the_month_of_reporting.noofmarriages_specialmarriageotherforms) as noofmarriages_specialmarriageotherforms_in_the_month,
(in_the_month_of_reporting.fees_specialmarriageotherforms) as fees_specialmarriageotherforms_in_the_month,
(sum(before_fy_2022_23.noofmarriages_Hindumarriage) + sum(in_the_month_of_reporting.noofmarriages_Hindumarriage)) number_of_documents,
(sum(before_fy_2022_23.fees_Hindumarriage) + sum(before_fy_2022_23.fees_specialmarriage) + sum(before_fy_2022_23.fees_specialmarriageotherforms)
) Totalfees
from kaveri.sromaster b
join (
select a.srocode,
case when a.marriagetypeid = 1 then
count(a.registrationid) else 0 end as noofmarriages_Hindumarriage,
case when a.marriagetypeid = 1 then
sum(feesreceived) else 0 end as fees_Hindumarriage,
case when a.marriagetypeid = 2 then
count(a.registrationid) else 0 end as noofmarriages_specialmarriage,
case when a.marriagetypeid = 2 then
sum(feesreceived) else 0 end as fees_specialmarriage,
case when a.marriagetypeid = 3 then
count(a.registrationid) else 0 end as noofmarriages_specialmarriageotherforms,
case when a.marriagetypeid = 3 then
sum(feesreceived) else 0 end as fees_specialmarriageotherforms from
kaveri.marriageregistration a  
join kaveri.marriagetype c on a.marriagetypeid = c.marriagetypeid
where dateofmarriage >= _before_fy_from_date and 
dateofmarriage <= _before_fy_to_date and a.srocode = _srocode
group by a.srocode,a.marriagetypeid
) before_fy_2022_23 on before_fy_2022_23.srocode = b.srocode
join
(
select a.srocode,
case when a.marriagetypeid = 1 then
count(a.registrationid) else 0 end as noofmarriages_Hindumarriage,
case when a.marriagetypeid = 1 then
sum(feesreceived) else 0 end as fees_Hindumarriage,
case when a.marriagetypeid = 2 then
count(a.registrationid) else 0 end as noofmarriages_specialmarriage,
case when a.marriagetypeid = 2 then
sum(feesreceived) else 0 end as fees_specialmarriage,
case when a.marriagetypeid = 3 then
count(a.registrationid) else 0 end as noofmarriages_specialmarriageotherforms,
case when a.marriagetypeid = 3 then
sum(feesreceived) else 0 end as fees_specialmarriageotherforms from
kaveri.marriageregistration a  
join kaveri.marriagetype c on a.marriagetypeid = c.marriagetypeid
where dateofmarriage >= _inthemonth_from_date and 
dateofmarriage <= _inthemonth_to_date and a.srocode = _srocode
group by a.srocode,a.marriagetypeid
) in_the_month_of_reporting on before_fy_2022_23.srocode = in_the_month_of_reporting.srocode
where in_the_month_of_reporting.srocode = _srocode  
group by b.sronamee,
(in_the_month_of_reporting.noofmarriages_Hindumarriage),
(in_the_month_of_reporting.fees_Hindumarriage),
(in_the_month_of_reporting.noofmarriages_specialmarriage),
(in_the_month_of_reporting.fees_specialmarriage),
(in_the_month_of_reporting.noofmarriages_specialmarriageotherforms),
(in_the_month_of_reporting.fees_specialmarriageotherforms)
having (sum(before_fy_2022_23.fees_Hindumarriage) + sum(before_fy_2022_23.fees_specialmarriage) + sum(before_fy_2022_23.fees_specialmarriageotherforms)
) >= _minval and (sum(before_fy_2022_23.fees_Hindumarriage) + sum(before_fy_2022_23.fees_specialmarriage) + sum(before_fy_2022_23.fees_specialmarriageotherforms)
) <= _maxval;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form23_details_of_marriages_registration(_srocode integer, _before_fy_from_date timestamp without time zone, _before_fy_to_date timestamp without time zone, _inthemonth_from_date timestamp without time zone, _inthemonth_to_date timestamp without time zone, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer) OWNER TO csgadmin;

