case when feerulecode = 58 and regionid = 4 then
(sum(e.amountpaid) * 2/100) else 0 end as Townpanchayat_Surcharge,
case when feerulecode = 58  then
(sum(e.amountpaid) * 10/100) else 0 end as Governmentcomission_Surcharge,
(case when feerulecode = 58 and regionid = 1 then
(sum(e.amountpaid) * 2/100) else 0 end +
case when feerulecode = 58 and regionid = 2 then
(sum(e.amountpaid) * 2/100) else 0 end +
case when feerulecode = 58 and regionid = 3 then
(sum(e.amountpaid) * 2/100) else 0 end +
case when feerulecode = 58 and regionid = 7 then
(sum(e.amountpaid) * 2/100) else 0 end +
case when feerulecode = 58 and regionid = 4 then
(sum(e.amountpaid) * 2/100) else 0 end ) as netsurcharge,
0 as Talukpanchayat_surcharge,
(sum(e.amountpaid) * 3/100) as government_comission,
(0 + (sum(e.amountpaid) * 3/100)) as netsurcharge_Talukpanchayat_government,
((case when feerulecode = 58 and regionid = 1 then
(sum(e.amountpaid) * 2/100) else 0 end +
case when feerulecode = 58 and regionid = 2 then
(sum(e.amountpaid) * 2/100) else 0 end +
case when feerulecode = 58 and regionid = 3 then
(sum(e.amountpaid) * 2/100) else 0 end +
case when feerulecode = 58 and regionid = 7 then
(sum(e.amountpaid) * 2/100) else 0 end +
case when feerulecode = 58 and regionid = 4 then
(sum(e.amountpaid) * 2/100) else 0 end ) +
(0 + (sum(e.amountpaid) * 3/100))) as Total_surcharge,
case when feerulecode = 36 then
(sum(e.amountpaid) * 10/100) else 0 end as bmrtl_cess_on_government_stamp_duty,
case when feerulecode = 1 then
sum(e.amountpaid) else 0 end as registrationfee,
(case when feerulecode = 36 then
(sum(e.amountpaid) * 5/100) else 0 end +
((case when feerulecode = 58 and regionid = 1 then
(sum(e.amountpaid) * 2/100) else 0 end +
case when feerulecode = 58 and regionid = 2 then
(sum(e.amountpaid) * 2/100) else 0 end +
case when feerulecode = 58 and regionid = 3 then
(sum(e.amountpaid) * 2/100) else 0 end +
case when feerulecode = 58 and regionid = 7 then
(sum(e.amountpaid) * 2/100) else 0 end +
case when feerulecode = 58 and regionid = 4 then
(sum(e.amountpaid) * 2/100) else 0 end ) +
(0 + (sum(e.amountpaid) * 3/100))) +
case when feerulecode = 36 then
(sum(e.amountpaid) * 10/100) else 0 end +
case when feerulecode = 1 then
sum(e.amountpaid) else 0 end) Totalrevenue
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.villagemaster c on b.srocode = c.srocode
join kaveri.roadmaster d on c.villagecode = d.villagecode
--join kaveri.feesrequired e on a.documentid = e.documentid
join
kaverimis.vw_mis_revenue_report e on a.applicationnumber = e.applicationnumber 
inner join  
 (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where srocode=_srocode
    )
     vw1 on e.applicationnumber=vw1.applicationnumber
where a.srocode = _srocode and a.registrationdatetime >= _from_date and 
a.registrationdatetime <= _to_date and a.isregistrationcompleted = true
group by 
b.sronamee,feerulecode,regionid;
end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form26_details_of_surcharge(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _minval integer, _maxval integer, pagenumber integer, pagesize integer, _choice integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form39_details_of_the_denoting_under_section_16(bigint, date, date, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form39_details_of_the_denoting_under_section_16(_srocode bigint, _fromdate date, _todate date, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(principaldeedno character varying, natureofdeed character varying, date timestamp without time zone, amountpaidinprincipaldeed numeric, documentnumber integer, natureofdeed_denoted text, date_denoted text, amountdenotated integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize); 	
return query 
select distinct 
a.finalregistrationnumber as principaldeedno,
b.articlenamee as natureofdeed,
a.registrationdatetime as date,
sum(c.amountpaid) as amountpaidinprincipaldeed,
a.documentnumber,
null as natureofdeed_denoted,
null as date_denoted,
0 as amountdenotated
from kaveri.documentmaster a join
kaveri.registrationarticles b on a.regarticlecode = b.regarticlecode
join kaveri.stamprules e on a.stamparticlecode = e.stamparticlecode
join kaveri.stampfeerulerelations d on e.stampruleid = d.stampruleid
join kaveri.feesrequired c on d.feerulecode = c.feerulecode
where a.regarticlecode in (
9,
16,
69,
91,
92,
100
) and isregistrationcompleted = true and a.srocode = _srocode and
registrationdatetime >= _fromdate and registrationdatetime <= _todate
group by a.finalregistrationnumber,
b.articlenamee,
a.registrationdatetime,
a.documentid,
a.documentnumber,
a.regarticlecode;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form39_details_of_the_denoting_under_section_16(_srocode bigint, _fromdate date, _todate date, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form3_details_sale_gift_mortgage_release_cancellation(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_form3_details_sale_gift_mortgage_release_cancellation(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, srooffice character varying, sale bigint, sale_withinfamilymembers bigint, sale_totalrevenue numeric, giftdeed bigint, giftdeedwithfamilymembers bigint, gift_totalrevenue numeric, releaseofrightdeeds bigint, releaseofrightdeeds_withinfamily bigint, release_totalrevenue numeric, leasedeeds bigint, leasedeeds_withinfamily bigint, lease_totalrevenue numeric, settlementdeeds bigint, settlementdeeds_withinfanily bigint, settlement_totalrevenue numeric, partitiondeed bigint, partitiondeed_withinfamily bigint, partition_totalrevenue numeric, exchangedeed bigint, exchangedeed_withinfamily bigint, exchange_totalrevenue numeric, mortgagedeedwithpossession bigint, mortgagedeedwithpossession_withinfamily bigint, mortgage_totalrevenue numeric, mortgagedeedwithoutpossession bigint, mortgagedeedwithoutpossession_withinfamily bigint, mortgagedeed_totalrevenue numeric, dtd integer, dtd_withinfamily integer, dtd_totalrevenue numeric, jda integer, jda_withinfamily integer, jda_totalrevenue numeric, cancellationdeed bigint, cancellationdeed_withinfamily bigint, cancellation_totalrevenue numeric, otherdeeds bigint, otherdeeds_withinfamily bigint, other_totalrevenue numeric, totalrevenue numeric, total bigint, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

declare
PageOffset integer:= 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
if (_districtcode = 0) then
	
		return query 
		
		with cte as (select distinct 
		d.districtnamee as districtname,
		b.sronamee as srooffice,
		count(distinct case when fr.stamparticlecode =21 then a.documentid else null end) as sale,
        count(distinct case when fr.stamparticlecode = 21 and pm.stampruleid = 0 then a.documentid end) as sale_withinfamilymembers,
		sum(case when fr.stamparticlecode = 21 then f.amountpaid else 0 end) as sale_totalrevenue,
		count(distinct case when fr.stamparticlecode = 29 then a.documentid else null end) as giftdeed,
		count(distinct case when fr.stamparticlecode = 29 and
		pm.stampruleid in (360,364,365,361,403,73,363) then a.documentid else null end) as giftdeed_withinfamilymembers,	
		sum(case when fr.stamparticlecode = 29 then f.amountpaid else 0 end)as gift_totalrevenue,	
		
		count(distinct case when fr.stamparticlecode = 47 then a.documentid else null end) as relaseofrightdeeds,
		count(distinct case when fr.stamparticlecode = 47 and pm.stampruleid =143 then a.documentid else null end) as relaseofrightdeeds_withinfamily,
		sum(case when fr.stamparticlecode = 47 then f.amountpaid else 0 end) as relase_totalrevenue,	
		
		count(distinct case when fr.stamparticlecode = 31 then a.documentid else null end) as leasedeeds,
		count(distinct case when fr.stamparticlecode = 31 and pm.stampruleid =252 then a.documentid else null end) as leasedeeds_withinfamily,
		sum(case when fr.stamparticlecode =31 then f.amountpaid else 0 end)as lease_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 50 then a.documentid else null end) as settlementdeeds,
		count(distinct case when fr.stamparticlecode = 50 and pm.stampruleid =150 then a.documentid else null end) as settlementdeeds_withinfamily,
		sum(case when fr.stamparticlecode =50 then f.amountpaid else 0 end) as settlement_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 41 then a.documentid else null end) as partitiondeed,	
		count(distinct case when fr.stamparticlecode = 41 and pm.stampruleid = 0 then a.documentid end) as partitiondeed_withinfamily,
		sum(case when fr.stamparticlecode =41 then f.amountpaid else 0 end) as partition_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 27 then a.documentid else null end) as Exchangedeed,
		count(distinct case when fr.stamparticlecode = 27 and pm.stampruleid = 0 then a.documentid end) as Exchangedeed_withinfamily,
		sum(case when fr.stamparticlecode =27 then f.amountpaid else 0 end) as Exchange_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 36 and pm.stampruleid=107 then a.documentid else null end) as Mortgagedeedwithpossession,
		count(distinct case when fr.stamparticlecode = 36 and pm.stampruleid = 0 then a.documentid end) as Mortgagedeedwithpossession_withinfamily,
		sum(case when fr.stamparticlecode =36 and pm.stampruleid in (107,0) then f.amountpaid else 0 end) as Mortgage_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 36 and pm.stampruleid=110 then a.documentid else null end) as Mortgagedeedwithoutpossession,
		count(distinct case when fr.stamparticlecode = 36 and  pm.stampruleid = 0 then a.documentid end) as Mortgagedeedwithoutpossession_withinfamily,
		sum(case when fr.stamparticlecode =36 and pm.stampruleid=110 then f.amountpaid else 0 end) as Mortgagedeed_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 6 then a.documentid else null end)::integer as DTD,
		count(distinct case when fr.stamparticlecode = 6 and pm.stampruleid = 0 then a.documentid end)::integer as DTD_withinfamily,
		sum( case when fr.stamparticlecode =6 then f.amountpaid else 0 end) as DTD_totalrevenue,
		
		count(distinct case when pm.stampruleid=339 then a.documentid else null end)::integer as JDA,
		count(distinct case when pm.stampruleid=0 then a.documentid else null end)::integer as JDA_withinfamily,
		sum(case when pm.stampruleid =339 then f.amountpaid else 0 end) as JDA_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 14 then a.documentid else null end) as CancellationDeed,
		count(distinct case when fr.stamparticlecode = 14 and pm.stampruleid=0 then a.documentid end) as CancellationDeed_withinfamily,
		sum(case when fr.stamparticlecode =14 then f.amountpaid else 0 end) as Cancellation_totalrevenue,
		
		count(distinct case when fr.stamparticlecode not in (21,29,47,31,50,41,27,36,6,14) then a.documentid else null end) as otherdeeds,
		count(distinct case when fr.stamparticlecode not in (21,29,47,31,50,41,27,36,6,14) 
		and pm.stampruleid not in(143,360,364,365,361,403,73,363,252,252,150,110,107) then a.documentid else null end) as otherdeeds_withinfamily,
		sum(case when fr.stamparticlecode not in (21,29,47,31,50,41,27,36,6,14) then f.amountpaid else 0 end) as other_totalrevenue,
		
		sum(f.amountpaid) as totalrevenue,
		count(distinct a.documentid) as Total
	
		from kaveri.documentmaster a 
		inner join 
		(select distinct applicationnumber,stamparticlecode,stampruleid from kaveri.propertymaster) 
		pm on a.applicationnumber =pm.applicationnumber 
		inner join kaveri.stampregrelations fr on a.regarticlecode  = fr.regarticlecode 
		inner join kaveri.feesrequired f on a.applicationnumber =f.applicationnumber  
		inner join kaveri.sromaster b on a.srocode  = b.srocode
		inner join kaveri.districtmaster d on b.districtcode = d.districtcode
		where 
		--a.srocode =_srocode and
		--b.districtcode = _districtcode and
		a.registrationdatetime ::date>= _fromdate and a.registrationdatetime ::date<=_todate
		and isregistrationcompleted = true  
		group by districtname,srooffice),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

		
		elsif ( _srocode = 0) then
	
	
		return query 
		
		with cte as (select distinct 
		d.districtnamee as districtname,
		b.sronamee as srooffice,
		count(distinct case when fr.stamparticlecode =21 then a.documentid else null end) as sale,
        count(distinct case when fr.stamparticlecode = 21 and pm.stampruleid = 0 then a.documentid end) as sale_withinfamilymembers,
		sum(case when fr.stamparticlecode = 21 then f.amountpaid else 0 end) as sale_totalrevenue,
		count(distinct case when fr.stamparticlecode = 29 then a.documentid else null end) as giftdeed,
		count(distinct case when fr.stamparticlecode = 29 and pm.stampruleid in (360,364,365,361,403,73,363) then a.documentid else null end) as giftdeed_withinfamilymembers,	
		sum(case when fr.stamparticlecode = 29 then f.amountpaid else 0 end)as gift_totalrevenue,	
		
		count(distinct case when fr.stamparticlecode = 47 then a.documentid else null end) as relaseofrightdeeds,
		count(distinct case when fr.stamparticlecode = 47 and pm.stampruleid =143 then a.documentid else null end) as relaseofrightdeeds_withinfamily,
		sum(case when fr.stamparticlecode = 47 then f.amountpaid else 0 end) as relase_totalrevenue,	
		
		count(distinct case when fr.stamparticlecode = 31 then a.documentid else null end) as leasedeeds,
		count(distinct case when fr.stamparticlecode = 31 and pm.stampruleid =252 then a.documentid else null end) as leasedeeds_withinfamily,
		sum(case when fr.stamparticlecode =31 then f.amountpaid else 0 end)as lease_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 50 then a.documentid else null end) as settlementdeeds,
		count(distinct case when fr.stamparticlecode = 50 and pm.stampruleid =150 then a.documentid else null end) as settlementdeeds_withinfamily,
		sum(case when fr.stamparticlecode =50 then f.amountpaid else 0 end) as settlement_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 41 then a.documentid else null end) as partitiondeed,	
		count(distinct case when fr.stamparticlecode = 41 and pm.stampruleid = 0 then a.documentid end) as partitiondeed_withinfamily,
		sum(case when fr.stamparticlecode =41 then f.amountpaid else 0 end) as partition_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 27 then a.documentid else null end) as Exchangedeed,
		count(distinct case when fr.stamparticlecode = 27 and pm.stampruleid = 0 then a.documentid end) as Exchangedeed_withinfamily,
		sum(case when fr.stamparticlecode =27 then f.amountpaid else 0 end) as Exchange_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 36 and pm.stampruleid=107 then a.documentid else null end) as Mortgagedeedwithpossession,
		count(distinct case when fr.stamparticlecode = 36 and pm.stampruleid = 0 then a.documentid end) as Mortgagedeedwithpossession_withinfamily,
		sum(case when fr.stamparticlecode =36 and pm.stampruleid in (107,0) then f.amountpaid else 0 end) as Mortgage_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 36 and pm.stampruleid=110 then a.documentid else null end) as Mortgagedeedwithoutpossession,
		count(distinct case when fr.stamparticlecode = 36 and  pm.stampruleid = 0 then a.documentid end) as Mortgagedeedwithoutpossession_withinfamily,
		sum(case when fr.stamparticlecode =36 and pm.stampruleid=110 then f.amountpaid else 0 end) as Mortgagedeed_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 6 then a.documentid else null end)::integer as DTD,
		count(distinct case when fr.stamparticlecode = 6 and pm.stampruleid = 0 then a.documentid end)::integer as DTD_withinfamily,
		sum( case when fr.stamparticlecode =6 then f.amountpaid else 0 end) as DTD_totalrevenue,
		
		count(distinct case when pm.stampruleid=339 then a.documentid else null end)::integer as JDA,
		count(distinct case when pm.stampruleid=0 then a.documentid else null end)::integer as JDA_withinfamily,
		sum(case when pm.stampruleid =339 then f.amountpaid else 0 end) as JDA_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 14 then a.documentid else null end) as CancellationDeed,
		count(distinct case when fr.stamparticlecode = 14 and pm.stampruleid=0 then a.documentid end) as CancellationDeed_withinfamily,
		sum(case when fr.stamparticlecode =14 then f.amountpaid else 0 end) as Cancellation_totalrevenue,
		
		count(distinct case when fr.stamparticlecode not in (21,29,47,31,50,41,27,36,6,14) then a.documentid else null end) as otherdeeds,
		count(distinct case when fr.stamparticlecode not in (21,29,47,31,50,41,27,36,6,14) and pm.stampruleid not in(143,360,364,365,361,403,73,363,252,252,150,110,107) then a.documentid else null end) as otherdeeds_withinfamily,
		sum(case when fr.stamparticlecode not in (21,29,47,31,50,41,27,36,6,14) then f.amountpaid else 0 end) as other_totalrevenue,
		
		sum(f.amountpaid) as totalrevenue,
		count(distinct a.documentid) as Total
	
		from kaveri.documentmaster a 
		inner join (select distinct applicationnumber,stamparticlecode,stampruleid from kaveri.propertymaster) pm on a.applicationnumber =pm.applicationnumber 
		inner join kaveri.stampregrelations fr on a.regarticlecode  = fr.regarticlecode 
		inner join kaveri.feesrequired f on a.applicationnumber =f.applicationnumber  
		inner join kaveri.sromaster b on a.srocode  = b.srocode
		inner join kaveri.districtmaster d on b.districtcode = d.districtcode
		where 
		--a.srocode =_srocode and
		b.districtcode = _districtcode and
		a.registrationdatetime ::date>= _fromdate and a.registrationdatetime ::date<=_todate
		and isregistrationcompleted = true  
		group by districtname,srooffice),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
		
		else 
			
	
		return query 
		
				with cte as (select distinct 
		d.districtnamee as districtname,
		b.sronamee as srooffice,
		count(distinct case when fr.stamparticlecode =21 then a.documentid else null end) as sale,
        count(distinct case when fr.stamparticlecode = 21 and pm.stampruleid = 0 then a.documentid end) as sale_withinfamilymembers,
		sum(case when fr.stamparticlecode = 21 then f.amountpaid else 0 end) as sale_totalrevenue,
		count(distinct case when fr.stamparticlecode = 29 then a.documentid else null end) as giftdeed,
		count(distinct case when fr.stamparticlecode = 29 and pm.stampruleid in (360,364,365,361,403,73,363) then a.documentid else null end) as giftdeed_withinfamilymembers,	
		sum(case when fr.stamparticlecode = 29 then f.amountpaid else 0 end)as gift_totalrevenue,	
		
		count(distinct case when fr.stamparticlecode = 47 then a.documentid else null end) as relaseofrightdeeds,
		count(distinct case when fr.stamparticlecode = 47 and pm.stampruleid =143 then a.documentid else null end) as relaseofrightdeeds_withinfamily,
		sum(case when fr.stamparticlecode = 47 then f.amountpaid else 0 end) as relase_totalrevenue,	
		
		count(distinct case when fr.stamparticlecode = 31 then a.documentid else null end) as leasedeeds,
		count(distinct case when fr.stamparticlecode = 31 and pm.stampruleid =252 then a.documentid else null end) as leasedeeds_withinfamily,
		sum(case when fr.stamparticlecode =31 then f.amountpaid else 0 end)as lease_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 50 then a.documentid else null end) as settlementdeeds,
		count(distinct case when fr.stamparticlecode = 50 and pm.stampruleid =150 then a.documentid else null end) as settlementdeeds_withinfamily,
		sum(case when fr.stamparticlecode =50 then f.amountpaid else 0 end) as settlement_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 41 then a.documentid else null end) as partitiondeed,	
		count(distinct case when fr.stamparticlecode = 41 and pm.stampruleid = 0 then a.documentid end) as partitiondeed_withinfamily,
		sum(case when fr.stamparticlecode =41 then f.amountpaid else 0 end) as partition_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 27 then a.documentid else null end) as Exchangedeed,
		count(distinct case when fr.stamparticlecode = 27 and pm.stampruleid = 0 then a.documentid end) as Exchangedeed_withinfamily,
		sum(case when fr.stamparticlecode =27 then f.amountpaid else 0 end) as Exchange_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 36 and pm.stampruleid=107 then a.documentid else null end) as Mortgagedeedwithpossession,
		count(distinct case when fr.stamparticlecode = 36 and pm.stampruleid = 0 then a.documentid end) as Mortgagedeedwithpossession_withinfamily,
		sum(case when fr.stamparticlecode =36 and pm.stampruleid in (107,0) then f.amountpaid else 0 end) as Mortgage_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 36 and pm.stampruleid=110 then a.documentid else null end) as Mortgagedeedwithoutpossession,
		count(distinct case when fr.stamparticlecode = 36 and  pm.stampruleid = 0 then a.documentid end) as Mortgagedeedwithoutpossession_withinfamily,
		sum(case when fr.stamparticlecode =36 and pm.stampruleid=110 then f.amountpaid else 0 end) as Mortgagedeed_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 6 then a.documentid else null end)::integer as DTD,
		count(distinct case when fr.stamparticlecode = 6 and pm.stampruleid = 0 then a.documentid end)::integer as DTD_withinfamily,
		sum( case when fr.stamparticlecode =6 then f.amountpaid else 0 end) as DTD_totalrevenue,
		
		count(distinct case when pm.stampruleid=339 then a.documentid else null end)::integer as JDA,
		count(distinct case when pm.stampruleid=0 then a.documentid else null end)::integer as JDA_withinfamily,
		sum(case when pm.stampruleid =339 then f.amountpaid else 0 end) as JDA_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 14 then a.documentid else null end) as CancellationDeed,
		count(distinct case when fr.stamparticlecode = 14 and pm.stampruleid=0 then a.documentid end) as CancellationDeed_withinfamily,
		sum(case when fr.stamparticlecode =14 then f.amountpaid else 0 end) as Cancellation_totalrevenue,
		
		count(distinct case when fr.stamparticlecode not in (21,29,47,31,50,41,27,36,6,14) then a.documentid else null end) as otherdeeds,
		count(distinct case when fr.stamparticlecode not in (21,29,47,31,50,41,27,36,6,14) and pm.stampruleid not in(143,360,364,365,361,403,73,363,252,252,150,110,107) then a.documentid else null end) as otherdeeds_withinfamily,
		sum(case when fr.stamparticlecode not in (21,29,47,31,50,41,27,36,6,14) then f.amountpaid else 0 end) as other_totalrevenue,
		
		sum(f.amountpaid) as totalrevenue,
		count(distinct a.documentid) as Total
	
		from kaveri.documentmaster a 
		inner join (select distinct applicationnumber,stamparticlecode,stampruleid from kaveri.propertymaster) pm on a.applicationnumber =pm.applicationnumber 
		inner join kaveri.stampregrelations fr on a.regarticlecode  = fr.regarticlecode 
		inner join kaveri.feesrequired f on a.applicationnumber =f.applicationnumber  
		inner join kaveri.sromaster b on a.srocode  = b.srocode
		inner join kaveri.districtmaster d on b.districtcode = d.districtcode
		where 
		a.srocode =_srocode and
		b.districtcode = _districtcode and
		a.registrationdatetime ::date>= _fromdate and a.registrationdatetime ::date<=_todate
		and isregistrationcompleted = true  
		group by districtname,srooffice),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
		end if;
	

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_form3_details_sale_gift_mortgage_release_cancellation(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_form3_details_sale_gift_mortgage_release_cancellation(integer, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form3_details_sale_gift_mortgage_release_cancellation(_srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _flag integer, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(srooffice character varying, sale bigint, giftdeed bigint, giftdeedwithfamilymembers bigint, releaseofrightdeeds bigint, releaseofrightdeeds_withinfamily bigint, leasedeeds bigint, leasedeeds_withinfamily bigint, settlementdeeds bigint, settlementdeeds_withinfanily bigint, partitiondeed bigint, exchangedeed bigint, mortgagedeedwithpossession bigint, mortgagedeedwithoutpossession bigint, dtd integer, jda integer, cancellationdeed bigint, otherdeeds bigint, total bigint)
    LANGUAGE plpgsql
    AS $$
declare
PageOffset integer;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
if _flag = 0 then
return query 
select distinct b.sronamee as srooffice,
count(distinct case when pm.stamparticlecode = 21 then
a.documentid else 0 end) as sale,
count(distinct case when pm.stamparticlecode = 29 then
a.documentid else null end) as giftdeed,--pm.stamparticlecode
count(distinct case when pm.stamparticlecode = 29 and pm.stampruleid in (403,73,360,361) then
a.documentid else 0 end) as giftdeedwithinfamilymembers,
count(distinct case when pm.stamparticlecode = 47 then
a.documentid else 0 end) as relaseofrightdeeds,
count(distinct case when pm.stamparticlecode = 47 and pm.stampruleid=143 then
a.documentid else 0 end) as relaseofrightdeeds_withinfamily,
count(distinct case when pm.stamparticlecode = 31 then
a.documentid else 0 end) as leasedeeds,
count(distinct case when pm.stamparticlecode = 31 and pm.stampruleid=252 then
a.documentid else 0 end) as leasedeeds_withinfamily,
count(distinct case when pm.stamparticlecode = 50 then
a.documentid else 0 end) as settlementdeeds,
count(distinct case when pm.stamparticlecode = 50 and pm.stampruleid=150 then
a.documentid else 0 end) as settlementdeeds_withinfanily,
count(distinct case when pm.stamparticlecode = 41 then
a.documentid else 0 end) as partitiondeed,
count(distinct case when pm.stamparticlecode = 27 then
a.documentid else 0 end) as Exchangedeed,
count(distinct case when pm.stamparticlecode = 36 and pm.stampruleid=107 then
a.documentid else 0 end) as Mortgagedeedwithpossession,
count(distinct case when pm.stamparticlecode = 36 and pm.stampruleid=110 then
a.documentid else 0 end) as Mortgagedeedwithoutpossession,
count(distinct case when pm.stamparticlecode = 6 then
a.documentid else 0 end)::integer as DTD,
count(distinct case when pm.stampruleid=339 then
a.documentid else 0 end)::integer as JDA,
count(distinct case when pm.stamparticlecode = 14 then
a.documentid else 0 end) as CancellationDeed,
count(distinct case when pm.stamparticlecode not in (21,29,47,31,50,41,27,36,6,14) and pm.stampruleid!=339 then
a.documentid else 0 end) as otherdeeds,
count(distinct a.documentid) as Total
from kaveri.documentmaster a inner join kaveri.propertymaster pm on a.documentid=pm.documentid inner join kaveri.sromaster b on a.srocode = b.srocode
where a.srocode = _srocode and a.registrationdatetime >= _fromdate and a.registrationdatetime < _todate
and isregistrationcompleted = true  
group by (b.sronamee)
having count(distinct a.documentid) >= _minval and
count(distinct a.documentid) <= _maxval;
elsif (_flag = 1) then
return query 
select distinct b.sronamee as srooffice,
count(distinct case when pm.stamparticlecode = 21 then
a.documentid else 0 end) as sale,
count(distinct case when pm.stamparticlecode = 29 then
a.documentid else null end) as giftdeed,--pm.stamparticlecode
count(distinct case when pm.stamparticlecode = 29 and pm.stampruleid in (403,73,360,361) then
a.documentid else 0 end) as giftdeedwithinfamilymembers,
count(distinct case when pm.stamparticlecode = 47 then
a.documentid else 0 end) as relaseofrightdeeds,
count(distinct case when pm.stamparticlecode = 47 and pm.stampruleid=143 then
a.documentid else 0 end) as relaseofrightdeeds_withinfamily,
count(distinct case when pm.stamparticlecode = 31 then
a.documentid else 0 end) as leasedeeds,
count(distinct case when pm.stamparticlecode = 31 and pm.stampruleid=252 then
a.documentid else 0 end) as leasedeeds_withinfamily,
count(distinct case when pm.stamparticlecode = 50 then
a.documentid else 0 end) as settlementdeeds,
count(distinct case when pm.stamparticlecode = 50 and pm.stampruleid=150 then
a.documentid else 0 end) as settlementdeeds_withinfanily,
count(distinct case when pm.stamparticlecode = 41 then
a.documentid else 0 end) as partitiondeed,
count(distinct case when pm.stamparticlecode = 27 then
a.documentid else 0 end) as Exchangedeed,
count(distinct case when pm.stamparticlecode = 36 and pm.stampruleid=107 then
a.documentid else 0 end) as Mortgagedeedwithpossession,
count(distinct case when pm.stamparticlecode = 36 and pm.stampruleid=110 then
a.documentid else 0 end) as Mortgagedeedwithoutpossession,
count(distinct case when pm.stamparticlecode = 6 then
a.documentid else 0 end)::integer as DTD,
count(distinct case when pm.stampruleid=339 then
a.documentid else 0 end)::integer as JDA,
count(distinct case when pm.stamparticlecode = 14 then
a.documentid else 0 end) as CancellationDeed,
count(distinct case when pm.stamparticlecode not in (21,29,47,31,50,41,27,36,6,14) and pm.stampruleid!=339 then
a.documentid else 0 end) as otherdeeds,
count(distinct a.documentid) as Total
from kaveri.documentmaster a inner join kaveri.propertymaster pm on a.documentid=pm.documentid inner join kaveri.sromaster b on a.srocode = b.srocode
where a.srocode = _srocode and a.registrationdatetime >= _fromdate and a.registrationdatetime < _todate
and isregistrationcompleted = true  
group by (b.sronamee);
/*having count(distinct a.documentid) >= _minval and
count(distinct a.documentid) <= _maxval;*/
end if;
END;
$$;


