		sum(case when fr.stamparticlecode =14 then f.amountpaid else 0 end) as Cancellation_totalrevenue,
		
		count(distinct case when fr.stamparticlecode not in (21,29,47,31,50,41,27,36,6,14) then a.documentid else null end) as otherdeeds,
		count(distinct case when fr.stamparticlecode not in (21,29,47,31,50,41,27,36,6,14) and pm.stampruleid not in(143,403,73,360,361,252,252,150,110,107) then a.documentid else null end) as otherdeeds_withinfamily,
		sum(case when fr.stamparticlecode not in (21,29,47,31,50,41,27,36,6,14) then f.amountpaid else 0 end) as other_totalrevenue,
		
		sum(f.amountpaid) as totalrevenue,
		count(distinct a.documentid) as Total
	
		from kaveri.documentmaster a 
		inner join (select distinct applicationnumber,stamparticlecode,stampruleid from kaveri.propertymaster) pm on a.applicationnumber =pm.applicationnumber 
		inner join kaveri.stampregrelations fr on a.regarticlecode  = fr.regarticlecode 
		inner join kaveri.feesrequired f on a.applicationnumber =f.applicationnumber  
		inner join kaveri.sromaster b on a.srocode  = b.srocode
		inner join kaveri.districtmaster d on b.districtcode = d.districtcode
		where 
		--a.srocode =_srocode and
		b.districtcode = _districtcode and
		a.registrationdatetime ::date>= _fromdate and a.registrationdatetime ::date<=_todate
		and isregistrationcompleted = true  
		group by districtname,srooffice),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
		
		else 
			
	
		return query 
		
				with cte as (select distinct 
		d.districtnamee as districtname,
		b.sronamee as srooffice,
		count(distinct case when fr.stamparticlecode =21 then a.documentid else null end) as sale,
        count(distinct case when fr.stamparticlecode = 21 and pm.stampruleid = 0 then a.documentid end) as sale_withinfamilymembers,
		sum(case when fr.stamparticlecode = 21 then f.amountpaid else 0 end) as sale_totalrevenue,
		count(distinct case when fr.stamparticlecode = 29 then a.documentid else null end) as giftdeed,
		count(distinct case when fr.stamparticlecode = 29 and pm.stampruleid in (403,73,360,361) then a.documentid else null end) as giftdeed_withinfamilymembers,	
		sum(case when fr.stamparticlecode = 29 then f.amountpaid else 0 end)as gift_totalrevenue,	
		
		count(distinct case when fr.stamparticlecode = 47 then a.documentid else null end) as relaseofrightdeeds,
		count(distinct case when fr.stamparticlecode = 47 and pm.stampruleid =143 then a.documentid else null end) as relaseofrightdeeds_withinfamily,
		sum(case when fr.stamparticlecode = 47 then f.amountpaid else 0 end) as relase_totalrevenue,	
		
		count(distinct case when fr.stamparticlecode = 31 then a.documentid else null end) as leasedeeds,
		count(distinct case when fr.stamparticlecode = 31 and pm.stampruleid =252 then a.documentid else null end) as leasedeeds_withinfamily,
		sum(case when fr.stamparticlecode =31 then f.amountpaid else 0 end)as lease_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 50 then a.documentid else null end) as settlementdeeds,
		count(distinct case when fr.stamparticlecode = 50 and pm.stampruleid =150 then a.documentid else null end) as settlementdeeds_withinfamily,
		sum(case when fr.stamparticlecode =50 then f.amountpaid else 0 end) as settlement_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 41 then a.documentid else null end) as partitiondeed,	
		count(distinct case when fr.stamparticlecode = 41 and pm.stampruleid = 0 then a.documentid end) as partitiondeed_withinfamily,
		sum(case when fr.stamparticlecode =41 then f.amountpaid else 0 end) as partition_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 27 then a.documentid else null end) as Exchangedeed,
		count(distinct case when fr.stamparticlecode = 27 and pm.stampruleid = 0 then a.documentid end) as Exchangedeed_withinfamily,
		sum(case when fr.stamparticlecode =27 then f.amountpaid else 0 end) as Exchange_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 36 and pm.stampruleid=107 then a.documentid else null end) as Mortgagedeedwithpossession,
		count(distinct case when fr.stamparticlecode = 36 and pm.stampruleid = 0 then a.documentid end) as Mortgagedeedwithpossession_withinfamily,
		sum(case when fr.stamparticlecode =36 and pm.stampruleid in (107,0) then f.amountpaid else 0 end) as Mortgage_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 36 and pm.stampruleid=110 then a.documentid else null end) as Mortgagedeedwithoutpossession,
		count(distinct case when fr.stamparticlecode = 36 and  pm.stampruleid = 0 then a.documentid end) as Mortgagedeedwithoutpossession_withinfamily,
		sum(case when fr.stamparticlecode =36 and pm.stampruleid=110 then f.amountpaid else 0 end) as Mortgagedeed_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 6 then a.documentid else null end)::integer as DTD,
		count(distinct case when fr.stamparticlecode = 6 and pm.stampruleid = 0 then a.documentid end)::integer as DTD_withinfamily,
		sum( case when fr.stamparticlecode =6 then f.amountpaid else 0 end) as DTD_totalrevenue,
		
		count(distinct case when pm.stampruleid=339 then a.documentid else null end)::integer as JDA,
		count(distinct case when pm.stampruleid=0 then a.documentid else null end)::integer as JDA_withinfamily,
		sum(case when pm.stampruleid =339 then f.amountpaid else 0 end) as JDA_totalrevenue,
		
		count(distinct case when fr.stamparticlecode = 14 then a.documentid else null end) as CancellationDeed,
		count(distinct case when fr.stamparticlecode = 14 and pm.stampruleid=0 then a.documentid end) as CancellationDeed_withinfamily,
		sum(case when fr.stamparticlecode =14 then f.amountpaid else 0 end) as Cancellation_totalrevenue,
		
		count(distinct case when fr.stamparticlecode not in (21,29,47,31,50,41,27,36,6,14) then a.documentid else null end) as otherdeeds,
		count(distinct case when fr.stamparticlecode not in (21,29,47,31,50,41,27,36,6,14) and pm.stampruleid not in(143,403,73,360,361,252,252,150,110,107) then a.documentid else null end) as otherdeeds_withinfamily,
		sum(case when fr.stamparticlecode not in (21,29,47,31,50,41,27,36,6,14) then f.amountpaid else 0 end) as other_totalrevenue,
		
		sum(f.amountpaid) as totalrevenue,
		count(distinct a.documentid) as Total
	
		from kaveri.documentmaster a 
		inner join (select distinct applicationnumber,stamparticlecode,stampruleid from kaveri.propertymaster) pm on a.applicationnumber =pm.applicationnumber 
		inner join kaveri.stampregrelations fr on a.regarticlecode  = fr.regarticlecode 
		inner join kaveri.feesrequired f on a.applicationnumber =f.applicationnumber  
		inner join kaveri.sromaster b on a.srocode  = b.srocode
		inner join kaveri.districtmaster d on b.districtcode = d.districtcode
		where 
		a.srocode =_srocode and
		b.districtcode = _districtcode and
		a.registrationdatetime ::date>= _fromdate and a.registrationdatetime ::date<=_todate
		and isregistrationcompleted = true  
		group by districtname,srooffice),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
		end if;
	

END;

$$;


