CREATE FUNCTION kaverimis.fn_mis_form45_court_case_entry_report(_srocode bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(drofficename character varying, sronamee character varying, ordernumber character varying, issuing_court_or_revenue_authority character varying, description_of_scheduled_authority character varying, issueddate timestamp without time zone, isinforce boolean, iscancelled_or_closed boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize); 	
return query 
select districtnamee as drofficename,
b.sronamee as sroname,
a.ordernumber, 
issuingauthority as issuing_court_or_revenue_authority,
description as description_of_scheduled_authority,
a.issueddate as dateofissue,
a.isinforce,
iscancelled as iscancelled_or_closed from
kaveri.courtorders a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.districtmaster c on b.districtcode = c.districtcode
where a.srocode = _srocode;
END;
$$;


