		from
		kaveri.courtorders a join kaveri.sromaster b on a.srocode = b.srocode and a.srocode=_srocode
		join kaveri.districtmaster c on b.districtcode = c.districtcode and b.districtcode=_distictcode
		where a.issueddate::date>=_fromdate AND
		a.issueddate::date<=_todate),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
		
		end if;
		
		
	
END;
$$;


