ALTER FUNCTION kaverimis.fn_mis_form45_court_case_entry_report_23012024(_distictcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form9_genderwise_transaction(integer, timestamp without time zone, timestamp without time zone, integer, integer, numeric, numeric, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form9_genderwise_transaction(_srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _stamparticle integer, _amounttype integer DEFAULT NULL::integer, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer, _choice integer DEFAULT NULL::integer) RETURNS TABLE(srooffice character varying, total_number_of_documents_registered bigint, documentregistered_male character varying, booktype_male character varying, documentregistered_female character varying, booktype_female character varying, documentregistered_transgender character varying, booktype_transgender character varying, stampduty_male numeric, registrationfee_male numeric, otherfee_male numeric, total_male numeric, stampduty_female numeric, registrationfee_female numeric, otherfee_female numeric, total_female numeric, stampduty_transgender numeric, registrationfee_transgender numeric, otherfee_transgender numeric, total_transgender numeric, stampduty_total numeric, registrationfee_total numeric, otherfee_total numeric, total numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
if _choice = 1 then                                           /* 1. with particular sro,minval,maxval,fromdate,todate,article,amounttype -- registration fee, stampduty */
return query 
select  distinct 
b.sronamee as srooffice,
count(a.documentid) as total_number_of_documents_registered,
case when e.sex = '1' then 
h.articlename  else 'Not Registered' end as documentregistered_male,
case when e.sex = '1' then 
g.booknameenglish  else null end as booktype_male,
case when e.sex = '0' then 
h.articlename  else 'Not Registered' end as documentregistered_female,
case when e.sex = '0' then 
g.booknameenglish  else null end as booktype_female,
case when e.sex = '2' then 
h.articlename  else 'Not Registered' end as documentregistered_transgender,
case when e.sex = '2' then 
g.booknameenglish  else null end as booktype_transgender,

/* Male */

sum(case when e.sex = '1' and h.feerulecode = 36 then
h.amountpaid else 0 end) as stampduty_male,
sum(case when e.sex = '1' and h.feerulecode = 1 then
h.amountpaid else 0 end) as registrationfee_male,
(sum(case when e.sex = '1' and  h.feerulecode not in (1,36) then
h.amountpaid else 0 end) -
(
sum(case when e.sex = '1' and h.feerulecode = 36 then
h.amountpaid else 0 end) +
sum(case when e.sex = '1' and h.feerulecode = 1 then
h.amountpaid else 0 end) 
)
)
as otherfee_male,

/* Total - Male */
(
(sum(case when e.sex = '1' and h.feerulecode = 36 then
h.amountpaid else 0 end) +
sum(case when e.sex = '1' and h.feerulecode = 1 then
h.amountpaid else 0 end) +
--case when e.sex = '1' and h.feerulecode = 2 then
sum(case when e.sex = '1' and  h.feerulecode not in (1,36) then 
h.amountpaid else 0 end)
)
-
(
sum(case when e.sex = '1' and h.feerulecode = 36 then
h.amountpaid else 0 end) +
sum(case when e.sex = '1' and h.feerulecode = 1 then
h.amountpaid else 0 end)
)
)
 as total_male,

/* Female */
sum(case when e.sex = '0' and h.feerulecode = 36 then
h.amountpaid else 0 end) as stampduty_female,
sum(case when e.sex = '0' and h.feerulecode = 1 then
h.amountpaid else 0 end) as registrationfee_female,
(sum(case when e.sex = '0' and  h.feerulecode not in (1,36) then 
h.amountpaid else 0 end)
-
(
sum(case when e.sex = '0' and h.feerulecode = 36 then
h.amountpaid else 0 end) +
sum(case when e.sex = '0' and h.feerulecode = 1 then
h.amountpaid else 0 end 
)
)
 )
as otherfee_female,

/* Total - Female */
(sum(case when e.sex = '0' and h.feerulecode = 36 then
h.amountpaid else 0 end) +
sum(case when e.sex = '0' and h.feerulecode = 1 then
h.amountpaid else 0 end) +
sum(case when e.sex = '0' and  h.feerulecode not in (1,36) then 
h.amountpaid else 0 end)
-
(
(
sum(case when e.sex = '0' and h.feerulecode = 36 then
h.amountpaid else 0 end) +
sum(case when e.sex = '0' and h.feerulecode = 1 then
h.amountpaid else 0 end) 
)
)
) as total_female,

/*===============TRANSGENDER=======================*/
/* Transgender */
sum(case when e.sex = '2' and h.feerulecode = 36 then
h.amountpaid else 0 end) as stampduty_transgender,
sum(case when e.sex = '2' and h.feerulecode = 1 then
h.amountpaid else 0 end) as registrationfee_transgender,
(sum(case when e.sex = '2' and  h.feerulecode not in (1,36) then 
h.amountpaid else 0 end)
-
(
sum(case when e.sex = '2' and h.feerulecode = 36 then
h.amountpaid else 0 end) +
sum(case when e.sex = '2' and h.feerulecode = 1 then
h.amountpaid else 0 end) 
)
)
as otherfee_transgender,

/* Total - transgender */
(sum(case when e.sex = '2' and h.feerulecode = 36 then
h.amountpaid else 0 end) +
sum(case when e.sex = '2' and h.feerulecode = 1 then
h.amountpaid else 0 end) +
sum(case when e.sex = '2' and  h.feerulecode not in (1,36) then 
h.amountpaid else 0 end))
-
(
(
sum(case when e.sex = '2' and h.feerulecode = 36 then
h.amountpaid else 0 end) +
sum(case when e.sex = '2' and h.feerulecode = 1 then
h.amountpaid else 0 end 
)
)
 )as total_transgender,

/*=================================================*/

/* Total stampduty both male,female and transgender*/
(sum(case when e.sex = '1' and h.feerulecode = 36 then
h.amountpaid else 0 end) +
sum(case when e.sex = '0' and h.feerulecode = 36 then
h.amountpaid else 0 end) +
sum(case when e.sex = '2' and h.feerulecode = 36 then
h.amountpaid else 0 end
)) as stampduty_total,

/* Total registrationfee both male,female and transgender*/
(sum(case when e.sex = '1' and h.feerulecode = 1 then
h.amountpaid else 0 end) +
sum(case when e.sex = '0' and h.feerulecode = 1 then
h.amountpaid else 0 end) +
sum(case when e.sex = '2' and h.feerulecode = 1 then
h.amountpaid else 0 end)
) as registrationfee_total,

/* Total otherfee both male,female and transgender*/
(
(sum(case when e.sex = '1' and  h.feerulecode not in (1,36) then 
h.amountpaid else 0 end)
-
(
sum(case when e.sex = '1' and h.feerulecode = 36 then
h.amountpaid else 0 end) +
sum(case when e.sex = '1' and h.feerulecode = 1 then
h.amountpaid else 0 end 
)
) 
 )
 +
sum(case when e.sex = '0' and  h.feerulecode not in (1,36) then 
h.amountpaid else 0 end)
-
(
sum(case when e.sex = '0' and h.feerulecode = 36 then
h.amountpaid else 0 end) +
sum(case when e.sex = '0' and h.feerulecode = 1 then
h.amountpaid else 0 end 
)
) +
(sum(case when e.sex = '2' and  h.feerulecode not in (1,36) then 
h.amountpaid else 0 end)
-
(
sum(case when e.sex = '2' and h.feerulecode = 36 then
h.amountpaid else 0 end) +
sum(case when e.sex = '2' and h.feerulecode = 1 then
h.amountpaid else 0 end)
)
))
as otherfee_total,

/* grand total of stampduty,registrationfee,otherfee */
(
(
(sum(case when e.sex = '1' and h.feerulecode = 36 then
