	)
 as Total
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.partyinfo e on a.documentid = e.documentid
join kaveri.gendermaster f on e.sex = f.genderid
join kaveri.booktypemaster g on a.bookid = g.bookid
join kaverimis.vw_mis_revenue_report h on a.applicationnumber = h.applicationnumber 
inner join  
 (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report where amountpaid >= _minval
  and amountpaid < _maxval 
  )
     vw1 on h.applicationnumber=vw1.applicationnumber
where  a.registrationdatetime >=  _fromdate and a.registrationdatetime < _todate
 group by 
a.registrationdatetime,a.srocode,b.sronamee,e.sex,h.feerulecode,h.articlename,g.booknameenglish;

/* 13.  with all sros,fromdate,todate,all articles,all amounttypes without min and max*/

elseif (_choice = 13 and _srocode = 0 and _stamparticle = 0 ) then                                          
return query 
select  distinct 
