h.amountpaid else 0 end) +
sum(case when e.sex = '0' and h.feerulecode = 1 then
h.amountpaid else 0 end) 
)
)
) as total_female,

/*===============TRANSGENDER=======================*/
/* Transgender */
sum(case when e.sex = '2' and h.feerulecode = 36 then
h.amountpaid else 0 end) as stampduty_transgender,
sum(case when e.sex = '2' and h.feerulecode = 1 then
h.amountpaid else 0 end) as registrationfee_transgender,
(sum(case when e.sex = '2' and  h.feerulecode not in (1,36) then 
h.amountpaid else 0 end)
-
(
sum(case when e.sex = '2' and h.feerulecode = 36 then
h.amountpaid else 0 end) +
sum(case when e.sex = '2' and h.feerulecode = 1 then
h.amountpaid else 0 end) 
)
)
as otherfee_transgender,

