)
-
(
sum(case when e.sex = '0' and h.feerulecode = 36 then
h.amountpaid else 0 end) +
sum(case when e.sex = '0' and h.feerulecode = 1 then
h.amountpaid else 0 end 
)
)
) +
(
(sum(case when e.sex = '2' and h.feerulecode = 36 then
h.amountpaid else 0 end) +
sum(case when e.sex = '2' and h.feerulecode = 1 then
h.amountpaid else 0 end) +
sum(case when e.sex = '2' and  h.feerulecode not in (1,36) then 
h.amountpaid else 0 end))
-
(
sum(case when e.sex = '2' and h.feerulecode = 36 then
h.amountpaid else 0 end) +
sum(case when e.sex = '2' and h.feerulecode = 1 then
h.amountpaid else 0 end )
)
)
	)
 as Total
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.partyinfo e on a.documentid = e.documentid
join kaveri.gendermaster f on e.sex = f.genderid
join kaveri.booktypemaster g on a.bookid = g.bookid
join kaverimis.vw_mis_revenue_report h on a.applicationnumber = h.applicationnumber 
inner join  
 (select applicationnumber,amountpaid from kaverimis.vw_mis_revenue_report 
  )
     vw1 on h.applicationnumber=vw1.applicationnumber
where  a.registrationdatetime >=  _fromdate and a.registrationdatetime < _todate
 group by 
a.registrationdatetime,a.srocode,b.sronamee,e.sex,h.feerulecode,h.articlename,g.booknameenglish;

end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form9_genderwise_transaction(_srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _stamparticle integer, _amounttype integer, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer, _choice integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form_27_details_of_cases_disposed_and_pending(integer, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form_27_details_of_cases_disposed_and_pending(_srocode integer, _fin_fromdate timestamp without time zone, _fin_todate timestamp without time zone, _within_fromdate timestamp without time zone, _within_todate timestamp without time zone, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(subregistrationoffice character varying, number_cases_pending_end_of_previous_fy_month integer, stampduty_cases_pending_end_of_previous_fy_month integer, registrationfee_cases_pending_end_of_previous_fy_month integer, totalfee_cases_pending_end_of_previous_fy_month integer, number_cases_disposed_during_fy bigint, stampduty_cases_disposed_during_fy numeric, registrationfee_cases_disposed_during_fy numeric, totalfee_cases_disposed_during_fy numeric, number_cases_pending_during_reporting_month bigint, stampduty_cases_pending_during_reporting_month numeric, registrationfee_cases_pending_during_reporting_month numeric, totalfee_cases_pending_during_reporting_month numeric, number_recovered_in_disposal_cases_eof_prev_fin_year integer, stampduty_recovered_in_disposal_cases_eof_prev_fin_year integer, registrationfee_recovered_in_disposal_cases_eof_prev_fin_year integer, amount_fee_recovered_in_disposal_cases_eof_prev_fin_year integer, number_amount_recovered_disposed_cases_during_fy integer, stampduty_amount_recovered_disposed_cases_during_fy integer, registrationfee_amount_recovered_disposed_cases_during_fy integer, totalfee_recovered_disposed_cases_during_fy integer, number_total_recovery_details bigint, stampduty_total_recovery_details numeric, registrationfee_total_recovery_details numeric, totalfee_total_recovery_details numeric, number_details_of_cases_disposed_but_not_recovered integer, stampduty_details_of_cases_disposed_but_not_recovered integer, registrationfee_details_of_cases_disposed_but_not_recovered integer, totalfee_details_of_cases_disposed_but_not_recovered integer, six_months_period_of_pendency integer, six_months_to_1_year_period_of_pendency integer, one_year_to_2_years_period_of_pendency integer, two_years_to_3_years_period_of_pendency integer, cases_above_3_years_of_age_period_of_pendency integer)
    LANGUAGE plpgsql
    AS $$
 
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	 
return query 
select distinct a.sronamee as subregistrationoffice,
0 as number_cases_pending_end_of_previous_fy_month,
0 as stampduty_cases_pending_end_of_previous_fy_month,
0 as registrationfee_cases_pending_end_of_previous_fy_month,
0 as Totalfee_cases_pending_end_of_previous_fy_month,
cases_disposed_during_2022_23.number as number_cases_disposed_during_fy,
cases_disposed_during_2022_23.stampduty as stampduty_cases_disposed_during_fy,
cases_disposed_during_2022_23.registrationfee as registrationfee_cases_disposed_during_fy,
cases_disposed_during_2022_23.Totalfee as Totalfee_cases_disposed_during_fy,
cases_pending_during_reporting_month.number as number_cases_pending_during_reporting_month,
cases_pending_during_reporting_month.stampduty as stampduty_cases_pending_during_reporting_month,
cases_pending_during_reporting_month.registrationfee as registrationfee_cases_pending_during_reporting_month,
cases_pending_during_reporting_month.Totalfee as Totalfee_cases_pending_during_reporting_month,
0 as number_recovered_in_disposal_cases_eof_prev_fin_year,
0 as stampduty_recovered_in_disposal_cases_eof_prev_fin_year,
0 as registrationfee_recovered_in_disposal_cases_eof_prev_fin_year,
0 as Amount_fee_recovered_in_disposal_cases_eof_prev_fin_year,
0 as number_Amount_recovered_disposed_cases_during_fy,
0 as stampduty_Amount_recovered_disposed_cases_during_fy,
0 as registrationfee_Amount_recovered_disposed_cases_during_fy,
0 as Totalfee_recovered_disposed_cases_during_fy,
(cases_disposed_during_2022_23.number + cases_pending_during_reporting_month.number)
number_Total_Recovery_Details,
(cases_disposed_during_2022_23.stampduty + cases_pending_during_reporting_month.stampduty)
stampduty_Total_Recovery_Details,
(cases_disposed_during_2022_23.registrationfee + cases_pending_during_reporting_month.registrationfee)
registrationfee_Total_Recovery_Details,
(cases_disposed_during_2022_23.Totalfee + cases_pending_during_reporting_month.Totalfee)
Totalfee_Total_Recovery_Details,
0 as number_Details_of_cases_disposed_but_not_recovered,
0 as stampduty_Details_of_cases_disposed_but_not_recovered,
0 as registrationfee_Details_of_cases_disposed_but_not_recovered,
0 as Totalfee_Details_of_cases_disposed_but_not_recovered,
0 as six_months_Period_of_pendency,
0 as six_months_to_1_year_Period_of_pendency,
0 as one_year_to_2_years_Period_of_pendency,
0 as two_years_to_3_years_Period_of_pendency,
0 as Cases_above_3_years_of_age_Period_of_pendency
from kaveri.sromaster a
join (
select a.srocode,
count(a.documentid) as number,
case when a.feerulecode = 36 then
sum(a.amountpaid) else 0 end as stampduty,
case when a.feerulecode = 1 then
sum(a.amountpaid) else 0 end as registrationfee,
(case when a.feerulecode = 36 then
sum(a.amountpaid) else 0 end +
case when a.feerulecode = 1 then
sum(a.amountpaid) else 0 end) Totalfee
from kaveri.feesrequired a join kaveri.documentmaster d on a.documentid = d.documentid
join kaveri.courtorders c  on d.srocode = c.srocode
where a.srocode = _srocode and iscancelled = false and isregistrationcompleted = true
and d.registrationdatetime > _fin_fromdate
and d.registrationdatetime <= _fin_todate
group by a.srocode,a.feerulecode 
having (case when a.feerulecode = 36 then
sum(a.amountpaid) else 0 end +
case when a.feerulecode = 1 then
sum(a.amountpaid) else 0 end) > 0) cases_disposed_during_2022_23 
 on a.srocode = 
cases_disposed_during_2022_23.srocode
join (
select a.srocode,
count(a.documentid) as number,
case when a.feerulecode = 36 then
sum(a.amountpaid) else 0 end as stampduty,
case when a.feerulecode = 1 then
sum(a.amountpaid) else 0 end as registrationfee,
(case when a.feerulecode = 36 then
sum(a.amountpaid) else 0 end +
case when a.feerulecode = 1 then
sum(a.amountpaid) else 0 end) Totalfee
from kaveri.feesrequired a join kaveri.documentmaster d on a.documentid = d.documentid
join kaveri.courtorders c  on d.srocode = c.srocode
where a.srocode = _srocode and iscancelled = false and  isregistrationcompleted = true and
	d.registrationdatetime > _within_fromdate
and d.registrationdatetime <= _within_todate
group by a.srocode,a.feerulecode 
having (case when a.feerulecode = 36 then
sum(a.amountpaid) else 0 end +
case when a.feerulecode = 1 then
sum(a.amountpaid) else 0 end) > 0
) cases_pending_during_reporting_month 
 on cases_disposed_during_2022_23.srocode = 
cases_pending_during_reporting_month.srocode
where
(cases_disposed_during_2022_23.Totalfee + cases_pending_during_reporting_month.Totalfee) 
>= _minval and
(cases_disposed_during_2022_23.Totalfee + cases_pending_during_reporting_month.Totalfee) 
<= _maxval;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form_27_details_of_cases_disposed_and_pending(_srocode integer, _fin_fromdate timestamp without time zone, _fin_todate timestamp without time zone, _within_fromdate timestamp without time zone, _within_todate timestamp without time zone, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form_29_number_of_pages_scanned_and_fee_collected(integer, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form_29_number_of_pages_scanned_and_fee_collected(_srocode integer, _before_april_2022_23_from_date timestamp without time zone, _before_april_2022_23_to_date timestamp without time zone, _in_the_month_from_date timestamp without time zone, _in_the_month_to_date timestamp without time zone, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(sroofficename character varying, total_docs_registered_month_before_fy bigint, total_no_of_pages_acanned_before_fy bigint, scanningfee_collected_before_fy numeric, total_docs_registered_month_of_april_curr_fy bigint, total_no_of_pages_acanned_of_april_curr_fy bigint, scanningfee_collected_month_of_april_curr_fy numeric, total_docs_registered_during_fy bigint, total_no_of_pages_acanned_during_fy bigint, scanningfee_collected_during_fy numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
	return query 
select 
a.sronamee sroofficename,
/* The Month before April 2022-23 */
month_before_April_2022_23.total_docs_registered_month_before_April_2022_23 as total_docs_registered_month_before_fy,
month_before_April_2022_23.total_no_of_pages_acanned_before_April_2022_23 as total_no_of_pages_acanned_before_fy,
month_before_April_2022_23.scanningfee_collected_before_April_2022_23 as scanningfee_collected_before_fy,
month_of_April_2022.total_docs_registered_month_of_April_2022 as total_docs_registered_month_of_April_curr_fy,
month_of_April_2022.total_no_of_pages_acanned_of_April_2022 as total_no_of_pages_acanned_of_April_curr_fy,
month_of_April_2022.scanningfee_collected_month_of_April_2022 as scanningfee_collected_month_of_April_curr_fy,
during_2022_2023.total_docs_registered_during_2022_23 as total_docs_registered_during_fy,
during_2022_2023.total_no_of_pages_acanned_during_2022_23 as total_no_of_pages_acanned_during_fy,
during_2022_2023.scanningfee_collected_during_2022_23 as scanningfee_collected_during_fy
from kaveri.sromaster a 
join
(
select a.srocode,
count(a.documentid) total_docs_registered_month_before_April_2022_23 ,
sum(noofscanpages) total_no_of_pages_acanned_before_April_2022_23,
case when c.feerulecode = 2 then
sum(amountpaid) else 0 end as scanningfee_collected_before_April_2022_23
from kaveri.documentmaster a join kaveri.propertymaster b on a.documentid = b.documentid
join kaveri.feesrequired c on a.documentid = c.documentid
where feerulecode = 2 and isregistrationcompleted = true and a.registrationdatetime >= _before_April_2022_23_from_date
and a.registrationdatetime <= _before_April_2022_23_to_date and a.srocode = _srocode
group by a.srocode,c.feerulecode
)month_before_April_2022_23 on a.srocode = month_before_April_2022_23.srocode
join
(
select a.srocode,
count(a.documentid) total_docs_registered_month_of_April_2022 ,
sum(noofscanpages) total_no_of_pages_acanned_of_April_2022,
sum(amountpaid) scanningfee_collected_month_of_April_2022
from kaveri.documentmaster a join kaveri.propertymaster b on a.documentid = b.documentid
join kaveri.feesrequired c on a.documentid = c.documentid
where feerulecode = 2 and isregistrationcompleted = true and a.registrationdatetime >= _in_the_month_from_date
and a.registrationdatetime <= _in_the_month_to_date and a.srocode = _srocode
group by a.srocode
)month_of_April_2022 on a.srocode = month_of_April_2022.srocode
join
(
select a.srocode,
count(a.documentid) total_docs_registered_during_2022_23 ,
sum(noofscanpages) total_no_of_pages_acanned_during_2022_23,
sum(amountpaid) scanningfee_collected_during_2022_23
from kaveri.documentmaster a join kaveri.propertymaster b on a.documentid = b.documentid
join kaveri.feesrequired c on a.documentid = c.documentid
where feerulecode = 2 and isregistrationcompleted = true and a.registrationdatetime >= _from_date
and a.registrationdatetime <= _to_date and a.srocode = _srocode
group by a.srocode) during_2022_2023 on a.srocode = during_2022_2023.srocode
group by a.sronamee,
month_before_April_2022_23.total_docs_registered_month_before_April_2022_23,
month_before_April_2022_23.total_no_of_pages_acanned_before_April_2022_23,
month_before_April_2022_23.scanningfee_collected_before_April_2022_23,
month_of_April_2022.total_docs_registered_month_of_April_2022,
month_of_April_2022.total_no_of_pages_acanned_of_April_2022,
month_of_April_2022.scanningfee_collected_month_of_April_2022,
during_2022_2023.total_docs_registered_during_2022_23,
during_2022_2023.total_no_of_pages_acanned_during_2022_23,
during_2022_2023.scanningfee_collected_during_2022_23;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form_29_number_of_pages_scanned_and_fee_collected(_srocode integer, _before_april_2022_23_from_date timestamp without time zone, _before_april_2022_23_to_date timestamp without time zone, _in_the_month_from_date timestamp without time zone, _in_the_month_to_date timestamp without time zone, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form_31_details_of_cases_disp_act_1957_prior_18_aug_1999(integer, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form_31_details_of_cases_disp_act_1957_prior_18_aug_1999(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _pending_cases_from_date timestamp without time zone, _pending_cases_to_date timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(nameofsubregistrationoffice character varying, pendingcases_attheendfy integer, stampduty_attheendfy integer, registrationfee_attheendfy integer, totalfee_attheendfy integer, number_duringtheperiod numeric, stampduty_duringtheperiod numeric, registrationfee_duringtheperiod numeric, totalfee_duringtheperiod numeric, number_pendingcases numeric, stampduty_pendingcases numeric, registrationfee_pendingcases numeric, totalfee_pendingcases numeric, disposable_cases_eoy_2022 numeric, stampduty_eoy_2022 numeric, registrationfee_eoy_2022 numeric, total_eoy_2022 numeric, number_disposed_2022_2023 numeric, stampduty_disposed_2022_2023 numeric, registrationfee_disposed_2022_2023 numeric, totalfee_disposed_2022_2023 numeric, number_total_recovery_details numeric, stampduty_total_recovery_details numeric, registrationfee_total_recovery_details numeric, totalfee_total_recovery_details numeric, number_cases_disposed_but_fee_unrecovered numeric, stampduty_cases_disposed_but_fee_unrecovered numeric, registrationfee_cases_disposed_but_fee_unrecovered numeric, totalfee_cases_disposed_but_fee_unrecovered numeric, period_of_pendency_six_months numeric, period_of_pendency_6months_to_1year integer, period_of_pendency_1year_to_2years integer, period_of_pendency_12years_to_3years integer, period_of_pendency_above_3_years integer)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
	return query 
select a.sronamee as nameofsubregistrationoffice,
	
/*	Pending cases at the end of 31.03.2022 */

	0 as pendingcases_attheendfy,
	0 stampduty_attheendfy,
	0 registrationfee_attheendfy,
	0 totalfee_attheendfy,
	
	/* Details for the cases disposed during the year 2022-23  */

	
	sum(casesrdisposedduringtheperiod.number_casesrdisposedduringtheperiod) as number_duringtheperiod,
	sum(casesrdisposedduringtheperiod.stampduty_casesrdisposedduringtheperiod) as stampduty_duringtheperiod,
	sum(casesrdisposedduringtheperiod.registrationfee_casesrdisposedduringtheperiod) as registrationfee_duringtheperiod,
	(sum(casesrdisposedduringtheperiod.stampduty_casesrdisposedduringtheperiod) +
	sum(casesrdisposedduringtheperiod.registrationfee_casesrdisposedduringtheperiod)) totalfee_duringtheperiod,
	
		/* Details of pending cases pending by end of reporting month */
	
	sum(detailsofthependingcases.number_pendingcases) number_pendingcases,
	sum(detailsofthependingcases.stampduty_pendingcases) stampduty_pendingcases,
	sum(detailsofthependingcases.registrationfee_pendingcases) registrationfee_pendingcases,
	(sum(detailsofthependingcases.stampduty_pendingcases) + sum(detailsofthependingcases.registrationfee_pendingcases))
	Totalfee_pendingcases,
	
	/* Details of recovery in cases concluded during 2021-2022 */
	sum(disposablecases_eof_fy.number_disposablecases) as disposable_cases_eoy_2022,
	sum(disposablecases_eof_fy.stampduty_disposablecases) stampduty_eoy_2022,
	sum(disposablecases_eof_fy.registrationfee_disposablecases) registrationfee_eoy_2022,
	(sum(disposablecases_eof_fy.stampduty_disposablecases) +
	sum(disposablecases_eof_fy.registrationfee_disposablecases)) total_eoy_2022,
	
   /* Amount recovered in disposed cases during 2022-23 */
   
   sum(disposedduring_2022_23.number_disposedduring_2022_23) as number_disposed_2022_2023,
   sum(disposedduring_2022_23.stampduty_disposedduring_2022_23) as stampduty_disposed_2022_2023,
   sum(disposedduring_2022_23.registrationfee_disposedduring_2022_23) as registrationfee_disposed_2022_2023,
   (sum(disposedduring_2022_23.stampduty_disposedduring_2022_23) + sum(disposedduring_2022_23.registrationfee_disposedduring_2022_23))
   as Totalfee_disposed_2022_2023,
   
   /* Total Recovery Details */
   
   (sum(disposablecases_eof_fy.number_disposablecases) + sum(disposedduring_2022_23.number_disposedduring_2022_23)) number_total_recovery_details,
   (sum(disposablecases_eof_fy.stampduty_disposablecases) + sum(disposedduring_2022_23.stampduty_disposedduring_2022_23)) stampduty_total_recovery_details,
   (sum(disposablecases_eof_fy.registrationfee_disposablecases) + sum(disposedduring_2022_23.registrationfee_disposedduring_2022_23)) registrationfee_total_recovery_details,
   (sum(disposablecases_eof_fy.stampduty_disposablecases) +
	sum(disposablecases_eof_fy.registrationfee_disposablecases) + sum(disposedduring_2022_23.stampduty_disposedduring_2022_23) + sum(disposedduring_2022_23.registrationfee_disposedduring_2022_23))
	Totalfee_total_recovery_details,
   /* Amount not recovered for disposed cases during 2022-23 */
   
   sum(details_cases_disposed_but_fee_unrecovered.number_disposedduring_2022_23) as number_cases_disposed_but_fee_unrecovered,
   sum(details_cases_disposed_but_fee_unrecovered.stampduty_disposedduring_2022_23) as stampduty_cases_disposed_but_fee_unrecovered,
   sum(details_cases_disposed_but_fee_unrecovered.registrationfee_disposedduring_2022_23) as registrationfee_cases_disposed_but_fee_unrecovered,
   (sum(details_cases_disposed_but_fee_unrecovered.stampduty_disposedduring_2022_23) +
    sum(details_cases_disposed_but_fee_unrecovered.registrationfee_disposedduring_2022_23)) Totalfee_cases_disposed_but_fee_unrecovered,
	
	/* Period of Pendency */
	
	sum(period_of_pendency_6months.periodofpendendency_6_monts)period_of_pendency_six_months,
	0 as period_of_pendency_6months_to_1year,
	0 as period_of_pendency_1year_to_2years,
	0 as period_of_pendency_12years_to_3years,
	0 as period_of_pendency_above_3_years
from kaveri.sromaster a 
	join
	(select distinct a.srocode,b.sronamee nameofsubregistrationoffice,
count(a.documentid)  as number_casesrdisposedduringtheperiod,
case when feerulecode = 36  then
sum(amountpaid) else 0 end as stampduty_casesrdisposedduringtheperiod,
case when feerulecode = 1  then
sum(amountpaid)  else 0 end as registrationfee_casesrdisposedduringtheperiod
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.feesrequired c on a.documentid = c.documentid
where a.srocode = _srocode and registrationdatetime >= _from_date and
registrationdatetime <= _to_date 
group by a.srocode,b.sronamee,feerulecode)
casesrdisposedduringtheperiod on a.srocode = casesrdisposedduringtheperiod.srocode
join
(
select distinct a.srocode,b.sronamee,b.districtcode,d.districtnamee nameofdroffice,
case when isregistrationcompleted = false then
count(a.documentid) else 0 end as number_pendingcases,
case when feerulecode = 36 and isregistrationcompleted = false then
sum(amountpaid) else 0 end as stampduty_pendingcases,
case when feerulecode = 1 and isregistrationcompleted = false then
sum(amountpaid)  else 0 end as registrationfee_pendingcases
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.feesrequired c on a.documentid = c.documentid
join kaveri.districtmaster d on b.districtcode = d.districtcode
where a.srocode = _srocode and registrationdatetime >= _pending_cases_from_date and
registrationdatetime <= _pending_cases_to_date
group by a.srocode,b.sronamee,b.districtcode,d.districtnamee,isregistrationcompleted,feerulecode
) detailsofthependingcases on casesrdisposedduringtheperiod.srocode = detailsofthependingcases.srocode
join 
	(
	select distinct srocode,count(documentid) as periodofpendendency_6_monts from kaveri.documentmaster where
isregistrationcompleted = false and srocode = _srocode
group by srocode,registrationdatetime
having min(registrationdatetime) <= min(registrationdatetime) + INTERVAL '6 months' 
	) period_of_pendency_6months on detailsofthependingcases.srocode = period_of_pendency_6months.srocode
join 
(
select distinct a.srocode,
count(a.documentid) as  number_disposablecases,
case when feerulecode = 36  then
sum(amountpaid) else 0 end as stampduty_disposablecases,
case when feerulecode = 1 then
sum(amountpaid)  else 0 end as registrationfee_disposablecases
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.feesrequired c on a.documentid = c.documentid
join kaveri.districtmaster d on b.districtcode = d.districtcode
where a.srocode = _srocode and registrationdatetime >= _from_date and
registrationdatetime <= _to_date and isregistrationcompleted = true
group by a.srocode,b.sronamee,b.districtcode,d.districtnamee,isregistrationcompleted,feerulecode
)disposablecases_eof_fy on casesrdisposedduringtheperiod.srocode = disposablecases_eof_fy.srocode
join
(select distinct a.srocode,b.sronamee nameofsubregistrationoffice,
count(a.documentid)  as number_disposedduring_2022_23,
case when feerulecode = 36  then
sum(amountpaid) else 0 end as stampduty_disposedduring_2022_23,
case when feerulecode = 1  then
sum(amountpaid)  else 0 end as registrationfee_disposedduring_2022_23
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.feesrequired c on a.documentid = c.documentid
where a.srocode = _srocode and registrationdatetime >= _from_date and
registrationdatetime <= _to_date and isregistrationcompleted = true
group by a.srocode,b.sronamee,feerulecode)  disposedduring_2022_23 on disposablecases_eof_fy.srocode = disposedduring_2022_23.srocode 
join
(
select distinct a.srocode,b.sronamee nameofsubregistrationoffice,
count(a.documentid)  as number_disposedduring_2022_23,
case when feerulecode = 36  then
sum(amountpaid) else 0 end as stampduty_disposedduring_2022_23,
case when feerulecode = 1  then
sum(amountpaid)  else 0 end as registrationfee_disposedduring_2022_23
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.feesrequired c on a.documentid = c.documentid
where a.srocode = _srocode and registrationdatetime >= _from_date and
registrationdatetime <= _to_date and isregistrationcompleted = true
group by a.srocode,b.sronamee,feerulecode
having case when feerulecode = 36  then
sum(amountpaid) else 0 end = 0
and case when feerulecode = 1  then
sum(amountpaid)  else 0 end = 0
) details_cases_disposed_but_fee_unrecovered on disposedduring_2022_23.srocode = details_cases_disposed_but_fee_unrecovered.srocode
group by a.sronamee;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form_31_details_of_cases_disp_act_1957_prior_18_aug_1999(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _pending_cases_from_date timestamp without time zone, _pending_cases_to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form_32_details_of_cases_disp_act_1957_after_18_aug_1999(integer, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form_32_details_of_cases_disp_act_1957_after_18_aug_1999(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _pending_cases_from_date timestamp without time zone, _pending_cases_to_date timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(nameofsubregistrationoffice character varying, pendingcases_attheendfy integer, stampduty_attheendfy integer, registrationfee_attheendfy integer, totalfee_attheendfy integer, number_duringtheperiod numeric, stampduty_duringtheperiod numeric, registrationfee_duringtheperiod numeric, totalfee_duringtheperiod numeric, number_totalnoofcases numeric, stampduty_totalnoofcases numeric, registrationfee_totalnoofcases numeric, totalfees_totalnumberofcases numeric, number_decidedbydr numeric, stampduty_decidedbydr numeric, registrationfee_decidedbydr numeric, totalfee_decidedbydr numeric, number_pendingcases numeric, stampduty_pendingcases numeric, registrationfee_pendingcases numeric, totalfee_pendingcases numeric, period_of_pendency_six_months numeric, period_of_pendency_6months_to_1year integer, period_of_pendency_1year_to_2years integer, period_of_pendency_12years_to_3years integer, period_of_pendency_above_3_years integer)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
	return query 
select a.sronamee as nameofsubregistrationoffice,
	
/*	Pending cases at the end of 31.03.2022 */

	0 as pendingcases_attheendfy,
	0 stampduty_attheendfy,
	0 registrationfee_attheendfy,
	0 totalfee_attheendfy,
	
	/* Cases referred during the period 2022-23 */

	
	sum(casesreferedduringtheperiod.number_casesreferedduringtheperiod) as number_duringtheperiod,
	sum(casesreferedduringtheperiod.stampduty_casesreferedduringtheperiod) as stampduty_duringtheperiod,
	sum(casesreferedduringtheperiod.registrationfee_casesreferedduringtheperiod) as registrationfee_duringtheperiod,
	(sum(casesreferedduringtheperiod.stampduty_casesreferedduringtheperiod) +
	sum(casesreferedduringtheperiod.registrationfee_casesreferedduringtheperiod)) totalfee_duringtheperiod,
	
	/* Total number of cases */
	
	(0 + sum(casesreferedduringtheperiod.number_casesreferedduringtheperiod)) Number_totalnoofcases,
	(0 + sum(casesreferedduringtheperiod.stampduty_casesreferedduringtheperiod)) stampduty_totalnoofcases,
	(0 + sum(casesreferedduringtheperiod.registrationfee_casesreferedduringtheperiod)) registrationfee_totalnoofcases,
	((0 + sum(casesreferedduringtheperiod.stampduty_casesreferedduringtheperiod)) +
	(0 + sum(casesreferedduringtheperiod.registrationfee_casesreferedduringtheperiod))) Totalfees_totalnumberofcases,
	
	/* The cases decided by the District Registrar end of the year 2022-23 */
	
	sum(casesdecidedbydr.number_casesdecidedbydr) number_decidedbydr,
	sum(casesdecidedbydr.stampduty_casesdecidedbydr) stampduty_decidedbydr,
	sum(casesdecidedbydr.registrationfee_casesdecidedbydr) registrationfee_decidedbydr,
	(sum(casesdecidedbydr.stampduty_casesdecidedbydr) + sum(casesdecidedbydr.registrationfee_casesdecidedbydr)) Totalfee_decidedbydr,
	
	/* Details of pending cases */
	
	sum(detailsofthependingcases.number_pendingcases) number_pendingcases,
	sum(detailsofthependingcases.stampduty_pendingcases) stampduty_pendingcases,
	sum(detailsofthependingcases.registrationfee_pendingcases) registrationfee_pendingcases,
	(sum(detailsofthependingcases.stampduty_pendingcases) + sum(detailsofthependingcases.registrationfee_pendingcases))
	Totalfee_pendingcases,
	
	/* Period of Pendency */
	
	sum(period_of_pendency_6months.periodofpendendency_6_monts)period_of_pendency_six_months,
	0 as period_of_pendency_6months_to_1year,
	0 as period_of_pendency_1year_to_2years,
	0 as period_of_pendency_12years_to_3years,
	0 as period_of_pendency_above_3_years
from kaveri.sromaster a 
	join
	(select distinct a.srocode,b.sronamee nameofsubregistrationoffice,
count(a.documentid)  as number_casesreferedduringtheperiod,
case when feerulecode = 36  then
sum(amountpaid) else 0 end as stampduty_casesreferedduringtheperiod,
case when feerulecode = 1  then
sum(amountpaid)  else 0 end as registrationfee_casesreferedduringtheperiod
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.feesrequired c on a.documentid = c.documentid
where a.srocode = _srocode and registrationdatetime >= _from_date and
registrationdatetime <= _to_date 
group by a.srocode,b.sronamee,feerulecode)
casesreferedduringtheperiod on a.srocode = casesreferedduringtheperiod.srocode
join
(
select distinct a.srocode,b.sronamee,b.districtcode,d.districtnamee nameofdroffice,
case when isregistrationcompleted = true then
count(a.documentid) else 0 end as number_casesdecidedbydr,
case when feerulecode = 36 and isregistrationcompleted = true then
sum(amountpaid) else 0 end as stampduty_casesdecidedbydr,
case when feerulecode = 1 and isregistrationcompleted = true then
sum(amountpaid)  else 0 end as registrationfee_casesdecidedbydr
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.feesrequired c on a.documentid = c.documentid
join kaveri.districtmaster d on b.districtcode = d.districtcode
where a.srocode = _srocode and registrationdatetime >= _from_date and
registrationdatetime <= _to_date 
group by a.srocode,b.sronamee,feerulecode,isregistrationcompleted,
b.districtcode,d.districtnamee) casesdecidedbydr on casesreferedduringtheperiod.srocode = casesdecidedbydr.srocode
join
(
select distinct a.srocode,b.sronamee,b.districtcode,d.districtnamee nameofdroffice,
case when isregistrationcompleted = false then
count(a.documentid) else 0 end as number_pendingcases,
case when feerulecode = 36 and isregistrationcompleted = false then
sum(amountpaid) else 0 end as stampduty_pendingcases,
case when feerulecode = 1 and isregistrationcompleted = false then
sum(amountpaid)  else 0 end as registrationfee_pendingcases
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.feesrequired c on a.documentid = c.documentid
join kaveri.districtmaster d on b.districtcode = d.districtcode
where a.srocode = _srocode and registrationdatetime >= _pending_cases_from_date and
registrationdatetime <= _pending_cases_to_date 
group by a.srocode,b.sronamee,b.districtcode,d.districtnamee,isregistrationcompleted,feerulecode
) detailsofthependingcases on casesdecidedbydr.srocode = detailsofthependingcases.srocode
join 
	(
	select distinct srocode,count(documentid) as periodofpendendency_6_monts from kaveri.documentmaster where
isregistrationcompleted = false and srocode = 173
group by srocode,registrationdatetime
having min(registrationdatetime) <= min(registrationdatetime) + INTERVAL '6 months' 
	) period_of_pendency_6months on detailsofthependingcases.srocode = period_of_pendency_6months.srocode
group by a.sronamee;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form_32_details_of_cases_disp_act_1957_after_18_aug_1999(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _pending_cases_from_date timestamp without time zone, _pending_cases_to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form_36_details_of_pending_cases_in_various_courts(integer, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form_36_details_of_pending_cases_in_various_courts(_districtcode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _pending_cases_from_date timestamp without time zone, _pending_cases_to_date timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(nameoftheoffice character varying, no_casespending_reg_comm_month_prev_fy integer, amount_casespending_reg_comm_month_prev_fy integer, no_casespending_reg_comm_fy integer, amount_casespending_reg_comm_fy integer, no_casespending_reg_comm integer, total_casespending_reg_comm integer, no_casespending_highcourt_during_month_prev_fy bigint, amount_casespending_highcourt_during_month_prev_fy numeric, no_casespending_highcourt_during_fy_2022_23 bigint, amount_casespending_highcourt_during_fy numeric, total_cases_pending_highcourt bigint, total_amount_pending_highcourt numeric, no_casespending_supreme_court_comm_month_prev_fy integer, amount_casespending_supreme_court_month_prev_fy integer, no_casespending_supreme_court_comm_fy integer, amount_casespending_supreme_court_fy integer, no_casespending_supreme_court integer, total_casespending_supreme_court integer, no_casespending_various_courts_during_month_prev_fy bigint, amount_casespending_various_courts_during_month_prev_fy numeric, no_casespending_various_courts_during_fy bigint, amount_casespending_various_courts_during_fy numeric, totalcasespending_various_courts bigint, totalamountpending_various_courts numeric, total_no_casespending bigint, total_amountpending numeric, no_disposedcases_during_fy bigint, amountpending_disposedcases_during_fy numeric, noofcases_pending_end_of_reporting_month bigint, amountpending_end_of_reporting_month numeric, no_of_cases_received_stay_order integer, amount_pending_receiving_stay_order integer)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
	return query 
select sronamee as Nameoftheoffice,

/* Cases in the Regional Commissioner Court and the amount involved */

0 as no_casespending_reg_comm_month_prev_fy,
0 as amount_casespending_reg_comm_month_prev_fy,
0 as no_casespending_reg_comm_fy,
0 as amount_casespending_reg_comm_fy,
0 as no_casespending_reg_comm,
0 as total_casespending_reg_comm,

/* Appeals in the High Courts and the amount involved */

pending_Highcourt_during_march_2022.no_casespending_Highcourt_during_march_2022 as no_casespending_Highcourt_during_month_prev_fy ,
pending_Highcourt_during_march_2022.amount_casespending_Highcourt_during_march_2022 as amount_casespending_Highcourt_during_month_prev_fy,
pending_Highcourt_during_fy_2022_23.no_casespending_Highcourt_during_fy_2022_23 as no_casespending_Highcourt_during_fy,
pending_Highcourt_during_fy_2022_23.amount_casespending_Highcourt_during_fy_2022_23 as amount_casespending_Highcourt_during_fy,
(pending_Highcourt_during_march_2022.no_casespending_Highcourt_during_march_2022 +
pending_Highcourt_during_fy_2022_23.no_casespending_Highcourt_during_fy_2022_23) Total_cases_pending_highcourt,
(pending_Highcourt_during_march_2022.amount_casespending_Highcourt_during_march_2022 +
pending_Highcourt_during_fy_2022_23.amount_casespending_Highcourt_during_fy_2022_23) Total_amount_pending_highcourt,

/* Appeals filed in Supreme Court and amount involved */

0 as no_casespending_supreme_court_comm_month_prev_fy,
0 as amount_casespending_supreme_court_month_prev_fy,
0 as no_casespending_supreme_court_comm_fy ,
0 as amount_casespending_supreme_court_fy,
0 as no_casespending_supreme_court,
0 as total_casespending_supreme_court,

/* The Number of cases pending in various courts */
pending_various_courts_during_march_2022.no_casespending_various_courts_during_march_2022 as no_casespending_various_courts_during_month_prev_fy,
pending_various_courts_during_march_2022.amount_casespending_various_courts_during_march_2022 as amount_casespending_various_courts_during_month_prev_fy,
pending_various_courts_during_fy_2022_23.no_casespending_various_courts_during_fy_2022_23 as no_casespending_various_courts_during_fy,
pending_various_courts_during_fy_2022_23.amount_casespending_various_courts_during_fy_2022_23 as amount_casespending_various_courts_during_fy,
(pending_various_courts_during_march_2022.no_casespending_various_courts_during_march_2022 +
pending_various_courts_during_fy_2022_23.no_casespending_various_courts_during_fy_2022_23) totalcasespending_various_courts,
(pending_various_courts_during_march_2022.amount_casespending_various_courts_during_march_2022 +
pending_various_courts_during_fy_2022_23.amount_casespending_various_courts_during_fy_2022_23) totalamountpending_various_courts,

/* Total cases and amount involved */

(0 + (pending_Highcourt_during_march_2022.no_casespending_Highcourt_during_march_2022 +
pending_Highcourt_during_fy_2022_23.no_casespending_Highcourt_during_fy_2022_23) +
0 + (pending_various_courts_during_march_2022.no_casespending_various_courts_during_march_2022 +
pending_various_courts_during_fy_2022_23.no_casespending_various_courts_during_fy_2022_23) +
(pending_various_courts_during_march_2022.no_casespending_various_courts_during_march_2022 +
pending_various_courts_during_fy_2022_23.no_casespending_various_courts_during_fy_2022_23)
) Total_no_casespending,

(0 + (pending_Highcourt_during_march_2022.amount_casespending_Highcourt_during_march_2022 +
pending_Highcourt_during_fy_2022_23.amount_casespending_Highcourt_during_fy_2022_23) +
0 + (pending_various_courts_during_march_2022.amount_casespending_various_courts_during_march_2022 +
pending_various_courts_during_fy_2022_23.amount_casespending_various_courts_during_fy_2022_23) +
(pending_various_courts_during_march_2022.amount_casespending_various_courts_during_march_2022 +
pending_various_courts_during_fy_2022_23.amount_casespending_various_courts_during_fy_2022_23)
) Total_amountpending,

 /* Disposed cases and amount involved in the year 2022-23 */
 
 disposedcases_during_fy_2022_2023.no_disposedcases_during_fy_2022_2023 as no_disposedcases_during_fy,
 disposedcases_during_fy_2022_2023.amountpending_disposedcases_during_fy_2022_2023 as amountpending_disposedcases_during_fy,
 
 /* Cases pending at the end of the reporting month and amount involved */
 
 pending_at_the_end_of_reporting_month.noofcases_pending_end_of_reporting_month,
 pending_at_the_end_of_reporting_month.amountpending_end_of_reporting_month,
 
 
 /* No. of cases which received stay order from court and amount involved */
 
 0 no_of_cases_received_stay_order,
 0 amount_pending_receiving_stay_order
 
from 
kaveri.sromaster a 
join
(
select a.srocode,
	count(d.ordernumber) no_casespending_Highcourt_during_march_2022,
	sum(amount) amount_casespending_Highcourt_during_march_2022 from kaveri.liabilitydetails a join 
kaveri.referencemaster b on a.srocode = b.srocode
join kaveri.documentmaster c on b.documentid = c.documentid
join kaveri.courtorders d on b.srocode = d.srocode
where --a.srocode = _srocode and 
	iscancelled = false and
registrationdatetime >= _pending_cases_from_date and 
registrationdatetime <= _pending_cases_to_date and issuingauthority like 'High%'
group by a.srocode) pending_Highcourt_during_march_2022 
on a.srocode = pending_Highcourt_during_march_2022.srocode
join
(
select b.srocode,
	count(d.ordernumber) no_casespending_Highcourt_during_fy_2022_23,
	sum(amount) amount_casespending_Highcourt_during_fy_2022_23
	from kaveri.liabilitydetails a join 
kaveri.referencemaster b on a.srocode = b.srocode
join kaveri.documentmaster c on b.documentid = c.documentid
join kaveri.courtorders d on b.srocode = d.srocode
where --a.srocode = _srocode and 
	iscancelled = false and
registrationdatetime >= _from_date and 
registrationdatetime <= _to_date and issuingauthority like 'High%'
group by b.srocode) pending_Highcourt_during_fy_2022_23
on a.srocode = pending_Highcourt_during_fy_2022_23.srocode
join
(
select a.srocode,
	count(d.ordernumber) no_casespending_various_courts_during_march_2022,
	sum(amount) amount_casespending_various_courts_during_march_2022
	from kaveri.liabilitydetails a join 
kaveri.referencemaster b on a.srocode = b.srocode
join kaveri.documentmaster c on b.documentid = c.documentid
join kaveri.courtorders d on b.srocode = d.srocode
where --a.srocode = _srocode and 
	iscancelled = false and
registrationdatetime >= _pending_cases_from_date and 
registrationdatetime <= _pending_cases_to_date
	group by a.srocode
) pending_various_courts_during_march_2022  on a.srocode = pending_various_courts_during_march_2022.srocode
join
(
select a.srocode,
	count(d.ordernumber) no_casespending_various_courts_during_fy_2022_23,
	sum(amount) amount_casespending_various_courts_during_fy_2022_23
	from kaveri.liabilitydetails a join 
kaveri.referencemaster b on a.srocode = b.srocode
join kaveri.documentmaster c on b.documentid = c.documentid
join kaveri.courtorders d on b.srocode = d.srocode
where --a.srocode = _srocode and 
	iscancelled = false and
registrationdatetime >= _from_date and 
registrationdatetime <= _to_date 
group by a.srocode
) pending_various_courts_during_fy_2022_23 on a.srocode = pending_various_courts_during_fy_2022_23.srocode
join
(
select a.srocode, 
	count(d.ordernumber) no_disposedcases_during_fy_2022_2023,
	sum(amount) amountpending_disposedcases_during_fy_2022_2023
	from kaveri.liabilitydetails a join 
kaveri.referencemaster b on a.srocode = b.srocode
join kaveri.documentmaster c on b.documentid = c.documentid
join kaveri.courtorders d on b.srocode = d.srocode
where --a.srocode = _srocode and 
	iscancelled = true and
registrationdatetime >= _from_date and 
registrationdatetime <= _to_date
	group by a.srocode
) disposedcases_during_fy_2022_2023 on a.srocode = disposedcases_during_fy_2022_2023.srocode
join
(
select a.srocode,
	count(d.ordernumber) noofcases_pending_end_of_reporting_month,
	sum(amount) amountpending_end_of_reporting_month
	from kaveri.liabilitydetails a join 
kaveri.referencemaster b on a.srocode = b.srocode
join kaveri.documentmaster c on b.documentid = c.documentid
join kaveri.courtorders d on b.srocode = d.srocode
where --a.srocode = _srocode and 
	iscancelled = true and
registrationdatetime >= _pending_cases_from_date and 
registrationdatetime <= _pending_cases_to_date
	group by a.srocode
) pending_at_the_end_of_reporting_month on a.srocode = pending_at_the_end_of_reporting_month.srocode
where a.districtcode = _districtcode
group by sronamee,
pending_Highcourt_during_march_2022.no_casespending_Highcourt_during_march_2022,
pending_Highcourt_during_march_2022.amount_casespending_Highcourt_during_march_2022,
pending_Highcourt_during_fy_2022_23.no_casespending_Highcourt_during_fy_2022_23,
pending_Highcourt_during_fy_2022_23.amount_casespending_Highcourt_during_fy_2022_23,
pending_various_courts_during_march_2022.no_casespending_various_courts_during_march_2022,
pending_various_courts_during_march_2022.amount_casespending_various_courts_during_march_2022,
pending_various_courts_during_fy_2022_23.no_casespending_various_courts_during_fy_2022_23,
pending_various_courts_during_fy_2022_23.amount_casespending_various_courts_during_fy_2022_23,
disposedcases_during_fy_2022_2023.no_disposedcases_during_fy_2022_2023,
 disposedcases_during_fy_2022_2023.amountpending_disposedcases_during_fy_2022_2023,
  pending_at_the_end_of_reporting_month.noofcases_pending_end_of_reporting_month,
 pending_at_the_end_of_reporting_month.amountpending_end_of_reporting_month;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form_36_details_of_pending_cases_in_various_courts(_districtcode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _pending_cases_from_date timestamp without time zone, _pending_cases_to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

