CREATE FUNCTION kaverimis.fn_mis_form_37_details_of_pending_cases_in_various_courts_46_a(_districtcode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _pending_cases_from_date timestamp without time zone, _pending_cases_to_date timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(nameoftheoffice character varying, no_casespending_kat_month_prev_fy integer, amount_casespending_kat_month_prev_fy integer, no_casespending_kat_during_fy integer, amount_casespending_kat_during_fy integer, no_casespending_kat integer, total_casespending_kat integer, no_casespending_highcourt_during_month_prev_fy bigint, amount_casespending_highcourt_during_month_prev_fy numeric, no_casespending_highcourt_during_fy_2022_23 bigint, amount_casespending_highcourt_during_fy_2022_23 numeric, total_cases_pending_highcourt bigint, total_amount_pending_highcourt numeric, no_casespending_supreme_court_comm_month_prev_fy integer, amount_casespending_supreme_court_month_prev_fy integer, no_casespending_supreme_court_comm_fy_2022_23 integer, amount_casespending_supreme_court_fy_2022_23 integer, no_casespending_supreme_court integer, total_casespending_supreme_court integer, no_casespending_various_courts_during_month_prev_fy bigint, amount_casespending_various_courts_during_month_prev_fy numeric, no_casespending_various_courts_during_during_fy bigint, amount_casespending_various_courts_during_during_fy numeric, totalcasespending_various_courts bigint, totalamountpending_various_courts numeric, total_no_casespending bigint, total_amountpending numeric, no_disposedcases_during_during_fy bigint, amountpending_disposedcases_during_fy numeric, noofcases_pending_end_of_reporting_month bigint, amountpending_end_of_reporting_month numeric, no_of_cases_received_stay_order integer, amount_pending_receiving_stay_order integer)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
	return query 
select sronamee as Nameoftheoffice,

/* Cases in the KAT and the amount involved */

0 as no_casespending_kat_month_prev_fy,
0 as amount_casespending_KAT_prev_fy,
0 as no_casespending_KAT_during_fy,
0 as amount_casespending_KAT_during_fy,
0 as no_casespending_kat,
0 as total_casespending_KAT,

/* Appeals in the High Courts and the amount involved */

pending_Highcourt_during_march_2022.no_casespending_Highcourt_during_march_2022 as no_casespending_highcourt_during_month_prev_fy,
pending_Highcourt_during_march_2022.amount_casespending_Highcourt_during_march_2022 as amount_casespending_highcourt_during_month_prev_fy,
pending_Highcourt_during_fy_2022_23.no_casespending_Highcourt_during_fy_2022_23 as no_casespending_Highcourt_during_fy,
