(pending_Highcourt_during_march_2022.no_casespending_Highcourt_during_march_2022 +
pending_Highcourt_during_fy_2022_23.no_casespending_Highcourt_during_fy_2022_23) Total_cases_pending_highcourt,
(pending_Highcourt_during_march_2022.amount_casespending_Highcourt_during_march_2022 +
pending_Highcourt_during_fy_2022_23.amount_casespending_Highcourt_during_fy_2022_23) Total_amount_pending_highcourt,

/* Appeals filed in Supreme Court and amount involved */

0 as no_casespending_supreme_court_comm_month_prev_fy,
0 as amount_casespending_supreme_court_month_prev_fy,
0 as no_casespending_supreme_court_comm_during_fy,
0 as amount_casespending_supreme_court_during_fy,
0 as no_casespending_supreme_court,
0 as total_casespending_supreme_court,

/* The Number of cases pending in various courts */
pending_various_courts_during_march_2022.no_casespending_various_courts_during_march_2022 as  no_casespending_various_courts_during_month_prev_fy,
pending_various_courts_during_march_2022.amount_casespending_various_courts_during_march_2022 as amount_casespending_various_courts_during_during_fy,
pending_various_courts_during_fy_2022_23.no_casespending_various_courts_during_fy_2022_23 as no_casespending_various_courts_during_fy,
pending_various_courts_during_fy_2022_23.amount_casespending_various_courts_during_fy_2022_23 as amount_casespending_various_courts_during_fy,
(pending_various_courts_during_march_2022.no_casespending_various_courts_during_march_2022 +
pending_various_courts_during_fy_2022_23.no_casespending_various_courts_during_fy_2022_23) totalcasespending_various_courts,
(pending_various_courts_during_march_2022.amount_casespending_various_courts_during_march_2022 +
pending_various_courts_during_fy_2022_23.amount_casespending_various_courts_during_fy_2022_23) totalamountpending_various_courts,

/* Total cases and amount involved */

(0 + (pending_Highcourt_during_march_2022.no_casespending_Highcourt_during_march_2022 +
pending_Highcourt_during_fy_2022_23.no_casespending_Highcourt_during_fy_2022_23) +
0 + (pending_various_courts_during_march_2022.no_casespending_various_courts_during_march_2022 +
pending_various_courts_during_fy_2022_23.no_casespending_various_courts_during_fy_2022_23) +
(pending_various_courts_during_march_2022.no_casespending_various_courts_during_march_2022 +
pending_various_courts_during_fy_2022_23.no_casespending_various_courts_during_fy_2022_23)
) Total_no_casespending,

(0 + (pending_Highcourt_during_march_2022.amount_casespending_Highcourt_during_march_2022 +
pending_Highcourt_during_fy_2022_23.amount_casespending_Highcourt_during_fy_2022_23) +
0 + (pending_various_courts_during_march_2022.amount_casespending_various_courts_during_march_2022 +
pending_various_courts_during_fy_2022_23.amount_casespending_various_courts_during_fy_2022_23) +
(pending_various_courts_during_march_2022.amount_casespending_various_courts_during_march_2022 +
pending_various_courts_during_fy_2022_23.amount_casespending_various_courts_during_fy_2022_23)
) Total_amountpending,

 /* Disposed cases and amount involved in the year 2022-23 */
 
 disposedcases_during_fy_2022_2023.no_disposedcases_during_fy_2022_2023 as no_disposedcases_during_fy,
 disposedcases_during_fy_2022_2023.amountpending_disposedcases_during_fy_2022_2023 as amountpending_disposedcases_during_fy,
 
 /* Cases pending at the end of the reporting month and amount involved */
 
 pending_at_the_end_of_reporting_month.noofcases_pending_end_of_reporting_month,
 pending_at_the_end_of_reporting_month.amountpending_end_of_reporting_month,
 
 
 /* No. of cases which received stay order from court and amount involved */
 
 0 no_of_cases_received_stay_order,
 0 amount_pending_receiving_stay_order
 
from 
kaveri.sromaster a 
join
(
select a.srocode,
	count(d.ordernumber) no_casespending_Highcourt_during_march_2022,
	sum(amount) amount_casespending_Highcourt_during_march_2022 from kaveri.liabilitydetails a join 
kaveri.referencemaster b on a.srocode = b.srocode
join kaveri.documentmaster c on b.documentid = c.documentid
join kaveri.courtorders d on b.srocode = d.srocode
where --a.srocode = _srocode and 
	iscancelled = false and
registrationdatetime >= _pending_cases_from_date and 
registrationdatetime <= _pending_cases_to_date and issuingauthority like 'High%'
group by a.srocode) pending_Highcourt_during_march_2022 
on a.srocode = pending_Highcourt_during_march_2022.srocode
join
(
select b.srocode,
	count(d.ordernumber) no_casespending_Highcourt_during_fy_2022_23,
	sum(amount) amount_casespending_Highcourt_during_fy_2022_23
	from kaveri.liabilitydetails a join 
kaveri.referencemaster b on a.srocode = b.srocode
join kaveri.documentmaster c on b.documentid = c.documentid
join kaveri.courtorders d on b.srocode = d.srocode
where --a.srocode = _srocode and 
	iscancelled = false and
registrationdatetime >= _from_date and 
registrationdatetime <= _to_date and issuingauthority like 'High%'
group by b.srocode) pending_Highcourt_during_fy_2022_23
on a.srocode = pending_Highcourt_during_fy_2022_23.srocode
join
(
select a.srocode,
	count(d.ordernumber) no_casespending_various_courts_during_march_2022,
	sum(amount) amount_casespending_various_courts_during_march_2022
	from kaveri.liabilitydetails a join 
kaveri.referencemaster b on a.srocode = b.srocode
join kaveri.documentmaster c on b.documentid = c.documentid
join kaveri.courtorders d on b.srocode = d.srocode
where --a.srocode = _srocode and 
	iscancelled = false and
registrationdatetime >= _pending_cases_from_date and 
registrationdatetime <= _pending_cases_to_date
	group by a.srocode
) pending_various_courts_during_march_2022  on a.srocode = pending_various_courts_during_march_2022.srocode
join
(
select a.srocode,
	count(d.ordernumber) no_casespending_various_courts_during_fy_2022_23,
	sum(amount) amount_casespending_various_courts_during_fy_2022_23
	from kaveri.liabilitydetails a join 
kaveri.referencemaster b on a.srocode = b.srocode
join kaveri.documentmaster c on b.documentid = c.documentid
join kaveri.courtorders d on b.srocode = d.srocode
where --a.srocode = _srocode and 
	iscancelled = false and
registrationdatetime >= _from_date and 
registrationdatetime <= _to_date 
group by a.srocode
) pending_various_courts_during_fy_2022_23 on a.srocode = pending_various_courts_during_fy_2022_23.srocode
join
(
select a.srocode, 
	count(d.ordernumber) no_disposedcases_during_fy_2022_2023,
	sum(amount) amountpending_disposedcases_during_fy_2022_2023
	from kaveri.liabilitydetails a join 
kaveri.referencemaster b on a.srocode = b.srocode
join kaveri.documentmaster c on b.documentid = c.documentid
join kaveri.courtorders d on b.srocode = d.srocode
where --a.srocode = _srocode and 
	iscancelled = true and
registrationdatetime >= _from_date and 
registrationdatetime <= _to_date
	group by a.srocode
) disposedcases_during_fy_2022_2023 on a.srocode = disposedcases_during_fy_2022_2023.srocode
join
(
select a.srocode,
	count(d.ordernumber) noofcases_pending_end_of_reporting_month,
	sum(amount) amountpending_end_of_reporting_month
	from kaveri.liabilitydetails a join 
kaveri.referencemaster b on a.srocode = b.srocode
join kaveri.documentmaster c on b.documentid = c.documentid
join kaveri.courtorders d on b.srocode = d.srocode
where --a.srocode = _srocode and 
	iscancelled = true and
registrationdatetime >= _pending_cases_from_date and 
registrationdatetime <= _pending_cases_to_date
	group by a.srocode
