            WHEN a.statuscode = 0 THEN 'F'::text
            WHEN a.statuscode = 1 THEN 'DRO Added an Order'::text
            WHEN a.statuscode = 2 THEN 'Assigned to DEO for Rescan'::text
            WHEN a.statuscode = 3 THEN 'Rescan Completed'::text
            WHEN a.statuscode = 4 THEN 'F'::text
            ELSE NULL::text
        END AS  actionpending
	FROM kaveri.dec_drordermaster a
     JOIN kaveri.dec_drpndnote b ON a.orderid = b.orderid 
     JOIN kaveri.documentmaster c ON a.documentid = c.documentid
   	 JOIN kaveri.sromaster f on c.srocode = f.srocode
	 JOIN kaveri.districtmaster g on f.districtcode = g.districtcode
	 where   a.orderdate::date>=_from_date and a.orderdate::date<=_to_date
	 and c.isregistrationcompleted = true 
	 and g.districtcode=_districtcode),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true 
			
			where total_row.total_rows<>0 
			
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
	 --and f.srocode=_srocode
	 
	 ELSE
	 
	 return query 
	with cte as (SELECT distinct 
	g.districtnamee as drooffice,
	f.sronamee as srooffice,
	a.absolutefilepath as Order_Uploaded_By_District_registrar,
	a.ordernumber AS drordernumber,
	a.orderdate,
	b.note_enteredpart AS note,
	c.finalregistrationnumber as registrationnnumber,
	CASE
            WHEN a.statuscode = 0 THEN 'Pending'::text
            WHEN a.statuscode = 1 THEN 'Drorder'::text
            WHEN a.statuscode = 2 THEN 'Deorescan'::text
            WHEN a.statuscode = 3 THEN 'Rescandone'::text
            WHEN a.statuscode = 4 THEN 'Finalized'::text
            ELSE 'Finalized'::text
    END AS status,
    a.absolutefilepath AS view_dr_order_copy,
    CASE
            WHEN a.statuscode = 0 THEN 'F'::text
            WHEN a.statuscode = 1 THEN 'DRO Added an Order'::text
            WHEN a.statuscode = 2 THEN 'Assigned to DEO for Rescan'::text
            WHEN a.statuscode = 3 THEN 'Rescan Completed'::text
            WHEN a.statuscode = 4 THEN 'F'::text
            ELSE NULL::text
        END AS  actionpending
	FROM kaveri.dec_drordermaster a
     JOIN kaveri.dec_drpndnote b ON a.orderid = b.orderid 
     JOIN kaveri.documentmaster c ON a.documentid = c.documentid
   	 JOIN kaveri.sromaster f on c.srocode = f.srocode
	 JOIN kaveri.districtmaster g on f.districtcode = g.districtcode
	 where   a.orderdate::date>=_from_date and a.orderdate::date<=_to_date
	 and c.isregistrationcompleted = true 
	 and g.districtcode=_districtcode
	 and f.srocode=_srocode),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true 
			where total_row.total_rows<>0 
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
	 end if;
END;
$$;


