CREATE FUNCTION kaverimis.fn_mis_form_details_of_29(_districtcode integer, _srocode integer, _before_fy_from_date timestamp without time zone, _before_fy_to_date timestamp without time zone, _month_of_report_from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _month_of_report_to_date timestamp without time zone DEFAULT NULL::timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, nameofsubregistrationoffice character varying, b_document_reg bigint, b_pages_scanned bigint, b_scanningfees numeric, in_document_reg bigint, in_pages_scanned bigint, in_scanningfees numeric, total_document_reg bigint, total_pages_scanned bigint, total_scanningfees numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if(_districtcode=0)	 then

	return query

with cte as (select distinct
d.districtnamee as districtname,
s.sronamee as Nameofsubregistrationoffice,
month_before.b_document_reg,
month_before.b_pages_scanned,
month_before.b_Scanningfees,

In_month.In_document_reg,
In_month.In_pages_scanned,
In_month.In_Scanningfees,

month_before.b_document_reg+In_month.In_document_reg as Total_document_reg,
month_before.b_pages_scanned+In_month.In_pages_scanned as Total_pages_scanned,
In_month.In_Scanningfees+month_before.b_Scanningfees as Total_Scanningfees

from kaveri.sromaster s
join kaveri.districtmaster d on s.districtcode =d.districtcode 

join
(
with a as (
select distinct a.srocode,
count(distinct a.applicationnumber) as b_document_reg,
sum(p.sronoofscanpages) as b_pages_scanned
from kaveri.documentmaster a
join kaveri.applicantapplicationdetails a2 on a2.applicationnumber = a.applicationnumber
join kaveri.feesrequired f on f.applicationnumber = a.applicationnumber and f.feerulecode = 2
join kaveri.sromaster s on a.srocode  =s.srocode 
join kaveri.districtmaster d on s.districtcode =d.districtcode 
join(
select distinct applicationnumber ,sronoofscanpages from
kaveri.propertymaster) p on a.applicationnumber =p.applicationnumber
 where a.isregistrationcompleted = true and 
 --a2.currentstatus = 'CD120' and 
--a.srocode = _srocode and 
--d.districtcode =_districtcode and 
a.registrationdatetime ::date>= _before_fy_from_date and a.registrationdatetime ::date<= _before_fy_to_date
group by a.srocode)
select a.*,
sum(case when fr.feerulecode=2 then fr.amountpaid else 0 end) as b_Scanningfees
from kaveri.feesrequired fr
join kaveri.documentmaster dm on dm.applicationnumber = fr.applicationnumber
join a on dm.srocode = a.srocode
where dm.registrationdatetime ::date>= _before_fy_from_date and dm.registrationdatetime ::date<= _before_fy_to_date
group by a.srocode,
a.b_document_reg, a.b_pages_scanned)month_before on month_before.srocode=s.srocode

left join 
(
with a as (
select distinct a.srocode,
count(distinct a.applicationnumber) as In_document_reg,
sum(p.sronoofscanpages) as In_pages_scanned
from kaveri.documentmaster a
