group by a.srocode,
a.In_document_reg, a.In_pages_scanned)In_month on In_month.srocode=s.srocode),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

