ALTER FUNCTION kaverimis.fn_mis_form_details_of_29_23012024(_districtcode integer, _srocode integer, _before_fy_from_date timestamp without time zone, _before_fy_to_date timestamp without time zone, _month_of_report_from_date timestamp without time zone, _month_of_report_to_date timestamp without time zone) OWNER TO csgadmin;

--
-- Name: fn_mis_form_details_surcharge_fin_26(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_form_details_surcharge_fin_26(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, nameofsubregistrationoffice character varying, numberofdocuments bigint, governmentstampfee numeric, bbmp_surcharge numeric, city_corporation numeric, municipality numeric, town_municipalcouncil numeric, town_panchayat numeric, government_comission_surcharge numeric, net_surcharge numeric, taluk_panchayat numeric, government_comission numeric, net_surchargetwo integer, total_surcharge numeric, bmrtl_cess_stamp_duty numeric, registrationfee numeric, totalrevenue numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;

BEGIN	
	PageOffset := (pagesize*pagenumber) - pagesize;
	
	if (pagenumber<>-1 and pagesize<>-1) then
	
	return query

		with cte as ( with a as (select  distinct

				dm.districtnamee as districtname, 
				s.sronamee as Nameofsubregistrationoffice,
				d.applicationnumber,
				r.regionid 
				
 				from kaveri.documentmaster d 
				join kaveri.applicantapplicationdetails a on d.applicationnumber = a.applicationnumber 
				join kaveri.sromaster s on d.srocode = s.srocode  
				join kaveri.districtmaster dm on s.districtcode =dm.districtcode 
				left join  kaveri.propertymaster pm on d.applicationnumber = pm.applicationnumber
				left join kaveri.roadmaster r on pm.roadcode=r.roadcode and pm.villagecode=r.villagecode
				
				
				where d.isregistrationcompleted=true and 
				--a.currentstatus = 'CD120' and
			(d.registrationdatetime between _from_date and  _to_date+ INTERVAL '1 day')
								
			and (case
					when _districtcode <> 0 then dm.districtcode = _districtcode
					else
						true
				end)
				
				and (case
					when _srocode<>0 then d.srocode =_srocode
					else true
				end)
			)
			select 
			a.districtname,
			a.Nameofsubregistrationoffice,
			count(distinct a.applicationnumber) as numberofdocuments,
				sum(case when f.feerulecode = 36 then (f.amountpaid) * 0.05 else 0 end) as Governmentstampfee,
				sum(case when f.feerulecode = 58 and a.regionid = 1 then (f.amountpaid) * 0.02  else 0 end )as BBMP_Surcharge, 
				sum(case when f.feerulecode=58 and a.regionid =2 then  (f.amountpaid) * 0.02  else 0 end) as City_Corporation , 
				sum(case when f.feerulecode=58 and a.regionid =3 then  (f.amountpaid) * 0.02 else 0 end) as Municipality, 
				sum(case when f.feerulecode=58 and a.regionid =7 then  (f.amountpaid) * 0.02  else 0 end) as Town_MunicipalCouncil, 
				sum(case when f.feerulecode=58 and a.regionid =4 then  (f.amountpaid) * 0.02  else 0 end) as Town_Panchayat, 
				sum(case when f.feerulecode = 58 then (f.amountpaid) * 0.1 else 0 end )as Government_comission_Surcharge ,
--				sum(case when f.feerulecode=58 and a.regionid in (2,3,4,7) then f.amountpaid  else 0 end)as Net_Surcharge,
				
				sum(case when f.feerulecode=58 and a.regionid =2 then  (f.amountpaid) * 0.02  else 0 end)+
				sum(case when f.feerulecode=58 and a.regionid =3 then  (f.amountpaid) * 0.02 else 0 end)+
				sum(case when f.feerulecode=58 and a.regionid =7 then  (f.amountpaid) * 0.02  else 0 end)+
				sum(case when f.feerulecode=58 and a.regionid =4 then  (f.amountpaid) * 0.02  else 0 end) as Net_Surcharge,

				sum(case when f.feerulecode=58 and a.regionid =5 then (f.amountpaid) * 0.03 else 0 end) as taluk_panchayat,
				sum(case when f.feerulecode = 58 then (f.amountpaid) * 0.03 else 0 end ) as government_comission, 
				
				0 as Net_Surchargetwo,
				
				sum(case when f.feerulecode=58 and a.regionid in (1,2,3,7,4,5) then f.amountpaid else 0 end) +
				sum(case when f.feerulecode = 58 then (f.amountpaid) * 0.03 else 0 end ) as Total_Surcharge, 

				sum(case when f.feerulecode = 59 then (f.amountpaid) * 0.10 else 0 end) as BMRTL_CESS_stamp_duty, 

				sum(case when f.feerulecode = 1 then  f.amountpaid else 0 end )as registrationfee, 
		
--				sum(case when f.feerulecode=58 and a.regionid =5 then f.amountpaid else 0 end) +
--				sum(case when f.feerulecode = 58 then ((f.amountpaid) * .03) else 0 end )+
--				sum(case when f.feerulecode = 59 then f.amountpaid else 0 end)+
--				sum(case when f.feerulecode = 1 then  f.amountpaid else 0 end )+
--				sum(case when f.feerulecode = 36 then f.amountpaid else 0 end) as Totalrevenue
				
				sum(case when f.feerulecode = 36 then (f.amountpaid) * 0.05 else 0 end)+
				sum(case when f.feerulecode = 58 and a.regionid = 1 then (f.amountpaid) * 0.02  else 0 end )+
				sum(case when f.feerulecode=58 and a.regionid =2 then  (f.amountpaid) * 0.02  else 0 end)+
				sum(case when f.feerulecode=58 and a.regionid =2 then  (f.amountpaid) * 0.02  else 0 end)+
				sum(case when f.feerulecode=58 and a.regionid =3 then  (f.amountpaid) * 0.02 else 0 end)+
				sum(case when f.feerulecode=58 and a.regionid =7 then  (f.amountpaid) * 0.02  else 0 end)+
				sum(case when f.feerulecode=58 and a.regionid =4 then  (f.amountpaid) * 0.02  else 0 end)+
				sum(case when f.feerulecode=58 and a.regionid =5 then (f.amountpaid) * 0.03 else 0 end)+
				sum(case when f.feerulecode = 58 then (f.amountpaid) * 0.03 else 0 end )+
				sum(case when f.feerulecode = 59 then (f.amountpaid) * 0.10 else 0 end)+
				sum(case when f.feerulecode = 1 then  f.amountpaid else 0 end ) as Totalrevenue
				
				from a
				join  kaveri.feesrequired f on  a.applicationnumber =f.applicationnumber 
				join (select applicationnumber from kaveri.feesrequired f2 where f2.applicationnumber in 
				(select applicationnumber from a) group by applicationnumber having 
				(case 
				WHEN _minval is not null and _maxval is not null then
	
				 sum(amountpaid) >= _minval and sum(amountpaid) <= _maxval    
		
				ELSE 
					 true 
			end
				)
				) f3 on a.applicationnumber=f3.applicationnumber 
				
				group by a.districtname,a.Nameofsubregistrationoffice),cte_count as (select count(*) as total_rows from cte)

            select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0 					
			limit pagesize offset PageOffset;

elsif (pagenumber=-1 or  pagesize=-1) then 

		return query

		with cte as ( with a as (select  distinct

				dm.districtnamee as districtname, 
				s.sronamee as Nameofsubregistrationoffice,
				d.applicationnumber,
				r.regionid 
				
 				from kaveri.documentmaster d  
				join kaveri.applicantapplicationdetails a on d.applicationnumber = a.applicationnumber 
				join kaveri.sromaster s on d.srocode = s.srocode  
				join kaveri.districtmaster dm on s.districtcode =dm.districtcode 
				left join  kaveri.propertymaster pm on d.applicationnumber = pm.applicationnumber
				left join kaveri.roadmaster r on pm.roadcode=r.roadcode and pm.villagecode=r.villagecode
				
				
				where d.isregistrationcompleted=true and 
				--a.currentstatus = 'CD120' and
			(d.registrationdatetime between _from_date and  _to_date+ INTERVAL '1 day')
								
			and (case
					when _districtcode <> 0 then dm.districtcode = _districtcode
					else
						true
				end)
				
				and (case
					when _srocode<>0 then d.srocode =_srocode
					else true
				end)
			)
			select 
			a.districtname,
			a.Nameofsubregistrationoffice,
			count(distinct a.applicationnumber) as numberofdocuments,
				sum(case when f.feerulecode = 36 then (f.amountpaid) * 0.05 else 0 end) as Governmentstampfee,
				sum(case when f.feerulecode = 58 and a.regionid = 1 then (f.amountpaid) * 0.02  else 0 end )as BBMP_Surcharge, 
				sum(case when f.feerulecode=58 and a.regionid =2 then  (f.amountpaid) * 0.02  else 0 end) as City_Corporation , 
				sum(case when f.feerulecode=58 and a.regionid =3 then  (f.amountpaid) * 0.02 else 0 end) as Municipality, 
				sum(case when f.feerulecode=58 and a.regionid =7 then  (f.amountpaid) * 0.02  else 0 end) as Town_MunicipalCouncil, 
				sum(case when f.feerulecode=58 and a.regionid =4 then  (f.amountpaid) * 0.02  else 0 end) as Town_Panchayat, 
				sum(case when f.feerulecode = 58 then (f.amountpaid) * 0.1 else 0 end )as Government_comission_Surcharge ,
--				sum(case when f.feerulecode=58 and a.regionid in (2,3,4,7) then f.amountpaid  else 0 end)as Net_Surcharge,
				
				sum(case when f.feerulecode=58 and a.regionid =2 then  (f.amountpaid) * 0.02  else 0 end)+
				sum(case when f.feerulecode=58 and a.regionid =3 then  (f.amountpaid) * 0.02 else 0 end)+
				sum(case when f.feerulecode=58 and a.regionid =7 then  (f.amountpaid) * 0.02  else 0 end)+
				sum(case when f.feerulecode=58 and a.regionid =4 then  (f.amountpaid) * 0.02  else 0 end) as Net_Surcharge,

				sum(case when f.feerulecode=58 and a.regionid =5 then (f.amountpaid) * 0.03 else 0 end) as taluk_panchayat,
				sum(case when f.feerulecode = 58 then (f.amountpaid) * 0.03 else 0 end ) as government_comission, 
				
				0 as Net_Surchargetwo,
				
				sum(case when f.feerulecode=58 and a.regionid in (1,2,3,7,4,5) then f.amountpaid else 0 end) +
				sum(case when f.feerulecode = 58 then (f.amountpaid) * 0.03 else 0 end ) as Total_Surcharge, 

				sum(case when f.feerulecode = 59 then (f.amountpaid) * 0.10 else 0 end) as BMRTL_CESS_stamp_duty, 

				sum(case when f.feerulecode = 1 then  f.amountpaid else 0 end )as registrationfee, 
		
--				sum(case when f.feerulecode=58 and a.regionid =5 then f.amountpaid else 0 end) +
--				sum(case when f.feerulecode = 58 then ((f.amountpaid) * .03) else 0 end )+
--				sum(case when f.feerulecode = 59 then f.amountpaid else 0 end)+
--				sum(case when f.feerulecode = 1 then  f.amountpaid else 0 end )+
--				sum(case when f.feerulecode = 36 then f.amountpaid else 0 end) as Totalrevenue
				
				sum(case when f.feerulecode = 36 then (f.amountpaid) * 0.05 else 0 end)+
				sum(case when f.feerulecode = 58 and a.regionid = 1 then (f.amountpaid) * 0.02  else 0 end )+
				sum(case when f.feerulecode=58 and a.regionid =2 then  (f.amountpaid) * 0.02  else 0 end)+
				sum(case when f.feerulecode=58 and a.regionid =2 then  (f.amountpaid) * 0.02  else 0 end)+
				sum(case when f.feerulecode=58 and a.regionid =3 then  (f.amountpaid) * 0.02 else 0 end)+
				sum(case when f.feerulecode=58 and a.regionid =7 then  (f.amountpaid) * 0.02  else 0 end)+
				sum(case when f.feerulecode=58 and a.regionid =4 then  (f.amountpaid) * 0.02  else 0 end)+
				sum(case when f.feerulecode=58 and a.regionid =5 then (f.amountpaid) * 0.03 else 0 end)+
				sum(case when f.feerulecode = 58 then (f.amountpaid) * 0.03 else 0 end )+
				sum(case when f.feerulecode = 59 then (f.amountpaid) * 0.10 else 0 end)+
				sum(case when f.feerulecode = 1 then  f.amountpaid else 0 end ) as Totalrevenue
				
				from a
				join  kaveri.feesrequired f on  a.applicationnumber =f.applicationnumber 
				join (select applicationnumber from kaveri.feesrequired f2 where f2.applicationnumber in 
				(select applicationnumber from a) group by applicationnumber having 
				(case 
				WHEN _minval is not null and _maxval is not null then
	
				 sum(amountpaid) >= _minval and sum(amountpaid) <= _maxval    
		
				ELSE 
					 true 
			end
				)
				) f3 on a.applicationnumber=f3.applicationnumber 
				
				group by a.districtname,a.Nameofsubregistrationoffice),cte_count as (select count(*) as total_rows from cte)

            select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0;

end if ;
END

$$;


