				sum(case when f.feerulecode=58 and r.regionid =3 then  f.amountpaid else 0 end) + 

				sum(case when f.feerulecode=58 and r.regionid =7 then  f.amountpaid  else 0 end)+ 

				sum(case when f.feerulecode=58 and r.regionid =4 then  f.amountpaid  else 0 end)+
				sum(case when f.feerulecode=58 and r.regionid =5 then f.amountpaid else 0 end) +
				sum(case when f.feerulecode = 58 then ((f.amountpaid) * .03) else 0 end ) as Total_Surcharge, 

				sum(case when f.feerulecode = 59 then f.amountpaid else 0 end) as BMRTL_CESS_stamp_duty, 

				sum(case when f.feerulecode = 1 then  f.amountpaid else 0 end )as registrationfee, 

				sum(case when f.feerulecode = 58 and r.regionid = 1 then f.amountpaid  else 0 end )+ 

				sum(case when f.feerulecode=58 and r.regionid =2 then  f.amountpaid  else 0 end)+ 

				sum(case when f.feerulecode=58 and r.regionid =3 then  f.amountpaid else 0 end) + 

				sum(case when f.feerulecode=58 and r.regionid =7 then  f.amountpaid  else 0 end)+ 

				sum(case when f.feerulecode=58 and r.regionid =4 then  f.amountpaid  else 0 end)+
				sum(case when f.feerulecode=58 and r.regionid =5 then f.amountpaid else 0 end) +
				sum(case when f.feerulecode = 58 then ((f.amountpaid) * .03) else 0 end )+
				sum(case when f.feerulecode = 59 then f.amountpaid else 0 end)+
				sum(case when f.feerulecode = 1 then  f.amountpaid else 0 end )+ 
				sum(case when f.feerulecode = 36 then f.amountpaid else 0 end) as Totalrevenue 

				from kaveri.documentmaster d  

				join kaveri.feesrequired f on d.documentid =f.documentid and d.applicationnumber =f.applicationnumber  

				join kaveri.sromaster s on d.srocode =s.srocode  
				--
				join kaveri.districtmaster dm on s.districtcode =dm.districtcode 
				join (select distinct applicationnumber,villagecode,roadcode from kaveri.propertymaster ) pm   on d.applicationnumber=pm.applicationnumber
				join kaveri.roadmaster r on pm.roadcode=r.roadcode and pm.villagecode=r.villagecode 
							

				where d.isregistrationcompleted = true 

				and dm.districtcode = _districtcode 

				and d.srocode =_srocode 

				and d.registrationdatetime::date >= _from_date

				and d.registrationdatetime::date <= _to_date

				group by dm.districtnamee,s.sronamee;
				
		ELSE
		
		
				return query

				select distinct  

				dm.districtnamee as districtname, 

				s.sronamee as Nameofsubregistrationoffice, 

				count(distinct d.applicationnumber) as numberofdocuments,

				sum(case when f.feerulecode = 36 then f.amountpaid else 0 end) as Governmentstampfee,

				sum(case when f.feerulecode = 58 and r.regionid = 1 then f.amountpaid  else 0 end )as BBMP_Surcharge, 

				sum(case when f.feerulecode=58 and r.regionid =2 then  f.amountpaid  else 0 end) as City_Corporation , 

				sum(case when f.feerulecode=58 and r.regionid =3 then  f.amountpaid else 0 end) as Municipality, 

				sum(case when f.feerulecode=58 and r.regionid =7 then  f.amountpaid  else 0 end) as Town_MunicipalCouncil, 

				sum(case when f.feerulecode=58 and r.regionid =4 then  f.amountpaid  else 0 end) as Town_Panchayat, 

				sum(case when f.feerulecode = 58 then (f.amountpaid) * 0.1 else 0 end )as Government_comission_Surcharge ,

				(sum(case when f.feerulecode = 58 and r.regionid = 1 then f.amountpaid  else 0 end )+ 

				sum(case when f.feerulecode=58 and r.regionid =2 then  f.amountpaid  else 0 end)+ 

				sum(case when f.feerulecode=58 and r.regionid =3 then  f.amountpaid else 0 end) + 

				sum(case when f.feerulecode=58 and r.regionid =7 then  f.amountpaid  else 0 end)+ 

				sum(case when f.feerulecode=58 and r.regionid =4 then  f.amountpaid  else 0 end)) as Net_Surcharge, 

				sum(case when f.feerulecode=58 and r.regionid =5 then f.amountpaid else 0 end) as taluk_panchayat, 

				sum(case when f.feerulecode = 58 then ((f.amountpaid) * .03) else 0 end ) as government_comission, 

				0 as Net_Surchargetwo, 

				sum(case when f.feerulecode = 58 and r.regionid = 1 then f.amountpaid  else 0 end )+ 

				sum(case when f.feerulecode=58 and r.regionid =2 then  f.amountpaid  else 0 end)+ 

				sum(case when f.feerulecode=58 and r.regionid =3 then  f.amountpaid else 0 end) + 

				sum(case when f.feerulecode=58 and r.regionid =7 then  f.amountpaid  else 0 end)+ 

				sum(case when f.feerulecode=58 and r.regionid =4 then  f.amountpaid  else 0 end)+
				sum(case when f.feerulecode=58 and r.regionid =5 then f.amountpaid else 0 end) +
				sum(case when f.feerulecode = 58 then ((f.amountpaid) * .03) else 0 end ) as Total_Surcharge, 

				sum(case when f.feerulecode = 59 then f.amountpaid else 0 end) as BMRTL_CESS_stamp_duty, 

				sum(case when f.feerulecode = 1 then  f.amountpaid else 0 end )as registrationfee, 

				sum(case when f.feerulecode = 58 and r.regionid = 1 then f.amountpaid  else 0 end )+ 

				sum(case when f.feerulecode=58 and r.regionid =2 then  f.amountpaid  else 0 end)+ 

				sum(case when f.feerulecode=58 and r.regionid =3 then  f.amountpaid else 0 end) + 

				sum(case when f.feerulecode=58 and r.regionid =7 then  f.amountpaid  else 0 end)+ 

				sum(case when f.feerulecode=58 and r.regionid =4 then  f.amountpaid  else 0 end)+
				sum(case when f.feerulecode=58 and r.regionid =5 then f.amountpaid else 0 end) +
				sum(case when f.feerulecode = 58 then ((f.amountpaid) * .03) else 0 end )+
				sum(case when f.feerulecode = 59 then f.amountpaid else 0 end)+
				sum(case when f.feerulecode = 1 then  f.amountpaid else 0 end )+ 
				sum(case when f.feerulecode = 36 then f.amountpaid else 0 end) as Totalrevenue 

				from kaveri.documentmaster d  

				join kaveri.feesrequired f on d.documentid =f.documentid and d.applicationnumber =f.applicationnumber  

				join kaveri.sromaster s on d.srocode =s.srocode  
				--
				join kaveri.districtmaster dm on s.districtcode =dm.districtcode 
				join (select distinct applicationnumber,villagecode,roadcode from kaveri.propertymaster ) pm   on d.applicationnumber=pm.applicationnumber
				join kaveri.roadmaster r on pm.roadcode=r.roadcode and pm.villagecode=r.villagecode 

				inner join  
				--
				(select distinct applicationnumber,sum(amountpaid) as amountpaid from kaveri.feesrequired 

				--where srocode=_srocode 

				group by applicationnumber 

				having sum(amountpaid) >= _minval and sum(amountpaid) <= _maxval 

				) vw1 on f.applicationnumber = vw1.applicationnumber 

				where d.isregistrationcompleted = true 

				and dm.districtcode = _districtcode 

				and d.srocode =_srocode 

				and d.registrationdatetime::date >= _from_date

				and d.registrationdatetime::date <= _to_date

				group by dm.districtnamee,s.sronamee;
				
			end if;
	end if;

 end;

$$;


ALTER FUNCTION kaverimis.fn_mis_form_details_surcharge_fin_26_bck(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form_of_index_number_1(integer, character varying, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form_of_index_number_1(_srocode integer, _documentnumber character varying DEFAULT NULL::character varying, _from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _to_date timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE(uploaddocdeedpath text, nameofclaimingparty text, placeofresidence_claimant text, nameofexecutingparty text, placeofresidence_executant text, situationofproperty text, officeoforiginalregistration character varying, dateofexecution text, dateofregistrationorfiling text, serialnumbervolumeandpage text, copy_of_document text)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$

BEGIN	 
if (_documentnumber is null) then
return query 
select distinct
d.uploaddocdeedpath,
string_agg(distinct CASE WHEN pi.partytypeid = 1 THEN concat(e.descriptione, pi.firstname, ' ', pi.middlename, ' ', pi.lastname)
            ELSE NULL END,', ') AS nameofclaimingparty ,
string_agg(distinct CASE WHEN pi.partytypeid = 1 THEN (case when md.ispendingdocument = true then pi.address
				else concat_ws(' '::text, (((((
            CASE
                WHEN pi.housenumber IS NULL THEN ''::text
                ELSE pi.housenumber
            END || ', '::text) || pi.address::text) || ', '::text) || kaveri.fn_fetch_address_village(pi.talukcode)) || ' - '::text) || pi.pin)
        end) else null end,' ,')  AS placeofresidence_claimant ,
string_agg(distinct CASE WHEN pi.partytypeid = 2 THEN concat(e.descriptione, pi.firstname, ' ', pi.middlename, ' ', pi.lastname)
            ELSE NULL END,', ') as nameofexecutingparty,            
string_agg(distinct CASE WHEN pi.partytypeid = 1 THEN (case when md.ispendingdocument = true then pi.address
				else concat_ws(' '::text, (((((
            CASE
                WHEN pi.housenumber IS NULL THEN ''::text
                ELSE pi.housenumber
            END || ', '::text) || pi.address::text) || ', '::text) ||  kaveri.fn_fetch_address_village(pi.talukcode)) || ' - '::text) || pi.pin)
        end) else null end,' ,') AS placeofresidence_executant,
        
string_agg(distinct 'Schedule '::text || d1.scheduletype::text || ' '::text || d1.description::text || ' '::text || case when d1.landcode is not null then d1.landcode::text else '' end || ' '::text || case when d1.easttowest is not null then d1.easttowest::text else '' end,', ')::text AS situationofproperty,
  string_agg(distinct b.sronamee,', ')::character varying as officeoforiginalregistration,
    to_char(d.executiondatetime,'dd/mm/yyyy') AS dateofexecution,
    to_char(d.registrationdatetime,'dd/mm/yyyy') AS dateofregistrationorfiling,
(d.finalregistrationnumber ||'-'||p1.noofscanpages)::text AS serialnumbervolumeandpage /* un commented as per Naveen Sir's inputs */
,d.uploaddocdeedpath as copy_of_document        
from kaveri.documentmaster d 
JOIN kaveri.sromaster b ON d.srocode = b.srocode
JOIN kaveri.districtmaster c ON b.districtcode = c.districtcode
join kaveri.partyinfo pi on d.applicationnumber =pi.applicationnumber 
left join kaveri.salutationmaster e on pi.salutationid=e.salutationid
LEFT JOIN kaveri.minutebook_data md ON pi.applicationnumber = md.applicationnumber
JOIN kaveri.propertymaster p1 ON d.applicationnumber = p1.applicationnumber --AND b.srocode = e.regsrocode AND e.regsrocode > 0
JOIN kaveri.propertyschedules d1 ON d1.propertyid = p1.propertyid
where d.bookid = 1 and d.srocode =_srocode and d.registrationdatetime::date >=_from_date and d.registrationdatetime::date<=_to_date
and d.isregistrationcompleted =true
group by d.uploaddocdeedpath,d.executiondatetime,d.registrationdatetime,d.finalregistrationnumber,
pi.applicationnumber,p1.noofscanpages;

elseif (_from_date is null and _to_date is null) then
return query
select distinct
d.uploaddocdeedpath,
string_agg(distinct CASE WHEN pi.partytypeid = 1 THEN concat(e.descriptione, pi.firstname, ' ', pi.middlename, ' ', pi.lastname)
            ELSE NULL END,', ') AS nameofclaimingparty ,
string_agg(distinct CASE WHEN pi.partytypeid = 1 THEN (case when md.ispendingdocument = true then pi.address
				else concat_ws(' '::text, (((((
            CASE
                WHEN pi.housenumber IS NULL THEN ''::text
                ELSE pi.housenumber
            END || ', '::text) || pi.address::text) || ', '::text) || kaveri.fn_fetch_address_village(pi.talukcode)) || ' - '::text) || pi.pin)
        end) else null end,' ,')  AS placeofresidence_claimant ,
string_agg(distinct CASE WHEN pi.partytypeid = 2 THEN concat(e.descriptione, pi.firstname, ' ', pi.middlename, ' ', pi.lastname)
            ELSE NULL END,', ') as nameofexecutingparty,            
string_agg(distinct CASE WHEN pi.partytypeid = 1 THEN (case when md.ispendingdocument = true then pi.address
				else concat_ws(' '::text, (((((
            CASE
                WHEN pi.housenumber IS NULL THEN ''::text
                ELSE pi.housenumber
            END || ', '::text) || pi.address::text) || ', '::text) || kaveri.fn_fetch_address_village(pi.talukcode)) || ' - '::text) || pi.pin)
        end) else null end,' ,') AS placeofresidence_executant,
        
string_agg(distinct 'Schedule '::text || d1.scheduletype::text || ' '::text || d1.description::text || ' '::text || case when d1.landcode is not null then d1.landcode::text else '' end || ' '::text || case when d1.easttowest is not null then d1.easttowest::text else '' end,', ')::text AS situationofproperty,
  string_agg(distinct b.sronamee,', ')::character varying as officeoforiginalregistration,
    to_char(d.executiondatetime,'dd/mm/yyyy') AS dateofexecution,
    to_char(d.registrationdatetime,'dd/mm/yyyy') AS dateofregistrationorfiling,
(d.finalregistrationnumber ||'-'||p1.noofscanpages)::text AS serialnumbervolumeandpage /* un commented as per Naveen Sir's inputs */
,d.uploaddocdeedpath as copy_of_document        
from kaveri.documentmaster d 
JOIN kaveri.sromaster b ON d.srocode = b.srocode
JOIN kaveri.districtmaster c ON b.districtcode = c.districtcode
join kaveri.partyinfo pi on d.applicationnumber =pi.applicationnumber 
left join kaveri.salutationmaster e on pi.salutationid=e.salutationid
LEFT JOIN kaveri.minutebook_data md ON pi.applicationnumber = md.applicationnumber
JOIN kaveri.propertymaster p1 ON d.applicationnumber = p1.applicationnumber --AND b.srocode = e.regsrocode AND e.regsrocode > 0
JOIN kaveri.propertyschedules d1 ON d1.propertyid = p1.propertyid
where d.bookid = 1 and d.srocode =_srocode  and d.finalregistrationnumber = _documentnumber --and d.registrationdatetime::date >='2023-07-17' and d.registrationdatetime::date<='2023-07-17'
and d.isregistrationcompleted =true
group by d.uploaddocdeedpath,d.executiondatetime,d.registrationdatetime,d.finalregistrationnumber,
pi.applicationnumber,p1.noofscanpages;

else 
return query
select distinct
d.uploaddocdeedpath,
string_agg(distinct CASE WHEN pi.partytypeid = 1 THEN concat(e.descriptione, pi.firstname, ' ', pi.middlename, ' ', pi.lastname)
            ELSE NULL END,', ') AS nameofclaimingparty ,
string_agg(distinct CASE WHEN pi.partytypeid = 1 THEN (case when md.ispendingdocument = true then pi.address
				else concat_ws(' '::text, (((((
            CASE
                WHEN pi.housenumber IS NULL THEN ''::text
                ELSE pi.housenumber
            END || ', '::text) || pi.address::text) || ', '::text) || kaveri.fn_fetch_address_village(pi.talukcode)) || ' - '::text) || pi.pin)
        end) else null end,' ,')  AS placeofresidence_claimant ,
string_agg(distinct CASE WHEN pi.partytypeid = 2 THEN concat(e.descriptione, pi.firstname, ' ', pi.middlename, ' ', pi.lastname)
            ELSE NULL END,', ') as nameofexecutingparty,            
string_agg(distinct CASE WHEN pi.partytypeid = 1 THEN (case when md.ispendingdocument = true then pi.address
				else concat_ws(' '::text, (((((
            CASE
                WHEN pi.housenumber IS NULL THEN ''::text
                ELSE pi.housenumber
            END || ', '::text) || pi.address::text) || ', '::text) || kaveri.fn_fetch_address_village(pi.talukcode)) || ' - '::text) || pi.pin)
        end) else null end,' ,') AS placeofresidence_executant,
        
string_agg(distinct 'Schedule '::text || d1.scheduletype::text || ' '::text || d1.description::text || ' '::text || case when d1.landcode is not null then d1.landcode::text else '' end || ' '::text || case when d1.easttowest is not null then d1.easttowest::text else '' end,', ')::text AS situationofproperty,
  string_agg(distinct b.sronamee,', ')::character varying as officeoforiginalregistration,
    to_char(d.executiondatetime,'dd/mm/yyyy') AS dateofexecution,
    to_char(d.registrationdatetime,'dd/mm/yyyy') AS dateofregistrationorfiling,
(d.finalregistrationnumber ||'-'||p1.noofscanpages)::text AS serialnumbervolumeandpage /* un commented as per Naveen Sir's inputs */
,d.uploaddocdeedpath as copy_of_document        
from kaveri.documentmaster d 
JOIN kaveri.sromaster b ON d.srocode = b.srocode
JOIN kaveri.districtmaster c ON b.districtcode = c.districtcode
join kaveri.partyinfo pi on d.applicationnumber =pi.applicationnumber 
left join kaveri.salutationmaster e on pi.salutationid=e.salutationid
LEFT JOIN kaveri.minutebook_data md ON pi.applicationnumber = md.applicationnumber
JOIN kaveri.propertymaster p1 ON d.applicationnumber = p1.applicationnumber --AND b.srocode = e.regsrocode AND e.regsrocode > 0
JOIN kaveri.propertyschedules d1 ON d1.propertyid = p1.propertyid
where d.bookid = 1 and d.srocode =_srocode  and d.finalregistrationnumber = _documentnumber and d.registrationdatetime::date >=_from_date and d.registrationdatetime::date<=_to_date
and d.isregistrationcompleted =true
group by d.uploaddocdeedpath,d.executiondatetime,d.registrationdatetime,d.finalregistrationnumber,
pi.applicationnumber,p1.noofscanpages;
	 end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form_of_index_number_1(_srocode integer, _documentnumber character varying, _from_date timestamp without time zone, _to_date timestamp without time zone) OWNER TO csgadmin;

--
-- Name: fn_mis_form_of_index_number_1(integer, integer, character varying, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_form_of_index_number_1(_districtcode integer, _srocode integer, _documentnumber character varying DEFAULT NULL::character varying, _from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _to_date timestamp without time zone DEFAULT NULL::timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, uploaddocdeedpath text, nameofclaimingparty text, placeofresidence_claimant text, nameofexecutingparty text, placeofresidence_executant text, situationofproperty text, officeoforiginalregistration character varying, dateofexecution text, dateofregistrationorfiling text, serialnumbervolumeandpage text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$

DECLARE
PageOffset INTEGER := 0;

	begin
		
---		PageOffset := ((pagenumber - 1) * pagesize);
		PageOffset := (pagesize*pagenumber) - pagesize;
	
if (pagenumber<>-1 and pagesize<>-1) then 
return query
	with cte as (select
	distinct

                c.districtnamee,
	b.sronamee,
	d.uploaddocdeedpath,
	string_agg(distinct case
		when pi.partytypeid = 1 then concat(e.descriptione,
		pi.firstname,
		' ',
		pi.middlename,
		' ',
		pi.lastname)
		else null
	end,
	', ') as nameofclaimingparty ,
	string_agg(distinct case
		when pi.partytypeid = 1 then (case
			when md.ispendingdocument = true then pi.address
			else concat_ws(' '::text,
			(((((

                            case
				when pi.housenumber is null then ''::text
				else pi.housenumber
			end || ', '::text) || pi.address::text) || ', '::text) || kaveri.fn_fetch_address_village(pi.talukcode)) || ' - '::text) || pi.pin)
		end)
		else null
	end,
	' ,') as placeofresidence_claimant ,
	string_agg(distinct case
		when pi.partytypeid = 2 then concat(e.descriptione,
		pi.firstname,
		' ',
		pi.middlename,
		' ',
		pi.lastname)
		else null
	end,
	', ') as nameofexecutingparty,
	string_agg(distinct case
		when pi.partytypeid = 1 then (case
			when md.ispendingdocument = true then pi.address
			else concat_ws(' '::text,
			(((((

                            case
				when pi.housenumber is null then ''::text
				else pi.housenumber
			end || ', '::text) || pi.address::text) || ', '::text) || kaveri.fn_fetch_address_village(pi.talukcode)) || ' - '::text) || pi.pin)
		end)
		else null
	end,
	' ,') as placeofresidence_executant,
	string_agg(distinct 'Schedule '::text || d1.scheduletype::text || ' '::text || d1.description::text || ' '::text || case
		when d1.landcode is not null then d1.landcode::text
		else ''
	end || ' '::text || case
		when d1.easttowest is not null then d1.easttowest::text
		else ''
	end,
	', ')::text as situationofproperty,
	string_agg(distinct b.sronamee,
	', ')::character varying as officeoforiginalregistration,
	to_char(d.executiondatetime,
	'dd/mm/yyyy') as dateofexecution,
	to_char(d.registrationdatetime,
	'dd/mm/yyyy') as dateofregistrationorfiling,
	(d.finalregistrationnumber || '-' || p1.noofscanpages)::text as serialnumbervolumeandpage /* un commented as per Naveen Sir's inputs */
	,
	d.uploaddocdeedpath as copy_of_document
from
	kaveri.documentmaster d
join kaveri.sromaster b on
	d.srocode = b.srocode
join kaveri.districtmaster c on
	b.districtcode = c.districtcode
join kaveri.partyinfo pi on
	d.applicationnumber = pi.applicationnumber
left join kaveri.salutationmaster e on
	pi.salutationid = e.salutationid
left join kaveri.minutebook_data md on
	pi.applicationnumber = md.applicationnumber
join kaveri.propertymaster p1 on
	d.applicationnumber = p1.applicationnumber
	--AND b.srocode = e.regsrocode AND e.regsrocode > 0
join kaveri.propertyschedules d1 on
	d1.propertyid = p1.propertyid
where
	d.bookid = 1
	and (case
		when _districtcode <> 0 then c.districtcode = _districtcode
		else true
	end

                )
	and (case
		when _srocode <> 0 then d.srocode = _srocode
		else true
	end

                )
	--d.srocode =_srocode and
	-- c.districtcode=_districtcode and
	and (case
		when _from_date is not null
			and _to_date is not null then ( d.registrationdatetime between _from_date and _to_date)
			else true
		end

                )
	--(d.registrationdatetime between _from_date and _to_date)
	and (case
		when _documentnumber is not null then d.finalregistrationnumber = _documentnumber
		else true
	end

                )
	and d.isregistrationcompleted = true
group by
	c.districtnamee,
	b.sronamee,
	d.uploaddocdeedpath,
	d.executiondatetime,
	d.registrationdatetime,
	d.finalregistrationnumber,
	pi.applicationnumber,
	p1.noofscanpages
	
--	limit pagesize offset PageOffset)
		
--   select * from cte;

	)
	select * from cte
   right join (select count(*) as total_rows from cte) total_row on true 
   where total_row.total_rows<>0
  OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
			
elsif (pagenumber = -1 or pagesize = -1) then 

	return query
	with cte as (select
	distinct

                c.districtnamee,
	b.sronamee,
	d.uploaddocdeedpath,
	string_agg(distinct case
		when pi.partytypeid = 1 then concat(e.descriptione,
		pi.firstname,
		' ',
		pi.middlename,
		' ',
		pi.lastname)
		else null
	end,
	', ') as nameofclaimingparty ,
	string_agg(distinct case
		when pi.partytypeid = 1 then (case
			when md.ispendingdocument = true then pi.address
			else concat_ws(' '::text,
			(((((

                            case
				when pi.housenumber is null then ''::text
				else pi.housenumber
			end || ', '::text) || pi.address::text) || ', '::text) || kaveri.fn_fetch_address_village(pi.talukcode)) || ' - '::text) || pi.pin)
		end)
		else null
	end,
	' ,') as placeofresidence_claimant ,
	string_agg(distinct case
		when pi.partytypeid = 2 then concat(e.descriptione,
		pi.firstname,
		' ',
		pi.middlename,
		' ',
		pi.lastname)
		else null
	end,
	', ') as nameofexecutingparty,
	string_agg(distinct case
		when pi.partytypeid = 1 then (case
			when md.ispendingdocument = true then pi.address
			else concat_ws(' '::text,
			(((((

                            case
				when pi.housenumber is null then ''::text
				else pi.housenumber
			end || ', '::text) || pi.address::text) || ', '::text) || kaveri.fn_fetch_address_village(pi.talukcode)) || ' - '::text) || pi.pin)
		end)
		else null
	end,
	' ,') as placeofresidence_executant,
	string_agg(distinct 'Schedule '::text || d1.scheduletype::text || ' '::text || d1.description::text || ' '::text || case
		when d1.landcode is not null then d1.landcode::text
		else ''
	end || ' '::text || case
		when d1.easttowest is not null then d1.easttowest::text
		else ''
	end,
	', ')::text as situationofproperty,
	string_agg(distinct b.sronamee,
	', ')::character varying as officeoforiginalregistration,
	to_char(d.executiondatetime,
	'dd/mm/yyyy') as dateofexecution,
	to_char(d.registrationdatetime,
	'dd/mm/yyyy') as dateofregistrationorfiling,
	(d.finalregistrationnumber || '-' || p1.noofscanpages)::text as serialnumbervolumeandpage /* un commented as per Naveen Sir's inputs */
	,
	d.uploaddocdeedpath as copy_of_document
from
	kaveri.documentmaster d
join kaveri.sromaster b on
	d.srocode = b.srocode
join kaveri.districtmaster c on
	b.districtcode = c.districtcode
join kaveri.partyinfo pi on
	d.applicationnumber = pi.applicationnumber
left join kaveri.salutationmaster e on
	pi.salutationid = e.salutationid
left join kaveri.minutebook_data md on
	pi.applicationnumber = md.applicationnumber
join kaveri.propertymaster p1 on
	d.applicationnumber = p1.applicationnumber
	--AND b.srocode = e.regsrocode AND e.regsrocode > 0
join kaveri.propertyschedules d1 on
	d1.propertyid = p1.propertyid
where
	d.bookid = 1
	and (case
		when _districtcode <> 0 then c.districtcode = _districtcode
		else true
	end

                )
	and (case
		when _srocode <> 0 then d.srocode = _srocode
		else true
	end

                )
	--d.srocode =_srocode and
	-- c.districtcode=_districtcode and
	and (case
		when _from_date is not null
			and _to_date is not null then ( d.registrationdatetime between _from_date and _to_date)
			else true
		end

                )
	--(d.registrationdatetime between _from_date and _to_date)
	and (case
		when _documentnumber is not null then d.finalregistrationnumber = _documentnumber
		else true
	end

                )
	and d.isregistrationcompleted = true
group by
	c.districtnamee,
	b.sronamee,
	d.uploaddocdeedpath,
	d.executiondatetime,
	d.registrationdatetime,
	d.finalregistrationnumber,
	pi.applicationnumber,
	p1.noofscanpages
	
--	limit pagesize offset PageOffset)
		)
   select * from cte
	
   right join (select count(*) as total_rows from cte) total_row on true 
   where total_row.total_rows<>0;
end if;		

	
	END;
$$;


