CREATE FUNCTION kaverimis.fn_mis_form_of_index_number_1_bck_myversion(_srocode integer, _documentnumber character varying DEFAULT NULL::character varying, _from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _to_date timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE(uploaddocdeedpath text, nameofclaimingparty text, placeofresidence_claimant text, nameofexecutingparty text, placeofresidence_executant text, situationofproperty text, officeoforiginalregistration character varying, dateofexecution text, dateofregistrationorfiling text, serialnumbervolumeandpage text, copy_of_document text)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$

BEGIN	 
if (_documentnumber is null) then
return query 
select distinct
d.uploaddocdeedpath,
string_agg(distinct CASE WHEN pi.partytypeid = 1 THEN concat(e.descriptione, pi.firstname, ' ', pi.middlename, ' ', pi.lastname)
            ELSE NULL END,', ') AS nameofclaimingparty ,
string_agg(distinct CASE WHEN pi.partytypeid = 1 THEN (case when md.ispendingdocument = true then pi.address
				else concat_ws(' '::text, (((((
            CASE
                WHEN pi.housenumber IS NULL THEN ''::text
                ELSE pi.housenumber
            END || ', '::text) || pi.address::text) || ', '::text) || kaveri.fn_fetch_address_village(pi.talukcode)) || ' - '::text) || pi.pin)
        end) else null end,' ,')  AS placeofresidence_claimant ,
string_agg(distinct CASE WHEN pi.partytypeid = 2 THEN concat(e.descriptione, pi.firstname, ' ', pi.middlename, ' ', pi.lastname)
            ELSE NULL END,', ') as nameofexecutingparty,            
string_agg(distinct CASE WHEN pi.partytypeid = 1 THEN (case when md.ispendingdocument = true then pi.address
