JOIN kaveri.districtmaster c ON b.districtcode = c.districtcode
join kaveri.partyinfo pi on d.applicationnumber =pi.applicationnumber 
left join kaveri.salutationmaster e on pi.salutationid=e.salutationid
LEFT JOIN kaveri.minutebook_data md ON pi.applicationnumber = md.applicationnumber
JOIN kaveri.propertymaster p1 ON d.applicationnumber = p1.applicationnumber --AND b.srocode = e.regsrocode AND e.regsrocode > 0
JOIN kaveri.propertyschedules d1 ON d1.propertyid = p1.propertyid
where d.bookid = 1 and d.srocode =_srocode  and d.finalregistrationnumber = _documentnumber and d.registrationdatetime::date >=_from_date and d.registrationdatetime::date<=_to_date
and d.isregistrationcompleted =true
group by d.uploaddocdeedpath,d.executiondatetime,d.registrationdatetime,d.finalregistrationnumber,
pi.applicationnumber,p1.noofscanpages;
	 end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form_of_index_number_1_bck_myversion(_srocode integer, _documentnumber character varying, _from_date timestamp without time zone, _to_date timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_mis_form_of_index_number_1_bck_parthversion(integer, character varying, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form_of_index_number_1_bck_parthversion(_srocode integer, _documentnumber character varying DEFAULT NULL::character varying, _from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _to_date timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE(uploaddocdeedpath text, nameofclaimingparty text, placeofresidence_claimant character varying, nameofexecutingparty text, placeofresidence_executant character varying, situationofproperty text, officeoforiginalregistration character varying, dateofexecution text, dateofregistrationorfiling text, serialnumbervolumeandpage text, copy_of_document text)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$

BEGIN	 
if (_documentnumber is null) then
return query
   SELECT DISTINCT 
   -- string_agg(distinct c.districtnamee,', ')::character varying AS district,
   -- string_agg(distinct b.sronamee,', ')::character varying AS sroname,
    a.uploaddocdeedpath,
       vparty.nameofclaimingparty::text,
    vparty.placeofresidence_claimant::character varying,
    vparty.nameofexecutingparty::text,
    vparty.placeofresidence_executant::character varying,
    string_agg(distinct 'Schedule '::text || d.scheduletype::text || ' '::text || d.description::text || ' '::text || case when d.landcode is not null then d.landcode::text else '' end || ' '::text || case when d.easttowest is not null then d.easttowest::text else '' end,', ')::text AS situationofproperty,
   --string_agg(distinct 'Schedule '::text || d.scheduletype::text || ' '::text || d.description::text || ' '::text || case when d.landcode is not null then d.landcode::text else '' end || ' '::text  || case when prd.survey_no is not null then prd.survey_no else 0 end || ' '::text || case when d.easttowest is not null then d.easttowest::text else '' end,', ')::text AS situationofproperty,
    string_agg(distinct b.sronamee,', ')::character varying as officeoforiginalregistration,
    to_char(a.executiondatetime,'dd/mm/yyyy') AS dateofexecution,
    to_char(a.registrationdatetime,'dd/mm/yyyy') AS dateofregistrationorfiling,
	--(lpad(a.documentnumber::text, 5, '0') 
	(a.finalregistrationnumber ||'-'||e.noofscanpages)::text AS serialnumbervolumeandpage /* un commented as per Naveen Sir's inputs */
	,a.uploaddocdeedpath as copy_of_document
	--(a.finalregistrationnumber)::text AS serialnumbervolumeandpage 
   -- e.noofscanpages AS serialnumbervolumeandpage
   FROM kaveri.documentmaster a
     LEFT JOIN kaveri.sromaster b ON a.srocode = b.srocode
     LEFT JOIN kaveri.districtmaster c ON b.districtcode = c.districtcode
	 left outer join
	 (select pi.applicationnumber, string_agg(distinct CASE
            WHEN pi.partytypeid = 1 THEN COALESCE(pi.name, NULL::text)
            ELSE NULL::text
        END,', ') AS nameofclaimingparty,
        string_agg(distinct CASE
            WHEN pi.partytypeid = 1 THEN COALESCE(pi.address, NULL::character varying)
            ELSE NULL::character varying
        END,', ')::character varying AS placeofresidence_claimant,
        CASE
            WHEN pi1.partytypeid = 2 THEN COALESCE(pi1.name, NULL::text)
            ELSE NULL::text
        END AS nameofexecutingparty,
        CASE
            WHEN pi1.partytypeid = 2 THEN COALESCE(pi1.address, NULL::character varying)
            ELSE NULL::character varying
        END AS placeofresidence_executant
		 from kaveri.vw_fetch_party pi
		inner join kaveri.vw_fetch_party pi1 on pi.applicationnumber=pi1.applicationnumber
		group by pi.applicationnumber,pi1.partytypeid, pi1.name,pi1.address) as vparty
		on vparty.applicationnumber=a.applicationnumber and vparty.nameofexecutingparty is not null
     --LEFT JOIN kaveri.vw_fetch_party pi ON a.applicationnumber = pi.applicationnumber 
	 --LEFT JOIN kaveri.vw_fetch_party pi1 ON pi1.applicationnumber = pi.applicationnumber and pi1.name is not null
     LEFT JOIN kaveri.propertymaster e ON a.applicationnumber = e.applicationnumber AND b.srocode = e.regsrocode AND e.regsrocode > 0
	 LEFT JOIN kaveri.propertyschedules d ON d.propertyid = e.propertyid
     where a.bookid = 1 and a.srocode = _srocode and a.isregistrationcompleted=true 
	 and a.registrationdatetime >= _from_date
	 and a.registrationdatetime <= _to_date group by vparty.nameofclaimingparty,a.finalregistrationnumber,
     vparty.placeofresidence_claimant, vparty.nameofexecutingparty,vparty.placeofresidence_executant,a.uploaddocdeedpath,
	 a.executiondatetime, a.registrationdatetime, e.noofscanpages,a.uploaddocdeedpath;
	 elseif (_from_date is null and _to_date is null) then
	 return query
	    SELECT DISTINCT 
   -- string_agg(distinct c.districtnamee,', ')::character varying AS district,
   -- string_agg(distinct b.sronamee,', ')::character varying AS sroname,
    a.uploaddocdeedpath,
    vparty.nameofclaimingparty::text,
    vparty.placeofresidence_claimant::character varying,
    vparty.nameofexecutingparty::text,
    vparty.placeofresidence_executant::character varying,
    string_agg(distinct 'Schedule '::text || d.scheduletype::text || ' '::text || d.description::text || ' '::text || case when d.landcode is not null then d.landcode::text else '' end || ' '::text || case when d.easttowest is not null then d.easttowest::text else '' end,', ')::text AS situationofproperty,
   --string_agg(distinct 'Schedule '::text || d.scheduletype::text || ' '::text || d.description::text || ' '::text || case when d.landcode is not null then d.landcode::text else '' end || ' '::text  || case when prd.survey_no is not null then prd.survey_no else 0 end || ' '::text || case when d.easttowest is not null then d.easttowest::text else '' end,', ')::text AS situationofproperty,
    string_agg(distinct b.sronamee,', ')::character varying as officeoforiginalregistration,
    to_char(a.executiondatetime,'dd/mm/yyyy') AS dateofexecution,
    to_char(a.registrationdatetime,'dd/mm/yyyy') AS dateofregistrationorfiling,
	--(lpad(a.documentnumber::text, 5, '0') 
	--(a.finalregistrationnumber ||'-'||e.noofscanpages)::text AS serialnumbervolumeandpage 
	(a.finalregistrationnumber)::text AS serialnumbervolumeandpage
	,a.uploaddocdeedpath as copy_of_document
   -- e.noofscanpages AS serialnumbervolumeandpage
   FROM kaveri.documentmaster a
     LEFT JOIN kaveri.sromaster b ON a.srocode = b.srocode
     LEFT JOIN kaveri.districtmaster c ON b.districtcode = c.districtcode
	 left outer join
	 (select pi.applicationnumber, string_agg(distinct CASE
            WHEN pi.partytypeid = 1 THEN COALESCE(pi.name, NULL::text)
            ELSE NULL::text
        END,', ') AS nameofclaimingparty,
        string_agg(distinct CASE
            WHEN pi.partytypeid = 1 THEN COALESCE(pi.address, NULL::character varying)
            ELSE NULL::character varying
        END,', ')::character varying AS placeofresidence_claimant,
        CASE
            WHEN pi1.partytypeid = 2 THEN COALESCE(pi1.name, NULL::text)
            ELSE NULL::text
        END AS nameofexecutingparty,
        CASE
            WHEN pi1.partytypeid = 2 THEN COALESCE(pi1.address, NULL::character varying)
            ELSE NULL::character varying
        END AS placeofresidence_executant
		 from kaveri.vw_fetch_party pi
		inner join kaveri.vw_fetch_party pi1 on pi.applicationnumber=pi1.applicationnumber
		group by pi.applicationnumber,pi1.partytypeid, pi1.name,pi1.address) as vparty
		on vparty.applicationnumber=a.applicationnumber and vparty.nameofexecutingparty is not null
     --LEFT JOIN kaveri.vw_fetch_party pi ON a.applicationnumber = pi.applicationnumber 
	 --LEFT JOIN kaveri.vw_fetch_party pi1 ON pi1.applicationnumber = pi.applicationnumber and pi1.name is not null
     LEFT JOIN kaveri.propertymaster e ON a.applicationnumber = e.applicationnumber AND b.srocode = e.regsrocode AND e.regsrocode > 0
	 LEFT JOIN kaveri.propertyschedules d ON d.propertyid = e.propertyid
     where a.bookid = 1 and a.srocode = _srocode and a.finalregistrationnumber = _documentnumber and a.isregistrationcompleted=true 
	 --and a.registrationdatetime >= _from_date
	-- and a.registrationdatetime <= _to_date 
	 group by vparty.nameofclaimingparty,a.finalregistrationnumber,a.uploaddocdeedpath,
     vparty.placeofresidence_claimant, vparty.nameofexecutingparty,vparty.placeofresidence_executant,
	 a.executiondatetime, a.registrationdatetime, e.noofscanpages,a.uploaddocdeedpath;
	 else
	 return query
	 	    SELECT DISTINCT 
   -- string_agg(distinct c.districtnamee,', ')::character varying AS district,
   -- string_agg(distinct b.sronamee,', ')::character varying AS sroname,
    a.uploaddocdeedpath,
    vparty.nameofclaimingparty::text,
    vparty.placeofresidence_claimant::character varying,
    vparty.nameofexecutingparty::text,
    vparty.placeofresidence_executant::character varying,
    string_agg(distinct 'Schedule '::text || d.scheduletype::text || ' '::text || d.description::text || ' '::text || case when d.landcode is not null then d.landcode::text else '' end || ' '::text || case when d.easttowest is not null then d.easttowest::text else '' end,', ')::text AS situationofproperty,
   --string_agg(distinct 'Schedule '::text || d.scheduletype::text || ' '::text || d.description::text || ' '::text || case when d.landcode is not null then d.landcode::text else '' end || ' '::text  || case when prd.survey_no is not null then prd.survey_no else 0 end || ' '::text || case when d.easttowest is not null then d.easttowest::text else '' end,', ')::text AS situationofproperty,
    string_agg(distinct b.sronamee,', ')::character varying as officeoforiginalregistration,
     to_char(a.executiondatetime,'dd/mm/yyyy') AS dateofexecution,
    to_char(a.registrationdatetime,'dd/mm/yyyy') AS dateofregistrationorfiling,
	--(lpad(a.documentnumber::text, 5, '0') 
	(a.finalregistrationnumber)::text AS serialnumbervolumeandpage
	,a.uploaddocdeedpath as copy_of_document
   -- e.noofscanpages AS serialnumbervolumeandpage
   FROM kaveri.documentmaster a
     LEFT JOIN kaveri.sromaster b ON a.srocode = b.srocode
     LEFT JOIN kaveri.districtmaster c ON b.districtcode = c.districtcode
	 left outer join
	 (select pi.applicationnumber, string_agg(distinct CASE
            WHEN pi.partytypeid = 1 THEN COALESCE(pi.name, NULL::text)
            ELSE NULL::text
        END,', ') AS nameofclaimingparty,
        string_agg(distinct CASE
            WHEN pi.partytypeid = 1 THEN COALESCE(pi.address, NULL::character varying)
            ELSE NULL::character varying
        END,', ')::character varying AS placeofresidence_claimant,
        CASE
            WHEN pi1.partytypeid = 2 THEN COALESCE(pi1.name, NULL::text)
            ELSE NULL::text
        END AS nameofexecutingparty,
        CASE
            WHEN pi1.partytypeid = 2 THEN COALESCE(pi1.address, NULL::character varying)
            ELSE NULL::character varying
        END AS placeofresidence_executant
		 from kaveri.vw_fetch_party pi
		inner join kaveri.vw_fetch_party pi1 on pi.applicationnumber=pi1.applicationnumber
		group by pi.applicationnumber,pi1.partytypeid, pi1.name,pi1.address) as vparty
		on vparty.applicationnumber=a.applicationnumber and vparty.nameofexecutingparty is not null
     --LEFT JOIN kaveri.vw_fetch_party pi ON a.applicationnumber = pi.applicationnumber 
	 --LEFT JOIN kaveri.vw_fetch_party pi1 ON pi1.applicationnumber = pi.applicationnumber and pi1.name is not null
     LEFT JOIN kaveri.propertymaster e ON a.applicationnumber = e.applicationnumber AND b.srocode = e.regsrocode AND e.regsrocode > 0
	 LEFT JOIN kaveri.propertyschedules d ON d.propertyid = e.propertyid
     where a.bookid = 1 and a.srocode = _srocode and a.finalregistrationnumber = _documentnumber and a.isregistrationcompleted=true 
	 and a.registrationdatetime >= _from_date
	and a.registrationdatetime <= _to_date 
	 group by vparty.nameofclaimingparty,a.finalregistrationnumber,a.uploaddocdeedpath,
     vparty.placeofresidence_claimant, vparty.nameofexecutingparty,vparty.placeofresidence_executant,
	 a.executiondatetime, a.registrationdatetime, e.noofscanpages;
	 end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form_of_index_number_1_bck_parthversion(_srocode integer, _documentnumber character varying, _from_date timestamp without time zone, _to_date timestamp without time zone) OWNER TO csgadmin;

--
-- Name: fn_mis_form_of_index_number_1_optimization(integer, integer, character varying, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form_of_index_number_1_optimization(_districtcode integer, _srocode integer, _documentnumber character varying DEFAULT NULL::character varying, _from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _to_date timestamp without time zone DEFAULT NULL::timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, uploaddocdeedpath text, nameofclaimingparty text, placeofresidence_claimant text, nameofexecutingparty text, placeofresidence_executant text, situationofproperty text, officeoforiginalregistration character varying, dateofexecution text, dateofregistrationorfiling text, serialnumbervolumeandpage text, copy_of_document text)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$

DECLARE
PageOffset INTEGER := 0;

	begin
		
---		PageOffset := ((pagenumber - 1) * pagesize);
		PageOffset := (pagesize*pagenumber) - pagesize;
return query
	with cte as (select
	distinct

                c.districtnamee,
	b.sronamee,
	d.uploaddocdeedpath,
	string_agg(distinct case
		when pi.partytypeid = 1 then concat(e.descriptione,
		pi.firstname,
		' ',
		pi.middlename,
		' ',
		pi.lastname)
		else null
	end,
	', ') as nameofclaimingparty ,
	string_agg(distinct case
		when pi.partytypeid = 1 then (case
			when md.ispendingdocument = true then pi.address
			else concat_ws(' '::text,
			(((((

                            case
				when pi.housenumber is null then ''::text
				else pi.housenumber
			end || ', '::text) || pi.address::text) || ', '::text) || kaveri.fn_fetch_address_village(pi.talukcode)) || ' - '::text) || pi.pin)
		end)
		else null
	end,
	' ,') as placeofresidence_claimant ,
	string_agg(distinct case
		when pi.partytypeid = 2 then concat(e.descriptione,
		pi.firstname,
		' ',
		pi.middlename,
		' ',
		pi.lastname)
		else null
	end,
	', ') as nameofexecutingparty,
	string_agg(distinct case
		when pi.partytypeid = 1 then (case
			when md.ispendingdocument = true then pi.address
			else concat_ws(' '::text,
			(((((

                            case
				when pi.housenumber is null then ''::text
				else pi.housenumber
			end || ', '::text) || pi.address::text) || ', '::text) || kaveri.fn_fetch_address_village(pi.talukcode)) || ' - '::text) || pi.pin)
		end)
		else null
	end,
	' ,') as placeofresidence_executant,
	string_agg(distinct 'Schedule '::text || d1.scheduletype::text || ' '::text || d1.description::text || ' '::text || case
		when d1.landcode is not null then d1.landcode::text
		else ''
	end || ' '::text || case
		when d1.easttowest is not null then d1.easttowest::text
		else ''
	end,
	', ')::text as situationofproperty,
	string_agg(distinct b.sronamee,
	', ')::character varying as officeoforiginalregistration,
	to_char(d.executiondatetime,
	'dd/mm/yyyy') as dateofexecution,
	to_char(d.registrationdatetime,
	'dd/mm/yyyy') as dateofregistrationorfiling,
	(d.finalregistrationnumber || '-' || p1.noofscanpages)::text as serialnumbervolumeandpage /* un commented as per Naveen Sir's inputs */
	,
	d.uploaddocdeedpath as copy_of_document
from
	kaveri.documentmaster d
join kaveri.sromaster b on
	d.srocode = b.srocode
join kaveri.districtmaster c on
	b.districtcode = c.districtcode
join kaveri.partyinfo pi on
	d.applicationnumber = pi.applicationnumber
left join kaveri.salutationmaster e on
	pi.salutationid = e.salutationid
left join kaveri.minutebook_data md on
	pi.applicationnumber = md.applicationnumber
join kaveri.propertymaster p1 on
	d.applicationnumber = p1.applicationnumber
	--AND b.srocode = e.regsrocode AND e.regsrocode > 0
join kaveri.propertyschedules d1 on
	d1.propertyid = p1.propertyid
where
	d.bookid = 1
	and (case
		when _districtcode <> 0 then c.districtcode = _districtcode
		else true
	end

                )
	and (case
		when _srocode <> 0 then d.srocode = _srocode
		else true
	end

                )
	--d.srocode =_srocode and
	-- c.districtcode=_districtcode and
	and (case
		when _from_date is not null
			and _to_date is not null then d.registrationdatetime between _from_date and _to_date
			else true
		end

                )
	--(d.registrationdatetime between _from_date and _to_date)
	and (case
		when _documentnumber is not null then d.finalregistrationnumber = _documentnumber
		else true
	end

                )
	and d.isregistrationcompleted = true
group by
	c.districtnamee,
	b.sronamee,
	d.uploaddocdeedpath,
	d.executiondatetime,
	d.registrationdatetime,
	d.finalregistrationnumber,
	pi.applicationnumber,
	p1.noofscanpages
	
	limit pagesize offset PageOffset)
		
   select * from cte;
	END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form_of_index_number_1_optimization(_districtcode integer, _srocode integer, _documentnumber character varying, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form_of_index_number_2_form17_report(integer, integer, integer, bigint, character varying, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_form_of_index_number_2_form17_report(_districtcode integer, _talukcode integer, _hoblicode integer, _villagecode bigint, _documentnumber character varying DEFAULT NULL::character varying, _from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _to_date timestamp without time zone DEFAULT NULL::timestamp without time zone, page_number integer DEFAULT NULL::integer, per_page integer DEFAULT NULL::integer) RETURNS TABLE(districtcode integer, district character varying, talukcode integer, talukname character varying, hoblicode integer, hoblinamee character varying, villagecode bigint, nameofvillage character varying, propertyid bigint, finalregistrationnumber character varying, registrationdatetime timestamp without time zone, natureofdeedandconsideration text, surveyno_subdivisionno_houseno text, area text, assessment character varying, claimant text, executant text, officeoforiginalregistration character varying, srocode integer, executiondate text, regndate text, serialno_volume_and_page text, copy_of_document text, remarks character varying, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

declare 
	PageOffset INTEGER := 0;

	begin
		
		PageOffset := (per_page*page_number) - per_page;
        
	if (page_number<>-1 and per_page<>-1) then 
--        raise notice 'Function execution start for all districts_form17_statutory';
    
        return query
  with cte as (
       select
				distinct 
					c.districtcode,
					c.districtnamee as district,
					tal.talukcode,
					tal.taluknamee as talukname,
					hob.hoblicode,
					hob.hoblinamee,
					d.villagecode,
					d.villagenamee as nameofvillage,
					a.propertyid,
					i.finalregistrationnumber,
					i.registrationdatetime,
					string_agg(distinct (coalesce(r.articlenamee::text, null::text) || ' - '::text) || ' ' || to_char(coalesce(a.sroconsideration, 0),
					'₹9,99,99,999D99'), ', ')::text as natureofdeedandconsideration,
					string_agg(distinct replace(f.currentnumber, '*', '/')::text, ', ')::text as surveyno_subdivisionno_houseno,
					case
						when g.unitid = 1 then div(ceil(a.totalarea * 40),
						40)::text || ' ' || 'Acre' || ' '
										   || mod(ceil(a.totalarea * 40),
						40)::text || ' ' || 'Gunta'
						when g.unitid = 2 then div(a.totalarea,
						40)::text || ' ' || 'Acre' || ' '
										   || mod(a.totalarea,
						40)::text || ' ' || 'Gunta'
						else
				 	string_agg(distinct (round( a.totalarea, 2 ) || ' '::text) || g.descriptionenglish::text, ', ')::text
					end as area,
					null::character varying as assessment,
					string_agg( distinct case
                            when pi.partytypeid = 1 then
                      coalesce(coalesce(pi.firstname,
                            ' ')|| ' ' || coalesce(pi.middlename,
                            ' ')|| ' ' || coalesce(pi.lastname,
                            ' '),
                            null::text)
                            else null
                        end ,
                        ', ')::text as claimant,
                        
                        string_agg( distinct case
                            when pi.partytypeid = 2 then
                      coalesce(coalesce(pi.firstname,
                            ' ')|| ' ' || coalesce(pi.middlename,
                            ' ')|| ' ' || coalesce(pi.lastname,
                            ' '),
                            null::text)
                            else null
                        end ,
                        ', ')::text as executant,
						b.sronamee as officeoforiginalregistration,
						b.srocode,
						to_char(i.executiondatetime,
						'DD-MM-YYYY') as executiondate,
						to_char(i.registrationdatetime,
						'DD-MM-YYYY') as regndate,
						TO_CHAR(i.documentnumber,
						'fm00000') as serialno_volume_and_page,
						i.uploaddocdeedpath as copy_of_document
					  ,
						(coalesce(ld.liabilitynote,
						' ')|| ' ' || coalesce(referencetext,
						' ') ||
					  ' ' /*||coalesce(cor.footnotefordesc,' ')*/
						)::character varying as remarks

from
	kaveri.documentmaster i
join kaveri.propertymaster a on
	i.applicationnumber = a.applicationnumber
	and i.isregistrationcompleted = true
left join kaveri.liabilityonpropertydetails lpm on a.propertyid = lpm.propertyid   
left join kaveri.liabilitydetails ld on lpm.liabilityid = ld.liabilityid
left join kaveri.referencemaster ref on i.documentid = ref.documentid
join kaveri.propertynumberdetails f on a.propertyid = f.propertyid
join kaveri.partyinfo pi on i.applicationnumber = pi.applicationnumber
join kaveri.registrationarticles r on  i.regarticlecode = r.regarticlecode
left join kaveri.measunitmaster g on a.unitid = g.unitid

join kaveri.villagemaster d on
     a.villagecode = d.villagecode
     --and d.srocode = i.srocode
join kaveri.hoblimaster hob on
     d.hoblicode=hob.hoblicode
join kaveri.talukmaster tal on d.talukcode = tal.talukcode
join kaveri.sromaster b on
	d.srocode = b.srocode
     --tal.districtcode = c.districtcode
     --and
                            
join kaveri.districtmaster c on
    tal.districtcode = c.districtcode

where

	 (CASE   
                                WHEN _documentnumber is not NULL THEN i.finalregistrationnumber=_documentnumber
                                WHEN _from_date is not NULL and _to_date is not NULL THEN
                                i.registrationdatetime between _from_date and _to_date
                                ELSE 
                                    TRUE
	END)
	and  i.finalregistrationnumber is not null
	and (
                                            CASE
                                                WHEN _districtcode <> 0 THEN  c.districtcode = _districtcode
                                                ELSE TRUE
                                            END
                                        ) 
                                        and (
                                            CASE
                                                WHEN _talukcode <> 0 THEN  tal.talukcode = _talukcode
                                                ELSE TRUE
                                            end
                                            ) 
                                        and (
                                            CASE
                                                WHEN _hoblicode <> 0 THEN  hob.hoblicode = _hoblicode
                                                ELSE TRUE
                                            END
                                        ) 
                                        and (
                                            CASE
                                                WHEN _villagecode <> 0 THEN  a.villagecode = _villagecode
                                                ELSE TRUE
                                            END
                                        ) 
	
group by
	i.uploaddocdeedpath,
	g.unitid,
	a.totalarea,
	c.districtnamee,
	b.sronamee,
	d.villagenamee,
	tal.taluknamee,
	officeoforiginalregistration,
	executiondate,
	regndate,
	remarks,
	lpm.documentid,
	ld.liabilitynote,
	i.finalregistrationnumber,
	tal.talukcode,
	hob.hoblicode,
	a.villagecode,
	a.noofscanpages,
	i.applicationnumber,
	i.documentnumber, c.districtcode,b.srocode,tal.talukcode,hob.hoblicode,hob.hoblinamee,d.villagecode,a.propertyid,i.registrationdatetime
	
	
	
	
--	limit per_page offset PageOffset;
	              
--        raise notice 'Function execution end for all districts_form17_statutory'
       ),cte_count as (select count(*) as total_rows from cte)

            select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0 					
			limit per_page offset PageOffset;
			
elsif (page_number = -1 or per_page = -1) then 
       
return query
		with cte as (
  				select
				distinct 
					c.districtcode,
					c.districtnamee as district,
					tal.talukcode,
					tal.taluknamee as talukname,
					hob.hoblicode,
					hob.hoblinamee,
					d.villagecode,
					d.villagenamee as nameofvillage,
					a.propertyid,
					i.finalregistrationnumber,
					i.registrationdatetime,
					string_agg(distinct (coalesce(r.articlenamee::text, null::text) || ' - '::text) || ' ' || to_char(coalesce(a.sroconsideration, 0),
					'₹9,99,99,999D99'), ', ')::text as natureofdeedandconsideration,
					string_agg(distinct replace(f.currentnumber, '*', '/')::text, ', ')::text as surveyno_subdivisionno_houseno,
					case
						when g.unitid = 1 then div(ceil(a.totalarea * 40),
						40)::text || ' ' || 'Acre' || ' '
										   || mod(ceil(a.totalarea * 40),
						40)::text || ' ' || 'Gunta'
						when g.unitid = 2 then div(a.totalarea,
						40)::text || ' ' || 'Acre' || ' '
										   || mod(a.totalarea,
						40)::text || ' ' || 'Gunta'
						else
				 	string_agg(distinct (round( a.totalarea, 2 ) || ' '::text) || g.descriptionenglish::text, ', ')::text
					end as area,
					null::character varying as assessment,
					string_agg( distinct case
                            when pi.partytypeid = 1 then
                      coalesce(coalesce(pi.firstname,
                            ' ')|| ' ' || coalesce(pi.middlename,
                            ' ')|| ' ' || coalesce(pi.lastname,
                            ' '),
                            null::text)
                            else null
                        end ,
                        ', ')::text as claimant,
                        
                        string_agg( distinct case
                            when pi.partytypeid = 2 then
                      coalesce(coalesce(pi.firstname,
                            ' ')|| ' ' || coalesce(pi.middlename,
                            ' ')|| ' ' || coalesce(pi.lastname,
                            ' '),
                            null::text)
                            else null
                        end ,
                        ', ')::text as executant,
						b.sronamee as officeoforiginalregistration,
						b.srocode,
						to_char(i.executiondatetime,
						'DD-MM-YYYY') as executiondate,
						to_char(i.registrationdatetime,
						'DD-MM-YYYY') as regndate,
						TO_CHAR(i.documentnumber,
						'fm00000') as serialno_volume_and_page,
						i.uploaddocdeedpath as copy_of_document
					  ,
						(coalesce(ld.liabilitynote,
						' ')|| ' ' || coalesce(referencetext,
						' ') ||
					  ' ' /*||coalesce(cor.footnotefordesc,' ')*/
						)::character varying as remarks

from
	kaveri.documentmaster i
join kaveri.propertymaster a on
	i.applicationnumber = a.applicationnumber
	and i.isregistrationcompleted = true
left join kaveri.liabilityonpropertydetails lpm on a.propertyid = lpm.propertyid   
left join kaveri.liabilitydetails ld on lpm.liabilityid = ld.liabilityid
left join kaveri.referencemaster ref on i.documentid = ref.documentid
join kaveri.propertynumberdetails f on a.propertyid = f.propertyid
join kaveri.partyinfo pi on i.applicationnumber = pi.applicationnumber
join kaveri.registrationarticles r on  i.regarticlecode = r.regarticlecode
left join kaveri.measunitmaster g on a.unitid = g.unitid

join kaveri.villagemaster d on
     a.villagecode = d.villagecode
     --and d.srocode = i.srocode
join kaveri.hoblimaster hob on
     d.hoblicode=hob.hoblicode
join kaveri.talukmaster tal on d.talukcode = tal.talukcode
join kaveri.sromaster b on
	d.srocode = b.srocode
     --tal.districtcode = c.districtcode
     --and
                            
join kaveri.districtmaster c on
    tal.districtcode = c.districtcode

where

	 (CASE   
                                WHEN _documentnumber is not NULL THEN i.finalregistrationnumber=_documentnumber
                                WHEN _from_date is not NULL and _to_date is not NULL THEN
                                i.registrationdatetime between _from_date and _to_date
                                ELSE 
                                    TRUE
	END)
	and  i.finalregistrationnumber is not null
	and (
                                            CASE
                                                WHEN _districtcode <> 0 THEN  c.districtcode = _districtcode
                                                ELSE TRUE
                                            END
                                        ) 
                                        and (
                                            CASE
                                                WHEN _talukcode <> 0 THEN  tal.talukcode = _talukcode
                                                ELSE TRUE
                                            end
                                            ) 
                                        and (
                                            CASE
                                                WHEN _hoblicode <> 0 THEN  hob.hoblicode = _hoblicode
                                                ELSE TRUE
                                            END
                                        ) 
                                        and (
                                            CASE
                                                WHEN _villagecode <> 0 THEN  a.villagecode = _villagecode
                                                ELSE TRUE
                                            END
                                        ) 
	
group by
	i.uploaddocdeedpath,
	g.unitid,
	a.totalarea,
	c.districtnamee,
	b.sronamee,
	d.villagenamee,
	tal.taluknamee,
	officeoforiginalregistration,
	executiondate,
	regndate,
	remarks,
	lpm.documentid,
	ld.liabilitynote,
	i.finalregistrationnumber,
	tal.talukcode,
	hob.hoblicode,
	a.villagecode,
	a.noofscanpages,
	i.applicationnumber,
	i.documentnumber, c.districtcode,b.srocode,tal.talukcode,hob.hoblicode,hob.hoblinamee,d.villagecode,a.propertyid,i.registrationdatetime
	
	
	
	
--	limit per_page offset PageOffset;
	              
       
       ),cte_count as (select count(*) as total_rows from cte)

            select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0;
--   raise notice 'Function execution end for all districts_form17_statutory' ;
end if;		

	END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form_of_index_number_2_form17_report(_districtcode integer, _talukcode integer, _hoblicode integer, _villagecode bigint, _documentnumber character varying, _from_date timestamp without time zone, _to_date timestamp without time zone, page_number integer, per_page integer) OWNER TO postgres;

--
-- Name: fn_mis_form_of_index_number_2_part1(integer, integer, integer, bigint, character varying, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_form_of_index_number_2_part1(_districtcode integer, _talukcode integer, _hoblicode integer, _villagecode bigint, _documentnumber character varying DEFAULT NULL::character varying, _from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _to_date timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE(district character varying, sroname character varying, nameofvillage character varying, natureofdeedandconsideration text, surveyno_subdivisionno_houseno text, area text, assessment character varying, claimant text, executant text, officeoforiginalregistration character varying, executiondate text, regndate text, serialno_volume_and_page text, copy_of_document text, remarks character varying)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$


BEGIN	 
	
if(0=_districtcode) then 
raise notice 'All district';
return query
 
SELECT DISTINCT 
c.districtnamee AS district,
tal.taluknamee AS talukname,
d.villagenamee as nameofvillage,
string_agg(distinct (COALESCE(r.articlenamee::text,NULL::text) || ' - '::text) ||' '||
to_char(COALESCE(a.sroconsideration,0), '₹9,99,99,999D99'),', ')::text AS natureofdeedandconsideration,
string_agg(distinct replace(f.currentnumber,'*','/')::text,', ')::text AS surveyno_subdivisionno_houseno,
case 
when g.unitid = 1 then div(ceil(a.totalarea*40),40)::text ||' '||'Acre' ||' '
						   ||mod(ceil(a.totalarea*40),40)::text ||' '||'Gunta'
when g.unitid = 2 then div(a.totalarea,40)::text ||' '||'Acre' ||' '
						   ||mod(a.totalarea,40)::text ||' '||'Gunta'
else
 string_agg(distinct (round( a.totalarea, 2 ) || ' '::text) || g.descriptionenglish::text,', ')::text  
end AS area,
null::character varying as assessment,
string_agg(  distinct COALESCE(coalesce(pi.firstname,' ')||' '||coalesce(pi.middlename,' ')||' '||coalesce(pi.lastname,' '), NULL::text)
            ,', ')::text AS claimant,
    string_agg(distinct COALESCE(coalesce(pi1.firstname,' ')||' '||coalesce(pi1.middlename,' ')
            ||' '||coalesce(pi1.lastname,' '), NULL::text),', ')::text AS executant,
    b.sronamee AS officeoforiginalregistration,
    to_char(i.executiondatetime,'DD-MM-YYYY')  AS executiondate,
    to_char(i.registrationdatetime,'DD-MM-YYYY') AS regndate,
   TO_CHAR(i.documentnumber, 'fm00000') AS serialno_volume_and_page,
   i.uploaddocdeedpath as copy_of_document
  ,(coalesce(ld.liabilitynote,' ')||' '|| coalesce(referencetext,' ') ||
  ' '/*||coalesce(cor.footnotefordesc,' ')*/)::character varying AS remarks
   FROM 
     kaveri.documentmaster i 
      JOIN kaveri.propertymaster a ON a.applicationnumber = i.applicationnumber AND i.isregistrationcompleted = true
     JOIN kaveri.sromaster b ON a.srocode = b.srocode
     JOIN kaveri.districtmaster c ON b.districtcode = c.districtcode
     JOIN kaveri.villagemaster d ON a.villagecode = d.villagecode and d.srocode=i.srocode 
     --JOIN kaveri.stamprules e ON a.stampruleid = e.stampruleid
	 JOIN kaveri.registrationarticles r ON i.regarticlecode = r.regarticlecode
     JOIN kaveri.propertynumberdetails f ON a.propertyid = f.propertyid
     JOIN kaveri.measunitmaster g ON a.unitid = g.unitid
    JOIN kaveri.partyinfo  pi ON i.applicationnumber = pi.applicationnumber and pi.partytypeid = 1
	JOIN kaveri.partyinfo pi1 ON  i.applicationnumber=pi1.applicationnumber and pi1.partytypeid = 2
     --JOIN kaveri.mas_officemaster h ON a.srocode = h.kavericode 
	JOIN kaveri.talukmaster tal on tal.districtcode = c.districtcode and d.talukcode=tal.talukcode 
	join kaveri.hoblimaster hob on hob.talukcode = tal.talukcode
	left join kaveri.liabilityonpropertydetails   lpm on lpm.propertyid =a.propertyid 
	left join kaveri.liabilitydetails ld on ld.liabilityid = lpm.liabilityid
	left join kaveri.referencemaster ref on ref.documentid = i.documentid
	--left join kaveri.vw_fetch_section68_property_return_string cor on cor.propertyid = a.propertyid
     where
	 a.totalarea is not null and i.isregistrationcompleted is true and 
	 i.finalregistrationnumber is not null 
	  and  (i.registrationdatetime::date >= _from_date
     and i.registrationdatetime::date <= _to_date) /*or  (ld.issuedate ::date >= _from_date
     and ld.issuedate::date <= _to_date)*/
        group by i.uploaddocdeedpath,g.unitid,a.totalarea,c.districtnamee, b.sronamee, d.villagenamee,tal.taluknamee, officeoforiginalregistration, executiondate, regndate,remarks,lpm.documentid,
	ld.liabilitynote,i.finalregistrationnumber,tal.talukcode,hob.hoblicode,
	a.villagecode, a.noofscanpages,i.applicationnumber,i.documentnumber;
	 
	 	 
