ALTER FUNCTION kaverimis.fn_mis_form_of_index_number_2_part1(_districtcode integer, _talukcode integer, _hoblicode integer, _villagecode bigint, _documentnumber character varying, _from_date timestamp without time zone, _to_date timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_mis_form_of_index_number_2_part1(integer, integer, integer, bigint, character varying, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_form_of_index_number_2_part1(_districtcode integer, _talukcode integer, _hoblicode integer, _villagecode bigint, _documentnumber character varying DEFAULT NULL::character varying, _from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _to_date timestamp without time zone DEFAULT NULL::timestamp without time zone, page_number integer DEFAULT NULL::integer, per_page integer DEFAULT NULL::integer) RETURNS TABLE(districtcode integer, district character varying, talukcode integer, talukname character varying, hoblicode integer, hoblinamee character varying, villagecode bigint, nameofvillage character varying, propertyid bigint, finalregistrationnumber character varying, registrationdatetime timestamp without time zone, natureofdeedandconsideration text, surveyno_subdivisionno_houseno text, area text, assessment character varying, claimant text, executant text, officeoforiginalregistration character varying, srocode integer, executiondate text, regndate text, serialno_volume_and_page text, copy_of_document text, remarks character varying, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

declare 
	PageOffset INTEGER := 0;

	begin
		
		PageOffset := (per_page*page_number) - per_page;
        
	if (page_number<>-1 and per_page<>-1) then 
--        raise notice 'Function execution start for all districts_form17_statutory';
    
        return query
  with cte as (
       select
				distinct 
					c.districtcode,
					c.districtnamee as district,
					tal.talukcode,
					tal.taluknamee as talukname,
					hob.hoblicode,
					hob.hoblinamee,
					d.villagecode,
					d.villagenamee as nameofvillage,
					a.propertyid,
					i.finalregistrationnumber,
					i.registrationdatetime,
					string_agg(distinct (coalesce(r.articlenamee::text, null::text) || ' - '::text) || ' ' || to_char(coalesce(a.sroconsideration, 0),
					'₹9,99,99,999D99'), ', ')::text as natureofdeedandconsideration,
					string_agg(distinct replace(f.currentnumber, '*', '/')::text, ', ')::text as surveyno_subdivisionno_houseno,
					case
						when g.unitid = 1 then div(ceil(a.totalarea * 40),
						40)::text || ' ' || 'Acre' || ' '
										   || mod(ceil(a.totalarea * 40),
						40)::text || ' ' || 'Gunta'
						when g.unitid = 2 then div(a.totalarea,
						40)::text || ' ' || 'Acre' || ' '
										   || mod(a.totalarea,
						40)::text || ' ' || 'Gunta'
						else
				 	string_agg(distinct (round( a.totalarea, 2 ) || ' '::text) || g.descriptionenglish::text, ', ')::text
					end as area,
					null::character varying as assessment,
					string_agg( distinct case
                            when pi.partytypeid = 1 then
                      coalesce(coalesce(pi.firstname,
                            ' ')|| ' ' || coalesce(pi.middlename,
                            ' ')|| ' ' || coalesce(pi.lastname,
                            ' '),
                            null::text)
                            else null
                        end ,
                        ', ')::text as claimant,
                        
                        string_agg( distinct case
                            when pi.partytypeid = 2 then
                      coalesce(coalesce(pi.firstname,
                            ' ')|| ' ' || coalesce(pi.middlename,
                            ' ')|| ' ' || coalesce(pi.lastname,
                            ' '),
                            null::text)
                            else null
                        end ,
                        ', ')::text as executant,
						b.sronamee as officeoforiginalregistration,
						b.srocode,
						to_char(i.executiondatetime,
						'DD-MM-YYYY') as executiondate,
						to_char(i.registrationdatetime,
						'DD-MM-YYYY') as regndate,
						TO_CHAR(i.documentnumber,
						'fm00000') as serialno_volume_and_page,
						i.uploaddocdeedpath as copy_of_document
					  ,
						(coalesce(ld.liabilitynote,
						' ')|| ' ' || coalesce(referencetext,
						' ') ||
					  ' ' /*||coalesce(cor.footnotefordesc,' ')*/
						)::character varying as remarks

from
	kaveri.documentmaster i
join kaveri.propertymaster a on
	i.applicationnumber = a.applicationnumber
	and i.isregistrationcompleted = true
left join kaveri.liabilityonpropertydetails lpm on a.propertyid = lpm.propertyid   
left join kaveri.liabilitydetails ld on lpm.liabilityid = ld.liabilityid
left join kaveri.referencemaster ref on i.documentid = ref.documentid
join kaveri.propertynumberdetails f on a.propertyid = f.propertyid
join kaveri.partyinfo pi on i.applicationnumber = pi.applicationnumber
join kaveri.registrationarticles r on  i.regarticlecode = r.regarticlecode
left join kaveri.measunitmaster g on a.unitid = g.unitid

join kaveri.villagemaster d on
     a.villagecode = d.villagecode
     --and d.srocode = i.srocode
join kaveri.hoblimaster hob on
     d.hoblicode=hob.hoblicode
join kaveri.talukmaster tal on d.talukcode = tal.talukcode
join kaveri.sromaster b on
	d.srocode = b.srocode
     --tal.districtcode = c.districtcode
     --and
                            
join kaveri.districtmaster c on
    tal.districtcode = c.districtcode

where

	 (CASE   
                                WHEN _documentnumber is not NULL THEN i.finalregistrationnumber=_documentnumber
                                WHEN _from_date is not NULL and _to_date is not NULL THEN
                                i.registrationdatetime between _from_date and _to_date
                                ELSE 
                                    TRUE
	END)
	and  i.finalregistrationnumber is not null
	and (
                                            CASE
                                                WHEN _districtcode <> 0 THEN  c.districtcode = _districtcode
                                                ELSE TRUE
                                            END
                                        ) 
                                        and (
                                            CASE
                                                WHEN _talukcode <> 0 THEN  tal.talukcode = _talukcode
                                                ELSE TRUE
                                            end
                                            ) 
                                        and (
                                            CASE
                                                WHEN _hoblicode <> 0 THEN  hob.hoblicode = _hoblicode
                                                ELSE TRUE
                                            END
                                        ) 
                                        and (
                                            CASE
                                                WHEN _villagecode <> 0 THEN  a.villagecode = _villagecode
                                                ELSE TRUE
                                            END
                                        ) 
	
group by
	i.uploaddocdeedpath,
	g.unitid,
	a.totalarea,
	c.districtnamee,
	b.sronamee,
	d.villagenamee,
	tal.taluknamee,
	officeoforiginalregistration,
	executiondate,
	regndate,
	remarks,
	lpm.documentid,
	ld.liabilitynote,
	i.finalregistrationnumber,
	tal.talukcode,
	hob.hoblicode,
	a.villagecode,
	a.noofscanpages,
	i.applicationnumber,
	i.documentnumber, c.districtcode,b.srocode,tal.talukcode,hob.hoblicode,hob.hoblinamee,d.villagecode,a.propertyid,i.registrationdatetime
	
	
	
	
--	limit per_page offset PageOffset;
	              
--        raise notice 'Function execution end for all districts_form17_statutory'
       ),cte_count as (select count(*) as total_rows from cte)

            select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0 					
			limit per_page offset PageOffset;
			
elsif (page_number = -1 or per_page = -1) then 
       
return query
		with cte as (
  				select
				distinct 
					c.districtcode,
					c.districtnamee as district,
					tal.talukcode,
					tal.taluknamee as talukname,
					hob.hoblicode,
					hob.hoblinamee,
					d.villagecode,
					d.villagenamee as nameofvillage,
					a.propertyid,
					i.finalregistrationnumber,
					i.registrationdatetime,
					string_agg(distinct (coalesce(r.articlenamee::text, null::text) || ' - '::text) || ' ' || to_char(coalesce(a.sroconsideration, 0),
					'₹9,99,99,999D99'), ', ')::text as natureofdeedandconsideration,
					string_agg(distinct replace(f.currentnumber, '*', '/')::text, ', ')::text as surveyno_subdivisionno_houseno,
					case
						when g.unitid = 1 then div(ceil(a.totalarea * 40),
						40)::text || ' ' || 'Acre' || ' '
										   || mod(ceil(a.totalarea * 40),
						40)::text || ' ' || 'Gunta'
						when g.unitid = 2 then div(a.totalarea,
						40)::text || ' ' || 'Acre' || ' '
										   || mod(a.totalarea,
						40)::text || ' ' || 'Gunta'
						else
				 	string_agg(distinct (round( a.totalarea, 2 ) || ' '::text) || g.descriptionenglish::text, ', ')::text
					end as area,
					null::character varying as assessment,
					string_agg( distinct case
                            when pi.partytypeid = 1 then
                      coalesce(coalesce(pi.firstname,
                            ' ')|| ' ' || coalesce(pi.middlename,
                            ' ')|| ' ' || coalesce(pi.lastname,
                            ' '),
                            null::text)
                            else null
                        end ,
                        ', ')::text as claimant,
                        
                        string_agg( distinct case
                            when pi.partytypeid = 2 then
                      coalesce(coalesce(pi.firstname,
                            ' ')|| ' ' || coalesce(pi.middlename,
                            ' ')|| ' ' || coalesce(pi.lastname,
                            ' '),
                            null::text)
                            else null
                        end ,
                        ', ')::text as executant,
						b.sronamee as officeoforiginalregistration,
						b.srocode,
						to_char(i.executiondatetime,
						'DD-MM-YYYY') as executiondate,
						to_char(i.registrationdatetime,
						'DD-MM-YYYY') as regndate,
						TO_CHAR(i.documentnumber,
						'fm00000') as serialno_volume_and_page,
						i.uploaddocdeedpath as copy_of_document
					  ,
						(coalesce(ld.liabilitynote,
						' ')|| ' ' || coalesce(referencetext,
						' ') ||
					  ' ' /*||coalesce(cor.footnotefordesc,' ')*/
						)::character varying as remarks

from
	kaveri.documentmaster i
join kaveri.propertymaster a on
	i.applicationnumber = a.applicationnumber
	and i.isregistrationcompleted = true
left join kaveri.liabilityonpropertydetails lpm on a.propertyid = lpm.propertyid   
left join kaveri.liabilitydetails ld on lpm.liabilityid = ld.liabilityid
left join kaveri.referencemaster ref on i.documentid = ref.documentid
join kaveri.propertynumberdetails f on a.propertyid = f.propertyid
join kaveri.partyinfo pi on i.applicationnumber = pi.applicationnumber
join kaveri.registrationarticles r on  i.regarticlecode = r.regarticlecode
