						40)::text || ' ' || 'Acre' || ' '
										   || mod(ceil(a.totalarea * 40),
						40)::text || ' ' || 'Gunta'
						when g.unitid = 2 then div(a.totalarea,
						40)::text || ' ' || 'Acre' || ' '
										   || mod(a.totalarea,
						40)::text || ' ' || 'Gunta'
						else
				 	string_agg(distinct (round( a.totalarea, 2 ) || ' '::text) || g.descriptionenglish::text, ', ')::text
					end as area,
					null::character varying as assessment,
					string_agg( distinct case
                            when pi.partytypeid = 1 then
                      coalesce(coalesce(pi.firstname,
                            ' ')|| ' ' || coalesce(pi.middlename,
                            ' ')|| ' ' || coalesce(pi.lastname,
                            ' '),
                            null::text)
                            else null
                        end ,
                        ', ')::text as claimant,
                        
                        string_agg( distinct case
                            when pi.partytypeid = 2 then
                      coalesce(coalesce(pi.firstname,
                            ' ')|| ' ' || coalesce(pi.middlename,
                            ' ')|| ' ' || coalesce(pi.lastname,
                            ' '),
                            null::text)
                            else null
                        end ,
                        ', ')::text as executant,
						b.sronamee as officeoforiginalregistration,
						b.srocode,
						to_char(i.executiondatetime,
						'DD-MM-YYYY') as executiondate,
						to_char(i.registrationdatetime,
						'DD-MM-YYYY') as regndate,
						TO_CHAR(i.documentnumber,
						'fm00000') as serialno_volume_and_page,
						i.uploaddocdeedpath as copy_of_document
					  ,
						(coalesce(ld.liabilitynote,
						' ')|| ' ' || coalesce(referencetext,
						' ') ||
					  ' ' /*||coalesce(cor.footnotefordesc,' ')*/
						)::character varying as remarks

from
	kaveri.documentmaster i
join kaveri.propertymaster a on
	a.applicationnumber = i.applicationnumber
	and i.isregistrationcompleted = true
left join kaveri.liabilityonpropertydetails lpm on lpm.propertyid = a.propertyid   
left join kaveri.liabilitydetails ld on ld.liabilityid = lpm.liabilityid
left join kaveri.referencemaster ref on ref.documentid = i.documentid
join kaveri.propertynumberdetails f on a.propertyid = f.propertyid
join kaveri.partyinfo pi on i.applicationnumber = pi.applicationnumber
join kaveri.registrationarticles r on  i.regarticlecode = r.regarticlecode
join kaveri.measunitmaster g on a.unitid = g.unitid

join kaveri.sromaster b on
	a.srocode = b.srocode
                           
join kaveri.districtmaster c on
    b.districtcode = c.districtcode
                            
join kaveri.villagemaster d on
     a.villagecode = d.villagecode
     and d.srocode = i.srocode
                             
join kaveri.talukmaster tal on
     tal.districtcode = c.districtcode
     and d.talukcode = tal.talukcode
                         
join kaveri.hoblimaster hob on
     hob.hoblicode=d.hoblicode

where

	 (CASE   
                                WHEN _documentnumber is not NULL THEN i.finalregistrationnumber=_documentnumber
                                WHEN _from_date is not NULL and _to_date is not NULL THEN
                                i.registrationdatetime between _from_date and _to_date
                                ELSE 
                                    TRUE
	END)
	and  i.finalregistrationnumber is not null
	and (
                                            CASE
                                                WHEN _districtcode <> 0 THEN  b.districtcode = _districtcode
                                                ELSE TRUE
                                            END
                                        ) 
                                        and (
                                            CASE
                                                WHEN _talukcode <> 0 THEN  tal.talukcode = _talukcode
                                                ELSE TRUE
                                            end
                                            ) 
                                        and (
                                            CASE
                                                WHEN _hoblicode <> 0 THEN  hob.hoblicode = _hoblicode
                                                ELSE TRUE
                                            END
                                        ) 
                                        and (
                                            CASE
                                                WHEN _villagecode <> 0 THEN  a.villagecode = _villagecode
                                                ELSE TRUE
                                            END
                                        ) 
	
group by
	i.uploaddocdeedpath,
	g.unitid,
	a.totalarea,
	c.districtnamee,
	b.sronamee,
	d.villagenamee,
	tal.taluknamee,
	officeoforiginalregistration,
	executiondate,
	regndate,
	remarks,
	lpm.documentid,
	ld.liabilitynote,
	i.finalregistrationnumber,
	tal.talukcode,
	hob.hoblicode,
	a.villagecode,
	a.noofscanpages,
	i.applicationnumber,
	i.documentnumber, c.districtcode,b.srocode,tal.talukcode,hob.hoblicode,hob.hoblinamee,d.villagecode,a.propertyid,i.registrationdatetime
	
	
	
	
--	limit per_page offset PageOffset;
	              
       
       ),cte_count as (select count(*) as total_rows from cte)

            select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0;
--   raise notice 'Function execution end for all districts_form17_statutory' ;
end if;		

	END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form_of_index_number_2_part1_bck(_districtcode integer, _talukcode integer, _hoblicode integer, _villagecode bigint, _documentnumber character varying, _from_date timestamp without time zone, _to_date timestamp without time zone, page_number integer, per_page integer) OWNER TO postgres;

--
-- Name: fn_mis_form_of_index_number_2_part1_optimization(integer, integer, integer, bigint, character varying, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form_of_index_number_2_part1_optimization(_districtcode integer, _talukcode integer, _hoblicode integer, _villagecode bigint, _documentnumber character varying DEFAULT NULL::character varying, _from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _to_date timestamp without time zone DEFAULT NULL::timestamp without time zone, page_number integer DEFAULT NULL::integer, per_page integer DEFAULT NULL::integer) RETURNS TABLE(districtcode integer, district character varying, talukcode integer, talukname character varying, hoblicode integer, hoblinamee character varying, villagecode bigint, nameofvillage character varying, propertyid bigint, finalregistrationnumber character varying, registrationdatetime timestamp without time zone, natureofdeedandconsideration text, surveyno_subdivisionno_houseno text, area text, assessment character varying, claimant text, executant text, officeoforiginalregistration character varying, srocode integer, executiondate text, regndate text, serialno_volume_and_page text, copy_of_document text, remarks character varying)
    LANGUAGE plpgsql
    AS $$

declare 
	PageOffset INTEGER := 0;

	begin
		
		PageOffset := (per_page*page_number) - per_page;
        
        raise notice 'Function execution start for all districts_form17_statutory';
    
        return query
 
        select
		distinct 
					c.districtcode,
					c.districtnamee as district,
					tal.talukcode,
					tal.taluknamee as talukname,
					hob.hoblicode,
					hob.hoblinamee,
					d.villagecode,
					d.villagenamee as nameofvillage,
					a.propertyid,
					i.finalregistrationnumber,
					i.registrationdatetime,
					string_agg(distinct (coalesce(r.articlenamee::text, null::text) || ' - '::text) || ' ' || to_char(coalesce(a.sroconsideration, 0),
					'₹9,99,99,999D99'), ', ')::text as natureofdeedandconsideration,
					string_agg(distinct replace(f.currentnumber, '*', '/')::text, ', ')::text as surveyno_subdivisionno_houseno,
					case
						when g.unitid = 1 then div(ceil(a.totalarea * 40),
						40)::text || ' ' || 'Acre' || ' '
										   || mod(ceil(a.totalarea * 40),
						40)::text || ' ' || 'Gunta'
						when g.unitid = 2 then div(a.totalarea,
						40)::text || ' ' || 'Acre' || ' '
										   || mod(a.totalarea,
						40)::text || ' ' || 'Gunta'
						else
				 	string_agg(distinct (round( a.totalarea, 2 ) || ' '::text) || g.descriptionenglish::text, ', ')::text
					end as area,
					null::character varying as assessment,
					string_agg( distinct case
                            when pi.partytypeid = 1 then
                      coalesce(coalesce(pi.firstname,
                            ' ')|| ' ' || coalesce(pi.middlename,
                            ' ')|| ' ' || coalesce(pi.lastname,
                            ' '),
                            null::text)
                            else null
                        end ,
                        ', ')::text as claimant,
                        
                        string_agg( distinct case
                            when pi.partytypeid = 2 then
                      coalesce(coalesce(pi.firstname,
                            ' ')|| ' ' || coalesce(pi.middlename,
                            ' ')|| ' ' || coalesce(pi.lastname,
                            ' '),
                            null::text)
                            else null
                        end ,
                        ', ')::text as executant,
						b.sronamee as officeoforiginalregistration,
						b.srocode,
						to_char(i.executiondatetime,
						'DD-MM-YYYY') as executiondate,
						to_char(i.registrationdatetime,
						'DD-MM-YYYY') as regndate,
						TO_CHAR(i.documentnumber,
						'fm00000') as serialno_volume_and_page,
						i.uploaddocdeedpath as copy_of_document
					  ,
						(coalesce(ld.liabilitynote,
						' ')|| ' ' || coalesce(referencetext,
						' ') ||
					  ' ' /*||coalesce(cor.footnotefordesc,' ')*/
						)::character varying as remarks

from
	kaveri.documentmaster i
join kaveri.propertymaster a on
	a.applicationnumber = i.applicationnumber
	and i.isregistrationcompleted = true
left join kaveri.liabilityonpropertydetails lpm on lpm.propertyid = a.propertyid   
left join kaveri.liabilitydetails ld on ld.liabilityid = lpm.liabilityid
left join kaveri.referencemaster ref on ref.documentid = i.documentid
join kaveri.propertynumberdetails f on a.propertyid = f.propertyid
join kaveri.partyinfo pi on i.applicationnumber = pi.applicationnumber
join kaveri.registrationarticles r on  i.regarticlecode = r.regarticlecode
join kaveri.measunitmaster g on a.unitid = g.unitid

join kaveri.sromaster b on
	a.srocode = b.srocode
                           
join kaveri.districtmaster c on
    b.districtcode = c.districtcode
                            
join kaveri.villagemaster d on
     a.villagecode = d.villagecode
     and d.srocode = i.srocode
                             
join kaveri.talukmaster tal on
     tal.districtcode = c.districtcode
     and d.talukcode = tal.talukcode
                         
join kaveri.hoblimaster hob on
     hob.hoblicode=d.hoblicode

where

	 (CASE   
                                WHEN _documentnumber is not NULL THEN i.finalregistrationnumber=_documentnumber
                                WHEN _from_date is not NULL and _to_date is not NULL THEN
                                i.registrationdatetime::date between _from_date and _to_date
                                ELSE 
                                    TRUE
	END)
	and  i.finalregistrationnumber is not null
	and (
                                            CASE
                                                WHEN _districtcode <> 0 THEN  b.districtcode = _districtcode
                                                ELSE TRUE
                                            END
                                        ) 
                                        and (
                                            CASE
                                                WHEN _talukcode <> 0 THEN  tal.talukcode = _talukcode
                                                ELSE TRUE
                                            end
                                            ) 
                                        and (
                                            CASE
                                                WHEN _hoblicode <> 0 THEN  hob.hoblicode = _hoblicode
                                                ELSE TRUE
                                            END
                                        ) 
                                        and (
                                            CASE
                                                WHEN _villagecode <> 0 THEN  a.villagecode = _villagecode
                                                ELSE TRUE
                                            END
                                        ) 
	
group by
	i.uploaddocdeedpath,
	g.unitid,
	a.totalarea,
	c.districtnamee,
	b.sronamee,
	d.villagenamee,
	tal.taluknamee,
	officeoforiginalregistration,
	executiondate,
	regndate,
	remarks,
	lpm.documentid,
	ld.liabilitynote,
	i.finalregistrationnumber,
	tal.talukcode,
	hob.hoblicode,
	a.villagecode,
	a.noofscanpages,
	i.applicationnumber,
	i.documentnumber, c.districtcode,b.srocode,tal.talukcode,hob.hoblicode,hob.hoblinamee,d.villagecode,a.propertyid,i.registrationdatetime
	
	limit per_page offset PageOffset;
	              
        raise notice 'Function execution end for all districts_form17_statutory';
       

	END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form_of_index_number_2_part1_optimization(_districtcode integer, _talukcode integer, _hoblicode integer, _villagecode bigint, _documentnumber character varying, _from_date timestamp without time zone, _to_date timestamp without time zone, page_number integer, per_page integer) OWNER TO csgadmin;

--
-- Name: fn_mis_form_of_index_number_2_part2(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_form_of_index_number_2_part2(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, sroname character varying, natureofdocument character varying, consideration numeric, nameoffirstclaimant text, dateofregistration timestamp without time zone, volumename character varying, assessment character varying)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$
BEGIN	 
return query
 SELECT DISTINCT 
    c.districtnamee AS district,
    b.sronamee AS sroname,
    d.articlenamee AS nameofthedocument,
    a.consideration,
    string_agg(CASE
            WHEN pi.partytypeid = 1 THEN pi.name
            ELSE NULL::text
        END,', ')::text AS nameoffirstclaimant,
    e.registrationdatetime AS dateofregistration,
    e.finalregistrationnumber::character varying as volumename,
    a.valuationreport
   FROM kaveri.documentmaster e
     LEFT JOIN kaveri.propertymaster a ON e.applicationnumber = a.applicationnumber
     LEFT JOIN kaveri.sromaster b ON a.srocode = b.srocode AND a.consideration > 0::numeric
     LEFT JOIN kaveri.districtmaster c ON b.districtcode = c.districtcode
     LEFT JOIN kaveri.stamparticles d ON a.stamparticlecode = d.stamparticlecode
     LEFT JOIN kaveri.vw_fetch_party pi ON a.applicationnumber = pi.applicationnumber AND pi.name IS NOT NULL
     where b.districtcode = _districtcode and a.srocode = _srocode and e.registrationdatetime >= _from_date
	 and e.registrationdatetime <= _to_date
	 group by c.districtnamee, b.sronamee, d.articlenamee, a.consideration,e.registrationdatetime,
     volumename, a.valuationreport;

END;
$$;


ALTER FUNCTION kaverimis.fn_mis_form_of_index_number_2_part2(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_get_book4_form2b(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_get_book4_form2b(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer) RETURNS TABLE(districtcode bigint, srocode bigint, documentcount bigint, stampduty numeric, registrationfee numeric, scanningfee numeric, otherfees numeric, totalfees numeric)
    LANGUAGE plpgsql
    AS $$

begin
	
		return query 
		with a as (select distinct 
			 dsm.districtcode,a.srocode,a.applicationnumber
			from kaveri.documentmaster a 
			JOIN kaveri.applicantapplicationdetails aad ON a.applicationnumber=aad.applicationnumber
			left JOIN kaveri.feesrequired fr ON a.applicationnumber=fr.applicationnumber
			JOIN kaveri.sromaster sm ON a.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
		    --join kaveri.propertymaster pm  on a.applicationnumber=pm.applicationnumber 
			where (a.registrationdatetime between _fromdate and _todate ::timestamp + INTERVAL '1 day')
			and a.isregistrationcompleted = true 
			--and aad.currentstatus='CD120'
			--and pm.stamparticlecode not in (43,3,56) and pm.stampruleid != 345   
			and a.bookid=4 
			and (case when _districtcode<>0 then dsm.districtcode=_districtcode ELSE true end)
			and (case when _srocode<> 0 then sm.srocode=_srocode ELSE true end)
			
                ),
                
                
			b as (
			  
			 select distinct a.districtcode,a.srocode,f.applicationnumber  from 
			 a
			 left join  kaveri.feesrequired f on a.applicationnumber=f.applicationnumber
			 where 
			 (case

		                    when _amounttype=1 then true   --Total
		                                    
		                    when _amounttype=2 then  f.feerulecode in (36,58,59,104,89,88)  --stamp duty
		                    
		                    when _amounttype=3 then  f.feerulecode in  (1)  -- registrationfee
		                    
		                    when _amounttype=4 then  f.feerulecode in  (2)  -- Scanning fees
		                    
		                    when _amounttype=5 then  f.feerulecode  not in  (1,2,36,58,59,104,89,88)  -- Other fees
		                   
		
		                    else     true --amounttype null

                                                

  					 end)
			 
			 group by a.districtcode,a.srocode,f.applicationnumber 
			 having 
				(case
					when _amounttype in (1,2,3,4,5) then sum(f.amountpaid) >= _minval 
					and sum(f.amountpaid) <= _maxval
                                        
                    ELSE          true                                               

                end )
			
			
			)
                
                
                
			select 
			b.districtcode::bigint,b.srocode::bigint,count(distinct b.applicationnumber),
			sum(case when f.feerulecode in (36,58,59,104,89,88)  then f.amountpaid  else 0 end) as stampduty,
			sum(case when f.feerulecode in (1) then	f.amountpaid  else 0 end) as registrationfee,
			sum(case when f.feerulecode in (2) then	f.amountpaid  else 0 end) as scanningfee,
			sum(case when f.feerulecode  not in  (1,2,36,58,59,104,89,88) then f.amountpaid else 0 end) as otherfees,
			sum(f.amountpaid)as totalfees
			from b 
			left join kaveri.feesrequired f on b.applicationnumber=f.applicationnumber 
			group by b.districtcode,b.srocode;

END;
$$;


ALTER FUNCTION kaverimis.fn_mis_get_book4_form2b(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer) OWNER TO postgres;

--
-- Name: fn_mis_get_data_otherdeed_form2b(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_get_data_otherdeed_form2b(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer) RETURNS TABLE(districtcode bigint, srocode bigint, documentcount bigint, stampduty numeric, registrationfee numeric, scanningfee numeric, otherfees numeric, totalfees numeric)
    LANGUAGE plpgsql
    AS $$

begin
	
		return query 
		with a as (select distinct 
			 dsm.districtcode,a.srocode,a.applicationnumber
			from kaveri.documentmaster a 
			JOIN kaveri.applicantapplicationdetails aad ON a.applicationnumber=aad.applicationnumber
			left JOIN kaveri.feesrequired fr ON a.applicationnumber=fr.applicationnumber
			JOIN kaveri.sromaster sm ON a.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
		    join kaveri.propertymaster pm  on a.applicationnumber=pm.applicationnumber 
			where (a.registrationdatetime between _fromdate and _todate ::timestamp + INTERVAL '1 day')
			and a.isregistrationcompleted = true 
--			and aad.currentstatus='CD120'
			and pm.stamparticlecode not in (43,3,56) and pm.stampruleid != 345   
			and a.bookid=4 
			and (case  when _districtcode<>0 then dsm.districtcode=_districtcode  ELSE  true end)
			and (case  when _srocode<> 0 then sm.srocode=_srocode  ELSE  true end)
			
                ),
                
                
			b as (
			  
			 select distinct a.districtcode,a.srocode,f.applicationnumber  from 
			 a
			 left join  kaveri.feesrequired f on a.applicationnumber=f.applicationnumber
			 where 
			 (case

		                    when _amounttype=1 then true   --Total
		                                    
		                    when _amounttype=2 then  f.feerulecode in (36,58,59,104,89,88)  --stamp duty
		                    
		                    when _amounttype=3 then  f.feerulecode in  (1)  -- registrationfee
		                    
		                    when _amounttype=4 then  f.feerulecode in  (2)  -- Scanning fees
		                    
		                    when _amounttype=5 then  f.feerulecode  not in  (1,2,36,58,59,104,89,88)  -- Other fees
		                   
		
		                    else     true --amounttype null

                                                

  					 end)
			 
			 group by a.districtcode,a.srocode,f.applicationnumber 
			 having 
				(case
					when _amounttype in (1,2,3,4,5) then sum(f.amountpaid) >= _minval 
					and sum(f.amountpaid) <= _maxval
                                        
                    ELSE          true                                               

                end )
			
			
			)
                
                
                
			select 
			b.districtcode::bigint,b.srocode::bigint,count(distinct b.applicationnumber),
			sum(case when f.feerulecode in (36,58,59,104,89,88) then f.amountpaid  else 0 end) as stampduty,
			sum(case when f.feerulecode in (1) then	f.amountpaid  else 0 end) as registrationfee,
			sum(case when f.feerulecode in (2) then	f.amountpaid  else 0 end) as scanningfee,
			sum(case when f.feerulecode not in (1,2,36,58,59,104,89,88) then f.amountpaid else 0 end) as otherfees,
			sum(f.amountpaid)as totalfees
			from b 
			left join kaveri.feesrequired f on b.applicationnumber=f.applicationnumber 
			group by b.districtcode,b.srocode;

END;
$$;


ALTER FUNCTION kaverimis.fn_mis_get_data_otherdeed_form2b(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer) OWNER TO postgres;

--
-- Name: fn_mis_high_val_props(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_high_val_props(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _choice integer DEFAULT NULL::integer, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(sronamee character varying, districtnamee character varying, finyear text, monthname text, documentsregistered bigint, registrationfees numeric, stampduty numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);


if (pagenumber<>-1 and pagesize<>-1) then

return query

with cte as (
				with a as (
				
					select 
					d.districtnamee,
					sm.sronamee ,
					dm.registrationdatetime ,
					dm.applicationnumber 
					from kaveri.documentmaster dm
					join kaveri.applicantapplicationdetails a on dm.applicationnumber=a.applicationnumber
					inner join kaveri.feesrequired fr ON dm.applicationnumber = fr.applicationnumber
					inner join kaveri.sromaster sm on dm.srocode = sm.srocode
					join kaveri.districtmaster d on sm.districtcode = d.districtcode
					where  
					(case  when _districtcode<>0 then d.districtcode=_districtcode  ELSE  true end)
					and (case  when _srocode<> 0 then sm.srocode=_srocode  ELSE  true end)
					and dm.isregistrationcompleted = true
					and a.currentstatus = 'CD120'
					and (dm.registrationdatetime between _from_date  and  _to_date +INTERVAL '1 day')
					
					and 

 					(case

		                    when _choice=1 then true   --Total
		                                    
		                    when _choice=2 then  fr.feerulecode in (36,58,59,64)  --stamp duty
		                    
		                    when _choice=3 then  fr.feerulecode in  (1,65)  -- registrationfee
		                   
		
		                    else     true --amounttype null

                                                

  					 end)
 
 				group by d.districtnamee,sm.sronamee,dm.applicationnumber,dm.registrationdatetime
				having 
				(case
					when _choice in (1,2,3) then sum(fr.amountpaid) >= _minval  and sum(fr.amountpaid) <= _maxval
                                        
                    ELSE          true                                               

                end ))
				
				

				select 
			a.sronamee ,a.districtnamee,
			to_char(a.registrationdatetime, 'yyyy') as finyear,
			to_char(a.registrationdatetime, 'month') as monthname,
			count(distinct a.applicationnumber) as documentsregistered,
			sum(case when rr.feerulecode in (1,65)   then rr.amountpaid else 0 end) as RegistrationFees,
			sum(case when rr.feerulecode in (36,58,59,64)  then rr.amountpaid else 0 end)as StampDuty,
			sum(case when rr.feerulecode in (1,36,58,59,64,65)  then rr.amountpaid else 0 end) as Total
		from a 
		inner join kaveri.feesrequired rr   on a.applicationnumber=rr.applicationnumber 
		group by finyear, monthname,a.sronamee ,a.districtnamee)  ,cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0  
			limit pagesize offset PageOffset;
		
	elsif (pagenumber=-1 or  pagesize=-1) then 
	
	return query

with cte as (with a as (
				
					select 
					d.districtnamee,
					sm.sronamee ,
					dm.registrationdatetime ,
					dm.applicationnumber 
					from kaveri.documentmaster dm
					join kaveri.applicantapplicationdetails a on dm.applicationnumber=a.applicationnumber
					inner join kaveri.feesrequired fr ON dm.applicationnumber = fr.applicationnumber
					inner join kaveri.sromaster sm on dm.srocode = sm.srocode
					join kaveri.districtmaster d on sm.districtcode = d.districtcode
					where  
					(case  when _districtcode<>0 then d.districtcode=_districtcode  ELSE  true end)
					and (case  when _srocode<> 0 then sm.srocode=_srocode  ELSE  true end)
					and dm.isregistrationcompleted = true
					and a.currentstatus = 'CD120'
					and (dm.registrationdatetime between _from_date  and  _to_date +INTERVAL '1 day')
					
					and 

 					(case

		                    when _choice=1 then true   --Total
		                                    
		                    when _choice=2 then  fr.feerulecode in (36,58,59,64)  --stamp duty
		                    
		                    when _choice=3 then  fr.feerulecode in  (1,65)  -- registrationfee
		                   
		
		                    else     true --amounttype null

                                                

  					 end)
 
 				group by d.districtnamee,sm.sronamee,dm.applicationnumber,dm.registrationdatetime
				having 
				(case
					when _choice in (1,2,3) then sum(fr.amountpaid) >= _minval  and sum(fr.amountpaid) <= _maxval
                                        
                    ELSE          true                                               

                end ))
				
				

				select 
			a.sronamee ,a.districtnamee,
			to_char(a.registrationdatetime, 'yyyy') as finyear,
			to_char(a.registrationdatetime, 'month') as monthname,
			count(distinct a.applicationnumber) as documentsregistered,
			sum(case when rr.feerulecode in (1,65)   then rr.amountpaid else 0 end) as RegistrationFees,
			sum(case when rr.feerulecode in (36,58,59,64)  then rr.amountpaid else 0 end)as StampDuty,
			sum(case when rr.feerulecode in (1,36,58,59,64,65)  then rr.amountpaid else 0 end) as Total
		from a 
		inner join kaveri.feesrequired rr   on a.applicationnumber=rr.applicationnumber 
		group by finyear, monthname,a.sronamee ,a.districtnamee)  ,cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0  ;
	
	
	
	end if;





END;

$$;


ALTER FUNCTION kaverimis.fn_mis_high_val_props(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _choice integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_high_val_props(integer, integer, timestamp without time zone, timestamp without time zone, numeric, numeric, integer, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_high_val_props(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _minval1 numeric DEFAULT NULL::numeric, _maxval1 numeric DEFAULT NULL::numeric, _choice integer DEFAULT NULL::integer, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtnamee character varying, sronamee character varying, finyear text, monthname text, documentsregistered bigint, stampduty numeric, registrationfees numeric, scanningfees numeric, otherfees numeric, total numeric, considerationamount numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
    PageOffset INTEGER := 0;

BEGIN
    PageOffset := ((pagenumber - 1) * pagesize);

    IF (pagenumber = 1) THEN

        RETURN QUERY
        WITH cte AS (
            WITH b AS (
                SELECT DISTINCT
                    d.districtnamee,
                    sm.sronamee,
                    dm.registrationdatetime,
                    dm.applicationnumber,
                    SUM(p.sroconsideration) AS totalconsideration
                FROM kaveri.documentmaster dm
                JOIN kaveri.applicantapplicationdetails a
                    ON dm.applicationnumber = a.applicationnumber
                LEFT JOIN kaveri.propertymaster p
                    ON dm.applicationnumber = p.applicationnumber
                JOIN kaveri.sromaster sm
                    ON dm.srocode = sm.srocode
                JOIN kaveri.districtmaster d
                    ON sm.districtcode = d.districtcode
                WHERE (CASE WHEN _districtcode <> 0 THEN d.districtcode = _districtcode ELSE true END)
                  AND (CASE WHEN _srocode <> 0 THEN sm.srocode = _srocode ELSE true END)
                  AND dm.isregistrationcompleted = true
                  AND (dm.registrationdatetime BETWEEN _from_date AND _to_date + INTERVAL '1 day')
                  AND (p.sroconsideration BETWEEN _minval1 AND _maxval1)
                GROUP BY
                    d.districtnamee,
                    sm.sronamee,
                    dm.applicationnumber,
                    dm.registrationdatetime
            ),

            a AS (
                SELECT DISTINCT
                    dm.applicationnumber
                FROM kaveri.documentmaster dm
                LEFT JOIN kaveri.feesrequired fr
                    ON dm.applicationnumber = fr.applicationnumber
                JOIN b
                    ON dm.applicationnumber = b.applicationnumber
                WHERE
                    (CASE
                        WHEN _choice = 1 THEN true  -- Total

                        -- UPDATED: StampDuty choice (exclude 64/89/104/88 from stamp bucket; they are special/non-total)
                        WHEN _choice = 2 THEN fr.feerulecode IN (35,36,91,92,101,107,110,138)

                        -- UPDATED: RegistrationFees choice (expand beyond only 1; exclude 88)
                        WHEN _choice = 3 THEN fr.feerulecode IN (
                            1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                            57,63,65,90,93,94,95,96,97,98,102,103,106,108,109
                        )

                        WHEN _choice = 4 THEN fr.feerulecode IN (2) -- Scanning

                        -- UPDATED: OtherFees choice (exclude stamp/reg/scanning + special 64/88/89/104)
                        WHEN _choice = 5 THEN fr.feerulecode NOT IN (
                            2,
                            35,36,91,92,101,107,110,138,
                            1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                            57,63,65,90,93,94,95,96,97,98,102,103,106,108,109,
                            64,88,89,104
                        )
                        ELSE true
                     END)
                GROUP BY dm.applicationnumber
                HAVING
                    (CASE
                        WHEN _choice IN (1,2,3,4,5) THEN SUM(fr.amountpaid) >= _minval AND SUM(fr.amountpaid) <= _maxval
                        ELSE true
                     END)
            ),

            c AS (
                SELECT
                    b.districtnamee,
                    b.sronamee,
                    to_char(b.registrationdatetime, 'yyyy') AS finyear,
                    to_char(b.registrationdatetime, 'Month') AS monthname,
                    SUM(totalconsideration) AS consideration
                FROM b
                GROUP BY
                    b.districtnamee,
                    b.sronamee,
                    finyear,
                    monthname
            )

            SELECT DISTINCT temp.*, c.consideration
            FROM (
                (
                    SELECT
                        b.districtnamee,
                        b.sronamee,
                        to_char(b.registrationdatetime, 'yyyy') AS finyear,
                        to_char(b.registrationdatetime, 'Month') AS monthname,
                        COUNT(DISTINCT a.applicationnumber) AS documentsregistered,

                        -- UPDATED: StampDuty bucket
                        SUM(CASE WHEN rr.feerulecode IN (35,36,91,92,101,107,110,138)
                                 THEN rr.amountpaid ELSE 0 END) AS StampDuty,

                        -- UPDATED: RegistrationFees bucket
                        SUM(CASE WHEN rr.feerulecode IN (
                                     1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                                     57,63,65,90,93,94,95,96,97,98,102,103,106,108,109
                                 )
                                 THEN rr.amountpaid ELSE 0 END) AS RegistrationFees,

                        -- Scanning bucket (unchanged)
                        SUM(CASE WHEN rr.feerulecode IN (2)
                                 THEN rr.amountpaid ELSE 0 END) AS scanningfees,

                        -- UPDATED: OtherFees bucket (exclude special 64/88/89/104)
                        SUM(CASE WHEN rr.amountpaid > 0
                                   AND rr.feerulecode NOT IN (
                                       2,
                                       35,36,91,92,101,107,110,138,
                                       1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                                       57,63,65,90,93,94,95,96,97,98,102,103,106,108,109,
                                       64,88,89,104
                                   )
                                 THEN rr.amountpaid ELSE 0 END) AS otherfees,

                        -- IMPORTANT: Total must EXCLUDE 64/88/89/104 (as you confirmed)
                        SUM(CASE WHEN rr.feerulecode NOT IN (64,104,89,88)
                                 THEN rr.amountpaid ELSE 0 END) AS Total
                    FROM b
                    JOIN a
                        ON b.applicationnumber = a.applicationnumber
                    LEFT JOIN kaveri.feesrequired rr
                        ON a.applicationnumber = rr.applicationnumber
                    GROUP BY
                        finyear,
                        monthname,
                        b.sronamee,
                        b.districtnamee
                ) temp
                JOIN c
                    ON temp.districtnamee = c.districtnamee
                   AND temp.sronamee = c.sronamee
                   AND temp.finyear = c.finyear
                   AND temp.monthname = c.monthname
            )
        ),
        cte_count AS (
            SELECT COUNT(*) AS total_rows FROM cte
        )
        SELECT *
        FROM cte
        JOIN (SELECT DISTINCT total_rows FROM cte_count) total_row ON true
        ORDER BY cte.districtnamee ASC, cte.sronamee ASC
        LIMIT pagesize OFFSET PageOffset;

    ELSIF (pagenumber > 1) THEN

        RETURN QUERY
        WITH cte AS (
            WITH b AS (
                SELECT DISTINCT
                    d.districtnamee,
                    sm.sronamee,
                    dm.registrationdatetime,
                    dm.applicationnumber,
                    SUM(p.sroconsideration) AS totalconsideration
                FROM kaveri.documentmaster dm
                JOIN kaveri.applicantapplicationdetails a
                    ON dm.applicationnumber = a.applicationnumber
                LEFT JOIN kaveri.propertymaster p
                    ON dm.applicationnumber = p.applicationnumber
                JOIN kaveri.sromaster sm
                    ON dm.srocode = sm.srocode
                JOIN kaveri.districtmaster d
                    ON sm.districtcode = d.districtcode
                WHERE (CASE WHEN _districtcode <> 0 THEN d.districtcode = _districtcode ELSE true END)
                  AND (CASE WHEN _srocode <> 0 THEN sm.srocode = _srocode ELSE true END)
                  AND dm.isregistrationcompleted = true
                  AND (dm.registrationdatetime BETWEEN _from_date AND _to_date + INTERVAL '1 day')
                  AND (p.sroconsideration BETWEEN _minval1 AND _maxval1)
                GROUP BY
                    d.districtnamee,
                    sm.sronamee,
                    dm.applicationnumber,
                    dm.registrationdatetime
            ),

            a AS (
                SELECT DISTINCT
                    dm.applicationnumber
                FROM kaveri.documentmaster dm
                LEFT JOIN kaveri.feesrequired fr
                    ON dm.applicationnumber = fr.applicationnumber
                JOIN b
                    ON dm.applicationnumber = b.applicationnumber
                WHERE
                    (CASE
                        WHEN _choice = 1 THEN true
                        WHEN _choice = 2 THEN fr.feerulecode IN (35,36,91,92,101,107,110,138)
                        WHEN _choice = 3 THEN fr.feerulecode IN (
                            1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                            57,63,65,90,93,94,95,96,97,98,102,103,106,108,109
                        )
                        WHEN _choice = 4 THEN fr.feerulecode IN (2)
                        WHEN _choice = 5 THEN fr.feerulecode NOT IN (
                            2,
                            35,36,91,92,101,107,110,138,
                            1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                            57,63,65,90,93,94,95,96,97,98,102,103,106,108,109,
                            64,88,89,104
                        )
                        ELSE true
                     END)
                GROUP BY dm.applicationnumber
                HAVING
                    (CASE
                        WHEN _choice IN (1,2,3,4,5) THEN SUM(fr.amountpaid) >= _minval AND SUM(fr.amountpaid) <= _maxval
                        ELSE true
                     END)
            ),

            c AS (
                SELECT
                    b.districtnamee,
                    b.sronamee,
                    to_char(b.registrationdatetime, 'yyyy') AS finyear,
                    to_char(b.registrationdatetime, 'Month') AS monthname,
                    SUM(totalconsideration) AS consideration
                FROM b
                GROUP BY
                    b.districtnamee,
                    b.sronamee,
                    finyear,
                    monthname
            )

            SELECT DISTINCT temp.*, c.consideration
            FROM (
                (
                    SELECT
                        b.districtnamee,
                        b.sronamee,
                        to_char(b.registrationdatetime, 'yyyy') AS finyear,
                        to_char(b.registrationdatetime, 'Month') AS monthname,
                        COUNT(DISTINCT a.applicationnumber) AS documentsregistered,
                        SUM(CASE WHEN rr.feerulecode IN (35,36,91,92,101,107,110,138)
                                 THEN rr.amountpaid ELSE 0 END) AS StampDuty,
                        SUM(CASE WHEN rr.feerulecode IN (
                                     1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                                     57,63,65,90,93,94,95,96,97,98,102,103,106,108,109
                                 )
                                 THEN rr.amountpaid ELSE 0 END) AS RegistrationFees,
                        SUM(CASE WHEN rr.feerulecode IN (2)
                                 THEN rr.amountpaid ELSE 0 END) AS scanningfees,
                        SUM(CASE WHEN rr.amountpaid > 0
                                   AND rr.feerulecode NOT IN (
                                       2,
                                       35,36,91,92,101,107,110,138,
                                       1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                                       57,63,65,90,93,94,95,96,97,98,102,103,106,108,109,
                                       64,88,89,104
                                   )
                                 THEN rr.amountpaid ELSE 0 END) AS otherfees,
                        SUM(CASE WHEN rr.feerulecode NOT IN (64,104,89,88)
                                 THEN rr.amountpaid ELSE 0 END) AS Total
                    FROM b
                    JOIN a
                        ON b.applicationnumber = a.applicationnumber
                    LEFT JOIN kaveri.feesrequired rr
                        ON a.applicationnumber = rr.applicationnumber
                    GROUP BY
                        finyear,
                        monthname,
                        b.sronamee,
                        b.districtnamee
                ) temp
                JOIN c
                    ON temp.districtnamee = c.districtnamee
                   AND temp.sronamee = c.sronamee
                   AND temp.finyear = c.finyear
                   AND temp.monthname = c.monthname
            )
        )
        SELECT DISTINCT *, NULL::bigint AS totalcount
        FROM cte
        ORDER BY cte.districtnamee ASC, cte.sronamee ASC
        LIMIT pagesize OFFSET PageOffset;

    ELSIF (pagenumber = -1 OR pagesize = -1) THEN

        RETURN QUERY
        WITH cte AS (
            WITH b AS (
                SELECT DISTINCT
                    d.districtnamee,
                    sm.sronamee,
                    dm.registrationdatetime,
                    dm.applicationnumber,
                    SUM(p.sroconsideration) AS totalconsideration
                FROM kaveri.documentmaster dm
                JOIN kaveri.applicantapplicationdetails a
                    ON dm.applicationnumber = a.applicationnumber
                LEFT JOIN kaveri.propertymaster p
                    ON dm.applicationnumber = p.applicationnumber
                JOIN kaveri.sromaster sm
                    ON dm.srocode = sm.srocode
                JOIN kaveri.districtmaster d
                    ON sm.districtcode = d.districtcode
                WHERE (CASE WHEN _districtcode <> 0 THEN d.districtcode = _districtcode ELSE true END)
                  AND (CASE WHEN _srocode <> 0 THEN sm.srocode = _srocode ELSE true END)
                  AND dm.isregistrationcompleted = true
                  AND (dm.registrationdatetime BETWEEN _from_date AND _to_date + INTERVAL '1 day')
                  AND (p.sroconsideration BETWEEN _minval1 AND _maxval1)
                GROUP BY
                    d.districtnamee,
                    sm.sronamee,
                    dm.applicationnumber,
                    dm.registrationdatetime
            ),

            a AS (
                SELECT DISTINCT
                    dm.applicationnumber
                FROM kaveri.documentmaster dm
                LEFT JOIN kaveri.feesrequired fr
                    ON dm.applicationnumber = fr.applicationnumber
                JOIN b
                    ON dm.applicationnumber = b.applicationnumber
                WHERE
                    (CASE
                        WHEN _choice = 1 THEN true
                        WHEN _choice = 2 THEN fr.feerulecode IN (35,36,91,92,101,107,110,138)
                        WHEN _choice = 3 THEN fr.feerulecode IN (
                            1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                            57,63,65,90,93,94,95,96,97,98,102,103,106,108,109
                        )
                        WHEN _choice = 4 THEN fr.feerulecode IN (2)
                        WHEN _choice = 5 THEN fr.feerulecode NOT IN (
                            2,
                            35,36,91,92,101,107,110,138,
                            1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                            57,63,65,90,93,94,95,96,97,98,102,103,106,108,109,
                            64,88,89,104
                        )
                        ELSE true
                     END)
                GROUP BY dm.applicationnumber
                HAVING
                    (CASE
                        WHEN _choice IN (1,2,3,4,5) THEN SUM(fr.amountpaid) >= _minval AND SUM(fr.amountpaid) <= _maxval
                        ELSE true
                     END)
            ),

            c AS (
                SELECT
                    b.districtnamee,
                    b.sronamee,
                    to_char(b.registrationdatetime, 'yyyy') AS finyear,
                    to_char(b.registrationdatetime, 'Month') AS monthname,
                    SUM(totalconsideration) AS consideration
                FROM b
                GROUP BY
                    b.districtnamee,
                    b.sronamee,
                    finyear,
                    monthname
            )

            SELECT DISTINCT temp.*, c.consideration
            FROM (
                (
                    SELECT
                        b.districtnamee,
                        b.sronamee,
                        to_char(b.registrationdatetime, 'yyyy') AS finyear,
                        to_char(b.registrationdatetime, 'Month') AS monthname,
                        COUNT(DISTINCT a.applicationnumber) AS documentsregistered,
                        SUM(CASE WHEN rr.feerulecode IN (35,36,91,92,101,107,110,138)
                                 THEN rr.amountpaid ELSE 0 END) AS StampDuty,
                        SUM(CASE WHEN rr.feerulecode IN (
                                     1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                                     57,63,65,90,93,94,95,96,97,98,102,103,106,108,109
                                 )
                                 THEN rr.amountpaid ELSE 0 END) AS RegistrationFees,
                        SUM(CASE WHEN rr.feerulecode IN (2)
                                 THEN rr.amountpaid ELSE 0 END) AS scanningfees,
                        SUM(CASE WHEN rr.amountpaid > 0
                                   AND rr.feerulecode NOT IN (
                                       2,
                                       35,36,91,92,101,107,110,138,
                                       1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                                       57,63,65,90,93,94,95,96,97,98,102,103,106,108,109,
                                       64,88,89,104
                                   )
                                 THEN rr.amountpaid ELSE 0 END) AS otherfees,
                        SUM(CASE WHEN rr.feerulecode NOT IN (64,104,89,88)
                                 THEN rr.amountpaid ELSE 0 END) AS Total
                    FROM b
                    JOIN a
                        ON b.applicationnumber = a.applicationnumber
                    LEFT JOIN kaveri.feesrequired rr
                        ON a.applicationnumber = rr.applicationnumber
                    GROUP BY
                        finyear,
                        monthname,
                        b.sronamee,
                        b.districtnamee
                ) temp
                JOIN c
                    ON temp.districtnamee = c.districtnamee
                   AND temp.sronamee = c.sronamee
                   AND temp.finyear = c.finyear
                   AND temp.monthname = c.monthname
            )
        )
        SELECT DISTINCT *, NULL::bigint AS totalcount
        FROM cte
        ORDER BY cte.districtnamee ASC, cte.sronamee ASC;

    END IF;

END;
$$;


ALTER FUNCTION kaverimis.fn_mis_high_val_props(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _minval1 numeric, _maxval1 numeric, _choice integer, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_high_val_props_20260316(integer, integer, timestamp without time zone, timestamp without time zone, numeric, numeric, integer, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: manjunathswamy
--

CREATE FUNCTION kaverimis.fn_mis_high_val_props_20260316(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _minval1 numeric DEFAULT NULL::numeric, _maxval1 numeric DEFAULT NULL::numeric, _choice integer DEFAULT NULL::integer, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtnamee character varying, sronamee character varying, finyear text, monthname text, documentsregistered bigint, finalregistrationnumber character varying, stampduty numeric, registrationfees numeric, scanningfees numeric, otherfees numeric, total numeric, considerationamount numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    PageOffset integer := 0;
BEGIN
    IF COALESCE(pagenumber, -1) <> -1
       AND COALESCE(pagesize, -1) <> -1 THEN

        PageOffset := (pagesize * pagenumber) - pagesize;

        RETURN QUERY
        WITH prop_amt AS
        (
            SELECT
                p.applicationnumber,
                COALESCE(SUM(p.sroconsideration), 0)::numeric AS considerationamount
            FROM kaveri.propertymaster p
            GROUP BY p.applicationnumber
        ),
        base_docs AS
        (
            SELECT
                d.districtnamee::varchar AS districtnamee,
                sm.sronamee::varchar AS sronamee,
                dm.applicationnumber,
                dm.documentid,
                dm.finalregistrationnumber::varchar AS finalregistrationnumber,
                dm.registrationdatetime,
                COALESCE(pa.considerationamount, 0)::numeric AS considerationamount
            FROM kaveri.documentmaster dm
            JOIN kaveri.sromaster sm
                ON sm.srocode = dm.srocode
            JOIN kaveri.districtmaster d
                ON d.districtcode = sm.districtcode
            LEFT JOIN prop_amt pa
                ON pa.applicationnumber = dm.applicationnumber
            WHERE dm.isregistrationcompleted = true
              AND dm.registrationdatetime >= _from_date
              AND dm.registrationdatetime < (_to_date + interval '1 day')
              AND (CASE WHEN _districtcode <> 0 THEN d.districtcode = _districtcode ELSE true END)
              AND (CASE WHEN _srocode <> 0 THEN dm.srocode = _srocode ELSE true END)
              AND _minval1 IS NOT NULL
              AND COALESCE(pa.considerationamount, 0) >= _minval1
              AND (_maxval1 IS NULL OR COALESCE(pa.considerationamount, 0) <= _maxval1)
        ),
        success_ref AS
        (
            SELECT DISTINCT b.deptreferencecode
            FROM kaveri.ams_reg_epaymentbankackdetails b
            WHERE b.paymentstatuscode IN ('10700066', '10700072')
        ),
        success_epay AS
        (
            SELECT
                e.applicationnumber,
                e.feerulecode,
                COALESCE(e.totalamount, 0)::numeric AS totalamount
            FROM kaveri.ams_reg_epaymenttransdetails e
            JOIN success_ref sr
                ON sr.deptreferencecode = e.deptreferencecode
            WHERE e.isdelete = false
              AND e.applicationnumber IN (SELECT bd.applicationnumber FROM base_docs bd)
        ),
        amt AS
        (
            SELECT
                se.applicationnumber,

                COALESCE(SUM(
                    CASE
                        WHEN se.feerulecode IN (35,36,64,89,91,92,101,107,110,138,59,100)
                        THEN se.totalamount ELSE 0
                    END
                ), 0)::numeric AS stampduty_amt,

                COALESCE(SUM(
                    CASE
                        WHEN se.feerulecode IN (
