                COALESCE(SUM(
                    CASE
                        WHEN se.feerulecode IN (
                            1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                            57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                        )
                        THEN se.totalamount ELSE 0
                    END
                ), 0)::numeric AS registrationfees_amt,

                COALESCE(SUM(
                    CASE
                        WHEN se.feerulecode = 2
                        THEN se.totalamount ELSE 0
                    END
                ), 0)::numeric AS scanningfees_amt,

                COALESCE(SUM(
                    CASE
                        WHEN se.feerulecode NOT IN (
                            35,36,64,89,91,92,101,107,110,138,59,100,
                            1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                            57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109,
                            2
                        )
                        THEN se.totalamount ELSE 0
                    END
                ), 0)::numeric AS otherfees_amt

            FROM success_epay se
            GROUP BY se.applicationnumber
        ),
        final_cte AS
        (
            SELECT
                bd.districtnamee,
                bd.sronamee,
                bd.articlename,
                to_char(bd.registrationdatetime, 'YYYY')::text AS finyear,
                trim(to_char(bd.registrationdatetime, 'Month'))::text AS monthname,
                1::bigint AS documentsregistered,
                bd.finalregistrationnumber,
                COALESCE(a.stampduty_amt, 0)::numeric AS stampduty,
                COALESCE(a.registrationfees_amt, 0)::numeric AS registrationfees,
                COALESCE(a.scanningfees_amt, 0)::numeric AS scanningfees,
                COALESCE(a.otherfees_amt, 0)::numeric AS otherfees,
                (
                    COALESCE(a.stampduty_amt, 0)
                    + COALESCE(a.registrationfees_amt, 0)
                    + COALESCE(a.scanningfees_amt, 0)
                    + COALESCE(a.otherfees_amt, 0)
                )::numeric AS total,
                COALESCE(bd.considerationamount, 0)::numeric AS considerationamount,
                COUNT(*) OVER()::bigint AS totalcount
            FROM base_docs bd
            LEFT JOIN amt a
                ON a.applicationnumber = bd.applicationnumber
            WHERE CASE
                    WHEN _choice = 2 THEN COALESCE(a.stampduty_amt, 0) > 0
                    WHEN _choice = 3 THEN COALESCE(a.registrationfees_amt, 0) > 0
                    WHEN _choice = 4 THEN COALESCE(a.scanningfees_amt, 0) > 0
                    WHEN _choice = 5 THEN COALESCE(a.otherfees_amt, 0) > 0
                    ELSE true
                  END
        )
        SELECT
            f.districtnamee,
            f.sronamee,
            f.articlename,
            f.finyear,
            f.monthname,
            f.documentsregistered,
            f.finalregistrationnumber,
            f.stampduty,
            f.registrationfees,
            f.scanningfees,
            f.otherfees,
            f.total,
            f.considerationamount,
            f.totalcount
        FROM final_cte f
        ORDER BY f.districtnamee, f.sronamee, f.finalregistrationnumber
        LIMIT pagesize OFFSET PageOffset;

    ELSIF (pagenumber = -1 OR pagesize = -1) THEN

        RETURN QUERY
        WITH prop_amt AS
        (
            SELECT
                p.applicationnumber,
                COALESCE(SUM(p.sroconsideration), 0)::numeric AS considerationamount
            FROM kaveri.propertymaster p
            GROUP BY p.applicationnumber
        ),
        base_docs AS
        (
            SELECT
                d.districtnamee::varchar AS districtnamee,
                sm.sronamee::varchar AS sronamee,
                COALESCE(r.articlenamee, 'unknown')::varchar AS articlename,
                dm.applicationnumber,
                dm.documentid,
                dm.finalregistrationnumber::varchar AS finalregistrationnumber,
                dm.registrationdatetime,
                COALESCE(pa.considerationamount, 0)::numeric AS considerationamount
            FROM kaveri.documentmaster dm
            JOIN kaveri.sromaster sm
                ON sm.srocode = dm.srocode
            JOIN kaveri.districtmaster d
                ON d.districtcode = sm.districtcode
            LEFT JOIN kaveri.registrationarticles r
                ON dm.regarticlecode = r.regarticlecode
            LEFT JOIN prop_amt pa
                ON pa.applicationnumber = dm.applicationnumber
            WHERE dm.isregistrationcompleted = true
              AND dm.registrationdatetime >= _from_date
              AND dm.registrationdatetime < (_to_date + interval '1 day')
              AND (
                    CASE
                        WHEN _regarticlecode = 0 THEN true
                        ELSE dm.regarticlecode = _regarticlecode
                    END
                  )
              AND (CASE WHEN _districtcode <> 0 THEN d.districtcode = _districtcode ELSE true END)
              AND (CASE WHEN _srocode <> 0 THEN dm.srocode = _srocode ELSE true END)
              AND _minval1 IS NOT NULL
              AND COALESCE(pa.considerationamount, 0) >= _minval1
              AND (_maxval1 IS NULL OR COALESCE(pa.considerationamount, 0) <= _maxval1)
        ),
        success_ref AS
        (
            SELECT DISTINCT b.deptreferencecode
            FROM kaveri.ams_reg_epaymentbankackdetails b
            WHERE b.paymentstatuscode IN ('10700066', '10700072')
        ),
        success_epay AS
        (
            SELECT
                e.applicationnumber,
                e.feerulecode,
                COALESCE(e.totalamount, 0)::numeric AS totalamount
            FROM kaveri.ams_reg_epaymenttransdetails e
            JOIN success_ref sr
                ON sr.deptreferencecode = e.deptreferencecode
            WHERE e.isdelete = false
              AND e.applicationnumber IN (SELECT bd.applicationnumber FROM base_docs bd)
        ),
        amt AS
        (
            SELECT
                se.applicationnumber,

                COALESCE(SUM(
                    CASE
                        WHEN se.feerulecode IN (35,36,64,89,91,92,101,107,110,138,59,100)
                        THEN se.totalamount ELSE 0
                    END
                ), 0)::numeric AS stampduty_amt,

                COALESCE(SUM(
                    CASE
                        WHEN se.feerulecode IN (
                            1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                            57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                        )
                        THEN se.totalamount ELSE 0
                    END
                ), 0)::numeric AS registrationfees_amt,

                COALESCE(SUM(
                    CASE
                        WHEN se.feerulecode = 2
                        THEN se.totalamount ELSE 0
                    END
                ), 0)::numeric AS scanningfees_amt,

                COALESCE(SUM(
                    CASE
                        WHEN se.feerulecode NOT IN (
                            35,36,64,89,91,92,101,107,110,138,59,100,
                            1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                            57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109,
                            2
                        )
                        THEN se.totalamount ELSE 0
                    END
                ), 0)::numeric AS otherfees_amt

            FROM success_epay se
            GROUP BY se.applicationnumber
        )
        SELECT
            bd.districtnamee,
            bd.sronamee,
            bd.articlename,
            to_char(bd.registrationdatetime, 'YYYY')::text AS finyear,
            trim(to_char(bd.registrationdatetime, 'Month'))::text AS monthname,
            1::bigint AS documentsregistered,
            bd.finalregistrationnumber,
            COALESCE(a.stampduty_amt, 0)::numeric AS stampduty,
            COALESCE(a.registrationfees_amt, 0)::numeric AS registrationfees,
            COALESCE(a.scanningfees_amt, 0)::numeric AS scanningfees,
            COALESCE(a.otherfees_amt, 0)::numeric AS otherfees,
            (
                COALESCE(a.stampduty_amt, 0)
                + COALESCE(a.registrationfees_amt, 0)
                + COALESCE(a.scanningfees_amt, 0)
                + COALESCE(a.otherfees_amt, 0)
            )::numeric AS total,
            COALESCE(bd.considerationamount, 0)::numeric AS considerationamount,
            COUNT(*) OVER()::bigint AS totalcount
        FROM base_docs bd
        LEFT JOIN amt a
            ON a.applicationnumber = bd.applicationnumber
        WHERE CASE
                WHEN _choice = 2 THEN COALESCE(a.stampduty_amt, 0) > 0
                WHEN _choice = 3 THEN COALESCE(a.registrationfees_amt, 0) > 0
                WHEN _choice = 4 THEN COALESCE(a.scanningfees_amt, 0) > 0
                WHEN _choice = 5 THEN COALESCE(a.otherfees_amt, 0) > 0
                ELSE true
              END
        ORDER BY bd.districtnamee, bd.sronamee, bd.finalregistrationnumber;

    END IF;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_high_val_props_20260413(_districtcode integer, _srocode integer, _regarticlecode bigint, _from_date timestamp without time zone, _to_date timestamp without time zone, _minval1 numeric, _maxval1 numeric, _choice integer, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer) OWNER TO manjunathswamy;

--
-- Name: fn_mis_high_val_props_23012024(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_high_val_props_23012024(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _choice integer DEFAULT NULL::integer, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(sronamee character varying, districtnamee character varying, finyear text, monthname text, documentsregistered bigint, registrationfees numeric, stampduty numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if(_districtcode = 0)then

	if _choice = 3 then -- registrationfee
	return query
	
	with cte as (select  sm.sronamee ,d.districtnamee,
    to_char(dm.registrationdatetime, 'yyyy') as finyear,
	to_char(dm.registrationdatetime, 'month') as monthname,
	count(distinct dm.documentid) as documentsregistered,
	sum(case when fr.feerulecode=1   then fr.amountpaid else 0 end) as RegistrationFees,
	sum(case when fr.feerulecode in (36,58,59)  then fr.amountpaid else 0 end)as StampDuty,
	(sum(case when fr.feerulecode=1  then fr.amountpaid else 0 end) +
	sum(case when fr.feerulecode in (36,58,59)  then fr.amountpaid else 0 end)) as Total
    from kaveri.documentmaster dm
	inner join kaveri.feesrequired fr ON dm.applicationnumber = fr.applicationnumber and dm.srocode = fr.srocode
	inner join kaveri.sromaster sm on fr.srocode = sm.srocode
	join kaveri.districtmaster d on sm.districtcode = d.districtcode
	join 
    (select sm.srocode,applicationnumber,sum(amountpaid) as amountpaid
     from kaveri.feesrequired fr
     inner join kaveri.sromaster sm on fr.srocode = sm.srocode
     where    
     --sm.srocode=_srocode and
     feerulecode in (1)
     group by applicationnumber,sm.srocode 
    having sum(amountpaid) >= _minval and sum(amountpaid) <= _maxval
     )vw1 on fr.applicationnumber  = vw1.applicationnumber and fr.srocode = vw1.srocode
	 where dm.isregistrationcompleted = true
	 --and d.districtcode = _districtcode
	 --and dm.srocode = _srocode
	 and dm.registrationdatetime ::date>= _from_date
	 and dm.registrationdatetime ::date<= _to_date
	group by finyear, monthname,sm.sronamee ,d.districtnamee),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
	

elseif _choice=2 then  -- stamp duty
  	return query
	
	with cte as (select  sm.sronamee ,d.districtnamee,
    to_char(dm.registrationdatetime, 'yyyy') as finyear,
