--
-- Name: fn_mis_high_val_props_bck_20260122(integer, integer, timestamp without time zone, timestamp without time zone, numeric, numeric, integer, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_high_val_props_bck_20260122(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _minval1 numeric DEFAULT NULL::numeric, _maxval1 numeric DEFAULT NULL::numeric, _choice integer DEFAULT NULL::integer, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtnamee character varying, sronamee character varying, finyear text, monthname text, documentsregistered bigint, stampduty numeric, registrationfees numeric, scanningfees numeric, otherfees numeric, total numeric, considerationamount numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);


if (pagenumber=1) then

		return query

		with cte as (
		
			with b as (
				
					select  distinct   
					d.districtnamee,
					sm.sronamee ,
					dm.registrationdatetime ,
					dm.applicationnumber,
					sum( p.sroconsideration) as totalconsideration
					from kaveri.documentmaster dm
					join kaveri.applicantapplicationdetails a on dm.applicationnumber=a.applicationnumber
					left join kaveri.propertymaster p on dm.applicationnumber=p.applicationnumber 
					join kaveri.sromaster sm on dm.srocode = sm.srocode
					join kaveri.districtmaster d on sm.districtcode = d.districtcode
					where  
					(case  when _districtcode<>0 then d.districtcode=_districtcode  ELSE  true end)
					and (case  when _srocode<> 0 then sm.srocode=_srocode  ELSE  true end)
					and dm.isregistrationcompleted = true
					--and a.currentstatus = 'CD120'
					and (dm.registrationdatetime between _from_date  and  _to_date +INTERVAL '1 day')
					
					and 	(p.sroconsideration between _minval1 and _maxval1) 
 
 				group by d.districtnamee,sm.sronamee,dm.applicationnumber,dm.registrationdatetime                           

               ),
		
				
				a as (
				
					select  distinct   
					dm.applicationnumber 
					from kaveri.documentmaster dm
					left  join kaveri.feesrequired fr ON dm.applicationnumber = fr.applicationnumber
					join  b on dm.applicationnumber=b.applicationnumber
					where  
					

 					(case

		                    when _choice=1 then true   --Total
		                                    
		                    when _choice=2 then  fr.feerulecode in (36,58,59,104,89,88)  --stamp duty
		                    
		                    when _choice=3 then  fr.feerulecode in  (1)  -- registrationfee
		                    
		                    when _choice=4 then  fr.feerulecode in  (2)  -- Scanning Fees
		                    
		                    when _choice=5 then  fr.feerulecode not in (1,2,36,58,59,104,89,88)   -- Other fees
		                               	                   
		
		                    else     true --amounttype null

                                                

  					 end)
 
 				group by dm.applicationnumber
				having 
				(case
					when _choice in (1,2,3,4,5) then sum(fr.amountpaid) >= _minval  
					and sum(fr.amountpaid) <= _maxval
                                        
                    ELSE          true                                               

                end )),
                
                c as (select     b.districtnamee,
			b.sronamee ,to_char(b.registrationdatetime, 'yyyy') as finyear,
			to_char(b.registrationdatetime, 'Month') as monthname,
			sum(totalconsideration)as consideration from b
			group by b.districtnamee,
			b.sronamee,finyear,monthname )
				
		select  distinct   temp.*,c.consideration  from 

				((select     
			b.districtnamee,
			b.sronamee ,
			to_char(b.registrationdatetime, 'yyyy') as finyear,
			to_char(b.registrationdatetime, 'Month') as monthname,
			count(distinct a.applicationnumber) as documentsregistered,
			sum(case when rr.feerulecode in (36,58,59,104,89,88)  then rr.amountpaid else 0 end)as StampDuty,
			sum(case when rr.feerulecode in (1)   then rr.amountpaid else 0 end) as RegistrationFees,
			sum(case when rr.feerulecode in (2)   then rr.amountpaid else 0 end) as scanningfees,
			sum(case when rr.feerulecode not in (1,2,36,58,59,104,89,88)  
			then rr.amountpaid else 0 end) as otherfees ,
			sum( rr.amountpaid ) as Total
		from 
		b
		join a on b.applicationnumber=a.applicationnumber
		left join kaveri.feesrequired rr   on a.applicationnumber=rr.applicationnumber 
		group by finyear, monthname,b.sronamee ,b.districtnamee
		)temp
		join c on  temp.districtnamee=c.districtnamee and temp.sronamee=c.sronamee 
		and temp.finyear=c.finyear and temp.monthname=c.monthname )),
		
		cte_count as (select    count(*) as total_rows from cte)
		select    * from cte
		join (select  distinct   total_rows from cte_count) total_row on true
		order by cte.districtnamee asc ,cte.sronamee asc
		limit pagesize offset PageOffset;
		
		
		
		
	
		
	elsif (pagenumber>1) then 
	return query
	
			with cte as (
		
			with b as (
				
					select  distinct   
					d.districtnamee,
					sm.sronamee ,
					dm.registrationdatetime ,
					dm.applicationnumber,
					sum( p.sroconsideration) as totalconsideration
					from kaveri.documentmaster dm
					join kaveri.applicantapplicationdetails a on dm.applicationnumber=a.applicationnumber
					left join kaveri.propertymaster p on dm.applicationnumber=p.applicationnumber 
					join kaveri.sromaster sm on dm.srocode = sm.srocode
					join kaveri.districtmaster d on sm.districtcode = d.districtcode
					where  
					(case  when _districtcode<>0 then d.districtcode=_districtcode  ELSE  true end)
					and (case  when _srocode<> 0 then sm.srocode=_srocode  ELSE  true end)
					and dm.isregistrationcompleted = true
					--and a.currentstatus = 'CD120'
					and (dm.registrationdatetime between _from_date  and  _to_date +INTERVAL '1 day')
					
					and 	(p.sroconsideration between _minval1 and _maxval1) 
 
 				group by d.districtnamee,sm.sronamee,dm.applicationnumber,dm.registrationdatetime                           

               ),
		
				
				a as (
				
					select  distinct   
					dm.applicationnumber 
					from kaveri.documentmaster dm
					left  join kaveri.feesrequired fr ON dm.applicationnumber = fr.applicationnumber
					join  b on dm.applicationnumber=b.applicationnumber
					where  
					

 					(case

		                    when _choice=1 then true   --Total
		                                    
		                    when _choice=2 then  fr.feerulecode in (36,58,59,104,89,88)  --stamp duty
		                    
		                    when _choice=3 then  fr.feerulecode in  (1)  -- registrationfee
		                    
		                    when _choice=4 then  fr.feerulecode in  (2)  -- Scanning Fees
		                    
		                    when _choice=5 then  fr.feerulecode not in (1,2,36,58,59,104,89,88)   -- Other fees
		                               	                   
		
		                    else     true --amounttype null

                                                

  					 end)
 
 				group by dm.applicationnumber
				having 
				(case
					when _choice in (1,2,3,4,5) then sum(fr.amountpaid) >= _minval  
					and sum(fr.amountpaid) <= _maxval
                                        
                    ELSE          true                                               

                end )),
                
                c as (select     b.districtnamee,
			b.sronamee ,to_char(b.registrationdatetime, 'yyyy') as finyear,
			to_char(b.registrationdatetime, 'Month') as monthname,
			sum(totalconsideration)as consideration from b
			group by b.districtnamee,
			b.sronamee,finyear,monthname )
				
		select  distinct   temp.*,c.consideration  from 

				((select     
			b.districtnamee,
			b.sronamee ,
			to_char(b.registrationdatetime, 'yyyy') as finyear,
			to_char(b.registrationdatetime, 'Month') as monthname,
			count(distinct a.applicationnumber) as documentsregistered,
			sum(case when rr.feerulecode in (36,58,59,104,89,88)  then rr.amountpaid else 0 end)as StampDuty,
			sum(case when rr.feerulecode in (1)   then rr.amountpaid else 0 end) as RegistrationFees,
			sum(case when rr.feerulecode in (2)   then rr.amountpaid else 0 end) as scanningfees,
			sum(case when rr.feerulecode not in (1,2,36,58,59,104,89,88)  
			then rr.amountpaid else 0 end) as otherfees ,
			sum( rr.amountpaid ) as Total
		from 
		b
		join a on b.applicationnumber=a.applicationnumber
		left join kaveri.feesrequired rr   on a.applicationnumber=rr.applicationnumber 
		group by finyear, monthname,b.sronamee ,b.districtnamee
		)temp
		join c on  temp.districtnamee=c.districtnamee and temp.sronamee=c.sronamee 
		and temp.finyear=c.finyear and temp.monthname=c.monthname ))
		
		
		select  distinct   *,null::bigint as total  from cte
		order by cte.districtnamee asc ,cte.sronamee asc
		limit pagesize offset PageOffset ;
	
	
	
	
	elsif (pagenumber=-1 or  pagesize=-1) then 
	
	return query
	
		with cte as (
		
			with b as (
				
					select  distinct   
					d.districtnamee,
					sm.sronamee ,
					dm.registrationdatetime ,
					dm.applicationnumber,
					sum( p.sroconsideration) as totalconsideration
					from kaveri.documentmaster dm
					join kaveri.applicantapplicationdetails a on dm.applicationnumber=a.applicationnumber
					left join kaveri.propertymaster p on dm.applicationnumber=p.applicationnumber 
					join kaveri.sromaster sm on dm.srocode = sm.srocode
					join kaveri.districtmaster d on sm.districtcode = d.districtcode
					where  
					(case  when _districtcode<>0 then d.districtcode=_districtcode  ELSE  true end)
					and (case  when _srocode<> 0 then sm.srocode=_srocode  ELSE  true end)
					and dm.isregistrationcompleted = true
					--and a.currentstatus = 'CD120'
					and (dm.registrationdatetime between _from_date  and  _to_date +INTERVAL '1 day')
					
					and 	(p.sroconsideration between _minval1 and _maxval1) 
 
 				group by d.districtnamee,sm.sronamee,dm.applicationnumber,dm.registrationdatetime                           

               ),
		
				
				a as (
				
					select  distinct   
					dm.applicationnumber 
					from kaveri.documentmaster dm
					left  join kaveri.feesrequired fr ON dm.applicationnumber = fr.applicationnumber
					join  b on dm.applicationnumber=b.applicationnumber
					where  
					

 					(case

		                    when _choice=1 then true   --Total
		                                    
		                    when _choice=2 then  fr.feerulecode in (36,58,59,104,89,88)  --stamp duty
		                    
		                    when _choice=3 then  fr.feerulecode in  (1)  -- registrationfee
		                    
		                    when _choice=4 then  fr.feerulecode in  (2)  -- Scanning Fees
		                    
		                    when _choice=5 then  fr.feerulecode not in (1,2,36,58,59,104,89,88)   -- Other fees
		                               	                   
		
		                    else     true --amounttype null

                                                

  					 end)
 
 				group by dm.applicationnumber
				having 
				(case
					when _choice in (1,2,3,4,5) then sum(fr.amountpaid) >= _minval  
					and sum(fr.amountpaid) <= _maxval
                                        
                    ELSE          true                                               

                end )),
                
                c as (select     b.districtnamee,
			b.sronamee ,to_char(b.registrationdatetime, 'yyyy') as finyear,
			to_char(b.registrationdatetime, 'Month') as monthname,
			sum(totalconsideration)as consideration from b
			group by b.districtnamee,
			b.sronamee,finyear,monthname )
				
		select  distinct   temp.*,c.consideration  from 

				((select     
			b.districtnamee,
			b.sronamee ,
			to_char(b.registrationdatetime, 'yyyy') as finyear,
			to_char(b.registrationdatetime, 'Month') as monthname,
			count(distinct a.applicationnumber) as documentsregistered,
			sum(case when rr.feerulecode in (36,58,59,104,89,88)  then rr.amountpaid else 0 end)as StampDuty,
			sum(case when rr.feerulecode in (1)   then rr.amountpaid else 0 end) as RegistrationFees,
			sum(case when rr.feerulecode in (2)   then rr.amountpaid else 0 end) as scanningfees,
			sum(case when rr.feerulecode not in (1,2,36,58,59,104,89,88)  
			then rr.amountpaid else 0 end) as otherfees ,
			sum( rr.amountpaid ) as Total
