--
-- Name: fn_mis_index2_form17_report_pid(integer, integer, integer, bigint, character varying, character varying, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_index2_form17_report_pid(_districtcode integer, _talukcode integer, _hoblicode integer, _villagecode bigint, _pid character varying, _documentnumber character varying DEFAULT NULL::character varying, _from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _to_date timestamp without time zone DEFAULT NULL::timestamp without time zone, page_number integer DEFAULT NULL::integer, per_page integer DEFAULT NULL::integer) RETURNS TABLE(districtcode integer, district character varying, talukcode integer, talukname character varying, hoblicode integer, hoblinamee character varying, villagecode bigint, nameofvillage character varying, propertyid bigint, finalregistrationnumber character varying, registrationdatetime timestamp without time zone, natureofdeedandconsideration text, surveyno_subdivisionno_houseno text, area text, assessment character varying, claimant text, executant text, officeoforiginalregistration character varying, srocode integer, executiondate text, regndate text, serialno_volume_and_page text, copy_of_document text, remarks character varying, pid character varying, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

declare 
	PageOffset INTEGER := 0;

	begin
		
		PageOffset := (per_page*page_number) - per_page;
        
	if (page_number<>-1 and per_page<>-1) then 
--        raise notice 'Function execution start for all districts_form17_statutory';
    
        return query
  with cte as (
       select
				distinct 
					c.districtcode,
					c.districtnamee as district,
					tal.talukcode,
					tal.taluknamee as talukname,
					hob.hoblicode,
					hob.hoblinamee,
					d.villagecode,
					d.villagenamee as nameofvillage,
					a.propertyid,
					i.finalregistrationnumber,
					i.registrationdatetime,
					string_agg(distinct (coalesce(r.articlenamee::text, null::text) || ' - '::text) || ' ' || to_char(coalesce(a.sroconsideration, 0),
					'₹9,99,99,999D99'), ', ')::text as natureofdeedandconsideration,
					string_agg(distinct replace(f.currentnumber, '*', '/')::text, ', ')::text as surveyno_subdivisionno_houseno,
					case
						when g.unitid = 1 then div(ceil(a.totalarea * 40),
						40)::text || ' ' || 'Acre' || ' '
										   || mod(ceil(a.totalarea * 40),
						40)::text || ' ' || 'Gunta'
						when g.unitid = 2 then div(a.totalarea,
						40)::text || ' ' || 'Acre' || ' '
										   || mod(a.totalarea,
						40)::text || ' ' || 'Gunta'
						else
				 	string_agg(distinct (round( a.totalarea, 2 ) || ' '::text) || g.descriptionenglish::text, ', ')::text
					end as area,
					null::character varying as assessment,
					string_agg( distinct case
                            when pi.partytypeid = 1 then
                      coalesce(coalesce(pi.firstname,
                            ' ')|| ' ' || coalesce(pi.middlename,
                            ' ')|| ' ' || coalesce(pi.lastname,
                            ' '),
                            null::text)
                            else null
                        end ,
                        ', ')::text as claimant,
                        
                        string_agg( distinct case
                            when pi.partytypeid = 2 then
                      coalesce(coalesce(pi.firstname,
                            ' ')|| ' ' || coalesce(pi.middlename,
                            ' ')|| ' ' || coalesce(pi.lastname,
                            ' '),
                            null::text)
                            else null
                        end ,
                        ', ')::text as executant,
						b.sronamee as officeoforiginalregistration,
						b.srocode,
						to_char(i.executiondatetime,
						'DD-MM-YYYY') as executiondate,
						to_char(i.registrationdatetime,
						'DD-MM-YYYY') as regndate,
						TO_CHAR(i.documentnumber,
						'fm00000') as serialno_volume_and_page,
						i.uploaddocdeedpath as copy_of_document
					  ,
						(coalesce(ld.liabilitynote,
						' ')|| ' ' || coalesce(referencetext,
						' ') ||
					  ' ' /*||coalesce(cor.footnotefordesc,' ')*/
						)::character varying as remarks,
						f.currentnumber as pid
from
	kaveri.documentmaster i
join kaveri.propertymaster a on
	i.applicationnumber = a.applicationnumber
	and i.isregistrationcompleted = true
left join kaveri.liabilityonpropertydetails lpm on a.propertyid = lpm.propertyid   
left join kaveri.liabilitydetails ld on lpm.liabilityid = ld.liabilityid
left join kaveri.referencemaster ref on i.documentid = ref.documentid
join kaveri.propertynumberdetails f on a.propertyid = f.propertyid
join kaveri.partyinfo pi on i.applicationnumber = pi.applicationnumber
join kaveri.registrationarticles r on  i.regarticlecode = r.regarticlecode
left join kaveri.measunitmaster g on a.unitid = g.unitid

join kaveri.villagemaster d on
     a.villagecode = d.villagecode
     --and d.srocode = i.srocode
join kaveri.hoblimaster hob on
     d.hoblicode=hob.hoblicode
join kaveri.talukmaster tal on d.talukcode = tal.talukcode
join kaveri.sromaster b on
	d.srocode = b.srocode
     --tal.districtcode = c.districtcode
     --and
                            
join kaveri.districtmaster c on
    tal.districtcode = c.districtcode

where

	 (CASE   
                                WHEN _documentnumber is not NULL THEN i.finalregistrationnumber=_documentnumber
                                WHEN _from_date is not NULL and _to_date is not NULL THEN
                                i.registrationdatetime between _from_date and _to_date
                                ELSE 
                                    TRUE
	END)
	and  i.finalregistrationnumber is not null
	and (
                                            CASE
                                                WHEN _districtcode <> 0 THEN  c.districtcode = _districtcode
                                                ELSE TRUE
                                            END
                                        ) 
                                        and (
                                            CASE
                                                WHEN _talukcode <> 0 THEN  tal.talukcode = _talukcode
                                                ELSE TRUE
                                            end
                                            ) 
                                        and (
                                            CASE
                                                WHEN _hoblicode <> 0 THEN  hob.hoblicode = _hoblicode
                                                ELSE TRUE
                                            END
                                        ) 
                                        and (
                                            CASE
                                                WHEN _villagecode <> 0 THEN  a.villagecode = _villagecode
                                                ELSE TRUE
                                            END
                                        ) and f.currentnumber = _pid 
	
group by
	i.uploaddocdeedpath,
	g.unitid,
	a.totalarea,
	c.districtnamee,
	b.sronamee,
	d.villagenamee,
	tal.taluknamee,
	officeoforiginalregistration,
	executiondate,
	regndate,
	remarks,
	f.currentnumber,
	lpm.documentid,
	ld.liabilitynote,
	i.finalregistrationnumber,
	tal.talukcode,
	hob.hoblicode,
	a.villagecode,
	a.noofscanpages,
	i.applicationnumber,
	i.documentnumber, c.districtcode,b.srocode,tal.talukcode,hob.hoblicode,hob.hoblinamee,d.villagecode,a.propertyid,i.registrationdatetime
	
	
	
	
--	limit per_page offset PageOffset;
	              
--        raise notice 'Function execution end for all districts_form17_statutory'
       ),cte_count as (select count(*) as total_rows from cte)

            select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0 					
			limit per_page offset PageOffset;
			
elsif (page_number = -1 or per_page = -1) then 
       
return query
		with cte as (
  				select
				distinct 
					c.districtcode,
					c.districtnamee as district,
					tal.talukcode,
					tal.taluknamee as talukname,
					hob.hoblicode,
					hob.hoblinamee,
					d.villagecode,
					d.villagenamee as nameofvillage,
					a.propertyid,
					i.finalregistrationnumber,
					i.registrationdatetime,
					string_agg(distinct (coalesce(r.articlenamee::text, null::text) || ' - '::text) || ' ' || to_char(coalesce(a.sroconsideration, 0),
					'₹9,99,99,999D99'), ', ')::text as natureofdeedandconsideration,
					string_agg(distinct replace(f.currentnumber, '*', '/')::text, ', ')::text as surveyno_subdivisionno_houseno,
					case
						when g.unitid = 1 then div(ceil(a.totalarea * 40),
						40)::text || ' ' || 'Acre' || ' '
										   || mod(ceil(a.totalarea * 40),
						40)::text || ' ' || 'Gunta'
						when g.unitid = 2 then div(a.totalarea,
						40)::text || ' ' || 'Acre' || ' '
										   || mod(a.totalarea,
						40)::text || ' ' || 'Gunta'
						else
				 	string_agg(distinct (round( a.totalarea, 2 ) || ' '::text) || g.descriptionenglish::text, ', ')::text
					end as area,
					null::character varying as assessment,
					string_agg( distinct case
                            when pi.partytypeid = 1 then
                      coalesce(coalesce(pi.firstname,
                            ' ')|| ' ' || coalesce(pi.middlename,
                            ' ')|| ' ' || coalesce(pi.lastname,
                            ' '),
                            null::text)
                            else null
                        end ,
                        ', ')::text as claimant,
                        
                        string_agg( distinct case
                            when pi.partytypeid = 2 then
                      coalesce(coalesce(pi.firstname,
                            ' ')|| ' ' || coalesce(pi.middlename,
                            ' ')|| ' ' || coalesce(pi.lastname,
                            ' '),
                            null::text)
                            else null
                        end ,
                        ', ')::text as executant,
						b.sronamee as officeoforiginalregistration,
						b.srocode,
						to_char(i.executiondatetime,
						'DD-MM-YYYY') as executiondate,
						to_char(i.registrationdatetime,
						'DD-MM-YYYY') as regndate,
						TO_CHAR(i.documentnumber,
						'fm00000') as serialno_volume_and_page,
						i.uploaddocdeedpath as copy_of_document
					  ,
						(coalesce(ld.liabilitynote,
						' ')|| ' ' || coalesce(referencetext,
						' ') ||
					  ' ' /*||coalesce(cor.footnotefordesc,' ')*/
						)::character varying as remarks,
						f.currentnumber as pid
from
	kaveri.documentmaster i
join kaveri.propertymaster a on
	i.applicationnumber = a.applicationnumber
	and i.isregistrationcompleted = true
left join kaveri.liabilityonpropertydetails lpm on a.propertyid = lpm.propertyid   
left join kaveri.liabilitydetails ld on lpm.liabilityid = ld.liabilityid
left join kaveri.referencemaster ref on i.documentid = ref.documentid
join kaveri.propertynumberdetails f on a.propertyid = f.propertyid
join kaveri.partyinfo pi on i.applicationnumber = pi.applicationnumber
join kaveri.registrationarticles r on  i.regarticlecode = r.regarticlecode
left join kaveri.measunitmaster g on a.unitid = g.unitid

join kaveri.villagemaster d on
     a.villagecode = d.villagecode
     --and d.srocode = i.srocode
join kaveri.hoblimaster hob on
     d.hoblicode=hob.hoblicode
join kaveri.talukmaster tal on d.talukcode = tal.talukcode
join kaveri.sromaster b on
	d.srocode = b.srocode
     --tal.districtcode = c.districtcode
     --and
                            
join kaveri.districtmaster c on
    tal.districtcode = c.districtcode

where

	 (CASE   
                                WHEN _documentnumber is not NULL THEN i.finalregistrationnumber=_documentnumber
                                WHEN _from_date is not NULL and _to_date is not NULL THEN
                                i.registrationdatetime between _from_date and _to_date
                                ELSE 
                                    TRUE
	END)
	and  i.finalregistrationnumber is not null
	and (
                                            CASE
                                                WHEN _districtcode <> 0 THEN  c.districtcode = _districtcode
                                                ELSE TRUE
                                            END
                                        ) 
                                        and (
                                            CASE
                                                WHEN _talukcode <> 0 THEN  tal.talukcode = _talukcode
                                                ELSE TRUE
                                            end
                                            ) 
                                        and (
                                            CASE
                                                WHEN _hoblicode <> 0 THEN  hob.hoblicode = _hoblicode
                                                ELSE TRUE
                                            END
                                        ) 
                                        and (
                                            CASE
                                                WHEN _villagecode <> 0 THEN  a.villagecode = _villagecode
                                                ELSE TRUE
                                            END
                                        ) and f.currentnumber = _pid 
	
group by
	i.uploaddocdeedpath,
	g.unitid,
	a.totalarea,
	c.districtnamee,
	b.sronamee,
	d.villagenamee,
	tal.taluknamee,
	officeoforiginalregistration,
	executiondate,
	regndate,
	remarks,
	f.currentnumber,
	lpm.documentid,
	ld.liabilitynote,
	i.finalregistrationnumber,
	tal.talukcode,
	hob.hoblicode,
	a.villagecode,
	a.noofscanpages,
	i.applicationnumber,
	i.documentnumber, c.districtcode,b.srocode,tal.talukcode,hob.hoblicode,hob.hoblinamee,d.villagecode,a.propertyid,i.registrationdatetime
	
	
	
	
--	limit per_page offset PageOffset;
	              
       
       ),cte_count as (select count(*) as total_rows from cte)

            select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0;
--   raise notice 'Function execution end for all districts_form17_statutory' ;
end if;		

	END;
$$;


ALTER FUNCTION kaverimis.fn_mis_index2_form17_report_pid(_districtcode integer, _talukcode integer, _hoblicode integer, _villagecode bigint, _pid character varying, _documentnumber character varying, _from_date timestamp without time zone, _to_date timestamp without time zone, page_number integer, per_page integer) OWNER TO postgres;

--
-- Name: fn_mis_index_2(bigint, bigint, date, date, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_index_2(_srocode bigint, _regarticlecode bigint, _fromdate date, _todate date, pagenumber integer, pagesize integer) RETURNS TABLE(finalregistrationnumber character varying, article character varying, registrationdatetime timestamp without time zone, totalarea numeric, unit character varying, propertydetails character varying, schedule character varying, claimants text, executants text, villagename character varying, marketvalue numeric, consideration numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
return query 
select 
	dm.finalregistrationnumber,
	ra.articlenamee as article,
	dm.registrationdatetime,
	pm.totalarea,
	mum.descriptionenglish as unit,
	--concat_ws(' ', 'Village Name: ', vm.villagenamee, '(Landmark:', pm.landmark,'), Index-II Village: ', vm.villagenamee, ', Hobli Name: ', hm.hoblinamee,', ', ps.description), 
	ps.description as propertydetails,
	null::varchar as Schedule,
	prt_cl.parties as Claimants,
	prt_ex.parties as executants,
	vm.villagenamee as villagename,
	pm.marketvalue,
	pm.consideration
from kaveri.documentmaster dm
join kaveri.sromaster sr on dm.srocode=sr.srocode
join kaveri.registrationarticles ra on dm.regarticlecode=ra.regarticlecode
join kaveri.propertymaster pm on dm.documentid=pm.documentid
join kaveri.measunitmaster mum on pm.unitid=mum.unitid
join kaveri.villagemaster vm on pm.villagecode=vm.villagecode
join kaveri.hoblimaster hm on vm.hoblicode=hm.hoblicode
join kaveri.propertyschedules ps on pm.propertyid=ps.propertyid
join ( select vw.applicationnumber,
	  		string_agg((vw.name || ' '::text) || vw.address, ', '::text) as parties
			from kaverimis.vw_mis_partyinfo vw 
			where vw.partytypeid=1 and vw.registrationdatetime>=_fromDate and vw.registrationdatetime<=_toDate
			group by vw.applicationnumber) prt_cl ON prt_cl.applicationnumber=dm.applicationnumber
join ( select vw.applicationnumber,
			string_agg((vw.name || ' '::text) || vw.address, ', '::text) as parties
			from kaverimis.vw_mis_partyinfo vw 
			where vw.partytypeid=2 and vw.registrationdatetime>=_fromDate and vw.registrationdatetime<=_toDate
			group by vw.applicationnumber) prt_ex ON prt_ex.applicationnumber=dm.applicationnumber
where dm.srocode=_srocode and dm.regarticlecode=_regarticlecode
and dm.registrationdatetime>=_fromDate and dm.registrationdatetime<=_toDate
OFFSET PageOffset
FETCH NEXT pagesize ROWS ONLY;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_index_2(_srocode bigint, _regarticlecode bigint, _fromdate date, _todate date, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_index_of_marriage(integer, integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_index_of_marriage(_districtcode integer, _srocode integer, _marriagetypeid integer, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtcode integer, srocode integer, marriagetypeid integer, marriagetype character varying, dateofregistration timestamp without time zone, districtname character varying, sronamee character varying, husband_name text, husbandaddress text, wifename text, wifeaddress text, placeofmarriage text, dateofmarriage text, finalregistrationnumber character varying, signedformpath character varying, totalcount bigint)
    LANGUAGE plpgsql
    AS $$



DECLARE

PageOffset INTEGER := 0;
v_count integer;

 
BEGIN 
	PageOffset := ((pagenumber - 1) * pagesize);

		

		if _districtcode=0 THEN
		
			return  query 
			with cte as (select 
			d.districtcode,
			sm.srocode,
			mm.marriagetypeid,
			mm.marriagetype,
			m.dateofregistration,
			d.districtnamee,
			sm.sronamee, 
			groom.firstname ||' '||groom.middlename||' '||groom.lastname as husband_name,
			groom.perhousebuildname || ','||groom.perstreetname||','||vgroom.villagenamee||','||hgroom.hoblinamee
			||','||tgroom.taluknamee||','||dgroom.districtnamee||','||sgroom.statenamee as husband_address,
			bride.firstname ||' '||bride.middlename||' '||bride.lastname as wife_name,
			bride.perhousebuildname || ','||bride.perstreetname||','||vbride.villagenamee||','||hbride.hoblinamee
			||','||tbride.taluknamee||','||dbride.districtnamee||','||sbride.statenamee as wife_address,
			m.housebuildingname || ',' || m.streetaddr||','||vpm.villagenamee||','||hpm.hoblinamee
			||','||sm.sronamee||','||d.districtnamee||','||spm.statenamee as  Place_of_marriage,
			to_char(m.dateofmarriage,'dd-mm-yyyy') as date_of_marriage,
			m.finalregistrationnumber,
			m.signedformpath


			from kaveri.marriageregistration m  
			join  kaveri.persondetails bride on m.registrationid=bride.registrationid  and m.bridepersonid=bride.personid 
			join  kaveri.persondetails groom on m.registrationid=groom.registrationid  and m.bridegroompersonid =groom.personid
			join  kaveri.districtmaster d on d.districtcode=m.districtcode 
			join  kaveri.sromaster sm on m.regsrocode=sm.srocode 
			join  kaveri.villagemaster vpm on m.cityvillagecode=vpm.villagecode 
			join kaveri.hoblimaster hpm on m.hoblicode=hpm.hoblicode 
			join kaveri.statemaster spm on m.statecode=spm.statecode
			join  kaveri.villagemaster vbride on bride.percityvillagecode=vbride.villagecode 
			join kaveri.hoblimaster hbride on bride.perhoblicode=hbride.hoblicode 
			join kaveri.talukmaster tbride on bride.pertalukacode=tbride.talukcode 
			join kaveri.districtmaster dbride on bride.perdistrictcode=dbride.districtcode 
			join kaveri.statemaster sbride on bride.perstatecode=sbride.statecode
			join  kaveri.villagemaster vgroom on groom.percityvillagecode=vgroom.villagecode 
			join kaveri.hoblimaster hgroom on groom.perhoblicode=hgroom.hoblicode 
			join kaveri.talukmaster tgroom on groom.pertalukacode=tgroom.talukcode 
			join kaveri.districtmaster dgroom on groom.perdistrictcode=dgroom.districtcode 
			join kaveri.statemaster sgroom on groom.perstatecode=sgroom.statecode
			join kaveri.mas_marriagetype mm on m.marriagetypeid=mm.marriagetypeid

			where 
			m.isregistraioncomplete=true  and 
			m.marriagetypeid=_marriagetypeid and 
			m.dateofregistration::date>=_fromdate  and m.dateofregistration::date<=_todate),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			join (select total_rows from cte_count) total_row on true OFFSET PageOffset
			FETCH NEXT pagesize ROWS ONLY;
			--and m.districtcode=_districtcode and  m.talukacode=_talukcode
			
			
		elsif _srocode =0 THEN
		
		
			return  query 
			with cte as (
			select 
			d.districtcode,
			sm.srocode,
			mm.marriagetypeid,
			mm.marriagetype,
			m.dateofregistration,
			d.districtnamee,
			sm.sronamee, 
			groom.firstname ||' '||groom.middlename||' '||groom.lastname as husband_name,
			groom.perhousebuildname || ','||groom.perstreetname||','||vgroom.villagenamee||','||hgroom.hoblinamee
			||','||tgroom.taluknamee||','||dgroom.districtnamee||','||sgroom.statenamee as husband_address,
			bride.firstname ||' '||bride.middlename||' '||bride.lastname as wife_name,
			bride.perhousebuildname || ','||bride.perstreetname||','||vbride.villagenamee||','||hbride.hoblinamee
			||','||tbride.taluknamee||','||dbride.districtnamee||','||sbride.statenamee as wife_address,
			m.housebuildingname || ',' || m.streetaddr||','||vpm.villagenamee||','||hpm.hoblinamee
			||','||sm.sronamee||','||d.districtnamee||','||spm.statenamee as  Place_of_marriage,
			to_char(m.dateofmarriage,'dd-mm-yyyy') as date_of_marriage,
			m.finalregistrationnumber,
			m.signedformpath


			from kaveri.marriageregistration m  
			join  kaveri.persondetails bride on m.registrationid=bride.registrationid  and m.bridepersonid=bride.personid 
			join  kaveri.persondetails groom on m.registrationid=groom.registrationid  and m.bridegroompersonid =groom.personid
			join  kaveri.districtmaster d on d.districtcode=m.districtcode 
			join  kaveri.sromaster sm on m.regsrocode=sm.srocode 
			join  kaveri.villagemaster vpm on m.cityvillagecode=vpm.villagecode 
			join kaveri.hoblimaster hpm on m.hoblicode=hpm.hoblicode 
			join kaveri.statemaster spm on m.statecode=spm.statecode
			join  kaveri.villagemaster vbride on bride.percityvillagecode=vbride.villagecode 
			join kaveri.hoblimaster hbride on bride.perhoblicode=hbride.hoblicode 
			join kaveri.talukmaster tbride on bride.pertalukacode=tbride.talukcode 
			join kaveri.districtmaster dbride on bride.perdistrictcode=dbride.districtcode 
			join kaveri.statemaster sbride on bride.perstatecode=sbride.statecode
			join  kaveri.villagemaster vgroom on groom.percityvillagecode=vgroom.villagecode 
			join kaveri.hoblimaster hgroom on groom.perhoblicode=hgroom.hoblicode 
			join kaveri.talukmaster tgroom on groom.pertalukacode=tgroom.talukcode 
			join kaveri.districtmaster dgroom on groom.perdistrictcode=dgroom.districtcode 
			join kaveri.statemaster sgroom on groom.perstatecode=sgroom.statecode
			join kaveri.mas_marriagetype mm on m.marriagetypeid=mm.marriagetypeid

			where 
			m.isregistraioncomplete=true  and
			m.marriagetypeid=_marriagetypeid and 
			m.dateofregistration::date>=_fromdate  and m.dateofregistration::date<=_todate
			and m.districtcode=_districtcode),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			join (select total_rows from cte_count) total_row on true OFFSET PageOffset
			FETCH NEXT pagesize ROWS ONLY;
			--and  m.talukacode=_talukcode;
			
		else
		
		return  query 
			with cte as (select 
			d.districtcode,
			sm.srocode,
			mm.marriagetypeid,
			mm.marriagetype,
			m.dateofregistration,
			d.districtnamee,
			sm.sronamee, 
			groom.firstname ||' '||groom.middlename||' '||groom.lastname as husband_name,
			groom.perhousebuildname || ','||groom.perstreetname||','||vgroom.villagenamee||','||hgroom.hoblinamee
			||','||tgroom.taluknamee||','||dgroom.districtnamee||','||sgroom.statenamee as husband_address,
			bride.firstname ||' '||bride.middlename||' '||bride.lastname as wife_name,
			bride.perhousebuildname || ','||bride.perstreetname||','||vbride.villagenamee||','||hbride.hoblinamee
			||','||tbride.taluknamee||','||dbride.districtnamee||','||sbride.statenamee as wife_address,
			m.housebuildingname || ',' || m.streetaddr||','||vpm.villagenamee||','||hpm.hoblinamee
			||','||sm.sronamee||','||d.districtnamee||','||spm.statenamee as  Place_of_marriage,
			to_char(m.dateofmarriage,'dd-mm-yyyy') as date_of_marriage,
			m.finalregistrationnumber,
			m.signedformpath


			from kaveri.marriageregistration m  
			join  kaveri.persondetails bride on m.registrationid=bride.registrationid  and m.bridepersonid=bride.personid 
			join  kaveri.persondetails groom on m.registrationid=groom.registrationid  and m.bridegroompersonid =groom.personid
			join  kaveri.districtmaster d on d.districtcode=m.districtcode 
			join  kaveri.sromaster sm on m.regsrocode=sm.srocode 
			join  kaveri.villagemaster vpm on m.cityvillagecode=vpm.villagecode 
			join kaveri.hoblimaster hpm on m.hoblicode=hpm.hoblicode 
			join kaveri.statemaster spm on m.statecode=spm.statecode
			join  kaveri.villagemaster vbride on bride.percityvillagecode=vbride.villagecode 
			join kaveri.hoblimaster hbride on bride.perhoblicode=hbride.hoblicode 
			join kaveri.talukmaster tbride on bride.pertalukacode=tbride.talukcode 
			join kaveri.districtmaster dbride on bride.perdistrictcode=dbride.districtcode 
			join kaveri.statemaster sbride on bride.perstatecode=sbride.statecode
			join  kaveri.villagemaster vgroom on groom.percityvillagecode=vgroom.villagecode 
			join kaveri.hoblimaster hgroom on groom.perhoblicode=hgroom.hoblicode 
			join kaveri.talukmaster tgroom on groom.pertalukacode=tgroom.talukcode 
			join kaveri.districtmaster dgroom on groom.perdistrictcode=dgroom.districtcode 
			join kaveri.statemaster sgroom on groom.perstatecode=sgroom.statecode
			join kaveri.mas_marriagetype mm on m.marriagetypeid=mm.marriagetypeid

			where 
			m.isregistraioncomplete=true  and
			m.marriagetypeid=_marriagetypeid and 
			m.dateofregistration::date>=_fromdate  and m.dateofregistration::date<=_todate and m.districtcode=_districtcode
			and sm.srocode=_srocode),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			join (select total_rows from cte_count) total_row on true OFFSET PageOffset
			FETCH NEXT pagesize ROWS ONLY;
			
	end if;			
				
						 
 

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_index_of_marriage(_districtcode integer, _srocode integer, _marriagetypeid integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_index_of_marriage_23012024(integer, integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_index_of_marriage_23012024(_districtcode integer, _srocode integer, _marriagetypeid integer, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtcode integer, srocode integer, marriagetypeid integer, marriagetype character varying, dateofregistration timestamp without time zone, districtname character varying, sronamee character varying, husband_name text, husbandaddress text, wifename text, wifeaddress text, placeofmarriage text, dateofmarriage text, finalregistrationnumber character varying, signedformpath character varying, totalcount bigint)
    LANGUAGE plpgsql
    AS $$




DECLARE

PageOffset INTEGER := 0;
v_count integer;

 
BEGIN 
    PageOffset := ((pagenumber - 1) * pagesize);

        

        if _districtcode=0 THEN
        
            return  query 
            with cte as (select 
            d.districtcode,
            sm.srocode,
            mm.marriagetypeid,
            mm.marriagetype,
            m.dateofregistration,
            d.districtnamee,
            sm.sronamee, 
            groom.firstname ||' '||groom.middlename||' '||groom.lastname as husband_name,
            groom.perhousebuildname || ','||groom.perstreetname||','||vgroom.villagenamee||','||hgroom.hoblinamee
            ||','||tgroom.taluknamee||','||dgroom.districtnamee||','||sgroom.statenamee as husband_address,
            bride.firstname ||' '||bride.middlename||' '||bride.lastname as wife_name,
            bride.perhousebuildname || ','||bride.perstreetname||','||vbride.villagenamee||','||hbride.hoblinamee
            ||','||tbride.taluknamee||','||dbride.districtnamee||','||sbride.statenamee as wife_address,
            m.housebuildingname || ',' || m.streetaddr||','||vpm.villagenamee||','||hpm.hoblinamee
            ||','||sm.sronamee||','||d.districtnamee||','||spm.statenamee as  Place_of_marriage,
            to_char(m.dateofmarriage,'dd-mm-yyyy') as date_of_marriage,
            m.finalregistrationnumber,
            m.signedformpath


            from kaveri.marriageregistration m  
            join  kaveri.persondetails bride on m.registrationid=bride.registrationid  and m.bridepersonid=bride.personid 
            join  kaveri.persondetails groom on m.registrationid=groom.registrationid  and m.bridegroompersonid =groom.personid
            join  kaveri.districtmaster d on d.districtcode=m.districtcode 
            join  kaveri.sromaster sm on m.regsrocode=sm.srocode 
            join  kaveri.villagemaster vpm on m.cityvillagecode=vpm.villagecode 
            join kaveri.hoblimaster hpm on m.hoblicode=hpm.hoblicode 
            join kaveri.statemaster spm on m.statecode=spm.statecode
            join  kaveri.villagemaster vbride on bride.percityvillagecode=vbride.villagecode 
            join kaveri.hoblimaster hbride on bride.perhoblicode=hbride.hoblicode 
            join kaveri.talukmaster tbride on bride.pertalukacode=tbride.talukcode 
            join kaveri.districtmaster dbride on bride.perdistrictcode=dbride.districtcode 
            join kaveri.statemaster sbride on bride.perstatecode=sbride.statecode
            join  kaveri.villagemaster vgroom on groom.percityvillagecode=vgroom.villagecode 
            join kaveri.hoblimaster hgroom on groom.perhoblicode=hgroom.hoblicode 
            join kaveri.talukmaster tgroom on groom.pertalukacode=tgroom.talukcode 
            join kaveri.districtmaster dgroom on groom.perdistrictcode=dgroom.districtcode 
            join kaveri.statemaster sgroom on groom.perstatecode=sgroom.statecode
            join kaveri.mas_marriagetype mm on m.marriagetypeid=mm.marriagetypeid

            where 
            m.isregistraioncomplete=true  and 
            m.marriagetypeid=_marriagetypeid and 
            m.dateofregistration between _fromdate and _todate),cte_count as (select count(*) as total_rows from cte)
            select * from cte
            join (select total_rows from cte_count) total_row on true OFFSET PageOffset
            FETCH NEXT pagesize ROWS ONLY;
            --and m.districtcode=_districtcode and  m.talukacode=_talukcode
            
            
        elsif _srocode =0 THEN
        
        
            return  query 
            with cte as (
            select 
            d.districtcode,
            sm.srocode,
            mm.marriagetypeid,
            mm.marriagetype,
            m.dateofregistration,
            d.districtnamee,
            sm.sronamee, 
            groom.firstname ||' '||groom.middlename||' '||groom.lastname as husband_name,
            groom.perhousebuildname || ','||groom.perstreetname||','||vgroom.villagenamee||','||hgroom.hoblinamee
            ||','||tgroom.taluknamee||','||dgroom.districtnamee||','||sgroom.statenamee as husband_address,
            bride.firstname ||' '||bride.middlename||' '||bride.lastname as wife_name,
            bride.perhousebuildname || ','||bride.perstreetname||','||vbride.villagenamee||','||hbride.hoblinamee
            ||','||tbride.taluknamee||','||dbride.districtnamee||','||sbride.statenamee as wife_address,
            m.housebuildingname || ',' || m.streetaddr||','||vpm.villagenamee||','||hpm.hoblinamee
            ||','||sm.sronamee||','||d.districtnamee||','||spm.statenamee as  Place_of_marriage,
            to_char(m.dateofmarriage,'dd-mm-yyyy') as date_of_marriage,
            m.finalregistrationnumber,
            m.signedformpath


            from kaveri.marriageregistration m  
            join  kaveri.persondetails bride on m.registrationid=bride.registrationid  and m.bridepersonid=bride.personid 
            join  kaveri.persondetails groom on m.registrationid=groom.registrationid  and m.bridegroompersonid =groom.personid
            join  kaveri.districtmaster d on d.districtcode=m.districtcode 
            join  kaveri.sromaster sm on m.regsrocode=sm.srocode 
            join  kaveri.villagemaster vpm on m.cityvillagecode=vpm.villagecode 
            join kaveri.hoblimaster hpm on m.hoblicode=hpm.hoblicode 
            join kaveri.statemaster spm on m.statecode=spm.statecode
            join  kaveri.villagemaster vbride on bride.percityvillagecode=vbride.villagecode 
            join kaveri.hoblimaster hbride on bride.perhoblicode=hbride.hoblicode 
            join kaveri.talukmaster tbride on bride.pertalukacode=tbride.talukcode 
            join kaveri.districtmaster dbride on bride.perdistrictcode=dbride.districtcode 
            join kaveri.statemaster sbride on bride.perstatecode=sbride.statecode
            join  kaveri.villagemaster vgroom on groom.percityvillagecode=vgroom.villagecode 
            join kaveri.hoblimaster hgroom on groom.perhoblicode=hgroom.hoblicode 
            join kaveri.talukmaster tgroom on groom.pertalukacode=tgroom.talukcode 
            join kaveri.districtmaster dgroom on groom.perdistrictcode=dgroom.districtcode 
            join kaveri.statemaster sgroom on groom.perstatecode=sgroom.statecode
            join kaveri.mas_marriagetype mm on m.marriagetypeid=mm.marriagetypeid

            where 
            m.isregistraioncomplete=true  and
            m.marriagetypeid=_marriagetypeid and 
            m.dateofregistration between _fromdate and _todate
            and m.districtcode=_districtcode),cte_count as (select count(*) as total_rows from cte)
            select * from cte
            join (select total_rows from cte_count) total_row on true OFFSET PageOffset
            FETCH NEXT pagesize ROWS ONLY;
            --and  m.talukacode=_talukcode;
            
        else
        
        return  query 
            with cte as (select 
            d.districtcode,
            sm.srocode,
            mm.marriagetypeid,
            mm.marriagetype,
            m.dateofregistration,
            d.districtnamee,
            sm.sronamee, 
            groom.firstname ||' '||groom.middlename||' '||groom.lastname as husband_name,
            groom.perhousebuildname || ','||groom.perstreetname||','||vgroom.villagenamee||','||hgroom.hoblinamee
            ||','||tgroom.taluknamee||','||dgroom.districtnamee||','||sgroom.statenamee as husband_address,
            bride.firstname ||' '||bride.middlename||' '||bride.lastname as wife_name,
            bride.perhousebuildname || ','||bride.perstreetname||','||vbride.villagenamee||','||hbride.hoblinamee
            ||','||tbride.taluknamee||','||dbride.districtnamee||','||sbride.statenamee as wife_address,
            m.housebuildingname || ',' || m.streetaddr||','||vpm.villagenamee||','||hpm.hoblinamee
            ||','||sm.sronamee||','||d.districtnamee||','||spm.statenamee as  Place_of_marriage,
            to_char(m.dateofmarriage,'dd-mm-yyyy') as date_of_marriage,
            m.finalregistrationnumber,
            m.signedformpath


            from kaveri.marriageregistration m  
            join  kaveri.persondetails bride on m.registrationid=bride.registrationid  and m.bridepersonid=bride.personid 
            join  kaveri.persondetails groom on m.registrationid=groom.registrationid  and m.bridegroompersonid =groom.personid
            join  kaveri.districtmaster d on d.districtcode=m.districtcode 
            join  kaveri.sromaster sm on m.regsrocode=sm.srocode 
            join  kaveri.villagemaster vpm on m.cityvillagecode=vpm.villagecode 
            join kaveri.hoblimaster hpm on m.hoblicode=hpm.hoblicode 
            join kaveri.statemaster spm on m.statecode=spm.statecode
            join  kaveri.villagemaster vbride on bride.percityvillagecode=vbride.villagecode 
            join kaveri.hoblimaster hbride on bride.perhoblicode=hbride.hoblicode 
            join kaveri.talukmaster tbride on bride.pertalukacode=tbride.talukcode 
            join kaveri.districtmaster dbride on bride.perdistrictcode=dbride.districtcode 
            join kaveri.statemaster sbride on bride.perstatecode=sbride.statecode
            join  kaveri.villagemaster vgroom on groom.percityvillagecode=vgroom.villagecode 
            join kaveri.hoblimaster hgroom on groom.perhoblicode=hgroom.hoblicode 
            join kaveri.talukmaster tgroom on groom.pertalukacode=tgroom.talukcode 
            join kaveri.districtmaster dgroom on groom.perdistrictcode=dgroom.districtcode 
            join kaveri.statemaster sgroom on groom.perstatecode=sgroom.statecode
            join kaveri.mas_marriagetype mm on m.marriagetypeid=mm.marriagetypeid

            where 
            m.isregistraioncomplete=true  and
            m.marriagetypeid=_marriagetypeid and 
            m.dateofregistration between _fromdate and _todate and m.districtcode=_districtcode
            and sm.srocode=_srocode),cte_count as (select count(*) as total_rows from cte)
            select * from cte
            join (select total_rows from cte_count) total_row on true OFFSET PageOffset
            FETCH NEXT pagesize ROWS ONLY;
            
    end if;         
                
                         
 

END;

$$;


