--
-- Name: fn_mis_integration_bhoomi(integer, integer, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_integration_bhoomi(_districtcode integer, _srocode integer, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber character varying, articlename character varying, regddatetime text, departmenttype text, referenceno character varying, uploaddatetime text, remarks1 text)
    LANGUAGE plpgsql
    AS $$



DECLARE
BEGIN 
	return query
			 select 
			 distinct
			 dsm.districtnamee,
			 sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,
			r.articlenamee as articlename,
			to_char(dm.registrationdatetime,'DD-MM-YYYY'),
			'Bhoomi' as departmenttype,
			 dm.acknowledgeno,
			 to_char(dm.uploaddate,'DD-MM-YYYY,HH:MM'),
			 dm.remarks::text
						

			from
			kaveri.vw_fetch_reuploadjslip dm
			join kaveri.registrationarticles r  on r.regarticlecode = dm.regarticlecode
			join kaveri.sromaster sm on dm.srocode=sm.srocode
			join kaveri.districtmaster dsm on sm.districtcode = dsm.districtcode
		where  
			dm.registrationdatetime::date>=_fromdate and
			dm.registrationdatetime::date<=_todate
		and 
		(case
		when _districtcode <> 0 then dsm.districtcode=_districtcode
		else true
	end

         )
	and (case
		when _srocode <> 0 then dm.srocode=_srocode
		else true
	end

                );
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_integration_bhoomi(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_mis_integration_bhoomi_optimized(integer, integer, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_integration_bhoomi_optimized(_districtcode integer, _srocode integer, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber character varying, articlename character varying, regddatetime text, departmenttype text, referenceno character varying, uploaddatetime text, remarks1 text)
    LANGUAGE plpgsql
    AS $$



DECLARE
BEGIN 
 return query
    select 
    distinct
    dsm.districtnamee,
    sm.sronamee,
   dm.finalregistrationnumber,
   dm.applicationnumber,
   r.articlenamee as articlename,
   to_char(dm.registrationdattime,'DD-MM-YYYY'),
   'Bhoomi' as departmenttype,
    dm.acknowledgeno,
    to_char(dm.uploaddate,'DD-MM-YYYY,HH:MM'),
    dm.remarks::text
      

   from
   (select ss.documentid,ss.finalregistrationnumber,ss.applicationnumber
   ,ss.registrationdattime,ss.bookid,ss.documentid,ss.srocode,ss.acknowledgeno,ss.createddate as uploaddate,ss.jslipsuccess,ss.regarticlecode,
   ss.remarks
    from kaverimis.fn_mis_integration_reuploadjslip(_districtcode, _srocode, _fromdate, _todate) as ss) dm
   join kaveri.registrationarticles r  on r.regarticlecode = dm.regarticlecode
   join kaveri.sromaster sm on dm.srocode=sm.srocode
   join kaveri.districtmaster dsm on sm.districtcode = dsm.districtcode
  where
  (case
  when _districtcode <> 0 then dsm.districtcode=_districtcode
  else true
 end

         )
 and (case
  when _srocode <> 0 then dm.srocode=_srocode
  else true
 end

                );
END;
$$;


