--
-- Name: fn_mis_integration_easthi_ab(integer, integer, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_integration_easthi_ab(_districtcode integer, _srocode integer, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber character varying, articlename character varying, regddatetime text, departmenttype text, referenceno character varying, uploaddatetime text, remarks1 text)
    LANGUAGE plpgsql
    AS $$



DECLARE
BEGIN 
	
	return query
	select  distinct
				sub.districtnamee,
					sub.sronamee,
					sub.finalregd,
					sub.applno,
					sub.article,
					sub.regddate,
					sub.department,
					sub.refno,
					sub.uploaddate,
					sub.remarks::text as remarks
					from
		
				(select 
				dsm.districtnamee as districtnamee ,
				sm.sronamee as sronamee,
				dm.finalregistrationnumber as finalregd ,
				dm.applicationnumber as  applno,
				r.articlenamee as article,
				to_char(dm.registrationdatetime,'DD-MM-YYYY') as regddate,
				'E-Aasthi' as department,
				ee.referencenumber as refno , ee.remarks,
				to_char(ee.uploaddate,'DD-MM-YYYY,HH:MM') as uploaddate,
				rank() over (partition by ee.finalregistrationnumber order by ee.createddate desc ) as rank1
				

				from
				kaveri.documentmaster dm
				join kaveri.registrationarticles r  on r.regarticlecode = dm.regarticlecode
				join kaveri.sromaster sm on dm.srocode=sm.srocode
				join kaveri.districtmaster dsm on sm.districtcode = dsm.districtcode
				join kaveri.propertymaster p on p.documentid=dm.documentid 
				join (select distinct propertyid  from kaveri.propertynumberdetails where currentpropertytypeid in (59,65)) p2  on p2.propertyid=p.propertyid 
				left join kaveri.easthi_eswathu_fileuploaddetails ee on ee.finalregistrationnumber = dm.finalregistrationnumber
				where 
				
				 
		
                dm.registrationdatetime::date>=_fromdate and
				dm.registrationdatetime::date<=_todate
				and (case
		when _districtcode <> 0 then dsm.districtcode=_districtcode
		else true
	end

         )
	and (case
		when _srocode <> 0 then dm.srocode=_srocode
		else true
	end

                )
				)sub 
				where sub.rank1=1 ;

	END;
$$;


