				join kaveri.sromaster sm on dm.srocode=sm.srocode
				join kaveri.districtmaster dsm on sm.districtcode = dsm.districtcode
				join kaveri.propertymaster p on p.documentid=dm.documentid 
				join (select distinct propertyid  from kaveri.propertynumberdetails where currentpropertytypeid in (60,59,65)) p2  on p2.propertyid=p.propertyid 
				left join kaveri.easthi_eswathu_fileuploaddetails ee on ee.finalregistrationnumber = dm.finalregistrationnumber
				where 
				
				 
		
                dm.registrationdatetime::date>=_fromdate and
				dm.registrationdatetime::date<=_todate
				and (case
		when _districtcode <> 0 then dsm.districtcode=_districtcode
		else true
	end

         )
	and (case
		when _srocode <> 0 then dm.srocode=_srocode
		else true
	end

                )
				)sub 
				where sub.rank1=1 ;

	END;
$$;


ALTER FUNCTION kaverimis.fn_mis_integration_eswathu_easthi(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_mis_integration_eswathu_easthi_optimized(integer, integer, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: manjunathswamy
--

CREATE FUNCTION kaverimis.fn_mis_integration_eswathu_easthi_optimized(_districtcode integer, _srocode integer, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber character varying, articlename character varying, regddatetime text, departmenttype text, referenceno character varying, uploaddatetime text, remarks1 text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN 
 
 return query
      SELECT distinct
        dsm.districtnamee,
        sm.sronamee,
        dm.finalregistrationnumber AS finalregd,
        dm.applicationnumber AS applno,
        r.articlenamee AS article,
        TO_CHAR(dm.registrationdatetime, 'DD-MM-YYYY') AS regddate,
        'E-Swathu, E-Aasthi' AS department,
        (select ee.referencenumber from kaveri.easthi_eswathu_fileuploaddetails ee
        where ee.finalregistrationnumber = dm.finalregistrationnumber order by ee.createddate desc limit 1) as  refno,
     (select ee.uploaddate::text from kaveri.easthi_eswathu_fileuploaddetails ee
     where ee.finalregistrationnumber = dm.finalregistrationnumber order by ee.createddate desc limit 1 ) as uploaddate,
     (select ee.remarks from kaveri.easthi_eswathu_fileuploaddetails ee
     where ee.finalregistrationnumber = dm.finalregistrationnumber order by ee.createddate desc limit 1
     ) as remarks
     from
     kaveri.documentmaster dm
     join kaveri.registrationarticles r  on r.regarticlecode = dm.regarticlecode
     join kaveri.sromaster sm on dm.srocode=sm.srocode
     join kaveri.districtmaster dsm on sm.districtcode = dsm.districtcode
     join kaveri.propertymaster p on p.documentid=dm.documentid
     join lateral (select distinct propertyid  from kaveri.propertynumberdetails pnd
      where pnd.propertyid=p.propertyid and currentpropertytypeid in (60,59,65)) p2  on p2.propertyid=p.propertyid
    where 
                dm.registrationdatetime::date>=_fromdate and
    dm.registrationdatetime::date<=_todate
    and (case
  when _districtcode <> 0 then dsm.districtcode=_districtcode
  else true end)
  and (case
  when _srocode <> 0 then dm.srocode=_srocode
  else true
  end);
 END;
$$;


