ALTER FUNCTION kaverimis.fn_mis_integration_form_1(_districtcode integer, _srocode integer, _departmenttype integer, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO csgadmin;

--
-- Name: fn_mis_integration_form_1(integer, integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_integration_form_1(_districtcode integer, _srocode integer, _departmenttype integer, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber character varying, articlename character varying, regddatetime text, departmenttype text, referenceno character varying, uploaddatetime text, remarks1 text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
			
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
			
			
	if _departmenttype=1 then -- bhoomi
		if (pagenumber<>-1 and pagesize<>-1) then
						 return query
						 with cte as (
						 
						 select * from kaverimis.fn_mis_integration_bhoomi(_districtcode, _srocode, _fromdate, _todate)
						 
						 ),cte_count as (select count(*) as total_rows from cte)

            select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0 					
			limit pagesize offset PageOffset;
		
		elsif (pagenumber=-1 or  pagesize=-1) then  
			return query
						 with cte as (
						 
						 select * from kaverimis.fn_mis_integration_bhoomi(_districtcode, _srocode, _fromdate, _todate)
						 
						 ),cte_count as (select count(*) as total_rows from cte)

            select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0;
		end if;

		
		elsif _departmenttype=2 then --E-swathu and E-Aasthi
			if (pagenumber<>-1 and pagesize<>-1) then

				return query with cte as (
				
