--

CREATE FUNCTION kaverimis.fn_mis_integration_form_1_ab(_districtcode integer, _srocode integer, _departmenttype integer, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber character varying, articlename character varying, regddatetime text, departmenttype text, departmenttypeid integer, referenceno character varying, uploaddatetime text, remarks1 text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
			
declare
pageoffset integer := 0;
begin	
pageoffset := ((pagenumber - 1) * pagesize);
			
			
	if _departmenttype=1 then -- bhoomi
		if (pagenumber<>-1 and pagesize<>-1) then
						 return query
						 with cte as (
						 
						 select * from kaverimis.fn_mis_integration_bhoomi(_districtcode, _srocode, _fromdate, _todate)
						 
						 ),cte_count as (select count(*) as total_rows from cte)

            select 
                cte.districtname,
                cte.sroname,
                cte.finalregistrationnumber,
                cte.applicationnumber,
                cte.articlename,
                cte.regddatetime,
                cte.departmenttype,
                _departmenttype as departmenttypeid,
                cte.referenceno,
                cte.uploaddatetime,
                cte.remarks1,
                total_row.total_rows
            from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0 					
			limit pagesize offset pageoffset;
		
		elsif (pagenumber=-1 or  pagesize=-1) then  
			return query
						 with cte as (
						 
						 select * from kaverimis.fn_mis_integration_bhoomi(_districtcode, _srocode, _fromdate, _todate)
						 
						 ),cte_count as (select count(*) as total_rows from cte)

            select 
                cte.districtname,
                cte.sroname,
                cte.finalregistrationnumber,
                cte.applicationnumber,
                cte.articlename,
                cte.regddatetime,
                cte.departmenttype,
                _departmenttype as departmenttypeid,
                cte.referenceno,
                cte.uploaddatetime,
                cte.remarks1,
                total_row.total_rows
            from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0;
		end if;

		
		elsif _departmenttype=3 then --e-swathu
			if (pagenumber<>-1 and pagesize<>-1) then

				return query with cte as (
				
					select * from kaverimis.fn_mis_integration_eswathu_ab(_districtcode, _srocode, _fromdate, _todate)
				
				),cte_count as (select count(*) as total_rows from cte)

            select 
                cte.districtname,
                cte.sroname,
                cte.finalregistrationnumber,
                cte.applicationnumber,
