				),cte_count as (select count(*) as total_rows from cte)

            select 
                cte.districtname,
                cte.sroname,
                cte.finalregistrationnumber,
                cte.applicationnumber,
                cte.articlename,
                cte.regddatetime,
                cte.departmenttype,
