                cte.referenceno,
                cte.uploaddatetime,
                cte.remarks1,
                total_row.total_rows
            from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0;
		end if;
				
	elsif _departmenttype=0 then  --all dept
	
	if (pagenumber<>-1 and pagesize<>-1) then

	
	return query with cte as (
	
		with bhoomi_data as (
				select * from kaverimis.fn_mis_integration_bhoomi(_districtcode, _srocode, _fromdate, _todate)),
					
		eswathu_data as (
				select * from kaverimis.fn_mis_integration_eswathu_ab(_districtcode, _srocode, _fromdate, _todate)),

		easthi_data as (
				select * from kaverimis.fn_mis_integration_easthi_ab(_districtcode, _srocode, _fromdate, _todate))
			
		select bhoomi_data.* from bhoomi_data

				union all

		select eswathu_data.* from eswathu_data
				
				union all

		select easthi_data.* from easthi_data
				
			order by finalregistrationnumber asc ),cte_count as (select count(*) as total_rows from cte)

            select 
                cte.districtname,
                cte.sroname,
                cte.finalregistrationnumber,
                cte.applicationnumber,
                cte.articlename,
