		select bhoomi_data.* from bhoomi_data

				union all

		select eswathu_data.* from eswathu_data
				
				union all

		select easthi_data.* from easthi_data
		order by finalregistrationnumber asc ),cte_count as (select count(*) as total_rows from cte)

