				kaveri.documentmaster dm
				join kaveri.registrationarticles r  on r.regarticlecode = dm.regarticlecode
				join kaveri.sromaster sm on dm.srocode=sm.srocode
				join kaveri.districtmaster dsm on sm.districtcode = dsm.districtcode
				join kaveri.fruits_data_recv_details fdr ON fdr.documentid = dm.documentid
				where 
				dsm.districtcode=_districtcode and
				dm.srocode=_srocode and 
				dm.registrationdatetime::date>=_fromdate and
				dm.registrationdatetime::date<=_todate;
		
		elsif _departmenttype=2 then --E-swathu and E-Aasthi
				return query
				select  distinct
				sub.districtnamee,
					sub.sronamee,
					sub.finalregd,
					sub.applno,
					sub.article,
					sub.regddate,
					sub.department,
					sub.refno,
					sub.uploaddate,
					sub.remarks::text as remarks
					from
		
				(select 
				dsm.districtnamee as districtnamee ,
				sm.sronamee as sronamee,
				dm.finalregistrationnumber as finalregd ,
				dm.applicationnumber as  applno,
				r.articlenamee as article,
				to_char(dm.registrationdatetime,'DD-MM-YYYY') as regddate,
				'E-Swathu, E-Aasthi' as department,
				ee.referencenumber as refno , ee.remarks,
				to_char(ee.uploaddate,'DD-MM-YYYY,HH:MM') as uploaddate,
				rank() over (partition by ee.finalregistrationnumber order by ee.createddate desc ) as rank1
				

				from
				kaveri.documentmaster dm
				join kaveri.registrationarticles r  on r.regarticlecode = dm.regarticlecode
				join kaveri.sromaster sm on dm.srocode=sm.srocode
				join kaveri.districtmaster dsm on sm.districtcode = dsm.districtcode
				join kaveri.easthi_eswathu_fileuploaddetails ee on ee.finalregistrationnumber = dm.finalregistrationnumber
				where 
				dsm.districtcode=_districtcode and
				dm.srocode=_srocode and
				dm.registrationdatetime::date>=_fromdate and
				dm.registrationdatetime::date<=_todate)sub 
				where sub.rank1=1; 
		
			--and (sub.refno is null or sub.refno::integer>999);
				
				
				elsif _departmenttype=0 then  --All dept
				
				
			return query
			select  distinct
			 dsm.districtnamee,
			 sm.sronamee,
			dm.finalregistrationnumber,
			dm.applicationnumber,
			r.articlenamee as articlename,
			to_char(dm.registrationdatetime,'DD-MM-YYYY'),
			'Bhoomi' as departmenttype,
			 dm.acknowledgeno,
			 to_char(dm.uploaddate,'DD-MM-YYYY,HH:MM'),
			 dm.remarks::text as remarks
						

			from
			kaveri.vw_fetch_reuploadjslip dm
			join kaveri.registrationarticles r  on r.regarticlecode = dm.regarticlecode
			join kaveri.sromaster sm on dm.srocode=sm.srocode
			join kaveri.districtmaster dsm on sm.districtcode = dsm.districtcode
			where
			--(dm.acknowledgeno is null or dm.acknowledgeno::integer >= 999 or dm.acknowledgeno='901') and 
			dsm.districtcode=_districtcode and
			dm.srocode=_srocode and
			dm.registrationdatetime::date>=_fromdate and
			dm.registrationdatetime::date<=_todate
					
					union ALL
					
					select  distinct
				dsm.districtnamee,
				sm.sronamee,
				dm.finalregistrationnumber,
				dm.applicationnumber,
				r.articlenamee as articlename,
				to_char(dm.registrationdatetime,'DD-MM-YYYY'),
				'Fruits' as departmenttype,
				fdr.referenceno::character varying,
				to_char(fdr.inserteddatetime,'DD-MM-YYYY,HH:MM'),
				null::text as remarks
				 

				from
				kaveri.documentmaster dm
				join kaveri.registrationarticles r  on r.regarticlecode = dm.regarticlecode
				join kaveri.sromaster sm on dm.srocode=sm.srocode
				join kaveri.districtmaster dsm on sm.districtcode = dsm.districtcode
				join kaveri.fruits_data_recv_details fdr ON fdr.documentid = dm.documentid
				where 
				dsm.districtcode=_districtcode and
				dm.srocode=_srocode and 
				dm.registrationdatetime::date>=_fromdate and
				dm.registrationdatetime::date<=_todate
					
				     
					  Union All
				
						select  distinct
				sub.districtnamee,
					sub.sronamee,
					sub.finalregd,
					sub.applno,
					sub.article,
					sub.regddate,
					sub.department,
					sub.refno,
					sub.uploaddate,
					sub.remarks::text as remarks
					from
		
				(select 
				dsm.districtnamee as districtnamee ,
				sm.sronamee as sronamee,
				dm.finalregistrationnumber as finalregd ,
				dm.applicationnumber as  applno,
				r.articlenamee as article,
				to_char(dm.registrationdatetime,'DD-MM-YYYY') as regddate,
				'E-Swathu, E-Aasthi' as department,
				ee.referencenumber as refno , ee.remarks,
				to_char(ee.uploaddate,'DD-MM-YYYY,HH:MM') as uploaddate,
				rank() over (partition by ee.finalregistrationnumber order by ee.createddate desc ) as rank1
				

				from
				kaveri.documentmaster dm
				join kaveri.registrationarticles r  on r.regarticlecode = dm.regarticlecode
				join kaveri.sromaster sm on dm.srocode=sm.srocode
				join kaveri.districtmaster dsm on sm.districtcode = dsm.districtcode
				join kaveri.easthi_eswathu_fileuploaddetails ee on ee.finalregistrationnumber = dm.finalregistrationnumber
				where 
				dsm.districtcode=_districtcode and
				dm.srocode=_srocode and
				dm.registrationdatetime::date>=_fromdate and
				dm.registrationdatetime::date<=_todate)sub 
				where sub.rank1=1; 
		
			--and (sub.refno is null or sub.refno::integer>999);
						
							
						
						end if;
						
				end if;			
			
			
				
				
				
				
				
						 

					 

END;

$$;


