--
-- Name: fn_mis_integration_form_1_optimized(integer, integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: manjunathswamy
--

CREATE FUNCTION kaverimis.fn_mis_integration_form_1_optimized(_districtcode integer, _srocode integer, _departmenttype integer, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, applicationnumber character varying, articlename character varying, regddatetime text, departmenttype text, referenceno character varying, uploaddatetime text, remarks1 text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
   
DECLARE
PageOffset INTEGER := 0;
BEGIN 
PageOffset := ((pagenumber - 1) * pagesize);
   
   
 if _departmenttype=1 then -- bhoomi
  if (pagenumber<>-1 and pagesize<>-1) then
       return query
       with cte as (
       
       select * from kaverimis.fn_mis_integration_bhoomi_optimized(_districtcode, _srocode, _fromdate, _todate)
       
       ),cte_count as (select count(*) as total_rows from cte)

            select * from cte
   right join (select total_rows from cte_count) total_row on true
   where total_row.total_rows<>0      
   limit pagesize offset PageOffset;
  
  elsif (pagenumber=-1 or  pagesize=-1) then  
   return query
       with cte as (
       
       select * from kaverimis.fn_mis_integration_bhoomi_optimized(_districtcode, _srocode, _fromdate, _todate)
       
       ),cte_count as (select count(*) as total_rows from cte)

            select * from cte
   right join (select total_rows from cte_count) total_row on true
   where total_row.total_rows<>0;
  end if;

  
  elsif _departmenttype=2 then --E-swathu and E-Aasthi
   if (pagenumber<>-1 and pagesize<>-1) then

    return query with cte as (
    
     select * from kaverimis.fn_mis_integration_eswathu_easthi_optimized(_districtcode, _srocode, _fromdate, _todate)
    
    ),cte_count as (select count(*) as total_rows from cte)

            select * from cte
   right join (select total_rows from cte_count) total_row on true
   where total_row.total_rows<>0      
   limit pagesize offset PageOffset;
  
  elsif (pagenumber=-1 or  pagesize=-1) then  
  return query with cte as (
    
     select * from kaverimis.fn_mis_integration_eswathu_easthi_optimized(_districtcode, _srocode, _fromdate, _todate)
    
    ),cte_count as (select count(*) as total_rows from cte)

            select * from cte
   right join (select total_rows from cte_count) total_row on true
   where total_row.total_rows<>0;
  end if;
    
 elsif _departmenttype=0 then  --All dept
 
 if (pagenumber<>-1 and pagesize<>-1) then

 
 return query with cte as (
 
 with bhoomi_data as (
    select * from kaverimis.fn_mis_integration_bhoomi_optimized(_districtcode, _srocode, _fromdate, _todate)),
     
  eswathu_asthi_data as (
    select * from kaverimis.fn_mis_integration_eswathu_easthi_optimized(_districtcode, _srocode, _fromdate, _todate))
   
  SELECT bhoomi_data.* from bhoomi_data

    UNION ALL

  select eswathu_asthi_data.* from eswathu_asthi_data
    
   order by finalregistrationnumber asc ),cte_count as (select count(*) as total_rows from cte)

            select * from cte
   right join (select total_rows from cte_count) total_row on true
   where total_row.total_rows<>0      
   limit pagesize offset PageOffset;
  
  elsif (pagenumber=-1 or  pagesize=-1) then  
  return query with cte as (
 
 with bhoomi_data as (
    select * from kaverimis.fn_mis_integration_bhoomi_optimized(_districtcode, _srocode, _fromdate, _todate)),
     
  eswathu_asthi_data as (
    select * from kaverimis.fn_mis_integration_eswathu_easthi_optimized(_districtcode, _srocode, _fromdate, _todate))
   
  SELECT bhoomi_data.* from bhoomi_data

    UNION ALL

  select eswathu_asthi_data.* from eswathu_asthi_data
    
  order by finalregistrationnumber asc ),cte_count as (select count(*) as total_rows from cte)

            select * from cte
   right join (select total_rows from cte_count) total_row on true
   where total_row.total_rows<>0;
  end if;
      
end if;


 END;
$$;


