--
-- Name: fn_mis_integration_reuploadjslip(integer, integer, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_integration_reuploadjslip(_districtcode integer, _srocode integer, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE(documentid bigint, srocode integer, bookid integer, regarticlecode integer, applicationnumber character varying, finalregistrationnumber character varying, registrationdattime timestamp without time zone, acknowledgeno character varying, remarks character varying, createddate timestamp without time zone, jslipsuccess boolean)
    LANGUAGE plpgsql
    AS $$
begin

return query
SELECT DISTINCT dm.documentid,
            dm.srocode,
            dm.bookid,
            dm.regarticlecode,
            dm.applicationnumber,
            dm.finalregistrationnumber,
            dm.registrationdatetime,
            COALESCE((select b.acknowledgeno from kaveri.bhoomifileuploaddetails b where b.finalregistrationnumber =dm.finalregistrationnumber
            order by b.createddate desc limit 1), '0'::character varying(8000)) AS acknowledgeno,
--            bf.remarks,
            (select b.remarks from kaveri.bhoomifileuploaddetails b where b.finalregistrationnumber =dm.finalregistrationnumber order by b.createddate
    desc limit 1) as remarks,
--            bf.createddate,
            (select b.createddate from kaveri.bhoomifileuploaddetails b where b.finalregistrationnumber =dm.finalregistrationnumber order by b.createddate desc limit 1)  as createddate
           , CASE
                    WHEN (select b.remarks from kaveri.bhoomifileuploaddetails b where b.finalregistrationnumber =dm.finalregistrationnumber 
                    order by b.createddate desc limit 1)::text = ANY (ARRAY['Already Saved'::character varying::text, 'Saved'::character varying::text])
                     THEN true
                    ELSE  
                     false
                 END AS jslipsuccess
           FROM kaveri.documentmaster dm
             JOIN kaveri.propertymaster pm ON dm.documentid = pm.documentid
             JOIN kaveri.stamprulesflag s ON pm.stampruleid = s.stampruleid
             join kaveri.sromaster ss on dm.srocode=ss.srocode
   join kaveri.districtmaster dsm on ss.districtcode = dsm.districtcode
          WHERE dm.isregistrationcompleted = true and dm.registrationdatetime::Date>=_fromdate  and dm.registrationdatetime::Date<=_todate
and (case when _districtcode <> 0 then dsm.districtcode=_districtcode else true
 end )
 and (case when _srocode <> 0 then dm.srocode=_srocode
  else true
 end )
 AND pm.propertytypeid = 17 AND s.isjslipagri IS true;
end;
$$;


ALTER FUNCTION kaverimis.fn_mis_integration_reuploadjslip(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_mis_intimation_slip_form(integer, character varying, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_intimation_slip_form(_srocode integer, _documentnnumber character varying DEFAULT NULL::character varying, _from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _to_date timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE(district character varying, sroname character varying, nameofregistrationoffice character varying, registrarno character varying, yearofthedocument text, nameofregofficedocsent character varying, copy_of_document text, no_and_date_of_despatch text, date_of_receipt_by_the_officer_and_no text, acknowledgement text)
    LANGUAGE plpgsql
    AS $$
/*DECLARE
PageOffset INTEGER := 0;*/
BEGIN	
_to_date:=(_to_date+'1 day'::interval);
--PageOffset := ((pagenumber - 1) * pagesize); 	
if (_from_date is not null and _to_date is not null) and (_documentnnumber is null) then
return query 
select distinct
c.districtnamee as district,
b.sronamee as sroname,
(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode) as nameofregistrationoffice,
a.finalregistrationnumber   as registrarno,
to_char(a.registrationdatetime,'yyyy') as yearofthedocument,
(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode) as nameofregofficedocsent,
a.uploaddocdeedpath as copy_of_document,
(a.finalregistrationnumber ||' '|| to_char(a.executiondatetime,'dd/mm/yyyy') ||' '|| b.sronamee ||' '|| 
to_char(a.executiondatetime,'dd/mm/yyyy'))::text as no_and_date_of_despatch,
coalesce(to_char(arl.memosentdatetime,'dd/mm/yyyy'),' ')||' '||arl.srocode||'-'||arl.logid as  date_of_receipt_by_the_officer_and_no,
coalesce(to_char(arl.memoaccepteddatetime,'dd/mm/yyyy'),' ')||' '||coalesce(dm.finalregistrationnumber,' ')as acknowledgement
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.districtmaster c on b.districtcode = c.districtcode
join kaveri.propertymaster d on a.documentid = d.documentid
join kaveri.anywhere_reg_log arl on arl.applicationnumber =a.applicationnumber
left join kaveri.documentmaster dm   on arl.newapplicationnumber=dm.applicationnumber
where b.srocode = _srocode and arl.srocode<>0 and arl.regsrocode<>0
and a.registrationdatetime >= _from_date and a.registrationdatetime <= _to_date and a.isregistrationcompleted = true;
elseif (_documentnnumber is not null) and (_from_date is null and _to_date is null) then
	 return query
select distinct
c.districtnamee as district,
b.sronamee as sroname,
(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode) as nameofregistrationoffice,
a.finalregistrationnumber   as registrarno,
to_char(a.registrationdatetime,'yyyy') as yearofthedocument,
(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode) as nameofregofficedocsent,
a.uploaddocdeedpath as copy_of_document,
(a.finalregistrationnumber ||' '|| to_char(a.executiondatetime,'dd/mm/yyyy') ||' '|| b.sronamee ||' '|| 
to_char(a.executiondatetime,'dd/mm/yyyy'))::text as no_and_date_of_despatch,
coalesce(to_char(arl.memosentdatetime,'dd/mm/yyyy'),' ')||' '||arl.srocode||'-'||arl.logid as  date_of_receipt_by_the_officer_and_no,
coalesce(to_char(arl.memoaccepteddatetime,'dd/mm/yyyy'),' ')||' '||coalesce(dm.finalregistrationnumber,' ')as acknowledgement
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.districtmaster c on b.districtcode = c.districtcode
join kaveri.propertymaster d on a.documentid = d.documentid
join kaveri.anywhere_reg_log arl on arl.applicationnumber =a.applicationnumber
left join kaveri.documentmaster dm   on arl.newapplicationnumber=dm.applicationnumber
where b.srocode = _srocode and arl.srocode<>0 and arl.regsrocode<>0
and a.isregistrationcompleted = true and a.finalregistrationnumber = _documentnnumber;
elseif (_documentnnumber is not null) and (_from_date is not null and _to_date is not null) then
--else
--raise notice 'checking else part';
return query
select distinct
c.districtnamee as district,
b.sronamee as sroname,
(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode) as nameofregistrationoffice,
a.finalregistrationnumber   as registrarno,
to_char(a.registrationdatetime,'yyyy') as yearofthedocument,
(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode) as nameofregofficedocsent,
a.uploaddocdeedpath as copy_of_document,
(a.finalregistrationnumber ||' '|| to_char(a.executiondatetime,'dd/mm/yyyy') ||' '|| b.sronamee ||' '|| 
to_char(a.executiondatetime,'dd/mm/yyyy'))::text as no_and_date_of_despatch,
coalesce(to_char(arl.memosentdatetime,'dd/mm/yyyy'),' ')||' '||arl.srocode||'-'||arl.logid as  date_of_receipt_by_the_officer_and_no,
coalesce(to_char(arl.memoaccepteddatetime,'dd/mm/yyyy'),' ')||' '||coalesce(dm.finalregistrationnumber,' ')as acknowledgement
from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode
join kaveri.districtmaster c on b.districtcode = c.districtcode
join kaveri.propertymaster d on a.documentid = d.documentid
join kaveri.anywhere_reg_log arl on arl.applicationnumber =a.applicationnumber
left join kaveri.documentmaster dm   on arl.newapplicationnumber=dm.applicationnumber
where b.srocode = _srocode and arl.srocode<>0 and arl.regsrocode<>0
and a.registrationdatetime >= _from_date and a.registrationdatetime <= _to_date and a.isregistrationcompleted = true and a.finalregistrationnumber = _documentnnumber;
end if;
END;
$$;


