			where arl.srocode<>0 and arl.regsrocode<>0
			and a.isregistrationcompleted = true and a.finalregistrationnumber = _documentnnumber),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
			end if;
else

				if (_documentnnumber is null) and (_from_date is not null and _to_date is not null)	 then
				return query 
				with cte as (select distinct
				c.districtnamee as district,
				b.sronamee as sroname,
				(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode) as nameofregistrationoffice,
				a.finalregistrationnumber   as registrarno,
