				coalesce(to_char(arl.memosentdatetime,'dd/mm/yyyy'),' ')||' '||arl.srocode||'-'||arl.logid as  date_of_receipt_by_the_officer_and_no,
				coalesce(to_char(arl.memoaccepteddatetime,'dd/mm/yyyy'),' ')||' '||coalesce(dm.finalregistrationnumber,' ')as acknowledgement
				from kaveri.documentmaster a join kaveri.sromaster b on a.srocode = b.srocode and b.districtcode = _districtcode
				join kaveri.districtmaster c on b.districtcode = c.districtcode
				join kaveri.propertymaster d on a.documentid = d.documentid
				join kaveri.anywhere_reg_log arl on arl.applicationnumber =a.applicationnumber
				left join kaveri.documentmaster dm   on arl.newapplicationnumber=dm.applicationnumber
				where b.srocode = _srocode and arl.srocode<>0 and arl.regsrocode<>0
				and (a.registrationdatetime between  _from_date and  _to_date) and a.isregistrationcompleted = true),cte_count as (select count(*) as total_rows from cte)
			select * from cte
