ALTER FUNCTION kaverimis.fn_mis_intimation_slip_form(_districtcode integer, _srocode integer, _documentnnumber character varying, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_khajane_credit_status_documentwise(bigint[], bigint[], date, date); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_khajane_credit_status_documentwise(_districtcode bigint[] DEFAULT '{}'::bigint[], _srocode bigint[] DEFAULT '{}'::bigint[], _fromdate date DEFAULT NULL::date, _todate date DEFAULT NULL::date) RETURNS TABLE(dr text, sr text, amount numeric, regn_date date, frn_appln text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF _fromdate IS NULL OR _todate IS NULL THEN
        RAISE EXCEPTION 'From date and To date are mandatory';
    END IF;
    RETURN QUERY
    WITH doc_wise AS
    (
        SELECT
            dm.districtnamee::text AS dr,
            s.sronamee::text AS sr,
            e.applicationnumber,
            SUM(COALESCE(e.totalamount, 0)::numeric) AS amount,
            MAX(d.registrationdatetime::date) AS regn_date,
            MAX(d.finalregistrationnumber) AS finalregistrationnumber
        FROM kaveri.ams_reg_epaymentbankackdetails b
        JOIN kaveri.ams_reg_epaymenttransdetails e
          ON e.deptreferencecode = b.deptreferencecode
         AND COALESCE(e.isdelete, false) = false
        LEFT JOIN kaveri.documentmaster d
          ON d.applicationnumber = e.applicationnumber
        LEFT JOIN kaveri.sromaster s
          ON s.srocode = d.srocode
        LEFT JOIN kaveri.districtmaster dm
          ON dm.districtcode = s.districtcode
        WHERE b.paymentstatuscode IN ('10700066', '10700072')
          AND b.transactiontimestamp >= _fromdate::timestamp
          AND b.transactiontimestamp < (_todate::timestamp + INTERVAL '1 day')
          AND (CASE WHEN _districtcode <> '{}' AND NOT (0 = ANY(_districtcode)) THEN s.districtcode = any(_districtcode) ELSE TRUE END)
          AND (CASE WHEN _srocode <> '{}' AND NOT (0 = ANY(_srocode))  THEN d.srocode = any(_srocode) ELSE TRUE END)
        GROUP BY
            dm.districtnamee,
            s.sronamee,
            e.applicationnumber
    )
    SELECT
        COALESCE(dw.dr, '')::text AS dr,
        COALESCE(dw.sr, '')::text AS sr,
        dw.amount::numeric AS amount,
        dw.regn_date,
        CASE
            WHEN dw.finalregistrationnumber IS NOT NULL AND dw.finalregistrationnumber <> ''
                THEN dw.finalregistrationnumber
            ELSE dw.applicationnumber
        END::text AS frn_appln
    FROM doc_wise dw
    ORDER BY
        dw.dr,
        dw.sr,
        dw.regn_date NULLS LAST,
        CASE
            WHEN dw.finalregistrationnumber IS NOT NULL AND dw.finalregistrationnumber <> ''
                THEN dw.finalregistrationnumber
            ELSE dw.applicationnumber
        END;
 
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_khajane_credit_status_documentwise(_districtcode bigint[], _srocode bigint[], _fromdate date, _todate date) OWNER TO postgres;

--
-- Name: fn_mis_khajane_credit_status_documentwise(bigint, bigint, date, date); Type: FUNCTION; Schema: kaverimis; Owner: manjunathswamy
--

CREATE FUNCTION kaverimis.fn_mis_khajane_credit_status_documentwise(_districtcode bigint DEFAULT 0, _srocode bigint DEFAULT 0, _fromdate date DEFAULT NULL::date, _todate date DEFAULT NULL::date) RETURNS TABLE(dr text, sr text, amount numeric, regn_date date, frn_appln text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF _fromdate IS NULL OR _todate IS NULL THEN
        RAISE EXCEPTION 'From date and To date are mandatory';
    END IF;
    RETURN QUERY
    WITH doc_wise AS
    (
        SELECT
            dm.districtnamee::text AS dr,
            s.sronamee::text AS sr,
            e.applicationnumber,
            SUM(COALESCE(e.totalamount, 0)::numeric) AS amount,
            MAX(d.registrationdatetime::date) AS regn_date,
            MAX(d.finalregistrationnumber) AS finalregistrationnumber
        FROM kaveri.ams_reg_epaymentbankackdetails b
        JOIN kaveri.ams_reg_epaymenttransdetails e
          ON e.deptreferencecode = b.deptreferencecode
         AND COALESCE(e.isdelete, false) = false
        LEFT JOIN kaveri.documentmaster d
          ON d.applicationnumber = e.applicationnumber
        LEFT JOIN kaveri.sromaster s
          ON s.srocode = d.srocode
        LEFT JOIN kaveri.districtmaster dm
          ON dm.districtcode = s.districtcode
        WHERE b.paymentstatuscode IN ('10700066', '10700072')
          AND b.transactiontimestamp >= _fromdate::timestamp
          AND b.transactiontimestamp < (_todate::timestamp + INTERVAL '1 day')
          AND (CASE WHEN _districtcode <> 0 THEN s.districtcode = _districtcode ELSE TRUE END)
          AND (CASE WHEN _srocode <> 0 THEN d.srocode = _srocode ELSE TRUE END)
        GROUP BY
            dm.districtnamee,
            s.sronamee,
            e.applicationnumber
    )
    SELECT
        COALESCE(dw.dr, '')::text AS dr,
        COALESCE(dw.sr, '')::text AS sr,
        dw.amount::numeric AS amount,
        dw.regn_date,
        CASE
            WHEN dw.finalregistrationnumber IS NOT NULL AND dw.finalregistrationnumber <> ''
                THEN dw.finalregistrationnumber
            ELSE dw.applicationnumber
        END::text AS frn_appln
    FROM doc_wise dw
    ORDER BY
        dw.dr,
        dw.sr,
        dw.regn_date NULLS LAST,
        CASE
            WHEN dw.finalregistrationnumber IS NOT NULL AND dw.finalregistrationnumber <> ''
                THEN dw.finalregistrationnumber
            ELSE dw.applicationnumber
        END;

END;
$$;


ALTER FUNCTION kaverimis.fn_mis_khajane_credit_status_documentwise(_districtcode bigint, _srocode bigint, _fromdate date, _todate date) OWNER TO manjunathswamy;

--
-- Name: fn_mis_khajane_credit_status_report(bigint[], bigint[], date, date); Type: FUNCTION; Schema: kaverimis; Owner: manjunathswamy
--

CREATE FUNCTION kaverimis.fn_mis_khajane_credit_status_report(_districtcode bigint[] DEFAULT '{}'::bigint[], _srocode bigint[] DEFAULT '{}'::bigint[], _fromdate date DEFAULT NULL::date, _todate date DEFAULT NULL::date) RETURNS TABLE(dr text, sr text, document_registered bigint, amount_credited_to_khajane_doc_registered numeric, yet_to_be_registered bigint, amount_credited_to_khajane_doc_not_registered numeric, total_documents bigint, amount_credited_to_khajane numeric)
    LANGUAGE plpgsql
    AS $$
begin
    if _fromdate is null or _todate is null then
        raise exception 'From date and To date are mandatory';
    end if;
    return query
    with sro_base as
    (
        select
            dm.districtnamee::text as dr,
            s.sronamee::text as sr,
            s.srocode,
            s.districtcode
        from kaveri.sromaster s
        left join kaveri.districtmaster dm
          on dm.districtcode = s.districtcode
        where
            (
                case
                    when _districtcode <> '{}' and not (0 = any(_districtcode))
                        then s.districtcode = any(_districtcode)
                    else true
                end
            )
          and
            (
                case
                    when _srocode <> '{}' and not (0 = any(_srocode))
                        then s.srocode = any(_srocode)
                    else true
                end
            )
    ),
    app_level as
    (
        select
            dm.districtnamee::text as dr,
            s.sronamee::text as sr,
            e.applicationnumber,
            max(d.finalregistrationnumber) as finalregistrationnumber,
            bool_or(coalesce(d.isregistrationcompleted, false)) as isregistrationcompleted,
            sum(coalesce(e.totalamount, 0)::numeric) as credited_amount
        from kaveri.ams_reg_epaymentbankackdetails b
        join kaveri.ams_reg_epaymenttransdetails e
          on e.deptreferencecode = b.deptreferencecode
         and coalesce(e.isdelete, false) = false
        left join kaveri.applicantapplicationdetails a
          on a.applicationnumber = e.applicationnumber
         and coalesce(a.isdeleted, false) = false
        left join kaveri.sromaster s
          on s.srocode = coalesce(a.regsrocode, a.srocode)
        left join kaveri.districtmaster dm
          on dm.districtcode = s.districtcode
        left join kaveri.documentmaster d
          on d.applicationnumber = e.applicationnumber
        where b.paymentstatuscode in ('10700066', '10700072')
          and b.transactiontimestamp >= _fromdate::timestamp
          and b.transactiontimestamp < (_todate::timestamp + interval '1 day')
          and (
                case
                    when _districtcode <> '{}' and not (0 = any(_districtcode))
                        then s.districtcode = any(_districtcode)
                    else true
                end
              )
          and (
                case
                    when _srocode <> '{}' and not (0 = any(_srocode))
                        then s.srocode = any(_srocode)
                    else true
                end
              )
        group by
            dm.districtnamee,
            s.sronamee,
            e.applicationnumber
    ),
    sro_level as
    (
        select
            sb.dr,
            sb.sr,

            count(*) filter
            (
                where al.isregistrationcompleted = true
                  and al.finalregistrationnumber is not null
            )::bigint as document_registered,

            coalesce(sum(al.credited_amount) filter
            (
                where al.isregistrationcompleted = true
                  and al.finalregistrationnumber is not null
            ), 0)::numeric as amount_credited_to_khajane_doc_registered,
            count(*) filter
            (
                where not
                (
                    al.isregistrationcompleted = true
                    and al.finalregistrationnumber is not null
                )
                and al.applicationnumber is not null
            )::bigint as yet_to_be_registered,
            coalesce(sum(al.credited_amount) filter
            (
                where not
                (
                    al.isregistrationcompleted = true
                    and al.finalregistrationnumber is not null
                )
                and al.applicationnumber is not null
            ), 0)::numeric as amount_credited_to_khajane_doc_not_registered,

            coalesce(sum(al.credited_amount), 0)::numeric as amount_credited_to_khajane
        from sro_base sb
        left join app_level al
          on sb.dr = al.dr
         and sb.sr = al.sr
        group by
            sb.dr,
            sb.sr
    )
    select
        case
            when grouping(sl.dr) = 1 then 'Consolidated'
            else coalesce(sl.dr, '')
        end::text as dr,
        case
            when grouping(sl.dr) = 1 then ''::text
            else coalesce(sl.sr, '')::text
        end as sr,
        sum(coalesce(sl.document_registered, 0))::bigint as document_registered,
        sum(coalesce(sl.amount_credited_to_khajane_doc_registered, 0))::numeric
            as amount_credited_to_khajane_doc_registered,
        sum(coalesce(sl.yet_to_be_registered, 0))::bigint as yet_to_be_registered,
        sum(coalesce(sl.amount_credited_to_khajane_doc_not_registered, 0))::numeric
            as amount_credited_to_khajane_doc_not_registered,
        (
            sum(coalesce(sl.document_registered, 0)) +
            sum(coalesce(sl.yet_to_be_registered, 0))
        )::bigint as total_documents,
        sum(coalesce(sl.amount_credited_to_khajane, 0))::numeric as amount_credited_to_khajane
    from sro_level sl
    group by grouping sets
    (
        (sl.dr, sl.sr),
        ()
    )
    order by
        case when grouping(sl.dr) = 1 then 0 else 1 end,
        sl.dr,
        sl.sr;
end;
$$;


ALTER FUNCTION kaverimis.fn_mis_khajane_credit_status_report(_districtcode bigint[], _srocode bigint[], _fromdate date, _todate date) OWNER TO manjunathswamy;

--
-- Name: fn_mis_khajane_credit_status_report_cc(bigint[], bigint[], date, date); Type: FUNCTION; Schema: kaverimis; Owner: manjunathswamy
--

CREATE FUNCTION kaverimis.fn_mis_khajane_credit_status_report_cc(_districtcode bigint[] DEFAULT '{}'::bigint[], _srocode bigint[] DEFAULT '{}'::bigint[], _fromdate date DEFAULT NULL::date, _todate date DEFAULT NULL::date) RETURNS TABLE(dr text, sr text, document_registered bigint, amount_credited_to_khajane_doc_registered numeric, yet_to_be_registered bigint, amount_credited_to_khajane_doc_not_registered numeric, total_documents bigint, amount_credited_to_khajane numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF _fromdate IS NULL OR _todate IS NULL THEN
        RAISE EXCEPTION 'From date and To date are mandatory';
    END IF;

    RETURN QUERY
    WITH app_level AS (
        SELECT
            dm.districtnamee::text AS dr,
            s.sronamee::text AS sr,
            COALESCE(e.applicationnumber, ca.applicationnumber, ca.ccid::text) AS application_ref,

            BOOL_OR(ca.signeddatetime IS NOT NULL) AS isregistrationcompleted,

            SUM(COALESCE(b.amount, 0)::numeric) AS credited_amount

        FROM kaveri.ams_reg_epaymentbankackdetails b
        JOIN kaveri.ams_reg_epaymenttransdetails e
            ON e.deptreferencecode = b.deptreferencecode
           AND COALESCE(e.isdelete, false) = false
           AND e.ccid IS NOT NULL

        LEFT JOIN kaveri.cc_applicationdetails ca
            ON ca.ccid = e.ccid

        LEFT JOIN kaveri.applicantapplicationdetails a
            ON a.applicationnumber = COALESCE(e.applicationnumber, ca.applicationnumber)
           AND COALESCE(a.isdeleted, false) = false

        LEFT JOIN kaveri.sromaster s
            ON s.srocode = ca.kaverisrocode

        LEFT JOIN kaveri.districtmaster dm
            ON dm.districtcode = s.districtcode

        WHERE b.paymentstatuscode IN ('10700066', '10700072')
          AND b.transactiontimestamp >= _fromdate::timestamp
          AND b.transactiontimestamp < (_todate::timestamp + INTERVAL '1 day')
          AND (
                CASE
                    WHEN _districtcode <> '{}' AND NOT (0 = ANY(_districtcode))
                        THEN s.districtcode = ANY(_districtcode)
                    ELSE TRUE
                END
              )
          AND (
                CASE
                    WHEN _srocode <> '{}' AND NOT (0 = ANY(_srocode))
                        THEN s.srocode = ANY(_srocode)
                    ELSE TRUE
                END
              )

        GROUP BY
            dm.districtnamee,
            s.sronamee,
            COALESCE(e.applicationnumber, ca.applicationnumber, ca.ccid::text)
    ),
    sro_level AS (
        SELECT
            al.dr,
            al.sr,

            COUNT(*) FILTER (
                WHERE al.isregistrationcompleted = true
            )::bigint AS document_registered,

            COALESCE(SUM(al.credited_amount) FILTER (
                WHERE al.isregistrationcompleted = true
            ), 0)::numeric AS amount_credited_to_khajane_doc_registered,

            COUNT(*) FILTER (
                WHERE al.isregistrationcompleted = false
            )::bigint AS yet_to_be_registered,

            COALESCE(SUM(al.credited_amount) FILTER (
                WHERE al.isregistrationcompleted = false
            ), 0)::numeric AS amount_credited_to_khajane_doc_not_registered,

            COALESCE(SUM(al.credited_amount), 0)::numeric AS amount_credited_to_khajane

        FROM app_level al
        GROUP BY
            al.dr,
            al.sr
    )
    SELECT
        CASE
            WHEN GROUPING(sl.dr) = 1 THEN 'Consolidated'
            ELSE COALESCE(sl.dr, '')
        END AS dr,

        CASE
            WHEN GROUPING(sl.dr) = 1 THEN ''
            ELSE COALESCE(sl.sr, '')
        END AS sr,

        SUM(COALESCE(sl.document_registered, 0))::bigint AS document_registered,

        SUM(COALESCE(sl.amount_credited_to_khajane_doc_registered, 0))::numeric
            AS amount_credited_to_khajane_doc_registered,

        SUM(COALESCE(sl.yet_to_be_registered, 0))::bigint AS yet_to_be_registered,

        SUM(COALESCE(sl.amount_credited_to_khajane_doc_not_registered, 0))::numeric
            AS amount_credited_to_khajane_doc_not_registered,

        (
            SUM(COALESCE(sl.document_registered, 0)) +
            SUM(COALESCE(sl.yet_to_be_registered, 0))
        )::bigint AS total_documents,

        SUM(COALESCE(sl.amount_credited_to_khajane, 0))::numeric AS amount_credited_to_khajane

    FROM sro_level sl
    GROUP BY GROUPING SETS ((sl.dr, sl.sr), ())
    ORDER BY
        CASE WHEN GROUPING(sl.dr) = 1 THEN 0 ELSE 1 END,
        sl.dr,
        sl.sr;

END;
$$;


ALTER FUNCTION kaverimis.fn_mis_khajane_credit_status_report_cc(_districtcode bigint[], _srocode bigint[], _fromdate date, _todate date) OWNER TO manjunathswamy;

--
-- Name: fn_mis_khajane_credit_status_report_ec(bigint[], bigint[], date, date); Type: FUNCTION; Schema: kaverimis; Owner: manjunathswamy
--

CREATE FUNCTION kaverimis.fn_mis_khajane_credit_status_report_ec(_districtcode bigint[] DEFAULT '{}'::bigint[], _srocode bigint[] DEFAULT '{}'::bigint[], _fromdate date DEFAULT NULL::date, _todate date DEFAULT NULL::date) RETURNS TABLE(dr text, sr text, document_registered bigint, amount_credited_to_khajane_doc_registered numeric, yet_to_be_registered bigint, amount_credited_to_khajane_doc_not_registered numeric, total_documents bigint, amount_credited_to_khajane numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF _fromdate IS NULL OR _todate IS NULL THEN
        RAISE EXCEPTION 'From date and To date are mandatory';
    END IF;

    RETURN QUERY
    WITH app_level AS (
        SELECT
            dm.districtnamee::text AS dr,
            s.sronamee::text AS sr,
            COALESCE(e.applicationnumber, ea.applicationnumber, ea.ecid::text) AS application_ref,
            BOOL_OR(ea.signeddatetime IS NOT NULL) AS isregistrationcompleted,
            SUM(COALESCE(b.amount, 0)::numeric) AS credited_amount
        FROM kaveri.ams_reg_epaymentbankackdetails b
        JOIN kaveri.ams_reg_epaymenttransdetails e
            ON e.deptreferencecode = b.deptreferencecode
           AND COALESCE(e.isdelete, false) = false
           AND e.ecid IS NOT NULL
        LEFT JOIN kaveri.ec_applicationdetails ea
            ON ea.ecid = e.ecid
        LEFT JOIN kaveri.sromaster s
            ON s.srocode = ea.kaverisrocode
        LEFT JOIN kaveri.districtmaster dm
            ON dm.districtcode = s.districtcode
        WHERE b.paymentstatuscode IN ('10700066', '10700072')
          AND b.transactiontimestamp >= _fromdate::timestamp
          AND b.transactiontimestamp < (_todate::timestamp + INTERVAL '1 day')

          AND (
                CASE
                    WHEN _districtcode <> '{}' AND NOT (0 = ANY(_districtcode))
                        THEN s.districtcode = ANY(_districtcode)
                    ELSE TRUE
                END
              )
          AND (
                CASE
                    WHEN _srocode <> '{}' AND NOT (0 = ANY(_srocode))
                        THEN s.srocode = ANY(_srocode)
                    ELSE TRUE
                END
              )

        GROUP BY
            dm.districtnamee,
            s.sronamee,
            COALESCE(e.applicationnumber, ea.applicationnumber, ea.ecid::text)
    ),
    sro_level AS (
        SELECT
            al.dr,
            al.sr,

            COUNT(*) FILTER (
                WHERE al.isregistrationcompleted = true
            )::bigint AS document_registered,

            COALESCE(SUM(al.credited_amount) FILTER (
                WHERE al.isregistrationcompleted = true
            ), 0)::numeric AS amount_credited_to_khajane_doc_registered,

            COUNT(*) FILTER (
                WHERE al.isregistrationcompleted = false
            )::bigint AS yet_to_be_registered,

            COALESCE(SUM(al.credited_amount) FILTER (
                WHERE al.isregistrationcompleted = false
            ), 0)::numeric AS amount_credited_to_khajane_doc_not_registered,

            COALESCE(SUM(al.credited_amount), 0)::numeric AS amount_credited_to_khajane

        FROM app_level al
        GROUP BY al.dr, al.sr
    )
    SELECT
        CASE
            WHEN GROUPING(sl.dr) = 1 THEN 'Consolidated'
            ELSE COALESCE(sl.dr, '')
        END AS dr,

        CASE
            WHEN GROUPING(sl.dr) = 1 THEN ''
            ELSE COALESCE(sl.sr, '')
        END AS sr,

        SUM(COALESCE(sl.document_registered, 0))::bigint AS document_registered,

        SUM(COALESCE(sl.amount_credited_to_khajane_doc_registered, 0))::numeric
            AS amount_credited_to_khajane_doc_registered,

        SUM(COALESCE(sl.yet_to_be_registered, 0))::bigint AS yet_to_be_registered,

        SUM(COALESCE(sl.amount_credited_to_khajane_doc_not_registered, 0))::numeric
            AS amount_credited_to_khajane_doc_not_registered,

        (
            SUM(COALESCE(sl.document_registered, 0)) +
            SUM(COALESCE(sl.yet_to_be_registered, 0))
        )::bigint AS total_documents,

        SUM(COALESCE(sl.amount_credited_to_khajane, 0))::numeric AS amount_credited_to_khajane

    FROM sro_level sl
    GROUP BY GROUPING SETS ((sl.dr, sl.sr), ())
    ORDER BY
        CASE WHEN GROUPING(sl.dr) = 1 THEN 0 ELSE 1 END,
        sl.dr,
        sl.sr;

END;
$$;


ALTER FUNCTION kaverimis.fn_mis_khajane_credit_status_report_ec(_districtcode bigint[], _srocode bigint[], _fromdate date, _todate date) OWNER TO manjunathswamy;

--
-- Name: fn_mis_liability_note(integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_liability_note(_srocode integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(sroname character varying, drofficename character varying, drorder character varying, drdate timestamp without time zone, documentnumber integer, stampduty numeric, registrationfee numeric, totalamount numeric, status text, remarks text, propertydetails text)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);		
	return query 
select distinct 
b.sronamee as sroname,
c.districtnamee as drofficename,
d.ordernumber as drorder,
orderissuedate as drdate,
e.documentnumber,
case when f.feerulecode = 36 then
(f.sroamountrequired - - f.amountpaid)
else 0 end as stampduty,
(case when f.feerulecode = 1 then
( f.sroamountrequired  - f.amountpaid)  
 else 0 end)  as registrationfee,
(case when f.feerulecode = 36 then
 (f.sroamountrequired - f.amountpaid)  
 else 0 end +
case when f.feerulecode = 1 then
 (f.sroamountrequired - f.amountpaid) 
 else 0 end) as Totalamount,
h.wrkflowstatusnamee as status,
g.remarks,
null::text as propertydetails
from kaveri.liabilitydetails a left join kaveri.sromaster b on a.srocode = b.srocode
left join kaveri.districtmaster c on b.districtcode = c.districtcode
left join kaveri.liabilityonpropertydetails d on a.liabilityid = d.liabilityid
left join kaveri.documentmaster e on d.documentid = e.documentid
left join kaveri.feesrequired f on e.applicationnumber = f.applicationnumber
left join kaveri.applicantapplicationdetails g on f.applicationnumber = g.applicationnumber
left join kaveri.wrkflowmaster h on g.currentstatus = wrkflowstatusid
where e.documentnumber is not null and a.srocode > 0
and a.srocode = _srocode;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_liability_note(_srocode integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_liability_note(bigint, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_liability_note(_districtcode bigint, _srocode integer, _fromdt timestamp without time zone, _todt timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(sroname character varying, drofficename character varying, drorder character varying, drdate text, propertydetails text, documentnumber integer, deficitstampduty numeric, deficitregistrationfee numeric, deficittotalamount numeric, status text, remarks character varying, totalcount bigint)
    LANGUAGE plpgsql
    AS $$


DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
if _districtcode=0 then --All District
		
		return query 
		 with cte as (select 
			distinct  
			s.sronamee,
			d.districtnamee,
			lop.ORDERNUMBER,
			to_char(lp.orderissuedate,'YYYY-MM-DD'),
			ps.SCHEDULETYPE ||' '||ps.DESCRIPTION AS PROPERTY_DETAILS,
			a.documentnumber,
			case when f.feerulecode = 36 then (f.sroamountrequired - f.amountpaid) else 0 end as deficitstampduty,
			(case when f2.feerulecode = 1 then	( f2.sroamountrequired  - f2.amountpaid)   else 0 end)  as deficitregistrationfee,
			(case when f.feerulecode = 36 then	 (f.sroamountrequired - f.amountpaid) else 0 end +
			case when f2.feerulecode = 1 then	 (f2.sroamountrequired - f2.amountpaid)	 else 0 end) as deficitTotalamount,
			h.wrkflowstatusnamee as status,
			lop.liabilitynote as remarks

			  from    
			  kaveri.districtmaster d 
			  join kaveri.sromaster s on d.districtcode=s.districtcode 
			  --and s.districtcode=_districtcode and s.srocode=_srocode
			  join kaveri.propertyschedules ps	on ps.srocode=s.srocode 
			  join kaveri.propertynumberdetails pn on  pn.propertyid=ps.propertyid 
			  join kaveri.LIABILITYONPROPERTYDETAILS lp	  on pn.propertyid=lp.propertyid 	
			  join kaveri.liabilitydetails lop on lp.liabilityid=lop.liabilityid
			  join kaveri.documentmaster a on a.applicationnumber=ps.applicationnumber
			  join kaveri.propertymaster p on p.propertyid=lp.propertyid
			  join kaveri.feesrequired f on f.applicationnumber=ps.applicationnumber
			  join kaveri.feesrequired f2 on f2.applicationnumber=ps.applicationnumber
			  join kaveri.applicantapplicationdetails g on f.applicationnumber  = g.applicationnumber 
			  join kaveri.wrkflowmaster h on g.currentstatus = h.wrkflowstatusid
			  
			  where 
			  --ps.applicationnumber=A.applicationnumber and pn.srocode=a.srocode  and 
			  f.feerulecode=36 and f2.feerulecode=1 
			  and a.srocode > 0 and lp.inserteddatetime::date>=_fromdt and lp.inserteddatetime::date<=_todt
			  group by d.districtnamee,
			 s.sronamee,lp.orderissuedate,a.documentnumber,f.feerulecode,f.sroamountrequired,f.amountpaid,h.wrkflowstatusnamee,
			  lop.ordernumber,ps.SCHEDULETYPE,ps.DESCRIPTION,lop.liabilitynote,f.applicationnumber,
			  f2.feerulecode,f2.sroamountrequired,f2.amountpaid),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
		elsif _srocode=0 then 
		
		
		return query 
		 with cte as (select 
			distinct  
			s.sronamee,
			d.districtnamee,
			lop.ORDERNUMBER,
			to_char(lp.orderissuedate,'YYYY-MM-DD'),
			ps.SCHEDULETYPE ||' '||ps.DESCRIPTION AS PROPERTY_DETAILS,
			a.documentnumber,
			case when f.feerulecode = 36 then (f.sroamountrequired - f.amountpaid) else 0 end as deficitstampduty,
			(case when f2.feerulecode = 1 then	( f2.sroamountrequired  - f2.amountpaid)   else 0 end)  as deficitregistrationfee,
			(case when f.feerulecode = 36 then	 (f.sroamountrequired - f.amountpaid) else 0 end +
			case when f2.feerulecode = 1 then	 (f2.sroamountrequired - f2.amountpaid)	 else 0 end) as deficitTotalamount,
			h.wrkflowstatusnamee as status,
			lop.liabilitynote as remarks

			  from    
			  kaveri.districtmaster d 
			  join kaveri.sromaster s on d.districtcode=s.districtcode 
			  and s.districtcode=_districtcode 
			  --and s.srocode=_srocode
			  join kaveri.propertyschedules ps	on ps.srocode=s.srocode 
			  join kaveri.propertynumberdetails pn on  pn.propertyid=ps.propertyid 
			  join kaveri.LIABILITYONPROPERTYDETAILS lp	  on pn.propertyid=lp.propertyid 	
			  join kaveri.liabilitydetails lop on lp.liabilityid=lop.liabilityid
			  join kaveri.documentmaster a on a.applicationnumber=ps.applicationnumber
			  join kaveri.propertymaster p on p.propertyid=lp.propertyid
			  join kaveri.feesrequired f on f.applicationnumber=ps.applicationnumber
			  join kaveri.feesrequired f2 on f2.applicationnumber=ps.applicationnumber
			  join kaveri.applicantapplicationdetails g on f.applicationnumber  = g.applicationnumber 
			  join kaveri.wrkflowmaster h on g.currentstatus = h.wrkflowstatusid
			  
			  where 
			  --ps.applicationnumber=A.applicationnumber and pn.srocode=a.srocode  and 
			  f.feerulecode=36 and f2.feerulecode=1 
			  and a.srocode > 0 and lp.inserteddatetime::date>=_fromdt and lp.inserteddatetime::date<=_todt
			  group by d.districtnamee,
			 s.sronamee,lp.orderissuedate,a.documentnumber,f.feerulecode,f.sroamountrequired,f.amountpaid,h.wrkflowstatusnamee,
			  lop.ordernumber,ps.SCHEDULETYPE,ps.DESCRIPTION,lop.liabilitynote,f.applicationnumber,
			  f2.feerulecode,f2.sroamountrequired,f2.amountpaid),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
		ELSE
		
		
		return query 
		 with cte as (select 
			distinct  
			s.sronamee,
			d.districtnamee,
			lop.ORDERNUMBER,
			to_char(lp.orderissuedate,'YYYY-MM-DD'),
			ps.SCHEDULETYPE ||' '||ps.DESCRIPTION AS PROPERTY_DETAILS,
			a.documentnumber,
			case when f.feerulecode = 36 then (f.sroamountrequired - f.amountpaid) else 0 end as deficitstampduty,
			(case when f2.feerulecode = 1 then	( f2.sroamountrequired  - f2.amountpaid)   else 0 end)  as deficitregistrationfee,
			(case when f.feerulecode = 36 then	 (f.sroamountrequired - f.amountpaid) else 0 end +
			case when f2.feerulecode = 1 then	 (f2.sroamountrequired - f2.amountpaid)	 else 0 end) as deficitTotalamount,
			h.wrkflowstatusnamee as status,
			lop.liabilitynote as remarks

			  from    
			  kaveri.districtmaster d 
			  join kaveri.sromaster s on d.districtcode=s.districtcode 
			  and s.districtcode=_districtcode and s.srocode=_srocode
			  join kaveri.propertyschedules ps	on ps.srocode=s.srocode 
			  join kaveri.propertynumberdetails pn on  pn.propertyid=ps.propertyid 
			  join kaveri.LIABILITYONPROPERTYDETAILS lp	  on pn.propertyid=lp.propertyid 	
			  join kaveri.liabilitydetails lop on lp.liabilityid=lop.liabilityid
			  join kaveri.documentmaster a on a.applicationnumber=ps.applicationnumber
			  join kaveri.propertymaster p on p.propertyid=lp.propertyid
			  join kaveri.feesrequired f on f.applicationnumber=ps.applicationnumber
			  join kaveri.feesrequired f2 on f2.applicationnumber=ps.applicationnumber
			  join kaveri.applicantapplicationdetails g on f.applicationnumber  = g.applicationnumber 
			  join kaveri.wrkflowmaster h on g.currentstatus = h.wrkflowstatusid
			  
			  where 
			  --ps.applicationnumber=A.applicationnumber and pn.srocode=a.srocode  and 
			  f.feerulecode=36 and f2.feerulecode=1 
			  and a.srocode > 0 and lp.inserteddatetime::date>=_fromdt and lp.inserteddatetime::date<=_todt
			  group by d.districtnamee,
			 s.sronamee,lp.orderissuedate,a.documentnumber,f.feerulecode,f.sroamountrequired,f.amountpaid,h.wrkflowstatusnamee,
			  lop.ordernumber,ps.SCHEDULETYPE,ps.DESCRIPTION,lop.liabilitynote,f.applicationnumber,f2.feerulecode,
			  f2.sroamountrequired,f2.amountpaid),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
	end if;
END;
$$;


