ALTER FUNCTION kaverimis.fn_mis_liability_note_23012024(_srocode integer, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_liability_note_23012024(bigint, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_liability_note_23012024(_districtcode bigint, _srocode integer, _fromdt timestamp without time zone, _todt timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(sroname character varying, drofficename character varying, drorder character varying, drdate text, propertydetails text, documentnumber integer, deficitstampduty numeric, deficitregistrationfee numeric, deficittotalamount numeric, status text, remarks character varying)
    LANGUAGE plpgsql
    AS $$


DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
if _districtcode=0 then --All District
		
		return query 
		 select 
			distinct  
			s.sronamee,
			d.districtnamee,
			lop.ORDERNUMBER,
			to_char(lp.orderissuedate,'YYYY-MM-DD'),
			ps.SCHEDULETYPE ||' '||ps.DESCRIPTION AS PROPERTY_DETAILS,
			a.documentnumber,
			case when f.feerulecode = 36 then (f.sroamountrequired - f.amountpaid) else 0 end as deficitstampduty,
			(case when f2.feerulecode = 1 then	( f2.sroamountrequired  - f2.amountpaid)   else 0 end)  as deficitregistrationfee,
			(case when f.feerulecode = 36 then	 (f.sroamountrequired - f.amountpaid) else 0 end +
			case when f2.feerulecode = 1 then	 (f2.sroamountrequired - f2.amountpaid)	 else 0 end) as deficitTotalamount,
			h.wrkflowstatusnamee as status,
			lop.liabilitynote as remarks

			  from    
			  kaveri.districtmaster d 
			  join kaveri.sromaster s on d.districtcode=s.districtcode 
			  --and s.districtcode=_districtcode and s.srocode=_srocode
			  join kaveri.propertyschedules ps	on ps.srocode=s.srocode 
			  join kaveri.propertynumberdetails pn on  pn.propertyid=ps.propertyid 
			  join kaveri.LIABILITYONPROPERTYDETAILS lp	  on pn.propertyid=lp.propertyid 	
			  join kaveri.liabilitydetails lop on lp.liabilityid=lop.liabilityid
			  join kaveri.documentmaster a on a.applicationnumber=ps.applicationnumber
			  join kaveri.propertymaster p on p.propertyid=lp.propertyid
			  join kaveri.feesrequired f on f.applicationnumber=ps.applicationnumber
			  join kaveri.feesrequired f2 on f2.applicationnumber=ps.applicationnumber
			  join kaveri.applicantapplicationdetails g on f.applicationnumber  = g.applicationnumber 
			  join kaveri.wrkflowmaster h on g.currentstatus = h.wrkflowstatusid
			  
			  where 
			  --ps.applicationnumber=A.applicationnumber and pn.srocode=a.srocode  and 
			  f.feerulecode=36 and f2.feerulecode=1 
			  and a.srocode > 0 and lp.inserteddatetime::date>=_fromdt and lp.inserteddatetime::date<=_todt
			  group by d.districtnamee,
			 s.sronamee,lp.orderissuedate,a.documentnumber,f.feerulecode,f.sroamountrequired,f.amountpaid,h.wrkflowstatusnamee,
			  lop.ordernumber,ps.SCHEDULETYPE,ps.DESCRIPTION,lop.liabilitynote,f.applicationnumber,f2.feerulecode,f2.sroamountrequired,f2.amountpaid;
		
		elsif _srocode=0 then 
		
		
		return query 
		 select 
			distinct  
			s.sronamee,
			d.districtnamee,
			lop.ORDERNUMBER,
			to_char(lp.orderissuedate,'YYYY-MM-DD'),
			ps.SCHEDULETYPE ||' '||ps.DESCRIPTION AS PROPERTY_DETAILS,
			a.documentnumber,
			case when f.feerulecode = 36 then (f.sroamountrequired - f.amountpaid) else 0 end as deficitstampduty,
			(case when f2.feerulecode = 1 then	( f2.sroamountrequired  - f2.amountpaid)   else 0 end)  as deficitregistrationfee,
			(case when f.feerulecode = 36 then	 (f.sroamountrequired - f.amountpaid) else 0 end +
			case when f2.feerulecode = 1 then	 (f2.sroamountrequired - f2.amountpaid)	 else 0 end) as deficitTotalamount,
			h.wrkflowstatusnamee as status,
			lop.liabilitynote as remarks

			  from    
			  kaveri.districtmaster d 
			  join kaveri.sromaster s on d.districtcode=s.districtcode 
			  and s.districtcode=_districtcode 
			  --and s.srocode=_srocode
			  join kaveri.propertyschedules ps	on ps.srocode=s.srocode 
			  join kaveri.propertynumberdetails pn on  pn.propertyid=ps.propertyid 
			  join kaveri.LIABILITYONPROPERTYDETAILS lp	  on pn.propertyid=lp.propertyid 	
			  join kaveri.liabilitydetails lop on lp.liabilityid=lop.liabilityid
			  join kaveri.documentmaster a on a.applicationnumber=ps.applicationnumber
			  join kaveri.propertymaster p on p.propertyid=lp.propertyid
			  join kaveri.feesrequired f on f.applicationnumber=ps.applicationnumber
			  join kaveri.feesrequired f2 on f2.applicationnumber=ps.applicationnumber
			  join kaveri.applicantapplicationdetails g on f.applicationnumber  = g.applicationnumber 
			  join kaveri.wrkflowmaster h on g.currentstatus = h.wrkflowstatusid
			  
			  where 
			  --ps.applicationnumber=A.applicationnumber and pn.srocode=a.srocode  and 
			  f.feerulecode=36 and f2.feerulecode=1 
			  and a.srocode > 0 and lp.inserteddatetime::date>=_fromdt and lp.inserteddatetime::date<=_todt
			  group by d.districtnamee,
			 s.sronamee,lp.orderissuedate,a.documentnumber,f.feerulecode,f.sroamountrequired,f.amountpaid,h.wrkflowstatusnamee,
			  lop.ordernumber,ps.SCHEDULETYPE,ps.DESCRIPTION,lop.liabilitynote,f.applicationnumber,f2.feerulecode,f2.sroamountrequired,f2.amountpaid;
		
		ELSE
		
		
		return query 
		 select 
			distinct  
			s.sronamee,
			d.districtnamee,
			lop.ORDERNUMBER,
			to_char(lp.orderissuedate,'YYYY-MM-DD'),
			ps.SCHEDULETYPE ||' '||ps.DESCRIPTION AS PROPERTY_DETAILS,
			a.documentnumber,
			case when f.feerulecode = 36 then (f.sroamountrequired - f.amountpaid) else 0 end as deficitstampduty,
			(case when f2.feerulecode = 1 then	( f2.sroamountrequired  - f2.amountpaid)   else 0 end)  as deficitregistrationfee,
			(case when f.feerulecode = 36 then	 (f.sroamountrequired - f.amountpaid) else 0 end +
			case when f2.feerulecode = 1 then	 (f2.sroamountrequired - f2.amountpaid)	 else 0 end) as deficitTotalamount,
			h.wrkflowstatusnamee as status,
			lop.liabilitynote as remarks

			  from    
			  kaveri.districtmaster d 
			  join kaveri.sromaster s on d.districtcode=s.districtcode 
			  and s.districtcode=_districtcode and s.srocode=_srocode
			  join kaveri.propertyschedules ps	on ps.srocode=s.srocode 
			  join kaveri.propertynumberdetails pn on  pn.propertyid=ps.propertyid 
			  join kaveri.LIABILITYONPROPERTYDETAILS lp	  on pn.propertyid=lp.propertyid 	
			  join kaveri.liabilitydetails lop on lp.liabilityid=lop.liabilityid
			  join kaveri.documentmaster a on a.applicationnumber=ps.applicationnumber
			  join kaveri.propertymaster p on p.propertyid=lp.propertyid
			  join kaveri.feesrequired f on f.applicationnumber=ps.applicationnumber
			  join kaveri.feesrequired f2 on f2.applicationnumber=ps.applicationnumber
			  join kaveri.applicantapplicationdetails g on f.applicationnumber  = g.applicationnumber 
			  join kaveri.wrkflowmaster h on g.currentstatus = h.wrkflowstatusid
			  
			  where 
			  --ps.applicationnumber=A.applicationnumber and pn.srocode=a.srocode  and 
			  f.feerulecode=36 and f2.feerulecode=1 
			  and a.srocode > 0 and lp.inserteddatetime::date>=_fromdt and lp.inserteddatetime::date<=_todt
			  group by d.districtnamee,
			 s.sronamee,lp.orderissuedate,a.documentnumber,f.feerulecode,f.sroamountrequired,f.amountpaid,h.wrkflowstatusnamee,
			  lop.ordernumber,ps.SCHEDULETYPE,ps.DESCRIPTION,lop.liabilitynote,f.applicationnumber,f2.feerulecode,f2.sroamountrequired,f2.amountpaid;
	end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_liability_note_23012024(_districtcode bigint, _srocode integer, _fromdt timestamp without time zone, _todt timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_liabilityreport(bigint, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_liabilityreport(_srocode bigint, _fromdt timestamp without time zone, _todt timestamp without time zone) RETURNS TABLE(sroname character varying, district_name character varying, drorder character varying, drdate timestamp without time zone, propertyid bigint, stampduty numeric, registrationfees numeric, totalfees numeric, status text, remarks text)
    LANGUAGE plpgsql
    AS $$
begin
return query
select Distinct s.sronamee as sroname
,d.districtnamee as districtname
,lp.ordernumber as Drorder
,lp.orderissuedate as Drdate
,lp.propertyid as propertynumber
,case when f.feerulecode=36 then sum(f.amountrequired) else 0 end as stamp_duty
,case when f.feerulecode=1 then sum(f.amountrequired) else 0 end as registration_fees
,case when f.feerulecode in (36,1) then sum(f.amountrequired) else 0 end as totalfees
,h.wrkflowstatusnamee  as status
,null as remarks
from kaveri.liabilityonpropertydetails lp
left join kaveri.sromaster s on lp.srocode=s.srocode
left join kaveri.districtmaster d on d.districtcode=s.districtcode
left join kaveri.feesrequired f on f.documentid=lp.documentid
left join kaveri.applicantapplicationdetails g on f.applicationnumber = g.applicationnumber
left join kaveri.wrkflowmaster h on g.currentstatus = h.wrkflowstatusid 
where lp.srocode=_srocode and lp.orderissuedate>=_fromdt and lp.orderissuedate<=_todt
group by s.sronamee,d.districtnamee,lp.ordernumber,lp.propertyid,lp.orderissuedate,f.feerulecode,h.wrkflowstatusnamee;
end;
$$;


ALTER FUNCTION kaverimis.fn_mis_liabilityreport(_srocode bigint, _fromdt timestamp without time zone, _todt timestamp without time zone) OWNER TO csgadmin;

--
-- Name: fn_mis_memorandum_of_document_registered_form25(bigint, timestamp without time zone, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_memorandum_of_document_registered_form25(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying DEFAULT NULL::character varying) RETURNS TABLE(finalregistrationnumber character varying, applicationnumber character varying, districtname character varying, regsroname character varying, sro character varying, serialnoofyear integer, natureofdeed text, propertydescription text, executants text, claimants text, all_date text, volumeregsro text, volumesro text, remarks text, copy_of_document text)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN	
_todate:=(_todate+'1 day'::interval);
if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
raise notice 'Documentnumber null';
return query 

select distinct 
		dm.finalregistrationnumber, 
		dm.applicationnumber, 
		c.districtnamee as districtname,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode) as regsroname,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode) as sroname,
		arl.logid as slnoyear,
		ra.articlenamee|| '  Considerationamount '||coalesce(dm.considerationamount::text,'0')  as natureofdeed_consideration,
		ps.description||' '||pm.northboundary||' '||pm.eastboundary||' '||pm.westboundary||' '||pm.southboundary as propertydescription,
		prt_ex.executants,
		prt_cl.claimants,
		to_char(dm.executiondatetime,'dd-mm-yyyy') ||','||to_char(dm.presentdatetime,'dd-mm-yyyy')||','||
		to_char(dm.registrationdatetime,'dd-mm-yyyy') as all_date ,
	    pm.noofscanpages||'  ,  '||dm.finalregistrationnumber as volumenoregsro,
	    null  as volumenosro,
		null as remarks,
		dm.uploaddocdeedpath as copy_of_document
	from kaveri.anywhere_reg_log arl
	left join kaveri.documentmaster dm on arl.applicationnumber = dm.applicationnumber
	join kaveri.registrationarticles ra on ra.regarticlecode=dm.regarticlecode
	join kaveri.sromaster b on dm.srocode = b.srocode
	join kaveri.districtmaster c on b.districtcode = c.districtcode
	left join kaveri.propertymaster pm on arl.propertyid = pm.propertyid  
	left join kaveri.propertyschedules ps on pm.propertyid = ps.propertyid 
	left JOIN ( SELECT vw.applicationnumber,
			string_agg((vw.name || ' '::text) || vw.address, ', '::text) as claimants
			FROM kaverimis.vw_mis_partyinfo vw
			WHERE vw.partytypeid = 1
			GROUP BY vw.applicationnumber) prt_cl ON prt_cl.applicationnumber::text = dm.applicationnumber::text
	left JOIN ( SELECT vw.applicationnumber,
			string_agg((vw.name || ' '::text) || vw.address, ', '::text) as executants
			FROM kaverimis.vw_mis_partyinfo vw
			WHERE vw.partytypeid = 2
			GROUP BY vw.applicationnumber) prt_ex ON prt_ex.applicationnumber::text = dm.applicationnumber::text			
	      where arl.regsrocode=_srocode and arl.ismemosent = true  AND
		  dm.registrationdatetime >=_fromdate and dm.registrationdatetime <=
		   _todate;

elseif 	_documentnumber is not NULL and (_fromdate  is NULL and _todate is NULL) then
	 
	return query
select distinct 
		dm.finalregistrationnumber, 
		dm.applicationnumber, 
		c.districtnamee as districtname,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode) as regsroname,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode) as sroname,
		arl.logid  as slnoyear,
		ra.articlenamee|| '  Considerationamount '||coalesce(dm.considerationamount::text,'0')  as natureofdeed_consideration,
		ps.description||' '||pm.northboundary||' '||pm.eastboundary||' '||pm.westboundary||' '||pm.southboundary as propertydescription,
		prt_ex.executants,
		prt_cl.claimants,
		to_char(dm.executiondatetime,'dd-mm-yyyy') ||','||to_char(dm.presentdatetime,'dd-mm-yyyy')||','||
		to_char(dm.registrationdatetime,'dd-mm-yyyy') as all_date ,
		pm.noofscanpages||'  ,  '||dm.finalregistrationnumber as volumenoregsro,
	    null  as volumenosro,
		null as remarks,
		dm.uploaddocdeedpath as copy_of_document
	from kaveri.anywhere_reg_log arl
	left join kaveri.documentmaster dm on arl.applicationnumber = dm.applicationnumber
	join kaveri.registrationarticles ra on ra.regarticlecode=dm.regarticlecode
	join kaveri.sromaster b on dm.srocode = b.srocode
	join kaveri.districtmaster c on b.districtcode = c.districtcode
	left join kaveri.propertymaster pm on arl.propertyid = pm.propertyid  
	left join kaveri.propertyschedules ps on pm.propertyid = ps.propertyid 
	left JOIN ( SELECT vw.applicationnumber,
			string_agg((vw.name || ' '::text) || vw.address, ', '::text) as claimants
			FROM kaverimis.vw_mis_partyinfo vw
			WHERE vw.partytypeid = 1
			GROUP BY vw.applicationnumber) prt_cl ON prt_cl.applicationnumber::text = dm.applicationnumber::text
	left JOIN ( SELECT vw.applicationnumber,
			string_agg((vw.name || ' '::text) || vw.address, ', '::text) as executants
			FROM kaverimis.vw_mis_partyinfo vw
			WHERE vw.partytypeid = 2
			GROUP BY vw.applicationnumber) prt_ex ON prt_ex.applicationnumber::text = dm.applicationnumber::text			
	      where arl.regsrocode=_srocode and arl.ismemosent = true  AND
		  dm.finalregistrationnumber=_documentnumber;
	
	
	
elseif _documentnumber is not NULL and (_fromdate is not NULL and _todate is not NULL) then

raise notice 'nothing null';
return query

select distinct 
		dm.finalregistrationnumber, 
		dm.applicationnumber, 
		c.districtnamee as districtname,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode) as regsroname,
		(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode) as sroname,
		arl.logid  as slnoyear,
		ra.articlenamee|| '  Considerationamount '||coalesce(dm.considerationamount::text,'0')  as natureofdeed_consideration,
		ps.description||' '||pm.northboundary||' '||pm.eastboundary||' '||pm.westboundary||' '||pm.southboundary as propertydescription,
		prt_ex.executants,
		prt_cl.claimants,
		to_char(dm.executiondatetime,'dd-mm-yyyy') ||','||to_char(dm.presentdatetime,'dd-mm-yyyy')||','||
		to_char(dm.registrationdatetime,'dd-mm-yyyy') as all_date ,
		pm.noofscanpages||'  ,  '||dm.finalregistrationnumber as volumenoregsro,
	    null  as volumenosro,
		null as remarks,
		dm.uploaddocdeedpath as copy_of_document
	from kaveri.anywhere_reg_log arl
	left join kaveri.documentmaster dm on arl.applicationnumber = dm.applicationnumber
	join kaveri.registrationarticles ra on ra.regarticlecode=dm.regarticlecode
	join kaveri.sromaster b on dm.srocode = b.srocode
	join kaveri.districtmaster c on b.districtcode = c.districtcode
	left join kaveri.propertymaster pm on arl.propertyid = pm.propertyid  
	left join kaveri.propertyschedules ps on pm.propertyid = ps.propertyid 
	left JOIN ( SELECT vw.applicationnumber,
			string_agg((vw.name || ' '::text) || vw.address, ', '::text) as claimants
			FROM kaverimis.vw_mis_partyinfo vw
			WHERE vw.partytypeid = 1
			GROUP BY vw.applicationnumber) prt_cl ON prt_cl.applicationnumber::text = dm.applicationnumber::text
	left JOIN ( SELECT vw.applicationnumber,
			string_agg((vw.name || ' '::text) || vw.address, ', '::text) as executants
			FROM kaverimis.vw_mis_partyinfo vw
			WHERE vw.partytypeid = 2
			GROUP BY vw.applicationnumber) prt_ex ON prt_ex.applicationnumber::text = dm.applicationnumber::text			
	      where arl.regsrocode=_srocode and arl.ismemosent = true  AND
		  dm.registrationdatetime >=_fromdate and dm.registrationdatetime <=
		   _todate and dm.finalregistrationnumber=_documentnumber;
else

raise notice 'condition failed';
end if;

END;
$$;


ALTER FUNCTION kaverimis.fn_mis_memorandum_of_document_registered_form25(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_mis_memorandum_of_document_registered_form25(integer, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_memorandum_of_document_registered_form25(_districtcode integer, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying DEFAULT NULL::character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(finalregistrationnumber character varying, applicationnumber character varying, districtname character varying, regsroname character varying, sro character varying, serialnoofyear integer, natureofdeed text, propertydescription text, executants text, claimants text, all_date text, volumeregsro text, volumesro text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
	

if pagenumber <> -1 and pagesize <> -1 then

			return query 

			with cte as (select distinct 
					dm.finalregistrationnumber, 
					dm.applicationnumber, 
					c.districtnamee as districtname,
					(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode) as regsroname,
					(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode) as sroname,
					arl.logid as slnoyear,
					ra.articlenamee|| '  Considerationamount '||coalesce(pm.sroconsideration::text,pm.consideration::text)  as natureofdeed_consideration,
					ps.description||' '||pm.northboundary||' '||pm.eastboundary||' '||pm.westboundary||' '||pm.southboundary as propertydescription,
					string_agg( distinct case when pr.partytypeid = 2 then 
					concat_ws(' '::text, pr.firstname, pr.middlename, pr.lastname) || ' '::text 
					|| concat_ws(' '::text, (((((pr.housenumber || ', '::text) || pr.address::text) || ', '::text) ||
					kaveri.fn_fetch_address_village(pr.talukcode::bigint)) || ' - '::text) || pr.pin) end,',' ) as executants ,
					string_agg( distinct case when pr.partytypeid = 1 then 
					concat_ws(' '::text, pr.firstname, pr.middlename, pr.lastname) || ' '::text 
					|| concat_ws(' '::text, (((((pr.housenumber || ', '::text) || pr.address::text) || ', '::text) ||
					kaveri.fn_fetch_address_village(pr.talukcode::bigint)) || ' - '::text) || pr.pin) end,',' ) as claimants ,
					to_char(dm.executiondatetime,'dd-mm-yyyy') ||','||to_char(dm.presentdatetime,'dd-mm-yyyy')||','||
					to_char(dm.registrationdatetime,'dd-mm-yyyy') as all_date ,
					pm.noofscanpages||'  ,  '||dm.finalregistrationnumber as volumenoregsro,
					null  as volumenosro,
					null as remarks,
					dm.uploaddocdeedpath as copy_of_document
				from kaveri.anywhere_reg_log arl
				left join kaveri.documentmaster dm on arl.applicationnumber = dm.applicationnumber
				left join kaveri.registrationarticles ra on dm.regarticlecode=ra.regarticlecode
				join kaveri.sromaster b on dm.srocode = b.srocode
				join kaveri.districtmaster c on b.districtcode = c.districtcode
				left join kaveri.propertymaster pm on arl.propertyid = pm.propertyid  
				left join kaveri.propertyschedules ps on pm.propertyid = ps.propertyid 
				left join kaveri.partyinfo pr on dm.applicationnumber=pr.applicationnumber 
				
				where arl.ismemosent = true  AND
					  (dm.registrationdatetime between _fromdate and   _todate+ INTERVAL '1 day')
					  and (case  when _districtcode<>0 then c.districtcode=_districtcode  ELSE  true end)
						and (case  when _srocode<> 0 then dm.srocode=_srocode  ELSE  true end)
				group by dm.finalregistrationnumber,dm.applicationnumber,districtname,regsroname,
				sroname,slnoyear,natureofdeed_consideration,propertydescription,dm.executiondatetime,dm.presentdatetime,
				dm.registrationdatetime,pm.noofscanpages,dm.uploaddocdeedpath),
				cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
			
			
elsif pagenumber = -1 or  pagesize = -1 then  

return query 

			with cte as (select distinct 
					dm.finalregistrationnumber, 
					dm.applicationnumber, 
					c.districtnamee as districtname,
					(select sronamee from kaveri.sromaster s where s.srocode=arl.regsrocode) as regsroname,
					(select sronamee from kaveri.sromaster s where s.srocode=arl.srocode) as sroname,
					arl.logid as slnoyear,
					ra.articlenamee|| '  Considerationamount '||coalesce(pm.sroconsideration::text,pm.consideration::text)  as natureofdeed_consideration,
					ps.description||' '||pm.northboundary||' '||pm.eastboundary||' '||pm.westboundary||' '||pm.southboundary as propertydescription,
					string_agg( distinct case when pr.partytypeid = 2 then 
					concat_ws(' '::text, pr.firstname, pr.middlename, pr.lastname) || ' '::text 
					|| concat_ws(' '::text, (((((pr.housenumber || ', '::text) || pr.address::text) || ', '::text) ||
					kaveri.fn_fetch_address_village(pr.talukcode::bigint)) || ' - '::text) || pr.pin) end,',' ) as executants ,
					string_agg( distinct case when pr.partytypeid = 1 then 
					concat_ws(' '::text, pr.firstname, pr.middlename, pr.lastname) || ' '::text 
					|| concat_ws(' '::text, (((((pr.housenumber || ', '::text) || pr.address::text) || ', '::text) ||
					kaveri.fn_fetch_address_village(pr.talukcode::bigint)) || ' - '::text) || pr.pin) end,',' ) as claimants ,
					to_char(dm.executiondatetime,'dd-mm-yyyy') ||','||to_char(dm.presentdatetime,'dd-mm-yyyy')||','||
					to_char(dm.registrationdatetime,'dd-mm-yyyy') as all_date ,
					pm.noofscanpages||'  ,  '||dm.finalregistrationnumber as volumenoregsro,
					null  as volumenosro,
					null as remarks,
					dm.uploaddocdeedpath as copy_of_document
				from kaveri.anywhere_reg_log arl
				left join kaveri.documentmaster dm on arl.applicationnumber = dm.applicationnumber
				left join kaveri.registrationarticles ra on dm.regarticlecode=ra.regarticlecode
				join kaveri.sromaster b on dm.srocode = b.srocode
				join kaveri.districtmaster c on b.districtcode = c.districtcode
				left join kaveri.propertymaster pm on arl.propertyid = pm.propertyid  
				left join kaveri.propertyschedules ps on pm.propertyid = ps.propertyid 
				left join kaveri.partyinfo pr on dm.applicationnumber=pr.applicationnumber 
				
				where arl.ismemosent = true  AND
					  (dm.registrationdatetime between _fromdate and   _todate+ INTERVAL '1 day')
					  and (case  when _districtcode<>0 then c.districtcode=_districtcode  ELSE  true end)
						and (case  when _srocode<> 0 then dm.srocode=_srocode  ELSE  true end)
				group by dm.finalregistrationnumber,dm.applicationnumber,districtname,regsroname,
				sroname,slnoyear,natureofdeed_consideration,propertydescription,dm.executiondatetime,dm.presentdatetime,
				dm.registrationdatetime,pm.noofscanpages,dm.uploaddocdeedpath),
				cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true ;

end if;

			

END;
$$;


