CREATE FUNCTION kaverimis.fn_mis_memorandum_of_document_registered_form25_05022024(_districtcode integer, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying DEFAULT NULL::character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(finalregistrationnumber character varying, applicationnumber character varying, districtname character varying, regsroname character varying, sro character varying, serialnoofyear integer, natureofdeed text, propertydescription text, executants text, claimants text, all_date text, volumeregsro text, volumesro text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
