ALTER FUNCTION kaverimis.fn_mis_memorandum_of_document_registered_form25_05022024(_districtcode integer, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_minutebook(bigint, timestamp without time zone, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_minutebook(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying DEFAULT NULL::character varying) RETURNS TABLE(id bigint, district character varying, sro character varying, appnum character varying, minutedate text, docdatenumber text, referencedisposal character varying, remarks text, copy_of_document text)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$

DECLARE

BEGIN

_todate:=(_todate+'1 day'::interval);
if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
raise notice 'Documentnumber null';

return query
select row_number() over() as id,* from 
(select 

sub.district,
sub.sro,
sub.appnum,
sub.minutedate,
sub.docdatenumber,
sub.referencedisposal,
sub.remarks,
sub.copy_of_document
from (
select 
	d2.districtnamee as district,
	s.sronamee as sro,
	md.applicationnumber as appnum,
    TO_CHAR(md.minutedate::timestamp,'dd-mm-yyyy') as minutedate,	
	d.pendingdocumentnumber || ', ' || to_char(d.presentdatetime,'DD-MM-YYYY') as docdatenumber, 
	d.finalregistrationnumber as referencedisposal,
	a.remarks as remarks,
	d.uploaddocdeedpath as copy_of_document
	from kaveri.minutebook_data md 
	left outer join kaveri.documentmaster d on md.applicationnumber = d.applicationnumber 
	left outer join kaveri.applicantapplicationdetails a on md.applicationnumber = a.applicationnumber 
	left outer join kaveri.feesrequired f on md.applicationnumber = f.applicationnumber 
	left outer join kaveri.sromaster s on md.srocode = s.srocode 
	left outer join kaveri.districtmaster d2 on d2.districtcode = s.districtcode 
	where to_char(a.registrationstartdate, 'YYYY-MM-DD') >= to_char(_fromdate, 'YYYY-MM-DD')
	and to_char(a.registrationstartdate, 'YYYY-MM-DD') <= to_char(_todate, 'YYYY-MM-DD')
	and d.pendingdocumentnumber is not null 
	and s.srocode = _srocode
	group by 
	md.applicationnumber,
	d.pendingdocumentnumber,
	d.finalregistrationnumber,
	d.presentdatetime,
	a.remarks,
	d2.districtnamee,
	s.sronamee,md.minutedate,d.uploaddocdeedpath,md.private_remark	
	union all
	select
	d2.districtnamee as district,
	s.sronamee as sro,
	md.applicationnumber as appnum,
	TO_CHAR(md.minutedate::timestamp,'dd-mm-yyyy') as minutedate,
		d.finalregistrationnumber || ', ' || to_char(d.presentdatetime,'DD-MM-YYYY')  as docdatenumber, 
	null::character varying as referencedisposal,
	md.private_remark  as remarks,
	d.uploaddocdeedpath as copy_of_document
	from kaveri.minutebook_data md 
	left outer join kaveri.documentmaster d on md.applicationnumber = d.applicationnumber 
	left outer join kaveri.applicantapplicationdetails a on md.applicationnumber = a.applicationnumber 
	left outer join kaveri.feesrequired f on md.applicationnumber = f.applicationnumber 
	left outer join kaveri.sromaster s on md.srocode = s.srocode 
	left outer join kaveri.districtmaster d2 on d2.districtcode = s.districtcode 
	where to_char(a.registrationstartdate, 'YYYY-MM-DD') >=to_char(_fromdate, 'YYYY-MM-DD')
	and to_char(a.registrationstartdate, 'YYYY-MM-DD') <= to_char(_todate, 'YYYY-MM-DD')
	and d.finalregistrationnumber is not null
	and d.pendingdocumentnumber is not null
	and s.srocode = _srocode
	group by 
	md.applicationnumber,
	d.finalregistrationnumber,
	d.presentdatetime,
	a.remarks,
	d2.districtnamee,
	s.sronamee,md.minutedate,d.uploaddocdeedpath,md.private_remark
	) sub order by sub.appnum ) as sub2 ;	 
	
	elseif 	_documentnumber is not NULL and (_fromdate  is NULL and _todate is NULL) then
	return query
	
	select row_number() over() as id,* from 
(
select 
sub.district,
sub.sro,
sub.appnum,
sub.minutedate,
sub.docdatenumber,
sub.referencedisposal,
sub.remarks,sub.copy_of_document
from (
select 
	d2.districtnamee as district,
	s.sronamee as sro,
	md.applicationnumber as appnum,
    TO_CHAR(md.minutedate::timestamp,'dd-mm-yyyy') as minutedate,	
	d.pendingdocumentnumber || ', ' || to_char(d.presentdatetime,'DD-MM-YYYY') as docdatenumber, 
	d.finalregistrationnumber as referencedisposal,
	a.remarks  as remarks,
	d.uploaddocdeedpath as copy_of_document
	from kaveri.minutebook_data md 
	left outer join kaveri.documentmaster d on md.applicationnumber = d.applicationnumber 
	left outer join kaveri.applicantapplicationdetails a on md.applicationnumber = a.applicationnumber 
	left outer join kaveri.feesrequired f on md.applicationnumber = f.applicationnumber 
	left outer join kaveri.sromaster s on md.srocode = s.srocode 
	left outer join kaveri.districtmaster d2 on d2.districtcode = s.districtcode 
	where  (d.finalregistrationnumber=_documentnumber )
	and s.srocode = _srocode
	group by 
	md.applicationnumber,
	d.pendingdocumentnumber,
	d.finalregistrationnumber,
	d.presentdatetime,
	a.remarks,
	d2.districtnamee,
	s.sronamee,md.minutedate,d.uploaddocdeedpath,md.private_remark	
	union all
	select
	d2.districtnamee as district,
	s.sronamee as sro,
	md.applicationnumber as appnum,
	TO_CHAR(md.minutedate::timestamp,'dd-mm-yyyy') as minutedate,
		d.finalregistrationnumber || ', ' || to_char(d.presentdatetime,'DD-MM-YYYY')  as docdatenumber, 
	null::character varying as referencedisposal,
	md.private_remark  as remarks,
	d.uploaddocdeedpath as copy_of_document
	from kaveri.minutebook_data md 
	left outer join kaveri.documentmaster d on md.applicationnumber = d.applicationnumber 
	left outer join kaveri.applicantapplicationdetails a on md.applicationnumber = a.applicationnumber 
	left outer join kaveri.feesrequired f on md.applicationnumber = f.applicationnumber 
	left outer join kaveri.sromaster s on md.srocode = s.srocode 
	left outer join kaveri.districtmaster d2 on d2.districtcode = s.districtcode 
	where  d.finalregistrationnumber is not null
	and ( d.finalregistrationnumber=_documentnumber)
	and s.srocode = _srocode
	group by 
	md.applicationnumber,
	d.finalregistrationnumber,
	d.presentdatetime,
	a.remarks,
	d2.districtnamee,
	s.sronamee,md.minutedate,d.uploaddocdeedpath,md.private_remark 
	) sub order by sub.appnum)as sub2;	 

elseif _documentnumber is not NULL and (_fromdate is not NULL and _todate is not NULL) then

raise notice 'nothing null';

return query
select row_number() over() as id,* from 
(
select 
sub.district,
sub.sro,
sub.appnum,
sub.minutedate,
sub.docdatenumber,
sub.referencedisposal,
sub.remarks,sub.copy_of_document
from (
select 
	d2.districtnamee as district,
	s.sronamee as sro,
	md.applicationnumber as appnum,
    TO_CHAR(md.minutedate::timestamp,'dd-mm-yyyy') as minutedate,	
	d.pendingdocumentnumber || ', ' || to_char(d.presentdatetime,'DD-MM-YYYY') as docdatenumber, 
	d.finalregistrationnumber as referencedisposal,
	a.remarks  as remarks,
	d.uploaddocdeedpath as copy_of_document
	from kaveri.minutebook_data md 
	left outer join kaveri.documentmaster d on md.applicationnumber = d.applicationnumber 
	left outer join kaveri.applicantapplicationdetails a on md.applicationnumber = a.applicationnumber 
	left outer join kaveri.feesrequired f on md.applicationnumber = f.applicationnumber 
	left outer join kaveri.sromaster s on md.srocode = s.srocode 
	left outer join kaveri.districtmaster d2 on d2.districtcode = s.districtcode 
	where to_char(a.registrationstartdate, 'YYYY-MM-DD') >= to_char(_fromdate, 'YYYY-MM-DD')
	and to_char(a.registrationstartdate, 'YYYY-MM-DD') <= to_char(_todate, 'YYYY-MM-DD')
	and (d.finalregistrationnumber=_documentnumber)
	and s.srocode = _srocode
	group by 
	md.applicationnumber,
	d.pendingdocumentnumber,
	d.finalregistrationnumber,
	d.presentdatetime,
	a.remarks,
	d2.districtnamee,
	s.sronamee,md.minutedate,d.uploaddocdeedpath,md.private_remark	
	union all
	select
	d2.districtnamee as district,
	s.sronamee as sro,
	md.applicationnumber as appnum,
	TO_CHAR(md.minutedate::timestamp,'dd-mm-yyyy') as minutedate,
		d.finalregistrationnumber || ', ' || to_char(d.presentdatetime,'DD-MM-YYYY')  as docdatenumber, 
	null::character varying as referencedisposal,
	md.private_remark  as remarks,
	d.uploaddocdeedpath as copy_of_document
	from kaveri.minutebook_data md 
	left outer join kaveri.documentmaster d on md.applicationnumber = d.applicationnumber 
	left outer join kaveri.applicantapplicationdetails a on md.applicationnumber = a.applicationnumber 
	left outer join kaveri.feesrequired f on md.applicationnumber = f.applicationnumber 
	left outer join kaveri.sromaster s on md.srocode = s.srocode 
	left outer join kaveri.districtmaster d2 on d2.districtcode = s.districtcode 
	where to_char(a.registrationstartdate, 'YYYY-MM-DD') >=to_char(_fromdate, 'YYYY-MM-DD')
	and to_char(a.registrationstartdate, 'YYYY-MM-DD') <= to_char(_todate, 'YYYY-MM-DD')
	and d.finalregistrationnumber is not null
	and ( d.finalregistrationnumber=_documentnumber)
	and s.srocode = _srocode
	group by 
	md.applicationnumber,
	d.finalregistrationnumber,
	d.presentdatetime,
	a.remarks,
	d2.districtnamee,
	s.sronamee,md.minutedate,d.uploaddocdeedpath,md.private_remark 
	) sub order by sub.appnum)as sub2;	 
	
	else

raise notice 'condition failed';
end if;
    
  
     END;

$$;


ALTER FUNCTION kaverimis.fn_mis_minutebook(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_mis_minutebook(integer, integer, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_minutebook(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying DEFAULT NULL::character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(id bigint, district character varying, sro character varying, appnum character varying, minutedate text, docdatenumber text, cross_ref_number text, referencedisposal character varying, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$


DECLARE
PageOffset INTEGER := 0;


BEGIN
PageOffset := ((pagenumber - 1) * pagesize);


 if (pagenumber<>-1 and pagesize<>-1) then
		return query
		with cte as (select row_number() over() as id,* from 
		(select  distinct

		sub.district,
		sub.sro,
		sub.appnum,
		sub.minutedate,
		sub.docdatenumber,
		sub.cross_ref_number,
		sub.referencedisposal,
		sub.remarks,
		sub.copy_of_document
		from (
		select  
			d2.districtnamee as district,
			s.sronamee as sro,
			md.applicationnumber as appnum,
			TO_CHAR(md.minutedate::timestamp,'dd-mm-yyyy') as minutedate,	
			d.pendingdocumentnumber || ', ' || to_char(d.presentdatetime,'DD-MM-YYYY') as docdatenumber,
			string_agg(distinct '('||r.refid || ' , '||r."year"||')',',') as cross_ref_number,
			d.finalregistrationnumber as referencedisposal,
			a.remarks as remarks,
			d.uploaddocdeedpath as copy_of_document
			from kaveri.minutebook_data md 
			join kaveri.documentmaster d on md.applicationnumber = d.applicationnumber 
			left outer join kaveri.referencemaster r  on d.documentid=r.documentid and d.srocode=r.srocode 
			join kaveri.applicantapplicationdetails a on md.applicationnumber = a.applicationnumber 
			left outer join kaveri.feesrequired f on md.applicationnumber = f.applicationnumber 
			join kaveri.sromaster s on md.srocode = s.srocode 
			join kaveri.districtmaster d2 on d2.districtcode = s.districtcode 
			where
			(md.inserteddatetime  between _fromdate and  _todate+ INTERVAL '1 day')
			
			and d.pendingdocumentnumber is not null 
			
			and (

                    CASE

                       WHEN _districtcode <> 0 THEN  d2.districtcode = _districtcode

                    ELSE TRUE

                    END

                )

               and (

                    CASE

                    WHEN _srocode <> 0 THEN  s.srocode = _srocode

                    ELSE TRUE

                    end

                    )
			--and s.srocode = _srocode
            
			group by 
			md.applicationnumber,
			d.pendingdocumentnumber,
			d.finalregistrationnumber,
			d.presentdatetime,
			a.remarks,
			d2.districtnamee,
			s.sronamee,md.minutedate,d.uploaddocdeedpath,md.private_remark
			union all
			select 
			d2.districtnamee as district,
			s.sronamee as sro,
			md.applicationnumber as appnum,
			TO_CHAR(d.registrationdatetime::timestamp,'dd-mm-yyyy') as minutedate,
			d.finalregistrationnumber || ', ' || to_char(d.registrationdatetime ,'DD-MM-YYYY')  as docdatenumber,
			string_agg(distinct '('||r.refid || ' , '||r."year"||')',',') as cross_ref_number,
			null::character varying as referencedisposal,
			md.private_remark  as remarks,
			d.uploaddocdeedpath as copy_of_document
			from kaveri.minutebook_data md 
			join kaveri.documentmaster d on md.applicationnumber = d.applicationnumber 
			left outer join kaveri.referencemaster r  on d.documentid=r.documentid and d.srocode=r.srocode 
			join kaveri.applicantapplicationdetails a on md.applicationnumber = a.applicationnumber 
			left outer join kaveri.feesrequired f on md.applicationnumber = f.applicationnumber 
			join kaveri.sromaster s on md.srocode = s.srocode 
			join kaveri.districtmaster d2 on d2.districtcode = s.districtcode 
			where (md.inserteddatetime between _fromdate and  _todate+ INTERVAL '1 day')
			and d.finalregistrationnumber is not null
			and (

                    CASE

                       WHEN _districtcode <> 0 THEN  d2.districtcode = _districtcode

                    ELSE TRUE

                    END

                )

               and (

                    CASE

                    WHEN _srocode <> 0 THEN  s.srocode = _srocode

                    ELSE TRUE

                    end

                    )
			
			--and s.srocode = _srocode
			group by 
			md.applicationnumber,
			d.finalregistrationnumber,
			a.remarks,
			d2.districtnamee,
			s.sronamee,md.minutedate,d.uploaddocdeedpath,md.private_remark,
			d.registrationdatetime
			) sub order by sub.appnum,sub.referencedisposal ) as sub2)
			,cte_count as (select count(*) as total_rows from cte)
			select * from cte
			join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0 OFFSET PageOffset
			FETCH NEXT pagesize ROWS ONLY;
		
		elsif (pagenumber=-1 or  pagesize=-1) then 
		
		return query
		with cte as (select row_number() over() as id,* from 
		(select distinct

		sub.district,
		sub.sro,
		sub.appnum,
		sub.minutedate,
		sub.docdatenumber,
		sub.cross_ref_number,
		sub.referencedisposal,
		sub.remarks,
		sub.copy_of_document
		from (
		select  
			d2.districtnamee as district,
			s.sronamee as sro,
			md.applicationnumber as appnum,
			TO_CHAR(md.minutedate::timestamp,'dd-mm-yyyy') as minutedate,	
			d.pendingdocumentnumber || ', ' || to_char(d.presentdatetime,'DD-MM-YYYY') as docdatenumber,
			string_agg(distinct '('||r.refid || ' , '||r."year"||')',',') as cross_ref_number,
			d.finalregistrationnumber as referencedisposal,
			a.remarks as remarks,
			d.uploaddocdeedpath as copy_of_document
			from kaveri.minutebook_data md 
			join kaveri.documentmaster d on md.applicationnumber = d.applicationnumber 
			left outer join kaveri.referencemaster r  on d.documentid=r.documentid and d.srocode=r.srocode 
			join kaveri.applicantapplicationdetails a on md.applicationnumber = a.applicationnumber 
			left outer join kaveri.feesrequired f on md.applicationnumber = f.applicationnumber 
			join kaveri.sromaster s on md.srocode = s.srocode 
			join kaveri.districtmaster d2 on d2.districtcode = s.districtcode 
			where
			(md.inserteddatetime between _fromdate and  _todate+ INTERVAL '1 day')
			
			and d.pendingdocumentnumber is not null 
			
			and (

                    CASE

                       WHEN _districtcode <> 0 THEN  d2.districtcode = _districtcode

                    ELSE TRUE

                    END

                )

               and (

                    CASE

                    WHEN _srocode <> 0 THEN  s.srocode = _srocode

                    ELSE TRUE

                    end

                    )
			--and s.srocode = _srocode
			group by 
			md.applicationnumber,
			d.pendingdocumentnumber,
			d.finalregistrationnumber,
			d.presentdatetime,
			a.remarks,
			d2.districtnamee,
			s.sronamee,md.minutedate,d.uploaddocdeedpath,md.private_remark
			union all
			select 
			d2.districtnamee as district,
			s.sronamee as sro,
			md.applicationnumber as appnum,
			TO_CHAR(d.registrationdatetime::timestamp,'dd-mm-yyyy') as minutedate,
			d.finalregistrationnumber || ', ' || to_char(d.registrationdatetime ,'DD-MM-YYYY')  as docdatenumber,
			string_agg(distinct '('||r.refid || ' , '||r."year"||')',',') as cross_ref_number,
			null::character varying as referencedisposal,
			md.private_remark  as remarks,
			d.uploaddocdeedpath as copy_of_document
			from kaveri.minutebook_data md 
			join kaveri.documentmaster d on md.applicationnumber = d.applicationnumber 
			left outer join kaveri.referencemaster r  on d.documentid=r.documentid and d.srocode=r.srocode 
			join kaveri.applicantapplicationdetails a on md.applicationnumber = a.applicationnumber 
			left outer join kaveri.feesrequired f on md.applicationnumber = f.applicationnumber 
			join kaveri.sromaster s on md.srocode = s.srocode 
			join kaveri.districtmaster d2 on d2.districtcode = s.districtcode 
			where (md.inserteddatetime between _fromdate and  _todate+ INTERVAL '1 day')
			and d.finalregistrationnumber is not null
			and (

                    CASE

                       WHEN _districtcode <> 0 THEN  d2.districtcode = _districtcode

                    ELSE TRUE

                    END

                )

               and (

                    CASE

                    WHEN _srocode <> 0 THEN  s.srocode = _srocode

                    ELSE TRUE

                    end

                    )
			
			--and s.srocode = _srocode
			group by 
			md.applicationnumber,
			d.finalregistrationnumber,
			a.remarks,
			d2.districtnamee,
			s.sronamee,md.minutedate,d.uploaddocdeedpath,md.private_remark,
			d.registrationdatetime
			) sub order by sub.appnum,sub.referencedisposal ) as sub2)
			,cte_count as (select count(*) as total_rows from cte)
			select * from cte
			join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0;
		
		end if;
		
		
			
		
     END;

$$;


ALTER FUNCTION kaverimis.fn_mis_minutebook(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_misellaneious_register(bigint, bigint, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_misellaneious_register(_srocode bigint, _districtcode bigint, _fromdt timestamp without time zone, _todt timestamp without time zone) RETURNS TABLE(registrationnumberofdocument character varying, documentcopy integer, ec_cc_copy text, valeofstampduty numeric, bookno text, registration_no_with_year text, volumn_no text, page_no text)
    LANGUAGE plpgsql
    AS $$
begin
return query
select d.finalregistrationnumber as registrationnumberofdocument,d.documentnumber as documentcopy,
null as EC_CC_Copy
,case when f.feerulecode=36 then 
sum(f.amountpaid) else 0 end as valeofstampduty,
null as bookno,
null as Registration_No_With_year,
null as volumn_no,
null as page_no
from kaveri.documentmaster d 
join kaveri.propertymaster p on d.documentid =p.documentid 
join kaveri.feesrequired f on f.documentid = d.documentid
join kaveri.sromaster s on d.srocode = s.srocode 
join kaveri.districtmaster d2 on s.districtcode = d2.districtcode 
where d.isregistrationcompleted =true and d.srocode =_srocode and d2.districtcode=_districtcode
and d.executiondatetime >=_fromdt and d.executiondatetime <=_todt
group by d.finalregistrationnumber,d.documentnumber,f.feerulecode;
end;
$$;


ALTER FUNCTION kaverimis.fn_mis_misellaneious_register(_srocode bigint, _districtcode bigint, _fromdt timestamp without time zone, _todt timestamp without time zone) OWNER TO csgadmin;

--
-- Name: fn_mis_monthwise_saledeed_revenue_collected(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_monthwise_saledeed_revenue_collected(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _property_type integer DEFAULT NULL::integer, _amount_type integer DEFAULT NULL::integer, _min integer DEFAULT NULL::integer, _max integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, month_year text, no_of_doc bigint, stampduty numeric, registrationfees numeric, scanningfees numeric, totalfees numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

 if _amount_type=0 then 
 _amount_type=null;
 end if;
 
		if _property_type=1  then  --agriculture
		
			return query
					 with cte as (with a as (select distinct  d2.districtnamee,s.sronamee,
			d.applicationnumber,d.registrationdatetime 
			from kaveri.documentmaster d
			join kaveri.applicantapplicationdetails a on a.applicationnumber = d.applicationnumber 
			join kaveri.propertymaster p on d.applicationnumber=p.applicationnumber 
			join kaveri.sromaster s on d.srocode=s.srocode 
			join kaveri.districtmaster d2 on  s.districtcode=d2.districtcode  
			where d.registrationdatetime::date between _fromdate and _todate
			and d.isregistrationcompleted=true and 
			--a.currentstatus = 'CD120' and
			p.propertytypeid=17 and
			case 
				when _districtcode=0 then true
				when _districtcode<>0 and _srocode=0 then d2.districtcode=_districtcode 
				when _districtcode<>0 and _srocode<>0 then d2.districtcode=_districtcode 
				and s.srocode=_srocode 
			end
			
			)

			select a.districtnamee,a.sronamee,
			to_char(a.registrationdatetime,'mm-yyyy') as month_year,
			count(distinct a.applicationnumber),
			sum(case when f.feerulecode=36  then f.amountpaid else 0 end) stampduty,
			sum(case when f.feerulecode=1 then f.amountpaid else 0 end) registrationfees,
			sum(case when f.feerulecode=2 then f.amountpaid else 0 end) scanningfees,
			sum(case when f.feerulecode=36  then f.amountpaid else 0 end)+
			sum(case when f.feerulecode=1 then f.amountpaid else 0 end)+ 
			sum(case when f.feerulecode=2 then f.amountpaid else 0 end)	as Total_fees


			from 
			a
			join kaveri.feesrequired f on a.applicationnumber=f.applicationnumber 
			where 
			case 
				when _amount_type is null then true
				when _amount_type=1 then  exists (select applicationnumber  from kaveri.feesrequired
													where applicationnumber=a.applicationnumber and  feerulecode=36 
													and (amountpaid between _min and _max)  )
				when _amount_type=2 then  exists (select applicationnumber  from kaveri.feesrequired
													where applicationnumber=a.applicationnumber and  feerulecode=1 
													and (amountpaid between _min and _max)  )
													
				when _amount_type=3 then  exists (select applicationnumber  from kaveri.feesrequired
													where applicationnumber=a.applicationnumber and  feerulecode=2 
													and (amountpaid between _min and _max)  )									
			end
			group by a.districtnamee,a.sronamee,month_year)
			,cte_count as (select count(*) as total_rows from cte)
						select * from cte
						right join (select total_rows from cte_count)
						total_row on true 
						where total_row.total_rows<>0 OFFSET PageOffset
							FETCH NEXT pagesize ROWS ONLY;
			
		
			
		
		
		elsif _property_type=2  then --non agriculture
		
			return query
					 with cte as (with a as (select distinct  d2.districtnamee,s.sronamee,
			d.applicationnumber,d.registrationdatetime 
			from kaveri.documentmaster d
			join kaveri.applicantapplicationdetails a on a.applicationnumber = d.applicationnumber 
			join kaveri.propertymaster p on d.applicationnumber=p.applicationnumber 
			join kaveri.sromaster s on d.srocode=s.srocode 
			join kaveri.districtmaster d2 on  s.districtcode=d2.districtcode  
			where d.registrationdatetime::date between _fromdate and _todate
			and d.isregistrationcompleted=true 	and 
			--a.currentstatus = 'CD120' and
			p.propertytypeid=28 and
			case 
				when _districtcode=0 then true
				when _districtcode<>0 and _srocode=0 then d2.districtcode=_districtcode 
				when _districtcode<>0 and _srocode<>0 then d2.districtcode=_districtcode 
				and s.srocode=_srocode 
			end
			)

			select a.districtnamee,a.sronamee,
		to_char(a.registrationdatetime,'mm-yyyy') as month_year,
			count(distinct a.applicationnumber),
			sum(case when f.feerulecode=36  then f.amountpaid else 0 end) stampduty,
			sum(case when f.feerulecode=1 then f.amountpaid else 0 end) registrationfees,
			sum(case when f.feerulecode=2 then f.amountpaid else 0 end) scanningfees,
			sum(case when f.feerulecode=36  then f.amountpaid else 0 end)+
			sum(case when f.feerulecode=1 then f.amountpaid else 0 end)+ 
			sum(case when f.feerulecode=2 then f.amountpaid else 0 end)	as Total_fees


			from 
			a
			join kaveri.feesrequired f on a.applicationnumber=f.applicationnumber 
			where 
			case 
				when _amount_type is null then true
				when _amount_type=1 then  exists (select applicationnumber  from kaveri.feesrequired
													where applicationnumber=a.applicationnumber and  feerulecode=36 
													and (amountpaid between _min and _max)  )
				when _amount_type=2 then  exists (select applicationnumber  from kaveri.feesrequired
													where applicationnumber=a.applicationnumber and  feerulecode=1 
													and (amountpaid between _min and _max)  )
				when _amount_type=3 then  exists (select applicationnumber  from kaveri.feesrequired
													where applicationnumber=a.applicationnumber and  feerulecode=2 
													and (amountpaid between _min and _max)  )	
			end
			group by a.districtnamee,a.sronamee,month_year)
			,cte_count as (select count(*) as total_rows from cte)
						select * from cte
						right join (select total_rows from cte_count)
						total_row on true
						where total_row.total_rows<>0 OFFSET PageOffset
							FETCH NEXT pagesize ROWS ONLY;
		
							
			
							
		elsif _property_type=3  then   --Apartment
		
				return query
					 with cte as (with a as (select distinct  
				d2.districtnamee,s.sronamee,
				d.applicationnumber,d.registrationdatetime 
				from kaveri.documentmaster d 
				join kaveri.applicantapplicationdetails a on a.applicationnumber = d.applicationnumber 
				join kaveri.propertymaster p on d.applicationnumber=p.applicationnumber
				join kaveri.propertynumberdetails p3 on p.propertyid=p3.propertyid 
				join kaveri.sromaster s on d.srocode=s.srocode 
				join kaveri.districtmaster d2 on  s.districtcode=d2.districtcode  
				where d.registrationdatetime::date between  _fromdate  and  _todate
				and d.isregistrationcompleted=true and 
				--a.currentstatus = 'CD120' and 
				p3.currentpropertytypeid in (16,36)
				and
				case 
				when _districtcode=0 then true
				when _districtcode<>0 and _srocode=0 then d2.districtcode=_districtcode 
				when _districtcode<>0 and _srocode<>0 then d2.districtcode=_districtcode 
				and s.srocode=_srocode 
				end 
				)

				select a.districtnamee,a.sronamee,
			to_char(a.registrationdatetime,'mm-yyyy') as month_year,
				count(distinct a.applicationnumber),
				sum(case when f.feerulecode=36  then f.amountpaid else 0 end) stampduty,
				sum(case when f.feerulecode=1 then f.amountpaid else 0 end) registrationfees,
				sum(case when f.feerulecode=2 then f.amountpaid else 0 end) scanningfees,
				sum(case when f.feerulecode=36  then f.amountpaid else 0 end)+
				sum(case when f.feerulecode=1 then f.amountpaid else 0 end)+ 
				sum(case when f.feerulecode=2 then f.amountpaid else 0 end)	as Total_fees


				from 
				a
				join kaveri.feesrequired f on a.applicationnumber=f.applicationnumber
				where 
				case 
				when _amount_type is null then true
				when _amount_type=1 then  exists (select applicationnumber  from kaveri.feesrequired
													where applicationnumber=a.applicationnumber and  feerulecode=36 
													and (amountpaid between _min and _max)  )
				when _amount_type=2 then  exists (select applicationnumber  from kaveri.feesrequired
													where applicationnumber=a.applicationnumber and  feerulecode=1 
													and (amountpaid between _min and _max)  )
				when _amount_type=3 then  exists (select applicationnumber  from kaveri.feesrequired
													where applicationnumber=a.applicationnumber and  feerulecode=2 
													and (amountpaid between _min and _max)  )	
				end
				group by a.districtnamee,a.sronamee,month_year)
							,cte_count as (select count(*) as total_rows from cte)
										select * from cte
										right join (select total_rows from cte_count)
										total_row on true
										where total_row.total_rows<>0
										OFFSET PageOffset
											FETCH NEXT pagesize ROWS ONLY;
		
			
		
		
		elsif _property_type=4  then -- Lease
				return query
							 with cte as ( with a as (select distinct  d2.districtnamee,s.sronamee,
			d.applicationnumber,d.registrationdatetime 
			from kaveri.documentmaster d 
			join kaveri.applicantapplicationdetails a on a.applicationnumber = d.applicationnumber 
			join kaveri.propertymaster p on d.applicationnumber=p.applicationnumber 
			join kaveri.sromaster s on d.srocode=s.srocode 
			join kaveri.districtmaster d2 on  s.districtcode=d2.districtcode  
			where d.registrationdatetime::date between _fromdate and _todate
			and d.isregistrationcompleted=true and 
			--a.currentstatus = 'CD120' and 
			p.regarticlecode in (11,12,13,14,15,16,17,18,19,75,76,
			77,78,122,135,138)
			and
			case 
				when _districtcode=0 then true
				when _districtcode<>0 and _srocode=0 then d2.districtcode=_districtcode 
				when _districtcode<>0 and _srocode<>0 then d2.districtcode=_districtcode 
				and s.srocode=_srocode 
			end
			)

			select a.districtnamee,a.sronamee,
			to_char(a.registrationdatetime,'mm-yyyy') as month_year,
			count(distinct a.applicationnumber),
			sum(case when f.feerulecode=36  then f.amountpaid else 0 end) stampduty,
			sum(case when f.feerulecode=1 then f.amountpaid else 0 end) registrationfees,
			sum(case when f.feerulecode=2 then f.amountpaid else 0 end) scanningfees,
			sum(case when f.feerulecode=36  then f.amountpaid else 0 end)+
			sum(case when f.feerulecode=1 then f.amountpaid else 0 end)+ 
			sum(case when f.feerulecode=2 then f.amountpaid else 0 end)	as Total_fees


			from 
			a
			join kaveri.feesrequired f on a.applicationnumber=f.applicationnumber 
			where 
			case 
				when _amount_type is null then true
				when _amount_type=1 then  exists (select applicationnumber  from kaveri.feesrequired
													where applicationnumber=a.applicationnumber and  feerulecode=36 
													and (amountpaid between _min and _max)  )
				when _amount_type=2 then  exists (select applicationnumber  from kaveri.feesrequired
													where applicationnumber=a.applicationnumber and  feerulecode=1 
													and (amountpaid between _min and _max)  )
				when _amount_type=3 then  exists (select applicationnumber  from kaveri.feesrequired
													where applicationnumber=a.applicationnumber and  feerulecode=2 
													and (amountpaid between _min and _max)  )	
			end
			group by a.districtnamee,a.sronamee,month_year)
							,cte_count as (select count(*) as total_rows from cte)
										select * from cte
										right join (select total_rows from cte_count)
										total_row on true
										where total_row.total_rows<>0
										OFFSET PageOffset
											FETCH NEXT pagesize ROWS ONLY;
		
		end if;

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_monthwise_saledeed_revenue_collected(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _property_type integer, _amount_type integer, _min integer, _max integer, pagenumber integer, pagesize integer) OWNER TO postgres;

