ALTER FUNCTION kaverimis.fn_mis_nominal_index_to_book_no_3(_srocode integer, _documentnumber character varying, _from_date timestamp without time zone, _to_date timestamp without time zone) OWNER TO csgadmin;

--
-- Name: fn_mis_nominal_index_to_book_no_3(integer, integer, character varying, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_nominal_index_to_book_no_3(_districtcode integer, _srocode integer, _documentnumber character varying DEFAULT NULL::character varying, _from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _to_date timestamp without time zone DEFAULT NULL::timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, sroname character varying, nameoftestorordonor text, placeofresidence text, claimant text, placeofresidence_claimant character varying, executant text, placeofresidence_executant character varying, placeofresidenceofpersonclaiming character varying, nameofthepersonclaimingunderwill text, descriptionoftheproperty text, dateofdeath text, dateofregistration text, volumeandpage text, serialnumberofdocument character varying, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$
DECLARE
    PageOffset integer := 0;
BEGIN
    pagenumber := coalesce(pagenumber, 1);
    pagesize := coalesce(pagesize, 10);
    PageOffset := ((pagenumber - 1) * pagesize);

    -- all districts
    IF (_districtcode = 0) THEN

        -- document number search
        IF (_documentnumber IS NOT NULL) THEN
            RETURN QUERY
            WITH cte AS (
                SELECT DISTINCT
                    c.districtnamee AS district,
                    b.sronamee AS sroname,
                    CASE
                        WHEN pi.partytypeid = 2 THEN COALESCE(concat(pi.firstname, pi.middlename, pi.lastname), NULL::text)
                        ELSE NULL::text
                    END AS nameoftestorordonor,
                    CASE
                        WHEN pi.partytypeid = 2 THEN COALESCE(pi.address, NULL::text)
                        ELSE NULL::text
                    END AS placeofresidence,
                    NULL::text AS claimant,
                    NULL::character varying AS placeofresidence_claimant,
                    NULL::text AS executant,
                    NULL::character varying AS placeofresidence_executant,
                    NULL::character varying AS placeofresidenceofpersonclaiming,
                    NULL::text AS nameofthepersonclaimingunderwill,
                    NULL::text AS descriptionoftheproperty,
                    NULL::text AS dateofdeath,
                    to_char(i.registrationdatetime, 'dd/mm/yyyy')::text AS dateofregistration,
                    NULL::text AS volumeandpage,
                    i.finalregistrationnumber AS serialnumberofdocument,
                    i.uploaddocdeedpath AS copy_of_document
                FROM kaveri.documentmaster i
                JOIN kaveri.partyinfo pi
                  ON pi.documentid = i.documentid
                JOIN kaveri.sromaster b
                  ON i.srocode = b.srocode
                JOIN kaveri.districtmaster c
                  ON b.districtcode = c.districtcode
                WHERE i.finalregistrationnumber = _documentnumber
                  AND i.bookid = 3
                  AND (
                        (_from_date IS NULL AND _to_date IS NULL)
                        OR i.registrationdatetime BETWEEN _from_date AND _to_date
                      )
            ),
            cte_count AS (
                SELECT count(*) AS total_rows FROM cte
            )
            SELECT
                cte.district,
                cte.sroname,
                cte.nameoftestorordonor,
                cte.placeofresidence,
                cte.claimant,
                cte.placeofresidence_claimant,
                cte.executant,
                cte.placeofresidence_executant,
                cte.placeofresidenceofpersonclaiming,
                cte.nameofthepersonclaimingunderwill,
                cte.descriptionoftheproperty,
                cte.dateofdeath,
                cte.dateofregistration,
                cte.volumeandpage,
                cte.serialnumberofdocument,
                cte.copy_of_document,
                total_row.total_rows AS totalcount
            FROM cte
            RIGHT JOIN (SELECT total_rows FROM cte_count) total_row ON true
            WHERE total_row.total_rows <> 0
            OFFSET PageOffset
            FETCH NEXT pagesize ROWS ONLY;

        -- date range search
        ELSIF (_from_date IS NOT NULL AND _to_date IS NOT NULL) AND (_documentnumber IS NULL) THEN
            RETURN QUERY
            WITH cte AS (
                SELECT DISTINCT
                    c.districtnamee AS district,
                    b.sronamee AS sroname,
                    CASE
                        WHEN pi.partytypeid = 2 THEN COALESCE(concat(pi.firstname, pi.middlename, pi.lastname), NULL::text)
                        ELSE NULL::text
                    END AS nameoftestorordonor,
                    CASE
                        WHEN pi.partytypeid = 2 THEN COALESCE(pi.address, NULL::text)
                        ELSE NULL::text
                    END AS placeofresidence,
                    NULL::text AS claimant,
                    NULL::character varying AS placeofresidence_claimant,
                    NULL::text AS executant,
                    NULL::character varying AS placeofresidence_executant,
                    NULL::character varying AS placeofresidenceofpersonclaiming,
                    NULL::text AS nameofthepersonclaimingunderwill,
                    NULL::text AS descriptionoftheproperty,
                    NULL::text AS dateofdeath,
                    to_char(i.registrationdatetime, 'dd/mm/yyyy')::text AS dateofregistration,
                    NULL::text AS volumeandpage,
                    i.finalregistrationnumber AS serialnumberofdocument,
                    i.uploaddocdeedpath AS copy_of_document
                FROM kaveri.documentmaster i
                JOIN kaveri.partyinfo pi
                  ON pi.documentid = i.documentid
                JOIN kaveri.sromaster b
                  ON i.srocode = b.srocode
                JOIN kaveri.districtmaster c
                  ON b.districtcode = c.districtcode
                WHERE i.registrationdatetime BETWEEN _from_date AND _to_date
                  AND i.bookid = 3
            ),
            cte_count AS (
                SELECT count(*) AS total_rows FROM cte
            )
            SELECT
                cte.district,
                cte.sroname,
                cte.nameoftestorordonor,
                cte.placeofresidence,
                cte.claimant,
                cte.placeofresidence_claimant,
                cte.executant,
                cte.placeofresidence_executant,
                cte.placeofresidenceofpersonclaiming,
                cte.nameofthepersonclaimingunderwill,
                cte.descriptionoftheproperty,
                cte.dateofdeath,
                cte.dateofregistration,
                cte.volumeandpage,
                cte.serialnumberofdocument,
                cte.copy_of_document,
                total_row.total_rows AS totalcount
            FROM cte
            RIGHT JOIN (SELECT total_rows FROM cte_count) total_row ON true
            WHERE total_row.total_rows <> 0
            OFFSET PageOffset
            FETCH NEXT pagesize ROWS ONLY;
        END IF;

    -- particular district and all SRO
    ELSIF (_srocode = 0) THEN

        IF (_documentnumber IS NOT NULL) THEN
            RETURN QUERY
            WITH cte AS (
                SELECT DISTINCT
                    c.districtnamee AS district,
                    b.sronamee AS sroname,
                    CASE
                        WHEN pi.partytypeid = 2 THEN COALESCE(concat(pi.firstname, pi.middlename, pi.lastname), NULL::text)
                        ELSE NULL::text
                    END AS nameoftestorordonor,
                    CASE
                        WHEN pi.partytypeid = 2 THEN COALESCE(pi.address, NULL::text)
                        ELSE NULL::text
                    END AS placeofresidence,
                    NULL::text AS claimant,
                    NULL::character varying AS placeofresidence_claimant,
                    NULL::text AS executant,
                    NULL::character varying AS placeofresidence_executant,
                    NULL::character varying AS placeofresidenceofpersonclaiming,
                    NULL::text AS nameofthepersonclaimingunderwill,
                    NULL::text AS descriptionoftheproperty,
                    NULL::text AS dateofdeath,
                    to_char(i.registrationdatetime, 'dd/mm/yyyy')::text AS dateofregistration,
                    NULL::text AS volumeandpage,
                    i.finalregistrationnumber AS serialnumberofdocument,
                    i.uploaddocdeedpath AS copy_of_document
                FROM kaveri.documentmaster i
                JOIN kaveri.partyinfo pi
                  ON pi.documentid = i.documentid
                JOIN kaveri.sromaster b
                  ON i.srocode = b.srocode
                JOIN kaveri.districtmaster c
                  ON b.districtcode = c.districtcode
                WHERE b.districtcode = _districtcode
                  AND i.finalregistrationnumber = _documentnumber
                  AND i.bookid = 3
                  AND (
                        (_from_date IS NULL AND _to_date IS NULL)
                        OR i.registrationdatetime BETWEEN _from_date AND _to_date
                      )
            ),
            cte_count AS (
                SELECT count(*) AS total_rows FROM cte
            )
            SELECT
                cte.district,
                cte.sroname,
                cte.nameoftestorordonor,
                cte.placeofresidence,
                cte.claimant,
                cte.placeofresidence_claimant,
                cte.executant,
                cte.placeofresidence_executant,
                cte.placeofresidenceofpersonclaiming,
                cte.nameofthepersonclaimingunderwill,
                cte.descriptionoftheproperty,
                cte.dateofdeath,
                cte.dateofregistration,
                cte.volumeandpage,
                cte.serialnumberofdocument,
                cte.copy_of_document,
                total_row.total_rows AS totalcount
            FROM cte
