ALTER FUNCTION kaverimis.fn_mis_nominal_index_to_book_no_3_20260410(_districtcode integer, _srocode integer, _documentnumber character varying, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_nominal_index_to_book_no_4(bigint, character varying, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_nominal_index_to_book_no_4(_srocode bigint, _documentnnumber character varying DEFAULT NULL::character varying, _from_date timestamp without time zone DEFAULT NULL::timestamp without time zone, _to_date timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS TABLE(district character varying, sroname character varying, nameoftheexecutingpartyordefendent text, placeofresidence character varying, nameandadditionsofpersons text, article_consideration text, dateofregistration text, volumenameandpage text, serialnumberofdocument character varying, remarks character varying)
    LANGUAGE plpgsql
    AS $$
/*DECLARE
PageOffset INTEGER := 0;*/
BEGIN	
--PageOffset := ((pagenumber - 1) * pagesize); 	
if (_from_date is not null and _to_date is not null) then
return query 
		SELECT DISTINCT --b.districtcode,
    c.districtnamee AS district,
    b.sronamee AS sroname,
        CASE
            WHEN pi.partytypeid = 1 THEN COALESCE(concat(pi.firstname, pi.middlename, pi.lastname), NULL::text)
            ELSE NULL::text
        END AS nameoftheexecutingpartyordefendent,
        CASE
            WHEN pi.partytypeid = 1 THEN COALESCE(pi.address, NULL::character varying)
            ELSE NULL::character varying
        END AS placeofresidence,
    NULL::text AS nameandadditionsofpersons,
   -- a.stamparticlecode,
    (d.articlenamee::text || ' '::text) || a.consideration AS article_consideration,
    to_char(e.registrationdatetime,'dd/mm/yyyy')::text AS dateofregistration,
    --(pi.volumename::text || ' '::text) || e.pagecount AS volumenameandpage,
  --( e.finalregistrationnumber::text ||' '::text) || e.pagecount AS volumenameandpage,
    null::text AS volumenameandpage,
    --b.registrationdocserial AS serialnumberofdocument,
	--e.documentnumber::bigint AS serialnumberofdocument,
	e.finalregistrationnumber  AS serialnumberofdocument,
		case when ref.referencetext like '%cancel%' then
    ref.referencetext else null end AS remarks
    --e.remarksbyuser AS remarks
   FROM kaveri.propertymaster a
      JOIN kaveri.sromaster b ON a.srocode = b.srocode
      JOIN kaveri.districtmaster c ON b.districtcode = c.districtcode
      JOIN kaveri.partyinfo pi ON a.propertyid = pi.propertyid
      JOIN kaveri.stamparticles d ON a.stamparticlecode = d.stamparticlecode
      JOIN kaveri.documentmaster e ON a.documentid = e.documentid
	  JOIN kaveri.referencemaster ref on e.documentid = ref.documentid
	 where e.bookid = 4 and  e.srocode = _srocode and e.registrationdatetime >= _from_date
	 and e.registrationdatetime <= _to_date and isregistrationcompleted = true;
	 elseif (_documentnnumber is not null) then
	 return query
	 		SELECT DISTINCT --b.districtcode,
    c.districtnamee AS district,
    b.sronamee AS sroname,
        CASE
            WHEN pi.partytypeid = 1 THEN COALESCE(concat(pi.firstname, pi.middlename, pi.lastname), NULL::text)
            ELSE NULL::text
        END AS nameoftheexecutingpartyordefendent,
        CASE
            WHEN pi.partytypeid = 1 THEN COALESCE(pi.address, NULL::character varying)
            ELSE NULL::character varying
        END AS placeofresidence,
    NULL::text AS nameandadditionsofpersons,
   -- a.stamparticlecode,
    (d.articlenamee::text || ' '::text) || a.consideration AS article_consideration,
    to_char(e.registrationdatetime,'dd/mm/yyyy')::text AS dateofregistration,
    --(pi.volumename::text || ' '::text) || e.pagecount AS volumenameandpage,
  --( e.finalregistrationnumber::text ||' '::text) || e.pagecount AS volumenameandpage,
    null::text AS volumenameandpage,
    --b.registrationdocserial AS serialnumberofdocument,
	--e.documentnumber::bigint AS serialnumberofdocument,
	e.finalregistrationnumber  AS serialnumberofdocument,
		case when ref.referencetext like '%cancel%' then
    ref.referencetext else null end AS remarks
    --e.remarksbyuser AS remarks
   FROM kaveri.propertymaster a
      JOIN kaveri.sromaster b ON a.srocode = b.srocode
      JOIN kaveri.districtmaster c ON b.districtcode = c.districtcode
      JOIN kaveri.partyinfo pi ON a.propertyid = pi.propertyid
      JOIN kaveri.stamparticles d ON a.stamparticlecode = d.stamparticlecode
      JOIN kaveri.documentmaster e ON a.documentid = e.documentid
	  JOIN kaveri.referencemaster ref on e.documentid = ref.documentid
	 where e.bookid = 4 and e.srocode = _srocode and e.finalregistrationnumber = _documentnnumber
	 and isregistrationcompleted = true;
	 else
	 return query
	 		SELECT DISTINCT --b.districtcode,
    c.districtnamee AS district,
    b.sronamee AS sroname,
        CASE
            WHEN pi.partytypeid = 1 THEN COALESCE(concat(pi.firstname, pi.middlename, pi.lastname), NULL::text)
            ELSE NULL::text
        END AS nameoftheexecutingpartyordefendent,
        CASE
            WHEN pi.partytypeid = 1 THEN COALESCE(pi.address, NULL::character varying)
            ELSE NULL::character varying
        END AS placeofresidence,
    NULL::text AS nameandadditionsofpersons,
   -- a.stamparticlecode,
    (d.articlenamee::text || ' '::text) || a.consideration AS article_consideration,
    to_char(e.registrationdatetime,'dd/mm/yyyy')::text AS dateofregistration,
    --(pi.volumename::text || ' '::text) || e.pagecount AS volumenameandpage,
  --( e.finalregistrationnumber::text ||' '::text) || e.pagecount AS volumenameandpage,
    null::text AS volumenameandpage,
    --b.registrationdocserial AS serialnumberofdocument,
	--e.documentnumber::bigint AS serialnumberofdocument,
	e.finalregistrationnumber  AS serialnumberofdocument,
		case when ref.referencetext like '%cancel%' then
    ref.referencetext else null end AS remarks
    --e.remarksbyuser AS remarks
   FROM kaveri.propertymaster a
      JOIN kaveri.sromaster b ON a.srocode = b.srocode
      JOIN kaveri.districtmaster c ON b.districtcode = c.districtcode
      JOIN kaveri.partyinfo pi ON a.propertyid = pi.propertyid
      JOIN kaveri.stamparticles d ON a.stamparticlecode = d.stamparticlecode
      JOIN kaveri.documentmaster e ON a.documentid = e.documentid
	  JOIN kaveri.referencemaster ref on e.documentid = ref.documentid
	 where e.bookid = 4 and e.srocode = _srocode and e.documentnumber=_documentnnumber and e.registrationdatetime >= _from_date
	 and e.registrationdatetime <= _to_date and isregistrationcompleted = true;
	 end if;
END;
$$;


