	  left outer JOIN kaveri.referencemaster ref on e.documentid = ref.documentid
	  left outer JOIN kaverimis.form19  form19 on form19.documentnumber = e.finalregistrationnumber
	 or form19.documentnumber = e.pendingdocumentnumber
	 where e.bookid = 4 and  e.srocode = _srocode and e.registrationdatetime >= _from_date
	 and e.registrationdatetime <= _to_date and isregistrationcompleted = true;
	 elseif 	_documentnnumber is not NULL and (_from_date  is NULL and _to_date is NULL) then
