    --e.remarksbyuser AS remarks
   FROM kaveri.propertymaster a
     left outer JOIN kaveri.sromaster b ON a.srocode = b.srocode and b.districtcode = _districtcode
      left outer JOIN kaveri.districtmaster c ON b.districtcode = c.districtcode
      left outer JOIN kaveri.partyinfo pi ON a.propertyid = pi.propertyid
      left outer JOIN kaveri.stamparticles d ON a.stamparticlecode = d.stamparticlecode
      left outer JOIN kaveri.documentmaster e ON a.documentid = e.documentid
	  left outer JOIN kaveri.referencemaster ref on e.documentid = ref.documentid
	  left outer JOIN kaverimis.form19  form19 on form19.documentnumber = e.finalregistrationnumber
	 or form19.documentnumber = e.pendingdocumentnumber
where e.bookid = 4 and (e.registrationdatetime between  _from_date and  _to_date) 
and isregistrationcompleted = true),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
	 elseif 	_documentnnumber is not NULL then
	 return query
	 		with cte as (SELECT DISTINCT --b.districtcode,
    c.districtnamee AS district,
    b.sronamee AS sroname,
        CASE
            WHEN pi.partytypeid = 1 THEN COALESCE(concat(pi.firstname, pi.middlename, pi.lastname), NULL::text)
            ELSE NULL::text
        END AS nameoftheexecutingpartyordefendent,
        CASE
            WHEN pi.partytypeid = 1 THEN COALESCE(pi.address, NULL::character varying)
            ELSE NULL::character varying
        END AS placeofresidence,
    NULL::text AS nameandadditionsofpersons,
   -- a.stamparticlecode,
    (d.articlenamee::text || ' '::text) || a.consideration AS article_consideration,
    to_char(e.registrationdatetime,'dd/mm/yyyy')::text AS dateofregistration,
    --(pi.volumename::text || ' '::text) || e.pagecount AS volumenameandpage,
  --( e.finalregistrationnumber::text ||' '::text) || e.pagecount AS volumenameandpage,
    null::text AS volumenameandpage,
    --b.registrationdocserial AS serialnumberofdocument,
	--e.documentnumber::bigint AS serialnumberofdocument,
	e.finalregistrationnumber  AS serialnumberofdocument,
	e.uploaddocdeedpath as copy_of_document,
	--	case when ref.referencetext like '%cancel%' then
    --ref.referencetext else null end AS remarks,
	form19.inx4rem as remarks
    --e.remarksbyuser AS remarks
   FROM kaveri.propertymaster a
      left outer JOIN kaveri.sromaster b ON a.srocode = b.srocode and b.districtcode = _districtcode
      left outer JOIN kaveri.districtmaster c ON b.districtcode = c.districtcode
      left outer JOIN kaveri.partyinfo pi ON a.propertyid = pi.propertyid
      left outer JOIN kaveri.stamparticles d ON a.stamparticlecode = d.stamparticlecode
      left outer JOIN kaveri.documentmaster e ON a.documentid = e.documentid
	  left outer JOIN kaveri.referencemaster ref on e.documentid = ref.documentid
	  left outer JOIN kaverimis.form19  form19 on form19.documentnumber = e.finalregistrationnumber
	 or form19.documentnumber = e.pendingdocumentnumber
	 where e.bookid = 4 and e.finalregistrationnumber = _documentnnumber and isregistrationcompleted = true),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

end if;
else	
if  _documentnnumber is NULL and (_from_date is not NULL and _to_date is not NULL) then
raise notice 'Documentnumber null';
return query 
		with cte as (SELECT DISTINCT --b.districtcode,
    c.districtnamee AS district,
    b.sronamee AS sroname,
        CASE
            WHEN pi.partytypeid = 1 THEN COALESCE(concat(pi.firstname, pi.middlename, pi.lastname), NULL::text)
            ELSE NULL::text
        END AS nameoftheexecutingpartyordefendent,
        CASE
            WHEN pi.partytypeid = 1 THEN COALESCE(pi.address, NULL::character varying)
            ELSE NULL::character varying
        END AS placeofresidence,
    NULL::text AS nameandadditionsofpersons,
   -- a.stamparticlecode,
    (d.articlenamee::text || ' '::text) || a.consideration AS article_consideration,
    to_char(e.registrationdatetime,'dd/mm/yyyy')::text AS dateofregistration,
    --(pi.volumename::text || ' '::text) || e.pagecount AS volumenameandpage,
  --( e.finalregistrationnumber::text ||' '::text) || e.pagecount AS volumenameandpage,
    null::text AS volumenameandpage,
    --b.registrationdocserial AS serialnumberofdocument,
	--e.documentnumber::bigint AS serialnumberofdocument,
	e.finalregistrationnumber  AS serialnumberofdocument,
	e.uploaddocdeedpath as copy_of_document,
	--	case when ref.referencetext like '%cancel%' then
   -- ref.referencetext else null end AS remarks,
	form19.inx4rem AS remarks
    --e.remarksbyuser AS remarks
   FROM kaveri.propertymaster a
     left outer JOIN kaveri.sromaster b ON a.srocode = b.srocode and b.districtcode = _districtcode
      left outer JOIN kaveri.districtmaster c ON b.districtcode = c.districtcode
      left outer JOIN kaveri.partyinfo pi ON a.propertyid = pi.propertyid
      left outer JOIN kaveri.stamparticles d ON a.stamparticlecode = d.stamparticlecode
      left outer JOIN kaveri.documentmaster e ON a.documentid = e.documentid
	  left outer JOIN kaveri.referencemaster ref on e.documentid = ref.documentid
	  left outer JOIN kaverimis.form19  form19 on form19.documentnumber = e.finalregistrationnumber
	 or form19.documentnumber = e.pendingdocumentnumber
	 where e.bookid = 4 and  e.srocode = _srocode and (e.registrationdatetime between  _from_date and  _to_date)
	 and isregistrationcompleted = true),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
	 elseif 	_documentnnumber is not NULL then
	 return query
	 		with cte as (SELECT DISTINCT --b.districtcode,
    c.districtnamee AS district,
    b.sronamee AS sroname,
        CASE
            WHEN pi.partytypeid = 1 THEN COALESCE(concat(pi.firstname, pi.middlename, pi.lastname), NULL::text)
            ELSE NULL::text
        END AS nameoftheexecutingpartyordefendent,
        CASE
            WHEN pi.partytypeid = 1 THEN COALESCE(pi.address, NULL::character varying)
            ELSE NULL::character varying
        END AS placeofresidence,
    NULL::text AS nameandadditionsofpersons,
   -- a.stamparticlecode,
    (d.articlenamee::text || ' '::text) || a.consideration AS article_consideration,
    to_char(e.registrationdatetime,'dd/mm/yyyy')::text AS dateofregistration,
    --(pi.volumename::text || ' '::text) || e.pagecount AS volumenameandpage,
  --( e.finalregistrationnumber::text ||' '::text) || e.pagecount AS volumenameandpage,
    null::text AS volumenameandpage,
    --b.registrationdocserial AS serialnumberofdocument,
	--e.documentnumber::bigint AS serialnumberofdocument,
	e.finalregistrationnumber  AS serialnumberofdocument,
	e.uploaddocdeedpath as copy_of_document,
	--	case when ref.referencetext like '%cancel%' then
    --ref.referencetext else null end AS remarks,
	form19.inx4rem as remarks
    --e.remarksbyuser AS remarks
   FROM kaveri.propertymaster a
      left outer JOIN kaveri.sromaster b ON a.srocode = b.srocode and b.districtcode = _districtcode
      left outer JOIN kaveri.districtmaster c ON b.districtcode = c.districtcode
      left outer JOIN kaveri.partyinfo pi ON a.propertyid = pi.propertyid
      left outer JOIN kaveri.stamparticles d ON a.stamparticlecode = d.stamparticlecode
      left outer JOIN kaveri.documentmaster e ON a.documentid = e.documentid
	  left outer JOIN kaveri.referencemaster ref on e.documentid = ref.documentid
	  left outer JOIN kaverimis.form19  form19 on form19.documentnumber = e.finalregistrationnumber
	 or form19.documentnumber = e.pendingdocumentnumber
	 where e.bookid = 4 and e.srocode = _srocode and e.finalregistrationnumber = _documentnnumber
	 and isregistrationcompleted = true),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
end if;
end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_nominal_index_to_book_no_4_query_bkp(_districtcode integer, _srocode bigint, _documentnnumber character varying, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_nominal_index_to_book_no_4_save(bigint, character varying, character varying); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_nominal_index_to_book_no_4_save(_srocode bigint, _documentnnumber character varying DEFAULT NULL::character varying, _inx4rem character varying DEFAULT NULL::character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
v_cnt bigint;
v_form7dataentryid bigint;
/*PageOffset INTEGER := 0;*/
BEGIN	
select count(*) into v_cnt from kaverimis.form19 where documentnumber = _documentnnumber;
IF (v_cnt = 0 ) then
insert into kaverimis.form19
(

srocode,
documentnumber,
inx4rem
)
values
(_srocode,
 _documentnnumber,
_inx4rem
) returning form7dataentryid into v_form7dataentryid;
elseif (v_cnt = 1 ) then
	update 
	kaverimis.form19 set
	inx4rem = _inx4rem where documentnumber = _documentnnumber and srocode = _srocode
	returning form7dataentryid into v_form7dataentryid; 
	end if;
	return  v_form7dataentryid;
end;
$$;


ALTER FUNCTION kaverimis.fn_mis_nominal_index_to_book_no_4_save(_srocode bigint, _documentnnumber character varying, _inx4rem character varying) OWNER TO csgadmin;

--
-- Name: fn_mis_nominal_index_to_book_no_5(bigint, date, date, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_nominal_index_to_book_no_5(_srocode bigint, _fromdate date, _todate date, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, sroname character varying, nameofdepositor text, placeofresidence character varying, volumeaspagenumber text, serialnumberofdocuments text, remarks character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize); 	
return query 
		 SELECT DISTINCT --a.executiondatetime,
    --b.districtcode,
    c.districtnamee AS district,
    b.sronamee AS sroname,
    COALESCE(concat(pi.firstname, pi.middlename, pi.lastname), NULL::text) AS nameofdepositor,
    COALESCE(pi.address, NULL::character varying) AS placeofresidence,
   -- (((d.volumnnumber || ' '::text) || d.frompagenumber) || ' '::text) || d.topagenumber AS volumeaspagenumber,
  --  NULL::text AS serialnumberofdocuments,
   ( a.finalregistrationnumber::text ||' '::text) || a.pagecount AS volumeaspagenumber,
   a.documentnumber::text AS serialnumberofdocuments,
    a.remarksbyuser AS remarks
   FROM kaveri.documentmaster a
     LEFT JOIN kaveri.sromaster b ON a.srocode = b.srocode
     LEFT JOIN kaveri.districtmaster c ON b.districtcode = c.districtcode
     LEFT JOIN kaveri.partyinfo pi ON a.documentid = pi.documentid
     LEFT JOIN kaveri.referencemaster d ON a.documentid = d.documentid
	 where a.srocode = _srocode and a.registrationdatetime >= _fromdate and
	 a.registrationdatetime <= _todate and isregistrationcompleted = true;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_nominal_index_to_book_no_5(_srocode bigint, _fromdate date, _todate date, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_other_department_import_report(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_other_department_import_report(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(officename character varying, finalregistrationnumber character varying, propertyidentificationnumber character varying, importedxml character varying, exportedxml character varying, referencenumber character varying, uploaddate timestamp without time zone, registrationdate timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	 
if (_districtcode > 0 and _srocode > 0) then
return query
select distinct e.sronamee as officename,
a.finalregistrationnumber,
d.currentnumber as propertyidentificationnumber,
b.transxmlpath as importedXML,
b.transxmlpath as exportedXML,
b.referenceno as referencenumber,
b.actiondatetime as uploaddate,
a.registrationdatetime as registrationdate
from kaveri.documentmaster a  left join kaveri.fruits_data_recv_details b on
a.documentid = b.documentid
left join kaveri.propertymaster c on a.documentid = c.documentid
left join kaveri.propertynumberdetails d on c.propertyid = d.propertyid
left join kaveri.sromaster e on a.srocode = e.srocode 
where e.districtcode = _districtcode  and e.srocode = _srocode and a.registrationdatetime >= _fromdate and 
a.registrationdatetime <= _todate and currentnumber is not null;
elsif (_districtcode = 0 and _srocode = 0) then
return query
select distinct e.sronamee as officename,
a.finalregistrationnumber,
d.currentnumber as propertyidentificationnumber,
b.transxmlpath as importedXML,
b.transxmlpath as exportedXML,
b.referenceno as referencenumber,
b.actiondatetime as uploaddate,
a.registrationdatetime as registrationdate
from kaveri.documentmaster a  left join kaveri.fruits_data_recv_details b on
a.documentid = b.documentid
left join kaveri.propertymaster c on a.documentid = c.documentid
left join kaveri.propertynumberdetails d on c.propertyid = d.propertyid
left join kaveri.sromaster e on a.srocode = e.srocode 
where  a.registrationdatetime >= _fromdate  and 
a.registrationdatetime <= _todate and currentnumber is not null;
end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_other_department_import_report(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_pages_scanned_and_fee_collected(integer, timestamp without time zone, timestamp without time zone, numeric, numeric, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_pages_scanned_and_fee_collected(_srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _minval numeric DEFAULT NULL::numeric, _maxval numeric DEFAULT NULL::numeric, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(sroofficename character varying, totaldocumentsregistered_before bigint, totalnumberofpagesscanned_before bigint, scanningfeecollected_before numeric, totaldocumentsregistered_withinthemonth bigint, totalnumberofpagesscanned_withinthemonth bigint, scanningfeecollected_withinthemonth numeric, totaldocuments bigint, totalnumberofpagesscanned bigint, totalscanningfeecollected numeric)
    LANGUAGE plpgsql
    AS $$
 
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize); 
return query 
select distinct
b.sronamee as sroofficename,
beforemonth.Totaldocumentsregistered_before,
beforemonth.totalnumberofpagesscanned_before,
beforemonth.scanningfeecollected_before,
withinthemonth.Totaldocumentsregistered_withinthemonth,
withinthemonth.totalnumberofpagesscanned_withinthemonth,
withinthemonth.scanningfeecollected_withinthemonth,
(beforemonth.Totaldocumentsregistered_before +
withinthemonth.Totaldocumentsregistered_withinthemonth) Totaldocuments,
(beforemonth.totalnumberofpagesscanned_before +
 withinthemonth.totalnumberofpagesscanned_withinthemonth) Totalnumberofpagesscanned,
 (beforemonth.scanningfeecollected_before +
 withinthemonth.scanningfeecollected_withinthemonth) Totalscanningfeecollected
from  kaveri.sromaster b 
join ( select distinct c.srocode,
count(c.documentid) as Totaldocumentsregistered_before,
sum(d.noofscanpages) as totalnumberofpagesscanned_before,
case when c.feerulecode = 2 then
sum(amountpaid) else 0 end as scanningfeecollected_before
from kaveri.feesrequired c join kaveri.propertymaster d on c.documentid = d.documentid
join kaveri.documentmaster a on d.documentid = a.documentid
where a.registrationdatetime < _fromdate
group by c.feerulecode,c.srocode
) beforemonth on b.srocode = beforemonth.srocode
join ( select distinct c.srocode,
count(c.documentid) as Totaldocumentsregistered_withinthemonth,
sum(d.noofscanpages) as totalnumberofpagesscanned_withinthemonth,
case when c.feerulecode = 2 then
sum(amountpaid) else 0 end as scanningfeecollected_withinthemonth
from kaveri.feesrequired c join kaveri.propertymaster d on c.documentid = d.documentid
join kaveri.documentmaster a on d.documentid = a.documentid
where a.registrationdatetime >= _fromdate and a.registrationdatetime < _todate
group by c.feerulecode,c.srocode
) withinthemonth on beforemonth.srocode = beforemonth.srocode
where 
b.srocode = 173 and (beforemonth.scanningfeecollected_before +
 withinthemonth.scanningfeecollected_withinthemonth) > _minval and
 (beforemonth.scanningfeecollected_before +
 withinthemonth.scanningfeecollected_withinthemonth) <= _maxval;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_pages_scanned_and_fee_collected(_srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _minval numeric, _maxval numeric, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_paymentmodewise(bigint, integer, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_paymentmodewise(_districtcode bigint, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS TABLE(districtnamee character varying, sronamee character varying, documentsregistered bigint, challan_amount_doc numeric, netback_doc numeric, cash_doc numeric, other_doc numeric, total_documentregistration numeric, ecregistered bigint, challan_ec numeric, netbank_ec numeric, cash_ec numeric, other_ec numeric, total_ec numeric, ccregistered bigint, challan_cc numeric, netbank_cc numeric, cash_cc numeric, other_cc numeric, total_cc numeric, anywhereec bigint, anywhereec_online_challan_amount_collected numeric, anywhereec_online_netbanking_amount_collected numeric, anywhereec_online_cash_amount_collected numeric, anywhereec_others_amount_collected numeric, anywhereec_total_amount numeric, others bigint, others_online_challan_amount_collected numeric, others_online_netbanking_amount_collected numeric, cash_other numeric, others_amount_collected numeric, others_total_amount numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN	
		
			if _districtcode=0 THEN --All district
			return query
			
				select 
				dsm.districtnamee,
				s.sronamee,
				tab1.documentsregistered,
				tab1.challan_amount_doc,
				tab1.netback_doc,
				tab1.cash_doc,
				tab1.other_doc,
				tab1.Total_amount,
				tab2.noofecregistered,
				tab2.challan_amount_doc,
				tab2.netback_doc,
				tab2.cash_doc,
				tab2.other_doc,
				tab2.Total_amount,
				tab3.noofccregistered,
				tab3.challan_amount_doc,
				tab3.netback_doc,
				tab3.cash_doc,
				tab3.other_doc,
				tab3.Total_amount,
				tab4.noof_any_ccregistered,
				tab4.challan_amount_doc,
				tab4.netback_doc,
				tab4.cash_doc,
				tab4.other_doc,
				tab4.Total_amount,
				tab5.otherregistered,
				tab5.challan_other,
				tab5.netbank_other,
				tab5.cash_other,
				tab5.other_other,
				tab5.Total_other

				from 

				kaveri.sromaster s
				join kaveri.districtmaster dsm on dsm.districtcode=s.districtcode
				--and dsm.districtcode=_districtcode and d.srocode=_srocode 
				left join

				(select		 d.srocode,
							count(distinct d.applicationnumber) as documentsregistered,
							sum(case when  paymentmodeid = 2 then  -- by challan
							f.amountpaid else 0 end )as challan_amount_doc,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							f.amountpaid else 0 end )as netback_doc,
							sum(case when  paymentmodeid = 1 then  -- By cash
							f.amountpaid else 0 end )as cash_doc,
							sum(case when  paymentmodeid = 3 then  -- others
							f.amountpaid else 0 end )as other_doc,
							sum(case when paymentmodeid = 2 then
							f.amountpaid else 0 end) +
							sum(case when  paymentmodeid = 4 then
							f.amountpaid else 0 end) +
							sum(case when  paymentmodeid = 1 then
							f.amountpaid  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							f.amountpaid else 0 end ) as Total_amount 

				from 
				kaveri.documentmaster d 
				left join kaveri.feesrequired f on d.applicationnumber=f.applicationnumber 

				left join (select distinct *   from kaveri.receiptpaymentdetails r  ) 
				rpd on  rpd.srocode=f.srocode and rpd.receiptid=f.receiptid
				where d.registrationdatetime::date>=_fromdate and d.registrationdatetime::date<=_todate
				and f.receiptid is not null

				group by d.srocode) tab1 on s.srocode=tab1.srocode 

				left join 

				(select
						
					 ea.kaverisrocode,
					 count(distinct ea.applicationnumber) as noofecregistered,
							sum(case when  paymentmodeid = 2 then  -- by challan
							er.payableamount else 0 end )as challan_amount_doc,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							er.payableamount else 0 end )as netback_doc,
							sum(case when  paymentmodeid = 1 then  -- By cash
							er.payableamount else 0 end )as cash_doc,
							sum(case when  paymentmodeid = 3 then  -- others
							er.payableamount else 0 end )as other_doc,
							sum(case when paymentmodeid = 2 then
							er.payableamount else 0 end) +
							sum(case when  paymentmodeid = 4 then
							er.payableamount else 0 end) +
							sum(case when  paymentmodeid = 1 then
							er.payableamount  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							er.payableamount else 0 end ) as Total_amount 

							from 
							kaveri.ec_applicationdetails ea 
							join kaveri.applicantapplicationdetails a on ea.applicationnumber=a.applicationnumber 
							join kaveri.ec_requiredfees er  on ea.ecid =er.ecid 
							left join kaveri.ams_reg_epaymenttransdetails are2 on are2.applicationnumber=ea.applicationnumber 
							left join (select distinct *   from kaveri.receiptpaymentdetails r  ) rpd on  are2.receiptid=rpd.receiptid

							where ea.submitteddatetime ::date>=_fromdate 
							and ea.submitteddatetime::date<=_todate  and a.currentstatus='CE110'
							group by ea.kaverisrocode)tab2 on s.srocode=tab2.kaverisrocode

							left join 
							(select
						
							ca.kaverisrocode,	
							count(distinct ca.applicationnumber) as noofccregistered,
							sum(case when  paymentmodeid = 2 then  -- by challan
							cr.payableamount else 0 end )as challan_amount_doc,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							cr.payableamount else 0 end )as netback_doc,
							sum(case when  paymentmodeid = 1 then  -- By cash
							cr.payableamount else 0 end )as cash_doc,
							sum(case when  paymentmodeid = 3 then  -- others
							cr.payableamount else 0 end )as other_doc,
							sum(case when paymentmodeid = 2 then
							cr.payableamount else 0 end) +
							sum(case when  paymentmodeid = 4 then
							cr.payableamount else 0 end) +
							sum(case when  paymentmodeid = 1 then
							cr.payableamount  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							cr.payableamount else 0 end ) as Total_amount 

							from 
							kaveri.cc_applicationdetails ca 
							join kaveri.applicantapplicationdetails a on ca.applicationnumber=a.applicationnumber 
							join kaveri.cc_requiredfees cr    on ca.ccid  =cr.ccid  
							left join kaveri.ams_reg_epaymenttransdetails are2 on are2.applicationnumber=ca.applicationnumber 
							left join (select distinct *   from kaveri.receiptpaymentdetails r  ) rpd on  are2.receiptid=rpd.receiptid

							where ca.submitteddatetime  ::date>=_fromdate and ca.submitteddatetime::date<=_todate 
							and a.currentstatus='CC109'
							group by ca.kaverisrocode)tab3 on s.srocode=tab3.kaverisrocode

						left join 
							(		select
							ea.kaverisrocode,	
						
							count(distinct ea.applicationnumber) as noof_any_ccregistered,
							sum(case when  paymentmodeid = 2 then  -- by challan
							er.payableamount else 0 end )as challan_amount_doc,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							er.payableamount else 0 end )as netback_doc,
							sum(case when  paymentmodeid = 1 then  -- By cash
							er.payableamount else 0 end )as cash_doc,
							sum(case when  paymentmodeid = 3 then  -- others
							er.payableamount else 0 end )as other_doc,
							sum(case when paymentmodeid = 2 then
							er.payableamount else 0 end) +
							sum(case when  paymentmodeid = 4 then
							er.payableamount else 0 end) +
							sum(case when  paymentmodeid = 1 then
							er.payableamount  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							er.payableamount else 0 end ) as Total_amount 

							from 
							kaveri.ec_applicationdetails ea 
							join kaveri.applicantapplicationdetails a on ea.applicationnumber=a.applicationnumber 
							join kaveri.anywhere_reg_log arl on arl.applicationnumber=ea.applicationnumber
							join kaveri.ec_requiredfees er  on ea.ecid =er.ecid 
							left join kaveri.ams_reg_epaymenttransdetails are2 on are2.applicationnumber=ea.applicationnumber 
							left join (select distinct *   from kaveri.receiptpaymentdetails r  ) rpd on  are2.receiptid=rpd.receiptid

							where ea.submitteddatetime ::date>=_fromdate and ea.submitteddatetime::date<=_todate 
							and a.currentstatus='CE110'
							group by  ea.kaverisrocode)tab4 on s.srocode=tab4.kaverisrocode
							left join 

							(select 	 b.regsrocode,

							count(distinct b.applicationnumber) as otherregistered,
							sum(case when paymentmodeid = 2 then -- by challan
							ar1.amount else 0 end )as  challan_other ,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							ar1.amount else 0 end )as netbank_other,
							sum(case when  paymentmodeid = 1 then  -- By cash
							ar1.amount else 0 end )as cash_other,
							sum(case when paymentmodeid = 3 then  -- others
							ar1.amount else 0 end )as other_other,
							sum(case when  paymentmodeid = 2 then
							ar1.amount else 0 end) +
							sum(case when  paymentmodeid = 4 then
							ar1.amount else 0 end) +
							sum(case when  paymentmodeid = 1 then
							ar1.amount  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							ar1.amount else 0 end ) as Total_other
							from 
							kaveri.applicantapplicationdetails b
							left join
							(select applicationnumber,deptreferencecode,receiptid,sum(totalamount) as amount
								  from kaveri.ams_reg_epaymenttransdetails group by applicationnumber,deptreferencecode,receiptid)
								  ar1 on b.applicationnumber=ar1.applicationnumber 
							left join kaveri.servicesmaster e on b.applicationtypeid = e.serviceid
							left join kaveri.receiptpaymentdetails rpd on  ar1.receiptid=rpd.receiptid
							where serviceid not in (1,12,13)
							group by b.regsrocode ) tab5 on s.srocode=tab5.regsrocode
								
							
							where coalesce(tab1.documentsregistered,0)+coalesce(tab2.noofecregistered,0)+coalesce(tab3.noofccregistered,0)+
							coalesce(tab4.noof_any_ccregistered,0)+coalesce(tab5.otherregistered,0) >0;
							

			
		elsif _srocode=0 then  --perticular district all sro
		
			return query
						select 
				dsm.districtnamee,
				s.sronamee,
			  tab1.documentsregistered,tab1.challan_amount_doc,
