				tab2.noofecregistered,tab2.challan_amount_doc,tab2.netback_doc,tab2.cash_doc,tab2.other_doc,tab2.Total_amount,
				tab3.noofccregistered,tab3.challan_amount_doc,tab3.netback_doc,tab3.cash_doc,tab3.other_doc,tab3.Total_amount,
				tab4.noof_any_ccregistered,tab4.challan_amount_doc,tab4.netback_doc,tab4.cash_doc,tab4.other_doc,tab4.Total_amount,
				tab5.otherregistered,tab5.challan_other,tab5.netbank_other,tab5.cash_other,tab5.other_other,tab5.Total_other

