							coalesce(tab4.noof_any_ccregistered,0)+coalesce(tab5.otherregistered,0) >0;
			
			
		end if;
			
			

end;
$$;


ALTER FUNCTION kaverimis.fn_mis_paymentmodewise(_districtcode bigint, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_mis_paymentmodewise(bigint, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_paymentmodewise(_districtcode bigint, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtnamee character varying, sronamee character varying, documentsregistered bigint, challan_amount_doc numeric, netback_doc numeric, cash_doc numeric, other_doc numeric, total_documentregistration numeric, ecregistered bigint, challan_ec numeric, netbank_ec numeric, cash_ec numeric, other_ec numeric, total_ec numeric, ccregistered bigint, challan_cc numeric, netbank_cc numeric, cash_cc numeric, other_cc numeric, total_cc numeric, anywhereec bigint, anywhereec_online_challan_amount_collected numeric, anywhereec_online_netbanking_amount_collected numeric, anywhereec_online_cash_amount_collected numeric, anywhereec_others_amount_collected numeric, anywhereec_total_amount numeric, others bigint, others_online_challan_amount_collected numeric, others_online_netbanking_amount_collected numeric, cash_other numeric, others_amount_collected numeric, others_total_amount numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

declare
PageOffset INTEGER := 0;


BEGIN	
	PageOffset := ((pagenumber - 1) * pagesize);
		
			if _districtcode=0 THEN --All district
			return query
			
				with cte as (select 
				dsm.districtnamee,
				s.sronamee,
				tab1.documentsregistered,
				tab1.challan_amount_doc,
				tab1.netback_doc,
				tab1.cash_doc,
				tab1.other_doc,
				tab1.Total_amount,
				tab2.noofecregistered,
				tab2.challan_amount_doc,
				tab2.netback_doc,
				tab2.cash_doc,
				tab2.other_doc,
				tab2.Total_amount,
				tab3.noofccregistered,
				tab3.challan_amount_doc,
				tab3.netback_doc,
				tab3.cash_doc,
				tab3.other_doc,
				tab3.Total_amount,
				tab4.noof_any_ccregistered,
				tab4.challan_amount_doc,
				tab4.netback_doc,
				tab4.cash_doc,
				tab4.other_doc,
				tab4.Total_amount,
				tab5.otherregistered,
				tab5.challan_other,
