							--case when paymentmodeid = 2 then -- by challan		ar1.amount else 0 end 
							)as  challan_other ,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							ar1.amount else 0 end )as netbank_other,
							sum(case when  paymentmodeid = 1 then  -- By cash
							ar1.amount else 0 end )as cash_other,
							sum(case when paymentmodeid = 3 then  -- others
							ar1.amount else 0 end )as other_other,
							sum(case when  paymentmodeid = 2 then
							ar1.amount else 0 end) +
							sum(case when  paymentmodeid = 4 then
							ar1.amount else 0 end) +
							sum(case when  paymentmodeid = 1 then
							ar1.amount  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							ar1.amount else 0 end ) as Total_other
							from 
							kaveri.applicantapplicationdetails b
							left join
							(select applicationnumber,deptreferencecode,receiptid,
							sum(totalamount) as amount
								  from kaveri.ams_reg_epaymenttransdetails
								  where paymentstatuscode in ('10700066','10700072')
								  group by applicationnumber,deptreferencecode,receiptid)
								  ar1 on b.applicationnumber=ar1.applicationnumber 
							left join kaveri.servicesmaster e on b.applicationtypeid = e.serviceid
							left join kaveri.receiptpaymentdetails rpd on  ar1.receiptid=rpd.receiptid
							where serviceid not in (1,12,13)
							group by b.regsrocode ) tab5 on s.srocode=tab5.regsrocode
								
							
							where coalesce(tab1.documentsregistered,0)+
							coalesce(tab2.noofecregistered,0)+coalesce(tab3.noofccregistered,0)+
							coalesce(tab4.noof_any_ccregistered,0)+
							coalesce(tab5.otherregistered,0) >0),
							cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
			
			
		end if;
			
			

end;
$$;


ALTER FUNCTION kaverimis.fn_mis_paymentmodewise(_districtcode bigint, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_paymentmodewise_23012024(bigint, integer, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_paymentmodewise_23012024(_districtcode bigint, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS TABLE(districtnamee character varying, sronamee character varying, documentsregistered bigint, challan_amount_doc numeric, netback_doc numeric, cash_doc numeric, other_doc numeric, total_documentregistration numeric, ecregistered bigint, challan_ec numeric, netbank_ec numeric, cash_ec numeric, other_ec numeric, total_ec numeric, ccregistered bigint, challan_cc numeric, netbank_cc numeric, cash_cc numeric, other_cc numeric, total_cc numeric, anywhereec bigint, anywhereec_online_challan_amount_collected numeric, anywhereec_online_netbanking_amount_collected numeric, anywhereec_online_cash_amount_collected numeric, anywhereec_others_amount_collected numeric, anywhereec_total_amount numeric, others bigint, others_online_challan_amount_collected numeric, others_online_netbanking_amount_collected numeric, cash_other numeric, others_amount_collected numeric, others_total_amount numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN	
		
			if _districtcode=0 THEN --All district
			return query
			
				select 
				dsm.districtnamee,
				s.sronamee,
				tab1.documentsregistered,
				tab1.challan_amount_doc,
				tab1.netback_doc,
				tab1.cash_doc,
				tab1.other_doc,
				tab1.Total_amount,
				tab2.noofecregistered,
				tab2.challan_amount_doc,
				tab2.netback_doc,
				tab2.cash_doc,
				tab2.other_doc,
				tab2.Total_amount,
				tab3.noofccregistered,
				tab3.challan_amount_doc,
				tab3.netback_doc,
				tab3.cash_doc,
				tab3.other_doc,
				tab3.Total_amount,
				tab4.noof_any_ccregistered,
				tab4.challan_amount_doc,
				tab4.netback_doc,
				tab4.cash_doc,
				tab4.other_doc,
				tab4.Total_amount,
				tab5.otherregistered,
				tab5.challan_other,
				tab5.netbank_other,
				tab5.cash_other,
				tab5.other_other,
				tab5.Total_other

				from 

				kaveri.sromaster s
				join kaveri.districtmaster dsm on dsm.districtcode=s.districtcode
				--and dsm.districtcode=_districtcode and d.srocode=_srocode 
				left join

				(select		 d.srocode,
							count(distinct d.applicationnumber) as documentsregistered,
							sum(case when  paymentmodeid = 2 then  -- by challan
							f.amountpaid else 0 end )as challan_amount_doc,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							f.amountpaid else 0 end )as netback_doc,
							sum(case when  paymentmodeid = 1 then  -- By cash
							f.amountpaid else 0 end )as cash_doc,
							sum(case when  paymentmodeid = 3 then  -- others
							f.amountpaid else 0 end )as other_doc,
							sum(case when paymentmodeid = 2 then
							f.amountpaid else 0 end) +
							sum(case when  paymentmodeid = 4 then
							f.amountpaid else 0 end) +
							sum(case when  paymentmodeid = 1 then
							f.amountpaid  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							f.amountpaid else 0 end ) as Total_amount 

				from 
				kaveri.documentmaster d 
				left join kaveri.feesrequired f on d.applicationnumber=f.applicationnumber 

				left join (select distinct *   from kaveri.receiptpaymentdetails r  ) 
				rpd on  rpd.srocode=f.srocode and rpd.receiptid=f.receiptid
				where d.registrationdatetime::date>=_fromdate and d.registrationdatetime::date<=_todate
				and f.receiptid is not null

				group by d.srocode) tab1 on s.srocode=tab1.srocode 

				left join 

				(select
						
					 ea.kaverisrocode,
					 count(distinct ea.applicationnumber) as noofecregistered,
							sum(case when  paymentmodeid = 2 then  -- by challan
							er.payableamount else 0 end )as challan_amount_doc,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							er.payableamount else 0 end )as netback_doc,
							sum(case when  paymentmodeid = 1 then  -- By cash
							er.payableamount else 0 end )as cash_doc,
							sum(case when  paymentmodeid = 3 then  -- others
							er.payableamount else 0 end )as other_doc,
							sum(case when paymentmodeid = 2 then
							er.payableamount else 0 end) +
							sum(case when  paymentmodeid = 4 then
							er.payableamount else 0 end) +
							sum(case when  paymentmodeid = 1 then
							er.payableamount  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							er.payableamount else 0 end ) as Total_amount 

							from 
							kaveri.ec_applicationdetails ea 
							join kaveri.applicantapplicationdetails a on ea.applicationnumber=a.applicationnumber 
							join kaveri.ec_requiredfees er  on ea.ecid =er.ecid 
							left join kaveri.ams_reg_epaymenttransdetails are2 on are2.applicationnumber=ea.applicationnumber 
							left join (select distinct *   from kaveri.receiptpaymentdetails r  ) rpd on  are2.receiptid=rpd.receiptid

							where ea.submitteddatetime ::date>=_fromdate 
							and ea.submitteddatetime::date<=_todate  and a.currentstatus='CE110'
							group by ea.kaverisrocode)tab2 on s.srocode=tab2.kaverisrocode

							left join 
							(select
						
							ca.kaverisrocode,	
							count(distinct ca.applicationnumber) as noofccregistered,
							sum(case when  paymentmodeid = 2 then  -- by challan
							cr.payableamount else 0 end )as challan_amount_doc,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							cr.payableamount else 0 end )as netback_doc,
							sum(case when  paymentmodeid = 1 then  -- By cash
							cr.payableamount else 0 end )as cash_doc,
							sum(case when  paymentmodeid = 3 then  -- others
							cr.payableamount else 0 end )as other_doc,
							sum(case when paymentmodeid = 2 then
							cr.payableamount else 0 end) +
							sum(case when  paymentmodeid = 4 then
							cr.payableamount else 0 end) +
							sum(case when  paymentmodeid = 1 then
							cr.payableamount  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							cr.payableamount else 0 end ) as Total_amount 

							from 
							kaveri.cc_applicationdetails ca 
							join kaveri.applicantapplicationdetails a on ca.applicationnumber=a.applicationnumber 
							join kaveri.cc_requiredfees cr    on ca.ccid  =cr.ccid  
							left join kaveri.ams_reg_epaymenttransdetails are2 on are2.applicationnumber=ca.applicationnumber 
							left join (select distinct *   from kaveri.receiptpaymentdetails r  ) rpd on  are2.receiptid=rpd.receiptid

							where ca.submitteddatetime  ::date>=_fromdate and ca.submitteddatetime::date<=_todate 
							and a.currentstatus='CC109'
							group by ca.kaverisrocode)tab3 on s.srocode=tab3.kaverisrocode

						left join 
							(		select
							ea.kaverisrocode,	
						
							count(distinct ea.applicationnumber) as noof_any_ccregistered,
							sum(case when  paymentmodeid = 2 then  -- by challan
							er.payableamount else 0 end )as challan_amount_doc,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							er.payableamount else 0 end )as netback_doc,
							sum(case when  paymentmodeid = 1 then  -- By cash
							er.payableamount else 0 end )as cash_doc,
							sum(case when  paymentmodeid = 3 then  -- others
							er.payableamount else 0 end )as other_doc,
							sum(case when paymentmodeid = 2 then
							er.payableamount else 0 end) +
							sum(case when  paymentmodeid = 4 then
							er.payableamount else 0 end) +
							sum(case when  paymentmodeid = 1 then
							er.payableamount  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							er.payableamount else 0 end ) as Total_amount 

							from 
							kaveri.ec_applicationdetails ea 
							join kaveri.applicantapplicationdetails a on ea.applicationnumber=a.applicationnumber 
							join kaveri.anywhere_reg_log arl on arl.applicationnumber=ea.applicationnumber
							join kaveri.ec_requiredfees er  on ea.ecid =er.ecid 
							left join kaveri.ams_reg_epaymenttransdetails are2 on are2.applicationnumber=ea.applicationnumber 
							left join (select distinct *   from kaveri.receiptpaymentdetails r  ) rpd on  are2.receiptid=rpd.receiptid

							where ea.submitteddatetime ::date>=_fromdate and ea.submitteddatetime::date<=_todate 
							and a.currentstatus='CE110'
							group by  ea.kaverisrocode)tab4 on s.srocode=tab4.kaverisrocode
							left join 

							(select 	 b.regsrocode,

							count(distinct b.applicationnumber) as otherregistered,
							sum(case when paymentmodeid = 2 then -- by challan
							ar1.amount else 0 end )as  challan_other ,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							ar1.amount else 0 end )as netbank_other,
							sum(case when  paymentmodeid = 1 then  -- By cash
							ar1.amount else 0 end )as cash_other,
							sum(case when paymentmodeid = 3 then  -- others
							ar1.amount else 0 end )as other_other,
							sum(case when  paymentmodeid = 2 then
							ar1.amount else 0 end) +
							sum(case when  paymentmodeid = 4 then
							ar1.amount else 0 end) +
							sum(case when  paymentmodeid = 1 then
							ar1.amount  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							ar1.amount else 0 end ) as Total_other
							from 
							kaveri.applicantapplicationdetails b
							left join
							(select applicationnumber,deptreferencecode,receiptid,sum(totalamount) as amount
								  from kaveri.ams_reg_epaymenttransdetails group by applicationnumber,deptreferencecode,receiptid)
								  ar1 on b.applicationnumber=ar1.applicationnumber 
							left join kaveri.servicesmaster e on b.applicationtypeid = e.serviceid
							left join kaveri.receiptpaymentdetails rpd on  ar1.receiptid=rpd.receiptid
							where serviceid not in (1,12,13)
							group by b.regsrocode ) tab5 on s.srocode=tab5.regsrocode
								
							
							where coalesce(tab1.documentsregistered,0)+coalesce(tab2.noofecregistered,0)+coalesce(tab3.noofccregistered,0)+
							coalesce(tab4.noof_any_ccregistered,0)+coalesce(tab5.otherregistered,0) >0;
							

			
		elsif _srocode=0 then  --perticular district all sro
		
			return query
						select 
				dsm.districtnamee,
				s.sronamee,
			  tab1.documentsregistered,tab1.challan_amount_doc,
				tab1.netback_doc,tab1.cash_doc,tab1.other_doc,tab1.Total_amount,
				tab2.noofecregistered,tab2.challan_amount_doc,tab2.netback_doc,tab2.cash_doc,tab2.other_doc,tab2.Total_amount,
				tab3.noofccregistered,tab3.challan_amount_doc,tab3.netback_doc,tab3.cash_doc,tab3.other_doc,tab3.Total_amount,
				tab4.noof_any_ccregistered,tab4.challan_amount_doc,tab4.netback_doc,tab4.cash_doc,tab4.other_doc,tab4.Total_amount,
				tab5.otherregistered,tab5.challan_other,tab5.netbank_other,tab5.cash_other,tab5.other_other,tab5.Total_other

				from 

				kaveri.sromaster s
				join kaveri.districtmaster dsm on dsm.districtcode=s.districtcode
				and dsm.districtcode=_districtcode --and d.srocode=_srocode 
				left join

				(select		 d.srocode,
							count(distinct d.applicationnumber) as documentsregistered,
							sum(case when  paymentmodeid = 2 then  -- by challan
							f.amountpaid else 0 end )as challan_amount_doc,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							f.amountpaid else 0 end )as netback_doc,
							sum(case when  paymentmodeid = 1 then  -- By cash
							f.amountpaid else 0 end )as cash_doc,
							sum(case when  paymentmodeid = 3 then  -- others
							f.amountpaid else 0 end )as other_doc,
							sum(case when paymentmodeid = 2 then
							f.amountpaid else 0 end) +
							sum(case when  paymentmodeid = 4 then
							f.amountpaid else 0 end) +
							sum(case when  paymentmodeid = 1 then
							f.amountpaid  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							f.amountpaid else 0 end ) as Total_amount 

				from 
				kaveri.documentmaster d 
				left join kaveri.feesrequired f on d.applicationnumber=f.applicationnumber 

				left join (select distinct *   from kaveri.receiptpaymentdetails r  ) 
				rpd on  rpd.srocode=f.srocode and rpd.receiptid=f.receiptid
				where d.registrationdatetime::date>=_fromdate and d.registrationdatetime::date<=_todate
				and f.receiptid is not null

				group by d.srocode) tab1 on s.srocode=tab1.srocode 

				left join 

				(select
						
					 ea.kaverisrocode,
					 count(distinct ea.applicationnumber) as noofecregistered,
							sum(case when  paymentmodeid = 2 then  -- by challan
							er.payableamount else 0 end )as challan_amount_doc,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							er.payableamount else 0 end )as netback_doc,
							sum(case when  paymentmodeid = 1 then  -- By cash
							er.payableamount else 0 end )as cash_doc,
							sum(case when  paymentmodeid = 3 then  -- others
							er.payableamount else 0 end )as other_doc,
							sum(case when paymentmodeid = 2 then
							er.payableamount else 0 end) +
							sum(case when  paymentmodeid = 4 then
							er.payableamount else 0 end) +
							sum(case when  paymentmodeid = 1 then
							er.payableamount  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							er.payableamount else 0 end ) as Total_amount 

							from 
							kaveri.ec_applicationdetails ea 
							join kaveri.applicantapplicationdetails a on ea.applicationnumber=a.applicationnumber 
							join kaveri.ec_requiredfees er  on ea.ecid =er.ecid 
							left join kaveri.ams_reg_epaymenttransdetails are2 on are2.applicationnumber=ea.applicationnumber 
							left join (select distinct *   from kaveri.receiptpaymentdetails r  ) rpd on  are2.receiptid=rpd.receiptid

							where ea.submitteddatetime ::date>=_fromdate 
							and ea.submitteddatetime::date<=_todate  and a.currentstatus='CE110'
							group by ea.kaverisrocode)tab2 on s.srocode=tab2.kaverisrocode

							left join 
							(select
						
							ca.kaverisrocode,	
							count(distinct ca.applicationnumber) as noofccregistered,
							sum(case when  paymentmodeid = 2 then  -- by challan
							cr.payableamount else 0 end )as challan_amount_doc,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							cr.payableamount else 0 end )as netback_doc,
							sum(case when  paymentmodeid = 1 then  -- By cash
							cr.payableamount else 0 end )as cash_doc,
							sum(case when  paymentmodeid = 3 then  -- others
							cr.payableamount else 0 end )as other_doc,
							sum(case when paymentmodeid = 2 then
							cr.payableamount else 0 end) +
							sum(case when  paymentmodeid = 4 then
							cr.payableamount else 0 end) +
							sum(case when  paymentmodeid = 1 then
							cr.payableamount  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							cr.payableamount else 0 end ) as Total_amount 

							from 
							kaveri.cc_applicationdetails ca 
							join kaveri.applicantapplicationdetails a on ca.applicationnumber=a.applicationnumber 
							join kaveri.cc_requiredfees cr    on ca.ccid  =cr.ccid  
							left join kaveri.ams_reg_epaymenttransdetails are2 on are2.applicationnumber=ca.applicationnumber 
							left join (select distinct *   from kaveri.receiptpaymentdetails r  ) rpd on  are2.receiptid=rpd.receiptid

							where ca.submitteddatetime  ::date>=_fromdate and ca.submitteddatetime::date<=_todate 
							and a.currentstatus='CC109'
							group by ca.kaverisrocode)tab3 on s.srocode=tab3.kaverisrocode

						left join 
							(		select
							ea.kaverisrocode,	
						
							count(distinct ea.applicationnumber) as noof_any_ccregistered,
							sum(case when  paymentmodeid = 2 then  -- by challan
							er.payableamount else 0 end )as challan_amount_doc,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							er.payableamount else 0 end )as netback_doc,
							sum(case when  paymentmodeid = 1 then  -- By cash
							er.payableamount else 0 end )as cash_doc,
							sum(case when  paymentmodeid = 3 then  -- others
							er.payableamount else 0 end )as other_doc,
							sum(case when paymentmodeid = 2 then
							er.payableamount else 0 end) +
							sum(case when  paymentmodeid = 4 then
							er.payableamount else 0 end) +
							sum(case when  paymentmodeid = 1 then
							er.payableamount  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							er.payableamount else 0 end ) as Total_amount 

							from 
							kaveri.ec_applicationdetails ea 
							join kaveri.applicantapplicationdetails a on ea.applicationnumber=a.applicationnumber 
							join kaveri.anywhere_reg_log arl on arl.applicationnumber=ea.applicationnumber
							join kaveri.ec_requiredfees er  on ea.ecid =er.ecid 
							left join kaveri.ams_reg_epaymenttransdetails are2 on are2.applicationnumber=ea.applicationnumber 
							left join (select distinct *   from kaveri.receiptpaymentdetails r  ) rpd on  are2.receiptid=rpd.receiptid

							where ea.submitteddatetime ::date>=_fromdate and ea.submitteddatetime::date<=_todate 
							and a.currentstatus='CE110'
							group by  ea.kaverisrocode)tab4 on s.srocode=tab4.kaverisrocode
							left join 

							(select 	 b.regsrocode,

							count(distinct b.applicationnumber) as otherregistered,
							sum(case when paymentmodeid = 2 then -- by challan
							ar1.amount else 0 end )as  challan_other ,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							ar1.amount else 0 end )as netbank_other,
							sum(case when  paymentmodeid = 1 then  -- By cash
							ar1.amount else 0 end )as cash_other,
							sum(case when paymentmodeid = 3 then  -- others
							ar1.amount else 0 end )as other_other,
							sum(case when  paymentmodeid = 2 then
							ar1.amount else 0 end) +
							sum(case when  paymentmodeid = 4 then
							ar1.amount else 0 end) +
							sum(case when  paymentmodeid = 1 then
							ar1.amount  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							ar1.amount else 0 end ) as Total_other
							from 
							kaveri.applicantapplicationdetails b
							left join
							(select applicationnumber,deptreferencecode,receiptid,sum(totalamount) as amount
								  from kaveri.ams_reg_epaymenttransdetails group by applicationnumber,deptreferencecode,receiptid)
								  ar1 on b.applicationnumber=ar1.applicationnumber 
							left join kaveri.servicesmaster e on b.applicationtypeid = e.serviceid
							left join kaveri.receiptpaymentdetails rpd on  ar1.receiptid=rpd.receiptid
							where serviceid not in (1,12,13)
							group by b.regsrocode ) tab5 on s.srocode=tab5.regsrocode
								
							
							where coalesce(tab1.documentsregistered,0)+coalesce(tab2.noofecregistered,0)+coalesce(tab3.noofccregistered,0)+
							coalesce(tab4.noof_any_ccregistered,0)+coalesce(tab5.otherregistered,0) >0;
			
			ELSE --perticular district and perticular srocode
			
			return query
					select 
				dsm.districtnamee,
				s.sronamee,
				tab1.documentsregistered,tab1.challan_amount_doc,
				tab1.netback_doc,tab1.cash_doc,tab1.other_doc,tab1.Total_amount,
				tab2.noofecregistered,tab2.challan_amount_doc,tab2.netback_doc,tab2.cash_doc,tab2.other_doc,tab2.Total_amount,
				tab3.noofccregistered,tab3.challan_amount_doc,tab3.netback_doc,tab3.cash_doc,tab3.other_doc,tab3.Total_amount,
				tab4.noof_any_ccregistered,tab4.challan_amount_doc,tab4.netback_doc,tab4.cash_doc,tab4.other_doc,tab4.Total_amount,
				tab5.otherregistered,tab5.challan_other,tab5.netbank_other,tab5.cash_other,tab5.other_other,tab5.Total_other

				from 

				kaveri.sromaster s
				join kaveri.districtmaster dsm on dsm.districtcode=s.districtcode
				and dsm.districtcode=_districtcode and s.srocode=_srocode 
				left join

				(select		 d.srocode,
							count(distinct d.applicationnumber) as documentsregistered,
							sum(case when  paymentmodeid = 2 then  -- by challan
							f.amountpaid else 0 end )as challan_amount_doc,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							f.amountpaid else 0 end )as netback_doc,
							sum(case when  paymentmodeid = 1 then  -- By cash
							f.amountpaid else 0 end )as cash_doc,
							sum(case when  paymentmodeid = 3 then  -- others
							f.amountpaid else 0 end )as other_doc,
							sum(case when paymentmodeid = 2 then
							f.amountpaid else 0 end) +
							sum(case when  paymentmodeid = 4 then
							f.amountpaid else 0 end) +
							sum(case when  paymentmodeid = 1 then
							f.amountpaid  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							f.amountpaid else 0 end ) as Total_amount 

				from 
				kaveri.documentmaster d 
				left join kaveri.feesrequired f on d.applicationnumber=f.applicationnumber 

				left join (select distinct *   from kaveri.receiptpaymentdetails r  ) 
				rpd on  rpd.srocode=f.srocode and rpd.receiptid=f.receiptid
				where d.registrationdatetime::date>=_fromdate and d.registrationdatetime::date<=_todate
				and f.receiptid is not null

				group by d.srocode) tab1 on s.srocode=tab1.srocode 

				left join 

				(select
						
					 ea.kaverisrocode,
					 count(distinct ea.applicationnumber) as noofecregistered,
							sum(case when  paymentmodeid = 2 then  -- by challan
							er.payableamount else 0 end )as challan_amount_doc,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							er.payableamount else 0 end )as netback_doc,
							sum(case when  paymentmodeid = 1 then  -- By cash
							er.payableamount else 0 end )as cash_doc,
							sum(case when  paymentmodeid = 3 then  -- others
							er.payableamount else 0 end )as other_doc,
							sum(case when paymentmodeid = 2 then
							er.payableamount else 0 end) +
							sum(case when  paymentmodeid = 4 then
							er.payableamount else 0 end) +
							sum(case when  paymentmodeid = 1 then
							er.payableamount  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							er.payableamount else 0 end ) as Total_amount 

							from 
							kaveri.ec_applicationdetails ea 
							join kaveri.applicantapplicationdetails a on ea.applicationnumber=a.applicationnumber 
							join kaveri.ec_requiredfees er  on ea.ecid =er.ecid 
							left join kaveri.ams_reg_epaymenttransdetails are2 on are2.applicationnumber=ea.applicationnumber 
							left join (select distinct *   from kaveri.receiptpaymentdetails r  ) rpd on  are2.receiptid=rpd.receiptid

							where ea.submitteddatetime ::date>=_fromdate 
							and ea.submitteddatetime::date<=_todate  and a.currentstatus='CE110'
							group by ea.kaverisrocode)tab2 on s.srocode=tab2.kaverisrocode

							left join 
							(select
						
							ca.kaverisrocode,	
							count(distinct ca.applicationnumber) as noofccregistered,
							sum(case when  paymentmodeid = 2 then  -- by challan
							cr.payableamount else 0 end )as challan_amount_doc,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							cr.payableamount else 0 end )as netback_doc,
							sum(case when  paymentmodeid = 1 then  -- By cash
							cr.payableamount else 0 end )as cash_doc,
							sum(case when  paymentmodeid = 3 then  -- others
							cr.payableamount else 0 end )as other_doc,
							sum(case when paymentmodeid = 2 then
							cr.payableamount else 0 end) +
							sum(case when  paymentmodeid = 4 then
							cr.payableamount else 0 end) +
							sum(case when  paymentmodeid = 1 then
							cr.payableamount  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							cr.payableamount else 0 end ) as Total_amount 

							from 
							kaveri.cc_applicationdetails ca 
							join kaveri.applicantapplicationdetails a on ca.applicationnumber=a.applicationnumber 
							join kaveri.cc_requiredfees cr    on ca.ccid  =cr.ccid  
							left join kaveri.ams_reg_epaymenttransdetails are2 on are2.applicationnumber=ca.applicationnumber 
							left join (select distinct *   from kaveri.receiptpaymentdetails r  ) rpd on  are2.receiptid=rpd.receiptid

							where ca.submitteddatetime  ::date>=_fromdate and ca.submitteddatetime::date<=_todate 
							and a.currentstatus='CC109'
							group by ca.kaverisrocode)tab3 on s.srocode=tab3.kaverisrocode

						left join 
							(		select
							ea.kaverisrocode,	
						
							count(distinct ea.applicationnumber) as noof_any_ccregistered,
							sum(case when  paymentmodeid = 2 then  -- by challan
							er.payableamount else 0 end )as challan_amount_doc,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							er.payableamount else 0 end )as netback_doc,
							sum(case when  paymentmodeid = 1 then  -- By cash
							er.payableamount else 0 end )as cash_doc,
							sum(case when  paymentmodeid = 3 then  -- others
							er.payableamount else 0 end )as other_doc,
							sum(case when paymentmodeid = 2 then
							er.payableamount else 0 end) +
							sum(case when  paymentmodeid = 4 then
							er.payableamount else 0 end) +
							sum(case when  paymentmodeid = 1 then
							er.payableamount  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							er.payableamount else 0 end ) as Total_amount 

							from 
							kaveri.ec_applicationdetails ea 
							join kaveri.applicantapplicationdetails a on ea.applicationnumber=a.applicationnumber 
							join kaveri.anywhere_reg_log arl on arl.applicationnumber=ea.applicationnumber
							join kaveri.ec_requiredfees er  on ea.ecid =er.ecid 
							left join kaveri.ams_reg_epaymenttransdetails are2 on are2.applicationnumber=ea.applicationnumber 
							left join (select distinct *   from kaveri.receiptpaymentdetails r  ) rpd on  are2.receiptid=rpd.receiptid

							where ea.submitteddatetime ::date>=_fromdate and ea.submitteddatetime::date<=_todate 
							and a.currentstatus='CE110'
							group by  ea.kaverisrocode)tab4 on s.srocode=tab4.kaverisrocode
							left join 

							(select 	 b.regsrocode,

							count(distinct b.applicationnumber) as otherregistered,
							sum(case when paymentmodeid = 2 then -- by challan
							ar1.amount else 0 end )as  challan_other ,
							sum(case when  paymentmodeid = 4 then  -- Epayment
							ar1.amount else 0 end )as netbank_other,
							sum(case when  paymentmodeid = 1 then  -- By cash
							ar1.amount else 0 end )as cash_other,
							sum(case when paymentmodeid = 3 then  -- others
							ar1.amount else 0 end )as other_other,
							sum(case when  paymentmodeid = 2 then
							ar1.amount else 0 end) +
							sum(case when  paymentmodeid = 4 then
							ar1.amount else 0 end) +
							sum(case when  paymentmodeid = 1 then
							ar1.amount  else 0 end) +
							sum(case when  paymentmodeid = 3 then
							ar1.amount else 0 end ) as Total_other
							from 
							kaveri.applicantapplicationdetails b
							left join
							(select applicationnumber,deptreferencecode,receiptid,sum(totalamount) as amount
								  from kaveri.ams_reg_epaymenttransdetails group by applicationnumber,deptreferencecode,receiptid)
								  ar1 on b.applicationnumber=ar1.applicationnumber 
							left join kaveri.servicesmaster e on b.applicationtypeid = e.serviceid
							left join kaveri.receiptpaymentdetails rpd on  ar1.receiptid=rpd.receiptid
							where serviceid not in (1,12,13)
							group by b.regsrocode ) tab5 on s.srocode=tab5.regsrocode
								
							
							where coalesce(tab1.documentsregistered,0)+coalesce(tab2.noofecregistered,0)+coalesce(tab3.noofccregistered,0)+
							coalesce(tab4.noof_any_ccregistered,0)+coalesce(tab5.otherregistered,0) >0;
			
			
		end if;
			
			

end;
$$;


ALTER FUNCTION kaverimis.fn_mis_paymentmodewise_23012024(_districtcode bigint, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO csgadmin;

--
-- Name: fn_mis_paymentmodewise_backup_28_03_2023(bigint, integer, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_paymentmodewise_backup_28_03_2023(_districtcode bigint, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS TABLE(districtnamee character varying, sronamee character varying, documentsregistered bigint, challan_amount_doc numeric, netback_doc numeric, cash_doc numeric, other_doc numeric, total_documentregistration numeric, ecregistered bigint, challan_ec numeric, netbank_ec numeric, cash_ec numeric, other_ec numeric, total_ec numeric, ccregistered bigint, challan_cc numeric, netbank_cc numeric, cash_cc numeric, other_cc numeric, total_cc numeric, anywhereec integer, anywhereec_online_challan_amount_collected numeric, anywhereec_online_netbanking_amount_collected numeric, anywhereec_others_amount_collected numeric, anywhereec_total_amount numeric, others bigint, others_online_challan_amount_collected numeric, others_online_netbanking_amount_collected numeric, cash_other numeric, others_amount_collected numeric, others_total_amount numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN	
		
			if _districtcode=0 THEN --All district
			return query
			
			select 

			dsm.districtnamee,
			sm.sronamee,
			/* Document Registration */
			count(case when serviceid = 1 then
			applicationnumber   else null end) as documentsregistered,
			sum(case when serviceid = 1 and paymentmodeid = 2 then  -- by challan
			totalamount else 0 end )as challan_amount_doc,
			sum(case when serviceid = 1 and paymentmodeid = 4 then  -- Epayment
			totalamount else 0 end )as netback_doc,
			sum(case when serviceid = 1 and paymentmodeid = 1 then  -- By cash
			totalamount else 0 end )as cash_doc,
			sum(case when serviceid = 1 and paymentmodeid = 3 then  -- others
			totalamount else 0 end )as other_doc,
			sum(case when serviceid = 1 and paymentmodeid = 2 then
			totalamount else 0 end) +
			sum(case when serviceid = 1 and paymentmodeid = 4 then
			totalamount else 0 end) +
			sum(case when serviceid = 1 and paymentmodeid = 1 then
			totalamount  else 0 end) +
			sum(case when serviceid = 1 and paymentmodeid = 3 then
			totalamount else 0 end ) as Total_documentregistration,

			/* Online EC */

			count(case when serviceid = 13 then
			applicationnumber   else null end) as ECregistered,
			sum(case when serviceid = 13 and paymentmodeid = 2 then  -- by challan
			totalamount else 0 end )as  challan_ec ,
			sum(case when serviceid = 13 and paymentmodeid = 4 then  -- Epayment
			totalamount else 0 end )as netbank_ec,
			sum(case when serviceid = 13 and paymentmodeid = 1 then  -- By cash
