			totalamount else 0 end )as cash_ec,
			sum(case when serviceid = 13 and paymentmodeid = 3 then  -- others
			totalamount else 0 end )as other_ec,
			sum(case when serviceid = 13 and paymentmodeid = 2 then
			totalamount else 0 end) +
			sum(case when serviceid = 13 and paymentmodeid = 4 then
			totalamount else 0 end) +
			sum(case when serviceid = 13 and paymentmodeid = 1 then
			totalamount  else 0 end) +
			sum(case when serviceid = 13 and paymentmodeid = 3 then
			totalamount else 0 end ) as Total_ec,

			/* online CC */

			count(case when serviceid = 12 then
			applicationnumber   else null end) as CCregistered,
			sum(case when serviceid = 12 and paymentmodeid = 2 then  -- by challan
			totalamount else 0 end )as  challan_cc ,
			sum(case when serviceid = 12 and paymentmodeid = 4 then  -- Epayment
			totalamount else 0 end )as netbank_cc,
			sum(case when serviceid = 12 and paymentmodeid = 1 then  -- By cash
			totalamount else 0 end )as cash_cc,
			sum(case when serviceid = 12 and paymentmodeid = 3 then  -- others
			totalamount else 0 end )as other_cc,
			sum(case when serviceid = 12 and paymentmodeid = 2 then
			totalamount else 0 end) +
			sum(case when serviceid = 12 and paymentmodeid = 4 then
			totalamount else 0 end) +
			sum(case when serviceid = 12 and paymentmodeid = 1 then
			totalamount  else 0 end) +
			sum(case when serviceid = 12 and paymentmodeid = 3 then
			totalamount else 0 end ) as Total_cc,

			/* Anywhere ec */

			null::integer as anywhereec,
			null::numeric  as anywhereec_Online_Challan_Amount_Collected,
			null::numeric as anywhereec_Online_Netbanking_Amount_Collected,
			null::numeric as anywhereec_Others_Amount_Collected,
			null::numeric  as anywhereec_Total_Amount,

			/* Others */

			count(case when serviceid not in (1,12,13) then
			applicationnumber   else null end) as otherregistered,
			sum(case when serviceid not in (1,12,13)  and paymentmodeid = 2 then  -- by challan
			totalamount else 0 end )as  challan_other ,
			sum(case when serviceid not in (1,12,13) and paymentmodeid = 4 then  -- Epayment
