--
-- Name: fn_mis_rbi_report(integer, integer, timestamp without time zone, timestamp without time zone, text, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_rbi_report(_districtcode integer, _srocode integer, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _finalregdno text DEFAULT NULL::text, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(propertyid bigint, districtname character varying, sroname character varying, seller text, buyer text, property_desc character varying, natureofdeed character varying, modeofpayment text, citizenmarketvalue bigint, citizenconsideration numeric, actual_paid_amount numeric, difference_amount numeric, registrationdate text, finalregistrationnumber character varying, totalarea numeric, unitofmeasurement character varying, propertytype character varying, uploaddocdeedpath text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN 
PageOffset := (pagesize*pagenumber) - pagesize;

				
		    
			 
			 if (pagenumber<>-1 and pagesize<>-1) then
			 return query 
			 with cte as (select distinct
				p2.propertyid,
				d.districtnamee,
				sm.sronamee,

				string_agg(
				distinct case when 
				p3.partytypeid=2 then 
						p3.firstname||' '||coalesce(p3.middlename,' ')||' '||coalesce(p3.lastname,' ') 
				else 
					null
				end,',') as seller, 
				string_agg(distinct case when p3.partytypeid=1 
				then p3.firstname||' '||coalesce(p3.middlename,' ')||' '||coalesce(p3.lastname,' ') 
				else null 
				end,',') as buyer,
				ps.description,
				r.articlenamee  as natureofdeed,
				string_agg( distinct  'Payment By Challan No '
				||epd.chlnrefnum||' '||'dated  '||to_char(epd.lastupdateddate,'YYYY-MM-DD')
				||'  of Amount of Rs '||epd.totalamount,',') as modeofpayment,

				GREATEST(p2.marketvalue::bigint,p2.sromarketvalue) as marketvalue ,
				GREATEST(p2.sroconsideration,p2.consideration) as consideration,
				GREATEST(p2.marketvalue,p2.sromarketvalue,p2.sroconsideration,p2.consideration) as actual_paid,
				GREATEST(p2.marketvalue,p2.sromarketvalue,p2.sroconsideration,p2.consideration) -
				GREATEST(p2.marketvalue,p2.sromarketvalue) as difference_amount,
				to_char(d2.registrationdatetime,'YYYY-MM-DD') as registrationdate,
				d2.finalregistrationnumber,
				p2.totalarea,
				m.descriptionenglish ,
				 
				coalesce ((select  pt.propertytypename from kaveri.propertytypemaster pt 
				where pt.propertytypeid in 
				( select v.propertytypeid  from kaveri.valuationdetails  v where v.propertyid=p2.propertyid 
				order by v.inserteddatetime desc limit 1)),'Non-agriculture')::character varying as propertynametype ,
				d2.uploaddocdeedpath 


				from 
				kaveri.documentmaster d2
				join kaveri.propertymaster p2 on d2.applicationnumber=p2.applicationnumber 
				and  p2.propertytypeid<>17
				join kaveri.propertynumberdetails p on p.propertyid=p2.propertyid 
				join kaveri.partyinfo p3 on p3.applicationnumber=d2.applicationnumber 
				join kaveri.propertyschedules ps on ps.propertyid=p2.propertyid 
				join kaveri.propertytypemaster p4 on p2.propertytypeid=p4.propertytypeid 
				join kaveri.registrationarticles r on d2.regarticlecode=r.regarticlecode
				left join kaveri.ams_reg_epaymenttransdetails epd on 
				epd.applicationnumber=d2.applicationnumber  and epd.isdelete=false
				join kaveri.measunitmaster m on p2.unitid=m.unitid 
				join kaveri.sromaster sm on d2.srocode=sm.srocode
				join kaveri.districtmaster d on d.districtcode=sm.districtcode
				
				--join kaveri.ams_reg_epaymentbankackdetails epb on epb.deptreferencecode=epd.deptreferencecode 
			where  
			d2.isregistrationcompleted=true and 
			(d2.registrationdatetime between _fromdate and  _todate+ INTERVAL '1 day')
			and (

                    CASE

                       WHEN _districtcode <> 0 THEN  d.districtcode = _districtcode

                    ELSE TRUE

                    END

                )

               and (

                    CASE

                    WHEN _srocode <> 0 THEN  sm.srocode = _srocode

                    ELSE TRUE

                    end

                    )
				and 
				(

                    CASE

                    WHEN _finalregdno is not null THEN  d2.finalregistrationnumber = _finalregdno

                    ELSE TRUE

                    end

                    )
					
					group by d2.applicationnumber,ps.description,
					p2.propertyid,
					p2.marketvalue,
					p2.sromarketvalue,
					p2.sroconsideration,
					p2.consideration,
					d2.registrationdatetime,
					d2.finalregistrationnumber,
					propertynametype,
					r.articlenamee,
					d.districtnamee,
					sm.sronamee,
					p2.totalarea,
					m.descriptionenglish,
					d2.uploaddocdeedpath ),cte_count as (select count(*) as total_rows from cte)

            select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0 OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
				
			elsif (pagenumber=-1 or  pagesize=-1) then 
			
			return query
			with cte as (select distinct
				p2.propertyid,
				d.districtnamee,
				sm.sronamee,

				string_agg(
				distinct case when 
				p3.partytypeid=2 then 
						p3.firstname||' '||coalesce(p3.middlename,' ')||' '||coalesce(p3.lastname,' ') 
				else 
					null
				end,',') as seller, 
				string_agg(distinct case when p3.partytypeid=1 
				then p3.firstname||' '||coalesce(p3.middlename,' ')||' '||coalesce(p3.lastname,' ') 
				else null 
				end,',') as buyer,
				ps.description,
				r.articlenamee  as natureofdeed,
				string_agg( distinct  'Payment By Challan No '
				||epd.chlnrefnum||' '||'dated  '||to_char(epd.lastupdateddate,'YYYY-MM-DD')
				||'  of Amount of Rs '||epd.totalamount,',') as modeofpayment,

				GREATEST(p2.marketvalue::bigint,p2.sromarketvalue) as marketvalue ,
				GREATEST(p2.sroconsideration,p2.consideration) as consideration,
				GREATEST(p2.marketvalue,p2.sromarketvalue,p2.sroconsideration,p2.consideration) as actual_paid,
				GREATEST(p2.marketvalue,p2.sromarketvalue,p2.sroconsideration,p2.consideration) -
				GREATEST(p2.marketvalue,p2.sromarketvalue) as difference_amount,
				to_char(d2.registrationdatetime,'YYYY-MM-DD') as registrationdate,
				d2.finalregistrationnumber,
				p2.totalarea,
				m.descriptionenglish ,
				coalesce ((select  pt.propertytypename from kaveri.propertytypemaster pt 
				where pt.propertytypeid in 
				( select v.propertytypeid  from kaveri.valuationdetails  v where v.propertyid=p2.propertyid 
				order by v.inserteddatetime desc limit 1)),'Non-agriculture')::character varying as propertynametype ,
				d2.uploaddocdeedpath 


				from 
				kaveri.documentmaster d2
				join kaveri.propertymaster p2 on d2.applicationnumber=p2.applicationnumber
				and  p2.propertytypeid<>17
				join kaveri.propertynumberdetails p on p.propertyid=p2.propertyid 
				join kaveri.partyinfo p3 on p3.applicationnumber=d2.applicationnumber 
				join kaveri.propertyschedules ps on ps.propertyid=p2.propertyid 
				join kaveri.propertytypemaster p4 on p2.propertytypeid=p4.propertytypeid 
				join kaveri.registrationarticles r on d2.regarticlecode=r.regarticlecode
				left join kaveri.ams_reg_epaymenttransdetails epd on 
				epd.applicationnumber=d2.applicationnumber  and epd.isdelete=false
				join kaveri.measunitmaster m on p2.unitid=m.unitid 
				join kaveri.sromaster sm on d2.srocode=sm.srocode
				join kaveri.districtmaster d on d.districtcode=sm.districtcode
				
				--join kaveri.ams_reg_epaymentbankackdetails epb on epb.deptreferencecode=epd.deptreferencecode 
			where  
			d2.isregistrationcompleted=true and 
			(d2.registrationdatetime between _fromdate and  _todate+ INTERVAL '1 day')
			and (

                    CASE

                       WHEN _districtcode <> 0 THEN  d.districtcode = _districtcode

                    ELSE TRUE

                    END

                )

               and (

                    CASE

                    WHEN _srocode <> 0 THEN  sm.srocode = _srocode

                    ELSE TRUE

                    end

                    )
				and 
				(

                    CASE

                    WHEN _finalregdno is not null THEN  d2.finalregistrationnumber = _finalregdno

                    ELSE TRUE

                    end

                    )
					
					group by d2.applicationnumber,ps.description,
					p2.propertyid,
					p2.marketvalue,
					p2.sromarketvalue,
					p2.sroconsideration,
					p2.consideration,
					d2.registrationdatetime,
					d2.finalregistrationnumber,
					propertynametype,
					r.articlenamee,
					d.districtnamee,
					sm.sronamee,
					p2.totalarea,
					m.descriptionenglish,
					d2.uploaddocdeedpath   )

            select cte.*,null::bigint as totalcount from cte;
			
			
			
			end if;

                                       

                                        
			 			
			
		
	
		
				
				
				
						 

					 

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_rbi_report(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _finalregdno text, pagenumber integer, pagesize integer) OWNER TO postgres;

