				else null 
				end,',') as buyer,
				ps.description,
				r.articlenamee  as natureofdeed,
				string_agg(distinct 'Payment By Challan No '||epd.chlnrefnum||' '||'dated '||lastupdateddate
				||'of Amount of Rs'||epd.totalamount,
				',') as modeofpayment,

				GREATEST(p2.marketvalue::bigint,p2.sromarketvalue) as marketvalue ,
				GREATEST(p2.sroconsideration,p2.consideration) as consideration,
				GREATEST(p2.marketvalue,p2.sromarketvalue,p2.sroconsideration,p2.consideration) as actual_paid,
				GREATEST(p2.marketvalue,p2.sromarketvalue,p2.sroconsideration,p2.consideration) -
				GREATEST(p2.marketvalue,p2.sromarketvalue) as difference_amount,
				to_char(d2.registrationdatetime,'YYYY-MM-DD') as registrationdate,
				d2.finalregistrationnumber,
				p2.totalarea,
				m.descriptionenglish,
				p4.propertytypename,
				d2.uploaddocdeedpath 


				from 
				kaveri.documentmaster d2
				join kaveri.propertymaster p2 on d2.applicationnumber=p2.applicationnumber  
				join kaveri.propertynumberdetails p on p.propertyid=p2.propertyid 
				join kaveri.partyinfo p3 on p3.applicationnumber=d2.applicationnumber 
				join kaveri.propertyschedules ps on ps.propertyid=p2.propertyid 
				join kaveri.propertytypemaster p4 on p2.propertytypeid=p4.propertytypeid 
				join kaveri.registrationarticles r on d2.regarticlecode=r.regarticlecode
				left join kaveri.ams_reg_epaymenttransdetails epd on epd.applicationnumber=d2.applicationnumber 
				join kaveri.measunitmaster m on p2.unitid=m.unitid 
				join kaveri.sromaster sm on d2.srocode=sm.srocode
				join kaveri.districtmaster d on d.districtcode=sm.districtcode
				--join kaveri.ams_reg_epaymentbankackdetails epb on epb.deptreferencecode=epd.deptreferencecode 
			where  
			d2.isregistrationcompleted=true and 
			d2.registrationdatetime::date>=_fromdate and
			d2.registrationdatetime::date<=_todate
			and (

                    CASE

                       WHEN _districtcode <> 0 THEN  d.districtcode = _districtcode

                    ELSE TRUE

                    END

                )

               and (

                    CASE

                    WHEN _srocode <> 0 THEN  sm.srocode = _srocode

                    ELSE TRUE

                    end

                    )
				and 
				(

                    CASE

                    WHEN _finalregdno is not null THEN  d2.finalregistrationnumber = _finalregdno

                    ELSE TRUE

                    end

                    )
					
					group by d2.applicationnumber,ps.description,
					p2.propertyid,
					p2.marketvalue,
					p2.sromarketvalue,
					p2.sroconsideration,
					p2.consideration,
					d2.registrationdatetime,
					d2.finalregistrationnumber,
					p4.propertytypename,
					r.articlenamee,
					d.districtnamee,
					sm.sronamee,
					p2.totalarea,
					m.descriptionenglish,
					d2.uploaddocdeedpath  )

            select cte.*,null::bigint as totalcount from cte	;
			
			
			
			end if;

                                       

                                        
			 			
			
		
	
		
				
				
				
						 

					 

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_rbi_report_01122023(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _finalregdno text, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_rbi_report_23012024(integer, integer, timestamp without time zone, timestamp without time zone, text, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_rbi_report_23012024(_districtcode integer, _srocode integer, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _finalregdno text DEFAULT NULL::text, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(propertyid bigint, districtname character varying, sroname character varying, seller text, buyer text, property_desc character varying, natureofdeed character varying, modeofpayment text, citizenmarketvalue bigint, citizenconsideration numeric, actual_paid_amount numeric, difference_amount numeric, registrationdate text, finalregistrationnumber character varying, totalarea numeric, unitofmeasurement character varying, propertytype character varying, uploaddocdeedpath text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN 
PageOffset := (pagesize*pagenumber) - pagesize;

				
		    
			 
			 if (pagenumber<>-1 and pagesize<>-1) then
			 return query 
			 with cte as (select distinct
				p2.propertyid,
				d.districtnamee,
				sm.sronamee,

				string_agg(
				distinct case when 
				p3.partytypeid=2 then 
						p3.firstname||' '||coalesce(p3.middlename,' ')||' '||coalesce(p3.lastname,' ') 
				else 
					null
				end,',') as seller, 
				string_agg(distinct case when p3.partytypeid=1 
				then p3.firstname||' '||coalesce(p3.middlename,' ')||' '||coalesce(p3.lastname,' ') 
				else null 
				end,',') as buyer,
				ps.description,
				r.articlenamee  as natureofdeed,
				string_agg( distinct  'Payment By Challan No '
				||epd.chlnrefnum||' '||'dated  '||to_char(epd.lastupdateddate,'YYYY-MM-DD')
				||'  of Amount of Rs '||epd.totalamount,',') as modeofpayment,

				GREATEST(p2.marketvalue::bigint,p2.sromarketvalue) as marketvalue ,
				GREATEST(p2.sroconsideration,p2.consideration) as consideration,
				GREATEST(p2.marketvalue,p2.sromarketvalue,p2.sroconsideration,p2.consideration) as actual_paid,
				GREATEST(p2.marketvalue,p2.sromarketvalue,p2.sroconsideration,p2.consideration) -
				GREATEST(p2.marketvalue,p2.sromarketvalue) as difference_amount,
				to_char(d2.registrationdatetime,'YYYY-MM-DD') as registrationdate,
				d2.finalregistrationnumber,
				p2.totalarea,
				m.descriptionenglish ,
				 
				coalesce ((select  pt.propertytypename from kaveri.propertytypemaster pt 
				where pt.propertytypeid in 
				( select v.propertytypeid  from kaveri.valuationdetails  v where v.propertyid=p2.propertyid 
				order by v.inserteddatetime desc limit 1)),'Non-agriculture')::character varying as propertynametype ,
				d2.uploaddocdeedpath 


				from 
				kaveri.documentmaster d2
				join kaveri.propertymaster p2 on d2.applicationnumber=p2.applicationnumber 
				and  p2.propertytypeid<>17
				join kaveri.propertynumberdetails p on p.propertyid=p2.propertyid 
				join kaveri.partyinfo p3 on p3.applicationnumber=d2.applicationnumber 
				join kaveri.propertyschedules ps on ps.propertyid=p2.propertyid 
				join kaveri.propertytypemaster p4 on p2.propertytypeid=p4.propertytypeid 
				join kaveri.registrationarticles r on d2.regarticlecode=r.regarticlecode
				left join kaveri.ams_reg_epaymenttransdetails epd on 
				epd.applicationnumber=d2.applicationnumber  and epd.isdelete=false
				join kaveri.measunitmaster m on p2.unitid=m.unitid 
				join kaveri.sromaster sm on d2.srocode=sm.srocode
				join kaveri.districtmaster d on d.districtcode=sm.districtcode
				
				--join kaveri.ams_reg_epaymentbankackdetails epb on epb.deptreferencecode=epd.deptreferencecode 
			where  
			d2.isregistrationcompleted=true and 
			(d2.registrationdatetime between _fromdate and  _todate+ INTERVAL '1 day')
			and (

                    CASE

                       WHEN _districtcode <> 0 THEN  d.districtcode = _districtcode

                    ELSE TRUE

                    END

                )

               and (

                    CASE

                    WHEN _srocode <> 0 THEN  sm.srocode = _srocode

                    ELSE TRUE

                    end

                    )
				and 
				(

                    CASE

                    WHEN _finalregdno is not null THEN  d2.finalregistrationnumber = _finalregdno

                    ELSE TRUE

                    end

                    )
					
					group by d2.applicationnumber,ps.description,
					p2.propertyid,
					p2.marketvalue,
					p2.sromarketvalue,
					p2.sroconsideration,
					p2.consideration,
					d2.registrationdatetime,
					d2.finalregistrationnumber,
					propertynametype,
					r.articlenamee,
					d.districtnamee,
					sm.sronamee,
					p2.totalarea,
					m.descriptionenglish,
					d2.uploaddocdeedpath ),cte_count as (select count(*) as total_rows from cte)

            select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0 OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
				
			elsif (pagenumber=-1 or  pagesize=-1) then 
			
			return query
			with cte as (select distinct
				p2.propertyid,
				d.districtnamee,
				sm.sronamee,

				string_agg(
				distinct case when 
				p3.partytypeid=2 then 
						p3.firstname||' '||coalesce(p3.middlename,' ')||' '||coalesce(p3.lastname,' ') 
				else 
					null
				end,',') as seller, 
				string_agg(distinct case when p3.partytypeid=1 
				then p3.firstname||' '||coalesce(p3.middlename,' ')||' '||coalesce(p3.lastname,' ') 
				else null 
				end,',') as buyer,
				ps.description,
				r.articlenamee  as natureofdeed,
				string_agg( distinct  'Payment By Challan No '
				||epd.chlnrefnum||' '||'dated  '||to_char(epd.lastupdateddate,'YYYY-MM-DD')
				||'  of Amount of Rs '||epd.totalamount,',') as modeofpayment,

				GREATEST(p2.marketvalue::bigint,p2.sromarketvalue) as marketvalue ,
				GREATEST(p2.sroconsideration,p2.consideration) as consideration,
				GREATEST(p2.marketvalue,p2.sromarketvalue,p2.sroconsideration,p2.consideration) as actual_paid,
				GREATEST(p2.marketvalue,p2.sromarketvalue,p2.sroconsideration,p2.consideration) -
				GREATEST(p2.marketvalue,p2.sromarketvalue) as difference_amount,
				to_char(d2.registrationdatetime,'YYYY-MM-DD') as registrationdate,
				d2.finalregistrationnumber,
				p2.totalarea,
				m.descriptionenglish ,
				coalesce ((select  pt.propertytypename from kaveri.propertytypemaster pt 
				where pt.propertytypeid in 
				( select v.propertytypeid  from kaveri.valuationdetails  v where v.propertyid=p2.propertyid 
				order by v.inserteddatetime desc limit 1)),'Non-agriculture')::character varying as propertynametype ,
				d2.uploaddocdeedpath 


				from 
				kaveri.documentmaster d2
				join kaveri.propertymaster p2 on d2.applicationnumber=p2.applicationnumber
				and  p2.propertytypeid<>17
				join kaveri.propertynumberdetails p on p.propertyid=p2.propertyid 
				join kaveri.partyinfo p3 on p3.applicationnumber=d2.applicationnumber 
				join kaveri.propertyschedules ps on ps.propertyid=p2.propertyid 
				join kaveri.propertytypemaster p4 on p2.propertytypeid=p4.propertytypeid 
				join kaveri.registrationarticles r on d2.regarticlecode=r.regarticlecode
				left join kaveri.ams_reg_epaymenttransdetails epd on 
				epd.applicationnumber=d2.applicationnumber  and epd.isdelete=false
				join kaveri.measunitmaster m on p2.unitid=m.unitid 
				join kaveri.sromaster sm on d2.srocode=sm.srocode
				join kaveri.districtmaster d on d.districtcode=sm.districtcode
				
				--join kaveri.ams_reg_epaymentbankackdetails epb on epb.deptreferencecode=epd.deptreferencecode 
			where  
			d2.isregistrationcompleted=true and 
			(d2.registrationdatetime between _fromdate and  _todate+ INTERVAL '1 day')
			and (

                    CASE

                       WHEN _districtcode <> 0 THEN  d.districtcode = _districtcode

                    ELSE TRUE

                    END

                )

               and (

                    CASE

                    WHEN _srocode <> 0 THEN  sm.srocode = _srocode

                    ELSE TRUE

                    end

                    )
				and 
				(

                    CASE

                    WHEN _finalregdno is not null THEN  d2.finalregistrationnumber = _finalregdno

                    ELSE TRUE

                    end

                    )
					
					group by d2.applicationnumber,ps.description,
					p2.propertyid,
					p2.marketvalue,
					p2.sromarketvalue,
					p2.sroconsideration,
					p2.consideration,
					d2.registrationdatetime,
					d2.finalregistrationnumber,
					propertynametype,
					r.articlenamee,
					d.districtnamee,
					sm.sronamee,
					p2.totalarea,
					m.descriptionenglish,
					d2.uploaddocdeedpath   )

            select cte.*,null::bigint as totalcount from cte;
			
			
			
			end if;

                                       

                                        
			 			
			
		
	
		
				
				
				
						 

					 

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_rbi_report_23012024(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _finalregdno text, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_reconciliation_report(integer, date, date, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_reconciliation_report(_srocode integer, _fromdate date, _todate date, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, officename character varying, date timestamp without time zone, documentno integer, stampduty numeric, registrationfee numeric, cess numeric, scanningfee numeric, miscfee numeric, marriage numeric, rti integer, rr integer, total numeric, remitteddate timestamp without time zone, scrolldate date, k2challanreferenceno character varying, remarks text, stampduty_k2challan numeric, registrationfee_k2challan numeric, cess_k2challan numeric, scanningfee_k2challan numeric, miscfee_k2challan numeric, marriage_k2challan numeric, rti_k2challan integer, rr_k2challan integer, total_k2challan numeric, k2challandate date, k2scrolldate date, k2_challanreferenceno character varying, treasurychallanno character varying, k2_remarks text, grandtotal numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize); 	
return query 
select c.districtnamee,b.sronamee,
a.registrationdatetime as date,a.documentnumber as documentno,
case when d.feerulecode = 1 then
sum(d.amountpaid) else 0 end as stampduty,
case when d.feerulecode = 36 then
sum(d.amountpaid) else 0 end as registrationfee,
case when d.feerulecode = 59 then
sum(d.amountpaid) else 0 end as cess,
case when d.feerulecode = 2 then
sum(d.amountpaid) else 0 end as scanningfee,
case when d.feerulecode = 8 then
sum(d.amountpaid) else 0 end as Miscfee,
case when d.feerulecode = 10 then
sum(d.amountpaid) else 0 end as Marriage,
0 as RTI,
0 as RR,
(case when d.feerulecode = 1 then
sum(d.amountpaid) else 0 end + case when d.feerulecode = 36 then
sum(d.amountpaid) else 0 end + case when d.feerulecode = 59 then
sum(d.amountpaid) else 0 end + case when d.feerulecode = 2 then
sum(d.amountpaid) else 0 end + case when d.feerulecode = 8 then
sum(d.amountpaid) else 0 end + case when d.feerulecode = 10 then
sum(d.amountpaid) else 0 end +0+0) as Total,
e.remiteddate,
current_date as scrolldate,
f.chlnrefnum as k2challanreferenceno,
g.remarks,
case when f.feerulecode = 1 then
sum(d.amountpaid) else 0 end as stampduty_k2challan,
case when f.feerulecode = 36 then
sum(d.amountpaid) else 0 end as registrationfee_k2challan,
case when f.feerulecode = 59 then
sum(d.amountpaid) else 0 end as cess_k2challan,
case when d.feerulecode = 2 then
sum(d.amountpaid) else 0 end as scanningfee_k2challan,
case when f.feerulecode = 8 then
sum(d.amountpaid) else 0 end as Miscfee_k2challan,
case when f.feerulecode = 10 then
sum(d.amountpaid) else 0 end as Marriage_k2challan,
0 as RTI_k2challan,
0 as RR_k2challan,
(case when f.feerulecode = 1 then
sum(d.amountpaid) else 0 end + case when f.feerulecode = 36 then
sum(d.amountpaid) else 0 end + case when f.feerulecode = 59 then
sum(d.amountpaid) else 0 end + case when f.feerulecode = 2 then
sum(d.amountpaid) else 0 end + case when f.feerulecode = 8 then
sum(d.amountpaid) else 0 end + case when f.feerulecode = 10 then
sum(d.amountpaid) else 0 end +0+0) as Total_k2challan,
current_date as K2challandate,
current_date as k2scrolldate,
f.chlnrefnum as k2_challanreferenceno,
f.treasurycode as Treasurychallanno,
g.remarks as k2_remarks,
((case when d.feerulecode = 1 then
sum(d.amountpaid) else 0 end + case when d.feerulecode = 36 then
sum(d.amountpaid) else 0 end + case when d.feerulecode = 59 then
sum(d.amountpaid) else 0 end + case when d.feerulecode = 2 then
sum(d.amountpaid) else 0 end + case when d.feerulecode = 8 then
sum(d.amountpaid) else 0 end + case when d.feerulecode = 10 then
sum(d.amountpaid) else 0 end +0+0) +
(case when f.feerulecode = 1 then
sum(d.amountpaid) else 0 end + case when f.feerulecode = 36 then
sum(d.amountpaid) else 0 end + case when f.feerulecode = 59 then
sum(d.amountpaid) else 0 end + case when f.feerulecode = 2 then
sum(d.amountpaid) else 0 end + case when f.feerulecode = 8 then
sum(d.amountpaid) else 0 end + case when f.feerulecode = 10 then
sum(d.amountpaid) else 0 end +0+0)) as Grandtotal
from kaveri.documentmaster a left join kaveri.sromaster b on a.srocode = b.srocode
left join kaveri.districtmaster c on b.districtcode = c.districtcode
left join kaveri.feesrequired d on a.documentid = d.documentid
left join kaveri.referencemaster e on d.documentid = e.documentid
left join kaveri.ams_reg_epaymenttransdetails f on a.documentid = f.documentid
left join kaveri.applicantapplicationdetails g on a.applicationnumber = g.applicationnumber
where a.srocode = 173 and a.registrationdatetime >= '2022-10-10' and
a.registrationdatetime <= current_date
group by b.districtcode,c.districtnamee,a.srocode,b.sronamee,
a.registrationdatetime,a.documentnumber,d.feerulecode,e.remiteddate,f.chlnrefnum,g.remarks,
f.feerulecode,f.treasurycode
having (case when d.feerulecode = 1 then
sum(d.amountpaid) else 0 end + case when d.feerulecode = 36 then
sum(d.amountpaid) else 0 end + case when d.feerulecode = 59 then
sum(d.amountpaid) else 0 end + case when d.feerulecode = 2 then
sum(d.amountpaid) else 0 end + case when d.feerulecode = 8 then
sum(d.amountpaid) else 0 end + case when d.feerulecode = 10 then
sum(d.amountpaid) else 0 end +0+0) > 0 and e.remiteddate is not null;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_reconciliation_report(_srocode integer, _fromdate date, _todate date, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_refund_report(integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_refund_report(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, officename text, servicetype character varying, certificatenumber character varying, challannumber character varying, challandate timestamp without time zone, challanamount numeric, refundrequestamount integer, dateofrefundrequest integer, refundableamount integer, trackrefundstatus integer, refundtoacc integer, annexures text, remarks text)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN	
return query
select distinct districtnamee as districtname,
a.officename,
d.servicename as servicetype,
e.certificatenumber,
f.deptreferencecode as challannumber,
f.lastupdateddate as challandate,
sum(f.totalamount) as challanamount,
0 as refundrequestamount,
0 as dateofrefundrequest,
0 as refundableamount,
0 as trackrefundstatus,
0 as refundtoacc,
null as annexures,
null as remarks
from kaveri.mas_officemaster a left join kaveri.districtmaster b on cast(a.parentofficeid as integer) = b.districtcode 
left join kaveri.referencemaster c on a.kavericode = c.srocode
left join kaveri.servicesmaster d on c.documenttypeid = d.serviceid
left join kaveri.ec_applicationdetails e on kaverisrocode = c.srocode
left join kaveri.ams_reg_epaymenttransdetails f on e.kaverisrocode = f.officeid
left join kaveri.documentmaster g on c.documentid = g.documentid
where f.officeid = _srocode and
f.lastupdateddate >= _from_date  and f.lastupdateddate <= _to_date
group by
districtnamee,
a.officename,
d.servicename,
e.certificatenumber,
f.deptreferencecode,
f.lastupdateddate;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_refund_report(_srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_refusalregister(bigint, timestamp without time zone, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_refusalregister(_srocode bigint, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _documentnumber character varying DEFAULT NULL::character varying) RETURNS TABLE(district character varying, sro character varying, applicationnumber2 character varying, pendingdocumentnumber character varying, copy_of_document text, slno_year text, stampduty numeric, dateofexecution timestamp without time zone, dateofpresent timestamp without time zone, presentername text, executantname text, name_addition_person_examined text, srorefusedate text, abstract_of_documents text, updated_abstract_of_documents text, refusalremarks text, updated_refusal_remarks text, summonsorder text, updated_summonsorder text)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$

DECLARE
BEGIN	

if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
raise notice 'Documentnumber null';

return query

	select distinct d2.districtnamee as district,  
	 s.sronamee as sro, 
	 a2.applicationnumber as applicationnumber,  
	 d.pendingdocumentnumber as pendingdocumentnumber, 
	 d.uploaddocdeedpath as copy_of_document, 
	  concat_ws('  ,  ',substring(d.pendingdocumentnumber,3,5), 
	 substring(d.pendingdocumentnumber,13,7)) as slno_year, 
	f2.amountpaid  as stampduty, 
	 d.executiondatetime as dateofexecution, 
	 d.presentdatetime as dateofpresent, 
	 string_agg(distinct case when vfp.ispresenter is true then vfp.name end,' ') as presentername, 
	 string_agg(distinct case when vfp.partytypeid = 2 then vfp.name end,' ') as executantname, 
	 string_agg(distinct case when vfp.partytypeid = 2  and vfp.thumbpath is not null then coalesce(vfp.name,' ')||','|| 
	 coalesce(vfp.relationship,' ')||' '||coalesce(vfp.relativename,' ')||','||coalesce(vfp.address,' ')||','||coalesce(vfp.profession,' ')end, ' ') as name_addition_person_examined, 
	 coalesce(s.sronamee,' ') || ' ' || to_char(a2.inserteddatetime , 'DD-MM-YYYY') as srorefusedate, 
	string_agg( distinct case when vfp.partytypeid=1   then coalesce( vfp.name,' ')  end,',')||' , ' ||
	string_agg( distinct case when vfp.partytypeid=1   then coalesce( w.name,'  ')   end,',')
	as  abstract_of_documents, 
    null as updated_abstract_of_documents, 
	a2.remarks   as refusalremarks, 
	null as updated_refusal_remarks, 
	null as summonorder, 
	null as updated_summonsorder 
	from kaveri.applicantapplicationdetails a2  
	join kaveri.documentmaster d on d.applicationnumber = a2.applicationnumber  
	join kaveri.vw_fetch_party vfp on vfp.applicationnumber = a2.applicationnumber  
	left join (select distinct applicationnumber,sum(amountpaid) as amountpaid from kaveri.feesrequired 
	where feerulecode in (36,58,59)  group by applicationnumber )f2 on f2.applicationnumber = a2.applicationnumber  
	join kaveri.sromaster s on s.srocode = d.srocode  
	join kaveri.districtmaster d2 on s.districtcode = d2.districtcode  
    left join kaveri.witnessinfo w on w.applicationnumber = d.applicationnumber 
	where 
	s.srocode =_srocode and	a2.currentstatus = 'CD134'   
	and  a2.applicationstartdate::date >= _fromdate  and  a2.applicationstartdate::date <=_todate
	group by d2.districtnamee, s.sronamee, a2.applicationnumber,d.pendingdocumentnumber, d.presentdatetime,	 a2.applicationstartdate, a2.remarks,d.executiondatetime,a2.inserteddatetime,
	d.applicationnumber,d.uploaddocdeedpath,f2.amountpaid;

	

	
	 elseif 	_documentnumber is not NULL and (_fromdate  is NULL and _todate is NULL) then
	 
	return query
	select distinct d2.districtnamee as district,  
	 s.sronamee as sro, 
	 a2.applicationnumber as applicationnumber,  
	 d.pendingdocumentnumber as pendingdocumentnumber, 
	 d.uploaddocdeedpath as copy_of_document, 
	  concat_ws('  ,  ',substring(d.pendingdocumentnumber,3,5), 
	 substring(d.pendingdocumentnumber,13,7)) as slno_year, 
	f2.amountpaid  as stampduty, 
	 d.executiondatetime as dateofexecution, 
	 d.presentdatetime as dateofpresent, 
	 string_agg(distinct case when vfp.ispresenter is true then vfp.name end,' ') as presentername, 
	 string_agg(distinct case when vfp.partytypeid = 2 then vfp.name end,' ') as executantname, 
	 string_agg(distinct case when vfp.partytypeid = 2  and vfp.thumbpath is not null then coalesce(vfp.name,' ')||','|| 
	 coalesce(vfp.relationship,' ')||' '||coalesce(vfp.relativename,' ')||','||coalesce(vfp.address,' ')||','||coalesce(vfp.profession,' ')end, ' ') as name_addition_person_examined, 
	 coalesce(s.sronamee,' ') || ' ' || to_char(a2.inserteddatetime , 'DD-MM-YYYY') as srorefusedate, 
	string_agg( distinct case when vfp.partytypeid=1   then coalesce( vfp.name,' ')  end,',')||' , ' ||
	string_agg( distinct case when vfp.partytypeid=1   then coalesce( w.name,'  ')   end,',')
	as  abstract_of_documents, 
    null as updated_abstract_of_documents, 
	a2.remarks   as refusalremarks, 
	null as updated_refusal_remarks, 
	null as summonorder, 
	null as updated_summonsorder 
	from kaveri.applicantapplicationdetails a2  
	join kaveri.documentmaster d on d.applicationnumber = a2.applicationnumber  
	 and d.finalregistrationnumber=_documentnumber or d.pendingdocumentnumber=_documentnumber
	join kaveri.vw_fetch_party vfp on vfp.applicationnumber = a2.applicationnumber  
	left join (select distinct applicationnumber,sum(amountpaid) as amountpaid from kaveri.feesrequired 
	where feerulecode in (36,58,59)  group by applicationnumber )f2 on f2.applicationnumber = a2.applicationnumber  
	join kaveri.sromaster s on s.srocode = d.srocode  
	join kaveri.districtmaster d2 on s.districtcode = d2.districtcode  
    left  join kaveri.witnessinfo w on w.applicationnumber = d.applicationnumber 
	where 
	s.srocode =_srocode and	a2.currentstatus = 'CD134'   
		 
	group by d2.districtnamee, s.sronamee, a2.applicationnumber,d.pendingdocumentnumber, d.presentdatetime,	 a2.applicationstartdate, a2.remarks,d.executiondatetime,a2.inserteddatetime,
	d.applicationnumber,d.uploaddocdeedpath,f2.amountpaid;

  
else

raise notice 'condition failed';
end if;
		  
     END;

$$;


