			d.finalregistrationnumber=_documentnumber and 
			a2.currentstatus = 'CD134'   
			
			group by d2.districtnamee, s.sronamee, a2.applicationnumber,
			d.pendingdocumentnumber, d.presentdatetime,	 a2.applicationstartdate,
			a2.remarks,d.executiondatetime,a2.inserteddatetime,
			d.applicationnumber,d.uploaddocdeedpath,f2.amountpaid)
			,cte_count as (select count(*) as total_rows from cte)
			select * from cte
			join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

		  
			else

				raise notice 'condition failed';
				end if;
	
	end if;
		  
     END;

$$;


ALTER FUNCTION kaverimis.fn_mis_refusalregister(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_refusalregister_backup_01_04_2023(bigint, timestamp without time zone, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_refusalregister_backup_01_04_2023(_srocode bigint, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _documentnumber character varying DEFAULT NULL::character varying) RETURNS TABLE(district character varying, sro character varying, applicationnumber character varying, pendingdocumentnumber character varying, copy_of_document text, slno_year text, stampduty numeric, dateofexecution timestamp without time zone, dateofpresent timestamp without time zone, presentername text, executantname text, name_addition_person_examined text, srorefusedate text, abstract_of_documents text, updated_abstract_of_documents character varying, refusalremarks text, updated_refusal_remarks character varying, summonsorder text, updated_summonsorder character varying)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$



DECLARE
BEGIN	

if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
raise notice 'Documentnumber null';

return query

	select distinct d2.districtnamee as district, 
	 s.sronamee as sro,
	 a2.applicationnumber as applicationnumber, 
	 d.pendingdocumentnumber as pendingdocumentnumber,
	 d.uploaddocdeedpath as copy_of_document,
	 concat_ws('  ,  ',substring(d.pendingdocumentnumber,3,5),
	 substring(d.pendingdocumentnumber,13,7)) as slno_year,
	 sum(distinct case when f2.feerulecode = 36 then f2.amountpaid else 0 end) as stampduty,
	 d.executiondatetime as dateofexecution,
	 d.presentdatetime as dateofpresent,
	 string_agg(distinct case when vfp.ispresenter is true then vfp.name end,' ') as presentername,
	 string_agg(distinct case when vfp.partytypeid = 2 then vfp.name end,' ') as executantname,
	 string_agg(distinct case when vfp.partytypeid = 2  and vfp.thumbpath is not null then coalesce(vfp.name,' ')||','||
	 coalesce(vfp.relationship,' ')||' '||coalesce(vfp.relativename,' ')||','||coalesce(vfp.address,' ')||','||coalesce(vfp.profession,' ')end, ' ') as name_addition_person_examined,
	 coalesce(s.sronamee,' ') || ' ' || to_char(a2.inserteddatetime , 'DD-MM-YYYY') as srorefusedate,
	 string_agg(distinct case when vfp.partytypeid=1   then coalesce(vfp.name,' ')||','||coalesce(w.name,'  ') end,',')
	 as  abstract_of_documents,
	for2.refusalscribe as updated_abstract_of_documents,
	a2.remarks   as refusalremarks,
	for2.refusalreasons as updated_refusal_remarks,
	null as summonorder,
	for2.dailyregrefusalsummons::character varying as updated_summonsorder
	from kaveri.applicantapplicationdetails a2 
	join kaveri.documentmaster d on d.applicationnumber = a2.applicationnumber 
	join kaveri.vw_fetch_party vfp on vfp.applicationnumber = a2.applicationnumber 
	join kaveri.feesrequired f2 on f2.applicationnumber = a2.applicationnumber 
	join kaveri.sromaster s on s.srocode = d.srocode 
	join kaveri.districtmaster d2 on s.districtcode = d2.districtcode 
    left join kaveri.witnessinfo w on w.applicationnumber = d.applicationnumber
	left join kaverimis.formno2 for2 on for2.applicationnumber = a2.applicationnumber 
	where
	s.srocode =_srocode and	a2.currentstatus = 'CD134'  and f2.feerulecode=36 
	and d.presentdatetime::date >= _fromdate  and d.presentdatetime::date <=_todate
	group by d2.districtnamee, s.sronamee, a2.applicationnumber,d.pendingdocumentnumber, d.presentdatetime,
	d.registrationdatetime, a2.remarks,d.executiondatetime,a2.inserteddatetime,
	w.name,
	d.applicationnumber,for2.refusalscribe,for2.refusalreasons,
	for2.dailyregrefusalsummons,d.uploaddocdeedpath,f2.amountpaid,
	f2.feerulecode order by a2.applicationnumber ;


	
	 elseif 	_documentnumber is not NULL and (_fromdate  is NULL and _todate is NULL) then
	 
	return query
	
	select distinct d2.districtnamee as district, 
	 s.sronamee as sro,
	 a2.applicationnumber as applicationnumber, 
	 d.pendingdocumentnumber as pendingdocumentnumber,
	 d.uploaddocdeedpath as copy_of_document,
	 concat_ws('  ,  ',substring(d.pendingdocumentnumber,3,5),
	 substring(d.pendingdocumentnumber,13,7)) as slno_year,
	 sum(distinct case when f2.feerulecode = 36 then f2.amountpaid else 0 end) as stampduty,
	 d.executiondatetime as dateofexecution,
	 d.presentdatetime as dateofpresent,
	 string_agg(distinct case when vfp.ispresenter is true then vfp.name end,' ') as presentername,
	 string_agg(distinct case when vfp.partytypeid = 2 then vfp.name end,' ') as executantname,
	 string_agg(distinct case when vfp.partytypeid = 2  and vfp.thumbpath is not null then coalesce(vfp.name,' ')||','||
	 coalesce(vfp.relationship,' ')||' '||coalesce(vfp.relativename,' ')||','||coalesce(vfp.address,' ')||','||coalesce(vfp.profession,' ')end, ' ') as name_addition_person_examined,
	 coalesce(s.sronamee,' ') || ' ' || to_char(a2.inserteddatetime , 'DD-MM-YYYY') as srorefusedate,
	 string_agg(distinct case when vfp.partytypeid=1   then coalesce(vfp.name,' ')||','||coalesce(w.name,'  ') end,',')
	 as  abstract_of_documents,
	for2.refusalscribe as updated_abstract_of_documents,
	a2.remarks   as refusalremarks,
	for2.refusalreasons as updated_refusal_remarks,
	null as summonorder,
	for2.dailyregrefusalsummons::character varying as updated_summonsorder
	from kaveri.applicantapplicationdetails a2 
	join kaveri.documentmaster d on d.applicationnumber = a2.applicationnumber 
	join kaveri.vw_fetch_party vfp on vfp.applicationnumber = a2.applicationnumber 
	join kaveri.feesrequired f2 on f2.applicationnumber = a2.applicationnumber 
	join kaveri.sromaster s on s.srocode = d.srocode 
	join kaveri.districtmaster d2 on s.districtcode = d2.districtcode 
    left join kaveri.witnessinfo w on w.applicationnumber = d.applicationnumber
	left join kaverimis.formno2 for2 on for2.applicationnumber = a2.applicationnumber 
	where
	s.srocode =_srocode and	a2.currentstatus = 'CD134'  and f2.feerulecode=36 
	and d.finalregistrationnumber=_documentnumber or d.pendingdocumentnumber=_documentnumber
	
	group by d2.districtnamee, s.sronamee, a2.applicationnumber,d.pendingdocumentnumber, d.presentdatetime,
	d.registrationdatetime, a2.remarks,d.executiondatetime,a2.inserteddatetime,
	w.name,
	d.applicationnumber,for2.refusalscribe,for2.refusalreasons,
	for2.dailyregrefusalsummons,d.uploaddocdeedpath,f2.amountpaid,
	f2.feerulecode order by a2.applicationnumber ;

	
	
	 elseif _documentnumber is not NULL and (_fromdate is not NULL and _todate is not NULL) then

raise notice 'nothing null';
return query

select distinct d2.districtnamee as district, 
	 s.sronamee as sro,
	 a2.applicationnumber as applicationnumber, 
	 d.pendingdocumentnumber as pendingdocumentnumber,
	 d.uploaddocdeedpath as copy_of_document,
	 concat_ws('  ,  ',substring(d.pendingdocumentnumber,3,5),
	 substring(d.pendingdocumentnumber,13,7)) as slno_year,
	 sum(distinct case when f2.feerulecode = 36 then f2.amountpaid else 0 end) as stampduty,
	 d.executiondatetime as dateofexecution,
	 d.presentdatetime as dateofpresent,
	 string_agg(distinct case when vfp.ispresenter is true then vfp.name end,' ') as presentername,
	 string_agg(distinct case when vfp.partytypeid = 2 then vfp.name end,' ') as executantname,
	 string_agg(distinct case when vfp.partytypeid = 2  and vfp.thumbpath is not null then coalesce(vfp.name,' ')||','||
	 coalesce(vfp.relationship,' ')||' '||coalesce(vfp.relativename,' ')||','||coalesce(vfp.address,' ')||','||coalesce(vfp.profession,' ')end, ' ') as name_addition_person_examined,
	 coalesce(s.sronamee,' ') || ' ' || to_char(a2.inserteddatetime , 'DD-MM-YYYY') as srorefusedate,
	 string_agg(distinct case when vfp.partytypeid=1   then coalesce(vfp.name,' ')||','||coalesce(w.name,'  ') end,',')
	 as  abstract_of_documents,
	for2.refusalscribe as updated_abstract_of_documents,
	a2.remarks   as refusalremarks,
	for2.refusalreasons as updated_refusal_remarks,
	null as summonorder,
	for2.dailyregrefusalsummons::character varying as updated_summonsorder
	from kaveri.applicantapplicationdetails a2 
	join kaveri.documentmaster d on d.applicationnumber = a2.applicationnumber 
	join kaveri.vw_fetch_party vfp on vfp.applicationnumber = a2.applicationnumber 
	join kaveri.feesrequired f2 on f2.applicationnumber = a2.applicationnumber 
	join kaveri.sromaster s on s.srocode = d.srocode 
	join kaveri.districtmaster d2 on s.districtcode = d2.districtcode 
    left join kaveri.witnessinfo w on w.applicationnumber = d.applicationnumber
	left join kaverimis.formno2 for2 on for2.applicationnumber = a2.applicationnumber 
	where
	s.srocode =_srocode and	a2.currentstatus = 'CD134'  and f2.feerulecode=36 
	and d.presentdatetime::date >= _fromdate  and d.presentdatetime::date <=_todate
	and d.finalregistrationnumber=_documentnumber or d.pendingdocumentnumber=_documentnumber
	group by d2.districtnamee, s.sronamee, a2.applicationnumber,d.pendingdocumentnumber, d.presentdatetime,
	d.registrationdatetime, a2.remarks,d.executiondatetime,a2.inserteddatetime,
	w.name,
	d.applicationnumber,for2.refusalscribe,for2.refusalreasons,
	for2.dailyregrefusalsummons,d.uploaddocdeedpath,f2.amountpaid,
	f2.feerulecode order by a2.applicationnumber ;



else

raise notice 'condition failed';
end if;
		  
     END;

$$;


ALTER FUNCTION kaverimis.fn_mis_refusalregister_backup_01_04_2023(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_mis_refusalregister_save(bigint, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_refusalregister_save(_srocode bigint, _applicationnumber character varying DEFAULT NULL::character varying, _refusalscribe character varying DEFAULT NULL::character varying, _refusalreasons character varying DEFAULT NULL::character varying, _dailyregrefusalsummons character varying DEFAULT NULL::character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$


DECLARE
v_cnt bigint;
v_docid bigint;
BEGIN	
select count(*) into v_cnt from kaverimis.formno2 where applicationnumber = _applicationnumber;
raise notice 'v_cnt=%',v_cnt;
IF (v_cnt = 0) and _applicationnumber is not null then
insert into kaverimis.formno2 
(
form2dataentryid,
srocode,
applicationnumber,
refusalscribe,
refusalreasons,
dailyregrefusalsummons,
insertdatetime
)
values 
(
nextval('kaverimis.form2dataentryid_seq'),
_srocode,
_applicationnumber,
_refusalscribe,
_refusalreasons,
_dailyregrefusalsummons,
CURRENT_TIMESTAMP) returning form2dataentryid into v_docid;
elseif (v_cnt = 1) then
update kaverimis.formno2 set 
refusalscribe=_refusalscribe,
refusalreasons=_refusalreasons,
dailyregrefusalsummons=_dailyregrefusalsummons,
insertdatetime=CURRENT_TIMESTAMP
 where
applicationnumber = _applicationnumber and srocode = _srocode
returning form2dataentryid into v_docid;
end if;
raise notice 'v_docid=%',v_docid;
return v_docid;
		  
     END;

$$;


ALTER FUNCTION kaverimis.fn_mis_refusalregister_save(_srocode bigint, _applicationnumber character varying, _refusalscribe character varying, _refusalreasons character varying, _dailyregrefusalsummons character varying) OWNER TO csgadmin;

--
-- Name: fn_mis_register_of_applications_for_ec_cc(bigint, date, date, character varying); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_register_of_applications_for_ec_cc(_srocode bigint, _from_date date, _to_date date, _documentnumber character varying DEFAULT NULL::character varying) RETURNS TABLE(district character varying, sro character varying, finalregistrationnumber character varying, applicationnumber character varying, dateofreceipt text, applicantnameaddr text, nooffollios integer, date_of_disposal text, remarks text)
    LANGUAGE plpgsql
    AS $$
DECLARE

BEGIN	

return query 
select  distinct 
districtnamee as district,
sronamee as sro,
dm.finalregistrationnumber,
cca.applicationnumber,
to_char(cca.submitteddatetime, 'DD-MM-YYYY') as DateOfReceipt,
concat_ws(' ',c.firstname,c.middlename,c.lastname,c.permanentaddress) as NameAddress,
cca.pagecount as nooffollios,
to_char(cca.accepteddatetime, 'DD-MM-YYYY') as DateOfDisposal,
case when cca.accepteddatetime is not null then 'Certified Copy Given' else 'In Process' end as remark
from kaveri.cc_applicationdetails cca 
join kaveri.citizenmaster c on cca.submittedby=c.citizenid 
join kaveri.documentmaster dm on dm.documentnumber::character varying=cca.documentnumber
join kaveri.sromaster sr on dm.srocode = sr.srocode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
where dm.srocode=_srocode and cca.submitteddatetime>=_from_date and cca.submitteddatetime <_to_date and dm.isregistrationcompleted is true;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_register_of_applications_for_ec_cc(_srocode bigint, _from_date date, _to_date date, _documentnumber character varying) OWNER TO csgadmin;

