--

CREATE FUNCTION kaverimis.fn_mis_register_of_applications_for_form23_cc(_srocode bigint, _fromdate date, _todate date, _documentnumber character varying DEFAULT NULL::character varying) RETURNS TABLE(district character varying, sro character varying, finalregistrationnumber character varying, filepath text, applicationnumber character varying, dateofreceipt text, applicantnameaddr text, nooffollios integer, date_of_disposal text, remarks text)
    LANGUAGE plpgsql
    AS $$



DECLARE

BEGIN	
_todate:=(_todate+'1 day'::interval);
if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
raise notice 'Documentnumber null';
return query 
select  distinct 
districtnamee as district,
