dm.finalregistrationnumber,
cca.signedform22 as filepath,
cca.applicationnumber,
to_char(cca.submitteddatetime, 'DD-MM-YYYY') as DateOfReceipt,
concat_ws(' ',c.firstname,c.middlename,c.lastname,c.permanentaddress) as NameAddress,
cca.pagecount as nooffollios,
to_char(cca.accepteddatetime, 'DD-MM-YYYY') as DateOfDisposal,
NULL as remark
from kaveri.cc_applicationdetails cca 
join kaveri.citizenmaster c on cca.submittedby=c.citizenid 
join kaveri.documentmaster dm on dm.documentnumber::character varying=cca.documentnumber
join kaveri.sromaster sr on dm.srocode = sr.srocode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
where dm.srocode=_srocode and cca.submitteddatetime>=_fromdate and cca.submitteddatetime <_todate and dm.isregistrationcompleted is true
and cca.signedform22 is not null ;

elseif 	_documentnumber is not NULL and (_fromdate  is NULL and _todate is NULL) then
	 
	return query

	select  distinct 
districtnamee as district,
sronamee as sro,
dm.finalregistrationnumber,
cca.signedform22 as filepath,
cca.applicationnumber,
to_char(cca.submitteddatetime, 'DD-MM-YYYY') as DateOfReceipt,
concat_ws(' ',c.firstname,c.middlename,c.lastname,c.permanentaddress) as NameAddress,
cca.pagecount as nooffollios,
to_char(cca.accepteddatetime, 'DD-MM-YYYY') as DateOfDisposal,
NULL as remark
from kaveri.cc_applicationdetails cca 
join kaveri.citizenmaster c on cca.submittedby=c.citizenid 
join kaveri.documentmaster dm on dm.documentnumber::character varying=cca.documentnumber
join kaveri.sromaster sr on dm.srocode = sr.srocode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
where dm.srocode=_srocode and  dm.isregistrationcompleted is true AND
cca.applicationnumber=_documentnumber and cca.signedform22 is not null;
	
	
elseif _documentnumber is not NULL and (_fromdate is not NULL and _todate is not NULL) then

raise notice 'nothing null';
return query
select  distinct 
districtnamee as district,
sronamee as sro,
dm.finalregistrationnumber,
cca.signedform22 as filepath,
cca.applicationnumber,
to_char(cca.submitteddatetime, 'DD-MM-YYYY') as DateOfReceipt,
concat_ws(' ',c.firstname,c.middlename,c.lastname,c.permanentaddress) as NameAddress,
cca.pagecount as nooffollios,
to_char(cca.accepteddatetime, 'DD-MM-YYYY') as DateOfDisposal,
NULL as remark
from kaveri.cc_applicationdetails cca 
join kaveri.citizenmaster c on cca.submittedby=c.citizenid 
join kaveri.documentmaster dm on dm.documentnumber::character varying=cca.documentnumber
join kaveri.sromaster sr on dm.srocode = sr.srocode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
where dm.srocode=_srocode and cca.submitteddatetime>=_fromdate and cca.submitteddatetime <_todate and dm.isregistrationcompleted is true AND
cca.applicationnumber=_documentnumber and cca.signedform22 is not null;

else

raise notice 'condition failed';
end if;

END;
$$;


ALTER FUNCTION kaverimis.fn_mis_register_of_applications_for_form23_cc(_srocode bigint, _fromdate date, _todate date, _documentnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_mis_register_of_applications_for_form23_cc(integer, bigint, date, date, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_register_of_applications_for_form23_cc(_districtcode integer, _srocode bigint, _fromdate date, _todate date, _documentnumber character varying DEFAULT NULL::character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, sro character varying, finalregistrationnumber character varying, filepath text, applicationnumber character varying, dateofreceipt text, applicantnameaddr text, nooffollios integer, date_of_disposal text, remarks text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
if(_districtcode=0) THEN --All district
if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
raise notice 'Documentnumber null';
return query 
with cte as (select  distinct 
districtnamee as district,
sronamee as sro,
dm.finalregistrationnumber,
cca.signedform22 as filepath,
cca.applicationnumber,
to_char(cca.submitteddatetime, 'DD-MM-YYYY') as DateOfReceipt,
concat_ws(' ',c.firstname,c.middlename,c.lastname,c.permanentaddress) as NameAddress,
cca.pagecount as nooffollios,
to_char(cca.accepteddatetime, 'DD-MM-YYYY') as DateOfDisposal,
NULL as remark
from kaveri.cc_applicationdetails cca 
join kaveri.citizenmaster c on cca.submittedby=c.citizenid 
join kaveri.documentmaster dm on dm.documentnumber::character varying=cca.documentnumber
join kaveri.sromaster sr on dm.srocode = sr.srocode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
where (cca.submitteddatetime  between  _fromdate and  _todate) and dm.isregistrationcompleted is true
and cca.signedform22 is not null),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY ;

elseif 	_documentnumber is not NULL then
	 
	return query

	with cte as (select  distinct 
districtnamee as district,
sronamee as sro,
dm.finalregistrationnumber,
cca.signedform22 as filepath,
cca.applicationnumber,
to_char(cca.submitteddatetime, 'DD-MM-YYYY') as DateOfReceipt,
concat_ws(' ',c.firstname,c.middlename,c.lastname,c.permanentaddress) as NameAddress,
cca.pagecount as nooffollios,
to_char(cca.accepteddatetime, 'DD-MM-YYYY') as DateOfDisposal,
NULL as remark
from kaveri.cc_applicationdetails cca 
join kaveri.citizenmaster c on cca.submittedby=c.citizenid 
join kaveri.documentmaster dm on dm.documentnumber::character varying=cca.documentnumber
join kaveri.sromaster sr on dm.srocode = sr.srocode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
where dm.isregistrationcompleted is true AND
cca.applicationnumber=_documentnumber and cca.signedform22 is not null),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

end if;
elseif(_srocode=0) then --Perticular District and All Sro
if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
raise notice 'Documentnumber null';
return query 
with cte as (select  distinct 
districtnamee as district,
sronamee as sro,
dm.finalregistrationnumber,
cca.signedform22 as filepath,
cca.applicationnumber,
to_char(cca.submitteddatetime, 'DD-MM-YYYY') as DateOfReceipt,
concat_ws(' ',c.firstname,c.middlename,c.lastname,c.permanentaddress) as NameAddress,
cca.pagecount as nooffollios,
to_char(cca.accepteddatetime, 'DD-MM-YYYY') as DateOfDisposal,
NULL as remark
from kaveri.cc_applicationdetails cca 
join kaveri.citizenmaster c on cca.submittedby=c.citizenid 
join kaveri.documentmaster dm on dm.documentnumber::character varying=cca.documentnumber
join kaveri.sromaster sr on dm.srocode = sr.srocode and sr.districtcode = _districtcode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
where (cca.submitteddatetime  between  _fromdate and  _todate) and dm.isregistrationcompleted is true
and cca.signedform22 is not null ),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

elseif 	_documentnumber is not NULL then
	 
	return query

	with cte as (select  distinct 
districtnamee as district,
sronamee as sro,
dm.finalregistrationnumber,
cca.signedform22 as filepath,
cca.applicationnumber,
to_char(cca.submitteddatetime, 'DD-MM-YYYY') as DateOfReceipt,
concat_ws(' ',c.firstname,c.middlename,c.lastname,c.permanentaddress) as NameAddress,
cca.pagecount as nooffollios,
to_char(cca.accepteddatetime, 'DD-MM-YYYY') as DateOfDisposal,
NULL as remark
from kaveri.cc_applicationdetails cca 
join kaveri.citizenmaster c on cca.submittedby=c.citizenid 
join kaveri.documentmaster dm on dm.documentnumber::character varying=cca.documentnumber
join kaveri.sromaster sr on dm.srocode = sr.srocode and sr.districtcode = _districtcode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
where dm.isregistrationcompleted is true AND
cca.applicationnumber=_documentnumber and cca.signedform22 is not null),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

end if;
else
if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
raise notice 'Documentnumber null';
return query 
with cte as (select  distinct 
districtnamee as district,
sronamee as sro,
dm.finalregistrationnumber,
cca.signedform22 as filepath,
cca.applicationnumber,
to_char(cca.submitteddatetime, 'DD-MM-YYYY') as DateOfReceipt,
concat_ws(' ',c.firstname,c.middlename,c.lastname,c.permanentaddress) as NameAddress,
cca.pagecount as nooffollios,
to_char(cca.accepteddatetime, 'DD-MM-YYYY') as DateOfDisposal,
NULL as remark
from kaveri.cc_applicationdetails cca 
join kaveri.citizenmaster c on cca.submittedby=c.citizenid 
join kaveri.documentmaster dm on dm.documentnumber::character varying=cca.documentnumber and dm.srocode=_srocode 
join kaveri.sromaster sr on dm.srocode = sr.srocode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
where (cca.submitteddatetime  between  _fromdate and  _todate) and dm.isregistrationcompleted is true
and cca.signedform22 is not null),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY ;

elseif 	_documentnumber is not NULL then
	 
	return query

	with cte as (select  distinct 
districtnamee as district,
sronamee as sro,
dm.finalregistrationnumber,
cca.signedform22 as filepath,
cca.applicationnumber,
to_char(cca.submitteddatetime, 'DD-MM-YYYY') as DateOfReceipt,
concat_ws(' ',c.firstname,c.middlename,c.lastname,c.permanentaddress) as NameAddress,
cca.pagecount as nooffollios,
to_char(cca.accepteddatetime, 'DD-MM-YYYY') as DateOfDisposal,
NULL as remark
from kaveri.cc_applicationdetails cca 
join kaveri.citizenmaster c on cca.submittedby=c.citizenid 
join kaveri.documentmaster dm on dm.documentnumber::character varying=cca.documentnumber and dm.srocode=_srocode
join kaveri.sromaster sr on dm.srocode = sr.srocode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
where dm.isregistrationcompleted is true AND
cca.applicationnumber=_documentnumber and cca.signedform22 is not null),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

else

raise notice 'condition failed';
end if;
end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_register_of_applications_for_form23_cc(_districtcode integer, _srocode bigint, _fromdate date, _todate date, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_register_of_applications_for_form24_ec_cc(bigint, timestamp without time zone, timestamp without time zone, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_register_of_applications_for_form24_ec_cc(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice_ec_cc integer) RETURNS TABLE(district character varying, sro character varying, applicationnumber character varying, receiptno text, amountpaid numeric, applicationnumber2 character varying, amount numeric, balance_on_hand text, remarks text)
    LANGUAGE plpgsql
    AS $$




DECLARE

BEGIN	
if  (_fromdate is not NULL and _todate is not NULL) and (_choice_ec_cc=0)  then
	
	return query 
	    select  distinct 
		districtnamee as district,
		sronamee as sro,
		eca.applicationnumber,
		null as receiptno,
		sum(amsre.totalamount), 
		eca.applicationnumber,
		sum(amsre.totalamount),
		null as Balance_on_hand,
		string_agg(distinct amsre.chlnrefnum,',')  as remark
		from kaveri.ec_applicationdetails eca 
		join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode
		join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
		join kaveri.ams_reg_epaymenttransdetails amsre on eca.applicationnumber=amsre.applicationnumber 
		where 
			eca.kaverisrocode=_srocode and
			eca.submitteddatetime>=_fromdate and eca.submitteddatetime <_todate
		group by districtnamee,sronamee, eca.applicationnumber,eca.totalamount, 
		eca.applicationnumber,eca.totalamount;
		
else 

	return query 
select  distinct 
districtnamee as district,
sronamee as sro,
cca.applicationnumber,
null as receiptno,
sum(amsre.totalamount), 
cca.applicationnumber,
sum(amsre.totalamount),
null as Balance_on_hand,
string_agg(distinct amsre.chlnrefnum,',')  as remark
from kaveri.cc_applicationdetails cca 
join kaveri.sromaster sr on cca.kaverisrocode  = sr.srocode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
join kaveri.ams_reg_epaymenttransdetails amsre on cca.applicationnumber=amsre.applicationnumber 

where cca.kaverisrocode=_srocode and cca.submitteddatetime>=_fromdate and cca.submitteddatetime <_todate 
 group by districtnamee,sronamee, cca.applicationnumber,cca.totalamount, 
cca.applicationnumber,cca.totalamount;

end if;




END;
$$;


ALTER FUNCTION kaverimis.fn_mis_register_of_applications_for_form24_ec_cc(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice_ec_cc integer) OWNER TO csgadmin;

--
-- Name: fn_mis_register_of_applications_for_form24_ec_cc(integer, bigint, timestamp without time zone, timestamp without time zone, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_register_of_applications_for_form24_ec_cc(_districtcode integer, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice_ec_cc integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, sro character varying, applicationnumber character varying, receiptno text, amountpaid numeric, applicationnumber2 character varying, amount numeric, balance_on_hand text, remarks text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

	
if(_districtcode=0) THEN --All district	
if  (_fromdate is not NULL and _todate is not NULL) and (_choice_ec_cc=0)  then
	
	return query 
	    with cte as (select  distinct 
		districtnamee as district,
		sronamee as sro,
		eca.applicationnumber,
		null as receiptno,
		sum(amsre.totalamount), 
		eca.applicationnumber,
		sum(amsre.totalamount),
		null as Balance_on_hand,
		string_agg(distinct amsre.chlnrefnum,',')  as remark
		from kaveri.ec_applicationdetails eca 
		join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode
		join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
		join kaveri.ams_reg_epaymenttransdetails amsre on eca.applicationnumber=amsre.applicationnumber 
		where (eca.submitteddatetime between  _fromdate and _todate)
		group by districtnamee,sronamee, eca.applicationnumber,eca.totalamount, 
		eca.applicationnumber,eca.totalamount),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
else 

	return query 
with cte as (select  distinct 
districtnamee as district,
sronamee as sro,
cca.applicationnumber,
null as receiptno,
sum(amsre.totalamount), 
cca.applicationnumber,
sum(amsre.totalamount),
null as Balance_on_hand,
string_agg(distinct amsre.chlnrefnum,',')  as remark
from kaveri.cc_applicationdetails cca 
join kaveri.sromaster sr on cca.kaverisrocode  = sr.srocode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
join kaveri.ams_reg_epaymenttransdetails amsre on cca.applicationnumber=amsre.applicationnumber 

where (cca.submitteddatetime between  _fromdate and _todate)
 group by districtnamee,sronamee, cca.applicationnumber,cca.totalamount, 
cca.applicationnumber,cca.totalamount),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

end if;
elseif(_srocode=0) then --Perticular District and All Sro
if  (_fromdate is not NULL and _todate is not NULL) and (_choice_ec_cc=0)  then
	
	return query 
	    with cte as (select  distinct 
		districtnamee as district,
		sronamee as sro,
		eca.applicationnumber,
		null as receiptno,
		sum(amsre.totalamount), 
		eca.applicationnumber,
		sum(amsre.totalamount),
		null as Balance_on_hand,
		string_agg(distinct amsre.chlnrefnum,',')  as remark
		from kaveri.ec_applicationdetails eca 
		join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode and sr.districtcode = _districtcode
		join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
		join kaveri.ams_reg_epaymenttransdetails amsre on eca.applicationnumber=amsre.applicationnumber 
		where (eca.submitteddatetime between  _fromdate and _todate)
		group by districtnamee,sronamee, eca.applicationnumber,eca.totalamount, 
		eca.applicationnumber,eca.totalamount),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
else 

	return query 
with cte as (select  distinct 
districtnamee as district,
sronamee as sro,
cca.applicationnumber,
null as receiptno,
sum(amsre.totalamount), 
cca.applicationnumber,
sum(amsre.totalamount),
null as Balance_on_hand,
string_agg(distinct amsre.chlnrefnum,',')  as remark
from kaveri.cc_applicationdetails cca 
join kaveri.sromaster sr on cca.kaverisrocode  = sr.srocode and sr.districtcode = _districtcode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
join kaveri.ams_reg_epaymenttransdetails amsre on cca.applicationnumber=amsre.applicationnumber 

where (cca.submitteddatetime between  _fromdate and _todate)
 group by districtnamee,sronamee, cca.applicationnumber,cca.totalamount, 
cca.applicationnumber,cca.totalamount),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

end if;
else
if  (_fromdate is not NULL and _todate is not NULL) and (_choice_ec_cc=0)  then
	
	return query 
	    with cte as (select  distinct 
		districtnamee as district,
		sronamee as sro,
		eca.applicationnumber,
		null as receiptno,
		sum(amsre.totalamount), 
		eca.applicationnumber,
		sum(amsre.totalamount),
		null as Balance_on_hand,
		string_agg(distinct amsre.chlnrefnum,',')  as remark
		from kaveri.ec_applicationdetails eca 
		join kaveri.sromaster sr on eca.kaverisrocode  = sr.srocode
		join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
		join kaveri.ams_reg_epaymenttransdetails amsre on eca.applicationnumber=amsre.applicationnumber 
		where 
			eca.kaverisrocode=_srocode and
			(eca.submitteddatetime between  _fromdate and _todate)
		group by districtnamee,sronamee, eca.applicationnumber,eca.totalamount, 
		eca.applicationnumber,eca.totalamount),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
else 

	return query 
with cte as (select  distinct 
districtnamee as district,
sronamee as sro,
cca.applicationnumber,
null as receiptno,
sum(amsre.totalamount), 
cca.applicationnumber,
sum(amsre.totalamount),
null as Balance_on_hand,
string_agg(distinct amsre.chlnrefnum,',')  as remark
from kaveri.cc_applicationdetails cca 
join kaveri.sromaster sr on cca.kaverisrocode  = sr.srocode
join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
join kaveri.ams_reg_epaymenttransdetails amsre on cca.applicationnumber=amsre.applicationnumber 

where cca.kaverisrocode=_srocode and (cca.submitteddatetime between  _fromdate and _todate)
 group by districtnamee,sronamee, cca.applicationnumber,cca.totalamount, 
cca.applicationnumber,cca.totalamount),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
end if;
end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_register_of_applications_for_form24_ec_cc(_districtcode integer, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _choice_ec_cc integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_register_of_deficient_fees_and_stamp_duty(integer, timestamp without time zone, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_register_of_deficient_fees_and_stamp_duty(_srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying DEFAULT NULL::character varying) RETURNS TABLE(district character varying, sroname character varying, monthofregistry text, documentnumber character varying, copy_of_document text, bookid integer, defregamountrequired numeric, dateofrecoverypenalty text, defamountofstampduty numeric, dateofrecoverystampduty text, dateoftreasuryreceipt text, remarks text)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$

DECLARE

BEGIN 
if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
raise notice 'Documentnumber null';
return query	   
select distinct 
c.districtnamee,
b.sronamee,
to_char(dm.registrationdatetime,'MON') as monthofregistry,
dm.finalregistrationnumber,
dm.uploaddocdeedpath as copy_of_document,
dm.bookid,
sum( case when fr.feerulecode=31 then fr.amountpaid else 0 end) AS deficientamountofregistrationfees,
to_char(fr.lastupdateddate,'dd-MM-YYYY') as dateofrecovery,
sum( case when fr.feerulecode in (35,99,100) then fr.amountpaid else 0 end) AS deficientamountofstampduty,
to_char(fr.lastupdateddate,'dd-MM-YYYY') as dateofrecoverystamp,
to_char(amsreg.inserteddatetime,'dd-MM-YYYY')as trasury_trans_date,
null as remarks
from kaveri.documentmaster dm 
JOIN kaveri.sromaster b ON dm.srocode = b.srocode
join kaveri.districtmaster c on b.districtcode=c.districtcode
join kaveri.feesrequired fr on dm.applicationnumber=fr.applicationnumber 
join  (select distinct applicationnumber,inserteddatetime from kaveri.ams_reg_epaymenttransdetails )amsreg on amsreg.applicationnumber =dm.applicationnumber 
where 
dm.isregistrationcompleted is true and
dm.registrationdatetime is not null and dm.srocode=_srocode
and amountpaid is not null and dm.registrationdatetime>=_fromdate and dm.registrationdatetime<=_todate
group by c.districtnamee,b.sronamee,dm.registrationdatetime,dm.finalregistrationnumber,dm.bookid,dm.uploaddocdeedpath,fr.lastupdateddate,amsreg.inserteddatetime
having sum(distinct  case when fr.feerulecode=31 then amountpaid else 0 end)+sum(distinct  case when fr.feerulecode in (35,39,100) then amountpaid else 0 end)>0;


elseif 	_documentnumber is not NULL and (_fromdate  is NULL and _todate is NULL) then

raise notice 'date null';
return query

select distinct 
c.districtnamee,
b.sronamee,
to_char(dm.registrationdatetime,'MON') as monthofregistry,
dm.finalregistrationnumber,
dm.uploaddocdeedpath as copy_of_document,
dm.bookid,
sum( case when fr.feerulecode=31 then fr.amountpaid else 0 end) AS deficientamountofregistrationfees,
to_char(fr.lastupdateddate,'dd-MM-YYYY') as dateofrecovery,
sum( case when fr.feerulecode in (35,99,100) then fr.amountpaid else 0 end) AS deficientamountofstampduty,
to_char(fr.lastupdateddate,'dd-MM-YYYY') as dateofrecoverystamp,
to_char(amsreg.inserteddatetime,'dd-MM-YYYY')as trasury_trans_date,
null as remarks
from kaveri.documentmaster dm 
JOIN kaveri.sromaster b ON dm.srocode = b.srocode
join kaveri.districtmaster c on b.districtcode=c.districtcode
join kaveri.feesrequired fr on dm.applicationnumber=fr.applicationnumber 
join  (select distinct applicationnumber,inserteddatetime from kaveri.ams_reg_epaymenttransdetails )amsreg on amsreg.applicationnumber =dm.applicationnumber 
where 
dm.isregistrationcompleted is true and
dm.registrationdatetime is not null and dm.srocode=_srocode
and amountpaid is not null and dm.finalregistrationnumber=_documentnumber
group by c.districtnamee,b.sronamee,dm.registrationdatetime,dm.finalregistrationnumber,dm.bookid,dm.uploaddocdeedpath,fr.lastupdateddate,amsreg.inserteddatetime
having sum(distinct  case when fr.feerulecode=31 then amountpaid else 0 end)+sum(distinct  case when fr.feerulecode in (35,39,100) then amountpaid else 0 end)>0;

elseif _documentnumber is not NULL and (_fromdate is not NULL and _todate is not NULL) then

raise notice 'nothing null';
return query	   
select distinct 
c.districtnamee,
b.sronamee,
to_char(dm.registrationdatetime,'MON') as monthofregistry,
dm.finalregistrationnumber,
dm.uploaddocdeedpath as copy_of_document,
dm.bookid,
sum( case when fr.feerulecode=31 then fr.amountpaid else 0 end) AS deficientamountofregistrationfees,
to_char(fr.lastupdateddate,'dd-MM-YYYY') as dateofrecovery,
sum( case when fr.feerulecode in (35,99,100) then fr.amountpaid else 0 end) AS deficientamountofstampduty,
to_char(fr.lastupdateddate,'dd-MM-YYYY') as dateofrecoverystamp,
to_char(amsreg.inserteddatetime,'dd-MM-YYYY')as trasury_trans_date,
null as remarks
from kaveri.documentmaster dm 
JOIN kaveri.sromaster b ON dm.srocode = b.srocode
join kaveri.districtmaster c on b.districtcode=c.districtcode
join kaveri.feesrequired fr on dm.applicationnumber=fr.applicationnumber 
join  (select distinct applicationnumber,inserteddatetime from kaveri.ams_reg_epaymenttransdetails )amsreg on amsreg.applicationnumber =dm.applicationnumber 
where 
dm.isregistrationcompleted is true and
dm.registrationdatetime is not null and dm.srocode=_srocode
and amountpaid is not null and dm.registrationdatetime>=_fromdate and dm.registrationdatetime<=_todate
and dm.finalregistrationnumber=_documentnumber
group by c.districtnamee,b.sronamee,dm.registrationdatetime,dm.finalregistrationnumber,dm.bookid,dm.uploaddocdeedpath,fr.lastupdateddate,amsreg.inserteddatetime
having sum(distinct  case when fr.feerulecode=31 then amountpaid else 0 end)+sum(distinct  case when fr.feerulecode in (35,39,100) then amountpaid else 0 end)>0;

 
 else

raise notice 'condition failed';
end if;

END;
$$;


ALTER FUNCTION kaverimis.fn_mis_register_of_deficient_fees_and_stamp_duty(_srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_mis_register_of_deficient_fees_and_stamp_duty(integer, integer, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_register_of_deficient_fees_and_stamp_duty(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying DEFAULT NULL::character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, sroname character varying, monthofregistry text, documentnumber character varying, copy_of_document text, bookid integer, defregamountrequired numeric, dateofrecoverypenalty text, defamountofstampduty numeric, dateofrecoverystampduty text, dateoftreasuryreceipt text, remarks text, totalcount bigint)
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
--PageOffset := ((pagenumber - 1) * pagesize);
	PageOffset := (pagesize*pagenumber) - pagesize;
	
	if (pagenumber<>-1 and pagesize<>-1) then
  
--if(_districtcode=0) THEN --All district	
--if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
--raise notice 'Documentnumber null';
		
return query
	   
with cte as (select distinct 
c.districtnamee,
b.sronamee,
to_char(dm.registrationdatetime,'MON') as monthofregistry,
dm.finalregistrationnumber,
dm.uploaddocdeedpath as copy_of_document,
dm.bookid,
sum( case when fr.feerulecode=31 then fr.amountpaid else 0 end) AS deficientamountofregistrationfees,
to_char(fr.lastupdateddate,'dd-MM-YYYY') as dateofrecovery,
sum( case when fr.feerulecode in (35,99,100) then fr.amountpaid else 0 end) AS deficientamountofstampduty,
to_char(fr.lastupdateddate,'dd-MM-YYYY') as dateofrecoverystamp,
(select to_char(amsreg.inserteddatetime,'dd-MM-YYYY') from kaveri.ams_reg_epaymenttransdetails amsreg 
where amsreg.documentid=dm.documentid limit 1) as trasury_trans_date,
null as remarks
from kaveri.documentmaster dm 
JOIN kaveri.sromaster b ON dm.srocode = b.srocode
join kaveri.districtmaster c on b.districtcode=c.districtcode
join kaveri.feesrequired fr on dm.applicationnumber=fr.applicationnumber 
where dm.isregistrationcompleted=true 
and dm.registrationdatetime between _fromdate ::timestamp and _todate ::timestamp
and (case
					when _districtcode <> 0 then c.districtcode = _districtcode
					else
						true
				end)
				
				and (case
					when _srocode<>0 then dm.srocode =_srocode
					else true
				end)
				
				and (case
					when _documentnumber<>null then dm.finalregistrationnumber =_documentnumber
					else true
				end)
				
			
--and dm.registrationdatetime between _fromdate::timestamp and _todate::timestamp
group by c.districtnamee,b.sronamee,dm.registrationdatetime,dm.documentid,
dm.finalregistrationnumber,dm.bookid,dm.uploaddocdeedpath,fr.lastupdateddate
having sum(distinct  case when fr.feerulecode=31 then amountpaid else 0 end)
+sum(distinct  case when fr.feerulecode in (35,39,100) then amountpaid else 0 end)>0),cte_count as (select count(*) as total_rows from cte)

			--select * from cte
			--right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
			--	FETCH NEXT pagesize ROWS ONLY;

               select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0 					
			limit pagesize offset PageOffset;
			
elsif (pagenumber=-1 or  pagesize=-1) then 
		
--elseif 	_documentnumber is not NULL then
--raise notice 'date null';
return query

with cte as (

select distinct 
c.districtnamee,
b.sronamee,
to_char(dm.registrationdatetime,'MON') as monthofregistry,
dm.finalregistrationnumber,
dm.uploaddocdeedpath as copy_of_document,
dm.bookid,
sum( case when fr.feerulecode=31 then fr.amountpaid else 0 end) AS deficientamountofregistrationfees,
to_char(fr.lastupdateddate,'dd-MM-YYYY') as dateofrecovery,
sum( case when fr.feerulecode in (35,99,100) then fr.amountpaid else 0 end) AS deficientamountofstampduty,
to_char(fr.lastupdateddate,'dd-MM-YYYY') as dateofrecoverystamp,
to_char(amsreg.inserteddatetime,'dd-MM-YYYY')as trasury_trans_date,
null as remarks
from kaveri.documentmaster dm 
JOIN kaveri.sromaster b ON dm.srocode = b.srocode
join kaveri.districtmaster c on b.districtcode=c.districtcode
join kaveri.feesrequired fr on dm.applicationnumber=fr.applicationnumber 
join  (select distinct applicationnumber,inserteddatetime from kaveri.ams_reg_epaymenttransdetails )amsreg on amsreg.applicationnumber =dm.applicationnumber 
where dm.isregistrationcompleted is true --and dm.registrationdatetime is not null and amountpaid is not null 
--and dm.finalregistrationnumber=_documentnumber
			and (case
					when _districtcode <> 0 then c.districtcode = _districtcode
					else
						true
				end)
				
				and (case
					when _srocode<>0 then dm.srocode =_srocode
					else true
				end)
				
					and (case
					when _documentnumber<>null then dm.finalregistrationnumber =_documentnumber
					else true
				end)
				
group by c.districtnamee,b.sronamee,dm.registrationdatetime,dm.finalregistrationnumber,dm.bookid,dm.uploaddocdeedpath,fr.lastupdateddate,amsreg.inserteddatetime
having sum(distinct  case when fr.feerulecode=31 then amountpaid else 0 end)
+sum(distinct  case when fr.feerulecode in (35,39,100) then amountpaid else 0 end)>0

),cte_count as (select count(*) as total_rows from cte)
			--select * from cte
			--right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				--FETCH NEXT pagesize ROWS ONLY;
				
				      select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0;


end if;

END;
$$;


