--
-- Name: fn_mis_register_of_impounded_doc(bigint, timestamp without time zone, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_register_of_impounded_doc(_srocode bigint, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _documentnumber character varying DEFAULT NULL::character varying) RETURNS TABLE(districtname character varying, sroname character varying, applicationnumber character varying, description_of_doc character varying, name_of_presenter text, executant_claimant text, date_of_execution timestamp without time zone, date_of_presentation timestamp without time zone, purport_of_document character varying, date_of_exec_appr timestamp without time zone, value_of_stamp_doc numeric, deficientamountofstampduty numeric, deficientamountofpenality numeric, dateofrefdc text, dateofreturndoc text, purportoforder text, howdisposedof text)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN 
_todate:=(_todate+'1 day'::interval);
if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
raise notice 'Documentnumber null';
return query	
SELECT distinct 
    c.districtnamee,
    b.sronamee,
	md.applicationnumber,
    string_agg(distinct md.applicationnumber || '  Schedule ' || ps.scheduletype || ' ' || ps.description, ', ')::character varying AS description_of_doc,
  	string_agg(distinct case when pi1.ispresenter=true then	pi1.name end, ', ') as name_of_presenter,
    string_agg(distinct CASE WHEN pi1.isexecutor = true THEN 'Executor'::text ELSE 'Claimant'::text END,', ') AS executant_claimant,
	dm.executiondatetime::timestamp without time zone AS date_of_execution,
	dm.presentdatetime::timestamp without time zone AS date_of_presentation,
    purport_of_doc   AS purport_of_document, -- NULL,
	dm.executiondatetime::timestamp without time zone   AS date_of_exec_appr,
	sum(distinct  case when fr.feerulecode=36 then amountpaid else 0 end) AS value_of_stamp_doc,
	case when form9.impdefstamp is not null then form9.impdefstamp::numeric else
	sum(distinct  case when fr.feerulecode=35 then amountpaid::numeric else 0 end) end as deficientamountofstampduty,
	case when form9.imppenal is not null then form9.imppenal::numeric else
	sum(distinct  case when fr.feerulecode=101 then amountpaid::numeric else 0 end) end  AS deficientamountofpenality,
	impdycomrref::text as dateofrefdc,
	impdycomrret::text as dateofreturndoc,
	imppurp::text as purportoforder,
	imphowdis::text as howdisposedof
   	 FROM kaveri.minutebook_data md left outer join kaveri.documentmaster dm ON md.applicationnumber = dm.applicationnumber 
	 left outer join kaveri.propertymaster pm on pm.applicationnumber=md.applicationnumber
	 left outer join kaveri.propertyschedules ps on pm.propertyid=ps.propertyid
	 left outer join kaveri.vw_fetch_party pi1 on pi1.applicationnumber=md.applicationnumber
	 left outer join kaveri.registrationarticles r on dm.regarticlecode=r.regarticlecode
	 left outer JOIN kaveri.sromaster b ON dm.srocode = b.srocode
	 left outer join kaveri.districtmaster c on b.districtcode=c.districtcode
	 left outer JOIN kaveri.feesrequired fr ON fr.applicationnumber = dm.applicationnumber 
	 left outer join kaverimis.formno9  form9 on form9.applicationnumber = dm.applicationnumber
	  where dm.srocode=_srocode and md.reasonid=2 and pi1.ispresenter=true and
	 dm.executiondatetime::date>=_fromdate and dm.executiondatetime::date<=_todate 
	 and pi1.name is not null
	 group by  form9.impdefstamp ,form9.imppenal, c.districtnamee,b.sronamee,dm.executiondatetime,dm.presentdatetime,r.articlenamee,md.applicationnumber,
	 impdycomrref,purport_of_doc,
	impdycomrret,
	imppurp,
	imphowdis;
	 
	 elseif 	_documentnumber is not NULL and (_fromdate  is NULL and _todate is NULL) then

raise notice 'date null';

return query

SELECT distinct 
    c.districtnamee,
    b.sronamee,
	md.applicationnumber,
    string_agg(distinct md.applicationnumber || '  Schedule ' || ps.scheduletype || ' ' || ps.description, ', ')::character varying AS description_of_doc,
  	string_agg(distinct case when pi1.ispresenter=true then	pi1.name end, ', ') as name_of_presenter,
    string_agg(distinct CASE WHEN pi1.isexecutor = true THEN 'Executor'::text ELSE 'Claimant'::text END,', ') AS executant_claimant,
	dm.executiondatetime::timestamp without time zone AS date_of_execution,
	dm.presentdatetime::timestamp without time zone AS date_of_presentation,
    purport_of_doc   AS purport_of_document, -- NULL,
	dm.executiondatetime::timestamp without time zone   AS date_of_exec_appr,
	sum(distinct  case when fr.feerulecode=36 then amountpaid else 0 end) AS value_of_stamp_doc,
	case when form9.impdefstamp is not null then form9.impdefstamp::numeric else
	sum(distinct  case when fr.feerulecode=35 then amountpaid::numeric else 0 end) end as deficientamountofstampduty,
	case when form9.imppenal is not null then form9.imppenal::numeric else
	sum(distinct  case when fr.feerulecode=101 then amountpaid::numeric else 0 end) end  AS deficientamountofpenality,
	impdycomrref::text as dateofrefdc,
	impdycomrret::text as dateofreturndoc,
	imppurp::text as purportoforder,
	imphowdis::text as howdisposedof
   	 FROM kaveri.minutebook_data md left outer join kaveri.documentmaster dm ON md.applicationnumber = dm.applicationnumber 
	 left outer join kaveri.propertymaster pm on pm.applicationnumber=md.applicationnumber
	 left outer join kaveri.propertyschedules ps on pm.propertyid=ps.propertyid
	 left outer join kaveri.vw_fetch_party pi1 on pi1.applicationnumber=md.applicationnumber
	 left outer join kaveri.registrationarticles r on dm.regarticlecode=r.regarticlecode
	 left outer JOIN kaveri.sromaster b ON dm.srocode = b.srocode
	 left outer join kaveri.districtmaster c on b.districtcode=c.districtcode
	 left outer JOIN kaveri.feesrequired fr ON fr.applicationnumber = dm.applicationnumber 
	 left outer join kaverimis.formno9  form9 on form9.applicationnumber = dm.applicationnumber
	 where dm.srocode=_srocode and md.reasonid=2 and pi1.ispresenter=true and
	  pi1.name is not null AND
	 dm.applicationnumber=_documentnumber
	 group by  form9.impdefstamp ,form9.imppenal, c.districtnamee,b.sronamee,dm.executiondatetime,dm.presentdatetime,r.articlenamee,md.applicationnumber,
	 impdycomrref,purport_of_doc,
	impdycomrret,
	imppurp,
	imphowdis;
	 
	 elseif _documentnumber is not NULL and (_fromdate is not NULL and _todate is not NULL) then

raise notice 'nothing null';
return query	
SELECT distinct 
    c.districtnamee,
    b.sronamee,
	md.applicationnumber,
    string_agg(distinct md.applicationnumber || '  Schedule ' || ps.scheduletype || ' ' || ps.description, ', ')::character varying AS description_of_doc,
  	string_agg(distinct case when pi1.ispresenter=true then	pi1.name end, ', ') as name_of_presenter,
    string_agg(distinct CASE WHEN pi1.isexecutor = true THEN 'Executor'::text ELSE 'Claimant'::text END,', ') AS executant_claimant,
	dm.executiondatetime::timestamp without time zone AS date_of_execution,
	dm.presentdatetime::timestamp without time zone AS date_of_presentation,
    purport_of_doc  AS purport_of_document, -- NULL,
	dm.executiondatetime::timestamp without time zone   AS date_of_exec_appr,
	sum(distinct  case when fr.feerulecode=36 then amountpaid else 0 end) AS value_of_stamp_doc,
	case when form9.impdefstamp is not null then form9.impdefstamp::numeric else
	sum(distinct  case when fr.feerulecode=35 then amountpaid::numeric else 0 end) end as deficientamountofstampduty,
	case when form9.imppenal is not null then form9.imppenal::numeric else
	sum(distinct  case when fr.feerulecode=101 then amountpaid::numeric else 0 end) end  AS deficientamountofpenality,
	impdycomrref::text as dateofrefdc,
	impdycomrret::text as dateofreturndoc,
	imppurp::text as purportoforder,
	imphowdis::text as howdisposedof
   	 FROM kaveri.minutebook_data md left outer join kaveri.documentmaster dm ON md.applicationnumber = dm.applicationnumber 
	 left outer join kaveri.propertymaster pm on pm.applicationnumber=md.applicationnumber
	 left outer join kaveri.propertyschedules ps on pm.propertyid=ps.propertyid
	 left outer join kaveri.vw_fetch_party pi1 on pi1.applicationnumber=md.applicationnumber
	 left outer join kaveri.registrationarticles r on dm.regarticlecode=r.regarticlecode
	 left outer JOIN kaveri.sromaster b ON dm.srocode = b.srocode
	 left outer join kaveri.districtmaster c on b.districtcode=c.districtcode
	 left outer JOIN kaveri.feesrequired fr ON fr.applicationnumber = dm.applicationnumber 
	 left outer join kaverimis.formno9  form9 on form9.applicationnumber = dm.applicationnumber
	  where dm.srocode=_srocode and md.reasonid=2 and pi1.ispresenter=true and
	 dm.executiondatetime::date>=_fromdate and dm.executiondatetime::date<=_todate 
	 and pi1.name is not null AND
	 dm.applicationnumber=_documentnumber
	 group by  form9.impdefstamp ,form9.imppenal, c.districtnamee,b.sronamee,dm.executiondatetime,dm.presentdatetime,r.articlenamee,md.applicationnumber,
	 impdycomrref,purport_of_doc,
	impdycomrret,
	imppurp,
	imphowdis;
	 
	 else

raise notice 'condition failed';
end if;

     
	 

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_register_of_impounded_doc(_srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_mis_register_of_impounded_doc(bigint, bigint, timestamp without time zone, timestamp without time zone, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
