CREATE FUNCTION kaverimis.fn_mis_register_of_impounded_doc(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _documentnumber character varying DEFAULT NULL::character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, applicationnumber character varying, description_of_doc character varying, name_of_presenter text, executant_claimant text, date_of_execution timestamp without time zone, date_of_presentation timestamp without time zone, purport_of_document character varying, date_of_exec_appr timestamp without time zone, value_of_stamp_doc numeric, deficientamountofstampduty numeric, deficientamountofpenality numeric, dateofrefdc text, dateofreturndoc text, purportoforder text, howdisposedof text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
if _districtcode=0 then

			if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
			raise notice 'Documentnumber null';
			return query	
			with cte as (SELECT distinct 
				c.districtnamee,
				b.sronamee,
				md.applicationnumber,
				string_agg(distinct md.applicationnumber || '  Schedule ' || ps.scheduletype || ' ' || ps.description, ', ')::character varying AS description_of_doc,
				string_agg(distinct case when pi1.ispresenter=true then	
				coalesce( pi1.firstname,'  ')
						||' '||coalesce(pi1.middlename,'  ') ||' '||coalesce(pi1.lastname,'  ') end, ', ') as name_of_presenter,
				string_agg(distinct CASE WHEN pi1.isexecutor = true THEN 'Executor'::text ELSE 'Claimant'::text END,', ') AS executant_claimant,
				dm.executiondatetime::timestamp without time zone AS date_of_execution,
				dm.presentdatetime::timestamp without time zone AS date_of_presentation,
				purport_of_doc   AS purport_of_document, -- NULL,
				dm.executiondatetime::timestamp without time zone   AS date_of_exec_appr,
				sum(distinct  case when fr.feerulecode=36 then amountpaid else 0 end) AS value_of_stamp_doc,
				case when form9.impdefstamp is not null then form9.impdefstamp::numeric else
				sum(distinct  case when fr.feerulecode=35 then amountpaid::numeric else 0 end) end as deficientamountofstampduty,
				case when form9.imppenal is not null then form9.imppenal::numeric else
				sum(distinct  case when fr.feerulecode=101 then amountpaid::numeric else 0 end) end  AS deficientamountofpenality,
				impdycomrref::text as dateofrefdc,
				impdycomrret::text as dateofreturndoc,
				imppurp::text as purportoforder,
				imphowdis::text as howdisposedof
				 FROM kaveri.minutebook_data md 
				 left outer join kaveri.documentmaster dm ON md.applicationnumber = dm.applicationnumber 
				 left outer join kaveri.propertymaster pm on pm.applicationnumber=md.applicationnumber
				 left outer join kaveri.propertyschedules ps on pm.propertyid=ps.propertyid
				 left outer join kaveri.partyinfo  pi1 on pi1.applicationnumber=md.applicationnumber
				 left outer join kaveri.registrationarticles r on dm.regarticlecode=r.regarticlecode
				 left outer JOIN kaveri.sromaster b ON dm.srocode = b.srocode
				 left outer join kaveri.districtmaster c on b.districtcode=c.districtcode
				 left outer JOIN kaveri.feesrequired fr ON fr.applicationnumber = dm.applicationnumber 
				 left outer join kaverimis.formno9  form9 on form9.applicationnumber = dm.applicationnumber
				  where 
				  --dm.srocode=173 and 
				  md.reasonid=2 and pi1.ispresenter=true and
				 (dm.executiondatetime between _fromdate and _todate) 
				 
				 group by  form9.impdefstamp ,form9.imppenal, c.districtnamee,b.sronamee,dm.executiondatetime,dm.presentdatetime,r.articlenamee,md.applicationnumber,
				 impdycomrref,purport_of_doc,impdycomrret,imppurp,imphowdis),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
				 
				 elsif 	_documentnumber is not NULL  then

				raise notice 'date null';

				return query

				with cte as (SELECT distinct 
				c.districtnamee,
				b.sronamee,
				md.applicationnumber,
				string_agg(distinct md.applicationnumber || '  Schedule ' || ps.scheduletype || ' ' || ps.description, ', ')::character varying AS description_of_doc,
				string_agg(distinct case when pi1.ispresenter=true then	
				coalesce( pi1.firstname,'  ')
						||' '||coalesce(pi1.middlename,'  ') ||' '||coalesce(pi1.lastname,'  ') end, ', ') as name_of_presenter,
				string_agg(distinct CASE WHEN pi1.isexecutor = true THEN 'Executor'::text ELSE 'Claimant'::text END,', ') AS executant_claimant,
				dm.executiondatetime::timestamp without time zone AS date_of_execution,
				dm.presentdatetime::timestamp without time zone AS date_of_presentation,
				purport_of_doc   AS purport_of_document, -- NULL,
				dm.executiondatetime::timestamp without time zone   AS date_of_exec_appr,
				sum(distinct  case when fr.feerulecode=36 then amountpaid else 0 end) AS value_of_stamp_doc,
				case when form9.impdefstamp is not null then form9.impdefstamp::numeric else
				sum(distinct  case when fr.feerulecode=35 then amountpaid::numeric else 0 end) end as deficientamountofstampduty,
				case when form9.imppenal is not null then form9.imppenal::numeric else
				sum(distinct  case when fr.feerulecode=101 then amountpaid::numeric else 0 end) end  AS deficientamountofpenality,
				impdycomrref::text as dateofrefdc,
				impdycomrret::text as dateofreturndoc,
				imppurp::text as purportoforder,
				imphowdis::text as howdisposedof
				 FROM kaveri.minutebook_data md 
				 left outer join kaveri.documentmaster dm ON md.applicationnumber = dm.applicationnumber 
				 left outer join kaveri.propertymaster pm on pm.applicationnumber=md.applicationnumber
				 left outer join kaveri.propertyschedules ps on pm.propertyid=ps.propertyid
				 left outer join kaveri.partyinfo  pi1 on pi1.applicationnumber=md.applicationnumber
				 left outer join kaveri.registrationarticles r on dm.regarticlecode=r.regarticlecode
				 left outer JOIN kaveri.sromaster b ON dm.srocode = b.srocode
				 left outer join kaveri.districtmaster c on b.districtcode=c.districtcode
				 left outer JOIN kaveri.feesrequired fr ON fr.applicationnumber = dm.applicationnumber 
				 left outer join kaverimis.formno9  form9 on form9.applicationnumber = dm.applicationnumber
				  where dm.applicationnumber=_documentnumber
				  --dm.srocode=173 and 
				 and 
				  md.reasonid=2 and pi1.ispresenter=true 
				 
				 
				 group by  form9.impdefstamp ,form9.imppenal, c.districtnamee,b.sronamee,dm.executiondatetime,dm.presentdatetime,
				 r.articlenamee,md.applicationnumber,
				 impdycomrref,purport_of_doc,impdycomrret,imppurp,imphowdis),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
				 
				
				 else

					raise notice 'condition failed';
				end if;
		elsif _srocode=0 then
		
					if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
			raise notice 'Documentnumber null';
			return query	
			with cte as (SELECT distinct 
				c.districtnamee,
				b.sronamee,
				md.applicationnumber,
				string_agg(distinct md.applicationnumber || '  Schedule ' || ps.scheduletype || ' ' || ps.description, ', ')::character varying AS description_of_doc,
