				  md.reasonid=2 and pi1.ispresenter=true and
				 (dm.executiondatetime between _fromdate and _todate) 
				 
				 group by  form9.impdefstamp ,form9.imppenal, c.districtnamee,b.sronamee,dm.executiondatetime,dm.presentdatetime,r.articlenamee,md.applicationnumber,
				 impdycomrref,purport_of_doc,impdycomrret,imppurp,imphowdis),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
				 
				 elsif 	_documentnumber is not NULL  then

				raise notice 'date null';

				return query

				with cte as (SELECT distinct 
				c.districtnamee,
				b.sronamee,
				md.applicationnumber,
				string_agg(distinct md.applicationnumber || '  Schedule ' || ps.scheduletype || ' ' || ps.description, ', ')::character varying AS description_of_doc,
				string_agg(distinct case when pi1.ispresenter=true then	
				coalesce( pi1.firstname,'  ')
						||' '||coalesce(pi1.middlename,'  ') ||' '||coalesce(pi1.lastname,'  ') end, ', ') as name_of_presenter,
				string_agg(distinct CASE WHEN pi1.isexecutor = true THEN 'Executor'::text ELSE 'Claimant'::text END,', ') AS executant_claimant,
				dm.executiondatetime::timestamp without time zone AS date_of_execution,
				dm.presentdatetime::timestamp without time zone AS date_of_presentation,
				purport_of_doc   AS purport_of_document, -- NULL,
				dm.executiondatetime::timestamp without time zone   AS date_of_exec_appr,
				sum(distinct  case when fr.feerulecode=36 then amountpaid else 0 end) AS value_of_stamp_doc,
				case when form9.impdefstamp is not null then form9.impdefstamp::numeric else
				sum(distinct  case when fr.feerulecode=35 then amountpaid::numeric else 0 end) end as deficientamountofstampduty,
				case when form9.imppenal is not null then form9.imppenal::numeric else
				sum(distinct  case when fr.feerulecode=101 then amountpaid::numeric else 0 end) end  AS deficientamountofpenality,
				impdycomrref::text as dateofrefdc,
				impdycomrret::text as dateofreturndoc,
				imppurp::text as purportoforder,
				imphowdis::text as howdisposedof
				 FROM kaveri.minutebook_data md 
				 left outer join kaveri.documentmaster dm ON md.applicationnumber = dm.applicationnumber 
				 left outer join kaveri.propertymaster pm on pm.applicationnumber=md.applicationnumber
				 left outer join kaveri.propertyschedules ps on pm.propertyid=ps.propertyid
				 left outer join kaveri.partyinfo  pi1 on pi1.applicationnumber=md.applicationnumber
				 left outer join kaveri.registrationarticles r on dm.regarticlecode=r.regarticlecode
				 left outer JOIN kaveri.sromaster b ON dm.srocode = b.srocode
				 left outer join kaveri.districtmaster c on b.districtcode=c.districtcode
				 left outer JOIN kaveri.feesrequired fr ON fr.applicationnumber = dm.applicationnumber 
				 left outer join kaverimis.formno9  form9 on form9.applicationnumber = dm.applicationnumber
				  where dm.applicationnumber=_documentnumber and  c.districtcode=_districtcode 
				  --dm.srocode=173 and 
				 and 
				  md.reasonid=2 and pi1.ispresenter=true 
				 
				 
				 group by  form9.impdefstamp ,form9.imppenal, c.districtnamee,b.sronamee,dm.executiondatetime,dm.presentdatetime,
				 r.articlenamee,md.applicationnumber,
				 impdycomrref,purport_of_doc,impdycomrret,imppurp,imphowdis),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
				 
				
				 else

					raise notice 'condition failed';
				end if;
		
		else
		
					if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
			raise notice 'Documentnumber null';
			return query	
			with cte as (SELECT distinct 
				c.districtnamee,
				b.sronamee,
				md.applicationnumber,
				string_agg(distinct md.applicationnumber || '  Schedule ' || ps.scheduletype || ' ' || ps.description, ', ')::character varying AS description_of_doc,
				string_agg(distinct case when pi1.ispresenter=true then	
				coalesce( pi1.firstname,'  ')
						||' '||coalesce(pi1.middlename,'  ') ||' '||coalesce(pi1.lastname,'  ') end, ', ') as name_of_presenter,
				string_agg(distinct CASE WHEN pi1.isexecutor = true THEN 'Executor'::text ELSE 'Claimant'::text END,', ') AS executant_claimant,
				dm.executiondatetime::timestamp without time zone AS date_of_execution,
				dm.presentdatetime::timestamp without time zone AS date_of_presentation,
				purport_of_doc   AS purport_of_document, -- NULL,
				dm.executiondatetime::timestamp without time zone   AS date_of_exec_appr,
				sum(distinct  case when fr.feerulecode=36 then amountpaid else 0 end) AS value_of_stamp_doc,
				case when form9.impdefstamp is not null then form9.impdefstamp::numeric else
				sum(distinct  case when fr.feerulecode=35 then amountpaid::numeric else 0 end) end as deficientamountofstampduty,
				case when form9.imppenal is not null then form9.imppenal::numeric else
				sum(distinct  case when fr.feerulecode=101 then amountpaid::numeric else 0 end) end  AS deficientamountofpenality,
				impdycomrref::text as dateofrefdc,
				impdycomrret::text as dateofreturndoc,
				imppurp::text as purportoforder,
				imphowdis::text as howdisposedof
				 FROM kaveri.minutebook_data md 
				 left outer join kaveri.documentmaster dm ON md.applicationnumber = dm.applicationnumber 
				 left outer join kaveri.propertymaster pm on pm.applicationnumber=md.applicationnumber
				 left outer join kaveri.propertyschedules ps on pm.propertyid=ps.propertyid
				 left outer join kaveri.partyinfo  pi1 on pi1.applicationnumber=md.applicationnumber
				 left outer join kaveri.registrationarticles r on dm.regarticlecode=r.regarticlecode
				 left outer JOIN kaveri.sromaster b ON dm.srocode = b.srocode
				 left outer join kaveri.districtmaster c on b.districtcode=c.districtcode
				 left outer JOIN kaveri.feesrequired fr ON fr.applicationnumber = dm.applicationnumber 
				 left outer join kaverimis.formno9  form9 on form9.applicationnumber = dm.applicationnumber
				  where 
				  c.districtcode=_districtcode and 
				  dm.srocode=_srocode and 
				  md.reasonid=2 and pi1.ispresenter=true and
				 (dm.executiondatetime between _fromdate and _todate) 
				 
				 group by  form9.impdefstamp ,form9.imppenal, c.districtnamee,b.sronamee,dm.executiondatetime,dm.presentdatetime,r.articlenamee,md.applicationnumber,
				 impdycomrref,purport_of_doc,impdycomrret,imppurp,imphowdis),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
				 
				 elsif 	_documentnumber is not NULL  then

				raise notice 'date null';

				return query

				with cte as (SELECT distinct 
				c.districtnamee,
				b.sronamee,
				md.applicationnumber,
				string_agg(distinct md.applicationnumber || '  Schedule ' || ps.scheduletype || ' ' || ps.description, ', ')::character varying AS description_of_doc,
				string_agg(distinct case when pi1.ispresenter=true then	
				coalesce( pi1.firstname,'  ')
						||' '||coalesce(pi1.middlename,'  ') ||' '||coalesce(pi1.lastname,'  ') end, ', ') as name_of_presenter,
				string_agg(distinct CASE WHEN pi1.isexecutor = true THEN 'Executor'::text ELSE 'Claimant'::text END,', ') AS executant_claimant,
				dm.executiondatetime::timestamp without time zone AS date_of_execution,
				dm.presentdatetime::timestamp without time zone AS date_of_presentation,
				purport_of_doc   AS purport_of_document, -- NULL,
				dm.executiondatetime::timestamp without time zone   AS date_of_exec_appr,
				sum(distinct  case when fr.feerulecode=36 then amountpaid else 0 end) AS value_of_stamp_doc,
				case when form9.impdefstamp is not null then form9.impdefstamp::numeric else
				sum(distinct  case when fr.feerulecode=35 then amountpaid::numeric else 0 end) end as deficientamountofstampduty,
				case when form9.imppenal is not null then form9.imppenal::numeric else
				sum(distinct  case when fr.feerulecode=101 then amountpaid::numeric else 0 end) end  AS deficientamountofpenality,
				impdycomrref::text as dateofrefdc,
				impdycomrret::text as dateofreturndoc,
				imppurp::text as purportoforder,
				imphowdis::text as howdisposedof
				 FROM kaveri.minutebook_data md 
				 left outer join kaveri.documentmaster dm ON md.applicationnumber = dm.applicationnumber 
				 left outer join kaveri.propertymaster pm on pm.applicationnumber=md.applicationnumber
				 left outer join kaveri.propertyschedules ps on pm.propertyid=ps.propertyid
				 left outer join kaveri.partyinfo  pi1 on pi1.applicationnumber=md.applicationnumber
				 left outer join kaveri.registrationarticles r on dm.regarticlecode=r.regarticlecode
				 left outer JOIN kaveri.sromaster b ON dm.srocode = b.srocode
				 left outer join kaveri.districtmaster c on b.districtcode=c.districtcode
				 left outer JOIN kaveri.feesrequired fr ON fr.applicationnumber = dm.applicationnumber 
				 left outer join kaverimis.formno9  form9 on form9.applicationnumber = dm.applicationnumber
				  where dm.applicationnumber=_documentnumber and  dm.districtcode=_districtcode  and 
				  dm.srocode=_srocode and 
			
				  md.reasonid=2 and pi1.ispresenter=true 
				 
				 
				 group by  form9.impdefstamp ,form9.imppenal, c.districtnamee,b.sronamee,dm.executiondatetime,dm.presentdatetime,
				 r.articlenamee,md.applicationnumber,
				 impdycomrref,purport_of_doc,impdycomrret,imppurp,imphowdis),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
				 
				
				 else

					raise notice 'condition failed';
				end if;
		
		end if;     
	 

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_register_of_impounded_doc(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_register_of_impounded_doc_save(bigint, character varying, character varying, timestamp without time zone, timestamp without time zone, character varying, character varying); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_register_of_impounded_doc_save(_srocode bigint, _applicationnumber character varying DEFAULT NULL::character varying, _purport_of_doc character varying DEFAULT NULL::character varying, _dateofrefdr timestamp without time zone DEFAULT NULL::timestamp without time zone, _dateofdroreturn timestamp without time zone DEFAULT NULL::timestamp without time zone, _purportoforder character varying DEFAULT NULL::character varying, _howdisposedof character varying DEFAULT NULL::character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$

DECLARE
v_cnt bigint;
v_docid bigint;
BEGIN	
select count(*) into v_cnt from kaverimis.formno9 where applicationnumber = _applicationnumber;
IF (v_cnt = 0) and _applicationnumber is not null then
insert into kaverimis.formno9 
(
     form9dataentryid,
     srocode,
     applicationnumber,
     purport_of_doc,
    impdycomrref,
    impdycomrret,
    imppurp,
    imphowdis,
	inserteddatetime)
	values
	( nextval('kaverimis.form9dataentryid_seq'),
	 _srocode,
	 _applicationnumber,
	 _dateOfRefDr,
    _DateOfDrOreturn,
    _purportOfOrder,
    _HowDisposedOf,
	CURRENT_TIMESTAMP
	) returning form9dataentryid into v_docid;
	elseif (v_cnt = 1) then
	update 
	kaverimis.formno9 set 
	 impdycomrref=_dateOfRefDr,
    impdycomrret=_DateOfDrOreturn,
    imppurp=_purportOfOrder,
    imphowdis=_HowDisposedOf,
    purport_of_doc=_purport_of_doc,
	inserteddatetime=CURRENT_TIMESTAMP
	where applicationnumber = _applicationnumber and srocode = _srocode
	returning form9dataentryid into v_docid;
end if;

raise notice 'v_docid=%',v_docid;
return v_docid;

    
	 

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_register_of_impounded_doc_save(_srocode bigint, _applicationnumber character varying, _purport_of_doc character varying, _dateofrefdr timestamp without time zone, _dateofdroreturn timestamp without time zone, _purportoforder character varying, _howdisposedof character varying) OWNER TO csgadmin;

--
-- Name: fn_mis_register_of_records_maintained_in_sr_dr(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_register_of_records_maintained_in_sr_dr(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, sroname character varying, no_of_book1 bigint, no_of_book2 bigint, no_of_book3 bigint, no_of_book4 bigint, no_of_book5 bigint, temporary_to_be_specified text, signature_of_the_sub_registrar text)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
	return query 
/*select distinct
b.districtnamee as district,
a.sronamee as sroname,
bookinfo.No_of_Book1,
bookinfo.No_of_Book2,
bookinfo.No_of_Book3,
bookinfo.No_of_Book4,
bookinfo.No_of_Book5
from kaveri.sromaster a inner join kaveri.districtmaster b on a.districtcode = b.districtcode
join ( select srocode,
case when bookid = 1  then
count(bookid) else 0 end as No_of_Book1,
case when bookid = 2  then
count(bookid) else 0 end as No_of_Book2,
case when bookid = 3  then
count(bookid) else 0 end as No_of_Book3,
case when bookid = 4  then
count(bookid) else 0 end as No_of_Book4,
case when bookid = 5  then
count(bookid) else 0 end as No_of_Book5
from kaveri.documentmaster 
where isregistrationcompleted = true and srocode = _srocode and
registrationdatetime >= _fromdate and registrationdatetime <= _todate 
group by srocode,bookid
	 ) bookinfo on bookinfo.srocode = a.srocode
where b.districtcode = _districtcode ;*/
 SELECT 
    c.districtnamee as district,
    b.sronamee as sroname,
   -- to_char(dm.executiondatetime, 'YYYY'::text) AS year,
    sum(
        CASE
            WHEN dm.bookid = 1 THEN 1
            ELSE 0
        END) AS No_of_Book1,
    sum(
        CASE
            WHEN dm.bookid = 2 THEN 1
            ELSE 0
        END) AS No_of_Book2,
    sum(
        CASE
            WHEN dm.bookid = 3 THEN 1
            ELSE 0
        END) AS No_of_Book3,
    sum(
        CASE
            WHEN dm.bookid = 4 THEN 1
            ELSE 0
        END) AS No_of_Book4,
    sum(
        CASE
            WHEN dm.bookid = 5 THEN 1
            ELSE 0
        END) AS No_of_Book5,
		null::text as Temporary_to_be_specified,
		null::text as Signature_of_the_sub_registrar
   FROM kaveri.districtmaster c
     JOIN kaveri.sromaster b ON c.districtcode = b.districtcode
     JOIN kaveri.documentmaster dm ON dm.srocode = b.srocode
  WHERE dm.bookid = ANY (ARRAY[1, 2, 3, 4, 5])
  and dm.srocode = _srocode and b.districtcode = _districtcode and dm.executiondatetime >= _fromdate and
  dm.executiondatetime <= _todate
  GROUP BY b.districtcode, c.districtnamee, b.srocode, b.sronamee, (to_char(dm.executiondatetime, 'YYYY'::text));
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_register_of_records_maintained_in_sr_dr(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_rescanning_details(integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_rescanning_details(_srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) RETURNS TABLE(subregistraroffice character varying, documentnumber integer, rescanningenabledatetime timestamp without time zone, order_date timestamp with time zone, no_of_pages_scanned integer, no_of_pages_rescanned integer, remark text, rescanneddate timestamp without time zone, status text)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize); 		
return query 
select 
c.sronamee as subregistraroffice,
b.documentnumber,
a.scandate as rescanningenabledatetime,
current_timestamp  as order_date,
pm.noofscanpages  as No_of_pages_scanned,
a.pages as No_of_Pages_Rescanned,
null::text as remark,
a.scandate as rescanneddate,
null::text as status
from kaveri.rescandetails a left join kaveri.documentmaster b
on a.documentid = b.documentid
left join kaveri.sromaster c on b.srocode = c.srocode
left join kaveri.propertymaster pm on a.documentid = pm.documentid 
where b.srocode = _srocode  
and a.scandate >= _fromdate and a.scandate <= _todate;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_rescanning_details(_srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_rescanning_details(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_rescanning_details(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(orderid bigint, districtname character varying, sroname character varying, finalregistrationnumber character varying, rescanrequestdate text, order_date text, no_of_pages_scanned integer, no_of_pages_rescanned integer, remark text, rescanneddate text, status text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize); 	
 if _districtcode=0 then --All districtname
    return query
	with cte as (select distinct
	drm.orderid,
	dsm.districtnamee,
	s.sronamee,
	d.finalregistrationnumber,
	to_char(drm.orderdate,'DD-MM-YYYY') as rescanrequestdate,
	to_char(drm.orderdate,'DD-MM-YYYY') as orderdate ,
	p.noofscanpages ,
	drm.rescannoofpages,
	vfuofd.note as remarks,
	to_char(drm.insertdatetime,'DD-MM-YYYY')  as rescanneddate,
	CASE
            WHEN drm.statuscode = 0 THEN 'Pending'::text
            WHEN drm.statuscode = 1 THEN 'Drorder'::text
            WHEN drm.statuscode = 2 THEN 'Deorescan'::text
            WHEN drm.statuscode = 3 THEN 'Rescandone'::text
            WHEN drm.statuscode = 4 THEN 'Finalized'::text
            ELSE 'Finalized'::text
    END AS status
	from kaveri.vw_fetch_under_68_order_from_dr vfuofd 
	left join kaveri.dec_drordermaster drm on  vfuofd.orderid=drm.orderid
	left join kaveri.propertymaster p on vfuofd.documentid=p.documentid
	join kaveri.sromaster s on vfuofd.srocode=s.srocode 
	join kaveri.districtmaster dsm on s.districtcode=dsm.districtcode 
	join kaveri.documentmaster d on vfuofd.documentid=d.documentid

	where 
	drm.orderdate::date>=_fromdate and drm.orderdate::date<=_todate
	--and dsm.districtcode=_districtcode
	--and s.srocode=_srocode 
	and drm.documentrescan is true),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0 OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
	--and dsm.districtcode=_districtcode and s.srocode=_srocode
	
	
	elsif _srocode=0 THEN
	
	return query
	with cte as (select distinct
	drm.orderid,
	dsm.districtnamee,
	s.sronamee,
	d.finalregistrationnumber,
	to_char(drm.orderdate,'DD-MM-YYYY') as rescanrequestdate,
	to_char(drm.orderdate,'DD-MM-YYYY') as orderdate ,
	p.noofscanpages ,
	drm.rescannoofpages,
	vfuofd.note as remarks,
	to_char(drm.insertdatetime,'DD-MM-YYYY')  as rescanneddate,
	CASE
            WHEN drm.statuscode = 0 THEN 'Pending'::text
            WHEN drm.statuscode = 1 THEN 'Drorder'::text
            WHEN drm.statuscode = 2 THEN 'Deorescan'::text
            WHEN drm.statuscode = 3 THEN 'Rescandone'::text
            WHEN drm.statuscode = 4 THEN 'Finalized'::text
            ELSE 'Finalized'::text
    END AS status
	from kaveri.vw_fetch_under_68_order_from_dr vfuofd 
	left join kaveri.dec_drordermaster drm on  vfuofd.orderid=drm.orderid
	left join kaveri.propertymaster p on vfuofd.documentid=p.documentid
	join kaveri.sromaster s on vfuofd.srocode=s.srocode 
	join kaveri.districtmaster dsm on s.districtcode=dsm.districtcode 
	join kaveri.documentmaster d on vfuofd.documentid=d.documentid

	where 
	drm.orderdate::date>=_fromdate and drm.orderdate::date<=_todate
	and dsm.districtcode=_districtcode
	--and s.srocode=_srocode 
	and drm.documentrescan is true),
	cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0 
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
	--and s.srocode=_srocode
	
	
	else --perticular district and perticular srocode
	
	return query
	with cte as (select distinct
	drm.orderid,
	dsm.districtnamee,
	s.sronamee,
	d.finalregistrationnumber,
	to_char(drm.orderdate,'DD-MM-YYYY') as rescanrequestdate,
	to_char(drm.orderdate,'DD-MM-YYYY') as orderdate ,
	p.noofscanpages ,
	drm.rescannoofpages,
	vfuofd.note as remarks,
	to_char(drm.insertdatetime,'DD-MM-YYYY')  as rescanneddate,
	CASE
            WHEN drm.statuscode = 0 THEN 'Pending'::text
            WHEN drm.statuscode = 1 THEN 'Drorder'::text
            WHEN drm.statuscode = 2 THEN 'Deorescan'::text
            WHEN drm.statuscode = 3 THEN 'Rescandone'::text
            WHEN drm.statuscode = 4 THEN 'Finalized'::text
            ELSE 'Finalized'::text
    END AS status
	from kaveri.vw_fetch_under_68_order_from_dr vfuofd 
	left join kaveri.dec_drordermaster drm on  vfuofd.orderid=drm.orderid
	left join kaveri.propertymaster p on vfuofd.documentid=p.documentid
	join kaveri.sromaster s on vfuofd.srocode=s.srocode 
	join kaveri.districtmaster dsm on s.districtcode=dsm.districtcode 
	join kaveri.documentmaster d on vfuofd.documentid=d.documentid

	where 
	drm.orderdate::date>=_fromdate and drm.orderdate::date<=_todate
	and dsm.districtcode=_districtcode
	and s.srocode=_srocode 
	and drm.documentrescan is true),
	cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true
			
			where total_row.total_rows<>0 
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

end if;
	
	
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_rescanning_details(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_rescanning_details_23012024(bigint, bigint, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_rescanning_details_23012024(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(orderid bigint, districtname character varying, sroname character varying, finalregistrationnumber character varying, rescanrequestdate text, order_date text, no_of_pages_scanned integer, no_of_pages_rescanned integer, remark text, rescanneddate text, status text)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize); 	
 if _districtcode=0 then --All districtname
    return query
	select distinct
	drm.orderid,
	dsm.districtnamee,
	s.sronamee,
	d.finalregistrationnumber,
	to_char(drm.orderdate,'DD-MM-YYYY') as rescanrequestdate,
	to_char(drm.orderdate,'DD-MM-YYYY') as orderdate ,
	p.noofscanpages ,
	drm.rescannoofpages,
	vfuofd.note as remarks,
	to_char(drm.insertdatetime,'DD-MM-YYYY')  as rescanneddate,
	CASE
            WHEN drm.statuscode = 0 THEN 'Pending'::text
            WHEN drm.statuscode = 1 THEN 'Drorder'::text
            WHEN drm.statuscode = 2 THEN 'Deorescan'::text
            WHEN drm.statuscode = 3 THEN 'Rescandone'::text
            WHEN drm.statuscode = 4 THEN 'Finalized'::text
            ELSE 'Finalized'::text
    END AS status
	from kaveri.vw_fetch_under_68_order_from_dr vfuofd 
	join kaveri.dec_drordermaster drm on  drm.orderid=vfuofd.orderid 
	join kaveri.propertymaster p on p.documentid=vfuofd.documentid 
	join kaveri.sromaster s on s.srocode=vfuofd.srocode 
	join kaveri.districtmaster dsm on s.districtcode=dsm.districtcode 
	join kaveri.documentmaster d on d.documentid=vfuofd.documentid 

	where 
	drm.orderdate::date>=_fromdate and drm.orderdate::date<=_todate and  drm.documentrescan is true;
	--and dsm.districtcode=_districtcode and s.srocode=_srocode
	
	
	elsif _srocode=0 THEN
	
	return query
	select distinct
	drm.orderid,
	dsm.districtnamee,
	s.sronamee,
	d.finalregistrationnumber,
	to_char(drm.orderdate,'DD-MM-YYYY') as rescanrequestdate,
	to_char(drm.orderdate,'DD-MM-YYYY') as orderdate ,
	p.noofscanpages ,
	drm.rescannoofpages,
	vfuofd.note as remarks,
	to_char(drm.insertdatetime,'DD-MM-YYYY')  as rescanneddate,
	CASE
            WHEN drm.statuscode = 0 THEN 'Pending'::text
            WHEN drm.statuscode = 1 THEN 'Drorder'::text
            WHEN drm.statuscode = 2 THEN 'Deorescan'::text
            WHEN drm.statuscode = 3 THEN 'Rescandone'::text
            WHEN drm.statuscode = 4 THEN 'Finalized'::text
            ELSE 'Finalized'::text
    END AS status
	from kaveri.vw_fetch_under_68_order_from_dr vfuofd 
	join kaveri.dec_drordermaster drm on  drm.orderid=vfuofd.orderid 
	join kaveri.propertymaster p on p.documentid=vfuofd.documentid 
	join kaveri.sromaster s on s.srocode=vfuofd.srocode 
	join kaveri.districtmaster dsm on s.districtcode=dsm.districtcode 
	join kaveri.documentmaster d on d.documentid=vfuofd.documentid 

	where 
	drm.orderdate::date>=_fromdate and drm.orderdate::date<=_todate
	and dsm.districtcode=_districtcode and drm.documentrescan is true;
	--and s.srocode=_srocode
	
	
	else --perticular district and perticular srocode
	
	return query
	select distinct
	drm.orderid,
	dsm.districtnamee,
	s.sronamee,
	d.finalregistrationnumber,
	to_char(drm.orderdate,'DD-MM-YYYY') as rescanrequestdate,
	to_char(drm.orderdate,'DD-MM-YYYY') as orderdate ,
	p.noofscanpages ,
	drm.rescannoofpages,
	vfuofd.note as remarks,
	to_char(drm.insertdatetime,'DD-MM-YYYY')  as rescanneddate,
	CASE
            WHEN drm.statuscode = 0 THEN 'Pending'::text
            WHEN drm.statuscode = 1 THEN 'Drorder'::text
            WHEN drm.statuscode = 2 THEN 'Deorescan'::text
            WHEN drm.statuscode = 3 THEN 'Rescandone'::text
            WHEN drm.statuscode = 4 THEN 'Finalized'::text
            ELSE 'Finalized'::text
    END AS status
	from kaveri.vw_fetch_under_68_order_from_dr vfuofd 
	join kaveri.dec_drordermaster drm on  drm.orderid=vfuofd.orderid 
	join kaveri.propertymaster p on p.documentid=vfuofd.documentid 
	join kaveri.sromaster s on s.srocode=vfuofd.srocode 
	join kaveri.districtmaster dsm on s.districtcode=dsm.districtcode 
	join kaveri.documentmaster d on d.documentid=vfuofd.documentid 

	where 
	drm.orderdate::date>=_fromdate and drm.orderdate::date<=_todate
	and dsm.districtcode=_districtcode
	and s.srocode=_srocode and drm.documentrescan is true;

end if;
	
	
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_rescanning_details_23012024(_districtcode bigint, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_rescanning_details_bck_07072023(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_rescanning_details_bck_07072023(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(documentnumber integer, subregistraroffice character varying, rescanningenabledatetime timestamp without time zone, order_date timestamp with time zone, no_of_pages_scanned integer, no_of_pages_rescanned integer, remark text, status text, rescanneddate timestamp without time zone)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize); 		
return query 
select b.documentnumber,
c.sronamee as subregistraroffice,
a.scandate as rescanningenabledatetime,
current_timestamp  as order_date,
pm.noofscanpages  as No_of_pages_scanned,
a.pages as No_of_Pages_Rescanned,
null::text as remark,
null::text as status,
a.scandate as rescanneddate
from kaveri.rescandetails a left join kaveri.documentmaster b
on a.documentid = b.documentid
left join kaveri.sromaster c on b.srocode = c.srocode
left join kaveri.propertymaster pm on a.documentid = pm.documentid 
where districtcode = _districtcode and b.srocode = _srocode  
and a.scandate >= _fromdate and a.scandate <= _todate;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_rescanning_details_bck_07072023(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_revenue_report_form_fin_13(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
