CREATE FUNCTION kaverimis.fn_mis_revenue_report_form_fin_13(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _amount_type integer DEFAULT NULL::integer, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer) RETURNS TABLE(srooffice character varying, districtname character varying, booktype character varying, part_type character varying, articlaname character varying, documentsregistered bigint, stampduty numeric, registrationfees numeric, otherfees numeric, total numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN	
	

if(_districtcode = 0) then

if _amount_type = 2 then -- registrationfee

	return query
	
select 
 sm.sronamee as SROOffice,
 --po.orgname as companyname,
 d.districtnamee as Districtname,
b.booknameenglish as Booktype,
b.printablename as part_type,
s.articlenamee as articlaname,
count(distinct a.documentid) as DocumentsRegistered,
sum(case when c1.feerulecode in (36,58,59)  then c1.amountpaid else 0 end)as StampDuty,
sum(case when c1.feerulecode=1  then c1.amountpaid else 0 end) as RegistrationFees,
sum(case when c1.feerulecode not in (1,36,58,59,64) then c1.amountpaid else 0 end) as otherfees,
sum(case when c1.feerulecode in (58,59,36)  then c1.amountpaid else 0 end)+
sum(case when c1.feerulecode=1  then c1.amountpaid else 0 end)+
sum(case when c1.feerulecode not in (1,36,58,59,64) then c1.amountpaid else 0 end) as Total

from kaveri.documentmaster a
 --join kaveri.partyorganizationinfo po on a.documentid =po.documentid  
join kaveri.booktypemaster b on a.bookid =b.bookid 
	join kaveri.feesrequired c1 on a.documentid = c1.documentid
	join kaveri.sromaster sm on c1.srocode = sm.srocode
	join kaveri.partyinfo p  on a.documentid =p.documentid 
	join kaveri.districtmaster d on sm.districtcode = d.districtcode
	join kaveri.stampregrelations s2 on s2.regarticlecode = a.regarticlecode 
    join kaveri.stamparticles s on s2.stamparticlecode= s.stamparticlecode 
	 inner join  
     (select applicationnumber,sum(amountpaid) as amountpaid
     from kaverimis.vw_mis_revenue_report 
     where --srocode=_srocode and 
     feerulecode in (1)
     group by applicationnumber
     having sum(amountpaid) >= _minval and sum(amountpaid) <= _maxval) vw1 on c1.applicationnumber  = vw1.applicationnumber
	where a.isregistrationcompleted = true
	--and d.districtcode = _districtcode
	--and a.srocode = _srocode
	and a.registrationdatetime::Date >= _from_date
	and a.registrationdatetime::Date <= _to_date and p.isorganization = true
	group by SROOffice,Districtnamee,Booktype,part_type,articlaname;

elseif _amount_type = 3 then -- StampDuty

	return query
	
	select 
 sm.sronamee as SROOffice,
 --po.orgname as companyname,
 d.districtnamee as Districtname,
b.booknameenglish as Booktype,
b.printablename as part_type,
s.articlenamee as articlaname,
count(distinct a.documentid) as DocumentsRegistered,
sum(case when c1.feerulecode in (36,58,59)  then c1.amountpaid else 0 end)as StampDuty,
sum(case when c1.feerulecode=1  then c1.amountpaid else 0 end) as RegistrationFees,
sum(case when c1.feerulecode not in (1,36,58,59,64) then c1.amountpaid else 0 end) as otherFee,
sum(case when c1.feerulecode in (36,58,59)  then c1.amountpaid else 0 end)+
sum(case when c1.feerulecode=1  then c1.amountpaid else 0 end)+
sum(case when c1.feerulecode not in (1,36,58,59,64) then c1.amountpaid else 0 end) as Total

from kaveri.documentmaster a
 --join kaveri.partyorganizationinfo po on a.documentid =po.documentid  
join kaveri.booktypemaster b on a.bookid =b.bookid 
	join kaveri.feesrequired c1 on a.documentid = c1.documentid
	join kaveri.sromaster sm on c1.srocode = sm.srocode
	join kaveri.partyinfo p  on a.documentid =p.documentid 
	join kaveri.districtmaster d on sm.districtcode = d.districtcode
	join kaveri.stampregrelations s2 on s2.regarticlecode = a.regarticlecode 
    join kaveri.stamparticles s on s2.stamparticlecode= s.stamparticlecode 
	 inner join  
     (select applicationnumber,sum(amountpaid) as amountpaid
     from kaverimis.vw_mis_revenue_report 
     where --srocode=_srocode and 
     feerulecode in (36,58,59)
     group by applicationnumber
     having sum(amountpaid) >= _minval and sum(amountpaid) <= _maxval) vw1 on c1.applicationnumber  = vw1.applicationnumber
	where a.isregistrationcompleted = true and p.isorganization = true
	--and d.districtcode = _districtcode
	--and a.srocode = _srocode
	and a.registrationdatetime::Date >= _from_date
	and a.registrationdatetime::Date <= _to_date
	group by SROOffice,Districtnamee,Booktype,part_type,articlaname;
	
elseif 	_amount_type = 4 then -- other

	return query
	
	select 
 sm.sronamee as SROOffice,
 --po.orgname as companyname,
 d.districtnamee as Districtname,
b.booknameenglish as Booktype,
b.printablename as part_type,
