	join kaveri.feesrequired c1 on a.documentid = c1.documentid
	join kaveri.sromaster sm on c1.srocode = sm.srocode
	join kaveri.partyinfo p  on a.documentid =p.documentid 
	join kaveri.districtmaster d on sm.districtcode = d.districtcode
	join kaveri.stampregrelations s2 on s2.regarticlecode = a.regarticlecode 
    join kaveri.stamparticles s on s2.stamparticlecode= s.stamparticlecode  
	 inner join  
     (select applicationnumber,sum(amountpaid) as amountpaid
     from kaverimis.vw_mis_revenue_report 
     where --srocode=_srocode and 
     feerulecode in (1,36,58,59,64)
     group by applicationnumber
     having sum(amountpaid) >= _minval and sum(amountpaid) <= _maxval) vw1 on c1.applicationnumber  = vw1.applicationnumber
	where a.isregistrationcompleted = true and p.isorganization = true
