ALTER FUNCTION kaverimis.fn_mis_revenue_report_form_fin_13(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _amount_type integer, _minval integer, _maxval integer) OWNER TO csgadmin;

--
-- Name: fn_mis_revenue_report_form_fin_13(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_revenue_report_form_fin_13(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _amount_type integer DEFAULT NULL::integer, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(srooffice character varying, districtname character varying, booktype character varying, part_type character varying, articlaname character varying, documentsregistered bigint, stampduty numeric, registrationfees numeric, otherfees numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE

PageOffset INTEGER := 0;

BEGIN	

PageOffset := ((pagenumber - 1) * pagesize);
--_amount_type = 1 then -- total
 --_amount_type = 2 then -- registrationfee
-- _amount_type = 3 then -- StampDuty
-- _amount_type = 4 then -- other
-- _amount_type = null then -- without min max
if (pagenumber<>-1 and pagesize<>-1) then

	return query
	
with cte as (with a as (select distinct
	 sm.sronamee as SROOffice,
	 d.districtnamee as Districtname,
	 b.booknameenglish as Booktype,
	 b.printablename as part_type,
	 s.articlenamee as articlaname,
	 a.applicationnumber
	 from kaveri.documentmaster a
	join kaveri.booktypemaster b on a.bookid =b.bookid 
	join kaveri.feesrequired c1 on a.applicationnumber = c1.applicationnumber
	join kaveri.sromaster sm on a.srocode = sm.srocode
	join kaveri.partyinfo p  on a.applicationnumber =p.applicationnumber 
	join kaveri.districtmaster d on sm.districtcode = d.districtcode
	join kaveri.stampregrelations s2 on s2.regarticlecode = a.regarticlecode 
    join kaveri.stamparticles s on s2.stamparticlecode= s.stamparticlecode
	
	where 
	
	a.isregistrationcompleted=true 
	and  p.isorganization = true
	and (a.registrationdatetime between  _from_date  and _to_date + INTERVAL '1 day')
	and (case  when _districtcode<>0 then d.districtcode=_districtcode  ELSE  true end)
	and (case  when _srocode<> 0 then a.srocode=_srocode  ELSE  true end)
	and 
	(case

                    when _amount_type=1 then true
                                    
                    when _amount_type=2 then c1.feerulecode in (1,65)
                    
                    when _amount_type=3 then c1.feerulecode in (36,58,59,64)
                                 
                    when _amount_type=4 then c1.feerulecode not in (1,2,36,58,59,64,104,89,88)



                    ELSE

                        true

                                                

                end)
       group by SROOffice,Districtname,Booktype,part_type,articlaname,a.applicationnumber
	having 
			(case
                                      
      			 when _amount_type in (1,2,3,4) then 
      					 sum(c1.amountpaid) >=_minval     and sum(c1.amountpaid) <=_maxval

      			 ELSE

      			 true                                               

         	 	end)
         	 )
	
	select 
	a.SROOffice,
  	a.Districtname,
	a.Booktype,
	a.part_type,
	a.articlaname,
	count(distinct a.applicationnumber) as DocumentsRegistered,
	sum(case when c1.feerulecode in (36,58,59,64)  then c1.amountpaid else 0 end)as StampDuty,
	sum(case when c1.feerulecode in (1,65)  then c1.amountpaid else 0 end) as RegistrationFees,
	sum(case when c1.feerulecode not in (1,36,58,59,64,65)  and 
	c1.amountpaid>0 then c1.amountpaid else 0 end) as otherfees,
	
	sum(case when  c1.amountpaid>0 then c1.amountpaid else 0 end) as Total
	
	from a
	join kaveri.feesrequired c1 on a.applicationnumber=c1.applicationnumber  
	group by a.SROOffice,a.Districtname,a.Booktype,	a.part_type,a.articlaname),
	cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

elsif (pagenumber=-1 or  pagesize=-1) then

return query
	
with cte as (with a as (select distinct
	 sm.sronamee as SROOffice,
	 d.districtnamee as Districtname,
	 b.booknameenglish as Booktype,
	 b.printablename as part_type,
	 s.articlenamee as articlaname,
	 a.applicationnumber
	 from kaveri.documentmaster a
	join kaveri.booktypemaster b on a.bookid =b.bookid 
	join kaveri.feesrequired c1 on a.applicationnumber = c1.applicationnumber
	join kaveri.sromaster sm on a.srocode = sm.srocode
	join kaveri.partyinfo p  on a.applicationnumber =p.applicationnumber 
	join kaveri.districtmaster d on sm.districtcode = d.districtcode
	join kaveri.stampregrelations s2 on s2.regarticlecode = a.regarticlecode 
    join kaveri.stamparticles s on s2.stamparticlecode= s.stamparticlecode
	
	where 
	
	a.isregistrationcompleted=true 
	and  p.isorganization = true
	and (a.registrationdatetime between  _from_date  and _to_date + INTERVAL '1 day')
	and (case  when _districtcode<>0 then d.districtcode=_districtcode  ELSE  true end)
	and (case  when _srocode<> 0 then a.srocode=_srocode  ELSE  true end)
	and 
	(case

                    when _amount_type=1 then true
                                    
                    when _amount_type=2 then c1.feerulecode in (1,65)
                    
                    when _amount_type=3 then c1.feerulecode in (36,58,59,64)
                                 
                    when _amount_type=4 then c1.feerulecode not in (1,2,36,58,59,64,104,89,88)



                    ELSE

                        true

                                                

                end)
       group by SROOffice,Districtname,Booktype,part_type,articlaname,a.applicationnumber
	having 
			(case
                                      
      			 when _amount_type in (1,2,3,4) then 
      					 sum(c1.amountpaid) >=_minval     and sum(c1.amountpaid) <=_maxval

      			 ELSE

      			 true                                               

         	 	end)
         	 )
	
	select 
	a.SROOffice,
  	a.Districtname,
	a.Booktype,
	a.part_type,
	a.articlaname,
	count(distinct a.applicationnumber) as DocumentsRegistered,
	sum(case when c1.feerulecode in (36,58,59,64)  then c1.amountpaid else 0 end)as StampDuty,
	sum(case when c1.feerulecode in (1,65)  then c1.amountpaid else 0 end) as RegistrationFees,
	sum(case when c1.feerulecode not in (1,36,58,59,64,65)  and 
	c1.amountpaid>0 then c1.amountpaid else 0 end) as otherfees,
	
	sum(case when  c1.amountpaid>0 then c1.amountpaid else 0 end) as Total
	
	from a
	join kaveri.feesrequired c1 on a.applicationnumber=c1.applicationnumber  
	group by a.SROOffice,a.Districtname,a.Booktype,	a.part_type,a.articlaname),
	cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0;

end if;

	
end;

$$;


ALTER FUNCTION kaverimis.fn_mis_revenue_report_form_fin_13(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _amount_type integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_revenue_report_form_fin_13_23012024(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_revenue_report_form_fin_13_23012024(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _amount_type integer DEFAULT NULL::integer, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(srooffice character varying, districtname character varying, booktype character varying, part_type character varying, articlaname character varying, documentsregistered bigint, stampduty numeric, registrationfees numeric, otherfees numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE

PageOffset INTEGER := 0;

BEGIN	

PageOffset := ((pagenumber - 1) * pagesize);



if(_districtcode = 0) then

if _amount_type = 2 then -- registrationfee

	return query
	
with cte as (select 
 sm.sronamee as SROOffice,
 --po.orgname as companyname,
 d.districtnamee as Districtname,
b.booknameenglish as Booktype,
b.printablename as part_type,
s.articlenamee as articlaname,
count(distinct a.documentid) as DocumentsRegistered,
sum(case when c1.feerulecode in (36,58,59)  then c1.amountpaid else 0 end)as StampDuty,
sum(case when c1.feerulecode=1  then c1.amountpaid else 0 end) as RegistrationFees,
sum(case when c1.feerulecode not in (1,36,58,59,64) then c1.amountpaid else 0 end) as otherfees,
sum(case when c1.feerulecode in (58,59,36)  then c1.amountpaid else 0 end)+
sum(case when c1.feerulecode=1  then c1.amountpaid else 0 end)+
sum(case when c1.feerulecode not in (1,36,58,59,64) then c1.amountpaid else 0 end) as Total

from kaveri.documentmaster a
 --join kaveri.partyorganizationinfo po on a.documentid =po.documentid  
join kaveri.booktypemaster b on a.bookid =b.bookid 
	join kaveri.feesrequired c1 on a.documentid = c1.documentid
	join kaveri.sromaster sm on c1.srocode = sm.srocode
	join kaveri.partyinfo p  on a.documentid =p.documentid 
	join kaveri.districtmaster d on sm.districtcode = d.districtcode
	join kaveri.stampregrelations s2 on s2.regarticlecode = a.regarticlecode 
    join kaveri.stamparticles s on s2.stamparticlecode= s.stamparticlecode 
	 inner join  
     (select applicationnumber,sum(amountpaid) as amountpaid
     from kaverimis.vw_mis_revenue_report 
     where --srocode=_srocode and 
     feerulecode in (1)
     group by applicationnumber
     having sum(amountpaid) >= _minval and sum(amountpaid) <= _maxval) vw1 on c1.applicationnumber  = vw1.applicationnumber
	where a.isregistrationcompleted = true
	--and d.districtcode = _districtcode
	--and a.srocode = _srocode
	and a.registrationdatetime::Date >= _from_date
	and a.registrationdatetime::Date <= _to_date and p.isorganization = true
	group by SROOffice,Districtnamee,Booktype,part_type,articlaname),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

elseif _amount_type = 3 then -- StampDuty

	return query
	
	with cte as (select 
 sm.sronamee as SROOffice,
 --po.orgname as companyname,
 d.districtnamee as Districtname,
b.booknameenglish as Booktype,
b.printablename as part_type,
s.articlenamee as articlaname,
count(distinct a.documentid) as DocumentsRegistered,
sum(case when c1.feerulecode in (36,58,59)  then c1.amountpaid else 0 end)as StampDuty,
sum(case when c1.feerulecode=1  then c1.amountpaid else 0 end) as RegistrationFees,
sum(case when c1.feerulecode not in (1,36,58,59,64) then c1.amountpaid else 0 end) as otherFee,
sum(case when c1.feerulecode in (36,58,59)  then c1.amountpaid else 0 end)+
sum(case when c1.feerulecode=1  then c1.amountpaid else 0 end)+
sum(case when c1.feerulecode not in (1,36,58,59,64) then c1.amountpaid else 0 end) as Total

from kaveri.documentmaster a
 --join kaveri.partyorganizationinfo po on a.documentid =po.documentid  
join kaveri.booktypemaster b on a.bookid =b.bookid 
	join kaveri.feesrequired c1 on a.documentid = c1.documentid
	join kaveri.sromaster sm on c1.srocode = sm.srocode
	join kaveri.partyinfo p  on a.documentid =p.documentid 
	join kaveri.districtmaster d on sm.districtcode = d.districtcode
	join kaveri.stampregrelations s2 on s2.regarticlecode = a.regarticlecode 
    join kaveri.stamparticles s on s2.stamparticlecode= s.stamparticlecode 
	 inner join  
     (select applicationnumber,sum(amountpaid) as amountpaid
     from kaverimis.vw_mis_revenue_report 
     where --srocode=_srocode and 
     feerulecode in (36,58,59)
     group by applicationnumber
     having sum(amountpaid) >= _minval and sum(amountpaid) <= _maxval) vw1 on c1.applicationnumber  = vw1.applicationnumber
	where a.isregistrationcompleted = true and p.isorganization = true
	--and d.districtcode = _districtcode
	--and a.srocode = _srocode
	and a.registrationdatetime::Date >= _from_date
	and a.registrationdatetime::Date <= _to_date
	group by SROOffice,Districtnamee,Booktype,part_type,articlaname),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
	
