ALTER FUNCTION kaverimis."fn_mis_revenue_report_form_fin_13_bck_31st_Jan"(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _amount_type integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_revenue_report_form_fin_16(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_revenue_report_form_fin_16(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, nameofsubregistrationoffice character varying, book1count bigint, book3count bigint, book4count bigint, book_total bigint, online_payment numeric, dd_cheque numeric, challanamount numeric, cash numeric, total_stamp_duty numeric, r_online_payment numeric, r_challanamount numeric, r_dd_cheque numeric, r_cash numeric, total_registration numeric, scanning numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);	
	
if(_districtcode = 0 and _srocode = 0) then

if(_minval is null and _maxval is null) then 
return query
with cte as (select distinct dsm.districtnamee as districtname, s.sronamee as Nameofsubregistrationoffice,
coalesce(tab1.book1count,0) as book1count,
coalesce(tab2.book3count,0) as book3count,
coalesce(tab3.book4count,0) as book4count,
coalesce(tab1.book1count,0)+coalesce(tab2.book3count,0)+coalesce(tab3.book4count,0) as Book_Total,
coalesce(tab4.Online_Payment,0) as Online_Payment,
coalesce(tab4.DD_Cheque,0) as DD_Cheque,
coalesce(tab4.challan_amount,0) as Challanamount,
coalesce(tab4.cash,0) as cash,
coalesce(tab4.Total_StampDuty,0)as Total_Stamp_Duty,
coalesce(tab5.Online_Payment,0) as R_Online_Payment,
coalesce(tab5.challan_amount,0) as R_Challanamount,
coalesce(tab5.DD_Cheque,0) as R_DD_Cheque,
coalesce(tab5.cash,0) as R_Cash,
coalesce(tab5.Total_Registration,0)as Total_Registration,
coalesce( tab6.Scanning,0)as Scanning,
coalesce(tab4.Total_StampDuty,0)+
coalesce(tab5.Total_Registration,0)+
coalesce( tab6.Scanning,0)as Total

from kaveri.sromaster s
join kaveri.districtmaster dsm on s.districtcode =dsm.districtcode 

join
(select distinct
a.srocode,count(distinct a.documentid) as book1count
from kaveri.documentmaster a
join kaveri.applicantapplicationdetails a2 on a2.applicationnumber = a.applicationnumber
where a.isregistrationcompleted = true and a2.currentstatus = 'CD120'
and a.registrationdatetime::date >=_from_date  and a.registrationdatetime::date <=_to_date
and a.bookid=1
group by a.srocode) tab1  on tab1.srocode=s.srocode
-----------
left join 
(select distinct a.srocode,
count(distinct a.documentid) as book3count
from kaveri.documentmaster a
join kaveri.applicantapplicationdetails a2 on a2.applicationnumber = a.applicationnumber
where a.isregistrationcompleted = true and a2.currentstatus = 'CD120'
and a.registrationdatetime::date >=_from_date  and a.registrationdatetime::date <= _to_date
and a.bookid=3
group by a.srocode) tab2 on s.srocode=tab2.srocode

----------------------
left join
(select distinct a.srocode,
count(distinct a.documentid)as book4count
from kaveri.documentmaster a
join kaveri.applicantapplicationdetails a2 on a2.applicationnumber = a.applicationnumber
where a.isregistrationcompleted = true and a2.currentstatus = 'CD120'
and a.registrationdatetime::date >=_from_date  and a.registrationdatetime::date <= _to_date
and a.bookid=4
group by a.srocode)tab3 on s.srocode=tab3.srocode

---------
left join 
(select distinct sm.srocode ,
--sum(case when feerulecode =89 then totalamount else 0 end) as estamp,
sum(case when paymentmodeid = 2 then totalamount else 0 end )as challan_amount, -- by challan
sum(case when paymentmodeid = 4 then  totalamount else 0 end )as Online_Payment, -- Epayment
sum(case when paymentmodeid = 1 then totalamount else 0 end )as cash, -- By cash
sum(case when paymentmodeid = 3 then totalamount else 0 end )as DD_Cheque, -- DD/cheque
sum(case when paymentmodeid = 2 then totalamount else 0 end) +
sum(case when paymentmodeid = 4 then totalamount else 0 end) +
sum(case when paymentmodeid = 1 then totalamount  else 0 end) +
sum(case when paymentmodeid = 3 then totalamount else 0 end ) as Total_StampDuty
from kaveri.sromaster sm
join (select distinct b.srocode, b.applicationnumber, rpd.paymentmodeid as paymentmodeid,fr.feerulecode, 
sum(fr.amountpaid) as totalamount
from kaveri.applicantapplicationdetails b
join kaveri.documentmaster d on b.applicationnumber =d.applicationnumber 
left join kaveri.feesrequired fr on b.applicationnumber=fr.applicationnumber 
left join kaveri.servicesmaster e on b.applicationtypeid = e.serviceid 
left join(select distinct paymentmodeid,receiptid, srocode from
kaveri.receiptpaymentdetails ) rpd on fr.receiptid=rpd.receiptid
where d.registrationdatetime>=_from_date and d.registrationdatetime<=_to_date and d.isregistrationcompleted = true
and b.currentstatus = 'CD120'
and b.srocode is not null and e.serviceid = 1 and fr.feerulecode in (36,58,59)
group by b.srocode, b.regsrocode,b.applicationnumber,e.serviceid,rpd.paymentmodeid,fr.feerulecode)sub1 on sub1.srocode=sm.srocode
group by sm.srocode)tab4 on s.srocode =tab4.srocode
--------------------
left join 
(select distinct sm.srocode ,
sum(case when paymentmodeid = 2 then totalamount else 0 end )as challan_amount, -- by challan
sum(case when paymentmodeid = 4 then  totalamount else 0 end )as Online_Payment, -- Epayment
sum(case when paymentmodeid = 1 then totalamount else 0 end )as cash, -- By cash
sum(case when paymentmodeid = 3 then totalamount else 0 end )as DD_Cheque, -- DD/cheque
sum(case when paymentmodeid = 2 then totalamount else 0 end) +
sum(case when paymentmodeid = 4 then totalamount else 0 end) +
sum(case when paymentmodeid = 1 then totalamount  else 0 end) +
sum(case when paymentmodeid = 3 then totalamount else 0 end ) as Total_Registration
from kaveri.sromaster sm
join (select distinct b.srocode, b.applicationnumber, rpd.paymentmodeid as paymentmodeid,fr.feerulecode, 
sum(fr.amountpaid) as totalamount
from kaveri.applicantapplicationdetails b
join kaveri.documentmaster d on b.applicationnumber =d.applicationnumber 
left join kaveri.feesrequired fr on b.applicationnumber=fr.applicationnumber 
