ALTER FUNCTION kaverimis.fn_mis_revenue_report_form_fin_16_230120204(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _minval integer, _maxval integer) OWNER TO csgadmin;

--
-- Name: fn_mis_revenue_report_form_fin_18(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_revenue_report_form_fin_18(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, _amount_type integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, nameofsubregistrationoffice character varying, book1count bigint, b1stampduty numeric, b1registrationfee numeric, book3count bigint, b3stampduty numeric, b3registrationfee numeric, book4count bigint, b4stampduty numeric, b4registrationfee numeric, mcstampduty numeric, mcregistrationfee numeric, mcscanningfee numeric, number_ducument bigint, total_stampduty numeric, total_registrationfee numeric, total_scanningfee numeric, total numeric)
    LANGUAGE plpgsql
    AS $$

declare

BEGIN	

	if(_districtcode = 0) then

if _amount_type = 2 then --book1_registrationfee

return query 

select distinct
d.districtnamee as districtname,
s.sronamee as Nameofsubregistrationoffic,
tab1.book1count,tab1.B1stampduty,tab1.B1Registrationfee,

coalesce(tab2.book3count,0) as book3count,
coalesce(tab2.B3stampduty,0) as B3stampduty,
coalesce(tab2.B3Registrationfee,0) as B3Registrationfee,

coalesce(tab3.book4count,0) as book4count,
coalesce(tab3.B4stampduty,0) as B4stampduty,
coalesce(tab3.B4Registrationfee,0) as B4Registrationfee,

coalesce(tab4.mcstampduty,0) as mcstampduty,
coalesce(tab4.mcRegistrationfee,0) as mcRegistrationfee,
coalesce(tab4.mcscanningfee,0) as mcscanningfee,

tab1.book1count +
coalesce(tab2.book3count,0) + 
coalesce(tab3.book4count,0) as Number_ducument,

tab1.B1stampduty+
coalesce(tab2.B3stampduty,0)+
coalesce(tab3.B4stampduty,0)+
coalesce(tab4.mcstampduty,0) as Total_Stampduty,

tab1.B1Registrationfee+
coalesce(tab2.B3Registrationfee,0)+
coalesce(tab3.B4Registrationfee,0)+
coalesce(tab4.mcRegistrationfee,0) as Total_Registrationfee,

coalesce(tab4.mcscanningfee,0) as Total_scanningfee,

tab1.B1stampduty+
coalesce(tab2.B3stampduty,0)+
coalesce(tab3.B4stampduty,0)+
coalesce(tab4.mcstampduty,0)+
tab1.B1Registrationfee+
coalesce(tab2.B3Registrationfee,0)+
coalesce(tab3.B4Registrationfee,0)+
coalesce(tab4.mcRegistrationfee,0)+ 
coalesce(tab4.mcscanningfee,0) as Total

from kaveri.sromaster s 
join kaveri.districtmaster d on s.districtcode=d.districtcode
inner join 
(select distinct a.srocode,
count(distinct a.documentid) as book1count,
sum(case when c1.feerulecode in (36,58,59) then c1.amountpaid else 0 end) as B1stampduty, 
sum(case when c1.feerulecode=1 then c1.amountpaid else 0 end) as B1Registrationfee
from kaveri.documentmaster a 
inner join kaveri.feesrequired c1 on a.documentid = c1.documentid
inner  join kaveri.sromaster b on a.srocode = b.srocode
inner join kaveri.districtmaster dm on b.districtcode = dm.districtcode
inner join  
     (select applicationnumber,sum(amountpaid) as amountpaid
     from kaveri.feesrequired 
     where --srocode=_srocode and 
     feerulecode in (1)
     group by applicationnumber
    having sum(amountpaid) >= _minval and sum(amountpaid) <= _maxval
    ) vw1 on c1.applicationnumber  = vw1.applicationnumber
where a.isregistrationcompleted = true
--and dm.districtcode = _districtcode
--and a.srocode = _srocode 
and a.registrationdatetime ::date>=_fromdate
and a.registrationdatetime ::date<= _todate
and bookid=1
group by a.srocode)tab1 on s.srocode=tab1.srocode

left join
(select distinct a.srocode,
count(distinct a.documentid) as book3count,
sum(case when c1.feerulecode in (36,58,59) then c1.amountpaid else 0 end) as B3stampduty, 
sum(case when c1.feerulecode=1 then c1.amountpaid else 0 end) as B3Registrationfee
from kaveri.documentmaster a 
inner join kaveri.feesrequired c1 on a.documentid = c1.documentid
inner  join kaveri.sromaster b on a.srocode = b.srocode
inner join kaveri.districtmaster dm on b.districtcode = dm.districtcode
inner join  
     (select applicationnumber,sum(amountpaid) as amountpaid
     from kaveri.feesrequired 
     where --srocode=_srocode and 
     feerulecode in (1)
     group by applicationnumber
    having sum(amountpaid) >= _minval and sum(amountpaid) <= _maxval
    ) vw1 on c1.applicationnumber  = vw1.applicationnumber
where a.isregistrationcompleted = true
--and dm.districtcode = _districtcode
--and a.srocode = _srocode 
and a.registrationdatetime ::date>=_fromdate
and a.registrationdatetime ::date<= _todate
and bookid=3
group by a.srocode)tab2 on tab1.srocode=tab2.srocode

left join
(select distinct a.srocode,
count(distinct a.documentid) as book4count,
sum(case when c1.feerulecode in (36,58,59) then c1.amountpaid else 0 end) as B4stampduty, 
sum(case when c1.feerulecode=1 then c1.amountpaid else 0 end) as B4Registrationfee
from kaveri.documentmaster a 
inner join kaveri.feesrequired c1 on a.documentid = c1.documentid
inner  join kaveri.sromaster b on a.srocode = b.srocode
inner join kaveri.districtmaster dm on b.districtcode = dm.districtcode
inner join  
     (select applicationnumber,sum(amountpaid) as amountpaid
     from kaveri.feesrequired 
     where --srocode=_srocode and 
     feerulecode in (1)
     group by applicationnumber
    having sum(amountpaid) >= _minval and sum(amountpaid) <= _maxval
    ) vw1 on c1.applicationnumber  = vw1.applicationnumber
where a.isregistrationcompleted = true
--and dm.districtcode = _districtcode
--and a.srocode = _srocode 
and a.registrationdatetime ::date>=_fromdate
and a.registrationdatetime ::date<= _todate
and bookid=4
group by a.srocode)tab3 on tab2.srocode=tab3.srocode

left join
(select distinct a.srocode,
count(distinct a.documentid) as mccount,
