from 
(select distinct
a.srocode,
b.sronamee, 
a.bookid,
d.districtnamee as districtname,
count(distinct a.documentid) as book1count,
sum(case when c1.feerulecode=36 then c1.amountpaid else 0 end) as B1stampduty, 
sum(case when c1.feerulecode=1 then c1.amountpaid else 0 end) as B1Registrationfee, 
sum(case when c1.feerulecode=2 then c1.amountpaid else 0 end) as B1scanningfee

