ALTER FUNCTION kaverimis.fn_mis_revenue_report_form_fin_18_backup_30_03_2023(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _minval numeric, _maxval numeric, _amount_type integer) OWNER TO csgadmin;

--
-- Name: fn_mis_revenue_report_form_fin_19(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_revenue_report_form_fin_19(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _amount_type integer DEFAULT NULL::integer, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, monthname text, numberofdocuments bigint, registrationfees numeric, stampduty numeric, scanningfees numeric, otherfees numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    PageOffset integer := 0;
BEGIN
    IF COALESCE(pagenumber, -1) <> -1
       AND COALESCE(pagesize, -1) <> -1 THEN

        PageOffset := (pagesize * pagenumber) - pagesize;

        RETURN QUERY
        WITH base_docs AS (
            SELECT
                dm.districtnamee::varchar AS districtname,
                sm.sronamee::varchar AS sroname,
                trim(to_char(d.registrationdatetime, 'Month'))::text AS monthname,
                d.documentid,
                d.applicationnumber,
                d.registrationdatetime,
                sm.srocode,
                dm.districtcode
            FROM kaveri.documentmaster d
            JOIN kaveri.sromaster sm
                ON sm.srocode = d.srocode
            JOIN kaveri.districtmaster dm
                ON dm.districtcode = sm.districtcode
            WHERE d.registrationdatetime::date >= _from_date::date
              AND d.registrationdatetime::date <= _to_date::date
              AND d.isregistrationcompleted = true
              AND d.bookid = 1
              AND (CASE WHEN _districtcode <> 0 THEN dm.districtcode = _districtcode ELSE true END)
              AND (CASE WHEN _srocode <> 0 THEN d.srocode = _srocode ELSE true END)
        ),
        success_epay AS (
            SELECT
                e.applicationnumber,
                e.deptreferencecode,
                e.feerulecode,
                COALESCE(e.totalamount, 0)::numeric AS totalamount,
                b.paymentmode,
                b.paymentstatuscode,
                b.transactiontimestamp
            FROM kaveri.ams_reg_epaymenttransdetails e
            JOIN kaveri.ams_reg_epaymentbankackdetails b
              ON b.deptreferencecode = e.deptreferencecode
            WHERE e.isdelete = false
              AND b.paymentstatuscode IN ('10700066','10700072')
              AND e.applicationnumber IN (SELECT bd.applicationnumber FROM base_docs bd)
        ),
        amt AS (
            SELECT
                se.applicationnumber,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (35,36,64,89,91,92,101,107,110,138,58,59,99,100)  --surcharge+cess--
                ), 0) AS stampduty_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ), 0) AS regfee_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode = 2
                ), 0) AS scanning_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode NOT IN (
                        35,36,64,89,91,92,101,107,110,138,58,59,99,100,   -- stamp + cess
                        2,                                            -- scanning
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109   -- reg fee
                    )
                ), 0) AS other_amt,

                COALESCE(SUM(se.totalamount), 0) AS total_amt
            FROM success_epay se
            GROUP BY se.applicationnumber
        ),
        app_level AS (
            SELECT
                bd.districtname,
                bd.sroname,
                bd.monthname,
                bd.documentid,
                bd.applicationnumber,
                COALESCE(a.regfee_amt, 0) AS registrationfees,
                COALESCE(a.stampduty_amt, 0) AS stampduty,
                COALESCE(a.scanning_amt, 0) AS scanningfees,
                COALESCE(a.other_amt, 0) AS otherfees,
                COALESCE(a.total_amt, 0) AS total,
                CASE
                    WHEN _amount_type = 2 THEN COALESCE(a.regfee_amt, 0)
                    WHEN _amount_type = 3 THEN COALESCE(a.stampduty_amt, 0)
                    WHEN _amount_type = 4 THEN COALESCE(a.scanning_amt, 0)
                    WHEN _amount_type = 5 THEN COALESCE(a.other_amt, 0)
                    ELSE COALESCE(a.total_amt, 0)
                END AS filter_amount
            FROM base_docs bd
            JOIN amt a
              ON a.applicationnumber = bd.applicationnumber
            WHERE
                (
                    (_minval IS NULL AND _maxval IS NULL)
                    OR
                    (
                        CASE
                            WHEN _amount_type = 2 THEN COALESCE(a.regfee_amt, 0)
                            WHEN _amount_type = 3 THEN COALESCE(a.stampduty_amt, 0)
                            WHEN _amount_type = 4 THEN COALESCE(a.scanning_amt, 0)
                            WHEN _amount_type = 5 THEN COALESCE(a.other_amt, 0)
                            ELSE COALESCE(a.total_amt, 0)
                        END
                        BETWEEN COALESCE(_minval, 0) AND COALESCE(_maxval, 999999999999::numeric)
                    )
                )
        ),
        cte AS (
            SELECT
                al.districtname,
                al.sroname,
                al.monthname,
                COUNT(DISTINCT al.documentid)::bigint AS numberofdocuments,
                COALESCE(SUM(al.registrationfees), 0)::numeric AS registrationfees,
                COALESCE(SUM(al.stampduty), 0)::numeric AS stampduty,
                COALESCE(SUM(al.scanningfees), 0)::numeric AS scanningfees,
                COALESCE(SUM(al.otherfees), 0)::numeric AS otherfees,
                COALESCE(SUM(al.total), 0)::numeric AS total
            FROM app_level al
            GROUP BY al.districtname, al.sroname, al.monthname
        ),
        cte_count AS (
            SELECT COUNT(*)::bigint AS total_rows
            FROM cte
        )
        SELECT
            c.districtname,
            c.sroname,
            c.monthname,
            c.numberofdocuments,
            c.registrationfees,
            c.stampduty,
            c.scanningfees,
            c.otherfees,
            c.total,
            cc.total_rows AS totalcount
        FROM cte c
        CROSS JOIN cte_count cc
        WHERE cc.total_rows <> 0
        ORDER BY c.districtname, c.sroname, c.monthname
        LIMIT pagesize OFFSET PageOffset;

    ELSE

        RETURN QUERY
        WITH base_docs AS (
            SELECT
                dm.districtnamee::varchar AS districtname,
                sm.sronamee::varchar AS sroname,
                trim(to_char(d.registrationdatetime, 'Month'))::text AS monthname,
                d.documentid,
                d.applicationnumber,
                d.registrationdatetime,
                sm.srocode,
                dm.districtcode
            FROM kaveri.documentmaster d
            JOIN kaveri.sromaster sm
                ON sm.srocode = d.srocode
            JOIN kaveri.districtmaster dm
                ON dm.districtcode = sm.districtcode
            WHERE d.registrationdatetime::date >= _from_date::date
              AND d.registrationdatetime::date <= _to_date::date
              AND d.isregistrationcompleted = true
              AND d.bookid = 1
              AND (CASE WHEN _districtcode <> 0 THEN dm.districtcode = _districtcode ELSE true END)
              AND (CASE WHEN _srocode <> 0 THEN d.srocode = _srocode ELSE true END)
        ),
        success_epay AS (
            SELECT
                e.applicationnumber,
                e.deptreferencecode,
                e.feerulecode,
                COALESCE(e.totalamount, 0)::numeric AS totalamount,
                b.paymentmode,
                b.paymentstatuscode,
                b.transactiontimestamp
            FROM kaveri.ams_reg_epaymenttransdetails e
            JOIN kaveri.ams_reg_epaymentbankackdetails b
              ON b.deptreferencecode = e.deptreferencecode
            WHERE e.isdelete = false
              AND b.paymentstatuscode IN ('10700066','10700072')
              AND e.applicationnumber IN (SELECT bd.applicationnumber FROM base_docs bd)
        ),
        amt AS (
            SELECT
                se.applicationnumber,
                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (35,36,64,89,91,92,101,107,110,138,58,59,99,100) ---surcharge+cess--
                ), 0) AS stampduty_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode IN (
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109
                    )
                ), 0) AS regfee_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode = 2
                ), 0) AS scanning_amt,

                COALESCE(SUM(se.totalamount) FILTER (
                    WHERE se.feerulecode NOT IN (
                        35,36,64,89,91,92,101,107,110,138,58,59,99,100,   -- stamp + cess
                        2,                                            -- scanning
                        1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,
                        57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109   -- reg fee
                    )
                ), 0) AS other_amt,

                COALESCE(SUM(se.totalamount), 0) AS total_amt
            FROM success_epay se
            GROUP BY se.applicationnumber
        ),
        app_level AS (
            SELECT
                bd.districtname,
                bd.sroname,
                bd.monthname,
                bd.documentid,
                bd.applicationnumber,
                COALESCE(a.regfee_amt, 0) AS registrationfees,
                COALESCE(a.stampduty_amt, 0) AS stampduty,
                COALESCE(a.scanning_amt, 0) AS scanningfees,
                COALESCE(a.other_amt, 0) AS otherfees,
                COALESCE(a.total_amt, 0) AS total,
                CASE
                    WHEN _amount_type = 2 THEN COALESCE(a.regfee_amt, 0)
                    WHEN _amount_type = 3 THEN COALESCE(a.stampduty_amt, 0)
                    WHEN _amount_type = 4 THEN COALESCE(a.scanning_amt, 0)
                    WHEN _amount_type = 5 THEN COALESCE(a.other_amt, 0)
                    ELSE COALESCE(a.total_amt, 0)
                END AS filter_amount
            FROM base_docs bd
            JOIN amt a
              ON a.applicationnumber = bd.applicationnumber
            WHERE
                (
                    (_minval IS NULL AND _maxval IS NULL)
                    OR
                    (
                        CASE
                            WHEN _amount_type = 2 THEN COALESCE(a.regfee_amt, 0)
                            WHEN _amount_type = 3 THEN COALESCE(a.stampduty_amt, 0)
                            WHEN _amount_type = 4 THEN COALESCE(a.scanning_amt, 0)
                            WHEN _amount_type = 5 THEN COALESCE(a.other_amt, 0)
                            ELSE COALESCE(a.total_amt, 0)
                        END
                        BETWEEN COALESCE(_minval, 0) AND COALESCE(_maxval, 999999999999::numeric)
                    )
                )
        ),
        cte AS (
            SELECT
                al.districtname,
                al.sroname,
                al.monthname,
                COUNT(DISTINCT al.documentid)::bigint AS numberofdocuments,
                COALESCE(SUM(al.registrationfees), 0)::numeric AS registrationfees,
                COALESCE(SUM(al.stampduty), 0)::numeric AS stampduty,
                COALESCE(SUM(al.scanningfees), 0)::numeric AS scanningfees,
                COALESCE(SUM(al.otherfees), 0)::numeric AS otherfees,
                COALESCE(SUM(al.total), 0)::numeric AS total
            FROM app_level al
            GROUP BY al.districtname, al.sroname, al.monthname
        ),
        cte_count AS (
            SELECT COUNT(*)::bigint AS total_rows
            FROM cte
        )
        SELECT
            c.districtname,
            c.sroname,
            c.monthname,
            c.numberofdocuments,
            c.registrationfees,
            c.stampduty,
            c.scanningfees,
            c.otherfees,
            c.total,
            cc.total_rows AS totalcount
        FROM cte c
        CROSS JOIN cte_count cc
        WHERE cc.total_rows <> 0
        ORDER BY c.districtname, c.sroname, c.monthname;

    END IF;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_revenue_report_form_fin_19(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _amount_type integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_revenue_report_form_fin_19_20260414(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_revenue_report_form_fin_19_20260414(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _amount_type integer DEFAULT NULL::integer, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, monthname text, numberofdocuments bigint, registrationfees numeric, stampduty numeric, scanningfees numeric, otherfees numeric, total numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$


declare

PageOffset INTEGER := 0;

	begin
		
		--PageOffset := ((pagenumber - 1) * pagesize);
		PageOffset := (pagesize*pagenumber) - pagesize;
	if (pagenumber<>-1 and pagesize<>-1) then	
		return query
		
		with cte as (select distinct dm.districtnamee as Districtname,sm.sronamee as sroname,to_char(d.registrationdatetime, 'month') as Monthname, 
	count(distinct d.documentid) as numberofdocuments,
	sum(case when f.feerulecode=1 then f.amountpaid else 0 end) as RegistrationFees, 
	sum(case when f.feerulecode in (36,58,59) then f.amountpaid else 0 end)as StampDuty, 
	sum(case when f.feerulecode=2 then f.amountpaid else 0 end) as Scanningfees, 
	sum(case when f.feerulecode not in (1,36,2,58,59) and f.amountpaid>0 then f.amountpaid else 0 end ) as otherfees, 
	(sum(case when f.feerulecode=1 then f.amountpaid else 0 end)+ 
	sum(case when f.feerulecode in (36,58,59) then f.amountpaid else 0 end)+ 
	sum(case when f.feerulecode=2 then f.amountpaid else 0 end)+ 
	sum(case when f.feerulecode not in (1,36,2,58,59) and f.amountpaid>0 then f.amountpaid else 0 end )) as Total

	from kaveri.documentmaster d 
-- 	join kaveri.applicantapplicationdetails a on a.applicationnumber = d.applicationnumber
	join kaveri.feesrequired f on f.applicationnumber=d.applicationnumber  
	join kaveri.sromaster sm on d.srocode = sm.srocode 
	join kaveri.districtmaster dm on sm.districtcode = dm.districtcode 
	where d.registrationdatetime::date >= _from_date and d.registrationdatetime::date <= _to_date 
	and d.isregistrationcompleted = true and d.bookid=1-- and a.currentstatus = 'CD120'

	and (CASE   
          WHEN _amount_type <> 1 and _amount_type <> 2 and _amount_type <> 3 and _amount_type <> 4 and _amount_type <> 5 then true 
							
          ELSE 
                                
			(case   
			     WHEN _amount_type = 3 THEN f.feerulecode in (36,58,59) 
			     WHEN _amount_type = 2 THEN f.feerulecode in (1)
			     WHEN _amount_type = 4 THEN f.feerulecode in (2) 
			     WHEN _amount_type = 5 THEN f.feerulecode  not in (1,2,36,58,59)
			     ELSE  TRUE
			end)
							
      end)

   and (case
		 when _districtcode <> 0 then dm.districtcode=_districtcode 
		 else
		 	true
	end)				

  and (case
		 when _srocode<>0 then d.srocode=_srocode
		 else 
		 	true
	end)				
  group by Monthname,Sronamee,Districtnamee,sm.srocode 
  having 
				
				(case   
			                                WHEN _minval is not null and _maxval is not null then
				                                sum(f.amountpaid)>=_minval and sum(f.amountpaid)<=_maxval
			                                ELSE 
			                                	true 
			                                    
				end)
				
--	limit pagesize offset PageOffset;
				),cte_count as (select count(*) as total_rows from cte)

            select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0
		
		limit pagesize offset PageOffset;

elsif (pagenumber=-1 or  pagesize=-1) then 
return query
		
		with cte as (select distinct dm.districtnamee as Districtname,sm.sronamee as sroname,to_char(d.registrationdatetime, 'month') as Monthname, 
	count(distinct d.documentid) as numberofdocuments,
	sum(case when f.feerulecode=1 then f.amountpaid else 0 end) as RegistrationFees, 
	sum(case when f.feerulecode in (36,58,59) then f.amountpaid else 0 end)as StampDuty, 
	sum(case when f.feerulecode=2 then f.amountpaid else 0 end) as Scanningfees, 
	sum(case when f.feerulecode not in (1,36,2,58,59) and  f.amountpaid>0 
	then f.amountpaid else 0 end ) as otherfees, 
	(sum(case when f.feerulecode=1 then f.amountpaid else 0 end)+ 
	sum(case when f.feerulecode in (36,58,59) then f.amountpaid else 0 end)+ 
	sum(case when f.feerulecode=2 then f.amountpaid else 0 end)+ 
	sum(case when f.feerulecode not in (1,36,2,58,59) and f.amountpaid>0 
	then f.amountpaid else 0 end )) as Total

	from kaveri.documentmaster d 
-- 	join kaveri.applicantapplicationdetails a on a.applicationnumber = d.applicationnumber
	join kaveri.feesrequired f on f.applicationnumber=d.applicationnumber  
	join kaveri.sromaster sm on d.srocode = sm.srocode 
	join kaveri.districtmaster dm on sm.districtcode = dm.districtcode 
	where d.registrationdatetime::date >= _from_date and d.registrationdatetime::date <= _to_date 

	and d.isregistrationcompleted = true and d.bookid=1-- and a.currentstatus = 'CD120'


	and (CASE   
          WHEN _amount_type <> 1 and _amount_type <> 2 and _amount_type <> 3 and _amount_type <> 4 and _amount_type <> 5 then true 
							
          ELSE 
                                
			(case   
			     WHEN _amount_type = 3 THEN f.feerulecode in (36,58,59) 
			     WHEN _amount_type = 2 THEN f.feerulecode in (1)
			     WHEN _amount_type = 4 THEN f.feerulecode in (2) 
			     WHEN _amount_type = 5 THEN f.feerulecode  not in (1,2,36,58,59)
			     ELSE  TRUE
			end)
							
      end)

   and (case
		 when _districtcode <> 0 then dm.districtcode=_districtcode 
		 else
		 	true
	end)				

  and (case
		 when _srocode<>0 then d.srocode=_srocode
		 else 
		 	true
	end)				
  group by Monthname,Sronamee,Districtnamee,sm.srocode 
  having 
				
				(case   
			                                WHEN _minval is not null and _maxval is not null then
				                                sum(f.amountpaid)>=_minval and sum(f.amountpaid)<=_maxval
			                                ELSE 
			                                	true 
			                                    
				end)
				
--	limit pagesize offset PageOffset;
				),cte_count as (select count(*) as total_rows from cte)

            select * from cte
			right join (select total_rows from cte_count) total_row on true
			where total_row.total_rows<>0;

end if ;
	END;
$$;


ALTER FUNCTION kaverimis.fn_mis_revenue_report_form_fin_19_20260414(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _amount_type integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_revenue_report_form_fin_19_23012024(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_revenue_report_form_fin_19_23012024(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _amount_type integer DEFAULT NULL::integer, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, monthname text, numberofdocuments bigint, registrationfees numeric, stampduty numeric, scanningfees numeric, otherfees numeric, total numeric)
    LANGUAGE plpgsql
    AS $$



DECLARE

BEGIN	
	

if(_districtcode = 0) then

if _amount_type = 2 then -- registrationfee

	return query

select distinct dm.districtnamee as Districtname,sm.sronamee as sroname,to_char(d.registrationdatetime, 'month') as Monthname, 
count(distinct d.documentid) as numberofdocuments,
sum(case when f.feerulecode=1 then f.amountpaid else 0 end) as RegistrationFees, 
sum(case when f.feerulecode in (36,58,59) then f.amountpaid else 0 end)as StampDuty, 
sum(case when f.feerulecode=2 then f.amountpaid else 0 end) as Scanningfees, 
sum(case when f.feerulecode not in (1,36,2,58,59)  and  f.amountpaid>0 then f.amountpaid else 0 end ) as otherfees, 
(sum(case when f.feerulecode=1 then f.amountpaid else 0 end)+ 
sum(case when f.feerulecode in (36,58,59) then f.amountpaid else 0 end)+ 
sum(case when f.feerulecode=2 then f.amountpaid else 0 end)+ 
sum(case when f.feerulecode not in (1,36,2,58,59)  and  f.amountpaid>0 then f.amountpaid else 0 end )) as Total
from kaveri.documentmaster d  
left join kaveri.feesrequired f on f.applicationnumber=d.applicationnumber  
left join kaveri.sromaster sm on d.srocode = sm.srocode 
left join kaveri.districtmaster dm on sm.districtcode = dm.districtcode 
where d.registrationdatetime::date >= _from_date and d.registrationdatetime::date <= _to_date 
and d.isregistrationcompleted = true  and f.feerulecode in (1)
group by Monthname,Sronamee,Districtnamee,sm.srocode 
having sum(f.amountpaid) >= _minval and sum(f.amountpaid) <= _maxval;

elseif _amount_type = 3 then -- StampDuty

	return query
	
select distinct dm.districtnamee as Districtname,sm.sronamee as sroname,to_char(d.registrationdatetime, 'month') as Monthname, 
count(distinct d.documentid) as numberofdocuments,
sum(case when f.feerulecode=1 then f.amountpaid else 0 end) as RegistrationFees, 
sum(case when f.feerulecode in (36,58,59) then f.amountpaid else 0 end)as StampDuty, 
sum(case when f.feerulecode=2 then f.amountpaid else 0 end) as Scanningfees, 
sum(case when f.feerulecode not in (1,36,2,58,59)  and  f.amountpaid>0 then f.amountpaid else 0 end ) as otherfees, 
(sum(case when f.feerulecode=1 then f.amountpaid else 0 end)+ 
sum(case when f.feerulecode in (36,58,59) then f.amountpaid else 0 end)+ 
sum(case when f.feerulecode=2 then f.amountpaid else 0 end)+ 
sum(case when f.feerulecode not in (1,36,2,58,59)  and  f.amountpaid>0 then f.amountpaid else 0 end )) as Total
from kaveri.documentmaster d  
left join kaveri.feesrequired f on f.applicationnumber=d.applicationnumber  
left join kaveri.sromaster sm on d.srocode = sm.srocode 
left join kaveri.districtmaster dm on sm.districtcode = dm.districtcode 
where d.registrationdatetime::date >= _from_date and d.registrationdatetime::date <= _to_date 
and d.isregistrationcompleted = true  and f.feerulecode in (36,58,59)
group by Monthname,Sronamee,Districtnamee,sm.srocode 
having sum(f.amountpaid) >= _minval and sum(f.amountpaid) <= _maxval;

elseif _amount_type = 4 then -- Scanningfees

	return query
	
select distinct dm.districtnamee as Districtname,sm.sronamee as sroname,to_char(d.registrationdatetime, 'month') as Monthname, 
count(distinct d.documentid) as numberofdocuments,
sum(case when f.feerulecode=1 then f.amountpaid else 0 end) as RegistrationFees, 
sum(case when f.feerulecode in (36,58,59) then f.amountpaid else 0 end)as StampDuty, 
sum(case when f.feerulecode=2 then f.amountpaid else 0 end) as Scanningfees, 
sum(case when f.feerulecode not in (1,36,2,58,59)  and  f.amountpaid>0 then f.amountpaid else 0 end ) as otherfees, 
(sum(case when f.feerulecode=1 then f.amountpaid else 0 end)+ 
sum(case when f.feerulecode in (36,58,59) then f.amountpaid else 0 end)+ 
sum(case when f.feerulecode=2 then f.amountpaid else 0 end)+ 
sum(case when f.feerulecode not in (1,36,2,58,59)  and  f.amountpaid>0 then f.amountpaid else 0 end )) as Total
from kaveri.documentmaster d  
left join kaveri.feesrequired f on f.applicationnumber=d.applicationnumber  
left join kaveri.sromaster sm on d.srocode = sm.srocode 
left join kaveri.districtmaster dm on sm.districtcode = dm.districtcode 
where d.registrationdatetime::date >= _from_date and d.registrationdatetime::date <= _to_date 
and d.isregistrationcompleted = true  and f.feerulecode in (2)
group by Monthname,Sronamee,Districtnamee,sm.srocode 
having sum(f.amountpaid) >= _minval and sum(f.amountpaid) <= _maxval;

	
elseif _amount_type = 5 then -- otherfees

	return query	
	
select distinct dm.districtnamee as Districtname,sm.sronamee as sroname,to_char(d.registrationdatetime, 'month') as Monthname, 
count(distinct d.documentid) as numberofdocuments,
sum(case when f.feerulecode=1 then f.amountpaid else 0 end) as RegistrationFees, 
sum(case when f.feerulecode in (36,58,59) then f.amountpaid else 0 end)as StampDuty, 
sum(case when f.feerulecode=2 then f.amountpaid else 0 end) as Scanningfees, 
sum(case when f.feerulecode not in (1,36,2,58,59)  and  f.amountpaid>0 then f.amountpaid else 0 end ) as otherfees, 
(sum(case when f.feerulecode=1 then f.amountpaid else 0 end)+ 
