--

CREATE FUNCTION kaverimis.fn_mis_revenue_report_form_fin_19_optimization(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _amount_type integer DEFAULT NULL::integer, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, monthname text, numberofdocuments bigint, registrationfees numeric, stampduty numeric, scanningfees numeric, otherfees numeric, total numeric)
    LANGUAGE plpgsql
    AS $$


declare

PageOffset INTEGER := 0;

	begin
		
		--PageOffset := ((pagenumber - 1) * pagesize);
		PageOffset := (pagesize*pagenumber) - pagesize;
		
		return query
		
		select distinct dm.districtnamee as Districtname,sm.sronamee as sroname,to_char(d.registrationdatetime, 'month') as Monthname, 
	count(distinct d.documentid) as numberofdocuments,
	sum(case when f.feerulecode=1 then f.amountpaid else 0 end) as RegistrationFees, 
	sum(case when f.feerulecode in (36,58,59) then f.amountpaid else 0 end)as StampDuty, 
	sum(case when f.feerulecode=2 then f.amountpaid else 0 end) as Scanningfees, 
	sum(case when f.feerulecode not in (1,36,2,58,59)  and  f.amountpaid>0 then f.amountpaid else 0 end ) as otherfees, 
	(sum(case when f.feerulecode=1 then f.amountpaid else 0 end)+ 
	sum(case when f.feerulecode in (36,58,59) then f.amountpaid else 0 end)+ 
	sum(case when f.feerulecode=2 then f.amountpaid else 0 end)+ 
	sum(case when f.feerulecode not in (1,36,2,58,59)  and  f.amountpaid>0 then f.amountpaid else 0 end )) as Total

	from kaveri.documentmaster d  

	left join kaveri.feesrequired f on f.applicationnumber=d.applicationnumber  

	left join kaveri.sromaster sm on d.srocode = sm.srocode 

	left join kaveri.districtmaster dm on sm.districtcode = dm.districtcode 

	where d.registrationdatetime::date >= _from_date and d.registrationdatetime::date <= _to_date 

	and d.isregistrationcompleted = true  


	and (CASE   
          WHEN _amount_type <> 1 and _amount_type <> 2 and _amount_type <> 3 and _amount_type <> 4 and _amount_type <> 5 then true 
							
          ELSE 
                                
			(case   
			     WHEN _amount_type = 3 THEN f.feerulecode in (36,58,59) 
			     WHEN _amount_type = 2 THEN f.feerulecode in (1)
			     WHEN _amount_type = 4 THEN f.feerulecode in (2) 
			     WHEN _amount_type = 5 THEN f.feerulecode  not in (1,2,36,58,59)
			     ELSE  TRUE
			end)
							
      end)

   and (case
		 when _districtcode <> 0 then dm.districtcode=_districtcode 
		 else
		 	true
	end)				

  and (case
		 when _srocode<>0 then d.srocode=_srocode
		 else 
		 	true
	end)				
  group by Monthname,Sronamee,Districtnamee,sm.srocode 
  having 
				
				(case   
			                                WHEN _minval is not null and _maxval is not null then
				                                sum(f.amountpaid)>=_minval and sum(f.amountpaid)<=_maxval
			                                ELSE 
			                                	true 
			                                    
				end)
				
	limit pagesize offset PageOffset;

	END;
$$;


ALTER FUNCTION kaverimis.fn_mis_revenue_report_form_fin_19_optimization(_districtcode integer, _srocode integer, _from_date timestamp without time zone, _to_date timestamp without time zone, _amount_type integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_revenue_saledeed_fy(bigint, integer, integer, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_revenue_saledeed_fy(_srocode bigint, _propertytypeid integer, _valuationflag integer, _finyear character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(monyear text, applicationnumber_cnt bigint, registrationfees numeric, stampduty numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize); 		
if _valuationflag = 0 then
return query 
select 
	to_char(dm.registrationdatetime, 'Mon-yyyy') as monYear,
    count(dm.applicationnumber) as applicationnumber_cnt,
    sum(rf.amountpaid) as RegistrationFees,
    sum(s.amountpaid) as StampDuty
from kaveri.documentmaster dm
join (select applicationnumber, amountpaid from kaveri.feesrequired fr where fr.feerulecode=1) rf ON dm.applicationnumber=rf.applicationnumber
join (select applicationnumber, amountpaid from kaveri.feesrequired fr where fr.feerulecode=36) s ON dm.applicationnumber=s.applicationnumber
join kaveri.propertymaster pm on dm.documentid=pm.documentid
where dm.isregistrationcompleted = true --and fr.amountpaid is not null
and dm.srocode=_srocode and dm.regarticlecode=106 and pm.marketvalue<=1000000 and pm.propertytypeid=_propertytypeid
and dm.registrationdatetime::date>=(to_date(substr(_finyear, 1, strpos(_finyear, '-')-1), 'YYYY-MM-DD') + interval '3 month')::date
and dm.registrationdatetime::date<=(to_date(substr(_finyear, 1, strpos(_finyear, '-')-1), 'YYYY-MM-DD') + interval '14 month' + interval '30 days')::date
group by dm.srocode, to_char(dm.registrationdatetime, 'Mon-yyyy');
else
return query 
select 
	to_char(dm.registrationdatetime, 'Mon-yyyy') as monYear,
    count(dm.applicationnumber) as applicationnumber_cnt,
    sum(rf.amountpaid) as RegistrationFees,
    sum(s.amountpaid) as StampDuty
from kaveri.documentmaster dm
join (select applicationnumber, amountpaid from kaveri.feesrequired fr where fr.feerulecode=1) rf ON dm.applicationnumber=rf.applicationnumber
join (select applicationnumber, amountpaid from kaveri.feesrequired fr where fr.feerulecode=36) s ON dm.applicationnumber=s.applicationnumber
join kaveri.propertymaster pm on dm.documentid=pm.documentid
where dm.isregistrationcompleted = true --and fr.amountpaid is not null
and dm.srocode=_srocode and dm.regarticlecode=106 and pm.marketvalue>1000000 and pm.propertytypeid=_propertytypeid
and dm.registrationdatetime::date>=(to_date(substr(_finyear, 1, strpos(_finyear, '-')-1), 'YYYY-MM-DD') + interval '3 month')::date
and dm.registrationdatetime::date<=(to_date(substr(_finyear, 1, strpos(_finyear, '-')-1), 'YYYY-MM-DD') + interval '14 month' + interval '30 days')::date
group by dm.srocode, to_char(dm.registrationdatetime, 'Mon-yyyy');
end if;

END;
$$;


ALTER FUNCTION kaverimis.fn_mis_revenue_saledeed_fy(_srocode bigint, _propertytypeid integer, _valuationflag integer, _finyear character varying, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_scannedfileuploadstatusreport_dro(integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_scannedfileuploadstatusreport_dro(_districtcode integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(district character varying, registrationmodule character varying, nooffiles bigint, filesize numeric, lastuploaddatetime timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize); 		
if (_districtcode = 0) then
return query
select distinct b.districtnamee as district,
e.servicename as registrationmodule,count(f.filename) nooffiles,sum(f.filesize) as FileSize,
max(c.lstupddate) as lastuploaddatetime
from kaveri.sromaster a left join kaveri.districtmaster b on a.districtcode = b.districtcode
left join kaveri.documentmaster c on a.srocode = c.srocode
left join kaveri.referencemaster d on d.documentid = d.documentid
left join kaveri.servicesmaster e on d.documenttypeid = e.serviceid
left join kaveri.scanmaster f on c.documentid = f.documentid
group by a.districtcode,b.districtnamee,a.srocode,a.sronamee,
d.documenttypeid,e.servicename limit 10;
else
return query
select distinct b.districtnamee as district,
e.servicename as registrationmodule,count(f.filename) nooffiles,sum(f.filesize) as FileSize,
max(c.lstupddate) as lastuploaddatetime
from kaveri.sromaster a left join kaveri.districtmaster b on a.districtcode = b.districtcode
left join kaveri.documentmaster c on a.srocode = c.srocode
left join kaveri.referencemaster d on d.documentid = d.documentid
left join kaveri.servicesmaster e on d.documenttypeid = e.serviceid
left join kaveri.scanmaster f on c.documentid = f.documentid
where a.districtcode = _districtcode 
group by a.districtcode,b.districtnamee,a.srocode,a.sronamee,
d.documenttypeid,e.servicename;
end if;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_scannedfileuploadstatusreport_dro(_districtcode integer, pagenumber integer, pagesize integer) OWNER TO csgadmin;

