-- Name: fn_mis_scannedfileuploadstatusreport_sro(integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_scannedfileuploadstatusreport_sro(_districtcode integer, _srocode integer, _documenttype integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(sro character varying, registrationmodule character varying, nooffiles bigint, filesize numeric, lastuploaddatetime timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize); 	
if ((_districtcode = 0) and (_srocode = 0)) then
return query
select distinct a.sronamee as sro,
e.servicename as registrationmodule,count(f.filename) nooffiles,sum(f.filesize) as FileSize,
max(c.lstupddate) as lastuploaddatetime
from kaveri.sromaster a left join kaveri.districtmaster b on a.districtcode = b.districtcode
left join kaveri.documentmaster c on a.srocode = c.srocode
left join kaveri.referencemaster d on d.documentid = d.documentid
left join kaveri.servicesmaster e on d.documenttypeid = e.serviceid
left join kaveri.scanmaster f on c.documentid = f.documentid
where  d.documenttypeid = _documenttype
group by a.districtcode,b.districtnamee,a.srocode,a.sronamee,
d.documenttypeid,e.servicename;
elsif (_srocode = 0) then
return query
select distinct a.sronamee as sro,
e.servicename as registrationmodule,count(f.filename) nooffiles,sum(f.filesize) as FileSize,
max(c.lstupddate) as lastuploaddatetime
from kaveri.sromaster a left join kaveri.districtmaster b on a.districtcode = b.districtcode
left join kaveri.documentmaster c on a.srocode = c.srocode
left join kaveri.referencemaster d on d.documentid = d.documentid
left join kaveri.servicesmaster e on d.documenttypeid = e.serviceid
left join kaveri.scanmaster f on c.documentid = f.documentid
where a.districtcode = _districtcode  and d.documenttypeid = _documenttype
group by a.districtcode,b.districtnamee,a.srocode,a.sronamee,
d.documenttypeid,e.servicename;
elsif (_districtcode=0) then
return query
select distinct a.sronamee as sro,
e.servicename as registrationmodule,count(f.filename) nooffiles,sum(f.filesize) as FileSize,
max(c.lstupddate) as lastuploaddatetime
from kaveri.sromaster a left join kaveri.districtmaster b on a.districtcode = b.districtcode
left join kaveri.documentmaster c on a.srocode = c.srocode
left join kaveri.referencemaster d on d.documentid = d.documentid
left join kaveri.servicesmaster e on d.documenttypeid = e.serviceid
left join kaveri.scanmaster f on c.documentid = f.documentid
where  a.srocode = _srocode and d.documenttypeid = _documenttype
group by a.districtcode,b.districtnamee,a.srocode,a.sronamee,
d.documenttypeid,e.servicename;
else
return query
select distinct a.sronamee as sro,
e.servicename as registrationmodule,count(f.filename) nooffiles,sum(f.filesize) as FileSize,
max(c.lstupddate) as lastuploaddatetime
from kaveri.sromaster a left join kaveri.districtmaster b on a.districtcode = b.districtcode
left join kaveri.documentmaster c on a.srocode = c.srocode
left join kaveri.referencemaster d on d.documentid = d.documentid
left join kaveri.servicesmaster e on d.documenttypeid = e.serviceid
left join kaveri.scanmaster f on c.documentid = f.documentid
where a.districtcode = _districtcode and a.srocode = _srocode and d.documenttypeid = _documenttype
group by a.districtcode,b.districtnamee,a.srocode,a.sronamee,
d.documenttypeid,e.servicename;
end if;
END;
$$;


