CREATE FUNCTION kaverimis.fn_mis_select_distsrocode(v_districtnamee integer) RETURNS json
    LANGUAGE plpgsql PARALLEL SAFE
    AS $$

declare 
v_data_json json;

BEGIN

select row_to_json(dro) into v_data_json
from (

select dm.districtnamee, sm.sronamee
