--
-- Name: fn_mis_sro_doc_cash_coll(bigint, date, date, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_sro_doc_cash_coll(_srocode bigint, _fromdate date, _todate date, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(sroname character varying, documentnumber integer, finalregistrationnumber character varying, presentdatetime date, receiptid bigint, registrationfees numeric, stampduty numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize); 	
return query 
	select 
		s.sronamee,
		dm.documentnumber,
		dm.finalregistrationnumber,
		dm.presentdatetime::date,
		pay.receiptid,
		sum(case when f.feerulecode=1  then f.amountpaid else 0 end) as RegistrationFees,
		sum(case when f.feerulecode=36  then f.amountpaid else 0 end)as StampDuty
	from kaveri.documentmaster dm
	join kaveri.sromaster s on dm.srocode = s.srocode 
	join kaveri.feesrequired f on f.documentid = dm.documentid 
	join kaveri.feesrulemaster fr on fr.feerulecode = f.feerulecode 
	left join kaveri.ams_reg_epaymenttransdetails pay on dm.applicationnumber = pay.applicationnumber and dm.srocode = pay.officeid 
	where dm.srocode=_srocode and dm.isregistrationcompleted =true
	and dm.presentdatetime::date >= _fromDate and dm.presentdatetime::date < _toDate
	group by s.sronamee, dm.documentnumber, dm.finalregistrationnumber, dm.presentdatetime::date, pay.receiptid;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_sro_doc_cash_coll(_srocode bigint, _fromdate date, _todate date, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_stat_2b_details_of_trust_registered(integer, integer, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_stat_2b_details_of_trust_registered(_districtcode integer, _srocode integer, _prev_fromdate timestamp without time zone, _prev_todate timestamp without time zone, _current_fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _current_todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(drname character varying, nameofsubregistrationoffice character varying, trust_cnt_lessthanmonth bigint, trust_stampduty_lessthanmonth numeric, trust_registrationfees_lessthanmonth numeric, trust_scanningfees_lessthanmonth numeric, trust_otherfees_lessthanmonth numeric, trust_totalfees_lessthanmonth numeric, trust_cnt_inthemonth bigint, trust_stampduty_inthemonth numeric, trust_registrationfees_inthemonth numeric, trust_scanningfees_inthemonth numeric, trust_otherfees_inthemonth numeric, trust_totalfees_inthemonth numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

	DECLARE
	PageOffset INTEGER := 0;
    
	BEGIN	
	PageOffset := ((pagenumber - 1) * pagesize);

if (pagenumber=1) then

			return query
			with cte as (select distinct b.districtnamee as drname,
			sronamee as nameofsubregistrationoffice,
			trust_lessthanmonth.documentcount,
			trust_lessthanmonth.stampduty,
			trust_lessthanmonth.registrationfee,
			trust_lessthanmonth.scanningfees,
			trust_lessthanmonth.otherfees,
			trust_lessthanmonth.totalfees,
			trust_inthemonth.documentcount,
			trust_inthemonth.stampduty,
			trust_inthemonth.registrationfee,
			trust_inthemonth.scanningfees,
			trust_inthemonth.otherfees,
			trust_inthemonth.totalfees
			

			from kaveri.sromaster a 
			join kaveri.districtmaster b on a.districtcode = b.districtcode 
						
			left outer join 

			(
				select * from kaverimis.fn_mis_stat_form2a_data
					(_districtcode ,_srocode ,56,_prev_fromdate,_prev_todate ,_amounttype ,_minval ,_maxval)
				
			)as trust_lessthanmonth on a.srocode = trust_lessthanmonth.srocode
			 
			left outer join 

			(select * from kaverimis.fn_mis_stat_form2a_data
					(_districtcode ,_srocode ,56,_prev_fromdate,_prev_todate ,_amounttype ,_minval ,_maxval))
					as trust_inthemonth on a.srocode = trust_inthemonth.srocode

			
			where trust_lessthanmonth.documentcount is not null or 
			trust_inthemonth.documentcount is not null ),
			cte_count as (select count(*) as total_rows from cte)
			select * from cte
			join (select total_rows from cte_count) total_row on true 
			order by cte.drname asc,cte.nameofsubregistrationoffice asc
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
			
elsif (pagenumber>1) then 
	
				return query
			with cte as (select distinct b.districtnamee as drname,
			sronamee as nameofsubregistrationoffice,
			trust_lessthanmonth.documentcount,
			trust_lessthanmonth.stampduty,
			trust_lessthanmonth.registrationfee,
			trust_lessthanmonth.scanningfees,
			trust_lessthanmonth.otherfees,
			trust_lessthanmonth.totalfees,
			trust_inthemonth.documentcount,
			trust_inthemonth.stampduty,
			trust_inthemonth.registrationfee,
			trust_inthemonth.scanningfees,
			trust_inthemonth.otherfees,
			trust_inthemonth.totalfees
			

			from kaveri.sromaster a 
			join kaveri.districtmaster b on a.districtcode = b.districtcode 
						
			left outer join 

			(
				select * from kaverimis.fn_mis_stat_form2a_data
					(_districtcode ,_srocode ,56,_prev_fromdate,_prev_todate ,_amounttype ,_minval ,_maxval)
				
			)as trust_lessthanmonth on a.srocode = trust_lessthanmonth.srocode
			 
			left outer join 

			(select * from kaverimis.fn_mis_stat_form2a_data
					(_districtcode ,_srocode ,56,_prev_fromdate,_prev_todate ,_amounttype ,_minval ,_maxval))
					as trust_inthemonth on a.srocode = trust_inthemonth.srocode

			
			where trust_lessthanmonth.documentcount is not null or 
			trust_inthemonth.documentcount is not null )
			
			select *,null::bigint as total_row from cte
			order by cte.drname asc,cte.nameofsubregistrationoffice asc
			OFFSET PageOffset
			FETCH NEXT pagesize ROWS ONLY	;
			

elsif (pagenumber=-1 or pagesize=-1) then

			return query
			with cte as (select distinct b.districtnamee as drname,
			sronamee as nameofsubregistrationoffice,
			trust_lessthanmonth.documentcount,
			trust_lessthanmonth.stampduty,
			trust_lessthanmonth.registrationfee,
			trust_lessthanmonth.scanningfees,
			trust_lessthanmonth.otherfees,
			trust_lessthanmonth.totalfees,
			trust_inthemonth.documentcount,
			trust_inthemonth.stampduty,
			trust_inthemonth.registrationfee,
			trust_inthemonth.scanningfees,
			trust_inthemonth.otherfees,
			trust_inthemonth.totalfees
			

			from kaveri.sromaster a 
			join kaveri.districtmaster b on a.districtcode = b.districtcode 
						
			left outer join 

			(
				select * from kaverimis.fn_mis_stat_form2a_data
					(_districtcode ,_srocode ,56,_prev_fromdate,_prev_todate ,_amounttype ,_minval ,_maxval)
				
			)as trust_lessthanmonth on a.srocode = trust_lessthanmonth.srocode
			 
			left outer join 

			(select * from kaverimis.fn_mis_stat_form2a_data
					(_districtcode ,_srocode ,56,_prev_fromdate,_prev_todate ,_amounttype ,_minval ,_maxval))
					as trust_inthemonth on a.srocode = trust_inthemonth.srocode

			
			where trust_lessthanmonth.documentcount is not null or 
			trust_inthemonth.documentcount is not null )
			
			select *,null::bigint as total_row from cte 
		 order by cte.drname asc,cte.nameofsubregistrationoffice asc;

end if;
	
	
	   
			
			
			
		
			
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_stat_2b_details_of_trust_registered(_districtcode integer, _srocode integer, _prev_fromdate timestamp without time zone, _prev_todate timestamp without time zone, _current_fromdate timestamp without time zone, _current_todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_stat_2c_details_of_adoption_registered(integer, integer, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_stat_2c_details_of_adoption_registered(_districtcode integer, _srocode integer, _prev_fromdate timestamp without time zone, _prev_todate timestamp without time zone, _current_fromdate timestamp without time zone DEFAULT NULL::timestamp without time zone, _current_todate timestamp without time zone DEFAULT NULL::timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(drname character varying, nameofsubregistrationoffice character varying, adoption_cnt_lessthanmonth bigint, adoption_stampduty_lessthanmonth numeric, adoption_registrationfees_lessthanmonth numeric, adoption_scanningfees_lessthanmonth numeric, adoption_otherfees_lessthanmonth numeric, adoption_totalfees_lessthanmonth numeric, adoption_cnt_inthemonth bigint, adoption_stampduty_inthemonth numeric, adoption_registrationfees_inthemonth numeric, adoption_scanningfees_inthemonth numeric, adoption_otherfees_inthemonth numeric, adoption_totalfees_inthemonth numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

	DECLARE
	PageOffset INTEGER := 0;
    
	BEGIN	
	PageOffset := ((pagenumber - 1) * pagesize);

if (pagenumber=1) then

			return query
			with cte as (select distinct b.districtnamee as drname,
			sronamee as nameofsubregistrationoffice,
			adoption_lessthanmonth.documentcount,
			adoption_lessthanmonth.stampduty,
			adoption_lessthanmonth.registrationfee,
			adoption_lessthanmonth.scanningfees,
			adoption_lessthanmonth.otherfees,
			adoption_lessthanmonth.totalfees,
			adoption_inthemonth.documentcount,
			adoption_inthemonth.stampduty,
			adoption_inthemonth.registrationfee,
			adoption_inthemonth.scanningfees,
			adoption_inthemonth.otherfees,
			adoption_inthemonth.totalfees
			

			from kaveri.sromaster a 
			join kaveri.districtmaster b on a.districtcode = b.districtcode 
						
			left outer join 

			(
				select * from kaverimis.fn_mis_stat_form2a_data
					(_districtcode ,_srocode ,3,_prev_fromdate,_prev_todate ,_amounttype ,_minval ,_maxval)
				
			)as adoption_lessthanmonth on a.srocode = adoption_lessthanmonth.srocode
			 
			left outer join 

			(select * from kaverimis.fn_mis_stat_form2a_data
					(_districtcode ,_srocode ,3,_prev_fromdate,_prev_todate ,_amounttype ,_minval ,_maxval))
					as adoption_inthemonth on a.srocode = adoption_inthemonth.srocode

			
			where adoption_lessthanmonth.documentcount is not null or 
			adoption_inthemonth.documentcount is not null ),
			cte_count as (select count(*) as total_rows from cte)
			select * from cte
			join (select total_rows from cte_count) total_row on true 
			order by cte.drname asc,cte.nameofsubregistrationoffice asc
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
			
elsif (pagenumber>1) then 
	
				return query
			with cte as (select distinct b.districtnamee as drname,
			sronamee as nameofsubregistrationoffice,
			adoption_lessthanmonth.documentcount,
			adoption_lessthanmonth.stampduty,
			adoption_lessthanmonth.registrationfee,
			adoption_lessthanmonth.scanningfees,
			adoption_lessthanmonth.otherfees,
			adoption_lessthanmonth.totalfees,
			adoption_inthemonth.documentcount,
			adoption_inthemonth.stampduty,
			adoption_inthemonth.registrationfee,
			adoption_inthemonth.scanningfees,
			adoption_inthemonth.otherfees,
			adoption_inthemonth.totalfees
			

			from kaveri.sromaster a 
			join kaveri.districtmaster b on a.districtcode = b.districtcode 
						
			left outer join 

			(
				select * from kaverimis.fn_mis_stat_form2a_data
					(_districtcode ,_srocode ,3,_prev_fromdate,_prev_todate ,_amounttype ,_minval ,_maxval)
				
			)as adoption_lessthanmonth on a.srocode = adoption_lessthanmonth.srocode
			 
			left outer join 

			(select * from kaverimis.fn_mis_stat_form2a_data
					(_districtcode ,_srocode ,3,_prev_fromdate,_prev_todate ,_amounttype ,_minval ,_maxval))
					as adoption_inthemonth on a.srocode = adoption_inthemonth.srocode

			
			where adoption_lessthanmonth.documentcount is not null or 
			adoption_inthemonth.documentcount is not null )
			
			select *,null::bigint as total_row from cte
			order by cte.drname asc,cte.nameofsubregistrationoffice asc
			OFFSET PageOffset
			FETCH NEXT pagesize ROWS ONLY	;
			

elsif (pagenumber=-1 or pagesize=-1) then

			return query
			with cte as (select distinct b.districtnamee as drname,
			sronamee as nameofsubregistrationoffice,
			adoption_lessthanmonth.documentcount,
			adoption_lessthanmonth.stampduty,
			adoption_lessthanmonth.registrationfee,
			adoption_lessthanmonth.scanningfees,
			adoption_lessthanmonth.otherfees,
			adoption_lessthanmonth.totalfees,
			adoption_inthemonth.documentcount,
			adoption_inthemonth.stampduty,
			adoption_inthemonth.registrationfee,
			adoption_inthemonth.scanningfees,
			adoption_inthemonth.otherfees,
			adoption_inthemonth.totalfees
			

			from kaveri.sromaster a 
			join kaveri.districtmaster b on a.districtcode = b.districtcode 
						
			left outer join 

			(
				select * from kaverimis.fn_mis_stat_form2a_data
					(_districtcode ,_srocode ,3,_prev_fromdate,_prev_todate ,_amounttype ,_minval ,_maxval)
				
			)as adoption_lessthanmonth on a.srocode = adoption_lessthanmonth.srocode
			 
			left outer join 

			(select * from kaverimis.fn_mis_stat_form2a_data
					(_districtcode ,_srocode ,3,_prev_fromdate,_prev_todate ,_amounttype ,_minval ,_maxval))
					as adoption_inthemonth on a.srocode = adoption_inthemonth.srocode

			
			where adoption_lessthanmonth.documentcount is not null or 
			adoption_inthemonth.documentcount is not null )
			
			select *,null::bigint as total_row from cte 
		 order by cte.drname asc,cte.nameofsubregistrationoffice asc;

end if;
	
	
	   
			
			
			
		
			
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_stat_2c_details_of_adoption_registered(_districtcode integer, _srocode integer, _prev_fromdate timestamp without time zone, _prev_todate timestamp without time zone, _current_fromdate timestamp without time zone, _current_todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_stat_form2a_data(integer, integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_stat_form2a_data(_districtcode integer, _srocode integer, _stamparticlecode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::integer, _maxval integer DEFAULT NULL::integer) RETURNS TABLE(districtcode bigint, srocode bigint, documentcount bigint, stampduty numeric, registrationfee numeric, scanningfees numeric, otherfees numeric, totalfees numeric)
    LANGUAGE plpgsql
    AS $$

Begin

		return query 
		
		with a as (select distinct 
			 dsm.districtcode,a.srocode,a.applicationnumber
			
			from kaveri.documentmaster a 
			JOIN kaveri.applicantapplicationdetails aad ON a.applicationnumber=aad.applicationnumber
			left JOIN kaveri.feesrequired fr ON a.applicationnumber=fr.applicationnumber
			JOIN kaveri.sromaster sm ON a.srocode = sm.srocode
			JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode
		    join kaveri.propertymaster pm  on a.applicationnumber=pm.applicationnumber 
		    		   
		    		
			where  
			(a.registrationdatetime between _fromdate  and 
			_todate ::timestamp + INTERVAL '1 day')
			and a.isregistrationcompleted = true 
			--and aad.currentstatus='CD120'
			and		pm.stamparticlecode=_stamparticlecode
					
			and (case  when _districtcode<>0 then dsm.districtcode=_districtcode  ELSE  true end)
			and (case  when _srocode<> 0 then sm.srocode=_srocode  ELSE  true end)
			group by a.srocode,dsm.districtcode,a.applicationnumber
			),
			b as (
			  
			 select distinct a.districtcode,a.srocode,f.applicationnumber  from 
			 a
			 left join  kaveri.feesrequired f on a.applicationnumber=f.applicationnumber
			 where 
			 (case

		                    when _amounttype=1 then true   --Total
		                                    
		                    when _amounttype=2 then  f.feerulecode in (36,58,59,104,89,88)  --stamp duty
		                    
		                    when _amounttype=3 then  f.feerulecode in  (1)  -- registrationfee
		                    
		                    when _amounttype=4 then  f.feerulecode in  (2)  -- Scanning fees
		                    
		                    when _amounttype=5 then  f.feerulecode  not in  (1,2,36,58,59,104,89,88)  -- Other fees
		                   
		
		                    else     true --amounttype null

                                                

  					 end)
			 
			 group by a.districtcode,a.srocode,f.applicationnumber 
			 having 
				(case
					when _amounttype in (1,2,3,4,5) then sum(f.amountpaid) >= _minval 
					and sum(f.amountpaid) <= _maxval
                                        
                    ELSE          true                                               

                end )
			
			
			)
			
			select 
			b.districtcode::bigint,b.srocode::bigint,count(distinct b.applicationnumber),
			sum(case when f.feerulecode in (36,58,59,104,89,88) then
			f.amountpaid  else 0 end) as stampduty,
			sum(case when f.feerulecode in (1) then	f.amountpaid  else 0 end)
			as registrationfee,
			sum(case when f.feerulecode in (2) then	f.amountpaid  else 0 end)
			as scanningfees,
			sum(case when f.feerulecode not in (1,2,36,58,59,104,89,88)  then	f.amountpaid  else 0 end)
			as otherfees,
			sum(f.amountpaid )
			as Total
			
			
			
			from 
			b 
			left join kaveri.feesrequired f on b.applicationnumber=f.applicationnumber 
			group by b.districtcode,b.srocode;
			

END;
$$;


ALTER FUNCTION kaverimis.fn_mis_stat_form2a_data(_districtcode integer, _srocode integer, _stamparticlecode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer) OWNER TO postgres;

--
-- Name: fn_mis_statistical_form10_cc(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
