CREATE FUNCTION kaverimis.fn_mis_statistical_form10_cc(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtnamee character varying, sronamee character varying, receiptnumber integer, paymentmode character varying, challannumber character varying, receiptdate text, sroapplicationnumber character varying, copy_of_doc text, applicantname text, issuedbyoffice character varying, periodofsearch character varying, amount numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$


DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);

if(_districtcode=0)then --All district	
raise notice 'All District';
		return query 
		with cte as (select  distinct
		dsm.districtnamee,
		sr.sronamee as sroname,
		-- r.receiptnumber  as receiptnumber,
		null::integer as receiptnumber,
		'Online'::varchar as modeofpayment,
		epd.deptreferencecode as challannumber,
		--to_char(r.dateofreceipt, 'DD-MM-YYYY') as receiptdate,
		to_char(bk.transactiontimestamp,'DD-MM-YYYY')  as receiptdate,
		cca.applicationnumber  as sroapplicationnumber,
		cca.signedform22 as copy_of_doc,
		concat_ws(' ',c.firstname,c.middlename,c.lastname) as Applicantname,
		sr.sronamee as Issuedbyofficename,
		cca.yearofregistration  as periodofsearch,
		cca.totalamount as amount
		from kaveri.cc_applicationdetails cca 
		join kaveri.applicantapplicationdetails a on cca.applicationnumber = a.applicationnumber
		left join kaveri.ams_reg_epaymenttransdetails epd on epd.ccid=cca.ccid -- epd.applicationnumber = cca.applicationnumber
		join kaveri.citizenmaster c on cca.submittedby=c.citizenid 
		join kaveri.sromaster sr on cca.kaverisrocode= sr.srocode
		join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
		--left join kaveri.receiptmaster r on epd.receiptid=epd.receiptid
		join kaveri.ams_reg_epaymentbankackdetails bk on epd.deptreferencecode =bk.deptreferencecode
		where a.currentstatus ='CC109' and  bk.paymentstatuscode='10700066' and 
		 (cca.submitteddatetime between _fromdate
		and  _todate)),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		

elsif(_srocode=0)THEN

		return query 

		with cte as (select  distinct
		dsm.districtnamee,
		sr.sronamee as sroname,
		-- r.receiptnumber  as receiptnumber,
		null::integer as receiptnumber,
		'Online'::varchar as modeofpayment,
		epd.deptreferencecode as challannumber,
		--to_char(r.dateofreceipt, 'DD-MM-YYYY') as receiptdate,
		to_char(bk.transactiontimestamp,'DD-MM-YYYY')  as receiptdate,
		cca.applicationnumber  as sroapplicationnumber,
		cca.signedform22 as copy_of_doc,
		concat_ws(' ',c.firstname,c.middlename,c.lastname) as Applicantname,
		sr.sronamee as Issuedbyofficename,
		cca.yearofregistration  as periodofsearch,
		cca.totalamount as amount
		from kaveri.cc_applicationdetails cca 
		join kaveri.applicantapplicationdetails a on cca.applicationnumber = a.applicationnumber
		left join kaveri.ams_reg_epaymenttransdetails epd on epd.ccid=cca.ccid -- epd.applicationnumber = cca.applicationnumber
		join kaveri.citizenmaster c on cca.submittedby=c.citizenid 
		join kaveri.sromaster sr on cca.kaverisrocode= sr.srocode
		join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
		--left join kaveri.receiptmaster r on epd.receiptid=epd.receiptid
		join kaveri.ams_reg_epaymentbankackdetails bk on epd.deptreferencecode =bk.deptreferencecode
		where a.currentstatus ='CC109' and  bk.paymentstatuscode='10700066' and 
		 (cca.submitteddatetime between _fromdate
		and  _todate) and dsm.districtcode=_districtcode),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

else
		return query
		
		with cte as (select  distinct
		dsm.districtnamee,
		sr.sronamee as sroname,
		-- r.receiptnumber  as receiptnumber,
		null::integer as receiptnumber,
		'Online'::varchar as modeofpayment,
		epd.deptreferencecode as challannumber,
		--to_char(r.dateofreceipt, 'DD-MM-YYYY') as receiptdate,
		to_char(bk.transactiontimestamp,'DD-MM-YYYY')  as receiptdate,
		cca.applicationnumber  as sroapplicationnumber,
		cca.signedform22 as copy_of_doc,
		concat_ws(' ',c.firstname,c.middlename,c.lastname) as Applicantname,
		sr.sronamee as Issuedbyofficename,
		cca.yearofregistration  as periodofsearch,
		cca.totalamount as amount
		from kaveri.cc_applicationdetails cca 
		join kaveri.applicantapplicationdetails a on cca.applicationnumber = a.applicationnumber
		left join kaveri.ams_reg_epaymenttransdetails epd on epd.ccid=cca.ccid -- epd.applicationnumber = cca.applicationnumber
		join kaveri.citizenmaster c on cca.submittedby=c.citizenid 
		join kaveri.sromaster sr on cca.kaverisrocode= sr.srocode
		join kaveri.districtmaster dsm on sr.districtcode = dsm.districtcode
		--left join kaveri.receiptmaster r on epd.receiptid=epd.receiptid
		join kaveri.ams_reg_epaymentbankackdetails bk on epd.deptreferencecode =bk.deptreferencecode
		where a.currentstatus ='CC109' and  bk.paymentstatuscode='10700066' and 
		 (cca.submitteddatetime between _fromdate
		and  _todate) and  
		cca.kaverisrocode=_srocode ),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
		
		
		
	end if;

 
END;
$$;


