    sum(pm.sromarketvalue) AS marketvalue,
    sum(pm.sroconsideration) AS consideration
   FROM kaveri.documentmaster dm
      JOIN kaveri.propertymaster pm ON dm.documentid = pm.documentid
      JOIN kaveri.propertyschedules ps ON pm.propertyid = ps.propertyid
     JOIN ( SELECT vw.applicationnumber,
            string_agg(DISTINCT vw.name, ', '::text) AS executants
           FROM kaverimis.vw_mis_partyinfo vw
          WHERE vw.partytypeid = 2
          GROUP BY vw.applicationnumber) prt_ex ON prt_ex.applicationnumber::text = dm.applicationnumber::text
      JOIN ( SELECT vw.applicationnumber,
            string_agg(DISTINCT vw.name, ', '::text) AS claimants
           FROM kaverimis.vw_mis_partyinfo vw
          WHERE vw.partytypeid = 1
          GROUP BY vw.applicationnumber) prt_cl ON prt_cl.applicationnumber::text = dm.applicationnumber::text
      JOIN kaveri.stamparticles sa ON pm.stamparticlecode = sa.stamparticlecode
      JOIN kaveri.villagemaster vm ON pm.villagecode = vm.villagecode
      JOIN kaveri.measunitmaster mum ON pm.unitid = mum.unitid
      JOIN kaveri.sromaster sro ON dm.srocode = sro.srocode
      JOIN kaveri.districtmaster d ON sro.districtcode = d.districtcode
      JOIN kaveri.booktypemaster bt ON dm.bookid = bt.bookid
  WHERE dm.isregistrationcompleted = true and
  dm.registrationdatetime::date>=_fromdate and dm.registrationdatetime::date<=_todate  
  
  GROUP BY  dm.finalregistrationnumber,dm.uploaddocdeedpath, pm.stamparticlecode,d.districtcode,dm.srocode,
   dm.registrationdatetime, prt_ex.executants, sa.articlenamee, prt_cl.claimants 
  having sum(pm.sroconsideration)+sum(pm.sromarketvalue) >=_minval and sum(pm.sroconsideration)+sum(pm.sromarketvalue) <=_maxval 
  OFFSET PageOffset   
FETCH NEXT pagesize ROWS ONLY; 
  
   elseif (_amounttype=2)then --Consideration
   
   raise notice 'All district and amounttype Consideration';
	return query
	SELECT 
	d.districtcode,
	string_agg(DISTINCT d.districtnamee::text, ', '::text) AS droffice,
	dm.srocode,
    string_agg(DISTINCT sro.sronamee::text, ', '::text)::character varying AS srooffice,
    string_agg(DISTINCT bt.booknameenglish::text, ', '::text) AS booktype,
    dm.finalregistrationnumber,
    dm.uploaddocdeedpath  as copy_of_document,
    pm.stamparticlecode,
