    sum(pm.sroconsideration) AS consideration
   FROM (select * from kaveri.documentmaster WHERE isregistrationcompleted = true and
	registrationdatetime::date>=_fromdate and registrationdatetime::date<=_todate  ) dm
     JOIN kaveri.propertymaster pm ON dm.documentid = pm.documentid
     JOIN kaveri.propertyschedules ps ON pm.propertyid = ps.propertyid
     JOIN ( SELECT applicationnumber,
  		 string_agg(distinct concat_ws(' '::text, a.firstname, a.middlename, a.lastname),',') AS executants
           FROM kaveri.partyinfo a
          WHERE a.partytypeid = 2
          GROUP BY  a.applicationnumber) prt_ex ON prt_ex.applicationnumber::text = dm.applicationnumber::text
     JOIN (SELECT applicationnumber,
  		  string_agg(distinct concat_ws(' '::text, a.firstname, a.middlename, a.lastname),',') AS claimants
           FROM kaveri.partyinfo a
          WHERE a.partytypeid = 1
          GROUP BY    a.applicationnumber) prt_cl ON prt_cl.applicationnumber::text = dm.applicationnumber::text
     JOIN kaveri.stamparticles sa ON pm.stamparticlecode = sa.stamparticlecode
     JOIN kaveri.villagemaster vm ON pm.villagecode = vm.villagecode
     JOIN kaveri.measunitmaster mum ON pm.unitid = mum.unitid
     JOIN kaveri.sromaster sro ON dm.srocode = sro.srocode
     JOIN kaveri.districtmaster d ON sro.districtcode = d.districtcode
     JOIN kaveri.booktypemaster bt ON dm.bookid = bt.bookid
 
  GROUP BY  d.districtnamee,  dm.finalregistrationnumber,dm.uploaddocdeedpath, pm.stamparticlecode,d.districtcode,dm.srocode,
   dm.registrationdatetime, prt_ex.executants, sa.articlenamee, prt_cl.claimants,sro.sronamee, bt.booknameenglish
  having sum(pm.sromarketvalue) >=_minval and sum(pm.sromarketvalue) <=_maxval ;
   
   end if;
   
   elseif(_srocode=0) then --Perticular District and All Sro
    
   if (_amounttype=0) then--no amounttype
	raise notice 'All district and no amounttype';
	return query
	SELECT 
	d.districtcode,
	d.districtnamee AS droffice,
	dm.srocode,
    sro.sronamee  AS srooffice,
