   FROM (select * from kaveri.documentmaster WHERE isregistrationcompleted = true and
	registrationdatetime::date>=_fromdate and registrationdatetime::date<=_todate  ) dm
     JOIN kaveri.propertymaster pm ON dm.documentid = pm.documentid
     JOIN kaveri.propertyschedules ps ON pm.propertyid = ps.propertyid
