ALTER FUNCTION kaverimis.fn_mis_statistical_form1_registration_summery_23012024_1(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer) OWNER TO csgadmin;

--
-- Name: fn_mis_statistical_form1_registration_summery_2802(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_statistical_form1_registration_summery_2802(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::bigint, _maxval integer DEFAULT NULL::bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtcode integer, droffice character varying, srocode1 integer, srooffice character varying, booktype character varying, finalregistrationnumber character varying, copy_of_document text, stamparticlecode integer, articlename character varying, registrationdatetime1 text, totalarea text, unit text, propertydetails text, schedule text, executants text, claimants text, villagenamee text, marketvalue numeric, consideration numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

declare 
	PageOffset INTEGER := 0;

	begin
		
		PageOffset := (pagesize*pagenumber) - pagesize;
	
		if (pagenumber<>-1 and pagesize<>-1) then 
		return query

		
		 with cte as (
		SELECT
     d.districtcode,
     d.districtnamee AS droffice,
     dm.srocode,
    sro.sronamee  AS srooffice,
    bt.booknameenglish AS booktype,
    dm.finalregistrationnumber,
    dm.uploaddocdeedpath  as copy_of_document,
    pm.stamparticlecode,
    sa.articlenamee AS articlename,
    to_char(dm.registrationdatetime,'dd-mm-yyyy') as regddatetime,
    string_agg(DISTINCT pm.totalarea::text, ', '::text) AS totalarea,
    string_agg(distinct mum.descriptionenglish::text, ', '::text) AS unit,
    string_agg(DISTINCT  ps.description::text, ', '::text) AS propertydetails,
    string_agg(DISTINCT ps.scheduletype::text, ', '::text) AS schedule,
    string_agg(distinct case when a.partytypeid=2 then
    concat_ws(' '::text, a.firstname, a.middlename, a.lastname) else null end ,',') AS executants,
    string_agg(distinct case when a.partytypeid=1 then
    concat_ws(' '::text, a.firstname, a.middlename, a.lastname) else null end ,',') AS claimants,
    string_agg(DISTINCT vm.villagenamee::text, ', '::text) AS villagenamee,
    sum(pm.sromarketvalue) AS marketvalue,
    sum(pm.sroconsideration) AS consideration
   FROM  kaveri.documentmaster dm
     JOIN kaveri.propertymaster pm ON dm.documentid = pm.documentid
     left JOIN kaveri.propertyschedules ps ON pm.propertyid = ps.propertyid
     JOIN kaveri.partyinfo a on a.applicationnumber=dm.applicationnumber
	 and a.partytypeid in (1,2)
     JOIN kaveri.stamparticles sa ON pm.stamparticlecode = sa.stamparticlecode
     JOIN kaveri.villagemaster vm ON pm.villagecode = vm.villagecode
     JOIN kaveri.measunitmaster mum ON pm.unitid = mum.unitid
     JOIN kaveri.sromaster sro ON dm.srocode = sro.srocode
     JOIN kaveri.districtmaster d ON sro.districtcode = d.districtcode
     JOIN kaveri.booktypemaster bt ON dm.bookid = bt.bookid
     WHERE dm.isregistrationcompleted = true and
--     dm.registrationdatetime::date between _fromdate and _todate

     dm.registrationdatetime between _fromdate and _todate::timestamp + INTERVAL '1 day'
     
     and (

             case 

                 when _districtcode<>0 then d.districtcode=_districtcode

                 ELSE

                        true


             end

            

         )
     and (

             case

                 when _srocode<> 0 then sro.srocode=_srocode
			 else
				true

             end

          )
      
 
  GROUP BY  d.districtnamee,  dm.finalregistrationnumber,dm.uploaddocdeedpath,
  pm.stamparticlecode,d.districtcode,dm.srocode,
   dm.registrationdatetime, sa.articlenamee, sro.sronamee, bt.booknameenglish
   
   having

                (case

                    when _amounttype=0 then true
                    
                    when _amounttype=1 then sum(pm.sroconsideration)+sum(pm.sromarketvalue) >=_minval and sum(pm.sroconsideration)+sum(pm.sromarketvalue) <=_maxval

                    when _amounttype=2 then sum(pm.sroconsideration) >=_minval and sum(pm.sroconsideration) <=_maxval

                    when _amounttype=3 then sum(pm.sromarketvalue) >=_minval and sum(pm.sromarketvalue) <=_maxval 

                    ELSE

                        true

                                                

                end)

                )

--    limit pagesize offset PageOffset ;---)
                 select * from cte
   right join (select count(*) as total_rows from cte) total_row on true 
   where total_row.total_rows<>0
  OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
			
elsif (pagenumber<>-1 or pagesize<>-1) then 
		return query

		
		 with cte as (
		SELECT
     d.districtcode,
     d.districtnamee AS droffice,
     dm.srocode,
    sro.sronamee  AS srooffice,
    bt.booknameenglish AS booktype,
    dm.finalregistrationnumber,
    dm.uploaddocdeedpath  as copy_of_document,
    pm.stamparticlecode,
    sa.articlenamee AS articlename,
    to_char(dm.registrationdatetime,'dd-mm-yyyy') as regddatetime,
    string_agg(DISTINCT pm.totalarea::text, ', '::text) AS totalarea,
    string_agg(distinct mum.descriptionenglish::text, ', '::text) AS unit,
    string_agg(DISTINCT  ps.description::text, ', '::text) AS propertydetails,
    string_agg(DISTINCT ps.scheduletype::text, ', '::text) AS schedule,
    string_agg(distinct case when a.partytypeid=2 then
    concat_ws(' '::text, a.firstname, a.middlename, a.lastname) else null end ,',') AS executants,
    string_agg(distinct case when a.partytypeid=1 then
    concat_ws(' '::text, a.firstname, a.middlename, a.lastname) else null end ,',') AS claimants,
    string_agg(DISTINCT vm.villagenamee::text, ', '::text) AS villagenamee,
    sum(pm.sromarketvalue) AS marketvalue,
    sum(pm.sroconsideration) AS consideration
   FROM  kaveri.documentmaster dm
     JOIN kaveri.propertymaster pm ON dm.documentid = pm.documentid
     left JOIN kaveri.propertyschedules ps ON pm.propertyid = ps.propertyid
     JOIN kaveri.partyinfo a on a.applicationnumber=dm.applicationnumber
	 and a.partytypeid in (1,2)
     JOIN kaveri.stamparticles sa ON pm.stamparticlecode = sa.stamparticlecode
     JOIN kaveri.villagemaster vm ON pm.villagecode = vm.villagecode
     JOIN kaveri.measunitmaster mum ON pm.unitid = mum.unitid
     JOIN kaveri.sromaster sro ON dm.srocode = sro.srocode
     JOIN kaveri.districtmaster d ON sro.districtcode = d.districtcode
     JOIN kaveri.booktypemaster bt ON dm.bookid = bt.bookid
     WHERE dm.isregistrationcompleted = true and
--     dm.registrationdatetime::date between _fromdate and _todate

     dm.registrationdatetime between _fromdate and _todate::timestamp + INTERVAL '1 day'
     
     and (

             case 

                 when _districtcode<>0 then d.districtcode=_districtcode

                 ELSE

                        true


             end

            

         )
     and (

             case

                 when _srocode<> 0 then sro.srocode=_srocode
			 else
				true

             end

          )
      
 
  GROUP BY  d.districtnamee,  dm.finalregistrationnumber,dm.uploaddocdeedpath,
  pm.stamparticlecode,d.districtcode,dm.srocode,
   dm.registrationdatetime, sa.articlenamee, sro.sronamee, bt.booknameenglish
   
   having

                (case

                    when _amounttype=0 then true
                    
                    when _amounttype=1 then sum(pm.sroconsideration)+sum(pm.sromarketvalue) >=_minval and sum(pm.sroconsideration)+sum(pm.sromarketvalue) <=_maxval

                    when _amounttype=2 then sum(pm.sroconsideration) >=_minval and sum(pm.sroconsideration) <=_maxval

                    when _amounttype=3 then sum(pm.sromarketvalue) >=_minval and sum(pm.sromarketvalue) <=_maxval 

                    ELSE

                        true

                                                

                end)

                )

--    limit pagesize offset PageOffset ;---)
                 select * from cte
   right join (select count(*) as total_rows from cte) total_row on true 
   where total_row.total_rows<>0;
end if;		
   ---select * from cte;
		
	END;
$$;


ALTER FUNCTION kaverimis.fn_mis_statistical_form1_registration_summery_2802(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_statistical_form1_registration_summery_31052024(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_statistical_form1_registration_summery_31052024(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::bigint, _maxval integer DEFAULT NULL::bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtcode integer, droffice character varying, srocode1 integer, srooffice character varying, booktype character varying, finalregistrationnumber character varying, copy_of_document text, stamparticlecode integer, articlename character varying, registrationdatetime1 text, totalarea text, unit text, propertydetails text, schedule text, executants text, claimants text, villagenamee text, marketvalue numeric, consideration numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

declare 
	PageOffset INTEGER := 0;

	begin
		
		PageOffset := (pagesize*pagenumber) - pagesize;
	
		if (pagenumber<>-1 and pagesize<>-1) then 
		return query

		
		 with cte as (
		 
		 with a as (SELECT
     d.districtcode,
     d.districtnamee AS droffice,
     dm.srocode,
    sro.sronamee  AS srooffice,
    bt.booknameenglish AS booktype,
    dm.finalregistrationnumber,
