--
-- Name: fn_mis_statistical_form1_registration_summery_backup_28_03_2023(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_statistical_form1_registration_summery_backup_28_03_2023(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::bigint, _maxval integer DEFAULT NULL::bigint) RETURNS TABLE(districtcode integer, droffice text, srocode integer, srooffice character varying, booktype text, finalregistrationnumber character varying, stamparticlecode integer, articlename character varying, registrationdatetime text, totalarea text, unit text, propertydetails text, schedule text, executants text, claimants text, villagenamee text, marketvalue numeric, consideration numeric)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN	
if(_districtcode=0) THEN --All district
	
	if (_amounttype=0) then--no amounttype
	raise notice 'All district and no amounttype';
	return query
	SELECT 
	d.districtcode,
	string_agg(DISTINCT d.districtnamee::text, ', '::text) AS droffice,
	dm.srocode,
    string_agg(DISTINCT sro.sronamee::text, ', '::text)::character varying AS srooffice,
    string_agg(DISTINCT bt.booknameenglish::text, ', '::text) AS booktype,
    dm.finalregistrationnumber,
    pm.stamparticlecode,
    sa.articlenamee AS articlename,
    to_char(dm.registrationdatetime,'dd-mm-yyyy') as regddatetime,
    string_agg(DISTINCT pm.totalarea::text, ', '::text) AS totalarea,
    string_agg(mum.descriptionenglish::text, ', '::text) AS unit,
    string_agg(DISTINCT  ps.description::text, ', '::text) AS propertydetails,
    string_agg(DISTINCT ps.scheduletype::text, ', '::text) AS schedule,
    prt_ex.executants,
    prt_cl.claimants,
    string_agg(DISTINCT vm.villagenamee::text, ', '::text) AS villagenamee,
    sum(pm.sromarketvalue) AS marketvalue,
    sum(pm.sroconsideration) AS consideration
   FROM kaveri.documentmaster dm
     LEFT JOIN kaveri.propertymaster pm ON dm.documentid = pm.documentid
     LEFT JOIN kaveri.propertyschedules ps ON pm.propertyid = ps.propertyid
     LEFT JOIN ( SELECT vw.applicationnumber,
            string_agg(DISTINCT vw.name, ', '::text) AS executants
           FROM kaverimis.vw_mis_partyinfo vw
          WHERE vw.partytypeid = 2
          GROUP BY vw.applicationnumber) prt_ex ON prt_ex.applicationnumber::text = dm.applicationnumber::text
     LEFT JOIN ( SELECT vw.applicationnumber,
            string_agg(DISTINCT vw.name, ', '::text) AS claimants
           FROM kaverimis.vw_mis_partyinfo vw
          WHERE vw.partytypeid = 1
          GROUP BY vw.applicationnumber) prt_cl ON prt_cl.applicationnumber::text = dm.applicationnumber::text
     LEFT JOIN kaveri.stamparticles sa ON pm.stamparticlecode = sa.stamparticlecode
     LEFT JOIN kaveri.villagemaster vm ON pm.villagecode = vm.villagecode
     LEFT JOIN kaveri.measunitmaster mum ON pm.unitid = mum.unitid
     LEFT JOIN kaveri.sromaster sro ON dm.srocode = sro.srocode
     LEFT JOIN kaveri.districtmaster d ON sro.districtcode = d.districtcode
     LEFT JOIN kaveri.booktypemaster bt ON dm.bookid = bt.bookid
  WHERE dm.isregistrationcompleted = true and
  dm.registrationdatetime::date>=_fromdate and dm.registrationdatetime::date<=_todate 
  GROUP BY  dm.finalregistrationnumber, pm.stamparticlecode,d.districtcode,dm.srocode,
   dm.registrationdatetime, prt_ex.executants, sa.articlenamee, prt_cl.claimants;
   
   elseif (_amounttype=1)then --Total
   
   raise notice 'All district and amounttype Total';
	return query
	SELECT 
	d.districtcode,
	string_agg(DISTINCT d.districtnamee::text, ', '::text) AS droffice,
	dm.srocode,
    string_agg(DISTINCT sro.sronamee::text, ', '::text)::character varying AS srooffice,
    string_agg(DISTINCT bt.booknameenglish::text, ', '::text) AS booktype,
    dm.finalregistrationnumber,
    pm.stamparticlecode,
    sa.articlenamee AS articlename,
    to_char(dm.registrationdatetime,'dd-mm-yyyy') as regddatetime,
    string_agg(DISTINCT pm.totalarea::text, ', '::text) AS totalarea,
    string_agg(mum.descriptionenglish::text, ', '::text) AS unit,
    string_agg(DISTINCT  ps.description::text, ', '::text) AS propertydetails,
    string_agg(DISTINCT ps.scheduletype::text, ', '::text) AS schedule,
    prt_ex.executants,
    prt_cl.claimants,
    string_agg(DISTINCT vm.villagenamee::text, ', '::text) AS villagenamee,
    sum(pm.sromarketvalue) AS marketvalue,
    sum(pm.sroconsideration) AS consideration
   FROM kaveri.documentmaster dm
     LEFT JOIN kaveri.propertymaster pm ON dm.documentid = pm.documentid
     LEFT JOIN kaveri.propertyschedules ps ON pm.propertyid = ps.propertyid
     LEFT JOIN ( SELECT vw.applicationnumber,
            string_agg(DISTINCT vw.name, ', '::text) AS executants
           FROM kaverimis.vw_mis_partyinfo vw
          WHERE vw.partytypeid = 2
          GROUP BY vw.applicationnumber) prt_ex ON prt_ex.applicationnumber::text = dm.applicationnumber::text
     LEFT JOIN ( SELECT vw.applicationnumber,
            string_agg(DISTINCT vw.name, ', '::text) AS claimants
           FROM kaverimis.vw_mis_partyinfo vw
          WHERE vw.partytypeid = 1
          GROUP BY vw.applicationnumber) prt_cl ON prt_cl.applicationnumber::text = dm.applicationnumber::text
     LEFT JOIN kaveri.stamparticles sa ON pm.stamparticlecode = sa.stamparticlecode
     LEFT JOIN kaveri.villagemaster vm ON pm.villagecode = vm.villagecode
     LEFT JOIN kaveri.measunitmaster mum ON pm.unitid = mum.unitid
     LEFT JOIN kaveri.sromaster sro ON dm.srocode = sro.srocode
     LEFT JOIN kaveri.districtmaster d ON sro.districtcode = d.districtcode
     LEFT JOIN kaveri.booktypemaster bt ON dm.bookid = bt.bookid
  WHERE dm.isregistrationcompleted = true and
  dm.registrationdatetime::date>=_fromdate and dm.registrationdatetime::date<=_todate  
  
  GROUP BY  dm.finalregistrationnumber, pm.stamparticlecode,d.districtcode,dm.srocode,
   dm.registrationdatetime, prt_ex.executants, sa.articlenamee, prt_cl.claimants 
  having sum(pm.sroconsideration)+sum(pm.sromarketvalue) >=_minval and sum(pm.sroconsideration)+sum(pm.sromarketvalue) <=_maxval ;
   
   elseif (_amounttype=2)then --Consideration
   
   raise notice 'All district and amounttype Consideration';
	return query
	SELECT 
	d.districtcode,
	string_agg(DISTINCT d.districtnamee::text, ', '::text) AS droffice,
	dm.srocode,
    string_agg(DISTINCT sro.sronamee::text, ', '::text)::character varying AS srooffice,
    string_agg(DISTINCT bt.booknameenglish::text, ', '::text) AS booktype,
    dm.finalregistrationnumber,
    pm.stamparticlecode,
    sa.articlenamee AS articlename,
    to_char(dm.registrationdatetime,'dd-mm-yyyy') as regddatetime,
    string_agg(DISTINCT pm.totalarea::text, ', '::text) AS totalarea,
    string_agg(mum.descriptionenglish::text, ', '::text) AS unit,
    string_agg(DISTINCT  ps.description::text, ', '::text) AS propertydetails,
    string_agg(DISTINCT ps.scheduletype::text, ', '::text) AS schedule,
    prt_ex.executants,
    prt_cl.claimants,
    string_agg(DISTINCT vm.villagenamee::text, ', '::text) AS villagenamee,
    sum(pm.sromarketvalue) AS marketvalue,
    sum(pm.sroconsideration) AS consideration
   FROM kaveri.documentmaster dm
     LEFT JOIN kaveri.propertymaster pm ON dm.documentid = pm.documentid
     LEFT JOIN kaveri.propertyschedules ps ON pm.propertyid = ps.propertyid
     LEFT JOIN ( SELECT vw.applicationnumber,
            string_agg(DISTINCT vw.name, ', '::text) AS executants
           FROM kaverimis.vw_mis_partyinfo vw
          WHERE vw.partytypeid = 2
          GROUP BY vw.applicationnumber) prt_ex ON prt_ex.applicationnumber::text = dm.applicationnumber::text
     LEFT JOIN ( SELECT vw.applicationnumber,
            string_agg(DISTINCT vw.name, ', '::text) AS claimants
           FROM kaverimis.vw_mis_partyinfo vw
          WHERE vw.partytypeid = 1
          GROUP BY vw.applicationnumber) prt_cl ON prt_cl.applicationnumber::text = dm.applicationnumber::text
     LEFT JOIN kaveri.stamparticles sa ON pm.stamparticlecode = sa.stamparticlecode
     LEFT JOIN kaveri.villagemaster vm ON pm.villagecode = vm.villagecode
     LEFT JOIN kaveri.measunitmaster mum ON pm.unitid = mum.unitid
     LEFT JOIN kaveri.sromaster sro ON dm.srocode = sro.srocode
     LEFT JOIN kaveri.districtmaster d ON sro.districtcode = d.districtcode
     LEFT JOIN kaveri.booktypemaster bt ON dm.bookid = bt.bookid
  WHERE dm.isregistrationcompleted = true and
  dm.registrationdatetime::date>=_fromdate and dm.registrationdatetime::date<=_todate  
  
  GROUP BY  dm.finalregistrationnumber, pm.stamparticlecode,d.districtcode,dm.srocode,
   dm.registrationdatetime, prt_ex.executants, sa.articlenamee, prt_cl.claimants
  having sum(pm.sroconsideration) >=_minval and sum(pm.sroconsideration) <=_maxval;
   
   elseif (_amounttype=3)then --marketvalue
   
   raise notice 'All district and amounttype Marketvalue';
	return query
	SELECT 
	d.districtcode,
	string_agg(DISTINCT d.districtnamee::text, ', '::text) AS droffice,
	dm.srocode,
    string_agg(DISTINCT sro.sronamee::text, ', '::text)::character varying AS srooffice,
    string_agg(DISTINCT bt.booknameenglish::text, ', '::text) AS booktype,
    dm.finalregistrationnumber,
    pm.stamparticlecode,
    sa.articlenamee AS articlename,
    to_char(dm.registrationdatetime,'dd-mm-yyyy') as regddatetime,
    string_agg(DISTINCT pm.totalarea::text, ', '::text) AS totalarea,
    string_agg(mum.descriptionenglish::text, ', '::text) AS unit,
    string_agg(DISTINCT  ps.description::text, ', '::text) AS propertydetails,
    string_agg(DISTINCT ps.scheduletype::text, ', '::text) AS schedule,
    prt_ex.executants,
    prt_cl.claimants,
    string_agg(DISTINCT vm.villagenamee::text, ', '::text) AS villagenamee,
    sum(pm.sromarketvalue) AS marketvalue,
    sum(pm.sroconsideration) AS consideration
   FROM kaveri.documentmaster dm
     LEFT JOIN kaveri.propertymaster pm ON dm.documentid = pm.documentid
     LEFT JOIN kaveri.propertyschedules ps ON pm.propertyid = ps.propertyid
     LEFT JOIN ( SELECT vw.applicationnumber,
            string_agg(DISTINCT vw.name, ', '::text) AS executants
           FROM kaverimis.vw_mis_partyinfo vw
          WHERE vw.partytypeid = 2
          GROUP BY vw.applicationnumber) prt_ex ON prt_ex.applicationnumber::text = dm.applicationnumber::text
     LEFT JOIN ( SELECT vw.applicationnumber,
            string_agg(DISTINCT vw.name, ', '::text) AS claimants
           FROM kaverimis.vw_mis_partyinfo vw
          WHERE vw.partytypeid = 1
          GROUP BY vw.applicationnumber) prt_cl ON prt_cl.applicationnumber::text = dm.applicationnumber::text
     LEFT JOIN kaveri.stamparticles sa ON pm.stamparticlecode = sa.stamparticlecode
     LEFT JOIN kaveri.villagemaster vm ON pm.villagecode = vm.villagecode
     LEFT JOIN kaveri.measunitmaster mum ON pm.unitid = mum.unitid
     LEFT JOIN kaveri.sromaster sro ON dm.srocode = sro.srocode
     LEFT JOIN kaveri.districtmaster d ON sro.districtcode = d.districtcode
     LEFT JOIN kaveri.booktypemaster bt ON dm.bookid = bt.bookid
  WHERE dm.isregistrationcompleted = true and
  dm.registrationdatetime::date>=_fromdate and dm.registrationdatetime::date<=_todate  
  
  GROUP BY  dm.finalregistrationnumber, pm.stamparticlecode,d.districtcode,dm.srocode,
   dm.registrationdatetime, prt_ex.executants, sa.articlenamee, prt_cl.claimants
  having sum(pm.sromarketvalue) >=_minval and sum(pm.sromarketvalue) <=_maxval;
   
