CREATE FUNCTION kaverimis.fn_mis_statistical_form1_registration_summery_flat_bck(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _regarticlecode integer, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::bigint, _maxval integer DEFAULT NULL::bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtcode integer, droffice character varying, srocode integer, srooffice character varying, booktype character varying, finalregistrationnumber character varying, copy_of_document text, regarticlecode integer, articlename character varying, registrationdatetime text, totalarea text, unit text, propertydetails text, schedule text, executants text, claimants text, villagenamee text, marketvalue numeric, consideration numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

declare 
	PageOffset INTEGER := 0;

	begin
		
		PageOffset := (pagesize*pagenumber) - pagesize;
	
		if (pagenumber=1) then 
		return query

		
		 with cte as (
		 
		 with a as (select
		 d.districtcode,
		 d.droffice,
 		 d.srocode,
 		 d.srooffice,
 		 d.booktype,
 		 d.finalregistrationnumber,
 		 d.applicationnumber, 
 		 d.copy_of_document,
 		 d.regarticlecode,
 		 d.articlename,
 		 to_char(d.registrationdatetime,'YYYY-MM-DD HH:MI AM') as registrationdatetime,
 		-- (CAST(d.totalarea AS NUMERIC)::DECIMAL(3))::text as totalarea ,
 		d.totalarea,
 		 d.unit,
 		 d.propertydetails,
 		 d.schedule,
 		 d.executants,
 		 d.claimants,
 		 d.villagenamee,
 		 d.marketvalue,
 		 d.consideration
    
   
   		FROM  
   
   		kaverimis.statisticalform1table d
   		WHERE 
    	 d.isregistrationcompleted = true and
--     dm.registrationdatetime::date between _fromdate and _todate

     	d.registrationdatetime between _fromdate and _todate::timestamp + INTERVAL '1 day'
     
     	and (

             case 

                 when _districtcode<>0 then d.districtcode=_districtcode

                 ELSE

                        true


             end

            

         )
     and (

             case

                 when _srocode<> 0 then d.srocode=_srocode
			 else
				true

             end

          )
          
      and 
      (
      case

                 when _regarticlecode <> 0 then d.regarticlecode=_regarticlecode
			 else
				true

             end
      )
     
     )
   	 
   	 select 
   	 a.districtcode,a.droffice,a.srocode,a.srooffice,a.booktype,a.finalregistrationnumber,
   	 a.copy_of_document,
   	 a.regarticlecode,a.articlename,a.registrationdatetime,a.totalarea,a.unit,a.propertydetails,
   	 a.schedule,
   	 a.executants,
   	 a.claimants,
   	 a.villagenamee,a.marketvalue,a.consideration
   	 from a 
   	 
    where

                (case

                    when _amounttype=0 then true
                    
                   -- when _amounttype=1 then a.consideration+a.marketvalue >=_minval and  a.consideration+a.marketvalue <=_maxval

                    when _amounttype=2 then a.consideration >=_minval and a.consideration <=_maxval

                    when _amounttype=3 then a.marketvalue >=_minval and a.marketvalue <=_maxval 

                    ELSE

                        true

                                                

                end) )


   select * from cte
   join (select count(*) as total_rows from cte) total_row on true 
   order by cte.droffice,cte.srooffice,cte.finalregistrationnumber asc
  OFFSET PageOffset
  FETCH NEXT pagesize ROWS ONLY;

elsif (pagenumber>1) then 

return query

		
		 with cte as (
	 with a as (select
		 d.districtcode,
		 d.droffice,
 		 d.srocode,
 		 d.srooffice,
 		 d.booktype,
 		 d.finalregistrationnumber,
 		 d.applicationnumber, 
 		 d.copy_of_document,
 		 d.regarticlecode,
 		 d.articlename,
 		  to_char(d.registrationdatetime,'YYYY-MM-DD HH:MI AM') as registrationdatetime,
 		 d.totalarea,
 		 d.unit,
 		 d.propertydetails,
 		 d.schedule,
 		 d.executants,
 		 d.claimants,
 		 d.villagenamee,
 		 d.marketvalue,
 		 d.consideration
    
   
   		FROM  
   
   		kaverimis.statisticalform1table d
   		WHERE 
    	 d.isregistrationcompleted = true and
--     dm.registrationdatetime::date between _fromdate and _todate

     	d.registrationdatetime between _fromdate and _todate::timestamp + INTERVAL '1 day'
     
     	and (

             case 

                 when _districtcode<>0 then d.districtcode=_districtcode

                 ELSE

                        true


             end

            

         )
     and (

             case

                 when _srocode<> 0 then d.srocode=_srocode
			 else
				true

             end

          )
          
      and 
      (
      case

                 when _regarticlecode <> 0 then d.regarticlecode=_regarticlecode
			 else
				true

             end
      )
     
     )
   	 
   	 select 
   	 a.districtcode,a.droffice,a.srocode,a.srooffice,a.booktype,a.finalregistrationnumber,
   	 a.copy_of_document,
   	 a.regarticlecode,a.articlename,a.registrationdatetime,a.totalarea,a.unit,a.propertydetails,
   	 a.schedule,
   	 a.executants,
   	 a.claimants,
   	 a.villagenamee,a.marketvalue,a.consideration
   	 from a 
   	 
    where

                (case

                    when _amounttype=0 then true
                    
                   -- when _amounttype=1 then a.consideration+a.marketvalue >=_minval and  a.consideration+a.marketvalue <=_maxval

                    when _amounttype=2 then a.consideration >=_minval and a.consideration <=_maxval

                    when _amounttype=3 then a.marketvalue >=_minval and a.marketvalue <=_maxval 

                    ELSE

                        true

                                                

                end) 	   OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY

                )
                
                   
                
                
                

	select *,null::bigint as total_row from cte	
	order by cte.droffice,cte.srooffice,cte.finalregistrationnumber asc;

		 
			
elsif (pagenumber = -1 or pagesize=-1) then 
		return query

		
		 with cte as (
		 with a as (select
		 d.districtcode,
		 d.droffice,
 		 d.srocode,
 		 d.srooffice,
 		 d.booktype,
 		 d.finalregistrationnumber,
 		 d.applicationnumber, 
 		 d.copy_of_document,
 		 d.regarticlecode,
 		 d.articlename,
 		  to_char(d.registrationdatetime,'YYYY-MM-DD HH:MI AM') as registrationdatetime,
 		 d.totalarea,
 		 d.unit,
 		 d.propertydetails,
 		 d.schedule,
 		 d.executants,
 		 d.claimants,
 		 d.villagenamee,
 		 d.marketvalue,
 		 d.consideration
    
   
   		FROM  
   
   		kaverimis.statisticalform1table d
   		WHERE 
    	 d.isregistrationcompleted = true and
--     dm.registrationdatetime::date between _fromdate and _todate

     	d.registrationdatetime between _fromdate and _todate::timestamp + INTERVAL '1 day'
     
     	and (

             case 

                 when _districtcode<>0 then d.districtcode=_districtcode

                 ELSE

                        true


             end

            

         )
     and (

             case

                 when _srocode<> 0 then d.srocode=_srocode
			 else
				true

             end

          )
          
      and 
      (
      case

                 when _regarticlecode <> 0 then d.regarticlecode=_regarticlecode
			 else
				true

             end
      )
     
     )
   	 
   	 select 
   	 a.districtcode,a.droffice,a.srocode,a.srooffice,a.booktype,a.finalregistrationnumber,
   	 a.copy_of_document,
   	 a.regarticlecode,a.articlename,a.registrationdatetime,a.totalarea,a.unit,a.propertydetails,
   	 a.schedule,
   	 a.executants,
   	 a.claimants,
   	 a.villagenamee,a.marketvalue,a.consideration
   	 from a 
   	 
    where

                (case

                    when _amounttype=0 then true
                    
                   -- when _amounttype=1 then a.consideration+a.marketvalue >=_minval and  a.consideration+a.marketvalue <=_maxval

                    when _amounttype=2 then a.consideration >=_minval and a.consideration <=_maxval

                    when _amounttype=3 then a.marketvalue >=_minval and a.marketvalue <=_maxval 

                    ELSE

                        true

                                                

                end) 
                )

	select *,null::bigint as total_row from cte	
	order by cte.droffice,cte.srooffice,cte.finalregistrationnumber asc;

end if;		
  
		
	END;
$$;


ALTER FUNCTION kaverimis.fn_mis_statistical_form1_registration_summery_flat_bck(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _regarticlecode integer, _amounttype integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_statistical_form1_registration_summery_optimization(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_statistical_form1_registration_summery_optimization(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::bigint, _maxval integer DEFAULT NULL::bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtcode integer, droffice character varying, srocode1 integer, srooffice character varying, booktype character varying, finalregistrationnumber character varying, copy_of_document text, stamparticlecode integer, articlename character varying, registrationdatetime1 text, totalarea text, unit text, propertydetails text, schedule text, executants text, claimants text, villagenamee text, marketvalue numeric, consideration numeric)
    LANGUAGE plpgsql
    AS $$

declare 
	PageOffset INTEGER := 0;

	begin
		
		PageOffset := (pagesize*pagenumber) - pagesize;
		return query

		
		--- with cte as (
		SELECT
     d.districtcode,
     d.districtnamee AS droffice,
     dm.srocode,
    sro.sronamee  AS srooffice,
    bt.booknameenglish AS booktype,
    dm.finalregistrationnumber,
    dm.uploaddocdeedpath  as copy_of_document,
    pm.stamparticlecode,
    sa.articlenamee AS articlename,
    to_char(dm.registrationdatetime,'dd-mm-yyyy') as regddatetime,
    string_agg(DISTINCT pm.totalarea::text, ', '::text) AS totalarea,
    string_agg(distinct mum.descriptionenglish::text, ', '::text) AS unit,
    string_agg(DISTINCT  ps.description::text, ', '::text) AS propertydetails,
    string_agg(DISTINCT ps.scheduletype::text, ', '::text) AS schedule,
    string_agg(distinct case when a.partytypeid=2 then
    concat_ws(' '::text, a.firstname, a.middlename, a.lastname) else null end ,',') AS executants,
    string_agg(distinct case when a.partytypeid=1 then
    concat_ws(' '::text, a.firstname, a.middlename, a.lastname) else null end ,',') AS claimants,
    string_agg(DISTINCT vm.villagenamee::text, ', '::text) AS villagenamee,
    sum(pm.sromarketvalue) AS marketvalue,
    sum(pm.sroconsideration) AS consideration
   FROM  kaveri.documentmaster dm
     JOIN kaveri.propertymaster pm ON dm.documentid = pm.documentid
     JOIN kaveri.propertyschedules ps ON pm.propertyid = ps.propertyid
     JOIN kaveri.partyinfo a on a.applicationnumber=dm.applicationnumber
	 and a.partytypeid in (1,2)
     JOIN kaveri.stamparticles sa ON pm.stamparticlecode = sa.stamparticlecode
     JOIN kaveri.villagemaster vm ON pm.villagecode = vm.villagecode
     JOIN kaveri.measunitmaster mum ON pm.unitid = mum.unitid
     JOIN kaveri.sromaster sro ON dm.srocode = sro.srocode
     JOIN kaveri.districtmaster d ON sro.districtcode = d.districtcode
     JOIN kaveri.booktypemaster bt ON dm.bookid = bt.bookid
     WHERE dm.isregistrationcompleted = true and
     dm.registrationdatetime::date between _fromdate and _todate
     and (

             case 

                 when _districtcode<>0 then d.districtcode=_districtcode

                 ELSE

                        true


             end

            

         )
     and (

             case

                 when _srocode<> 0 then sro.srocode=_srocode
			 else
				true

             end

          )
      
 
  GROUP BY  d.districtnamee,  dm.finalregistrationnumber,dm.uploaddocdeedpath,
  pm.stamparticlecode,d.districtcode,dm.srocode,
   dm.registrationdatetime, sa.articlenamee, sro.sronamee, bt.booknameenglish
   
   having

                (case

                    when _amounttype=0 then true
                    
                    when _amounttype=1 then sum(pm.sroconsideration)+sum(pm.sromarketvalue) >=_minval and sum(pm.sroconsideration)+sum(pm.sromarketvalue) <=_maxval

                    when _amounttype=2 then sum(pm.sroconsideration) >=_minval and sum(pm.sroconsideration) <=_maxval

                    when _amounttype=3 then sum(pm.sromarketvalue) >=_minval and sum(pm.sromarketvalue) <=_maxval 

                    ELSE

                        true

                                                

                end)

                

    limit pagesize offset PageOffset ;---)
		
   ---select * from cte;
		
	END;
$$;


ALTER FUNCTION kaverimis.fn_mis_statistical_form1_registration_summery_optimization(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _amounttype integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_statistical_form1_registration_summery_scheduler(integer, integer, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_statistical_form1_registration_summery_scheduler(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone) RETURNS TABLE(districtcode integer, droffice character varying, srocode integer, srooffice character varying, booktype character varying, finalregistrationnumber character varying, applicationnumber character varying, copy_of_document text, regarticlecode integer, articlename character varying, registrationdatetime timestamp without time zone, totalarea text, unit text, propertydetails text, schedule text, executants text, claimants text, villagenamee text, marketvalue numeric, consideration numeric, isregistrationcompleted boolean)
    LANGUAGE plpgsql
    AS $$

declare 

	begin
		
	return query

			 with cte as (
		  with a as (SELECT
     d.districtcode,
     d.districtnamee AS droffice,
     dm.srocode,
    sro.sronamee  AS srooffice,
    bt.booknameenglish AS booktype,
    dm.finalregistrationnumber,
    dm.applicationnumber,
    dm.uploaddocdeedpath  as copy_of_document,
    ra.regarticlecode,
    ra.articlenamee  AS articlename,
    dm.registrationdatetime as regddatetime,
    string_agg( (pm.totalarea::numeric(20,3))::text, ', '::text) AS totalarea,
    string_agg( mum.descriptionenglish::text, ', '::text) AS unit,
    string_agg(  ps.description::text, ', '::text) AS propertydetails,
    string_agg( ps.scheduletype::text, ', '::text) AS schedule,
    string_agg( vm.villagenamee::text, ', '::text) AS villagenamee,
    sum(pm.sromarketvalue) AS marketvalue,
    sum(pm.sroconsideration) AS consideration,dm.isregistrationcompleted
   
   FROM  kaveri.documentmaster dm
     left JOIN kaveri.propertymaster pm ON dm.documentid = pm.documentid  and dm.applicationnumber=pm.applicationnumber
     left JOIN kaveri.propertyschedules ps ON pm.propertyid = ps.propertyid and pm.applicationnumber=ps.applicationnumber
     left JOIN kaveri.registrationarticles ra   ON dm.regarticlecode = ra.regarticlecode 
     left JOIN kaveri.villagemaster vm ON pm.villagecode = vm.villagecode
     left JOIN kaveri.measunitmaster mum ON pm.unitid = mum.unitid
     JOIN kaveri.sromaster sro ON dm.srocode = sro.srocode
     JOIN kaveri.districtmaster d ON sro.districtcode = d.districtcode
     JOIN kaveri.booktypemaster bt ON dm.bookid = bt.bookid
     WHERE 
     dm.isregistrationcompleted = true and
--     dm.registrationdatetime::date between _fromdate and _todate

     dm.registrationdatetime between _fromdate and _todate::timestamp + INTERVAL '1 day'
     
     and (

             case 

                 when _districtcode<>0 then d.districtcode=_districtcode

                 ELSE

                        true


             end

            

         )
     and (

             case

                 when _srocode<> 0 then sro.srocode=_srocode
			 else
				true

             end

          )
          
      
     GROUP BY  d.districtnamee,  dm.finalregistrationnumber,dm.uploaddocdeedpath,
  	 ra.regarticlecode,d.districtcode,dm.srocode,
   	 dm.registrationdatetime, ra.articlenamee, sro.sronamee, bt.booknameenglish,
   	 dm.applicationnumber,dm.isregistrationcompleted)
   	 
   	 select 
   	 a.districtcode,a.droffice,a.srocode,a.srooffice,a.booktype,a.finalregistrationnumber,
   	 a.applicationnumber,
   	 a.copy_of_document,
   	 a.regarticlecode,a.articlename,a.regddatetime,a.totalarea,a.unit,a.propertydetails,a.schedule,
   	 string_agg(distinct case when p.partytypeid=2 then
     concat_ws(' '::text, p.firstname, p.middlename, p.lastname) else null end ,',') AS executants,
     string_agg(distinct case when p.partytypeid=1 then
     concat_ws(' '::text, p.firstname, p.middlename, p.lastname) else null end ,',') AS claimants,
   	 a.villagenamee,a.marketvalue,a.consideration,a.isregistrationcompleted  
   	 from a 
   	 join kaveri.partyinfo p on  p.applicationnumber=a.applicationnumber
   	 group by 
   	 a.districtcode,a.droffice,a.srocode,a.srooffice,a.booktype,a.finalregistrationnumber,
   	 a.copy_of_document,
   	 a.regarticlecode,a.articlename,a.regddatetime,a.totalarea,a.unit,a.propertydetails,
   	 a.schedule,a.villagenamee,
   	 a.marketvalue,a.consideration,a.isregistrationcompleted ,a.applicationnumber 
   	
        )

	select * from cte;
	
   
		
	END;
$$;


ALTER FUNCTION kaverimis.fn_mis_statistical_form1_registration_summery_scheduler(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: fn_mis_statistical_form1_registration_summery_test(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_statistical_form1_registration_summery_test(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _regarticlecode integer, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::bigint, _maxval integer DEFAULT NULL::bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtcode integer, droffice character varying, srocode integer, srooffice character varying, booktype character varying, finalregistrationnumber character varying, copy_of_document text, regarticlecode integer, articlename character varying, registrationdatetime timestamp without time zone, totalarea text, unit text, propertydetails text, schedule text, executants text, claimants text, villagenamee text, marketvalue numeric, consideration numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

declare 
	PageOffset INTEGER := 0;

	begin
		
		PageOffset := (pagesize*pagenumber) - pagesize;
	
		if (pagenumber=1) then 
--		return query
	CREATE TEMP TABLE dataselect AS
		SELECT
     d.districtcode,
     d.districtnamee AS droffice,
     dm.srocode,
    sro.sronamee  AS srooffice,
    bt.booknameenglish AS booktype,
    dm.finalregistrationnumber,
    dm.applicationnumber,
    dm.uploaddocdeedpath  as copy_of_document,
    ra.regarticlecode,
    ra.articlenamee  AS articlename,
    dm.registrationdatetime as regddatetime,
    string_agg( (pm.totalarea::numeric(20,3))::text, ', '::text) AS totalarea,
    string_agg( mum.descriptionenglish::text, ', '::text) AS unit,
    string_agg(  ps.description::text, ', '::text) AS propertydetails,
    string_agg( ps.scheduletype::text, ', '::text) AS schedule,
    string_agg( vm.villagenamee::text, ', '::text) AS villagenamee,
    sum(pm.sromarketvalue) AS marketvalue,
    sum(pm.sroconsideration) AS consideration
   FROM  kaveri.documentmaster dm
   JOIN kaveri.propertymaster pm ON dm.documentid = pm.documentid  and dm.applicationnumber=pm.applicationnumber
   JOIN kaveri.propertyschedules ps ON pm.propertyid = ps.propertyid  and pm.applicationnumber=ps.applicationnumber
   JOIN kaveri.registrationarticles ra   ON dm.regarticlecode = ra.regarticlecode 
   JOIN kaveri.villagemaster vm ON pm.villagecode = vm.villagecode
   JOIN kaveri.measunitmaster mum ON pm.unitid = mum.unitid
     JOIN kaveri.sromaster sro ON dm.srocode = sro.srocode
     JOIN kaveri.districtmaster d ON sro.districtcode = d.districtcode
     JOIN kaveri.booktypemaster bt ON dm.bookid = bt.bookid
     WHERE 
     dm.isregistrationcompleted = true and
     dm.registrationdatetime between '2024-02-01' and '2024-02-05'
     and (case  when 0<>0 then d.districtcode=0 else true end)
     and (case when 0<> 0 then sro.srocode=0 else true end) 
     and (case when 0 <> 0 then ra.regarticlecode=0 else true end)
     GROUP BY  d.districtnamee,  dm.finalregistrationnumber,dm.uploaddocdeedpath,
  	 ra.regarticlecode,d.districtcode,dm.srocode,
   	 dm.registrationdatetime, ra.articlenamee, sro.sronamee, bt.booknameenglish,dm.applicationnumber;
   	
   	return query
	with cte as (
		 select 
   	 a.districtcode,a.droffice,a.srocode,a.srooffice,a.booktype,a.finalregistrationnumber,
   	 a.copy_of_document,
   	 a.regarticlecode,a.articlename,a.regddatetime,a.totalarea,a.unit,a.propertydetails,a.schedule,
   	 string_agg(distinct case when p.partytypeid=2 then
    concat_ws(' '::text, p.firstname, p.middlename, p.lastname) else null end ,',') AS executants,
    string_agg(distinct case when p.partytypeid=1 then
    concat_ws(' '::text, p.firstname, p.middlename, p.lastname) else null end ,',') AS claimants,
   	 a.villagenamee,a.marketvalue,a.consideration
   	 from dataselect a
   	 join kaveri.partyinfo p on  p.applicationnumber=a.applicationnumber
   	 group by 
   	 a.districtcode,a.droffice,a.srocode,a.srooffice,a.booktype,a.finalregistrationnumber,a.copy_of_document,
   	 a.regarticlecode,a.articlename,a.regddatetime,a.totalarea,a.unit,a.propertydetails,
   	 a.schedule,a.villagenamee,
   	 a.marketvalue,a.consideration  
   	 having (case when _amounttype=0 then true
		when _amounttype=2 then a.consideration >=_minval and a.consideration <=_maxval
		when _amounttype=3 then a.marketvalue >=_minval and a.marketvalue <=_maxval 
		ELSE
		true end) )
select * from cte
   join (select count(*) as total_rows from cte) total_row on true 
   order by cte.droffice,cte.srooffice,cte.finalregistrationnumber asc
  OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

			
end if;		
END;
$$;


