CREATE FUNCTION kaverimis.fn_mis_statistical_form1_registration_summery_test20240610(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _regarticlecode integer, _amounttype integer DEFAULT 0, _minval integer DEFAULT NULL::bigint, _maxval integer DEFAULT NULL::bigint, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtcode integer, droffice character varying, srocode integer, srooffice character varying, booktype character varying, finalregistrationnumber character varying, copy_of_document text, regarticlecode integer, articlename character varying, registrationdatetime timestamp without time zone, totalarea text, unit text, propertydetails text, schedule text, executants text, claimants text, villagenamee text, marketvalue numeric, consideration numeric, totalcount bigint)
    LANGUAGE plpgsql
    AS $$

declare 
	PageOffset INTEGER := 0;

	begin
		
		PageOffset := (pagesize*pagenumber) - pagesize;
	
		if (pagenumber=1) then 
		return query

		
		 with cte as (
		 
		 with a as (SELECT
     d.districtcode,
     d.districtnamee AS droffice,
     dm.srocode,
    sro.sronamee  AS srooffice,
    bt.booknameenglish AS booktype,
    dm.finalregistrationnumber,
    dm.applicationnumber,
