ALTER FUNCTION kaverimis.fn_mis_statistical_form1_registration_summery_test20240610(_districtcode integer, _srocode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, _regarticlecode integer, _amounttype integer, _minval integer, _maxval integer, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_statutory_form1(bigint, date, date, character varying); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_statutory_form1(_srocode bigint, _fromdate date DEFAULT NULL::date, _todate date DEFAULT NULL::date, _documentnumber character varying DEFAULT NULL::character varying) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, copy_of_document text, copy_of_endorsement character varying)
    LANGUAGE plpgsql
    AS $$



DECLARE

BEGIN 
if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
raise notice 'Documentnumber null';
return query
select  dsm.districtnamee,sm.sronamee,
dm.finalregistrationnumber,dm.uploaddocdeedpath  as copy_of_document,copy_of_endorsement as NULL
  from kaveri.documentmaster dm  
        JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
        JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
        where dm.srocode=_srocode and dm.registrationdatetime >=_fromdate and dm.registrationdatetime <(_todate+'1 day'::interval) and 
        dm.bookid in (1,5,6,7,8,9,10,14) and dm.finalregistrationnumber is not null and dm.isregistrationcompleted is true 
       and dm.uploaddocdeedpath is not null;

elseif 	_documentnumber is not NULL and (_fromdate  is NULL and _todate is NULL) then

raise notice 'date null';
return query
select  dsm.districtnamee,sm.sronamee,
dm.finalregistrationnumber,dm.uploaddocdeedpath as copy_of_document,copy_of_endorsement as NULL
  from kaveri.documentmaster dm  
        JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
        JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
        where dm.srocode=_srocode and 
        dm.bookid in (1,5,6,7,8,9,10,14) and dm.finalregistrationnumber=_documentnumber and dm.isregistrationcompleted is true
        and dm.uploaddocdeedpath is not null ; 
		
elseif _documentnumber is not NULL and (_fromdate is not NULL and _todate is not NULL) then

raise notice 'nothing null';

return query
select  dsm.districtnamee,sm.sronamee,
dm.finalregistrationnumber,dm.uploaddocdeedpath as copy_of_document,copy_of_endorsement as NULL
  from kaveri.documentmaster dm  
        JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
        JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
        where dm.srocode=_srocode and dm.registrationdatetime >=_fromdate and dm.registrationdatetime <(_todate+'1 day'::interval) and 
        dm.bookid in (1,5,6,7,8,9,10,14) and dm.finalregistrationnumber=_documentnumber and dm.isregistrationcompleted is true
        and dm.uploaddocdeedpath is not null ;
       
       
else

raise notice 'condition failed';
end if;
          

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_statutory_form1(_srocode bigint, _fromdate date, _todate date, _documentnumber character varying) OWNER TO csgadmin;

--
-- Name: fn_mis_statutory_form1(integer, integer, date, date, character varying, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_statutory_form1(_districtcode integer, _srocode integer, _fromdate date DEFAULT NULL::date, _todate date DEFAULT NULL::date, _documentnumber character varying DEFAULT NULL::character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, copy_of_document text, copy_of_endorsement text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$


DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
		if (_districtcode=0) then --All District and All sro
				if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
				raise notice 'Documentnumber null';
				return query
				with cte as (select  dsm.districtnamee,sm.sronamee,
				dm.finalregistrationnumber,dm.uploaddocdeedpath  as copy_of_document,
				 null as copy_of_endorsement 
				  from kaveri.documentmaster dm  
						JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
						JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
						where 
						--dm.srocode=_srocode and 
						(dm.registrationdatetime::date between
					_fromdate and  _todate )
						and 
						dm.bookid in (1,5,6,7,8,9,10,14) 
						and dm.isregistrationcompleted is true ),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true where total_row.total_rows<>0 OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;

					elsif 	_documentnumber is not NULL  then

					raise notice 'date null';
					return query
					with cte as (select  dsm.districtnamee,sm.sronamee,
					dm.finalregistrationnumber,dm.uploaddocdeedpath  as copy_of_document,
					null as copy_of_endorsement 
					from kaveri.documentmaster dm  
						JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
						JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
						where 
						dm.finalregistrationnumber=_documentnumber),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true where total_row.total_rows<>0 OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
			
					   
					   
					else

						raise notice 'condition failed';
				end if;
			elsif (_srocode=0)then --Perticular district and All sro
	
				if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
				raise notice 'Documentnumber null';
				return query
				with cte as (select  dsm.districtnamee,sm.sronamee,
				dm.finalregistrationnumber,dm.uploaddocdeedpath  as copy_of_document,
				 null as copy_of_endorsement 
				  from kaveri.documentmaster dm  
						JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
						JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
						where 
						dsm.districtcode=_districtcode and dm.isregistrationcompleted is true and 
						--dm.srocode=_srocode and 
						(dm.registrationdatetime::date between
					_fromdate and  _todate )
						and 
						dm.bookid in (1,5,6,7,8,9,10,14)),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true where total_row.total_rows<>0 OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY ;

				elsif 	_documentnumber is not NULL  then

				raise notice 'date null';
				return query
				with cte as (select  dsm.districtnamee,sm.sronamee,
				dm.finalregistrationnumber,dm.uploaddocdeedpath  as copy_of_document,
				 null as copy_of_endorsement 
				  from kaveri.documentmaster dm  
						JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
						JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
						where 
						dm.finalregistrationnumber=_documentnumber and dsm.districtcode=_districtcode),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true where total_row.total_rows<>0 OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
									   
					   
				else

				raise notice 'condition failed';
				end if;
				
		else --prticular district and perticular sro
		
				if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
				raise notice 'Documentnumber null';
				return query
				with cte as (select  dsm.districtnamee,sm.sronamee,
				dm.finalregistrationnumber,dm.uploaddocdeedpath  as copy_of_document,
				 null as copy_of_endorsement 
				  from kaveri.documentmaster dm  
						JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
						JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
						where 
						dsm.districtcode=_districtcode and dm.isregistrationcompleted is true and 
						dm.srocode=_srocode and 
						(dm.registrationdatetime::date between
					_fromdate and  _todate )
						and 
						dm.bookid in (1,5,6,7,8,9,10,14)),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true where total_row.total_rows<>0 OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY ;

				elsif 	_documentnumber is not NULL  then

				raise notice 'date null';
				return query
				with cte as (select  dsm.districtnamee,sm.sronamee,
				dm.finalregistrationnumber,dm.uploaddocdeedpath  as copy_of_document,
				 null as copy_of_endorsement 
				  from kaveri.documentmaster dm  
						JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
						JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
						where 
						dm.finalregistrationnumber=_documentnumber and dsm.districtcode=_districtcode and sm.srocode=_srocode),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true 
			where total_row.total_rows<>0 OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
									   
									   
					   
				else

				raise notice 'condition failed';
				end if;
				
		end if;
				
				
						  

END;

$$;


