-- Name: fn_mis_statutory_form10_register_of_unclaimed_doc(bigint, timestamp without time zone, timestamp without time zone, character varying); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_statutory_form10_register_of_unclaimed_doc(_srocode bigint, _fromdate timestamp without time zone DEFAULT NULL::date, _todate timestamp without time zone DEFAULT NULL::date, _documentnumber character varying DEFAULT NULL::character varying) RETURNS TABLE(districtname character varying, sroname character varying, regdate text, refdate text, presenter text, book1regnum character varying, book2regnum character varying, book3regnum character varying, book4regnum character varying, stampduty numeric, dateissuepresenter text, datereturn text, custodyfees text, remarks text, copy_of_document text)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN 

if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
raise notice 'Documentnumber null';
return query
select c.districtnamee as district,
 b.sronamee AS sroname,
  (case when dm.isregistrationcompleted is true then to_char(dm.registrationdatetime, 'DD-MM-YYYY')  end) as regdate,
  (case when ap.currentstatus = 'CD134' then to_char(dm.presentdatetime, 'DD-MM-YYYY') end) as refdate,
  concat_ws(' '::text, e.descriptione, a.firstname, a.middlename, a.lastname) AS  presenter,
   (case when dm.bookid = 1 then dm.finalregistrationnumber end) as book1regnum,
   (case when dm.bookid = 2 then dm.finalregistrationnumber end) as book2regnum,
   (case when dm.bookid = 3 then dm.finalregistrationnumber end) as book3regnum,
   (case when dm.bookid = 4 then dm.finalregistrationnumber end) as book4regnum,
   sum(case when fr.feerulecode = 36 then COALESCE(fr.amountpaid,0) else 0 end) as stampduty,
   null as dateissuepresenter,
   null as datereturn,
   null as custodyfees,
   null as remarks,
   dm.uploaddocdeedpath as copy_of_document
    from 
