CREATE FUNCTION kaverimis.fn_mis_statutory_form10_register_of_unclaimed_doc(_districtcode integer, _srocode bigint, _fromdate timestamp without time zone DEFAULT NULL::date, _todate timestamp without time zone DEFAULT NULL::date, _documentnumber character varying DEFAULT NULL::character varying, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, regdate text, refdate text, presenter text, book1regnum character varying, book2regnum character varying, book3regnum character varying, book4regnum character varying, stampduty numeric, dateissuepresenter text, datereturn text, custodyfees text, remarks text, copy_of_document text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$
 
 
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize);
 
if pagenumber <>-1 and pagesize <>-1 then 
return query
with cte as (select c.districtnamee as district,
b.sronamee AS sroname,
  (case when dm.isregistrationcompleted is true then to_char(dm.registrationdatetime, 'DD-MM-YYYY')  end)
  as regdate,
  (case when ap.currentstatus = 'CD134' then to_char(dm.presentdatetime, 'DD-MM-YYYY') end) as refdate,
  concat_ws(' '::text, e.descriptione, a.firstname, a.middlename, a.lastname) AS  presenter,
   (case when dm.bookid = 1 then dm.finalregistrationnumber end) as book1regnum,
   (case when dm.bookid = 2 then dm.finalregistrationnumber end) as book2regnum,
   (case when dm.bookid = 3 then dm.finalregistrationnumber end) as book3regnum,
   (case when dm.bookid = 4 then dm.finalregistrationnumber end) as book4regnum,
   sum(case when fr.feerulecode = 36 then COALESCE(fr.amountpaid,0) else 0 end) as stampduty,
   null as dateissuepresenter,
   null as datereturn,
   null as custodyfees,
   ap.remarks  as remarks,
   dm.uploaddocdeedpath as copy_of_document
    from 
	kaveri.applicantapplicationdetails ap 
   join	kaveri.documentmaster dm	on ap.applicationnumber = dm.applicationnumber
	JOIN kaveri.sromaster b on b.srocode = dm.srocode 
	join  kaveri.districtmaster c ON c.districtcode = b.districtcode
    join kaveri.feesrequired fr on dm.applicationnumber = fr.applicationnumber
   join kaveri.partyinfo a on a.applicationnumber::text = dm.applicationnumber::text
     LEFT JOIN kaveri.salutationmaster e ON a.salutationid = e.salutationid 
    where 
    dm.ackdatetime is null and dm.isregistrationcompleted=true and ap.currentstatus <>'CD120' and 
    a.ispresenter is true and fr.feerulecode = 36 
	and 
	(
 
                    CASE
 
                    WHEN _districtcode <> 0 THEN  c.districtcode = _districtcode
 
                    ELSE TRUE
 
                    end
 
                    )
			and
				(
 
                    CASE
 
                    WHEN _srocode <> 0 THEN  b.srocode = _srocode
 
                    ELSE TRUE
 
                    end
 
                    )
			 and 
			 (
 
                    CASE
 
                    WHEN _fromdate <> null and _todate<>null  then
                    (dm.registrationdatetime between _fromdate	and _todate + INTERVAL '1 day'  )
 
                    ELSE TRUE
 
                    end
 
                    )
			  and 
			  (
 
                    CASE
 
                    WHEN _documentnumber<>null THEN  dm.finalregistrationnumber=_documentnumber
 
                    ELSE TRUE
 
                    end
 
                    )
    group by c.districtnamee,b.sronamee,dm.srocode,ap.applicationnumber,dm.finalregistrationnumber,pendingdocumentnumber,regdate,
    refdate,book1regnum,book2regnum, book3regnum, book4regnum,e.descriptione,a.firstname, a.middlename, a.lastname,
   dm.uploaddocdeedpath,ap.remarks),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true 
			OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
 
			
elsif  pagenumber =-1 or pagesize =-1 then
 
 
	return query
with cte as (select c.districtnamee as district,
b.sronamee AS sroname,
  (case when dm.isregistrationcompleted is true then to_char(dm.registrationdatetime, 'DD-MM-YYYY')  end)
