   null as datereturn,
   null as custodyfees,
   ap.remarks as remarks,
   dm.uploaddocdeedpath as copy_of_document
    from 
	kaveri.applicantapplicationdetails ap 
   join	kaveri.documentmaster dm	on ap.applicationnumber = dm.applicationnumber
	JOIN kaveri.sromaster b on b.srocode = dm.srocode 
	join  kaveri.districtmaster c ON c.districtcode = b.districtcode
    join kaveri.feesrequired fr on dm.applicationnumber = fr.applicationnumber
   join kaveri.partyinfo a on a.applicationnumber::text = dm.applicationnumber::text
     LEFT JOIN kaveri.salutationmaster e ON a.salutationid = e.salutationid 
    where 
    dm.ackdatetime is null and dm.isregistrationcompleted=true and  ap.currentstatus <>'CD120' and 
    a.ispresenter is true and fr.feerulecode = 36 
	and 
	(
 
                    CASE
 
                    WHEN _districtcode <> 0 THEN  c.districtcode = _districtcode
 
                    ELSE TRUE
 
                    end
 
                    )
			and
				(
 
                    CASE
 
                    WHEN _srocode <> 0 THEN  b.srocode = _srocode
 
                    ELSE TRUE
 
                    end
 
                    )
			 and 
			 (
 
                    CASE
 
                    WHEN _fromdate <> null and _todate<>null  then
                    (dm.registrationdatetime between _fromdate	and _todate + INTERVAL '1 day'  )
 
                    ELSE TRUE
 
                    end
 
                    )
			  and 
			  (
 
                    CASE
 
                    WHEN _documentnumber<>null THEN  dm.finalregistrationnumber=_documentnumber
 
                    ELSE TRUE
 
                    end
 
                    )
    group by c.districtnamee,b.sronamee,dm.srocode,ap.applicationnumber,dm.finalregistrationnumber,pendingdocumentnumber,regdate,
    refdate,book1regnum,book2regnum, book3regnum, book4regnum,e.descriptione,a.firstname, a.middlename, a.lastname,
   dm.uploaddocdeedpath,ap.remarks),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true 
			;
 
 
end if;
 
 
END;
 
$$;


