ALTER FUNCTION kaverimis.fn_mis_statutory_form10_register_of_unclaimed_doc_bck_18122023(_districtcode integer, _srocode bigint, _fromdate timestamp without time zone, _todate timestamp without time zone, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_statutory_form10_register_of_unclaimed_doc_save(bigint, character varying, character varying); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_statutory_form10_register_of_unclaimed_doc_save(_srocode bigint, _documentnumber character varying DEFAULT NULL::character varying, _remarks character varying DEFAULT NULL::character varying) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
v_cnt bigint;
v_form10dataentryid bigint;
BEGIN 
select count(*) into v_cnt from kaverimis.formno10 where documentnumber = _documentnumber;
IF (v_cnt = 0) and _documentnumber is not null  then
insert into kaverimis.formno10 
(
srocode,
documentnumber,
remarks)
values 
(
_srocode,
_documentnumber,
_remarks
) returning form10dataentryid into v_form10dataentryid;
elseif (v_cnt = 1) then
update kaverimis.formno10 set 
remarks=_remarks where
documentnumber=_documentnumber and srocode = _srocode
returning form10dataentryid into v_form10dataentryid;
end if;
return v_form10dataentryid;
end;
$$;


ALTER FUNCTION kaverimis.fn_mis_statutory_form10_register_of_unclaimed_doc_save(_srocode bigint, _documentnumber character varying, _remarks character varying) OWNER TO csgadmin;

--
-- Name: fn_mis_statutory_form1_book_part(bigint, date, date, character varying, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_statutory_form1_book_part(_srocode bigint, _fromdate date DEFAULT NULL::date, _todate date DEFAULT NULL::date, _documentnumber character varying DEFAULT NULL::character varying, _part integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, copy_of_document text, copy_of_endorsement text)
    LANGUAGE plpgsql
    AS $$

DECLARE

BEGIN 

if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
raise notice 'Documentnumber null';

	if(_part=7)then

	return query
	select  distinct dsm.districtnamee,sm.sronamee,
	dm.finalregistrationnumber,dm.uploaddocdeedpath as copy_of_document,null as copy_of_endorsement 
	from kaveri.documentmaster dm  
        JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
        JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
        where dm.srocode=_srocode and dm.registrationdatetime::date >=_fromdate and dm.registrationdatetime::date <=_todate and 
        dm.bookid in (7,8)  and dm.finalregistrationnumber is not null and dm.isregistrationcompleted is true; 
		--and		dm.uploaddocdeedpath is not null;
		
	elseif(_part=9 or _part=10)  then
	raise notice 'fruits data';
		
	return query
		select distinct  dsm.districtnamee,sm.sronamee,
		dm.finalregistrationnumber,
		fd.formiiipath as copy_of_document,
		null as copy_of_endorsement
		from kaveri.documentmaster dm  
        JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
        JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode   
		left join  kaveri.fruits_data_recv_details  fd on dm.applicationnumber=fd.applicationnumber
        where dm.srocode=_srocode and dm.registrationdatetime::date >=_fromdate and dm.registrationdatetime::date <=_todate and 
        dm.bookid=_part  and dm.finalregistrationnumber is not null and dm.isregistrationcompleted is true;
		--and
		--dm.uploaddocdeedpath is not null;
		
	elseif(_part=5) then
	return query
	   select distinct  dsm.districtnamee,
        sm.sronamee,
        dm.finalregistrationnumber,
        dm.uploaddocdeedpath as copy_of_document,
		null as copy_of_endorsement
        from kaveri.documentmaster dm  
        JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
        JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
        join kaveri.anywhere_reg_log arl on dm.applicationnumber = arl.applicationnumber 
        where dm.srocode= _srocode and 
		dm.registrationdatetime::date >=_fromdate and dm.registrationdatetime::date <=_todate
        and  dm.isregistrationcompleted is true;
--and arl.ismemosent is true;   
		
	ELSE

	return query
		select distinct  dsm.districtnamee,sm.sronamee,
		dm.finalregistrationnumber,dm.uploaddocdeedpath as copy_of_document,null as copy_of_endorsement
		from kaveri.documentmaster dm  
        JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
        JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
        where dm.srocode=_srocode and  
        dm.bookid=_part  and dm.finalregistrationnumber=_documentnumber and dm.isregistrationcompleted is true;

  end if;
  
  elseif 	_documentnumber is not NULL and (_fromdate  is NULL and _todate is NULL) then
  
 	if(_part=7)then

	return query
	select distinct  dsm.districtnamee,sm.sronamee,
	dm.finalregistrationnumber,dm.uploaddocdeedpath as copy_of_document,null as copy_of_endorsement 
	from kaveri.documentmaster dm  
        JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
        JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
        where dm.srocode=_srocode and dm.finalregistrationnumber=_documentnumber and 
        dm.bookid in (7,8)  and dm.finalregistrationnumber is not null and dm.isregistrationcompleted is true; 
		--and		dm.uploaddocdeedpath is not null;
		
	elseif(_part=9 or _part=10)  then
		raise notice 'fruits data';
		
	return query
		select distinct  dsm.districtnamee,sm.sronamee,
		dm.finalregistrationnumber,
		fd.formiiipath as copy_of_document,null as copy_of_endorsement
		from kaveri.documentmaster dm  
        JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
        JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode   
		left join  kaveri.fruits_data_recv_details  fd on dm.applicationnumber=fd.applicationnumber
        where dm.srocode=_srocode and  dm.finalregistrationnumber=_documentnumber
        and dm.bookid=_part  and dm.finalregistrationnumber is not null and dm.isregistrationcompleted is true;
		--and
		--dm.uploaddocdeedpath is not null;
		
		elseif(_part=5) then
	return query
	   select distinct  dsm.districtnamee,
        sm.sronamee,
        dm.finalregistrationnumber,
        dm.uploaddocdeedpath as copy_of_document,
		null as copy_of_endorsement
        from kaveri.documentmaster dm  
        JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
        JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
        join kaveri.anywhere_reg_log arl on dm.applicationnumber = arl.applicationnumber 
        where dm.srocode= _srocode and  dm.finalregistrationnumber=_documentnumber
        and  dm.isregistrationcompleted is true;
--and arl.ismemosent is true; 
		
	ELSE

	return query
		select  distinct dsm.districtnamee,sm.sronamee,
		dm.finalregistrationnumber,dm.uploaddocdeedpath as copy_of_document,null as copy_of_endorsement
		from kaveri.documentmaster dm  
        JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
        JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
        where dm.srocode=_srocode and  
        dm.bookid=_part  and dm.finalregistrationnumber=_documentnumber and dm.isregistrationcompleted is true;

 	 end if;
  
  elseif _documentnumber is not NULL and (_fromdate is not NULL and _todate is not NULL) then

	raise notice 'nothing null';

	if(_part=7)then

	return query
	select distinct  dsm.districtnamee,sm.sronamee,
	dm.finalregistrationnumber,dm.uploaddocdeedpath as copy_of_document,null as copy_of_endorsement 
	from kaveri.documentmaster dm  
        JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
        JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
        where dm.srocode=_srocode and dm.registrationdatetime::date >=_fromdate and dm.registrationdatetime::date <=_todate and dm.finalregistrationnumber=_documentnumber and 
        dm.bookid in (7,8)  and dm.finalregistrationnumber is not null and dm.isregistrationcompleted is true; 
		--and		dm.uploaddocdeedpath is not null;
		
	elseif(_part=9 or _part=10)  then
		raise notice 'fruits data';
		
	return query
		select  distinct dsm.districtnamee,sm.sronamee,
		dm.finalregistrationnumber,
		fd.formiiipath as copy_of_document,null as copy_of_endorsement
		from kaveri.documentmaster dm  
        JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
        JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode   
		left join  kaveri.fruits_data_recv_details  fd on dm.applicationnumber=fd.applicationnumber
        where dm.srocode=_srocode and dm.registrationdatetime::date >=_fromdate and dm.registrationdatetime::date <=_todate and  dm.finalregistrationnumber=_documentnumber and
        dm.bookid=_part  and dm.finalregistrationnumber is not null and dm.isregistrationcompleted is true;
		--and
		--dm.uploaddocdeedpath is not null;
		
		elseif(_part=5) then
	return query
	   select distinct  dsm.districtnamee,
        sm.sronamee,
        dm.finalregistrationnumber,
        dm.uploaddocdeedpath as copy_of_document,
		null as copy_of_endorsement
        from kaveri.documentmaster dm  
        JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
        JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
        join kaveri.anywhere_reg_log arl on dm.applicationnumber = arl.applicationnumber 
        where dm.srocode= _srocode and  dm.finalregistrationnumber=_documentnumber and 
		dm.registrationdatetime::date >=_fromdate and dm.registrationdatetime::date <=_todate
        and  dm.isregistrationcompleted is true;
        --and arl.ismemosent is true; 
		
	ELSE

	return query
		select distinct  dsm.districtnamee,sm.sronamee,
		dm.finalregistrationnumber,dm.uploaddocdeedpath as copy_of_document,null as copy_of_endorsement
		from kaveri.documentmaster dm  
        JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
        JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
		where dm.srocode=_srocode and  dm.registrationdatetime::date >=_fromdate and dm.registrationdatetime::date <=_todate and
        dm.bookid=_part  and dm.finalregistrationnumber=_documentnumber and dm.isregistrationcompleted is true;

  	end if;
  
  else

raise notice 'condition failed';
end if;
  
           

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_statutory_form1_book_part(_srocode bigint, _fromdate date, _todate date, _documentnumber character varying, _part integer) OWNER TO csgadmin;

--
-- Name: fn_mis_statutory_form1_book_part(integer, integer, date, date, character varying, integer, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_mis_statutory_form1_book_part(_districtcode integer, _srocode integer, _fromdate date DEFAULT NULL::date, _todate date DEFAULT NULL::date, _documentnumber character varying DEFAULT NULL::character varying, _part integer DEFAULT NULL::integer, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtname character varying, sroname character varying, finalregistrationnumber character varying, copy_of_document text, copy_of_endorsement text, totalcount bigint)
    LANGUAGE plpgsql
    AS $$



declare

PageOffset INTEGER := 0;


BEGIN 
	PageOffset := ((pagenumber - 1) * pagesize);

	if _districtcode=0 then --All District and All srocode
	
	
			if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
			raise notice 'Documentnumber null';

				if(_part=7)then

				return query
				with cte as(select  distinct dsm.districtnamee,sm.sronamee,
				dm.finalregistrationnumber,dm.uploaddocdeedpath as copy_of_document,null as copy_of_endorsement 
				from kaveri.documentmaster dm  
					JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
					JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
					where 
					dm.bookid in (7,8) and 
					dm.isregistrationcompleted is true and 
					--dm.srocode=_srocode and 
					(dm.registrationdatetime between _fromdate and _todate))
					,cte_count as (select count(*) as total_rows from cte)
					select * from cte
					join (select total_rows from cte_count) total_row on true OFFSET PageOffset
