				FETCH NEXT pagesize ROWS ONLY; 
					
					
				elsif(_part=9 or _part=10)  then
					raise notice 'fruits data';
					
				return query
					with cte as (select distinct  dsm.districtnamee,sm.sronamee,
					dm.finalregistrationnumber,
					fd.formiiipath as copy_of_document,null as copy_of_endorsement
					from kaveri.documentmaster dm  
					JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
					JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode   
					left join  kaveri.fruits_data_recv_details  fd on dm.applicationnumber=fd.applicationnumber
					where 
					dsm.districtcode=_districtcode and 
					dm.srocode=_srocode and 
					dm.finalregistrationnumber=_documentnumber
					and dm.bookid=_part   and dm.isregistrationcompleted is true)	
					,cte_count as (select count(*) as total_rows from cte)
					select * from cte
					join (select total_rows from cte_count) total_row on true OFFSET PageOffset
					FETCH NEXT pagesize ROWS ONLY;
					
					
					elseif(_part=5) then
				return query
				   with cte as (select distinct  dsm.districtnamee,
					sm.sronamee,
					dm.finalregistrationnumber,
					dm.uploaddocdeedpath as copy_of_document,
					null as copy_of_endorsement
					from kaveri.documentmaster dm  
					JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
					JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
					join kaveri.anywhere_reg_log arl on dm.applicationnumber = arl.applicationnumber 
					where 
					
					
					dm.finalregistrationnumber=_documentnumber
					and  dm.isregistrationcompleted is true)
					,cte_count as (select count(*) as total_rows from cte)
					select * from cte
					join (select total_rows from cte_count) total_row on true OFFSET PageOffset
					FETCH NEXT pagesize ROWS ONLY;
			--and arl.ismemosent is true; 
					
				ELSE

				return query
					with cte as (select  distinct dsm.districtnamee,sm.sronamee,
					dm.finalregistrationnumber,dm.uploaddocdeedpath as copy_of_document,null as copy_of_endorsement
					from kaveri.documentmaster dm  
					JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
					JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
					where 
					--dm.districtcode=_districtcode and 
					--dm.srocode=_srocode and  
					dm.bookid=_part  and dm.finalregistrationnumber=_documentnumber and dm.isregistrationcompleted is true)
					,cte_count as (select count(*) as total_rows from cte)
					select * from cte
					join (select total_rows from cte_count) total_row on true OFFSET PageOffset
					FETCH NEXT pagesize ROWS ONLY;

				 end if;
				
					else

						raise notice 'condition failed';
				end if;
				
	end if;
	
	
			
	
		
			  
           

END;

$$;


ALTER FUNCTION kaverimis.fn_mis_statutory_form1_book_part_bck(_districtcode integer, _srocode integer, _fromdate date, _todate date, _documentnumber character varying, _part integer, pagenumber integer, pagesize integer) OWNER TO postgres;

