    LANGUAGE plpgsql
    AS $$


DECLARE

BEGIN 

_todate:=(_todate+'1 day'::interval);
if  _documentnumber is NULL and (_fromdate is not NULL and _todate is not NULL) then
raise notice 'Documentnumber null';
return query
select  dsm.districtnamee,sm.sronamee,
dm.finalregistrationnumber,null as ref_book_5,dm.uploaddocdeedpath  as scanned_copy,null as copy_of_endorsement 
  from kaveri.documentmaster dm  
        JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
        JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
        where dm.srocode=_srocode and dm.registrationdatetime >=_fromdate and dm.registrationdatetime <_todate and 
        dm.bookid=3  and dm.finalregistrationnumber is not null and dm.isregistrationcompleted is true;
elseif 	_documentnumber is not NULL and (_fromdate  is NULL and _todate is NULL) then

raise notice 'date null';
return query
select  dsm.districtnamee,sm.sronamee,
dm.finalregistrationnumber,null as ref_book_5,dm.uploaddocdeedpath  as scanned_copy,null as copy_of_endorsement 
  from kaveri.documentmaster dm  
        JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
        JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
        where dm.srocode=_srocode and dm.finalregistrationnumber=_documentnumber and 
        dm.bookid=3  and dm.finalregistrationnumber is not null and dm.isregistrationcompleted is true;
		
elseif _documentnumber is not NULL and (_fromdate is not NULL and _todate is not NULL) then

raise notice 'nothing null';

return query
select  dsm.districtnamee,sm.sronamee,
dm.finalregistrationnumber,null as ref_book_5,dm.uploaddocdeedpath  as scanned_copy,null as copy_of_endorsement 
  from kaveri.documentmaster dm  
        JOIN kaveri.sromaster sm ON dm.srocode = sm.srocode
        JOIN kaveri.districtmaster dsm ON sm.districtcode = dsm.districtcode        
        where dm.srocode=_srocode and dm.registrationdatetime >=_fromdate and dm.registrationdatetime <_todate and dm.finalregistrationnumber=_documentnumber and 
        dm.bookid=3  and dm.finalregistrationnumber is not null and dm.isregistrationcompleted is true;
       
       
else

raise notice 'condition failed';
end if;
          

END;

$$;


