ALTER FUNCTION kaverimis.fn_mis_statutory_form4_book4(_districtcode integer, _srocode integer, _fromdate date, _todate date, _documentnumber character varying, pagenumber integer, pagesize integer) OWNER TO postgres;

--
-- Name: fn_mis_summ_of_imported_properties_from_other_departments(integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_summ_of_imported_properties_from_other_departments(_srocode integer, _districtcode integer, _registrationfromdatetime timestamp without time zone, _registrationtodatetime timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(districtnamee character varying, sronamee character varying, total_cnt bigint, bhoomi_cnt bigint, eswathu_cnt bigint, eaasti_cnt bigint, mojini_cnt bigint, upor integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize); 	
return query 
select distinct
    dm.districtnamee,
    s.sronamee,
    total_cnt.total_cnt,
    bhoomi_cnt.bhoomi_cnt,
    eswathu_cnt.eswathu_cnt,
    eaasti_cnt.eaasti_cnt,
    mojini_cnt.mojini_cnt,
	0 upor
from kaveri.documentmaster d
join kaveri.sromaster s on d.srocode = s.srocode
join kaveri.districtmaster dm on s.districtcode = dm.districtcode,
(select count(*) as total_cnt from kaveri.documentmaster d1
    where d1.isregistrationcompleted = true
    and d1.registrationdatetime >= _registrationfromdatetime  and d1.registrationdatetime <= _registrationtodatetime) as total_cnt,
(select count(d2.documentid) as bhoomi_cnt from kaveri.documentmaster d2
    join kaveri.propertymaster p on d2.documentid = p.documentid
    where p.propertytypeid = 17
    and d2.registrationdatetime >= _registrationfromdatetime  and d2.registrationdatetime <= _registrationtodatetime ) as bhoomi_cnt,
(select count(*) as eswathu_cnt from kaveri.documentmaster d3
    join kaveri.eaasti_eswatuxmllog ee1 on d3.documentid = ee1.documentid
    where d3.registrationdatetime >= _registrationfromdatetime  and d3.registrationdatetime <= _registrationtodatetime 
    and lower(ee1."xml") like '%swathu%') as eswathu_cnt,
(select count(*) as eaasti_cnt from kaveri.documentmaster d4  
    join kaveri.eaasti_eswatuxmllog ee2 on d4.documentid = ee2.documentid
    where d4.registrationdatetime >= _registrationfromdatetime  and d4.registrationdatetime <= _registrationtodatetime
    and ee2.xml like '%easthi%') 
	as eaasti_cnt,
(select count(*) as mojini_cnt from kaveri.documentmaster d5
    join kaveri.mojanixml m on d5.documentid = m.documentid
    where d5.registrationdatetime >= _registrationfromdatetime  and d5.registrationdatetime <= _registrationtodatetime ) as mojini_cnt
--join kaveri.eaasti_eswatuxmllog ee on ee.documentid = d.documentid
--join kaveri.mojanixml m on m.documentid = d.documentid
where d.isregistrationcompleted = true and d.srocode = _srocode  and s.districtcode = _districtcode
and d.registrationdatetime >= _registrationfromdatetime  and d.registrationdatetime <= _registrationtodatetime ;
END;
$$;


ALTER FUNCTION kaverimis.fn_mis_summ_of_imported_properties_from_other_departments(_srocode integer, _districtcode integer, _registrationfromdatetime timestamp without time zone, _registrationtodatetime timestamp without time zone, pagenumber integer, pagesize integer) OWNER TO csgadmin;

--
-- Name: fn_mis_surcharge_and_cess_details(integer, integer, integer, timestamp without time zone, timestamp without time zone, integer, integer); Type: FUNCTION; Schema: kaverimis; Owner: csgadmin
--

CREATE FUNCTION kaverimis.fn_mis_surcharge_and_cess_details(_districtcode integer, _srocode integer, _regarticlecode integer, _fromdate timestamp without time zone, _todate timestamp without time zone, pagenumber integer DEFAULT NULL::integer, pagesize integer DEFAULT NULL::integer) RETURNS TABLE(sroname character varying, articlename character varying, propertyvalue numeric, govtduty numeric, additionalduty_urban numeric, additionalduty_rural numeric, cessduty numeric, totalstampduty numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
PageOffset INTEGER := 0;
BEGIN	
PageOffset := ((pagenumber - 1) * pagesize); 	
if _regarticlecode = 0 then
return query
select distinct
b.sronamee as sroname,
e.articlenamee as articlename,
a.marketvalue as propertyvalue,
a.govtduty,
( 2 * marketvalue)
 as additionalduty_urban,
(3 * marketvalue)
 additionalduty_rural,
a.cessduty,
(( 2 * marketvalue)
+  (3 * marketvalue)
  + a.cessduty + a.govtduty) as totalstampduty
from kaveri.propertymaster a left join kaveri.sromaster b on a.srocode = b.srocode
left join kaveri.districtmaster c on b.districtcode = c.districtcode
left join kaveri.documentmaster d on a.documentid = d.documentid
left join kaveri.registrationarticles e on a.regarticlecode = e.regarticlecode
left join kaveri.stamprules f on a.stampruleid = f.stampruleid
where d.registrationdatetime >= _fromdate and d.registrationdatetime <= _todate
and b.districtcode = _districtcode and b.srocode = _srocode 
and f.issurcharge = true;
elsif (_regarticlecode > 0) then
return query
select distinct
b.sronamee as sroname,
e.articlenamee as articlename,
a.marketvalue as propertyvalue,
a.govtduty,
( 2 * marketvalue)
 as additionalduty_urban,
(3 * marketvalue)
 additionalduty_rural,
a.cessduty,
(( 2 * marketvalue)
+  (3 * marketvalue)
  + a.cessduty + a.govtduty) as totalstampduty
from kaveri.propertymaster a left join kaveri.sromaster b on a.srocode = b.srocode
left join kaveri.districtmaster c on b.districtcode = c.districtcode
left join kaveri.documentmaster d on a.documentid = d.documentid
left join kaveri.registrationarticles e on a.regarticlecode = e.regarticlecode
left join kaveri.stamprules f on a.stampruleid = f.stampruleid
where d.registrationdatetime >= _fromdate and d.registrationdatetime <= _todate
and b.districtcode = _districtcode and b.srocode = _srocode and  a.regarticlecode = _regarticlecode 
and f.issurcharge = true;
end if;
END;
$$;


