 where (d.executiondatetime between _from_date and _to_date)
and d.isregistrationcompleted is true 
 --and pi.thumbpath IS NOT NULL 
 and d.srocode=_srocode and
 pi.partytypeid = 2
 group by d.applicationnumber)as prt_exec  on dm.applicationnumber=prt_exec.applicationnumber

where (dm.executiondatetime between _from_date and _to_date) and dm.isregistrationcompleted is true
and dm.srocode=_srocode),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY; 

 
 elseif _finalregistrationnumber is not null then
raise notice 'date null'; 
return query
  with cte as (select 
c.districtnamee as district,
 b.sronamee AS sroname,
dm.uploaddocdeedpath,
(to_char(dm.executiondatetime, 'YYYY'::text) || ' '::text) ||  bt.booknameenglish ||' '|| dm.finalregistrationnumber AS yearofentry_bookid,
prt_thumb.name_of_person,
prt_exec.name_of_exec,
prt_exec.thumbpath,
prt_exec.photopath,
dm.finalregistrationnumber,
null::character varying as servicename

from 

kaveri.documentmaster dm
join  kaveri.sromaster b on dm.srocode = b.srocode and b.districtcode = _districtcode
join kaveri.districtmaster c  ON c.districtcode = b.districtcode
JOIN kaveri.booktypemaster bt on dm.bookid = bt.bookid 

join 
(select d.applicationnumber,
 string_agg(distinct COALESCE(pi.firstname,' ')||' '||coalesce(pi.middlename,' ')||' '||COALESCE(pi.lastname,' ')||
			' '||coalesce(pi.thumbremarks,' '),',') as name_of_person
 from kaveri.partyinfo pi 
 join kaveri.documentmaster d on pi.applicationnumber = d.applicationnumber 
where d.finalregistrationnumber=_finalregistrationnumber
and d.isregistrationcompleted is true
 --and pi.thumbpath IS NOT NULL 
 and d.srocode=_srocode
 group by d.applicationnumber 
)
 as prt_thumb on dm.applicationnumber=prt_thumb.applicationnumber
join
(select d.applicationnumber,
 string_agg(distinct COALESCE(pi.firstname,' ')||' '||coalesce(pi.middlename,' ')||' '||COALESCE(pi.lastname,' ')||
			' '||coalesce(pi.thumbremarks,' '),',') as name_of_exec,
 (string_to_array( string_agg(distinct pi.thumbpath,','),','))[1]::character varying as thumbpath,
 (string_to_array(string_agg(distinct pi.photopath,','),','))[1]::character varying as photopath
 from kaveri.partyinfo pi 
 join kaveri.documentmaster d on pi.applicationnumber = d.applicationnumber
 where d.finalregistrationnumber=_finalregistrationnumber
and d.isregistrationcompleted is true 
 --and pi.thumbpath IS NOT NULL 
 and d.srocode=_srocode and
 pi.partytypeid = 2
 group by d.applicationnumber)as prt_exec  on dm.applicationnumber=prt_exec.applicationnumber

where dm.finalregistrationnumber=_finalregistrationnumber and dm.isregistrationcompleted is true and dm.srocode=_srocode),cte_count as (select count(*) as total_rows from cte)
			select * from cte
			right join (select total_rows from cte_count) total_row on true OFFSET PageOffset
				FETCH NEXT pagesize ROWS ONLY;
	 end if;
end if;
END;
$$;


