CREATE FUNCTION kaverimis.fn_update_download_report_status(_reportfilepath character varying, _isreportdownloaded boolean) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE

reportid bigint;
BEGIN	
	
	
update  kaverimis.report_queue  set isreportdownloaded=_isreportdownloaded
where   reportfilepath=_reportfilepath returning rid into  reportid;


return reportid;
end;
