-- Name: fn_update_report_queue(bigint, text); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_update_report_queue(_rid bigint, _reportfilepath text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare
v_cnt bigint;
v_id bigint;
begin




		update kaverimis.report_queue set reportfilepath=_reportfilepath,status='Success'
		
		where rid=_rid 
		returning rid into v_id ;
		
	
   

raise notice 'Succefully inserted  into table misreportqueue ';
return v_id;
EXCEPTION
        WHEN others then
        	RAISE EXCEPTION 'Error inserting data into misreportqueue: %', SQLERRM;
            return -1;
  END;
$$;


ALTER FUNCTION kaverimis.fn_update_report_queue(_rid bigint, _reportfilepath text) OWNER TO postgres;

--
-- Name: fn_update_report_queue(text, text, timestamp without time zone, timestamp without time zone, bigint, text); Type: FUNCTION; Schema: kaverimis; Owner: postgres
--

CREATE FUNCTION kaverimis.fn_update_report_queue(_requestedapi text, _requestedreport text, _fromdate timestamp without time zone, _todate timestamp without time zone, _requesteduser bigint, _reportfilepath text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
Declare
v_cnt bigint;
v_id bigint;
begin
select count(*) into v_cnt 
from kaverimis.report_queue
where requestedapi=_requestedapi and 
requestedreport=_requestedreport and fromdate=to_char(_fromdate,'yyyy-mm-dd')::date 
and todate=to_char(_todate,'yyyy-mm-dd')::date  and requesteduser=_requesteduser;


if (v_cnt =0) then

	raise notice 'No matching record found';
	return 0;
    
	
else
		update kaverimis.report_queue set reportfilepath=_reportfilepath,status='Success'
		
		where requestedapi=_requestedapi and 
	requestedreport=_requestedreport and fromdate=to_char(_fromdate,'yyyy-mm-dd')::date 
	and todate=to_char(_todate,'yyyy-mm-dd')::date  and requesteduser=_requesteduser
		returning rid into v_id ;
		
	
   
end if;
raise notice 'Succefully inserted  into table misreportqueue ';
return v_id;
EXCEPTION
        WHEN others then
        	RAISE EXCEPTION 'Error inserting data into misreportqueue: %', SQLERRM;
            return -1;
  END;
$$;


