--
-- Name: get_district_dashboard_report1(text, text); Type: FUNCTION; Schema: kaverimis; Owner: manjunathswamy
--

CREATE FUNCTION kaverimis.get_district_dashboard_report1(p_report_type text, p_period text) RETURNS TABLE(district_name text, period text, application_received bigint, document_registered bigint, compliance_percent numeric, revenue_earned numeric, average_fees numeric, female bigint, male bigint, other_institute bigint, min_time interval, max_time interval, avg_time interval, median_time interval)
    LANGUAGE plpgsql
    AS $_$
declare
    v_start timestamp;
    v_end timestamp;
    v_year int;
begin
    if p_report_type = 'monthly' then
        if p_period is null or p_period !~ '^\d{2}-\d{4}$' then
            raise exception 'Provide p_period in mm-yyyy format';
        end if;

        v_start := date_trunc('month', to_date(p_period, 'MM-YYYY'));
        v_end := v_start + interval '1 month';

    elsif p_report_type = 'yearly' then
        if p_period is null or p_period !~ '^\d{4}$' then
            raise exception 'Provide year in YYYY format';
        end if;

        v_year := p_period::int;
        v_start := make_date(v_year, 4, 1);
        v_end := make_date(v_year + 1, 4, 1);

    else
        raise exception 'Invalid report_type';
    end if;

    return query
    with app_base as (
        select distinct
            a.applicationnumber,
            s.districtcode
        from kaveri.applicantapplicationdetails a
        join kaveri.sromaster s
            on s.srocode = a.srocode
        where a.inserteddatetime >= v_start
          and a.inserteddatetime < v_end
          and coalesce(a.isdeleted, false) = false
    ),

    app_received as (
        select
            ab.districtcode,
            count(distinct ab.applicationnumber)::bigint as application_received
        from app_base ab
        group by ab.districtcode
    ),

    registered_docs_base as (
        select distinct
            d.applicationnumber,
            s.districtcode,
            d.registrationdatetime,
            d.inserteddatetime
        from kaveri.documentmaster d
        join app_base ab
            on ab.applicationnumber = d.applicationnumber
        join kaveri.sromaster s
            on s.srocode = d.srocode
        where d.isregistrationcompleted = true
          and d.inserteddatetime >= v_start
          and d.inserteddatetime < v_end
    ),

    document_count as (
        select
            r.districtcode,
            count(distinct r.applicationnumber)::bigint as document_registered,
            min(r.registrationdatetime - r.inserteddatetime) as min_time,
            max(r.registrationdatetime - r.inserteddatetime) as max_time,
            avg(r.registrationdatetime - r.inserteddatetime) as avg_time,
            percentile_cont(0.5) within group (
                order by r.registrationdatetime - r.inserteddatetime
            ) as median_time
        from registered_docs_base r
        group by r.districtcode
    ),

    gender_count as (
        select
            r.districtcode,
            count(*) filter (where p.sex = 0)::bigint as female,
            count(*) filter (where p.sex = 1)::bigint as male,
            count(*) filter (where p.sex = 3)::bigint as other_institute
        from registered_docs_base r
        join kaveri.partyinfo p
            on p.applicationnumber = r.applicationnumber
        group by r.districtcode
    ),

    revenue as (
        select
            r.districtcode,
            coalesce(sum(e.totalamount), 0)::numeric as revenue_earned
        from registered_docs_base r
        join kaveri.ams_reg_epaymenttransdetails e
            on e.applicationnumber = r.applicationnumber
        group by r.districtcode
    )

    select
        dm.districtnamee::text as district_name,

        case
            when p_report_type = 'monthly' then to_char(v_start, 'Mon-YYYY')
            else 'FY ' || p_period || '-' || (p_period::int + 1)
        end as period,

        coalesce(ar.application_received, 0) as application_received,
        coalesce(dc.document_registered, 0) as document_registered,

        case
            when coalesce(ar.application_received, 0) = 0 then 0
            else round(
                coalesce(dc.document_registered, 0)::numeric
                / ar.application_received::numeric * 100,
                2
            )
        end as compliance_percent,

        coalesce(rv.revenue_earned, 0) as revenue_earned,

        case
            when coalesce(dc.document_registered, 0) = 0 then 0
            else round(
                coalesce(rv.revenue_earned, 0)::numeric
                / dc.document_registered::numeric,
                2
            )
        end as average_fees,

        coalesce(gc.female, 0) as female,
        coalesce(gc.male, 0) as male,
        coalesce(gc.other_institute, 0) as other_institute,
        dc.min_time,
        dc.max_time,
        dc.avg_time,
        dc.median_time

    from kaveri.districtmaster dm
    left join app_received ar
        on ar.districtcode = dm.districtcode
    left join document_count dc
        on dc.districtcode = dm.districtcode
    left join gender_count gc
        on gc.districtcode = dm.districtcode
    left join revenue rv
        on rv.districtcode = dm.districtcode
    order by dm.districtnamee;

end;
$_$;


ALTER FUNCTION kaverimis.get_district_dashboard_report1(p_report_type text, p_period text) OWNER TO manjunathswamy;

--
-- Name: sp_insert_doc_revenuereport_flat(); Type: PROCEDURE; Schema: kaverimis; Owner: postgres
--

CREATE PROCEDURE kaverimis.sp_insert_doc_revenuereport_flat()
    LANGUAGE plpgsql
    AS $$
declare
	p_start_date DATE = '2023-04-01';
    p_end_date DATE = current_date - 1;
    v_current_start DATE;
    v_current_end DATE;
BEGIN
	v_current_start := p_start_date;
	WHILE v_current_start < p_end_date
		loop
			v_current_end := (v_current_start + INTERVAL '1 month' - INTERVAL '1 day')::DATE;
			
			IF v_current_end > p_end_date THEN
            	v_current_end := p_end_date;
        	END IF;

        	RAISE NOTICE 'Processing from % to %', v_current_start, v_current_end;
				insert into kaverimis.document_revenue_flat(applicationnumber ,registrationdatetime ,srocode,feerulecode ,totalamount,applicationtypeid)
				select d.applicationnumber ,d.registrationdatetime ,s.srocode,ams.feerulecode ,ams.totalamount,a.applicationtypeid
				from kaveri.documentmaster d
				join kaveri.sromaster s on s.srocode = d.srocode
				join kaveri.applicantapplicationdetails a on a.applicationnumber = d.applicationnumber
				JOIN kaveri.ams_reg_epaymenttransdetails ams ON ams.applicationnumber = d.applicationnumber
				JOIN kaveri.ams_reg_epaymentbankackdetails amk ON ams.deptreferencecode = amk.deptreferencecode
				where d.registrationdatetime::date between v_current_start and v_current_end 
				and d.isregistrationcompleted = true and ams.isdelete = false 
				AND amk.paymentstatuscode IN ('10700066','10700072');commit;
			v_current_start := (v_current_start + INTERVAL '1 month')::DATE;
		END LOOP;
    RAISE NOTICE 'Completed processing from % to %', p_start_date, p_end_date;
END;
$$;


ALTER PROCEDURE kaverimis.sp_insert_doc_revenuereport_flat() OWNER TO postgres;

--
-- Name: sp_insert_mis_daily_register_of_fees_statutory_docreg_12(timestamp without time zone, timestamp without time zone); Type: PROCEDURE; Schema: kaverimis; Owner: postgres
--

CREATE PROCEDURE kaverimis.sp_insert_mis_daily_register_of_fees_statutory_docreg_12(IN _fromdate timestamp without time zone, IN _todate timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
 

DECLARE
PageOffset INTEGER := 0;
v_record record; 
--v_array text[];
BEGIN	
for v_record in (select applicationnumber from kaveri.documentmaster d where d.registrationdatetime::date>=_fromdate  and d.registrationdatetime::date<=_todate
and d.bookid in (1,2,3,4) and isregistrationcompleted = true)
loop
raise notice 'applicationnumber %',v_record.applicationnumber;
--v_array:=array_append(v_array,v_record.applicationnumber);
insert into kaveri.revised_form_7_statutory_doc_reg
with cte as (
			with dm as (
					select d2.districtnamee,d.applicationnumber, d.registrationdatetime, d.finalregistrationnumber, d.bookid, d.presentdatetime, d.srocode,s.sronamee
					from kaveri.documentmaster d
					join kaveri.sromaster s on d.srocode = s.srocode
                    join kaveri.districtmaster d2 on d2.districtcode = s.districtcode
					where d.applicationnumber=v_record.applicationnumber
				),
				success_txns as (
					select distinct e.deptreferencecode
					from kaveri.ams_reg_epaymenttransdetails e
					join kaveri.ams_reg_epaymentbankackdetails b on b.deptreferencecode = e.deptreferencecode
					where b.paymentstatuscode in ('10700066','10700072')
					  and e.isdelete = false
					  and e.applicationnumber =v_record.applicationnumber
				),
				pm as (
					select
						applicationnumber,
						sum(totalarea) as totalarea,
						coalesce(sum(sroconsideration),0) as consideration,
						coalesce(sum(sromarketvalue),0) as marketvalue
					from kaveri.propertymaster
					where applicationnumber =v_record.applicationnumber
					  --and totalarea <= 0.125
					group by applicationnumber
				),
				epay as (
					select
						e.applicationnumber,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (35,36,64,89,91,92,101,107,110,138)),0) as stampduty,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (59,100)),0) as cessduty,
						coalesce(sum(e.totalamount) filter (where e.feerulecode in (1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109)),0) as feesforregistrationofdocs,
						coalesce(sum(e.totalamount) filter (where e.feerulecode = 2),0) as scanningfee,
						coalesce(sum(e.totalamount) filter (where e.feerulecode = 6),0) as mutationfee
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.applicationnumber =v_record.applicationnumber
					  and e.isdelete = false
					group by e.applicationnumber
				),
				surcharge as (
					select e.applicationnumber, sum(e.totalamount) as totalsurcharge
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.isdelete = false
					  and e.feerulecode in (58,99)
					  and e.applicationnumber =v_record.applicationnumber
					group by e.applicationnumber
				),
				has_taluk as (
					select pm.applicationnumber, bool_or(pnd.currentpropertytypeid = 60) as has_taluk
					from kaveri.propertymaster pm
					join kaveri.propertynumberdetails pnd on pnd.propertyid = pm.propertyid
					where pm.applicationnumber =v_record.applicationnumber
					group by pm.applicationnumber
				),
				bk as (
					select e.applicationnumber, sum(e.totalamount) as feesremittedtotreasury
					from kaveri.ams_reg_epaymenttransdetails e
					join success_txns s using (deptreferencecode)
					where e.isdelete = false
					  and e.applicationnumber =v_record.applicationnumber
					group by e.applicationnumber
				)
				select d.districtnamee,
					d.sronamee,
					null::varchar as finalregistrationnumber,
					d.applicationnumber as applicationnumber2,
					d.presentdatetime::text as presentationdatetime,
					pr.presenternamee as presenter_name,
					art.description_of_docs as description_of_document,
					pm.consideration::numeric as considerationamount,
					pm.marketvalue::bigint as marketvalue,
					ep.stampduty::numeric as stampduty,
					ep.cessduty::numeric as cess,
					case when h.has_taluk then 0 else coalesce(s.totalsurcharge,0) end::numeric as surcharge_duty_muncipal,
					case when h.has_taluk then coalesce(s.totalsurcharge,0) else 0 end::numeric as surcharge_duty_taluk,
--					total_duty::numeric,
					coalesce(ep.stampduty::numeric + ep.cessduty::numeric + s.totalsurcharge::numeric,0) as total_duty,
					d.finalregistrationnumber::varchar as documentnumber,
					d.bookid::varchar as bookid,
					null::text as volumenumber,
					d.registrationdatetime::text as dateofcompletion,
					d.registrationdatetime::text as dateofreturn,
					ep.feesforregistrationofdocs::numeric as registrationfees,
					null::numeric as feescopygranted,
					ep.scanningfee::numeric as miscfees,
					null::numeric as otherstampduty,
					null::numeric as miscarticlefees,
					(COALESCE(ep.feesforregistrationofdocs,0)
						+ COALESCE(ep.scanningfee,0))::numeric as total_fees, --sum
					bk.feesremittedtotreasury::numeric as treasury_fees,
					bklast.transactiondate::text as feedate_treasury,
					null::text as dailymutationreceipts,
					ep.mutationfee::numeric as mutationfees,
					mut.mutationfeeremittedtotreasurydate::text as mutationfeedate,
					ar.copiesofmemo::text as transmission_of_memorandum,
					--ar.officename as transmission_of_memoranda,
					ar.memoacceptingoffice::text as transmission_of_memoranda,
					  (coalesce(ep.stampduty,0)
					  + coalesce(ep.cessduty,0)
					  + coalesce(case when h.has_taluk then 0 else s.totalsurcharge end,0)
					  + coalesce(case when h.has_taluk then s.totalsurcharge else 0 end,0)
					  + coalesce(ep.feesforregistrationofdocs,0)
					  + coalesce(ep.scanningfee,0)
					  + coalesce(ep.mutationfee,0))::bigint as total_amount_collected,
					null::text as signature_of_register,
					null::text as remarks,
					null::text as copy_of_document
					--pm.totalarea,	
					--ar.memosentdate,
					--ar.memonumber,
					--ar.memoaccepteddate
				from dm d
				left join pm on pm.applicationnumber = d.applicationnumber
				left join epay ep on ep.applicationnumber = d.applicationnumber
				left join surcharge s on s.applicationnumber = d.applicationnumber
				left join has_taluk h on h.applicationnumber = d.applicationnumber
				left join bk on bk.applicationnumber = d.applicationnumber
				
				left join lateral (
					select b.amount as feesremittedtotreasury, b.transactiontimestamp::date as transactiondate
					from kaveri.ams_reg_epaymenttransdetails e2
					join kaveri.ams_reg_epaymentbankackdetails b on b.deptreferencecode = e2.deptreferencecode
					where e2.applicationnumber = d.applicationnumber
					  and e2.isdelete = false
					  and b.paymentstatuscode in ('10700066','10700072')
					order by b.transactiontimestamp desc
					limit 1
				) bklast on true
				
				left join lateral (
					select coalesce(nullif(p2.firstname,''), nullif(p1.firstname,''), p.firstname) as presenternamee
					from kaveri.partyinfo p
					left join kaveri.partyinfo p1 on p.partyid = p1.linkpartyid
					left join kaveri.partyinfo p2 on p1.partyid = p2.linkpartyid
					where p.applicationnumber = d.applicationnumber and p.ispresenter = true
					order by p.partyid
					limit 1
				) pr on true
				
				left join lateral (
					select s.articlenamee as description_of_docs
					from (
						select distinct stamparticlecode
						from kaveri.propertymaster
						where applicationnumber = d.applicationnumber
						order by stamparticlecode
						limit 1
					) pmx
					join kaveri.stamparticles s on s.stamparticlecode = pmx.stamparticlecode
				) art on true
				
				left join lateral (
					select min(t.inserteddatetime)::date as mutationfeeremittedtotreasurydate
					from kaveri.ams_reg_epaymenttransdetails t
					join success_txns st using (deptreferencecode)
					where t.applicationnumber = d.applicationnumber
					  and t.feerulecode = 6
					  and t.isdelete = false
				) mut on true
				left join lateral (
					select
						a.newapplicationnumber as copiesofmemo,
						a.memosentdatetime::date as memosentdate,
						a.memoaccepteddatetime::date as memoaccepteddate,
						d2.finalregistrationnumber as memonumber,
						s1.sronamee as officename,
						s2.sronamee as memoacceptingoffice
					from kaveri.anywhere_reg_log a
					left join kaveri.documentmaster d2 on d2.applicationnumber = a.newapplicationnumber
					left join kaveri.sromaster s1 on s1.srocode = a.srocode
					left join kaveri.sromaster s2 on s2.srocode = a.regsrocode
					where a.applicationnumber = d.applicationnumber
					order by a.memosentdatetime desc
					limit 1
				) ar on true
				order by d.finalregistrationnumber)
				select cte.*,
                1 as totalcount
                from cte;

end loop;
commit;
--return v_array;
END;

$$;


ALTER PROCEDURE kaverimis.sp_insert_mis_daily_register_of_fees_statutory_docreg_12(IN _fromdate timestamp without time zone, IN _todate timestamp without time zone) OWNER TO postgres;

--
-- Name: sp_insert_mis_daily_register_of_fees_statutory_docreg_13(); Type: PROCEDURE; Schema: kaverimis; Owner: postgres
--

CREATE PROCEDURE kaverimis.sp_insert_mis_daily_register_of_fees_statutory_docreg_13()
    LANGUAGE plpgsql
    AS $$
 

DECLARE
PageOffset INTEGER := 0;
v_record record; 
--v_array text[];
BEGIN 
for v_record in (select applicationnumber from kaveri.documentmaster d where d.registrationdatetime::date=current_date
and d.bookid in (1,2,3,4) and isregistrationcompleted = true)
loop
raise notice 'applicationnumber %',v_record.applicationnumber;
--v_array:=array_append(v_array,v_record.applicationnumber);
insert into kaveri.revised_form_7_statutory_doc_reg
with cte as (
   with dm as (
     select d2.districtnamee,d.applicationnumber, d.registrationdatetime, d.finalregistrationnumber, d.bookid, d.presentdatetime, d.srocode,s.sronamee
     from kaveri.documentmaster d
     join kaveri.sromaster s on d.srocode = s.srocode
                    join kaveri.districtmaster d2 on d2.districtcode = s.districtcode
     where d.applicationnumber=v_record.applicationnumber
    ),
    success_txns as (
     select distinct e.deptreferencecode
     from kaveri.ams_reg_epaymenttransdetails e
     join kaveri.ams_reg_epaymentbankackdetails b on b.deptreferencecode = e.deptreferencecode
     where b.paymentstatuscode in ('10700066','10700072')
       and e.isdelete = false
       and e.applicationnumber =v_record.applicationnumber
    ),
    pm as (
     select
      applicationnumber,
      sum(totalarea) as totalarea,
      coalesce(sum(sroconsideration),0) as consideration,
      coalesce(sum(sromarketvalue),0) as marketvalue
     from kaveri.propertymaster
     where applicationnumber =v_record.applicationnumber
       --and totalarea <= 0.125
     group by applicationnumber
    ),
    epay as (
     select
      e.applicationnumber,
      coalesce(sum(e.totalamount) filter (where e.feerulecode in (35,36,64,89,91,92,101,107,110,138)),0) as stampduty,
      coalesce(sum(e.totalamount) filter (where e.feerulecode in (59,100)),0) as cessduty,
      coalesce(sum(e.totalamount) filter (where e.feerulecode in (1,3,4,5,7,8,9,13,14,15,16,17,18,19,20,22,23,24,25,26,27,28,30,31,34,57,63,65,88,90,93,94,95,96,97,98,102,103,106,108,109)),0) as feesforregistrationofdocs,
      coalesce(sum(e.totalamount) filter (where e.feerulecode = 2),0) as scanningfee,
      coalesce(sum(e.totalamount) filter (where e.feerulecode = 6),0) as mutationfee
     from kaveri.ams_reg_epaymenttransdetails e
     join success_txns s using (deptreferencecode)
     where e.applicationnumber =v_record.applicationnumber
       and e.isdelete = false
     group by e.applicationnumber
    ),
    surcharge as (
     select e.applicationnumber, sum(e.totalamount) as totalsurcharge
     from kaveri.ams_reg_epaymenttransdetails e
     join success_txns s using (deptreferencecode)
     where e.isdelete = false
       and e.feerulecode in (58,99)
       and e.applicationnumber =v_record.applicationnumber
     group by e.applicationnumber
    ),
    has_taluk as (
     select pm.applicationnumber, bool_or(pnd.currentpropertytypeid = 60) as has_taluk
     from kaveri.propertymaster pm
     join kaveri.propertynumberdetails pnd on pnd.propertyid = pm.propertyid
     where pm.applicationnumber =v_record.applicationnumber
     group by pm.applicationnumber
    ),
    bk as (
     select e.applicationnumber, sum(e.totalamount) as feesremittedtotreasury
     from kaveri.ams_reg_epaymenttransdetails e
     join success_txns s using (deptreferencecode)
     where e.isdelete = false
       and e.applicationnumber =v_record.applicationnumber
     group by e.applicationnumber
    )
    select d.districtnamee,
     d.sronamee,
     null::varchar as finalregistrationnumber,
     d.applicationnumber as applicationnumber2,
     d.presentdatetime::text as presentationdatetime,
     pr.presenternamee as presenter_name,
     art.description_of_docs as description_of_document,
     pm.consideration::numeric as considerationamount,
     pm.marketvalue::bigint as marketvalue,
     ep.stampduty::numeric as stampduty,
     ep.cessduty::numeric as cess,
     case when h.has_taluk then 0 else coalesce(s.totalsurcharge,0) end::numeric as surcharge_duty_muncipal,
     case when h.has_taluk then coalesce(s.totalsurcharge,0) else 0 end::numeric as surcharge_duty_taluk,
--     total_duty::numeric,
     coalesce(ep.stampduty::numeric + ep.cessduty::numeric + s.totalsurcharge::numeric,0) as total_duty,
     d.finalregistrationnumber::varchar as documentnumber,
     d.bookid::varchar as bookid,
     null::text as volumenumber,
     d.registrationdatetime::text as dateofcompletion,
     d.registrationdatetime::text as dateofreturn,
     ep.feesforregistrationofdocs::numeric as registrationfees,
     null::numeric as feescopygranted,
     ep.scanningfee::numeric as miscfees,
     null::numeric as otherstampduty,
     null::numeric as miscarticlefees,
     (COALESCE(ep.feesforregistrationofdocs,0)
      + COALESCE(ep.scanningfee,0))::numeric as total_fees, --sum
     bk.feesremittedtotreasury::numeric as treasury_fees,
     bklast.transactiondate::text as feedate_treasury,
     null::text as dailymutationreceipts,
     ep.mutationfee::numeric as mutationfees,
     mut.mutationfeeremittedtotreasurydate::text as mutationfeedate,
     ar.copiesofmemo::text as transmission_of_memorandum,
     --ar.officename as transmission_of_memoranda,
     ar.memoacceptingoffice::text as transmission_of_memoranda,
       (coalesce(ep.stampduty,0)
       + coalesce(ep.cessduty,0)
       + coalesce(case when h.has_taluk then 0 else s.totalsurcharge end,0)
       + coalesce(case when h.has_taluk then s.totalsurcharge else 0 end,0)
       + coalesce(ep.feesforregistrationofdocs,0)
       + coalesce(ep.scanningfee,0)
       + coalesce(ep.mutationfee,0))::bigint as total_amount_collected,
     null::text as signature_of_register,
     null::text as remarks,
     null::text as copy_of_document
     --pm.totalarea, 
     --ar.memosentdate,
     --ar.memonumber,
     --ar.memoaccepteddate
    from dm d
    left join pm on pm.applicationnumber = d.applicationnumber
    left join epay ep on ep.applicationnumber = d.applicationnumber
    left join surcharge s on s.applicationnumber = d.applicationnumber
    left join has_taluk h on h.applicationnumber = d.applicationnumber
    left join bk on bk.applicationnumber = d.applicationnumber
    
    left join lateral (
     select b.amount as feesremittedtotreasury, b.transactiontimestamp::date as transactiondate
     from kaveri.ams_reg_epaymenttransdetails e2
     join kaveri.ams_reg_epaymentbankackdetails b on b.deptreferencecode = e2.deptreferencecode
     where e2.applicationnumber = d.applicationnumber
       and e2.isdelete = false
       and b.paymentstatuscode in ('10700066','10700072')
     order by b.transactiontimestamp desc
     limit 1
    ) bklast on true
    
    left join lateral (
     select coalesce(nullif(p2.firstname,''), nullif(p1.firstname,''), p.firstname) as presenternamee
     from kaveri.partyinfo p
     left join kaveri.partyinfo p1 on p.partyid = p1.linkpartyid
     left join kaveri.partyinfo p2 on p1.partyid = p2.linkpartyid
     where p.applicationnumber = d.applicationnumber and p.ispresenter = true
     order by p.partyid
     limit 1
    ) pr on true
    
    left join lateral (
     select s.articlenamee as description_of_docs
     from (
      select distinct stamparticlecode
      from kaveri.propertymaster
      where applicationnumber = d.applicationnumber
      order by stamparticlecode
      limit 1
     ) pmx
     join kaveri.stamparticles s on s.stamparticlecode = pmx.stamparticlecode
    ) art on true
    
    left join lateral (
     select min(t.inserteddatetime)::date as mutationfeeremittedtotreasurydate
     from kaveri.ams_reg_epaymenttransdetails t
     join success_txns st using (deptreferencecode)
     where t.applicationnumber = d.applicationnumber
       and t.feerulecode = 6
       and t.isdelete = false
    ) mut on true
    left join lateral (
     select
      a.newapplicationnumber as copiesofmemo,
      a.memosentdatetime::date as memosentdate,
      a.memoaccepteddatetime::date as memoaccepteddate,
      d2.finalregistrationnumber as memonumber,
      s1.sronamee as officename,
      s2.sronamee as memoacceptingoffice
     from kaveri.anywhere_reg_log a
     left join kaveri.documentmaster d2 on d2.applicationnumber = a.newapplicationnumber
     left join kaveri.sromaster s1 on s1.srocode = a.srocode
     left join kaveri.sromaster s2 on s2.srocode = a.regsrocode
     where a.applicationnumber = d.applicationnumber
     order by a.memosentdatetime desc
     limit 1
    ) ar on true
    order by d.finalregistrationnumber)
    select cte.*,
                1 as totalcount
                from cte;

end loop;
commit;
--return v_array;
END;

$$;


