--
-- Name: vw_form17_collection_of_revenue_details; Type: VIEW; Schema: kaverimis; Owner: csgadmin
--

CREATE VIEW kaverimis.vw_form17_collection_of_revenue_details AS
 SELECT DISTINCT a.srocode,
    a.registrationdatetime,
    to_char(a.registrationdatetime, 'Month-yyyy'::text) AS month,
    count(a.documentid) AS numberofdocuments,
        CASE
            WHEN (b.feerulecode = 36) THEN sum(b.amountpaid)
            ELSE (0)::numeric
        END AS stampduty,
        CASE
            WHEN (b.feerulecode = 1) THEN sum(b.amountpaid)
            ELSE (0)::numeric
        END AS registrationfees,
        CASE
            WHEN (b.feerulecode = 2) THEN sum(b.amountpaid)
            ELSE (0)::numeric
        END AS scanningfees,
    0 AS otherfees,
    (((
        CASE
            WHEN (b.feerulecode = 36) THEN sum(b.amountpaid)
            ELSE (0)::numeric
        END +
        CASE
            WHEN (b.feerulecode = 1) THEN sum(b.amountpaid)
            ELSE (0)::numeric
        END) +
        CASE
            WHEN (b.feerulecode = 2) THEN sum(b.amountpaid)
            ELSE (0)::numeric
        END) + (0)::numeric) AS total
   FROM ((kaveri.documentmaster a
     JOIN kaveri.feesrequired b ON ((a.documentid = b.documentid)))
     JOIN kaveri.sromaster c ON ((a.srocode = c.srocode)))
  GROUP BY a.srocode, a.registrationdatetime, (to_char(a.registrationdatetime, 'Month-yyyy'::text)), b.feerulecode;


ALTER TABLE kaverimis.vw_form17_collection_of_revenue_details OWNER TO csgadmin;

--
-- Name: vw_mis_68_order_report; Type: VIEW; Schema: kaverimis; Owner: csgadmin
--

CREATE VIEW kaverimis.vw_mis_68_order_report AS
 SELECT d.districtnamee AS drooffice,
    d.districtcode,
    s.srocode,
    s.sronamee AS srooffice,
    c.documentnumber,
    u.loginname AS orderuploadedby,
    a.ordernumber AS drordernumber,
    a.orderdate,
    b.note_enteredpart AS note,
    c.finalregistrationnumber AS registrationnumber,
    a.statuscode AS isfinalized,
        CASE
            WHEN (e.actiontype = 'I'::bpchar) THEN 'Pending'::text
            WHEN (e.actiontype = 'F'::bpchar) THEN 'Finalized'::text
            ELSE NULL::text
        END AS status,
    a.absolutefilepath AS ordercopypath
   FROM ((((((kaveri.dec_drordermaster a
     JOIN kaveri.dec_drpndnote b ON ((a.orderid = b.orderid)))
     JOIN kaveri.documentmaster c ON ((a.documentid = c.documentid)))
     JOIN kaveri.districtmaster d ON ((a.districtcode = d.districtcode)))
     JOIN kaveri.sromaster s ON ((a.srocode = s.srocode)))
     JOIN kaveri.departmentusers u ON ((a.userid = u.userid)))
     LEFT JOIN kaveri.ecpropertysearchkeyvalues e ON ((a.orderid = e.orderid)));


ALTER TABLE kaverimis.vw_mis_68_order_report OWNER TO csgadmin;

--
-- Name: vw_mis_aregister; Type: VIEW; Schema: kaverimis; Owner: postgres
--

CREATE VIEW kaverimis.vw_mis_aregister AS
 SELECT DISTINCT a.feerulecode,
    b.feerulename AS feeruledescription,
    a.srocode,
    to_char(c.lastupdateddate, 'YYYY-MM-DD'::text) AS lastupdateddate,
    d.regarticlecode,
    e.articlenamee AS regarticlename,
    d.documentnumber,
    e.bookid,
    f.booknameenglish AS booknname,
    d.cdnumber,
    g.firstname,
    g.middlename,
    g.lastname,
    d.executiondatetime,
    h.remarks AS comments,
    a.applicationnumber,
    sum(a.amountpaid) AS amountpaid
   FROM (((((((kaveri.feesrequired a
     JOIN kaveri.vw_feesrule_mapping b ON ((a.feerulecode = b.feerulecode)))
     LEFT JOIN kaveri.ams_reg_epaymenttransdetails c ON (((a.applicationnumber)::text = (c.applicationnumber)::text)))
     LEFT JOIN kaveri.documentmaster d ON (((c.applicationnumber)::text = (d.applicationnumber)::text)))
     LEFT JOIN kaveri.registrationarticles e ON ((d.regarticlecode = e.regarticlecode)))
     LEFT JOIN kaveri.booktypemaster f ON ((e.bookid = f.bookid)))
     LEFT JOIN kaveri.partyinfo g ON (((d.applicationnumber)::text = (g.applicationnumber)::text)))
     LEFT JOIN kaveri.applicantapplicationdetails h ON (((g.applicationnumber)::text = (h.applicationnumber)::text)))
  GROUP BY a.feerulecode, b.feerulename, a.srocode, c.lastupdateddate, d.regarticlecode, e.articlenamee, d.documentnumber, e.bookid, f.booknameenglish, d.cdnumber, g.firstname, g.middlename, g.*, g.lastname, d.executiondatetime, h.remarks, a.applicationnumber
 HAVING (sum(a.amountpaid) > (0)::numeric)
UNION ALL
 SELECT DISTINCT ecfees.feeruleid AS feerulecode,
    fm.feerulename AS feeruledescription,
    b.kaverisrocode AS srocode,
    to_char(c.lastupdateddate, 'YYYY-MM-DD'::text) AS lastupdateddate,
    d.regarticlecode,
    e.articlenamee AS regarticlename,
    d.documentnumber,
    e.bookid,
    f.booknameenglish AS booknname,
    d.cdnumber,
    g.firstname,
    g.middlename,
    g.lastname,
    d.executiondatetime,
    NULL::text AS comments,
    b.applicationnumber,
    sum(ecfees.payableamount) AS amountpaid
   FROM (((((((kaveri.ec_requiredfees ecfees
     LEFT JOIN kaveri.vw_feesrule_mapping fm ON ((ecfees.feeruleid = fm.feerulecode)))
     LEFT JOIN kaveri.ec_applicationdetails b ON ((b.ecid = ecfees.ecid)))
     LEFT JOIN kaveri.ams_reg_epaymenttransdetails c ON (((b.applicationnumber)::text = (c.applicationnumber)::text)))
     LEFT JOIN kaveri.documentmaster d ON (((c.applicationnumber)::text = (d.applicationnumber)::text)))
     LEFT JOIN kaveri.registrationarticles e ON ((d.regarticlecode = e.regarticlecode)))
     LEFT JOIN kaveri.booktypemaster f ON ((e.bookid = f.bookid)))
     LEFT JOIN kaveri.partyinfo g ON ((((d.applicationnumber)::text = (g.applicationnumber)::text) AND (ecfees.ispaid = true))))
  GROUP BY ecfees.feeruleid, fm.feerulename, b.kaverisrocode, (to_char(c.lastupdateddate, 'YYYY-MM-DD'::text)), d.regarticlecode, e.articlenamee, d.documentnumber, e.bookid, f.booknameenglish, d.cdnumber, g.firstname, g.middlename, g.*, g.lastname, d.executiondatetime, b.applicationnumber
 HAVING (sum(ecfees.payableamount) > (0)::numeric)
UNION ALL
 SELECT DISTINCT ccfees.feeruleid AS feerulecode,
    fm.feerulename AS feeruledescription,
    b.kaverisrocode AS srocode,
    to_char(c.lastupdateddate, 'YYYY-MM-DD'::text) AS lastupdateddate,
    d.regarticlecode,
    e.articlenamee AS regarticlename,
    d.documentnumber,
    e.bookid,
    f.booknameenglish AS booknname,
    d.cdnumber,
    g.firstname,
    g.middlename,
    g.lastname,
    d.executiondatetime,
    NULL::text AS comments,
    b.applicationnumber,
    sum(ccfees.payableamount) AS amountpaid
   FROM (((((((kaveri.cc_requiredfees ccfees
     LEFT JOIN kaveri.vw_feesrule_mapping fm ON ((ccfees.feeruleid = fm.feerulecode)))
     LEFT JOIN kaveri.cc_applicationdetails b ON ((b.ccid = ccfees.ccid)))
     LEFT JOIN kaveri.ams_reg_epaymenttransdetails c ON (((b.applicationnumber)::text = (c.applicationnumber)::text)))
     LEFT JOIN kaveri.documentmaster d ON (((c.applicationnumber)::text = (d.applicationnumber)::text)))
     LEFT JOIN kaveri.registrationarticles e ON ((d.regarticlecode = e.regarticlecode)))
     LEFT JOIN kaveri.booktypemaster f ON ((e.bookid = f.bookid)))
     LEFT JOIN kaveri.partyinfo g ON ((((d.applicationnumber)::text = (g.applicationnumber)::text) AND (ccfees.ispaid = true))))
  GROUP BY ccfees.feeruleid, fm.feerulename, b.applicationnumber, b.kaverisrocode, (to_char(c.lastupdateddate, 'YYYY-MM-DD'::text)), d.regarticlecode, e.articlenamee, d.documentnumber, e.bookid, f.booknameenglish, d.cdnumber, g.firstname, g.middlename, g.lastname, d.executiondatetime
 HAVING (sum(ccfees.payableamount) > (0)::numeric);


ALTER TABLE kaverimis.vw_mis_aregister OWNER TO postgres;

