ALTER TABLE kaverimis.vw_mis_court_order_report OWNER TO csgadmin;

--
-- Name: vw_mis_form4; Type: VIEW; Schema: kaverimis; Owner: csgadmin
--

CREATE VIEW kaverimis.vw_mis_form4 AS
 SELECT DISTINCT c.districtnamee AS districtname,
    b.sronamee AS officename,
    h.booknameenglish AS book,
    NULL::text AS part,
    e.documenttypedesc AS documenttype,
    f.articlenamee AS articlename,
    count(a.documentid) AS documentsregistered,
    g.feerulecode,
        CASE
            WHEN (g.feerulecode = 36) THEN sum(g.amountpaid)
            ELSE (0)::numeric
        END AS stampduty,
        CASE
            WHEN (g.feerulecode = 1) THEN sum(g.amountpaid)
            ELSE (0)::numeric
        END AS registrationfee,
        CASE
            WHEN (g.feerulecode = 2) THEN sum(g.amountpaid)
            ELSE (0)::numeric
        END AS servicecharge,
        CASE
            WHEN (g.feerulecode <> ALL (ARRAY[1, 2, 36])) THEN (sum(g.amountpaid) - ((
            CASE
                WHEN (g.feerulecode = 36) THEN sum(g.amountpaid)
                ELSE (0)::numeric
            END +
            CASE
                WHEN (g.feerulecode = 1) THEN sum(g.amountpaid)
                ELSE (0)::numeric
            END) +
            CASE
                WHEN (g.feerulecode = 2) THEN sum(g.amountpaid)
                ELSE (0)::numeric
            END))
            ELSE (0)::numeric
        END AS otherfees,
    ((
        CASE
            WHEN (g.feerulecode = 1) THEN sum(g.amountpaid)
            ELSE (0)::numeric
        END +
        CASE
            WHEN (g.feerulecode = 2) THEN sum(g.amountpaid)
            ELSE (0)::numeric
        END) +
        CASE
            WHEN (g.feerulecode <> ALL (ARRAY[1, 2, 36])) THEN (sum(g.amountpaid) - ((
            CASE
                WHEN (g.feerulecode = 36) THEN sum(g.amountpaid)
                ELSE (0)::numeric
            END +
            CASE
                WHEN (g.feerulecode = 1) THEN sum(g.amountpaid)
                ELSE (0)::numeric
            END) +
            CASE
                WHEN (g.feerulecode = 2) THEN sum(g.amountpaid)
                ELSE (0)::numeric
            END))
            ELSE (0)::numeric
        END) AS total
   FROM (((((((kaveri.documentmaster a
     JOIN kaveri.sromaster b ON ((a.srocode = b.srocode)))
     JOIN kaveri.districtmaster c ON ((b.districtcode = c.districtcode)))
     JOIN kaveri.referencemaster d ON ((a.documentid = d.documentid)))
     JOIN kaveri.documenttypemaster e ON ((d.documenttypeid = e.documenttypeid)))
     JOIN kaveri.stamparticles f ON ((a.stamparticlecode = f.stamparticlecode)))
     JOIN kaveri.feesrequired g ON ((a.documentid = g.documentid)))
     JOIN kaveri.booktypemaster h ON ((a.bookid = h.bookid)))
  WHERE ((a.isregistrationcompleted = true) AND (d.documenttypeid = 0))
  GROUP BY c.districtnamee, b.sronamee, h.booknameenglish, e.documenttypedesc, f.articlenamee, g.feerulecode
 HAVING ((((
        CASE
            WHEN (g.feerulecode = 1) THEN sum(g.amountpaid)
            ELSE (0)::numeric
        END +
        CASE
            WHEN (g.feerulecode = 2) THEN sum(g.amountpaid)
            ELSE (0)::numeric
        END) +
        CASE
            WHEN (g.feerulecode <> ALL (ARRAY[1, 2, 36])) THEN (sum(g.amountpaid) - ((
            CASE
                WHEN (g.feerulecode = 36) THEN sum(g.amountpaid)
                ELSE (0)::numeric
            END +
            CASE
                WHEN (g.feerulecode = 1) THEN sum(g.amountpaid)
                ELSE (0)::numeric
            END) +
            CASE
                WHEN (g.feerulecode = 2) THEN sum(g.amountpaid)
                ELSE (0)::numeric
            END))
            ELSE (0)::numeric
        END) IS NOT NULL) AND (((
        CASE
            WHEN (g.feerulecode = 1) THEN sum(g.amountpaid)
            ELSE (0)::numeric
        END +
        CASE
            WHEN (g.feerulecode = 2) THEN sum(g.amountpaid)
            ELSE (0)::numeric
        END) +
        CASE
            WHEN (g.feerulecode <> ALL (ARRAY[1, 2, 36])) THEN (sum(g.amountpaid) - ((
            CASE
