--
-- Name: vw_mis_impounddoc; Type: VIEW; Schema: kaverimis; Owner: postgres
--

CREATE VIEW kaverimis.vw_mis_impounddoc AS
 SELECT row_number() OVER (ORDER BY b.districtcode, b.srocode) AS sl_no,
    c.districtcode,
    c.districtnamee,
    b.srocode,
    b.sronamee,
    ( SELECT (((((pi.firstname)::text || ' '::text) || (pi.middlename)::text) || ' '::text) || (pi.lastname)::text) AS nameofpresentor
           FROM kaveri.partyinfo pi
          WHERE ((pi.ispresenter = true) AND (pi.partytypeid = 7) AND (pi.partyid = pi1.partyid))) AS nameofpresentor,
    ( SELECT
                CASE
                    WHEN (p.isexecutor = true) THEN 'Executor'::text
                    ELSE 'Claimant'::text
                END AS "case"
           FROM kaveri.partyinfo p
          WHERE (p.partyid = pi1.partyid)) AS executantorclaimant,
    dm.executiondatetime AS dateofexecution,
    dm.executiondatetime AS dateofexecutantsappearence,
    NULL::character varying(100) AS purposeofdocument,
    frm.value AS deficientamountofstampduty,
    frm.value AS deficientamountofpenality,
    frm.descriptione AS descriptionofdocument,
    NULL::timestamp without time zone AS dateofpresentation,
    sr.value AS valueofstampofdocument,
    NULL::timestamp without time zone AS dateofrefdepcommr,
    NULL::timestamp without time zone AS dateofdeputycommrorderreturndocument,
    NULL::character varying(500) AS purposeoforders,
    NULL::character varying(100) AS howdisposedof
   FROM (((((((kaveri.districtmaster c
     JOIN kaveri.sromaster b ON ((c.districtcode = b.districtcode)))
     JOIN kaveri.partyinfo pi1 ON (((b.srocode = pi1.srocode) AND (c.districtcode = pi1.districtcode))))
     JOIN kaveri.documentmaster dm ON (((pi1.documentid = dm.documentid) AND ((pi1.applicationnumber)::text = (dm.applicationnumber)::text))))
     JOIN kaveri.feesrequired fr ON (((fr.documentid = dm.documentid) AND ((dm.applicationnumber)::text = (fr.applicationnumber)::text) AND (fr.srocode = b.srocode))))
     JOIN kaveri.feesrulemaster frm ON ((frm.feerulecode = fr.feerulecode)))
     JOIN kaveri.propertymaster pm ON ((((fr.applicationnumber)::text = (fr.applicationnumber)::text) AND (pm.documentid = dm.documentid) AND (pm.srocode = b.srocode))))
     JOIN kaveri.stamprules sr ON ((pm.stampruleid = sr.stampruleid)));


ALTER TABLE kaverimis.vw_mis_impounddoc OWNER TO postgres;

--
-- Name: vw_mis_jurisdiction_revenue_report; Type: VIEW; Schema: kaverimis; Owner: postgres
--

CREATE VIEW kaverimis.vw_mis_jurisdiction_revenue_report AS
 SELECT DISTINCT dsm.districtnamee AS district,
    sm.srocode,
    sm.sronamee AS sroname,
    aad.applicationtypeid,
    dm.applicationnumber,
    s.stamparticlecode,
    s.articlenamee AS articlename,
    fr.amountpaid,
    fr.feerulecode,
    dm.registrationdatetime,
    dm.finalregistrationnumber,
    bt.booknameenglish AS booktype,
    count(dm.bookid) AS bookcount,
    pr.marketvalue,
    dm.regarticlecode,
    pr.consideration,
    bt.printablename
   FROM ((((((((kaveri.documentmaster dm
     JOIN kaveri.applicantapplicationdetails aad ON (((dm.applicationnumber)::text = (aad.applicationnumber)::text)))
     JOIN kaveri.feesrequired fr ON (((dm.applicationnumber)::text = (fr.applicationnumber)::text)))
     JOIN kaveri.booktypemaster bt ON ((dm.bookid = bt.bookid)))
     JOIN kaveri.propertymaster pr ON ((dm.documentid = pr.documentid)))
     JOIN kaveri.propertynumberdetails pnd ON ((pr.propertyid = pnd.propertyid)))
     JOIN kaveri.sromaster sm ON ((dm.srocode = sm.srocode)))
     JOIN kaveri.districtmaster dsm ON ((sm.districtcode = dsm.districtcode)))
     JOIN kaveri.stamparticles s ON ((s.stamparticlecode = pr.stamparticlecode)))
  WHERE ((dm.isregistrationcompleted = true) AND (fr.amountpaid IS NOT NULL))
  GROUP BY dsm.districtnamee, sm.srocode, sm.sronamee, aad.applicationtypeid, dm.applicationnumber, s.stamparticlecode, s.articlenamee, fr.amountpaid, fr.feerulecode, dm.registrationdatetime, dm.finalregistrationnumber, bt.booknameenglish, pr.marketvalue, dm.regarticlecode, pr.consideration, bt.printablename;


ALTER TABLE kaverimis.vw_mis_jurisdiction_revenue_report OWNER TO postgres;

--
-- Name: vw_mis_minutebook; Type: VIEW; Schema: kaverimis; Owner: csgadmin
--

CREATE VIEW kaverimis.vw_mis_minutebook AS
 SELECT row_number() OVER (ORDER BY b.districtcode, a.srocode) AS sl_no,
    b.districtcode,
    c.districtnamee,
    a.srocode,
    b.sronamee,
    dm.documentnumber AS crossreflastserial,
    (((a.registrationno)::text || ' '::text) || a.minutedate) AS nodateofdoc,
    a.details AS minuteofmeeting,
    a.remarks AS referencetofinaldisposal,
    a.minutedate AS date
   FROM (((kaveri.districtmaster c
     JOIN kaveri.sromaster b ON ((c.districtcode = b.districtcode)))
     JOIN kaveri.minutebook a ON ((a.srocode = b.srocode)))
     JOIN kaveri.documentmaster dm ON (((a.documentid = dm.documentid) AND (a.srocode = dm.srocode))))
  WHERE ((substr((a.registrationno)::text, 9, 5) <> ''::text) AND (substr((a.registrationno)::text, 9, 5) <> 'le 17'::text) AND (substr((a.registrationno)::text, 9, 5) <> 'Part-'::text));


ALTER TABLE kaverimis.vw_mis_minutebook OWNER TO csgadmin;

--
-- Name: vw_mis_minutebook_form6; Type: VIEW; Schema: kaverimis; Owner: postgres
--

CREATE VIEW kaverimis.vw_mis_minutebook_form6 AS
 SELECT sro.districtcode,
    dist.districtnamee,
    aad.srocode,
    sro.sronamee,
    aad.applicationnumber AS applicationnum,
    replace(regexp_replace((dm.pendingdocumentnumber)::text, '^([^-]*-[^-]*)-.*$'::text, '\1'::text), 'P-'::text, ''::text) AS crossreflastserial,
    ((regexp_replace((dm.pendingdocumentnumber)::text, '^([^-]*-[^-]*)-.*$'::text, '\1'::text) || ' '::text) || (dm.presentdatetime)::date) AS nodateofdoc,
    ( SELECT string_agg(aad_1.remarks, ';'::text) AS string_agg
           FROM kaveri.applicantapplicationdetails aad_1
          WHERE (((aad_1.currentstatus)::text = 'CD119'::text) AND ((aad_1.applicationnumber)::text = (dm.applicationnumber)::text))
          GROUP BY aad_1.applicationnumber) AS remarks,
    wm.wrkflowstatusnamee AS status,
    dm.presentdatetime
   FROM (((((kaveri.documentmaster dm
     JOIN kaveri.applicantapplicationdetails aad ON (((dm.applicationnumber)::text = (aad.applicationnumber)::text)))
     JOIN kaveri.sromaster sro ON ((dm.srocode = sro.srocode)))
     LEFT JOIN kaveri.districtmaster dist ON ((dist.districtcode = sro.districtcode)))
     LEFT JOIN kaveri.wrkflowmaster wm ON (((aad.currentstatus)::text = (wm.wrkflowstatusid)::text)))
     LEFT JOIN kaveri.servicesmaster sm ON ((aad.applicationtypeid = sm.serviceid)))
  WHERE ((aad.currentstatus)::text = 'CD119'::text);


ALTER TABLE kaverimis.vw_mis_minutebook_form6 OWNER TO postgres;

--
-- Name: vw_mis_partyinfo; Type: VIEW; Schema: kaverimis; Owner: postgres
--

CREATE VIEW kaverimis.vw_mis_partyinfo AS
 SELECT dm.applicationnumber,
    a.partytypeid,
    concat_ws(' '::text, e.descriptione, a.firstname, a.middlename, a.lastname) AS name,
    concat_ws(' '::text, ((((((a.housenumber || ', '::text) || (a.address)::text) || ', '::text) || kaveri.fn_fetch_address_village((a.talukcode)::bigint)) || ' - '::text) || a.pin)) AS address,
    a.isexecutor,
    a.ispresenter,
    dm.presentdatetime,
    dm.registrationdatetime
   FROM ((kaveri.partyinfo a
     LEFT JOIN kaveri.salutationmaster e ON ((a.salutationid = e.salutationid)))
     JOIN kaveri.documentmaster dm ON (((a.applicationnumber)::text = (dm.applicationnumber)::text)))
UNION ALL
 SELECT ea.applicationnumber,
    7 AS partytypeid,
    concat_ws(' '::text, c.firstname, c.middlename, c.lastname) AS name,
    (c.permanentaddress)::text AS address,
    (0)::boolean AS isexecutor,
    (1)::boolean AS ispresenter,
    ea.submitteddatetime AS presentdatetime,
    ea.signeddatetime AS registrationdatetime
   FROM ((kaveri.ec_applicationdetails ea
     JOIN kaveri.applicantapplicationdetails a ON (((ea.applicationnumber)::text = (a.applicationnumber)::text)))
     JOIN kaveri.citizenmaster c ON ((a.citizenid = c.citizenid)))
UNION ALL
 SELECT ca.applicationnumber,
    7 AS partytypeid,
    concat_ws(' '::text, c.firstname, c.middlename, c.lastname) AS name,
    (c.permanentaddress)::text AS address,
    (0)::boolean AS isexecutor,
    (1)::boolean AS ispresenter,
    ca.submitteddatetime AS presentdatetime,
    ca.signeddatetime AS registrationdatetime
   FROM ((kaveri.cc_applicationdetails ca
     JOIN kaveri.applicantapplicationdetails a ON (((ca.applicationnumber)::text = (a.applicationnumber)::text)))
     JOIN kaveri.citizenmaster c ON ((a.citizenid = c.citizenid)));


ALTER TABLE kaverimis.vw_mis_partyinfo OWNER TO postgres;

--
-- Name: vw_mis_register_poa_form12; Type: VIEW; Schema: kaverimis; Owner: csgadmin
--

CREATE VIEW kaverimis.vw_mis_register_poa_form12 AS
 SELECT b.districtcode,
    c.districtnamee AS district,
    b.sronamee AS sroname,
    a.stamparticlecode,
    d.articlenamee AS article,
    min(a.executiondatetime) AS dateofexecution_min,
    max(a.executiondatetime) AS dateofexecution_max
   FROM ((((kaveri.documentmaster a
     JOIN kaveri.sromaster b ON ((a.srocode = b.srocode)))
     JOIN kaveri.districtmaster c ON ((b.districtcode = c.districtcode)))
     JOIN kaveri.stamparticles d ON ((a.stamparticlecode = d.stamparticlecode)))
     JOIN kaveri.stamprules e ON ((d.stamparticlecode = e.stamparticlecode)))
  GROUP BY b.districtcode, c.districtnamee, b.sronamee, a.stamparticlecode, d.articlenamee;


ALTER TABLE kaverimis.vw_mis_register_poa_form12 OWNER TO csgadmin;

--
-- Name: vw_mis_registerofdeficientfeesandstampduty_form11; Type: VIEW; Schema: kaverimis; Owner: csgadmin
--

CREATE VIEW kaverimis.vw_mis_registerofdeficientfeesandstampduty_form11 AS
 SELECT b.districtcode,
    c.districtnamee,
    b.srocode,
    b.sronamee AS sroname,
    b.sronamee AS nameofofficies,
    regfeesandpenalties.monthofregistry,
    regfeesandpenalties.documentnumber AS noofdocument,
    regfeesandpenalties.executiondatetime,
    regfeesandpenalties.bookid AS noofbook,
    regfeesandpenalties.amountrequired AS amount,
    NULL::timestamp without time zone AS dateofrecoverypenalty,
    stampdutyfees.dateofrecovery AS dateofrecoverystampduty,
    stampdutyfees.documentnumber,
    stampdutyfees.amountofstampduty,
    NULL::timestamp without time zone AS dateoftreasuryreceipt,
    NULL::character varying AS remarks
   FROM (((kaveri.districtmaster c
     JOIN kaveri.sromaster b ON ((c.districtcode = b.districtcode)))
     JOIN ( SELECT dm.srocode,
            dm.executiondatetime,
            to_char(dm.executiondatetime, 'Month'::text) AS monthofregistry,
            to_char(dm.executiondatetime, 'Month'::text) AS dateofrecovery,
            dm.documentnumber,
            dm.bookid,
            fr.amountrequired
           FROM (kaveri.feesrequired fr
             JOIN kaveri.documentmaster dm ON (((fr.documentid = dm.documentid) AND ((fr.applicationnumber)::text = (dm.applicationnumber)::text) AND (fr.srocode = dm.srocode) AND (fr.feerulecode = ANY (ARRAY[28, 1])))))) regfeesandpenalties ON ((b.srocode = regfeesandpenalties.srocode)))
     LEFT JOIN ( SELECT dm.srocode,
            to_char(dm.executiondatetime, 'Month'::text) AS dateofrecovery,
            dm.documentnumber,
            fr.amountrequired AS amountofstampduty
           FROM (kaveri.feesrequired fr
             JOIN kaveri.documentmaster dm ON (((fr.documentid = dm.documentid) AND ((fr.applicationnumber)::text = (dm.applicationnumber)::text) AND (fr.srocode = dm.srocode))))
          WHERE (fr.feerulecode = 36)) stampdutyfees ON (((stampdutyfees.documentnumber = regfeesandpenalties.documentnumber) AND (regfeesandpenalties.srocode = stampdutyfees.srocode))));


ALTER TABLE kaverimis.vw_mis_registerofdeficientfeesandstampduty_form11 OWNER TO csgadmin;

--
-- Name: vw_mis_registerofrecords_form13; Type: VIEW; Schema: kaverimis; Owner: csgadmin
--

CREATE VIEW kaverimis.vw_mis_registerofrecords_form13 AS
 SELECT b.districtcode,
    c.districtnamee,
    b.srocode,
    b.sronamee,
    to_char(dm.executiondatetime, 'YYYY'::text) AS year,
    sum(
        CASE
            WHEN (dm.bookid = 1) THEN 1
            ELSE 0
        END) AS book1volno,
    sum(
        CASE
            WHEN (dm.bookid = 2) THEN 1
            ELSE 0
        END) AS book2volno,
    sum(
        CASE
            WHEN (dm.bookid = 3) THEN 1
            ELSE 0
        END) AS book3volno,
    sum(
        CASE
            WHEN (dm.bookid = 4) THEN 1
            ELSE 0
        END) AS book4volno,
    sum(
        CASE
            WHEN (dm.bookid = 5) THEN 1
            ELSE 0
        END) AS book5volno
   FROM ((kaveri.districtmaster c
     JOIN kaveri.sromaster b ON ((c.districtcode = b.districtcode)))
     JOIN kaveri.documentmaster dm ON ((dm.srocode = b.srocode)))
  WHERE (dm.bookid = ANY (ARRAY[1, 2, 3, 4, 5]))
  GROUP BY b.districtcode, c.districtnamee, b.srocode, b.sronamee, (to_char(dm.executiondatetime, 'YYYY'::text));


ALTER TABLE kaverimis.vw_mis_registerofrecords_form13 OWNER TO csgadmin;

--
-- Name: vw_mis_registerunclaimdocuments; Type: VIEW; Schema: kaverimis; Owner: postgres
--

CREATE VIEW kaverimis.vw_mis_registerunclaimdocuments AS
 SELECT row_number() OVER (ORDER BY b.districtcode, b.srocode) AS sl_no,
    c.districtcode,
    c.districtnamee,
    b.srocode,
    b.sronamee,
    docm.executiondatetime AS dateofregistry,
    NULL::timestamp without time zone AS dateofrefusalwhennotregd,
    ( SELECT (((((pi.firstname)::text || ' '::text) || (pi.middlename)::text) || ' '::text) || (pi.lastname)::text) AS nameofpresentor
           FROM kaveri.partyinfo pi
          WHERE ((pi.ispresenter = true) AND (pi.partytypeid = 7) AND (pi.partyid = pi1.partyid) AND (pi.documentid = pi1.documentid))) AS nameofpresentor,
    docm.cntbook1 AS countofregisternumofdocbook1,
    docm.cntbook2 AS countofregisternumofdocbook2,
    docm.cntbook3 AS countofregisternumofdocbook3,
    docm.cntbook4 AS countofregisternumofdocbook4,
    frm.value AS valueofdocument,
    NULL::timestamp without time zone AS dateofissueofnoticestopresentant,
    NULL::timestamp without time zone AS dateofreturnordestruction,
    NULL::character varying AS feeleviedforcustodysafereturn,
    docm.remarksbysystem AS remarks
   FROM (((((kaveri.districtmaster c
     JOIN kaveri.sromaster b ON ((c.districtcode = b.districtcode)))
     JOIN kaveri.partyinfo pi1 ON (((b.srocode = pi1.srocode) AND (c.districtcode = pi1.districtcode))))
     JOIN ( SELECT dm.srocode,
            (dm.executiondatetime)::date AS executiondatetime,
            dm.remarksbysystem,
            dm.documentid,
            sum(
                CASE
                    WHEN (btm.bookid = 1) THEN 1
                    ELSE 0
                END) AS cntbook1,
            sum(
                CASE
                    WHEN (btm.bookid = 2) THEN 1
                    ELSE 0
                END) AS cntbook2,
            sum(
                CASE
                    WHEN (btm.bookid = 3) THEN 1
                    ELSE 0
                END) AS cntbook3,
            sum(
                CASE
                    WHEN (btm.bookid = 4) THEN 1
                    ELSE 0
                END) AS cntbook4
           FROM kaveri.booktypemaster btm,
            kaveri.documentmaster dm
          WHERE ((btm.bookid = ANY (ARRAY[1, 2, 3, 4])) AND (dm.bookid = btm.bookid))
          GROUP BY dm.srocode, ((dm.executiondatetime)::date), dm.remarksbysystem, dm.documentid) docm ON (((pi1.srocode = docm.srocode) AND (pi1.documentid = docm.documentid))))
     JOIN kaveri.feesrequired fr ON (((fr.documentid = docm.documentid) AND (fr.srocode = docm.srocode))))
     JOIN kaveri.feesrulemaster frm ON ((frm.feerulecode = fr.feerulecode)));


ALTER TABLE kaverimis.vw_mis_registerunclaimdocuments OWNER TO postgres;

--
-- Name: vw_mis_registration_summary; Type: VIEW; Schema: kaverimis; Owner: postgres
--

CREATE VIEW kaverimis.vw_mis_registration_summary AS
 SELECT dm.srocode,
    (string_agg(DISTINCT (sro.sronamee)::text, ', '::text))::character varying AS srooffice,
    string_agg(DISTINCT (d.districtnamee)::text, ', '::text) AS droffice,
    string_agg(DISTINCT (bt.booknameenglish)::text, ', '::text) AS booktype,
    dm.finalregistrationnumber,
    pm.stamparticlecode,
    sa.articlenamee AS articlename,
    dm.registrationdatetime,
    string_agg(DISTINCT (pm.totalarea)::text, ', '::text) AS totalarea,
    string_agg((mum.descriptionenglish)::text, ', '::text) AS unit,
    string_agg(DISTINCT ((('Schedule '::text || (ps.scheduletype)::text) || ': '::text) || (ps.description)::text), ', '::text) AS propertydetails,
    string_agg(DISTINCT (ps.scheduletype)::text, ', '::text) AS schedule,
    prt_ex.executants,
    prt_cl.claimants,
    string_agg(DISTINCT (vm.villagenamee)::text, ', '::text) AS villagenamee,
    sum(pm.marketvalue) AS marketvalue,
    sum(pm.consideration) AS consideration
   FROM ((((((((((kaveri.documentmaster dm
     LEFT JOIN kaveri.propertymaster pm ON ((dm.documentid = pm.documentid)))
     LEFT JOIN kaveri.propertyschedules ps ON ((pm.propertyid = ps.propertyid)))
     LEFT JOIN ( SELECT vw.applicationnumber,
            string_agg(DISTINCT vw.name, ', '::text) AS executants
           FROM kaverimis.vw_mis_partyinfo vw
          WHERE (vw.partytypeid = 2)
          GROUP BY vw.applicationnumber) prt_ex ON (((prt_ex.applicationnumber)::text = (dm.applicationnumber)::text)))
     LEFT JOIN ( SELECT vw.applicationnumber,
            string_agg(DISTINCT vw.name, ', '::text) AS claimants
           FROM kaverimis.vw_mis_partyinfo vw
          WHERE (vw.partytypeid = 1)
          GROUP BY vw.applicationnumber) prt_cl ON (((prt_cl.applicationnumber)::text = (dm.applicationnumber)::text)))
     LEFT JOIN kaveri.stamparticles sa ON ((pm.stamparticlecode = sa.stamparticlecode)))
     LEFT JOIN kaveri.villagemaster vm ON ((pm.villagecode = vm.villagecode)))
     LEFT JOIN kaveri.measunitmaster mum ON ((pm.unitid = mum.unitid)))
     LEFT JOIN kaveri.sromaster sro ON ((dm.srocode = sro.srocode)))
     LEFT JOIN kaveri.districtmaster d ON ((sro.districtcode = d.districtcode)))
     LEFT JOIN kaveri.booktypemaster bt ON ((dm.bookid = bt.bookid)))
  WHERE (dm.isregistrationcompleted = true)
  GROUP BY dm.finalregistrationnumber, pm.stamparticlecode, dm.srocode, dm.registrationdatetime, prt_ex.executants, sa.articlenamee, prt_cl.claimants;


ALTER TABLE kaverimis.vw_mis_registration_summary OWNER TO postgres;

--
-- Name: vw_mis_revenue_report; Type: VIEW; Schema: kaverimis; Owner: postgres
--

CREATE VIEW kaverimis.vw_mis_revenue_report AS
 SELECT dsm.districtnamee AS district,
    sm.srocode,
    sm.sronamee AS sroname,
    aad.applicationtypeid,
    dm.applicationnumber,
    s.stamparticlecode,
    s.articlenamee AS articlename,
    fr.amountpaid,
    fr.feerulecode,
    dm.registrationdatetime,
    dm.finalregistrationnumber,
    bt.booknameenglish AS booktype,
    count(dm.bookid) AS bookcount,
    pr.marketvalue,
    dm.regarticlecode,
    pr.consideration,
    bt.printablename
   FROM (((((((kaveri.documentmaster dm
     JOIN kaveri.applicantapplicationdetails aad ON (((dm.applicationnumber)::text = (aad.applicationnumber)::text)))
     JOIN kaveri.feesrequired fr ON (((dm.applicationnumber)::text = (fr.applicationnumber)::text)))
     JOIN kaveri.sromaster sm ON ((dm.srocode = sm.srocode)))
     JOIN kaveri.districtmaster dsm ON ((sm.districtcode = dsm.districtcode)))
     JOIN kaveri.booktypemaster bt ON ((dm.bookid = bt.bookid)))
     JOIN kaveri.propertymaster pr ON ((dm.documentid = pr.documentid)))
     JOIN kaveri.stamparticles s ON ((s.stamparticlecode = pr.stamparticlecode)))
  WHERE ((dm.isregistrationcompleted = true) AND (fr.amountpaid IS NOT NULL))
  GROUP BY dsm.districtnamee, sm.srocode, sm.sronamee, aad.applicationtypeid, dm.applicationnumber, s.stamparticlecode, s.articlenamee, fr.amountpaid, fr.feerulecode, dm.registrationdatetime, dm.finalregistrationnumber, bt.booknameenglish, pr.marketvalue, dm.regarticlecode, pr.consideration, bt.printablename;


ALTER TABLE kaverimis.vw_mis_revenue_report OWNER TO postgres;

--
-- Name: vw_mis_revenue_report_stampartclecode; Type: VIEW; Schema: kaverimis; Owner: postgres
--

CREATE VIEW kaverimis.vw_mis_revenue_report_stampartclecode AS
 SELECT dsm.districtnamee AS district,
    sm.srocode,
    sm.sronamee AS sroname,
    aad.applicationtypeid,
    dm.applicationnumber,
    sa.stamparticlecode,
    sa.articlenamee AS articlename,
    fr.amountpaid,
    fr.feerulecode,
    dm.registrationdatetime,
    dm.finalregistrationnumber,
    bt.booknameenglish AS booktype,
    count(dm.bookid) AS bookcount,
    pr.marketvalue
   FROM (((((((kaveri.documentmaster dm
     JOIN kaveri.applicantapplicationdetails aad ON (((dm.applicationnumber)::text = (aad.applicationnumber)::text)))
     JOIN kaveri.feesrequired fr ON (((dm.applicationnumber)::text = (fr.applicationnumber)::text)))
     JOIN kaveri.sromaster sm ON ((dm.srocode = sm.srocode)))
     JOIN kaveri.districtmaster dsm ON ((sm.districtcode = dsm.districtcode)))
     JOIN kaveri.stamparticles sa ON ((dm.regarticlecode = sa.stamparticlecode)))
     JOIN kaveri.booktypemaster bt ON ((dm.bookid = bt.bookid)))
     JOIN kaveri.propertymaster pr ON ((dm.documentid = pr.documentid)))
  WHERE ((dm.isregistrationcompleted = true) AND (fr.amountpaid IS NOT NULL))
  GROUP BY dsm.districtnamee, sm.srocode, sm.sronamee, aad.applicationtypeid, dm.applicationnumber, sa.stamparticlecode, sa.articlenamee, fr.amountpaid, fr.feerulecode, dm.registrationdatetime, dm.finalregistrationnumber, bt.booknameenglish, pr.marketvalue;


ALTER TABLE kaverimis.vw_mis_revenue_report_stampartclecode OWNER TO postgres;

--
-- Name: vw_mis_sakala_upload_report_cc; Type: VIEW; Schema: kaverimis; Owner: postgres
--

CREATE VIEW kaverimis.vw_mis_sakala_upload_report_cc AS
 SELECT s.srocode,
    dis.districtcode,
    s.sronamee AS officename,
    concat(cc.certificatenumber, '/', a.applicationnumber) AS regorpenno,
    cc.gscno,
    su.webmethod AS applicationstage,
    su.inputdataset AS exportedxml,
    su.processingstatus,
    su.transferdatetime,
    cc.signeddatetime AS documentregistered,
    NULL::text AS documentdelivered,
        CASE
            WHEN ((a.currentstatus)::text = 'CD119'::text) THEN 'Yes'::text
            ELSE 'No'::text
        END AS documentpending,
        CASE
            WHEN ((a.currentstatus)::text = 'CD119'::text) THEN a.remarks
            ELSE ''::text
        END AS pendingreason
   FROM ((((kaveri.applicantapplicationdetails a
     JOIN kaveri.cc_applicationdetails cc ON (((cc.applicationnumber)::text = (a.applicationnumber)::text)))
     JOIN kaveri.sakala_uploadfiledetails su ON (((su.gscno)::text = (cc.gscno)::text)))
     JOIN kaveri.sromaster s ON ((s.srocode = a.srocode)))
     JOIN kaveri.districtmaster dis ON ((dis.districtcode = s.districtcode)));


ALTER TABLE kaverimis.vw_mis_sakala_upload_report_cc OWNER TO postgres;

--
-- Name: vw_mis_sakala_upload_report_document; Type: VIEW; Schema: kaverimis; Owner: postgres
--

CREATE VIEW kaverimis.vw_mis_sakala_upload_report_document AS
 SELECT s.srocode,
    dis.districtcode,
    s.sronamee AS officename,
    concat(d.finalregistrationnumber, '/', a.applicationnumber) AS regorpenno,
    d.gscno,
    su.webmethod AS applicationstage,
    su.inputdataset AS exportedxml,
    su.processingstatus,
    su.transferdatetime,
    d.registrationdatetime AS documentregistered,
    NULL::text AS documentdelivered,
        CASE
            WHEN ((a.currentstatus)::text = 'CD119'::text) THEN 'Yes'::text
            ELSE 'No'::text
        END AS documentpending,
        CASE
            WHEN ((a.currentstatus)::text = 'CD119'::text) THEN a.remarks
            ELSE ''::text
        END AS pendingreason
   FROM ((((kaveri.applicantapplicationdetails a
     JOIN kaveri.documentmaster d ON (((d.applicationnumber)::text = (a.applicationnumber)::text)))
     JOIN kaveri.sakala_uploadfiledetails su ON (((su.gscno)::text = (d.gscno)::text)))
     JOIN kaveri.sromaster s ON ((s.srocode = a.srocode)))
     JOIN kaveri.districtmaster dis ON ((dis.districtcode = s.districtcode)));


ALTER TABLE kaverimis.vw_mis_sakala_upload_report_document OWNER TO postgres;

--
-- Name: vw_mis_sakala_upload_report_ec; Type: VIEW; Schema: kaverimis; Owner: postgres
--

CREATE VIEW kaverimis.vw_mis_sakala_upload_report_ec AS
 SELECT s.srocode,
    d.districtcode,
    s.sronamee AS officename,
    concat(a.applicationnumber, '/', ea.certificatenumber) AS regorpenno,
    ea.gscno,
    su.webmethod AS applicationstage,
    su.inputdataset AS exportedxml,
    su.processingstatus,
    su.transferdatetime,
    ea.signeddatetime AS documentregistered,
    NULL::text AS documentdelivered,
        CASE
            WHEN ((a.currentstatus)::text = 'CD119'::text) THEN 'Yes'::text
            ELSE 'No'::text
        END AS documentpending,
        CASE
            WHEN ((a.currentstatus)::text = 'CD119'::text) THEN a.remarks
            ELSE ''::text
        END AS pendingreason
   FROM ((((kaveri.applicantapplicationdetails a
     JOIN kaveri.ec_applicationdetails ea ON (((ea.applicationnumber)::text = (a.applicationnumber)::text)))
     JOIN kaveri.sakala_uploadfiledetails su ON (((su.gscno)::text = (ea.gscno)::text)))
     JOIN kaveri.sromaster s ON ((s.srocode = a.srocode)))
     JOIN kaveri.districtmaster d ON ((d.districtcode = s.districtcode)));


ALTER TABLE kaverimis.vw_mis_sakala_upload_report_ec OWNER TO postgres;

--
-- Name: vw_mis_stautory_revenue_report; Type: VIEW; Schema: kaverimis; Owner: postgres
--

CREATE VIEW kaverimis.vw_mis_stautory_revenue_report AS
 SELECT dm.documentid,
    dm.srocode,
    dm.bookid,
    dm.stamparticlecode,
    dm.finalregistrationnumber,
    dm.applicationnumber,
    dm.registrationdatetime,
    sm.sronamee AS sroname,
    dsm.districtnamee AS districtname,
    dsm.districtcode,
    bm.booknameenglish,
    fr.feerulecode,
    fr.amountpaid,
    pr.sronoofscanpages,
    s.articlenamee AS articlename
   FROM ((((((kaveri.documentmaster dm
     JOIN kaveri.sromaster sm ON ((dm.srocode = sm.srocode)))
     JOIN kaveri.districtmaster dsm ON ((sm.districtcode = dsm.districtcode)))
     JOIN kaveri.booktypemaster bm ON ((dm.bookid = bm.bookid)))
     JOIN kaveri.feesrequired fr ON (((dm.applicationnumber)::text = (fr.applicationnumber)::text)))
     JOIN kaveri.propertymaster pr ON ((dm.documentid = pr.documentid)))
     JOIN kaveri.stamparticles s ON ((s.stamparticlecode = pr.stamparticlecode)))
  WHERE ((dm.isregistrationcompleted = true) AND (fr.amountpaid IS NOT NULL))
  GROUP BY dm.documentid, dm.srocode, dm.bookid, dm.stamparticlecode, dm.finalregistrationnumber, dm.applicationnumber, dm.registrationdatetime, sm.sronamee, dsm.districtnamee, dsm.districtcode, bm.booknameenglish, fr.feerulecode, fr.amountpaid, pr.sronoofscanpages, s.articlenamee;


ALTER TABLE kaverimis.vw_mis_stautory_revenue_report OWNER TO postgres;

--
-- Name: vw_property_fees_details; Type: VIEW; Schema: kaverimis; Owner: csgadmin
--

CREATE VIEW kaverimis.vw_property_fees_details AS
 SELECT crosstab.propertyid,
    crosstab.cess,
    crosstab.deficitstampduty,
    crosstab.mutationfee,
    crosstab.registrationfee,
    crosstab.servicecharge,
    crosstab.stampduty,
    crosstab.surcharge
   FROM kaveri.crosstab('select distinct a.propertyid::BIGINT propertyid, 
e.descriptione::text descriptione,b.amountrequired::bigint	 
from
kaveri.valuationdetails a inner join kaveri.feesrequired b 
on (a.srocode = b.srocode and
a.propertyid = b.propertyid and a.applicationnumber = b.applicationnumber) 
left join kaveri.feesrulemaster e on
a.regarticlecode = e.regarticlecode and b.feerulecode = e.feerulecode 
	order by a.propertyid'::text, 'SELECT distinct descriptione FROM kaveri.feesrulemaster 
	where feerulecode in (1,2,6,35,36,58,59) order by descriptione'::text) crosstab(propertyid bigint, cess bigint, deficitstampduty bigint, mutationfee bigint, registrationfee bigint, servicecharge bigint, stampduty bigint, surcharge bigint);


ALTER TABLE kaverimis.vw_property_fees_details OWNER TO csgadmin;

